--
-- Name: assign_business_code(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.assign_business_code() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if new.business_code is null or trim(new.business_code)='' then
    new.business_code := 'BIZ-'||upper(substr(replace(new.id::text,'-',''),1,12));
  end if;
  return new;
end $$;


--
-- Name: assign_device_document_number(uuid, uuid, text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.assign_device_document_number(p_tenant_id uuid, p_device_id uuid, p_entity_type text, p_entity_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_existing text;v_no bigint;v_prefix text;v_kind text;v_number text;
begin
  if p_device_id is null or p_entity_type not in ('sale','purchase','expense') then return null;end if;
  select terminal_number into v_existing from public.device_document_numbers where entity_type=p_entity_type and entity_id=p_entity_id;
  if v_existing is not null then return v_existing;end if;

  select coalesce(nullif(trim(d.invoice_prefix),''),
                  coalesce(nullif(trim(l.invoice_prefix),''),l.location_code)||'-'||d.device_code)
  into v_prefix
  from public.business_devices d join public.business_locations l on l.id=d.location_id
  where d.id=p_device_id and d.tenant_id=p_tenant_id;
  if v_prefix is null then raise exception 'Invalid terminal for document number';end if;

  insert into public.device_document_counters(tenant_id,device_id,entity_type,last_number)
  values(p_tenant_id,p_device_id,p_entity_type,1)
  on conflict(tenant_id,device_id,entity_type)
  do update set last_number=public.device_document_counters.last_number+1
  returning last_number into v_no;

  v_kind:=case p_entity_type when 'sale' then 'INV' when 'purchase' then 'PUR' else 'EXP' end;
  v_number:=upper(v_prefix)||'-'||v_kind||'-'||lpad(v_no::text,6,'0');
  insert into public.device_document_numbers(tenant_id,device_id,entity_type,entity_id,terminal_number)
  values(p_tenant_id,p_device_id,p_entity_type,p_entity_id,v_number)
  on conflict(entity_type,entity_id) do nothing;
  return coalesce((select terminal_number from public.device_document_numbers where entity_type=p_entity_type and entity_id=p_entity_id),v_number);
end $$;


--
-- Name: assign_location_document_number(uuid, uuid, text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.assign_location_document_number(p_tenant_id uuid, p_location_id uuid, p_entity_type text, p_entity_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_existing text;v_no bigint;v_prefix text;v_kind text;v_number text;
begin
  select local_number into v_existing from public.location_document_numbers
  where entity_type=p_entity_type and entity_id=p_entity_id;
  if v_existing is not null then return v_existing; end if;
  if p_entity_type not in ('sale','purchase','expense') then return null; end if;

  select coalesce(nullif(trim(invoice_prefix),''),location_code)
  into v_prefix from public.business_locations
  where id=p_location_id and tenant_id=p_tenant_id;
  if v_prefix is null then raise exception 'Invalid location for document number'; end if;

  insert into public.location_document_counters(tenant_id,location_id,entity_type,last_number)
  values(p_tenant_id,p_location_id,p_entity_type,1)
  on conflict(tenant_id,location_id,entity_type)
  do update set last_number=public.location_document_counters.last_number+1
  returning last_number into v_no;

  v_kind:=case p_entity_type when 'sale' then 'INV' when 'purchase' then 'PUR' else 'EXP' end;
  v_number:=upper(v_prefix)||'-'||v_kind||'-'||lpad(v_no::text,6,'0');
  insert into public.location_document_numbers(tenant_id,location_id,entity_type,entity_id,local_number)
  values(p_tenant_id,p_location_id,p_entity_type,p_entity_id,v_number)
  on conflict(entity_type,entity_id) do nothing;
  return coalesce((select local_number from public.location_document_numbers where entity_type=p_entity_type and entity_id=p_entity_id),v_number);
end $$;


