--
-- Name: business_audit_write(uuid, text, text, uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.business_audit_write(p_tenant_id uuid, p_action text, p_entity_type text, p_entity_id uuid, p_reference text, p_before jsonb, p_after jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_location uuid; v_device uuid;
begin
  select o.location_id,o.device_id into v_location,v_device
  from public.document_origins o
  where o.tenant_id=p_tenant_id and o.entity_type=p_entity_type and o.entity_id=p_entity_id
  limit 1;

  if v_location is null and p_after ? 'location_id' then
    begin v_location := nullif(p_after->>'location_id','')::uuid; exception when others then null; end;
  end if;
  if v_device is null and p_after ? 'device_id' then
    begin v_device := nullif(p_after->>'device_id','')::uuid; exception when others then null; end;
  end if;

  insert into public.business_audit_log(
    tenant_id,user_id,action,entity_type,entity_id,entity_reference,
    before_data,after_data,location_id,device_id,metadata
  ) values(
    p_tenant_id,auth.uid(),p_action,p_entity_type,p_entity_id,p_reference,
    p_before,p_after,v_location,v_device,
    jsonb_build_object('source','erp','recorded_at',now(),'version','4.6')
  );
end $$;


--
-- Name: business_audit_write(uuid, text, text, uuid, text, uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.business_audit_write(p_tenant_id uuid, p_action text, p_entity_type text, p_entity_id uuid, p_reference text, p_location_id uuid, p_after jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  perform private.business_audit_write(
    p_tenant_id,p_action,p_entity_type,p_entity_id,p_reference,
    jsonb_build_object('location_id',p_location_id),
    coalesce(p_after,'{}'::jsonb) || jsonb_build_object('location_id',p_location_id)
  );
end $$;


--
-- Name: business_audit_write_v471(uuid, text, text, uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.business_audit_write_v471(p_tenant_id uuid, p_action text, p_entity_type text, p_entity_id uuid, p_reference text, p_before jsonb, p_after jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  -- All argument types are fixed at this boundary, so PostgreSQL cannot choose
  -- the legacy UUID overload accidentally.
  perform private.business_audit_write(
    p_tenant_id,
    p_action,
    p_entity_type,
    p_entity_id,
    p_reference,
    p_before::jsonb,
    coalesce(p_after,'{}'::jsonb)::jsonb
  );
end $$;


