--
-- Name: can_access_role(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_access_role(target_role_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.roles r
    join public.tenant_memberships tm
      on tm.tenant_id = r.tenant_id
    where r.id = target_role_id
      and tm.user_id = (select auth.uid())
      and tm.status = 'active'
  );
$$;


--
-- Name: erp_document_scope_allowed(uuid, uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.erp_document_scope_allowed(p_tenant_id uuid, p_location_id uuid, p_requested_location uuid DEFAULT NULL::uuid, p_required text DEFAULT 'view'::text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if p_location_id is null then return private.erp_user_is_owner(p_tenant_id);end if;
  if p_requested_location is not null and p_location_id<>p_requested_location then return false;end if;
  if private.erp_user_location_allowed(p_tenant_id,p_location_id,p_required) then return true;end if;
  if private.erp_has_permission(p_tenant_id,'locations.manage_all') then return true;end if;
  if lower(coalesce(p_required,'view'))='view' and private.erp_has_permission(p_tenant_id,'locations.view_all') then return true;end if;
  return false;
end $$;


--
-- Name: erp_has_permission(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.erp_has_permission(p_tenant_id uuid, p_permission_key text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.tenant_memberships tm
    join public.user_roles ur
      on ur.tenant_id = tm.tenant_id
     and ur.membership_id = tm.id
    join public.roles r on r.id = ur.role_id
    left join public.role_permissions rp on rp.role_id = r.id
    where tm.tenant_id = p_tenant_id
      and tm.user_id = auth.uid()
      and tm.status = 'active'
      and (r.key = 'owner' or rp.permission_key = p_permission_key)
  );
$$;


--
-- Name: erp_module_available(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.erp_module_available(p_tenant_id uuid, p_module_key text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
  select private.erp_module_enabled(p_tenant_id, p_module_key)
     and coalesce((select m.is_active from public.modules m where m.key=p_module_key), false)
     and (
       not exists (select 1 from public.tenant_subscriptions ts where ts.tenant_id=p_tenant_id)
       or exists (
         select 1
         from public.tenant_subscriptions ts
         join public.subscription_plan_modules spm on spm.plan_id=ts.plan_id
         where ts.tenant_id=p_tenant_id
           and ts.status in ('trial','active','past_due')
           and spm.module_key=p_module_key
       )
     );
$$;


--
-- Name: erp_module_enabled(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.erp_module_enabled(p_tenant_id uuid, p_module_key text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
  select exists (
    select 1 from public.tenant_modules tm
    where tm.tenant_id = p_tenant_id
      and tm.module_key = p_module_key
      and tm.enabled = true
  );
$$;


--
-- Name: erp_user_app_allowed(uuid, text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.erp_user_app_allowed(p_tenant_id uuid, p_app_key text, p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
  select private.erp_user_is_owner(p_tenant_id,p_user_id)
      or coalesce((select a.enabled from public.business_user_app_access a where a.tenant_id=p_tenant_id and a.user_id=p_user_id and a.app_key=p_app_key),false);
$$;


--
-- Name: erp_user_has_tenant_access(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.erp_user_has_tenant_access(p_tenant_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.tenant_memberships tm
    where tm.tenant_id = p_tenant_id
      and tm.user_id = auth.uid()
      and tm.status = 'active'
  );
$$;


--
-- Name: erp_user_is_owner(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.erp_user_is_owner(p_tenant_id uuid, p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
  select exists(
    select 1
    from public.tenant_memberships tm
    join public.user_roles ur on ur.tenant_id=tm.tenant_id and ur.membership_id=tm.id
    join public.roles r on r.id=ur.role_id
    where tm.tenant_id=p_tenant_id and tm.user_id=p_user_id and tm.status='active' and r.key='owner'
  );
$$;


--
-- Name: erp_user_location_allowed(uuid, uuid, text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.erp_user_location_allowed(p_tenant_id uuid, p_location_id uuid, p_required text DEFAULT 'view'::text, p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_level text;v_rank int;v_required int;
begin
  if private.erp_user_is_owner(p_tenant_id,p_user_id) then return true;end if;
  select access_level into v_level from public.business_user_location_access
   where tenant_id=p_tenant_id and user_id=p_user_id and location_id=p_location_id;
  if v_level is null then return false;end if;
  v_rank:=case v_level when 'manage' then 3 when 'operate' then 2 else 1 end;
  v_required:=case p_required when 'manage' then 3 when 'operate' then 2 else 1 end;
  return v_rank>=v_required;
end $$;


--
-- Name: erp_validate_transaction_origin(uuid, uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.erp_validate_transaction_origin(p_tenant_id uuid, p_location_id uuid, p_device_id uuid, p_required_pos_module text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_app text;
  v_device_location uuid;
  v_modules text[];
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  if p_location_id is null then raise exception 'A business location is required'; end if;
  if not private.erp_user_location_allowed(p_tenant_id,p_location_id,'operate') then
    raise exception 'You cannot create records for this location';
  end if;

  if p_device_id is null then raise exception 'A registered system is required'; end if;
  select d.app_type,d.location_id,d.allowed_modules
    into v_app,v_device_location,v_modules
  from public.business_devices d
  where d.id=p_device_id and d.tenant_id=p_tenant_id and d.status='active';
  if not found then raise exception 'Registered system is invalid or revoked'; end if;

  -- A POS is fixed to its own store and its per-terminal module selection.
  if v_app='pos' then
    if v_device_location is distinct from p_location_id then
      raise exception 'POS terminals can only post to their assigned store';
    end if;
    if p_required_pos_module is not null and not (p_required_pos_module = any(coalesce(v_modules,'{}'::text[]))) then
      raise exception 'This POS terminal is not enabled for %',p_required_pos_module;
    end if;
  elsif v_app <> 'client' then
    raise exception 'Unsupported system type';
  end if;
end $$;


--
-- Name: erp_validate_vertical_device_scope(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.erp_validate_vertical_device_scope(p_tenant_id uuid, p_location_id uuid, p_device_id uuid, p_module_key text, p_required_access text DEFAULT 'view'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_app text;
  v_device_location uuid;
  v_modules text[];
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  if p_device_id is null then raise exception 'A registered system is required'; end if;

  select d.app_type,d.location_id,d.allowed_modules
    into v_app,v_device_location,v_modules
  from public.business_devices d
  where d.id=p_device_id and d.tenant_id=p_tenant_id and d.status='active';
  if not found then raise exception 'Registered system is invalid or revoked'; end if;

  if v_app='pos' then
    if p_location_id is null or p_location_id is distinct from v_device_location then
      raise exception 'POS terminals can only access their assigned store';
    end if;
    if p_module_key is not null and not (p_module_key = any(coalesce(v_modules,'{}'::text[]))) then
      raise exception 'This POS terminal is not enabled for %',p_module_key;
    end if;
    if not private.erp_user_location_allowed(p_tenant_id,p_location_id,p_required_access) then
      raise exception 'Location access denied';
    end if;
  elsif v_app='client' then
    if p_location_id is null then
      if lower(coalesce(p_required_access,'view'))<>'view'
         or not (private.erp_user_is_owner(p_tenant_id)
                 or private.erp_has_permission(p_tenant_id,'locations.view_all')
                 or private.erp_has_permission(p_tenant_id,'locations.manage_all')) then
        raise exception 'Choose an accessible store';
      end if;
    elsif not private.erp_document_scope_allowed(p_tenant_id,p_location_id,p_location_id,p_required_access) then
      raise exception 'Location access denied';
    end if;
  else
    raise exception 'Unsupported system type';
  end if;
end $$;


--
-- Name: expense_change_history_capture_v600(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.expense_change_history_capture_v600() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_reason text := nullif(current_setting('thq.expense_change_reason', true), '');
begin
  if tg_op = 'INSERT' then
    insert into public.expense_change_history_v600(
      tenant_id, expense_id, action, reason, before_data, after_data, changed_by
    ) values (
      new.tenant_id, new.id, 'created', coalesce(v_reason, 'Expense created'),
      null, to_jsonb(new), coalesce(new.created_by, auth.uid())
    );
  elsif tg_op = 'UPDATE' then
    if to_jsonb(new) is distinct from to_jsonb(old) then
      insert into public.expense_change_history_v600(
        tenant_id, expense_id, action, reason, before_data, after_data, changed_by
      ) values (
        new.tenant_id, new.id, 'edited', v_reason,
        to_jsonb(old), to_jsonb(new), coalesce(new.updated_by, auth.uid())
      );
    end if;
  end if;
  return new;
end;
$$;


