--
-- Name: loan_accounts_v490; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.loan_accounts_v490 (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    location_id uuid NOT NULL,
    loan_number text NOT NULL,
    client_id uuid,
    external_client_reference text,
    purpose text,
    principal_amount numeric NOT NULL,
    interest_rate numeric DEFAULT 0 NOT NULL,
    rate_type text DEFAULT 'fixed'::text NOT NULL,
    rate_index text,
    rate_margin numeric DEFAULT 0 NOT NULL,
    rate_reset_frequency text,
    next_rate_review_date date,
    amortization_method text DEFAULT 'reducing_balance'::text NOT NULL,
    repayment_frequency text DEFAULT 'monthly'::text NOT NULL,
    repayment_term_count integer NOT NULL,
    repayment_terms text,
    first_payment_date date NOT NULL,
    maturity_date date NOT NULL,
    disbursement_date date,
    payment_warning_days integer DEFAULT 5 NOT NULL,
    maturity_warning_days integer DEFAULT 30 NOT NULL,
    grace_days integer DEFAULT 0 NOT NULL,
    penalty_rate numeric DEFAULT 0 NOT NULL,
    collateral_summary text,
    notes text,
    status text DEFAULT 'draft'::text NOT NULL,
    principal_outstanding numeric DEFAULT 0 NOT NULL,
    interest_outstanding numeric DEFAULT 0 NOT NULL,
    penalty_outstanding numeric DEFAULT 0 NOT NULL,
    total_paid numeric DEFAULT 0 NOT NULL,
    approved_by uuid,
    approved_at timestamp with time zone,
    rejected_by uuid,
    rejected_at timestamp with time zone,
    rejection_reason text,
    disbursed_by uuid,
    disbursed_at timestamp with time zone,
    closed_at timestamp with time zone,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    direction text DEFAULT 'given'::text NOT NULL,
    counterparty_type text DEFAULT 'customer'::text NOT NULL,
    supplier_id uuid,
    counterparty_name text,
    counterparty_reference text,
    accounting_enabled boolean DEFAULT true NOT NULL,
    CONSTRAINT loan_accounts_v490_amortization_method_check CHECK ((amortization_method = ANY (ARRAY['reducing_balance'::text, 'flat'::text]))),
    CONSTRAINT loan_accounts_v490_check CHECK ((maturity_date >= first_payment_date)),
    CONSTRAINT loan_accounts_v490_counterparty_chk CHECK ((counterparty_type = ANY (ARRAY['customer'::text, 'supplier'::text, 'other'::text]))),
    CONSTRAINT loan_accounts_v490_direction_chk CHECK ((direction = ANY (ARRAY['given'::text, 'taken'::text]))),
    CONSTRAINT loan_accounts_v490_grace_days_check CHECK (((grace_days >= 0) AND (grace_days <= 365))),
    CONSTRAINT loan_accounts_v490_interest_rate_check CHECK (((interest_rate >= (0)::numeric) AND (interest_rate <= (1000)::numeric))),
    CONSTRAINT loan_accounts_v490_maturity_warning_days_check CHECK (((maturity_warning_days >= 0) AND (maturity_warning_days <= 3650))),
    CONSTRAINT loan_accounts_v490_payment_warning_days_check CHECK (((payment_warning_days >= 0) AND (payment_warning_days <= 365))),
    CONSTRAINT loan_accounts_v490_penalty_rate_check CHECK (((penalty_rate >= (0)::numeric) AND (penalty_rate <= (1000)::numeric))),
    CONSTRAINT loan_accounts_v490_principal_amount_check CHECK ((principal_amount > (0)::numeric)),
    CONSTRAINT loan_accounts_v490_rate_reset_frequency_check CHECK (((rate_reset_frequency IS NULL) OR (rate_reset_frequency = ANY (ARRAY['monthly'::text, 'quarterly'::text, 'half_yearly'::text, 'yearly'::text])))),
    CONSTRAINT loan_accounts_v490_rate_type_check CHECK ((rate_type = ANY (ARRAY['fixed'::text, 'variable'::text]))),
    CONSTRAINT loan_accounts_v490_repayment_frequency_check CHECK ((repayment_frequency = ANY (ARRAY['weekly'::text, 'biweekly'::text, 'monthly'::text, 'quarterly'::text, 'half_yearly'::text, 'yearly'::text]))),
    CONSTRAINT loan_accounts_v490_repayment_term_count_check CHECK (((repayment_term_count > 0) AND (repayment_term_count <= 1200))),
    CONSTRAINT loan_accounts_v490_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'submitted'::text, 'approved'::text, 'active'::text, 'closed'::text, 'defaulted'::text, 'cancelled'::text, 'rejected'::text])))
);


--
-- Name: loan_v491_party_json(public.loan_accounts_v490); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.loan_v491_party_json(v public.loan_accounts_v490) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare j jsonb; begin
 if v.counterparty_type='customer' then select jsonb_build_object('id',c.id,'type','customer','name',c.name,'public_id',c.tracking_code,'phone',c.phone,'email',c.email,'tax_number',c.tax_number) into j from public.customers c where c.id=v.client_id;
 elsif v.counterparty_type='supplier' then select jsonb_build_object('id',s.id,'type','supplier','name',s.name,'public_id',s.tracking_code,'phone',s.phone,'email',s.email,'tax_number',s.tax_number) into j from public.suppliers s where s.id=v.supplier_id;
 else j:=jsonb_build_object('id',null,'type','other','name',v.counterparty_name,'public_id',coalesce(v.counterparty_reference,''),'phone','','email','','tax_number',''); end if; return coalesce(j,'{}'::jsonb); end $$;


--
-- Name: next_document_number(uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.next_document_number(target_tenant_id uuid, target_document_type text, target_prefix text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_number bigint;
begin

  insert into public.document_counters (
    tenant_id,
    document_type,
    last_number,
    updated_at
  )
  values (
    target_tenant_id,
    target_document_type,
    1,
    now()
  )

  on conflict (
    tenant_id,
    document_type
  )
  do update set
    last_number =
      public.document_counters.last_number + 1,

    updated_at = now()

  returning last_number
  into v_number;


  return
    target_prefix
    || '-'
    || lpad(
      v_number::text,
      6,
      '0'
    );

end;
$$;


--
-- Name: next_tracking_code(uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.next_tracking_code(p_tenant_id uuid, p_entity_key text, p_prefix text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_no bigint;
begin
  insert into public.entity_tracking_counters(tenant_id,entity_key,last_number)
  values(p_tenant_id,p_entity_key,1)
  on conflict(tenant_id,entity_key)
  do update set last_number=public.entity_tracking_counters.last_number+1
  returning last_number into v_no;
  return upper(p_prefix)||'-'||lpad(v_no::text,8,'0');
end $$;


