--
-- Name: pricing_resolve_v482_internal(uuid, uuid, uuid, uuid, numeric, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.pricing_resolve_v482_internal(p_tenant_id uuid, p_variant_id uuid, p_customer_id uuid, p_unit_id uuid, p_quantity numeric, p_location_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v_price numeric;v_source text;v_list uuid;v_list_name text;v_factor numeric:=1;v_qty numeric:=greatest(coalesce(p_quantity,1),0.000001);v_unit_id uuid:=p_unit_id;v_group_id uuid;v_group_name text;v_group_discount numeric:=0;begin if v_unit_id is null then select pu.unit_id into v_unit_id from public.product_units_v481 pu where pu.tenant_id=p_tenant_id and pu.variant_id=p_variant_id and pu.active and pu.is_default_sale limit 1;end if;if v_unit_id is null then select pu.unit_id into v_unit_id from public.product_units_v481 pu where pu.tenant_id=p_tenant_id and pu.variant_id=p_variant_id and pu.active and pu.is_base limit 1;end if;select pu.conversion_to_base into v_factor from public.product_units_v481 pu where pu.tenant_id=p_tenant_id and pu.variant_id=p_variant_id and pu.unit_id=v_unit_id and pu.active and pu.allow_sale;if v_factor is null then raise exception 'Sale unit is not enabled for this product';end if;if p_customer_id is not null then select cp.unit_price into v_price from public.customer_prices_v482 cp where cp.tenant_id=p_tenant_id and cp.customer_id=p_customer_id and cp.variant_id=p_variant_id and cp.unit_id=v_unit_id and cp.active and cp.min_quantity<=v_qty order by cp.min_quantity desc limit 1;if v_price is not null then v_source:='customer';end if;end if;if v_price is null then if p_customer_id is not null then select cpp.price_list_id into v_list from public.customer_pricing_profiles_v482 cpp where cpp.tenant_id=p_tenant_id and cpp.customer_id=p_customer_id and cpp.active;end if;if v_list is null then select pl.id into v_list from public.price_lists_v482 pl where pl.tenant_id=p_tenant_id and pl.active and pl.is_default limit 1;end if;if v_list is not null then select pli.unit_price,pl.name into v_price,v_list_name from public.price_list_items_v482 pli join public.price_lists_v482 pl on pl.id=pli.price_list_id where pli.tenant_id=p_tenant_id and pli.price_list_id=v_list and pli.variant_id=p_variant_id and pli.unit_id=v_unit_id and pli.active and pl.active and pli.min_quantity<=v_qty order by pli.min_quantity desc limit 1;if v_price is not null then v_source:='price_list';end if;end if;end if;if v_price is null then select coalesce(pu.sale_price,coalesce(lps.selling_price,pv.selling_price)*pu.conversion_to_base),case when pu.sale_price is not null then 'unit_price' when lps.selling_price is not null then 'location_price' else 'product_price' end into v_price,v_source from public.product_units_v481 pu join public.product_variants pv on pv.id=pu.variant_id left join public.location_product_settings lps on lps.tenant_id=p_tenant_id and lps.variant_id=p_variant_id and lps.location_id=p_location_id and lps.active where pu.tenant_id=p_tenant_id and pu.variant_id=p_variant_id and pu.unit_id=v_unit_id and pu.active limit 1;if p_customer_id is not null then select g.id,g.name,least(greatest(coalesce(g.discount_percent,0),0),100) into v_group_id,v_group_name,v_group_discount from public.customer_crm_profiles_v500 c join public.customer_groups_v500 g on g.id=c.group_id and g.tenant_id=c.tenant_id where c.tenant_id=p_tenant_id and c.customer_id=p_customer_id and g.active limit 1;if coalesce(v_group_discount,0)>0 then v_price:=round(coalesce(v_price,0)*(100-v_group_discount)/100,4);v_source:='customer_group';end if;end if;end if;return jsonb_build_object('variant_id',p_variant_id,'customer_id',p_customer_id,'unit_id',v_unit_id,'quantity',v_qty,'unit_price',coalesce(v_price,0),'source',coalesce(v_source,'product_price'),'price_list_id',v_list,'price_list_name',v_list_name,'customer_group_id',v_group_id,'customer_group_name',v_group_name,'customer_group_discount_percent',coalesce(v_group_discount,0));end $$;


