--
-- Name: purchase_planning_access_v480(uuid, uuid, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.purchase_planning_access_v480(p_tenant_id uuid, p_location_id uuid, p_manage boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if not private.erp_document_scope_allowed(p_tenant_id,p_location_id,p_location_id,case when p_manage then 'operate' else 'view' end) then raise exception 'Location access denied';end if;
  if not private.erp_user_is_owner(p_tenant_id) then
    if p_manage and not private.erp_has_permission(p_tenant_id,'purchases.manage') then raise exception 'Purchase management permission required';end if;
    if not p_manage and not private.erp_has_permission(p_tenant_id,'purchases.view') and not private.erp_has_permission(p_tenant_id,'purchases.manage') then raise exception 'Purchase permission required';end if;
  end if;
end $$;


--
-- Name: purchasing_v484_access(uuid, uuid, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.purchasing_v484_access(p_tenant_id uuid, p_location_id uuid, p_manage boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  perform private.purchasing_v484_permission(p_tenant_id,p_manage);
  if p_location_id is null or not private.erp_document_scope_allowed(p_tenant_id,p_location_id,p_location_id,case when p_manage then 'operate' else 'view' end) then raise exception 'Location access denied';end if;
end$$;


--
-- Name: purchasing_v484_approval_access(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.purchasing_v484_approval_access(p_tenant_id uuid, p_location_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  perform private.purchasing_v484_access(p_tenant_id,p_location_id,false);
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'approvals.approve') then raise exception 'Approval permission required';end if;
end$$;


--
-- Name: purchasing_v484_permission(uuid, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.purchasing_v484_permission(p_tenant_id uuid, p_manage boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if not private.erp_user_is_owner(p_tenant_id) then
    if p_manage and not private.erp_has_permission(p_tenant_id,'purchases.manage') then raise exception 'Purchase management permission required';end if;
    if not p_manage and not private.erp_has_permission(p_tenant_id,'purchases.view') and not private.erp_has_permission(p_tenant_id,'purchases.manage') then raise exception 'Purchase permission required';end if;
  end if;
end$$;


