--
-- Name: seed_default_roles(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.seed_default_roles(target_tenant_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_role_id uuid;
begin

  -- OWNER

  v_role_id := null;

  insert into public.roles (
    tenant_id,
    key,
    name,
    is_system
  )
  values (
    target_tenant_id,
    'owner',
    'Owner',
    true
  )
  on conflict (tenant_id, key)
  do nothing
  returning id into v_role_id;

  if v_role_id is not null then
    perform private.grant_default_role_permissions(
      target_tenant_id,
      v_role_id,
      'owner'
    );
  end if;


  -- MANAGER

  v_role_id := null;

  insert into public.roles (
    tenant_id,
    key,
    name,
    is_system
  )
  values (
    target_tenant_id,
    'manager',
    'Manager',
    true
  )
  on conflict (tenant_id, key)
  do nothing
  returning id into v_role_id;

  if v_role_id is not null then
    perform private.grant_default_role_permissions(
      target_tenant_id,
      v_role_id,
      'manager'
    );
  end if;


  -- CASHIER

  v_role_id := null;

  insert into public.roles (
    tenant_id,
    key,
    name,
    is_system
  )
  values (
    target_tenant_id,
    'cashier',
    'Cashier',
    true
  )
  on conflict (tenant_id, key)
  do nothing
  returning id into v_role_id;

  if v_role_id is not null then
    perform private.grant_default_role_permissions(
      target_tenant_id,
      v_role_id,
      'cashier'
    );
  end if;


  -- SALESPERSON

  v_role_id := null;

  insert into public.roles (
    tenant_id,
    key,
    name,
    is_system
  )
  values (
    target_tenant_id,
    'salesperson',
    'Salesperson',
    true
  )
  on conflict (tenant_id, key)
  do nothing
  returning id into v_role_id;

  if v_role_id is not null then
    perform private.grant_default_role_permissions(
      target_tenant_id,
      v_role_id,
      'salesperson'
    );
  end if;


  -- STORE KEEPER

  v_role_id := null;

  insert into public.roles (
    tenant_id,
    key,
    name,
    is_system
  )
  values (
    target_tenant_id,
    'store_keeper',
    'Store Keeper',
    true
  )
  on conflict (tenant_id, key)
  do nothing
  returning id into v_role_id;

  if v_role_id is not null then
    perform private.grant_default_role_permissions(
      target_tenant_id,
      v_role_id,
      'store_keeper'
    );
  end if;


  -- ACCOUNTANT

  v_role_id := null;

  insert into public.roles (
    tenant_id,
    key,
    name,
    is_system
  )
  values (
    target_tenant_id,
    'accountant',
    'Accountant',
    true
  )
  on conflict (tenant_id, key)
  do nothing
  returning id into v_role_id;

  if v_role_id is not null then
    perform private.grant_default_role_permissions(
      target_tenant_id,
      v_role_id,
      'accountant'
    );
  end if;

end;
$$;


