--
-- Name: v44_product_barcode_unique(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v44_product_barcode_unique() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if nullif(trim(coalesce(new.barcode,'')),'') is not null and exists(
    select 1 from public.product_variants x
    where x.tenant_id=new.tenant_id and x.id<>new.id and lower(trim(coalesce(x.barcode,'')))=lower(trim(new.barcode))
  ) then
    raise exception 'Barcode % already belongs to another product',new.barcode;
  end if;
  return new;
end $$;


--
-- Name: v471_platform_insert_sale_payment(uuid, numeric, text, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v471_platform_insert_sale_payment(p_sale_id uuid, p_amount numeric, p_method text, p_reference text, p_notes text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $_$
declare v_id uuid;v_sql text;v_cols text:='sale_id,amount,payment_method';v_vals text:='$1,$2,$3';
begin
  if not private.platform_v2_is_admin() then raise exception 'Platform admin required';end if;
  if exists(select 1 from information_schema.columns where table_schema='public' and table_name='sale_payments' and column_name='reference_number') then
    v_cols:=v_cols||',reference_number';v_vals:=v_vals||',$4';
  end if;
  if exists(select 1 from information_schema.columns where table_schema='public' and table_name='sale_payments' and column_name='notes') then
    v_cols:=v_cols||',notes';
    v_vals:=v_vals||case when position('reference_number' in v_cols)>0 then ',$5' else ',$4' end;
  end if;
  v_sql:='insert into public.sale_payments('||v_cols||') values('||v_vals||') returning id';
  if position('reference_number' in v_cols)>0 and position('notes' in v_cols)>0 then execute v_sql into v_id using p_sale_id,p_amount,p_method,p_reference,p_notes;
  elsif position('reference_number' in v_cols)>0 then execute v_sql into v_id using p_sale_id,p_amount,p_method,p_reference;
  elsif position('notes' in v_cols)>0 then execute v_sql into v_id using p_sale_id,p_amount,p_method,p_notes;
  else execute v_sql into v_id using p_sale_id,p_amount,p_method;end if;
  return v_id;
end $_$;


--
-- Name: v471_pos_operational_modules_sync(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v471_pos_operational_modules_sync() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if new.module_key='pos' and new.enabled then
    insert into public.tenant_modules(tenant_id,module_key,enabled) values(new.tenant_id,'cashier_shifts',true)
      on conflict(tenant_id,module_key) do update set enabled=true;
    insert into public.tenant_modules(tenant_id,module_key,enabled) values(new.tenant_id,'terminal_day',true)
      on conflict(tenant_id,module_key) do update set enabled=true;
  end if;
  return new;
end $$;


--
-- Name: v472_guard_operational_module_change(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v472_guard_operational_module_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if old.app_type='pos'
     and 'cashier_shifts'=any(coalesce(old.allowed_modules,'{}'::text[]))
     and not ('cashier_shifts'=any(coalesce(new.allowed_modules,'{}'::text[])))
     and exists(select 1 from public.cashier_shifts s where s.device_id=old.id and s.status='open') then
    raise exception 'End the open Cashier Shift before deactivating Cashier Shift for this POS';
  end if;
  return new;
end $$;


--
-- Name: v472_guard_tenant_operational_module_change(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v472_guard_tenant_operational_module_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_tenant_id uuid:=old.tenant_id;
  v_key text:=old.module_key;
  v_was_enabled boolean:=coalesce(old.enabled,false);
  v_will_enabled boolean:=case when tg_op='DELETE' then false else coalesce(new.enabled,false) end;
begin
  if v_key='cashier_shifts' and v_was_enabled and not v_will_enabled
     and exists(
       select 1 from public.cashier_shifts s
       where s.tenant_id=v_tenant_id and s.status='open'
     ) then
    raise exception 'End all open Cashier Shifts before deactivating Cashier Shift for this business';
  end if;
  if tg_op='DELETE' then return old;end if;
  return new;
end $$;


--
-- Name: v472_shift_expected_cash(uuid); Type: FUNCTION; Schema: private; Owner: -
--

