--
-- Name: v472_shift_module_enabled(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v472_shift_module_enabled(p_tenant_id uuid, p_device_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
  select exists(
    select 1
    from public.business_devices d
    where d.id=p_device_id
      and d.tenant_id=p_tenant_id
      and d.app_type='pos'
      and d.status='active'
      and 'cashier_shifts'=any(coalesce(d.allowed_modules,'{}'::text[]))
  )
  and exists(
    select 1 from public.tenant_modules tm
    where tm.tenant_id=p_tenant_id and tm.module_key='cashier_shifts' and tm.enabled
  )
$$;


--
-- Name: v472_shift_period_conflicts(uuid, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v472_shift_period_conflicts(p_device_id uuid, p_shift_id uuid, p_opened_at timestamp with time zone, p_closed_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
  select exists(
    select 1
    from public.cashier_shifts s
    where s.device_id=p_device_id
      and (p_shift_id is null or s.id<>p_shift_id)
      and s.opened_at < coalesce(p_closed_at,'infinity'::timestamptz)
      and coalesce(s.closed_at,'infinity'::timestamptz) > p_opened_at
  )
$$;


--
-- Name: v472_terminal_day_module_enabled(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v472_terminal_day_module_enabled(p_tenant_id uuid, p_device_id uuid) RETURNS boolean
