-- Name: v482_sync_legacy_identifiers(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v482_sync_legacy_identifiers(p_tenant_id uuid, p_variant_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_barcode text;v_part text;begin
 select i.code into v_barcode from public.product_identifiers_v482 i where i.tenant_id=p_tenant_id and i.variant_id=p_variant_id and i.identifier_type='barcode' and i.active order by i.is_primary desc,i.updated_at desc limit 1;
 select i.code into v_part from public.product_identifiers_v482 i where i.tenant_id=p_tenant_id and i.variant_id=p_variant_id and i.identifier_type='manufacturer' and i.active order by i.is_primary desc,i.updated_at desc limit 1;
 update public.product_variants set barcode=v_barcode,part_number=v_part,updated_at=now() where tenant_id=p_tenant_id and id=p_variant_id;
end$$;


--
-- Name: v483_apply_batch_sale(uuid, uuid, uuid, uuid, uuid, uuid, date, numeric, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v483_apply_batch_sale(p_tenant_id uuid, p_variant_id uuid, p_sale_id uuid, p_sale_item_id uuid, p_customer_id uuid, p_location_id uuid, p_sale_date date, p_quantity numeric, p_requested jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_remaining numeric:=p_quantity;v_out jsonb:='[]'::jsonb;v_allow_expired boolean:=false;r record;x jsonb;v_batch_id uuid;v_take numeric;v_requested_qty numeric;v_batch_number text;v_seen uuid[]:='{}'::uuid[];v_ref text;v_available numeric;
begin
 select allow_expired_sale into v_allow_expired from public.product_tracking_policies_v483 where tenant_id=p_tenant_id and variant_id=p_variant_id;
 select sale_number into v_ref from public.sales where tenant_id=p_tenant_id and id=p_sale_id;
 if jsonb_array_length(coalesce(p_requested,'[]'::jsonb))>0 then
  for x in select value from jsonb_array_elements(p_requested) loop
   v_requested_qty:=coalesce(nullif(x->>'quantity','')::numeric,0);if v_requested_qty<=0 then raise exception 'Requested batch quantity must be positive';end if;
   v_batch_id:=null;
   if nullif(x->>'batch_id','') is not null then v_batch_id:=(x->>'batch_id')::uuid;else
    v_batch_number:=trim(coalesce(x->>'batch_number',''));select id into v_batch_id from public.inventory_batches_v483 where tenant_id=p_tenant_id and variant_id=p_variant_id and lower(trim(batch_number))=lower(v_batch_number);end if;
   if v_batch_id is null then raise exception 'Batch not found for tracked product';end if;
   if v_batch_id=any(v_seen) then raise exception 'The same batch cannot appear twice on one sale line';end if;v_seen:=array_append(v_seen,v_batch_id);
   select b.batch_number,b.expiry_on,bb.quantity-coalesce(bb.reserved_quantity,0) available_quantity into r
     from public.inventory_batches_v483 b join public.inventory_batch_balances_v483 bb on bb.tenant_id=b.tenant_id and bb.batch_id=b.id
     where b.tenant_id=p_tenant_id and b.id=v_batch_id and b.variant_id=p_variant_id and bb.location_id=p_location_id and b.status='active' for update of bb;
   v_available:=coalesce(r.available_quantity,0);
   if not found or v_available+0.000001<v_requested_qty then raise exception 'Insufficient unreserved quantity in selected batch %',coalesce(r.batch_number,v_batch_number);end if;
   if not coalesce(v_allow_expired,false) and r.expiry_on is not null and r.expiry_on<p_sale_date then raise exception 'Batch % expired on %',r.batch_number,r.expiry_on;end if;
   update public.inventory_batch_balances_v483 set quantity=quantity-v_requested_qty,updated_at=now() where tenant_id=p_tenant_id and batch_id=v_batch_id and location_id=p_location_id;
   insert into public.inventory_trace_events_v483(tenant_id,variant_id,batch_id,event_type,quantity,location_id,customer_id,sale_id,sale_item_id,reference_number,source_key,created_by)
     values(p_tenant_id,p_variant_id,v_batch_id,'sale',v_requested_qty,p_location_id,p_customer_id,p_sale_id,p_sale_item_id,v_ref,'sale:'||p_sale_id::text||':item:'||p_sale_item_id::text||':batch:'||v_batch_id::text,auth.uid());
   perform private.v483_create_warranty(p_tenant_id,p_variant_id,null,v_batch_id,p_customer_id,p_sale_id,p_sale_item_id,v_requested_qty,p_sale_date);
   v_remaining:=v_remaining-v_requested_qty;v_out:=v_out||jsonb_build_array(jsonb_build_object('batch_id',v_batch_id,'batch_number',r.batch_number,'quantity',v_requested_qty,'expiry_on',r.expiry_on));
  end loop;
  if abs(v_remaining)>0.000001 then raise exception 'Selected batch quantities must equal required base quantity %',p_quantity;end if;
 else
  for r in
    select b.id batch_id,b.batch_number,b.expiry_on,bb.quantity-coalesce(bb.reserved_quantity,0) available_quantity
    from public.inventory_batches_v483 b join public.inventory_batch_balances_v483 bb on bb.tenant_id=b.tenant_id and bb.batch_id=b.id
    where b.tenant_id=p_tenant_id and b.variant_id=p_variant_id and bb.location_id=p_location_id
      and bb.quantity-coalesce(bb.reserved_quantity,0)>0 and b.status='active'
      and (coalesce(v_allow_expired,false) or b.expiry_on is null or b.expiry_on>=p_sale_date)
    order by (b.expiry_on is null),b.expiry_on,b.created_at,b.batch_number for update of bb
  loop
   exit when v_remaining<=0.000001;v_take:=least(v_remaining,r.available_quantity);
   update public.inventory_batch_balances_v483 set quantity=quantity-v_take,updated_at=now() where tenant_id=p_tenant_id and batch_id=r.batch_id and location_id=p_location_id;
   insert into public.inventory_trace_events_v483(tenant_id,variant_id,batch_id,event_type,quantity,location_id,customer_id,sale_id,sale_item_id,reference_number,source_key,metadata,created_by)
     values(p_tenant_id,p_variant_id,r.batch_id,'sale',v_take,p_location_id,p_customer_id,p_sale_id,p_sale_item_id,v_ref,'sale:'||p_sale_id::text||':item:'||p_sale_item_id::text||':batch:'||r.batch_id::text,jsonb_build_object('allocation','FEFO'),auth.uid());
   perform private.v483_create_warranty(p_tenant_id,p_variant_id,null,r.batch_id,p_customer_id,p_sale_id,p_sale_item_id,v_take,p_sale_date);
   v_remaining:=v_remaining-v_take;v_out:=v_out||jsonb_build_array(jsonb_build_object('batch_id',r.batch_id,'batch_number',r.batch_number,'quantity',v_take,'expiry_on',r.expiry_on));
  end loop;
  if v_remaining>0.000001 then raise exception 'Insufficient eligible unreserved batch stock. Required %, unavailable %',p_quantity,v_remaining;end if;
 end if;
 update public.inventory_batches_v483 b set status='exhausted',updated_at=now()
 where b.tenant_id=p_tenant_id and b.variant_id=p_variant_id and b.status='active'
   and not exists(select 1 from public.inventory_batch_balances_v483 bb where bb.tenant_id=b.tenant_id and bb.batch_id=b.id and bb.quantity>0);
 return v_out;
end$$;


--
-- Name: v483_apply_purchase_trace(uuid, uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v483_apply_purchase_trace(p_tenant_id uuid, p_purchase_id uuid, p_supplier_id uuid, p_location_id uuid, p_items jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare x jsonb;v_mode text;v_variant uuid;v_qty numeric;v_item_id uuid;v_serials jsonb;v_batches jsonb;v_count numeric;v_sum numeric;s jsonb;v_serial text;b jsonb;v_batch text;v_bqty numeric;v_mfg date;v_exp date;v_batch_id uuid;v_serial_id uuid;v_ref text;v_require boolean;v_seen_serials text[];v_seen_batches text[];begin
 if exists(select 1 from public.inventory_trace_events_v483 where tenant_id=p_tenant_id and purchase_id=p_purchase_id) then return;end if;
 select purchase_number into v_ref from public.purchases where tenant_id=p_tenant_id and id=p_purchase_id;
 for x in select value from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) loop
  v_variant:=(x->>'variant_id')::uuid;v_mode:=private.v483_tracking_mode(p_tenant_id,v_variant);if v_mode='none' then continue;end if;v_seen_serials:='{}'::text[];v_seen_batches:='{}'::text[];
  v_qty:=coalesce(nullif(x->>'quantity','')::numeric,0);select id into v_item_id from public.purchase_items where purchase_id=p_purchase_id and variant_id=v_variant limit 1;if v_item_id is null then raise exception 'Purchase line not found for tracked product';end if;
  if v_mode='serial' then
   if v_qty<>trunc(v_qty) then raise exception 'Serial-tracked product % requires whole base units',v_variant;end if;
   v_serials:=coalesce(x->'serial_numbers','[]'::jsonb);select count(*)::numeric into v_count from jsonb_array_elements(v_serials);if v_count<>v_qty then raise exception 'Provide exactly % serial numbers for tracked purchase line',v_qty;end if;
   for s in select value from jsonb_array_elements(v_serials) loop
    v_serial:=trim(coalesce(case when jsonb_typeof(s)='string' then s#>>'{}' else s->>'serial_number' end,''));if v_serial='' then raise exception 'Serial number cannot be blank';end if;
    if lower(v_serial)=any(v_seen_serials) then raise exception 'Duplicate serial number % on tracked purchase line',v_serial;end if;v_seen_serials:=array_append(v_seen_serials,lower(v_serial));
    insert into public.inventory_serials_v483(tenant_id,variant_id,serial_number,status,current_location_id,supplier_id,purchase_id,purchase_item_id,received_at,created_by) values(p_tenant_id,v_variant,v_serial,'in_stock',p_location_id,p_supplier_id,p_purchase_id,v_item_id,now(),auth.uid()) returning id into v_serial_id;
    insert into public.inventory_trace_events_v483(tenant_id,variant_id,serial_id,event_type,quantity,location_id,supplier_id,purchase_id,purchase_item_id,reference_number,source_key,created_by) values(p_tenant_id,v_variant,v_serial_id,'purchase',1,p_location_id,p_supplier_id,p_purchase_id,v_item_id,v_ref,'purchase:'||p_purchase_id::text||':serial:'||v_serial_id::text,auth.uid());
   end loop;
  else
   v_batches:=coalesce(x->'batches','[]'::jsonb);select coalesce(sum(coalesce(nullif(value->>'quantity','')::numeric,0)),0) into v_sum from jsonb_array_elements(v_batches);if abs(v_sum-v_qty)>0.000001 then raise exception 'Batch quantities must total base quantity %; received %',v_qty,v_sum;end if;
   select require_batch_expiry into v_require from public.product_tracking_policies_v483 where tenant_id=p_tenant_id and variant_id=v_variant;
   for b in select value from jsonb_array_elements(v_batches) loop
    v_batch:=trim(coalesce(b->>'batch_number',''));v_bqty:=coalesce(nullif(b->>'quantity','')::numeric,0);v_mfg:=nullif(b->>'manufactured_on','')::date;v_exp:=nullif(b->>'expiry_on','')::date;
    if v_batch='' or v_bqty<=0 then raise exception 'Each batch requires a batch number and positive quantity';end if;if lower(v_batch)=any(v_seen_batches) then raise exception 'Duplicate batch % on tracked purchase line',v_batch;end if;v_seen_batches:=array_append(v_seen_batches,lower(v_batch));if coalesce(v_require,false) and v_exp is null then raise exception 'Expiry date is required for batch %',v_batch;end if;
    insert into public.inventory_batches_v483(tenant_id,variant_id,batch_number,manufactured_on,expiry_on,supplier_id,first_purchase_id,first_purchase_item_id,created_by) values(p_tenant_id,v_variant,v_batch,v_mfg,v_exp,p_supplier_id,p_purchase_id,v_item_id,auth.uid())
    on conflict(tenant_id,variant_id,lower(trim(batch_number))) do update set manufactured_on=coalesce(public.inventory_batches_v483.manufactured_on,excluded.manufactured_on),expiry_on=coalesce(public.inventory_batches_v483.expiry_on,excluded.expiry_on),supplier_id=coalesce(public.inventory_batches_v483.supplier_id,excluded.supplier_id),status='active',updated_at=now() returning id into v_batch_id;
    if exists(select 1 from public.inventory_batches_v483 where id=v_batch_id and ((manufactured_on is not null and v_mfg is not null and manufactured_on<>v_mfg) or (expiry_on is not null and v_exp is not null and expiry_on<>v_exp))) then raise exception 'Batch % already exists with different manufacture/expiry dates',v_batch;end if;
    insert into public.inventory_batch_balances_v483(tenant_id,batch_id,location_id,quantity) values(p_tenant_id,v_batch_id,p_location_id,v_bqty) on conflict(tenant_id,batch_id,location_id) do update set quantity=public.inventory_batch_balances_v483.quantity+excluded.quantity,updated_at=now();
    insert into public.inventory_trace_events_v483(tenant_id,variant_id,batch_id,event_type,quantity,location_id,supplier_id,purchase_id,purchase_item_id,reference_number,source_key,created_by) values(p_tenant_id,v_variant,v_batch_id,'purchase',v_bqty,p_location_id,p_supplier_id,p_purchase_id,v_item_id,v_ref,'purchase:'||p_purchase_id::text||':item:'||v_item_id::text||':batch:'||v_batch_id::text,auth.uid());
   end loop;
  end if;
 end loop;
end$$;


--
-- Name: v483_apply_sale_trace(uuid, uuid, uuid, uuid, date, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v483_apply_sale_trace(p_tenant_id uuid, p_sale_id uuid, p_customer_id uuid, p_location_id uuid, p_sale_date date, p_items jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare x jsonb;v_mode text;v_variant uuid;v_qty numeric;v_item_id uuid;v_serials jsonb;v_count numeric;s jsonb;v_serial text;v_serial_id uuid;v_ref text;v_batches jsonb;
begin
 if exists(select 1 from public.inventory_trace_events_v483 where tenant_id=p_tenant_id and sale_id=p_sale_id) then return;end if;
 select sale_number into v_ref from public.sales where tenant_id=p_tenant_id and id=p_sale_id;
 for x in select value from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) loop
  v_variant:=(x->>'variant_id')::uuid;v_mode:=private.v483_tracking_mode(p_tenant_id,v_variant);if v_mode='none' then continue;end if;
  v_qty:=coalesce(nullif(x->>'quantity','')::numeric,0);select id into v_item_id from public.sale_items where sale_id=p_sale_id and variant_id=v_variant limit 1;if v_item_id is null then raise exception 'Sale line not found for tracked product';end if;
  if v_mode='serial' then
   if v_qty<>trunc(v_qty) then raise exception 'Serial-tracked product % requires whole base units',v_variant;end if;
   v_serials:=coalesce(x->'serial_numbers','[]'::jsonb);select count(*)::numeric into v_count from jsonb_array_elements(v_serials);if v_count<>v_qty then raise exception 'Provide exactly % serial numbers for tracked sale line',v_qty;end if;
   for s in select value from jsonb_array_elements(v_serials) loop
    v_serial:=trim(coalesce(case when jsonb_typeof(s)='string' then s#>>'{}' else s->>'serial_number' end,''));
    select id into v_serial_id from public.inventory_serials_v483
      where tenant_id=p_tenant_id and variant_id=v_variant and current_location_id=p_location_id and status='in_stock'
        and reserved_transfer_id is null and lower(trim(serial_number))=lower(v_serial) for update;
    if v_serial_id is null then raise exception 'Serial % is not available at the selected store (it may be reserved for transfer)',v_serial;end if;
    update public.inventory_serials_v483 set status='sold',current_location_id=null,customer_id=p_customer_id,sale_id=p_sale_id,sale_item_id=v_item_id,sold_at=now(),updated_at=now() where id=v_serial_id;
    insert into public.inventory_trace_events_v483(tenant_id,variant_id,serial_id,event_type,quantity,location_id,customer_id,sale_id,sale_item_id,reference_number,source_key,created_by)
      values(p_tenant_id,v_variant,v_serial_id,'sale',1,p_location_id,p_customer_id,p_sale_id,v_item_id,v_ref,'sale:'||p_sale_id::text||':serial:'||v_serial_id::text,auth.uid());
    perform private.v483_create_warranty(p_tenant_id,v_variant,v_serial_id,null,p_customer_id,p_sale_id,v_item_id,1,p_sale_date);
   end loop;
  else
   v_batches:=coalesce(x->'batches','[]'::jsonb);perform private.v483_apply_batch_sale(p_tenant_id,v_variant,p_sale_id,v_item_id,p_customer_id,p_location_id,p_sale_date,v_qty,v_batches);
  end if;
 end loop;
end$$;


--
-- Name: v483_assert_reconciled(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v483_assert_reconciled(p_tenant_id uuid, p_variant_id uuid, p_location_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_mode text;v_stock numeric;v_tracked numeric;begin
 v_mode:=private.v483_tracking_mode(p_tenant_id,p_variant_id);if v_mode='none' then return;end if;
 select coalesce(quantity,0) into v_stock from public.location_stock_balances where tenant_id=p_tenant_id and location_id=p_location_id and variant_id=p_variant_id;
 v_stock:=coalesce(v_stock,0);v_tracked:=private.v483_location_tracked_quantity(p_tenant_id,p_variant_id,p_location_id,v_mode);
 if abs(v_stock-v_tracked)>0.000001 then raise exception 'Tracked stock is not reconciled for product %. Ledger %, tracked %. Register/fix serial or batch opening stock before posting',p_variant_id,v_stock,v_tracked;end if;
end$$;


--
-- Name: v483_create_warranty(uuid, uuid, uuid, uuid, uuid, uuid, uuid, numeric, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v483_create_warranty(p_tenant_id uuid, p_variant_id uuid, p_serial_id uuid, p_batch_id uuid, p_customer_id uuid, p_sale_id uuid, p_sale_item_id uuid, p_quantity numeric, p_sale_date date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_enabled boolean;v_months integer;v_days integer;v_expiry date;begin
 select warranty_enabled,warranty_months,warranty_days into v_enabled,v_months,v_days from public.product_tracking_policies_v483 where tenant_id=p_tenant_id and variant_id=p_variant_id;
 if not coalesce(v_enabled,false) then return;end if;
 v_expiry:=(p_sale_date+make_interval(months=>coalesce(v_months,0),days=>coalesce(v_days,0)))::date;
 insert into public.product_warranties_v483(tenant_id,variant_id,serial_id,batch_id,customer_id,sale_id,sale_item_id,quantity,warranty_start,warranty_expiry,status,created_by)
 values(p_tenant_id,p_variant_id,p_serial_id,p_batch_id,p_customer_id,p_sale_id,p_sale_item_id,p_quantity,p_sale_date,v_expiry,'active',auth.uid()) on conflict do nothing;
end$$;


--
-- Name: v483_location_tracked_quantity(uuid, uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v483_location_tracked_quantity(p_tenant_id uuid, p_variant_id uuid, p_location_id uuid, p_mode text) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v numeric;begin
 if p_mode='serial' then
  select count(*)::numeric into v from public.inventory_serials_v483 where tenant_id=p_tenant_id and variant_id=p_variant_id and current_location_id=p_location_id and status in('in_stock','quarantine');
 elsif p_mode='batch' then
  select coalesce(sum(bb.quantity+coalesce(bb.damaged_quantity,0)),0) into v from public.inventory_batch_balances_v483 bb join public.inventory_batches_v483 b on b.id=bb.batch_id and b.tenant_id=bb.tenant_id where bb.tenant_id=p_tenant_id and bb.location_id=p_location_id and b.variant_id=p_variant_id;
 else v:=0;end if;return coalesce(v,0);
end$$;


--
-- Name: v483_trace_view_allowed(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v483_trace_view_allowed(p_tenant_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
 select private.erp_user_is_owner(p_tenant_id)
     or private.erp_has_permission(p_tenant_id,'inventory.view')
     or private.erp_has_permission(p_tenant_id,'inventory.manage')
     or private.erp_has_permission(p_tenant_id,'sales.view')
     or private.erp_has_permission(p_tenant_id,'sales.manage')
     or private.erp_has_permission(p_tenant_id,'purchases.view')
     or private.erp_has_permission(p_tenant_id,'purchases.manage')
$$;


--
-- Name: v483_tracking_mode(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v483_tracking_mode(p_tenant_id uuid, p_variant_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
 select coalesce((select tracking_mode from public.product_tracking_policies_v483 where tenant_id=p_tenant_id and variant_id=p_variant_id),'none')
$$;


--
-- Name: v484_invoice_ledger_after_status(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v484_invoice_ledger_after_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if new.status in('posted','part_paid','paid') and old.status='draft' then
    insert into public.supplier_ledger_entries_v484(tenant_id,supplier_id,location_id,entry_date,entry_type,source_id,reference_number,description,debit,credit,created_by)
    values(new.tenant_id,new.supplier_id,new.location_id,new.invoice_date,'purchase_invoice',new.id,new.invoice_number,'Purchase Invoice '||coalesce(new.supplier_invoice_number,new.invoice_number),new.grand_total,0,new.posted_by)
    on conflict(tenant_id,entry_type,source_id) do nothing;
  end if;
  return new;
end$$;


--
-- Name: v484_refresh_invoice_payment_status(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v484_refresh_invoice_payment_status(p_invoice_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_paid numeric;v_total numeric;v_status text;begin
 select grand_total,status into v_total,v_status from public.purchase_invoices_v484 where id=p_invoice_id for update;if not found or v_status='void' then return;end if;
 select coalesce(sum(a.amount),0) into v_paid from public.supplier_payment_allocations_v484 a join public.supplier_payments_v484 p on p.id=a.supplier_payment_id where a.purchase_invoice_id=p_invoice_id and p.status='posted';
 update public.purchase_invoices_v484 set paid_total=v_paid,balance_due=greatest(v_total-v_paid,0),status=case when v_paid>=v_total-0.005 then 'paid' when v_paid>0 then 'part_paid' else 'posted' end,updated_at=now() where id=p_invoice_id;
end$$;


--
-- Name: v485_transfer_history_add(uuid, uuid, text, text, text, text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v485_transfer_history_add(p_tenant_id uuid, p_transfer_id uuid, p_event_type text, p_from_status text, p_to_status text, p_note text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  insert into public.stock_transfer_history_v485(tenant_id,transfer_id,event_type,from_status,to_status,note,metadata,changed_by)
  values(p_tenant_id,p_transfer_id,p_event_type,nullif(p_from_status,''),nullif(p_to_status,''),nullif(trim(coalesce(p_note,'')),''),coalesce(p_metadata,'{}'::jsonb),auth.uid());
end$$;


--
-- Name: v485_transfer_release_reservation(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v485_transfer_release_reservation(p_transfer_id uuid, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v public.stock_transfers%rowtype;r record;a record;
begin
  select * into v from public.stock_transfers where id=p_transfer_id for update;
  if not found or not coalesce(v.reservation_applied,false) then return;end if;

  for r in select * from public.stock_transfer_items where transfer_id=v.id order by id loop
    update public.location_stock_balances
      set reserved_quantity=greatest(0,reserved_quantity-r.quantity),updated_at=now()
    where tenant_id=v.tenant_id and location_id=v.from_location_id and variant_id=r.variant_id;
  end loop;

  for a in select * from public.stock_transfer_allocations_v485 where transfer_id=v.id and status='reserved' order by id loop
    if a.serial_id is not null then
      update public.inventory_serials_v483
        set reserved_transfer_id=null,updated_at=now()
      where id=a.serial_id and tenant_id=v.tenant_id and reserved_transfer_id=v.id;
    elsif a.batch_id is not null then
      update public.inventory_batch_balances_v483
        set reserved_quantity=greatest(0,reserved_quantity-a.quantity),updated_at=now()
      where tenant_id=v.tenant_id and batch_id=a.batch_id and location_id=v.from_location_id;
    end if;
    update public.stock_transfer_allocations_v485
      set status='released',released_at=now(),updated_at=now()
    where id=a.id;
  end loop;

  update public.stock_transfers set reservation_applied=false,updated_at=now() where id=v.id;
end$$;


--
-- Name: v486_offline_conflict(uuid, uuid, uuid, text, text, text, text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v486_offline_conflict(p_tenant_id uuid, p_device_id uuid, p_location_id uuid, p_request_id text, p_local text, p_code text, p_message text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  insert into public.pos_offline_sync_v486(
    tenant_id,request_id,device_id,location_id,local_invoice_number,status,conflict_code,conflict_message,payload_snapshot,attempts,last_attempt_at,created_by,updated_at
  ) values(
    p_tenant_id,trim(p_request_id),p_device_id,p_location_id,p_local,'conflict',p_code,p_message,coalesce(p_payload,'{}'::jsonb),1,now(),auth.uid(),now()
  ) on conflict(tenant_id,request_id) do update set
    status='conflict',conflict_code=excluded.conflict_code,conflict_message=excluded.conflict_message,payload_snapshot=excluded.payload_snapshot,
    attempts=public.pos_offline_sync_v486.attempts+1,last_attempt_at=now(),updated_at=now();
  return jsonb_build_object('ok',false,'status','conflict','code',p_code,'message',p_message,'request_id',trim(p_request_id),'local_invoice_number',p_local);
end$$;


--
-- Name: v486_pos_device_location(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v486_pos_device_location(p_tenant_id uuid, p_device_id uuid, p_location_id uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_location uuid;v_type text;v_status text;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  select d.location_id,d.app_type,d.status into v_location,v_type,v_status
  from public.business_devices d where d.id=p_device_id and d.tenant_id=p_tenant_id;
  if v_location is null then raise exception 'POS terminal not found';end if;
  if v_status<>'active' then raise exception 'POS terminal is not active';end if;
  if v_type<>'pos' then raise exception 'Offline POS sync requires a POS terminal';end if;
  if p_location_id is not null and p_location_id<>v_location then raise exception 'POS terminal location mismatch';end if;
  return v_location;
end$$;


--
-- Name: v487_client_mobile_location(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v487_client_mobile_location(p_tenant_id uuid, p_device_id uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_location uuid;v_type text;v_status text;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  select d.location_id,d.app_type,d.status into v_location,v_type,v_status
  from public.business_devices d where d.id=p_device_id and d.tenant_id=p_tenant_id;
  if v_location is null then raise exception 'Client Mobile system not found';end if;
  if v_status<>'active' then raise exception 'Client Mobile system is not active';end if;
  if v_type<>'client' then raise exception 'Client Mobile requires a Client system activation';end if;
  if not private.erp_document_scope_allowed(p_tenant_id,v_location,v_location,'view') then raise exception 'Location access denied';end if;
  return v_location;
end$$;


--
-- Name: v488_mobile_pos_location(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v488_mobile_pos_location(p_tenant_id uuid, p_device_id uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  return private.v486_pos_device_location(p_tenant_id,p_device_id,null);
end$$;


--
-- Name: v491_ensure_financial_mappings(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v491_ensure_financial_mappings(p_tenant_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_id uuid; begin
  perform private.v47_ensure_accounting_for_tenant(p_tenant_id);

  select id into v_id from public.accounting_accounts where tenant_id=p_tenant_id and system_key='customer_credits' limit 1;
  if v_id is null then
    insert into public.accounting_accounts(tenant_id,code,name,account_type,system_key,is_system,description)
    values(p_tenant_id,'2051','Customer Refunds / Credits','liability','customer_credits',true,'Amounts owed or credited to customers after returns')
    on conflict(tenant_id,code) do update set name=excluded.name,account_type=excluded.account_type,system_key=excluded.system_key,is_system=true,description=excluded.description
    returning id into v_id;
  end if;
  insert into public.accounting_account_mappings(tenant_id,mapping_key,account_id) values(p_tenant_id,'customer_credits',v_id)
  on conflict(tenant_id,mapping_key) do update set account_id=excluded.account_id,updated_at=now();

  select id into v_id from public.accounting_accounts where tenant_id=p_tenant_id and system_key='supplier_credits' limit 1;
  if v_id is null then
    insert into public.accounting_accounts(tenant_id,code,name,account_type,system_key,is_system,description)
    values(p_tenant_id,'1151','Supplier Credits','asset','supplier_credits',true,'Credits/refunds due from suppliers after purchase returns')
    on conflict(tenant_id,code) do update set name=excluded.name,account_type=excluded.account_type,system_key=excluded.system_key,is_system=true,description=excluded.description
    returning id into v_id;
  end if;
  insert into public.accounting_account_mappings(tenant_id,mapping_key,account_id) values(p_tenant_id,'supplier_credits',v_id)
  on conflict(tenant_id,mapping_key) do update set account_id=excluded.account_id,updated_at=now();

  -- Keep all loan accounting mappings available for both existing and newly-created tenants.
  insert into public.accounting_accounts(tenant_id,code,name,account_type,system_key,is_system,description)
  select p_tenant_id,x.code,x.name,x.typ,x.key,true,x.descr
  from (values
    ('1110','Loan Receivable','asset','loan_receivable','Outstanding principal advanced by the business'),
    ('4020','Loan Interest Income','income','loan_interest_income','Interest earned on loans given'),
    ('4030','Loan Penalty Income','income','loan_penalty_income','Penalty income on loans given'),
    ('2210','Loan Payable','liability','loan_payable','Principal borrowed by the business'),
    ('5210','Loan Interest Expense','expense','loan_interest_expense','Interest paid or accrued on loans taken'),
    ('5220','Loan Penalty Expense','expense','loan_penalty_expense','Penalty and late charges on loans taken')
  ) as x(code,name,typ,key,descr)
  on conflict(tenant_id,code) do update
  set name=excluded.name,account_type=excluded.account_type,system_key=excluded.system_key,is_system=true,description=excluded.description;

  insert into public.accounting_account_mappings(tenant_id,mapping_key,account_id)
  select a.tenant_id,a.system_key,a.id
  from public.accounting_accounts a
  where a.tenant_id=p_tenant_id
    and a.system_key in ('loan_receivable','loan_interest_income','loan_penalty_income','loan_payable','loan_interest_expense','loan_penalty_expense')
  on conflict(tenant_id,mapping_key) do update set account_id=excluded.account_id,updated_at=now();
end $$;


--
-- Name: v495_refresh_notifications(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v495_refresh_notifications(p_tenant_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare r record;
begin
  -- Customer balances becoming due in the next three days.
  for r in
    select s.id,s.due_date,c.name,o.location_id,
      greatest(s.grand_total-coalesce(py.paid,0)-coalesce(rt.returned,0),0) balance
    from public.sales s join public.customers c on c.id=s.customer_id
    left join(select sale_id,sum(amount) paid from public.sale_payments group by sale_id)py on py.sale_id=s.id
    left join(select sale_id,sum(grand_total) returned from public.sales_returns where refund_status<>'waived' group by sale_id)rt on rt.sale_id=s.id
    left join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='sale' and o.entity_id=s.id
    where s.tenant_id=p_tenant_id and s.due_date between current_date and current_date+3
      and coalesce(s.status,'') not in('void','cancelled')
      and greatest(s.grand_total-coalesce(py.paid,0)-coalesce(rt.returned,0),0)>0.005
      and (o.location_id is null or private.erp_user_is_owner(p_tenant_id) or private.erp_user_location_allowed(p_tenant_id,o.location_id,'view'))
    order by s.due_date limit 100
  loop
    if not exists(select 1 from public.notifications n where n.tenant_id=p_tenant_id and n.user_id=p_user_id and n.category='receivable' and n.entity_type='sale' and n.entity_id=r.id and n.title like 'Payment due soon%' and n.read_at is null and n.created_at>now()-interval '24 hours') then
      insert into public.notifications(tenant_id,user_id,location_id,category,severity,title,message,entity_type,entity_id)
      values(p_tenant_id,p_user_id,r.location_id,'receivable','info','Payment due soon • '||r.name,'Balance '||round(r.balance,2)||' • due '||r.due_date,'sale',r.id);
    end if;
  end loop;

  -- Supplier payable exposure, including Purchasing V2 invoices.
  for r in
    select * from public.supplier_payables_intelligence_v480(p_tenant_id,null,'',1000)
    where (days_1_30+days_31_60+days_61_90+days_90_plus)>0.005
    order by days_90_plus desc,total_outstanding desc limit 100
  loop
    if not exists(select 1 from public.notifications n where n.tenant_id=p_tenant_id and n.user_id=p_user_id and n.category='payable' and n.entity_type='supplier' and n.entity_id=r.supplier_id and n.read_at is null and n.created_at>now()-interval '24 hours') then
      insert into public.notifications(tenant_id,user_id,category,severity,title,message,entity_type,entity_id)
      values(p_tenant_id,p_user_id,'payable',case when r.days_90_plus>0 then 'critical' else 'warning' end,'Supplier payment overdue • '||r.supplier_name,
        'Outstanding '||round(r.total_outstanding,2)||case when r.oldest_due_date is null then '' else ' • oldest due '||r.oldest_due_date::text end,'supplier',r.supplier_id);
    end if;
  end loop;

  -- Pending approvals for users able to approve.
  if private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'approvals.approve') then
    for r in select id,module_key,action_key,entity_type,entity_id,amount,requested_at from public.approval_requests where tenant_id=p_tenant_id and status='pending' order by requested_at limit 100 loop
      if not exists(select 1 from public.notifications n where n.tenant_id=p_tenant_id and n.user_id=p_user_id and n.category='approval' and n.entity_type='approval_request' and n.entity_id=r.id and n.read_at is null and n.created_at>now()-interval '12 hours') then
        insert into public.notifications(tenant_id,user_id,category,severity,title,message,entity_type,entity_id)
        values(p_tenant_id,p_user_id,'approval','warning','Approval required • '||replace(r.module_key,'_',' '),replace(r.action_key,'_',' ')||coalesce(' • amount '||round(r.amount,2)::text,'')||' • requested '||r.requested_at,'approval_request',r.id);
      end if;
    end loop;
  end if;

  -- Explicit task reminders, including unassigned tasks for owners/managers.
  for r in
    select id,title,due_at,reminder_at,location_id,assigned_to,priority
    from public.business_tasks
    where tenant_id=p_tenant_id and status not in('done','cancelled')
      and (assigned_to=p_user_id or (assigned_to is null and (private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'tasks.manage'))))
      and coalesce(reminder_at,due_at) is not null and coalesce(reminder_at,due_at)<=now()+interval '15 minutes'
    order by coalesce(reminder_at,due_at) limit 100
  loop
    if not exists(select 1 from public.notifications n where n.tenant_id=p_tenant_id and n.user_id=p_user_id and n.category='task' and n.entity_type='task' and n.entity_id=r.id and n.read_at is null and n.created_at>now()-interval '6 hours') then
      insert into public.notifications(tenant_id,user_id,location_id,category,severity,title,message,entity_type,entity_id)
      values(p_tenant_id,p_user_id,r.location_id,'task',case when r.due_at is not null and r.due_at<now() then 'critical' when r.priority in('urgent','high') then 'warning' else 'info' end,
        case when r.due_at is not null and r.due_at<now() then 'Task overdue • ' else 'Task reminder • ' end||r.title,
        case when r.due_at is null then 'Task requires attention' else 'Due '||r.due_at end,'task',r.id);
    end if;
  end loop;
end $$;


--
-- Name: v4_account_id(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v4_account_id(p_tenant_id uuid, p_key text) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v uuid;begin
  select account_id into v from public.accounting_account_mappings where tenant_id=p_tenant_id and mapping_key=p_key;
  if v is null then select id into v from public.accounting_accounts where tenant_id=p_tenant_id and system_key=replace(p_key,'payment.','') and active limit 1;end if;
  if v is null then raise exception 'Accounting mapping % is not configured',p_key;end if;return v;
end $$;


--
-- Name: v4_accounting_post_document(uuid, text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v4_accounting_post_document(p_tenant_id uuid, p_entity_type text, p_entity_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v_loc uuid;v_origin_created timestamptz;v_total numeric;v_tax numeric;v_net numeric;v_cost numeric:=0;v_paid numeric:=0;v_round numeric:=0;v_subtotal numeric:=0;v_discount numeric:=0;v_charges numeric:=0;v_method text:='cash';v_date date;v_ref text;v_party uuid;v_lines jsonb:='[]'::jsonb;v_pay_account uuid;begin if private.gst_v520_authoritative_context_for_source(p_tenant_id,p_entity_type,p_entity_id) then return null;end if;select location_id,created_at into v_loc,v_origin_created from public.document_origins where tenant_id=p_tenant_id and entity_type=p_entity_type and entity_id=p_entity_id order by created_at limit 1;if p_entity_type='sale' then select grand_total,tax_total,round_off,greatest(grand_total-tax_total-round_off,0),cost_total,sale_date,sale_number,customer_id into v_total,v_tax,v_round,v_net,v_cost,v_date,v_ref,v_party from public.sales where id=p_entity_id and tenant_id=p_tenant_id;if not found then return null;end if;select coalesce(sum(amount),0),(array_agg(payment_method order by paid_at,id))[1] into v_paid,v_method from public.sale_payments where sale_id=p_entity_id and (v_origin_created is null or created_at<=v_origin_created);v_paid:=least(coalesce(v_paid,0),v_total);v_pay_account:=private.v4_payment_account(p_tenant_id,v_method);if v_paid>0 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',v_pay_account,'debit',v_paid,'credit',0,'party_type','customer','party_id',v_party,'description','Sale receipt'));end if;if v_total-v_paid>0.005 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'accounts_receivable'),'debit',v_total-v_paid,'credit',0,'party_type','customer','party_id',v_party,'description','Customer receivable'));end if;if v_net>0 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'sales_revenue'),'debit',0,'credit',v_net,'party_type','customer','party_id',v_party,'description','Sales revenue'));end if;if v_tax>0 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'output_gst'),'debit',0,'credit',v_tax,'description','Output GST'));end if;if v_round>0.000001 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'rounding'),'debit',0,'credit',v_round,'description','Sale round off'));end if;if v_round< -0.000001 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'rounding'),'debit',abs(v_round),'credit',0,'description','Sale round off'));end if;if coalesce(v_cost,0)>0 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'cogs'),'debit',v_cost,'credit',0,'description','Cost of goods sold'),jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'inventory_asset'),'debit',0,'credit',v_cost,'description','Inventory issued'));end if;return private.v4_journal_create(p_tenant_id,v_loc,v_date,'Sale '||v_ref,'sale',p_entity_id,v_ref,v_lines);elsif p_entity_type='purchase' then select grand_total,tax_total,round_off,subtotal,discount_total,additional_charges,purchase_date,purchase_number,supplier_id into v_total,v_tax,v_round,v_subtotal,v_discount,v_charges,v_date,v_ref,v_party from public.purchases where id=p_entity_id and tenant_id=p_tenant_id;if not found then return null;end if;select coalesce(sum(amount),0),(array_agg(payment_method order by paid_at,id))[1] into v_paid,v_method from public.purchase_payments where purchase_id=p_entity_id and (v_origin_created is null or created_at<=v_origin_created);v_paid:=least(coalesce(v_paid,0),v_total);v_pay_account:=private.v4_payment_account(p_tenant_id,v_method);if v_subtotal>0 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'inventory_asset'),'debit',v_subtotal,'credit',0,'party_type','supplier','party_id',v_party,'description','Purchased inventory at ERP item cost'));end if;if v_tax>0 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'input_gst'),'debit',v_tax,'credit',0,'description','Input GST'));end if;if v_charges>0 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'purchase_expense'),'debit',v_charges,'credit',0,'description','Purchase additional charges'));end if;if v_discount>0 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',private.v500_purchase_discount_account(p_tenant_id),'debit',0,'credit',v_discount,'description','Supplier purchase discount'));end if;if v_round>0.000001 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'rounding'),'debit',v_round,'credit',0,'description','Purchase round off'));end if;if v_round< -0.000001 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'rounding'),'debit',0,'credit',abs(v_round),'description','Purchase round off'));end if;if v_paid>0 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',v_pay_account,'debit',0,'credit',v_paid,'party_type','supplier','party_id',v_party,'description','Supplier payment'));end if;if v_total-v_paid>0.005 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'accounts_payable'),'debit',0,'credit',v_total-v_paid,'party_type','supplier','party_id',v_party,'description','Supplier payable'));end if;return private.v4_journal_create(p_tenant_id,v_loc,v_date,'Purchase '||v_ref,'purchase',p_entity_id,v_ref,v_lines);elsif p_entity_type='expense' then select total_amount,tax_amount,round_off,greatest(total_amount-tax_amount-round_off,0),expense_date,expense_number into v_total,v_tax,v_round,v_net,v_date,v_ref from public.expenses where id=p_entity_id and tenant_id=p_tenant_id;if not found then return null;end if;select payment_method into v_method from public.expenses where id=p_entity_id;v_pay_account:=private.v4_payment_account(p_tenant_id,v_method);if v_net>0 then v_lines:=jsonb_build_array(jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'operating_expense'),'debit',v_net,'credit',0,'description','Operating expense'));end if;if v_tax>0 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'input_gst'),'debit',v_tax,'credit',0,'description','Input GST'));end if;if v_round>0.000001 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'rounding'),'debit',v_round,'credit',0,'description','Expense round off'));end if;if v_round< -0.000001 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'rounding'),'debit',0,'credit',abs(v_round),'description','Expense round off'));end if;v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',v_pay_account,'debit',0,'credit',v_total,'description','Expense payment'));return private.v4_journal_create(p_tenant_id,v_loc,v_date,'Expense '||v_ref,'expense',p_entity_id,v_ref,v_lines);end if;return null;end $$;


--
-- Name: v4_journal_create(uuid, uuid, date, text, text, uuid, text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v4_journal_create(p_tenant_id uuid, p_location_id uuid, p_entry_date date, p_description text, p_source_type text, p_source_id uuid, p_source_reference text, p_lines jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v_id uuid:=gen_random_uuid();v_no text;x jsonb;v_dr numeric:=0;v_cr numeric:=0;v_debit numeric;v_credit numeric;v_account uuid;begin if p_source_type is not null and p_source_id is not null and exists(select 1 from public.journal_entries where tenant_id=p_tenant_id and source_type=p_source_type and source_id=p_source_id and status='posted') then select id into v_id from public.journal_entries where tenant_id=p_tenant_id and source_type=p_source_type and source_id=p_source_id and status='posted' order by created_at limit 1;return v_id;end if;perform private.v500_assert_posting_period_open(p_tenant_id,p_entry_date);if p_location_id is not null and not exists(select 1 from public.business_locations where id=p_location_id and tenant_id=p_tenant_id) then raise exception 'Invalid accounting location';end if;if jsonb_typeof(coalesce(p_lines,'null'::jsonb))<>'array' or jsonb_array_length(p_lines)<2 then raise exception 'Journal must contain at least two lines';end if;for x in select value from jsonb_array_elements(p_lines) loop begin v_account:=(x->>'account_id')::uuid;v_debit:=round(coalesce(nullif(x->>'debit','')::numeric,0),2);v_credit:=round(coalesce(nullif(x->>'credit','')::numeric,0),2);exception when others then raise exception 'Invalid journal line';end;if not exists(select 1 from public.accounting_accounts a where a.id=v_account and a.tenant_id=p_tenant_id and a.active) then raise exception 'Journal account % is missing, inactive or belongs to another business',v_account;end if;if v_debit<0 or v_credit<0 or (v_debit>0 and v_credit>0) or (v_debit=0 and v_credit=0) then raise exception 'Each journal line must contain exactly one positive debit or credit';end if;v_dr:=v_dr+v_debit;v_cr:=v_cr+v_credit;end loop;v_dr:=round(v_dr,2);v_cr:=round(v_cr,2);if v_dr<=0 or v_cr<=0 or v_dr<>v_cr then raise exception 'Journal is not balanced. Debit %, Credit %',v_dr,v_cr;end if;v_no:='JRN-'||lpad(nextval('public.journal_entry_number_seq')::text,8,'0');insert into public.journal_entries(id,tenant_id,location_id,entry_number,entry_date,description,status,source_type,source_id,source_reference,created_by,posted_at) values(v_id,p_tenant_id,p_location_id,v_no,p_entry_date,coalesce(nullif(trim(p_description),''),'Journal entry'),'posted',nullif(trim(coalesce(p_source_type,'')),''),p_source_id,nullif(trim(coalesce(p_source_reference,'')),''),auth.uid(),now());for x in select value from jsonb_array_elements(p_lines) loop insert into public.journal_lines(journal_entry_id,account_id,party_type,party_id,description,debit,credit) values(v_id,(x->>'account_id')::uuid,nullif(x->>'party_type',''),nullif(x->>'party_id','')::uuid,nullif(trim(coalesce(x->>'description','')),''),round(coalesce(nullif(x->>'debit','')::numeric,0),2),round(coalesce(nullif(x->>'credit','')::numeric,0),2));end loop;return v_id;end $$;


--
-- Name: v4_location_access(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v4_location_access(p_tenant_id uuid, p_location_id uuid, p_required text DEFAULT 'view'::text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  if not exists(select 1 from public.business_locations where id=p_location_id and tenant_id=p_tenant_id and active) then
    raise exception 'Invalid or inactive location';
  end if;
  if private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'locations.manage_all') then return; end if;
  if lower(coalesce(p_required,'view'))='view' and private.erp_has_permission(p_tenant_id,'locations.view_all') then return; end if;
  if not private.erp_user_location_allowed(p_tenant_id,p_location_id,p_required) then
    raise exception 'Location % access denied',p_required;
  end if;
end $$;


--
-- Name: v4_location_stock_apply(uuid, uuid, uuid, numeric, text, text, uuid, text, text, uuid, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v4_location_stock_apply(p_tenant_id uuid, p_location_id uuid, p_variant_id uuid, p_delta numeric, p_movement_type text, p_reference_type text DEFAULT NULL::text, p_reference_id uuid DEFAULT NULL::uuid, p_reference_number text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_device_id uuid DEFAULT NULL::uuid, p_allow_negative boolean DEFAULT false) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_before numeric:=0;v_after numeric;v_cost numeric:=0;v_reserved numeric:=0;v_damaged numeric:=0;v_quarantine numeric:=0;v_available numeric:=0;v_unit uuid;v_unit_code text;
begin
  insert into public.location_stock_balances(tenant_id,location_id,variant_id,quantity,average_cost,updated_at)
  values(p_tenant_id,p_location_id,p_variant_id,0,0,now()) on conflict(tenant_id,location_id,variant_id) do nothing;
  select b.quantity,b.reserved_quantity,b.damaged_quantity,b.quarantine_quantity into v_before,v_reserved,v_damaged,v_quarantine
  from public.location_stock_balances b where b.tenant_id=p_tenant_id and b.location_id=p_location_id and b.variant_id=p_variant_id for update;
  v_before:=coalesce(v_before,0);v_reserved:=coalesce(v_reserved,0);v_damaged:=coalesce(v_damaged,0);v_quarantine:=coalesce(v_quarantine,0);
  v_available:=v_before-v_reserved-v_damaged-v_quarantine;v_after:=v_before+coalesce(p_delta,0);
  if not p_allow_negative and coalesce(p_delta,0)<0 and v_available+coalesce(p_delta,0)<-0.000001 then raise exception 'Insufficient available stock at selected location. Available: %, requested: %',v_available,abs(p_delta);end if;
  if not p_allow_negative and v_after<0 then raise exception 'Insufficient physical stock at selected location';end if;
  select coalesce(pv.cost_price,0) into v_cost from public.product_variants pv where pv.id=p_variant_id and pv.tenant_id=p_tenant_id;
  select pu.unit_id,u.code into v_unit,v_unit_code from public.product_units_v481 pu join public.inventory_units_v481 u on u.id=pu.unit_id where pu.tenant_id=p_tenant_id and pu.variant_id=p_variant_id and pu.is_base and pu.active limit 1;
  insert into public.location_product_settings(tenant_id,location_id,variant_id,active) values(p_tenant_id,p_location_id,p_variant_id,true) on conflict(tenant_id,location_id,variant_id) do nothing;
  update public.location_stock_balances set quantity=v_after,average_cost=case when v_cost<>0 then v_cost else average_cost end,updated_at=now() where tenant_id=p_tenant_id and location_id=p_location_id and variant_id=p_variant_id;
  insert into public.location_stock_movements(tenant_id,location_id,variant_id,movement_type,quantity_delta,base_quantity_delta,display_quantity,unit_id,unit_code,conversion_to_base,balance_before,balance_after,unit_cost,reference_type,reference_id,reference_number,note,created_by,device_id,movement_group)
  values(p_tenant_id,p_location_id,p_variant_id,p_movement_type,p_delta,p_delta,p_delta,v_unit,v_unit_code,1,v_before,v_after,v_cost,p_reference_type,p_reference_id,p_reference_number,nullif(trim(coalesce(p_note,'')),''),auth.uid(),p_device_id,case when p_movement_type like 'transfer_%' then 'transfer' when p_movement_type like 'production_%' then 'production' else p_movement_type end);
  return v_after;
end $$;


--
-- Name: v4_origin_after_insert(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v4_origin_after_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_shift uuid;v_cash numeric;v_ref text;v_method text;begin if not private.gst_v520_authoritative_context_for_source(new.tenant_id,new.entity_type,new.entity_id) then perform private.v4_accounting_post_document(new.tenant_id,new.entity_type,new.entity_id);end if;if new.device_id is not null then select id into v_shift from public.cashier_shifts where tenant_id=new.tenant_id and device_id=new.device_id and status='open' order by opened_at desc limit 1;end if;if v_shift is not null and new.entity_type='sale' then select coalesce(sum(amount),0),max(s.sale_number) into v_cash,v_ref from public.sale_payments p join public.sales s on s.id=p.sale_id where p.sale_id=new.entity_id and lower(coalesce(p.payment_method,''))='cash';if v_cash>0 and not exists(select 1 from public.cash_drawer_movements where shift_id=v_shift and reference_type='sale' and reference_id=new.entity_id) then insert into public.cash_drawer_movements(tenant_id,shift_id,movement_type,amount,reference_type,reference_id,reference_number,note,created_by) values(new.tenant_id,v_shift,'sale',v_cash,'sale',new.entity_id,v_ref,'Cash sale',new.created_by);end if;elsif v_shift is not null and new.entity_type='expense' then select payment_method,total_amount,expense_number into v_method,v_cash,v_ref from public.expenses where id=new.entity_id and tenant_id=new.tenant_id;if lower(coalesce(v_method,''))='cash' and coalesce(v_cash,0)>0 and not exists(select 1 from public.cash_drawer_movements where shift_id=v_shift and reference_type='expense' and reference_id=new.entity_id) then insert into public.cash_drawer_movements(tenant_id,shift_id,movement_type,amount,reference_type,reference_id,reference_number,note,created_by) values(new.tenant_id,v_shift,'expense',-abs(v_cash),'expense',new.entity_id,v_ref,'Cash expense',new.created_by);end if;end if;return new;end $$;


--
-- Name: v4_payment_account(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v4_payment_account(p_tenant_id uuid, p_method text) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare k text:=lower(coalesce(p_method,'cash'));begin
  if k in('cash') then k:='cash';elsif k in('upi') then k:='upi';elsif k in('card','credit_card','debit_card') then k:='card';else k:='bank';end if;
  return private.v4_account_id(p_tenant_id,'payment.'||k);
end $$;


--
-- Name: v4_post_purchase_return(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v4_post_purchase_return(p_return_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  r public.purchase_returns%rowtype;
  v_purchase public.purchases%rowtype;
  v_paid numeric:=0;
  v_previous_returns numeric:=0;
  v_payable_before numeric:=0;
  v_ap_reduce numeric:=0;
  v_supplier_credit numeric:=0;
  v_lines jsonb:='[]'::jsonb;
begin
  select * into r from public.purchase_returns where id=p_return_id;
  if not found or coalesce(r.grand_total,0)<=0 then return null; end if;
  select * into v_purchase from public.purchases where id=r.purchase_id and tenant_id=r.tenant_id;
  if not found then return null; end if;
  perform private.v491_ensure_financial_mappings(r.tenant_id);

  if exists(select 1 from public.journal_entries where tenant_id=r.tenant_id and source_type='purchase_return' and source_id=r.id and status='posted') then
    return (select id from public.journal_entries where tenant_id=r.tenant_id and source_type='purchase_return' and source_id=r.id and status='posted' limit 1);
  end if;

  select coalesce(sum(amount),0) into v_paid from public.purchase_payments where purchase_id=r.purchase_id;
  select coalesce(sum(grand_total),0) into v_previous_returns
  from public.purchase_returns
  where purchase_id=r.purchase_id and id<>r.id and created_at<=r.created_at and credit_status<>'waived';

  v_payable_before:=greatest(coalesce(v_purchase.grand_total,0)-v_paid-v_previous_returns,0);
  v_ap_reduce:=least(coalesce(r.grand_total,0),v_payable_before);
  v_supplier_credit:=greatest(coalesce(r.grand_total,0)-v_ap_reduce,0);

  if v_ap_reduce>0 then
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
      'account_id',private.v4_account_id(r.tenant_id,'accounts_payable'),'debit',v_ap_reduce,'credit',0,
      'party_type','supplier','party_id',v_purchase.supplier_id,'description','Reduce supplier payable'));
  end if;
  if v_supplier_credit>0 then
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
      'account_id',private.v4_account_id(r.tenant_id,'supplier_credits'),'debit',v_supplier_credit,'credit',0,
      'party_type','supplier','party_id',v_purchase.supplier_id,'description','Supplier return credit / refund due'));
  end if;
  if coalesce(r.subtotal,0)>0 then
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
      'account_id',private.v4_account_id(r.tenant_id,'inventory_asset'),'debit',0,'credit',r.subtotal,
      'party_type','supplier','party_id',v_purchase.supplier_id,'description','Purchase return inventory reduction'));
  end if;
  if coalesce(r.tax_total,0)>0 then
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
      'account_id',private.v4_account_id(r.tenant_id,'input_gst'),'debit',0,'credit',r.tax_total,
      'description','Purchase return input GST reversal'));
  end if;

  return private.v4_journal_create(r.tenant_id,r.location_id,r.return_date,'Purchase return '||r.return_number,'purchase_return',r.id,r.return_number,v_lines);
end $$;


--
-- Name: v4_post_sales_return(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v4_post_sales_return(p_return_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  r public.sales_returns%rowtype;
  v_sale public.sales%rowtype;
  v_paid numeric:=0;
  v_previous_returns numeric:=0;
  v_outstanding_before numeric:=0;
  v_ar_reduce numeric:=0;
  v_customer_credit numeric:=0;
  v_cost numeric:=0;
  v_lines jsonb:='[]'::jsonb;
begin
  select * into r from public.sales_returns where id=p_return_id;
  if not found or coalesce(r.grand_total,0)<=0 then return null; end if;
  select * into v_sale from public.sales where id=r.sale_id and tenant_id=r.tenant_id;
  if not found then return null; end if;
  perform private.v491_ensure_financial_mappings(r.tenant_id);

  if exists(select 1 from public.journal_entries where tenant_id=r.tenant_id and source_type='sales_return' and source_id=r.id and status='posted') then
    return (select id from public.journal_entries where tenant_id=r.tenant_id and source_type='sales_return' and source_id=r.id and status='posted' limit 1);
  end if;

  select coalesce(sum(amount),0) into v_paid from public.sale_payments where sale_id=r.sale_id;
  select coalesce(sum(grand_total),0) into v_previous_returns
  from public.sales_returns
  where sale_id=r.sale_id and id<>r.id and created_at<=r.created_at and refund_status<>'waived';

  v_outstanding_before:=greatest(coalesce(v_sale.grand_total,0)-v_paid-v_previous_returns,0);
  v_ar_reduce:=least(coalesce(r.grand_total,0),v_outstanding_before);
  v_customer_credit:=greatest(coalesce(r.grand_total,0)-v_ar_reduce,0);

  select coalesce(sum(coalesce(si.cost_total,0)*(ri.quantity/nullif(si.quantity,0))),0)
  into v_cost
  from public.sales_return_items ri
  join public.sale_items si on si.id=ri.sale_item_id
  where ri.sales_return_id=r.id;

  if coalesce(r.subtotal,0)>0 then
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
      'account_id',private.v4_account_id(r.tenant_id,'sales_revenue'),'debit',r.subtotal,'credit',0,
      'party_type','customer','party_id',v_sale.customer_id,'description','Sales return revenue reversal'));
  end if;
  if coalesce(r.tax_total,0)>0 then
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
      'account_id',private.v4_account_id(r.tenant_id,'output_gst'),'debit',r.tax_total,'credit',0,
      'description','Sales return GST reversal'));
  end if;
  if v_ar_reduce>0 then
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
      'account_id',private.v4_account_id(r.tenant_id,'accounts_receivable'),'debit',0,'credit',v_ar_reduce,
      'party_type','customer','party_id',v_sale.customer_id,'description','Reduce customer receivable'));
  end if;
  if v_customer_credit>0 then
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
      'account_id',private.v4_account_id(r.tenant_id,'customer_credits'),'debit',0,'credit',v_customer_credit,
      'party_type','customer','party_id',v_sale.customer_id,'description','Customer return credit / refund due'));
  end if;
  if v_cost>0 then
    v_lines:=v_lines||jsonb_build_array(
      jsonb_build_object('account_id',private.v4_account_id(r.tenant_id,'inventory_asset'),'debit',v_cost,'credit',0,'description','Returned inventory restored'),
      jsonb_build_object('account_id',private.v4_account_id(r.tenant_id,'cogs'),'debit',0,'credit',v_cost,'description','COGS reversed for returned goods')
    );
  end if;

  return private.v4_journal_create(r.tenant_id,r.location_id,r.return_date,'Sales return '||r.return_number,'sales_return',r.id,r.return_number,v_lines);
end $$;


--
-- Name: v4_purchase_payment_after_insert(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v4_purchase_payment_after_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_tenant uuid;v_loc uuid;v_ref text;v_supplier uuid;v_lines jsonb;begin
  select p.tenant_id,p.purchase_number,p.supplier_id,o.location_id into v_tenant,v_ref,v_supplier,v_loc from public.purchases p left join public.document_origins o on o.entity_type='purchase' and o.entity_id=p.id where p.id=new.purchase_id;
  if v_tenant is null or v_loc is null then return new;end if;if exists(select 1 from public.journal_entries where tenant_id=v_tenant and source_type='purchase_payment' and source_id=new.id) then return new;end if;
  v_lines:=jsonb_build_array(jsonb_build_object('account_id',private.v4_account_id(v_tenant,'accounts_payable'),'debit',new.amount,'credit',0,'party_type','supplier','party_id',v_supplier,'description','Payable settlement'),jsonb_build_object('account_id',private.v4_payment_account(v_tenant,new.payment_method),'debit',0,'credit',new.amount,'party_type','supplier','party_id',v_supplier,'description','Supplier payment'));
  perform private.v4_journal_create(v_tenant,v_loc,coalesce(new.paid_at::date,current_date),'Supplier payment • '||v_ref,'purchase_payment',new.id,v_ref,v_lines);return new;
end $$;


--
-- Name: v4_purchase_return_accounting_trigger(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v4_purchase_return_accounting_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if private.gst_v520_authoritative_context_for_source(new.tenant_id,'purchase_return',new.id) then
    return new;
  end if;
  if coalesce(new.grand_total,0)>0 and (tg_op='INSERT' or coalesce(old.grand_total,0)<>coalesce(new.grand_total,0)) then
    perform private.v4_post_purchase_return(new.id);
  end if;
  return new;
end
$$;


--
-- Name: v4_purchase_void_accounting_trigger(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v4_purchase_void_accounting_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if coalesce(old.status,'')<>'void' and coalesce(new.status,'')='void' then
    perform private.v4_reverse_source_journal(new.tenant_id,'purchase',new.id,'purchase_void','Void purchase '||coalesce(new.purchase_number,''));
  end if;
  return new;
end $$;


--
-- Name: v4_refresh_notifications(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v4_refresh_notifications(p_tenant_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare r record;begin
  -- Low stock per accessible branch.
  for r in
    select s.location_id,s.variant_id,p.name product_name,l.name location_name,coalesce(b.quantity,0) qty,coalesce(s.reorder_level,pv.reorder_level,0) reorder
    from public.location_product_settings s join public.product_variants pv on pv.id=s.variant_id join public.products p on p.id=pv.product_id join public.business_locations l on l.id=s.location_id
    left join public.location_stock_balances b on b.tenant_id=s.tenant_id and b.location_id=s.location_id and b.variant_id=s.variant_id
    where s.tenant_id=p_tenant_id and s.active and l.active and coalesce(s.reorder_level,pv.reorder_level,0)>0 and coalesce(b.quantity,0)<=coalesce(s.reorder_level,pv.reorder_level,0)
      and (private.erp_user_is_owner(p_tenant_id) or private.erp_user_location_allowed(p_tenant_id,s.location_id,'view'))
    limit 100
  loop
    if not exists(select 1 from public.notifications n where n.tenant_id=p_tenant_id and n.user_id=p_user_id and n.category='stock' and n.entity_type='product_variant' and n.entity_id=r.variant_id and n.location_id=r.location_id and n.read_at is null and n.created_at>now()-interval '24 hours') then
      insert into public.notifications(tenant_id,user_id,location_id,category,severity,title,message,entity_type,entity_id)
      values(p_tenant_id,p_user_id,r.location_id,'stock',case when r.qty<=0 then 'critical' else 'warning' end,'Low stock • '||r.product_name,r.location_name||': '||r.qty||' available (reorder '||r.reorder||')','product_variant',r.variant_id);
    end if;
  end loop;

  -- Overdue customer receivables.
  for r in
    select s.id,s.due_date,c.name,coalesce(o.location_id,null) location_id,
      greatest(s.grand_total-coalesce(py.paid,0)-coalesce(rt.returned,0),0) balance
    from public.sales s join public.customers c on c.id=s.customer_id
    left join (select sale_id,sum(amount) paid from public.sale_payments group by sale_id)py on py.sale_id=s.id
    left join (select sale_id,sum(grand_total) returned from public.sales_returns where refund_status<>'waived' group by sale_id)rt on rt.sale_id=s.id
    left join public.document_origins o on o.entity_type='sale' and o.entity_id=s.id
    where s.tenant_id=p_tenant_id and s.due_date is not null and s.due_date<current_date and coalesce(s.status,'') not in('void','cancelled')
      and greatest(s.grand_total-coalesce(py.paid,0)-coalesce(rt.returned,0),0)>0.005
      and (o.location_id is null or private.erp_user_is_owner(p_tenant_id) or private.erp_user_location_allowed(p_tenant_id,o.location_id,'view'))
    order by s.due_date limit 100
  loop
    if not exists(select 1 from public.notifications n where n.tenant_id=p_tenant_id and n.user_id=p_user_id and n.category='receivable' and n.entity_type='sale' and n.entity_id=r.id and n.read_at is null and n.created_at>now()-interval '24 hours') then
      insert into public.notifications(tenant_id,user_id,location_id,category,severity,title,message,entity_type,entity_id)
      values(p_tenant_id,p_user_id,r.location_id,'receivable','warning','Customer payment overdue',r.name||' • balance '||round(r.balance,2)||' • due '||r.due_date,'sale',r.id);
    end if;
  end loop;

  -- Tasks due/overdue assigned to the current user.
  for r in select id,title,due_at,location_id from public.business_tasks where tenant_id=p_tenant_id and assigned_to=p_user_id and status not in('done','cancelled') and due_at is not null and due_at<=now()+interval '24 hours' limit 100 loop
    if not exists(select 1 from public.notifications n where n.tenant_id=p_tenant_id and n.user_id=p_user_id and n.category='task' and n.entity_type='task' and n.entity_id=r.id and n.read_at is null and n.created_at>now()-interval '12 hours') then
      insert into public.notifications(tenant_id,user_id,location_id,category,severity,title,message,entity_type,entity_id)
      values(p_tenant_id,p_user_id,r.location_id,'task',case when r.due_at<now() then 'warning' else 'info' end,'Task due • '||r.title,'Due '||r.due_at,'task',r.id);
    end if;
  end loop;
end $$;


--
-- Name: v4_reverse_source_journal(uuid, text, uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v4_reverse_source_journal(p_tenant_id uuid, p_source_type text, p_source_id uuid, p_reversal_type text, p_description text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_original public.journal_entries%rowtype;
  v_lines jsonb;
  v_id uuid;
begin
  select * into v_original
  from public.journal_entries
  where tenant_id=p_tenant_id and source_type=p_source_type and source_id=p_source_id and status='posted'
  order by created_at limit 1;
  if not found then return null; end if;

  if exists(select 1 from public.journal_entries where tenant_id=p_tenant_id and source_type=p_reversal_type and source_id=p_source_id and status='posted') then
    return (select id from public.journal_entries where tenant_id=p_tenant_id and source_type=p_reversal_type and source_id=p_source_id and status='posted' limit 1);
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'account_id',l.account_id,
    'party_type',l.party_type,
    'party_id',l.party_id,
    'description','Reversal • '||coalesce(l.description,v_original.description),
    'debit',l.credit,
    'credit',l.debit
  ) order by l.id),'[]'::jsonb)
  into v_lines
  from public.journal_lines l
  where l.journal_entry_id=v_original.id;

  v_id:=private.v4_journal_create(p_tenant_id,v_original.location_id,current_date,p_description,p_reversal_type,p_source_id,v_original.source_reference,v_lines);
  update public.journal_entries set reversal_of=v_original.id where id=v_id;
  return v_id;
end $$;


--
-- Name: v4_sale_payment_after_insert(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v4_sale_payment_after_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_tenant uuid;v_loc uuid;v_ref text;v_customer uuid;v_lines jsonb;v_receipt text;begin
  v_receipt:=current_setting('thq.customer_receipt_id',true);
  if nullif(v_receipt,'') is not null then return new;end if;
  select s.tenant_id,s.sale_number,s.customer_id,o.location_id into v_tenant,v_ref,v_customer,v_loc
  from public.sales s left join public.document_origins o on o.entity_type='sale' and o.entity_id=s.id where s.id=new.sale_id;
  if v_tenant is null or v_loc is null then return new;end if;
  if exists(select 1 from public.journal_entries where tenant_id=v_tenant and source_type='sale_payment' and source_id=new.id) then return new;end if;
  v_lines:=jsonb_build_array(
    jsonb_build_object('account_id',private.v4_payment_account(v_tenant,new.payment_method),'debit',new.amount,'credit',0,'party_type','customer','party_id',v_customer,'description','Customer receipt'),
    jsonb_build_object('account_id',private.v4_account_id(v_tenant,'accounts_receivable'),'debit',0,'credit',new.amount,'party_type','customer','party_id',v_customer,'description','Receivable settlement')
  );
  perform private.v4_journal_create(v_tenant,v_loc,coalesce(new.paid_at::date,current_date),'Customer receipt • '||v_ref,'sale_payment',new.id,v_ref,v_lines);
  if lower(coalesce(new.payment_method,''))='cash' then
    insert into public.cash_drawer_movements(tenant_id,shift_id,movement_type,amount,reference_type,reference_id,reference_number,note,created_by)
    select v_tenant,sh.id,'sale',new.amount,'sale_payment',new.id,v_ref,'Customer cash receipt',auth.uid()
    from public.document_origins o join public.cashier_shifts sh on sh.tenant_id=v_tenant and sh.device_id=o.device_id and sh.status='open'
    where o.entity_type='sale' and o.entity_id=new.sale_id
      and not exists(select 1 from public.cash_drawer_movements m where m.reference_type='sale_payment' and m.reference_id=new.id)
    limit 1;
  end if;
  return new;
end $$;


--
-- Name: v4_sale_void_accounting_trigger(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v4_sale_void_accounting_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if coalesce(old.status,'')<>'void' and coalesce(new.status,'')='void' then
    perform private.v4_reverse_source_journal(new.tenant_id,'sale',new.id,'sale_void','Void sale '||coalesce(new.sale_number,''));
  end if;
  return new;
end $$;


--
-- Name: v4_sales_return_accounting_trigger(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v4_sales_return_accounting_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if private.gst_v520_authoritative_context_for_source(new.tenant_id,'sales_return',new.id) then
    return new;
  end if;
  if coalesce(new.grand_total,0)>0 and (tg_op='INSERT' or coalesce(old.grand_total,0)<>coalesce(new.grand_total,0)) then
    perform private.v4_post_sales_return(new.id);
  end if;
  return new;
end $$;


--
-- Name: v4_sync_document_actor(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v4_sync_document_actor() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if new.entity_type='sale' then
    update public.sales set created_by=coalesce(created_by,new.created_by) where id=new.entity_id and tenant_id=new.tenant_id;
  elsif new.entity_type='purchase' then
    update public.purchases set created_by=coalesce(created_by,new.created_by) where id=new.entity_id and tenant_id=new.tenant_id;
  elsif new.entity_type='expense' then
    update public.expenses set created_by=coalesce(created_by,new.created_by) where id=new.entity_id and tenant_id=new.tenant_id;
  end if;
  return new;
end $$;


--
-- Name: v500_accounting_access(uuid, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v500_accounting_access(p_tenant_id uuid, p_manage boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if p_manage then
    if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'accounting.manage') and not private.erp_has_permission(p_tenant_id,'accounting.journal') then raise exception 'Accounting manage permission required';end if;
  else
    if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'accounting.view') and not private.erp_has_permission(p_tenant_id,'accounting.manage') and not private.erp_has_permission(p_tenant_id,'accounting.journal') then raise exception 'Accounting permission required';end if;
  end if;
end $$;


--
-- Name: v500_assert_posting_period_open(uuid, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v500_assert_posting_period_open(p_tenant_id uuid, p_entry_date date) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$begin if p_entry_date is null then raise exception 'Journal date is required';end if;if exists(select 1 from public.financial_years_v500 y where y.tenant_id=p_tenant_id and y.locked_through is not null and p_entry_date<=y.locked_through) then raise exception 'Accounting period is locked through %',(select max(y.locked_through) from public.financial_years_v500 y where y.tenant_id=p_tenant_id and y.locked_through is not null and p_entry_date<=y.locked_through);end if;end $$;


--
-- Name: v500_build25_refresh_notifications(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v500_build25_refresh_notifications(p_tenant_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare r record;begin if private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'accounting.manage') then for r in select id,name,end_date from public.financial_years_v500 where tenant_id=p_tenant_id and status='open' and end_date<=current_date+7 order by end_date loop if not exists(select 1 from public.notifications n where n.tenant_id=p_tenant_id and n.user_id=p_user_id and n.category='closing' and n.entity_type='financial_year' and n.entity_id=r.id and n.read_at is null and n.created_at>now()-interval '24 hours') then insert into public.notifications(tenant_id,user_id,category,severity,title,message,entity_type,entity_id) values(p_tenant_id,p_user_id,'closing',case when r.end_date<current_date then 'critical' else 'warning' end,'Financial year closing • '||r.name,case when r.end_date<current_date then 'Year ended '||r.end_date::text||' and is still open' else 'Year ends '||r.end_date::text end,'financial_year',r.id);end if;end loop;end if;for r in select c.id,c.name,cp.birthday,cp.anniversary from public.customer_crm_profiles_v500 cp join public.customers c on c.id=cp.customer_id and c.tenant_id=cp.tenant_id where cp.tenant_id=p_tenant_id and c.status='active' and ((cp.birthday is not null and extract(month from cp.birthday)=extract(month from current_date) and extract(day from cp.birthday)=extract(day from current_date)) or (cp.anniversary is not null and extract(month from cp.anniversary)=extract(month from current_date) and extract(day from cp.anniversary)=extract(day from current_date))) loop if not exists(select 1 from public.notifications n where n.tenant_id=p_tenant_id and n.user_id=p_user_id and n.category='crm' and n.entity_type='customer' and n.entity_id=r.id and n.created_at::date=current_date) then insert into public.notifications(tenant_id,user_id,category,severity,title,message,entity_type,entity_id) values(p_tenant_id,p_user_id,'crm','info',case when r.birthday is not null and extract(month from r.birthday)=extract(month from current_date) and extract(day from r.birthday)=extract(day from current_date) then 'Customer birthday • ' else 'Customer anniversary • ' end||r.name,'CRM reminder for today','customer',r.id);end if;end loop;end $$;


--
-- Name: v500_customer_manage_access(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v500_customer_manage_access(p_tenant_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'customers.manage') and not private.erp_has_permission(p_tenant_id,'sales.manage') then raise exception 'Customer management permission required';end if;
end $$;


--
-- Name: v500_document_location(uuid, text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v500_document_location(p_tenant_id uuid, p_entity_type text, p_entity_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$select o.location_id from public.document_origins o where o.tenant_id=p_tenant_id and o.entity_type=p_entity_type and o.entity_id=p_entity_id limit 1$$;


--
-- Name: v500_ensure_main_location(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v500_ensure_main_location(p_tenant_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_main uuid;
  v_name text;
begin
  select l.id into v_main
  from public.business_locations l
  where l.tenant_id=p_tenant_id and l.hierarchy_role='main_store'
  order by l.active desc,l.created_at
  limit 1;
  if v_main is null then
    select l.id into v_main from public.business_locations l where l.tenant_id=p_tenant_id and upper(l.location_code)='MAIN' order by l.created_at limit 1;
  end if;
  if v_main is null then
    select t.name into v_name from public.tenants t where t.id=p_tenant_id;
    if v_name is null then raise exception 'Business not found'; end if;
    insert into public.business_locations(tenant_id,parent_location_id,location_code,name,location_type,hierarchy_role,sort_order,invoice_prefix,active)
    values(p_tenant_id,null,'MAIN',v_name||' - Main','head_office','main_store',0,null,true) returning id into v_main;
  else
    update public.business_locations set parent_location_id=null,location_code='MAIN',location_type='head_office',hierarchy_role='main_store',sort_order=0,active=true,updated_at=now() where id=v_main and tenant_id=p_tenant_id;
  end if;
  update public.business_locations set parent_location_id=v_main,updated_at=now() where tenant_id=p_tenant_id and id<>v_main and hierarchy_role<>'main_store' and parent_location_id is null;
  return v_main;
end $$;


--
-- Name: v500_next_pos_invoice_prefix(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v500_next_pos_invoice_prefix(p_tenant_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $_$
declare v_no integer;v_prefix text;
begin
  perform 1 from public.tenants where id=p_tenant_id for update;
  if not found then raise exception 'Business not found'; end if;
  select coalesce(max((substring(upper(trim(d.invoice_prefix)) from '^POS0*([0-9]+)$'))::integer),0)+1 into v_no
  from public.business_devices d where d.tenant_id=p_tenant_id and d.app_type='pos' and nullif(trim(d.invoice_prefix),'') is not null;
  loop
    v_prefix:='POS'||lpad(v_no::text,2,'0');
    exit when not exists(select 1 from public.business_devices d where d.tenant_id=p_tenant_id and d.app_type='pos' and upper(trim(coalesce(d.invoice_prefix,'')))=v_prefix);
    v_no:=v_no+1;
    if v_no>999999 then raise exception 'POS invoice prefix sequence exhausted'; end if;
  end loop;
  return v_prefix;
end $_$;


--
-- Name: v500_purchase_discount_account(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v500_purchase_discount_account(p_tenant_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v uuid;v_code text:='4040';begin select id into v from public.accounting_accounts where tenant_id=p_tenant_id and system_key='purchase_discount' and active limit 1;if v is not null then return v;end if;if exists(select 1 from public.accounting_accounts where tenant_id=p_tenant_id and code=v_code) then v_code:='4040-PD';end if;insert into public.accounting_accounts(tenant_id,code,name,account_type,system_key,is_system,description,active) values(p_tenant_id,v_code,'Purchase Discounts','income','purchase_discount',true,'Supplier discounts kept separate from the ERP gross-item inventory cost basis',true) returning id into v;return v;end $$;


--
-- Name: v500_refresh_notifications(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v500_refresh_notifications(p_tenant_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare r record;begin
  -- Inventory severity: out-of-stock, low-stock and dead-stock.
  for r in select * from public.inventory_intelligence_v480(p_tenant_id,null,30,'',1000) where status in('out_of_stock','low_stock','dead_stock') order by case status when 'out_of_stock' then 0 when 'low_stock' then 1 else 2 end limit 150 loop
    if not exists(select 1 from public.notifications n where n.tenant_id=p_tenant_id and n.user_id=p_user_id and n.category='inventory' and n.entity_type='product_variant' and n.entity_id=r.variant_id and n.title like case when r.status='out_of_stock' then 'Out of stock%' when r.status='low_stock' then 'Low stock%' else 'Dead stock%' end and n.read_at is null and n.created_at>now()-interval '12 hours') then
      insert into public.notifications(tenant_id,user_id,location_id,category,severity,title,message,entity_type,entity_id)
      values(p_tenant_id,p_user_id,r.location_id,'inventory',case when r.status='out_of_stock' then 'critical' when r.status='low_stock' then 'warning' else 'info' end,case when r.status='out_of_stock' then 'Out of stock • ' when r.status='low_stock' then 'Low stock • ' else 'Dead stock • ' end||r.product_name,'Available '||round(r.available,2)||' • reorder '||round(r.suggested_reorder,2),'product_variant',r.variant_id);
    end if;
  end loop;

  -- POS/client systems that have not checked in for two hours.
  for r in select d.id,d.location_id,d.device_code,d.name,d.app_type,d.last_seen_at from public.business_devices d where d.tenant_id=p_tenant_id and d.status='active' and d.app_type in('pos','client') and d.last_seen_at is not null and d.last_seen_at<now()-interval '2 hours' order by d.last_seen_at limit 100 loop
    if not exists(select 1 from public.notifications n where n.tenant_id=p_tenant_id and n.user_id=p_user_id and n.category='sync' and n.entity_type='device' and n.entity_id=r.id and n.read_at is null and n.created_at>now()-interval '6 hours') then
      insert into public.notifications(tenant_id,user_id,location_id,category,severity,title,message,entity_type,entity_id) values(p_tenant_id,p_user_id,r.location_id,'sync','critical',upper(r.app_type)||' not synchronized • '||coalesce(r.device_code,r.name),'Last seen '||r.last_seen_at,'device',r.id);
    end if;
  end loop;

  -- Recurring expenses due now.
  for r in select id,location_id,title,next_run_date,amount from public.recurring_expenses_v500 where tenant_id=p_tenant_id and active and next_run_date<=current_date order by next_run_date limit 100 loop
    if not exists(select 1 from public.notifications n where n.tenant_id=p_tenant_id and n.user_id=p_user_id and n.category='expense' and n.entity_type='recurring_expense' and n.entity_id=r.id and n.read_at is null and n.created_at>now()-interval '24 hours') then
      insert into public.notifications(tenant_id,user_id,location_id,category,severity,title,message,entity_type,entity_id) values(p_tenant_id,p_user_id,r.location_id,'expense','warning','Recurring expense due • '||r.title,'Amount '||round(r.amount,2)||' • due '||r.next_run_date,'recurring_expense',r.id);
    end if;
  end loop;

  -- Task escalation.
  for r in select id,location_id,title,assigned_to,escalation_user_id,due_at from public.business_tasks where tenant_id=p_tenant_id and status not in('done','cancelled') and escalation_at is not null and escalation_at<=now() and escalated_at is null for update loop
    insert into public.notifications(tenant_id,user_id,location_id,category,severity,title,message,entity_type,entity_id) values(p_tenant_id,coalesce(r.escalation_user_id,r.assigned_to,p_user_id),r.location_id,'task','critical','Task escalated • '||r.title,case when r.due_at is null then 'Task requires immediate attention' else 'Due '||r.due_at end,'task',r.id);
    update public.business_tasks set escalated_at=now(),updated_at=now() where id=r.id;
  end loop;
end $$;


--
-- Name: v500_retained_earnings_account(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v500_retained_earnings_account(p_tenant_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v uuid;v_code text:='3990-RE';begin select id into v from public.accounting_accounts where tenant_id=p_tenant_id and system_key='retained_earnings' and active limit 1;if v is null then if exists(select 1 from public.accounting_accounts where tenant_id=p_tenant_id and code=v_code) then v_code:='3990-RE-'||substr(gen_random_uuid()::text,1,6);end if;insert into public.accounting_accounts(tenant_id,code,name,account_type,system_key,is_system,description) values(p_tenant_id,v_code,'Retained Earnings','equity','retained_earnings',true,'Accumulated retained earnings from financial year closing') returning id into v;end if;return v;end $$;


--
-- Name: v500_stock_adjustment_post(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v500_stock_adjustment_post(p_tenant_id uuid, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare s public.stock_adjustment_requests_v500%rowtype;v jsonb;begin select * into s from public.stock_adjustment_requests_v500 where id=p_request_id and tenant_id=p_tenant_id for update;if not found then raise exception 'Stock adjustment request not found';end if;if s.status='posted' then return coalesce(s.result,'{}'::jsonb);end if;if s.status<>'approved' then raise exception 'Stock adjustment must be approved before posting';end if;v:=public.inventory_adjust_stock_v47(p_tenant_id,s.location_id,s.device_id,s.variant_id,s.quantity_delta,s.note,'stock-adjustment-approved:'||s.id::text);update public.stock_adjustment_requests_v500 set status='posted',result=v,decided_by=coalesce(decided_by,auth.uid()),decided_at=coalesce(decided_at,now()) where id=s.id;return v||jsonb_build_object('adjustment_request_id',s.id,'status','posted');end $$;


--
-- Name: v500_task_audit_trigger(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v500_task_audit_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if tg_op='INSERT' then
    insert into public.business_task_history_v500(tenant_id,task_id,event_type,to_status,note,changed_by,metadata)
    values(new.tenant_id,new.id,'created',new.status,'Task created',coalesce(auth.uid(),new.created_by),jsonb_build_object('priority',new.priority,'assigned_to',new.assigned_to));
  elsif tg_op='UPDATE' then
    if old.status is distinct from new.status or old.assigned_to is distinct from new.assigned_to or old.due_at is distinct from new.due_at or old.priority is distinct from new.priority then
      insert into public.business_task_history_v500(tenant_id,task_id,event_type,from_status,to_status,note,changed_by,metadata)
      values(new.tenant_id,new.id,'updated',old.status,new.status,'Task updated',auth.uid(),jsonb_build_object('old_priority',old.priority,'priority',new.priority,'old_assigned_to',old.assigned_to,'assigned_to',new.assigned_to,'old_due_at',old.due_at,'due_at',new.due_at));
    end if;
  end if;return new;
end $$;


--
-- Name: v500_task_visible(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v500_task_visible(p_tenant_id uuid, p_task_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$select exists(select 1 from public.business_tasks t where t.id=p_task_id and t.tenant_id=p_tenant_id and private.erp_user_has_tenant_access(p_tenant_id) and (t.location_id is null or private.erp_user_location_allowed(p_tenant_id,t.location_id,'view') or private.erp_user_is_owner(p_tenant_id)) and (t.assigned_to is null or t.assigned_to=auth.uid() or private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'tasks.manage')))$$;


--
-- Name: v520_offline_conflict(uuid, uuid, uuid, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v520_offline_conflict(p_tenant_id uuid, p_device_id uuid, p_location_id uuid, p_request_id text, p_request_hash text, p_local text, p_code text, p_message text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  insert into public.pos_offline_sync_v486(
    tenant_id,request_id,device_id,location_id,local_invoice_number,status,
    conflict_code,conflict_message,payload_snapshot,attempts,last_attempt_at,
    created_by,updated_at,sync_contract_version,request_hash
  ) values(
    p_tenant_id,trim(p_request_id),p_device_id,p_location_id,p_local,'conflict',
    p_code,p_message,coalesce(p_payload,'{}'::jsonb),1,now(),auth.uid(),now(),'v5.2',p_request_hash
  )
  on conflict(tenant_id,request_id) do update set
    status='conflict',
    conflict_code=excluded.conflict_code,
    conflict_message=excluded.conflict_message,
    attempts=public.pos_offline_sync_v486.attempts+1,
    last_attempt_at=now(),
    updated_at=now();

  return jsonb_build_object(
    'ok',false,'status','conflict','code',p_code,'message',p_message,
    'request_id',trim(p_request_id),'local_invoice_number',p_local,
    'offline_sync','v5.2','authoritative_gst',false
  );
end
$$;


--
-- Name: v520_offline_sync_guard(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v520_offline_sync_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if tg_op='UPDATE' and old.sync_contract_version='v5.2' then
    if new.sync_contract_version is distinct from old.sync_contract_version
       or new.request_hash is distinct from old.request_hash
       or new.device_id is distinct from old.device_id
       or new.location_id is distinct from old.location_id
       or new.payload_snapshot is distinct from old.payload_snapshot then
      raise exception 'A v5.2 Offline POS request identity/payload is immutable; create a new request ID for an edited invoice';
    end if;
  end if;

  if new.sync_contract_version='v5.2' then
    if nullif(trim(coalesce(new.request_hash,'')),'') is null then
      raise exception 'v5.2 Offline POS request hash is required';
    end if;
    if new.status='synced' then
      if new.sale_id is null or new.gst_snapshot_id is null or new.gst_journal_id is null then
        raise exception 'v5.2 Offline POS cannot be marked synced without Sale/GST snapshot/journal evidence';
      end if;
      if not exists(
        select 1
        from public.gst_document_snapshots_v520 s
        where s.id=new.gst_snapshot_id
          and s.tenant_id=new.tenant_id
          and s.source_type='sale'
          and s.source_id=new.sale_id
      ) then
        raise exception 'v5.2 Offline POS GST snapshot does not match the synced Sale';
      end if;
      if not exists(
        select 1
        from public.journal_entries j
        where j.id=new.gst_journal_id
          and j.tenant_id=new.tenant_id
          and j.source_type='sale'
          and j.source_id=new.sale_id
          and j.status='posted'
      ) then
        raise exception 'v5.2 Offline POS authoritative Sale journal does not match the synced Sale';
      end if;
    end if;
  end if;
  return new;
end
$$;


--
-- Name: transaction_story_events_v600; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.transaction_story_events_v600 (
    event_sequence bigint NOT NULL,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    correlation_id uuid NOT NULL,
    root_entity_type text NOT NULL,
    root_entity_id uuid NOT NULL,
    entity_type text NOT NULL,
    entity_id uuid NOT NULL,
    entity_reference text,
    action text NOT NULL,
    event_time timestamp with time zone DEFAULT now() NOT NULL,
    actor_user_id uuid,
    actor_name text,
    actor_role_keys text[] DEFAULT '{}'::text[] NOT NULL,
    location_id uuid,
    device_id uuid,
    device_name text,
    device_code text,
    source_app text,
    request_id text,
    before_data jsonb,
    after_data jsonb,
    changed_fields text[] DEFAULT '{}'::text[] NOT NULL,
    reason text,
    approval_request_id uuid,
    approved_by uuid,
    approved_at timestamp with time zone,
    approval_note text,
    source_module text,
    source_function text,
    related_entities jsonb DEFAULT '[]'::jsonb NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    previous_event_hash text,
    event_hash text NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT transaction_story_events_v600_action_chk CHECK ((length(TRIM(BOTH FROM action)) > 0)),
    CONSTRAINT transaction_story_events_v600_entity_chk CHECK ((length(TRIM(BOTH FROM entity_type)) > 0)),
    CONSTRAINT transaction_story_events_v600_related_chk CHECK ((jsonb_typeof(related_entities) = 'array'::text))
);


--
-- Name: v600_add_finding(public.transaction_story_events_v600, text, text, text, text, numeric, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v600_add_finding(p_event public.transaction_story_events_v600, p_severity text, p_rule_code text, p_title text, p_description text, p_score numeric, p_evidence jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into public.audit_findings_v600(
    tenant_id,source_event_id,correlation_id,severity,rule_code,title,description,risk_score,
    entity_type,entity_id,entity_reference,location_id,device_id,actor_user_id,detected_at,evidence
  ) values (
    p_event.tenant_id,p_event.id,p_event.correlation_id,p_severity,p_rule_code,p_title,p_description,p_score,
    p_event.entity_type,p_event.entity_id,p_event.entity_reference,p_event.location_id,p_event.device_id,p_event.actor_user_id,
    p_event.event_time,coalesce(p_evidence,'{}'::jsonb) || jsonb_build_object('event_id',p_event.id,'action',p_event.action,'changed_fields',p_event.changed_fields)
  )
  on conflict (tenant_id,source_event_id,rule_code) do nothing;
end;
$$;


--
-- Name: v600_balance_components(uuid, text, date, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v600_balance_components(p_tenant_id uuid, p_metric text, p_as_of date, p_location_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
select coalesce(jsonb_agg(jsonb_build_object(
  'account_id',q.account_id,'code',q.code,'name',q.name,'system_key',q.system_key,'account_type',q.account_type,
  'balance',round(q.balance,4),'contribution',round(q.contribution,4)
) order by q.code),'[]'::jsonb)
from (
  select a.id account_id,a.code,a.name,a.system_key,a.account_type,
    case when a.account_type in ('asset','expense','cogs')
      then coalesce(sum(jl.debit-jl.credit) filter(where j.id is not null),0)
      else coalesce(sum(jl.credit-jl.debit) filter(where j.id is not null),0) end::numeric balance,
    case
      when p_metric='gst_payable' and a.system_key in ('input_gst','input_cgst','input_sgst','input_utgst','input_igst','input_cess','rcm_input_gst','rcm_input_cgst','rcm_input_sgst','rcm_input_utgst','rcm_input_igst','rcm_input_cess')
        then -coalesce(sum(jl.debit-jl.credit) filter(where j.id is not null),0)
      when a.account_type in ('asset','expense','cogs') then coalesce(sum(jl.debit-jl.credit) filter(where j.id is not null),0)
      else coalesce(sum(jl.credit-jl.debit) filter(where j.id is not null),0)
    end::numeric contribution
  from public.accounting_accounts a
  left join public.journal_lines jl on jl.account_id=a.id
  left join public.journal_entries j on j.id=jl.journal_entry_id and j.tenant_id=p_tenant_id and j.status='posted' and j.entry_date<=p_as_of
    and private.erp_document_scope_allowed(p_tenant_id,j.location_id,p_location_id,'view')
  where a.tenant_id=p_tenant_id and a.active and (
    (p_metric='inventory_value' and a.system_key='inventory_asset') or
    (p_metric='receivables' and a.system_key='accounts_receivable') or
    (p_metric='payables' and a.system_key='accounts_payable') or
    (p_metric='cash' and a.system_key='cash') or
    (p_metric='bank' and a.system_key='bank') or
    (p_metric='gst_payable' and a.system_key in ('output_gst','output_cgst','output_sgst','output_utgst','output_igst','output_cess','rcm_gst_payable','rcm_cgst_payable','rcm_sgst_payable','rcm_utgst_payable','rcm_igst_payable','rcm_cess_payable','input_gst','input_cgst','input_sgst','input_utgst','input_igst','input_cess','rcm_input_gst','rcm_input_cgst','rcm_input_sgst','rcm_input_utgst','rcm_input_igst','rcm_input_cess'))
  )
  group by a.id,a.code,a.name,a.system_key,a.account_type
) q;
$$;


--
-- Name: v600_balance_metric_values(uuid, date, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v600_balance_metric_values(p_tenant_id uuid, p_as_of date, p_location_id uuid DEFAULT NULL::uuid) RETURNS TABLE(inventory_value numeric, receivables numeric, payables numeric, cash numeric, bank numeric, upi numeric, card numeric, gst_payable numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
with balances as (
  select a.system_key,a.account_type,
    case when a.account_type in ('asset','expense','cogs')
      then coalesce(sum(jl.debit-jl.credit) filter(where j.id is not null),0)
      else coalesce(sum(jl.credit-jl.debit) filter(where j.id is not null),0)
    end::numeric amount
  from public.accounting_accounts a
  left join public.journal_lines jl on jl.account_id=a.id
  left join public.journal_entries j on j.id=jl.journal_entry_id
    and j.tenant_id=p_tenant_id and j.status='posted' and j.entry_date<=p_as_of
    and private.erp_document_scope_allowed(p_tenant_id,j.location_id,p_location_id,'view')
  where a.tenant_id=p_tenant_id and a.active
  group by a.id,a.system_key,a.account_type
)
select
  coalesce(sum(amount) filter(where system_key='inventory_asset'),0)::numeric,
  coalesce(sum(amount) filter(where system_key='accounts_receivable'),0)::numeric,
  coalesce(sum(amount) filter(where system_key='accounts_payable'),0)::numeric,
  coalesce(sum(amount) filter(where system_key='cash'),0)::numeric,
  coalesce(sum(amount) filter(where system_key='bank'),0)::numeric,
  coalesce(sum(amount) filter(where system_key='upi'),0)::numeric,
  coalesce(sum(amount) filter(where system_key='card'),0)::numeric,
  (
    coalesce(sum(amount) filter(where system_key in ('output_gst','output_cgst','output_sgst','output_utgst','output_igst','output_cess','rcm_gst_payable','rcm_cgst_payable','rcm_sgst_payable','rcm_utgst_payable','rcm_igst_payable','rcm_cess_payable')),0)
    -coalesce(sum(amount) filter(where system_key in ('input_gst','input_cgst','input_sgst','input_utgst','input_igst','input_cess','rcm_input_gst','rcm_input_cgst','rcm_input_sgst','rcm_input_utgst','rcm_input_igst','rcm_input_cess')),0)
  )::numeric
from balances;
$$;


--
-- Name: v600_balance_source_drivers(uuid, text, date, date, uuid, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v600_balance_source_drivers(p_tenant_id uuid, p_metric text, p_from date, p_to date, p_location_id uuid, p_limit integer) RETURNS TABLE(drivers jsonb, driver_sum numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
with values_by_source as (
  select coalesce(j.source_type,'manual') as source_type,
    sum(case
      when p_metric='inventory_value' and a.system_key='inventory_asset' then jl.debit-jl.credit
      when p_metric='receivables' and a.system_key='accounts_receivable' then jl.debit-jl.credit
      when p_metric='payables' and a.system_key='accounts_payable' then jl.credit-jl.debit
      when p_metric='cash' and a.system_key='cash' then jl.debit-jl.credit
      when p_metric='bank' and a.system_key='bank' then jl.debit-jl.credit
      when p_metric='gst_payable' and a.system_key in ('output_gst','output_cgst','output_sgst','output_utgst','output_igst','output_cess','rcm_gst_payable','rcm_cgst_payable','rcm_sgst_payable','rcm_utgst_payable','rcm_igst_payable','rcm_cess_payable') then jl.credit-jl.debit
      when p_metric='gst_payable' and a.system_key in ('input_gst','input_cgst','input_sgst','input_utgst','input_igst','input_cess','rcm_input_gst','rcm_input_cgst','rcm_input_sgst','rcm_input_utgst','rcm_input_igst','rcm_input_cess') then -(jl.debit-jl.credit)
      else 0 end)::numeric impact
  from public.journal_entries j
  join public.journal_lines jl on jl.journal_entry_id=j.id
  join public.accounting_accounts a on a.id=jl.account_id and a.tenant_id=j.tenant_id
  where j.tenant_id=p_tenant_id and j.status='posted' and j.entry_date between p_from and p_to
    and private.erp_document_scope_allowed(p_tenant_id,j.location_id,p_location_id,'view')
    and (
      (p_metric='inventory_value' and a.system_key='inventory_asset') or
      (p_metric='receivables' and a.system_key='accounts_receivable') or
      (p_metric='payables' and a.system_key='accounts_payable') or
      (p_metric='cash' and a.system_key='cash') or
      (p_metric='bank' and a.system_key='bank') or
      (p_metric='gst_payable' and a.system_key in ('output_gst','output_cgst','output_sgst','output_utgst','output_igst','output_cess','rcm_gst_payable','rcm_cgst_payable','rcm_sgst_payable','rcm_utgst_payable','rcm_igst_payable','rcm_cess_payable','input_gst','input_cgst','input_sgst','input_utgst','input_igst','input_cess','rcm_input_gst','rcm_input_cgst','rcm_input_sgst','rcm_input_utgst','rcm_input_igst','rcm_input_cess'))
    )
  group by coalesce(j.source_type,'manual')
), ranked as (
  select source_type,round(impact,4) impact
  from values_by_source where abs(impact)>0.00005
  order by abs(impact) desc,source_type
  limit greatest(1,least(coalesce(p_limit,10),50))
)
select coalesce(jsonb_agg(to_jsonb(r) order by abs(r.impact) desc),'[]'::jsonb),coalesce(sum(r.impact),0)::numeric
from ranked r;
$$;


--
-- Name: v600_block_story_mutation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v600_block_story_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  raise exception 'THQ v6.0 transaction story is append-only; % is not permitted', tg_op
    using errcode='55000';
end;
$$;


--
-- Name: v600_can_view_entity(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v600_can_view_entity(p_tenant_id uuid, p_entity_type text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_type text := lower(coalesce(p_entity_type,''));
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then return false; end if;
  if private.has_permission(p_tenant_id,'audit_center.view') then return true; end if;
  if v_type in ('sale','sale_item','sale_payment','sales_return','sales_return_item') then
    return private.has_permission(p_tenant_id,'sales.view') or private.has_permission(p_tenant_id,'sales.manage');
  elsif v_type in ('purchase','purchase_item','purchase_payment') then
    return private.has_permission(p_tenant_id,'purchases.view') or private.has_permission(p_tenant_id,'purchases.manage');
  elsif v_type in ('purchase_invoice','purchase_invoice_item','supplier_payment') then
    return private.has_permission(p_tenant_id,'purchasing.view') or private.has_permission(p_tenant_id,'purchasing.manage')
      or private.has_permission(p_tenant_id,'purchases.view') or private.has_permission(p_tenant_id,'purchases.manage');
  elsif v_type in ('journal_entry','journal_line') then
    return private.has_permission(p_tenant_id,'accounting.view') or private.has_permission(p_tenant_id,'accounting.manage');
  elsif v_type in ('stock_movement','stock_adjustment') then
    return private.has_permission(p_tenant_id,'inventory.view') or private.has_permission(p_tenant_id,'inventory.manage');
  elsif v_type='approval_request' then
    return private.has_permission(p_tenant_id,'approvals.view') or private.has_permission(p_tenant_id,'approvals.manage');
  end if;
  return false;
end;
$$;


--
-- Name: v600_capture_business_row(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v600_capture_business_row() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_new jsonb := case when tg_op='DELETE' then null else to_jsonb(new) end;
  v_old jsonb := case when tg_op='INSERT' then null else to_jsonb(old) end;
  v_row jsonb := coalesce(v_new,v_old,'{}'::jsonb);
  v_tenant uuid;
  v_entity_type text;
  v_entity_id uuid;
  v_reference text;
  v_root_type text;
  v_root_id uuid;
  v_action text;
  v_actor uuid;
  v_location uuid;
  v_device uuid;
  v_reason text;
  v_approval uuid;
  v_event_time timestamptz;
  v_source_module text;
  v_related jsonb := '[]'::jsonb;
  v_parent jsonb;
  v_changed text[];
begin
  v_changed := private.v600_changed_fields(v_old,v_new);
  if tg_op='UPDATE' and coalesce(array_length(v_changed,1),0)=0 then
    return new;
  end if;

  begin v_tenant := nullif(v_row->>'tenant_id','')::uuid; exception when others then v_tenant := null; end;
  begin v_entity_id := nullif(v_row->>'id','')::uuid; exception when others then v_entity_id := null; end;
  begin v_location := nullif(v_row->>'location_id','')::uuid; exception when others then v_location := null; end;
  begin v_device := nullif(v_row->>'device_id','')::uuid; exception when others then v_device := null; end;
  begin v_approval := nullif(v_row->>'approval_request_id','')::uuid; exception when others then v_approval := null; end;

  v_action := case tg_op when 'INSERT' then 'created' when 'UPDATE' then 'modified' else 'deleted' end;
  v_actor := coalesce(
    nullif(v_row->>'updated_by','')::uuid,
    nullif(v_row->>'decided_by','')::uuid,
    nullif(v_row->>'created_by','')::uuid,
    nullif(v_row->>'requested_by','')::uuid,
    auth.uid()
  );
  v_reason := nullif(trim(coalesce(v_row->>'reason',v_row->>'void_reason',v_row->>'decision_note',v_row->>'note',v_row->>'notes','')),'');
  v_event_time := coalesce(
    nullif(v_row->>'updated_at','')::timestamptz,
    nullif(v_row->>'decided_at','')::timestamptz,
    nullif(v_row->>'paid_at','')::timestamptz,
    nullif(v_row->>'occurred_at','')::timestamptz,
    nullif(v_row->>'posted_at','')::timestamptz,
    nullif(v_row->>'requested_at','')::timestamptz,
    nullif(v_row->>'created_at','')::timestamptz,
    now()
  );

  if tg_table_name='sales' then
    v_entity_type := 'sale'; v_root_type := 'sale'; v_root_id := v_entity_id;
    v_reference := v_row->>'sale_number'; v_source_module := 'sales';
    if tg_op='INSERT' then v_action := 'sale_created';
    elsif tg_op='DELETE' then v_action := 'sale_deleted';
    elsif (v_old->>'status') is distinct from (v_new->>'status') then v_action := 'sale_status_changed';
    else v_action := 'sale_modified'; end if;

  elsif tg_table_name='sale_items' then
    v_entity_type := 'sale_item';
    v_root_type := 'sale'; v_root_id := nullif(v_row->>'sale_id','')::uuid;
    v_reference := coalesce(v_row->>'sku',v_row->>'product_name'); v_source_module := 'sales';
    v_related := jsonb_build_array(jsonb_build_object('type','sale','id',v_root_id));
    if tg_op='INSERT' then v_action := 'sale_item_added';
    elsif tg_op='DELETE' then v_action := 'sale_item_removed'; else v_action := 'sale_item_modified'; end if;

  elsif tg_table_name='sale_payments' then
    v_entity_type := 'sale_payment';
    v_root_type := 'sale'; v_root_id := nullif(v_row->>'sale_id','')::uuid;
    select s.sale_number into v_reference from public.sales s where s.tenant_id=v_tenant and s.id=v_root_id;
    v_source_module := 'payments';
    v_related := jsonb_build_array(jsonb_build_object('type','sale','id',v_root_id));
    if tg_op='INSERT' then v_action := 'payment_recorded';
    elsif tg_op='DELETE' then v_action := 'payment_deleted'; else v_action := 'payment_modified'; end if;

  elsif tg_table_name='sales_returns' then
    v_entity_type := 'sales_return';
    v_root_type := 'sale'; v_root_id := nullif(v_row->>'sale_id','')::uuid;
    v_reference := v_row->>'return_number'; v_source_module := 'returns';
    v_related := jsonb_build_array(jsonb_build_object('type','sale','id',v_root_id),jsonb_build_object('type','sales_return','id',v_entity_id));
    if tg_op='INSERT' then v_action := 'sales_return_created';
    elsif tg_op='DELETE' then v_action := 'sales_return_deleted'; else v_action := 'sales_return_modified'; end if;

  elsif tg_table_name='sales_return_items' then
    select to_jsonb(sr) into v_parent
    from public.sales_returns sr where sr.id=nullif(v_row->>'sales_return_id','')::uuid;
    v_tenant := nullif(v_parent->>'tenant_id','')::uuid;
    v_entity_type := 'sales_return_item';
    v_root_type := 'sale'; v_root_id := nullif(v_parent->>'sale_id','')::uuid;
    v_reference := v_parent->>'return_number'; v_source_module := 'returns';
    v_related := jsonb_build_array(jsonb_build_object('type','sale','id',v_root_id),jsonb_build_object('type','sales_return','id',nullif(v_row->>'sales_return_id','')::uuid));
    if tg_op='INSERT' then v_action := 'sales_return_item_added';
    elsif tg_op='DELETE' then v_action := 'sales_return_item_removed'; else v_action := 'sales_return_item_modified'; end if;

  elsif tg_table_name='purchases' then
    v_entity_type := 'purchase'; v_root_type := 'purchase'; v_root_id := v_entity_id;
    v_reference := v_row->>'purchase_number'; v_source_module := 'purchases';
    if tg_op='INSERT' then v_action := 'purchase_created';
    elsif tg_op='DELETE' then v_action := 'purchase_deleted';
    elsif (v_old->>'status') is distinct from (v_new->>'status') then v_action := 'purchase_status_changed';
    else v_action := 'purchase_modified'; end if;

  elsif tg_table_name='purchase_items' then
    v_entity_type := 'purchase_item';
    v_root_type := 'purchase'; v_root_id := nullif(v_row->>'purchase_id','')::uuid;
    v_reference := coalesce(v_row->>'sku',v_row->>'product_name'); v_source_module := 'purchases';
    v_related := jsonb_build_array(jsonb_build_object('type','purchase','id',v_root_id));
    if tg_op='INSERT' then v_action := 'purchase_item_added';
    elsif tg_op='DELETE' then v_action := 'purchase_item_removed'; else v_action := 'purchase_item_modified'; end if;

  elsif tg_table_name='purchase_invoices_v484' then
    v_entity_type := 'purchase_invoice'; v_root_type := 'purchase_invoice'; v_root_id := v_entity_id;
    v_reference := coalesce(v_row->>'supplier_invoice_number',v_row->>'invoice_number'); v_source_module := 'purchase_details';
    if tg_op='INSERT' then v_action := 'purchase_invoice_created';
    elsif tg_op='DELETE' then v_action := 'purchase_invoice_deleted';
    elsif (v_old->>'status') is distinct from (v_new->>'status') then v_action := 'purchase_invoice_status_changed';
    else v_action := 'purchase_invoice_modified'; end if;

  elsif tg_table_name='purchase_invoice_items_v484' then
    select to_jsonb(pi) into v_parent from public.purchase_invoices_v484 pi where pi.id=nullif(v_row->>'purchase_invoice_id','')::uuid;
    v_tenant := nullif(v_parent->>'tenant_id','')::uuid;
    v_location := nullif(v_parent->>'location_id','')::uuid;
    v_entity_type := 'purchase_invoice_item'; v_root_type := 'purchase_invoice'; v_root_id := nullif(v_row->>'purchase_invoice_id','')::uuid;
    v_reference := coalesce(v_parent->>'supplier_invoice_number',v_parent->>'invoice_number'); v_source_module := 'purchase_details';
    v_related := jsonb_build_array(jsonb_build_object('type','purchase_invoice','id',v_root_id));
    if tg_op='INSERT' then v_action := 'purchase_invoice_item_added';
    elsif tg_op='DELETE' then v_action := 'purchase_invoice_item_removed'; else v_action := 'purchase_invoice_item_modified'; end if;

  elsif tg_table_name='purchase_payments' then
    v_entity_type := 'purchase_payment';
    v_root_type := 'purchase'; v_root_id := nullif(v_row->>'purchase_id','')::uuid;
    select p.purchase_number into v_reference from public.purchases p where p.tenant_id=v_tenant and p.id=v_root_id;
    v_source_module := 'payments';
    v_related := jsonb_build_array(jsonb_build_object('type','purchase','id',v_root_id));
    if tg_op='INSERT' then v_action := 'supplier_payment_recorded';
    elsif tg_op='DELETE' then v_action := 'supplier_payment_deleted'; else v_action := 'supplier_payment_modified'; end if;

  elsif tg_table_name='supplier_payments_v484' then
    v_entity_type := 'supplier_payment'; v_root_type := 'supplier_payment'; v_root_id := v_entity_id;
    v_reference := v_row->>'payment_number'; v_source_module := 'payments';
    if tg_op='INSERT' then v_action := 'supplier_payment_recorded';
    elsif tg_op='DELETE' then v_action := 'supplier_payment_deleted';
    elsif (v_old->>'status') is distinct from (v_new->>'status') then v_action := 'supplier_payment_status_changed';
    else v_action := 'supplier_payment_modified'; end if;

  elsif tg_table_name='location_stock_movements' then
    v_entity_type := 'stock_movement'; v_source_module := 'inventory';
    v_reference := v_row->>'reference_number';
    if nullif(v_row->>'reference_id','') is not null then
      v_root_id := nullif(v_row->>'reference_id','')::uuid;
      v_root_type := coalesce(nullif(v_row->>'reference_type',''),'stock_movement');
    else
      v_root_id := v_entity_id; v_root_type := 'stock_movement';
    end if;
    v_related := case when v_root_id<>v_entity_id then jsonb_build_array(jsonb_build_object('type',v_root_type,'id',v_root_id)) else '[]'::jsonb end;
    if tg_op='INSERT' then v_action := 'stock_movement_recorded';
    elsif tg_op='DELETE' then v_action := 'stock_movement_deleted'; else v_action := 'stock_movement_modified'; end if;

  elsif tg_table_name='stock_adjustment_requests_v500' then
    v_entity_type := 'stock_adjustment'; v_root_type := 'stock_adjustment'; v_root_id := v_entity_id;
    v_reference := v_row->>'request_key'; v_source_module := 'inventory';
    if tg_op='INSERT' then v_action := 'stock_adjustment_requested';
    elsif tg_op='DELETE' then v_action := 'stock_adjustment_deleted';
    elsif (v_old->>'status') is distinct from (v_new->>'status') then v_action := 'stock_adjustment_status_changed';
    else v_action := 'stock_adjustment_modified'; end if;

  elsif tg_table_name='journal_entries' then
    v_entity_type := 'journal_entry'; v_reference := v_row->>'entry_number'; v_source_module := 'accounting';
    if nullif(v_row->>'source_id','') is not null then
      v_root_id := nullif(v_row->>'source_id','')::uuid; v_root_type := coalesce(nullif(v_row->>'source_type',''),'journal_entry');
      v_related := jsonb_build_array(jsonb_build_object('type',v_root_type,'id',v_root_id));
    else
      v_root_id := v_entity_id; v_root_type := 'journal_entry';
    end if;
    if tg_op='INSERT' then v_action := 'journal_created';
    elsif tg_op='DELETE' then v_action := 'journal_deleted';
    elsif (v_old->>'status') is distinct from (v_new->>'status') then v_action := 'journal_status_changed';
    else v_action := 'journal_modified'; end if;

  elsif tg_table_name='journal_lines' then
    select to_jsonb(j) into v_parent from public.journal_entries j where j.id=nullif(v_row->>'journal_entry_id','')::uuid;
    v_tenant := nullif(v_parent->>'tenant_id','')::uuid;
    v_location := nullif(v_parent->>'location_id','')::uuid;
    v_entity_type := 'journal_line';
    if nullif(v_parent->>'source_id','') is not null then
      v_root_id := nullif(v_parent->>'source_id','')::uuid; v_root_type := coalesce(nullif(v_parent->>'source_type',''),'journal_entry');
    else
      v_root_id := nullif(v_row->>'journal_entry_id','')::uuid; v_root_type := 'journal_entry';
    end if;
    v_reference := v_parent->>'entry_number'; v_source_module := 'accounting';
    v_related := jsonb_build_array(jsonb_build_object('type','journal_entry','id',nullif(v_row->>'journal_entry_id','')::uuid));
    if tg_op='INSERT' then v_action := 'journal_line_added';
    elsif tg_op='DELETE' then v_action := 'journal_line_removed'; else v_action := 'journal_line_modified'; end if;

  elsif tg_table_name='approval_requests' then
    v_entity_type := 'approval_request'; v_source_module := 'approvals';
    v_approval := v_entity_id;
    if nullif(v_row->>'entity_id','') is not null then
      v_root_id := nullif(v_row->>'entity_id','')::uuid; v_root_type := coalesce(nullif(v_row->>'entity_type',''),'approval_request');
      v_related := jsonb_build_array(jsonb_build_object('type',v_root_type,'id',v_root_id));
    else
      v_root_id := v_entity_id; v_root_type := 'approval_request';
    end if;
    v_reference := coalesce(v_row->>'action_key',v_row->>'module_key');
    if tg_op='INSERT' then v_action := 'approval_requested';
    elsif tg_op='DELETE' then v_action := 'approval_request_deleted';
    elsif (v_old->>'status') is distinct from (v_new->>'status') then v_action := 'approval_decided';
    else v_action := 'approval_modified'; end if;

  elsif tg_table_name='document_origins' then
    v_entity_type := 'document_origin';
    v_entity_id := nullif(v_row->>'entity_id','')::uuid;
    v_root_id := v_entity_id; v_root_type := coalesce(nullif(v_row->>'entity_type',''),'document');
    v_reference := v_row->>'entity_type'; v_source_module := 'platform';
    v_actor := coalesce(nullif(v_row->>'created_by','')::uuid,auth.uid());
    if tg_op='INSERT' then v_action := 'origin_linked';
    elsif tg_op='DELETE' then v_action := 'origin_unlinked'; else v_action := 'origin_modified'; end if;
  else
    return coalesce(new,old);
  end if;

  if v_tenant is null or v_entity_id is null or v_root_id is null then
    return coalesce(new,old);
  end if;

  if v_location is null or v_device is null then
    select coalesce(v_location,o.location_id),coalesce(v_device,o.device_id)
      into v_location,v_device
    from public.document_origins o
    where o.tenant_id=v_tenant and o.entity_type=v_root_type and o.entity_id=v_root_id
    limit 1;
  end if;

  perform private.v600_story_write(
    p_tenant_id=>v_tenant,
    p_entity_type=>v_entity_type,
    p_entity_id=>v_entity_id,
    p_entity_reference=>v_reference,
    p_action=>v_action,
    p_event_time=>v_event_time,
    p_actor_user_id=>v_actor,
    p_location_id=>v_location,
    p_device_id=>v_device,
    p_before=>v_old,
    p_after=>v_new,
    p_reason=>v_reason,
    p_approval_request_id=>v_approval,
    p_source_module=>v_source_module,
    p_source_function=>'trigger:'||tg_table_name,
    p_root_entity_type=>v_root_type,
    p_root_entity_id=>v_root_id,
    p_request_id=>nullif(v_row->>'request_id',''),
    p_related_entities=>v_related,
    p_metadata=>jsonb_build_object('table',tg_table_name,'operation',tg_op,'capture_version','6.0.0-build1')
  );

  return coalesce(new,old);
end;
$$;


--
-- Name: v600_capture_gst_evidence(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v600_capture_gst_evidence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_source_type text;
  v_source_id uuid;
  v_source_number text;
  v_root_type text;
  v_root_id uuid;
  v_location uuid;
  v_actor uuid;
  v_event_time timestamptz;
  v_after jsonb;
  v_action text;
begin
  if tg_op<>'INSERT' then return new; end if;
  v_source_type:=new.source_type;
  v_source_id:=new.source_id;
  v_source_number:=new.source_number;
  v_root_type:=v_source_type;
  v_root_id:=v_source_id;

  if v_source_type='sales_return' then
    select sr.sale_id into v_root_id from public.sales_returns sr where sr.tenant_id=new.tenant_id and sr.id=v_source_id;
    if v_root_id is not null then v_root_type:='sale'; else v_root_id:=v_source_id; end if;
  end if;

  if tg_table_name='gst_document_snapshots_v520' then
    v_location:=new.location_id;
    v_actor:=new.created_by;
    v_event_time:=new.created_at;
    v_action:='gst_authoritative_snapshot_created';
    v_after:=jsonb_build_object(
      'snapshot_id',new.id,'source_type',new.source_type,'source_id',new.source_id,'source_number',new.source_number,
      'document_number',new.document_number,'document_date',new.document_date,'direction',new.direction,
      'document_kind',new.document_kind,'document_class',new.document_class,'tax_mode',new.tax_mode,
      'taxable_total',new.taxable_total,'cgst_total',new.cgst_total,'sgst_total',new.sgst_total,'utgst_total',new.utgst_total,
      'igst_total',new.igst_total,'cess_total',new.cess_total,'tax_collected_total',new.tax_collected_total,
      'rcm_tax_payable_total',new.rcm_tax_payable_total,'government_tax_total',new.government_tax_total,
      'grand_total',new.grand_total,'engine_version',new.engine_version,'snapshot_hash',new.snapshot_hash,
      'document_identity_hash',new.document_identity_hash,'evidence_class','authoritative_v520'
    );
  else
    v_location:=new.location_id;
    v_actor:=auth.uid();
    v_event_time:=new.marked_at;
    v_action:='gst_legacy_evidence_marked';
    v_after:=jsonb_build_object(
      'marker_id',new.id,'source_type',new.source_type,'source_id',new.source_id,'source_number',new.source_number,
      'document_date',new.document_date,'legacy_taxable_total',new.legacy_taxable_total,'legacy_tax_total',new.legacy_tax_total,
      'legacy_grand_total',new.legacy_grand_total,'verification_status',new.verification_status,'note',new.note,
      'source_hash',new.source_hash,'evidence_class','legacy_unverified'
    );
  end if;

  perform private.v600_story_write(
    p_tenant_id=>new.tenant_id,
    p_entity_type=>case when tg_table_name='gst_document_snapshots_v520' then 'gst_snapshot' else 'gst_legacy_marker' end,
    p_entity_id=>new.id,
    p_entity_reference=>v_source_number,
    p_action=>v_action,
    p_event_time=>v_event_time,
    p_actor_user_id=>v_actor,
    p_location_id=>v_location,
    p_before=>null,
    p_after=>v_after,
    p_source_module=>'gst_compliance',
    p_source_function=>'trigger:'||tg_table_name,
    p_root_entity_type=>v_root_type,
    p_root_entity_id=>v_root_id,
    p_related_entities=>jsonb_build_array(jsonb_build_object('type',v_source_type,'id',v_source_id)),
    p_metadata=>jsonb_build_object('capture_version','6.0.0-build1','gst_rule','v5.2 authoritative transactions never fall back to legacy after failure')
  );
  return new;
end;
$$;


--
-- Name: v600_changed_fields(jsonb, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v600_changed_fields(p_before jsonb, p_after jsonb) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(array_agg(k order by k),'{}'::text[])
  from (
    select key as k
    from jsonb_object_keys(coalesce(p_before,'{}'::jsonb)) key
    union
    select key as k
    from jsonb_object_keys(coalesce(p_after,'{}'::jsonb)) key
  ) s
  where coalesce(p_before,'{}'::jsonb)->k is distinct from coalesce(p_after,'{}'::jsonb)->k;
$$;


--
-- Name: v600_evaluate_story_event(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v600_evaluate_story_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  c public.audit_risk_config_v600%rowtype;
  v_discount_pct numeric := 0;
  v_subtotal numeric;
  v_discount numeric;
  v_gp numeric;
  v_value numeric;
  v_days integer;
  v_entry_date date;
  v_sale_date date;
  v_paid boolean := false;
  v_historical boolean := coalesce((new.metadata->>'historical_reconstruction')::boolean,false);
  v_financial_fields text[] := array['customer_id','sale_date','due_date','quantity','unit_price','unit_cost','discount_amount','discount_total','tax_rate','taxable_total','tax_total','additional_charges','grand_total','cost_total','gross_profit','round_off','status'];
begin
  select * into c from public.audit_risk_config_v600 where tenant_id=new.tenant_id;
  if not found then
    insert into public.audit_risk_config_v600(tenant_id) values(new.tenant_id) on conflict do nothing;
    select * into c from public.audit_risk_config_v600 where tenant_id=new.tenant_id;
  end if;
  if not coalesce(c.active,true) then return new; end if;

  if new.action in ('sale_deleted','sales_return_deleted','purchase_deleted','purchase_invoice_deleted','payment_deleted','supplier_payment_deleted','journal_deleted','stock_movement_deleted','approval_request_deleted') then
    perform private.v600_add_finding(new,'high_risk','DELETION_OR_REMOVAL','Deleted or removed business record','A business-significant record was deleted or removed. Review the full transaction story and linked accounting/stock effects.',95,jsonb_build_object('operation',new.action));
  end if;

  if new.entity_type='sale' and new.after_data is not null then
    begin v_subtotal := nullif(new.after_data->>'subtotal','')::numeric; exception when others then v_subtotal := null; end;
    begin v_discount := nullif(new.after_data->>'discount_total','')::numeric; exception when others then v_discount := null; end;
    if coalesce(v_subtotal,0)<>0 then v_discount_pct := round(abs(coalesce(v_discount,0))*100/abs(v_subtotal),4); end if;
    if v_discount_pct >= c.discount_high_pct and v_discount_pct>0 then
      perform private.v600_add_finding(new,'high_risk','UNUSUAL_DISCOUNT_HIGH','Unusually high discount','Discount exceeds the tenant high-risk threshold.',88,jsonb_build_object('discount_pct',v_discount_pct,'threshold_pct',c.discount_high_pct,'subtotal',v_subtotal,'discount',v_discount));
    elsif v_discount_pct >= c.discount_review_pct and v_discount_pct>0 then
      perform private.v600_add_finding(new,'needs_review','UNUSUAL_DISCOUNT_REVIEW','Discount needs review','Discount exceeds the tenant review threshold.',62,jsonb_build_object('discount_pct',v_discount_pct,'threshold_pct',c.discount_review_pct,'subtotal',v_subtotal,'discount',v_discount));
    end if;
    begin v_gp := nullif(new.after_data->>'gross_profit','')::numeric; exception when others then v_gp := null; end;
    if c.negative_margin_high and coalesce(v_gp,0)<0 then
      perform private.v600_add_finding(new,'high_risk','NEGATIVE_MARGIN_SALE','Negative-margin sale','Recognized gross profit for the sale is negative.',92,jsonb_build_object('gross_profit',v_gp,'grand_total',new.after_data->>'grand_total','cost_total',new.after_data->>'cost_total'));
    end if;
    if not v_historical then
      begin v_sale_date := nullif(new.after_data->>'sale_date','')::date; exception when others then v_sale_date := null; end;
      if v_sale_date is not null then
        v_days := new.event_time::date-v_sale_date;
        if v_days >= c.backdate_high_days and v_days>0 then
          perform private.v600_add_finding(new,'high_risk','BACKDATED_SALE_HIGH','Significantly backdated sale','Sale date is substantially earlier than the recorded transaction time.',86,jsonb_build_object('backdated_days',v_days,'threshold_days',c.backdate_high_days,'sale_date',v_sale_date));
        elsif v_days >= c.backdate_review_days and v_days>0 then
          perform private.v600_add_finding(new,'needs_review','BACKDATED_SALE_REVIEW','Backdated sale','Sale date is earlier than the recorded transaction time beyond the review threshold.',58,jsonb_build_object('backdated_days',v_days,'threshold_days',c.backdate_review_days,'sale_date',v_sale_date));
        end if;
      end if;
    end if;
  end if;

  if new.entity_type='sale_item' and new.after_data is not null then
    begin v_gp := nullif(new.after_data->>'gross_profit','')::numeric; exception when others then v_gp := null; end;
    if c.negative_margin_high and coalesce(v_gp,0)<0 then
      perform private.v600_add_finding(new,'high_risk','NEGATIVE_MARGIN_ITEM','Negative-margin product line','A sale line has negative recognized gross profit.',90,jsonb_build_object('gross_profit',v_gp,'sku',new.after_data->>'sku','product_name',new.after_data->>'product_name'));
    end if;
  end if;

  if new.action in ('sale_modified','sale_item_modified') and c.payment_edit_high and new.root_entity_type='sale' then
    select exists(select 1 from public.sale_payments sp where sp.tenant_id=new.tenant_id and sp.sale_id=new.root_entity_id) into v_paid;
    if v_paid and new.changed_fields && v_financial_fields then
      perform private.v600_add_finding(new,'high_risk','EDIT_AFTER_PAYMENT','Invoice changed after payment','Financial or commercial fields changed after at least one payment had been recorded.',91,jsonb_build_object('changed_fields',new.changed_fields));
    end if;
  end if;

  if new.action in ('payment_modified','supplier_payment_modified') and c.payment_edit_high then
    perform private.v600_add_finding(new,'high_risk','PAYMENT_EDITED','Posted payment changed','A recorded payment was modified. Review method, amount, reference, actor and linked journal.',94,jsonb_build_object('before',new.before_data,'after',new.after_data));
  end if;

  if new.entity_type in ('purchase','purchase_invoice') and new.action like '%modified' and c.posted_purchase_edit_review then
    if coalesce(new.before_data->>'posted_at',new.after_data->>'posted_at','')<>'' or coalesce(new.before_data->>'status',new.after_data->>'status','') in ('posted','approved','received') then
      perform private.v600_add_finding(new,'needs_review','POSTED_PURCHASE_EDIT','Posted purchase changed','A posted/approved purchase record was modified and should be reviewed.',72,jsonb_build_object('changed_fields',new.changed_fields,'status',coalesce(new.after_data->>'status',new.before_data->>'status')));
    end if;
  end if;

  if new.entity_type='stock_adjustment' then
    perform private.v600_add_finding(new,'needs_review','STOCK_ADJUSTMENT','Stock adjustment','A manual stock adjustment request was created or changed.',68,jsonb_build_object('quantity_delta',coalesce(new.after_data->>'quantity_delta',new.before_data->>'quantity_delta'),'status',coalesce(new.after_data->>'status',new.before_data->>'status')));
  end if;

  if new.entity_type='stock_movement' and lower(coalesce(new.after_data->>'movement_type',new.before_data->>'movement_type','')) like '%adjust%' then
    begin v_value := abs(coalesce(nullif(coalesce(new.after_data->>'quantity_delta',new.before_data->>'quantity_delta'),'')::numeric,0) * coalesce(nullif(coalesce(new.after_data->>'unit_cost',new.before_data->>'unit_cost'),'')::numeric,0)); exception when others then v_value := 0; end;
    if v_value>=c.stock_adjustment_high_value then
      perform private.v600_add_finding(new,'high_risk','STOCK_ADJUSTMENT_HIGH_VALUE','High-value stock adjustment','The estimated value of a stock adjustment exceeds the high-risk threshold.',89,jsonb_build_object('estimated_value',v_value,'threshold_value',c.stock_adjustment_high_value));
    elsif v_value>=c.stock_adjustment_review_value then
      perform private.v600_add_finding(new,'needs_review','STOCK_ADJUSTMENT_VALUE_REVIEW','Stock adjustment value needs review','The estimated value of a stock adjustment exceeds the review threshold.',66,jsonb_build_object('estimated_value',v_value,'threshold_value',c.stock_adjustment_review_value));
    end if;
  end if;

  if new.entity_type='journal_entry' and new.after_data is not null then
    if c.manual_journal_review and nullif(new.after_data->>'source_id','') is null then
      perform private.v600_add_finding(new,'needs_review','MANUAL_JOURNAL','Manual journal','A journal entry has no source transaction and should be reviewed as a manual journal.',64,jsonb_build_object('entry_number',new.after_data->>'entry_number','description',new.after_data->>'description'));
    end if;
    if not v_historical then
      begin v_entry_date := nullif(new.after_data->>'entry_date','')::date; exception when others then v_entry_date := null; end;
      if v_entry_date is not null then
        v_days := new.event_time::date-v_entry_date;
        if v_days>=c.backdate_high_days and v_days>0 then
          perform private.v600_add_finding(new,'high_risk','BACKDATED_JOURNAL_HIGH','Significantly backdated journal','Journal entry date is substantially earlier than the recorded event time.',87,jsonb_build_object('backdated_days',v_days,'entry_date',v_entry_date));
        elsif v_days>=c.backdate_review_days and v_days>0 then
          perform private.v600_add_finding(new,'needs_review','BACKDATED_JOURNAL_REVIEW','Backdated journal','Journal entry date is earlier than the recorded event time beyond the review threshold.',60,jsonb_build_object('backdated_days',v_days,'entry_date',v_entry_date));
        end if;
      end if;
    end if;
  end if;

  return new;
exception when others then
  begin
    perform private.platform_audit_write('audit_risk_evaluation_error','transaction_story_event',new.id::text,new.tenant_id,jsonb_build_object('sqlstate',sqlstate,'message',sqlerrm));
  exception when others then null;
  end;
  return new;
end;
$$;


--
-- Name: v600_gp_product_drivers(uuid, date, date, date, date, uuid, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v600_gp_product_drivers(p_tenant_id uuid, p_from date, p_to date, p_prev_from date, p_prev_to date, p_location_id uuid, p_limit integer) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
with cur as (select * from private.v600_product_profit_rows(p_tenant_id,p_from,p_to,p_location_id,null)),
prev as (select * from private.v600_product_profit_rows(p_tenant_id,p_prev_from,p_prev_to,p_location_id,null)),
keys as (select variant_id from cur union select variant_id from prev), ranked as (
  select k.variant_id,coalesce(c.product_name,p.product_name) product_name,coalesce(c.variant_name,p.variant_name) variant_name,coalesce(c.sku,p.sku) sku,
    round(coalesce(c.gross_profit,0),4) current_profit,round(coalesce(p.gross_profit,0),4) previous_profit,
    round(coalesce(c.gross_profit,0)-coalesce(p.gross_profit,0),4) profit_change
  from keys k left join cur c using(variant_id) left join prev p using(variant_id)
  order by abs(coalesce(c.gross_profit,0)-coalesce(p.gross_profit,0)) desc,coalesce(c.sku,p.sku)
  limit greatest(1,least(coalesce(p_limit,10),50))
)
select coalesce(jsonb_agg(to_jsonb(r) order by abs(r.profit_change) desc),'[]'::jsonb) from ranked r;
$$;


--
-- Name: v600_guard_finding_evidence(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v600_guard_finding_evidence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if old.tenant_id is distinct from new.tenant_id
    or old.source_event_id is distinct from new.source_event_id
    or old.correlation_id is distinct from new.correlation_id
    or old.severity is distinct from new.severity
    or old.rule_code is distinct from new.rule_code
    or old.title is distinct from new.title
    or old.description is distinct from new.description
    or old.risk_score is distinct from new.risk_score
    or old.entity_type is distinct from new.entity_type
    or old.entity_id is distinct from new.entity_id
    or old.entity_reference is distinct from new.entity_reference
    or old.location_id is distinct from new.location_id
    or old.device_id is distinct from new.device_id
    or old.actor_user_id is distinct from new.actor_user_id
    or old.detected_at is distinct from new.detected_at
    or old.evidence is distinct from new.evidence then
      raise exception 'Audit finding evidence is immutable; only review lifecycle fields may change' using errcode='55000';
  end if;
  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: v600_period_metric_values(uuid, date, date, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v600_period_metric_values(p_tenant_id uuid, p_from date, p_to date, p_location_id uuid DEFAULT NULL::uuid) RETURNS TABLE(sales_revenue numeric, total_income numeric, cogs numeric, expenses numeric, gross_profit numeric, net_profit numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    coalesce(sum(case when a.system_key='sales_revenue' then jl.credit-jl.debit else 0 end),0)::numeric as sales_revenue,
    coalesce(sum(case when a.account_type='income' then jl.credit-jl.debit else 0 end),0)::numeric as total_income,
    coalesce(sum(case when a.account_type='cogs' then jl.debit-jl.credit else 0 end),0)::numeric as cogs,
    coalesce(sum(case when a.account_type='expense' then jl.debit-jl.credit else 0 end),0)::numeric as expenses,
    (coalesce(sum(case when a.system_key='sales_revenue' then jl.credit-jl.debit else 0 end),0)
      -coalesce(sum(case when a.account_type='cogs' then jl.debit-jl.credit else 0 end),0))::numeric as gross_profit,
    (coalesce(sum(case when a.account_type='income' then jl.credit-jl.debit else 0 end),0)
      -coalesce(sum(case when a.account_type='cogs' then jl.debit-jl.credit else 0 end),0)
      -coalesce(sum(case when a.account_type='expense' then jl.debit-jl.credit else 0 end),0))::numeric as net_profit
  from public.journal_entries j
  join public.journal_lines jl on jl.journal_entry_id=j.id
  join public.accounting_accounts a on a.id=jl.account_id and a.tenant_id=j.tenant_id
  where j.tenant_id=p_tenant_id and j.status='posted' and j.entry_date between p_from and p_to
    and private.erp_document_scope_allowed(p_tenant_id,j.location_id,p_location_id,'view');
$$;


--
-- Name: v600_period_source_drivers(uuid, text, date, date, date, date, uuid, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v600_period_source_drivers(p_tenant_id uuid, p_metric text, p_from date, p_to date, p_prev_from date, p_prev_to date, p_location_id uuid, p_limit integer) RETURNS TABLE(drivers jsonb, driver_sum numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
with values_by_source as (
  select coalesce(j.source_type,'manual') as source_type,
    coalesce(sum(case
      when p_metric='sales' and a.system_key='sales_revenue' then jl.credit-jl.debit
      when p_metric='cogs' and a.account_type='cogs' then jl.debit-jl.credit
      when p_metric='gross_profit' and a.system_key='sales_revenue' then jl.credit-jl.debit
      when p_metric='gross_profit' and a.account_type='cogs' then -(jl.debit-jl.credit)
      when p_metric='net_profit' and a.account_type='income' then jl.credit-jl.debit
      when p_metric='net_profit' and a.account_type in ('cogs','expense') then -(jl.debit-jl.credit)
      else 0 end) filter(where j.entry_date between p_from and p_to),0)::numeric current_value,
    coalesce(sum(case
      when p_metric='sales' and a.system_key='sales_revenue' then jl.credit-jl.debit
      when p_metric='cogs' and a.account_type='cogs' then jl.debit-jl.credit
      when p_metric='gross_profit' and a.system_key='sales_revenue' then jl.credit-jl.debit
      when p_metric='gross_profit' and a.account_type='cogs' then -(jl.debit-jl.credit)
      when p_metric='net_profit' and a.account_type='income' then jl.credit-jl.debit
      when p_metric='net_profit' and a.account_type in ('cogs','expense') then -(jl.debit-jl.credit)
      else 0 end) filter(where j.entry_date between p_prev_from and p_prev_to),0)::numeric previous_value
  from public.journal_entries j
  join public.journal_lines jl on jl.journal_entry_id=j.id
  join public.accounting_accounts a on a.id=jl.account_id and a.tenant_id=j.tenant_id
  where j.tenant_id=p_tenant_id and j.status='posted'
    and j.entry_date between p_prev_from and p_to
    and private.erp_document_scope_allowed(p_tenant_id,j.location_id,p_location_id,'view')
    and (
      (p_metric='sales' and a.system_key='sales_revenue') or
      (p_metric='cogs' and a.account_type='cogs') or
      (p_metric='gross_profit' and (a.system_key='sales_revenue' or a.account_type='cogs')) or
      (p_metric='net_profit' and a.account_type in ('income','cogs','expense'))
    )
  group by coalesce(j.source_type,'manual')
), ranked as (
  select source_type,round(current_value,4) current_value,round(previous_value,4) previous_value,
    round(current_value-previous_value,4) impact
  from values_by_source
  where abs(current_value)>0.00005 or abs(previous_value)>0.00005
  order by abs(current_value-previous_value) desc,source_type
  limit greatest(1,least(coalesce(p_limit,10),50))
)
select coalesce(jsonb_agg(to_jsonb(r) order by abs(r.impact) desc),'[]'::jsonb),coalesce(sum(r.impact),0)::numeric
from ranked r;
$$;


--
-- Name: v600_product_profit_rows(uuid, date, date, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v600_product_profit_rows(p_tenant_id uuid, p_from date, p_to date, p_location_id uuid DEFAULT NULL::uuid, p_variant_id uuid DEFAULT NULL::uuid) RETURNS TABLE(variant_id uuid, product_id uuid, product_name text, variant_name text, sku text, category_id uuid, category_name text, brand_id uuid, brand_name text, sold_qty numeric, sale_revenue numeric, sale_cogs numeric, sale_discount numeric, returned_qty numeric, return_revenue numeric, return_cogs numeric, net_revenue numeric, net_cogs numeric, gross_profit numeric, margin_pct numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
with sale_facts as (
  select
    si.variant_id,
    sum(si.quantity)::numeric as sold_qty,
    sum(si.taxable_amount)::numeric as sale_revenue,
    sum(si.cost_total)::numeric as sale_cogs,
    sum(si.discount_amount)::numeric as sale_discount
  from public.sales s
  join public.sale_items si on si.tenant_id=s.tenant_id and si.sale_id=s.id
  left join lateral (
    select o.location_id
    from public.document_origins o
    where o.tenant_id=s.tenant_id and o.entity_type='sale' and o.entity_id=s.id
    order by o.created_at asc
    limit 1
  ) origin on true
  where s.tenant_id=p_tenant_id
    and s.status='posted'
    and s.sale_date between p_from and p_to
    and (p_location_id is null or origin.location_id=p_location_id)
    and (p_variant_id is null or si.variant_id=p_variant_id)
  group by si.variant_id
), return_facts as (
  select
    sri.variant_id,
    sum(sri.quantity)::numeric as returned_qty,
    sum(case when si.quantity<>0 then (si.taxable_amount/si.quantity)*sri.quantity else 0 end)::numeric as return_revenue,
    sum(case when si.quantity<>0 then (si.cost_total/si.quantity)*sri.quantity else 0 end)::numeric as return_cogs
  from public.sales_returns sr
  join public.sales_return_items sri on sri.sales_return_id=sr.id
  join public.sale_items si on si.id=sri.sale_item_id and si.variant_id=sri.variant_id
  where sr.tenant_id=p_tenant_id
    and sr.return_date between p_from and p_to
    and (p_location_id is null or sr.location_id=p_location_id)
    and (p_variant_id is null or sri.variant_id=p_variant_id)
  group by sri.variant_id
), variants as (
  select variant_id from sale_facts
  union
  select variant_id from return_facts
)
select
  v.id as variant_id,
  p.id as product_id,
  p.name as product_name,
  v.name as variant_name,
  v.sku,
  p.category_id,
  c.name as category_name,
  p.brand_id,
  b.name as brand_name,
  coalesce(sf.sold_qty,0)::numeric as sold_qty,
  round(coalesce(sf.sale_revenue,0),4)::numeric as sale_revenue,
  round(coalesce(sf.sale_cogs,0),4)::numeric as sale_cogs,
  round(coalesce(sf.sale_discount,0),4)::numeric as sale_discount,
  coalesce(rf.returned_qty,0)::numeric as returned_qty,
  round(coalesce(rf.return_revenue,0),4)::numeric as return_revenue,
  round(coalesce(rf.return_cogs,0),4)::numeric as return_cogs,
  round(coalesce(sf.sale_revenue,0)-coalesce(rf.return_revenue,0),4)::numeric as net_revenue,
  round(coalesce(sf.sale_cogs,0)-coalesce(rf.return_cogs,0),4)::numeric as net_cogs,
  round((coalesce(sf.sale_revenue,0)-coalesce(rf.return_revenue,0))-(coalesce(sf.sale_cogs,0)-coalesce(rf.return_cogs,0)),4)::numeric as gross_profit,
  case when (coalesce(sf.sale_revenue,0)-coalesce(rf.return_revenue,0))=0 then null
       else round((((coalesce(sf.sale_revenue,0)-coalesce(rf.return_revenue,0))-(coalesce(sf.sale_cogs,0)-coalesce(rf.return_cogs,0))) * 100.0)
                  /(coalesce(sf.sale_revenue,0)-coalesce(rf.return_revenue,0)),4)::numeric end as margin_pct
from variants x
join public.product_variants v on v.tenant_id=p_tenant_id and v.id=x.variant_id
join public.products p on p.tenant_id=p_tenant_id and p.id=v.product_id
left join public.product_categories c on c.tenant_id=p_tenant_id and c.id=p.category_id
left join public.product_brands b on b.tenant_id=p_tenant_id and b.id=p.brand_id
left join sale_facts sf on sf.variant_id=v.id
left join return_facts rf on rf.variant_id=v.id;
$$;


--
-- Name: v600_seed_role_permissions(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v600_seed_role_permissions() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.key='auditor' then
    insert into public.role_permissions(role_id,permission_key)
    select new.id,x.k from (values('audit_center.view'::text),('audit_center.review'),('audit_center.export'),('audit_history.view_sensitive'),('profitability.view'),('explain.view')) x(k)
    on conflict do nothing;
  elsif new.key='owner' then
    insert into public.role_permissions(role_id,permission_key)
    select new.id,x.k from (values('audit_center.view'::text),('audit_center.review'),('audit_center.resolve'),('audit_center.export'),('audit_center.configure'),('audit_history.view_sensitive'),('profitability.view'),('explain.view')) x(k)
    on conflict do nothing;
  elsif new.key in ('manager','accountant') then
    insert into public.role_permissions(role_id,permission_key)
    select new.id,x.k from (values('audit_center.view'::text),('audit_center.review'),('audit_center.resolve'),('audit_center.export'),('profitability.view'),('explain.view')) x(k)
    on conflict do nothing;
  end if;
  return new;
end;
$$;


--
-- Name: v600_seed_tenant_audit(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v600_seed_tenant_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_role uuid;
begin
  insert into public.tenant_modules(tenant_id,module_key,enabled,config) values(new.id,'audit_center',true,'{}'::jsonb) on conflict (tenant_id,module_key) do update set enabled=true,updated_at=now();
  insert into public.audit_risk_config_v600(tenant_id) values(new.id) on conflict do nothing;
  select id into v_role from public.roles where tenant_id=new.id and key='auditor';
  if v_role is null then
    insert into public.roles(id,tenant_id,key,name,is_system) values(gen_random_uuid(),new.id,'auditor','Auditor',true) returning id into v_role;
  end if;
  return new;
end;
$$;


--
-- Name: v600_story_write(uuid, text, uuid, text, text, timestamp with time zone, uuid, uuid, uuid, jsonb, jsonb, text, uuid, text, text, text, text, uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.v600_story_write(p_tenant_id uuid, p_entity_type text, p_entity_id uuid, p_entity_reference text, p_action text, p_event_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_actor_user_id uuid DEFAULT NULL::uuid, p_location_id uuid DEFAULT NULL::uuid, p_device_id uuid DEFAULT NULL::uuid, p_before jsonb DEFAULT NULL::jsonb, p_after jsonb DEFAULT NULL::jsonb, p_reason text DEFAULT NULL::text, p_approval_request_id uuid DEFAULT NULL::uuid, p_source_module text DEFAULT NULL::text, p_source_function text DEFAULT NULL::text, p_source_app text DEFAULT NULL::text, p_root_entity_type text DEFAULT NULL::text, p_root_entity_id uuid DEFAULT NULL::uuid, p_request_id text DEFAULT NULL::text, p_related_entities jsonb DEFAULT '[]'::jsonb, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_id uuid := gen_random_uuid();
  v_actor uuid := coalesce(p_actor_user_id,auth.uid());
  v_actor_name text;
  v_roles text[] := '{}'::text[];
  v_device_name text;
  v_device_code text;
  v_source_app text := p_source_app;
  v_location uuid := p_location_id;
  v_device uuid := p_device_id;
  v_root_type text := coalesce(nullif(trim(p_root_entity_type),''),p_entity_type);
  v_root_id uuid := coalesce(p_root_entity_id,p_entity_id);
  v_corr uuid;
  v_prev_hash text;
  v_hash text;
  v_changed text[];
  v_approved_by uuid;
  v_approved_at timestamptz;
  v_approval_note text;
  v_reason text := nullif(trim(coalesce(p_reason,'')),'');
  v_event_time timestamptz := coalesce(p_event_time,now());
  v_payload jsonb;
begin
  if p_tenant_id is null or p_entity_id is null or nullif(trim(p_entity_type),'') is null or nullif(trim(p_action),'') is null then
    raise exception 'tenant, entity type, entity id and action are required for THQ transaction story';
  end if;

  if not exists (select 1 from public.tenants t where t.id=p_tenant_id) then
    raise exception 'Unknown tenant for THQ transaction story';
  end if;

  if v_actor is not null then
    select u.username::text into v_actor_name
    from public.user_login_names u
    where u.user_id=v_actor;

    select coalesce(array_agg(distinct r.key order by r.key),'{}'::text[])
      into v_roles
    from public.tenant_memberships m
    join public.user_roles ur on ur.membership_id=m.id and ur.tenant_id=m.tenant_id
    join public.roles r on r.id=ur.role_id and r.tenant_id=m.tenant_id
    where m.tenant_id=p_tenant_id and m.user_id=v_actor and m.status='active';
  end if;

  if v_device is not null then
    select d.name,d.device_code,coalesce(v_source_app,d.app_type),coalesce(v_location,d.location_id)
      into v_device_name,v_device_code,v_source_app,v_location
    from public.business_devices d
    where d.tenant_id=p_tenant_id and d.id=v_device;
  end if;

  if p_approval_request_id is not null then
    select a.decided_by,a.decided_at,a.decision_note,coalesce(v_reason,a.reason)
      into v_approved_by,v_approved_at,v_approval_note,v_reason
    from public.approval_requests a
    where a.tenant_id=p_tenant_id and a.id=p_approval_request_id;
  end if;

  v_corr := extensions.uuid_generate_v5(
    extensions.uuid_ns_url(),
    'thq:v600:'||p_tenant_id::text||':'||lower(v_root_type)||':'||v_root_id::text
  );

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_corr::text,0));

  select e.event_hash into v_prev_hash
  from public.transaction_story_events_v600 e
  where e.tenant_id=p_tenant_id and e.correlation_id=v_corr
  order by e.event_sequence desc
  limit 1;

  v_changed := private.v600_changed_fields(p_before,p_after);

  v_payload := jsonb_build_object(
    'id',v_id,'tenant_id',p_tenant_id,'correlation_id',v_corr,
    'root_entity_type',v_root_type,'root_entity_id',v_root_id,
    'entity_type',p_entity_type,'entity_id',p_entity_id,'entity_reference',p_entity_reference,
    'action',p_action,'event_time',v_event_time,'actor_user_id',v_actor,'actor_name',v_actor_name,
    'actor_role_keys',v_roles,'location_id',v_location,'device_id',v_device,
    'device_name',v_device_name,'device_code',v_device_code,'source_app',v_source_app,
    'request_id',p_request_id,'before_data',p_before,'after_data',p_after,'changed_fields',v_changed,
    'reason',v_reason,'approval_request_id',p_approval_request_id,'approved_by',v_approved_by,
    'approved_at',v_approved_at,'approval_note',v_approval_note,'source_module',p_source_module,
    'source_function',p_source_function,'related_entities',coalesce(p_related_entities,'[]'::jsonb),
    'metadata',coalesce(p_metadata,'{}'::jsonb),'previous_event_hash',v_prev_hash
  );

  v_hash := encode(extensions.digest(coalesce(v_prev_hash,'')||v_payload::text,'sha256'),'hex');

  insert into public.transaction_story_events_v600(
    id,tenant_id,correlation_id,root_entity_type,root_entity_id,
    entity_type,entity_id,entity_reference,action,event_time,
    actor_user_id,actor_name,actor_role_keys,location_id,device_id,device_name,device_code,source_app,
    request_id,before_data,after_data,changed_fields,reason,approval_request_id,approved_by,approved_at,approval_note,
    source_module,source_function,related_entities,metadata,previous_event_hash,event_hash
  ) values (
    v_id,p_tenant_id,v_corr,v_root_type,v_root_id,
    p_entity_type,p_entity_id,p_entity_reference,p_action,v_event_time,
    v_actor,v_actor_name,v_roles,v_location,v_device,v_device_name,v_device_code,v_source_app,
    p_request_id,p_before,p_after,v_changed,v_reason,p_approval_request_id,v_approved_by,v_approved_at,v_approval_note,
    p_source_module,p_source_function,coalesce(p_related_entities,'[]'::jsonb),coalesce(p_metadata,'{}'::jsonb),v_prev_hash,v_hash
  );

  return v_id;
end;
$$;


--
-- Name: warehouse_v485_permission(uuid, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.warehouse_v485_permission(p_tenant_id uuid, p_approval boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if private.erp_user_is_owner(p_tenant_id) then return;end if;
  if p_approval then
    if not private.erp_has_permission(p_tenant_id,'inventory.manage') and not private.erp_has_permission(p_tenant_id,'approvals.approve') then
      raise exception 'Warehouse transfer approval permission required';
    end if;
  elsif not private.erp_has_permission(p_tenant_id,'inventory.transfer')
     and not private.erp_has_permission(p_tenant_id,'inventory.manage')
     and not private.erp_has_permission(p_tenant_id,'inventory.stock_count') then
    raise exception 'Warehouse inventory permission required';
  end if;
end$$;


--
-- Name: accounting_account_save_v4(uuid, uuid, text, text, text, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_account_save_v4(p_tenant_id uuid, p_account_id uuid, p_code text, p_name text, p_account_type text, p_parent_id uuid, p_description text, p_active boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v uuid;v_system boolean;begin
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'accounting.manage') then raise exception 'Accounting manage permission required';end if;
  if trim(coalesce(p_code,''))='' or trim(coalesce(p_name,''))='' then raise exception 'Account code and name are required';end if;
  if p_account_type not in('asset','liability','equity','income','expense','cogs') then raise exception 'Invalid account type';end if;
  if p_account_id is null then
    insert into public.accounting_accounts(tenant_id,code,name,account_type,parent_id,description,active) values(p_tenant_id,upper(trim(p_code)),trim(p_name),p_account_type,p_parent_id,nullif(trim(coalesce(p_description,'')),''),coalesce(p_active,true)) returning id into v;
  else
    select is_system into v_system from public.accounting_accounts where id=p_account_id and tenant_id=p_tenant_id;if not found then raise exception 'Account not found';end if;
    if coalesce(v_system,false) and not coalesce(p_active,true) then raise exception 'System accounts cannot be archived. Change its mapping or keep it active.';end if;
    update public.accounting_accounts set code=upper(trim(p_code)),name=trim(p_name),account_type=p_account_type,parent_id=p_parent_id,description=nullif(trim(coalesce(p_description,'')),''),active=coalesce(p_active,true),updated_at=now() where id=p_account_id returning id into v;
  end if;return v;
end $$;


--
-- Name: accounting_accounts_list_v4(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_accounts_list_v4(p_tenant_id uuid) RETURNS TABLE(id uuid, code text, name text, account_type text, parent_id uuid, system_key text, description text, is_system boolean, active boolean, balance numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$begin if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;if not private.erp_has_permission(p_tenant_id,'accounting.view') and not private.erp_has_permission(p_tenant_id,'accounting.manage') and not private.erp_user_is_owner(p_tenant_id) then raise exception 'Accounting permission required';end if;return query select a.id,a.code,a.name,a.account_type,a.parent_id,a.system_key,a.description,a.is_system,a.active,coalesce((select sum(case when a.account_type in('asset','expense','cogs') then l.debit-l.credit else l.credit-l.debit end) from public.journal_lines l join public.journal_entries j on j.id=l.journal_entry_id where l.account_id=a.id and j.tenant_id=p_tenant_id and j.status='posted'),0)::numeric from public.accounting_accounts a where a.tenant_id=p_tenant_id order by a.code;end $$;


--
-- Name: accounting_balance_sheet_v500(uuid, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_balance_sheet_v500(p_tenant_id uuid, p_to date, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v_rows jsonb;v_assets numeric:=0;v_liabilities numeric:=0;v_equity numeric:=0;v_earnings numeric:=0;begin perform private.v500_accounting_access(p_tenant_id,false);if p_to is null then raise exception 'End date is required';end if;with balances as (select a.id,a.code::text code,a.name::text name,a.account_type::text account_type,case when a.account_type='asset' then coalesce(sum(jl.debit-jl.credit) filter(where j.id is not null),0) else coalesce(sum(jl.credit-jl.debit) filter(where j.id is not null),0) end::numeric amount from public.accounting_accounts a left join public.journal_lines jl on jl.account_id=a.id left join public.journal_entries j on j.id=jl.journal_entry_id and j.tenant_id=p_tenant_id and j.status='posted' and j.entry_date<=p_to and private.erp_document_scope_allowed(p_tenant_id,j.location_id,p_location_id,'view') where a.tenant_id=p_tenant_id and a.active and a.account_type in('asset','liability','equity') group by a.id,a.code,a.name,a.account_type), earnings as (select coalesce(sum(case when a.account_type='income' then jl.credit-jl.debit when a.account_type in('expense','cogs') then -(jl.debit-jl.credit) else 0 end),0)::numeric amount from public.journal_lines jl join public.accounting_accounts a on a.id=jl.account_id and a.tenant_id=p_tenant_id join public.journal_entries j on j.id=jl.journal_entry_id and j.tenant_id=p_tenant_id and j.status='posted' and j.entry_date<=p_to where a.account_type in('income','expense','cogs') and private.erp_document_scope_allowed(p_tenant_id,j.location_id,p_location_id,'view')) select coalesce(jsonb_agg(jsonb_build_object('account_id',id,'code',code,'name',name,'account_type',account_type,'amount',amount) order by account_type,code) filter(where abs(amount)>0.0001),'[]'::jsonb),coalesce(sum(amount) filter(where account_type='asset'),0),coalesce(sum(amount) filter(where account_type='liability'),0),coalesce(sum(amount) filter(where account_type='equity'),0),coalesce((select amount from earnings),0) into v_rows,v_assets,v_liabilities,v_equity,v_earnings from balances;return jsonb_build_object('statement','balance_sheet','rows',v_rows,'summary',jsonb_build_object('assets',v_assets,'liabilities',v_liabilities,'equity',v_equity,'current_earnings',v_earnings,'liabilities_and_equity',v_liabilities+v_equity+v_earnings,'difference',v_assets-(v_liabilities+v_equity+v_earnings),'as_of',p_to),'location_id',p_location_id);end $$;


--
-- Name: accounting_get_summary(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_get_summary(p_tenant_id uuid, p_from_date date, p_to_date date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_revenue numeric:=0;v_cogs numeric:=0;v_gp numeric:=0;v_exp numeric:=0;v_recv numeric:=0;v_pay numeric:=0;v_stock numeric:=0;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  select coalesce(sum(taxable_total),0),coalesce(sum(cost_total),0),coalesce(sum(gross_profit),0) into v_revenue,v_cogs,v_gp from public.sales where tenant_id=p_tenant_id and sale_date between p_from_date and p_to_date and coalesce(status,'')<>'cancelled';
  if to_regclass('public.expenses') is not null then select coalesce(sum(total_amount),0) into v_exp from public.expenses where tenant_id=p_tenant_id and expense_date between p_from_date and p_to_date and status='posted'; end if;
  select coalesce(sum(greatest(s.grand_total-coalesce(p.paid,0),0)),0) into v_recv from public.sales s left join (select sale_id,sum(amount) paid from public.sale_payments group by sale_id)p on p.sale_id=s.id where s.tenant_id=p_tenant_id and coalesce(s.status,'')<>'cancelled';
  select coalesce(sum(greatest(pu.grand_total-coalesce(py.paid,0),0)),0) into v_pay from public.purchases pu left join (select purchase_id,sum(amount) paid from public.purchase_payments group by purchase_id)py on py.purchase_id=pu.id where pu.tenant_id=p_tenant_id and coalesce(pu.status,'')<>'cancelled';
  select coalesce(sum(sb.quantity*pv.cost_price),0) into v_stock from public.stock_balances sb join public.product_variants pv on pv.id=sb.variant_id where sb.tenant_id=p_tenant_id;
  return jsonb_build_object('revenue',v_revenue,'cost_of_goods_sold',v_cogs,'gross_profit',v_gp,'operating_expenses',v_exp,'net_operating_profit',v_gp-v_exp,'receivables',v_recv,'payables',v_pay,'inventory_value',v_stock);
end $$;


--
-- Name: accounting_get_summary_v32(uuid, date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_get_summary_v32(p_tenant_id uuid, p_from_date date, p_to_date date, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_revenue numeric:=0;v_cogs numeric:=0;v_gp numeric:=0;v_exp numeric:=0;v_recv numeric:=0;v_pay numeric:=0;v_stock numeric:=0;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  select coalesce(sum(s.taxable_total),0),coalesce(sum(s.cost_total),0),coalesce(sum(s.gross_profit),0) into v_revenue,v_cogs,v_gp
  from public.sales s left join public.document_origins o on o.entity_type='sale' and o.entity_id=s.id
  where s.tenant_id=p_tenant_id and s.sale_date between p_from_date and p_to_date and coalesce(s.status,'') not in ('cancelled','void') and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view');
  select coalesce(sum(e.total_amount),0) into v_exp from public.expenses e left join public.document_origins o on o.entity_type='expense' and o.entity_id=e.id
  where e.tenant_id=p_tenant_id and e.expense_date between p_from_date and p_to_date and e.status='posted' and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view');
  select coalesce(sum(greatest(s.grand_total-coalesce(py.paid,0),0)),0) into v_recv from public.sales s left join (select sale_id,sum(amount) paid from public.sale_payments group by sale_id)py on py.sale_id=s.id left join public.document_origins o on o.entity_type='sale' and o.entity_id=s.id where s.tenant_id=p_tenant_id and coalesce(s.status,'') not in ('cancelled','void') and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view');
  select coalesce(sum(greatest(p.grand_total-coalesce(py.paid,0),0)),0) into v_pay from public.purchases p left join (select purchase_id,sum(amount) paid from public.purchase_payments group by purchase_id)py on py.purchase_id=p.id left join public.document_origins o on o.entity_type='purchase' and o.entity_id=p.id where p.tenant_id=p_tenant_id and coalesce(p.status,'') not in ('cancelled','void') and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view');
  select coalesce(sum(sb.quantity*pv.cost_price),0) into v_stock from public.stock_balances sb join public.product_variants pv on pv.id=sb.variant_id where sb.tenant_id=p_tenant_id;
  return jsonb_build_object('revenue',v_revenue,'cost_of_goods_sold',v_cogs,'gross_profit',v_gp,'operating_expenses',v_exp,'net_operating_profit',v_gp-v_exp,'receivables',v_recv,'payables',v_pay,'inventory_value',v_stock,'location_id',p_location_id,'stock_scope','business');
end $$;


--
-- Name: accounting_get_summary_v4(uuid, date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_get_summary_v4(p_tenant_id uuid, p_from_date date, p_to_date date, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_revenue numeric:=0;v_cogs numeric:=0;v_exp numeric:=0;v_recv numeric:=0;v_pay numeric:=0;v_stock numeric:=0;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if not private.erp_has_permission(p_tenant_id,'accounting.view') and not private.erp_has_permission(p_tenant_id,'accounting.manage') and not private.erp_user_is_owner(p_tenant_id) then raise exception 'Accounting permission required';end if;
  if p_from_date is null or p_to_date is null or p_from_date>p_to_date then raise exception 'Invalid date range';end if;

  select
    coalesce(sum(case when a.account_type='income' then l.credit-l.debit else 0 end),0),
    coalesce(sum(case when a.account_type='cogs' then l.debit-l.credit else 0 end),0),
    coalesce(sum(case when a.account_type='expense' then l.debit-l.credit else 0 end),0)
  into v_revenue,v_cogs,v_exp
  from public.journal_entries j
  join public.journal_lines l on l.journal_entry_id=j.id
  join public.accounting_accounts a on a.id=l.account_id and a.tenant_id=j.tenant_id
  where j.tenant_id=p_tenant_id and j.status='posted' and j.entry_date between p_from_date and p_to_date
    and (p_location_id is null or j.location_id=p_location_id)
    and (j.location_id is null or private.erp_document_scope_allowed(p_tenant_id,j.location_id,p_location_id,'view'));

  select
    coalesce(sum(case when a.system_key='accounts_receivable' then l.debit-l.credit else 0 end),0),
    coalesce(sum(case when a.system_key='accounts_payable' then l.credit-l.debit else 0 end),0)
  into v_recv,v_pay
  from public.journal_entries j
  join public.journal_lines l on l.journal_entry_id=j.id
  join public.accounting_accounts a on a.id=l.account_id and a.tenant_id=j.tenant_id
  where j.tenant_id=p_tenant_id and j.status='posted' and j.entry_date<=p_to_date
    and (p_location_id is null or j.location_id=p_location_id)
    and (j.location_id is null or private.erp_document_scope_allowed(p_tenant_id,j.location_id,p_location_id,'view'));

  select coalesce(sum(coalesce(b.quantity,0)*coalesce(nullif(b.average_cost,0),pv.cost_price,0)),0)
  into v_stock
  from public.location_product_settings s
  join public.product_variants pv on pv.id=s.variant_id
  join public.business_locations bl on bl.id=s.location_id and bl.active
  left join public.location_stock_balances b on b.tenant_id=s.tenant_id and b.location_id=s.location_id and b.variant_id=s.variant_id
  where s.tenant_id=p_tenant_id and s.active
    and (p_location_id is null or s.location_id=p_location_id)
    and private.erp_document_scope_allowed(p_tenant_id,s.location_id,p_location_id,'view');

  return jsonb_build_object(
    'revenue',v_revenue,
    'cost_of_goods_sold',v_cogs,
    'gross_profit',v_revenue-v_cogs,
    'operating_expenses',v_exp,
    'net_operating_profit',v_revenue-v_cogs-v_exp,
    'receivables',greatest(v_recv,0),
    'payables',greatest(v_pay,0),
    'inventory_value',v_stock,
    'location_id',p_location_id,
    'stock_scope',case when p_location_id is null then 'accessible_locations' else 'location' end
  );
end $$;


--
-- Name: accounting_list_ledger(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_list_ledger(p_tenant_id uuid, p_from_date date, p_to_date date) RETURNS TABLE(entry_date date, entry_type text, reference text, party text, description text, debit numeric, credit numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  return query
  select x.entry_date,x.entry_type,x.reference,x.party,x.description,x.debit,x.credit
  from (
    select s.sale_date entry_date,'sale'::text entry_type,s.sale_number reference,c.name party,'Sales invoice'::text description,s.grand_total::numeric debit,0::numeric credit
    from public.sales s join public.customers c on c.id=s.customer_id where s.tenant_id=p_tenant_id and s.sale_date between p_from_date and p_to_date and coalesce(s.status,'')<>'cancelled'
    union all
    select p.purchase_date,'purchase',p.purchase_number,sp.name,'Purchase bill',p.grand_total::numeric,0::numeric
    from public.purchases p join public.suppliers sp on sp.id=p.supplier_id where p.tenant_id=p_tenant_id and p.purchase_date between p_from_date and p_to_date and coalesce(p.status,'')<>'cancelled'
    union all
    select e.expense_date,'expense',e.expense_number,coalesce(e.payee,''),e.description,e.total_amount::numeric,0::numeric
    from public.expenses e where e.tenant_id=p_tenant_id and e.expense_date between p_from_date and p_to_date and e.status='posted'
    union all
    select coalesce(sp.paid_at,sp.created_at)::date,'customer_payment',s.sale_number,c.name,'Customer receipt',0::numeric,sp.amount::numeric
    from public.sale_payments sp join public.sales s on s.id=sp.sale_id join public.customers c on c.id=s.customer_id
    where s.tenant_id=p_tenant_id and coalesce(sp.paid_at,sp.created_at)::date between p_from_date and p_to_date
    union all
    select coalesce(pp.paid_at,pp.created_at)::date,'supplier_payment',p.purchase_number,s.name,'Supplier payment',0::numeric,pp.amount::numeric
    from public.purchase_payments pp join public.purchases p on p.id=pp.purchase_id join public.suppliers s on s.id=p.supplier_id
    where p.tenant_id=p_tenant_id and coalesce(pp.paid_at,pp.created_at)::date between p_from_date and p_to_date
  ) x order by x.entry_date desc,x.reference desc;
end $$;


--
-- Name: accounting_list_ledger_v32(uuid, date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_list_ledger_v32(p_tenant_id uuid, p_from_date date, p_to_date date, p_location_id uuid DEFAULT NULL::uuid) RETURNS TABLE(entry_date date, entry_type text, reference text, party text, description text, debit numeric, credit numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  return query select x.entry_date,x.entry_type,x.reference,x.party,x.description,x.debit,x.credit from (
    select s.sale_date entry_date,'sale'::text entry_type,coalesce(dn.terminal_number,ln.local_number,s.sale_number) reference,c.name party,'Sales invoice'::text description,s.grand_total::numeric debit,0::numeric credit
    from public.sales s join public.customers c on c.id=s.customer_id left join public.document_origins o on o.entity_type='sale' and o.entity_id=s.id left join public.location_document_numbers ln on ln.entity_type='sale' and ln.entity_id=s.id left join public.device_document_numbers dn on dn.entity_type='sale' and dn.entity_id=s.id
    where s.tenant_id=p_tenant_id and s.sale_date between p_from_date and p_to_date and coalesce(s.status,'') not in ('cancelled','void') and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view')
    union all
    select p.purchase_date,'purchase',coalesce(dn.terminal_number,ln.local_number,p.purchase_number),sp.name,'Purchase bill',p.grand_total::numeric,0::numeric
    from public.purchases p join public.suppliers sp on sp.id=p.supplier_id left join public.document_origins o on o.entity_type='purchase' and o.entity_id=p.id left join public.location_document_numbers ln on ln.entity_type='purchase' and ln.entity_id=p.id left join public.device_document_numbers dn on dn.entity_type='purchase' and dn.entity_id=p.id
    where p.tenant_id=p_tenant_id and p.purchase_date between p_from_date and p_to_date and coalesce(p.status,'') not in ('cancelled','void') and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view')
    union all
    select e.expense_date,'expense',coalesce(dn.terminal_number,ln.local_number,e.expense_number),coalesce(e.payee,''),e.description,e.total_amount::numeric,0::numeric
    from public.expenses e left join public.document_origins o on o.entity_type='expense' and o.entity_id=e.id left join public.location_document_numbers ln on ln.entity_type='expense' and ln.entity_id=e.id left join public.device_document_numbers dn on dn.entity_type='expense' and dn.entity_id=e.id
    where e.tenant_id=p_tenant_id and e.expense_date between p_from_date and p_to_date and e.status='posted' and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view')
  )x order by x.entry_date desc,x.reference desc;
end $$;


--
-- Name: accounting_manual_journal_v4(uuid, uuid, date, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_manual_journal_v4(p_tenant_id uuid, p_location_id uuid, p_entry_date date, p_description text, p_lines jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'accounting.journal') and not private.erp_has_permission(p_tenant_id,'accounting.manage') then raise exception 'Manual journal permission required';end if;
  perform private.v4_location_access(p_tenant_id,p_location_id,'manage');return private.v4_journal_create(p_tenant_id,p_location_id,p_entry_date,trim(p_description),'manual',gen_random_uuid(),null,p_lines);
end $$;


--
-- Name: accounting_mapping_set_v4(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_mapping_set_v4(p_tenant_id uuid, p_mapping_key text, p_account_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'accounting.manage') then raise exception 'Accounting manage permission required';end if;
  if not exists(select 1 from public.accounting_accounts where id=p_account_id and tenant_id=p_tenant_id and active) then raise exception 'Account not found';end if;
  insert into public.accounting_account_mappings(tenant_id,mapping_key,account_id,updated_at) values(p_tenant_id,p_mapping_key,p_account_id,now()) on conflict(tenant_id,mapping_key) do update set account_id=excluded.account_id,updated_at=now();
end $$;


--
-- Name: accounting_mappings_list_v4(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_mappings_list_v4(p_tenant_id uuid) RETURNS TABLE(mapping_key text, account_id uuid, account_code text, account_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if not private.erp_has_permission(p_tenant_id,'accounting.view') and not private.erp_has_permission(p_tenant_id,'accounting.manage') and not private.erp_user_is_owner(p_tenant_id) then raise exception 'Accounting permission required';end if;
  return query
  select m.mapping_key,m.account_id,a.code,a.name
  from public.accounting_account_mappings m
  join public.accounting_accounts a on a.id=m.account_id and a.tenant_id=m.tenant_id
  where m.tenant_id=p_tenant_id
  order by m.mapping_key;
end $$;


--
-- Name: accounting_register_v4(uuid, text, date, date, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_register_v4(p_tenant_id uuid, p_register text, p_from date, p_to date, p_location_id uuid DEFAULT NULL::uuid, p_query text DEFAULT NULL::text) RETURNS TABLE(entry_date date, reference text, party text, description text, debit numeric, credit numeric, location_code text, user_name text, source_type text, source_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare q text:='%'||lower(trim(coalesce(p_query,'')))||'%';begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  return query
  select j.entry_date,j.source_reference::text,coalesce(case when jl.party_type='customer' then c.name::text when jl.party_type='supplier' then s.name::text else '' end,'')::text,coalesce(jl.description::text,j.description::text,'')::text,jl.debit,jl.credit,coalesce(bl.location_code::text,'')::text,coalesce(ul.username::text,'')::text,j.source_type::text,j.source_id
  from public.journal_entries j join public.journal_lines jl on jl.journal_entry_id=j.id join public.accounting_accounts a on a.id=jl.account_id
  left join public.customers c on jl.party_type='customer' and c.id=jl.party_id left join public.suppliers s on jl.party_type='supplier' and s.id=jl.party_id left join public.business_locations bl on bl.id=j.location_id left join public.user_login_names ul on ul.user_id=j.created_by
  where j.tenant_id=p_tenant_id and j.status='posted' and j.entry_date between p_from and p_to and private.erp_document_scope_allowed(p_tenant_id,j.location_id,p_location_id,'view')
    and (p_register='all' or (p_register='sales' and j.source_type in('sale','sale_payment','sales_return')) or (p_register='purchases' and j.source_type in('purchase','purchase_payment','purchase_return')) or (p_register='cash' and a.system_key='cash') or (p_register='bank' and a.system_key in('bank','upi','card')) or (p_register='gst' and private.gst_v520_account_family(a.system_key) is not null) or (p_register='receivables' and a.system_key='accounts_receivable') or (p_register='payables' and a.system_key='accounts_payable') or (p_register='journal' and j.source_type='manual'))
    and (trim(coalesce(p_query,''))='' or lower(coalesce(j.source_reference::text,'')) like q or lower(coalesce(j.description::text,'')) like q or lower(coalesce(c.name::text,'')) like q or lower(coalesce(s.name::text,'')) like q or lower(coalesce(a.name::text,'')) like q
      or exists(select 1 from public.sales sx join public.sale_items six on six.sale_id=sx.id join public.product_variants pvx on pvx.id=six.variant_id join public.products prx on prx.id=pvx.product_id where sx.tenant_id=p_tenant_id and sx.id=case when j.source_type='sale' then j.source_id when j.source_type='sale_payment' then (select spx.sale_id from public.sale_payments spx where spx.id=j.source_id) when j.source_type='sales_return' then (select srx.sale_id from public.sales_returns srx where srx.id=j.source_id) else null end and (lower(prx.name::text) like q or lower(coalesce(pvx.sku::text,'')) like q or lower(coalesce(pvx.part_number::text,'')) like q))
      or exists(select 1 from public.purchases pxh join public.purchase_items pix on pix.purchase_id=pxh.id join public.product_variants pvx on pvx.id=pix.variant_id join public.products prx on prx.id=pvx.product_id where pxh.tenant_id=p_tenant_id and pxh.id=case when j.source_type='purchase' then j.source_id when j.source_type='purchase_payment' then (select ppx.purchase_id from public.purchase_payments ppx where ppx.id=j.source_id) when j.source_type='purchase_return' then (select prx2.purchase_id from public.purchase_returns prx2 where prx2.id=j.source_id) else null end and (lower(prx.name::text) like q or lower(coalesce(pvx.sku::text,'')) like q or lower(coalesce(pvx.part_number::text,'')) like q)) )
  order by j.entry_date desc,j.created_at desc;
end $$;


--
-- Name: accounting_statement_v41(uuid, text, date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_statement_v41(p_tenant_id uuid, p_statement text, p_from date, p_to date, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_key text:=lower(trim(coalesce(p_statement,'')));
  v_rows jsonb:='[]'::jsonb;
  v_summary jsonb:='{}'::jsonb;
  v_revenue numeric:=0; v_cogs numeric:=0; v_expenses numeric:=0; v_net numeric:=0;
  v_assets numeric:=0; v_liabilities numeric:=0; v_equity numeric:=0; v_current_earnings numeric:=0;
  v_dr numeric:=0; v_cr numeric:=0; v_in numeric:=0; v_out numeric:=0;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if not private.erp_user_is_owner(p_tenant_id)
     and not private.erp_has_permission(p_tenant_id,'accounting.view')
     and not private.erp_has_permission(p_tenant_id,'accounting.manage') then
    raise exception 'Accounting permission required';
  end if;
  if p_to is null then raise exception 'End date is required';end if;
  if p_from is null then p_from:=date '2000-01-01';end if;
  if p_from>p_to then raise exception 'Invalid date range';end if;

  if v_key='trial_balance' then
    with balances as (
      select a.id,a.code::text code,a.name::text name,a.account_type::text account_type,
        coalesce(sum(jl.debit) filter(where j.id is not null),0)::numeric debit,
        coalesce(sum(jl.credit) filter(where j.id is not null),0)::numeric credit
      from public.accounting_accounts a
      left join public.journal_lines jl on jl.account_id=a.id
      left join public.journal_entries j on j.id=jl.journal_entry_id
        and j.tenant_id=p_tenant_id and j.status='posted' and j.entry_date<=p_to
        and private.erp_document_scope_allowed(p_tenant_id,j.location_id,p_location_id,'view')
      where a.tenant_id=p_tenant_id and a.active
      group by a.id,a.code,a.name,a.account_type
    )
    select coalesce(jsonb_agg(jsonb_build_object(
      'account_id',id,'code',code,'name',name,'account_type',account_type,
      'debit',debit,'credit',credit,
      'balance',case when account_type in('asset','expense','cogs') then debit-credit else credit-debit end
    ) order by code),'[]'::jsonb),coalesce(sum(debit),0),coalesce(sum(credit),0)
    into v_rows,v_dr,v_cr from balances where abs(debit)>0.0001 or abs(credit)>0.0001;
    v_summary:=jsonb_build_object('total_debit',v_dr,'total_credit',v_cr,'difference',v_dr-v_cr);

  elsif v_key='profit_loss' then
    with balances as (
      select a.id,a.code::text code,a.name::text name,a.account_type::text account_type,
        case when a.account_type='income' then coalesce(sum(jl.credit-jl.debit) filter(where j.id is not null),0)
             else coalesce(sum(jl.debit-jl.credit) filter(where j.id is not null),0) end::numeric amount
      from public.accounting_accounts a
      left join public.journal_lines jl on jl.account_id=a.id
      left join public.journal_entries j on j.id=jl.journal_entry_id
        and j.tenant_id=p_tenant_id and j.status='posted' and j.entry_date between p_from and p_to
        and private.erp_document_scope_allowed(p_tenant_id,j.location_id,p_location_id,'view')
      where a.tenant_id=p_tenant_id and a.active and a.account_type in('income','cogs','expense')
      group by a.id,a.code,a.name,a.account_type
    )
    select coalesce(jsonb_agg(jsonb_build_object('account_id',id,'code',code,'name',name,'account_type',account_type,'amount',amount) order by account_type,code),'[]'::jsonb),
      coalesce(sum(amount) filter(where account_type='income'),0),
      coalesce(sum(amount) filter(where account_type='cogs'),0),
      coalesce(sum(amount) filter(where account_type='expense'),0)
    into v_rows,v_revenue,v_cogs,v_expenses from balances where abs(amount)>0.0001;
    v_net:=v_revenue-v_cogs-v_expenses;
    v_summary:=jsonb_build_object('revenue',v_revenue,'cogs',v_cogs,'expenses',v_expenses,'net_profit',v_net,'from',p_from,'to',p_to);

  elsif v_key='balance_sheet' then
    with balances as (
      select a.id,a.code::text code,a.name::text name,a.account_type::text account_type,
        case when a.account_type='asset' then coalesce(sum(jl.debit-jl.credit) filter(where j.id is not null),0)
             else coalesce(sum(jl.credit-jl.debit) filter(where j.id is not null),0) end::numeric amount
      from public.accounting_accounts a
      left join public.journal_lines jl on jl.account_id=a.id
      left join public.journal_entries j on j.id=jl.journal_entry_id
        and j.tenant_id=p_tenant_id and j.status='posted' and j.entry_date<=p_to
        and private.erp_document_scope_allowed(p_tenant_id,j.location_id,p_location_id,'view')
      where a.tenant_id=p_tenant_id and a.active and a.account_type in('asset','liability','equity')
      group by a.id,a.code,a.name,a.account_type
    ), earnings as (
      select coalesce(sum(case when a.account_type='income' then jl.credit-jl.debit when a.account_type in('expense','cogs') then -(jl.debit-jl.credit) else 0 end),0)::numeric amount
      from public.journal_lines jl
      join public.accounting_accounts a on a.id=jl.account_id and a.tenant_id=p_tenant_id
      join public.journal_entries j on j.id=jl.journal_entry_id and j.tenant_id=p_tenant_id and j.status='posted' and j.entry_date<=p_to
      where a.account_type in('income','expense','cogs') and private.erp_document_scope_allowed(p_tenant_id,j.location_id,p_location_id,'view')
    )
    select coalesce(jsonb_agg(jsonb_build_object('account_id',id,'code',code,'name',name,'account_type',account_type,'amount',amount) order by account_type,code),'[]'::jsonb),
      coalesce(sum(amount) filter(where account_type='asset'),0),
      coalesce(sum(amount) filter(where account_type='liability'),0),
      coalesce(sum(amount) filter(where account_type='equity'),0)
    into v_rows,v_assets,v_liabilities,v_equity from balances where abs(amount)>0.0001;
    select coalesce(sum(case when a.account_type='income' then jl.credit-jl.debit when a.account_type in('expense','cogs') then -(jl.debit-jl.credit) else 0 end),0)::numeric into v_current_earnings from public.journal_lines jl join public.accounting_accounts a on a.id=jl.account_id and a.tenant_id=p_tenant_id join public.journal_entries j on j.id=jl.journal_entry_id and j.tenant_id=p_tenant_id and j.status='posted' and j.entry_date<=p_to where a.account_type in('income','expense','cogs') and private.erp_document_scope_allowed(p_tenant_id,j.location_id,p_location_id,'view');
    v_summary:=jsonb_build_object(
      'assets',v_assets,'liabilities',v_liabilities,'equity',v_equity,
      'current_earnings',v_current_earnings,
      'liabilities_and_equity',v_liabilities+v_equity+v_current_earnings,
      'difference',v_assets-(v_liabilities+v_equity+v_current_earnings),'as_of',p_to
    );

  elsif v_key='cash_flow' then
    with cash_accounts as (
      select distinct a.id,a.code::text code,a.name::text name,a.system_key::text system_key
      from public.accounting_accounts a
      left join public.accounting_account_mappings m on m.tenant_id=a.tenant_id and m.account_id=a.id
      where a.tenant_id=p_tenant_id and a.active
        and (a.system_key in('cash','bank','upi','card') or m.mapping_key in('payment.cash','payment.bank','payment.upi','payment.card'))
    ), moves as (
      select a.id,a.code,a.name,a.system_key,
        coalesce(sum(jl.debit) filter(where j.id is not null),0)::numeric inflow,
        coalesce(sum(jl.credit) filter(where j.id is not null),0)::numeric outflow
      from cash_accounts a
      left join public.journal_lines jl on jl.account_id=a.id
      left join public.journal_entries j on j.id=jl.journal_entry_id
        and j.tenant_id=p_tenant_id and j.status='posted' and j.entry_date between p_from and p_to
        and private.erp_document_scope_allowed(p_tenant_id,j.location_id,p_location_id,'view')
      group by a.id,a.code,a.name,a.system_key
    )
    select coalesce(jsonb_agg(jsonb_build_object('account_id',id,'code',code,'name',name,'system_key',system_key,'inflow',inflow,'outflow',outflow,'net_change',inflow-outflow) order by code),'[]'::jsonb),
      coalesce(sum(inflow),0),coalesce(sum(outflow),0)
    into v_rows,v_in,v_out from moves where abs(inflow)>0.0001 or abs(outflow)>0.0001;
    v_summary:=jsonb_build_object('inflow',v_in,'outflow',v_out,'net_change',v_in-v_out,'from',p_from,'to',p_to,'note','Cash/Bank/UPI/Card account movement');
  else
    raise exception 'Unknown accounting statement %',p_statement;
  end if;

  return jsonb_build_object('statement',v_key,'rows',v_rows,'summary',v_summary,'location_id',p_location_id);
end $$;


--
-- Name: analytics_top_customers_v4(uuid, date, date, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analytics_top_customers_v4(p_tenant_id uuid, p_from date, p_to date, p_location_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 10) RETURNS TABLE(customer_id uuid, customer_name text, sale_count bigint, revenue numeric, balance_due numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
 if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
 return query
 select c.id,c.name,count(s.id),sum(greatest(s.grand_total-coalesce(rt.returned,0),0)),sum(greatest(s.grand_total-coalesce(py.paid,0)-coalesce(rt.returned,0),0))
 from public.sales s join public.customers c on c.id=s.customer_id
 left join(select sale_id,sum(amount) paid from public.sale_payments group by sale_id)py on py.sale_id=s.id
 left join(select sale_id,sum(grand_total) returned from public.sales_returns where refund_status<>'waived' group by sale_id)rt on rt.sale_id=s.id
 left join public.document_origins o on o.entity_type='sale' and o.entity_id=s.id
 where s.tenant_id=p_tenant_id and s.sale_date between p_from and p_to and coalesce(s.status,'') not in('void','cancelled') and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view')
 group by c.id,c.name order by sum(greatest(s.grand_total-coalesce(rt.returned,0),0)) desc limit greatest(1,least(coalesce(p_limit,10),100));
end $$;


--
-- Name: analytics_top_products_v4(uuid, date, date, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analytics_top_products_v4(p_tenant_id uuid, p_from date, p_to date, p_location_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 10) RETURNS TABLE(variant_id uuid, product_name text, sku text, quantity numeric, revenue numeric, gross_profit numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
 if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
 return query
 with sold as (
   select si.variant_id,max(pr.name) product_name,max(pv.sku) sku,sum(si.quantity) qty,sum(si.line_total) revenue,sum(coalesce(si.gross_profit,0)) profit
   from public.sale_items si join public.sales s on s.id=si.sale_id join public.product_variants pv on pv.id=si.variant_id join public.products pr on pr.id=pv.product_id left join public.document_origins o on o.entity_type='sale' and o.entity_id=s.id
   where s.tenant_id=p_tenant_id and s.sale_date between p_from and p_to and coalesce(s.status,'') not in('void','cancelled') and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view') group by si.variant_id
 ),ret as (
   select ri.variant_id,sum(ri.quantity) qty,sum(ri.line_total) revenue,sum(coalesce(si.cost_total,0)*(ri.quantity/nullif(si.quantity,0))) return_cost
   from public.sales_return_items ri join public.sales_returns r on r.id=ri.sales_return_id join public.sale_items si on si.id=ri.sale_item_id
   where r.tenant_id=p_tenant_id and r.return_date between p_from and p_to and r.refund_status<>'waived' and private.erp_document_scope_allowed(p_tenant_id,r.location_id,p_location_id,'view') group by ri.variant_id
 )
 select s.variant_id,s.product_name,s.sku,greatest(s.qty-coalesce(r.qty,0),0),greatest(s.revenue-coalesce(r.revenue,0),0),s.profit-(coalesce(r.revenue,0)-coalesce(r.return_cost,0))
 from sold s left join ret r on r.variant_id=s.variant_id order by greatest(s.qty-coalesce(r.qty,0),0) desc limit greatest(1,least(coalesce(p_limit,10),100));
end $$;


--
-- Name: app_error_log_write(text, text, text, jsonb, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_error_log_write(p_app_key text, p_message text, p_stack_trace text DEFAULT NULL::text, p_context jsonb DEFAULT '{}'::jsonb, p_tenant_id uuid DEFAULT NULL::uuid, p_severity text DEFAULT 'error'::text, p_app_version text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_id uuid;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if p_tenant_id is not null and not private.erp_user_has_tenant_access(p_tenant_id) and not private.platform_v2_is_admin() then raise exception 'Access denied'; end if;
  insert into public.app_error_logs(tenant_id,user_id,app_key,severity,message,stack_trace,context,app_version)
  values(p_tenant_id,auth.uid(),p_app_key,coalesce(nullif(p_severity,''),'error'),left(coalesce(p_message,'Unknown error'),4000),left(p_stack_trace,16000),coalesce(p_context,'{}'::jsonb),p_app_version)
  returning id into v_id;
  return v_id;
end $$;


--
-- Name: app_error_logs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.app_error_logs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid,
    user_id uuid,
    app_key text NOT NULL,
    severity text DEFAULT 'error'::text NOT NULL,
    message text NOT NULL,
    stack_trace text,
    context jsonb DEFAULT '{}'::jsonb NOT NULL,
    app_version text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT app_error_logs_app_key_check CHECK ((app_key = ANY (ARRAY['client'::text, 'admin'::text, 'pos'::text, 'backend'::text]))),
    CONSTRAINT app_error_logs_severity_check CHECK ((severity = ANY (ARRAY['info'::text, 'warning'::text, 'error'::text, 'fatal'::text, 'issue'::text])))
);


--
-- Name: app_error_logs_list(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_error_logs_list(p_tenant_id uuid, p_limit integer DEFAULT 200) RETURNS SETOF public.app_error_logs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  if not private.erp_has_permission(p_tenant_id,'logs.view') then raise exception 'Permission denied'; end if;
  return query select * from public.app_error_logs where tenant_id=p_tenant_id order by created_at desc limit greatest(1,least(coalesce(p_limit,200),1000));
end $$;


--
-- Name: app_menu_tree_v45(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_menu_tree_v45(p_tenant_id uuid, p_app_key text) RETURNS TABLE(id uuid, node_key text, node_type text, module_key text, parent_id uuid, label text, icon_key text, sort_order integer, enabled boolean, collapsed_by_default boolean, metadata jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare use_tenant boolean;
begin
  if p_app_key not in('client','pos') then raise exception 'Invalid app key';end if;
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  select exists(select 1 from public.app_menu_nodes_v45 n where n.tenant_id=p_tenant_id and n.app_key=p_app_key) into use_tenant;
  return query
  select n.id,n.node_key,n.node_type,n.module_key,n.parent_id,n.label,n.icon_key,n.sort_order,n.enabled,n.collapsed_by_default,n.metadata
  from public.app_menu_nodes_v45 n
  where n.app_key=p_app_key and n.enabled and ((use_tenant and n.tenant_id=p_tenant_id) or (not use_tenant and n.tenant_id is null))
  order by n.sort_order,n.label;
end $$;


--
-- Name: approval_request_decide_v4(uuid, uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approval_request_decide_v4(p_tenant_id uuid, p_request_id uuid, p_approve boolean, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare a public.approval_requests%rowtype;begin if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'approvals.approve') then raise exception 'Approval permission required';end if;select * into a from public.approval_requests where id=p_request_id and tenant_id=p_tenant_id and status='pending' for update;if not found then raise exception 'Pending approval not found';end if;update public.approval_requests set status=case when p_approve then 'approved' else 'rejected' end,decided_by=auth.uid(),decided_at=now(),decision_note=nullif(trim(coalesce(p_note,'')),'') where id=a.id;if a.entity_type='stock_adjustment_v500' and a.entity_id is not null then update public.stock_adjustment_requests_v500 set status=case when p_approve then 'approved' else 'rejected' end,decided_by=auth.uid(),decided_at=now() where id=a.entity_id and tenant_id=p_tenant_id and status='pending';if p_approve then perform private.v500_stock_adjustment_post(p_tenant_id,a.entity_id);end if;end if;end $$;


--
-- Name: approval_requests_list_v4(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approval_requests_list_v4(p_tenant_id uuid, p_status text DEFAULT 'pending'::text) RETURNS TABLE(id uuid, module_key text, action_key text, entity_type text, entity_id uuid, amount numeric, percentage numeric, status text, reason text, requested_by uuid, requested_username text, requested_at timestamp with time zone, decided_at timestamp with time zone, decision_note text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  return query select r.id,r.module_key,r.action_key,r.entity_type,r.entity_id,r.amount,r.percentage,r.status,r.reason,r.requested_by,coalesce(u.username,''),r.requested_at,r.decided_at,r.decision_note
  from public.approval_requests r left join public.user_login_names u on u.user_id=r.requested_by
  where r.tenant_id=p_tenant_id and (p_status is null or p_status='' or r.status=p_status)
  order by case when r.status='pending' then 0 else 1 end,r.requested_at desc;
end $$;


--
-- Name: approval_rule_save_v4(uuid, uuid, text, text, text, numeric, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approval_rule_save_v4(p_tenant_id uuid, p_rule_id uuid, p_module_key text, p_action_key text, p_threshold_type text, p_threshold_value numeric, p_required_permission text, p_active boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_id uuid; begin
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'settings.manage') then raise exception 'Settings permission required';end if;
  if p_rule_id is null then
    insert into public.approval_rules(tenant_id,module_key,action_key,threshold_type,threshold_value,required_permission,active)
    values(p_tenant_id,trim(p_module_key),trim(p_action_key),p_threshold_type,p_threshold_value,coalesce(nullif(trim(p_required_permission),''),'approvals.approve'),coalesce(p_active,true)) returning id into v_id;
  else
    update public.approval_rules set module_key=trim(p_module_key),action_key=trim(p_action_key),threshold_type=p_threshold_type,threshold_value=p_threshold_value,required_permission=coalesce(nullif(trim(p_required_permission),''),'approvals.approve'),active=coalesce(p_active,true)
    where id=p_rule_id and tenant_id=p_tenant_id returning id into v_id;
  end if;
  if v_id is null then raise exception 'Approval rule not found';end if;
  return v_id;
end $$;


--
-- Name: audit_center_summary_v600(uuid, timestamp with time zone, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_center_summary_v600(p_tenant_id uuid, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_from timestamptz := coalesce(p_from,date_trunc('day',now()));
  v_to timestamptz := coalesce(p_to,now());
  v_high bigint:=0; v_review bigint:=0; v_open bigint:=0; v_normal bigint:=0; v_total_roots bigint:=0;
  v_resolved bigint:=0; v_dismissed bigint:=0; v_explained bigint:=0; v_total_findings bigint:=0;
begin
  if not private.has_permission(p_tenant_id,'audit_center.view') then raise exception 'Permission denied' using errcode='42501'; end if;

  select
    count(*) filter(where severity='high_risk' and status in ('open','under_review','escalated')),
    count(*) filter(where severity='needs_review' and status in ('open','under_review','escalated')),
    count(*) filter(where status in ('open','under_review','escalated')),
    count(*) filter(where status='resolved'),
    count(*) filter(where status='dismissed'),
    count(*) filter(where status='explained'),
    count(*)
  into v_high,v_review,v_open,v_resolved,v_dismissed,v_explained,v_total_findings
  from public.audit_findings_v600 f
  where f.tenant_id=p_tenant_id and f.detected_at>=v_from and f.detected_at<=v_to
    and (p_location_id is null or f.location_id=p_location_id);

  select count(distinct e.correlation_id) into v_total_roots
  from public.transaction_story_events_v600 e
  where e.tenant_id=p_tenant_id and e.event_time>=v_from and e.event_time<=v_to
    and (p_location_id is null or e.location_id=p_location_id);

  select count(*) into v_normal from (
    select distinct e.correlation_id
    from public.transaction_story_events_v600 e
    where e.tenant_id=p_tenant_id and e.event_time>=v_from and e.event_time<=v_to
      and (p_location_id is null or e.location_id=p_location_id)
      and not exists (
        select 1 from public.audit_findings_v600 f
        where f.tenant_id=e.tenant_id and f.correlation_id=e.correlation_id
          and f.detected_at>=v_from and f.detected_at<=v_to
          and f.status in ('open','under_review','escalated')
      )
  ) q;

  return jsonb_build_object(
    'from',v_from,'to',v_to,'location_id',p_location_id,
    'high_risk',coalesce(v_high,0),
    'needs_review',coalesce(v_review,0),
    'normal',coalesce(v_normal,0),
    'open_attention',coalesce(v_open,0),
    'transaction_roots',coalesce(v_total_roots,0),
    'finding_lifecycle',jsonb_build_object(
      'total',coalesce(v_total_findings,0),
      'resolved',coalesce(v_resolved,0),
      'dismissed',coalesce(v_dismissed,0),
      'explained',coalesce(v_explained,0)
    ),
    'category_rule','High Risk and Needs Review count only active attention states: open, under_review, escalated. Normal means no active finding in the selected period. Resolved, dismissed and explained evidence remains retained in history.'
  );
end;
$$;


--
-- Name: audit_finding_detail_v600(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_finding_detail_v600(p_tenant_id uuid, p_finding_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare f public.audit_findings_v600%rowtype; v_sensitive boolean; v_events jsonb;
begin
  if not private.has_permission(p_tenant_id,'audit_center.view') then raise exception 'Permission denied' using errcode='42501'; end if;
  select * into f from public.audit_findings_v600 where tenant_id=p_tenant_id and id=p_finding_id;
  if not found then raise exception 'Audit finding not found'; end if;
  v_sensitive := private.has_permission(p_tenant_id,'audit_history.view_sensitive');
  select coalesce(jsonb_agg(jsonb_build_object(
    'sequence',e.event_sequence,'id',e.id,'action',e.action,'event_time',e.event_time,'entity_type',e.entity_type,'entity_id',e.entity_id,'entity_reference',e.entity_reference,
    'actor',jsonb_build_object('user_id',e.actor_user_id,'name',e.actor_name,'roles',e.actor_role_keys),
    'device',jsonb_build_object('id',e.device_id,'name',e.device_name,'code',e.device_code,'app',e.source_app),'location_id',e.location_id,
    'changed_fields',e.changed_fields,'before',case when v_sensitive then e.before_data else null end,'after',case when v_sensitive then e.after_data else null end,
    'reason',e.reason,'approval',jsonb_build_object('request_id',e.approval_request_id,'approved_by',e.approved_by,'approved_at',e.approved_at,'note',e.approval_note),
    'related_entities',e.related_entities,'event_hash',e.event_hash
  ) order by e.event_sequence),'[]'::jsonb) into v_events
  from public.transaction_story_events_v600 e where e.tenant_id=p_tenant_id and e.correlation_id=f.correlation_id;
  return jsonb_build_object('finding',to_jsonb(f),'sensitive_values_visible',v_sensitive,'transaction_story',v_events);
end;
$$;


--
-- Name: audit_finding_review_v600(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_finding_review_v600(p_tenant_id uuid, p_finding_id uuid, p_status text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare f public.audit_findings_v600%rowtype; v_before jsonb; v_resolve boolean;
begin
  if p_status not in ('open','under_review','explained','resolved','escalated','dismissed') then raise exception 'Invalid audit finding status'; end if;
  v_resolve:=p_status in ('resolved','escalated','dismissed');
  if v_resolve then
    if not private.has_permission(p_tenant_id,'audit_center.resolve') then raise exception 'Permission denied' using errcode='42501'; end if;
  elsif not private.has_permission(p_tenant_id,'audit_center.review') then raise exception 'Permission denied' using errcode='42501'; end if;
  select to_jsonb(x) into v_before from public.audit_findings_v600 x where x.tenant_id=p_tenant_id and x.id=p_finding_id;
  if v_before is null then raise exception 'Audit finding not found'; end if;
  update public.audit_findings_v600 set status=p_status,reviewer_id=auth.uid(),reviewed_at=now(),
    review_note=case when v_resolve then review_note else coalesce(nullif(trim(p_note),''),review_note) end,
    resolution_note=case when v_resolve then coalesce(nullif(trim(p_note),''),resolution_note) else resolution_note end
  where tenant_id=p_tenant_id and id=p_finding_id returning * into f;
  perform private.business_audit_write(p_tenant_id,'audit_finding_reviewed','audit_finding',p_finding_id,f.entity_reference,v_before,to_jsonb(f));
  return to_jsonb(f);
end;
$$;


--
-- Name: audit_findings_export_v600(uuid, text, text, timestamp with time zone, timestamp with time zone, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_findings_export_v600(p_tenant_id uuid, p_severity text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_location_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 5000) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_sensitive boolean; v_rows jsonb;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) or not private.has_permission(p_tenant_id,'audit_center.export') then raise exception 'Permission denied' using errcode='42501'; end if;
  v_sensitive:=private.has_permission(p_tenant_id,'audit_history.view_sensitive');
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',f.id,'severity',f.severity,'risk_score',f.risk_score,'rule_code',f.rule_code,'title',f.title,'description',f.description,
    'status',f.status,'detected_at',f.detected_at,'entity_type',f.entity_type,'entity_id',f.entity_id,'entity_reference',f.entity_reference,
    'location_id',f.location_id,'device_id',f.device_id,'actor_user_id',f.actor_user_id,'reviewer_id',f.reviewer_id,'reviewed_at',f.reviewed_at,
    'review_note',f.review_note,'resolution_note',f.resolution_note,
    'evidence',case when v_sensitive then f.evidence else jsonb_build_object('redacted',true,'reason','audit_history.view_sensitive permission required') end
  ) order by f.detected_at desc),'[]'::jsonb) into v_rows
  from (
    select * from public.audit_findings_v600
    where tenant_id=p_tenant_id and (p_severity is null or severity=p_severity) and (p_status is null or status=p_status)
      and (p_from is null or detected_at>=p_from) and (p_to is null or detected_at<=p_to) and (p_location_id is null or location_id=p_location_id)
    order by detected_at desc limit greatest(1,least(coalesce(p_limit,5000),20000))
  ) f;
  return jsonb_build_object('format','thq-audit-export-v600','generated_at',now(),'tenant_id',p_tenant_id,'sensitive_evidence_included',v_sensitive,
    'filters',jsonb_build_object('severity',p_severity,'status',p_status,'from',p_from,'to',p_to,'location_id',p_location_id),'rows',v_rows);
end;
$$;


--
-- Name: audit_findings_list_v600(uuid, text, text, timestamp with time zone, timestamp with time zone, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_findings_list_v600(p_tenant_id uuid, p_severity text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_location_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_result jsonb;
begin
  if not private.has_permission(p_tenant_id,'audit_center.view') then raise exception 'Permission denied' using errcode='42501'; end if;
  select coalesce(jsonb_agg(to_jsonb(q) order by q.detected_at desc),'[]'::jsonb) into v_result
  from (
    select f.id,f.severity,f.risk_score,f.rule_code,f.title,f.description,f.status,f.detected_at,
      f.entity_type,f.entity_id,f.entity_reference,f.location_id,f.device_id,f.actor_user_id,f.reviewer_id,f.reviewed_at,f.review_note,f.resolution_note,
      e.actor_name,e.device_name,e.device_code,e.source_app,e.root_entity_type,e.root_entity_id
    from public.audit_findings_v600 f
    join public.transaction_story_events_v600 e on e.id=f.source_event_id and e.tenant_id=f.tenant_id
    where f.tenant_id=p_tenant_id
      and (p_severity is null or f.severity=p_severity)
      and (p_status is null or f.status=p_status)
      and (p_from is null or f.detected_at>=p_from)
      and (p_to is null or f.detected_at<=p_to)
      and (p_location_id is null or f.location_id=p_location_id)
    order by f.detected_at desc
    limit greatest(1,least(coalesce(p_limit,200),1000))
  ) q;
  return v_result;
end;
$$;


--
-- Name: audit_historical_bootstrap_v600(uuid, date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_historical_bootstrap_v600(p_tenant_id uuid, p_from date DEFAULT NULL::date, p_limit integer DEFAULT 5000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  r record;
  v_from date:=coalesce(p_from,date '2000-01-01');
  v_limit integer:=greatest(1,least(coalesce(p_limit,5000),20000));
  c_sales integer:=0; c_sale_payments integer:=0; c_returns integer:=0;
  c_purchases integer:=0; c_purchase_payments integer:=0; c_purchase_invoices integer:=0; c_supplier_payments integer:=0;
  c_journals integer:=0; c_adjustments integer:=0;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) or not private.has_permission(p_tenant_id,'audit_center.configure') then
    raise exception 'Permission denied' using errcode='42501';
  end if;

  for r in
    select s.id,s.sale_number,s.created_at,s.created_by,to_jsonb(s) row_data,o.location_id,o.device_id
    from public.sales s
    left join lateral (select d.location_id,d.device_id from public.document_origins d where d.tenant_id=s.tenant_id and d.entity_type='sale' and d.entity_id=s.id order by d.created_at asc limit 1) o on true
    where s.tenant_id=p_tenant_id and s.sale_date>=v_from
      and not exists(select 1 from public.transaction_story_events_v600 e where e.tenant_id=s.tenant_id and e.entity_type='sale' and e.entity_id=s.id)
    order by s.created_at limit v_limit
  loop
    perform private.v600_story_write(p_tenant_id,'sale',r.id,r.sale_number,'historical_sale_baseline',r.created_at,r.created_by,r.location_id,r.device_id,null,r.row_data,null,null,'sales','audit_historical_bootstrap_v600',null,'sale',r.id,null,'[]'::jsonb,jsonb_build_object('historical_reconstruction',true,'tracking_quality','baseline_only','no_inferred_edit_history',true)); c_sales:=c_sales+1;
  end loop;

  for r in
    select sp.id,sp.sale_id,sp.paid_at,sp.created_by,to_jsonb(sp) row_data,s.sale_number,o.location_id,o.device_id
    from public.sale_payments sp join public.sales s on s.tenant_id=sp.tenant_id and s.id=sp.sale_id
    left join lateral (select d.location_id,d.device_id from public.document_origins d where d.tenant_id=s.tenant_id and d.entity_type='sale' and d.entity_id=s.id order by d.created_at asc limit 1) o on true
    where sp.tenant_id=p_tenant_id and s.sale_date>=v_from
      and not exists(select 1 from public.transaction_story_events_v600 e where e.tenant_id=sp.tenant_id and e.entity_type='sale_payment' and e.entity_id=sp.id)
    order by sp.paid_at limit v_limit
  loop
    perform private.v600_story_write(p_tenant_id,'sale_payment',r.id,r.sale_number,'historical_payment_baseline',r.paid_at,r.created_by,r.location_id,r.device_id,null,r.row_data,null,null,'payments','audit_historical_bootstrap_v600',null,'sale',r.sale_id,null,jsonb_build_array(jsonb_build_object('type','sale','id',r.sale_id)),jsonb_build_object('historical_reconstruction',true,'tracking_quality','baseline_only','no_inferred_edit_history',true)); c_sale_payments:=c_sale_payments+1;
  end loop;

  for r in
    select sr.id,sr.sale_id,sr.return_number,sr.created_at,sr.created_by,sr.location_id,sr.device_id,to_jsonb(sr) row_data
    from public.sales_returns sr where sr.tenant_id=p_tenant_id and sr.return_date>=v_from
      and not exists(select 1 from public.transaction_story_events_v600 e where e.tenant_id=sr.tenant_id and e.entity_type='sales_return' and e.entity_id=sr.id)
    order by sr.created_at limit v_limit
  loop
    perform private.v600_story_write(p_tenant_id,'sales_return',r.id,r.return_number,'historical_sales_return_baseline',r.created_at,r.created_by,r.location_id,r.device_id,null,r.row_data,r.row_data->>'reason',null,'returns','audit_historical_bootstrap_v600',null,'sale',r.sale_id,null,jsonb_build_array(jsonb_build_object('type','sale','id',r.sale_id)),jsonb_build_object('historical_reconstruction',true,'tracking_quality','baseline_only','no_inferred_edit_history',true)); c_returns:=c_returns+1;
  end loop;

  for r in
    select p.id,p.purchase_number,p.created_at,p.created_by,to_jsonb(p) row_data,o.location_id,o.device_id
    from public.purchases p
    left join lateral (select d.location_id,d.device_id from public.document_origins d where d.tenant_id=p.tenant_id and d.entity_type='purchase' and d.entity_id=p.id order by d.created_at asc limit 1) o on true
    where p.tenant_id=p_tenant_id and p.purchase_date>=v_from
      and not exists(select 1 from public.transaction_story_events_v600 e where e.tenant_id=p.tenant_id and e.entity_type='purchase' and e.entity_id=p.id)
    order by p.created_at limit v_limit
  loop
    perform private.v600_story_write(p_tenant_id,'purchase',r.id,r.purchase_number,'historical_purchase_baseline',r.created_at,r.created_by,r.location_id,r.device_id,null,r.row_data,null,null,'purchases','audit_historical_bootstrap_v600',null,'purchase',r.id,null,'[]'::jsonb,jsonb_build_object('historical_reconstruction',true,'tracking_quality','baseline_only','no_inferred_edit_history',true)); c_purchases:=c_purchases+1;
  end loop;

  for r in
    select pp.id,pp.purchase_id,pp.paid_at,pp.created_by,to_jsonb(pp) row_data,p.purchase_number,o.location_id,o.device_id
    from public.purchase_payments pp join public.purchases p on p.tenant_id=pp.tenant_id and p.id=pp.purchase_id
    left join lateral (select d.location_id,d.device_id from public.document_origins d where d.tenant_id=p.tenant_id and d.entity_type='purchase' and d.entity_id=p.id order by d.created_at asc limit 1) o on true
    where pp.tenant_id=p_tenant_id and p.purchase_date>=v_from
      and not exists(select 1 from public.transaction_story_events_v600 e where e.tenant_id=pp.tenant_id and e.entity_type='purchase_payment' and e.entity_id=pp.id)
    order by pp.paid_at limit v_limit
  loop
    perform private.v600_story_write(p_tenant_id,'purchase_payment',r.id,r.purchase_number,'historical_purchase_payment_baseline',r.paid_at,r.created_by,r.location_id,r.device_id,null,r.row_data,null,null,'payments','audit_historical_bootstrap_v600',null,'purchase',r.purchase_id,null,jsonb_build_array(jsonb_build_object('type','purchase','id',r.purchase_id)),jsonb_build_object('historical_reconstruction',true,'tracking_quality','baseline_only','no_inferred_edit_history',true)); c_purchase_payments:=c_purchase_payments+1;
  end loop;

  for r in
    select pi.id,coalesce(pi.supplier_invoice_number,pi.invoice_number) reference,pi.created_at,pi.created_by,pi.location_id,to_jsonb(pi) row_data
    from public.purchase_invoices_v484 pi where pi.tenant_id=p_tenant_id and pi.invoice_date>=v_from
      and not exists(select 1 from public.transaction_story_events_v600 e where e.tenant_id=pi.tenant_id and e.entity_type='purchase_invoice' and e.entity_id=pi.id)
    order by pi.created_at limit v_limit
  loop
    perform private.v600_story_write(p_tenant_id,'purchase_invoice',r.id,r.reference,'historical_purchase_invoice_baseline',r.created_at,r.created_by,r.location_id,null,null,r.row_data,null,null,'purchase_details','audit_historical_bootstrap_v600',null,'purchase_invoice',r.id,null,'[]'::jsonb,jsonb_build_object('historical_reconstruction',true,'tracking_quality','baseline_only','no_inferred_edit_history',true)); c_purchase_invoices:=c_purchase_invoices+1;
  end loop;

  for r in
    select sp.id,sp.payment_number,sp.payment_date,sp.created_at,sp.created_by,sp.location_id,to_jsonb(sp) row_data
    from public.supplier_payments_v484 sp where sp.tenant_id=p_tenant_id and sp.payment_date>=v_from
      and not exists(select 1 from public.transaction_story_events_v600 e where e.tenant_id=sp.tenant_id and e.entity_type='supplier_payment' and e.entity_id=sp.id)
    order by sp.created_at limit v_limit
  loop
    perform private.v600_story_write(p_tenant_id,'supplier_payment',r.id,r.payment_number,'historical_supplier_payment_baseline',r.created_at,r.created_by,r.location_id,null,null,r.row_data,null,null,'payments','audit_historical_bootstrap_v600',null,'supplier_payment',r.id,null,'[]'::jsonb,jsonb_build_object('historical_reconstruction',true,'tracking_quality','baseline_only','no_inferred_edit_history',true)); c_supplier_payments:=c_supplier_payments+1;
  end loop;

  for r in
    select j.id,j.entry_number,j.created_at,j.created_by,j.location_id,j.source_type,j.source_id,to_jsonb(j) row_data
    from public.journal_entries j where j.tenant_id=p_tenant_id and j.entry_date>=v_from
      and not exists(select 1 from public.transaction_story_events_v600 e where e.tenant_id=j.tenant_id and e.entity_type='journal_entry' and e.entity_id=j.id)
    order by j.created_at limit v_limit
  loop
    perform private.v600_story_write(p_tenant_id,'journal_entry',r.id,r.entry_number,'historical_journal_baseline',r.created_at,r.created_by,r.location_id,null,null,r.row_data,null,null,'accounting','audit_historical_bootstrap_v600',null,coalesce(nullif(r.source_type,''),'journal_entry'),coalesce(r.source_id,r.id),null,case when r.source_id is null then '[]'::jsonb else jsonb_build_array(jsonb_build_object('type',r.source_type,'id',r.source_id)) end,jsonb_build_object('historical_reconstruction',true,'tracking_quality','baseline_only','no_inferred_edit_history',true)); c_journals:=c_journals+1;
  end loop;

  for r in
    select a.id,a.requested_at,a.requested_by,a.location_id,a.device_id,a.approval_request_id,to_jsonb(a) row_data
    from public.stock_adjustment_requests_v500 a where a.tenant_id=p_tenant_id and a.requested_at::date>=v_from
      and not exists(select 1 from public.transaction_story_events_v600 e where e.tenant_id=a.tenant_id and e.entity_type='stock_adjustment' and e.entity_id=a.id)
    order by a.requested_at limit v_limit
  loop
    perform private.v600_story_write(p_tenant_id,'stock_adjustment',r.id,r.row_data->>'request_key','historical_stock_adjustment_baseline',r.requested_at,r.requested_by,r.location_id,r.device_id,null,r.row_data,r.row_data->>'note',r.approval_request_id,'inventory','audit_historical_bootstrap_v600',null,'stock_adjustment',r.id,null,'[]'::jsonb,jsonb_build_object('historical_reconstruction',true,'tracking_quality','baseline_only','no_inferred_edit_history',true)); c_adjustments:=c_adjustments+1;
  end loop;

  perform private.business_audit_write(p_tenant_id,'audit_historical_bootstrap','audit_center',p_tenant_id,'v6.0 historical baseline',null::jsonb,jsonb_build_object('from',v_from,'sales',c_sales,'sale_payments',c_sale_payments,'sales_returns',c_returns,'purchases',c_purchases,'purchase_payments',c_purchase_payments,'purchase_invoices',c_purchase_invoices,'supplier_payments',c_supplier_payments,'journals',c_journals,'stock_adjustments',c_adjustments));
  return jsonb_build_object('from',v_from,'limit_per_type',v_limit,'created',jsonb_build_object('sales',c_sales,'sale_payments',c_sale_payments,'sales_returns',c_returns,'purchases',c_purchases,'purchase_payments',c_purchase_payments,'purchase_invoices',c_purchase_invoices,'supplier_payments',c_supplier_payments,'journals',c_journals,'stock_adjustments',c_adjustments),'rule','Baseline events only reflect records that actually exist. They do not infer historical edits, reasons, approvals or device activity not already recorded.');
end;
$$;


--
-- Name: audit_normal_transactions_v600(uuid, timestamp with time zone, timestamp with time zone, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_normal_transactions_v600(p_tenant_id uuid, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_location_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_result jsonb;
begin
  if not private.has_permission(p_tenant_id,'audit_center.view') then raise exception 'Permission denied' using errcode='42501'; end if;
  select coalesce(jsonb_agg(to_jsonb(q) order by q.last_event_at desc),'[]'::jsonb) into v_result
  from (
    select distinct on (e.correlation_id)
      e.correlation_id,e.root_entity_type,e.root_entity_id,e.entity_reference,e.event_time as last_event_at,e.action as last_action,
      e.actor_user_id,e.actor_name,e.location_id,e.device_id,e.device_name,e.device_code,e.source_app,
      case when coalesce((e.metadata->>'historical_reconstruction')::boolean,false) then 'historical_reconstructed_baseline' else 'native_v600_event' end as evidence_quality
    from public.transaction_story_events_v600 e
    where e.tenant_id=p_tenant_id
      and (p_from is null or e.event_time>=p_from)
      and (p_to is null or e.event_time<=p_to)
      and (p_location_id is null or e.location_id=p_location_id)
      and not exists (
        select 1 from public.audit_findings_v600 f
        where f.tenant_id=e.tenant_id and f.correlation_id=e.correlation_id
          and (p_from is null or f.detected_at>=p_from)
          and (p_to is null or f.detected_at<=p_to)
          and f.status in ('open','under_review','escalated')
      )
    order by e.correlation_id,e.event_sequence desc
    limit greatest(1,least(coalesce(p_limit,200),1000))
  ) q;
  return v_result;
end;
$$;


--
-- Name: audit_risk_config_get_v600(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_risk_config_get_v600(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare c public.audit_risk_config_v600%rowtype;
begin
  if not private.has_permission(p_tenant_id,'audit_center.view') then raise exception 'Permission denied' using errcode='42501'; end if;
  select * into c from public.audit_risk_config_v600 where tenant_id=p_tenant_id;
  return to_jsonb(c)-'updated_by';
end;
$$;


--
-- Name: audit_risk_config_set_v600(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_risk_config_set_v600(p_tenant_id uuid, p_config jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare c public.audit_risk_config_v600%rowtype;
begin
  if not private.has_permission(p_tenant_id,'audit_center.configure') then raise exception 'Permission denied' using errcode='42501'; end if;
  insert into public.audit_risk_config_v600(
    tenant_id,discount_review_pct,discount_high_pct,stock_adjustment_review_value,stock_adjustment_high_value,
    backdate_review_days,backdate_high_days,negative_margin_high,payment_edit_high,posted_purchase_edit_review,manual_journal_review,active,updated_by,updated_at
  ) values (
    p_tenant_id,coalesce((p_config->>'discount_review_pct')::numeric,10),coalesce((p_config->>'discount_high_pct')::numeric,20),
    coalesce((p_config->>'stock_adjustment_review_value')::numeric,10000),coalesce((p_config->>'stock_adjustment_high_value')::numeric,50000),
    coalesce((p_config->>'backdate_review_days')::integer,1),coalesce((p_config->>'backdate_high_days')::integer,7),
    coalesce((p_config->>'negative_margin_high')::boolean,true),coalesce((p_config->>'payment_edit_high')::boolean,true),
    coalesce((p_config->>'posted_purchase_edit_review')::boolean,true),coalesce((p_config->>'manual_journal_review')::boolean,true),coalesce((p_config->>'active')::boolean,true),auth.uid(),now()
  ) on conflict (tenant_id) do update set
    discount_review_pct=excluded.discount_review_pct,discount_high_pct=excluded.discount_high_pct,
    stock_adjustment_review_value=excluded.stock_adjustment_review_value,stock_adjustment_high_value=excluded.stock_adjustment_high_value,
    backdate_review_days=excluded.backdate_review_days,backdate_high_days=excluded.backdate_high_days,
    negative_margin_high=excluded.negative_margin_high,payment_edit_high=excluded.payment_edit_high,
    posted_purchase_edit_review=excluded.posted_purchase_edit_review,manual_journal_review=excluded.manual_journal_review,
    active=excluded.active,updated_by=auth.uid(),updated_at=now() returning * into c;
  perform private.business_audit_write(p_tenant_id,'audit_risk_config_updated','audit_risk_config',p_tenant_id,'v6.0 audit risk thresholds',null::jsonb,to_jsonb(c));
  return to_jsonb(c)-'updated_by';
end;
$$;


--
-- Name: bank_account_save_v500(uuid, uuid, text, text, text, text, uuid, numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_account_save_v500(p_tenant_id uuid, p_bank_account_id uuid, p_account_name text, p_bank_name text, p_account_number_masked text, p_ifsc_code text, p_accounting_account_id uuid, p_opening_balance numeric DEFAULT 0, p_active boolean DEFAULT true) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v uuid;begin perform private.v500_accounting_access(p_tenant_id,true);
  if not exists(select 1 from public.accounting_accounts where id=p_accounting_account_id and tenant_id=p_tenant_id and active and account_type='asset') then raise exception 'Active asset accounting account required';end if;
  if p_bank_account_id is null then insert into public.bank_accounts_v500(tenant_id,account_name,bank_name,account_number_masked,ifsc_code,accounting_account_id,opening_balance,active,created_by) values(p_tenant_id,trim(p_account_name),nullif(trim(coalesce(p_bank_name,'')),''),nullif(trim(coalesce(p_account_number_masked,'')),''),nullif(trim(coalesce(p_ifsc_code,'')),''),p_accounting_account_id,coalesce(p_opening_balance,0),coalesce(p_active,true),auth.uid()) returning id into v;
  else update public.bank_accounts_v500 set account_name=trim(p_account_name),bank_name=nullif(trim(coalesce(p_bank_name,'')),''),account_number_masked=nullif(trim(coalesce(p_account_number_masked,'')),''),ifsc_code=nullif(trim(coalesce(p_ifsc_code,'')),''),accounting_account_id=p_accounting_account_id,opening_balance=coalesce(p_opening_balance,0),active=coalesce(p_active,true),updated_at=now() where id=p_bank_account_id and tenant_id=p_tenant_id returning id into v;end if;
  if v is null then raise exception 'Bank account not found';end if;return v;
end $$;


--
-- Name: bank_accounts_list_v500(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_accounts_list_v500(p_tenant_id uuid) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare r record;begin perform private.v500_accounting_access(p_tenant_id,false);
  for r in select b.*,a.code account_code,a.name accounting_account_name from public.bank_accounts_v500 b join public.accounting_accounts a on a.id=b.accounting_account_id where b.tenant_id=p_tenant_id order by b.active desc,b.account_name loop return next to_jsonb(r);end loop;return;
end $$;


--
-- Name: bank_statement_line_save_v500(uuid, uuid, uuid, date, text, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_statement_line_save_v500(p_tenant_id uuid, p_bank_account_id uuid, p_line_id uuid, p_transaction_date date, p_direction text, p_amount numeric, p_reference text, p_description text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v uuid;begin perform private.v500_accounting_access(p_tenant_id,true);
  if not exists(select 1 from public.bank_accounts_v500 where id=p_bank_account_id and tenant_id=p_tenant_id) then raise exception 'Bank account not found';end if;
  if p_direction not in('debit','credit') or coalesce(p_amount,0)<=0 then raise exception 'Invalid statement transaction';end if;
  if p_line_id is null then insert into public.bank_statement_lines_v500(tenant_id,bank_account_id,transaction_date,direction,amount,reference,description,created_by) values(p_tenant_id,p_bank_account_id,p_transaction_date,p_direction,p_amount,nullif(trim(coalesce(p_reference,'')),''),nullif(trim(coalesce(p_description,'')),''),auth.uid()) returning id into v;
  else update public.bank_statement_lines_v500 set transaction_date=p_transaction_date,direction=p_direction,amount=p_amount,reference=nullif(trim(coalesce(p_reference,'')),''),description=nullif(trim(coalesce(p_description,'')),'') where id=p_line_id and tenant_id=p_tenant_id and status='unmatched' returning id into v;end if;
  if v is null then raise exception 'Unmatched bank statement line not found';end if;return v;
end $$;


--
-- Name: bank_statement_list_v500(uuid, uuid, date, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_statement_list_v500(p_tenant_id uuid, p_bank_account_id uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_status text DEFAULT NULL::text) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare r record;begin perform private.v500_accounting_access(p_tenant_id,false);
  for r in select s.*,j.entry_number,j.description journal_description from public.bank_statement_lines_v500 s left join public.journal_entries j on j.id=s.matched_journal_id where s.tenant_id=p_tenant_id and s.bank_account_id=p_bank_account_id and (p_from is null or s.transaction_date>=p_from) and (p_to is null or s.transaction_date<=p_to) and (p_status is null or s.status=p_status) order by s.transaction_date desc,s.created_at desc loop return next to_jsonb(r);end loop;return;
end $$;


--
-- Name: bank_statement_match_v500(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bank_statement_match_v500(p_tenant_id uuid, p_line_id uuid, p_journal_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare s public.bank_statement_lines_v500%rowtype;v_account uuid;v_net numeric;v_expected numeric;begin perform private.v500_accounting_access(p_tenant_id,true);select * into s from public.bank_statement_lines_v500 where id=p_line_id and tenant_id=p_tenant_id and status='unmatched' for update;if not found then raise exception 'Unmatched bank statement line not found';end if;select accounting_account_id into v_account from public.bank_accounts_v500 where id=s.bank_account_id and tenant_id=p_tenant_id and active;if v_account is null then raise exception 'Active bank account not found';end if;if not exists(select 1 from public.journal_entries where id=p_journal_id and tenant_id=p_tenant_id and status='posted') then raise exception 'Posted journal not found';end if;select round(coalesce(sum(l.debit-l.credit),0),2) into v_net from public.journal_lines l where l.journal_entry_id=p_journal_id and l.account_id=v_account;v_expected:=case when s.direction='credit' then round(s.amount,2) else -round(s.amount,2) end;if v_net<>v_expected then raise exception 'Journal bank movement % does not match statement % %',v_net,s.direction,s.amount;end if;update public.bank_statement_lines_v500 set matched_journal_id=p_journal_id,status='matched',matched_by=auth.uid(),matched_at=now() where id=s.id;end $$;


--
-- Name: business_attention_summary_v480(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_attention_summary_v480(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_low bigint:=0;v_out bigint:=0;v_dead bigint:=0;v_stock numeric:=0;v_recv numeric:=0;v_pay numeric:=0;v_overdue numeric:=0;
  v_pipeline jsonb;v_loans jsonb:='{}'::jsonb;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  select count(*) filter(where status='low_stock'),count(*) filter(where status='out_of_stock'),count(*) filter(where status='dead_stock'),coalesce(sum(stock_value),0)
    into v_low,v_out,v_dead,v_stock from public.inventory_intelligence_v480(p_tenant_id,p_location_id,p_days,'',5000);
  select coalesce(sum(total_outstanding),0),coalesce(sum(days_1_30+days_31_60+days_61_90+days_90_plus),0)
    into v_recv,v_overdue from public.customer_credit_intelligence_v480(p_tenant_id,p_location_id,'',5000);
  select coalesce(sum(total_outstanding),0) into v_pay from public.supplier_payables_intelligence_v480(p_tenant_id,p_location_id,'',5000);
  v_pipeline:=public.operations_pipeline_v489(p_tenant_id,p_location_id);
  if exists(select 1 from public.tenant_modules where tenant_id=p_tenant_id and module_key='loans' and enabled)
     and (private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'loans.view') or private.erp_has_permission(p_tenant_id,'loans.manage')) then
    v_loans:=public.loan_dashboard_v490(p_tenant_id,p_location_id);
  end if;
  return jsonb_build_object(
    'low_stock',v_low,'out_of_stock',v_out,'dead_stock',v_dead,'inventory_value',round(v_stock,2),
    'receivables',round(v_recv,2),'overdue_receivables',round(v_overdue,2),'payables',round(v_pay,2),'days',greatest(1,least(coalesce(p_days,30),365)),
    'loan_total_outstanding',coalesce((v_loans->>'total_outstanding')::numeric,0),
    'loan_overdue_amount',coalesce((v_loans->>'overdue_amount')::numeric,0),
    'loan_overdue_count',coalesce((v_loans->>'overdue_loans')::bigint,0),
    'loan_due_next_7_days',coalesce((v_loans->>'due_next_7_days')::bigint,0),
    'loan_maturing_next_30_days',coalesce((v_loans->>'maturing_next_30_days')::bigint,0),
    'loan_variable_rate_reviews',coalesce((v_loans->>'variable_rate_reviews')::bigint,0)
  )||v_pipeline;
end $$;


--
-- Name: business_audit_log; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.business_audit_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    user_id uuid,
    action text NOT NULL,
    entity_type text NOT NULL,
    entity_id uuid,
    entity_reference text,
    before_data jsonb,
    after_data jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    location_id uuid,
    device_id uuid,
    reason text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL
);


--
-- Name: business_audit_log_list(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_audit_log_list(p_tenant_id uuid, p_limit integer DEFAULT 300) RETURNS SETOF public.business_audit_log
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if not private.erp_has_permission(p_tenant_id,'logs.view') then raise exception 'Permission denied';end if;
  return query select * from public.business_audit_log where tenant_id=p_tenant_id order by created_at desc limit greatest(1,least(coalesce(p_limit,300),2000));
end $$;


--
-- Name: business_backup_export_v4(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_backup_export_v4(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_run uuid:=gen_random_uuid();v jsonb;
begin
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'backup.export') then
    raise exception 'Backup/export permission required';
  end if;

  insert into public.business_export_runs(id,tenant_id,requested_by,status)
  values(v_run,p_tenant_id,auth.uid(),'running');

  v:=jsonb_build_object(
    'format','flexi-erp-v4-complete',
    'exported_at',now(),
    'security_note','Auth passwords/tokens, activation hashes and device secrets are intentionally excluded.',
    'tenant',(select to_jsonb(t) from public.tenants t where t.id=p_tenant_id),
    'tenant_settings',coalesce((select to_jsonb(x) from public.tenant_settings x where x.tenant_id=p_tenant_id),'{}'::jsonb),
    'tenant_settings_v2',coalesce((select to_jsonb(x) from public.tenant_settings_v2 x where x.tenant_id=p_tenant_id),'{}'::jsonb),
    'subscription',coalesce((select to_jsonb(x) from public.tenant_subscriptions x where x.tenant_id=p_tenant_id order by x.created_at desc limit 1),'{}'::jsonb),
    'tenant_modules',coalesce((select jsonb_agg(to_jsonb(x)) from public.tenant_modules x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'locations',coalesce((select jsonb_agg(to_jsonb(x)) from public.business_locations x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'devices',coalesce((select jsonb_agg(to_jsonb(x)-'activation_hash'-'device_secret_hash') from public.business_devices x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'location_user_access',coalesce((select jsonb_agg(to_jsonb(x)) from public.business_user_location_access x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'document_origins',coalesce((select jsonb_agg(to_jsonb(x)) from public.document_origins x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'location_document_numbers',coalesce((select jsonb_agg(to_jsonb(x)) from public.location_document_numbers x where x.tenant_id=p_tenant_id),'[]'::jsonb),

    'products',coalesce((select jsonb_agg(to_jsonb(x)) from public.products x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'variants',coalesce((select jsonb_agg(to_jsonb(x)) from public.product_variants x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'stock_balances',coalesce((select jsonb_agg(to_jsonb(x)) from public.stock_balances x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'stock_movements',coalesce((select jsonb_agg(to_jsonb(x)) from public.stock_movements x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'location_products',coalesce((select jsonb_agg(to_jsonb(x)) from public.location_product_settings x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'location_stock',coalesce((select jsonb_agg(to_jsonb(x)) from public.location_stock_balances x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'location_stock_movements',coalesce((select jsonb_agg(to_jsonb(x)) from public.location_stock_movements x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'stock_transfers',coalesce((select jsonb_agg(to_jsonb(x)) from public.stock_transfers x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'stock_transfer_items',coalesce((select jsonb_agg(to_jsonb(i)) from public.stock_transfer_items i join public.stock_transfers t on t.id=i.transfer_id where t.tenant_id=p_tenant_id),'[]'::jsonb),
    'stock_counts',coalesce((select jsonb_agg(to_jsonb(x)) from public.stock_counts x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'stock_count_items',coalesce((select jsonb_agg(to_jsonb(i)) from public.stock_count_items i join public.stock_counts c on c.id=i.count_id where c.tenant_id=p_tenant_id),'[]'::jsonb),

    'customers',coalesce((select jsonb_agg(to_jsonb(x)) from public.customers x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'suppliers',coalesce((select jsonb_agg(to_jsonb(x)) from public.suppliers x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'sales',coalesce((select jsonb_agg(to_jsonb(x)) from public.sales x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'sale_items',coalesce((select jsonb_agg(to_jsonb(i)) from public.sale_items i join public.sales s on s.id=i.sale_id where s.tenant_id=p_tenant_id),'[]'::jsonb),
    'sale_payments',coalesce((select jsonb_agg(to_jsonb(i)) from public.sale_payments i join public.sales s on s.id=i.sale_id where s.tenant_id=p_tenant_id),'[]'::jsonb),
    'sales_returns',coalesce((select jsonb_agg(to_jsonb(x)) from public.sales_returns x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'sales_return_items',coalesce((select jsonb_agg(to_jsonb(i)) from public.sales_return_items i join public.sales_returns r on r.id=i.sales_return_id where r.tenant_id=p_tenant_id),'[]'::jsonb),
    'purchases',coalesce((select jsonb_agg(to_jsonb(x)) from public.purchases x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'purchase_items',coalesce((select jsonb_agg(to_jsonb(i)) from public.purchase_items i join public.purchases p on p.id=i.purchase_id where p.tenant_id=p_tenant_id),'[]'::jsonb),
    'purchase_payments',coalesce((select jsonb_agg(to_jsonb(i)) from public.purchase_payments i join public.purchases p on p.id=i.purchase_id where p.tenant_id=p_tenant_id),'[]'::jsonb),
    'purchase_returns',coalesce((select jsonb_agg(to_jsonb(x)) from public.purchase_returns x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'purchase_return_items',coalesce((select jsonb_agg(to_jsonb(i)) from public.purchase_return_items i join public.purchase_returns r on r.id=i.purchase_return_id where r.tenant_id=p_tenant_id),'[]'::jsonb),
    'transaction_corrections',coalesce((select jsonb_agg(to_jsonb(x)) from public.transaction_corrections x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'expenses',coalesce((select jsonb_agg(to_jsonb(x)) from public.expenses x where x.tenant_id=p_tenant_id),'[]'::jsonb),

    'cashier_shifts',coalesce((select jsonb_agg(to_jsonb(x)) from public.cashier_shifts x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'cash_drawer_movements',coalesce((select jsonb_agg(to_jsonb(x)) from public.cash_drawer_movements x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'accounts',coalesce((select jsonb_agg(to_jsonb(x)) from public.accounting_accounts x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'account_mappings',coalesce((select jsonb_agg(to_jsonb(x)) from public.accounting_account_mappings x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'journals',coalesce((select jsonb_agg(to_jsonb(x)) from public.journal_entries x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'journal_lines',coalesce((select jsonb_agg(to_jsonb(l)) from public.journal_lines l join public.journal_entries j on j.id=l.journal_entry_id where j.tenant_id=p_tenant_id),'[]'::jsonb),

    'tenant_invoice_templates',coalesce((select jsonb_agg(to_jsonb(x)) from public.tenant_invoice_templates x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'printer_profiles',coalesce((select jsonb_agg(to_jsonb(x)) from public.printer_profiles x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'invoice_print_events',coalesce((select jsonb_agg(to_jsonb(x)) from public.invoice_print_events x where x.tenant_id=p_tenant_id),'[]'::jsonb),

    'notifications',coalesce((select jsonb_agg(to_jsonb(x)) from public.notifications x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'tasks',coalesce((select jsonb_agg(to_jsonb(x)) from public.business_tasks x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'attachments',coalesce((select jsonb_agg(to_jsonb(x)) from public.entity_attachments x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'approval_rules',coalesce((select jsonb_agg(to_jsonb(x)) from public.approval_rules x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'approval_requests',coalesce((select jsonb_agg(to_jsonb(x)) from public.approval_requests x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'custom_fields',coalesce((select jsonb_agg(to_jsonb(x)) from public.custom_field_definitions x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'custom_field_values',coalesce((select jsonb_agg(to_jsonb(x)) from public.custom_field_values x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'audit',coalesce((select jsonb_agg(to_jsonb(x)) from public.business_audit_log x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'support_tickets',coalesce((select jsonb_agg(to_jsonb(x)) from public.support_tickets x where x.tenant_id=p_tenant_id),'[]'::jsonb),

    'production_recipes',coalesce((select jsonb_agg(to_jsonb(x)) from public.production_recipes x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'production_runs',coalesce((select jsonb_agg(to_jsonb(x)) from public.production_runs x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'production_boms',coalesce((select jsonb_agg(to_jsonb(x)) from public.production_boms x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'production_material_reservations',coalesce((select jsonb_agg(to_jsonb(x)) from public.production_material_reservations x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'service_vehicles',coalesce((select jsonb_agg(to_jsonb(x)) from public.service_vehicles x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'service_jobs',coalesce((select jsonb_agg(to_jsonb(x)) from public.service_jobs x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'restaurant_tables',coalesce((select jsonb_agg(to_jsonb(x)) from public.restaurant_tables x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'restaurant_orders',coalesce((select jsonb_agg(to_jsonb(x)) from public.restaurant_orders x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'restaurant_kots',coalesce((select jsonb_agg(to_jsonb(x)) from public.restaurant_kots x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'workshop_vehicles',coalesce((select jsonb_agg(to_jsonb(x)) from public.workshop_vehicles x where x.tenant_id=p_tenant_id),'[]'::jsonb),
    'workshop_job_cards',coalesce((select jsonb_agg(to_jsonb(x)) from public.workshop_job_cards x where x.tenant_id=p_tenant_id),'[]'::jsonb)
  );

  update public.business_export_runs
  set status='completed',completed_at=now(),record_counts=jsonb_build_object(
    'products',jsonb_array_length(v->'products'),
    'customers',jsonb_array_length(v->'customers'),
    'suppliers',jsonb_array_length(v->'suppliers'),
    'sales',jsonb_array_length(v->'sales'),
    'purchases',jsonb_array_length(v->'purchases'),
    'expenses',jsonb_array_length(v->'expenses'),
    'journals',jsonb_array_length(v->'journals'),
    'stock_movements',jsonb_array_length(v->'location_stock_movements')
  ) where id=v_run;

  return jsonb_build_object('run_id',v_run,'backup',v);
exception when others then
  update public.business_export_runs set status='failed',notes=sqlerrm where id=v_run;
  raise;
end $$;


--
-- Name: business_location_tree_v42(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_location_tree_v42(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_all boolean; v_result jsonb;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  v_all:=private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'locations.view_all') or private.erp_has_permission(p_tenant_id,'locations.manage_all');

  with recursive tree as (
    select l.id,l.tenant_id,l.parent_location_id,l.location_code,l.tracking_code,l.name,l.location_type,l.hierarchy_role,
           l.sort_order,l.active,0 depth,array[l.id] path_ids,array[l.name::text] path_names,
           array[lpad(l.sort_order::text,10,'0')||':'||lower(l.name)] path_sort
    from public.business_locations l
    where l.tenant_id=p_tenant_id and l.parent_location_id is null
    union all
    select c.id,c.tenant_id,c.parent_location_id,c.location_code,c.tracking_code,c.name,c.location_type,c.hierarchy_role,
           c.sort_order,c.active,t.depth+1,t.path_ids||c.id,t.path_names||c.name::text,
           t.path_sort||(lpad(c.sort_order::text,10,'0')||':'||lower(c.name))
    from public.business_locations c join tree t on c.parent_location_id=t.id
    where c.tenant_id=p_tenant_id and not c.id=any(t.path_ids)
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',t.id,'parent_location_id',t.parent_location_id,'code',t.location_code,'tracking_code',t.tracking_code,
    'name',t.name,'type',t.location_type,'hierarchy_role',t.hierarchy_role,'sort_order',t.sort_order,'active',t.active,
    'depth',t.depth,'path',array_to_string(t.path_names,' / '),
    'access_level',case when v_all then 'manage' else a.access_level end,
    'device_count',(select count(*) from public.business_devices d where d.location_id=t.id and d.status<>'revoked')
  ) order by t.path_sort),'[]'::jsonb)
  into v_result
  from tree t
  left join public.business_user_location_access a
    on a.tenant_id=p_tenant_id and a.user_id=auth.uid() and a.location_id=t.id
  where v_all or a.user_id is not null;
  return coalesce(v_result,'[]'::jsonb);
end $$;


--
-- Name: business_locations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.business_locations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    parent_location_id uuid,
    location_code text NOT NULL,
    tracking_code text,
    name text NOT NULL,
    location_type text DEFAULT 'branch'::text NOT NULL,
    phone text,
    email text,
    gstin text,
    address_line1 text,
    address_line2 text,
    city text,
    state text,
    postal_code text,
    country text DEFAULT 'India'::text NOT NULL,
    invoice_prefix text,
    inventory_location_id uuid,
    active boolean DEFAULT true NOT NULL,
    settings jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    hierarchy_role text DEFAULT 'child_store'::text NOT NULL,
    sort_order integer DEFAULT 100 NOT NULL,
    CONSTRAINT business_locations_hierarchy_role_check CHECK ((hierarchy_role = ANY (ARRAY['main_store'::text, 'child_store'::text, 'warehouse'::text, 'operational'::text]))),
    CONSTRAINT business_locations_location_type_v481_check CHECK ((location_type = ANY (ARRAY['head_office'::text, 'branch'::text, 'store'::text, 'warehouse'::text, 'production'::text, 'office'::text, 'scrap'::text, 'restaurant'::text, 'kitchen'::text, 'service_base'::text])))
);


--
-- Name: business_locations_list(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_locations_list(p_tenant_id uuid) RETURNS SETOF public.business_locations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  return query select * from public.business_locations where tenant_id=p_tenant_id and active order by name;
end $$;


--
-- Name: business_task_comment_add_v500(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_task_comment_add_v500(p_tenant_id uuid, p_task_id uuid, p_comment text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v uuid;begin if not private.v500_task_visible(p_tenant_id,p_task_id) then raise exception 'Task not found or access denied';end if;if trim(coalesce(p_comment,''))='' then raise exception 'Comment is required';end if;insert into public.business_task_comments_v500(tenant_id,task_id,comment,created_by) values(p_tenant_id,p_task_id,trim(p_comment),auth.uid()) returning id into v;insert into public.business_task_history_v500(tenant_id,task_id,event_type,note,changed_by) values(p_tenant_id,p_task_id,'comment',trim(p_comment),auth.uid());return v;end $$;


--
-- Name: business_task_escalation_set_v500(uuid, uuid, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_task_escalation_set_v500(p_tenant_id uuid, p_task_id uuid, p_escalation_at timestamp with time zone, p_escalation_user_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$begin if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'tasks.manage') then raise exception 'Task permission required';end if;if p_escalation_user_id is not null and not exists(select 1 from public.tenant_memberships where tenant_id=p_tenant_id and user_id=p_escalation_user_id and status='active') then raise exception 'Escalation user is not an active business member';end if;update public.business_tasks set escalation_at=p_escalation_at,escalation_user_id=p_escalation_user_id,escalated_at=null,updated_at=now() where id=p_task_id and tenant_id=p_tenant_id;if not found then raise exception 'Task not found';end if;end $$;


--
-- Name: business_task_from_notification_v495(uuid, uuid, uuid, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_task_from_notification_v495(p_tenant_id uuid, p_notification_id uuid, p_assigned_to uuid DEFAULT NULL::uuid, p_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_priority text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare n public.notifications%rowtype; v_existing uuid; v_due timestamptz; v_priority text;
begin
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'tasks.manage') then raise exception 'Task permission required';end if;
  select * into n from public.notifications where id=p_notification_id and tenant_id=p_tenant_id and (user_id is null or user_id=auth.uid());
  if n.id is null then raise exception 'Notification not found';end if;
  select id into v_existing from public.business_tasks where tenant_id=p_tenant_id and source_notification_id=p_notification_id and status not in('done','cancelled') order by created_at desc limit 1;
  if v_existing is not null then return v_existing;end if;
  v_due:=coalesce(p_due_at,now()+case when n.severity='critical' then interval '4 hours' when n.severity='warning' then interval '1 day' else interval '3 days' end);
  v_priority:=coalesce(nullif(p_priority,''),case when n.severity='critical' then 'urgent' when n.severity='warning' then 'high' else 'normal' end);
  return public.business_task_save_v495(
    p_tenant_id,null,n.location_id,n.title,n.message,v_priority,'open',coalesce(p_assigned_to,auth.uid()),v_due,
    greatest(now(),v_due-interval '4 hours'),n.entity_type,n.entity_id,n.id,jsonb_build_object('notification_category',n.category,'notification_severity',n.severity)
  );
end $$;


--
-- Name: business_task_save_v4(uuid, uuid, uuid, text, text, text, text, uuid, timestamp with time zone, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_task_save_v4(p_tenant_id uuid, p_task_id uuid, p_location_id uuid, p_title text, p_description text, p_priority text, p_status text, p_assigned_to uuid, p_due_at timestamp with time zone, p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_id uuid; begin
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'tasks.manage') then raise exception 'Task permission required';end if;
  if p_location_id is not null then perform private.v4_location_access(p_tenant_id,p_location_id,'operate');end if;
  if trim(coalesce(p_title,''))='' then raise exception 'Task title required';end if;
  if p_task_id is null then
    insert into public.business_tasks(tenant_id,location_id,title,description,priority,status,assigned_to,due_at,entity_type,entity_id,created_by)
    values(p_tenant_id,p_location_id,trim(p_title),nullif(trim(coalesce(p_description,'')),''),coalesce(nullif(p_priority,''),'normal'),coalesce(nullif(p_status,''),'open'),p_assigned_to,p_due_at,nullif(trim(coalesce(p_entity_type,'')),''),p_entity_id,auth.uid()) returning id into v_id;
  else
    update public.business_tasks set location_id=p_location_id,title=trim(p_title),description=nullif(trim(coalesce(p_description,'')),''),priority=coalesce(nullif(p_priority,''),'normal'),status=coalesce(nullif(p_status,''),'open'),assigned_to=p_assigned_to,due_at=p_due_at,entity_type=nullif(trim(coalesce(p_entity_type,'')),''),entity_id=p_entity_id,completed_at=case when p_status='done' then coalesce(completed_at,now()) else null end
    where id=p_task_id and tenant_id=p_tenant_id returning id into v_id;
  end if;
  if v_id is null then raise exception 'Task not found';end if;
  return v_id;
end $$;


--
-- Name: business_task_save_v495(uuid, uuid, uuid, text, text, text, text, uuid, timestamp with time zone, timestamp with time zone, text, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_task_save_v495(p_tenant_id uuid, p_task_id uuid, p_location_id uuid, p_title text, p_description text, p_priority text, p_status text, p_assigned_to uuid, p_due_at timestamp with time zone, p_reminder_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid, p_source_notification_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_id uuid; v_assigned uuid; v_old_status text;
begin
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'tasks.manage') then raise exception 'Task permission required';end if;
  if p_location_id is not null then perform private.v4_location_access(p_tenant_id,p_location_id,'operate');end if;
  if trim(coalesce(p_title,''))='' then raise exception 'Task title required';end if;
  if coalesce(p_priority,'normal') not in('low','normal','high','urgent') then raise exception 'Invalid task priority';end if;
  if coalesce(p_status,'open') not in('open','in_progress','done','cancelled') then raise exception 'Invalid task status';end if;
  if p_due_at is not null and p_reminder_at is not null and p_reminder_at>p_due_at then raise exception 'Reminder cannot be after the task due time';end if;
  if p_assigned_to is not null and not exists(
    select 1 from public.tenant_memberships m where m.tenant_id=p_tenant_id and m.user_id=p_assigned_to and m.status='active'
  ) then raise exception 'Assigned user is not an active member of this business';end if;

  if p_task_id is null then
    insert into public.business_tasks(
      tenant_id,location_id,title,description,priority,status,assigned_to,due_at,reminder_at,entity_type,entity_id,
      source_notification_id,metadata,created_by,updated_at
    ) values(
      p_tenant_id,p_location_id,trim(p_title),nullif(trim(coalesce(p_description,'')),''),coalesce(nullif(p_priority,''),'normal'),
      coalesce(nullif(p_status,''),'open'),p_assigned_to,p_due_at,p_reminder_at,nullif(trim(coalesce(p_entity_type,'')),''),p_entity_id,
      p_source_notification_id,coalesce(p_metadata,'{}'::jsonb),auth.uid(),now()
    ) returning id,assigned_to into v_id,v_assigned;
  else
    select status into v_old_status from public.business_tasks where id=p_task_id and tenant_id=p_tenant_id;
    update public.business_tasks set
      location_id=p_location_id,title=trim(p_title),description=nullif(trim(coalesce(p_description,'')),''),
      priority=coalesce(nullif(p_priority,''),'normal'),status=coalesce(nullif(p_status,''),'open'),assigned_to=p_assigned_to,
      due_at=p_due_at,reminder_at=p_reminder_at,entity_type=nullif(trim(coalesce(p_entity_type,'')),''),entity_id=p_entity_id,
      source_notification_id=coalesce(p_source_notification_id,source_notification_id),metadata=coalesce(p_metadata,metadata),updated_at=now(),
      completed_at=case when p_status='done' then coalesce(completed_at,now()) else null end
    where id=p_task_id and tenant_id=p_tenant_id returning id,assigned_to into v_id,v_assigned;
  end if;
  if v_id is null then raise exception 'Task not found';end if;

  if coalesce(p_status,'open') not in('done','cancelled') and v_assigned is not null then
    if not exists(select 1 from public.notifications n where n.tenant_id=p_tenant_id and n.user_id=v_assigned and n.category='task' and n.entity_type='task' and n.entity_id=v_id and n.read_at is null and n.created_at>now()-interval '15 minutes') then
      insert into public.notifications(tenant_id,user_id,location_id,category,severity,title,message,entity_type,entity_id)
      values(p_tenant_id,v_assigned,p_location_id,'task',case p_priority when 'urgent' then 'critical' when 'high' then 'warning' else 'info' end,
        case when p_task_id is null then 'Task assigned' else 'Task updated' end||' • '||trim(p_title),
        coalesce(nullif(trim(coalesce(p_description,'')),''),'Task requires attention')||case when p_due_at is null then '' else ' • Due '||p_due_at::text end,'task',v_id);
    end if;
  end if;

  if p_task_id is not null and v_old_status is distinct from p_status and p_status in('done','cancelled') then
    insert into public.notifications(tenant_id,user_id,location_id,category,severity,title,message,entity_type,entity_id)
    values(p_tenant_id,auth.uid(),p_location_id,'task','success','Task '||replace(p_status,'_',' ')||' • '||trim(p_title),'Task status changed to '||p_status,'task',v_id);
  end if;
  return v_id;
end $$;


--
-- Name: business_task_timeline_v500(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_task_timeline_v500(p_tenant_id uuid, p_task_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare h jsonb;c jsonb;t jsonb;begin if not private.v500_task_visible(p_tenant_id,p_task_id) then raise exception 'Task not found or access denied';end if;select to_jsonb(x) into t from public.business_tasks x where x.id=p_task_id and x.tenant_id=p_tenant_id;select coalesce(jsonb_agg(to_jsonb(x) order by x.changed_at desc),'[]'::jsonb) into h from public.business_task_history_v500 x where x.tenant_id=p_tenant_id and x.task_id=p_task_id;select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'comment',x.comment,'created_by',x.created_by,'created_at',x.created_at) order by x.created_at desc),'[]'::jsonb) into c from public.business_task_comments_v500 x where x.tenant_id=p_tenant_id and x.task_id=p_task_id;return jsonb_build_object('task',t,'history',h,'comments',c);end $$;


--
-- Name: business_tasks_list_v4(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_tasks_list_v4(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text) RETURNS TABLE(id uuid, title text, description text, priority text, status text, assigned_to uuid, assigned_username text, due_at timestamp with time zone, location_id uuid, location_code text, entity_type text, entity_id uuid, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  return query
  select t.id,t.title,t.description,t.priority,t.status,t.assigned_to,coalesce(u.username,''),t.due_at,t.location_id,coalesce(l.location_code,''),t.entity_type,t.entity_id,t.created_at
  from public.business_tasks t
  left join public.user_login_names u on u.user_id=t.assigned_to
  left join public.business_locations l on l.id=t.location_id
  where t.tenant_id=p_tenant_id
    and (p_location_id is null or t.location_id=p_location_id)
    and (p_status is null or p_status='' or t.status=p_status)
    and (t.location_id is null or private.erp_user_location_allowed(p_tenant_id,t.location_id,'view') or private.erp_user_is_owner(p_tenant_id))
  order by case t.priority when 'urgent' then 1 when 'high' then 2 when 'normal' then 3 else 4 end,coalesce(t.due_at,'infinity'::timestamptz),t.created_at desc;
end $$;


--
-- Name: business_tasks_list_v495(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_tasks_list_v495(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text) RETURNS TABLE(id uuid, title text, description text, priority text, status text, assigned_to uuid, assigned_username text, due_at timestamp with time zone, reminder_at timestamp with time zone, location_id uuid, location_code text, entity_type text, entity_id uuid, source_notification_id uuid, metadata jsonb, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  return query
  select t.id,t.title::text,t.description::text,t.priority::text,t.status::text,t.assigned_to,coalesce(u.username::text,''::text),
    t.due_at,t.reminder_at,t.location_id,coalesce(l.location_code::text,''::text),t.entity_type::text,t.entity_id,
    t.source_notification_id,coalesce(t.metadata,'{}'::jsonb),t.created_at,t.updated_at
  from public.business_tasks t
  left join public.user_login_names u on u.user_id=t.assigned_to
  left join public.business_locations l on l.id=t.location_id
  where t.tenant_id=p_tenant_id
    and (p_location_id is null or t.location_id=p_location_id)
    and (p_status is null or p_status='' or t.status=p_status)
    and (t.location_id is null or private.erp_user_location_allowed(p_tenant_id,t.location_id,'view') or private.erp_user_is_owner(p_tenant_id))
    and (t.assigned_to is null or t.assigned_to=auth.uid() or private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'tasks.manage'))
  order by case when t.status in('done','cancelled') then 1 else 0 end,case when t.due_at is not null and t.due_at<now() and t.status not in('done','cancelled') then 0 else 1 end,case t.priority when 'urgent' then 1 when 'high' then 2 when 'normal' then 3 else 4 end,coalesce(t.due_at,'infinity'::timestamptz),t.created_at desc;
end $$;


--
-- Name: business_tasks_list_v500(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_tasks_list_v500(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare r record;begin if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;for r in select t.id,t.title,t.description,t.priority,t.status,t.assigned_to,coalesce(u.username::text,'') assigned_username,t.due_at,t.reminder_at,t.location_id,coalesce(l.location_code,'') location_code,t.entity_type,t.entity_id,t.source_notification_id,coalesce(t.metadata,'{}'::jsonb) metadata,t.escalation_at,t.escalated_at,t.escalation_user_id,coalesce(eu.username::text,'') escalation_username,t.created_at,t.updated_at from public.business_tasks t left join public.user_login_names u on u.user_id=t.assigned_to left join public.user_login_names eu on eu.user_id=t.escalation_user_id left join public.business_locations l on l.id=t.location_id where t.tenant_id=p_tenant_id and (p_location_id is null or t.location_id=p_location_id) and (p_status is null or p_status='' or t.status=p_status) and private.v500_task_visible(p_tenant_id,t.id) order by case when t.status in('done','cancelled') then 1 else 0 end,case when t.due_at is not null and t.due_at<now() and t.status not in('done','cancelled') then 0 else 1 end,case t.priority when 'urgent' then 1 when 'high' then 2 when 'normal' then 3 else 4 end,coalesce(t.due_at,'infinity'::timestamptz),t.created_at desc loop return next to_jsonb(r);end loop;return;end $$;


--
-- Name: cashier_shift_cash_move_v4(uuid, uuid, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cashier_shift_cash_move_v4(p_tenant_id uuid, p_shift_id uuid, p_type text, p_amount numeric, p_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v public.cashier_shifts%rowtype;begin
  select * into v from public.cashier_shifts where id=p_shift_id and tenant_id=p_tenant_id and status='open';if not found then raise exception 'Open shift not found';end if;
  if v.user_id<>auth.uid() and not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'pos.shift_manage') then raise exception 'Shift access denied';end if;
  if p_type not in('cash_in','cash_out') then raise exception 'Invalid cash movement';end if;if coalesce(p_amount,0)<=0 then raise exception 'Amount must be positive';end if;
  insert into public.cash_drawer_movements(tenant_id,shift_id,movement_type,amount,note,created_by) values(p_tenant_id,p_shift_id,p_type,case when p_type='cash_out' then -abs(p_amount) else abs(p_amount) end,nullif(trim(coalesce(p_note,'')),''),auth.uid());
end $$;


--
-- Name: cashier_shift_close_v4(uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cashier_shift_close_v4(p_tenant_id uuid, p_shift_id uuid, p_declared_cash numeric, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v public.cashier_shifts%rowtype;v_expected numeric;v_diff numeric;begin
  select * into v from public.cashier_shifts where id=p_shift_id and tenant_id=p_tenant_id and status='open' for update;if not found then raise exception 'Open shift not found';end if;
  if v.user_id<>auth.uid() and not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'pos.shift_manage') then raise exception 'Shift access denied';end if;
  select coalesce(sum(amount),0) into v_expected from public.cash_drawer_movements where shift_id=p_shift_id;v_diff:=coalesce(p_declared_cash,0)-v_expected;
  update public.cashier_shifts set status='closed',closed_at=now(),expected_cash=v_expected,declared_cash=coalesce(p_declared_cash,0),difference=v_diff,closing_note=nullif(trim(coalesce(p_note,'')),'') where id=p_shift_id;
  return jsonb_build_object('shift_id',p_shift_id,'expected_cash',v_expected,'declared_cash',coalesce(p_declared_cash,0),'difference',v_diff,'status','closed');
end $$;


--
-- Name: cashier_shift_close_v47(uuid, uuid, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cashier_shift_close_v47(p_tenant_id uuid, p_shift_id uuid, p_declared_cash numeric, p_note text, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v jsonb;begin v:=private.v47_request_existing(p_tenant_id,p_request_id,'shift.close');if v is not null then return v;end if;v:=public.cashier_shift_close_v4(p_tenant_id,p_shift_id,p_declared_cash,p_note);return private.v47_request_complete(p_tenant_id,p_request_id,'shift.close',v);end$$;


--
-- Name: cashier_shift_close_v472(uuid, uuid, numeric, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cashier_shift_close_v472(p_tenant_id uuid, p_shift_id uuid, p_declared_cash numeric, p_closed_at timestamp with time zone, p_note text, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_existing jsonb;
  v public.cashier_shifts%rowtype;
  v_closed timestamptz:=coalesce(p_closed_at,now());
  v_expected numeric;
  v_declared numeric:=greatest(coalesce(p_declared_cash,0),0);
  v_diff numeric;
begin
  v_existing:=private.v47_request_existing(p_tenant_id,p_request_id,'shift.close.v472');
  if v_existing is not null then return v_existing;end if;

  select s.* into v from public.cashier_shifts s
  where s.id=p_shift_id and s.tenant_id=p_tenant_id and s.status='open' for update;
  if not found then raise exception 'Open shift not found';end if;
  if v.user_id<>auth.uid() and not private.erp_user_is_owner(p_tenant_id)
     and not private.erp_has_permission(p_tenant_id,'pos.shift_manage') then raise exception 'Shift access denied';end if;
  if v_closed<v.opened_at then raise exception 'Shift end time cannot be before shift start time';end if;
  if v_closed>now()+interval '5 minutes' then raise exception 'Shift end time cannot be in the future';end if;
  if private.v472_shift_period_conflicts(v.device_id,v.id,v.opened_at,v_closed) then
    raise exception 'Shift end time overlaps another shift on this terminal';
  end if;

  v_expected:=private.v472_shift_expected_cash(v.id);
  v_diff:=v_declared-v_expected;
  update public.cashier_shifts set
    status='closed',closed_at=v_closed,expected_cash=v_expected,declared_cash=v_declared,
    difference=v_diff,closing_note=nullif(trim(coalesce(p_note,'')),'')
  where cashier_shifts.id=v.id;

  return private.v47_request_complete(
    p_tenant_id,p_request_id,'shift.close.v472',
    jsonb_build_object(
      'shift_id',v.id,'shift_number',v.shift_number,'status','closed',
      'opened_at',v.opened_at,'closed_at',v_closed,
      'opening_cash',v.opening_cash,'expected_cash',v_expected,
      'declared_cash',v_declared,'difference',v_diff
    )
  );
end $$;


--
-- Name: cashier_shift_current_v4(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cashier_shift_current_v4(p_tenant_id uuid, p_device_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
select coalesce((
  select to_jsonb(s) || jsonb_build_object(
    'cash_movement_total',coalesce(sum(m.amount),0),
    'expected_cash',coalesce(sum(m.amount),0),
    'cash_sales',coalesce(sum(case when m.movement_type='sale' then m.amount else 0 end),0),
    'customer_receipts',coalesce(sum(case when m.movement_type='receipt' then m.amount else 0 end),0),
    'cash_in',coalesce(sum(case when m.movement_type='cash_in' then m.amount else 0 end),0),
    'cash_out',abs(coalesce(sum(case when m.movement_type='cash_out' then m.amount else 0 end),0)),
    'cash_expenses',abs(coalesce(sum(case when m.movement_type='expense' then m.amount else 0 end),0)),
    'refunds',abs(coalesce(sum(case when m.movement_type='refund' then m.amount else 0 end),0))
  )
  from public.cashier_shifts s left join public.cash_drawer_movements m on m.shift_id=s.id
  where s.tenant_id=p_tenant_id and s.device_id=p_device_id and s.status='open'
  group by s.id limit 1
),'{}'::jsonb)
$$;


--
-- Name: cashier_shift_current_v472(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cashier_shift_current_v472(p_tenant_id uuid, p_device_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_location uuid;v_result jsonb;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  select d.location_id into v_location from public.business_devices d
  where d.id=p_device_id and d.tenant_id=p_tenant_id and d.status='active';
  if v_location is null then raise exception 'Active terminal not found';end if;
  if not private.erp_user_is_owner(p_tenant_id)
     and not private.erp_user_location_allowed(p_tenant_id,v_location,'view') then raise exception 'Terminal access denied';end if;

  select coalesce(to_jsonb(x),'{}'::jsonb) into v_result from (
    select s.*,
      coalesce(ul.username,'')::text cashier_name,
      coalesce(sum(m.amount),0)::numeric cash_movement_total,
      coalesce(sum(m.amount),0)::numeric expected_cash_now,
      coalesce(sum(case when m.movement_type='sale' then m.amount else 0 end),0)::numeric cash_sales,
      coalesce(sum(case when m.movement_type='receipt' then m.amount else 0 end),0)::numeric customer_receipts,
      coalesce(sum(case when m.movement_type='cash_in' then m.amount else 0 end),0)::numeric cash_in,
      abs(coalesce(sum(case when m.movement_type='cash_out' then m.amount else 0 end),0))::numeric cash_out,
      abs(coalesce(sum(case when m.movement_type='expense' then m.amount else 0 end),0))::numeric cash_expenses,
      abs(coalesce(sum(case when m.movement_type='refund' then m.amount else 0 end),0))::numeric refunds
    from public.cashier_shifts s
    left join public.cash_drawer_movements m on m.shift_id=s.id
    left join public.user_login_names ul on ul.user_id=s.user_id
    where s.tenant_id=p_tenant_id and s.device_id=p_device_id and s.status='open'
    group by s.id,ul.username
    order by s.opened_at desc limit 1
  ) x;
  return coalesce(v_result,'{}'::jsonb);
end $$;


--
-- Name: cashier_shift_edit_v472(uuid, uuid, timestamp with time zone, numeric, timestamp with time zone, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cashier_shift_edit_v472(p_tenant_id uuid, p_shift_id uuid, p_opened_at timestamp with time zone, p_opening_cash numeric, p_closed_at timestamp with time zone, p_declared_cash numeric, p_note text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v public.cashier_shifts%rowtype;
  v_before jsonb;
  v_after jsonb;
  v_opened timestamptz;
  v_closed timestamptz;
  v_opening numeric;
  v_declared numeric;
  v_expected numeric;
  v_reason text:=nullif(trim(coalesce(p_reason,'')),'');
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if v_reason is null then raise exception 'Edit reason is required';end if;
  select s.* into v from public.cashier_shifts s where s.id=p_shift_id and s.tenant_id=p_tenant_id for update;
  if not found then raise exception 'Shift not found';end if;

  if v.status='open' and v.user_id=auth.uid() then
    null;
  elsif not private.erp_user_is_owner(p_tenant_id)
        and not private.erp_has_permission(p_tenant_id,'pos.shift_manage') then
    raise exception 'Owner or Shift Manage permission is required to edit this shift';
  end if;

  v_opened:=coalesce(p_opened_at,v.opened_at);
  v_opening:=greatest(coalesce(p_opening_cash,v.opening_cash,0),0);
  if v_opened>now()+interval '5 minutes' then raise exception 'Shift start time cannot be in the future';end if;
  if v.status='open' then
    v_closed:=null;
    v_declared:=null;
  else
    v_closed:=coalesce(p_closed_at,v.closed_at);
    v_declared:=greatest(coalesce(p_declared_cash,v.declared_cash,0),0);
    if v_closed is null then raise exception 'Closed shift requires an end time';end if;
    if v_closed<v_opened then raise exception 'Shift end time cannot be before shift start time';end if;
    if v_closed>now()+interval '5 minutes' then raise exception 'Shift end time cannot be in the future';end if;
  end if;

  if private.v472_shift_period_conflicts(v.device_id,v.id,v_opened,v_closed) then
    raise exception 'Edited shift time overlaps another shift on this terminal';
  end if;

  v_before:=to_jsonb(v);
  update public.cashier_shifts set
    opened_at=v_opened,
    opening_cash=v_opening,
    closed_at=v_closed,
    declared_cash=v_declared,
    closing_note=case when v.status='closed' then nullif(trim(coalesce(p_note,closing_note,'')),'') else closing_note end,
    last_edited_by=auth.uid(),
    last_edited_at=now(),
    edit_count=coalesce(edit_count,0)+1
  where cashier_shifts.id=v.id;

  update public.cash_drawer_movements set amount=v_opening,created_at=v_opened
  where shift_id=v.id and movement_type='opening';
  if not found then
    insert into public.cash_drawer_movements(
      tenant_id,shift_id,movement_type,amount,note,created_by,created_at
    ) values(p_tenant_id,v.id,'opening',v_opening,'Opening cash (recreated by shift correction)',auth.uid(),v_opened);
  end if;

  v_expected:=private.v472_shift_expected_cash(v.id);
  if v.status='closed' then
    update public.cashier_shifts set expected_cash=v_expected,difference=v_declared-v_expected where cashier_shifts.id=v.id;
  end if;

  select to_jsonb(s) into v_after from public.cashier_shifts s where s.id=v.id;
  insert into public.cashier_shift_edits(tenant_id,shift_id,changed_by,reason,before_state,after_state)
  values(p_tenant_id,v.id,auth.uid(),v_reason,v_before,v_after);

  return v_after||jsonb_build_object('expected_cash_now',v_expected);
end $$;


--
-- Name: cashier_shift_edits_v472(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cashier_shift_edits_v472(p_tenant_id uuid, p_shift_id uuid) RETURNS TABLE(id uuid, changed_by uuid, changed_by_name text, changed_at timestamp with time zone, reason text, before_state jsonb, after_state jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v public.cashier_shifts%rowtype;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  select s.* into v from public.cashier_shifts s where s.id=p_shift_id and s.tenant_id=p_tenant_id;
  if not found then raise exception 'Shift not found';end if;
  if v.user_id<>auth.uid() and not private.erp_user_is_owner(p_tenant_id)
     and not private.erp_has_permission(p_tenant_id,'pos.shift_manage') then raise exception 'Shift edit history access denied';end if;
  return query select e.id,e.changed_by,coalesce(ul.username,'')::text,e.changed_at,e.reason,e.before_state,e.after_state
  from public.cashier_shift_edits e left join public.user_login_names ul on ul.user_id=e.changed_by
  where e.tenant_id=p_tenant_id and e.shift_id=p_shift_id order by e.changed_at desc;
end $$;


--
-- Name: cashier_shift_history_v472(uuid, uuid, date, date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cashier_shift_history_v472(p_tenant_id uuid, p_device_id uuid, p_from date, p_to date, p_limit integer DEFAULT 50) RETURNS TABLE(id uuid, shift_number text, user_id uuid, cashier_name text, status text, opened_at timestamp with time zone, closed_at timestamp with time zone, opening_cash numeric, expected_cash numeric, declared_cash numeric, difference numeric, closing_note text, edit_count integer, last_edited_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_location uuid;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  select d.location_id into v_location from public.business_devices d
  where d.id=p_device_id and d.tenant_id=p_tenant_id and d.status='active';
  if v_location is null then raise exception 'Active terminal not found';end if;
  if not private.erp_user_is_owner(p_tenant_id)
     and not private.erp_user_location_allowed(p_tenant_id,v_location,'view') then raise exception 'Terminal access denied';end if;

  return query
  select s.id,s.shift_number,s.user_id,coalesce(ul.username,'')::text,s.status,
    s.opened_at,s.closed_at,s.opening_cash,
    case when s.status='open' then private.v472_shift_expected_cash(s.id) else coalesce(s.expected_cash,private.v472_shift_expected_cash(s.id)) end,
    s.declared_cash,s.difference,s.closing_note,coalesce(s.edit_count,0),s.last_edited_at
  from public.cashier_shifts s
  left join public.user_login_names ul on ul.user_id=s.user_id
  where s.tenant_id=p_tenant_id and s.device_id=p_device_id
    and s.opened_at::date<=coalesce(p_to,current_date)
    and coalesce(s.closed_at::date,s.opened_at::date)>=coalesce(p_from,current_date-30)
  order by s.opened_at desc
  limit greatest(1,least(coalesce(p_limit,50),200));
end $$;


--
-- Name: cashier_shift_open_v4(uuid, uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cashier_shift_open_v4(p_tenant_id uuid, p_location_id uuid, p_device_id uuid, p_opening_cash numeric DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_id uuid:=gen_random_uuid();v_no text;begin
  perform private.erp_validate_transaction_origin(p_tenant_id,p_location_id,p_device_id,'sales');
  if exists(select 1 from public.cashier_shifts where device_id=p_device_id and status='open') then raise exception 'This terminal already has an open shift';end if;
  v_no:='SHIFT-'||lpad(nextval('public.cashier_shift_number_seq')::text,6,'0');
  insert into public.cashier_shifts(id,tenant_id,location_id,device_id,user_id,shift_number,opening_cash) values(v_id,p_tenant_id,p_location_id,p_device_id,auth.uid(),v_no,greatest(coalesce(p_opening_cash,0),0));
  insert into public.cash_drawer_movements(tenant_id,shift_id,movement_type,amount,note,created_by) values(p_tenant_id,v_id,'opening',greatest(coalesce(p_opening_cash,0),0),'Opening cash',auth.uid());
  return jsonb_build_object('shift_id',v_id,'shift_number',v_no,'opening_cash',greatest(coalesce(p_opening_cash,0),0),'status','open');
end $$;


--
-- Name: cashier_shift_open_v47(uuid, uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cashier_shift_open_v47(p_tenant_id uuid, p_location_id uuid, p_device_id uuid, p_opening_cash numeric, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v jsonb;begin v:=private.v47_request_existing(p_tenant_id,p_request_id,'shift.open');if v is not null then return v;end if;v:=public.cashier_shift_open_v4(p_tenant_id,p_location_id,p_device_id,p_opening_cash);return private.v47_request_complete(p_tenant_id,p_request_id,'shift.open',v);end$$;


--
-- Name: cashier_shift_open_v472(uuid, uuid, uuid, numeric, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cashier_shift_open_v472(p_tenant_id uuid, p_location_id uuid, p_device_id uuid, p_opening_cash numeric, p_opened_at timestamp with time zone, p_note text, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_existing jsonb;
  v_id uuid:=gen_random_uuid();
  v_no text;
  v_opened timestamptz:=coalesce(p_opened_at,now());
  v_cash numeric:=greatest(coalesce(p_opening_cash,0),0);
  v_location uuid;
begin
  v_existing:=private.v47_request_existing(p_tenant_id,p_request_id,'shift.open.v472');
  if v_existing is not null then return v_existing;end if;

  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if not private.v472_shift_module_enabled(p_tenant_id,p_device_id) then raise exception 'Cashier Shift is disabled for this POS';end if;

  select d.location_id into v_location
  from public.business_devices d
  where d.id=p_device_id and d.tenant_id=p_tenant_id and d.status='active' for update;
  if v_location is null then raise exception 'Active POS terminal not found';end if;
  if v_location<>p_location_id then raise exception 'POS location changed. Refresh and try again';end if;
  if v_opened>now()+interval '5 minutes' then raise exception 'Shift start time cannot be in the future';end if;
  if not private.erp_user_is_owner(p_tenant_id)
     and not private.erp_user_location_allowed(p_tenant_id,v_location,'operate') then raise exception 'Terminal access denied';end if;

  if exists(select 1 from public.cashier_shifts s where s.device_id=p_device_id and s.status='open') then
    raise exception 'This terminal already has an open shift';
  end if;
  if private.v472_shift_period_conflicts(p_device_id,null,v_opened,null) then
    raise exception 'Shift start time overlaps an existing shift on this terminal';
  end if;

  v_no:='SHIFT-'||lpad(nextval('public.cashier_shift_number_seq')::text,6,'0');
  insert into public.cashier_shifts(
    id,tenant_id,location_id,device_id,user_id,shift_number,status,opened_at,opening_cash,opening_note
  ) values(
    v_id,p_tenant_id,v_location,p_device_id,auth.uid(),v_no,'open',v_opened,v_cash,nullif(trim(coalesce(p_note,'')),'')
  );
  insert into public.cash_drawer_movements(
    tenant_id,shift_id,movement_type,amount,note,created_by,created_at
  ) values(
    p_tenant_id,v_id,'opening',v_cash,'Opening cash',auth.uid(),v_opened
  );

  return private.v47_request_complete(
    p_tenant_id,p_request_id,'shift.open.v472',
    jsonb_build_object(
      'shift_id',v_id,'shift_number',v_no,'status','open',
      'opened_at',v_opened,'opening_cash',v_cash
    )
  );
end $$;


--
-- Name: client_runtime_context(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_runtime_context(p_tenant_id uuid, p_device_id uuid, p_app_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v jsonb;v_all boolean;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if not private.erp_user_app_allowed(p_tenant_id,p_app_key) then raise exception 'This user is not enabled for this application';end if;
  if not exists(select 1 from public.business_devices d where d.id=p_device_id and d.tenant_id=p_tenant_id and d.app_type=p_app_key and d.status='active') then raise exception 'Device is not active';end if;
  v_all:=private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'locations.view_all') or private.erp_has_permission(p_tenant_id,'locations.manage_all');
  select jsonb_build_object(
    'device_id',d.id,'device_code',d.device_code,'device_name',d.name,'device_modules',coalesce(to_jsonb(d.allowed_modules),'[]'::jsonb),
    'location_id',d.location_id,'location_code',l.location_code,'location_name',l.name,
    'can_view_all_locations',v_all,
    'locations',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'code',x.location_code,'name',x.name,'type',x.location_type,'tracking_code',x.tracking_code,'access_level',case when v_all then 'manage' else a.access_level end) order by x.name)
      from public.business_locations x
      left join public.business_user_location_access a on a.tenant_id=p_tenant_id and a.user_id=auth.uid() and a.location_id=x.id
      where x.tenant_id=p_tenant_id and x.active and (v_all or a.user_id is not null)),'[]'::jsonb)
  ) into v
  from public.business_devices d join public.business_locations l on l.id=d.location_id
  where d.id=p_device_id and d.tenant_id=p_tenant_id;
  return coalesce(v,'{}'::jsonb);
end $$;


--
-- Name: client_runtime_context_v4(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_runtime_context_v4(p_tenant_id uuid, p_device_id uuid, p_app_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v jsonb;v_all boolean;v_username text;v_roles jsonb;v_main uuid;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if not private.erp_user_app_allowed(p_tenant_id,p_app_key) then raise exception 'This user is not enabled for this application';end if;
  if not exists(select 1 from public.business_devices d where d.id=p_device_id and d.tenant_id=p_tenant_id and d.app_type=p_app_key and d.status='active') then raise exception 'Device is not active';end if;
  v_all:=private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'locations.view_all') or private.erp_has_permission(p_tenant_id,'locations.manage_all');
  v_main:=private.v42_main_location(p_tenant_id);
  select username into v_username from public.user_login_names where user_id=auth.uid();
  select coalesce(jsonb_agg(r.key order by r.key),'[]'::jsonb) into v_roles
  from public.tenant_memberships tm join public.user_roles ur on ur.membership_id=tm.id and ur.tenant_id=tm.tenant_id join public.roles r on r.id=ur.role_id
  where tm.tenant_id=p_tenant_id and tm.user_id=auth.uid() and tm.status='active';
  select jsonb_build_object(
    'schema_version','4.2','username',coalesce(v_username,''),'roles',coalesce(v_roles,'[]'::jsonb),'user_id',auth.uid(),
    'device_id',d.id,'device_code',d.device_code,'device_name',d.name,'device_modules',coalesce(to_jsonb(d.allowed_modules),'[]'::jsonb),
    'location_id',d.location_id,'location_code',l.location_code,'location_name',l.name,'device_invoice_prefix',d.invoice_prefix,
    'main_location_id',v_main,'can_view_all_locations',v_all,
    'locations',coalesce((select jsonb_agg(jsonb_build_object(
      'id',x.id,'parent_location_id',x.parent_location_id,'code',x.location_code,'name',x.name,'type',x.location_type,
      'hierarchy_role',x.hierarchy_role,'sort_order',x.sort_order,'tracking_code',x.tracking_code,
      'access_level',case when v_all then 'manage' else a.access_level end
    ) order by case when x.hierarchy_role='main_store' then 0 when x.hierarchy_role='warehouse' then 2 else 1 end,x.sort_order,x.name)
      from public.business_locations x left join public.business_user_location_access a on a.tenant_id=p_tenant_id and a.user_id=auth.uid() and a.location_id=x.id
      where x.tenant_id=p_tenant_id and x.active and (v_all or a.user_id is not null)),'[]'::jsonb),
    'open_shift',case when p_app_key='pos' then coalesce((select jsonb_build_object('id',s.id,'shift_number',s.shift_number,'opened_at',s.opened_at,'opening_cash',s.opening_cash) from public.cashier_shifts s where s.tenant_id=p_tenant_id and s.device_id=d.id and s.status='open' order by s.opened_at desc limit 1),'{}'::jsonb) else '{}'::jsonb end
  ) into v from public.business_devices d join public.business_locations l on l.id=d.location_id where d.id=p_device_id and d.tenant_id=p_tenant_id;
  return coalesce(v,'{}'::jsonb);
end $$;


--
-- Name: client_subscription_context(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_subscription_context(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v jsonb;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  select jsonb_build_object(
    'plan_key',sp.key,'plan_name',sp.name,'status',ts.status,'billing_cycle',ts.billing_cycle,
    'entitled_modules',coalesce((select jsonb_agg(spm.module_key order by m.sort_order,m.name) from public.subscription_plan_modules spm join public.modules m on m.key=spm.module_key where spm.plan_id=sp.id and m.is_active),'[]'::jsonb),
    'limits',sp.limits || ts.limit_overrides
  ) into v from public.tenant_subscriptions ts join public.subscription_plans sp on sp.id=ts.plan_id where ts.tenant_id=p_tenant_id;
  return coalesce(v,jsonb_build_object('status','none','billing_cycle','monthly','entitled_modules','[]'::jsonb,'limits','{}'::jsonb));
end $$;


