--
-- Name: custom_field_save_v4(uuid, uuid, text, text, text, text, boolean, boolean, boolean, jsonb, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.custom_field_save_v4(p_tenant_id uuid, p_id uuid, p_entity_type text, p_field_key text, p_label text, p_field_type text, p_required boolean, p_searchable boolean, p_invoice_visible boolean, p_options jsonb, p_active boolean, p_sort_order integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_id uuid; begin
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'settings.manage') then raise exception 'Settings permission required';end if;
  if trim(coalesce(p_entity_type,''))='' or trim(coalesce(p_field_key,''))='' or trim(coalesce(p_label,''))='' then raise exception 'Entity, key and label are required';end if;
  if p_field_type not in('text','number','date','dropdown','checkbox','multi_select') then raise exception 'Invalid custom field type';end if;
  if p_id is null then
    insert into public.custom_field_definitions(tenant_id,entity_type,field_key,label,field_type,required,searchable,invoice_visible,options,active,sort_order)
    values(p_tenant_id,lower(trim(p_entity_type)),lower(regexp_replace(trim(p_field_key),'[^a-zA-Z0-9_]+','_','g')),trim(p_label),p_field_type,coalesce(p_required,false),coalesce(p_searchable,false),coalesce(p_invoice_visible,false),coalesce(p_options,'[]'::jsonb),coalesce(p_active,true),coalesce(p_sort_order,0)) returning id into v_id;
  else
    update public.custom_field_definitions set entity_type=lower(trim(p_entity_type)),field_key=lower(regexp_replace(trim(p_field_key),'[^a-zA-Z0-9_]+','_','g')),label=trim(p_label),field_type=p_field_type,required=coalesce(p_required,false),searchable=coalesce(p_searchable,false),invoice_visible=coalesce(p_invoice_visible,false),options=coalesce(p_options,'[]'::jsonb),active=coalesce(p_active,true),sort_order=coalesce(p_sort_order,0)
    where id=p_id and tenant_id=p_tenant_id returning id into v_id;
  end if;
  if v_id is null then raise exception 'Custom field not found';end if;
  return v_id;
end $$;


--
-- Name: custom_field_values_get_v4(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.custom_field_values_get_v4(p_tenant_id uuid, p_entity_type text, p_entity_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v jsonb; begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  select coalesce(jsonb_object_agg(d.field_key,v.value),'{}'::jsonb) into v
  from public.custom_field_definitions d left join public.custom_field_values v on v.definition_id=d.id and v.entity_id=p_entity_id
  where d.tenant_id=p_tenant_id and d.entity_type=p_entity_type and d.active;
  return coalesce(v,'{}'::jsonb);
end $$;


--
-- Name: custom_field_values_set_v4(uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.custom_field_values_set_v4(p_tenant_id uuid, p_entity_type text, p_entity_id uuid, p_values jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare d record;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  for d in select * from public.custom_field_definitions where tenant_id=p_tenant_id and entity_type=p_entity_type and active loop
    if d.required and ((not (coalesce(p_values,'{}'::jsonb) ? d.field_key)) or nullif(trim(coalesce(p_values->>d.field_key,'')),'') is null) then raise exception 'Required custom field % is missing',d.label;end if;
    if coalesce(p_values,'{}'::jsonb) ? d.field_key then
      insert into public.custom_field_values(tenant_id,definition_id,entity_id,value,updated_by,updated_at)
      values(p_tenant_id,d.id,p_entity_id,p_values->d.field_key,auth.uid(),now())
      on conflict(definition_id,entity_id) do update set value=excluded.value,updated_by=auth.uid(),updated_at=now();
    end if;
  end loop;
end $$;


--
-- Name: custom_field_definitions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.custom_field_definitions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    entity_type text NOT NULL,
    field_key text NOT NULL,
    label text NOT NULL,
    field_type text NOT NULL,
    required boolean DEFAULT false NOT NULL,
    searchable boolean DEFAULT false NOT NULL,
    invoice_visible boolean DEFAULT false NOT NULL,
    options jsonb DEFAULT '[]'::jsonb NOT NULL,
    active boolean DEFAULT true NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    CONSTRAINT custom_field_definitions_field_type_check CHECK ((field_type = ANY (ARRAY['text'::text, 'number'::text, 'date'::text, 'dropdown'::text, 'checkbox'::text, 'multi_select'::text])))
);


--
-- Name: custom_fields_list_v4(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.custom_fields_list_v4(p_tenant_id uuid, p_entity_type text DEFAULT NULL::text) RETURNS SETOF public.custom_field_definitions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  return query select * from public.custom_field_definitions
  where tenant_id=p_tenant_id and (p_entity_type is null or p_entity_type='' or entity_type=p_entity_type)
  order by entity_type,sort_order,label;
end $$;


--
-- Name: customer_account_v471(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_account_v471(p_tenant_id uuid, p_customer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_customer jsonb;v_invoices jsonb;v_receipts jsonb;v_outstanding numeric:=0;v_platform boolean:=private.platform_v2_is_admin();
begin
  if not v_platform and not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if not v_platform and not private.erp_user_is_owner(p_tenant_id)
     and not private.erp_has_permission(p_tenant_id,'customers.view')
     and not private.erp_has_permission(p_tenant_id,'customers.manage')
     and not private.erp_has_permission(p_tenant_id,'sales.view')
     and not private.erp_has_permission(p_tenant_id,'sales.manage')
     and not private.erp_has_permission(p_tenant_id,'payments.receive') then
    raise exception 'Customer account permission required';
  end if;
  select to_jsonb(c) into v_customer from public.customers c where c.id=p_customer_id and c.tenant_id=p_tenant_id;
  if v_customer is null then raise exception 'Customer not found';end if;
  select coalesce(sum(greatest(s.grand_total-coalesce(rt.returned,0)-coalesce(py.paid,0),0)),0),
    coalesce(jsonb_agg(jsonb_build_object(
      'sale_id',s.id,'sale_number',s.sale_number,'sale_date',s.sale_date,'due_date',s.due_date,'grand_total',s.grand_total,
      'paid',coalesce(py.paid,0),'returned',coalesce(rt.returned,0),'balance',greatest(s.grand_total-coalesce(rt.returned,0)-coalesce(py.paid,0),0),'location_id',o.location_id,'location_name',l.name
    ) order by coalesce(s.due_date,s.sale_date),s.created_at) filter(where greatest(s.grand_total-coalesce(rt.returned,0)-coalesce(py.paid,0),0)>0.005),'[]'::jsonb)
  into v_outstanding,v_invoices
  from public.sales s
  left join (select sale_id,sum(amount) paid from public.sale_payments group by sale_id)py on py.sale_id=s.id
  left join (select sale_id,sum(grand_total) returned from public.sales_returns where refund_status<>'waived' group by sale_id)rt on rt.sale_id=s.id
  left join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='sale' and o.entity_id=s.id
  left join public.business_locations l on l.id=o.location_id
  where s.tenant_id=p_tenant_id and s.customer_id=p_customer_id and coalesce(s.status,'') not in('void','cancelled')
    and (v_platform or private.erp_document_scope_allowed(p_tenant_id,o.location_id,null,'view'));

  select coalesce(jsonb_agg(jsonb_build_object(
    'receipt_id',r.id,'receipt_number',r.receipt_number,'receipt_date',r.receipt_date,'amount',r.amount,
    'payment_method',r.payment_method,'reference_number',r.reference_number,'notes',r.notes,'location_id',r.location_id,
    'location_name',l.name,'device_id',r.device_id,'device_name',d.name,'created_at',r.created_at,
    'allocations',coalesce((select jsonb_agg(jsonb_build_object('sale_id',a.sale_id,'sale_number',s.sale_number,'amount',a.amount))
      from public.customer_receipt_allocations a join public.sales s on s.id=a.sale_id where a.receipt_id=r.id),'[]'::jsonb)
  ) order by r.created_at desc),'[]'::jsonb) into v_receipts
  from public.customer_receipts r left join public.business_locations l on l.id=r.location_id left join public.business_devices d on d.id=r.device_id
  where r.tenant_id=p_tenant_id and r.customer_id=p_customer_id
    and (v_platform or private.erp_document_scope_allowed(p_tenant_id,r.location_id,null,'view'));

  return jsonb_build_object('customer',v_customer,'outstanding',v_outstanding,'open_invoices',coalesce(v_invoices,'[]'::jsonb),'receipts',coalesce(v_receipts,'[]'::jsonb));
end $$;


--
-- Name: customer_accounts_list_v471(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_accounts_list_v471(p_tenant_id uuid, p_query text DEFAULT NULL::text, p_limit integer DEFAULT 500) RETURNS TABLE(customer_id uuid, public_id text, customer_name text, phone text, credit_limit numeric, outstanding numeric, open_invoice_count bigint, last_sale_date date)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_platform boolean:=private.platform_v2_is_admin();begin
  if not v_platform and not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if not v_platform and not private.erp_user_is_owner(p_tenant_id)
     and not private.erp_has_permission(p_tenant_id,'customers.view')
     and not private.erp_has_permission(p_tenant_id,'customers.manage')
     and not private.erp_has_permission(p_tenant_id,'sales.view')
     and not private.erp_has_permission(p_tenant_id,'sales.manage')
     and not private.erp_has_permission(p_tenant_id,'payments.receive') then
    raise exception 'Customer account permission required';
  end if;
  return query
  with visible_sales as (
    select s.id,s.customer_id,s.sale_date,s.grand_total,coalesce(py.paid,0)::numeric as paid,coalesce(rt.returned,0)::numeric as returned
    from public.sales s
    left join (select sale_id,sum(amount) paid from public.sale_payments group by sale_id) py on py.sale_id=s.id
    left join (select sale_id,sum(grand_total) returned from public.sales_returns where refund_status<>'waived' group by sale_id) rt on rt.sale_id=s.id
    left join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='sale' and o.entity_id=s.id
    where s.tenant_id=p_tenant_id and coalesce(s.status,'') not in('void','cancelled')
      and (v_platform or private.erp_document_scope_allowed(p_tenant_id,o.location_id,null,'view'))
  )
  select c.id,coalesce(c.tracking_code,''),c.name,coalesce(c.phone,''),coalesce(c.credit_limit,0),
    coalesce(sum(greatest(vs.grand_total-vs.returned-vs.paid,0)),0)::numeric,
    count(vs.id) filter(where greatest(vs.grand_total-vs.returned-vs.paid,0)>0.005),max(vs.sale_date)
  from public.customers c
  left join visible_sales vs on vs.customer_id=c.id
  where c.tenant_id=p_tenant_id and coalesce(c.status,'active')='active' and not coalesce(c.is_walk_in,false)
    and (trim(coalesce(p_query,''))='' or lower(c.name) like '%'||lower(trim(p_query))||'%' or lower(coalesce(c.phone,'')) like '%'||lower(trim(p_query))||'%' or lower(coalesce(c.tracking_code,'')) like '%'||lower(trim(p_query))||'%')
  group by c.id,c.tracking_code,c.name,c.phone,c.credit_limit
  order by 6 desc,c.name limit greatest(1,least(coalesce(p_limit,500),2000));
end $$;


--
-- Name: customer_credit_intelligence_v480(uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_credit_intelligence_v480(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_query text DEFAULT ''::text, p_limit integer DEFAULT 1000) RETURNS TABLE(customer_id uuid, public_id text, customer_name text, phone text, credit_limit numeric, total_outstanding numeric, available_credit numeric, utilization_pct numeric, current_amount numeric, days_1_30 numeric, days_31_60 numeric, days_61_90 numeric, days_90_plus numeric, open_invoice_count bigint, oldest_due_date date, status text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare q text:='%'||lower(trim(coalesce(p_query,'')))||'%';begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  return query
  with open_sales as (
    select s.id,s.customer_id,coalesce(s.due_date,s.sale_date) due_date,
      greatest(s.grand_total-coalesce(rt.returned,0)-coalesce(py.paid,0),0)::numeric balance
    from public.sales s
    left join(select sale_id,sum(amount) paid from public.sale_payments group by sale_id) py on py.sale_id=s.id
    left join(select sale_id,sum(grand_total) returned from public.sales_returns where refund_status<>'waived' group by sale_id) rt on rt.sale_id=s.id
    left join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='sale' and o.entity_id=s.id
    where s.tenant_id=p_tenant_id and coalesce(s.status,'') not in('void','cancelled')
      and (p_location_id is null or o.location_id=p_location_id)
      and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view')
      and greatest(s.grand_total-coalesce(rt.returned,0)-coalesce(py.paid,0),0)>0.005
  ), agg as (
    select os.customer_id,sum(os.balance)::numeric outstanding,count(*)::bigint cnt,min(os.due_date) oldest,
      sum(os.balance) filter(where os.due_date>=current_date)::numeric current_amt,
      sum(os.balance) filter(where os.due_date<current_date and os.due_date>=current_date-30)::numeric a1,
      sum(os.balance) filter(where os.due_date<current_date-30 and os.due_date>=current_date-60)::numeric a2,
      sum(os.balance) filter(where os.due_date<current_date-60 and os.due_date>=current_date-90)::numeric a3,
      sum(os.balance) filter(where os.due_date<current_date-90)::numeric a4
    from open_sales os group by os.customer_id
  )
  select c.id,coalesce(c.tracking_code,''),c.name,coalesce(c.phone,''),coalesce(c.credit_limit,0)::numeric,coalesce(a.outstanding,0)::numeric,
    greatest(coalesce(c.credit_limit,0)-coalesce(a.outstanding,0),0)::numeric,
    case when coalesce(c.credit_limit,0)>0 then round(coalesce(a.outstanding,0)*100/coalesce(c.credit_limit,1),1) else null end::numeric,
    coalesce(a.current_amt,0)::numeric,coalesce(a.a1,0)::numeric,coalesce(a.a2,0)::numeric,coalesce(a.a3,0)::numeric,coalesce(a.a4,0)::numeric,
    coalesce(a.cnt,0),a.oldest,
    (case when coalesce(a.outstanding,0)<=0.005 then 'clear'
      when coalesce(c.credit_limit,0)>0 and coalesce(a.outstanding,0)>c.credit_limit then 'over_limit'
      when coalesce(a.a4,0)>0 then 'critical_overdue'
      when coalesce(a.a1,0)+coalesce(a.a2,0)+coalesce(a.a3,0)>0 then 'overdue'
      else 'current' end)::text
  from public.customers c left join agg a on a.customer_id=c.id
  where c.tenant_id=p_tenant_id and coalesce(c.status,'active')='active' and not coalesce(c.is_walk_in,false)
    and (trim(coalesce(p_query,''))='' or lower(c.name) like q or lower(coalesce(c.phone,'')) like q or lower(coalesce(c.tracking_code,'')) like q)
  order by coalesce(a.a4,0) desc,coalesce(a.outstanding,0) desc,c.name
  limit greatest(1,least(coalesce(p_limit,1000),5000));
end $$;


--
-- Name: customer_crm_profile_v500(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_crm_profile_v500(p_tenant_id uuid, p_customer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare c jsonb;crm jsonb;v_sales numeric:=0;v_returns numeric:=0;v_paid numeric:=0;v_outstanding numeric:=0;v_loans_given numeric:=0;v_loans_taken numeric:=0;v_last_sale date;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  select to_jsonb(x) into c from public.customers x where x.tenant_id=p_tenant_id and x.id=p_customer_id;if c is null then raise exception 'Customer not found';end if;
  select jsonb_build_object('group_id',p.group_id,'group_name',g.name,'group_discount_percent',coalesce(g.discount_percent,0),'salesperson_user_id',p.salesperson_user_id,'birthday',p.birthday,'anniversary',p.anniversary,'loyalty_points',coalesce(p.loyalty_points,0),'notes',p.notes) into crm from public.customer_crm_profiles_v500 p left join public.customer_groups_v500 g on g.id=p.group_id where p.tenant_id=p_tenant_id and p.customer_id=p_customer_id;
  select coalesce(sum(s.grand_total),0),max(s.sale_date) into v_sales,v_last_sale from public.sales s where s.tenant_id=p_tenant_id and s.customer_id=p_customer_id and coalesce(s.status,'') not in('void','cancelled');
  select coalesce(sum(r.grand_total),0) into v_returns from public.sales_returns r join public.sales s on s.id=r.sale_id where r.tenant_id=p_tenant_id and s.customer_id=p_customer_id and r.refund_status<>'waived';
  select coalesce(sum(sp.amount),0) into v_paid from public.sale_payments sp join public.sales s on s.id=sp.sale_id where s.tenant_id=p_tenant_id and s.customer_id=p_customer_id;
  v_outstanding:=greatest(v_sales-v_returns-v_paid,0);
  if to_regclass('public.loan_accounts_v490') is not null then
    select coalesce(sum(principal_outstanding+interest_outstanding+penalty_outstanding),0) into v_loans_given from public.loan_accounts_v490 where tenant_id=p_tenant_id and client_id=p_customer_id and direction='given' and status in('active','defaulted');
    select coalesce(sum(principal_outstanding+interest_outstanding+penalty_outstanding),0) into v_loans_taken from public.loan_accounts_v490 where tenant_id=p_tenant_id and client_id=p_customer_id and direction='taken' and status in('active','defaulted');
  end if;
  return jsonb_build_object('customer',c,'crm',coalesce(crm,'{}'::jsonb),'summary',jsonb_build_object('gross_sales',v_sales,'returns',v_returns,'payments',v_paid,'outstanding_sales',v_outstanding,'loan_receivable',v_loans_given,'loan_payable',v_loans_taken,'last_sale_date',v_last_sale));
end $$;


--
-- Name: customer_crm_save_v500(uuid, uuid, uuid, uuid, date, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_crm_save_v500(p_tenant_id uuid, p_customer_id uuid, p_group_id uuid, p_salesperson_user_id uuid, p_birthday date, p_anniversary date, p_notes text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$begin perform private.v500_customer_manage_access(p_tenant_id);if not exists(select 1 from public.customers where id=p_customer_id and tenant_id=p_tenant_id) then raise exception 'Customer not found';end if;if p_group_id is not null and not exists(select 1 from public.customer_groups_v500 where id=p_group_id and tenant_id=p_tenant_id and active) then raise exception 'Active customer group not found';end if;if p_salesperson_user_id is not null and not exists(select 1 from public.tenant_memberships where tenant_id=p_tenant_id and user_id=p_salesperson_user_id and status='active') then raise exception 'Salesperson is not an active business member';end if;insert into public.customer_crm_profiles_v500(tenant_id,customer_id,group_id,salesperson_user_id,birthday,anniversary,notes,updated_by,updated_at) values(p_tenant_id,p_customer_id,p_group_id,p_salesperson_user_id,p_birthday,p_anniversary,nullif(trim(coalesce(p_notes,'')),''),auth.uid(),now()) on conflict(tenant_id,customer_id) do update set group_id=excluded.group_id,salesperson_user_id=excluded.salesperson_user_id,birthday=excluded.birthday,anniversary=excluded.anniversary,notes=excluded.notes,updated_by=auth.uid(),updated_at=now();end $$;


--
-- Name: customer_group_save_v500(uuid, uuid, text, text, numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_group_save_v500(p_tenant_id uuid, p_group_id uuid, p_name text, p_description text, p_discount_percent numeric, p_active boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v uuid;begin
  perform private.v500_customer_manage_access(p_tenant_id);
  if trim(coalesce(p_name,''))='' then raise exception 'Group name is required';end if;if coalesce(p_discount_percent,0)<0 or coalesce(p_discount_percent,0)>100 then raise exception 'Invalid group discount';end if;
  if p_group_id is null then insert into public.customer_groups_v500(tenant_id,name,description,discount_percent,active,created_by) values(p_tenant_id,trim(p_name),nullif(trim(coalesce(p_description,'')),''),coalesce(p_discount_percent,0),coalesce(p_active,true),auth.uid()) returning id into v;
  else update public.customer_groups_v500 set name=trim(p_name),description=nullif(trim(coalesce(p_description,'')),''),discount_percent=coalesce(p_discount_percent,0),active=coalesce(p_active,true) where id=p_group_id and tenant_id=p_tenant_id returning id into v;end if;
  if v is null then raise exception 'Customer group not found';end if;return v;
end $$;


--
-- Name: customer_groups_list_v500(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_groups_list_v500(p_tenant_id uuid) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare r record;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  for r in select * from public.customer_groups_v500 where tenant_id=p_tenant_id order by active desc,name loop return next to_jsonb(r);end loop;return;
end $$;


--
-- Name: customer_loan_summary_v490(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_loan_summary_v490(p_tenant_id uuid, p_customer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_customer jsonb;v_summary jsonb;begin
  perform private.loan_v490_access(p_tenant_id,null,'loans.view','view');
  select jsonb_build_object('id',c.id,'public_id',c.tracking_code,'name',c.name,'phone',c.phone,'email',c.email)
  into v_customer from public.customers c where c.tenant_id=p_tenant_id and c.id=p_customer_id;
  if v_customer is null then raise exception 'Customer/client not found';end if;
  with scoped as(
    select l.* from public.loan_accounts_v490 l where l.tenant_id=p_tenant_id and l.client_id=p_customer_id
      and private.erp_document_scope_allowed(p_tenant_id,l.location_id,null,'view')
  ) select jsonb_build_object(
    'customer',v_customer,
    'loan_count',count(*),
    'active_count',count(*) filter(where status in('active','defaulted')),
    'principal_outstanding',round(coalesce(sum(principal_outstanding) filter(where status in('active','defaulted')),0),2),
    'interest_outstanding',round(coalesce(sum(interest_outstanding) filter(where status in('active','defaulted')),0),2),
    'penalty_outstanding',round(coalesce(sum(penalty_outstanding) filter(where status in('active','defaulted')),0),2),
    'total_outstanding',round(coalesce(sum(principal_outstanding+interest_outstanding+penalty_outstanding) filter(where status in('active','defaulted')),0),2),
    'loans',coalesce(jsonb_agg(jsonb_build_object(
      'loan_id',id,'loan_number',loan_number,'status',status,'principal_amount',principal_amount,'principal_outstanding',principal_outstanding,
      'interest_outstanding',interest_outstanding,'penalty_outstanding',penalty_outstanding,'rate_type',rate_type,'interest_rate',interest_rate,
      'repayment_frequency',repayment_frequency,'maturity_date',maturity_date,'location_id',location_id
    ) order by updated_at desc),'[]'::jsonb)
  ) into v_summary from scoped;
  return coalesce(v_summary,jsonb_build_object('customer',v_customer,'loan_count',0,'active_count',0,'principal_outstanding',0,'interest_outstanding',0,'penalty_outstanding',0,'total_outstanding',0,'loans','[]'::jsonb));
end $$;


--
-- Name: customer_loyalty_adjust_v500(uuid, uuid, numeric, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_loyalty_adjust_v500(p_tenant_id uuid, p_customer_id uuid, p_points numeric, p_source_type text, p_source_id uuid, p_note text) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v numeric;begin
  perform private.v500_customer_manage_access(p_tenant_id);if coalesce(p_points,0)=0 then raise exception 'Points adjustment cannot be zero';end if;
  insert into public.customer_crm_profiles_v500(tenant_id,customer_id,loyalty_points,updated_by) values(p_tenant_id,p_customer_id,0,auth.uid()) on conflict(tenant_id,customer_id) do nothing;
  update public.customer_crm_profiles_v500 set loyalty_points=greatest(loyalty_points+p_points,0),updated_by=auth.uid(),updated_at=now() where tenant_id=p_tenant_id and customer_id=p_customer_id returning loyalty_points into v;
  insert into public.customer_loyalty_ledger_v500(tenant_id,customer_id,points,source_type,source_id,note,created_by) values(p_tenant_id,p_customer_id,p_points,coalesce(nullif(trim(p_source_type),''),'manual'),p_source_id,nullif(trim(coalesce(p_note,'')),''),auth.uid());return v;
end $$;


--
-- Name: customer_outstanding_v46(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_outstanding_v46(p_tenant_id uuid, p_customer_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'customer_id',p_customer_id,
    'outstanding',coalesce(sum(greatest(s.grand_total-coalesce((select sum(sp.amount) from public.sale_payments sp where sp.sale_id=s.id),0),0)),0)
  )
  from public.sales s
  where s.tenant_id=p_tenant_id and s.customer_id=p_customer_id and coalesce(s.status,'') not in('void','cancelled');
$$;


--
-- Name: customer_price_save_v482(uuid, uuid, uuid, uuid, uuid, numeric, numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_price_save_v482(p_tenant_id uuid, p_rule_id uuid, p_customer_id uuid, p_variant_id uuid, p_unit_id uuid, p_min_quantity numeric, p_unit_price numeric, p_active boolean DEFAULT true) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v_id uuid;begin
 if not private.v482_pricing_manage_allowed(p_tenant_id) then raise exception 'Pricing manage permission required';end if;
 if coalesce(p_min_quantity,0)<=0 or coalesce(p_unit_price,-1)<0 then raise exception 'Valid quantity and price are required';end if;
 if not exists(select 1 from public.customers c where c.id=p_customer_id and c.tenant_id=p_tenant_id) then raise exception 'Customer not found';end if;
 if not exists(select 1 from public.product_units_v481 pu where pu.tenant_id=p_tenant_id and pu.variant_id=p_variant_id and pu.unit_id=p_unit_id and pu.active and pu.allow_sale) then raise exception 'Unit is not enabled for sale on this product';end if;
 if p_rule_id is null then
  insert into public.customer_prices_v482(tenant_id,customer_id,variant_id,unit_id,min_quantity,unit_price,active) values(p_tenant_id,p_customer_id,p_variant_id,p_unit_id,p_min_quantity,p_unit_price,p_active)
  on conflict(tenant_id,customer_id,variant_id,unit_id,min_quantity) do update set unit_price=excluded.unit_price,active=excluded.active,updated_at=now() returning id into v_id;
 else
  update public.customer_prices_v482 set customer_id=p_customer_id,variant_id=p_variant_id,unit_id=p_unit_id,min_quantity=p_min_quantity,unit_price=p_unit_price,active=p_active,updated_at=now() where id=p_rule_id and tenant_id=p_tenant_id returning id into v_id;
  if v_id is null then raise exception 'Customer price rule not found';end if;
 end if;
 perform private.thq_sync_bump_v480(p_tenant_id,'parties','customer_price',p_customer_id::text,'save');return v_id;
end$$;


--
-- Name: customer_prices_v482(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_prices_v482(p_tenant_id uuid, p_customer_id uuid, p_variant_id uuid DEFAULT NULL::uuid) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$begin
 if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
 return query select jsonb_build_object('rule_id',r.id,'customer_id',r.customer_id,'variant_id',r.variant_id,'product_name',p.name,'sku',pv.sku,'unit_id',r.unit_id,'unit_code',u.code,'unit_name',u.name,'min_quantity',r.min_quantity,'unit_price',r.unit_price,'active',r.active)
 from public.customer_prices_v482 r join public.product_variants pv on pv.id=r.variant_id join public.products p on p.id=pv.product_id join public.inventory_units_v481 u on u.id=r.unit_id
 where r.tenant_id=p_tenant_id and r.customer_id=p_customer_id and (p_variant_id is null or r.variant_id=p_variant_id) order by p.name,u.name,r.min_quantity;
end$$;


--
-- Name: customer_pricing_profile_set_v482(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_pricing_profile_set_v482(p_tenant_id uuid, p_customer_id uuid, p_price_list_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$begin
 if not private.v482_pricing_manage_allowed(p_tenant_id) then raise exception 'Pricing manage permission required';end if;
 if not exists(select 1 from public.customers c where c.id=p_customer_id and c.tenant_id=p_tenant_id) then raise exception 'Customer not found';end if;
 if p_price_list_id is not null and not exists(select 1 from public.price_lists_v482 pl where pl.id=p_price_list_id and pl.tenant_id=p_tenant_id and pl.active) then raise exception 'Price list not found';end if;
 insert into public.customer_pricing_profiles_v482(tenant_id,customer_id,price_list_id,active,updated_at,updated_by) values(p_tenant_id,p_customer_id,p_price_list_id,true,now(),auth.uid())
 on conflict(tenant_id,customer_id) do update set price_list_id=excluded.price_list_id,active=true,updated_at=now(),updated_by=auth.uid();
 perform private.thq_sync_bump_v480(p_tenant_id,'parties','customer_pricing',p_customer_id::text,'save');
end$$;


--
-- Name: customer_receive_payment_v471(uuid, uuid, numeric, text, text, text, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_receive_payment_v471(p_tenant_id uuid, p_customer_id uuid, p_amount numeric, p_payment_method text, p_reference_number text, p_notes text, p_sale_id uuid DEFAULT NULL::uuid, p_location_id uuid DEFAULT NULL::uuid, p_device_id uuid DEFAULT NULL::uuid, p_request_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_existing jsonb;v_receipt uuid:=gen_random_uuid();v_receipt_no text;v_remaining numeric:=round(coalesce(p_amount,0),2);v_total_outstanding numeric:=0;
  v_location uuid:=p_location_id;v_sale record;v_alloc numeric;v_result jsonb;v_payment_id uuid;v_started timestamptz:=clock_timestamp();v_lines jsonb;v_response jsonb;
  v_is_platform boolean:=private.platform_v2_is_admin();v_device_type text;v_device_location uuid;
begin
  if nullif(trim(coalesce(p_request_id,'')),'') is null then raise exception 'Request ID is required';end if;
  v_existing:=private.v47_request_existing(p_tenant_id,p_request_id,'customer.receipt');if v_existing is not null then return v_existing;end if;
  if not v_is_platform then
    if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
    if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'payments.receive') and not private.erp_has_permission(p_tenant_id,'sales.manage') then raise exception 'Receive payment permission required';end if;
  end if;
  if v_remaining<=0 then raise exception 'Payment amount must be greater than zero';end if;
  -- Serialize receipts per customer so two terminals cannot both collect the same remaining balance.
  perform 1 from public.customers where id=p_customer_id and tenant_id=p_tenant_id and status='active' and not coalesce(is_walk_in,false) for update;
  if not found then raise exception 'Select an active non-walk-in customer';end if;
  if lower(coalesce(p_payment_method,'')) not in('cash','upi','card','bank','cheque','other') then raise exception 'Invalid payment method';end if;

  if p_device_id is not null then
    select app_type,location_id into v_device_type,v_device_location
    from public.business_devices where id=p_device_id and tenant_id=p_tenant_id and status='active';
    if v_device_type is null then raise exception 'Active collecting system not found';end if;
    if v_device_type='pos' then
      if p_location_id is not null and p_location_id<>v_device_location then raise exception 'Collecting POS/location mismatch';end if;
      v_location:=v_device_location;
    else
      v_location:=coalesce(p_location_id,v_device_location);
    end if;
    if not v_is_platform then perform private.erp_validate_transaction_origin(p_tenant_id,v_location,p_device_id,'sales');end if;
    if v_device_type='pos' and lower(p_payment_method)='cash'
       and exists(select 1 from public.business_devices d where d.id=p_device_id and d.tenant_id=p_tenant_id and 'cashier_shifts'=any(coalesce(d.allowed_modules,'{}'::text[])))
       and not exists(select 1 from public.cashier_shifts s where s.tenant_id=p_tenant_id and s.device_id=p_device_id and s.status='open') then
      raise exception 'Open cashier shift before receiving cash on this POS';
    end if;
  elsif v_location is not null and not v_is_platform and not private.erp_document_scope_allowed(p_tenant_id,v_location,v_location,'operate') then
    raise exception 'Location access denied';
  end if;

  select coalesce(sum(greatest(s.grand_total-coalesce(rt.returned,0)-coalesce(py.paid,0),0)),0) into v_total_outstanding
  from public.sales s left join(select sale_id,sum(amount) paid from public.sale_payments group by sale_id)py on py.sale_id=s.id
  left join (select sale_id,sum(grand_total) returned from public.sales_returns where refund_status<>'waived' group by sale_id)rt on rt.sale_id=s.id
  left join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='sale' and o.entity_id=s.id
  where s.tenant_id=p_tenant_id and s.customer_id=p_customer_id and coalesce(s.status,'') not in('void','cancelled')
    and (p_sale_id is null or s.id=p_sale_id)
    and (v_is_platform or private.erp_document_scope_allowed(p_tenant_id,o.location_id,null,'operate'));
  if v_total_outstanding<=0.005 then raise exception 'Customer has no outstanding balance in the permitted scope';end if;
  if v_remaining>v_total_outstanding+0.005 then raise exception 'Payment % exceeds outstanding balance %',v_remaining,v_total_outstanding;end if;

  if v_location is null then
    select o.location_id into v_location from public.sales s join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='sale' and o.entity_id=s.id
    where s.tenant_id=p_tenant_id and s.customer_id=p_customer_id and (p_sale_id is null or s.id=p_sale_id)
    order by coalesce(s.due_date,s.sale_date),s.created_at limit 1;
  end if;
  if v_location is null and v_is_platform then
    select id into v_location from public.business_locations where tenant_id=p_tenant_id and active order by case when hierarchy_role='main_store' then 0 else 1 end,created_at limit 1;
  end if;
  if v_location is null then raise exception 'Could not determine collection location';end if;
  v_receipt_no:='RCT-'||to_char(current_date,'YYMMDD')||'-'||lpad(nextval('public.customer_receipt_number_seq')::text,6,'0');
  insert into public.customer_receipts(id,tenant_id,customer_id,receipt_number,receipt_date,amount,payment_method,reference_number,notes,location_id,device_id,created_by)
  values(v_receipt,p_tenant_id,p_customer_id,v_receipt_no,current_date,v_remaining,lower(p_payment_method),nullif(trim(coalesce(p_reference_number,'')),''),nullif(trim(coalesce(p_notes,'')),''),v_location,p_device_id,auth.uid());

  perform set_config('thq.customer_receipt_id',v_receipt::text,true);
  for v_sale in
    select s.id,s.sale_number,greatest(s.grand_total-coalesce(rt.returned,0)-coalesce(py.paid,0),0)::numeric balance,o.location_id
    from public.sales s left join(select sale_id,sum(amount) paid from public.sale_payments group by sale_id)py on py.sale_id=s.id
    left join (select sale_id,sum(grand_total) returned from public.sales_returns where refund_status<>'waived' group by sale_id)rt on rt.sale_id=s.id
    left join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='sale' and o.entity_id=s.id
    where s.tenant_id=p_tenant_id and s.customer_id=p_customer_id and coalesce(s.status,'') not in('void','cancelled')
      and greatest(s.grand_total-coalesce(rt.returned,0)-coalesce(py.paid,0),0)>0.005 and (p_sale_id is null or s.id=p_sale_id)
      and (v_is_platform or private.erp_document_scope_allowed(p_tenant_id,o.location_id,null,'operate'))
    order by case when p_sale_id is not null then 0 else 1 end,coalesce(s.due_date,s.sale_date),s.created_at
    for update of s
  loop
    exit when v_remaining<=0.005;
    v_alloc:=least(v_remaining,v_sale.balance);
    v_payment_id:=null;
    if v_is_platform then
      v_payment_id:=private.v471_platform_insert_sale_payment(v_sale.id,v_alloc,lower(p_payment_method),p_reference_number,coalesce(p_notes,'')||case when trim(coalesce(p_notes,''))='' then '' else ' • ' end||'Receipt '||v_receipt_no);
    else
      v_result:=public.sales_add_payment_v32(p_tenant_id,v_sale.id,v_alloc,lower(p_payment_method),p_reference_number,coalesce(p_notes,'')||case when trim(coalesce(p_notes,''))='' then '' else ' • ' end||'Receipt '||v_receipt_no);
      begin v_payment_id:=nullif(coalesce(v_result->>'payment_id',v_result->>'id'),'')::uuid;exception when others then v_payment_id:=null;end;
      if v_payment_id is null then
        select sp.id into v_payment_id from public.sale_payments sp where sp.sale_id=v_sale.id and abs(sp.amount-v_alloc)<0.005 and lower(sp.payment_method)=lower(p_payment_method)
          and sp.paid_at>=v_started-interval '2 seconds' order by sp.paid_at desc,sp.id desc limit 1;
      end if;
    end if;
    insert into public.customer_receipt_allocations(tenant_id,receipt_id,sale_id,payment_id,amount)
    values(p_tenant_id,v_receipt,v_sale.id,v_payment_id,v_alloc);
    v_remaining:=v_remaining-v_alloc;
  end loop;
  perform set_config('thq.customer_receipt_id','',true);
  if v_remaining>0.005 then raise exception 'Could not allocate full receipt. Remaining %',v_remaining;end if;

  v_lines:=jsonb_build_array(
    jsonb_build_object('account_id',private.v4_payment_account(p_tenant_id,p_payment_method),'debit',p_amount,'credit',0,'party_type','customer','party_id',p_customer_id,'description','Customer account receipt'),
    jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'accounts_receivable'),'debit',0,'credit',p_amount,'party_type','customer','party_id',p_customer_id,'description','Receivable settlement')
  );
  perform private.v4_journal_create(p_tenant_id,v_location,current_date,'Customer account receipt • '||v_receipt_no,'customer_receipt',v_receipt,v_receipt_no,v_lines);

  if lower(p_payment_method)='cash' and p_device_id is not null then
    insert into public.cash_drawer_movements(tenant_id,shift_id,movement_type,amount,reference_type,reference_id,reference_number,note,created_by)
    select p_tenant_id,s.id,'receipt',p_amount,'customer_receipt',v_receipt,v_receipt_no,'Customer balance receipt',auth.uid()
    from public.cashier_shifts s where s.tenant_id=p_tenant_id and s.device_id=p_device_id and s.status='open'
      and not exists(select 1 from public.cash_drawer_movements m where m.reference_type='customer_receipt' and m.reference_id=v_receipt)
    order by s.opened_at desc limit 1;
  end if;

  perform private.business_audit_write_v471(p_tenant_id,'customer.payment.receive','customer',p_customer_id,v_receipt_no,null::jsonb,jsonb_build_object('receipt_id',v_receipt,'amount',p_amount,'payment_method',lower(p_payment_method),'sale_id',p_sale_id,'location_id',v_location,'device_id',p_device_id));
  v_response:=jsonb_build_object('success',true,'receipt_id',v_receipt,'receipt_number',v_receipt_no,'amount',p_amount,'outstanding_before',v_total_outstanding,'outstanding_after',greatest(v_total_outstanding-p_amount,0));
  return private.v47_request_complete(p_tenant_id,p_request_id,'customer.receipt',v_response);
end $$;


--
-- Name: customers_create(uuid, text, text, text, text, text, text, text, text, text, text, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customers_create(p_tenant_id uuid, p_name text, p_contact_person text, p_phone text, p_email text, p_tax_number text, p_address_line1 text, p_address_line2 text, p_city text, p_state text, p_postal_code text, p_country text, p_credit_limit numeric, p_notes text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_customer_id uuid;
  v_tax_number text;
begin

  -- ----------------------------------------------------------
  -- PERMISSION
  -- ----------------------------------------------------------

  if not private.has_permission(
    p_tenant_id,
    'customers.manage'
  ) then

    raise exception 'Access denied'
      using errcode = '42501';

  end if;


  -- ----------------------------------------------------------
  -- TENANT
  -- ----------------------------------------------------------

  if not exists (
    select 1
    from public.tenants t

    where t.id = p_tenant_id
      and t.status = 'active'
  ) then

    raise exception
      'Business not found or inactive';

  end if;


  -- ----------------------------------------------------------
  -- VALIDATION
  -- ----------------------------------------------------------

  if nullif(
    trim(
      coalesce(
        p_name,
        ''
      )
    ),
    ''
  ) is null then

    raise exception
      'Customer name is required';

  end if;


  if p_credit_limit is null
     or p_credit_limit < 0 then

    raise exception
      'Credit limit cannot be negative';

  end if;


  v_tax_number :=
    nullif(
      upper(
        trim(
          coalesce(
            p_tax_number,
            ''
          )
        )
      ),
      ''
    );


  if v_tax_number is not null
     and exists (
       select 1

       from public.customers c

       where c.tenant_id = p_tenant_id
         and upper(c.tax_number) =
             v_tax_number
     ) then

    raise exception
      'A customer with this Tax ID already exists';

  end if;


  -- ----------------------------------------------------------
  -- CREATE
  -- ----------------------------------------------------------

  insert into public.customers (
    tenant_id,

    name,

    contact_person,
    phone,
    email,

    tax_number,

    address_line1,
    address_line2,

    city,
    state,
    postal_code,
    country,

    credit_limit,

    notes,

    is_walk_in,

    status,

    created_by
  )
  values (
    p_tenant_id,

    trim(p_name),

    nullif(
      trim(
        coalesce(
          p_contact_person,
          ''
        )
      ),
      ''
    ),

    nullif(
      trim(
        coalesce(
          p_phone,
          ''
        )
      ),
      ''
    ),

    nullif(
      lower(
        trim(
          coalesce(
            p_email,
            ''
          )
        )
      ),
      ''
    ),

    v_tax_number,

    nullif(
      trim(
        coalesce(
          p_address_line1,
          ''
        )
      ),
      ''
    ),

    nullif(
      trim(
        coalesce(
          p_address_line2,
          ''
        )
      ),
      ''
    ),

    nullif(
      trim(
        coalesce(
          p_city,
          ''
        )
      ),
      ''
    ),

    nullif(
      trim(
        coalesce(
          p_state,
          ''
        )
      ),
      ''
    ),

    nullif(
      trim(
        coalesce(
          p_postal_code,
          ''
        )
      ),
      ''
    ),

    coalesce(
      nullif(
        trim(
          coalesce(
            p_country,
            ''
          )
        ),
        ''
      ),
      'India'
    ),

    p_credit_limit,

    nullif(
      trim(
        coalesce(
          p_notes,
          ''
        )
      ),
      ''
    ),

    false,

    'active',

    auth.uid()
  )

  returning id
  into v_customer_id;


  return v_customer_id;

end;
$$;


--
-- Name: customers_get_statement(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customers_get_statement(p_tenant_id uuid, p_customer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_name text; v_rows jsonb; v_debit numeric; v_credit numeric;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  select c.name into v_name from public.customers c where c.id=p_customer_id and c.tenant_id=p_tenant_id;
  if v_name is null then raise exception 'Customer not found'; end if;

  with raw as (
    select s.sale_date::timestamp as ts, s.sale_date as entry_date, 'sale'::text as entry_type,
           s.sale_number as reference, 'Sales invoice'::text as description,
           s.grand_total::numeric as debit, 0::numeric as credit
    from public.sales s
    where s.tenant_id=p_tenant_id and s.customer_id=p_customer_id and coalesce(s.status,'') <> 'cancelled'
    union all
    select coalesce(sp.paid_at,sp.created_at) as ts, coalesce(sp.paid_at,sp.created_at)::date as entry_date,
           'payment'::text, s.sale_number, 'Customer payment'::text,
           0::numeric, sp.amount::numeric
    from public.sale_payments sp join public.sales s on s.id=sp.sale_id
    where s.tenant_id=p_tenant_id and s.customer_id=p_customer_id
  ), running as (
    select *, sum(debit-credit) over(order by ts, entry_type, reference rows unbounded preceding) as balance
    from raw
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'entry_date',entry_date,'entry_type',entry_type,'reference',reference,'description',description,
      'debit',debit,'credit',credit,'balance',balance
    ) order by ts,entry_type,reference),'[]'::jsonb),
    coalesce(sum(debit),0),coalesce(sum(credit),0)
  into v_rows,v_debit,v_credit from running;

  return jsonb_build_object(
    'party_id',p_customer_id,'party_name',v_name,'opening_balance',0,
    'total_debit',v_debit,'total_credit',v_credit,'closing_balance',v_debit-v_credit,'rows',v_rows
  );
end $$;


--
-- Name: customers_list(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customers_list(p_tenant_id uuid) RETURNS TABLE(customer_id uuid, customer_name text, contact_person text, phone text, email text, tax_number text, address_line1 text, address_line2 text, city text, state text, postal_code text, country text, credit_limit numeric, notes text, is_walk_in boolean, status text, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin

  if not (
    private.has_permission(
      p_tenant_id,
      'customers.view'
    )
    or
    private.has_permission(
      p_tenant_id,
      'customers.manage'
    )
  ) then

    raise exception 'Access denied'
      using errcode = '42501';

  end if;


  return query

  select
    c.id,

    c.name,

    c.contact_person,

    c.phone,
    c.email,

    c.tax_number,

    c.address_line1,
    c.address_line2,

    c.city,
    c.state,
    c.postal_code,
    c.country,

    c.credit_limit,

    c.notes,

    c.is_walk_in,

    c.status,

    c.created_at,
    c.updated_at

  from public.customers c

  where c.tenant_id = p_tenant_id

  order by
    case
      when c.is_walk_in
        then 0
      when c.status = 'active'
        then 1
      else 2
    end,

    lower(c.name);

end;
$$;


--
-- Name: customers_list_v32(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customers_list_v32(p_tenant_id uuid) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_row jsonb;v_id uuid;v_code text;
begin
  for v_row in select to_jsonb(x) from public.customers_list(p_tenant_id) x loop
    begin v_id:=coalesce(nullif(v_row->>'customer_id',''),nullif(v_row->>'id',''))::uuid; exception when others then v_id:=null; end;
    if v_id is not null then select tracking_code into v_code from public.customers where tenant_id=p_tenant_id and id=v_id; end if;
    return next v_row || jsonb_build_object('tracking_code',v_code,'public_id',v_code);
  end loop;
  return;
end $$;


--
-- Name: customers_list_v482(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customers_list_v482(p_tenant_id uuid) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare r jsonb;v_id uuid;v_list uuid;v_name text;begin
 for r in select * from public.customers_list_v32(p_tenant_id) loop
  begin v_id:=coalesce(nullif(r->>'customer_id',''),nullif(r->>'id',''))::uuid;exception when others then v_id:=null;end;
  v_list:=null;v_name:=null;
  if v_id is not null then select cpp.price_list_id,pl.name into v_list,v_name from public.customer_pricing_profiles_v482 cpp left join public.price_lists_v482 pl on pl.id=cpp.price_list_id where cpp.tenant_id=p_tenant_id and cpp.customer_id=v_id and cpp.active;end if;
  return next r||jsonb_build_object('price_list_id',v_list,'price_list_name',v_name);
 end loop;return;
end$$;


--
-- Name: customers_update(uuid, uuid, text, text, text, text, text, text, text, text, text, text, text, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customers_update(p_tenant_id uuid, p_customer_id uuid, p_name text, p_contact_person text, p_phone text, p_email text, p_tax_number text, p_address_line1 text, p_address_line2 text, p_city text, p_state text, p_postal_code text, p_country text, p_credit_limit numeric, p_notes text, p_status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tax_number text;
  v_is_walk_in boolean;
begin

  -- ----------------------------------------------------------
  -- PERMISSION
  -- ----------------------------------------------------------

  if not private.has_permission(
    p_tenant_id,
    'customers.manage'
  ) then

    raise exception 'Access denied'
      using errcode = '42501';

  end if;


  -- ----------------------------------------------------------
  -- CUSTOMER
  -- ----------------------------------------------------------

  select c.is_walk_in
  into v_is_walk_in

  from public.customers c

  where c.id = p_customer_id
    and c.tenant_id = p_tenant_id;


  if v_is_walk_in is null then
    raise exception 'Customer not found';
  end if;


  -- ----------------------------------------------------------
  -- WALK-IN CUSTOMER PROTECTION
  -- ----------------------------------------------------------

  if v_is_walk_in = true then

    raise exception
      'Walk-in Customer is a protected system customer';

  end if;


  -- ----------------------------------------------------------
  -- VALIDATION
  -- ----------------------------------------------------------

  if nullif(
    trim(
      coalesce(
        p_name,
        ''
      )
    ),
    ''
  ) is null then

    raise exception
      'Customer name is required';

  end if;


  if p_status not in (
    'active',
    'inactive'
  ) then

    raise exception
      'Invalid customer status';

  end if;


  if p_credit_limit is null
     or p_credit_limit < 0 then

    raise exception
      'Credit limit cannot be negative';

  end if;


  v_tax_number :=
    nullif(
      upper(
        trim(
          coalesce(
            p_tax_number,
            ''
          )
        )
      ),
      ''
    );


  if v_tax_number is not null
     and exists (
       select 1

       from public.customers c

       where c.tenant_id = p_tenant_id
         and c.id <> p_customer_id
         and upper(c.tax_number) =
             v_tax_number
     ) then

    raise exception
      'A customer with this Tax ID already exists';

  end if;


  -- ----------------------------------------------------------
  -- UPDATE
  -- ----------------------------------------------------------

  update public.customers
  set
    name = trim(p_name),

    contact_person =
      nullif(
        trim(
          coalesce(
            p_contact_person,
            ''
          )
        ),
        ''
      ),

    phone =
      nullif(
        trim(
          coalesce(
            p_phone,
            ''
          )
        ),
        ''
      ),

    email =
      nullif(
        lower(
          trim(
            coalesce(
              p_email,
              ''
            )
          )
        ),
        ''
      ),

    tax_number =
      v_tax_number,

    address_line1 =
      nullif(
        trim(
          coalesce(
            p_address_line1,
            ''
          )
        ),
        ''
      ),

    address_line2 =
      nullif(
        trim(
          coalesce(
            p_address_line2,
            ''
          )
        ),
        ''
      ),

    city =
      nullif(
        trim(
          coalesce(
            p_city,
            ''
          )
        ),
        ''
      ),

    state =
      nullif(
        trim(
          coalesce(
            p_state,
            ''
          )
        ),
        ''
      ),

    postal_code =
      nullif(
        trim(
          coalesce(
            p_postal_code,
            ''
          )
        ),
        ''
      ),

    country =
      coalesce(
        nullif(
          trim(
            coalesce(
              p_country,
              ''
            )
          ),
          ''
        ),
        'India'
      ),

    credit_limit =
      p_credit_limit,

    notes =
      nullif(
        trim(
          coalesce(
            p_notes,
            ''
          )
        ),
        ''
      ),

    status =
      p_status

  where id = p_customer_id
    and tenant_id = p_tenant_id;

end;
$$;


--
-- Name: dashboard_business_intelligence_v500(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dashboard_business_intelligence_v500(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_day date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare sales_taxable numeric:=0;returns_taxable numeric:=0;sales_cost numeric:=0;return_cost numeric:=0;expenses numeric:=0;receivable numeric:=0;payable numeric:=0;cash_bank numeric:=0;low_stock bigint:=0;dead_stock bigint:=0;best jsonb:='[]';slow jsonb:='[]';stores jsonb:='[]';pos jsonb:='[]';hourly jsonb:='[]';daily jsonb:='[]';monthly jsonb:='[]';begin if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;select coalesce(sum(s.taxable_total),0),coalesce(sum(s.cost_total),0) into sales_taxable,sales_cost from public.sales s left join public.document_origins o on o.tenant_id=s.tenant_id and o.entity_type='sale' and o.entity_id=s.id where s.tenant_id=p_tenant_id and s.sale_date=p_day and coalesce(s.status,'') not in('void','cancelled') and (p_location_id is null or o.location_id=p_location_id);select coalesce(sum(subtotal),0) into returns_taxable from public.sales_returns where tenant_id=p_tenant_id and return_date=p_day and refund_status<>'waived' and (p_location_id is null or location_id=p_location_id);select coalesce(sum(ri.quantity*coalesce(si.unit_cost,0)),0) into return_cost from public.sales_return_items ri join public.sales_returns r on r.id=ri.sales_return_id join public.sale_items si on si.id=ri.sale_item_id where r.tenant_id=p_tenant_id and r.return_date=p_day and r.refund_status<>'waived' and (p_location_id is null or r.location_id=p_location_id);select coalesce(sum(e.total_amount),0) into expenses from public.expenses e left join public.document_origins o on o.tenant_id=e.tenant_id and o.entity_type='expense' and o.entity_id=e.id where e.tenant_id=p_tenant_id and e.expense_date=p_day and e.status='posted' and (p_location_id is null or o.location_id=p_location_id);select coalesce(sum(total_outstanding),0) into receivable from public.customer_credit_intelligence_v480(p_tenant_id,p_location_id,'',5000);select coalesce(sum(total_outstanding),0) into payable from public.supplier_payables_intelligence_v480(p_tenant_id,p_location_id,'',5000);select coalesce(sum(case when a.account_type='asset' then l.debit-l.credit else 0 end),0) into cash_bank from public.accounting_accounts a join public.journal_lines l on l.account_id=a.id join public.journal_entries j on j.id=l.journal_entry_id and j.status='posted' and j.tenant_id=p_tenant_id where a.tenant_id=p_tenant_id and a.system_key in('cash','bank','upi','card') and (p_location_id is null or j.location_id is null or j.location_id=p_location_id);select count(*) filter(where status in('low_stock','out_of_stock')),count(*) filter(where status='dead_stock') into low_stock,dead_stock from public.inventory_intelligence_v480(p_tenant_id,p_location_id,30,'',5000);select coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) into best from (select pr.name product_name,sum(si.quantity) quantity,round(sum(si.taxable_amount),2) sales_value from public.sale_items si join public.sales s on s.id=si.sale_id join public.product_variants pv on pv.id=si.variant_id join public.products pr on pr.id=pv.product_id left join public.document_origins o on o.tenant_id=s.tenant_id and o.entity_type='sale' and o.entity_id=s.id where s.tenant_id=p_tenant_id and s.sale_date between p_day-29 and p_day and coalesce(s.status,'') not in('void','cancelled') and (p_location_id is null or o.location_id=p_location_id) group by pr.id,pr.name order by quantity desc limit 10)q;select coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) into slow from (select product_name,sku,available,last_sale_date,case when last_sale_date is null then null else p_day-last_sale_date end days_since_last_sale,status from public.inventory_intelligence_v480(p_tenant_id,p_location_id,30,'',5000) where status in('slow_moving','dead_stock') order by last_sale_date nulls first limit 10)q;select coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) into stores from (select l.id location_id,l.name,round(coalesce(sum(s.taxable_total),0),2) net_sales from public.business_locations l left join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='sale' and o.location_id=l.id left join public.sales s on s.id=o.entity_id and s.tenant_id=p_tenant_id and s.sale_date=p_day and coalesce(s.status,'') not in('void','cancelled') where l.tenant_id=p_tenant_id group by l.id,l.name order by net_sales desc)q;select coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) into pos from (select d.id device_id,coalesce(d.device_code,d.name) device,round(coalesce(sum(s.taxable_total),0),2) net_sales,count(s.id) invoices from public.business_devices d left join public.document_origins o on o.tenant_id=p_tenant_id and o.device_id=d.id and o.entity_type='sale' left join public.sales s on s.id=o.entity_id and s.sale_date=p_day and coalesce(s.status,'') not in('void','cancelled') where d.tenant_id=p_tenant_id and d.app_type='pos' and (p_location_id is null or d.location_id=p_location_id) group by d.id,d.device_code,d.name order by net_sales desc)q;select coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) into hourly from (select date_part('hour',s.created_at)::int hour_of_day,round(sum(s.taxable_total),2) sales from public.sales s left join public.document_origins o on o.tenant_id=s.tenant_id and o.entity_type='sale' and o.entity_id=s.id where s.tenant_id=p_tenant_id and s.sale_date=p_day and coalesce(s.status,'') not in('void','cancelled') and (p_location_id is null or o.location_id=p_location_id) group by 1 order by 1)q;select coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) into daily from (select s.sale_date day_key,round(sum(s.taxable_total),2) sales from public.sales s left join public.document_origins o on o.tenant_id=s.tenant_id and o.entity_type='sale' and o.entity_id=s.id where s.tenant_id=p_tenant_id and s.sale_date between p_day-29 and p_day and coalesce(s.status,'') not in('void','cancelled') and (p_location_id is null or o.location_id=p_location_id) group by s.sale_date order by s.sale_date)q;select coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) into monthly from (select date_trunc('month',s.sale_date)::date month_start,round(sum(s.taxable_total),2) sales from public.sales s left join public.document_origins o on o.tenant_id=s.tenant_id and o.entity_type='sale' and o.entity_id=s.id where s.tenant_id=p_tenant_id and s.sale_date>=date_trunc('month',p_day)::date-interval '11 months' and s.sale_date<=p_day and coalesce(s.status,'') not in('void','cancelled') and (p_location_id is null or o.location_id=p_location_id) group by 1 order by 1)q;return jsonb_build_object('day',p_day,'net_sales',round(sales_taxable-returns_taxable,2),'gross_profit',round((sales_taxable-returns_taxable)-(sales_cost-return_cost),2),'gross_margin_pct',case when sales_taxable-returns_taxable>0 then round(((sales_taxable-returns_taxable)-(sales_cost-return_cost))*100/(sales_taxable-returns_taxable),2) else 0 end,'expenses',round(expenses,2),'estimated_profit',round((sales_taxable-returns_taxable)-(sales_cost-return_cost)-expenses,2),'cash_bank',round(cash_bank,2),'receivables',round(receivable,2),'payables',round(payable,2),'low_stock_count',low_stock,'dead_stock_count',dead_stock,'best_sellers',best,'slow_dead_stock',slow,'store_comparison',stores,'pos_comparison',pos,'hourly_sales',hourly,'daily_sales',daily,'monthly_sales',monthly);end $$;


--
-- Name: dashboard_get_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dashboard_get_summary(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_today_sales numeric:=0; v_month_sales numeric:=0; v_month_purchases numeric:=0; v_month_expenses numeric:=0;
  v_month_gp numeric:=0; v_receivables numeric:=0; v_payables numeric:=0; v_low int:=0; v_products int:=0; v_customers int:=0; v_suppliers int:=0;
  v_start date:=date_trunc('month',current_date)::date;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;

  select coalesce(sum(grand_total),0) into v_today_sales from public.sales where tenant_id=p_tenant_id and sale_date=current_date and coalesce(status,'')<>'cancelled';
  select coalesce(sum(grand_total),0),coalesce(sum(gross_profit),0) into v_month_sales,v_month_gp from public.sales where tenant_id=p_tenant_id and sale_date between v_start and current_date and coalesce(status,'')<>'cancelled';
  select coalesce(sum(grand_total),0) into v_month_purchases from public.purchases where tenant_id=p_tenant_id and purchase_date between v_start and current_date and coalesce(status,'')<>'cancelled';
  if to_regclass('public.expenses') is not null then select coalesce(sum(total_amount),0) into v_month_expenses from public.expenses where tenant_id=p_tenant_id and expense_date between v_start and current_date and status='posted'; end if;

  select coalesce(sum(greatest(s.grand_total-coalesce(p.paid,0),0)),0) into v_receivables
  from public.sales s left join (select sale_id,sum(amount) paid from public.sale_payments group by sale_id) p on p.sale_id=s.id
  where s.tenant_id=p_tenant_id and coalesce(s.status,'')<>'cancelled';
  select coalesce(sum(greatest(pu.grand_total-coalesce(py.paid,0),0)),0) into v_payables
  from public.purchases pu left join (select purchase_id,sum(amount) paid from public.purchase_payments group by purchase_id) py on py.purchase_id=pu.id
  where pu.tenant_id=p_tenant_id and coalesce(pu.status,'')<>'cancelled';

  select count(*) into v_products from public.products where tenant_id=p_tenant_id and coalesce(status,'active')='active';
  select count(*) into v_customers from public.customers where tenant_id=p_tenant_id and coalesce(status,'active')='active';
  select count(*) into v_suppliers from public.suppliers where tenant_id=p_tenant_id and coalesce(status,'active')='active';
  select count(*) into v_low from public.stock_balances sb join public.product_variants pv on pv.id=sb.variant_id
    where sb.tenant_id=p_tenant_id and sb.quantity <= coalesce(pv.reorder_level,0) and coalesce(pv.reorder_level,0)>0;

  return jsonb_build_object(
    'today_sales',v_today_sales,'month_sales',v_month_sales,'month_purchases',v_month_purchases,
    'month_expenses',v_month_expenses,'month_gross_profit',v_month_gp,'month_net_profit',v_month_gp-v_month_expenses,
    'receivables',v_receivables,'payables',v_payables,'low_stock_count',v_low,'product_count',v_products,
    'customer_count',v_customers,'supplier_count',v_suppliers
  );
end $$;


--
-- Name: dashboard_get_summary_v32(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dashboard_get_summary_v32(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare
  v_today_sales numeric:=0;v_month_sales numeric:=0;v_month_purchases numeric:=0;v_month_expenses numeric:=0;v_month_gp numeric:=0;
  v_receivables numeric:=0;v_payables numeric:=0;v_low int:=0;v_products int:=0;v_customers int:=0;v_suppliers int:=0;
  v_start date:=date_trunc('month',current_date)::date;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  select coalesce(sum(s.grand_total),0) into v_today_sales from public.sales s left join public.document_origins o on o.entity_type='sale' and o.entity_id=s.id
    where s.tenant_id=p_tenant_id and s.sale_date=current_date and coalesce(s.status,'') not in ('cancelled','void') and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view');
  select coalesce(sum(s.grand_total),0),coalesce(sum(s.gross_profit),0) into v_month_sales,v_month_gp from public.sales s left join public.document_origins o on o.entity_type='sale' and o.entity_id=s.id
    where s.tenant_id=p_tenant_id and s.sale_date between v_start and current_date and coalesce(s.status,'') not in ('cancelled','void') and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view');
  select coalesce(sum(p.grand_total),0) into v_month_purchases from public.purchases p left join public.document_origins o on o.entity_type='purchase' and o.entity_id=p.id
    where p.tenant_id=p_tenant_id and p.purchase_date between v_start and current_date and coalesce(p.status,'') not in ('cancelled','void') and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view');
  select coalesce(sum(e.total_amount),0) into v_month_expenses from public.expenses e left join public.document_origins o on o.entity_type='expense' and o.entity_id=e.id
    where e.tenant_id=p_tenant_id and e.expense_date between v_start and current_date and e.status='posted' and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view');
  select coalesce(sum(greatest(s.grand_total-coalesce(py.paid,0),0)),0) into v_receivables from public.sales s
    left join (select sale_id,sum(amount) paid from public.sale_payments group by sale_id)py on py.sale_id=s.id
    left join public.document_origins o on o.entity_type='sale' and o.entity_id=s.id
    where s.tenant_id=p_tenant_id and coalesce(s.status,'') not in ('cancelled','void') and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view');
  select coalesce(sum(greatest(p.grand_total-coalesce(py.paid,0),0)),0) into v_payables from public.purchases p
    left join (select purchase_id,sum(amount) paid from public.purchase_payments group by purchase_id)py on py.purchase_id=p.id
    left join public.document_origins o on o.entity_type='purchase' and o.entity_id=p.id
    where p.tenant_id=p_tenant_id and coalesce(p.status,'') not in ('cancelled','void') and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view');
  -- Master/product counts and stock warning remain tenant-wide until physical branch stock RPCs are upgraded.
  select count(*) into v_products from public.products where tenant_id=p_tenant_id and coalesce(status,'active')='active';
  select count(*) into v_customers from public.customers where tenant_id=p_tenant_id and coalesce(status,'active')='active';
  select count(*) into v_suppliers from public.suppliers where tenant_id=p_tenant_id and coalesce(status,'active')='active';
  select count(*) into v_low from public.stock_balances sb join public.product_variants pv on pv.id=sb.variant_id where sb.tenant_id=p_tenant_id and sb.quantity<=coalesce(pv.reorder_level,0) and coalesce(pv.reorder_level,0)>0;
  return jsonb_build_object('today_sales',v_today_sales,'month_sales',v_month_sales,'month_purchases',v_month_purchases,'month_expenses',v_month_expenses,
    'month_gross_profit',v_month_gp,'month_net_profit',v_month_gp-v_month_expenses,'receivables',v_receivables,'payables',v_payables,
    'low_stock_count',v_low,'product_count',v_products,'customer_count',v_customers,'supplier_count',v_suppliers,'stock_scope','business');
end $$;


--
-- Name: dashboard_get_summary_v4(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dashboard_get_summary_v4(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v jsonb;v_low integer:=0;v_products integer:=0;v_receivables numeric:=0;v_payables numeric:=0;
  v_today_returns numeric:=0;v_month_returns numeric:=0;v_month_purchase_returns numeric:=0;v_start date:=date_trunc('month',current_date)::date;
begin
  select public.dashboard_get_summary_v32(p_tenant_id,p_location_id) into v;

  select count(*) into v_products
  from public.location_product_settings s join public.business_locations l on l.id=s.location_id
  where s.tenant_id=p_tenant_id and s.active and l.active and (p_location_id is null or s.location_id=p_location_id)
    and private.erp_document_scope_allowed(p_tenant_id,s.location_id,p_location_id,'view');

  select count(*) into v_low
  from public.location_product_settings s join public.product_variants pv on pv.id=s.variant_id join public.business_locations l on l.id=s.location_id
  left join public.location_stock_balances b on b.tenant_id=s.tenant_id and b.location_id=s.location_id and b.variant_id=s.variant_id
  where s.tenant_id=p_tenant_id and s.active and l.active and (p_location_id is null or s.location_id=p_location_id)
    and private.erp_document_scope_allowed(p_tenant_id,s.location_id,p_location_id,'view')
    and coalesce(s.reorder_level,pv.reorder_level,0)>0 and coalesce(b.quantity,0)<=coalesce(s.reorder_level,pv.reorder_level,0);

  select coalesce(sum(r.grand_total),0) into v_today_returns from public.sales_returns r
  where r.tenant_id=p_tenant_id and r.return_date=current_date and r.refund_status<>'waived'
    and private.erp_document_scope_allowed(p_tenant_id,r.location_id,p_location_id,'view');
  select coalesce(sum(r.grand_total),0) into v_month_returns from public.sales_returns r
  where r.tenant_id=p_tenant_id and r.return_date between v_start and current_date and r.refund_status<>'waived'
    and private.erp_document_scope_allowed(p_tenant_id,r.location_id,p_location_id,'view');
  select coalesce(sum(r.grand_total),0) into v_month_purchase_returns from public.purchase_returns r
  where r.tenant_id=p_tenant_id and r.return_date between v_start and current_date and r.credit_status<>'waived'
    and private.erp_document_scope_allowed(p_tenant_id,r.location_id,p_location_id,'view');

  select coalesce(sum(greatest(s.grand_total-coalesce(py.paid,0)-coalesce(rt.returned,0),0)),0) into v_receivables
  from public.sales s
  left join (select sale_id,sum(amount) paid from public.sale_payments group by sale_id) py on py.sale_id=s.id
  left join (select sale_id,sum(grand_total) returned from public.sales_returns where refund_status<>'waived' group by sale_id) rt on rt.sale_id=s.id
  left join public.document_origins o on o.entity_type='sale' and o.entity_id=s.id
  where s.tenant_id=p_tenant_id and coalesce(s.status,'') not in('cancelled','void') and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view');

  select coalesce(sum(greatest(p.grand_total-coalesce(py.paid,0)-coalesce(rt.returned,0),0)),0) into v_payables
  from public.purchases p
  left join (select purchase_id,sum(amount) paid from public.purchase_payments group by purchase_id) py on py.purchase_id=p.id
  left join (select purchase_id,sum(grand_total) returned from public.purchase_returns where credit_status<>'waived' group by purchase_id) rt on rt.purchase_id=p.id
  left join public.document_origins o on o.entity_type='purchase' and o.entity_id=p.id
  where p.tenant_id=p_tenant_id and coalesce(p.status,'') not in('cancelled','void') and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view');

  return coalesce(v,'{}'::jsonb)||jsonb_build_object(
    'today_sales',greatest(coalesce((v->>'today_sales')::numeric,0)-v_today_returns,0),
    'month_sales',greatest(coalesce((v->>'month_sales')::numeric,0)-v_month_returns,0),
    'month_purchases',greatest(coalesce((v->>'month_purchases')::numeric,0)-v_month_purchase_returns,0),
    'receivables',v_receivables,'payables',v_payables,'product_count',v_products,'low_stock_count',v_low,
    'sales_returns_month',v_month_returns,'purchase_returns_month',v_month_purchase_returns
  );
end $$;


--
-- Name: dashboard_v3_insights(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dashboard_v3_insights(p_tenant_id uuid, p_from_date date DEFAULT ((CURRENT_DATE - '29 days'::interval))::date, p_to_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_top_products jsonb;v_top_customers jsonb;v_daily jsonb; begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('variant_id',variant_id,'product_name',product_name,'quantity',qty,'sales',sales) order by sales desc),'[]'::jsonb) into v_top_products from (
    select si.variant_id,max(coalesce(p.name,'Product')) product_name,sum(si.quantity)::numeric qty,sum(si.line_total)::numeric sales
    from public.sale_items si join public.sales s on s.id=si.sale_id left join public.product_variants pv on pv.id=si.variant_id left join public.products p on p.id=pv.product_id
    where s.tenant_id=p_tenant_id and s.sale_date between p_from_date and p_to_date and coalesce(s.status,'') not in ('cancelled','void') group by si.variant_id order by sales desc limit 10
  ) x;
  select coalesce(jsonb_agg(jsonb_build_object('customer_id',customer_id,'customer_name',customer_name,'sales',sales,'invoice_count',invoice_count) order by sales desc),'[]'::jsonb) into v_top_customers from (
    select s.customer_id,max(c.name) customer_name,sum(s.grand_total)::numeric sales,count(*)::int invoice_count from public.sales s join public.customers c on c.id=s.customer_id where s.tenant_id=p_tenant_id and s.sale_date between p_from_date and p_to_date and coalesce(s.status,'') not in ('cancelled','void') group by s.customer_id order by sales desc limit 10
  ) x;
  select coalesce(jsonb_agg(jsonb_build_object('date',d.day,'sales',coalesce(x.sales,0)) order by d.day),'[]'::jsonb) into v_daily from generate_series(p_from_date::timestamp,p_to_date::timestamp,interval '1 day') d(day) left join (select sale_date,sum(grand_total)::numeric sales from public.sales where tenant_id=p_tenant_id and sale_date between p_from_date and p_to_date and coalesce(status,'') not in ('cancelled','void') group by sale_date)x on x.sale_date=d.day::date;
  return jsonb_build_object('top_products',v_top_products,'top_customers',v_top_customers,'daily_sales',v_daily);
end $$;


--
-- Name: dashboard_v3_insights_v32(uuid, uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dashboard_v3_insights_v32(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_from_date date DEFAULT ((CURRENT_DATE - '29 days'::interval))::date, p_to_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_top_products jsonb;v_top_customers jsonb;v_daily jsonb;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  select coalesce(jsonb_agg(jsonb_build_object('variant_id',variant_id,'product_name',product_name,'quantity',qty,'sales',sales) order by sales desc),'[]'::jsonb) into v_top_products from (
    select si.variant_id,max(coalesce(pr.name,'Product')) product_name,sum(si.quantity)::numeric qty,sum(si.line_total)::numeric sales
    from public.sale_items si join public.sales s on s.id=si.sale_id left join public.product_variants pv on pv.id=si.variant_id left join public.products pr on pr.id=pv.product_id
    left join public.document_origins o on o.entity_type='sale' and o.entity_id=s.id
    where s.tenant_id=p_tenant_id and s.sale_date between p_from_date and p_to_date and coalesce(s.status,'') not in ('cancelled','void') and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view')
    group by si.variant_id order by sales desc limit 10
  )x;
  select coalesce(jsonb_agg(jsonb_build_object('customer_id',customer_id,'customer_name',customer_name,'sales',sales,'invoice_count',invoice_count) order by sales desc),'[]'::jsonb) into v_top_customers from (
    select s.customer_id,max(c.name) customer_name,sum(s.grand_total)::numeric sales,count(*)::int invoice_count from public.sales s join public.customers c on c.id=s.customer_id
    left join public.document_origins o on o.entity_type='sale' and o.entity_id=s.id
    where s.tenant_id=p_tenant_id and s.sale_date between p_from_date and p_to_date and coalesce(s.status,'') not in ('cancelled','void') and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view')
    group by s.customer_id order by sales desc limit 10
  )x;
  select coalesce(jsonb_agg(jsonb_build_object('date',d.day,'sales',coalesce(x.sales,0)) order by d.day),'[]'::jsonb) into v_daily
  from generate_series(p_from_date::timestamp,p_to_date::timestamp,interval '1 day')d(day)
  left join (
    select s.sale_date,sum(s.grand_total)::numeric sales from public.sales s left join public.document_origins o on o.entity_type='sale' and o.entity_id=s.id
    where s.tenant_id=p_tenant_id and s.sale_date between p_from_date and p_to_date and coalesce(s.status,'') not in ('cancelled','void') and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view') group by s.sale_date
  )x on x.sale_date=d.day::date;
  return jsonb_build_object('top_products',v_top_products,'top_customers',v_top_customers,'daily_sales',v_daily);
end $$;


--
-- Name: device_heartbeat_v4(uuid, uuid, text, text, text, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.device_heartbeat_v4(p_tenant_id uuid, p_device_id uuid, p_app_key text, p_platform text, p_version text, p_build integer, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_latest record;v_installation text;begin
  select installation_id into v_installation from public.business_devices
  where id=p_device_id and tenant_id=p_tenant_id and status='active';
  if v_installation is null then raise exception 'System installation is not active';end if;

  update public.business_devices set last_seen_at=now() where id=p_device_id;
  update public.system_installations
  set last_seen_at=now(),platform_hint=coalesce(nullif(trim(p_platform),''),platform_hint),app_version=nullif(trim(coalesce(p_version,'')),'')
  where tenant_id=p_tenant_id and system_id=p_device_id and installation_id=v_installation and status='active';

  insert into public.device_app_status(device_id,tenant_id,app_key,platform,version,build_number,last_seen_at,metadata)
  values(p_device_id,p_tenant_id,p_app_key,p_platform,p_version,coalesce(p_build,0),now(),coalesce(p_metadata,'{}'::jsonb))
  on conflict(device_id) do update set app_key=excluded.app_key,platform=excluded.platform,version=excluded.version,build_number=excluded.build_number,last_seen_at=now(),metadata=excluded.metadata;

  select * into v_latest from public.platform_app_releases
  where app_key=p_app_key and platform=p_platform and status='stable' order by released_at desc limit 1;
  return jsonb_build_object(
    'latest_version',v_latest.version,'mandatory',coalesce(v_latest.mandatory,false),
    'status',case when v_latest.version is null or v_latest.version=p_version then 'latest' when coalesce(v_latest.mandatory,false) then 'update_required' else 'update_available' end,
    'release_notes',v_latest.release_notes,'download_url',v_latest.download_url,
    'backend',public.thq_backend_contract_v47()
  );
end $$;


--
-- Name: division_overview_v44(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.division_overview_v44(p_main_tenant_id uuid, p_from date, p_to date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_div uuid;v_name text;v_rows jsonb;v_sales numeric:=0;v_purchases numeric:=0;v_expenses numeric:=0;v_receivables numeric:=0;v_payables numeric:=0;
begin
  if not private.erp_user_has_tenant_access(p_main_tenant_id) then raise exception 'Access denied';end if;
  if not private.erp_user_is_owner(p_main_tenant_id) and not private.erp_has_permission(p_main_tenant_id,'division.view') then raise exception 'Division permission required';end if;
  select d.id,d.name into v_div,v_name from public.business_divisions d where d.main_tenant_id=p_main_tenant_id and d.active;
  if v_div is null then return jsonb_build_object('has_division',false,'businesses','[]'::jsonb);end if;

  with members as (
    select dm.tenant_id,dm.member_type,t.name,t.slug
    from public.business_division_members dm join public.tenants t on t.id=dm.tenant_id
    where dm.division_id=v_div
  ), totals as (
    select m.*,
      coalesce((select sum(s.grand_total) from public.sales s where s.tenant_id=m.tenant_id and s.sale_date between p_from and p_to and coalesce(s.status,'') not in('void','cancelled')),0)::numeric sales,
      coalesce((select sum(p.grand_total) from public.purchases p where p.tenant_id=m.tenant_id and p.purchase_date between p_from and p_to and coalesce(p.status,'') not in('void','cancelled')),0)::numeric purchases,
      coalesce((select sum(e.total_amount) from public.expenses e where e.tenant_id=m.tenant_id and e.expense_date between p_from and p_to and coalesce(e.status,'') not in('void','cancelled')),0)::numeric expenses,
      coalesce((select sum(greatest(s.grand_total-coalesce((select sum(sp.amount) from public.sale_payments sp where sp.sale_id=s.id),0),0)) from public.sales s where s.tenant_id=m.tenant_id and coalesce(s.status,'') not in('void','cancelled')),0)::numeric receivables,
      coalesce((select sum(greatest(p.grand_total-coalesce((select sum(pp.amount) from public.purchase_payments pp where pp.purchase_id=p.id),0),0)) from public.purchases p where p.tenant_id=m.tenant_id and coalesce(p.status,'') not in('void','cancelled')),0)::numeric payables
    from members m
  )
  select coalesce(jsonb_agg(jsonb_build_object('tenant_id',tenant_id,'name',name,'slug',slug,'member_type',member_type,'sales',sales,'purchases',purchases,'expenses',expenses,'receivables',receivables,'payables',payables) order by case when member_type='main' then 0 else 1 end,name),'[]'::jsonb),
    coalesce(sum(sales),0),coalesce(sum(purchases),0),coalesce(sum(expenses),0),coalesce(sum(receivables),0),coalesce(sum(payables),0)
  into v_rows,v_sales,v_purchases,v_expenses,v_receivables,v_payables from totals;

  return jsonb_build_object('has_division',true,'division_id',v_div,'division_name',v_name,'from',p_from,'to',p_to,
    'sales',v_sales,'purchases',v_purchases,'expenses',v_expenses,'receivables',v_receivables,'payables',v_payables,'businesses',v_rows);
end $$;


--
-- Name: document_origin_attach(uuid, text, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_origin_attach(p_tenant_id uuid, p_entity_type text, p_entity_id uuid, p_location_id uuid, p_device_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if not private.erp_user_location_allowed(p_tenant_id,p_location_id,'operate') then raise exception 'You cannot create records for this location';end if;
  if not exists(select 1 from public.business_locations l where l.id=p_location_id and l.tenant_id=p_tenant_id and l.active) then raise exception 'Invalid business location';end if;
  if p_device_id is not null and not exists(select 1 from public.business_devices d where d.id=p_device_id and d.tenant_id=p_tenant_id and d.status='active') then raise exception 'Invalid device';end if;
  insert into public.document_origins(tenant_id,entity_type,entity_id,location_id,device_id,created_by)
  values(p_tenant_id,p_entity_type,p_entity_id,p_location_id,p_device_id,auth.uid())
  on conflict(entity_type,entity_id) do nothing;
  if p_entity_type in ('sale','purchase','expense') then
    perform private.assign_location_document_number(p_tenant_id,p_location_id,p_entity_type,p_entity_id);
    if p_device_id is not null then perform private.assign_device_document_number(p_tenant_id,p_device_id,p_entity_type,p_entity_id);end if;
  end if;
end $$;


--
-- Name: document_origin_attach_by_reference(uuid, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_origin_attach_by_reference(p_tenant_id uuid, p_entity_type text, p_reference text, p_location_id uuid, p_device_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_id uuid; begin
  if p_entity_type='sale' then select id into v_id from public.sales where tenant_id=p_tenant_id and sale_number=p_reference;
  elsif p_entity_type='purchase' then select id into v_id from public.purchases where tenant_id=p_tenant_id and purchase_number=p_reference;
  elsif p_entity_type='expense' then select id into v_id from public.expenses where tenant_id=p_tenant_id and expense_number=p_reference;
  else raise exception 'Unsupported entity type'; end if;
  if v_id is null then raise exception 'Document not found'; end if;
  perform public.document_origin_attach(p_tenant_id,p_entity_type,v_id,p_location_id,p_device_id);
  return v_id;
end $$;


--
-- Name: document_origin_get(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_origin_get(p_tenant_id uuid, p_entity_type text, p_entity_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v jsonb;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if exists(select 1 from public.document_origins o where o.tenant_id=p_tenant_id and o.entity_type=p_entity_type and o.entity_id=p_entity_id and not private.erp_user_location_allowed(p_tenant_id,o.location_id,'view')) then raise exception 'Location access denied';end if;
  select jsonb_build_object(
    'location_id',o.location_id,'location_name',l.name,'location_code',l.location_code,'location_tracking_code',l.tracking_code,
    'local_number',n.local_number,'terminal_number',dn.terminal_number,'invoice_number',coalesce(dn.terminal_number,n.local_number),
    'gstin',l.gstin,'phone',l.phone,'email',l.email,
    'address_line1',l.address_line1,'address_line2',l.address_line2,'city',l.city,'state',l.state,'postal_code',l.postal_code,'country',l.country,
    'location_settings',coalesce(l.settings,'{}'::jsonb),'location_logo_url',l.settings->>'logo_url',
    'device_id',o.device_id,'device_code',d.device_code,'device_name',d.name,'device_invoice_prefix',d.invoice_prefix,'created_at',o.created_at,
    'created_by',o.created_by
  ) into v
  from public.document_origins o
  left join public.business_locations l on l.id=o.location_id
  left join public.business_devices d on d.id=o.device_id
  left join public.location_document_numbers n on n.entity_type=o.entity_type and n.entity_id=o.entity_id
  left join public.device_document_numbers dn on dn.entity_type=o.entity_type and dn.entity_id=o.entity_id
  where o.tenant_id=p_tenant_id and o.entity_type=p_entity_type and o.entity_id=p_entity_id;
  return v;
end $$;


--
-- Name: document_output_log_v495(uuid, text, text, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_output_log_v495(p_tenant_id uuid, p_output_type text, p_document_type text, p_document_id uuid DEFAULT NULL::uuid, p_reference text DEFAULT NULL::text, p_location_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_id uuid;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if p_output_type not in('print','pdf','xlsx','csv') then raise exception 'Invalid output type';end if;
  insert into public.document_output_events_v495(tenant_id,user_id,location_id,output_type,document_type,document_id,reference)
  values(p_tenant_id,auth.uid(),p_location_id,p_output_type,trim(p_document_type),p_document_id,nullif(trim(coalesce(p_reference,'')),'')) returning id into v_id;
  return v_id;
end $$;


--
-- Name: entity_activity_timeline_v4(uuid, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.entity_activity_timeline_v4(p_tenant_id uuid, p_entity_type text, p_entity_id uuid, p_limit integer DEFAULT 100) RETURNS TABLE(activity_time timestamp with time zone, activity_type text, title text, description text, user_name text, location_code text, device_code text, metadata jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  return query
  select * from (
    select
      a.created_at,
      'audit'::text,
      a.action,
      coalesce(a.entity_reference,a.entity_type,'')::text,
      coalesce(u.username,''),
      coalesce(l.location_code,''),
      coalesce(d.device_code,''),
      coalesce(a.metadata,'{}'::jsonb) || jsonb_build_object('before',a.before_data,'after',a.after_data,'reason',a.reason)
    from public.business_audit_log a
    left join public.user_login_names u on u.user_id=a.user_id
    left join public.business_locations l on l.id=a.location_id
    left join public.business_devices d on d.id=a.device_id
    where a.tenant_id=p_tenant_id and a.entity_type=p_entity_type and a.entity_id=p_entity_id

    union all

    select
      c.created_at,
      'correction'::text,
      c.correction_type,
      c.reason,
      coalesce(u.username,''),
      coalesce(l.location_code,''),
      coalesce(d.device_code,''),
      coalesce(c.metadata,'{}'::jsonb)
    from public.transaction_corrections c
    left join public.user_login_names u on u.user_id=c.created_by
    left join public.document_origins o on o.tenant_id=c.tenant_id and o.entity_type=c.entity_type and o.entity_id=c.entity_id
    left join public.business_locations l on l.id=o.location_id
    left join public.business_devices d on d.id=o.device_id
    where c.tenant_id=p_tenant_id and c.entity_type=p_entity_type and c.entity_id=p_entity_id

    union all

    select
      p.created_at,
      'print'::text,
      p.action,
      coalesce(p.invoice_number,''),
      coalesce(u.username,''),
      coalesce(l.location_code,''),
      coalesce(d.device_code,''),
      jsonb_build_object('copy_number',p.copy_number,'template_id',p.template_id,'printer_profile_id',p.printer_profile_id)
    from public.invoice_print_events p
    left join public.user_login_names u on u.user_id=p.created_by
    left join public.business_devices d on d.id=p.device_id
    left join public.business_locations l on l.id=d.location_id
    where p.tenant_id=p_tenant_id and p.entity_type=p_entity_type and p.entity_id=p_entity_id
  ) x
  order by activity_time desc
  limit greatest(1,least(coalesce(p_limit,100),500));
end $$;


--
-- Name: entity_attachment_register_v4(uuid, text, uuid, text, text, text, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.entity_attachment_register_v4(p_tenant_id uuid, p_entity_type text, p_entity_id uuid, p_file_name text, p_storage_path text, p_mime_type text, p_file_size bigint, p_visibility text DEFAULT 'tenant'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v uuid;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if p_visibility not in('tenant','restricted','private') then raise exception 'Invalid visibility';end if;
  insert into public.entity_attachments(tenant_id,entity_type,entity_id,file_name,storage_path,mime_type,file_size,visibility,uploaded_by)
  values(p_tenant_id,trim(p_entity_type),p_entity_id,trim(p_file_name),trim(p_storage_path),nullif(trim(coalesce(p_mime_type,'')),''),p_file_size,p_visibility,auth.uid()) returning id into v;return v;
end $$;


--
-- Name: entity_attachments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.entity_attachments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    entity_type text NOT NULL,
    entity_id uuid NOT NULL,
    file_name text NOT NULL,
    storage_path text NOT NULL,
    mime_type text,
    file_size bigint,
    visibility text DEFAULT 'tenant'::text NOT NULL,
    uploaded_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT entity_attachments_visibility_check CHECK ((visibility = ANY (ARRAY['tenant'::text, 'restricted'::text, 'private'::text])))
);


--
-- Name: entity_attachments_list_v4(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.entity_attachments_list_v4(p_tenant_id uuid, p_entity_type text, p_entity_id uuid) RETURNS SETOF public.entity_attachments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  return query select * from public.entity_attachments where tenant_id=p_tenant_id and entity_type=p_entity_type and entity_id=p_entity_id order by created_at desc;
end $$;


--
-- Name: entity_public_id_get(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.entity_public_id_get(p_tenant_id uuid, p_entity_type text, p_entity_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v text;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  case p_entity_type
    when 'product' then select tracking_code into v from public.products where tenant_id=p_tenant_id and id=p_entity_id;
    when 'customer' then select tracking_code into v from public.customers where tenant_id=p_tenant_id and id=p_entity_id;
    when 'supplier' then select tracking_code into v from public.suppliers where tenant_id=p_tenant_id and id=p_entity_id;
    when 'sale' then select tracking_code into v from public.sales where tenant_id=p_tenant_id and id=p_entity_id;
    when 'purchase' then select tracking_code into v from public.purchases where tenant_id=p_tenant_id and id=p_entity_id;
    else raise exception 'Unsupported entity type';
  end case;
  return v;
end $$;


--
-- Name: entity_tracking_lookup(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.entity_tracking_lookup(p_tenant_id uuid, p_tracking_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $_$
declare x record;v_result jsonb;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if trim(coalesce(p_tracking_code,''))='' then return null;end if;
  for x in select * from (values
    ('products'),('product_variants'),('inventory_locations'),('customers'),('suppliers'),('purchases'),('sales'),('expenses'),
    ('business_locations'),('business_devices'),('production_recipes'),('production_runs'),('service_vehicles'),('service_jobs'),('restaurant_tables'),('restaurant_orders'),('restaurant_kots')
  ) v(table_name)
  loop
    if to_regclass('public.'||x.table_name) is null then continue;end if;
    if not exists(select 1 from information_schema.columns where table_schema='public' and table_name=x.table_name and column_name='tracking_code') then continue;end if;
    if not exists(select 1 from information_schema.columns where table_schema='public' and table_name=x.table_name and column_name='tenant_id') then continue;end if;
    execute format('select jsonb_build_object(''entity_type'',%L,''id'',id,''tracking_code'',tracking_code) from public.%I where tenant_id=$1 and upper(tracking_code)=upper($2) limit 1',x.table_name,x.table_name)
    into v_result using p_tenant_id,p_tracking_code;
    if v_result is not null then return v_result;end if;
  end loop;
  return null;
end $_$;


--
-- Name: erp_runtime_health_v489(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.erp_runtime_health_v489(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_required_functions text[]:=array[
    'current_user_is_platform_admin',
    'customers_create','customers_update','suppliers_create','suppliers_update',
    'inventory_list_products','inventory_get_product_detail','inventory_create_product','inventory_update_product',
    'platform_create_business','platform_get_business_modules','platform_get_business_permissions',
    'platform_get_business_roles','platform_list_modules','platform_update_role_permissions',
    'sales_create_v489','purchases_create_v489','expenses_create_v489','expenses_update_v489',
    'inventory_product_units_v481','inventory_product_units_save_v481','pricing_resolve_v482',
    'purchase_invoice_create_v489','purchase_invoice_post_v484','purchase_order_decide_v484','operations_pipeline_v489',
    'sales_add_payment_v47','restaurant_order_create_v32','restaurant_order_bill_v489','restaurant_operations_summary_v489','pos_offline_sale_sync_v486',
    'mobile_client_context_v487','mobile_client_dashboard_v487','mobile_approvals_v487','mobile_customer_payment_v487',
    'mobile_pos_terminal_context_v488','mobile_pos_sale_sync_v488','mobile_pos_cache_manifest_v488','mobile_pos_sync_status_v488',
    'thq_backend_contract_v47','thq_api_contract_v480'
  ];
  v_required_tables text[]:=array[
    'tenants','tenant_memberships','tenant_modules','tenant_settings','modules','roles','role_permissions','user_roles',
    'products','product_variants','customers','suppliers',
    'sales','sale_items','purchases','purchase_items','expenses','business_locations','business_devices',
    'inventory_units_v481','product_units_v481','price_lists_v482','restaurant_orders','restaurant_order_items',
    'purchase_invoices_v484','pos_offline_sync_v486','thq_schema_releases'
  ];
  v_missing_functions text[]:='{}'::text[];v_missing_tables text[]:='{}'::text[];
  v text;v_release jsonb;v_pipeline jsonb:='{}'::jsonb;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  foreach v in array v_required_functions loop
    if not exists(
      select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
      where n.nspname='public' and p.proname=v
    ) then v_missing_functions:=array_append(v_missing_functions,v);end if;
  end loop;
  foreach v in array v_required_tables loop
    if to_regclass('public.'||v) is null then v_missing_tables:=array_append(v_missing_tables,v);end if;
  end loop;
  select jsonb_build_object(
    'schema_version',schema_version,'migration_no',migration_no,'release_name',release_name
  ) into v_release from public.thq_schema_releases order by migration_no desc limit 1;
  if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='operations_pipeline_v489') then
    begin v_pipeline:=public.operations_pipeline_v489(p_tenant_id,null); exception when others then v_pipeline:=jsonb_build_object('error',sqlerrm);end;
  end if;
  return jsonb_build_object(
    'ready',cardinality(v_missing_functions)=0 and cardinality(v_missing_tables)=0,
    'missing_functions',to_jsonb(v_missing_functions),'missing_tables',to_jsonb(v_missing_tables),
    'release',coalesce(v_release,'{}'::jsonb),'operations',v_pipeline,
    'pricing_engine','v4.8.2-authoritative','unit_engine','v4.8.1','tracking_engine','v4.8.3',
    'purchasing_engine','v4.8.4','warehouse_engine','v4.8.5','offline_pos_engine','v4.8.6',
    'client_mobile','v4.8.7','mobile_pos','v4.8.8','stabilization','v4.8.9'
  );
end $$;


--
-- Name: expense_detail_v600(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expense_detail_v600(p_tenant_id uuid, p_expense_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_result jsonb;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then
    raise exception 'Access denied' using errcode='42501';
  end if;
  if not (
    private.erp_user_is_owner(p_tenant_id, auth.uid())
    or private.erp_has_permission(p_tenant_id,'expenses.view')
    or private.erp_has_permission(p_tenant_id,'expenses.edit')
    or private.erp_has_permission(p_tenant_id,'expenses.manage')
  ) then
    raise exception 'Expense view permission required' using errcode='42501';
  end if;

  select jsonb_build_object(
    'expense', jsonb_build_object(
      'id',e.id,'expense_number',e.expense_number,'expense_date',e.expense_date,
      'category_id',e.category_id,'category_name',c.name,'payee',e.payee,
      'description',e.description,'amount',e.amount,'tax_amount',e.tax_amount,
      'round_off',coalesce(e.round_off,0),'total_amount',e.total_amount,
      'payment_method',e.payment_method,'reference_number',e.reference_number,
      'notes',e.notes,'status',e.status,'created_at',e.created_at,'updated_at',e.updated_at,
      'tracking_code',e.tracking_code
    ),
    'origin', jsonb_build_object(
      'location_id',o.location_id,'location_name',l.name,'device_id',o.device_id,
      'device_name',d.name,'device_code',d.device_code,'created_by',o.created_by,'created_at',o.created_at
    ),
    'journals', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',j.id,'entry_number',j.entry_number,'entry_date',j.entry_date,
        'description',j.description,'status',j.status,'source_reference',j.source_reference,
        'created_at',j.created_at,'posted_at',j.posted_at
      ) order by j.created_at)
      from public.journal_entries j
      where j.tenant_id=e.tenant_id and j.source_type='expense' and j.source_id=e.id
    ),'[]'::jsonb),
    'history', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',h.id,'action',h.action,'reason',h.reason,'changed_by',h.changed_by,
        'changed_at',h.changed_at,'before',h.before_data,'after',h.after_data
      ) order by h.changed_at desc)
      from public.expense_change_history_v600 h
      where h.tenant_id=e.tenant_id and h.expense_id=e.id
    ),'[]'::jsonb)
  ) into v_result
  from public.expenses e
  join public.expense_categories c on c.id=e.category_id
  left join public.document_origins o on o.tenant_id=e.tenant_id and o.entity_type='expense' and o.entity_id=e.id
  left join public.business_locations l on l.id=o.location_id
  left join public.business_devices d on d.id=o.device_id
  where e.tenant_id=p_tenant_id and e.id=p_expense_id;

  if v_result is null then raise exception 'Expense not found'; end if;
  return v_result;
end;
$$;


--
-- Name: expense_summary_v600(uuid, date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expense_summary_v600(p_tenant_id uuid, p_from date, p_to date, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_total numeric := 0;
  v_tax numeric := 0;
  v_count bigint := 0;
  v_categories jsonb := '[]'::jsonb;
  v_methods jsonb := '[]'::jsonb;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then
    raise exception 'Access denied' using errcode='42501';
  end if;
  if p_from is null or p_to is null or p_to < p_from then
    raise exception 'Valid expense date range is required';
  end if;

  select count(*),coalesce(sum(e.total_amount),0),coalesce(sum(e.tax_amount),0)
  into v_count,v_total,v_tax
  from public.expenses e
  left join public.document_origins o on o.tenant_id=e.tenant_id and o.entity_type='expense' and o.entity_id=e.id
  where e.tenant_id=p_tenant_id and e.expense_date between p_from and p_to
    and e.status='posted' and (p_location_id is null or o.location_id=p_location_id);

  select coalesce(jsonb_agg(to_jsonb(x) order by x.total desc),'[]'::jsonb)
  into v_categories
  from (
    select c.id category_id,c.name category_name,count(*) expense_count,
      round(sum(e.total_amount),2) total,round(sum(e.tax_amount),2) tax
    from public.expenses e
    join public.expense_categories c on c.id=e.category_id
    left join public.document_origins o on o.tenant_id=e.tenant_id and o.entity_type='expense' and o.entity_id=e.id
    where e.tenant_id=p_tenant_id and e.expense_date between p_from and p_to
      and e.status='posted' and (p_location_id is null or o.location_id=p_location_id)
    group by c.id,c.name
  ) x;

  select coalesce(jsonb_agg(to_jsonb(x) order by x.total desc),'[]'::jsonb)
  into v_methods
  from (
    select lower(coalesce(e.payment_method,'unknown')) payment_method,count(*) expense_count,
      round(sum(e.total_amount),2) total
    from public.expenses e
    left join public.document_origins o on o.tenant_id=e.tenant_id and o.entity_type='expense' and o.entity_id=e.id
    where e.tenant_id=p_tenant_id and e.expense_date between p_from and p_to
      and e.status='posted' and (p_location_id is null or o.location_id=p_location_id)
    group by 1
  ) x;

  return jsonb_build_object(
    'from',p_from,'to',p_to,'location_id',p_location_id,'expense_count',v_count,
    'total',round(v_total,2),'tax',round(v_tax,2),'net_before_tax',round(v_total-v_tax,2),
    'categories',v_categories,'payment_methods',v_methods
  );
end;
$$;


--
-- Name: expenses_create(uuid, uuid, date, text, text, numeric, numeric, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expenses_create(p_tenant_id uuid, p_category_id uuid, p_expense_date date, p_payee text, p_description text, p_amount numeric, p_tax_amount numeric DEFAULT 0, p_payment_method text DEFAULT 'cash'::text, p_reference_number text DEFAULT ''::text, p_notes text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_no bigint; v_id uuid; v_number text;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  if not private.erp_module_enabled(p_tenant_id,'expenses') then raise exception 'Expenses module is disabled'; end if;
  if not private.erp_has_permission(p_tenant_id,'expenses.manage') then raise exception 'Permission denied'; end if;
  if coalesce(trim(p_description),'')='' then raise exception 'Description is required'; end if;
  if coalesce(p_amount,0)<=0 then raise exception 'Amount must be greater than zero'; end if;
  if coalesce(p_tax_amount,0)<0 then raise exception 'Tax cannot be negative'; end if;
  if not exists(select 1 from public.expense_categories where id=p_category_id and tenant_id=p_tenant_id and active) then raise exception 'Invalid expense category'; end if;

  insert into public.expense_counters(tenant_id,last_number) values(p_tenant_id,1)
  on conflict(tenant_id) do update set last_number=public.expense_counters.last_number+1
  returning last_number into v_no;
  v_number := 'EXP-' || lpad(v_no::text,6,'0');

  insert into public.expenses(tenant_id,expense_number,category_id,expense_date,payee,description,amount,tax_amount,payment_method,reference_number,notes)
  values(p_tenant_id,v_number,p_category_id,coalesce(p_expense_date,current_date),nullif(trim(p_payee),''),trim(p_description),p_amount,coalesce(p_tax_amount,0),coalesce(nullif(trim(p_payment_method),''),'cash'),nullif(trim(p_reference_number),''),nullif(trim(p_notes),''))
  returning id into v_id;

  return jsonb_build_object('expense_id',v_id,'expense_number',v_number);
end $$;


--
-- Name: expenses_create_v32(uuid, uuid, date, text, text, numeric, numeric, text, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expenses_create_v32(p_tenant_id uuid, p_category_id uuid, p_expense_date date, p_payee text, p_description text, p_amount numeric, p_tax_amount numeric, p_payment_method text, p_reference_number text, p_notes text, p_location_id uuid, p_device_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_result jsonb;
  v_ref text;
  v_id uuid;
  v_origin jsonb;
begin
  perform private.erp_validate_transaction_origin(p_tenant_id,p_location_id,p_device_id,'expenses');

  select public.expenses_create(
    p_tenant_id=>p_tenant_id,
    p_category_id=>p_category_id,
    p_expense_date=>p_expense_date,
    p_payee=>p_payee,
    p_description=>p_description,
    p_amount=>p_amount,
    p_tax_amount=>p_tax_amount,
    p_payment_method=>p_payment_method,
    p_reference_number=>p_reference_number,
    p_notes=>p_notes
  ) into v_result;

  v_ref:=coalesce(v_result->>'expense_number',v_result->>'number');
  if nullif(v_ref,'') is null then raise exception 'Expense transaction did not return an expense number'; end if;
  v_id:=public.document_origin_attach_by_reference(p_tenant_id,'expense',v_ref,p_location_id,p_device_id);
  v_origin:=public.document_origin_get(p_tenant_id,'expense',v_id);
  return coalesce(v_result,'{}'::jsonb) || jsonb_build_object(
    'expense_id',coalesce(v_result->>'expense_id',v_id::text),
    'invoice_number',v_origin->>'invoice_number',
    'location_id',p_location_id,
    'device_id',p_device_id
  );
end $$;


--
-- Name: expenses_create_v47(uuid, uuid, date, text, text, numeric, numeric, text, text, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expenses_create_v47(p_tenant_id uuid, p_category_id uuid, p_expense_date date, p_payee text, p_description text, p_amount numeric, p_tax_amount numeric, p_payment_method text, p_reference_number text, p_notes text, p_location_id uuid, p_device_id uuid, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v jsonb;begin
  v:=private.v47_request_existing(p_tenant_id,p_request_id,'expense.create');if v is not null then return v;end if;
  v:=public.expenses_create_v32(p_tenant_id,p_category_id,p_expense_date,p_payee,p_description,p_amount,p_tax_amount,p_payment_method,p_reference_number,p_notes,p_location_id,p_device_id);
  return private.v47_request_complete(p_tenant_id,p_request_id,'expense.create',v);
end$$;


--
-- Name: expenses_create_v489(uuid, uuid, date, text, text, numeric, numeric, numeric, text, text, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expenses_create_v489(p_tenant_id uuid, p_category_id uuid, p_expense_date date, p_payee text, p_description text, p_amount numeric, p_tax_amount numeric, p_round_off numeric, p_payment_method text, p_reference_number text, p_notes text, p_location_id uuid, p_device_id uuid, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v jsonb;v_id uuid;v_round numeric:=round(coalesce(p_round_off,0),2);v_final numeric:=round(coalesce(p_amount,0)+coalesce(p_tax_amount,0)+round(coalesce(p_round_off,0),2),2);v_old_round numeric;
begin
  if abs(v_round)>0.999999 then raise exception 'Round off must be between -1.00 and 1.00';end if;
  if v_final<=0 then raise exception 'Rounded expense total must be positive';end if;
  v:=public.expenses_create_v47(p_tenant_id,p_category_id,p_expense_date,p_payee,p_description,p_amount,p_tax_amount,p_payment_method,p_reference_number,p_notes,p_location_id,p_device_id,p_request_id);
  v_id:=nullif(v->>'expense_id','')::uuid;if v_id is null then return v;end if;
  select round_off into v_old_round from public.expenses where id=v_id and tenant_id=p_tenant_id for update;
  if abs(coalesce(v_old_round,0)-v_round)>0.000001 then
    update public.journal_entries set status='reversed' where tenant_id=p_tenant_id and source_type='expense' and source_id=v_id and status='posted';
    update public.expenses set round_off=v_round,total_amount=v_final where id=v_id and tenant_id=p_tenant_id;
    perform private.v4_accounting_post_document(p_tenant_id,'expense',v_id);
  end if;
  return v||jsonb_build_object('total_amount',v_final,'round_off',v_round,'rounding_engine','v4.8.9');
end $$;


--
-- Name: expenses_list(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expenses_list(p_tenant_id uuid, p_from_date date DEFAULT NULL::date, p_to_date date DEFAULT NULL::date) RETURNS TABLE(expense_id uuid, expense_number text, category_id uuid, category_name text, expense_date date, payee text, description text, amount numeric, tax_amount numeric, total_amount numeric, payment_method text, reference_number text, notes text, status text, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  if not private.erp_module_enabled(p_tenant_id,'expenses') then raise exception 'Expenses module is disabled'; end if;
  return query
  select e.id,e.expense_number,e.category_id,ec.name,e.expense_date,e.payee,e.description,
         e.amount,e.tax_amount,e.total_amount,e.payment_method,e.reference_number,e.notes,e.status,e.created_at
  from public.expenses e join public.expense_categories ec on ec.id=e.category_id
  where e.tenant_id=p_tenant_id
    and (p_from_date is null or e.expense_date>=p_from_date)
    and (p_to_date is null or e.expense_date<=p_to_date)
  order by e.expense_date desc,e.created_at desc;
end $$;


--
-- Name: expenses_list_categories(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expenses_list_categories(p_tenant_id uuid) RETURNS TABLE(category_id uuid, category_name text, active boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  if not private.erp_module_enabled(p_tenant_id,'expenses') then raise exception 'Expenses module is disabled'; end if;
  return query select ec.id, ec.name, ec.active from public.expense_categories ec where ec.tenant_id=p_tenant_id and ec.active order by ec.name;
end $$;


--
-- Name: expenses_list_v32(uuid, uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expenses_list_v32(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_from_date date DEFAULT NULL::date, p_to_date date DEFAULT NULL::date) RETURNS TABLE(expense_id uuid, expense_number text, invoice_number text, category_id uuid, category_name text, expense_date date, payee text, description text, amount numeric, tax_amount numeric, total_amount numeric, payment_method text, reference_number text, notes text, status text, created_at timestamp with time zone, location_id uuid, location_name text, device_id uuid, device_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  return query select e.id,e.expense_number,coalesce(dn.terminal_number,ln.local_number,e.expense_number),e.category_id,c.name,e.expense_date,e.payee,e.description,
    e.amount,e.tax_amount,e.total_amount,e.payment_method,e.reference_number,e.notes,e.status,e.created_at,o.location_id,l.name,o.device_id,d.name
  from public.expenses e join public.expense_categories c on c.id=e.category_id
  left join public.document_origins o on o.entity_type='expense' and o.entity_id=e.id
  left join public.business_locations l on l.id=o.location_id left join public.business_devices d on d.id=o.device_id
  left join public.location_document_numbers ln on ln.entity_type='expense' and ln.entity_id=e.id
  left join public.device_document_numbers dn on dn.entity_type='expense' and dn.entity_id=e.id
  where e.tenant_id=p_tenant_id and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view')
    and (p_from_date is null or e.expense_date>=p_from_date) and (p_to_date is null or e.expense_date<=p_to_date)
  order by e.expense_date desc,e.created_at desc;
end $$;


--
-- Name: expenses_update(uuid, uuid, uuid, date, text, text, numeric, numeric, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expenses_update(p_tenant_id uuid, p_expense_id uuid, p_category_id uuid, p_expense_date date, p_payee text, p_description text, p_amount numeric, p_tax_amount numeric, p_payment_method text, p_reference_number text, p_notes text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb; v_number text;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  if not private.erp_has_permission(p_tenant_id,'expenses.edit') and not private.erp_has_permission(p_tenant_id,'expenses.manage') then raise exception 'Permission denied'; end if;
  select to_jsonb(e),e.expense_number into v_before,v_number from public.expenses e where e.id=p_expense_id and e.tenant_id=p_tenant_id for update;
  if v_before is null then raise exception 'Expense not found'; end if;
  if coalesce((v_before->>'status'),'') <> 'posted' then raise exception 'Only posted expenses can be edited'; end if;
  if not exists(select 1 from public.expense_categories where id=p_category_id and tenant_id=p_tenant_id and active) then raise exception 'Invalid expense category'; end if;
  if coalesce(p_amount,0)<=0 or coalesce(p_tax_amount,0)<0 then raise exception 'Invalid amount'; end if;
  update public.expenses set category_id=p_category_id,expense_date=p_expense_date,payee=nullif(trim(p_payee),''),description=trim(p_description),amount=p_amount,tax_amount=coalesce(p_tax_amount,0),payment_method=coalesce(nullif(trim(p_payment_method),''),'cash'),reference_number=nullif(trim(p_reference_number),''),notes=nullif(trim(p_notes),''),updated_at=now()
  where id=p_expense_id and tenant_id=p_tenant_id;
  select to_jsonb(e) into v_after from public.expenses e where e.id=p_expense_id;
  perform private.business_audit_write(p_tenant_id,'update','expense',p_expense_id,v_number,v_before,v_after);
  return jsonb_build_object('expense_id',p_expense_id,'expense_number',v_number);
end $$;


--
-- Name: expenses_update_v32(uuid, uuid, uuid, date, text, text, numeric, numeric, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expenses_update_v32(p_tenant_id uuid, p_expense_id uuid, p_category_id uuid, p_expense_date date, p_payee text, p_description text, p_amount numeric, p_tax_amount numeric, p_payment_method text, p_reference_number text, p_notes text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_loc uuid;begin
  select location_id into v_loc from public.document_origins where entity_type='expense' and entity_id=p_expense_id and tenant_id=p_tenant_id;
  if not private.erp_document_scope_allowed(p_tenant_id,v_loc,null,'operate') then raise exception 'Location access denied';end if;
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'expenses.edit') then raise exception 'Expense edit permission denied';end if;
  perform public.expenses_update(p_tenant_id,p_expense_id,p_category_id,p_expense_date,p_payee,p_description,p_amount,p_tax_amount,p_payment_method,p_reference_number,p_notes);
end $$;


--
-- Name: expenses_update_v489(uuid, uuid, uuid, date, text, text, numeric, numeric, numeric, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expenses_update_v489(p_tenant_id uuid, p_expense_id uuid, p_category_id uuid, p_expense_date date, p_payee text, p_description text, p_amount numeric, p_tax_amount numeric, p_round_off numeric, p_payment_method text, p_reference_number text, p_notes text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_round numeric:=round(coalesce(p_round_off,0),2);v_loc uuid;
begin
  if abs(v_round)>0.999999 then raise exception 'Round off must be between -1.00 and 1.00';end if;
  select location_id into v_loc from public.document_origins where tenant_id=p_tenant_id and entity_type='expense' and entity_id=p_expense_id;
  if not private.erp_document_scope_allowed(p_tenant_id,v_loc,null,'operate') then raise exception 'Location access denied';end if;
  perform public.expenses_update(p_tenant_id,p_expense_id,p_category_id,p_expense_date,p_payee,p_description,p_amount,p_tax_amount,p_payment_method,p_reference_number,p_notes);
  -- Editing keeps the expense active. Retire the old source journal and post the new
  -- values once; do not leave a posted void-style reversal alongside the replacement.
  update public.journal_entries set status='reversed' where tenant_id=p_tenant_id and source_type='expense' and source_id=p_expense_id and status='posted';
  update public.expenses set round_off=v_round,updated_at=now() where id=p_expense_id and tenant_id=p_tenant_id;
  perform private.v4_accounting_post_document(p_tenant_id,'expense',p_expense_id);
end $$;


--
-- Name: expenses_update_v600(uuid, uuid, uuid, date, text, text, numeric, numeric, numeric, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expenses_update_v600(p_tenant_id uuid, p_expense_id uuid, p_category_id uuid, p_expense_date date, p_payee text, p_description text, p_amount numeric, p_tax_amount numeric, p_round_off numeric, p_payment_method text, p_reference_number text, p_notes text, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then
    raise exception 'Access denied' using errcode='42501';
  end if;
  if not (
    private.erp_user_is_owner(p_tenant_id, auth.uid())
    or private.erp_has_permission(p_tenant_id,'expenses.edit')
    or private.erp_has_permission(p_tenant_id,'expenses.manage')
  ) then
    raise exception 'Expense edit permission required' using errcode='42501';
  end if;
  if nullif(trim(coalesce(p_reason,'')),'') is null then
    raise exception 'Edit reason is required for expense tracking';
  end if;

  perform set_config('thq.expense_change_reason', trim(p_reason), true);
  perform public.expenses_update_v489(
    p_tenant_id,p_expense_id,p_category_id,p_expense_date,p_payee,p_description,
    p_amount,p_tax_amount,p_round_off,p_payment_method,p_reference_number,p_notes
  );
end;
$$;


--
-- Name: explain_metric_contract_v600(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.explain_metric_contract_v600(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) or not private.has_permission(p_tenant_id,'explain.view') then
    raise exception 'Permission denied' using errcode='42501';
  end if;
  return jsonb_build_object(
    'version','6.0.0-build1',
    'metrics',jsonb_build_array(
      jsonb_build_object('key','sales','label','Sales','kind','period','equation','Posted Sales Revenue credits - debits'),
      jsonb_build_object('key','cogs','label','COGS','kind','period','equation','Posted COGS debits - credits'),
      jsonb_build_object('key','gross_profit','label','Gross Profit','kind','period','equation','Sales - COGS'),
      jsonb_build_object('key','net_profit','label','Net Profit','kind','period','equation','Income - COGS - Expenses'),
      jsonb_build_object('key','inventory_value','label','Inventory Value','kind','balance','equation','Inventory Asset debits - credits as of date'),
      jsonb_build_object('key','receivables','label','Receivables','kind','balance','equation','Accounts Receivable debits - credits as of date'),
      jsonb_build_object('key','payables','label','Payables','kind','balance','equation','Accounts Payable credits - debits as of date'),
      jsonb_build_object('key','cash','label','Cash','kind','balance','equation','Cash in Hand debits - credits as of date'),
      jsonb_build_object('key','bank','label','Bank','kind','balance','equation','Bank Account debits - credits as of date'),
      jsonb_build_object('key','gst_payable','label','Net GST Payable','kind','balance','equation','Output/RCM GST liabilities - eligible Input/RCM Input GST assets as of date')
    ),
    'rule','ERP calculates first and explains second. Returned equations/components are derived from posted journals; natural-language text must not alter numeric values.'
  );
end;
$$;


--
-- Name: explain_metric_v600(uuid, text, date, date, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.explain_metric_v600(p_tenant_id uuid, p_metric text, p_from date, p_to date, p_location_id uuid DEFAULT NULL::uuid, p_driver_limit integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_metric text := lower(trim(coalesce(p_metric,'')));
  v_kind text;
  v_label text;
  v_basis text;
  v_equation text;
  v_value numeric := 0;
  v_previous numeric := 0;
  v_change numeric := 0;
  v_driver_sum numeric := 0;
  v_days integer;
  v_prev_from date;
  v_prev_to date;
  curp record; prevp record; curb record; prevb record; d record;
  v_components jsonb := '[]'::jsonb;
  v_drivers jsonb := '[]'::jsonb;
  v_product_drivers jsonb := '[]'::jsonb;
  v_reconciles boolean := true;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) or not private.has_permission(p_tenant_id,'explain.view') then
    raise exception 'Permission denied' using errcode='42501';
  end if;
  if p_from is null or p_to is null or p_to<p_from then raise exception 'Valid from/to dates are required'; end if;
  if v_metric not in ('sales','cogs','gross_profit','net_profit','inventory_value','receivables','payables','cash','bank','gst_payable') then
    raise exception 'Unsupported explain metric %',p_metric;
  end if;

  v_days:=(p_to-p_from)+1; v_prev_to:=p_from-1; v_prev_from:=v_prev_to-(v_days-1);

  if v_metric in ('sales','cogs','gross_profit','net_profit') then
    v_kind:='period';
    select * into curp from private.v600_period_metric_values(p_tenant_id,p_from,p_to,p_location_id);
    select * into prevp from private.v600_period_metric_values(p_tenant_id,v_prev_from,v_prev_to,p_location_id);
    if v_metric='sales' then
      v_label:='Sales'; v_basis:='Posted Sales Revenue journal lines'; v_equation:='Sales Revenue credits - debits'; v_value:=curp.sales_revenue; v_previous:=prevp.sales_revenue;
      v_components:=jsonb_build_array(jsonb_build_object('key','sales_revenue','label','Sales Revenue','value',round(v_value,4),'operator','+'));
    elsif v_metric='cogs' then
      v_label:='COGS'; v_basis:='Posted COGS journal lines'; v_equation:='COGS debits - credits'; v_value:=curp.cogs; v_previous:=prevp.cogs;
      v_components:=jsonb_build_array(jsonb_build_object('key','cogs','label','COGS','value',round(v_value,4),'operator','+'));
    elsif v_metric='gross_profit' then
      v_label:='Gross Profit'; v_basis:='Posted Sales Revenue and COGS journal lines'; v_equation:='Sales - COGS'; v_value:=curp.gross_profit; v_previous:=prevp.gross_profit;
      v_components:=jsonb_build_array(jsonb_build_object('key','sales','label','Sales','value',round(curp.sales_revenue,4),'operator','+'),jsonb_build_object('key','cogs','label','COGS','value',round(curp.cogs,4),'operator','-'));
      v_product_drivers:=private.v600_gp_product_drivers(p_tenant_id,p_from,p_to,v_prev_from,v_prev_to,p_location_id,p_driver_limit);
    else
      v_label:='Net Profit'; v_basis:='All posted Income, COGS and Expense journal lines'; v_equation:='Income - COGS - Expenses'; v_value:=curp.net_profit; v_previous:=prevp.net_profit;
      v_components:=jsonb_build_array(jsonb_build_object('key','income','label','Income','value',round(curp.total_income,4),'operator','+'),jsonb_build_object('key','cogs','label','COGS','value',round(curp.cogs,4),'operator','-'),jsonb_build_object('key','expenses','label','Expenses','value',round(curp.expenses,4),'operator','-'));
    end if;
    select * into d from private.v600_period_source_drivers(p_tenant_id,v_metric,p_from,p_to,v_prev_from,v_prev_to,p_location_id,p_driver_limit);
    v_drivers:=coalesce(d.drivers,'[]'::jsonb); v_driver_sum:=coalesce(d.driver_sum,0); v_change:=v_value-v_previous;
  else
    v_kind:='balance';
    select * into curb from private.v600_balance_metric_values(p_tenant_id,p_to,p_location_id);
    select * into prevb from private.v600_balance_metric_values(p_tenant_id,p_from-1,p_location_id);
    if v_metric='inventory_value' then v_label:='Inventory Value'; v_basis:='Posted Inventory Asset balance'; v_equation:='Inventory Asset debits - credits'; v_value:=curb.inventory_value; v_previous:=prevb.inventory_value;
    elsif v_metric='receivables' then v_label:='Receivables'; v_basis:='Posted Accounts Receivable balance'; v_equation:='AR debits - credits'; v_value:=curb.receivables; v_previous:=prevb.receivables;
    elsif v_metric='payables' then v_label:='Payables'; v_basis:='Posted Accounts Payable balance'; v_equation:='AP credits - debits'; v_value:=curb.payables; v_previous:=prevb.payables;
    elsif v_metric='cash' then v_label:='Cash'; v_basis:='Posted Cash in Hand balance'; v_equation:='Cash debits - credits'; v_value:=curb.cash; v_previous:=prevb.cash;
    elsif v_metric='bank' then v_label:='Bank'; v_basis:='Posted Bank Account balance'; v_equation:='Bank debits - credits'; v_value:=curb.bank; v_previous:=prevb.bank;
    else v_label:='Net GST Payable'; v_basis:='Posted GST component control-account balances'; v_equation:='Output + RCM GST liabilities - Input + RCM Input GST assets'; v_value:=curb.gst_payable; v_previous:=prevb.gst_payable;
    end if;
    v_components:=private.v600_balance_components(p_tenant_id,v_metric,p_to,p_location_id);
    select * into d from private.v600_balance_source_drivers(p_tenant_id,v_metric,p_from,p_to,p_location_id,p_driver_limit);
    v_drivers:=coalesce(d.drivers,'[]'::jsonb); v_driver_sum:=coalesce(d.driver_sum,0); v_change:=v_value-v_previous;
  end if;

  if abs(v_driver_sum-v_change)>0.01 then v_reconciles:=false; end if;
  return jsonb_build_object(
    'metric',v_metric,'label',v_label,'kind',v_kind,'value',round(v_value,4),'basis',v_basis,'equation',v_equation,
    'period',jsonb_build_object('from',p_from,'to',p_to,'location_id',p_location_id),'components',v_components,
    'previous',jsonb_build_object('from',case when v_kind='period' then v_prev_from else null end,'to',case when v_kind='period' then v_prev_to else p_from-1 end,'value',round(v_previous,4)),
    'change',round(v_change,4),'drivers',v_drivers,'product_profit_drivers',v_product_drivers,
    'driver_reconciliation',jsonb_build_object('sum',round(v_driver_sum,4),'expected_change',round(v_change,4),'reconciles',v_reconciles,'note',case when v_reconciles then 'Displayed driver impacts reconcile to the metric change within rounding.' else 'Driver list is limited; hidden smaller drivers account for the remaining change.' end),
    'integrity_rule','Numbers are calculated from posted journal entries first. Explanation text is descriptive only and cannot change the calculation.'
  );
end;
$$;


--
-- Name: finance_controls_summary_v500(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finance_controls_summary_v500(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v_unmatched bigint;v_due bigint;v_open_years bigint;v_banks bigint;begin perform private.v500_accounting_access(p_tenant_id,false);select count(*) into v_unmatched from public.bank_statement_lines_v500 where tenant_id=p_tenant_id and status='unmatched';select count(*) into v_due from public.recurring_expenses_v500 where tenant_id=p_tenant_id and active and next_run_date<=current_date;select count(*) into v_open_years from public.financial_years_v500 where tenant_id=p_tenant_id and status='open';select count(*) into v_banks from public.bank_accounts_v500 where tenant_id=p_tenant_id and active;return jsonb_build_object('unmatched_bank_lines',v_unmatched,'due_recurring_expenses',v_due,'open_financial_years',v_open_years,'active_bank_accounts',v_banks,'reconciliation',public.finance_reconciliation_v500(p_tenant_id));end $$;


--
-- Name: finance_operations_health_v490(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finance_operations_health_v490(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$begin return public.finance_reconciliation_v500(p_tenant_id);end $$;


--
-- Name: finance_reconciliation_v491(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finance_reconciliation_v491(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  unbalanced bigint:=0;
  duplicate_journals bigint:=0;
  missing text[]:='{}';
  sales_missing bigint:=0;
  purchases_missing bigint:=0;
  purchase_invoices_missing bigint:=0;
  expenses_missing bigint:=0;
  sret_missing bigint:=0;
  pret_missing bigint:=0;
  loan_missing bigint:=0;
  sale_overpayments bigint:=0;
  purchase_overpayments bigint:=0;
  purchase_invoice_overpayments bigint:=0;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) and not private.platform_v2_is_admin() then
    raise exception 'Access denied';
  end if;

  select count(*) into unbalanced
  from (
    select j.id
    from public.journal_entries j
    join public.journal_lines l on l.journal_entry_id=j.id
    where j.tenant_id=p_tenant_id and j.status='posted'
    group by j.id
    having abs(sum(coalesce(l.debit,0))-sum(coalesce(l.credit,0)))>0.005
  ) q;

  -- More than one posted journal for the same source indicates a double-posting risk.
  select count(*) into duplicate_journals
  from (
    select source_type,source_id
    from public.journal_entries
    where tenant_id=p_tenant_id and status='posted' and source_id is not null
    group by source_type,source_id
    having count(*)>1
  ) q;

  select array_agg(k) into missing
  from unnest(array[
    'sales_revenue','output_gst','accounts_receivable','inventory_asset','cogs',
    'accounts_payable','input_gst','operating_expense','rounding',
    'customer_credits','supplier_credits','loan_receivable','loan_payable',
    'loan_interest_income','loan_interest_expense','loan_penalty_income','loan_penalty_expense'
  ]) k
  where private.v4_account_id(p_tenant_id,k) is null;

  select count(*) into sales_missing
  from public.sales s
  where s.tenant_id=p_tenant_id and coalesce(s.status,'') not in('void','cancelled')
    and not exists(select 1 from public.journal_entries j where j.tenant_id=p_tenant_id and j.source_type='sale' and j.source_id=s.id and j.status='posted');

  select count(*) into purchases_missing
  from public.purchases p
  where p.tenant_id=p_tenant_id and coalesce(p.status,'') not in('void','cancelled')
    and not exists(select 1 from public.journal_entries j where j.tenant_id=p_tenant_id and j.source_type='purchase' and j.source_id=p.id and j.status='posted');

  select count(*) into purchase_invoices_missing
  from public.purchase_invoices_v484 p
  where p.tenant_id=p_tenant_id and p.status in('posted','part_paid','paid')
    and not exists(select 1 from public.journal_entries j where j.tenant_id=p_tenant_id and j.source_type='purchase_invoice_v484' and j.source_id=p.id and j.status='posted');

  select count(*) into expenses_missing
  from public.expenses e
  where e.tenant_id=p_tenant_id and e.status='posted'
    and not exists(select 1 from public.journal_entries j where j.tenant_id=p_tenant_id and j.source_type='expense' and j.source_id=e.id and j.status='posted');

  select count(*) into sret_missing
  from public.sales_returns r
  where r.tenant_id=p_tenant_id and coalesce(r.grand_total,0)>0 and coalesce(r.refund_status,'')<>'waived'
    and not exists(select 1 from public.journal_entries j where j.tenant_id=p_tenant_id and j.source_type='sales_return' and j.source_id=r.id and j.status='posted');

  select count(*) into pret_missing
  from public.purchase_returns r
  where r.tenant_id=p_tenant_id and coalesce(r.grand_total,0)>0 and coalesce(r.credit_status,'')<>'waived'
    and not exists(select 1 from public.journal_entries j where j.tenant_id=p_tenant_id and j.source_type='purchase_return' and j.source_id=r.id and j.status='posted');

  select count(*) into loan_missing
  from public.loan_accounts_v490 l
  where l.tenant_id=p_tenant_id and l.accounting_enabled and l.status in('active','closed','defaulted')
    and not exists(select 1 from public.journal_entries j where j.tenant_id=p_tenant_id and j.source_id=l.id and j.source_type in('loan_activation_v491','loan_disbursement_v490') and j.status='posted');

  select count(*) into sale_overpayments
  from public.sales s
  where s.tenant_id=p_tenant_id
    and coalesce((select sum(sp.amount) from public.sale_payments sp where sp.sale_id=s.id),0)>coalesce(s.grand_total,0)+0.01;

  select count(*) into purchase_overpayments
  from public.purchases p
  where p.tenant_id=p_tenant_id
    and coalesce((select sum(pp.amount) from public.purchase_payments pp where pp.purchase_id=p.id),0)>coalesce(p.grand_total,0)+0.01;

  select count(*) into purchase_invoice_overpayments
  from public.purchase_invoices_v484 p
  where p.tenant_id=p_tenant_id and coalesce(p.paid_total,0)>coalesce(p.grand_total,0)+0.01;

  return jsonb_build_object(
    'ok',unbalanced=0 and duplicate_journals=0 and cardinality(coalesce(missing,'{}'))=0
      and sales_missing=0 and purchases_missing=0 and purchase_invoices_missing=0 and expenses_missing=0
      and sret_missing=0 and pret_missing=0 and loan_missing=0
      and sale_overpayments=0 and purchase_overpayments=0 and purchase_invoice_overpayments=0,
    'unbalanced_journals',unbalanced,
    'duplicate_posted_source_journals',duplicate_journals,
    'missing_mappings',to_jsonb(coalesce(missing,'{}')),
    'operational_without_journal',jsonb_build_object(
      'sales',sales_missing,
      'purchases',purchases_missing,
      'purchase_invoices',purchase_invoices_missing,
      'expenses',expenses_missing,
      'sales_returns',sret_missing,
      'purchase_returns',pret_missing,
      'accounted_loans',loan_missing
    ),
    'overpayments',jsonb_build_object(
      'sales',sale_overpayments,
      'purchases',purchase_overpayments,
      'purchase_invoices',purchase_invoice_overpayments
    ),
    'checked_at',now()
  );
end $$;


--
-- Name: finance_reconciliation_v500(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finance_reconciliation_v500(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare ar_op numeric:=0;ap_op numeric:=0;ar_gl numeric:=0;ap_gl numeric:=0;inv_op numeric:=0;inv_gl numeric:=0;cogs_op numeric:=0;cogs_gl numeric:=0;out_tax_op numeric:=0;out_tax_gl numeric:=0;in_tax_op numeric:=0;in_tax_gl numeric:=0;ar uuid;ap uuid;inv uuid;cogs uuid;unbalanced bigint:=0;zero_lines bigint:=0;duplicate_sources bigint:=0;missing_source bigint:=0;
begin
 perform private.v500_accounting_access(p_tenant_id,false);
 ar:=private.v4_account_id(p_tenant_id,'accounts_receivable');ap:=private.v4_account_id(p_tenant_id,'accounts_payable');inv:=private.v4_account_id(p_tenant_id,'inventory_asset');cogs:=private.v4_account_id(p_tenant_id,'cogs');
 select coalesce(sum(greatest(s.grand_total-coalesce(rt.x,0)-coalesce(py.x,0),0)),0) into ar_op from public.sales s left join(select sale_id,sum(grand_total)x from public.sales_returns where refund_status<>'waived' group by sale_id)rt on rt.sale_id=s.id left join(select sale_id,sum(amount)x from public.sale_payments group by sale_id)py on py.sale_id=s.id where s.tenant_id=p_tenant_id and coalesce(s.status,'') not in('void','cancelled');
 select coalesce(sum(x.balance),0) into ap_op from (select greatest(p.grand_total-coalesce(rt.x,0)-coalesce(py.x,0),0) balance from public.purchases p left join(select purchase_id,sum(grand_total)x from public.purchase_returns where credit_status<>'waived' group by purchase_id)rt on rt.purchase_id=p.id left join(select purchase_id,sum(amount)x from public.purchase_payments group by purchase_id)py on py.purchase_id=p.id where p.tenant_id=p_tenant_id and coalesce(p.status,'') not in('void','cancelled') union all select greatest(i.balance_due,0) from public.purchase_invoices_v484 i where i.tenant_id=p_tenant_id and i.status in('posted','part_paid'))x;
 select coalesce(sum(b.quantity*coalesce(nullif(b.average_cost,0),pv.cost_price,0)),0) into inv_op from public.location_stock_balances b join public.product_variants pv on pv.id=b.variant_id and pv.tenant_id=b.tenant_id where b.tenant_id=p_tenant_id;
 select coalesce(sum(si.cost_total),0)-coalesce((select sum(ri.quantity*coalesce(si2.unit_cost,0)) from public.sales_return_items ri join public.sales_returns r on r.id=ri.sales_return_id and r.tenant_id=p_tenant_id and r.refund_status<>'waived' join public.sale_items si2 on si2.id=ri.sale_item_id),0) into cogs_op from public.sale_items si join public.sales s on s.id=si.sale_id where s.tenant_id=p_tenant_id and coalesce(s.status,'') not in('void','cancelled');
 select coalesce(sum(tax_total),0)-coalesce((select sum(tax_total) from public.sales_returns where tenant_id=p_tenant_id and refund_status<>'waived'),0) into out_tax_op from public.sales where tenant_id=p_tenant_id and coalesce(status,'') not in('void','cancelled');
 select coalesce(sum(x.tax_total),0) into in_tax_op from (select tax_total from public.purchases where tenant_id=p_tenant_id and coalesce(status,'') not in('void','cancelled') union all select tax_total from public.purchase_invoices_v484 where tenant_id=p_tenant_id and status in('posted','part_paid','paid'))x;
 in_tax_op:=in_tax_op+coalesce((select sum(tax_amount) from public.expenses where tenant_id=p_tenant_id and status='posted'),0)-coalesce((select sum(tax_total) from public.purchase_returns where tenant_id=p_tenant_id and credit_status<>'waived'),0);
 select coalesce(sum(l.debit-l.credit),0) into ar_gl from public.journal_lines l join public.journal_entries j on j.id=l.journal_entry_id where j.tenant_id=p_tenant_id and j.status='posted' and l.account_id=ar;
 select coalesce(sum(l.credit-l.debit),0) into ap_gl from public.journal_lines l join public.journal_entries j on j.id=l.journal_entry_id where j.tenant_id=p_tenant_id and j.status='posted' and l.account_id=ap;
 select coalesce(sum(l.debit-l.credit),0) into inv_gl from public.journal_lines l join public.journal_entries j on j.id=l.journal_entry_id where j.tenant_id=p_tenant_id and j.status='posted' and l.account_id=inv;
 select coalesce(sum(l.debit-l.credit),0) into cogs_gl from public.journal_lines l join public.journal_entries j on j.id=l.journal_entry_id where j.tenant_id=p_tenant_id and j.status='posted' and l.account_id=cogs;
 select coalesce(sum(l.credit-l.debit),0) into out_tax_gl from public.journal_lines l join public.journal_entries j on j.id=l.journal_entry_id where j.tenant_id=p_tenant_id and j.status='posted' and l.account_id in(select account_id from private.gst_v520_account_ids(p_tenant_id,'output'));
 select coalesce(sum(l.debit-l.credit),0) into in_tax_gl from public.journal_lines l join public.journal_entries j on j.id=l.journal_entry_id where j.tenant_id=p_tenant_id and j.status='posted' and l.account_id in(select account_id from private.gst_v520_account_ids(p_tenant_id,'input_booked'));
 select count(*) into unbalanced from (select j.id from public.journal_entries j join public.journal_lines l on l.journal_entry_id=j.id where j.tenant_id=p_tenant_id and j.status='posted' group by j.id having round(sum(l.debit),2)<>round(sum(l.credit),2))q;
 select count(*) into zero_lines from public.journal_lines l join public.journal_entries j on j.id=l.journal_entry_id where j.tenant_id=p_tenant_id and j.status='posted' and round(l.debit,2)=0 and round(l.credit,2)=0;
 select count(*) into duplicate_sources from (select source_type,source_id from public.journal_entries where tenant_id=p_tenant_id and status='posted' and source_type is not null and source_id is not null group by source_type,source_id having count(*)>1)q;
 select count(*) into missing_source from (select s.id from public.sales s where s.tenant_id=p_tenant_id and coalesce(s.status,'') not in('void','cancelled') and not exists(select 1 from public.journal_entries j where j.tenant_id=p_tenant_id and j.source_type='sale' and j.source_id=s.id and j.status='posted') union all select p.id from public.purchases p where p.tenant_id=p_tenant_id and coalesce(p.status,'') not in('void','cancelled') and not exists(select 1 from public.journal_entries j where j.tenant_id=p_tenant_id and j.source_type='purchase' and j.source_id=p.id and j.status='posted') union all select r.id from public.sales_returns r where r.tenant_id=p_tenant_id and r.refund_status<>'waived' and not exists(select 1 from public.journal_entries j where j.tenant_id=p_tenant_id and j.source_type='sales_return' and j.source_id=r.id and j.status='posted') union all select r.id from public.purchase_returns r where r.tenant_id=p_tenant_id and r.credit_status<>'waived' and not exists(select 1 from public.journal_entries j where j.tenant_id=p_tenant_id and j.source_type='purchase_return' and j.source_id=r.id and j.status='posted'))q;
 return jsonb_build_object('ready',unbalanced=0 and zero_lines=0 and duplicate_sources=0 and missing_source=0 and abs(ar_op-ar_gl)<=0.05 and abs(ap_op-ap_gl)<=0.05 and abs(inv_op-inv_gl)<=0.05 and abs(cogs_op-cogs_gl)<=0.05 and abs(out_tax_op-out_tax_gl)<=0.05 and abs(in_tax_op-in_tax_gl)<=0.05,'accounts_receivable',jsonb_build_object('operational',round(ar_op,2),'general_ledger',round(ar_gl,2),'difference',round(ar_op-ar_gl,2),'reconciled',abs(ar_op-ar_gl)<=0.05),'accounts_payable',jsonb_build_object('operational',round(ap_op,2),'general_ledger',round(ap_gl,2),'difference',round(ap_op-ap_gl,2),'reconciled',abs(ap_op-ap_gl)<=0.05),'inventory',jsonb_build_object('operational_value',round(inv_op,2),'general_ledger',round(inv_gl,2),'difference',round(inv_op-inv_gl,2)),'cogs',jsonb_build_object('operational',round(cogs_op,2),'general_ledger',round(cogs_gl,2),'difference',round(cogs_op-cogs_gl,2)),'output_gst',jsonb_build_object('operational',round(out_tax_op,2),'general_ledger',round(out_tax_gl,2),'difference',round(out_tax_op-out_tax_gl,2)),'input_gst',jsonb_build_object('operational',round(in_tax_op,2),'general_ledger',round(in_tax_gl,2),'difference',round(in_tax_op-in_tax_gl,2)),'integrity',jsonb_build_object('unbalanced_posted_journals',unbalanced,'zero_value_posted_lines',zero_lines,'duplicate_source_journals',duplicate_sources,'missing_source_journals',missing_source),'checked_at',now());
end $$;


--
-- Name: finance_repair_inventory_residual_v500(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finance_repair_inventory_residual_v500(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v_inv uuid;v_equity uuid;v_operational numeric:=0;v_gl numeric:=0;v_diff numeric:=0;v_lines jsonb;begin perform private.v500_accounting_access(p_tenant_id,true);v_inv:=private.v4_account_id(p_tenant_id,'inventory_asset');v_equity:=private.v4_account_id(p_tenant_id,'owner_equity');select round(coalesce(sum(b.quantity*coalesce(nullif(b.average_cost,0),pv.cost_price,0)),0),2) into v_operational from public.location_stock_balances b join public.product_variants pv on pv.id=b.variant_id and pv.tenant_id=b.tenant_id where b.tenant_id=p_tenant_id;select round(coalesce(sum(l.debit-l.credit),0),2) into v_gl from public.journal_lines l join public.journal_entries j on j.id=l.journal_entry_id where j.tenant_id=p_tenant_id and j.status='posted' and l.account_id=v_inv;v_diff:=round(v_operational-v_gl,2);if abs(v_diff)>0.005 and not exists(select 1 from public.journal_entries where tenant_id=p_tenant_id and status='posted' and source_type='inventory_legacy_balance_v500' and source_id=p_tenant_id) then if v_diff>0 then v_lines:=jsonb_build_array(jsonb_build_object('account_id',v_inv,'debit',v_diff,'credit',0,'description','Legacy inventory balance bootstrap'),jsonb_build_object('account_id',v_equity,'debit',0,'credit',v_diff,'description','Legacy inventory opening equity'));else v_lines:=jsonb_build_array(jsonb_build_object('account_id',v_inv,'debit',0,'credit',abs(v_diff),'description','Legacy inventory balance bootstrap'),jsonb_build_object('account_id',v_equity,'debit',abs(v_diff),'credit',0,'description','Legacy inventory opening equity'));end if;perform private.v4_journal_create(p_tenant_id,null,current_date,'Legacy inventory balance reconciliation','inventory_legacy_balance_v500',p_tenant_id,'LEGACY-INVENTORY',v_lines);end if;return jsonb_build_object('operational_inventory',v_operational,'general_ledger_before',v_gl,'posted_difference',v_diff);end $$;


--
-- Name: finance_repair_legacy_accounting_v500(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finance_repair_legacy_accounting_v500(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare r record;v_inv uuid;v_equity uuid;v_discount_account uuid;v_purchase_expense uuid;v_delta numeric;v_lines jsonb;v_open_value numeric;v_open_date date;begin perform private.v500_accounting_access(p_tenant_id,true);for r in select id from public.sales s where s.tenant_id=p_tenant_id and coalesce(s.status,'') not in('void','cancelled') and not exists(select 1 from public.journal_entries j where j.tenant_id=p_tenant_id and j.source_type='sale' and j.source_id=s.id and j.status='posted') loop perform private.v4_accounting_post_document(p_tenant_id,'sale',r.id);end loop;for r in select id from public.purchases p where p.tenant_id=p_tenant_id and coalesce(p.status,'') not in('void','cancelled') and not exists(select 1 from public.journal_entries j where j.tenant_id=p_tenant_id and j.source_type='purchase' and j.source_id=p.id and j.status='posted') loop perform private.v4_accounting_post_document(p_tenant_id,'purchase',r.id);end loop;v_inv:=private.v4_account_id(p_tenant_id,'inventory_asset');v_equity:=private.v4_account_id(p_tenant_id,'owner_equity');v_purchase_expense:=private.v4_account_id(p_tenant_id,'purchase_expense');v_discount_account:=private.v500_purchase_discount_account(p_tenant_id);for r in select p.id,p.purchase_number,p.subtotal,p.discount_total,p.additional_charges,coalesce((select sum(l.debit-l.credit) from public.journal_entries j join public.journal_lines l on l.journal_entry_id=j.id where j.tenant_id=p_tenant_id and j.status='posted' and j.source_type='purchase' and j.source_id=p.id and l.account_id=v_inv),0) source_inventory from public.purchases p where p.tenant_id=p_tenant_id and coalesce(p.status,'') not in('void','cancelled') loop v_delta:=round(coalesce(r.subtotal,0)-coalesce(r.source_inventory,0),2);if (abs(v_delta)>0.005 or coalesce(r.discount_total,0)>0.005 or coalesce(r.additional_charges,0)>0.005) and not exists(select 1 from public.journal_entries j where j.tenant_id=p_tenant_id and j.status='posted' and j.source_type='purchase_cost_reclass_v500' and j.source_id=r.id) then v_lines:='[]'::jsonb;if v_delta>0 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',v_inv,'debit',v_delta,'credit',0,'description','Purchase inventory cost-basis correction'));elsif v_delta<0 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',v_inv,'debit',0,'credit',abs(v_delta),'description','Purchase inventory cost-basis correction'));end if;if coalesce(r.additional_charges,0)>0 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',v_purchase_expense,'debit',round(r.additional_charges,2),'credit',0,'description','Purchase additional charges reclass'));end if;if coalesce(r.discount_total,0)>0 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',v_discount_account,'debit',0,'credit',round(r.discount_total,2),'description','Purchase discount reclass'));end if;if jsonb_array_length(v_lines)>=2 then perform private.v4_journal_create(p_tenant_id,null,current_date,'Purchase cost reclassification • '||r.purchase_number,'purchase_cost_reclass_v500',r.id,r.purchase_number,v_lines);end if;end if;end loop;select round(coalesce(sum(quantity_delta*coalesce(unit_cost,0)),0),2),min(created_at)::date into v_open_value,v_open_date from public.location_stock_movements where tenant_id=p_tenant_id and movement_type='opening' and reference_type='product';if abs(coalesce(v_open_value,0))>0.005 and not exists(select 1 from public.journal_entries where tenant_id=p_tenant_id and status='posted' and source_type='inventory_opening_v500' and source_id=p_tenant_id) then if v_open_value>0 then v_lines:=jsonb_build_array(jsonb_build_object('account_id',v_inv,'debit',v_open_value,'credit',0,'description','Legacy opening inventory'),jsonb_build_object('account_id',v_equity,'debit',0,'credit',v_open_value,'description','Opening inventory equity'));else v_lines:=jsonb_build_array(jsonb_build_object('account_id',v_inv,'debit',0,'credit',abs(v_open_value),'description','Legacy opening inventory'),jsonb_build_object('account_id',v_equity,'debit',abs(v_open_value),'credit',0,'description','Opening inventory equity'));end if;perform private.v4_journal_create(p_tenant_id,null,coalesce(v_open_date,current_date),'Legacy opening inventory reconciliation','inventory_opening_v500',p_tenant_id,'OPENING-STOCK',v_lines);end if;return public.finance_reconciliation_v500(p_tenant_id);end $$;


--
-- Name: finance_voucher_post_v500(uuid, uuid, text, date, numeric, uuid, uuid, text, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finance_voucher_post_v500(p_tenant_id uuid, p_location_id uuid, p_voucher_type text, p_voucher_date date, p_amount numeric, p_debit_account_id uuid, p_credit_account_id uuid, p_party_type text DEFAULT NULL::text, p_party_id uuid DEFAULT NULL::uuid, p_payment_method text DEFAULT NULL::text, p_reference_number text DEFAULT NULL::text, p_narration text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v_id uuid:=gen_random_uuid();v_no text;v_journal uuid;v_lines jsonb;v_bad text;begin perform private.v500_accounting_access(p_tenant_id,true);if p_voucher_type not in('payment','receipt','contra') then raise exception 'Invalid voucher type';end if;if coalesce(p_amount,0)<=0 then raise exception 'Voucher amount must be greater than zero';end if;if p_debit_account_id=p_credit_account_id then raise exception 'Debit and credit accounts must be different';end if;select string_agg(coalesce(system_key,code),', ') into v_bad from public.accounting_accounts where tenant_id=p_tenant_id and id in(p_debit_account_id,p_credit_account_id) and system_key in('accounts_receivable','accounts_payable','inventory_asset','input_gst','output_gst','loan_receivable','loan_payable');if v_bad is not null then raise exception 'Use the source transaction/Payment Center for protected control account(s): %',v_bad;end if;if (select count(*) from public.accounting_accounts where id in(p_debit_account_id,p_credit_account_id) and tenant_id=p_tenant_id and active)<>2 then raise exception 'Invalid accounting account';end if;if p_location_id is not null then perform private.v4_location_access(p_tenant_id,p_location_id,'operate');end if;v_no:=upper(substr(p_voucher_type,1,3))||'-'||lpad(nextval('public.finance_voucher_number_seq_v500')::text,8,'0');v_lines:=jsonb_build_array(jsonb_build_object('account_id',p_debit_account_id,'debit',round(p_amount,2),'credit',0,'party_type',p_party_type,'party_id',p_party_id,'description',coalesce(nullif(trim(p_narration),''),v_no)),jsonb_build_object('account_id',p_credit_account_id,'debit',0,'credit',round(p_amount,2),'party_type',p_party_type,'party_id',p_party_id,'description',coalesce(nullif(trim(p_narration),''),v_no)));v_journal:=private.v4_journal_create(p_tenant_id,p_location_id,coalesce(p_voucher_date,current_date),coalesce(nullif(trim(p_narration),''),initcap(p_voucher_type)||' voucher '||v_no),'finance_voucher_v500',v_id,v_no,v_lines);insert into public.finance_vouchers_v500(id,tenant_id,location_id,voucher_number,voucher_type,voucher_date,amount,debit_account_id,credit_account_id,party_type,party_id,payment_method,reference_number,narration,journal_id,created_by) values(v_id,p_tenant_id,p_location_id,v_no,p_voucher_type,coalesce(p_voucher_date,current_date),round(p_amount,2),p_debit_account_id,p_credit_account_id,nullif(trim(coalesce(p_party_type,'')),''),p_party_id,nullif(trim(coalesce(p_payment_method,'')),''),nullif(trim(coalesce(p_reference_number,'')),''),coalesce(nullif(trim(p_narration),''),initcap(p_voucher_type)||' voucher'),v_journal,auth.uid());return jsonb_build_object('voucher_id',v_id,'voucher_number',v_no,'journal_id',v_journal);end $$;


--
-- Name: finance_vouchers_list_v500(uuid, date, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finance_vouchers_list_v500(p_tenant_id uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_type text DEFAULT NULL::text, p_query text DEFAULT ''::text) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare r record;q text:='%'||lower(trim(coalesce(p_query,'')))||'%';begin perform private.v500_accounting_access(p_tenant_id,false);
  for r in select v.*,da.code debit_code,da.name debit_name,ca.code credit_code,ca.name credit_name from public.finance_vouchers_v500 v join public.accounting_accounts da on da.id=v.debit_account_id join public.accounting_accounts ca on ca.id=v.credit_account_id where v.tenant_id=p_tenant_id and (p_from is null or v.voucher_date>=p_from) and (p_to is null or v.voucher_date<=p_to) and (p_type is null or v.voucher_type=p_type) and (trim(coalesce(p_query,''))='' or lower(v.voucher_number) like q or lower(coalesce(v.reference_number,'')) like q or lower(v.narration) like q) order by v.voucher_date desc,v.created_at desc loop return next to_jsonb(r);end loop;return;
end $$;


--
-- Name: financial_year_close_v500(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.financial_year_close_v500(p_tenant_id uuid, p_year_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare y public.financial_years_v500%rowtype;r record;v_lines jsonb:='[]'::jsonb;v_profit numeric:=0;v_re uuid;v_journal uuid;v_bal numeric;begin perform private.v500_accounting_access(p_tenant_id,true);select * into y from public.financial_years_v500 where id=p_year_id and tenant_id=p_tenant_id and status='open' for update;if not found then raise exception 'Open financial year not found';end if;if y.end_date>current_date then raise exception 'Cannot close a financial year before its end date';end if;if exists(select 1 from public.financial_years_v500 x where x.tenant_id=p_tenant_id and x.status='open' and x.end_date<y.end_date and x.id<>y.id) then raise exception 'Close earlier financial years first';end if;v_re:=private.v500_retained_earnings_account(p_tenant_id);for r in select a.id,a.account_type,a.name,round(case when a.account_type='income' then coalesce(sum(case when j.id is not null then l.credit-l.debit else 0 end),0) else coalesce(sum(case when j.id is not null then l.debit-l.credit else 0 end),0) end,2) bal from public.accounting_accounts a left join public.journal_lines l on l.account_id=a.id left join public.journal_entries j on j.id=l.journal_entry_id and j.status='posted' and j.entry_date between y.start_date and y.end_date and j.tenant_id=p_tenant_id where a.tenant_id=p_tenant_id and a.account_type in('income','expense','cogs') group by a.id,a.account_type,a.name loop v_bal:=coalesce(r.bal,0);if abs(v_bal)<0.005 then continue;end if;if r.account_type='income' then v_profit:=v_profit+v_bal;if v_bal>0 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',r.id,'debit',v_bal,'credit',0,'description','Financial year close • '||r.name));else v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',r.id,'debit',0,'credit',abs(v_bal),'description','Financial year close • '||r.name));end if;else v_profit:=v_profit-v_bal;if v_bal>0 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',r.id,'debit',0,'credit',v_bal,'description','Financial year close • '||r.name));else v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',r.id,'debit',abs(v_bal),'credit',0,'description','Financial year close • '||r.name));end if;end if;end loop;v_profit:=round(v_profit,2);if jsonb_array_length(v_lines)>0 then if v_profit>0 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',v_re,'debit',0,'credit',v_profit,'description','Net profit transferred to retained earnings'));elsif v_profit<0 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',v_re,'debit',abs(v_profit),'credit',0,'description','Net loss transferred to retained earnings'));end if;v_journal:=private.v4_journal_create(p_tenant_id,null,y.end_date,'Financial year closing • '||y.name,'financial_year_close_v500',y.id,y.name,v_lines);end if;update public.financial_years_v500 set status='closed',locked_through=end_date,closing_journal_id=v_journal,closed_by=auth.uid(),closed_at=now() where id=y.id;end $$;


--
-- Name: financial_year_save_v500(uuid, uuid, text, date, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.financial_year_save_v500(p_tenant_id uuid, p_year_id uuid, p_name text, p_start_date date, p_end_date date, p_locked_through date DEFAULT NULL::date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v uuid;begin perform private.v500_accounting_access(p_tenant_id,true);if trim(coalesce(p_name,''))='' then raise exception 'Financial year name is required';end if;if p_start_date is null or p_end_date is null or p_end_date<p_start_date then raise exception 'Invalid financial year dates';end if;if p_locked_through is not null and (p_locked_through<p_start_date or p_locked_through>p_end_date) then raise exception 'Locked-through date must be inside the financial year';end if;if exists(select 1 from public.financial_years_v500 y where y.tenant_id=p_tenant_id and y.id is distinct from p_year_id and daterange(y.start_date,y.end_date,'[]') && daterange(p_start_date,p_end_date,'[]')) then raise exception 'Financial year overlaps an existing year';end if;if p_year_id is null then insert into public.financial_years_v500(tenant_id,name,start_date,end_date,locked_through,created_by) values(p_tenant_id,trim(p_name),p_start_date,p_end_date,p_locked_through,auth.uid()) returning id into v;else update public.financial_years_v500 set name=trim(p_name),start_date=p_start_date,end_date=p_end_date,locked_through=p_locked_through where id=p_year_id and tenant_id=p_tenant_id and status='open' returning id into v;if v is null then raise exception 'Open financial year not found';end if;end if;return v;end $$;


--
-- Name: financial_years_list_v500(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.financial_years_list_v500(p_tenant_id uuid) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare r record;begin
  perform private.v500_accounting_access(p_tenant_id,false);
  for r in select * from public.financial_years_v500 where tenant_id=p_tenant_id order by start_date desc loop return next to_jsonb(r);end loop;return;
end $$;


--
-- Name: global_search_v32(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.global_search_v32(p_tenant_id uuid, p_query text, p_limit integer DEFAULT 40) RETURNS TABLE(entity_type text, entity_id uuid, public_id text, title text, subtitle text, module_key text, location_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare q text:='%'||lower(trim(coalesce(p_query,'')))||'%';lim int:=greatest(5,least(coalesce(p_limit,40),100));begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if trim(coalesce(p_query,''))='' then return;end if;
  return query
  select * from (
    select 'product'::text,pv.id,p.tracking_code,p.name,coalesce('SKU '||pv.sku||case when pv.part_number is not null and pv.part_number<>'' then ' • Part '||pv.part_number else '' end,''),'inventory'::text,null::uuid
      from public.products p join public.product_variants pv on pv.product_id=p.id and pv.tenant_id=p.tenant_id
      where p.tenant_id=p_tenant_id and (private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'inventory.view') or private.erp_has_permission(p_tenant_id,'inventory.manage')) and (lower(p.name) like q or lower(pv.sku) like q or lower(coalesce(pv.barcode,'')) like q or lower(coalesce(pv.part_number,'')) like q or lower(coalesce(p.tracking_code,'')) like q)
    union all
    select 'customer',c.id,c.tracking_code,c.name,coalesce(c.phone,''),'customers',null::uuid from public.customers c where c.tenant_id=p_tenant_id and (private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'customers.view') or private.erp_has_permission(p_tenant_id,'customers.manage')) and (lower(c.name) like q or lower(coalesce(c.phone,'')) like q or lower(coalesce(c.tracking_code,'')) like q)
    union all
    select 'supplier',s.id,s.tracking_code,s.name,coalesce(s.phone,''),'suppliers',null::uuid from public.suppliers s where s.tenant_id=p_tenant_id and (private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'suppliers.view') or private.erp_has_permission(p_tenant_id,'suppliers.manage')) and (lower(s.name) like q or lower(coalesce(s.phone,'')) like q or lower(coalesce(s.tracking_code,'')) like q)
    union all
    select 'sale',s.id,s.tracking_code,coalesce(dn.terminal_number,ln.local_number,s.sale_number),c.name,'sales',o.location_id from public.sales s join public.customers c on c.id=s.customer_id left join public.document_origins o on o.entity_type='sale' and o.entity_id=s.id left join public.location_document_numbers ln on ln.entity_type='sale' and ln.entity_id=s.id left join public.device_document_numbers dn on dn.entity_type='sale' and dn.entity_id=s.id where s.tenant_id=p_tenant_id and private.erp_document_scope_allowed(p_tenant_id,o.location_id,null,'view') and (lower(s.sale_number) like q or lower(coalesce(s.tracking_code,'')) like q or lower(c.name) like q or lower(coalesce(dn.terminal_number,ln.local_number,'')) like q)
    union all
    select 'purchase',p.id,p.tracking_code,coalesce(dn.terminal_number,ln.local_number,p.purchase_number),sp.name,'purchases',o.location_id from public.purchases p join public.suppliers sp on sp.id=p.supplier_id left join public.document_origins o on o.entity_type='purchase' and o.entity_id=p.id left join public.location_document_numbers ln on ln.entity_type='purchase' and ln.entity_id=p.id left join public.device_document_numbers dn on dn.entity_type='purchase' and dn.entity_id=p.id where p.tenant_id=p_tenant_id and private.erp_document_scope_allowed(p_tenant_id,o.location_id,null,'view') and (lower(p.purchase_number) like q or lower(coalesce(p.tracking_code,'')) like q or lower(sp.name) like q or lower(coalesce(dn.terminal_number,ln.local_number,'')) like q)
  )z limit lim;
end $$;


--
-- Name: global_search_v4(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.global_search_v4(p_tenant_id uuid, p_query text, p_limit integer DEFAULT 60) RETURNS TABLE(entity_type text, entity_id uuid, public_id text, title text, subtitle text, module_key text, location_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare q text:='%'||lower(trim(coalesce(p_query,'')))||'%';lim integer:=greatest(5,least(coalesce(p_limit,60),150));begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;if trim(coalesce(p_query,''))='' then return;end if;
  return query select * from (
    select 'product'::text,pv.id,coalesce(p.tracking_code,pv.sku),p.name,concat_ws(' • ','SKU '||pv.sku,nullif(pv.part_number,''),nullif(pv.barcode,'')),'inventory'::text,null::uuid from public.products p join public.product_variants pv on pv.product_id=p.id and pv.tenant_id=p.tenant_id where p.tenant_id=p_tenant_id and (lower(p.name) like q or lower(pv.sku) like q or lower(coalesce(pv.barcode,'')) like q or lower(coalesce(pv.part_number,'')) like q or lower(coalesce(p.tracking_code,'')) like q)
    union all select 'customer',c.id,c.tracking_code,c.name,concat_ws(' • ',c.phone,c.email,c.tax_number),'customers',null::uuid from public.customers c where c.tenant_id=p_tenant_id and (lower(c.name) like q or lower(coalesce(c.phone,'')) like q or lower(coalesce(c.email,'')) like q or lower(coalesce(c.tracking_code,'')) like q)
    union all select 'supplier',s.id,s.tracking_code,s.name,concat_ws(' • ',s.phone,s.email,s.tax_number),'suppliers',null::uuid from public.suppliers s where s.tenant_id=p_tenant_id and (lower(s.name) like q or lower(coalesce(s.phone,'')) like q or lower(coalesce(s.email,'')) like q or lower(coalesce(s.tracking_code,'')) like q)
    union all select 'sale',s.id,s.tracking_code,coalesce(dn.terminal_number,ln.local_number,s.sale_number),c.name||' • '||s.grand_total::text,'sales',o.location_id from public.sales s join public.customers c on c.id=s.customer_id left join public.document_origins o on o.entity_type='sale' and o.entity_id=s.id left join public.location_document_numbers ln on ln.entity_type='sale' and ln.entity_id=s.id left join public.device_document_numbers dn on dn.entity_type='sale' and dn.entity_id=s.id where s.tenant_id=p_tenant_id and private.erp_document_scope_allowed(p_tenant_id,o.location_id,null,'view') and (lower(s.sale_number) like q or lower(coalesce(dn.terminal_number,'')) like q or lower(c.name) like q or lower(coalesce(s.tracking_code,'')) like q)
    union all select 'purchase',p.id,p.tracking_code,coalesce(dn.terminal_number,ln.local_number,p.purchase_number),s.name||' • '||p.grand_total::text,'purchases',o.location_id from public.purchases p join public.suppliers s on s.id=p.supplier_id left join public.document_origins o on o.entity_type='purchase' and o.entity_id=p.id left join public.location_document_numbers ln on ln.entity_type='purchase' and ln.entity_id=p.id left join public.device_document_numbers dn on dn.entity_type='purchase' and dn.entity_id=p.id where p.tenant_id=p_tenant_id and private.erp_document_scope_allowed(p_tenant_id,o.location_id,null,'view') and (lower(p.purchase_number) like q or lower(coalesce(dn.terminal_number,'')) like q or lower(s.name) like q or lower(coalesce(p.tracking_code,'')) like q)
    union all select 'loan',l.id,l.loan_number,l.loan_number,c.name||' • '||l.status||' • outstanding '||round(l.principal_outstanding+l.interest_outstanding+l.penalty_outstanding,2)::text,'loans',l.location_id from public.loan_accounts_v490 l join public.customers c on c.id=l.client_id where l.tenant_id=p_tenant_id and exists(select 1 from public.tenant_modules tm where tm.tenant_id=p_tenant_id and tm.module_key='loans' and tm.enabled) and (private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'loans.view') or private.erp_has_permission(p_tenant_id,'loans.manage')) and private.erp_document_scope_allowed(p_tenant_id,l.location_id,null,'view') and (lower(l.loan_number) like q or lower(c.name) like q or lower(coalesce(c.tracking_code,'')) like q or lower(coalesce(l.external_client_reference,'')) like q or lower(coalesce(l.purpose,'')) like q)
    union all select 'account',a.id,a.code,a.name,a.account_type,'accounting',null::uuid from public.accounting_accounts a where a.tenant_id=p_tenant_id and active and (lower(a.code) like q or lower(a.name) like q)
    union all select 'stock_transfer',t.id,t.transfer_number,t.transfer_number,fl.location_code||' → '||tl.location_code||' • '||t.status,'stock_transfers',t.from_location_id from public.stock_transfers t join public.business_locations fl on fl.id=t.from_location_id join public.business_locations tl on tl.id=t.to_location_id where t.tenant_id=p_tenant_id and lower(t.transfer_number) like q
    union all select 'task',t.id,null,t.title,coalesce(t.status,'')||' • '||coalesce(t.description,''),'tasks',t.location_id from public.business_tasks t where t.tenant_id=p_tenant_id and (lower(t.title) like q or lower(coalesce(t.description,'')) like q)
    union all select 'workshop_job',j.id,j.job_number,j.job_number,coalesce(v.vehicle_number,'')||' • '||j.status,'workshop',j.location_id from public.workshop_job_cards j join public.workshop_vehicles v on v.id=j.vehicle_id where j.tenant_id=p_tenant_id and (lower(j.job_number) like q or lower(v.vehicle_number) like q)
  )z limit lim;
end $$;


--
-- Name: goods_receipt_cancel_v490(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.goods_receipt_cancel_v490(p_tenant_id uuid, p_goods_receipt_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare g public.goods_receipts_v484%rowtype;begin
  if nullif(trim(coalesce(p_reason,'')),'') is null then raise exception 'Cancellation reason is required';end if;
  select * into g from public.goods_receipts_v484 where tenant_id=p_tenant_id and id=p_goods_receipt_id for update;
  if not found then raise exception 'GRN not found';end if;
  perform private.purchasing_v484_access(p_tenant_id,g.location_id,true);
  if g.status='cancelled' then return jsonb_build_object('success',true,'goods_receipt_id',g.id,'status','cancelled','idempotent',true);end if;
  if g.status<>'draft' then raise exception 'Only Draft GRNs can be cancelled. Posted receipts require a controlled purchase return/reversal so stock traceability is preserved';end if;
  update public.goods_receipts_v484 set status='cancelled',cancelled_by=auth.uid(),cancelled_at=now(),notes=concat_ws(E'\n',notes,'Cancelled: '||trim(p_reason)),updated_at=now() where id=g.id;
  perform private.thq_sync_bump_v480(p_tenant_id,'transactions','goods_receipt',g.id::text,'cancel');
  return jsonb_build_object('success',true,'goods_receipt_id',g.id,'grn_number',g.grn_number,'status','cancelled');
end $$;


--
-- Name: goods_receipt_create_v484(uuid, uuid, date, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.goods_receipt_create_v484(p_tenant_id uuid, p_purchase_order_id uuid, p_receipt_date date, p_items jsonb, p_supplier_delivery_note text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_po public.purchase_orders_v480%rowtype;v_id uuid:=gen_random_uuid();v_no text;x jsonb;v_po_item public.purchase_order_items_v480%rowtype;v_received numeric;v_accepted numeric;v_damaged numeric;v_rejected numeric;v_remaining numeric;begin
  select * into v_po from public.purchase_orders_v480 where tenant_id=p_tenant_id and id=p_purchase_order_id for update;if not found then raise exception 'Purchase Order not found';end if;
  perform private.purchasing_v484_access(p_tenant_id,v_po.location_id,true);
  if v_po.status not in('approved','ordered','partially_received') then raise exception 'Only Approved/Ordered/Partially Received Purchase Orders can receive goods';end if;
  if p_items is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'At least one receiving line is required';end if;
  v_no:='GRN-'||to_char(coalesce(p_receipt_date,current_date),'YYMMDD')||'-'||lpad(nextval('public.goods_receipt_number_seq_v484')::text,6,'0');
  insert into public.goods_receipts_v484(id,tenant_id,location_id,supplier_id,purchase_order_id,grn_number,receipt_date,supplier_delivery_note,notes,created_by)
  values(v_id,p_tenant_id,v_po.location_id,v_po.supplier_id,p_purchase_order_id,v_no,coalesce(p_receipt_date,current_date),nullif(trim(coalesce(p_supplier_delivery_note,'')),''),nullif(trim(coalesce(p_notes,'')),''),auth.uid());
  for x in select value from jsonb_array_elements(p_items) loop
    select * into v_po_item from public.purchase_order_items_v480 where id=nullif(x->>'purchase_order_item_id','')::uuid and purchase_order_id=p_purchase_order_id;if not found then raise exception 'PO line not found';end if;
    v_received:=coalesce(nullif(x->>'received_quantity','')::numeric,0);v_accepted:=coalesce(nullif(x->>'accepted_quantity','')::numeric,v_received);v_damaged:=coalesce(nullif(x->>'damaged_quantity','')::numeric,0);v_rejected:=coalesce(nullif(x->>'rejected_quantity','')::numeric,0);
    if v_received<=0 or v_accepted<0 or v_damaged<0 or v_rejected<0 or abs(v_received-(v_accepted+v_damaged+v_rejected))>0.000001 then raise exception 'Received quantity must equal accepted + damaged + rejected';end if;
    v_remaining:=greatest(v_po_item.quantity-coalesce(v_po_item.received_quantity,0),0);if v_received-v_remaining>0.000001 then raise exception 'Receiving quantity % exceeds remaining PO quantity %',v_received,v_remaining;end if;
    if v_rejected>0 and trim(coalesce(x->>'rejection_reason',''))='' then raise exception 'Rejected quantity requires a reason';end if;
    insert into public.goods_receipt_items_v484(goods_receipt_id,purchase_order_item_id,variant_id,received_quantity,accepted_quantity,damaged_quantity,rejected_quantity,unit_cost,tracking_payload,rejection_reason,damage_note)
    values(v_id,v_po_item.id,v_po_item.variant_id,v_received,v_accepted,v_damaged,v_rejected,v_po_item.unit_cost,coalesce(x->'tracking','{}'::jsonb),nullif(trim(coalesce(x->>'rejection_reason','')),''),nullif(trim(coalesce(x->>'damage_note','')),''));
  end loop;
  perform private.thq_sync_bump_v480(p_tenant_id,'transactions','goods_receipt',v_id::text,'create');
  return jsonb_build_object('success',true,'goods_receipt_id',v_id,'grn_number',v_no,'status','draft');
end$$;


--
-- Name: goods_receipt_detail_v484(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.goods_receipt_detail_v484(p_tenant_id uuid, p_goods_receipt_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_loc uuid;v jsonb;begin
 select location_id into v_loc from public.goods_receipts_v484 where tenant_id=p_tenant_id and id=p_goods_receipt_id;if v_loc is null then raise exception 'GRN not found';end if;perform private.purchasing_v484_access(p_tenant_id,v_loc,false);
 select jsonb_build_object('grn',to_jsonb(g)||jsonb_build_object('order_number',po.order_number,'supplier_name',s.name,'location_name',l.name),
 'items',coalesce((select jsonb_agg(to_jsonb(i)||jsonb_build_object('product_name',p.name,'sku',pv.sku,'ordered_quantity',poi.quantity,'po_received_quantity',poi.received_quantity) order by p.name) from public.goods_receipt_items_v484 i join public.purchase_order_items_v480 poi on poi.id=i.purchase_order_item_id join public.product_variants pv on pv.id=i.variant_id join public.products p on p.id=pv.product_id where i.goods_receipt_id=g.id),'[]'::jsonb)) into v
 from public.goods_receipts_v484 g join public.purchase_orders_v480 po on po.id=g.purchase_order_id join public.suppliers s on s.id=g.supplier_id join public.business_locations l on l.id=g.location_id where g.id=p_goods_receipt_id and g.tenant_id=p_tenant_id;return v;
end$$;


--
-- Name: goods_receipt_list_v484(uuid, uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.goods_receipt_list_v484(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_query text DEFAULT ''::text, p_limit integer DEFAULT 500) RETURNS TABLE(id uuid, grn_number text, receipt_date date, status text, purchase_order_id uuid, order_number text, supplier_id uuid, supplier_name text, location_id uuid, location_name text, line_count bigint, received_quantity numeric, accepted_quantity numeric, damaged_quantity numeric, rejected_quantity numeric, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare q text:='%'||lower(trim(coalesce(p_query,'')))||'%';begin
 perform private.purchasing_v484_permission(p_tenant_id,false);
 return query select g.id,g.grn_number,g.receipt_date,g.status,g.purchase_order_id,po.order_number,g.supplier_id,s.name,g.location_id,l.name,count(i.id),coalesce(sum(i.received_quantity),0),coalesce(sum(i.accepted_quantity),0),coalesce(sum(i.damaged_quantity),0),coalesce(sum(i.rejected_quantity),0),g.created_at
 from public.goods_receipts_v484 g join public.purchase_orders_v480 po on po.id=g.purchase_order_id join public.suppliers s on s.id=g.supplier_id join public.business_locations l on l.id=g.location_id left join public.goods_receipt_items_v484 i on i.goods_receipt_id=g.id left join public.product_variants pv on pv.id=i.variant_id left join public.products p on p.id=pv.product_id
 where g.tenant_id=p_tenant_id and (p_location_id is null or g.location_id=p_location_id) and (p_status is null or p_status='' or g.status=p_status) and private.erp_document_scope_allowed(p_tenant_id,g.location_id,p_location_id,'view')
 and (trim(coalesce(p_query,''))='' or lower(g.grn_number) like q or lower(po.order_number) like q or lower(s.name) like q or lower(coalesce(g.supplier_delivery_note,'')) like q or lower(coalesce(p.name,'')) like q or lower(coalesce(pv.sku,'')) like q)
 group by g.id,po.order_number,s.name,l.name order by g.created_at desc limit greatest(1,least(coalesce(p_limit,500),2000));
end$$;


--
-- Name: goods_receipt_post_v484(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.goods_receipt_post_v484(p_tenant_id uuid, p_goods_receipt_id uuid, p_device_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare g public.goods_receipts_v484%rowtype;gi public.goods_receipt_items_v484%rowtype;v_item_type text;v_physical numeric;v_before numeric;v_after numeric;v_remaining numeric;v_any_open boolean:=false;v_old_po_status text;begin
  select * into g from public.goods_receipts_v484 where tenant_id=p_tenant_id and id=p_goods_receipt_id for update;if not found then raise exception 'GRN not found';end if;perform private.purchasing_v484_access(p_tenant_id,g.location_id,true);if g.status='posted' then return jsonb_build_object('success',true,'goods_receipt_id',g.id,'grn_number',g.grn_number,'status','posted','idempotent',true);end if;if g.status<>'draft' then raise exception 'Only Draft GRNs can be posted';end if;
  for gi in select * from public.goods_receipt_items_v484 where goods_receipt_id=g.id order by id loop
    select p.item_type into v_item_type from public.product_variants pv join public.products p on p.id=pv.product_id where pv.id=gi.variant_id and pv.tenant_id=p_tenant_id;if v_item_type is null then raise exception 'Product not found';end if;
    select greatest(quantity-coalesce(received_quantity,0),0) into v_remaining from public.purchase_order_items_v480 where id=gi.purchase_order_item_id for update;if gi.received_quantity-v_remaining>0.000001 then raise exception 'PO remaining quantity changed; reopen the GRN and receive only the remaining quantity';end if;
    if v_item_type='stock' then
      perform private.goods_receipt_apply_tracking_v484(gi.id);
      v_physical:=gi.accepted_quantity+gi.damaged_quantity;
      if v_physical>0 then
        perform public.inventory_adjust_stock(p_tenant_id,gi.variant_id,v_physical,'GRN '||g.grn_number);
        v_after:=private.v4_location_stock_apply(p_tenant_id,g.location_id,gi.variant_id,v_physical,'grn','goods_receipt',g.id,g.grn_number,'Goods received',p_device_id,false);
        if gi.damaged_quantity>0 then
          update public.location_stock_balances set damaged_quantity=coalesce(damaged_quantity,0)+gi.damaged_quantity,updated_at=now() where tenant_id=p_tenant_id and location_id=g.location_id and variant_id=gi.variant_id;
          select balance_before,balance_after into v_before,v_after from public.location_stock_movements where tenant_id=p_tenant_id and reference_type='goods_receipt' and reference_id=g.id and variant_id=gi.variant_id and movement_type='grn' order by created_at desc limit 1;
          insert into public.location_stock_movements(tenant_id,location_id,variant_id,movement_type,quantity_delta,base_quantity_delta,display_quantity,balance_before,balance_after,unit_cost,reference_type,reference_id,reference_number,note,created_by,device_id,movement_group,metadata)
          values(p_tenant_id,g.location_id,gi.variant_id,'damage',0,0,gi.damaged_quantity,coalesce(v_after-v_physical,0),coalesce(v_after,0),gi.unit_cost,'goods_receipt',g.id,g.grn_number,coalesce(gi.damage_note,'Damaged on receipt'),auth.uid(),p_device_id,'damage',jsonb_build_object('damaged_quantity',gi.damaged_quantity,'goods_receipt_item_id',gi.id));
        end if;
      end if;
    end if;
    update public.purchase_order_items_v480 set received_quantity=received_quantity+gi.received_quantity,accepted_quantity=accepted_quantity+gi.accepted_quantity,damaged_quantity=damaged_quantity+gi.damaged_quantity,rejected_quantity=rejected_quantity+gi.rejected_quantity where id=gi.purchase_order_item_id;
  end loop;
  select exists(select 1 from public.purchase_order_items_v480 where purchase_order_id=g.purchase_order_id and received_quantity+0.000001<quantity) into v_any_open;
  select status into v_old_po_status from public.purchase_orders_v480 where id=g.purchase_order_id for update;
  update public.purchase_orders_v480 set status=case when v_any_open then 'partially_received' else 'received' end,updated_at=now() where id=g.purchase_order_id;
  insert into public.purchase_order_status_history_v480(purchase_order_id,from_status,to_status,reason,changed_by)
  values(g.purchase_order_id,v_old_po_status,case when v_any_open then 'partially_received' else 'received' end,'GRN '||g.grn_number||' posted',auth.uid());
  update public.goods_receipts_v484 set status='posted',posted_by=auth.uid(),posted_at=now(),updated_at=now() where id=g.id;
  perform private.thq_sync_bump_v480(p_tenant_id,'inventory','goods_receipt',g.id::text,'post');
  return jsonb_build_object('success',true,'goods_receipt_id',g.id,'grn_number',g.grn_number,'status','posted','purchase_order_status',case when v_any_open then 'partially_received' else 'received' end);
end$$;


--
-- Name: gst_accounting_control_v520(uuid, date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_accounting_control_v520(p_tenant_id uuid, p_from date, p_to date, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v jsonb;
begin
 if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.view') then raise exception 'GST compliance view permission required';end if;
 with balances as (
  select a.system_key,private.gst_v520_account_family(a.system_key) family,
    round(coalesce(sum(case when j.id is null then 0 when a.account_type='asset' then l.debit-l.credit else l.credit-l.debit end),0),2) balance
  from public.accounting_accounts a left join public.journal_lines l on l.account_id=a.id left join public.journal_entries j on j.id=l.journal_entry_id and j.status='posted' and j.entry_date between p_from and p_to and private.erp_document_scope_allowed(p_tenant_id,j.location_id,p_location_id,'view')
  where a.tenant_id=p_tenant_id and private.gst_v520_account_family(a.system_key) is not null
  group by a.system_key,a.account_type
 ), f as (
  select family,jsonb_object_agg(system_key,balance order by system_key) components,round(sum(balance),2) total from balances group by family
 )
 select jsonb_object_agg(family,jsonb_build_object('components',components,'total',total)) into v from f;
 return coalesce(v,'{}'::jsonb)||jsonb_build_object('from',p_from,'to',p_to);
end $$;


--
-- Name: gst_accounting_health_v520(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_accounting_health_v520(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare missing text[]:='{}';k text;mixed_input bigint;mixed_output bigint;mixed_rcm bigint;mixed_rcm_input bigint;orphan_component bigint;
begin
 if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.view') then raise exception 'GST compliance view permission required';end if;
 foreach k in array array['input_cgst','input_sgst','input_utgst','input_igst','input_cess','rcm_input_gst','rcm_input_cgst','rcm_input_sgst','rcm_input_utgst','rcm_input_igst','rcm_input_cess','output_cgst','output_sgst','output_utgst','output_igst','output_cess','rcm_gst_payable','rcm_cgst_payable','rcm_sgst_payable','rcm_utgst_payable','rcm_igst_payable','rcm_cess_payable'] loop
  if not exists(select 1 from public.accounting_account_mappings m join public.accounting_accounts a on a.id=m.account_id where m.tenant_id=p_tenant_id and m.mapping_key=k and a.tenant_id=p_tenant_id and a.system_key=k and a.active) then missing:=array_append(missing,k);end if;
 end loop;
 select count(*) into mixed_input from public.journal_entries j where j.tenant_id=p_tenant_id and j.status='posted' and exists(select 1 from public.journal_lines l join public.accounting_accounts a on a.id=l.account_id where l.journal_entry_id=j.id and a.system_key='input_gst') and exists(select 1 from public.journal_lines l join public.accounting_accounts a on a.id=l.account_id where l.journal_entry_id=j.id and a.system_key in('input_cgst','input_sgst','input_utgst','input_igst','input_cess'));
 select count(*) into mixed_output from public.journal_entries j where j.tenant_id=p_tenant_id and j.status='posted' and exists(select 1 from public.journal_lines l join public.accounting_accounts a on a.id=l.account_id where l.journal_entry_id=j.id and a.system_key='output_gst') and exists(select 1 from public.journal_lines l join public.accounting_accounts a on a.id=l.account_id where l.journal_entry_id=j.id and a.system_key in('output_cgst','output_sgst','output_utgst','output_igst','output_cess'));
 select count(*) into mixed_rcm from public.journal_entries j where j.tenant_id=p_tenant_id and j.status='posted' and exists(select 1 from public.journal_lines l join public.accounting_accounts a on a.id=l.account_id where l.journal_entry_id=j.id and a.system_key='rcm_gst_payable') and exists(select 1 from public.journal_lines l join public.accounting_accounts a on a.id=l.account_id where l.journal_entry_id=j.id and a.system_key in('rcm_cgst_payable','rcm_sgst_payable','rcm_utgst_payable','rcm_igst_payable','rcm_cess_payable'));
 select count(*) into mixed_rcm_input from public.journal_entries j where j.tenant_id=p_tenant_id and j.status='posted' and exists(select 1 from public.journal_lines l join public.accounting_accounts a on a.id=l.account_id where l.journal_entry_id=j.id and a.system_key='rcm_input_gst') and exists(select 1 from public.journal_lines l join public.accounting_accounts a on a.id=l.account_id where l.journal_entry_id=j.id and a.system_key in('rcm_input_cgst','rcm_input_sgst','rcm_input_utgst','rcm_input_igst','rcm_input_cess'));
 select count(distinct j.id) into orphan_component from public.journal_entries j join public.journal_lines l on l.journal_entry_id=j.id join public.accounting_accounts a on a.id=l.account_id where j.tenant_id=p_tenant_id and j.status='posted' and j.source_type in('sale','purchase','sales_return','purchase_return','purchase_invoice_v484') and a.system_key in('input_cgst','input_sgst','input_utgst','input_igst','input_cess','output_cgst','output_sgst','output_utgst','output_igst','output_cess','rcm_cgst_payable','rcm_sgst_payable','rcm_utgst_payable','rcm_igst_payable','rcm_cess_payable') and not exists(select 1 from public.gst_document_snapshots_v520 s where s.tenant_id=p_tenant_id and s.source_type=j.source_type and s.source_id=j.source_id);
 return jsonb_build_object('ready',cardinality(missing)=0 and mixed_input=0 and mixed_output=0 and mixed_rcm=0 and mixed_rcm_input=0 and orphan_component=0,'missing_mappings',to_jsonb(missing),'mixed_legacy_and_component_input_journals',mixed_input,'mixed_legacy_and_component_output_journals',mixed_output,'mixed_rcm_parent_and_component_journals',mixed_rcm,'mixed_rcm_input_parent_and_component_journals',mixed_rcm_input,'component_journals_without_authoritative_snapshot',orphan_component);
end $$;


--
-- Name: gst_app_cutover_contract_v520(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_app_cutover_contract_v520(p_tenant_id uuid, p_device_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_location uuid;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then
    raise exception 'Access denied';
  end if;

  if p_device_id is not null then
    v_location:=private.v486_pos_device_location(p_tenant_id,p_device_id,null);
  end if;

  return jsonb_build_object(
    'release','5.2',
    'contract','gst-authoritative-v520',
    'tenant_id',p_tenant_id,
    'device_id',p_device_id,
    'location_id',v_location,
    'cutover_ready',true,
    'rules',jsonb_build_object(
      'new_transactions_must_use_v520',true,
      'legacy_writers_compatibility_only',true,
      'legacy_fallback_for_failed_v520',false,
      'authoritative_snapshot_required',true,
      'authoritative_journal_required',true,
      'legacy_unverified_required_for_legacy_transactions',true
    ),
    'client',jsonb_build_object(
      'sale_create','gst_sale_create_v520',
      'purchase_create','gst_purchase_create_v520',
      'purchasing_v2_invoice_create','gst_purchase_invoice_create_v520',
      'sales_return_create','gst_sales_return_create_v520',
      'purchase_return_create','gst_purchase_return_create_v520',
      'service_job_bill','gst_service_job_bill_v520',
      'restaurant_bill','gst_restaurant_order_bill_v520'
    ),
    'desktop_pos',jsonb_build_object(
      'sale_create','gst_sale_create_v520',
      'restaurant_bill','gst_restaurant_order_bill_v520',
      'offline_sale_sync','gst_pos_offline_sale_sync_v520',
      'offline_contract','pos_offline_api_contract_v520'
    ),
    'mobile_pos',jsonb_build_object(
      'api_contract','mobile_pos_api_contract_v520',
      'sale_sync','gst_mobile_pos_sale_sync_v520',
      'product_cache','mobile_pos_product_cache_v520',
      'cache_manifest','mobile_pos_cache_manifest_v520',
      'sync_status','mobile_pos_sync_status_v520',
      'receipt_event','mobile_pos_receipt_event_v520',
      'kot_create','mobile_pos_kot_create_v520',
      'restaurant_bill','mobile_pos_restaurant_bill_v520'
    ),
    'compatibility_only',jsonb_build_object(
      'sale_create','sales_create_v483',
      'purchase_create','purchases_create_v483',
      'sales_return_create','sales_return_create_v483',
      'purchase_return_create','purchase_return_create_v481',
      'service_job_bill','service_job_bill_v51',
      'restaurant_bill','restaurant_order_bill_v489',
      'offline_sale_sync','pos_offline_sale_sync_v486',
      'mobile_sale_sync','mobile_pos_sale_sync_v488'
    )
  );
end
$$;


--
-- Name: FUNCTION gst_app_cutover_contract_v520(p_tenant_id uuid, p_device_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gst_app_cutover_contract_v520(p_tenant_id uuid, p_device_id uuid) IS 'Authoritative THQ ERP v5.2 GST Client/POS RPC cutover map. Legacy transaction writers remain compatibility-only and must not be used as fallback for new v5.2 GST transactions.';


--
-- Name: gst_compliance_bootstrap_v520(uuid, date, date, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_compliance_bootstrap_v520(p_tenant_id uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_location_id uuid DEFAULT NULL::uuid, p_document_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_from date:=coalesce(p_from,date_trunc('month',current_date)::date);
  v_to date:=coalesce(p_to,current_date);
  v_limit integer:=coalesce(p_document_limit,50);
  v_mode text:=private.gst_tax_mode_resolve_v520(p_tenant_id,current_date);
begin
  if p_tenant_id is null then raise exception 'Tenant is required'; end if;
  if v_from>v_to then raise exception 'GST period start date cannot be after end date'; end if;
  if v_limit<1 or v_limit>100 then raise exception 'GST bootstrap document limit must be between 1 and 100'; end if;

  return jsonb_build_object(
    'release','5.2.0-foundation',
    'contract_version',2,
    'server_date',current_date,
    'tax_mode',v_mode,
    'period',jsonb_build_object('from',v_from,'to',v_to,'location_id',p_location_id),
    'rules',jsonb_build_object(
      'tax_calculation','server_authoritative_only',
      'tenant_tax_mode_required',true,
      'gst_applicable',v_mode='gst_registered',
      'legacy_transactions','view_only_legacy_unverified',
      'v520_failure_fallback',false,
      'provider_submission',false,
      'provider_phase','gsp_irp_not_started'
    ),
    'ui_contract',public.gst_ui_contract_v520(p_tenant_id),
    'workspace',public.gst_compliance_workspace_v520(p_tenant_id,v_from,v_to,p_location_id),
    'masters',public.gst_masters_v520(p_tenant_id,v_to),
    'readiness',public.gst_compliance_readiness_v520(p_tenant_id),
    'documents',public.gst_documents_list_v520(p_tenant_id,v_from,v_to,p_location_id,null,'all','',v_limit,0),
    'defaults',jsonb_build_object(
      'document_limit',v_limit,'document_evidence_status','all','document_query','','document_offset',0,
      'tax_mode',v_mode
    )
  );
end
$$;


--
-- Name: FUNCTION gst_compliance_bootstrap_v520(p_tenant_id uuid, p_from date, p_to date, p_location_id uuid, p_document_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gst_compliance_bootstrap_v520(p_tenant_id uuid, p_from date, p_to date, p_location_id uuid, p_document_limit integer) IS 'THQ ERP v5.2 GST & Compliance screen bootstrap. Returns UI contract, workspace/readiness, masters and first transaction page in one call. Provider submission remains disabled.';


--
-- Name: gst_compliance_readiness_v520(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_compliance_readiness_v520(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_mode text:=private.gst_tax_mode_resolve_v520(p_tenant_id,current_date);
  v_setup jsonb;
  v_accounting jsonb;
  v_coverage jsonb;
  v_blockers jsonb:='[]'::jsonb;
  v_warnings jsonb:='[]'::jsonb;
  v_new_ready boolean:=false;
  v_history_ready boolean:=false;
  v_filing_data_ready boolean:=false;
begin
  if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.view') then
    raise exception 'GST compliance view permission required';
  end if;

  v_accounting:=public.gst_accounting_health_v520(p_tenant_id);
  v_coverage:=public.gst_snapshot_coverage_v520(p_tenant_id);
  v_history_ready:=coalesce((v_coverage->>'legacy_unverified')::bigint,0)=0
    and coalesce((v_coverage->>'unclassified_documents')::bigint,0)=0
    and coalesce((v_coverage->>'legacy_source_hash_mismatches')::bigint,0)=0;

  if v_mode='unconfigured' then
    v_setup:=jsonb_build_object(
      'stage','v5.2-tax-mode-selection',
      'tax_mode','unconfigured',
      'tax_mode_configured',false,
      'gst_setup_required',null,
      'setup_ready',false,
      'notes','Choose GST Registered or Non-GST before v5.2 transactions are enabled.'
    );
    v_blockers:=v_blockers||jsonb_build_array('tax_mode_unconfigured');
    if not coalesce((v_accounting->>'ready')::boolean,false) then
      v_blockers:=v_blockers||jsonb_build_array('gst_accounting_mapping_or_integrity_issue');
    end if;

  elsif v_mode='non_gst' then
    v_setup:=jsonb_build_object(
      'stage','v5.2-non-gst',
      'tax_mode','non_gst',
      'tax_mode_configured',true,
      'gst_applicable',false,
      'gst_setup_required',false,
      'setup_ready',true,
      'registrations',0,
      'mapped_locations',0,
      'unmapped_locations',0,
      'tax_profiles',0,
      'profiles_missing_hsn_sac',0,
      'profiles_review_required',0,
      'party_gst_profiles',0,
      'provider_connected',false,
      'provider_applicable',false,
      'einvoice_live',false,
      'ewaybill_live',false,
      'returns_live',false,
      'notes','Business is configured as Non-GST. GST registration, GST rates, HSN/SAC readiness and GSP/IRP provider setup are not required for new v5.2 transactions.'
    );
    v_new_ready:=coalesce((v_accounting->>'ready')::boolean,false);
    if not v_new_ready then
      v_blockers:=v_blockers||jsonb_build_array('accounting_mapping_or_integrity_issue');
    end if;
    if not v_history_ready then
      v_warnings:=v_warnings||jsonb_build_array('legacy_history_remains_legacy_unverified');
    end if;

  else
    -- GST-registered mode retains the original strict GST readiness rules.
    v_setup:=public.gst_setup_health_v520(p_tenant_id);
    v_new_ready:=coalesce((v_setup->>'setup_ready')::boolean,false)
      and coalesce((v_accounting->>'ready')::boolean,false);
    v_filing_data_ready:=v_new_ready and v_history_ready;

    if not coalesce((v_setup->>'setup_ready')::boolean,false) then
      v_blockers:=v_blockers||jsonb_build_array('gst_setup_incomplete');
    end if;
    if not coalesce((v_accounting->>'ready')::boolean,false) then
      v_blockers:=v_blockers||jsonb_build_array('gst_accounting_mapping_or_integrity_issue');
    end if;
    if coalesce((v_coverage->>'unclassified_documents')::bigint,0)>0 then
      v_blockers:=v_blockers||jsonb_build_array('documents_without_gst_evidence');
    end if;
    if coalesce((v_coverage->>'legacy_source_hash_mismatches')::bigint,0)>0 then
      v_blockers:=v_blockers||jsonb_build_array('legacy_evidence_source_hash_mismatch');
    end if;
    if coalesce((v_coverage->>'legacy_unverified')::bigint,0)>0 then
      v_blockers:=v_blockers||jsonb_build_array('legacy_unverified_history_requires_review_or_migration');
    end if;
    v_blockers:=v_blockers||jsonb_build_array('gsp_irp_provider_not_configured');
  end if;

  return jsonb_build_object(
    'tax_mode',v_mode,
    'tax_mode_configured',v_mode<>'unconfigured',
    'gst_applicable',v_mode='gst_registered',
    'gst_setup_required',case when v_mode='gst_registered' then true when v_mode='non_gst' then false else null end,
    'new_transaction_ready',v_new_ready,
    'transition_coverage_ready',coalesce((v_coverage->>'ready')::boolean,false),
    'historical_authoritative_complete',v_history_ready,
    'filing_applicable',v_mode='gst_registered',
    'filing_data_ready',case when v_mode='gst_registered' then v_filing_data_ready else false end,
    'provider_applicable',v_mode='gst_registered',
    'provider_ready',false,
    'submission_ready',false,
    'blockers',v_blockers,
    'warnings',v_warnings,
    'setup',v_setup,
    'accounting',v_accounting,
    'coverage',v_coverage
  );
end
$$;


--
-- Name: gst_compliance_workspace_v520(uuid, date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_compliance_workspace_v520(p_tenant_id uuid, p_from date, p_to date, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_mode text:=private.gst_tax_mode_resolve_v520(p_tenant_id,current_date);
  v_readiness jsonb;
  v_setup jsonb;
  v_dashboard jsonb;
  v_provider jsonb;
begin
  if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.view') then
    raise exception 'GST compliance view permission required';
  end if;

  v_readiness:=public.gst_compliance_readiness_v520(p_tenant_id);
  v_setup:=coalesce(v_readiness->'setup','{}'::jsonb);

  if v_mode='non_gst' then
    v_dashboard:=jsonb_build_object(
      'stage','non_gst',
      'tax_mode','non_gst',
      'provider_status','not_applicable',
      'exceptions',jsonb_build_object(
        'irn_failed',0,
        'irn_pending',0,
        'gstin_errors',0,
        'missing_hsn_sac',0,
        'ewaybill_missing',0,
        'itc_mismatch',0,
        'product_profiles_review',0
      ),
      'message','GST is not applicable for this business. New v5.2 transactions remain authoritative with zero GST.'
    );
    v_provider:=jsonb_build_object(
      'connected',false,'applicable',false,'einvoice',false,'ewaybill',false,
      'returns_submission',false,'mode','not_applicable_non_gst'
    );
  elsif v_mode='unconfigured' then
    v_dashboard:=jsonb_build_object(
      'stage','tax_mode_selection_required',
      'tax_mode','unconfigured',
      'provider_status','not_configured',
      'exceptions','{}'::jsonb,
      'message','Choose GST Registered or Non-GST to enable v5.2 transactions.'
    );
    v_provider:=jsonb_build_object(
      'connected',false,'applicable',null,'einvoice',false,'ewaybill',false,
      'returns_submission',false,'mode','waiting_for_tax_mode'
    );
  else
    v_dashboard:=public.gst_dashboard_v520(p_tenant_id);
    v_provider:=jsonb_build_object(
      'connected',false,'applicable',true,'einvoice',false,'ewaybill',false,
      'returns_submission',false,'mode','not_configured'
    );
  end if;

  return jsonb_build_object(
    'stage',case when v_mode='non_gst' then 'v5.2-non-gst-workspace'
                 when v_mode='unconfigured' then 'v5.2-tax-mode-selection'
                 else 'v5.2-compliance-workspace' end,
    'tax_mode',v_mode,
    'gst_applicable',v_mode='gst_registered',
    'readiness',v_readiness,
    'dashboard',v_dashboard,
    'setup',v_setup,
    'coverage',public.gst_snapshot_coverage_v520(p_tenant_id),
    'accounting_health',public.gst_accounting_health_v520(p_tenant_id),
    'period',public.gst_period_summary_v520(p_tenant_id,p_from,p_to,p_location_id),
    'accounting_control',public.gst_accounting_control_v520(p_tenant_id,p_from,p_to,p_location_id),
    'provider',v_provider
  );
end
$$;


--
-- Name: gst_dashboard_v520(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_dashboard_v520(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.view') then raise exception 'GST compliance view permission required';end if;return jsonb_build_object('setup',public.gst_setup_health_v520(p_tenant_id),'exceptions',jsonb_build_object('irn_pending',0,'irn_failed',0,'ewaybill_missing',0,'gstin_errors',(select count(*) from public.gst_registrations_v520 where tenant_id=p_tenant_id and validation_status='invalid'),'product_profiles_review',(select count(*) from public.gst_product_tax_profiles_v520 where tenant_id=p_tenant_id and active and effective_to is null and validation_status='review_required'),'missing_hsn_sac',(select count(*) from public.gst_product_tax_profiles_v520 where tenant_id=p_tenant_id and active and effective_to is null and hsn_sac is null),'itc_mismatch',0),'stage','foundation','provider_status','not_configured');end $$;


--
-- Name: gst_document_evidence_v520(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_document_evidence_v520(p_tenant_id uuid, p_source_type text, p_source_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_snapshot jsonb; v_legacy jsonb; v_journal jsonb; v_location uuid;
begin
 if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.view') then raise exception 'GST compliance view permission required'; end if;
 select location_id into v_location from public.gst_document_snapshots_v520 where tenant_id=p_tenant_id and source_type=p_source_type and source_id=p_source_id;
 if v_location is null then select location_id into v_location from public.gst_legacy_document_markers_v520 where tenant_id=p_tenant_id and source_type=p_source_type and source_id=p_source_id; end if;
 if v_location is not null and not private.erp_document_scope_allowed(p_tenant_id,v_location,v_location,'view') then raise exception 'Location access denied'; end if;

 v_snapshot:=public.gst_snapshot_get_v520(p_tenant_id,p_source_type,p_source_id);
 if v_snapshot is not null then
   select jsonb_build_object('entry',to_jsonb(j),'lines',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from (
       select jl.id,jl.party_type,jl.party_id,jl.description,jl.debit,jl.credit,a.system_key,a.code account_code,a.name account_name
       from public.journal_lines jl join public.accounting_accounts a on a.id=jl.account_id
       where jl.journal_entry_id=j.id order by jl.id) x),'[]'::jsonb)) into v_journal
   from public.journal_entries j where j.tenant_id=p_tenant_id and j.source_type=p_source_type and j.source_id=p_source_id and j.status='posted'
   order by j.created_at desc limit 1;
   return jsonb_build_object('evidence_status','authoritative','snapshot',v_snapshot,'journal',coalesce(v_journal,'{}'::jsonb));
 end if;

 v_legacy:=public.gst_legacy_marker_get_v520(p_tenant_id,p_source_type,p_source_id);
 if v_legacy is not null then
   select jsonb_build_object('entry',to_jsonb(j),'lines',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from (
       select jl.id,jl.party_type,jl.party_id,jl.description,jl.debit,jl.credit,a.system_key,a.code account_code,a.name account_name
       from public.journal_lines jl join public.accounting_accounts a on a.id=jl.account_id
       where jl.journal_entry_id=j.id order by jl.id) x),'[]'::jsonb)) into v_journal
   from public.journal_entries j where j.tenant_id=p_tenant_id and j.source_type=p_source_type and j.source_id=p_source_id and j.status='posted'
   order by j.created_at desc limit 1;
   return jsonb_build_object('evidence_status','legacy_unverified','legacy',v_legacy,'journal',coalesce(v_journal,'{}'::jsonb));
 end if;
 return jsonb_build_object('evidence_status','missing','source_type',p_source_type,'source_id',p_source_id);
end$$;


--
-- Name: gst_document_quote_registered_v520(uuid, text, uuid, uuid, date, text, text, jsonb, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_document_quote_registered_v520(p_tenant_id uuid, p_document_kind text, p_location_id uuid, p_party_id uuid, p_document_date date, p_supply_type text, p_place_of_supply_code text, p_items jsonb, p_additional_charges numeric DEFAULT 0, p_round_off numeric DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
 d date:=coalesce(p_document_date,current_date);kind text:=lower(trim(coalesce(p_document_kind,'')));supply text:=upper(trim(coalesce(p_supply_type,case when lower(trim(coalesce(p_document_kind,'')))='purchase' then 'B2B' else 'B2C' end)));v_party_type text;
 loc public.business_locations%rowtype;reg public.gst_registrations_v520%rowtype;reg_cfg public.gst_registration_versions_v520%rowtype;party public.gst_party_registrations_v520%rowtype;
 supplier_state text;recipient_state text;pos text:=nullif(trim(coalesce(p_place_of_supply_code,'')),'');local_uses_utgst boolean:=false;interstate boolean;zero_rated boolean:=false;without_payment boolean:=false;deemed_export boolean:=false;composition_supplier boolean:=false;document_class text:='tax_invoice';
 x jsonb;prof public.gst_product_tax_profiles_v520%rowtype;variant uuid;prod record;qty numeric;price numeric;discount numeric;gross numeric;taxable numeric;v_rate numeric;cess_rate numeric;cess_unit numeric;fixed_cess numeric;applied_rate numeric;applied_cess_rate numeric;applied_cess_unit numeric;
 raw_cgst numeric;raw_sgst numeric;raw_utgst numeric;raw_igst numeric;raw_cess numeric;cgst numeric;sgst numeric;utgst numeric;igst numeric;cess numeric;rcm_cgst numeric;rcm_sgst numeric;rcm_utgst numeric;rcm_igst numeric;rcm_cess numeric;collected_tax numeric;rcm_tax numeric;line_total numeric;line_total_sum numeric:=0;calculation_rounding numeric;calculation_rounding_total numeric:=0;
 lines jsonb:='[]'::jsonb;subtotal numeric:=0;discount_total numeric:=0;taxable_total numeric:=0;cgst_total numeric:=0;sgst_total numeric:=0;utgst_total numeric:=0;igst_total numeric:=0;cess_total numeric:=0;rcm_cgst_total numeric:=0;rcm_sgst_total numeric:=0;rcm_utgst_total numeric:=0;rcm_igst_total numeric:=0;rcm_cess_total numeric:=0;grand numeric;
 warnings text[]:='{}';errors text[]:='{}';profile_source text;profile_status text;hsn text;taxability text;inclusive boolean;rcm boolean;supply_kind text;local_tax_name text;ready boolean;has_service boolean:=false;has_rcm boolean:=false;party_required boolean:=false;party_valid boolean:=false;rate_valid boolean;
begin
 if not (private.gst_v520_has_access(p_tenant_id,'gst_compliance.calculate') or private.gst_v520_has_access(p_tenant_id,'gst_compliance.view')) then raise exception 'GST calculation permission required';end if;
 if kind not in('sale','purchase') then raise exception 'GST document kind must be sale or purchase';end if;
 v_party_type:=case when kind='sale' then 'customer' else 'supplier' end;
 if supply not in('B2B','B2C','SEZWP','SEZWOP','EXPWP','EXPWOP','DEXP','IMPG','IMPS') then raise exception 'Invalid GST supply type';end if;
 if kind='sale' and supply in('IMPG','IMPS') then raise exception 'Import supply types are purchase-only';end if;
 if kind='purchase' and supply in('EXPWP','EXPWOP','DEXP') then raise exception 'Export/deemed-export supply types are sale-only';end if;
 if jsonb_typeof(coalesce(p_items,'[]'::jsonb))<>'array' or jsonb_array_length(coalesce(p_items,'[]'::jsonb))=0 then raise exception 'GST quote requires at least one item';end if;
 if coalesce(p_additional_charges,0)<0 then raise exception 'Additional charges cannot be negative';end if;
 if abs(coalesce(p_round_off,0))>1.000001 then raise exception 'Round-off cannot exceed 1.00 in either direction';end if;
 select * into loc from public.business_locations where id=p_location_id and tenant_id=p_tenant_id and active;
 if not found then raise exception 'Active location not found';end if;
 select r.* into reg from public.gst_location_registrations_v520 m join public.gst_registrations_v520 r on r.id=m.registration_id and r.tenant_id=m.tenant_id where m.tenant_id=p_tenant_id and m.location_id=p_location_id and d between m.effective_from and coalesce(m.effective_to,'infinity'::date) order by m.effective_from desc limit 1;
 if reg.id is null then errors:=array_append(errors,'Location is not mapped to a GST registration for the document date');
 else
  select v.* into reg_cfg from public.gst_registration_versions_v520 v where v.tenant_id=p_tenant_id and v.registration_id=reg.id and d between v.effective_from and coalesce(v.effective_to,'infinity'::date) and v.active order by v.effective_from desc limit 1;
  if reg_cfg.id is null then errors:=array_append(errors,'Mapped GST registration has no active configuration version for the document date');end if;
 end if;
 if p_party_id is not null then
  select * into party from public.gst_party_registrations_v520 g where g.tenant_id=p_tenant_id and g.party_type=v_party_type and g.party_id=p_party_id and g.active and d between g.effective_from and coalesce(g.effective_to,'infinity'::date) order by g.effective_from desc,g.created_at desc limit 1;
  if party.id is null then warnings:=array_append(warnings,'Party has no normalized GST profile for the document date');end if;
 end if;
 if kind='sale' then
  supplier_state:=reg.state_code;recipient_state:=party.state_code;
  if recipient_state is null and p_party_id is not null then select public.gst_state_code_resolve_v520(c.state) into recipient_state from public.customers c where c.id=p_party_id and c.tenant_id=p_tenant_id;end if;
  composition_supplier:=coalesce(reg_cfg.registration_type,reg.registration_type)='composition';
 else
  supplier_state:=party.state_code;
  if supplier_state is null and p_party_id is not null then select public.gst_state_code_resolve_v520(s.state) into supplier_state from public.suppliers s where s.id=p_party_id and s.tenant_id=p_tenant_id;end if;
  recipient_state:=reg.state_code;composition_supplier:=coalesce(party.registration_type,'')='composition';
 end if;
 if kind='sale' and supply in('EXPWP','EXPWOP') then pos:='96';zero_rated:=true;without_payment:=supply='EXPWOP';party_required:=false;
 elsif kind='sale' and supply in('SEZWP','SEZWOP') then pos:=coalesce(pos,party.place_of_supply_code,party.state_code);zero_rated:=true;without_payment:=supply='SEZWOP';party_required:=true;
 elsif kind='sale' and supply='DEXP' then deemed_export:=true;pos:=coalesce(pos,party.place_of_supply_code,party.state_code,recipient_state);party_required:=true;
 elsif kind='purchase' and supply in('IMPG','IMPS') then pos:=coalesce(pos,recipient_state);party_required:=false;
 else
  if pos is null then pos:=case when kind='sale' then coalesce(party.place_of_supply_code,party.state_code,recipient_state) else coalesce(recipient_state,party.place_of_supply_code) end;end if;
 end if;
 if supplier_state is null and not(kind='purchase' and supply in('IMPG','IMPS')) then errors:=array_append(errors,'Supplier GST state is unresolved');end if;
 if recipient_state is null and kind='purchase' then errors:=array_append(errors,'Recipient/THQ GST state is unresolved');end if;
 if pos is null then errors:=array_append(errors,'Place of Supply is unresolved');end if;
 if pos is not null and not exists(select 1 from public.gst_state_master_v520 s where s.code=pos and s.active) then errors:=array_append(errors,'Place of Supply code is not an active GST state/special code');end if;
 party_required:=party_required or supply in('B2B','SEZWP','SEZWOP');
 party_valid:=party.id is not null and party.validation_status in('local_validated','provider_validated','not_applicable');
 if party_required and not party_valid then errors:=array_append(errors,'Normalized GST party profile is required for this supply type');end if;
 if kind='sale' and supply='B2B' and coalesce(party.registration_type,'') not in('registered','composition','sez') then errors:=array_append(errors,'B2B sale requires a registered recipient GST profile');end if;
 if kind='sale' and supply in('SEZWP','SEZWOP') and coalesce(party.registration_type,'')<>'sez' then errors:=array_append(errors,'SEZ supply requires an SEZ recipient profile');end if;
 if kind='purchase' and supply='B2B' and p_party_id is null then errors:=array_append(errors,'B2B purchase requires a supplier');end if;
 if kind='purchase' and supply in('IMPG','IMPS') then interstate:=true;
 elsif kind='sale' and supply in('SEZWP','SEZWOP','EXPWP','EXPWOP') then interstate:=true;
 else interstate:=case when supplier_state is null or pos is null then null else supplier_state<>pos end;
 end if;
 select coalesce(s.uses_utgst,false) into local_uses_utgst from public.gst_state_master_v520 s where s.code=supplier_state;
 local_tax_name:=case when local_uses_utgst then 'UTGST' else 'SGST' end;
 if composition_supplier then
  document_class:='bill_of_supply';
  if kind='sale' and interstate is true then errors:=array_append(errors,'Composition taxpayer cannot use this outward inter-State tax calculation path');end if;
  if kind='sale' and supply in('SEZWP','SEZWOP','EXPWP','EXPWOP','DEXP') then errors:=array_append(errors,'Composition taxpayer cannot use export/SEZ/deemed-export tax invoice path');end if;
 end if;
 for x in select value from jsonb_array_elements(p_items) loop
  begin variant:=(x->>'variant_id')::uuid;qty:=coalesce(nullif(x->>'quantity','')::numeric,0);price:=coalesce(nullif(x->>'unit_price','')::numeric,nullif(x->>'unit_cost','')::numeric,0);discount:=coalesce(nullif(x->>'discount_amount','')::numeric,0);exception when others then raise exception 'Invalid GST quote item';end;
  if variant is null or qty<=0 or price<0 or discount<0 then raise exception 'GST quote item has invalid product/quantity/price/discount';end if;
  select p.id product_id,p.name,p.item_type,p.tax_rate,pv.name variant_name,pv.sku,a.hsn_sac legacy_hsn into prod from public.product_variants pv join public.products p on p.id=pv.product_id and p.tenant_id=pv.tenant_id left join public.product_invoice_attributes_v45 a on a.tenant_id=pv.tenant_id and a.variant_id=pv.id where pv.id=variant and pv.tenant_id=p_tenant_id and pv.status='active' and p.status='active';
  if not found then raise exception 'GST quote product is invalid or inactive';end if;
  select * into prof from private.gst_profile_for_variant_v520(p_tenant_id,variant,d);
  if prof.id is null then
   v_rate:=coalesce(prod.tax_rate,0);cess_rate:=0;cess_unit:=0;inclusive:=false;rcm:=false;taxability:='taxable';hsn:=prod.legacy_hsn;supply_kind:=case when prod.item_type='service' then 'service' else 'goods' end;profile_source:='legacy_product';profile_status:='review_required';warnings:=array_append(warnings,'Product '||prod.sku||' has no GST profile; generic legacy tax rate used');errors:=array_append(errors,'Product '||prod.sku||' has no validated GST profile; review and validate the product GST profile before compliance posting');
  else
   v_rate:=prof.gst_rate;cess_rate:=prof.cess_rate;cess_unit:=prof.cess_per_unit;inclusive:=prof.tax_inclusive;rcm:=prof.reverse_charge;taxability:=prof.taxability;hsn:=prof.hsn_sac;supply_kind:=prof.supply_kind;profile_source:=prof.source;profile_status:=prof.validation_status;
   if prof.validation_status='review_required' then warnings:=array_append(warnings,'Product '||prod.sku||' GST profile requires review');errors:=array_append(errors,'Product '||prod.sku||' GST profile requires review and validation before compliance posting');end if;
  end if;
  if supply_kind='service' then has_service:=true;end if;if rcm then has_rcm:=true;end if;
  if hsn is null then errors:=array_append(errors,'Product '||prod.sku||' is missing HSN/SAC');end if;
  rate_valid:=taxability<>'taxable' or exists(select 1 from public.gst_tax_rate_master_v520 tr where tr.rate=v_rate and tr.active and d between tr.effective_from and coalesce(tr.effective_to,'infinity'::date));
  if not rate_valid then errors:=array_append(errors,'Product '||prod.sku||' GST rate is not in the active GST rate master for the document date');end if;
  gross:=round(qty*price,4);if discount>gross then raise exception 'GST quote discount exceeds line value';end if;gross:=gross-discount;
  applied_rate:=v_rate;applied_cess_rate:=cess_rate;applied_cess_unit:=cess_unit;
  if taxability<>'taxable' or without_payment or(composition_supplier and not rcm) then applied_rate:=0;applied_cess_rate:=0;applied_cess_unit:=0;end if;
  fixed_cess:=round(qty*applied_cess_unit,4);
  if rcm and inclusive then warnings:=array_append(warnings,'Product '||prod.sku||' is reverse-charge and tax-inclusive; price is treated as taxable value because recipient liability is not collected by supplier');end if;
  if inclusive and not rcm and(applied_rate+applied_cess_rate)>0 then
   if gross<fixed_cess then raise exception 'Tax-inclusive line value is lower than fixed cess';end if;
   taxable:=round((gross-fixed_cess)*100/(100+applied_rate+applied_cess_rate),4);
  else taxable:=round(gross,4);end if;
  raw_cgst:=0;raw_sgst:=0;raw_utgst:=0;raw_igst:=0;raw_cess:=round(taxable*applied_cess_rate/100+fixed_cess,2);
  if applied_rate>0 then
   if interstate is true then raw_igst:=round(taxable*applied_rate/100,2);
   elsif interstate is false then raw_cgst:=round(taxable*(applied_rate/2)/100,2);if local_uses_utgst then raw_utgst:=round(taxable*(applied_rate/2)/100,2);else raw_sgst:=round(taxable*(applied_rate/2)/100,2);end if;
   end if;
  end if;
  if rcm then cgst:=0;sgst:=0;utgst:=0;igst:=0;cess:=0;rcm_cgst:=raw_cgst;rcm_sgst:=raw_sgst;rcm_utgst:=raw_utgst;rcm_igst:=raw_igst;rcm_cess:=raw_cess;
  else cgst:=raw_cgst;sgst:=raw_sgst;utgst:=raw_utgst;igst:=raw_igst;cess:=raw_cess;rcm_cgst:=0;rcm_sgst:=0;rcm_utgst:=0;rcm_igst:=0;rcm_cess:=0;end if;
  collected_tax:=cgst+sgst+utgst+igst+cess;rcm_tax:=rcm_cgst+rcm_sgst+rcm_utgst+rcm_igst+rcm_cess;
  line_total:=case when inclusive and not rcm then round(gross,2) else round(taxable+collected_tax,2) end;calculation_rounding:=round(line_total-round(taxable+collected_tax,2),2);line_total_sum:=line_total_sum+line_total;calculation_rounding_total:=calculation_rounding_total+calculation_rounding;
  subtotal:=subtotal+round(qty*price,4);discount_total:=discount_total+discount;taxable_total:=taxable_total+taxable;cgst_total:=cgst_total+cgst;sgst_total:=sgst_total+sgst;utgst_total:=utgst_total+utgst;igst_total:=igst_total+igst;cess_total:=cess_total+cess;rcm_cgst_total:=rcm_cgst_total+rcm_cgst;rcm_sgst_total:=rcm_sgst_total+rcm_sgst;rcm_utgst_total:=rcm_utgst_total+rcm_utgst;rcm_igst_total:=rcm_igst_total+rcm_igst;rcm_cess_total:=rcm_cess_total+rcm_cess;
  lines:=lines||jsonb_build_array(jsonb_build_object('variant_id',variant,'product_id',prod.product_id,'product_name',prod.name,'variant_name',prod.variant_name,'sku',prod.sku,'supply_kind',supply_kind,'hsn_sac',hsn,'quantity',qty,'unit_price',price,'discount',discount,'taxability',taxability,'tax_inclusive',inclusive,'reverse_charge',rcm,'gst_rate',v_rate,'applied_gst_rate',applied_rate,'cess_rate',cess_rate,'applied_cess_rate',applied_cess_rate,'cess_per_unit',cess_unit,'applied_cess_per_unit',applied_cess_unit,'taxable_value',round(taxable,2),'cgst',cgst,'sgst',sgst,'utgst',utgst,'igst',igst,'cess',cess,'tax_amount',round(collected_tax,2),'rcm_cgst',rcm_cgst,'rcm_sgst',rcm_sgst,'rcm_utgst',rcm_utgst,'rcm_igst',rcm_igst,'rcm_cess',rcm_cess,'rcm_tax_amount',round(rcm_tax,2),'rcm_liability_party',case when rcm then case when kind='sale' then 'recipient' else 'thq' end else null end,'line_total',line_total,'calculation_rounding',calculation_rounding,'profile_source',profile_source,'profile_status',profile_status));
 end loop;
 if has_rcm and kind='sale' and (party.id is null or party.registration_type not in('registered','composition','sez')) then errors:=array_append(errors,'Outward reverse-charge supply requires a normalized registered recipient GST profile');end if;if has_service and p_place_of_supply_code is null and supply not in('EXPWP','EXPWOP','SEZWP','SEZWOP','IMPS') then errors:=array_append(errors,'Service supply requires explicit Place of Supply until service-specific place-of-supply rules are configured');end if;
 if coalesce(p_additional_charges,0)<>0 then errors:=array_append(errors,'Additional charges must be tax-classified before GST compliance posting; unclassified additional charges are not tax-calculated');end if;
 grand:=round(line_total_sum+coalesce(p_additional_charges,0)+coalesce(p_round_off,0),2);
 ready:=cardinality(errors)=0 and reg.id is not null and reg_cfg.id is not null and not exists(select 1 from jsonb_array_elements(lines) j(value) where j.value->>'profile_status'='review_required');
 return jsonb_build_object('engine','gst_v520_document_1','document_kind',kind,'document_class',document_class,'document_date',d,'supply_type',supply,'supplier_registration_id',case when kind='sale' then reg.id else null end,'supplier_gstin',case when kind='sale' then reg.gstin else party.gstin end,'supplier_state_code',supplier_state,'recipient_registration_id',case when kind='purchase' then reg.id else null end,'recipient_gstin',case when kind='purchase' then reg.gstin else party.gstin end,'recipient_state_code',recipient_state,'party_profile_id',party.id,'place_of_supply_code',pos,'interstate',interstate,'local_tax_name',local_tax_name,'zero_rated',zero_rated,'without_payment',without_payment,'deemed_export',deemed_export,'composition_supplier',composition_supplier,'lines',lines,'totals',jsonb_build_object('subtotal',round(subtotal,2),'discount',round(discount_total,2),'taxable_value',round(taxable_total,2),'cgst',round(cgst_total,2),'sgst',round(sgst_total,2),'utgst',round(utgst_total,2),'igst',round(igst_total,2),'cess',round(cess_total,2),'tax_collected_total',round(cgst_total+sgst_total+utgst_total+igst_total+cess_total,2),'rcm_cgst',round(rcm_cgst_total,2),'rcm_sgst',round(rcm_sgst_total,2),'rcm_utgst',round(rcm_utgst_total,2),'rcm_igst',round(rcm_igst_total,2),'rcm_cess',round(rcm_cess_total,2),'rcm_tax_payable_total',round(rcm_cgst_total+rcm_sgst_total+rcm_utgst_total+rcm_igst_total+rcm_cess_total,2),'thq_rcm_tax_payable_total',case when kind='purchase' then round(rcm_cgst_total+rcm_sgst_total+rcm_utgst_total+rcm_igst_total+rcm_cess_total,2) else 0 end,'recipient_rcm_tax_payable_total',case when kind='sale' then round(rcm_cgst_total+rcm_sgst_total+rcm_utgst_total+rcm_igst_total+rcm_cess_total,2) else 0 end,'government_tax_total',round(cgst_total+sgst_total+utgst_total+igst_total+cess_total+rcm_cgst_total+rcm_sgst_total+rcm_utgst_total+rcm_igst_total+rcm_cess_total,2),'additional_charges',round(coalesce(p_additional_charges,0),2),'round_off',round(coalesce(p_round_off,0),2),'calculation_rounding',round(calculation_rounding_total,2),'grand_total',grand),'ready_for_compliance',ready,'warnings',to_jsonb(warnings),'errors',to_jsonb(errors));
end $$;


--
-- Name: gst_document_quote_v520(uuid, text, uuid, uuid, date, text, text, jsonb, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_document_quote_v520(p_tenant_id uuid, p_document_kind text, p_location_id uuid, p_party_id uuid, p_document_date date, p_supply_type text, p_place_of_supply_code text, p_items jsonb, p_additional_charges numeric DEFAULT 0, p_round_off numeric DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_mode text:=private.gst_tax_mode_resolve_v520(p_tenant_id,coalesce(p_document_date,current_date));
  v jsonb;
begin
  if v_mode='unconfigured' then
    raise exception 'Business tax mode is not configured. Choose GST Registered or Non-GST before using v5.2 transactions.';
  end if;
  if v_mode='non_gst' then
    return private.gst_document_quote_non_gst_v520(
      p_tenant_id,p_document_kind,p_location_id,p_party_id,p_document_date,p_supply_type,p_place_of_supply_code,
      p_items,p_additional_charges,p_round_off
    );
  end if;
  v:=public.gst_document_quote_registered_v520(
    p_tenant_id,p_document_kind,p_location_id,p_party_id,p_document_date,p_supply_type,p_place_of_supply_code,
    p_items,p_additional_charges,p_round_off
  );
  return coalesce(v,'{}'::jsonb)||jsonb_build_object('tax_mode','gst_registered','gst_applicable',true);
end
$$;


--
-- Name: FUNCTION gst_document_quote_v520(p_tenant_id uuid, p_document_kind text, p_location_id uuid, p_party_id uuid, p_document_date date, p_supply_type text, p_place_of_supply_code text, p_items jsonb, p_additional_charges numeric, p_round_off numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gst_document_quote_v520(p_tenant_id uuid, p_document_kind text, p_location_id uuid, p_party_id uuid, p_document_date date, p_supply_type text, p_place_of_supply_code text, p_items jsonb, p_additional_charges numeric, p_round_off numeric) IS 'GST v5.2 central document quote. review_required/missing GST profiles remain hard compliance blockers and are now surfaced in errors as well as warnings.';


--
-- Name: gst_documents_list_v520(uuid, date, date, uuid, text, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_documents_list_v520(p_tenant_id uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_location_id uuid DEFAULT NULL::uuid, p_source_type text DEFAULT NULL::text, p_evidence_status text DEFAULT 'all'::text, p_query text DEFAULT ''::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_rows jsonb; v_total bigint; v_status text:=lower(trim(coalesce(p_evidence_status,'all'))); v_q text:='%'||lower(trim(coalesce(p_query,'')))||'%';
begin
 if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.view') then raise exception 'GST compliance view permission required'; end if;
 if v_status not in('all','authoritative','legacy_unverified') then raise exception 'Invalid evidence status'; end if;
 if p_from is not null and p_to is not null and p_to < p_from then raise exception 'Invalid date range'; end if;

 with docs as (
   select s.tenant_id,s.source_type,s.source_id,s.source_number,s.document_number,s.document_date,s.location_id,
     'authoritative'::text evidence_status,s.direction,s.document_class,s.supply_type,s.place_of_supply_code,
     s.taxable_total,s.government_tax_total tax_total,s.rcm_tax_payable_total,s.grand_total,s.created_at evidence_at,s.snapshot_hash evidence_hash
   from public.gst_document_snapshots_v520 s where s.tenant_id=p_tenant_id
   union all
   select m.tenant_id,m.source_type,m.source_id,m.source_number,m.source_number,m.document_date,m.location_id,
     'legacy_unverified'::text,null::text,null::text,null::text,null::text,
     m.legacy_taxable_total,m.legacy_tax_total,0::numeric,m.legacy_grand_total,m.marked_at,m.source_hash
   from public.gst_legacy_document_markers_v520 m where m.tenant_id=p_tenant_id
 ), f as (
   select d.*,l.name location_name
   from docs d left join public.business_locations l on l.id=d.location_id and l.tenant_id=d.tenant_id
   where (p_from is null or d.document_date>=p_from) and (p_to is null or d.document_date<=p_to)
     and (p_source_type is null or d.source_type=p_source_type)
     and (v_status='all' or d.evidence_status=v_status)
     and private.erp_document_scope_allowed(p_tenant_id,d.location_id,p_location_id,'view')
     and (v_q='%%' or lower(coalesce(d.document_number,'')) like v_q or lower(coalesce(d.source_number,'')) like v_q or lower(coalesce(d.source_type,'')) like v_q)
 )
 select count(*) into v_total from f;

 with docs as (
   select s.tenant_id,s.source_type,s.source_id,s.source_number,s.document_number,s.document_date,s.location_id,
     'authoritative'::text evidence_status,s.direction,s.document_class,s.supply_type,s.place_of_supply_code,
     s.taxable_total,s.government_tax_total tax_total,s.rcm_tax_payable_total,s.grand_total,s.created_at evidence_at,s.snapshot_hash evidence_hash
   from public.gst_document_snapshots_v520 s where s.tenant_id=p_tenant_id
   union all
   select m.tenant_id,m.source_type,m.source_id,m.source_number,m.source_number,m.document_date,m.location_id,
     'legacy_unverified'::text,null::text,null::text,null::text,null::text,
     m.legacy_taxable_total,m.legacy_tax_total,0::numeric,m.legacy_grand_total,m.marked_at,m.source_hash
   from public.gst_legacy_document_markers_v520 m where m.tenant_id=p_tenant_id
 ), f as (
   select d.*,l.name location_name
   from docs d left join public.business_locations l on l.id=d.location_id and l.tenant_id=d.tenant_id
   where (p_from is null or d.document_date>=p_from) and (p_to is null or d.document_date<=p_to)
     and (p_source_type is null or d.source_type=p_source_type)
     and (v_status='all' or d.evidence_status=v_status)
     and private.erp_document_scope_allowed(p_tenant_id,d.location_id,p_location_id,'view')
     and (v_q='%%' or lower(coalesce(d.document_number,'')) like v_q or lower(coalesce(d.source_number,'')) like v_q or lower(coalesce(d.source_type,'')) like v_q)
   order by d.document_date desc,d.evidence_at desc
   limit greatest(1,least(coalesce(p_limit,100),500)) offset greatest(coalesce(p_offset,0),0)
 ) select coalesce(jsonb_agg(to_jsonb(f) order by document_date desc,evidence_at desc),'[]'::jsonb) into v_rows from f;
 return jsonb_build_object('total',v_total,'limit',greatest(1,least(coalesce(p_limit,100),500)),'offset',greatest(coalesce(p_offset,0),0),'rows',coalesce(v_rows,'[]'::jsonb));
end$$;


--
-- Name: gst_gstin_validate_v520(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_gstin_validate_v520(p_gstin text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $_$ declare v text:=upper(regexp_replace(coalesce(p_gstin,''),'\s','','g'));chars constant text:='0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';i integer;val integer;factor integer;prod integer;sm integer:=0;check_index integer;expected text;actual text;fmt boolean;state_ok boolean;checksum_ok boolean;state_code text;pan text;begin fmt:=v ~ '^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$';state_code:=case when length(v)>=2 then substring(v,1,2) end;pan:=case when length(v)>=12 then substring(v,3,10) end;state_ok:=state_code is not null and exists(select 1 from public.gst_state_master_v520 s where s.code=state_code and not s.is_special_code);checksum_ok:=false;expected:=null;actual:=case when length(v)=15 then substring(v,15,1) end;if fmt then for i in 1..14 loop val:=position(substring(v,i,1) in chars)-1;factor:=case when mod(i,2)=1 then 1 else 2 end;prod:=val*factor;sm:=sm+(prod/36)+mod(prod,36);end loop;check_index:=mod(36-mod(sm,36),36);expected:=substring(chars,check_index+1,1);checksum_ok:=expected=actual;end if;return jsonb_build_object('input',p_gstin,'normalized',v,'format_valid',fmt,'state_code',state_code,'state_valid',state_ok,'pan',pan,'expected_check_digit',expected,'actual_check_digit',actual,'checksum_valid',checksum_ok,'structurally_valid',fmt and state_ok and checksum_ok,'network_status','not_checked');end $_$;


--
-- Name: gst_legacy_marker_get_v520(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_legacy_marker_get_v520(p_tenant_id uuid, p_source_type text, p_source_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare m public.gst_legacy_document_markers_v520%rowtype;p jsonb;current_hash text;begin if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.view') then raise exception 'GST compliance view permission required';end if;select * into m from public.gst_legacy_document_markers_v520 x where x.tenant_id=p_tenant_id and x.source_type=p_source_type and x.source_id=p_source_id;if not found then return null;end if;p:=private.gst_legacy_source_payload_v520(p_tenant_id,p_source_type,p_source_id);current_hash:=case when p is null then null else encode(extensions.digest(convert_to(p::text,'UTF8'),'sha256'),'hex') end;return to_jsonb(m)||jsonb_build_object('source_still_exists',p is not null,'source_hash_valid',current_hash is not null and current_hash=m.source_hash);end$$;


--
-- Name: gst_location_registration_set_v520(uuid, uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_location_registration_set_v520(p_tenant_id uuid, p_location_id uuid, p_registration_id uuid, p_effective_from date DEFAULT CURRENT_DATE) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_loc public.business_locations%rowtype;v_reg public.gst_registrations_v520%rowtype;v_current public.gst_location_registrations_v520%rowtype;v_state text;v_date date:=coalesce(p_effective_from,current_date);begin
 if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.configure') then raise exception 'GST configuration permission required';end if;
 select * into v_loc from public.business_locations where id=p_location_id and tenant_id=p_tenant_id and active;if not found then raise exception 'Active location not found';end if;
 select * into v_reg from public.gst_registrations_v520 where id=p_registration_id and tenant_id=p_tenant_id and active;if not found then raise exception 'Active GST registration not found';end if;
 if not exists(select 1 from public.gst_registration_versions_v520 v where v.tenant_id=p_tenant_id and v.registration_id=p_registration_id and v.active and v_date between v.effective_from and coalesce(v.effective_to,'infinity'::date)) then raise exception 'GST registration is not active for the requested effective date';end if;
 v_state:=public.gst_state_code_resolve_v520(v_loc.state);if v_state is not null and v_state is distinct from v_reg.state_code then raise exception 'Location state does not match GST registration state';end if;
 select * into v_current from public.gst_location_registrations_v520 where tenant_id=p_tenant_id and location_id=p_location_id and effective_to is null for update;
 if found then
  if v_date<v_current.effective_from then raise exception 'Effective date cannot precede current location GST mapping (%)',v_current.effective_from;end if;
  if v_current.registration_id=p_registration_id then return;end if;
  if v_date=v_current.effective_from then update public.gst_location_registrations_v520 set registration_id=p_registration_id where id=v_current.id;
  else update public.gst_location_registrations_v520 set effective_to=v_date-1 where id=v_current.id;insert into public.gst_location_registrations_v520(tenant_id,location_id,registration_id,effective_from,created_by) values(p_tenant_id,p_location_id,p_registration_id,v_date,auth.uid());end if;
 else insert into public.gst_location_registrations_v520(tenant_id,location_id,registration_id,effective_from,created_by) values(p_tenant_id,p_location_id,p_registration_id,v_date,auth.uid());end if;
 perform private.business_audit_write_v471(p_tenant_id,'gst.location_registration.set','business_location',p_location_id,v_loc.name,null::jsonb,jsonb_build_object('registration_id',p_registration_id,'gstin',v_reg.gstin,'effective_from',v_date));
end $$;


--
-- Name: gst_masters_v520(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_masters_v520(p_tenant_id uuid, p_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.view') then raise exception 'GST compliance view permission required';end if;return jsonb_build_object('states',(select coalesce(jsonb_agg(jsonb_build_object('code',s.code,'name',s.name,'is_union_territory',s.is_union_territory,'is_special_code',s.is_special_code,'active',s.active) order by s.code),'[]'::jsonb) from public.gst_state_master_v520 s where s.active),'rates',(select coalesce(jsonb_agg(jsonb_build_object('rate',r.rate,'label',r.label,'effective_from',r.effective_from,'source_note',r.source_note) order by r.rate),'[]'::jsonb) from public.gst_tax_rate_master_v520 r where r.active and r.effective_from<=coalesce(p_date,current_date) and (r.effective_to is null or r.effective_to>=coalesce(p_date,current_date))),'rules',(select coalesce(jsonb_agg(jsonb_build_object('key',r.rule_key,'effective_from',r.effective_from,'value',r.rule_value,'source_note',r.source_note) order by r.rule_key,r.effective_from),'[]'::jsonb) from public.gst_policy_rules_v520 r where r.active and r.effective_from<=coalesce(p_date,current_date) and (r.effective_to is null or r.effective_to>=coalesce(p_date,current_date))));end $$;


--
-- Name: gst_mobile_pos_sale_sync_v520(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_mobile_pos_sale_sync_v520(p_tenant_id uuid, p_device_id uuid, p_request_id text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_location uuid;
  v_payload jsonb;
  v_result jsonb;
begin
  v_location:=private.v488_mobile_pos_location(p_tenant_id,p_device_id);
  v_payload:=coalesce(p_payload,'{}'::jsonb) || jsonb_build_object(
    'channel','mobile_pos',
    'mobile_release','5.2',
    'mobile_contract','v5.2'
  );

  v_result:=public.gst_pos_offline_sale_sync_v520(
    p_tenant_id,p_device_id,v_location,p_request_id,v_payload
  );

  return coalesce(v_result,'{}'::jsonb) || jsonb_build_object(
    'mobile_pos',true,
    'mobile_release','5.2',
    'mobile_contract','v5.2',
    'authoritative_gst',coalesce((v_result->>'authoritative_gst')::boolean,false)
  );
end
$$;


--
-- Name: gst_mobile_pos_sale_sync_v522(uuid, uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_mobile_pos_sale_sync_v522(p_tenant_id uuid, p_device_id uuid, p_location_id uuid, p_request_id text, p_payload jsonb) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select public.gst_pos_offline_sale_sync_v522(p_tenant_id,p_device_id,p_location_id,p_request_id,p_payload);
$$;


--
-- Name: gst_party_profile_save_v520(uuid, uuid, text, uuid, text, text, text, text, text, text, text, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_party_profile_save_v520(p_tenant_id uuid, p_id uuid, p_party_type text, p_party_id uuid, p_registration_type text, p_gstin text, p_legal_name text, p_trade_name text, p_state_code text, p_place_of_supply_code text, p_address_line1 text, p_address_line2 text, p_city text, p_postal_code text, p_country text, p_active boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_id uuid;v_type text:=lower(trim(coalesce(p_party_type,'')));v_regtype text:=lower(trim(coalesce(p_registration_type,'unregistered')));v_gstin text:=nullif(upper(regexp_replace(coalesce(p_gstin,''),'\s','','g')),'');v_valid jsonb;v_state text:=nullif(trim(coalesce(p_state_code,'')),'');v_before jsonb;v_status text;v_date date:=current_date;v_current public.gst_party_registrations_v520%rowtype;begin
 if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.manage') then raise exception 'GST manage permission required';end if;if v_type not in('customer','supplier') then raise exception 'Party type must be customer or supplier';end if;if v_regtype not in('registered','unregistered','composition','sez','export','exempt') then raise exception 'Invalid GST party registration type';end if;
 if v_type='customer' and not exists(select 1 from public.customers where id=p_party_id and tenant_id=p_tenant_id) then raise exception 'Customer not found';end if;if v_type='supplier' and not exists(select 1 from public.suppliers where id=p_party_id and tenant_id=p_tenant_id) then raise exception 'Supplier not found';end if;
 if v_regtype in('registered','composition','sez') then if v_gstin is null then raise exception 'GSTIN is required for this registration type';end if;v_valid:=public.gst_gstin_validate_v520(v_gstin);if not coalesce((v_valid->>'structurally_valid')::boolean,false) then raise exception 'GSTIN failed structural/checksum validation';end if;if v_state is null then v_state:=v_valid->>'state_code';end if;if v_state is distinct from(v_valid->>'state_code') then raise exception 'Party GSTIN state and selected state differ';end if;v_status:='local_validated';else v_gstin:=null;v_status:='not_applicable';end if;
 select * into v_current from public.gst_party_registrations_v520 where tenant_id=p_tenant_id and party_type=v_type and party_id=p_party_id and effective_to is null and is_default for update;
 if p_id is not null and(v_current.id is null or v_current.id<>p_id) then raise exception 'Only the current GST party profile can be changed';end if;if v_current.id is not null then v_before:=to_jsonb(v_current);end if;
 if v_current.id is not null and v_current.effective_from=v_date then
  v_id:=v_current.id;update public.gst_party_registrations_v520 set registration_type=v_regtype,gstin=v_gstin,pan=case when v_gstin is null then null else substring(v_gstin,3,10) end,legal_name=nullif(trim(coalesce(p_legal_name,'')),''),trade_name=nullif(trim(coalesce(p_trade_name,'')),''),state_code=v_state,place_of_supply_code=nullif(trim(coalesce(p_place_of_supply_code,'')),''),address_line1=nullif(trim(coalesce(p_address_line1,'')),''),address_line2=nullif(trim(coalesce(p_address_line2,'')),''),city=nullif(trim(coalesce(p_city,'')),''),postal_code=nullif(trim(coalesce(p_postal_code,'')),''),country=coalesce(nullif(trim(coalesce(p_country,'')),''),'India'),is_default=true,validation_status=v_status,active=coalesce(p_active,true),updated_by=auth.uid(),updated_at=now() where id=v_id;
 else
  if v_current.id is not null then update public.gst_party_registrations_v520 set effective_to=v_date-1,is_default=false,updated_by=auth.uid(),updated_at=now() where id=v_current.id;end if;v_id:=gen_random_uuid();
  insert into public.gst_party_registrations_v520(id,tenant_id,party_type,party_id,registration_type,gstin,pan,legal_name,trade_name,state_code,place_of_supply_code,address_line1,address_line2,city,postal_code,country,is_default,validation_status,active,effective_from,created_by,updated_by)
  values(v_id,p_tenant_id,v_type,p_party_id,v_regtype,v_gstin,case when v_gstin is null then null else substring(v_gstin,3,10) end,nullif(trim(coalesce(p_legal_name,'')),''),nullif(trim(coalesce(p_trade_name,'')),''),v_state,nullif(trim(coalesce(p_place_of_supply_code,'')),''),nullif(trim(coalesce(p_address_line1,'')),''),nullif(trim(coalesce(p_address_line2,'')),''),nullif(trim(coalesce(p_city,'')),''),nullif(trim(coalesce(p_postal_code,'')),''),coalesce(nullif(trim(coalesce(p_country,'')),''),'India'),true,v_status,coalesce(p_active,true),v_date,auth.uid(),auth.uid());
 end if;
 perform private.business_audit_write_v471(p_tenant_id,'gst.party_profile.save','gst_party_registration',v_id,coalesce(v_gstin,p_party_id::text),v_before,(select to_jsonb(g) from public.gst_party_registrations_v520 g where g.id=v_id));return v_id;
end $$;


--
-- Name: gst_party_profiles_list_v520(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_party_profiles_list_v520(p_tenant_id uuid, p_party_type text DEFAULT NULL::text, p_query text DEFAULT ''::text, p_limit integer DEFAULT 300) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare q text:='%'||lower(trim(coalesce(p_query,'')))||'%';begin if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.view') then raise exception 'GST compliance view permission required';end if;return query select jsonb_build_object('id',g.id,'party_type',g.party_type,'party_id',g.party_id,'party_name',case when g.party_type='customer' then c.name else s.name end,'registration_type',g.registration_type,'gstin',g.gstin,'pan',g.pan,'legal_name',g.legal_name,'trade_name',g.trade_name,'state_code',g.state_code,'state_name',st.name,'place_of_supply_code',g.place_of_supply_code,'address_line1',g.address_line1,'address_line2',g.address_line2,'city',g.city,'postal_code',g.postal_code,'country',g.country,'validation_status',g.validation_status,'active',g.active,'is_default',g.is_default,'effective_from',g.effective_from,'effective_to',g.effective_to) from public.gst_party_registrations_v520 g left join public.customers c on g.party_type='customer' and c.id=g.party_id and c.tenant_id=g.tenant_id left join public.suppliers s on g.party_type='supplier' and s.id=g.party_id and s.tenant_id=g.tenant_id left join public.gst_state_master_v520 st on st.code=g.state_code where g.tenant_id=p_tenant_id and (p_party_type is null or g.party_type=lower(p_party_type)) and (trim(coalesce(p_query,''))='' or lower(coalesce(g.gstin,'')) like q or lower(coalesce(g.legal_name,'')) like q or lower(coalesce(c.name,s.name,'')) like q) order by g.active desc,g.updated_at desc limit greatest(1,least(coalesce(p_limit,300),1000));end $$;


--
-- Name: gst_period_summary_v520(uuid, date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_period_summary_v520(p_tenant_id uuid, p_from date, p_to date, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_totals jsonb; v_rates jsonb; v_legacy jsonb;
begin
 if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.view') then raise exception 'GST compliance view permission required'; end if;
 if p_from is null or p_to is null or p_to < p_from then raise exception 'Valid GST period is required'; end if;

 with s as (
   select x.*,
     case when x.source_type in('sales_return','purchase_return','credit_note') then -1::numeric else 1::numeric end as effect
   from public.gst_document_snapshots_v520 x
   where x.tenant_id=p_tenant_id
     and x.document_date between p_from and p_to
     and private.erp_document_scope_allowed(p_tenant_id,x.location_id,p_location_id,'view')
 ), a as (
   select
     count(*)::bigint documents,
     count(*) filter(where direction='outward')::bigint outward_documents,
     count(*) filter(where direction='inward')::bigint inward_documents,
     round(coalesce(sum(effect*taxable_total),0),2) net_taxable,
     round(coalesce(sum(effect*cgst_total),0),2) net_cgst,
     round(coalesce(sum(effect*sgst_total),0),2) net_sgst,
     round(coalesce(sum(effect*utgst_total),0),2) net_utgst,
     round(coalesce(sum(effect*igst_total),0),2) net_igst,
     round(coalesce(sum(effect*cess_total),0),2) net_cess,
     round(coalesce(sum(effect*tax_collected_total),0),2) net_supplier_or_customer_gst,
     round(coalesce(sum(effect*rcm_tax_payable_total),0),2) net_rcm_payable,
     round(coalesce(sum(effect*government_tax_total),0),2) net_government_tax,
     round(coalesce(sum(effect*grand_total),0),2) net_document_total,
     round(coalesce(sum(case when direction='outward' then effect*taxable_total else 0 end),0),2) outward_taxable,
     round(coalesce(sum(case when direction='outward' then effect*government_tax_total else 0 end),0),2) outward_tax,
     round(coalesce(sum(case when direction='outward' then effect*grand_total else 0 end),0),2) outward_total,
     round(coalesce(sum(case when direction='inward' then effect*taxable_total else 0 end),0),2) inward_taxable,
     round(coalesce(sum(case when direction='inward' then effect*tax_collected_total else 0 end),0),2) inward_supplier_gst,
     round(coalesce(sum(case when direction='inward' then effect*rcm_tax_payable_total else 0 end),0),2) inward_rcm_payable,
     round(coalesce(sum(case when direction='inward' then effect*grand_total else 0 end),0),2) inward_total
   from s
 ) select to_jsonb(a) into v_totals from a;

 with l as (
   select ls.applied_gst_rate rate,
     case when s.source_type in('sales_return','purchase_return','credit_note') then -1::numeric else 1::numeric end as effect,
     ls.taxable_value,ls.cgst,ls.sgst,ls.utgst,ls.igst,ls.cess,ls.rcm_tax_amount
   from public.gst_document_line_snapshots_v520 ls
   join public.gst_document_snapshots_v520 s on s.id=ls.snapshot_id and s.tenant_id=ls.tenant_id
   where s.tenant_id=p_tenant_id and s.document_date between p_from and p_to
     and private.erp_document_scope_allowed(p_tenant_id,s.location_id,p_location_id,'view')
 ), r as (
   select rate,
     round(sum(effect*taxable_value),2) taxable,
     round(sum(effect*cgst),2) cgst,
     round(sum(effect*sgst),2) sgst,
     round(sum(effect*utgst),2) utgst,
     round(sum(effect*igst),2) igst,
     round(sum(effect*cess),2) cess,
     round(sum(effect*rcm_tax_amount),2) rcm
   from l group by rate order by rate
 ) select coalesce(jsonb_agg(to_jsonb(r) order by rate),'[]'::jsonb) into v_rates from r;

 select jsonb_build_object(
   'count',count(*)::bigint,
   'taxable_total',round(coalesce(sum(legacy_taxable_total),0),2),
   'tax_total',round(coalesce(sum(legacy_tax_total),0),2),
   'grand_total',round(coalesce(sum(legacy_grand_total),0),2)
 ) into v_legacy
 from public.gst_legacy_document_markers_v520 m
 where m.tenant_id=p_tenant_id and m.document_date between p_from and p_to
   and private.erp_document_scope_allowed(p_tenant_id,m.location_id,p_location_id,'view');

 return jsonb_build_object('from',p_from,'to',p_to,'location_id',p_location_id,
   'authoritative',coalesce(v_totals,'{}'::jsonb),'rate_summary',coalesce(v_rates,'[]'::jsonb),
   'legacy_unverified',coalesce(v_legacy,'{}'::jsonb));
end$$;


--
-- Name: gst_pos_offline_sale_sync_v520(uuid, uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_pos_offline_sale_sync_v520(p_tenant_id uuid, p_device_id uuid, p_location_id uuid, p_request_id text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_request text:=nullif(trim(coalesce(p_request_id,'')),'');
  v_location uuid;
  v_identity jsonb;
  v_hash text;
  q public.pos_offline_sync_v486%rowtype;
  v_items jsonb;
  v_priced jsonb;
  v_post_priced jsonb;
  v_client jsonb;
  v_server jsonb;
  v_i integer;
  v_client_price numeric;
  v_server_price numeric;
  v_client_tax numeric;
  v_server_tax numeric;
  v_variant uuid;
  v_customer uuid;
  v_sale_date date;
  v_due_date date;
  v_local text;
  v_message text;
  v_code text;
  v_profile public.gst_product_tax_profiles_v520%rowtype;
  v_product_tax numeric;
  v_result jsonb;
  v_sale_id uuid;
  v_snapshot uuid;
  v_journal uuid;
  v_sale_request text;
begin
  if v_request is null then raise exception 'Request ID is required'; end if;
  if length(v_request)>160 then raise exception 'Offline v5.2 request ID is too long'; end if;

  v_location:=private.v486_pos_device_location(p_tenant_id,p_device_id,p_location_id);
  perform private.erp_validate_transaction_origin(p_tenant_id,v_location,p_device_id,'sales');

  v_identity:=jsonb_build_object(
    'device_id',p_device_id,
    'location_id',v_location,
    'payload',coalesce(p_payload,'{}'::jsonb)
  );
  v_hash:=private.gst_request_hash_v520(v_identity);

  perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':offline-v520:'||v_request,0));
  select * into q
  from public.pos_offline_sync_v486
  where tenant_id=p_tenant_id and request_id=v_request
  for update;

  if found then
    if coalesce(q.sync_contract_version,'v4.8.6')<>'v5.2' then
      raise exception 'Request ID already belongs to the legacy Offline POS sync contract';
    end if;
    if q.request_hash is distinct from v_hash
       or q.device_id is distinct from p_device_id
       or q.location_id is distinct from v_location
       or q.payload_snapshot is distinct from coalesce(p_payload,'{}'::jsonb) then
      raise exception 'Request ID was already used with a different Offline POS device, location, or payload';
    end if;
    if q.status='synced' then
      if q.server_response is null or q.sale_id is null or q.gst_snapshot_id is null or q.gst_journal_id is null then
        raise exception 'Synced v5.2 Offline POS request is missing authoritative recovery evidence';
      end if;
      return q.server_response||jsonb_build_object('idempotent_replay',true);
    end if;
    if q.status='cancelled' then
      raise exception 'Cancelled Offline POS request cannot be reused';
    end if;
  end if;

  v_items:=coalesce(p_payload->'items','[]'::jsonb);
  if jsonb_typeof(v_items)<>'array' or jsonb_array_length(v_items)=0 then
    raise exception 'Offline invoice has no items';
  end if;

  v_customer:=nullif(p_payload->>'customer_id','')::uuid;
  v_local:=nullif(trim(coalesce(p_payload->>'local_invoice_number','')),'');
  if v_customer is null or not exists(
    select 1 from public.customers c
    where c.id=v_customer and c.tenant_id=p_tenant_id and c.status='active'
  ) then
    return private.v520_offline_conflict(
      p_tenant_id,p_device_id,v_location,v_request,v_hash,v_local,
      'CUSTOMER_UNAVAILABLE','Customer is no longer available.',p_payload
    );
  end if;

  v_sale_date:=coalesce(nullif(p_payload->>'sale_date','')::date,current_date);
  v_due_date:=nullif(p_payload->>'due_date','')::date;
  v_priced:=private.v482_price_sale_items(p_tenant_id,v_customer,v_items,v_location);

  for v_i in 0..jsonb_array_length(v_items)-1 loop
    v_client:=v_items->v_i;
    v_server:=v_priced->v_i;
    v_variant:=nullif(v_client->>'variant_id','')::uuid;
    v_client_price:=coalesce(nullif(v_client->>'unit_price','')::numeric,0);
    v_server_price:=coalesce(nullif(v_server->>'unit_price','')::numeric,0);
    if abs(v_client_price-v_server_price)>0.005 then
      v_message:=format('Price changed for product %s. Offline %s, current %s.',v_variant,round(v_client_price,2),round(v_server_price,2));
      return private.v520_offline_conflict(
        p_tenant_id,p_device_id,v_location,v_request,v_hash,v_local,
        'PRICE_CHANGED',v_message,p_payload
      );
    end if;

    select p.tax_rate into v_product_tax
    from public.product_variants pv
    join public.products p on p.id=pv.product_id and p.tenant_id=pv.tenant_id
    where pv.id=v_variant and pv.tenant_id=p_tenant_id;
    if not found then
      return private.v520_offline_conflict(
        p_tenant_id,p_device_id,v_location,v_request,v_hash,v_local,
        'PRODUCT_UNAVAILABLE','A product on the offline invoice is no longer available.',p_payload
      );
    end if;

    select * into v_profile from private.gst_profile_for_variant_v520(p_tenant_id,v_variant,v_sale_date);
    v_server_tax:=case
      when v_profile.id is null then coalesce(v_product_tax,0)
      when v_profile.taxability='taxable' then coalesce(v_profile.gst_rate,0)
      else 0
    end;
    v_client_tax:=coalesce(nullif(v_client->>'tax_rate','')::numeric,0);
    if abs(v_client_tax-v_server_tax)>0.0001 then
      v_message:=format('Tax changed for product %s. Offline %s, current %s.',v_variant,round(v_client_tax,4),round(v_server_tax,4));
      return private.v520_offline_conflict(
        p_tenant_id,p_device_id,v_location,v_request,v_hash,v_local,
        'TAX_CHANGED',v_message,p_payload
      );
    end if;
  end loop;

  insert into public.pos_offline_sync_v486(
    tenant_id,request_id,device_id,location_id,local_invoice_number,status,
    payload_snapshot,attempts,last_attempt_at,created_by,updated_at,
    sync_contract_version,request_hash
  ) values(
    p_tenant_id,v_request,p_device_id,v_location,v_local,'syncing',
    p_payload,1,now(),auth.uid(),now(),'v5.2',v_hash
  )
  on conflict(tenant_id,request_id) do update set
    status='syncing',
    attempts=public.pos_offline_sync_v486.attempts+1,
    last_attempt_at=now(),
    updated_at=now(),
    conflict_code=null,
    conflict_message=null;

  begin
    v_sale_request:='offline-v520:'||v_request;
    v_result:=public.gst_sale_create_v520(
      p_tenant_id,
      v_customer,
      v_sale_date,
      v_due_date,
      v_items,
      coalesce(nullif(p_payload->>'additional_charges','')::numeric,0),
      coalesce(nullif(p_payload->>'round_off','')::numeric,0),
      coalesce(nullif(p_payload->>'initial_payment','')::numeric,0),
      coalesce(nullif(p_payload->>'payment_method',''),'cash'),
      coalesce(p_payload->>'payment_reference',''),
      trim(concat_ws(' • ',nullif(p_payload->>'notes',''),'Offline POS '||coalesce(v_local,''))),
      v_location,
      p_device_id,
      v_sale_request,
      nullif(p_payload->>'supply_type',''),
      nullif(p_payload->>'place_of_supply_code','')
    );

    v_sale_id:=nullif(v_result->>'sale_id','')::uuid;
    v_snapshot:=nullif(v_result->>'gst_snapshot_id','')::uuid;
    v_journal:=nullif(v_result->>'journal_id','')::uuid;
    if v_sale_id is null or v_snapshot is null or v_journal is null then
      raise exception 'Authoritative GST Sale did not return complete evidence';
    end if;

    -- Re-check after the authoritative Sale call. If price/tax changed concurrently
    -- between the initial conflict check and acceptance, roll the Sale back and leave
    -- the offline request as a conflict rather than accepting a different invoice.
    v_post_priced:=private.v482_price_sale_items(p_tenant_id,v_customer,v_items,v_location);
    for v_i in 0..jsonb_array_length(v_items)-1 loop
      v_client:=v_items->v_i;
      v_server:=v_post_priced->v_i;
      v_variant:=nullif(v_client->>'variant_id','')::uuid;
      v_client_price:=coalesce(nullif(v_client->>'unit_price','')::numeric,0);
      v_server_price:=coalesce(nullif(v_server->>'unit_price','')::numeric,0);
      if abs(v_client_price-v_server_price)>0.005 then
        raise exception 'OFFLINE_PRICE_CHANGED: product % changed during sync',v_variant;
      end if;
      select p.tax_rate into v_product_tax
      from public.product_variants pv
      join public.products p on p.id=pv.product_id and p.tenant_id=pv.tenant_id
      where pv.id=v_variant and pv.tenant_id=p_tenant_id;
      select * into v_profile from private.gst_profile_for_variant_v520(p_tenant_id,v_variant,v_sale_date);
      v_server_tax:=case
        when v_profile.id is null then coalesce(v_product_tax,0)
        when v_profile.taxability='taxable' then coalesce(v_profile.gst_rate,0)
        else 0
      end;
      v_client_tax:=coalesce(nullif(v_client->>'tax_rate','')::numeric,0);
      if abs(v_client_tax-v_server_tax)>0.0001 then
        raise exception 'OFFLINE_TAX_CHANGED: product % changed during sync',v_variant;
      end if;
    end loop;
  exception when others then
    v_message:=sqlerrm;
    if v_message like 'OFFLINE_PRICE_CHANGED:%' then
      v_code:='PRICE_CHANGED';
    elsif v_message like 'OFFLINE_TAX_CHANGED:%' then
      v_code:='TAX_CHANGED';
    elsif v_message ilike '%stock%' or v_message ilike '%serial%' or v_message ilike '%batch%' or v_message ilike '%reconciled%' then
      v_code:='STOCK_CONFLICT';
    else
      v_code:='SERVER_VALIDATION';
    end if;
    return private.v520_offline_conflict(
      p_tenant_id,p_device_id,v_location,v_request,v_hash,v_local,
      v_code,v_message,p_payload
    );
  end;

  v_result:=coalesce(v_result,'{}'::jsonb)||jsonb_build_object(
    'ok',true,
    'status','synced',
    'request_id',v_request,
    'local_invoice_number',v_local,
    'offline_sync','v5.2',
    'offline_contract','authoritative_gst',
    'authoritative_gst',true
  );

  update public.pos_offline_sync_v486 set
    status='synced',
    server_response=v_result,
    conflict_code=null,
    conflict_message=null,
    sale_id=v_sale_id,
    gst_snapshot_id=v_snapshot,
    gst_journal_id=v_journal,
    synced_at=now(),
    last_attempt_at=now(),
    updated_at=now()
  where tenant_id=p_tenant_id and request_id=v_request;

  return v_result;
end
$$;


--
-- Name: gst_pos_offline_sale_sync_v522(uuid, uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_pos_offline_sale_sync_v522(p_tenant_id uuid, p_device_id uuid, p_location_id uuid, p_request_id text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_request text:=nullif(trim(coalesce(p_request_id,'')),'');
  v_location uuid;v_identity jsonb;v_hash text;q public.pos_offline_sync_v486%rowtype;
  v_items jsonb;v_priced jsonb;v_post_priced jsonb;v_client jsonb;v_server jsonb;
  v_i integer;v_client_price numeric;v_server_price numeric;v_client_tax numeric;v_server_tax numeric;
  v_variant uuid;v_customer uuid;v_sale_date date;v_due_date date;v_local text;v_message text;v_code text;
  v_profile public.gst_product_tax_profiles_v520%rowtype;v_product_tax numeric;
  v_result jsonb;v_sale_id uuid;v_snapshot uuid;v_journal uuid;v_sale_request text;
  v_allocations jsonb;
begin
  if v_request is null then raise exception 'Request ID is required'; end if;
  if length(v_request)>160 then raise exception 'Offline v5.2.2 request ID is too long'; end if;
  v_location:=private.v486_pos_device_location(p_tenant_id,p_device_id,p_location_id);
  perform private.erp_validate_transaction_origin(p_tenant_id,v_location,p_device_id,'sales');

  if coalesce(nullif(p_payload->>'additional_charges','')::numeric,0)<>0 then
    return private.v520_offline_conflict(p_tenant_id,p_device_id,v_location,v_request,
      private.gst_request_hash_v520(jsonb_build_object('device_id',p_device_id,'location_id',v_location,'payload',coalesce(p_payload,'{}'::jsonb))),
      nullif(trim(coalesce(p_payload->>'local_invoice_number','')),''),
      'UNCLASSIFIED_CHARGE','Additional Charges are not supported. Add a GST-classified Service product instead.',p_payload);
  end if;

  v_identity:=jsonb_build_object('device_id',p_device_id,'location_id',v_location,'payload',coalesce(p_payload,'{}'::jsonb));
  v_hash:=private.gst_request_hash_v520(v_identity);
  perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':offline-v522:'||v_request,0));

  select * into q from public.pos_offline_sync_v486
  where tenant_id=p_tenant_id and request_id=v_request for update;
  if found then
    if coalesce(q.sync_contract_version,'v4.8.6') not in ('v5.2.2','v5.2') then
      raise exception 'Request ID already belongs to a legacy Offline POS sync contract';
    end if;
    if q.request_hash is distinct from v_hash or q.device_id is distinct from p_device_id or
       q.location_id is distinct from v_location or q.payload_snapshot is distinct from coalesce(p_payload,'{}'::jsonb) then
      raise exception 'Request ID was already used with a different Offline POS device, location, or payload';
    end if;
    if q.status='synced' then
      if q.server_response is null or q.sale_id is null or q.gst_snapshot_id is null or q.gst_journal_id is null then
        raise exception 'Synced v5.2.2 Offline POS request is missing authoritative recovery evidence';
      end if;
      return q.server_response||jsonb_build_object('idempotent_replay',true);
    end if;
    if q.status='cancelled' then raise exception 'Cancelled Offline POS request cannot be reused'; end if;
  end if;

  v_items:=coalesce(p_payload->'items','[]'::jsonb);
  if jsonb_typeof(v_items)<>'array' or jsonb_array_length(v_items)=0 then raise exception 'Offline invoice has no items'; end if;
  v_customer:=nullif(p_payload->>'customer_id','')::uuid;
  v_local:=nullif(trim(coalesce(p_payload->>'local_invoice_number','')),'');
  if v_customer is null or not exists(select 1 from public.customers c where c.id=v_customer and c.tenant_id=p_tenant_id and c.status='active') then
    return private.v520_offline_conflict(p_tenant_id,p_device_id,v_location,v_request,v_hash,v_local,'CUSTOMER_UNAVAILABLE','Customer is no longer available.',p_payload);
  end if;

  v_sale_date:=coalesce(nullif(p_payload->>'sale_date','')::date,current_date);
  v_due_date:=nullif(p_payload->>'due_date','')::date;
  v_allocations:=coalesce(p_payload->'payment_allocations','[]'::jsonb);
  if jsonb_typeof(v_allocations)<>'array' or jsonb_array_length(v_allocations)=0 then
    return private.v520_offline_conflict(p_tenant_id,p_device_id,v_location,v_request,v_hash,v_local,'PAYMENT_ALLOCATION_REQUIRED','Build 30 offline invoices require payment_allocations.',p_payload);
  end if;

  v_priced:=private.v482_price_sale_items(p_tenant_id,v_customer,v_items,v_location);
  for v_i in 0..jsonb_array_length(v_items)-1 loop
    v_client:=v_items->v_i;v_server:=v_priced->v_i;v_variant:=nullif(v_client->>'variant_id','')::uuid;
    v_client_price:=coalesce(nullif(v_client->>'unit_price','')::numeric,0);v_server_price:=coalesce(nullif(v_server->>'unit_price','')::numeric,0);
    if abs(v_client_price-v_server_price)>0.005 then
      v_message:=format('Price changed for product %s. Offline %s, current %s.',v_variant,round(v_client_price,2),round(v_server_price,2));
      return private.v520_offline_conflict(p_tenant_id,p_device_id,v_location,v_request,v_hash,v_local,'PRICE_CHANGED',v_message,p_payload);
    end if;
    select p.tax_rate into v_product_tax from public.product_variants pv join public.products p on p.id=pv.product_id and p.tenant_id=pv.tenant_id
    where pv.id=v_variant and pv.tenant_id=p_tenant_id;
    if not found then return private.v520_offline_conflict(p_tenant_id,p_device_id,v_location,v_request,v_hash,v_local,'PRODUCT_UNAVAILABLE','A product on the offline invoice is no longer available.',p_payload); end if;
    select * into v_profile from private.gst_profile_for_variant_v520(p_tenant_id,v_variant,v_sale_date);
    v_server_tax:=case when v_profile.id is null then coalesce(v_product_tax,0) when v_profile.taxability='taxable' then coalesce(v_profile.gst_rate,0) else 0 end;
    v_client_tax:=coalesce(nullif(v_client->>'tax_rate','')::numeric,0);
    if abs(v_client_tax-v_server_tax)>0.0001 then
      v_message:=format('Tax changed for product %s. Offline %s, current %s.',v_variant,round(v_client_tax,4),round(v_server_tax,4));
      return private.v520_offline_conflict(p_tenant_id,p_device_id,v_location,v_request,v_hash,v_local,'TAX_CHANGED',v_message,p_payload);
    end if;
  end loop;

  insert into public.pos_offline_sync_v486(tenant_id,request_id,device_id,location_id,local_invoice_number,status,payload_snapshot,attempts,last_attempt_at,created_by,updated_at,sync_contract_version,request_hash)
  values(p_tenant_id,v_request,p_device_id,v_location,v_local,'syncing',p_payload,1,now(),auth.uid(),now(),'v5.2.2',v_hash)
  on conflict(tenant_id,request_id) do update set status='syncing',attempts=public.pos_offline_sync_v486.attempts+1,last_attempt_at=now(),updated_at=now(),conflict_code=null,conflict_message=null;

  begin
    v_sale_request:='offline-v522:'||v_request;
    v_result:=public.gst_sale_create_v522(p_tenant_id,v_customer,v_sale_date,v_due_date,v_items,v_allocations,
      trim(concat_ws(' • ',nullif(p_payload->>'notes',''),'Offline POS '||coalesce(v_local,''))),v_location,p_device_id,v_sale_request,
      nullif(p_payload->>'supply_type',''),nullif(p_payload->>'place_of_supply_code',''));
    v_sale_id:=nullif(v_result->>'sale_id','')::uuid;v_snapshot:=nullif(v_result->>'gst_snapshot_id','')::uuid;v_journal:=nullif(v_result->>'journal_id','')::uuid;
    if v_sale_id is null or v_snapshot is null or v_journal is null then raise exception 'Authoritative GST Sale did not return complete evidence'; end if;

    v_post_priced:=private.v482_price_sale_items(p_tenant_id,v_customer,v_items,v_location);
    for v_i in 0..jsonb_array_length(v_items)-1 loop
      v_client:=v_items->v_i;v_server:=v_post_priced->v_i;v_variant:=nullif(v_client->>'variant_id','')::uuid;
      v_client_price:=coalesce(nullif(v_client->>'unit_price','')::numeric,0);v_server_price:=coalesce(nullif(v_server->>'unit_price','')::numeric,0);
      if abs(v_client_price-v_server_price)>0.005 then raise exception 'OFFLINE_PRICE_CHANGED: product % changed during sync',v_variant; end if;
      select p.tax_rate into v_product_tax from public.product_variants pv join public.products p on p.id=pv.product_id and p.tenant_id=pv.tenant_id where pv.id=v_variant and pv.tenant_id=p_tenant_id;
      select * into v_profile from private.gst_profile_for_variant_v520(p_tenant_id,v_variant,v_sale_date);
      v_server_tax:=case when v_profile.id is null then coalesce(v_product_tax,0) when v_profile.taxability='taxable' then coalesce(v_profile.gst_rate,0) else 0 end;
      v_client_tax:=coalesce(nullif(v_client->>'tax_rate','')::numeric,0);
      if abs(v_client_tax-v_server_tax)>0.0001 then raise exception 'OFFLINE_TAX_CHANGED: product % changed during sync',v_variant; end if;
    end loop;
  exception when others then
    v_message:=sqlerrm;
    if v_message like 'OFFLINE_PRICE_CHANGED:%' then v_code:='PRICE_CHANGED';
    elsif v_message like 'OFFLINE_TAX_CHANGED:%' then v_code:='TAX_CHANGED';
    elsif v_message ilike '%stock%' or v_message ilike '%serial%' or v_message ilike '%batch%' or v_message ilike '%reconciled%' then v_code:='STOCK_CONFLICT';
    elsif v_message ilike '%payment%' or v_message ilike '%credit%' or v_message ilike '%ledger%' then v_code:='PAYMENT_CONFLICT';
    else v_code:='SERVER_VALIDATION'; end if;
    return private.v520_offline_conflict(p_tenant_id,p_device_id,v_location,v_request,v_hash,v_local,v_code,v_message,p_payload);
  end;

  v_result:=coalesce(v_result,'{}'::jsonb)||jsonb_build_object('ok',true,'status','synced','request_id',v_request,'local_invoice_number',v_local,
    'offline_sync','v5.2.2','offline_contract','authoritative_gst_multi_payment','authoritative_gst',true,'gst_journal_id',v_journal);
  update public.pos_offline_sync_v486 set status='synced',server_response=v_result,conflict_code=null,conflict_message=null,sale_id=v_sale_id,
    gst_snapshot_id=v_snapshot,gst_journal_id=v_journal,synced_at=now(),last_attempt_at=now(),updated_at=now(),sync_contract_version='v5.2.2'
  where tenant_id=p_tenant_id and request_id=v_request;
  return v_result;
end;
$$;


--
-- Name: gst_pos_sale_create_v522(uuid, uuid, date, date, jsonb, jsonb, text, uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_pos_sale_create_v522(p_tenant_id uuid, p_customer_id uuid, p_sale_date date, p_due_date date, p_items jsonb, p_payment_allocations jsonb, p_notes text DEFAULT NULL::text, p_location_id uuid DEFAULT NULL::uuid, p_device_id uuid DEFAULT NULL::uuid, p_request_id text DEFAULT NULL::text, p_supply_type text DEFAULT NULL::text, p_place_of_supply_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
 select public.gst_sale_create_v522(p_tenant_id,p_customer_id,p_sale_date,p_due_date,p_items,p_payment_allocations,p_notes,p_location_id,p_device_id,p_request_id,p_supply_type,p_place_of_supply_code);
$$;


--
-- Name: gst_product_profile_save_v520(uuid, uuid, text, text, text, numeric, numeric, numeric, boolean, boolean, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_product_profile_save_v520(p_tenant_id uuid, p_variant_id uuid, p_supply_kind text, p_hsn_sac text, p_taxability text, p_gst_rate numeric, p_cess_rate numeric, p_cess_per_unit numeric, p_tax_inclusive boolean, p_reverse_charge boolean, p_notes text, p_effective_from date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $_$
declare
 v_id uuid;v_kind text:=lower(trim(coalesce(p_supply_kind,'')));v_taxability text:=lower(trim(coalesce(p_taxability,'taxable')));
 v_hsn text:=nullif(regexp_replace(coalesce(p_hsn_sac,''),'\s','','g'),'');v_rate numeric:=coalesce(p_gst_rate,0);v_status text;
 v_old jsonb;v_old_effective date;v_effective date:=coalesce(p_effective_from,current_date);
begin
 if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.manage') then raise exception 'GST manage permission required';end if;
 if not exists(select 1 from public.product_variants where id=p_variant_id and tenant_id=p_tenant_id) then raise exception 'Product variant not found';end if;
 if v_kind not in('goods','service') then raise exception 'Supply kind must be goods or service';end if;
 if v_taxability not in('taxable','nil_rated','exempt','non_gst') then raise exception 'Invalid taxability';end if;
 if v_hsn is not null and v_hsn !~ '^[0-9]{4}([0-9]{2})?([0-9]{2})?$' then raise exception 'HSN/SAC must be 4, 6 or 8 digits';end if;
 if v_taxability<>'taxable' then v_rate:=0;end if;
 if v_rate<0 or v_rate>100 or coalesce(p_cess_rate,0)<0 or coalesce(p_cess_rate,0)>100 or coalesce(p_cess_per_unit,0)<0 then raise exception 'Invalid GST/Cess rate';end if;
 v_status:=case when v_hsn is not null and exists(select 1 from public.gst_tax_rate_master_v520 r where r.rate=v_rate and r.active and r.effective_from<=v_effective and (r.effective_to is null or r.effective_to>=v_effective)) then 'locally_validated' else 'review_required' end;
 select to_jsonb(g),g.id,g.effective_from into v_old,v_id,v_old_effective
 from public.gst_product_tax_profiles_v520 g
 where g.tenant_id=p_tenant_id and g.variant_id=p_variant_id and g.active and g.effective_to is null
 order by g.effective_from desc limit 1 for update;
 if v_id is not null and v_old_effective>=v_effective then
   update public.gst_product_tax_profiles_v520
   set supply_kind=v_kind,hsn_sac=v_hsn,taxability=v_taxability,gst_rate=v_rate,cess_rate=coalesce(p_cess_rate,0),cess_per_unit=coalesce(p_cess_per_unit,0),
       tax_inclusive=coalesce(p_tax_inclusive,false),reverse_charge=coalesce(p_reverse_charge,false),validation_status=v_status,source='manual',
       notes=nullif(trim(coalesce(p_notes,'')),''),effective_from=v_effective,updated_by=auth.uid(),updated_at=now()
   where id=v_id;
 else
   if v_id is not null then update public.gst_product_tax_profiles_v520 set effective_to=v_effective-1,updated_at=now(),updated_by=auth.uid() where id=v_id;end if;
   v_id:=gen_random_uuid();
   insert into public.gst_product_tax_profiles_v520(id,tenant_id,variant_id,supply_kind,hsn_sac,taxability,gst_rate,cess_rate,cess_per_unit,tax_inclusive,reverse_charge,validation_status,source,notes,active,effective_from,created_by,updated_by)
   values(v_id,p_tenant_id,p_variant_id,v_kind,v_hsn,v_taxability,v_rate,coalesce(p_cess_rate,0),coalesce(p_cess_per_unit,0),coalesce(p_tax_inclusive,false),coalesce(p_reverse_charge,false),v_status,'manual',nullif(trim(coalesce(p_notes,'')),''),true,v_effective,auth.uid(),auth.uid());
 end if;
 perform private.business_audit_write_v471(p_tenant_id,'gst.product_profile.save','product_variant',p_variant_id,null,v_old,(select to_jsonb(g) from public.gst_product_tax_profiles_v520 g where g.id=v_id));
 return v_id;
end $_$;


--
-- Name: gst_product_profiles_list_v520(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_product_profiles_list_v520(p_tenant_id uuid, p_query text DEFAULT ''::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 500) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare q text:='%'||lower(trim(coalesce(p_query,'')))||'%';begin if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.view') then raise exception 'GST compliance view permission required';end if;return query select jsonb_build_object('id',g.id,'variant_id',g.variant_id,'product_id',p.id,'product_name',p.name,'variant_name',pv.name,'sku',pv.sku,'item_type',p.item_type,'supply_kind',g.supply_kind,'hsn_sac',g.hsn_sac,'taxability',g.taxability,'gst_rate',g.gst_rate,'cess_rate',g.cess_rate,'cess_per_unit',g.cess_per_unit,'tax_inclusive',g.tax_inclusive,'reverse_charge',g.reverse_charge,'validation_status',g.validation_status,'source',g.source,'notes',g.notes,'active',g.active,'effective_from',g.effective_from,'effective_to',g.effective_to) from public.gst_product_tax_profiles_v520 g join public.product_variants pv on pv.id=g.variant_id and pv.tenant_id=g.tenant_id join public.products p on p.id=pv.product_id where g.tenant_id=p_tenant_id and (p_status is null or g.validation_status=p_status) and (trim(coalesce(p_query,''))='' or lower(p.name) like q or lower(pv.sku) like q or lower(coalesce(g.hsn_sac,'')) like q) order by g.active desc,p.name,pv.name limit greatest(1,least(coalesce(p_limit,500),2000));end $$;


--
-- Name: gst_product_profiles_validate_imported_v600(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_product_profiles_validate_imported_v600(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $_$
declare
  v_row record;
  v_before jsonb;
  v_after jsonb;
  v_candidates integer := 0;
  v_validated integer := 0;
  v_remaining integer := 0;
  v_hsn text;
begin
  if not private.gst_v520_has_access(
    p_tenant_id,
    'gst_compliance.manage'
  ) then
    raise exception 'GST manage permission required';
  end if;

  for v_row in
    select
      g.id,
      g.variant_id,
      g.hsn_sac,
      g.gst_rate,
      g.effective_from
    from public.gst_product_tax_profiles_v520 g
    join public.product_variants pv
      on pv.id = g.variant_id
     and pv.tenant_id = g.tenant_id
    join public.products p
      on p.id = pv.product_id
     and p.tenant_id = pv.tenant_id
    where g.tenant_id = p_tenant_id
      and g.active
      and g.validation_status = 'review_required'
      and coalesce(g.source, '') like 'legacy%'
      and g.effective_from <= current_date
      and (g.effective_to is null or g.effective_to >= current_date)
      and pv.status = 'active'
      and p.status = 'active'
    order by g.created_at, g.id
    for update of g
  loop
    v_candidates := v_candidates + 1;
    v_hsn := nullif(
      regexp_replace(coalesce(v_row.hsn_sac, ''), '\s', '', 'g'),
      ''
    );

    if v_hsn is not null
       and v_hsn ~ '^[0-9]{4}([0-9]{2})?([0-9]{2})?$'
       and exists (
         select 1
         from public.gst_tax_rate_master_v520 r
         where r.rate = coalesce(v_row.gst_rate, 0)
           and r.active
           and r.effective_from <= v_row.effective_from
           and (
             r.effective_to is null
             or r.effective_to >= v_row.effective_from
           )
       ) then
      select to_jsonb(g)
      into v_before
      from public.gst_product_tax_profiles_v520 g
      where g.id = v_row.id;

      update public.gst_product_tax_profiles_v520
      set
        validation_status = 'locally_validated',
        updated_by = auth.uid(),
        updated_at = now()
      where id = v_row.id
        and tenant_id = p_tenant_id
        and validation_status = 'review_required';

      if found then
        v_validated := v_validated + 1;

        select to_jsonb(g)
        into v_after
        from public.gst_product_tax_profiles_v520 g
        where g.id = v_row.id;

        perform private.business_audit_write_v471(
          p_tenant_id,
          'gst.product_profile.validate_imported',
          'product_variant',
          v_row.variant_id,
          v_row.id::text,
          v_before,
          v_after
        );
      end if;
    end if;
  end loop;

  select count(*)
  into v_remaining
  from public.gst_product_tax_profiles_v520 g
  join public.product_variants pv
    on pv.id = g.variant_id
   and pv.tenant_id = g.tenant_id
  join public.products p
    on p.id = pv.product_id
   and p.tenant_id = pv.tenant_id
  where g.tenant_id = p_tenant_id
    and g.active
    and g.validation_status = 'review_required'
    and coalesce(g.source, '') like 'legacy%'
    and g.effective_from <= current_date
    and (g.effective_to is null or g.effective_to >= current_date)
    and pv.status = 'active'
    and p.status = 'active';

  return jsonb_build_object(
    'success', true,
    'candidates', v_candidates,
    'validated', v_validated,
    'skipped', greatest(v_candidates - v_validated, 0),
    'remaining_review', v_remaining
  );
end;
$_$;


--
-- Name: FUNCTION gst_product_profiles_validate_imported_v600(p_tenant_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gst_product_profiles_validate_imported_v600(p_tenant_id uuid) IS 'Explicitly validates current legacy-imported GST product profiles against local THQ v5.2 rules. Never silently promotes invalid profiles.';


--
-- Name: gst_purchase_create_v520(uuid, uuid, text, date, date, jsonb, numeric, numeric, numeric, text, text, text, uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_purchase_create_v520(p_tenant_id uuid, p_supplier_id uuid, p_supplier_invoice_number text, p_purchase_date date, p_due_date date, p_items jsonb, p_additional_charges numeric DEFAULT 0, p_round_off numeric DEFAULT 0, p_initial_payment numeric DEFAULT 0, p_payment_method text DEFAULT 'cash'::text, p_payment_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_location_id uuid DEFAULT NULL::uuid, p_device_id uuid DEFAULT NULL::uuid, p_request_id text DEFAULT NULL::text, p_supply_type text DEFAULT NULL::text, p_place_of_supply_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_req_payload jsonb;v_req_state jsonb;v_old_req jsonb;v_supply text;v_normalized jsonb;v_quote jsonb;v_bridge jsonb;v_basis jsonb;v_recon jsonb;v_source jsonb;v_purchase_id uuid;v_purchase_number text;v_snapshot uuid;v_journal uuid;v_document_number text;v_response jsonb;v_totals jsonb;v_supplier_invoice text:=nullif(trim(coalesce(p_supplier_invoice_number,'')),'');
begin
 if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
 if not(private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'purchases.manage')) then raise exception 'Purchases permission required';end if;
 if not(private.gst_v520_has_access(p_tenant_id,'gst_compliance.calculate') or private.gst_v520_has_access(p_tenant_id,'gst_compliance.view')) then raise exception 'GST calculation permission required';end if;
 if p_location_id is null then raise exception 'Business location is required';end if;
 if v_supplier_invoice is null then raise exception 'Supplier invoice number is required for an authoritative GST Purchase';end if;
 if coalesce(p_additional_charges,0)<>0 then raise exception 'Additional charges are not enabled for authoritative GST Purchases until charge-level GST classification is configured';end if;
 if p_purchase_date is null then raise exception 'Purchase date is required';end if;if p_due_date is not null and p_due_date<p_purchase_date then raise exception 'Due date cannot be before purchase date';end if;if coalesce(p_initial_payment,0)<0 then raise exception 'Initial payment cannot be negative';end if;
 v_req_payload:=jsonb_build_object('supplier_id',p_supplier_id,'supplier_invoice_number',v_supplier_invoice,'purchase_date',p_purchase_date,'due_date',p_due_date,'items',coalesce(p_items,'[]'::jsonb),'additional_charges',coalesce(p_additional_charges,0),'round_off',coalesce(p_round_off,0),'initial_payment',coalesce(p_initial_payment,0),'payment_method',lower(trim(coalesce(p_payment_method,''))),'payment_reference',nullif(trim(coalesce(p_payment_reference,'')),''),'notes',nullif(trim(coalesce(p_notes,'')),''),'location_id',p_location_id,'device_id',p_device_id,'supply_type',nullif(upper(trim(coalesce(p_supply_type,''))),''),'place_of_supply_code',nullif(trim(coalesce(p_place_of_supply_code,'')),''));
 v_req_state:=private.gst_request_begin_v520(p_tenant_id,p_request_id,'gst.purchase.create.v520',v_req_payload);if coalesce((v_req_state->>'existing')::boolean,false) then return v_req_state->'response';end if;
 v_old_req:=private.v47_request_existing(p_tenant_id,p_request_id,'purchase.create');if v_old_req is not null then raise exception 'Request ID is already used by the legacy Purchase path';end if;
 v_normalized:=private.v481_normalize_items(p_tenant_id,p_items,'purchase');v_basis:=private.gst_purchase_inventory_basis_capture_v520(p_tenant_id,v_normalized);v_supply:=private.gst_purchase_supply_type_resolve_v520(p_tenant_id,p_supplier_id,p_purchase_date,p_supply_type);
 v_quote:=public.gst_purchase_quote_v520(p_tenant_id,p_location_id,p_supplier_id,p_purchase_date,v_supply,p_place_of_supply_code,v_normalized,0,p_round_off);
 if coalesce((v_quote->>'ready_for_compliance')::boolean,false) is not true then raise exception 'GST Purchase is not compliance-ready: %',coalesce(v_quote->'errors','[]'::jsonb)::text;end if;
 v_totals:=v_quote->'totals';if coalesce(p_initial_payment,0)>coalesce((v_totals->>'grand_total')::numeric,0)+0.005 then raise exception 'Payment cannot exceed GST Purchase total';end if;
 v_bridge:=private.gst_purchase_bridge_v520(p_items,v_normalized,(v_totals->>'grand_total')::numeric);
 perform private.gst_authoritative_context_enter_v520(p_tenant_id,'purchase');
 v_source:=public.purchases_create_v483(p_tenant_id,p_supplier_id,v_supplier_invoice,p_purchase_date,p_due_date,v_bridge->'items',(v_bridge->>'additional_charges')::numeric,p_initial_payment,p_payment_method,p_notes,p_location_id,p_device_id,p_request_id);
 v_purchase_id:=nullif(v_source->>'purchase_id','')::uuid;if v_purchase_id is null then raise exception 'GST Purchase source could not be resolved';end if;perform private.gst_authoritative_context_bind_v520(v_purchase_id);
 select p.purchase_number into v_purchase_number from public.purchases p where p.tenant_id=p_tenant_id and p.id=v_purchase_id and p.status='posted' and lower(trim(coalesce(p.supplier_invoice_number,'')))=lower(v_supplier_invoice) for update;
 if v_purchase_number is null then raise exception 'GST Purchase source is not posted or supplier invoice identity changed';end if;
 if exists(select 1 from public.journal_entries j where j.tenant_id=p_tenant_id and j.source_type='purchase' and j.source_id=v_purchase_id and j.status='posted') then raise exception 'Legacy Purchase journal was created inside authoritative GST context';end if;
 if exists(select 1 from public.gst_legacy_document_markers_v520 m where m.tenant_id=p_tenant_id and m.source_type='purchase' and m.source_id=v_purchase_id) then raise exception 'Legacy GST evidence was created inside authoritative GST context';end if;
 if exists(select 1 from public.journal_entries j join public.purchase_payments pp on pp.id=j.source_id and pp.purchase_id=v_purchase_id where j.tenant_id=p_tenant_id and j.source_type='purchase_payment' and j.status='posted') then raise exception 'Standalone initial Purchase payment journal was created inside authoritative GST context';end if;
 v_recon:=private.gst_purchase_reconcile_source_v520(p_tenant_id,v_purchase_id,p_location_id,v_quote,v_basis,p_payment_reference);
 v_snapshot:=private.gst_snapshot_create_v520(p_tenant_id,'purchase',v_purchase_id,v_purchase_number,p_location_id,p_purchase_date,v_quote,v_recon->'line_ids');v_journal:=private.gst_authoritative_journal_post_v520(p_tenant_id,v_snapshot);
 select s.document_number into v_document_number from public.gst_document_snapshots_v520 s where s.id=v_snapshot and s.tenant_id=p_tenant_id;
 if v_document_number is null or lower(trim(v_document_number))<>lower(v_supplier_invoice) then raise exception 'GST Purchase legal supplier invoice number was not captured';end if;
 v_response:=coalesce(v_source,'{}'::jsonb)||jsonb_build_object('success',true,'gst_engine',v_quote->>'engine','gst_status','POSTED','gst_supply_type',v_supply,'place_of_supply_code',v_quote->>'place_of_supply_code','purchase_id',v_purchase_id,'purchase_number',v_purchase_number,'supplier_invoice_number',v_document_number,'grand_total',(v_totals->>'grand_total')::numeric,'taxable_total',(v_totals->>'taxable_value')::numeric,'tax_total',(v_totals->>'tax_collected_total')::numeric,'cgst',(v_totals->>'cgst')::numeric,'sgst',(v_totals->>'sgst')::numeric,'utgst',(v_totals->>'utgst')::numeric,'igst',(v_totals->>'igst')::numeric,'cess',(v_totals->>'cess')::numeric,'thq_rcm_tax_payable_total',coalesce((v_totals->>'thq_rcm_tax_payable_total')::numeric,0),'gst_snapshot_id',v_snapshot,'journal_id',v_journal,'inventory_costs',v_recon->'inventory_costs','gst_ready_for_compliance',true);
 v_response:=private.gst_request_complete_v520(p_tenant_id,p_request_id,'gst.purchase.create.v520','purchase',v_purchase_id,v_snapshot,v_journal,v_response);
 update public.transaction_requests_v47 set response=v_response where tenant_id=p_tenant_id and request_id=trim(p_request_id) and operation='purchase.create';
 perform private.gst_authoritative_context_exit_v520();return v_response;
end $$;


--
-- Name: gst_purchase_invoice_create_v520(uuid, uuid, text, date, date, jsonb, numeric, numeric, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_purchase_invoice_create_v520(p_tenant_id uuid, p_purchase_order_id uuid, p_supplier_invoice_number text, p_invoice_date date, p_due_date date, p_items jsonb, p_additional_charges numeric DEFAULT 0, p_round_off numeric DEFAULT 0, p_notes text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text, p_supply_type text DEFAULT NULL::text, p_place_of_supply_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare po public.purchase_orders_v480%rowtype;v_supplier_invoice text:=nullif(trim(coalesce(p_supplier_invoice_number,'')),'');v_payload jsonb;v_req jsonb;v_supply text;v_quote_items jsonb;v_quote jsonb;v_bridge_items jsonb;v_create jsonb;v_post jsonb;v_recon jsonb;v_id uuid;v_internal_number text;v_snapshot uuid;v_journal uuid;v_document_number text;v_totals jsonb;v_response jsonb;
begin
 if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
 if not(private.gst_v520_has_access(p_tenant_id,'gst_compliance.calculate') or private.gst_v520_has_access(p_tenant_id,'gst_compliance.view')) then raise exception 'GST calculation permission required';end if;
 select * into po from public.purchase_orders_v480 where tenant_id=p_tenant_id and id=p_purchase_order_id for update;if not found then raise exception 'Purchase Order not found';end if;
 perform private.purchasing_v484_access(p_tenant_id,po.location_id,true);
 if po.status not in('partially_received','received','closed') then raise exception 'Authoritative GST Purchase Invoice requires posted GRN quantities';end if;
 if v_supplier_invoice is null then raise exception 'Supplier invoice number is required';end if;
 if p_invoice_date is null then raise exception 'Supplier invoice date is required';end if;if p_due_date is not null and p_due_date<p_invoice_date then raise exception 'Due date cannot be before supplier invoice date';end if;
 if coalesce(p_additional_charges,0)<>0 then raise exception 'Additional charges are not enabled for authoritative GST Purchase Invoices until charge-level GST classification is configured';end if;
 if abs(coalesce(p_round_off,0))>1.000001 then raise exception 'Round-off cannot exceed 1.00 in either direction';end if;
 v_payload:=jsonb_build_object('purchase_order_id',p_purchase_order_id,'supplier_invoice_number',v_supplier_invoice,'invoice_date',p_invoice_date,'due_date',p_due_date,'items',coalesce(p_items,'[]'::jsonb),'additional_charges',coalesce(p_additional_charges,0),'round_off',coalesce(p_round_off,0),'notes',nullif(trim(coalesce(p_notes,'')),''),'supply_type',nullif(upper(trim(coalesce(p_supply_type,''))),''),'place_of_supply_code',nullif(trim(coalesce(p_place_of_supply_code,'')),''));
 v_req:=private.gst_request_begin_v520(p_tenant_id,p_request_id,'gst.purchase_invoice_v484.create.v520',v_payload);if coalesce((v_req->>'existing')::boolean,false) then return v_req->'response';end if;
 v_supply:=private.gst_purchase_supply_type_resolve_v520(p_tenant_id,po.supplier_id,p_invoice_date,p_supply_type);
 v_quote_items:=private.gst_purchase_invoice_quote_items_v520(p_tenant_id,p_purchase_order_id,p_items);
 v_quote:=public.gst_purchase_quote_v520(p_tenant_id,po.location_id,po.supplier_id,p_invoice_date,v_supply,p_place_of_supply_code,v_quote_items,0,p_round_off);
 if coalesce((v_quote->>'ready_for_compliance')::boolean,false) is not true then raise exception 'GST Purchase Invoice is not compliance-ready: %',coalesce(v_quote->'errors','[]'::jsonb)::text;end if;
 v_totals:=v_quote->'totals';if coalesce((v_totals->>'grand_total')::numeric,0)<=0 then raise exception 'Authoritative GST Purchase Invoice total must be positive';end if;
 v_bridge_items:=private.gst_purchase_invoice_bridge_items_v520(p_items,v_quote);
 perform private.gst_authoritative_context_enter_v520(p_tenant_id,'purchase_invoice_v484');
 v_create:=public.purchase_invoice_create_v489(p_tenant_id,p_purchase_order_id,v_supplier_invoice,p_invoice_date,p_due_date,v_bridge_items,0,p_round_off,p_notes);
 v_id:=nullif(v_create->>'purchase_invoice_id','')::uuid;if v_id is null then raise exception 'GST Purchase Invoice source could not be created';end if;perform private.gst_authoritative_context_bind_v520(v_id);
 select invoice_number into v_internal_number from public.purchase_invoices_v484 where tenant_id=p_tenant_id and id=v_id and status='draft' and lower(trim(supplier_invoice_number))=lower(v_supplier_invoice) for update;if v_internal_number is null then raise exception 'GST Purchase Invoice source identity changed during creation';end if;
 if exists(select 1 from public.journal_entries j where j.tenant_id=p_tenant_id and j.source_type='purchase_invoice_v484' and j.source_id=v_id and j.status='posted') then raise exception 'Legacy Purchase Invoice journal was created before authoritative posting';end if;
 if exists(select 1 from public.gst_legacy_document_markers_v520 m where m.tenant_id=p_tenant_id and m.source_type='purchase_invoice_v484' and m.source_id=v_id) then raise exception 'Legacy GST evidence was created before authoritative Purchase Invoice posting';end if;
 v_recon:=private.gst_purchase_invoice_reconcile_v520(p_tenant_id,v_id,p_items,v_quote);
 v_post:=public.purchase_invoice_post_v484(p_tenant_id,v_id);
 if coalesce(v_post->>'status','') not in('posted','part_paid','paid') then raise exception 'GST Purchase Invoice did not reach a posted state';end if;
 if exists(select 1 from public.journal_entries j where j.tenant_id=p_tenant_id and j.source_type='purchase_invoice_v484' and j.source_id=v_id and j.status='posted') then raise exception 'Legacy Purchase Invoice journal was created inside authoritative GST context';end if;
 if exists(select 1 from public.gst_legacy_document_markers_v520 m where m.tenant_id=p_tenant_id and m.source_type='purchase_invoice_v484' and m.source_id=v_id) then raise exception 'Legacy GST evidence was created inside authoritative GST context';end if;
 v_snapshot:=private.gst_snapshot_create_v520(p_tenant_id,'purchase_invoice_v484',v_id,v_internal_number,po.location_id,p_invoice_date,v_quote,v_recon->'line_ids');
 v_journal:=private.gst_authoritative_journal_post_v520(p_tenant_id,v_snapshot);
 select document_number into v_document_number from public.gst_document_snapshots_v520 where tenant_id=p_tenant_id and id=v_snapshot;if v_document_number is null or lower(trim(v_document_number))<>lower(v_supplier_invoice) then raise exception 'GST Purchase Invoice legal supplier invoice number was not captured';end if;
 v_response:=coalesce(v_post,'{}'::jsonb)||jsonb_build_object('success',true,'gst_engine',v_quote->>'engine','gst_status','POSTED','gst_supply_type',v_supply,'place_of_supply_code',v_quote->>'place_of_supply_code','purchase_invoice_id',v_id,'invoice_number',v_internal_number,'supplier_invoice_number',v_document_number,'grand_total',(v_totals->>'grand_total')::numeric,'taxable_total',(v_totals->>'taxable_value')::numeric,'discount_total',(v_totals->>'discount')::numeric,'tax_total',(v_totals->>'tax_collected_total')::numeric,'cgst',(v_totals->>'cgst')::numeric,'sgst',(v_totals->>'sgst')::numeric,'utgst',(v_totals->>'utgst')::numeric,'igst',(v_totals->>'igst')::numeric,'cess',(v_totals->>'cess')::numeric,'thq_rcm_tax_payable_total',coalesce((v_totals->>'thq_rcm_tax_payable_total')::numeric,0),'gst_snapshot_id',v_snapshot,'journal_id',v_journal,'inventory_costs',v_recon->'inventory_costs','gst_ready_for_compliance',true);
 v_response:=private.gst_request_complete_v520(p_tenant_id,p_request_id,'gst.purchase_invoice_v484.create.v520','purchase_invoice_v484',v_id,v_snapshot,v_journal,v_response);
 perform private.gst_authoritative_context_exit_v520();return v_response;
end $$;


--
-- Name: gst_purchase_quote_v520(uuid, uuid, uuid, date, text, text, jsonb, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_purchase_quote_v520(p_tenant_id uuid, p_location_id uuid, p_supplier_id uuid, p_document_date date, p_supply_type text, p_place_of_supply_code text, p_items jsonb, p_additional_charges numeric DEFAULT 0, p_round_off numeric DEFAULT 0) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $_$select public.gst_document_quote_v520($1,'purchase',$2,$3,$4,$5,$6,$7,$8,$9)$_$;


--
-- Name: gst_purchase_return_create_v520(uuid, uuid, date, jsonb, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_purchase_return_create_v520(p_tenant_id uuid, p_purchase_id uuid, p_return_date date, p_items jsonb, p_reason text, p_location_id uuid DEFAULT NULL::uuid, p_device_id uuid DEFAULT NULL::uuid, p_request_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_req_payload jsonb; v_req_state jsonb; v_quote jsonb; v_totals jsonb;
  v_purchase public.purchases%rowtype; v_origin public.document_origins%rowtype;
  v_id uuid:=gen_random_uuid(); v_no text; x jsonb; ql jsonb; pi public.purchase_items%rowtype; v_ri uuid;
  v_line_ids jsonb:='[]'::jsonb; v_snapshot uuid; v_journal uuid; v_response jsonb;
  v_stock_type text; v_available numeric; v_paid numeric:=0; v_prev_returns numeric:=0; v_ap_reduce numeric; v_credit numeric;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  if not(private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'purchases.return') or private.erp_has_permission(p_tenant_id,'purchases.manage')) then
    raise exception 'Purchase return permission required';
  end if;
  if not(private.gst_v520_has_access(p_tenant_id,'gst_compliance.calculate') or private.gst_v520_has_access(p_tenant_id,'gst_compliance.view')) then
    raise exception 'GST calculation permission required';
  end if;
  if trim(coalesce(p_reason,''))='' then raise exception 'Return reason is required'; end if;
  if p_return_date is null then raise exception 'Return date is required'; end if;

  select * into v_purchase from public.purchases
  where tenant_id=p_tenant_id and id=p_purchase_id and status='posted'
  for update;
  if not found then raise exception 'Posted Purchase not found'; end if;

  select * into v_origin from public.document_origins
  where tenant_id=p_tenant_id and entity_type='purchase' and entity_id=p_purchase_id
  order by created_at limit 1;
  if v_origin.location_id is null then raise exception 'Original Purchase does not have a business location'; end if;
  if p_location_id is not null and p_location_id<>v_origin.location_id then
    raise exception 'Purchase Return location must match the original Purchase location';
  end if;
  perform private.v4_location_access(p_tenant_id,v_origin.location_id,'operate');
  if p_device_id is not null then
    perform private.erp_validate_transaction_origin(p_tenant_id,v_origin.location_id,p_device_id,'purchases');
  end if;

  v_req_payload:=jsonb_build_object(
    'purchase_id',p_purchase_id,'return_date',p_return_date,'items',coalesce(p_items,'[]'::jsonb),
    'reason',trim(p_reason),'location_id',v_origin.location_id,'device_id',p_device_id
  );
  v_req_state:=private.gst_request_begin_v520(p_tenant_id,p_request_id,'gst.purchase_return.create.v520',v_req_payload);
  if coalesce((v_req_state->>'existing')::boolean,false) then return v_req_state->'response'; end if;

  v_quote:=private.gst_purchase_return_quote_v520(p_tenant_id,p_purchase_id,p_return_date,p_items);
  v_totals:=v_quote->'totals';
  if coalesce((v_quote->>'ready_for_compliance')::boolean,false) is not true then
    raise exception 'GST Purchase Return is not compliance-ready';
  end if;

  perform private.gst_authoritative_context_enter_v520(p_tenant_id,'purchase_return');
  v_no:='PRN-'||lpad(nextval('public.purchase_return_number_seq')::text,6,'0');
  insert into public.purchase_returns(
    id,tenant_id,purchase_id,return_number,location_id,device_id,return_date,reason,credit_status,created_by
  ) values(
    v_id,p_tenant_id,p_purchase_id,v_no,v_origin.location_id,p_device_id,p_return_date,trim(p_reason),'supplier_credit',auth.uid()
  );
  perform private.gst_authoritative_context_bind_v520(v_id);

  for ql in select value from jsonb_array_elements(v_quote->'lines') loop
    select * into pi from public.purchase_items
    where tenant_id=p_tenant_id and purchase_id=p_purchase_id and id=(ql->>'purchase_item_id')::uuid;

    insert into public.purchase_return_items(
      purchase_return_id,purchase_item_id,variant_id,quantity,unit_cost,discount_amount,tax_rate,line_total,
      entered_unit_id,entered_unit_code,entered_quantity,conversion_to_base
    ) values(
      v_id,pi.id,pi.variant_id,(ql->>'quantity')::numeric,(ql->>'unit_price')::numeric,(ql->>'discount')::numeric,
      coalesce((ql->>'applied_gst_rate')::numeric,0),(ql->>'line_total')::numeric,
      pi.entered_unit_id,pi.entered_unit_code,
      case when coalesce(pi.conversion_to_base,1)>0 then (ql->>'quantity')::numeric/coalesce(pi.conversion_to_base,1) else (ql->>'quantity')::numeric end,
      coalesce(pi.conversion_to_base,1)
    ) returning id into v_ri;
    v_line_ids:=v_line_ids||jsonb_build_array(v_ri);

    select p.item_type into v_stock_type
    from public.product_variants pv
    join public.products p on p.id=pv.product_id and p.tenant_id=pv.tenant_id
    where pv.id=pi.variant_id and pv.tenant_id=p_tenant_id;

    if v_stock_type='stock' then
      select quantity-reserved_quantity-damaged_quantity-quarantine_quantity into v_available
      from public.location_stock_balances
      where tenant_id=p_tenant_id and location_id=v_origin.location_id and variant_id=pi.variant_id
      for update;
      if coalesce(v_available,0)+0.000001<(ql->>'quantity')::numeric then
        raise exception 'Insufficient available branch stock for GST Purchase Return item %',pi.id;
      end if;

      perform public.inventory_adjust_stock(p_tenant_id,pi.variant_id,-(ql->>'quantity')::numeric,'GST Purchase return • '||v_no);
      perform private.v4_location_stock_apply(
        p_tenant_id,v_origin.location_id,pi.variant_id,-(ql->>'quantity')::numeric,
        'purchase_return','purchase_return',v_id,v_no,trim(p_reason),p_device_id,false
      );
    end if;

    select value into x from jsonb_array_elements(p_items)
    where (value->>'purchase_item_id')::uuid=pi.id limit 1;
    perform private.gst_purchase_return_tracking_apply_v520(p_tenant_id,v_id,v_ri,coalesce(x,'{}'::jsonb));
  end loop;

  update public.purchase_returns
  set subtotal=(v_totals->>'taxable_value')::numeric,
      tax_total=(v_totals->>'tax_collected_total')::numeric,
      grand_total=(v_totals->>'grand_total')::numeric
  where id=v_id and tenant_id=p_tenant_id;

  if exists(
    select 1 from public.journal_entries
    where tenant_id=p_tenant_id and source_type='purchase_return' and source_id=v_id and status='posted'
  ) then raise exception 'Legacy Purchase Return journal was created inside authoritative GST context'; end if;
  if exists(
    select 1 from public.gst_legacy_document_markers_v520
    where tenant_id=p_tenant_id and source_type='purchase_return' and source_id=v_id
  ) then raise exception 'Legacy GST evidence was created inside authoritative GST context'; end if;

  insert into public.transaction_corrections(
    tenant_id,entity_type,entity_id,correction_type,reason,created_by,metadata
  ) values(
    p_tenant_id,'purchase',p_purchase_id,'return',trim(p_reason),auth.uid(),
    jsonb_build_object('return_id',v_id,'return_number',v_no,'amount',(v_totals->>'grand_total')::numeric,'gst_engine','v5.2')
  );

  v_snapshot:=private.gst_snapshot_create_v520(
    p_tenant_id,'purchase_return',v_id,v_no,v_origin.location_id,p_return_date,v_quote,v_line_ids
  );
  v_journal:=private.gst_authoritative_journal_post_v520(p_tenant_id,v_snapshot);

  insert into public.supplier_ledger_entries_v484(
    tenant_id,supplier_id,location_id,entry_date,entry_type,source_id,reference_number,description,debit,credit,created_by
  ) values(
    p_tenant_id,v_purchase.supplier_id,v_origin.location_id,p_return_date,'purchase_return',v_id,v_no,
    'GST Purchase Return '||v_no,0,(v_totals->>'grand_total')::numeric,auth.uid()
  ) on conflict(tenant_id,entry_type,source_id) do nothing;

  select coalesce(sum(amount),0) into v_paid
  from public.purchase_payments where tenant_id=p_tenant_id and purchase_id=p_purchase_id;
  select coalesce(sum(grand_total),0) into v_prev_returns
  from public.purchase_returns
  where tenant_id=p_tenant_id and purchase_id=p_purchase_id and id<>v_id and credit_status<>'waived'
    and created_at<=(select created_at from public.purchase_returns where id=v_id);
  v_ap_reduce:=least((v_totals->>'grand_total')::numeric,greatest(v_purchase.grand_total-v_paid-v_prev_returns,0));
  v_credit:=greatest((v_totals->>'grand_total')::numeric-v_ap_reduce,0);

  perform private.thq_sync_bump_v480(p_tenant_id,'finance','purchase_return',v_id::text,'post');

  v_response:=jsonb_build_object(
    'success',true,'gst_engine',v_quote->>'engine','gst_status','POSTED',
    'return_id',v_id,'return_number',v_no,'purchase_id',p_purchase_id,'document_class','credit_note',
    'grand_total',(v_totals->>'grand_total')::numeric,'taxable_total',(v_totals->>'taxable_value')::numeric,
    'tax_total',(v_totals->>'tax_collected_total')::numeric,
    'cgst',(v_totals->>'cgst')::numeric,'sgst',(v_totals->>'sgst')::numeric,'utgst',(v_totals->>'utgst')::numeric,
    'igst',(v_totals->>'igst')::numeric,'cess',(v_totals->>'cess')::numeric,
    'thq_rcm_tax_reversal_total',(v_totals->>'thq_rcm_tax_payable_total')::numeric,
    'payable_reduction',round(v_ap_reduce,2),'supplier_credit_due',round(v_credit,2),'credit_status','supplier_credit',
    'gst_snapshot_id',v_snapshot,'journal_id',v_journal,
    'original_purchase_snapshot_id',v_quote->>'original_purchase_snapshot_id'
  );

  v_response:=private.gst_request_complete_v520(
    p_tenant_id,p_request_id,'gst.purchase_return.create.v520','purchase_return',v_id,v_snapshot,v_journal,v_response
  );
  perform private.gst_authoritative_context_exit_v520();
  return v_response;
end
$$;


--
-- Name: gst_quote_v520(uuid, uuid, text, uuid, date, text, text, jsonb, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_quote_v520(p_tenant_id uuid, p_location_id uuid, p_party_type text, p_party_id uuid, p_document_date date, p_supply_type text, p_place_of_supply_code text, p_items jsonb, p_additional_charges numeric DEFAULT 0, p_round_off numeric DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$begin if lower(trim(coalesce(p_party_type,'customer')))<> 'customer' then raise exception 'gst_quote_v520 is the sales/outward wrapper. Use gst_purchase_quote_v520 for suppliers/purchases';end if;return public.gst_document_quote_v520(p_tenant_id,'sale',p_location_id,p_party_id,p_document_date,p_supply_type,p_place_of_supply_code,p_items,p_additional_charges,p_round_off);end $$;


--
-- Name: gst_registration_config_v520(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_registration_config_v520(p_tenant_id uuid, p_registration_id uuid, p_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v jsonb;begin
 if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.view') then raise exception 'GST compliance view permission required';end if;
 select to_jsonb(vr)||jsonb_build_object('gstin',r.gstin,'pan',r.pan,'state_code',r.state_code,'registration_id',r.id) into v
 from public.gst_registrations_v520 r join public.gst_registration_versions_v520 vr on vr.tenant_id=r.tenant_id and vr.registration_id=r.id and coalesce(p_date,current_date) between vr.effective_from and coalesce(vr.effective_to,'infinity'::date)
 where r.tenant_id=p_tenant_id and r.id=p_registration_id order by vr.effective_from desc,vr.created_at desc limit 1;return v;end $$;


--
-- Name: gst_registration_save_v520(uuid, uuid, text, text, text, text, text, text, text, text, text, boolean, boolean, boolean, text, boolean, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_registration_save_v520(p_tenant_id uuid, p_id uuid, p_gstin text, p_legal_name text, p_trade_name text, p_registration_type text, p_state_code text, p_address_line1 text, p_address_line2 text, p_city text, p_postal_code text, p_einvoice_enabled boolean, p_ewaybill_enabled boolean, p_returns_enabled boolean, p_provider_key text, p_active boolean, p_effective_from date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_id uuid:=coalesce(p_id,gen_random_uuid());v_gstin text:=upper(regexp_replace(coalesce(p_gstin,''),'\s','','g'));v_valid jsonb;v_before jsonb;v_type text:=lower(trim(coalesce(p_registration_type,'regular')));v_state text:=trim(coalesce(p_state_code,''));v_date date:=coalesce(p_effective_from,current_date);v_existing public.gst_registrations_v520%rowtype;v_current public.gst_registration_versions_v520%rowtype;
begin
 if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.configure') then raise exception 'GST configuration permission required';end if;
 if nullif(trim(coalesce(p_legal_name,'')),'') is null then raise exception 'GST legal name is required';end if;
 if v_type not in('regular','composition','casual','sez','isd','tcs','tds','non_resident','other') then raise exception 'Invalid GST registration type';end if;
 v_valid:=public.gst_gstin_validate_v520(v_gstin);if not coalesce((v_valid->>'structurally_valid')::boolean,false) then raise exception 'GSTIN failed structural/checksum validation';end if;
 if v_state='' then v_state:=v_valid->>'state_code';end if;if v_state is distinct from(v_valid->>'state_code') then raise exception 'GSTIN state code does not match selected state';end if;
 if not exists(select 1 from public.gst_state_master_v520 where code=v_state and active and not is_special_code) then raise exception 'Invalid active GST state code';end if;
 if p_id is not null then
  select * into v_existing from public.gst_registrations_v520 where id=p_id and tenant_id=p_tenant_id for update;if not found then raise exception 'GST registration not found';end if;v_before:=to_jsonb(v_existing);
  if v_existing.gstin is distinct from v_gstin or v_existing.pan is distinct from(v_valid->>'pan') or v_existing.state_code is distinct from v_state then raise exception 'GSTIN, PAN and state are immutable for a registration. Create a new GST registration instead';end if;
  select * into v_current from public.gst_registration_versions_v520 where tenant_id=p_tenant_id and registration_id=p_id and effective_to is null for update;
  if found and v_date<v_current.effective_from then raise exception 'Effective date cannot precede the current GST configuration version (%)',v_current.effective_from;end if;
 else if exists(select 1 from public.gst_registrations_v520 where tenant_id=p_tenant_id and gstin=v_gstin) then raise exception 'GSTIN already exists for this business';end if;end if;
 if p_id is null then
  insert into public.gst_registrations_v520(id,tenant_id,gstin,pan,legal_name,trade_name,registration_type,state_code,address_line1,address_line2,city,postal_code,einvoice_enabled,ewaybill_enabled,returns_enabled,provider_key,validation_status,active,effective_from,created_by,updated_by)
  values(v_id,p_tenant_id,v_gstin,v_valid->>'pan',trim(p_legal_name),nullif(trim(coalesce(p_trade_name,'')),''),v_type,v_state,nullif(trim(coalesce(p_address_line1,'')),''),nullif(trim(coalesce(p_address_line2,'')),''),nullif(trim(coalesce(p_city,'')),''),nullif(trim(coalesce(p_postal_code,'')),''),coalesce(p_einvoice_enabled,false),coalesce(p_ewaybill_enabled,false),coalesce(p_returns_enabled,true),nullif(trim(coalesce(p_provider_key,'')),''),'local_validated',coalesce(p_active,true),v_date,auth.uid(),auth.uid());
  insert into public.gst_registration_versions_v520(tenant_id,registration_id,legal_name,trade_name,registration_type,address_line1,address_line2,city,postal_code,country,einvoice_enabled,ewaybill_enabled,returns_enabled,provider_key,provider_config,validation_status,active,effective_from,change_reason,created_by)
  values(p_tenant_id,v_id,trim(p_legal_name),nullif(trim(coalesce(p_trade_name,'')),''),v_type,nullif(trim(coalesce(p_address_line1,'')),''),nullif(trim(coalesce(p_address_line2,'')),''),nullif(trim(coalesce(p_city,'')),''),nullif(trim(coalesce(p_postal_code,'')),''),'India',coalesce(p_einvoice_enabled,false),coalesce(p_ewaybill_enabled,false),coalesce(p_returns_enabled,true),nullif(trim(coalesce(p_provider_key,'')),''),'{}'::jsonb,'local_validated',coalesce(p_active,true),v_date,'Initial GST registration configuration',auth.uid());
 else
  if v_current.id is not null and v_date=v_current.effective_from then
   update public.gst_registration_versions_v520 set legal_name=trim(p_legal_name),trade_name=nullif(trim(coalesce(p_trade_name,'')),''),registration_type=v_type,address_line1=nullif(trim(coalesce(p_address_line1,'')),''),address_line2=nullif(trim(coalesce(p_address_line2,'')),''),city=nullif(trim(coalesce(p_city,'')),''),postal_code=nullif(trim(coalesce(p_postal_code,'')),''),einvoice_enabled=coalesce(p_einvoice_enabled,false),ewaybill_enabled=coalesce(p_ewaybill_enabled,false),returns_enabled=coalesce(p_returns_enabled,true),provider_key=nullif(trim(coalesce(p_provider_key,'')),''),validation_status='local_validated',active=coalesce(p_active,true),change_reason='Same-day GST configuration correction' where id=v_current.id;
  else
   if v_current.id is not null then update public.gst_registration_versions_v520 set effective_to=v_date-1 where id=v_current.id;end if;
   insert into public.gst_registration_versions_v520(tenant_id,registration_id,legal_name,trade_name,registration_type,address_line1,address_line2,city,postal_code,country,einvoice_enabled,ewaybill_enabled,returns_enabled,provider_key,provider_config,validation_status,active,effective_from,change_reason,created_by)
   values(p_tenant_id,v_id,trim(p_legal_name),nullif(trim(coalesce(p_trade_name,'')),''),v_type,nullif(trim(coalesce(p_address_line1,'')),''),nullif(trim(coalesce(p_address_line2,'')),''),nullif(trim(coalesce(p_city,'')),''),nullif(trim(coalesce(p_postal_code,'')),''),coalesce(v_existing.country,'India'),coalesce(p_einvoice_enabled,false),coalesce(p_ewaybill_enabled,false),coalesce(p_returns_enabled,true),nullif(trim(coalesce(p_provider_key,'')),''),coalesce(v_existing.provider_config,'{}'::jsonb),'local_validated',coalesce(p_active,true),v_date,'GST registration configuration change',auth.uid());
  end if;
  update public.gst_registrations_v520 set legal_name=trim(p_legal_name),trade_name=nullif(trim(coalesce(p_trade_name,'')),''),registration_type=v_type,address_line1=nullif(trim(coalesce(p_address_line1,'')),''),address_line2=nullif(trim(coalesce(p_address_line2,'')),''),city=nullif(trim(coalesce(p_city,'')),''),postal_code=nullif(trim(coalesce(p_postal_code,'')),''),einvoice_enabled=coalesce(p_einvoice_enabled,false),ewaybill_enabled=coalesce(p_ewaybill_enabled,false),returns_enabled=coalesce(p_returns_enabled,true),provider_key=nullif(trim(coalesce(p_provider_key,'')),''),validation_status='local_validated',active=coalesce(p_active,true),updated_by=auth.uid(),updated_at=now() where id=v_id and tenant_id=p_tenant_id;
 end if;
 perform private.business_audit_write_v471(p_tenant_id,'gst.registration.save','gst_registration',v_id,v_gstin,v_before,(select to_jsonb(r) from public.gst_registrations_v520 r where r.id=v_id));return v_id;
end $$;


--
-- Name: gst_registrations_list_v520(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_registrations_list_v520(p_tenant_id uuid) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.view') then raise exception 'GST compliance view permission required';end if;return query select jsonb_build_object('id',r.id,'gstin',r.gstin,'pan',r.pan,'legal_name',r.legal_name,'trade_name',r.trade_name,'registration_type',r.registration_type,'state_code',r.state_code,'state_name',s.name,'address_line1',r.address_line1,'address_line2',r.address_line2,'city',r.city,'postal_code',r.postal_code,'country',r.country,'einvoice_enabled',r.einvoice_enabled,'ewaybill_enabled',r.ewaybill_enabled,'returns_enabled',r.returns_enabled,'provider_key',r.provider_key,'validation_status',r.validation_status,'active',r.active,'effective_from',r.effective_from,'effective_to',r.effective_to,'locations',coalesce((select jsonb_agg(jsonb_build_object('location_id',m.location_id,'location_name',l.name,'effective_from',m.effective_from,'effective_to',m.effective_to) order by l.name) from public.gst_location_registrations_v520 m join public.business_locations l on l.id=m.location_id where m.tenant_id=r.tenant_id and m.registration_id=r.id and m.effective_to is null),'[]'::jsonb)) from public.gst_registrations_v520 r join public.gst_state_master_v520 s on s.code=r.state_code where r.tenant_id=p_tenant_id order by r.active desc,r.state_code,r.legal_name;end $$;


--
-- Name: gst_restaurant_order_bill_v520(uuid, uuid, uuid, uuid, date, numeric, text, text, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_restaurant_order_bill_v520(p_tenant_id uuid, p_order_id uuid, p_device_id uuid, p_customer_id uuid, p_due_date date, p_initial_payment numeric, p_payment_method text, p_payment_reference text, p_round_off numeric DEFAULT 0, p_supply_type text DEFAULT NULL::text, p_place_of_supply_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  o public.restaurant_orders%rowtype;
  v_customer uuid;
  v_items jsonb;
  v_method text;
  v_wrapper_request text;
  v_sale_request text;
  v_payment_request text;
  v_req_payload jsonb;
  v_req_state jsonb;
  v_sale jsonb;
  v_payment jsonb;
  v_sale_id uuid;
  v_snapshot uuid;
  v_sale_journal uuid;
  v_payment_id uuid;
  v_payment_journal uuid;
  v_total numeric;
  v_response jsonb;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  if not (private.erp_user_is_owner(p_tenant_id)
          or private.erp_has_permission(p_tenant_id,'restaurant.order')
          or private.erp_has_permission(p_tenant_id,'restaurant.manage')) then
    raise exception 'Restaurant billing permission denied';
  end if;
  if not (private.gst_v520_has_access(p_tenant_id,'gst_compliance.calculate')
          or private.gst_v520_has_access(p_tenant_id,'gst_compliance.view')) then
    raise exception 'GST calculation permission required';
  end if;
  if p_order_id is null then raise exception 'Restaurant order is required'; end if;
  if abs(coalesce(p_round_off,0))>0.999999 then raise exception 'Round off must be between -1.00 and 1.00'; end if;

  v_method:=coalesce(nullif(lower(trim(p_payment_method)),''),'cash');
  if v_method not in('cash','bank','card','upi','cheque','other','credit') then
    raise exception 'Invalid restaurant payment method';
  end if;

  v_wrapper_request:='gst-restaurant-order:'||p_order_id::text;
  v_sale_request:='gst-restaurant-sale:'||p_order_id::text;
  v_payment_request:='gst-restaurant-payment:'||p_order_id::text;
  v_req_payload:=jsonb_build_object(
    'order_id',p_order_id,
    'device_id',p_device_id,
    'customer_id',p_customer_id,
    'due_date',p_due_date,
    -- v4.8.9 already treats non-credit Restaurant billing as full settlement.
    -- Retain this input in the idempotency payload for caller compatibility,
    -- but do not let it create a partial/ambiguous restaurant settlement.
    'legacy_initial_payment_argument',coalesce(p_initial_payment,0),
    'payment_method',v_method,
    'payment_reference',nullif(trim(coalesce(p_payment_reference,'')),''),
    'round_off',round(coalesce(p_round_off,0),2),
    'supply_type',nullif(upper(trim(coalesce(p_supply_type,''))),''),
    'place_of_supply_code',nullif(trim(coalesce(p_place_of_supply_code,'')),'')
  );
  v_req_state:=private.gst_request_begin_v520(p_tenant_id,v_wrapper_request,'gst.restaurant.order.bill.v520',v_req_payload);
  if coalesce((v_req_state->>'existing')::boolean,false) then
    return v_req_state->'response';
  end if;

  select * into o
  from public.restaurant_orders
  where id=p_order_id and tenant_id=p_tenant_id
  for update;
  if not found then raise exception 'Restaurant order not found'; end if;
  perform private.erp_validate_vertical_device_scope(p_tenant_id,o.location_id,p_device_id,'restaurant','operate');
  if o.status='cancelled' then raise exception 'Cancelled restaurant order cannot be billed'; end if;
  if o.status='billed' or o.sale_id is not null then
    raise exception 'Restaurant order is already billed outside this v5.2 GST billing request; reconcile the existing invoice instead of converting it silently';
  end if;

  v_customer:=coalesce(o.customer_id,p_customer_id);
  if v_customer is null or not exists(
    select 1 from public.customers c
    where c.id=v_customer and c.tenant_id=p_tenant_id and coalesce(c.status,'active')='active'
  ) then
    raise exception 'Choose an active customer before billing';
  end if;

  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
      'variant_id',i.variant_id,
      'quantity',i.quantity,
      'unit_id',i.unit_id,
      'unit_price',i.unit_price,
      'discount_amount',i.discount_amount
    )) order by i.created_at,i.id),'[]'::jsonb)
  into v_items
  from public.restaurant_order_items i
  where i.order_id=o.id and i.tenant_id=p_tenant_id;
  if jsonb_array_length(v_items)=0 then raise exception 'Restaurant order has no items'; end if;

  -- GST Sale remains the legal invoice.  The Sale writer re-resolves current server
  -- pricing at the instant of billing, preserving the v4.8.9 Restaurant rule.
  -- KOT/order tax_rate fields are never authoritative GST evidence.
  v_sale:=public.gst_sale_create_v520(
    p_tenant_id=>p_tenant_id,
    p_customer_id=>v_customer,
    p_sale_date=>current_date,
    p_due_date=>p_due_date,
    p_items=>v_items,
    p_additional_charges=>0,
    p_round_off=>round(coalesce(p_round_off,0),2),
    p_initial_payment=>0,
    p_payment_method=>'credit',
    p_payment_reference=>null,
    p_notes=>'Restaurant '||o.order_number,
    p_location_id=>o.location_id,
    p_device_id=>p_device_id,
    p_request_id=>v_sale_request,
    p_supply_type=>p_supply_type,
    p_place_of_supply_code=>p_place_of_supply_code
  );
  v_sale_id:=nullif(v_sale->>'sale_id','')::uuid;
  v_snapshot:=nullif(v_sale->>'gst_snapshot_id','')::uuid;
  v_sale_journal:=nullif(v_sale->>'journal_id','')::uuid;
  v_total:=coalesce(nullif(v_sale->>'grand_total','')::numeric,0);
  if v_sale_id is null or v_snapshot is null or v_sale_journal is null then
    raise exception 'Restaurant GST Sale did not create complete authoritative evidence';
  end if;

  -- Preserve v4.8.9 semantics: every non-credit Restaurant bill is settled for
  -- the exact server-authoritative invoice total.  The legacy initial-payment argument
  -- is intentionally not used for partial settlement.
  if v_method<>'credit' and v_total>0.005 then
    v_payment:=public.sales_add_payment_v47(
      p_tenant_id,v_sale_id,v_total,v_method,coalesce(p_payment_reference,''),
      'Restaurant settlement '||o.order_number,v_payment_request
    );
    v_payment_id:=nullif(v_payment->>'payment_id','')::uuid;
    if v_payment_id is null then raise exception 'Restaurant settlement payment was not created'; end if;
    select j.id into v_payment_journal
    from public.journal_entries j
    where j.tenant_id=p_tenant_id and j.source_type='sale_payment' and j.source_id=v_payment_id and j.status='posted'
    order by j.created_at desc limit 1;
    if v_payment_journal is null then raise exception 'Restaurant settlement payment journal was not created'; end if;
  else
    v_payment:=jsonb_build_object(
      'success',true,'payment_id',null,'amount',0,'paid_amount',0,
      'balance_due',v_total,'payment_status','unpaid'
    );
  end if;

  update public.restaurant_orders
  set status='billed',sale_id=v_sale_id,billed_at=coalesce(billed_at,now()),updated_at=now()
  where id=o.id and tenant_id=p_tenant_id and status<>'cancelled' and sale_id is null;
  if not found then raise exception 'Restaurant order billing state changed concurrently'; end if;

  update public.restaurant_kots
  set status='served',served_at=coalesce(served_at,now())
  where tenant_id=p_tenant_id and order_id=o.id and status not in('served','cancelled');

  perform private.thq_sync_bump_v480(p_tenant_id,'transactions','restaurant_order',o.id::text,'bill');

  v_response:=coalesce(v_sale,'{}'::jsonb)||jsonb_build_object(
    'success',true,
    'order_id',o.id,
    'order_number',o.order_number,
    'restaurant_billing','v5.2-gst',
    'settlement_mode',case when v_method='credit' then 'credit' else 'full' end,
    'requested_initial_payment_argument',coalesce(p_initial_payment,0),
    'payment_method',v_method,
    'payment',v_payment,
    'payment_id',v_payment_id,
    'payment_journal_id',v_payment_journal,
    'gst_snapshot_id',v_snapshot,
    'journal_id',v_sale_journal
  );

  perform private.business_audit_write_v471(
    p_tenant_id,'restaurant.order.bill.gst_v520','restaurant_order',o.id,o.order_number,to_jsonb(o),
    jsonb_build_object(
      'sale_id',v_sale_id,'sale_number',v_sale->>'sale_number','grand_total',v_total,
      'payment_method',v_method,'payment_id',v_payment_id,
      'gst_snapshot_id',v_snapshot,'journal_id',v_sale_journal
    )
  );

  v_response:=private.gst_request_complete_v520(
    p_tenant_id,v_wrapper_request,'gst.restaurant.order.bill.v520','restaurant_order',o.id,v_snapshot,v_sale_journal,v_response
  );
  return v_response;
end
$$;


--
-- Name: gst_sale_create_v520(uuid, uuid, date, date, jsonb, numeric, numeric, numeric, text, text, text, uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_sale_create_v520(p_tenant_id uuid, p_customer_id uuid, p_sale_date date, p_due_date date, p_items jsonb, p_additional_charges numeric DEFAULT 0, p_round_off numeric DEFAULT 0, p_initial_payment numeric DEFAULT 0, p_payment_method text DEFAULT 'cash'::text, p_payment_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_location_id uuid DEFAULT NULL::uuid, p_device_id uuid DEFAULT NULL::uuid, p_request_id text DEFAULT NULL::text, p_supply_type text DEFAULT NULL::text, p_place_of_supply_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_req_payload jsonb;v_req_state jsonb;v_old_req jsonb;v_supply text;v_pos text;v_priced jsonb;v_normalized jsonb;v_quote jsonb;v_bridge jsonb;v_source jsonb;v_sale_id uuid;v_sale_number text;v_line_ids jsonb;v_snapshot uuid;v_journal uuid;v_document_number text;v_response jsonb;v_totals jsonb;begin if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;if not(private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'sales.manage')) then raise exception 'Sales permission required';end if;if not(private.gst_v520_has_access(p_tenant_id,'gst_compliance.calculate') or private.gst_v520_has_access(p_tenant_id,'gst_compliance.view')) then raise exception 'GST calculation permission required';end if;if p_location_id is null then raise exception 'Business location is required';end if;if coalesce(p_additional_charges,0)<>0 then raise exception 'Additional charges are not enabled for authoritative GST Sales until charge-level GST classification is configured';end if;if p_sale_date is null then raise exception 'Sale date is required';end if;if p_due_date is not null and p_due_date<p_sale_date then raise exception 'Due date cannot be before sale date';end if;if coalesce(p_initial_payment,0)<0 then raise exception 'Initial payment cannot be negative';end if;v_req_payload:=jsonb_build_object('customer_id',p_customer_id,'sale_date',p_sale_date,'due_date',p_due_date,'items',coalesce(p_items,'[]'::jsonb),'additional_charges',coalesce(p_additional_charges,0),'round_off',coalesce(p_round_off,0),'initial_payment',coalesce(p_initial_payment,0),'payment_method',lower(trim(coalesce(p_payment_method,''))),'payment_reference',nullif(trim(coalesce(p_payment_reference,'')),''),'notes',nullif(trim(coalesce(p_notes,'')),''),'location_id',p_location_id,'device_id',p_device_id,'supply_type',nullif(upper(trim(coalesce(p_supply_type,''))),''),'place_of_supply_code',nullif(trim(coalesce(p_place_of_supply_code,'')),'') );v_req_state:=private.gst_request_begin_v520(p_tenant_id,p_request_id,'gst.sale.create.v520',v_req_payload);if coalesce((v_req_state->>'existing')::boolean,false) then return v_req_state->'response';end if;v_old_req:=private.v47_request_existing(p_tenant_id,p_request_id,'sale.create');if v_old_req is not null then raise exception 'Request ID is already used by the legacy Sale path';end if;v_priced:=private.v482_price_sale_items(p_tenant_id,p_customer_id,p_items,p_location_id);v_normalized:=private.v481_normalize_items(p_tenant_id,v_priced,'sale');v_supply:=private.gst_sale_supply_type_resolve_v520(p_tenant_id,p_customer_id,p_sale_date,p_supply_type);v_pos:=private.gst_sale_pos_resolve_v520(p_tenant_id,p_customer_id,p_location_id,p_sale_date,v_supply,v_normalized,p_place_of_supply_code);v_quote:=public.gst_document_quote_v520(p_tenant_id,'sale',p_location_id,p_customer_id,p_sale_date,v_supply,v_pos,v_normalized,0,p_round_off);if coalesce((v_quote->>'ready_for_compliance')::boolean,false) is not true then raise exception 'GST Sale is not compliance-ready: %',coalesce(v_quote->'errors','[]'::jsonb)::text;end if;v_totals:=v_quote->'totals';if coalesce(p_initial_payment,0)>coalesce((v_totals->>'grand_total')::numeric,0)+0.005 then raise exception 'Payment cannot exceed GST Sale total';end if;v_bridge:=private.gst_sale_bridge_v520(v_priced,v_normalized,(v_totals->>'grand_total')::numeric);perform private.gst_authoritative_context_enter_v520(p_tenant_id,'sale');v_source:=public.sales_create_v483(p_tenant_id,p_customer_id,p_sale_date,p_due_date,v_bridge->'items',(v_bridge->>'additional_charges')::numeric,p_initial_payment,p_payment_method,p_payment_reference,p_notes,p_location_id,p_device_id,p_request_id);v_sale_id:=nullif(v_source->>'sale_id','')::uuid;if v_sale_id is null then raise exception 'GST Sale source could not be resolved';end if;perform private.gst_authoritative_context_bind_v520(v_sale_id);select s.sale_number into v_sale_number from public.sales s where s.tenant_id=p_tenant_id and s.id=v_sale_id and s.status='posted' for update;if v_sale_number is null then raise exception 'GST Sale source is not posted';end if;if exists(select 1 from public.journal_entries j where j.tenant_id=p_tenant_id and j.source_type='sale' and j.source_id=v_sale_id and j.status='posted') then raise exception 'Legacy Sale journal was created inside authoritative GST context';end if;if exists(select 1 from public.gst_legacy_document_markers_v520 m where m.tenant_id=p_tenant_id and m.source_type='sale' and m.source_id=v_sale_id) then raise exception 'Legacy GST evidence was created inside authoritative GST context';end if;v_line_ids:=private.gst_sale_reconcile_source_v520(p_tenant_id,v_sale_id,v_quote);v_snapshot:=private.gst_snapshot_create_v520(p_tenant_id,'sale',v_sale_id,v_sale_number,p_location_id,p_sale_date,v_quote,v_line_ids);v_journal:=private.gst_authoritative_journal_post_v520(p_tenant_id,v_snapshot);select s.document_number into v_document_number from public.gst_document_snapshots_v520 s where s.id=v_snapshot and s.tenant_id=p_tenant_id;if v_document_number is null then raise exception 'GST Sale legal document number was not captured';end if;v_response:=coalesce(v_source,'{}'::jsonb)||jsonb_build_object('success',true,'gst_engine',v_quote->>'engine','gst_status','POSTED','gst_supply_type',v_supply,'place_of_supply_code',v_quote->>'place_of_supply_code','sale_id',v_sale_id,'sale_number',v_sale_number,'invoice_number',v_document_number,'grand_total',(v_totals->>'grand_total')::numeric,'taxable_total',(v_totals->>'taxable_value')::numeric,'tax_total',(v_totals->>'tax_collected_total')::numeric,'cgst',(v_totals->>'cgst')::numeric,'sgst',(v_totals->>'sgst')::numeric,'utgst',(v_totals->>'utgst')::numeric,'igst',(v_totals->>'igst')::numeric,'cess',(v_totals->>'cess')::numeric,'recipient_rcm_tax_payable_total',coalesce((v_totals->>'recipient_rcm_tax_payable_total')::numeric,0),'gst_snapshot_id',v_snapshot,'journal_id',v_journal,'gst_ready_for_compliance',true);v_response:=private.gst_request_complete_v520(p_tenant_id,p_request_id,'gst.sale.create.v520','sale',v_sale_id,v_snapshot,v_journal,v_response);update public.transaction_requests_v47 set response=v_response where tenant_id=p_tenant_id and request_id=trim(p_request_id) and operation='sale.create';perform private.gst_authoritative_context_exit_v520();return v_response;end $$;


--
-- Name: gst_sale_create_v522(uuid, uuid, date, date, jsonb, jsonb, text, uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_sale_create_v522(p_tenant_id uuid, p_customer_id uuid, p_sale_date date, p_due_date date, p_items jsonb, p_payment_allocations jsonb, p_notes text DEFAULT NULL::text, p_location_id uuid DEFAULT NULL::uuid, p_device_id uuid DEFAULT NULL::uuid, p_request_id text DEFAULT NULL::text, p_supply_type text DEFAULT NULL::text, p_place_of_supply_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_req_payload jsonb;v_req_state jsonb;v_old_req jsonb;v_supply text;v_pos text;v_priced jsonb;v_normalized jsonb;
  v_quote0 jsonb;v_quote jsonb;v_bridge jsonb;v_source jsonb;v_sale_id uuid;v_sale_number text;v_line_ids jsonb;v_snapshot uuid;v_journal uuid;
  v_document_number text;v_response jsonb;v_totals jsonb;v_round numeric;v_payment_result jsonb;v_discount numeric;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  if not(private.erp_user_is_owner(p_tenant_id, auth.uid()) or private.erp_has_permission(p_tenant_id,'sales.manage')) then raise exception 'Sales permission required'; end if;
  if not(private.gst_v520_has_access(p_tenant_id,'gst_compliance.calculate') or private.gst_v520_has_access(p_tenant_id,'gst_compliance.view')) then raise exception 'GST calculation permission required'; end if;
  if p_location_id is null then raise exception 'Business location is required'; end if;
  if p_sale_date is null then raise exception 'Sale date is required'; end if;
  if p_due_date is not null and p_due_date<p_sale_date then raise exception 'Due date cannot be before sale date'; end if;
  v_req_payload:=jsonb_build_object('customer_id',p_customer_id,'sale_date',p_sale_date,'due_date',p_due_date,'items',coalesce(p_items,'[]'::jsonb),
    'payment_allocations',coalesce(p_payment_allocations,'[]'::jsonb),'notes',nullif(trim(coalesce(p_notes,'')),''),'location_id',p_location_id,
    'device_id',p_device_id,'supply_type',nullif(upper(trim(coalesce(p_supply_type,''))),''),'place_of_supply_code',nullif(trim(coalesce(p_place_of_supply_code,'')),'') );
  v_req_state:=private.gst_request_begin_v520(p_tenant_id,p_request_id,'gst.sale.create.v522',v_req_payload);
  if coalesce((v_req_state->>'existing')::boolean,false) then return v_req_state->'response'; end if;
  v_old_req:=private.v47_request_existing(p_tenant_id,p_request_id,'sale.create');if v_old_req is not null then raise exception 'Request ID is already used by the legacy Sale path'; end if;
  v_priced:=private.v482_price_sale_items(p_tenant_id,p_customer_id,p_items,p_location_id);
  v_normalized:=private.v481_normalize_items(p_tenant_id,v_priced,'sale');
  v_supply:=private.gst_sale_supply_type_resolve_v520(p_tenant_id,p_customer_id,p_sale_date,p_supply_type);
  v_pos:=private.gst_sale_pos_resolve_v520(p_tenant_id,p_customer_id,p_location_id,p_sale_date,v_supply,v_normalized,p_place_of_supply_code);
  v_quote0:=public.gst_document_quote_v520(p_tenant_id,'sale',p_location_id,p_customer_id,p_sale_date,v_supply,v_pos,v_normalized,0,0);
  if coalesce((v_quote0->>'ready_for_compliance')::boolean,false) is not true then raise exception 'GST Sale is not compliance-ready: %',coalesce(v_quote0->'errors','[]'::jsonb)::text; end if;
  v_round:=round(round(coalesce((v_quote0->'totals'->>'grand_total')::numeric,0),0)-coalesce((v_quote0->'totals'->>'grand_total')::numeric,0),2);
  v_quote:=public.gst_document_quote_v520(p_tenant_id,'sale',p_location_id,p_customer_id,p_sale_date,v_supply,v_pos,v_normalized,0,v_round);
  if coalesce((v_quote->>'ready_for_compliance')::boolean,false) is not true then raise exception 'GST Sale is not compliance-ready after round-off: %',coalesce(v_quote->'errors','[]'::jsonb)::text; end if;
  v_totals:=v_quote->'totals';v_discount:=coalesce((v_totals->>'discount')::numeric,0);
  v_bridge:=private.gst_sale_bridge_v520(v_priced,v_normalized,(v_totals->>'grand_total')::numeric);
  perform private.gst_authoritative_context_enter_v520(p_tenant_id,'sale');
  v_source:=public.sales_create_v483(p_tenant_id,p_customer_id,p_sale_date,p_due_date,v_bridge->'items',(v_bridge->>'additional_charges')::numeric,0,'cash',null,p_notes,p_location_id,p_device_id,p_request_id);
  v_sale_id:=nullif(v_source->>'sale_id','')::uuid;if v_sale_id is null then raise exception 'GST Sale source could not be resolved'; end if;
  perform private.gst_authoritative_context_bind_v520(v_sale_id);
  select sale_number into v_sale_number from public.sales where tenant_id=p_tenant_id and id=v_sale_id and status='posted' for update;
  if v_sale_number is null then raise exception 'GST Sale source is not posted'; end if;
  if exists(select 1 from public.journal_entries where tenant_id=p_tenant_id and source_type='sale' and source_id=v_sale_id and status='posted') then raise exception 'Legacy Sale journal was created inside authoritative GST context'; end if;
  if exists(select 1 from public.gst_legacy_document_markers_v520 where tenant_id=p_tenant_id and source_type='sale' and source_id=v_sale_id) then raise exception 'Legacy GST evidence was created inside authoritative GST context'; end if;
  v_line_ids:=private.gst_sale_reconcile_source_v520(p_tenant_id,v_sale_id,v_quote);
  v_payment_result:=private.sale_payment_allocations_create_v522(p_tenant_id,v_sale_id,p_customer_id,(v_totals->>'grand_total')::numeric,coalesce(p_payment_allocations,'[]'::jsonb));
  perform private.gst_sale_credit_limit_assert_v600(p_tenant_id,v_sale_id,p_customer_id,coalesce((v_payment_result->>'credit_amount')::numeric,0));
  v_snapshot:=private.gst_snapshot_create_v520(p_tenant_id,'sale',v_sale_id,v_sale_number,p_location_id,p_sale_date,v_quote,v_line_ids);
  v_journal:=private.gst_authoritative_sale_journal_post_v522(p_tenant_id,v_snapshot);
  select document_number into v_document_number from public.gst_document_snapshots_v520 where id=v_snapshot and tenant_id=p_tenant_id;
  if v_document_number is null then raise exception 'GST Sale legal document number was not captured'; end if;
  v_response:=coalesce(v_source,'{}'::jsonb)||jsonb_build_object('success',true,'writer','gst_sale_create_v522','version','5.2.2','gst_engine',v_quote->>'engine',
    'gst_status','POSTED','gst_supply_type',v_supply,'place_of_supply_code',v_quote->>'place_of_supply_code','sale_id',v_sale_id,'sale_number',v_sale_number,
    'invoice_number',v_document_number,'subtotal',(v_totals->>'subtotal')::numeric,'discount_total',v_discount,'round_off',v_round,
    'grand_total',(v_totals->>'grand_total')::numeric,'taxable_total',(v_totals->>'taxable_value')::numeric,'tax_total',(v_totals->>'tax_collected_total')::numeric,
    'cgst',(v_totals->>'cgst')::numeric,'sgst',(v_totals->>'sgst')::numeric,'utgst',(v_totals->>'utgst')::numeric,'igst',(v_totals->>'igst')::numeric,'cess',(v_totals->>'cess')::numeric,
    'payments',v_payment_result,'gst_snapshot_id',v_snapshot,'journal_id',v_journal,'gst_ready_for_compliance',true,'legacy_fallback_used',false);
  v_response:=private.gst_request_complete_v520(p_tenant_id,p_request_id,'gst.sale.create.v522','sale',v_sale_id,v_snapshot,v_journal,v_response);
  update public.transaction_requests_v47 set response=v_response where tenant_id=p_tenant_id and request_id=trim(p_request_id) and operation='sale.create';
  perform private.gst_authoritative_context_exit_v520();return v_response;
end;
$$;


--
-- Name: gst_sales_return_create_v520(uuid, uuid, date, jsonb, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_sales_return_create_v520(p_tenant_id uuid, p_sale_id uuid, p_return_date date, p_items jsonb, p_reason text, p_location_id uuid DEFAULT NULL::uuid, p_device_id uuid DEFAULT NULL::uuid, p_request_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_req_payload jsonb; v_req_state jsonb; v_quote jsonb; v_totals jsonb; v_sale public.sales%rowtype; v_origin public.document_origins%rowtype;
  v_id uuid:=gen_random_uuid(); v_no text; x jsonb; ql jsonb; si public.sale_items%rowtype; v_ri uuid; v_line_ids jsonb:='[]'::jsonb;
  v_snapshot uuid; v_journal uuid; v_response jsonb; v_stock_type text; v_cost numeric:=0; v_paid numeric:=0; v_prev_returns numeric:=0; v_ar_reduce numeric; v_credit numeric;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  if not(private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'sales.return') or private.erp_has_permission(p_tenant_id,'sales.manage')) then raise exception 'Sales return permission required'; end if;
  if not(private.gst_v520_has_access(p_tenant_id,'gst_compliance.calculate') or private.gst_v520_has_access(p_tenant_id,'gst_compliance.view')) then raise exception 'GST calculation permission required'; end if;
  if trim(coalesce(p_reason,''))='' then raise exception 'Return reason is required'; end if;
  if p_return_date is null then raise exception 'Return date is required'; end if;
  select * into v_sale from public.sales where tenant_id=p_tenant_id and id=p_sale_id and status='posted' for update;
  if not found then raise exception 'Posted Sale not found'; end if;
  select * into v_origin from public.document_origins where tenant_id=p_tenant_id and entity_type='sale' and entity_id=p_sale_id order by created_at limit 1;
  if v_origin.location_id is null then raise exception 'Original Sale does not have a business location'; end if;
  if p_location_id is not null and p_location_id<>v_origin.location_id then raise exception 'Sales Return location must match the original Sale location'; end if;
  perform private.v4_location_access(p_tenant_id,v_origin.location_id,'operate');
  if p_device_id is not null then perform private.erp_validate_transaction_origin(p_tenant_id,v_origin.location_id,p_device_id,'sales'); end if;

  v_req_payload:=jsonb_build_object('sale_id',p_sale_id,'return_date',p_return_date,'items',coalesce(p_items,'[]'::jsonb),'reason',trim(p_reason),'location_id',v_origin.location_id,'device_id',p_device_id);
  v_req_state:=private.gst_request_begin_v520(p_tenant_id,p_request_id,'gst.sales_return.create.v520',v_req_payload);
  if coalesce((v_req_state->>'existing')::boolean,false) then return v_req_state->'response'; end if;
  v_quote:=private.gst_sales_return_quote_v520(p_tenant_id,p_sale_id,p_return_date,p_items);
  v_totals:=v_quote->'totals';
  if coalesce((v_quote->>'ready_for_compliance')::boolean,false) is not true then raise exception 'GST Sales Return is not compliance-ready'; end if;

  perform private.gst_authoritative_context_enter_v520(p_tenant_id,'sales_return');
  v_no:='SRN-'||lpad(nextval('public.sales_return_number_seq')::text,6,'0');
  insert into public.sales_returns(id,tenant_id,sale_id,return_number,location_id,device_id,return_date,reason,created_by)
  values(v_id,p_tenant_id,p_sale_id,v_no,v_origin.location_id,p_device_id,p_return_date,trim(p_reason),auth.uid());
  perform private.gst_authoritative_context_bind_v520(v_id);

  for ql in select value from jsonb_array_elements(v_quote->'lines') loop
    select * into si from public.sale_items where tenant_id=p_tenant_id and sale_id=p_sale_id and id=(ql->>'sale_item_id')::uuid;
    insert into public.sales_return_items(sales_return_id,sale_item_id,variant_id,quantity,unit_price,discount_amount,tax_rate,line_total,entered_unit_id,entered_unit_code,entered_quantity,conversion_to_base)
    values(v_id,si.id,si.variant_id,(ql->>'quantity')::numeric,(ql->>'unit_price')::numeric,(ql->>'discount')::numeric,coalesce((ql->>'applied_gst_rate')::numeric,0),(ql->>'line_total')::numeric,
      si.entered_unit_id,si.entered_unit_code,case when coalesce(si.conversion_to_base,1)>0 then (ql->>'quantity')::numeric/coalesce(si.conversion_to_base,1) else (ql->>'quantity')::numeric end,coalesce(si.conversion_to_base,1))
    returning id into v_ri;
    v_line_ids:=v_line_ids||jsonb_build_array(v_ri);
    select p.item_type into v_stock_type from public.product_variants pv join public.products p on p.id=pv.product_id and p.tenant_id=pv.tenant_id where pv.id=si.variant_id and pv.tenant_id=p_tenant_id;
    if v_stock_type='stock' then
      perform public.inventory_adjust_stock(p_tenant_id,si.variant_id,(ql->>'quantity')::numeric,'GST Sale return • '||v_no);
      perform private.v4_location_stock_apply(p_tenant_id,v_origin.location_id,si.variant_id,(ql->>'quantity')::numeric,'sale_return','sales_return',v_id,v_no,trim(p_reason),p_device_id,false);
      select coalesce(si.cost_total,0)*((ql->>'quantity')::numeric/nullif(si.quantity,0)) into v_cost;
    end if;
    select value into x from jsonb_array_elements(p_items) where (value->>'sale_item_id')::uuid=si.id limit 1;
    perform private.gst_sales_return_tracking_apply_v520(p_tenant_id,v_id,v_ri,coalesce(x,'{}'::jsonb));
  end loop;

  update public.sales_returns set subtotal=(v_totals->>'taxable_value')::numeric,tax_total=(v_totals->>'tax_collected_total')::numeric,grand_total=(v_totals->>'grand_total')::numeric where id=v_id and tenant_id=p_tenant_id;
  if exists(select 1 from public.journal_entries where tenant_id=p_tenant_id and source_type='sales_return' and source_id=v_id and status='posted') then raise exception 'Legacy Sales Return journal was created inside authoritative GST context'; end if;
  if exists(select 1 from public.gst_legacy_document_markers_v520 where tenant_id=p_tenant_id and source_type='sales_return' and source_id=v_id) then raise exception 'Legacy GST evidence was created inside authoritative GST context'; end if;

  insert into public.transaction_corrections(tenant_id,entity_type,entity_id,correction_type,reason,created_by,metadata)
  values(p_tenant_id,'sale',p_sale_id,'return',trim(p_reason),auth.uid(),jsonb_build_object('return_id',v_id,'return_number',v_no,'amount',(v_totals->>'grand_total')::numeric,'gst_engine','v5.2'));

  v_snapshot:=private.gst_snapshot_create_v520(p_tenant_id,'sales_return',v_id,v_no,v_origin.location_id,p_return_date,v_quote,v_line_ids);
  v_journal:=private.gst_authoritative_journal_post_v520(p_tenant_id,v_snapshot);
  select coalesce(sum(amount),0) into v_paid from public.sale_payments where tenant_id=p_tenant_id and sale_id=p_sale_id;
  select coalesce(sum(grand_total),0) into v_prev_returns from public.sales_returns where tenant_id=p_tenant_id and sale_id=p_sale_id and id<>v_id and refund_status<>'waived' and created_at<=(select created_at from public.sales_returns where id=v_id);
  v_ar_reduce:=least((v_totals->>'grand_total')::numeric,greatest(v_sale.grand_total-v_paid-v_prev_returns,0));
  v_credit:=greatest((v_totals->>'grand_total')::numeric-v_ar_reduce,0);
  v_response:=jsonb_build_object('success',true,'gst_engine',v_quote->>'engine','gst_status','POSTED','return_id',v_id,'return_number',v_no,'sale_id',p_sale_id,
    'document_class','credit_note','grand_total',(v_totals->>'grand_total')::numeric,'taxable_total',(v_totals->>'taxable_value')::numeric,'tax_total',(v_totals->>'tax_collected_total')::numeric,
    'cgst',(v_totals->>'cgst')::numeric,'sgst',(v_totals->>'sgst')::numeric,'utgst',(v_totals->>'utgst')::numeric,'igst',(v_totals->>'igst')::numeric,'cess',(v_totals->>'cess')::numeric,
    'recipient_rcm_tax_reversal_total',(v_totals->>'recipient_rcm_tax_payable_total')::numeric,'receivable_reduction',round(v_ar_reduce,2),'customer_credit_due',round(v_credit,2),'refund_status','credit_due',
    'gst_snapshot_id',v_snapshot,'journal_id',v_journal,'original_sale_snapshot_id',v_quote->>'original_sale_snapshot_id');
  v_response:=private.gst_request_complete_v520(p_tenant_id,p_request_id,'gst.sales_return.create.v520','sales_return',v_id,v_snapshot,v_journal,v_response);
  perform private.gst_authoritative_context_exit_v520();
  return v_response;
end $$;


--
-- Name: gst_service_job_bill_v520(uuid, uuid, uuid, date, numeric, text, text, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_service_job_bill_v520(p_tenant_id uuid, p_job_id uuid, p_billing_variant_id uuid, p_due_date date, p_initial_payment numeric, p_payment_method text, p_payment_reference text, p_device_id uuid, p_request_id text, p_supply_type text DEFAULT NULL::text, p_place_of_supply_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  j public.service_jobs%rowtype;
  v_item_type text;
  v_variant_status text;
  v_product_status text;
  v_req_payload jsonb;
  v_req_state jsonb;
  v_old_req jsonb;
  v_contract_items jsonb;
  v_normalized jsonb;
  v_supply text;
  v_pos text;
  v_quote jsonb;
  v_totals jsonb;
  v_bridge jsonb;
  v_source jsonb;
  v_sale_id uuid;
  v_sale_number text;
  v_line_ids jsonb;
  v_snapshot uuid;
  v_journal uuid;
  v_document_number text;
  v_response jsonb;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then
    raise exception 'Access denied';
  end if;
  if not (private.erp_user_is_owner(p_tenant_id)
          or private.erp_has_permission(p_tenant_id,'transport_service.create')
          or private.erp_has_permission(p_tenant_id,'transport_service.manage')) then
    raise exception 'Transport service permission required';
  end if;
  if not (private.gst_v520_has_access(p_tenant_id,'gst_compliance.calculate')
          or private.gst_v520_has_access(p_tenant_id,'gst_compliance.view')) then
    raise exception 'GST calculation permission required';
  end if;
  if p_job_id is null then raise exception 'Service job is required'; end if;
  if p_billing_variant_id is null then raise exception 'Billing service item is required'; end if;
  if coalesce(p_initial_payment,0)<0 then raise exception 'Initial payment cannot be negative'; end if;

  v_req_payload:=jsonb_build_object(
    'job_id',p_job_id,
    'billing_variant_id',p_billing_variant_id,
    'due_date',p_due_date,
    'initial_payment',coalesce(p_initial_payment,0),
    'payment_method',lower(trim(coalesce(p_payment_method,''))),
    'payment_reference',nullif(trim(coalesce(p_payment_reference,'')),''),
    'device_id',p_device_id,
    'supply_type',nullif(upper(trim(coalesce(p_supply_type,''))),''),
    'place_of_supply_code',nullif(trim(coalesce(p_place_of_supply_code,'')),'')
  );
  v_req_state:=private.gst_request_begin_v520(p_tenant_id,p_request_id,'gst.service_job.bill.v520',v_req_payload);
  if coalesce((v_req_state->>'existing')::boolean,false) then
    return v_req_state->'response';
  end if;

  v_old_req:=private.v47_request_existing(p_tenant_id,p_request_id,'sale.create');
  if v_old_req is not null then
    raise exception 'Request ID is already used by the legacy Sale path';
  end if;

  select * into j
  from public.service_jobs
  where id=p_job_id and tenant_id=p_tenant_id
  for update;
  if not found then raise exception 'Service job not found'; end if;
  if j.sale_id is not null then raise exception 'Service job is already billed'; end if;
  if j.status='cancelled' then raise exception 'Cancelled service job cannot be billed'; end if;
  if j.customer_id is null then raise exception 'Assign a customer before billing'; end if;
  if j.location_id is null then raise exception 'Service job must have a business location before billing'; end if;
  if coalesce(j.quantity,0)<=0 then raise exception 'Service job quantity must be positive'; end if;
  if coalesce(j.rate,0)<0 then raise exception 'Service job rate cannot be negative'; end if;
  if p_due_date is not null and p_due_date<j.service_date then raise exception 'Due date cannot be before service date'; end if;

  perform private.v4_location_access(p_tenant_id,j.location_id,'operate');
  perform private.erp_validate_transaction_origin(p_tenant_id,j.location_id,p_device_id,'sales');

  select p.item_type,p.status,pv.status
    into v_item_type,v_product_status,v_variant_status
  from public.product_variants pv
  join public.products p on p.id=pv.product_id and p.tenant_id=pv.tenant_id
  where pv.id=p_billing_variant_id and pv.tenant_id=p_tenant_id;
  if v_item_type is null or v_product_status<>'active' or v_variant_status<>'active' then
    raise exception 'Billing service item is invalid or inactive';
  end if;
  if v_item_type='stock' then
    raise exception 'Transport/service billing requires a Service or Non-stock item';
  end if;

  v_contract_items:=jsonb_build_array(jsonb_build_object(
    'variant_id',p_billing_variant_id,
    'quantity',j.quantity,
    'unit_price',j.rate,
    'discount_amount',0
  ));
  v_normalized:=private.v481_normalize_items(p_tenant_id,v_contract_items,'sale');
  v_supply:=private.gst_sale_supply_type_resolve_v520(p_tenant_id,j.customer_id,j.service_date,p_supply_type);
  v_pos:=private.gst_sale_pos_resolve_v520(p_tenant_id,j.customer_id,j.location_id,j.service_date,v_supply,v_normalized,p_place_of_supply_code);
  if v_pos is null then
    raise exception 'Place of supply is required for GST service billing; select the legally applicable GST state/territory code for this service';
  end if;

  v_quote:=public.gst_document_quote_v520(
    p_tenant_id,'sale',j.location_id,j.customer_id,j.service_date,v_supply,v_pos,v_normalized,0,0
  );
  if coalesce((v_quote->>'ready_for_compliance')::boolean,false) is not true then
    raise exception 'GST Service invoice is not compliance-ready: %',coalesce(v_quote->'errors','[]'::jsonb)::text;
  end if;
  v_totals:=v_quote->'totals';
  if coalesce(p_initial_payment,0)>coalesce((v_totals->>'grand_total')::numeric,0)+0.005 then
    raise exception 'Initial payment cannot exceed GST service invoice total';
  end if;
  if coalesce(p_initial_payment,0)>0
     and lower(trim(coalesce(p_payment_method,''))) not in('cash','bank','card','upi','cheque','other') then
    raise exception 'Invalid payment method';
  end if;

  -- Preserve the contractual service-job rate.  Do not call the ordinary v4.8.2
  -- price resolver here: service jobs are already commercially priced upstream.
  -- The bridge lets the legacy operational Sale carry the exact GST grand total
  -- without making legacy tax calculation authoritative.
  v_bridge:=private.gst_sale_bridge_v520(v_contract_items,v_normalized,(v_totals->>'grand_total')::numeric);

  perform private.gst_authoritative_context_enter_v520(p_tenant_id,'sale');
  v_source:=public.sales_create_v481(
    p_tenant_id,j.customer_id,j.service_date,p_due_date,
    v_bridge->'items',(v_bridge->>'additional_charges')::numeric,
    coalesce(p_initial_payment,0),
    case when coalesce(p_initial_payment,0)>0 then lower(trim(p_payment_method)) else 'credit' end,
    coalesce(p_payment_reference,''),
    'Transport service '||j.job_number||' • '||coalesce(j.tracking_code,''),
    j.location_id,p_device_id,p_request_id
  );
  v_sale_id:=nullif(v_source->>'sale_id','')::uuid;
  if v_sale_id is null then raise exception 'GST Service Sale source could not be resolved'; end if;
  perform private.gst_authoritative_context_bind_v520(v_sale_id);

  select s.sale_number into v_sale_number
  from public.sales s
  where s.tenant_id=p_tenant_id and s.id=v_sale_id and s.status='posted'
  for update;
  if v_sale_number is null then raise exception 'GST Service Sale source is not posted'; end if;

  if exists(select 1 from public.journal_entries x where x.tenant_id=p_tenant_id and x.source_type='sale' and x.source_id=v_sale_id and x.status='posted') then
    raise exception 'Legacy Sale journal was created inside authoritative GST service context';
  end if;
  if exists(select 1 from public.gst_legacy_document_markers_v520 x where x.tenant_id=p_tenant_id and x.source_type='sale' and x.source_id=v_sale_id) then
    raise exception 'Legacy GST evidence was created inside authoritative GST service context';
  end if;

  v_line_ids:=private.gst_sale_reconcile_source_v520(p_tenant_id,v_sale_id,v_quote);
  v_snapshot:=private.gst_snapshot_create_v520(p_tenant_id,'sale',v_sale_id,v_sale_number,j.location_id,j.service_date,v_quote,v_line_ids);
  v_journal:=private.gst_authoritative_journal_post_v520(p_tenant_id,v_snapshot);

  select s.document_number into v_document_number
  from public.gst_document_snapshots_v520 s
  where s.id=v_snapshot and s.tenant_id=p_tenant_id;
  if v_document_number is null then raise exception 'GST Service legal document number was not captured'; end if;

  update public.sale_items
  set pricing_source='service_job',
      pricing_metadata=coalesce(pricing_metadata,'{}'::jsonb)||jsonb_strip_nulls(jsonb_build_object(
        'service_job_id',j.id,
        'service_job_number',j.job_number,
        'service_rate',j.rate,
        'quantity_unit',j.quantity_unit,
        'from_location',j.from_location,
        'to_location',j.to_location,
        'distance_km',j.distance_km,
        'pricing_policy','contract_rate_preserved_v520'
      ))
  where tenant_id=p_tenant_id and sale_id=v_sale_id and variant_id=p_billing_variant_id;

  update public.service_jobs
  set sale_id=v_sale_id,status='completed',updated_at=now()
  where id=j.id and tenant_id=p_tenant_id and sale_id is null;
  if not found then raise exception 'Service job billing link changed concurrently'; end if;

  v_response:=coalesce(v_source,'{}'::jsonb)||jsonb_build_object(
    'success',true,
    'billing_source','service_job_v520',
    'gst_engine',v_quote->>'engine',
    'gst_status','POSTED',
    'gst_supply_type',v_supply,
    'place_of_supply_code',v_quote->>'place_of_supply_code',
    'job_id',j.id,
    'job_number',j.job_number,
    'service_rate',j.rate,
    'service_quantity',j.quantity,
    'service_quantity_unit',j.quantity_unit,
    'sale_id',v_sale_id,
    'sale_number',v_sale_number,
    'invoice_number',v_document_number,
    'grand_total',(v_totals->>'grand_total')::numeric,
    'taxable_total',(v_totals->>'taxable_value')::numeric,
    'tax_total',(v_totals->>'tax_collected_total')::numeric,
    'cgst',(v_totals->>'cgst')::numeric,
    'sgst',(v_totals->>'sgst')::numeric,
    'utgst',(v_totals->>'utgst')::numeric,
    'igst',(v_totals->>'igst')::numeric,
    'cess',(v_totals->>'cess')::numeric,
    'recipient_rcm_tax_payable_total',coalesce((v_totals->>'recipient_rcm_tax_payable_total')::numeric,0),
    'gst_snapshot_id',v_snapshot,
    'journal_id',v_journal,
    'gst_ready_for_compliance',true
  );

  perform private.business_audit_write_v471(
    p_tenant_id,'service.job.bill.gst_v520','service_job',j.id,j.job_number,to_jsonb(j),
    jsonb_build_object('sale_id',v_sale_id,'sale_number',v_sale_number,'invoice_number',v_document_number,'grand_total',(v_totals->>'grand_total')::numeric,'gst_snapshot_id',v_snapshot,'journal_id',v_journal)
  );

  v_response:=private.gst_request_complete_v520(
    p_tenant_id,p_request_id,'gst.service_job.bill.v520','sale',v_sale_id,v_snapshot,v_journal,v_response
  );
  update public.transaction_requests_v47
  set response=v_response
  where tenant_id=p_tenant_id and request_id=trim(p_request_id) and operation='sale.create';

  perform private.gst_authoritative_context_exit_v520();
  return v_response;
end
$$;


--
-- Name: gst_setup_health_v520(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_setup_health_v520(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare regs int;locs int;mapped int;products int;profiles int;review int;missing_hsn int;party_profiles int;legacy_invalid int;begin if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.view') then raise exception 'GST compliance view permission required';end if;select count(*) into regs from public.gst_registrations_v520 where tenant_id=p_tenant_id and active;select count(*) into locs from public.business_locations where tenant_id=p_tenant_id and active;select count(distinct location_id) into mapped from public.gst_location_registrations_v520 where tenant_id=p_tenant_id and effective_to is null;select count(*) into products from public.product_variants pv join public.products p on p.id=pv.product_id and p.tenant_id=pv.tenant_id where pv.tenant_id=p_tenant_id and pv.status='active' and p.status='active';select count(*),count(*) filter(where validation_status='review_required'),count(*) filter(where hsn_sac is null) into profiles,review,missing_hsn from public.gst_product_tax_profiles_v520 where tenant_id=p_tenant_id and active and effective_to is null;select count(*) into party_profiles from public.gst_party_registrations_v520 where tenant_id=p_tenant_id and active and effective_to is null;select count(*) into legacy_invalid from public.products p where p.tenant_id=p_tenant_id and p.status='active' and not exists(select 1 from public.gst_tax_rate_master_v520 r where r.active and r.rate=p.tax_rate);return jsonb_build_object('stage','v5.2-A foundation','registrations',regs,'active_locations',locs,'mapped_locations',mapped,'unmapped_locations',greatest(locs-mapped,0),'active_variants',products,'tax_profiles',profiles,'profiles_review_required',review,'profiles_missing_hsn_sac',missing_hsn,'party_gst_profiles',party_profiles,'legacy_products_with_unlisted_rate',legacy_invalid,'setup_ready',regs>0 and locs=mapped and products=profiles and review=0 and missing_hsn=0,'provider_connected',false,'einvoice_live',false,'ewaybill_live',false,'returns_live',false,'notes','Provider/GSP/IRP integration is intentionally disabled in foundation stage.');end $$;


--
-- Name: gst_setup_lookups_v520(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_setup_lookups_v520(p_tenant_id uuid, p_kind text DEFAULT 'all'::text, p_query text DEFAULT ''::text, p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_kind text := lower(trim(coalesce(p_kind,'all')));
  v_query text := lower(trim(coalesce(p_query,'')));
  v_like text := '%'||lower(trim(coalesce(p_query,'')))||'%';
  v_limit integer := greatest(1,least(coalesce(p_limit,200),500));
  v_locations jsonb := '[]'::jsonb;
  v_products jsonb := '[]'::jsonb;
  v_customers jsonb := '[]'::jsonb;
  v_suppliers jsonb := '[]'::jsonb;
begin
  if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.view') then
    raise exception 'GST compliance view permission required';
  end if;

  if v_kind not in ('all','locations','products','customers','suppliers') then
    raise exception 'Unsupported GST setup lookup kind %',v_kind;
  end if;

  if v_kind in ('all','products','customers','suppliers')
     and not private.gst_v520_has_access(p_tenant_id,'gst_compliance.manage') then
    raise exception 'GST compliance manage permission required';
  end if;

  if v_kind in ('all','locations') then
    select coalesce(jsonb_agg(x.row_json order by x.location_name),'[]'::jsonb)
      into v_locations
    from (
      select l.name as location_name,
             jsonb_build_object(
               'id',l.id,
               'name',l.name,
               'location_type',l.location_type,
               'active',l.active,
               'registration_id',gm.registration_id,
               'gstin',gr.gstin,
               'registration_legal_name',gr.legal_name,
               'registration_state_code',gr.state_code,
               'mapping_effective_from',gm.effective_from
             ) as row_json
      from public.business_locations l
      left join lateral (
        select m.registration_id,m.effective_from
        from public.gst_location_registrations_v520 m
        where m.tenant_id=l.tenant_id
          and m.location_id=l.id
          and current_date between m.effective_from and coalesce(m.effective_to,'infinity'::date)
        order by m.effective_from desc,m.created_at desc
        limit 1
      ) gm on true
      left join public.gst_registrations_v520 gr
        on gr.tenant_id=l.tenant_id and gr.id=gm.registration_id
      where l.tenant_id=p_tenant_id
        and l.active
        and (
          coalesce(auth.role(),'')='service_role'
          or private.erp_user_is_owner(p_tenant_id)
          or private.erp_has_permission(p_tenant_id,'locations.manage_all')
          or private.erp_has_permission(p_tenant_id,'locations.view_all')
          or private.erp_user_location_allowed(p_tenant_id,l.id,'view',auth.uid())
        )
        and (v_query='' or lower(l.name) like v_like)
      order by l.name
      limit v_limit
    ) x;
  end if;

  if v_kind in ('all','products') then
    select coalesce(jsonb_agg(x.row_json order by x.product_name,x.variant_name),'[]'::jsonb)
      into v_products
    from (
      select p.name as product_name,pv.name as variant_name,
             jsonb_build_object(
               'variant_id',pv.id,
               'product_id',p.id,
               'product_name',p.name,
               'variant_name',pv.name,
               'sku',pv.sku,
               'item_type',p.item_type,
               'configured',gp.id is not null,
               'profile_id',gp.id,
               'supply_kind',gp.supply_kind,
               'hsn_sac',gp.hsn_sac,
               'taxability',gp.taxability,
               'gst_rate',gp.gst_rate,
               'cess_rate',gp.cess_rate,
               'cess_per_unit',gp.cess_per_unit,
               'tax_inclusive',gp.tax_inclusive,
               'reverse_charge',gp.reverse_charge,
               'validation_status',gp.validation_status,
               'effective_from',gp.effective_from
             ) as row_json
      from public.product_variants pv
      join public.products p on p.id=pv.product_id and p.tenant_id=pv.tenant_id
      left join lateral (
        select g.*
        from public.gst_product_tax_profiles_v520 g
        where g.tenant_id=pv.tenant_id
          and g.variant_id=pv.id
          and current_date between g.effective_from and coalesce(g.effective_to,'infinity'::date)
        order by g.active desc,g.effective_from desc,g.created_at desc
        limit 1
      ) gp on true
      where pv.tenant_id=p_tenant_id
        and pv.status='active'
        and p.status='active'
        and (
          v_query=''
          or lower(p.name) like v_like
          or lower(coalesce(pv.name,'')) like v_like
          or lower(coalesce(pv.sku,'')) like v_like
          or lower(coalesce(gp.hsn_sac,'')) like v_like
        )
      order by p.name,pv.name
      limit v_limit
    ) x;
  end if;

  if v_kind in ('all','customers') then
    select coalesce(jsonb_agg(x.row_json order by x.party_name),'[]'::jsonb)
      into v_customers
    from (
      select c.name as party_name,
             jsonb_build_object(
               'party_id',c.id,
               'party_type','customer',
               'party_name',c.name,
               'configured',gp.id is not null,
               'profile_id',gp.id,
               'registration_type',gp.registration_type,
               'gstin',gp.gstin,
               'legal_name',gp.legal_name,
               'trade_name',gp.trade_name,
               'state_code',gp.state_code,
               'place_of_supply_code',gp.place_of_supply_code,
               'validation_status',gp.validation_status,
               'effective_from',gp.effective_from
             ) as row_json
      from public.customers c
      left join lateral (
        select g.*
        from public.gst_party_registrations_v520 g
        where g.tenant_id=c.tenant_id
          and g.party_type='customer'
          and g.party_id=c.id
          and current_date between g.effective_from and coalesce(g.effective_to,'infinity'::date)
        order by g.active desc,g.is_default desc,g.effective_from desc,g.created_at desc
        limit 1
      ) gp on true
      where c.tenant_id=p_tenant_id
        and c.status='active'
        and (
          v_query=''
          or lower(c.name) like v_like
          or lower(coalesce(gp.gstin,'')) like v_like
          or lower(coalesce(gp.legal_name,'')) like v_like
        )
      order by c.name
      limit v_limit
    ) x;
  end if;

  if v_kind in ('all','suppliers') then
    select coalesce(jsonb_agg(x.row_json order by x.party_name),'[]'::jsonb)
      into v_suppliers
    from (
      select s.name as party_name,
             jsonb_build_object(
               'party_id',s.id,
               'party_type','supplier',
               'party_name',s.name,
               'configured',gp.id is not null,
               'profile_id',gp.id,
               'registration_type',gp.registration_type,
               'gstin',gp.gstin,
               'legal_name',gp.legal_name,
               'trade_name',gp.trade_name,
               'state_code',gp.state_code,
               'place_of_supply_code',gp.place_of_supply_code,
               'validation_status',gp.validation_status,
               'effective_from',gp.effective_from
             ) as row_json
      from public.suppliers s
      left join lateral (
        select g.*
        from public.gst_party_registrations_v520 g
        where g.tenant_id=s.tenant_id
          and g.party_type='supplier'
          and g.party_id=s.id
          and current_date between g.effective_from and coalesce(g.effective_to,'infinity'::date)
        order by g.active desc,g.is_default desc,g.effective_from desc,g.created_at desc
        limit 1
      ) gp on true
      where s.tenant_id=p_tenant_id
        and s.status='active'
        and (
          v_query=''
          or lower(s.name) like v_like
          or lower(coalesce(gp.gstin,'')) like v_like
          or lower(coalesce(gp.legal_name,'')) like v_like
        )
      order by s.name
      limit v_limit
    ) x;
  end if;

  return jsonb_build_object(
    'kind',v_kind,
    'query',trim(coalesce(p_query,'')),
    'limit',v_limit,
    'locations',v_locations,
    'products',v_products,
    'customers',v_customers,
    'suppliers',v_suppliers
  );
end;
$$;


--
-- Name: gst_snapshot_coverage_v520(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_snapshot_coverage_v520(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare total_docs bigint;authoritative bigint;legacy bigint;unclassified bigint;tampered_legacy bigint;begin if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.view') then raise exception 'GST compliance view permission required';end if;select count(*) into total_docs from (select id from public.sales where tenant_id=p_tenant_id and status='posted' union all select id from public.purchases where tenant_id=p_tenant_id and status='posted' union all select id from public.sales_returns where tenant_id=p_tenant_id union all select id from public.purchase_returns where tenant_id=p_tenant_id union all select id from public.purchase_invoices_v484 where tenant_id=p_tenant_id and status not in('draft','void'))z;select count(*) into authoritative from public.gst_document_snapshots_v520 where tenant_id=p_tenant_id;select count(*) into legacy from public.gst_legacy_document_markers_v520 where tenant_id=p_tenant_id;unclassified:=greatest(total_docs-authoritative-legacy,0);select count(*) into tampered_legacy from public.gst_legacy_document_markers_v520 m where m.tenant_id=p_tenant_id and m.source_hash is distinct from(case when private.gst_legacy_source_payload_v520(m.tenant_id,m.source_type,m.source_id) is null then null else encode(extensions.digest(convert_to(private.gst_legacy_source_payload_v520(m.tenant_id,m.source_type,m.source_id)::text,'UTF8'),'sha256'),'hex') end);return jsonb_build_object('total_finalized_documents',total_docs,'authoritative_snapshots',authoritative,'legacy_unverified',legacy,'unclassified_documents',unclassified,'legacy_source_hash_mismatches',tampered_legacy,'ready',unclassified=0 and tampered_legacy=0);end$$;


--
-- Name: gst_snapshot_get_v520(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_snapshot_get_v520(p_tenant_id uuid, p_source_type text, p_source_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v_lines jsonb;stored_hash text;calculated_hash text;links jsonb;q jsonb;s record;begin if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.view') then raise exception 'GST compliance view permission required';end if;select x.* into s from public.gst_document_snapshots_v520 x where x.tenant_id=p_tenant_id and x.source_type=p_source_type and x.source_id=p_source_id;if not found then return null;end if;select coalesce(jsonb_agg(to_jsonb(l) order by l.line_no),'[]'::jsonb),coalesce(jsonb_agg(to_jsonb(l.source_line_id) order by l.line_no),'[]'::jsonb) into v_lines,links from public.gst_document_line_snapshots_v520 l where l.snapshot_id=s.id;q:=s.quote_payload;stored_hash:=s.snapshot_hash;calculated_hash:=encode(extensions.digest(convert_to(jsonb_build_object('tenant_id',s.tenant_id,'source_type',s.source_type,'source_id',s.source_id,'source_number',s.source_number,'document_date',s.document_date,'location_id',s.location_id,'source_line_ids',links,'quote',q)::text,'UTF8'),'sha256'),'hex');return to_jsonb(s)||jsonb_build_object('lines',v_lines,'hash_valid',stored_hash=calculated_hash);end$$;


--
-- Name: gst_state_code_resolve_v520(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_state_code_resolve_v520(p_value text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $_$ declare v text:=trim(coalesce(p_value,''));v_code text;begin if v='' then return null;end if;if v ~ '^[0-9]{2}$' and exists(select 1 from public.gst_state_master_v520 where code=v) then return v;end if;select s.code into v_code from public.gst_state_master_v520 s where lower(s.name)=lower(v) or exists(select 1 from jsonb_array_elements_text(s.aliases) a(value) where lower(a.value)=lower(v)) order by s.active desc,s.code limit 1;return v_code;end $_$;


--
-- Name: gst_summary_v4(uuid, date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_summary_v4(p_tenant_id uuid, p_from date, p_to date, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_out numeric;v_in numeric;v_sales numeric;v_purchases numeric;v_sr_tax numeric;v_pr_tax numeric;v_sr_sub numeric;v_pr_sub numeric;begin
 if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
 select coalesce(sum(s.tax_total),0),coalesce(sum(s.taxable_total),0) into v_out,v_sales from public.sales s left join public.document_origins o on o.entity_type='sale' and o.entity_id=s.id where s.tenant_id=p_tenant_id and s.sale_date between p_from and p_to and coalesce(s.status,'') not in('void','cancelled') and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view');
 select coalesce(sum(p.tax_total),0),coalesce(sum(p.taxable_total),0) into v_in,v_purchases from public.purchases p left join public.document_origins o on o.entity_type='purchase' and o.entity_id=p.id where p.tenant_id=p_tenant_id and p.purchase_date between p_from and p_to and coalesce(p.status,'') not in('void','cancelled') and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view');
 select coalesce(sum(tax_total),0),coalesce(sum(subtotal),0) into v_sr_tax,v_sr_sub from public.sales_returns where tenant_id=p_tenant_id and return_date between p_from and p_to and refund_status<>'waived' and private.erp_document_scope_allowed(p_tenant_id,location_id,p_location_id,'view');
 select coalesce(sum(tax_total),0),coalesce(sum(subtotal),0) into v_pr_tax,v_pr_sub from public.purchase_returns where tenant_id=p_tenant_id and return_date between p_from and p_to and credit_status<>'waived' and private.erp_document_scope_allowed(p_tenant_id,location_id,p_location_id,'view');
 return jsonb_build_object('taxable_sales',greatest(v_sales-v_sr_sub,0),'output_gst',greatest(v_out-v_sr_tax,0),'taxable_purchases',greatest(v_purchases-v_pr_sub,0),'input_gst',greatest(v_in-v_pr_tax,0),'sales_return_tax',v_sr_tax,'purchase_return_tax',v_pr_tax,'net_gst_payable',(v_out-v_sr_tax)-(v_in-v_pr_tax));
end $$;


--
-- Name: gst_tax_mode_get_v520(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_tax_mode_get_v520(p_tenant_id uuid, p_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  r public.gst_tenant_tax_modes_v520%rowtype;
  d date:=coalesce(p_date,current_date);
begin
  if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.view')
     and not private.gst_v520_has_access(p_tenant_id,'gst_compliance.calculate') then
    raise exception 'GST/tax configuration view permission required';
  end if;

  select * into r
  from public.gst_tenant_tax_modes_v520 m
  where m.tenant_id=p_tenant_id
    and d between m.effective_from and coalesce(m.effective_to,'infinity'::date)
  order by m.effective_from desc,m.created_at desc
  limit 1;

  return jsonb_build_object(
    'tax_mode',coalesce(r.tax_mode,'unconfigured'),
    'configured',r.id is not null,
    'gst_applicable',coalesce(r.tax_mode,'unconfigured')='gst_registered',
    'effective_from',r.effective_from,
    'effective_to',r.effective_to,
    'reason',r.reason,
    'as_of',d
  );
end
$$;


--
-- Name: gst_tax_mode_set_v520(uuid, text, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_tax_mode_set_v520(p_tenant_id uuid, p_tax_mode text, p_effective_from date DEFAULT CURRENT_DATE, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_mode text:=lower(trim(coalesce(p_tax_mode,'')));
  v_date date:=coalesce(p_effective_from,current_date);
  v_reason text:=nullif(trim(coalesce(p_reason,'')),'');
  cur public.gst_tenant_tax_modes_v520%rowtype;
  v_id uuid;
  v_before jsonb;
begin
  if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.configure') then
    raise exception 'GST/tax configuration permission required';
  end if;
  if v_mode not in ('gst_registered','non_gst') then
    raise exception 'Tax mode must be gst_registered or non_gst';
  end if;
  if not exists(select 1 from public.tenants t where t.id=p_tenant_id and t.status='active') then
    raise exception 'Active business not found';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':tax-mode-v520',0));

  if exists(
    select 1 from public.gst_document_snapshots_v520 s
    where s.tenant_id=p_tenant_id
      and s.document_date>=v_date
      and s.tax_mode<>v_mode
  ) then
    raise exception 'Tax mode cannot be changed across already-posted authoritative documents. Choose a later effective date.';
  end if;

  select * into cur
  from public.gst_tenant_tax_modes_v520 m
  where m.tenant_id=p_tenant_id and m.effective_to is null
  order by m.effective_from desc
  limit 1
  for update;

  if cur.id is null then
    insert into public.gst_tenant_tax_modes_v520(tenant_id,tax_mode,effective_from,reason,created_by)
    values(p_tenant_id,v_mode,v_date,v_reason,auth.uid())
    returning id into v_id;
  elsif v_date<cur.effective_from then
    raise exception 'Effective date cannot precede the current tax-mode period (%)',cur.effective_from;
  elsif v_date=cur.effective_from then
    v_before:=to_jsonb(cur);
    update public.gst_tenant_tax_modes_v520
    set tax_mode=v_mode,reason=v_reason
    where id=cur.id
    returning id into v_id;
  elsif cur.tax_mode=v_mode then
    v_id:=cur.id;
  else
    v_before:=to_jsonb(cur);
    update public.gst_tenant_tax_modes_v520
      set effective_to=v_date-1
      where id=cur.id;
    insert into public.gst_tenant_tax_modes_v520(tenant_id,tax_mode,effective_from,reason,created_by)
    values(p_tenant_id,v_mode,v_date,v_reason,auth.uid())
    returning id into v_id;
  end if;

  perform private.business_audit_write_v471(
    p_tenant_id,'gst.tax_mode.set','tenant',p_tenant_id,v_mode,
    v_before,
    (select to_jsonb(m) from public.gst_tenant_tax_modes_v520 m where m.id=v_id)
  );

  return public.gst_tax_mode_get_v520(p_tenant_id,v_date);
end
$$;


--
-- Name: gst_transaction_cutover_contract_base_v520(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_transaction_cutover_contract_base_v520(p_tenant_id uuid, p_channel text DEFAULT 'client'::text, p_device_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_channel text := lower(trim(coalesce(p_channel,'client')));
  v_device_contract jsonb := null;
begin
  if p_tenant_id is null then
    raise exception 'Tenant is required';
  end if;

  if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.calculate')
     and not private.gst_v520_has_access(p_tenant_id,'gst_compliance.view') then
    raise exception 'GST transaction access required';
  end if;

  if v_channel not in ('client','pos','pos_offline','mobile_pos') then
    raise exception 'Unsupported GST cutover channel: %', p_channel;
  end if;

  if v_channel in ('pos_offline','mobile_pos') then
    if p_device_id is null then
      raise exception 'Device is required for % GST cutover contract', v_channel;
    end if;

    if v_channel='pos_offline' then
      v_device_contract := public.pos_offline_api_contract_v520(p_tenant_id,p_device_id);
    else
      v_device_contract := public.mobile_pos_api_contract_v520(p_tenant_id,p_device_id);
    end if;
  end if;

  return jsonb_build_object(
    'release','5.2.0-foundation',
    'contract_version',1,
    'channel',v_channel,
    'cutover_ready',true,
    'activation_mode','explicit_app_rpc_switch',
    'legacy_app_baseline',jsonb_build_object(
      'app_version','5.1.0',
      'build',27,
      'backend_contract_migration',213,
      'behavior','unchanged'
    ),
    'rules',jsonb_build_object(
      'old_clients_continue_v510',true,
      'v520_route_requires_v520_writer',true,
      'legacy_fallback_after_v520_route',false,
      'tax_calculation','server_authoritative_only',
      'request_id','required_for_retryable_writes',
      'authoritative_evidence','same_transaction',
      'authoritative_accounting','same_transaction'
    ),
    'rpc',jsonb_build_object(
      'sale','gst_sale_create_v520',
      'purchase','gst_purchase_create_v520',
      'purchase_invoice_v2','gst_purchase_invoice_create_v520',
      'sales_return','gst_sales_return_create_v520',
      'purchase_return','gst_purchase_return_create_v520',
      'service_bill','gst_service_job_bill_v520',
      'restaurant_bill',case when v_channel='mobile_pos' then 'mobile_pos_restaurant_bill_v520' else 'gst_restaurant_order_bill_v520' end,
      'offline_sale_sync','gst_pos_offline_sale_sync_v520',
      'mobile_sale_sync','gst_mobile_pos_sale_sync_v520',
      'gst_workspace','gst_ui_contract_v520'
    ),
    'channel_routes',
      case v_channel
        when 'client' then jsonb_build_object(
          'sale','gst_sale_create_v520',
          'purchase','gst_purchase_create_v520',
          'purchase_invoice_v2','gst_purchase_invoice_create_v520',
          'sales_return','gst_sales_return_create_v520',
          'purchase_return','gst_purchase_return_create_v520',
          'service_bill','gst_service_job_bill_v520',
          'gst_workspace','gst_ui_contract_v520'
        )
        when 'pos' then jsonb_build_object(
          'sale','gst_sale_create_v520',
          'sales_return','gst_sales_return_create_v520',
          'restaurant_bill','gst_restaurant_order_bill_v520'
        )
        when 'pos_offline' then jsonb_build_object(
          'sale_sync','gst_pos_offline_sale_sync_v520',
          'api_contract','pos_offline_api_contract_v520'
        )
        else jsonb_build_object(
          'sale_sync','gst_mobile_pos_sale_sync_v520',
          'restaurant_bill','mobile_pos_restaurant_bill_v520',
          'api_contract','mobile_pos_api_contract_v520'
        )
      end,
    'device_contract',v_device_contract
  );
end$$;


--
-- Name: gst_transaction_cutover_contract_v520(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_transaction_cutover_contract_v520(p_tenant_id uuid, p_channel text DEFAULT 'client'::text, p_device_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v jsonb;
  v_mode text := private.gst_tax_mode_resolve_v520(p_tenant_id,current_date);
  v_channel text := lower(trim(coalesce(p_channel,'client')));
begin
  v := public.gst_transaction_cutover_contract_base_v520(
    p_tenant_id,
    p_channel,
    p_device_id
  );

  -- Client has always had a Restaurant workspace. v5.2 final billing must use
  -- the same authoritative restaurant GST writer as POS rather than leaving
  -- Client on restaurant_order_bill_v489.
  if v_channel = 'client' then
    v := jsonb_set(
      v,
      '{channel_routes}',
      coalesce(v->'channel_routes','{}'::jsonb) ||
        jsonb_build_object('restaurant_bill','gst_restaurant_order_bill_v520'),
      true
    );
  end if;

  v := coalesce(v,'{}'::jsonb) || jsonb_build_object(
    'tax_mode',v_mode,
    'tax_mode_configured',v_mode<>'unconfigured',
    'gst_applicable',v_mode='gst_registered',
    'tax_mode_rpc','gst_tax_mode_get_v520',
    'tax_mode_save_rpc','gst_tax_mode_set_v520'
  );
  v := jsonb_set(v,'{cutover_ready}',to_jsonb(v_mode<>'unconfigured'),true);
  v := jsonb_set(
    v,
    '{rules}',
    coalesce(v->'rules','{}'::jsonb) || jsonb_build_object(
      'tenant_tax_mode_required',true,
      'non_gst_uses_v520_writer',true,
      'non_gst_gst_amounts_zero',true,
      'non_gst_legacy_fallback',false
    ),
    true
  );
  if v_mode='unconfigured' then
    v := v || jsonb_build_object('blocking_reason','tax_mode_unconfigured');
  end if;
  return v;
end;
$$;


--
-- Name: gst_transaction_cutover_contract_v522(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_transaction_cutover_contract_v522(p_tenant_id uuid, p_channel text DEFAULT 'client'::text, p_device_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v jsonb;v_channel text:=lower(trim(coalesce(p_channel,'client')));
begin
  v:=public.gst_transaction_cutover_contract_v520(p_tenant_id,p_channel,p_device_id);
  if v_channel='client' then
    v:=jsonb_set(v,'{channel_routes}',coalesce(v->'channel_routes','{}'::jsonb)||jsonb_build_object('sale','gst_sale_create_v522'),true);
  elsif v_channel='pos' then
    v:=jsonb_set(v,'{channel_routes}',coalesce(v->'channel_routes','{}'::jsonb)||jsonb_build_object('sale','gst_pos_sale_create_v522'),true);
  elsif v_channel in ('pos_offline','offline_pos') then
    v:=jsonb_set(v,'{channel_routes}',coalesce(v->'channel_routes','{}'::jsonb)||jsonb_build_object('sale_sync','gst_pos_offline_sale_sync_v522'),true);
  elsif v_channel='mobile_pos' then
    v:=jsonb_set(v,'{channel_routes}',coalesce(v->'channel_routes','{}'::jsonb)||jsonb_build_object('sale_sync','gst_mobile_pos_sale_sync_v522'),true);
  end if;
  v:=v||jsonb_build_object('version','5.2.2','build',30,'multi_payment',true,'automatic_round_off',true,
    'legacy_fallback_after_v522_failure',false,'additional_charges','service_products_only',
    'payment_methods',jsonb_build_array('cash','upi','card','bank','cheque','wallet','credit','other'));
  return v;
end;
$$;


--
-- Name: gst_ui_contract_base_v520(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_ui_contract_base_v520(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if not private.gst_v520_has_access(p_tenant_id,'gst_compliance.view') then
    raise exception 'GST compliance view permission required';
  end if;

  return jsonb_build_object(
    'release','5.2.0-foundation',
    'contract_version',4,
    'workspace','GST & Compliance',
    'bootstrap_rpc','gst_compliance_bootstrap_v520',
    'setup_lookup_rpc','gst_setup_lookups_v520',
    'capabilities',jsonb_build_object(
      'view',private.gst_v520_has_access(p_tenant_id,'gst_compliance.view'),
