      'returns',private.gst_v520_has_access(p_tenant_id,'gst_compliance.returns'),
      'submit',private.gst_v520_has_access(p_tenant_id,'gst_compliance.submit'),
      'einvoice',private.gst_v520_has_access(p_tenant_id,'gst_compliance.einvoice'),
      'ewaybill',private.gst_v520_has_access(p_tenant_id,'gst_compliance.ewaybill'),
      'cancel_irn',private.gst_v520_has_access(p_tenant_id,'gst_compliance.cancel_irn'),
      'period_lock',private.gst_v520_has_access(p_tenant_id,'gst_compliance.period_lock')
    ),
    'form_options',jsonb_build_object(
      'registration_types',jsonb_build_array('regular','composition','casual','sez','isd','tcs','tds','non_resident','other'),
      'party_registration_types',jsonb_build_array('registered','unregistered','composition','sez','export','exempt'),
      'supply_kinds',jsonb_build_array('goods','service'),
      'taxability',jsonb_build_array('taxable','nil_rated','exempt','non_gst')
    ),
    'tabs',jsonb_build_array(
      jsonb_build_object(
        'key','overview','label','Overview','rpc','gst_compliance_workspace_v520',
        'permission','gst_compliance.view','enabled',true
      ),
      jsonb_build_object(
        'key','registrations','label','Registrations',
        'list_rpc','gst_registrations_list_v520',
        'save_rpc','gst_registration_save_v520',
        'config_rpc','gst_registration_config_v520',
        'location_map_rpc','gst_location_registration_set_v520',
        'lookup_rpc','gst_setup_lookups_v520',
        'location_mapping_required',true,
        'permission','gst_compliance.view',
        'write_permission','gst_compliance.configure',
        'enabled',true
      ),
      jsonb_build_object(
        'key','products','label','Product GST',
        'list_rpc','gst_product_profiles_list_v520',
        'save_rpc','gst_product_profile_save_v520',
        'lookup_rpc','gst_setup_lookups_v520',
        'permission','gst_compliance.view',
        'write_permission','gst_compliance.manage',
        'enabled',true
      ),
      jsonb_build_object(
        'key','parties','label','Party GST',
        'list_rpc','gst_party_profiles_list_v520',
        'save_rpc','gst_party_profile_save_v520',
        'lookup_rpc','gst_setup_lookups_v520',
        'permission','gst_compliance.view',
        'write_permission','gst_compliance.manage',
        'enabled',true
      ),
      jsonb_build_object(
        'key','transactions','label','GST Transactions',
        'list_rpc','gst_documents_list_v520',
        'detail_rpc','gst_document_evidence_v520',
        'permission','gst_compliance.view','enabled',true
      ),
      jsonb_build_object(
        'key','tax_summary','label','Tax Summary','rpc','gst_period_summary_v520',
        'permission','gst_compliance.view','enabled',true
      ),
      jsonb_build_object(
        'key','accounting','label','GST Accounting',
        'health_rpc','gst_accounting_health_v520',
        'control_rpc','gst_accounting_control_v520',
        'permission','gst_compliance.reconcile','enabled',true
      ),
      jsonb_build_object(
        'key','returns','label','GST Returns',
        'preview_rpc','gst_period_summary_v520',
        'permission','gst_compliance.returns','enabled',true,
        'submission_enabled',false
      ),
      jsonb_build_object(
        'key','einvoice','label','E-Invoice',
        'permission','gst_compliance.einvoice','enabled',false,
        'reason','provider_not_configured'
      ),
      jsonb_build_object(
        'key','ewaybill','label','E-Way Bill',
        'permission','gst_compliance.ewaybill','enabled',false,
        'reason','provider_not_configured'
      )
    ),
    'masters_rpc','gst_masters_v520',
    'readiness_rpc','gst_compliance_readiness_v520',
    'rules',jsonb_build_object(
      'tax_calculation','server_authoritative_only',
      'legacy_transactions','view_only_legacy_unverified',
      'new_v520_transactions','no_legacy_fallback',
      'provider_submission','disabled_until_gsp_irp_phase'
    )
  );
end;
$$;


--
-- Name: gst_ui_contract_v520(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gst_ui_contract_v520(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v jsonb;
  v_mode_obj jsonb;
  v_mode text;
  v_tabs jsonb:='[]'::jsonb;
  t jsonb;
begin
  v:=public.gst_ui_contract_base_v520(p_tenant_id);
  v_mode_obj:=public.gst_tax_mode_get_v520(p_tenant_id,current_date);
  v_mode:=coalesce(v_mode_obj->>'tax_mode','unconfigured');

  for t in select value from jsonb_array_elements(coalesce(v->'tabs','[]'::jsonb)) loop
    if v_mode='non_gst' and coalesce(t->>'key','') in ('registrations','products','parties','tax_summary','accounting','returns','einvoice','ewaybill') then
      t:=jsonb_set(t,'{enabled}','false'::jsonb,true)
          || jsonb_build_object('reason','not_applicable_non_gst');
    end if;
    v_tabs:=v_tabs||jsonb_build_array(t);
  end loop;

  v:=jsonb_set(v,'{tabs}',v_tabs,true);
  v:=coalesce(v,'{}'::jsonb)||jsonb_build_object(
    'contract_version',6,
    'tax_mode',v_mode_obj,
    'tax_mode_rpc','gst_tax_mode_get_v520',
    'tax_mode_save_rpc','gst_tax_mode_set_v520',
    'gst_compliance_required',v_mode='gst_registered'
  );
  v:=jsonb_set(v,'{form_options}',coalesce(v->'form_options','{}'::jsonb)||jsonb_build_object(
    'business_tax_modes',jsonb_build_array('gst_registered','non_gst')
  ),true);
  v:=jsonb_set(v,'{rules}',coalesce(v->'rules','{}'::jsonb)||jsonb_build_object(
    'tenant_tax_mode_required',true,
    'non_gst_invoice_class','commercial_invoice',
    'non_gst_gst_amounts_zero',true,
    'non_gst_returns_follow_original_document_tax_mode',true,
    'non_gst_gst_setup_required',false,
    'non_gst_provider_required',false,
    'non_gst_hidden_tabs',jsonb_build_array('registrations','products','parties','tax_summary','accounting','returns','einvoice','ewaybill')
  ),true);
  return v;
end
$$;


--
-- Name: FUNCTION gst_ui_contract_v520(p_tenant_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gst_ui_contract_v520(p_tenant_id uuid) IS 'THQ ERP v5.2 GST & Compliance UI contract v2. Includes bootstrap and location-to-registration mapping actions. Provider submission remains disabled.';


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into public.profiles (id, display_name)
  values (
    new.id,
    coalesce(new.raw_user_meta_data ->> 'display_name', new.raw_user_meta_data ->> 'full_name')
  )
  on conflict (id) do nothing;

  return new;
end;
$$;


--
-- Name: installation_change_authorize_v520(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.installation_change_authorize_v520(p_tenant_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if auth.uid() is null then
    return false;
  end if;

  if not private.erp_user_has_tenant_access(p_tenant_id) then
    return false;
  end if;

  return private.erp_user_is_owner(p_tenant_id)
    or private.erp_has_permission(p_tenant_id, 'settings.manage');
end;
$$;


--
-- Name: inventory_adjust_stock(uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_adjust_stock(p_tenant_id uuid, p_variant_id uuid, p_quantity_delta numeric, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_location_id uuid;

  v_item_type text;

  v_current_quantity numeric;
  v_new_quantity numeric;

  v_movement_type text;
  v_unit_cost numeric;
begin

  -- ----------------------------------------------------------
  -- PERMISSION
  -- ----------------------------------------------------------

  if not private.has_permission(
    p_tenant_id,
    'inventory.manage'
  ) then

    raise exception 'Access denied'
      using errcode = '42501';

  end if;


  -- ----------------------------------------------------------
  -- VALIDATE QUANTITY
  -- ----------------------------------------------------------

  if p_quantity_delta is null
     or p_quantity_delta = 0 then

    raise exception
      'Adjustment quantity cannot be zero';

  end if;


  -- ----------------------------------------------------------
  -- PRODUCT
  -- ----------------------------------------------------------

  select
    p.item_type,
    pv.cost_price

  into
    v_item_type,
    v_unit_cost

  from public.product_variants pv

  join public.products p
    on p.id = pv.product_id
   and p.tenant_id = pv.tenant_id

  where pv.id = p_variant_id
    and pv.tenant_id = p_tenant_id;


  if v_item_type is null then
    raise exception 'Product not found';
  end if;


  if v_item_type <> 'stock' then
    raise exception
      'Stock adjustment is only allowed for stock items';
  end if;


  -- ----------------------------------------------------------
  -- DEFAULT LOCATION
  -- ----------------------------------------------------------

  select il.id
  into v_location_id

  from public.inventory_locations il

  where il.tenant_id = p_tenant_id
    and il.is_active = true

  order by
    il.is_default desc,
    case
      when il.code = 'MAIN'
        then 0
      else 1
    end,
    il.created_at

  limit 1;


  if v_location_id is null then
    raise exception
      'No active inventory location exists';
  end if;


  -- ----------------------------------------------------------
  -- ENSURE BALANCE ROW EXISTS
  -- ----------------------------------------------------------

  insert into public.stock_balances (
    tenant_id,
    location_id,
    variant_id,
    quantity,
    updated_at
  )
  values (
    p_tenant_id,
    v_location_id,
    p_variant_id,
    0,
    now()
  )

  on conflict (
    tenant_id,
    location_id,
    variant_id
  )
  do nothing;


  -- ----------------------------------------------------------
  -- LOCK CURRENT BALANCE
  --
  -- Prevents two stock adjustments from overwriting each other.
  -- ----------------------------------------------------------

  select sb.quantity
  into v_current_quantity

  from public.stock_balances sb

  where sb.tenant_id = p_tenant_id
    and sb.location_id = v_location_id
    and sb.variant_id = p_variant_id

  for update;


  v_current_quantity :=
    coalesce(
      v_current_quantity,
      0
    );


  v_new_quantity :=
    v_current_quantity
    + p_quantity_delta;


  -- ----------------------------------------------------------
  -- DEFAULT RULE:
  -- Do not allow negative stock.
  -- ----------------------------------------------------------

  if v_new_quantity < 0 then

    raise exception
      'Adjustment would make stock negative. Current stock: %',
      v_current_quantity;

  end if;


  -- ----------------------------------------------------------
  -- MOVEMENT TYPE
  -- ----------------------------------------------------------

  if p_quantity_delta > 0 then

    v_movement_type :=
      'adjustment_in';

  else

    v_movement_type :=
      'adjustment_out';

  end if;


  -- ----------------------------------------------------------
  -- STOCK MOVEMENT LEDGER
  -- ----------------------------------------------------------

  insert into public.stock_movements (
    tenant_id,
    variant_id,
    location_id,

    movement_type,
    quantity_delta,

    unit_cost,

    reference_type,

    note,

    occurred_at,
    created_by
  )
  values (
    p_tenant_id,
    p_variant_id,
    v_location_id,

    v_movement_type,
    p_quantity_delta,

    v_unit_cost,

    'manual_adjustment',

    nullif(
      trim(
        coalesce(
          p_note,
          ''
        )
      ),
      ''
    ),

    now(),
    auth.uid()
  );


  -- ----------------------------------------------------------
  -- UPDATE CURRENT BALANCE
  -- ----------------------------------------------------------

  update public.stock_balances
  set
    quantity = v_new_quantity,
    updated_at = now()

  where tenant_id = p_tenant_id
    and location_id = v_location_id
    and variant_id = p_variant_id;


  -- ----------------------------------------------------------
  -- RESULT
  -- ----------------------------------------------------------

  return jsonb_build_object(
    'success', true,
    'old_quantity', v_current_quantity,
    'quantity_delta', p_quantity_delta,
    'new_quantity', v_new_quantity
  );

end;
$$;


--
-- Name: inventory_adjust_stock_v4(uuid, uuid, uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_adjust_stock_v4(p_tenant_id uuid, p_location_id uuid, p_device_id uuid, p_variant_id uuid, p_quantity_delta numeric, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_core jsonb;v_after numeric;v_type text;begin
  perform private.v4_location_access(p_tenant_id,p_location_id,'operate');
  if not private.erp_has_permission(p_tenant_id,'inventory.manage') and not private.erp_has_permission(p_tenant_id,'inventory.adjust') and not private.erp_user_is_owner(p_tenant_id) then raise exception 'Stock adjustment permission required'; end if;
  if coalesce(p_quantity_delta,0)=0 then raise exception 'Adjustment cannot be zero'; end if;
  select public.inventory_adjust_stock(p_tenant_id,p_variant_id,p_quantity_delta,p_note) into v_core;
  v_type:=case when p_quantity_delta>0 then 'adjustment_in' else 'adjustment_out' end;
  v_after:=private.v4_location_stock_apply(p_tenant_id,p_location_id,p_variant_id,p_quantity_delta,v_type,'stock_adjustment',null,null,p_note,p_device_id,false);
  return coalesce(v_core,'{}'::jsonb)||jsonb_build_object('location_id',p_location_id,'location_quantity',v_after);
end $$;


--
-- Name: inventory_adjust_stock_v47(uuid, uuid, uuid, uuid, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_adjust_stock_v47(p_tenant_id uuid, p_location_id uuid, p_device_id uuid, p_variant_id uuid, p_quantity_delta numeric, p_note text, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v jsonb;begin v:=private.v47_request_existing(p_tenant_id,p_request_id,'inventory.adjust');if v is not null then return v;end if;v:=public.inventory_adjust_stock_v4(p_tenant_id,p_location_id,p_device_id,p_variant_id,p_quantity_delta,p_note);return private.v47_request_complete(p_tenant_id,p_request_id,'inventory.adjust',v);end$$;


--
-- Name: inventory_adjust_stock_v483(uuid, uuid, uuid, uuid, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_adjust_stock_v483(p_tenant_id uuid, p_location_id uuid, p_device_id uuid, p_variant_id uuid, p_quantity_delta numeric, p_note text, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$begin return public.stock_adjustment_request_v500(p_tenant_id,p_location_id,p_device_id,p_variant_id,p_quantity_delta,p_note,p_request_id);end $$;


--
-- Name: inventory_barcode_lookup_v44(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_barcode_lookup_v44(p_tenant_id uuid, p_barcode text, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v jsonb;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if trim(coalesce(p_barcode,''))='' then return '{}'::jsonb;end if;
  select jsonb_build_object(
    'variant_id',pv.id,'product_id',p.id,'product_name',p.name,'sku',pv.sku,'barcode',pv.barcode,'part_number',pv.part_number,
    'item_type',p.item_type,'selling_price',coalesce(lps.selling_price,pv.selling_price),'cost_price',pv.cost_price,'tax_rate',pv.tax_rate,
    'location_id',p_location_id,'stock_quantity',coalesce(lsb.quantity,0),'available_quantity',coalesce(lsb.quantity-lsb.reserved_quantity-lsb.damaged_quantity-lsb.quarantine_quantity,0)
  ) into v
  from public.product_variants pv join public.products p on p.id=pv.product_id and p.tenant_id=pv.tenant_id
  left join public.location_product_settings lps on lps.tenant_id=p_tenant_id and lps.variant_id=pv.id and lps.location_id=p_location_id
  left join public.location_stock_balances lsb on lsb.tenant_id=p_tenant_id and lsb.variant_id=pv.id and lsb.location_id=p_location_id
  where pv.tenant_id=p_tenant_id and lower(trim(coalesce(pv.barcode,'')))=lower(trim(p_barcode))
  order by pv.created_at limit 1;
  return coalesce(v,'{}'::jsonb);
end $$;


--
-- Name: inventory_batch_history_v483(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_batch_history_v483(p_tenant_id uuid, p_batch_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v jsonb;begin
 if not private.erp_user_has_tenant_access(p_tenant_id) or not private.v483_trace_view_allowed(p_tenant_id) then raise exception 'Traceability view permission required';end if;
 if not exists(
  select 1 from public.inventory_batch_balances_v483 bb
  where bb.tenant_id=p_tenant_id and bb.batch_id=p_batch_id
    and private.erp_document_scope_allowed(p_tenant_id,bb.location_id,null,'view')
  union all
  select 1 from public.inventory_trace_events_v483 e
  where e.tenant_id=p_tenant_id and e.batch_id=p_batch_id
    and private.erp_document_scope_allowed(p_tenant_id,e.location_id,null,'view')
 ) then raise exception 'Batch not found or location access denied';end if;
 select jsonb_build_object(
  'batch',jsonb_build_object(
    'batch_id',b.id,'batch_number',b.batch_number,'variant_id',b.variant_id,'product_name',p.name,'variant_name',pv.name,
    'sku',pv.sku,'manufactured_on',b.manufactured_on,'expiry_on',b.expiry_on,'status',b.status,'supplier_name',sup.name
  ),
  'balances',coalesce((
    select jsonb_agg(jsonb_build_object('location_id',bb.location_id,'location_name',l.name,'quantity',bb.quantity) order by l.name)
    from public.inventory_batch_balances_v483 bb
    left join public.business_locations l on l.id=bb.location_id
    where bb.tenant_id=p_tenant_id and bb.batch_id=b.id
      and private.erp_document_scope_allowed(p_tenant_id,bb.location_id,null,'view')
  ),'[]'::jsonb),
  'events',coalesce((
    select jsonb_agg(jsonb_build_object(
      'event_id',e.id,'event_type',e.event_type,'quantity',e.quantity,'location_name',l2.name,
      'supplier_name',s.name,'customer_name',c.name,'purchase_number',pur.purchase_number,'sale_number',sa.sale_number,
      'reference_number',e.reference_number,'metadata',e.metadata,'created_at',e.created_at
    ) order by e.created_at desc)
    from public.inventory_trace_events_v483 e
    left join public.business_locations l2 on l2.id=e.location_id
    left join public.suppliers s on s.id=e.supplier_id
    left join public.customers c on c.id=e.customer_id
    left join public.purchases pur on pur.id=e.purchase_id
    left join public.sales sa on sa.id=e.sale_id
    where e.tenant_id=p_tenant_id and e.batch_id=b.id
      and private.erp_document_scope_allowed(p_tenant_id,e.location_id,null,'view')
  ),'[]'::jsonb)
 ) into v
 from public.inventory_batches_v483 b
 join public.product_variants pv on pv.id=b.variant_id and pv.tenant_id=b.tenant_id
 join public.products p on p.id=pv.product_id
 left join public.suppliers sup on sup.id=b.supplier_id
 where b.tenant_id=p_tenant_id and b.id=p_batch_id;
 if v is null then raise exception 'Batch not found';end if;
 return v;
end$$;


--
-- Name: inventory_batch_search_v483(uuid, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_batch_search_v483(p_tenant_id uuid, p_query text DEFAULT ''::text, p_location_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 200) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare q text:='%'||lower(trim(coalesce(p_query,'')))||'%';begin
 if not private.erp_user_has_tenant_access(p_tenant_id) or not private.v483_trace_view_allowed(p_tenant_id) then raise exception 'Traceability view permission required';end if;
 return query
 select jsonb_build_object(
  'batch_id',b.id,'batch_number',b.batch_number,'status',b.status,'variant_id',b.variant_id,
  'product_name',p.name,'variant_name',pv.name,'sku',pv.sku,
  'manufactured_on',b.manufactured_on,'expiry_on',b.expiry_on,
  'expired',b.expiry_on is not null and b.expiry_on<current_date,
  'supplier_id',b.supplier_id,'supplier_name',sup.name,'purchase_id',b.first_purchase_id,'purchase_number',pur.purchase_number,
  'quantity',coalesce(sum(bb.quantity),0),
  'locations',coalesce(
    jsonb_agg(distinct jsonb_build_object('location_id',bb.location_id,'location_name',l.name,'quantity',bb.quantity))
      filter(where bb.location_id is not null),
    '[]'::jsonb
  )
 )
 from public.inventory_batches_v483 b
 join public.product_variants pv on pv.id=b.variant_id and pv.tenant_id=b.tenant_id
 join public.products p on p.id=pv.product_id
 left join public.inventory_batch_balances_v483 bb
   on bb.tenant_id=b.tenant_id and bb.batch_id=b.id
  and private.erp_document_scope_allowed(p_tenant_id,bb.location_id,p_location_id,'view')
 left join public.business_locations l on l.id=bb.location_id
 left join public.suppliers sup on sup.id=b.supplier_id
 left join public.purchases pur on pur.id=b.first_purchase_id
 where b.tenant_id=p_tenant_id
 and (
   exists(
    select 1 from public.inventory_batch_balances_v483 ab
    where ab.tenant_id=b.tenant_id and ab.batch_id=b.id
      and private.erp_document_scope_allowed(p_tenant_id,ab.location_id,p_location_id,'view')
   )
   or exists(
    select 1 from public.inventory_trace_events_v483 ae
    where ae.tenant_id=b.tenant_id and ae.batch_id=b.id
      and private.erp_document_scope_allowed(p_tenant_id,ae.location_id,p_location_id,'view')
   )
 )
 and (
  trim(coalesce(p_query,''))='' or lower(b.batch_number) like q or lower(coalesce(p.name,'')) like q or
  lower(coalesce(pv.sku,'')) like q or lower(coalesce(sup.name,'')) like q or exists(
   select 1
   from public.inventory_trace_events_v483 e
   left join public.customers c on c.id=e.customer_id
   left join public.sales s on s.id=e.sale_id
   left join public.purchases pp on pp.id=e.purchase_id
   where e.tenant_id=b.tenant_id and e.batch_id=b.id
     and private.erp_document_scope_allowed(p_tenant_id,e.location_id,p_location_id,'view')
     and (
       lower(coalesce(c.name,'')) like q or lower(coalesce(s.sale_number,'')) like q or
       lower(coalesce(pp.purchase_number,'')) like q or lower(coalesce(e.reference_number,'')) like q
     )
  )
 )
 group by b.id,p.name,pv.name,pv.sku,sup.name,pur.purchase_number
 order by b.updated_at desc
 limit greatest(1,least(coalesce(p_limit,200),1000));
end$$;


--
-- Name: inventory_branch_low_stock_v4(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_branch_low_stock_v4(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50) RETURNS TABLE(location_id uuid, location_code text, variant_id uuid, product_name text, sku text, quantity numeric, reorder_level numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;return query select l.id,l.location_code,pv.id,p.name,pv.sku,coalesce(b.quantity,0),coalesce(s.reorder_level,pv.reorder_level,0) from public.location_product_settings s join public.business_locations l on l.id=s.location_id join public.product_variants pv on pv.id=s.variant_id join public.products p on p.id=pv.product_id left join public.location_stock_balances b on b.tenant_id=s.tenant_id and b.location_id=s.location_id and b.variant_id=s.variant_id where s.tenant_id=p_tenant_id and s.active and l.active and (p_location_id is null or l.id=p_location_id) and private.erp_document_scope_allowed(p_tenant_id,l.id,p_location_id,'view') and coalesce(s.reorder_level,pv.reorder_level,0)>0 and coalesce(b.quantity,0)<=coalesce(s.reorder_level,pv.reorder_level,0) order by (coalesce(b.quantity,0)-coalesce(s.reorder_level,pv.reorder_level,0)),p.name limit greatest(1,least(coalesce(p_limit,50),500));end $$;


--
-- Name: inventory_bulk_create_products(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_bulk_create_products(p_tenant_id uuid, p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare r jsonb; ok int:=0; failed int:=0; errs jsonb:='[]'::jsonb; idx int:=0; begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  if not private.erp_has_permission(p_tenant_id,'bulk_import.use') and not private.erp_has_permission(p_tenant_id,'inventory.manage') then raise exception 'Permission denied'; end if;
  if jsonb_typeof(p_rows)<>'array' then raise exception 'Rows must be an array'; end if;
  for r in select * from jsonb_array_elements(p_rows) loop
    idx:=idx+1;
    begin
      perform public.inventory_create_product(
        p_tenant_id,
        coalesce(r->>'name',''),coalesce(r->>'sku',''),coalesce(nullif(r->>'item_type',''),'stock'),coalesce(r->>'description',''),coalesce(r->>'category',''),coalesce(r->>'brand',''),coalesce(r->>'barcode',''),coalesce(r->>'part_number',''),
        coalesce(nullif(r->>'cost_price','')::numeric,0),coalesce(nullif(r->>'selling_price','')::numeric,0),nullif(r->>'list_price','')::numeric,coalesce(nullif(r->>'tax_rate','')::numeric,0),coalesce(nullif(r->>'reorder_level','')::numeric,0),coalesce(nullif(r->>'opening_stock','')::numeric,0)
      ); ok:=ok+1;
    exception when others then failed:=failed+1; errs:=errs||jsonb_build_array(jsonb_build_object('row',idx,'sku',r->>'sku','error',sqlerrm)); end;
  end loop;
  perform private.business_audit_write(p_tenant_id,'bulk_import','product',null,null,null,jsonb_build_object('success',ok,'failed',failed));
  return jsonb_build_object('success_count',ok,'failed_count',failed,'errors',errs);
end $$;


--
-- Name: inventory_bulk_create_products_v45(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_bulk_create_products_v45(p_tenant_id uuid, p_location_id uuid, p_device_id uuid, p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  x jsonb;
  v_success int := 0;
  v_failed int := 0;
  v_errors jsonb := '[]'::jsonb;
  v_created jsonb := '[]'::jsonb;
  v_result jsonb;
  v_row int := 1;
  v_variant uuid;
begin

  perform private.v4_location_access(
    p_tenant_id,
    p_location_id,
    'operate'
  );

  if not private.erp_user_is_owner(p_tenant_id)
     and not private.erp_has_permission(
       p_tenant_id,
       'inventory.manage'
     ) then
    raise exception 'Inventory manage permission required';
  end if;

  for x in
    select value
    from jsonb_array_elements(
      coalesce(p_rows,'[]'::jsonb)
    )
  loop

    v_row := v_row + 1;

    begin

      if trim(coalesce(x->>'name','')) = '' then
        raise exception 'Product name is required';
      end if;

      v_result :=
        public.inventory_create_product_v4(
          p_tenant_id,
          p_location_id,
          p_device_id,
          x->>'name',
          nullif(trim(coalesce(x->>'sku','')),''),
          coalesce(
            nullif(trim(coalesce(x->>'item_type','')),''),
            'stock'
          ),
          x->>'description',
          nullif(trim(coalesce(x->>'category','')),''),
          nullif(trim(coalesce(x->>'brand','')),''),
          nullif(trim(coalesce(x->>'barcode','')),''),
          nullif(trim(coalesce(x->>'part_number','')),''),
          coalesce(nullif(x->>'cost_price','')::numeric,0),
          coalesce(nullif(x->>'selling_price','')::numeric,0),
          coalesce(nullif(x->>'list_price','')::numeric,0),
          coalesce(nullif(x->>'tax_rate','')::numeric,0),
          coalesce(nullif(x->>'reorder_level','')::numeric,0),
          coalesce(nullif(x->>'opening_stock','')::numeric,0)
        );

      v_variant :=
        nullif(v_result->>'variant_id','')::uuid;

      if v_variant is not null then

        insert into public.product_invoice_attributes_v45(
          tenant_id,
          variant_id,
          unit_code,
          hsn_sac,
          preferred_supplier_name,
          metadata,
          updated_at,
          updated_by
        )
        values(
          p_tenant_id,
          v_variant,
          nullif(trim(coalesce(x->>'unit','')),''),
          nullif(trim(coalesce(x->>'hsn_sac','')),''),
          nullif(trim(coalesce(x->>'supplier','')),''),
          jsonb_build_object(
            'source','bulk_import_v45',
            'store_code',
            nullif(trim(coalesce(x->>'store_code','')),'')
          ),
          now(),
          auth.uid()
        )
        on conflict(tenant_id,variant_id)
        do update set
          unit_code = excluded.unit_code,
          hsn_sac = excluded.hsn_sac,
          preferred_supplier_name =
            excluded.preferred_supplier_name,
          metadata =
            public.product_invoice_attributes_v45.metadata
            || excluded.metadata,
          updated_at = now(),
          updated_by = auth.uid();

      end if;

      v_success := v_success + 1;

      v_created :=
        v_created ||
        jsonb_build_array(
          jsonb_build_object(
            'row',v_row,
            'name',x->>'name',
            'sku',v_result->>'sku',
            'variant_id',v_result->>'variant_id',
            'hsn_sac',x->>'hsn_sac',
            'unit',x->>'unit'
          )
        );

    exception
      when others then

        v_failed := v_failed + 1;

        v_errors :=
          v_errors ||
          jsonb_build_array(
            jsonb_build_object(
              'row',v_row,
              'name',coalesce(x->>'name',''),
              'error',sqlerrm
            )
          );

    end;

  end loop;


  -- FIX:
  -- argument 6 must be JSONB, not p_location_id UUID.
  perform private.business_audit_write(
    p_tenant_id,
    'inventory.bulk_import',
    'inventory',
    null,
    null,
    null::jsonb,
    jsonb_build_object(
      'success_count',v_success,
      'failed_count',v_failed,
      'location_id',p_location_id,
      'device_id',p_device_id,
      'format','xlsx'
    )
  );

  return jsonb_build_object(
    'success_count',v_success,
    'failed_count',v_failed,
    'errors',v_errors,
    'created',v_created,
    'location_id',p_location_id
  );

end $$;


--
-- Name: inventory_create_product(uuid, text, text, text, text, text, text, text, text, numeric, numeric, numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_create_product(p_tenant_id uuid, p_name text, p_sku text, p_item_type text, p_description text, p_category_name text, p_brand_name text, p_barcode text, p_part_number text, p_cost_price numeric, p_selling_price numeric, p_list_price numeric, p_tax_rate numeric, p_reorder_level numeric, p_opening_stock numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$declare v_product uuid;v_variant uuid;v_cat uuid;v_brand uuid;v_unit uuid;v_loc uuid;v_open numeric:=coalesce(p_opening_stock,0);v_lines jsonb;begin
 if not private.has_permission(p_tenant_id,'inventory.manage') then raise exception 'Access denied' using errcode='42501';end if;if nullif(trim(coalesce(p_name,'')),'') is null or nullif(trim(coalesce(p_sku,'')),'') is null then raise exception 'Product name and SKU are required';end if;if p_item_type not in('stock','non_stock','service') then raise exception 'Invalid item type';end if;if coalesce(p_cost_price,0)<0 or coalesce(p_selling_price,0)<0 or coalesce(p_tax_rate,0)<0 or coalesce(p_tax_rate,0)>100 or coalesce(p_reorder_level,0)<0 or v_open<0 then raise exception 'Invalid product numeric values';end if;if p_item_type<>'stock' and v_open<>0 then raise exception 'Opening stock is only allowed for stock items';end if;if exists(select 1 from public.product_variants pv where pv.tenant_id=p_tenant_id and lower(pv.sku)=lower(trim(p_sku))) then raise exception 'A product with this SKU already exists';end if;
 select id into v_unit from public.inventory_units where tenant_id=p_tenant_id and code='PCS' and is_active limit 1;if v_unit is null then raise exception 'Default inventory unit PCS does not exist';end if;select id into v_loc from public.inventory_locations where tenant_id=p_tenant_id and is_active order by is_default desc,created_at limit 1;if v_loc is null then raise exception 'No active inventory location exists';end if;
 if nullif(trim(coalesce(p_category_name,'')),'') is not null then select id into v_cat from public.product_categories where tenant_id=p_tenant_id and lower(name)=lower(trim(p_category_name)) limit 1;if v_cat is null then insert into public.product_categories(tenant_id,name,is_active) values(p_tenant_id,trim(p_category_name),true) returning id into v_cat;end if;end if;
 if nullif(trim(coalesce(p_brand_name,'')),'') is not null then select id into v_brand from public.product_brands where tenant_id=p_tenant_id and lower(name)=lower(trim(p_brand_name)) limit 1;if v_brand is null then insert into public.product_brands(tenant_id,name,is_active) values(p_tenant_id,trim(p_brand_name),true) returning id into v_brand;end if;end if;
 insert into public.products(tenant_id,name,description,item_type,category_id,brand_id,base_unit_id,tax_rate,status,created_by) values(p_tenant_id,trim(p_name),nullif(trim(coalesce(p_description,'')),''),p_item_type,v_cat,v_brand,v_unit,coalesce(p_tax_rate,0),'active',auth.uid()) returning id into v_product;
 insert into public.product_variants(tenant_id,product_id,name,sku,barcode,part_number,cost_price,selling_price,list_price,reorder_level,is_default,status) values(p_tenant_id,v_product,'Default',trim(p_sku),nullif(trim(coalesce(p_barcode,'')),''),nullif(trim(coalesce(p_part_number,'')),''),coalesce(p_cost_price,0),coalesce(p_selling_price,0),p_list_price,coalesce(p_reorder_level,0),true,'active') returning id into v_variant;
 if p_item_type='stock' and v_open>0 then insert into public.stock_movements(tenant_id,variant_id,location_id,movement_type,quantity_delta,unit_cost,reference_type,reference_id,reference_number,note,created_by) values(p_tenant_id,v_variant,v_loc,'opening',v_open,coalesce(p_cost_price,0),'product',v_variant,trim(p_sku),'Opening stock',auth.uid());insert into public.stock_balances(tenant_id,location_id,variant_id,quantity,updated_at) values(p_tenant_id,v_loc,v_variant,v_open,now()) on conflict(tenant_id,location_id,variant_id) do update set quantity=public.stock_balances.quantity+excluded.quantity,updated_at=now();
   if coalesce(p_cost_price,0)>0 then v_lines:=jsonb_build_array(jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'inventory_asset'),'debit',round(v_open*p_cost_price,2),'credit',0,'description','Opening inventory • '||trim(p_name)),jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'owner_equity'),'debit',0,'credit',round(v_open*p_cost_price,2),'description','Opening inventory equity'));perform private.v4_journal_create(p_tenant_id,null,current_date,'Opening inventory • '||trim(p_name),'product_opening_stock',v_variant,trim(p_sku),v_lines);end if;
 end if;return jsonb_build_object('success',true,'product_id',v_product,'variant_id',v_variant,'sku',trim(p_sku),'opening_stock',v_open);
end$$;


--
-- Name: inventory_create_product_v4(uuid, uuid, uuid, text, text, text, text, text, text, text, text, numeric, numeric, numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_create_product_v4(p_tenant_id uuid, p_location_id uuid, p_device_id uuid, p_name text, p_sku text, p_item_type text, p_description text, p_category_name text, p_brand_name text, p_barcode text, p_part_number text, p_cost_price numeric, p_selling_price numeric, p_list_price numeric, p_tax_rate numeric, p_reorder_level numeric, p_opening_stock numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_result jsonb;v_variant uuid;v_sku text;begin
  perform private.v4_location_access(p_tenant_id,p_location_id,'operate');
  if not private.erp_has_permission(p_tenant_id,'inventory.manage') and not private.erp_user_is_owner(p_tenant_id) then raise exception 'Inventory manage permission required';end if;
  v_sku:=nullif(trim(coalesce(p_sku,'')),'');
  if v_sku is null then select public.inventory_next_sku(p_tenant_id) into v_sku; end if;
  select public.inventory_create_product(p_tenant_id,p_name,v_sku,p_item_type,p_description,p_category_name,p_brand_name,p_barcode,p_part_number,p_cost_price,p_selling_price,p_list_price,p_tax_rate,p_reorder_level,p_opening_stock) into v_result;
  begin v_variant:=coalesce(nullif(v_result->>'variant_id',''),nullif(v_result->>'id',''))::uuid; exception when others then v_variant:=null; end;
  if v_variant is null then select id into v_variant from public.product_variants where tenant_id=p_tenant_id and lower(sku)=lower(v_sku) order by created_at desc limit 1; end if;
  if v_variant is null then raise exception 'Could not resolve created product variant'; end if;
  perform public.inventory_location_assign_v4(p_tenant_id,p_location_id,v_variant,true,p_selling_price,p_reorder_level,null);
  if coalesce(p_opening_stock,0)<>0 then
    perform private.v4_location_stock_apply(p_tenant_id,p_location_id,v_variant,p_opening_stock,'opening','product',v_variant,null,'Opening stock',p_device_id,false);
  end if;
  return coalesce(v_result,'{}'::jsonb)||jsonb_build_object('variant_id',v_variant,'sku',v_sku,'location_id',p_location_id);
end $$;


--
-- Name: inventory_create_product_v481(uuid, uuid, uuid, text, text, text, text, text, text, text, text, numeric, numeric, numeric, numeric, numeric, numeric, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_create_product_v481(p_tenant_id uuid, p_location_id uuid, p_device_id uuid, p_name text, p_sku text, p_item_type text, p_description text, p_category_name text, p_brand_name text, p_barcode text, p_part_number text, p_cost_price numeric, p_selling_price numeric, p_list_price numeric, p_tax_rate numeric, p_reorder_level numeric, p_opening_stock numeric, p_base_unit_code text DEFAULT 'PCS'::text, p_units jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v jsonb;v_variant uuid;v_base_unit uuid;v_base_code text;begin
  v:=public.inventory_create_product_v4(p_tenant_id,p_location_id,p_device_id,p_name,p_sku,p_item_type,p_description,p_category_name,p_brand_name,p_barcode,p_part_number,p_cost_price,p_selling_price,p_list_price,p_tax_rate,p_reorder_level,p_opening_stock);
  v_variant:=nullif(v->>'variant_id','')::uuid;
  perform public.inventory_product_units_save_v481(p_tenant_id,v_variant,coalesce(nullif(trim(p_base_unit_code),''),case when p_item_type='service' then 'HR' else 'PCS' end),coalesce(p_units,'[]'::jsonb));
  select pu.unit_id,u.code into v_base_unit,v_base_code from public.product_units_v481 pu join public.inventory_units_v481 u on u.id=pu.unit_id where pu.tenant_id=p_tenant_id and pu.variant_id=v_variant and pu.is_base and pu.active limit 1;
  update public.location_stock_movements m set unit_id=v_base_unit,unit_code=v_base_code,conversion_to_base=1,display_quantity=m.base_quantity_delta
  where m.tenant_id=p_tenant_id and m.variant_id=v_variant and m.reference_type='product' and m.reference_id=v_variant and m.movement_type='opening' and m.unit_id is null;
  return v||jsonb_build_object('base_unit_code',upper(coalesce(nullif(trim(p_base_unit_code),''),case when p_item_type='service' then 'HR' else 'PCS' end)));
end $$;


--
-- Name: inventory_get_product_detail(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_get_product_detail(p_tenant_id uuid, p_variant_id uuid) RETURNS TABLE(product_id uuid, variant_id uuid, product_name text, description text, item_type text, category_name text, brand_name text, unit_name text, unit_code text, sku text, barcode text, part_number text, cost_price numeric, selling_price numeric, list_price numeric, tax_rate numeric, reorder_level numeric, stock_quantity numeric, product_status text, variant_status text, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin

  if not (
    private.has_permission(
      p_tenant_id,
      'inventory.view'
    )
    or
    private.has_permission(
      p_tenant_id,
      'inventory.manage'
    )
  ) then

    raise exception 'Access denied'
      using errcode = '42501';

  end if;


  return query

  select
    p.id,
    pv.id,

    p.name,
    p.description,
    p.item_type,

    pc.name,
    pb.name,

    iu.name,
    iu.code,

    pv.sku,
    pv.barcode,
    pv.part_number,

    pv.cost_price,
    pv.selling_price,
    pv.list_price,

    p.tax_rate,
    pv.reorder_level,

    coalesce(
      sum(sb.quantity),
      0
    )::numeric,

    p.status,
    pv.status,

    p.created_at,

    greatest(
      p.updated_at,
      pv.updated_at
    )

  from public.products p

  join public.product_variants pv
    on pv.product_id = p.id
   and pv.tenant_id = p.tenant_id

  left join public.product_categories pc
    on pc.id = p.category_id
   and pc.tenant_id = p.tenant_id

  left join public.product_brands pb
    on pb.id = p.brand_id
   and pb.tenant_id = p.tenant_id

  left join public.inventory_units iu
    on iu.id = p.base_unit_id
   and iu.tenant_id = p.tenant_id

  left join public.stock_balances sb
    on sb.variant_id = pv.id
   and sb.tenant_id = p.tenant_id

  where p.tenant_id = p_tenant_id
    and pv.id = p_variant_id

  group by
    p.id,
    pv.id,
    pc.name,
    pb.name,
    iu.name,
    iu.code;

end;
$$;


--
-- Name: inventory_intelligence_v480(uuid, uuid, integer, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_intelligence_v480(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_days integer DEFAULT 30, p_query text DEFAULT ''::text, p_limit integer DEFAULT 1000) RETURNS TABLE(location_id uuid, location_code text, location_name text, variant_id uuid, product_name text, sku text, quantity numeric, available numeric, reorder_level numeric, max_stock numeric, average_cost numeric, stock_value numeric, net_sold_qty numeric, avg_daily_sales numeric, days_cover numeric, suggested_reorder numeric, last_sale_date date, last_purchase_date date, status text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_days integer:=greatest(1,least(coalesce(p_days,30),365));
  v_from date:=current_date-(greatest(1,least(coalesce(p_days,30),365))-1);
  q text:='%'||lower(trim(coalesce(p_query,'')))||'%';
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if p_location_id is not null and not private.erp_document_scope_allowed(p_tenant_id,p_location_id,p_location_id,'view') then raise exception 'Location access denied';end if;

  return query
  with sold as (
    select o.location_id,si.variant_id,
      sum(greatest(si.quantity-coalesce((
        select sum(ri.quantity)
        from public.sales_return_items ri
        join public.sales_returns r on r.id=ri.sales_return_id
        where ri.sale_item_id=si.id and r.refund_status<>'waived' and r.return_date<=current_date
      ),0),0))::numeric qty
    from public.sale_items si join public.sales s on s.id=si.sale_id
    join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='sale' and o.entity_id=s.id
    where s.tenant_id=p_tenant_id and s.sale_date between v_from and current_date
      and coalesce(s.status,'') not in('void','cancelled')
      and (p_location_id is null or o.location_id=p_location_id)
      and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view')
    group by o.location_id,si.variant_id
  ), last_sold as (
    select o.location_id,si.variant_id,max(s.sale_date) last_sale
    from public.sale_items si join public.sales s on s.id=si.sale_id
    join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='sale' and o.entity_id=s.id
    where s.tenant_id=p_tenant_id and coalesce(s.status,'') not in('void','cancelled')
      and (p_location_id is null or o.location_id=p_location_id)
      and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view')
    group by o.location_id,si.variant_id
  ), purchased as (
    select o.location_id,pi.variant_id,max(p.purchase_date) last_purchase
    from public.purchase_items pi join public.purchases p on p.id=pi.purchase_id
    join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='purchase' and o.entity_id=p.id
    where p.tenant_id=p_tenant_id and coalesce(p.status,'') not in('void','cancelled')
      and (p_location_id is null or o.location_id=p_location_id)
      and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view')
    group by o.location_id,pi.variant_id
  ), base as (
    select l.id location_id,l.location_code,l.name location_name,pv.id variant_id,p.name product_name,pv.sku,
      coalesce(b.quantity,0)::numeric quantity,
      (coalesce(b.quantity,0)-coalesce(b.reserved_quantity,0)-coalesce(b.damaged_quantity,0)-coalesce(b.quarantine_quantity,0))::numeric available,
      coalesce(s.reorder_level,pv.reorder_level,0)::numeric reorder_level,coalesce(s.max_stock,0)::numeric max_stock,
      coalesce(b.average_cost,pv.cost_price,0)::numeric average_cost,
      coalesce(so.qty,0)::numeric net_sold_qty,
      ls.last_sale,pu.last_purchase
    from public.location_product_settings s
    join public.business_locations l on l.id=s.location_id and l.tenant_id=s.tenant_id and l.active
    join public.product_variants pv on pv.id=s.variant_id and pv.tenant_id=s.tenant_id
    join public.products p on p.id=pv.product_id and p.tenant_id=s.tenant_id
    left join public.location_stock_balances b on b.tenant_id=s.tenant_id and b.location_id=s.location_id and b.variant_id=s.variant_id
    left join sold so on so.location_id=s.location_id and so.variant_id=s.variant_id
    left join last_sold ls on ls.location_id=s.location_id and ls.variant_id=s.variant_id
    left join purchased pu on pu.location_id=s.location_id and pu.variant_id=s.variant_id
    where s.tenant_id=p_tenant_id and s.active
      and (p_location_id is null or s.location_id=p_location_id)
      and private.erp_document_scope_allowed(p_tenant_id,s.location_id,p_location_id,'view')
      and (trim(coalesce(p_query,''))='' or lower(p.name) like q or lower(coalesce(pv.sku,'')) like q or lower(coalesce(pv.barcode,'')) like q or lower(coalesce(pv.part_number,'')) like q)
  )
  select b.location_id,b.location_code,b.location_name,b.variant_id,b.product_name,b.sku,b.quantity,b.available,b.reorder_level,b.max_stock,b.average_cost,
    round(b.quantity*b.average_cost,2)::numeric,
    b.net_sold_qty,round(b.net_sold_qty/v_days,4)::numeric,
    case when b.net_sold_qty<=0 then null else round(b.available/(b.net_sold_qty/v_days),1) end::numeric,
    greatest(
      case
        when b.max_stock>0 and b.available<=b.reorder_level then b.max_stock-b.available
        when b.reorder_level>0 and b.available<=b.reorder_level then greatest(b.reorder_level*2-b.available,0)
        else 0
      end,0
    )::numeric,
    b.last_sale,b.last_purchase,
    (case
      when b.available<=0 then 'out_of_stock'
      when b.reorder_level>0 and b.available<=b.reorder_level then 'low_stock'
      when b.max_stock>0 and b.available>b.max_stock then 'overstock'
      when b.net_sold_qty=0 and b.available>0 and coalesce(b.last_sale,date '1900-01-01')<current_date-interval '90 days' then 'dead_stock'
      else 'healthy' end)::text
  from base b
  order by
    case when b.available<=0 then 0 when b.reorder_level>0 and b.available<=b.reorder_level then 1 when b.net_sold_qty=0 and b.available>0 then 2 else 3 end,
    b.product_name,b.location_name
  limit greatest(1,least(coalesce(p_limit,1000),5000));
end $$;


--
-- Name: inventory_list_products(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_list_products(p_tenant_id uuid) RETURNS TABLE(product_id uuid, variant_id uuid, product_name text, variant_name text, item_type text, category_name text, brand_name text, unit_name text, unit_code text, sku text, barcode text, part_number text, cost_price numeric, selling_price numeric, list_price numeric, tax_rate numeric, reorder_level numeric, stock_quantity numeric, product_status text, variant_status text, updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin

  -- ----------------------------------------------------------
  -- PERMISSION
  -- ----------------------------------------------------------

  if not (
    private.has_permission(
      p_tenant_id,
      'inventory.view'
    )
    or
    private.has_permission(
      p_tenant_id,
      'inventory.manage'
    )
  ) then

    raise exception 'Access denied'
      using errcode = '42501';

  end if;


  return query

  select
    p.id,
    pv.id,

    p.name,
    pv.name,

    p.item_type,

    pc.name,
    pb.name,

    iu.name,
    iu.code,

    pv.sku,
    pv.barcode,
    pv.part_number,

    pv.cost_price,
    pv.selling_price,
    pv.list_price,

    p.tax_rate,
    pv.reorder_level,

    coalesce(
      sum(sb.quantity),
      0
    )::numeric,

    p.status,
    pv.status,

    greatest(
      p.updated_at,
      pv.updated_at
    )

  from public.products p

  join public.product_variants pv
    on pv.product_id = p.id
   and pv.tenant_id = p.tenant_id

  left join public.product_categories pc
    on pc.id = p.category_id
   and pc.tenant_id = p.tenant_id

  left join public.product_brands pb
    on pb.id = p.brand_id
   and pb.tenant_id = p.tenant_id

  left join public.inventory_units iu
    on iu.id = p.base_unit_id
   and iu.tenant_id = p.tenant_id

  left join public.stock_balances sb
    on sb.variant_id = pv.id
   and sb.tenant_id = p.tenant_id

  where p.tenant_id = p_tenant_id

  group by
    p.id,
    pv.id,
    pc.name,
    pb.name,
    iu.name,
    iu.code

  order by
    p.name,
    pv.name;

end;
$$;


--
-- Name: inventory_list_products_v4(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_list_products_v4(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare r jsonb;v_variant uuid;v_qty numeric;v_price numeric;v_reorder numeric;v_assigned boolean;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  if p_location_id is not null then perform private.v4_location_access(p_tenant_id,p_location_id,'view'); end if;
  for r in select to_jsonb(x) from public.inventory_list_products(p_tenant_id) x loop
    begin v_variant:=coalesce(nullif(r->>'variant_id',''),nullif(r->>'id',''))::uuid; exception when others then v_variant:=null; end;
    if v_variant is null then continue; end if;
    if p_location_id is null then
      select coalesce(sum(b.quantity),0),coalesce(max(s.selling_price),null),coalesce(max(s.reorder_level),null),bool_or(coalesce(s.active,false))
      into v_qty,v_price,v_reorder,v_assigned
      from public.location_stock_balances b
      left join public.location_product_settings s on s.tenant_id=b.tenant_id and s.location_id=b.location_id and s.variant_id=b.variant_id
      where b.tenant_id=p_tenant_id and b.variant_id=v_variant;
      -- Owner/all-store view keeps historical products visible even before explicit assignment.
      v_assigned:=coalesce(v_assigned,true);
    else
      select coalesce(b.quantity,0),s.selling_price,s.reorder_level,coalesce(s.active,false)
      into v_qty,v_price,v_reorder,v_assigned
      from public.location_product_settings s
      left join public.location_stock_balances b on b.tenant_id=s.tenant_id and b.location_id=s.location_id and b.variant_id=s.variant_id
      where s.tenant_id=p_tenant_id and s.location_id=p_location_id and s.variant_id=v_variant;
      if not coalesce(v_assigned,false) then continue; end if;
    end if;
    return next r || jsonb_build_object(
      'stock_quantity',coalesce(v_qty,0),
      'selling_price',coalesce(v_price,(r->>'selling_price')::numeric),
      'reorder_level',coalesce(v_reorder,(r->>'reorder_level')::numeric),
      'location_id',p_location_id,
      'location_assigned',coalesce(v_assigned,false),
      'stock_scope',case when p_location_id is null then 'merged' else 'location' end
    );
  end loop;
  return;
end $$;


--
-- Name: inventory_list_products_v481(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_list_products_v481(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare r jsonb;v_variant uuid;v_units jsonb;v_purchase_units jsonb;v_base jsonb;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  for r in select * from public.inventory_list_products_v4(p_tenant_id,p_location_id) loop
    begin v_variant:=nullif(r->>'variant_id','')::uuid; exception when others then v_variant:=null;end;
    if v_variant is null then return next r;continue;end if;
    select to_jsonb(x) into v_base from (select u.id unit_id,u.code,u.name,u.decimal_places,u.allow_fractional,pu.quantity_step,pu.cutting_allowed,pu.cutting_charge from public.product_units_v481 pu join public.inventory_units_v481 u on u.id=pu.unit_id where pu.tenant_id=p_tenant_id and pu.variant_id=v_variant and pu.is_base and pu.active limit 1) x;
    select coalesce(jsonb_agg(jsonb_build_object('unit_id',u.id,'code',u.code,'name',u.name,'decimal_places',u.decimal_places,'allow_fractional',u.allow_fractional,'conversion_to_base',pu.conversion_to_base,'quantity_step',pu.quantity_step,'sale_price',pu.sale_price,'purchase_cost',pu.purchase_cost,'cutting_allowed',pu.cutting_allowed,'cutting_charge',pu.cutting_charge,'is_default_sale',pu.is_default_sale,'is_default_purchase',pu.is_default_purchase,'allow_sale',pu.allow_sale,'allow_purchase',pu.allow_purchase,'is_base',pu.is_base,'active',pu.active) order by pu.is_default_sale desc,pu.is_base desc,u.name),'[]'::jsonb) into v_units
    from public.product_units_v481 pu join public.inventory_units_v481 u on u.id=pu.unit_id where pu.tenant_id=p_tenant_id and pu.variant_id=v_variant and pu.active and pu.allow_sale;
    select coalesce(jsonb_agg(jsonb_build_object('unit_id',u.id,'code',u.code,'name',u.name,'decimal_places',u.decimal_places,'allow_fractional',u.allow_fractional,'conversion_to_base',pu.conversion_to_base,'quantity_step',pu.quantity_step,'sale_price',pu.sale_price,'purchase_cost',pu.purchase_cost,'cutting_allowed',pu.cutting_allowed,'cutting_charge',pu.cutting_charge,'is_default_sale',pu.is_default_sale,'is_default_purchase',pu.is_default_purchase,'allow_sale',pu.allow_sale,'allow_purchase',pu.allow_purchase,'is_base',pu.is_base,'active',pu.active) order by pu.is_default_purchase desc,pu.is_base desc,u.name),'[]'::jsonb) into v_purchase_units
    from public.product_units_v481 pu join public.inventory_units_v481 u on u.id=pu.unit_id where pu.tenant_id=p_tenant_id and pu.variant_id=v_variant and pu.active and pu.allow_purchase;
    return next r||jsonb_build_object('base_unit',coalesce(v_base,'{}'::jsonb),'sale_units',coalesce(v_units,'[]'::jsonb),'purchase_units',coalesce(v_purchase_units,'[]'::jsonb),'base_unit_code',coalesce(v_base->>'code',r->>'unit_code','PCS'),'unit_code',coalesce(v_base->>'code',r->>'unit_code','PCS'));
  end loop;return;
end $$;


--
-- Name: inventory_list_products_v482(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_list_products_v482(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare r jsonb;v_variant uuid;v_ids jsonb;v_codes text;begin
 if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
 for r in select * from public.inventory_list_products_v481(p_tenant_id,p_location_id) loop
  begin v_variant:=(r->>'variant_id')::uuid;exception when others then v_variant:=null;end;
  if v_variant is not null then
   select coalesce(jsonb_agg(jsonb_build_object('identifier_id',i.id,'type',i.identifier_type,'code',i.code,'label',i.label,'is_primary',i.is_primary,'supplier_id',i.supplier_id) order by i.is_primary desc,i.identifier_type,i.code),'[]'::jsonb),string_agg(i.code,' ' order by i.code)
   into v_ids,v_codes from public.product_identifiers_v482 i where i.tenant_id=p_tenant_id and i.variant_id=v_variant and i.active;
  else v_ids:='[]'::jsonb;v_codes:='';end if;
  return next r||jsonb_build_object('identifiers',coalesce(v_ids,'[]'::jsonb),'search_codes',coalesce(v_codes,''));
 end loop;return;
end$$;


--
-- Name: inventory_list_products_v483(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_list_products_v483(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare r jsonb;v_variant uuid;v_mode text;v_serial numeric;v_batch numeric;begin
 if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
 for r in select * from public.inventory_list_products_v482(p_tenant_id,p_location_id) loop
  v_variant:=(r->>'variant_id')::uuid;v_mode:=private.v483_tracking_mode(p_tenant_id,v_variant);
  select count(*)::numeric into v_serial from public.inventory_serials_v483 s where s.tenant_id=p_tenant_id and s.variant_id=v_variant and s.status='in_stock' and (p_location_id is null or s.current_location_id=p_location_id);
  select coalesce(sum(bb.quantity),0) into v_batch from public.inventory_batches_v483 b join public.inventory_batch_balances_v483 bb on bb.tenant_id=b.tenant_id and bb.batch_id=b.id where b.tenant_id=p_tenant_id and b.variant_id=v_variant and (p_location_id is null or bb.location_id=p_location_id);
  return next r||jsonb_build_object('tracking_mode',v_mode,'tracked_stock_quantity',case when v_mode='serial' then coalesce(v_serial,0) when v_mode='batch' then coalesce(v_batch,0) else null end);
 end loop;
end$$;


--
-- Name: inventory_list_stock_movements(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_list_stock_movements(p_tenant_id uuid, p_variant_id uuid) RETURNS TABLE(movement_id uuid, movement_type text, quantity_delta numeric, unit_cost numeric, location_name text, reference_type text, reference_number text, note text, occurred_at timestamp with time zone, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin

  if not (
    private.has_permission(
      p_tenant_id,
      'inventory.view'
    )
    or
    private.has_permission(
      p_tenant_id,
      'inventory.manage'
    )
  ) then

    raise exception 'Access denied'
      using errcode = '42501';

  end if;


  return query

  select
    sm.id,
    sm.movement_type,
    sm.quantity_delta,
    sm.unit_cost,

    il.name,

    sm.reference_type,
    sm.reference_number,

    sm.note,

    sm.occurred_at,
    sm.created_at

  from public.stock_movements sm

  join public.inventory_locations il
    on il.id = sm.location_id
   and il.tenant_id = sm.tenant_id

  where sm.tenant_id = p_tenant_id
    and sm.variant_id = p_variant_id

  order by
    sm.occurred_at desc,
    sm.created_at desc

  limit 200;

end;
$$;


--
-- Name: inventory_location_assign_v4(uuid, uuid, uuid, boolean, numeric, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_location_assign_v4(p_tenant_id uuid, p_location_id uuid, p_variant_id uuid, p_active boolean DEFAULT true, p_selling_price numeric DEFAULT NULL::numeric, p_reorder_level numeric DEFAULT NULL::numeric, p_rack_code text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  perform private.v4_location_access(p_tenant_id,p_location_id,'manage');
  if not private.erp_has_permission(p_tenant_id,'inventory.manage') and not private.erp_user_is_owner(p_tenant_id) then
    raise exception 'Inventory manage permission required';
  end if;
  if not exists(select 1 from public.product_variants where id=p_variant_id and tenant_id=p_tenant_id) then raise exception 'Product not found'; end if;
  insert into public.location_product_settings(tenant_id,location_id,variant_id,active,selling_price,reorder_level,rack_code,updated_at)
  values(p_tenant_id,p_location_id,p_variant_id,coalesce(p_active,true),p_selling_price,p_reorder_level,nullif(trim(coalesce(p_rack_code,'')),''),now())
  on conflict(tenant_id,location_id,variant_id) do update set
    active=excluded.active,
    selling_price=coalesce(excluded.selling_price,public.location_product_settings.selling_price),
    reorder_level=coalesce(excluded.reorder_level,public.location_product_settings.reorder_level),
    rack_code=coalesce(excluded.rack_code,public.location_product_settings.rack_code),
    updated_at=now();
  insert into public.location_stock_balances(tenant_id,location_id,variant_id) values(p_tenant_id,p_location_id,p_variant_id)
  on conflict do nothing;
end $$;


--
-- Name: inventory_location_movements_v4(uuid, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_location_movements_v4(p_tenant_id uuid, p_variant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 250) RETURNS TABLE(movement_id uuid, movement_type text, quantity_delta numeric, unit_cost numeric, location_name text, reference_type text, reference_number text, note text, occurred_at timestamp with time zone, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if p_location_id is not null then perform private.v4_location_access(p_tenant_id,p_location_id,'view');end if;
  return query
  select m.id,m.movement_type,m.quantity_delta,m.unit_cost,
    coalesce(l.location_code||' • '||l.name,l.name,'Store'),m.reference_type,m.reference_number,m.note,m.created_at,m.created_at
  from public.location_stock_movements m
  join public.business_locations l on l.id=m.location_id
  where m.tenant_id=p_tenant_id and m.variant_id=p_variant_id
    and (p_location_id is null or m.location_id=p_location_id)
    and (
      private.erp_user_is_owner(p_tenant_id)
      or private.erp_has_permission(p_tenant_id,'locations.view_all')
      or private.erp_user_location_allowed(p_tenant_id,m.location_id,'view')
    )
  order by m.created_at desc
  limit greatest(1,least(coalesce(p_limit,250),1000));
end $$;


--
-- Name: inventory_location_movements_v481(uuid, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_location_movements_v481(p_tenant_id uuid, p_variant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 500) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  return query select jsonb_build_object('movement_id',m.id,'movement_type',m.movement_type,'movement_group',m.movement_group,'quantity_delta',coalesce(m.display_quantity,m.quantity_delta),'base_quantity_delta',coalesce(m.base_quantity_delta,m.quantity_delta),'unit_code',m.unit_code,'conversion_to_base',coalesce(m.conversion_to_base,1),'balance_before',m.balance_before,'balance_after',m.balance_after,'unit_cost',m.unit_cost,'location_id',m.location_id,'location_name',l.name,'reference_type',m.reference_type,'reference_number',m.reference_number,'note',m.note,'occurred_at',m.created_at,'created_at',m.created_at)
  from public.location_stock_movements m join public.business_locations l on l.id=m.location_id
  where m.tenant_id=p_tenant_id and m.variant_id=p_variant_id and (p_location_id is null or m.location_id=p_location_id)
    and (private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'locations.view_all') or private.erp_user_location_allowed(p_tenant_id,m.location_id,'view'))
  order by m.created_at desc limit greatest(1,least(coalesce(p_limit,500),5000));
end $$;


--
-- Name: inventory_location_overview_v42(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_location_overview_v42(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v jsonb;v_can_view_cost boolean;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  v_can_view_cost:=private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'inventory.view_cost') or private.erp_has_permission(p_tenant_id,'inventory.manage');
  select coalesce(jsonb_agg(jsonb_build_object(
    'location_id',l.id,'parent_location_id',l.parent_location_id,'code',l.location_code,'name',l.name,'type',l.location_type,'hierarchy_role',l.hierarchy_role,
    'on_hand',coalesce(s.on_hand,0),'reserved',coalesce(s.reserved,0),'available',coalesce(s.available,0),'stock_value',case when v_can_view_cost then coalesce(s.stock_value,0) else null end,
    'in_transit_in',coalesce(ti.qty,0),'in_transit_out',coalesce(tout.qty,0),'device_count',coalesce(d.device_count,0)
  ) order by case when l.hierarchy_role='main_store' then 0 when l.hierarchy_role='warehouse' then 2 else 1 end,l.sort_order,l.name),'[]'::jsonb)
  into v
  from public.business_locations l
  left join lateral (
    select sum(b.quantity)::numeric on_hand,sum(b.reserved_quantity)::numeric reserved,
      sum(b.quantity-b.reserved_quantity-b.damaged_quantity-b.quarantine_quantity)::numeric available,
      sum(b.quantity*coalesce(nullif(b.average_cost,0),pv.cost_price,0))::numeric stock_value
    from public.location_stock_balances b join public.product_variants pv on pv.id=b.variant_id
    where b.tenant_id=p_tenant_id and b.location_id=l.id
  ) s on true
  left join lateral (
    select sum(greatest(i.dispatched_quantity-i.received_quantity,0))::numeric qty from public.stock_transfers t join public.stock_transfer_items i on i.transfer_id=t.id where t.tenant_id=p_tenant_id and t.to_location_id=l.id and t.status='dispatched'
  ) ti on true
  left join lateral (
    select sum(greatest(i.dispatched_quantity-i.received_quantity,0))::numeric qty from public.stock_transfers t join public.stock_transfer_items i on i.transfer_id=t.id where t.tenant_id=p_tenant_id and t.from_location_id=l.id and t.status='dispatched'
  ) tout on true
  left join lateral (
    select count(*)::bigint device_count from public.business_devices bd where bd.tenant_id=p_tenant_id and bd.location_id=l.id and bd.status<>'revoked'
  ) d on true
  where l.tenant_id=p_tenant_id and l.active
    and (private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'locations.view_all') or private.erp_has_permission(p_tenant_id,'locations.manage_all') or private.erp_user_location_allowed(p_tenant_id,l.id,'view'));
  return coalesce(v,'[]'::jsonb);
end $$;


--
-- Name: inventory_location_stock_summary_v4(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_location_stock_summary_v4(p_tenant_id uuid, p_variant_id uuid) RETURNS TABLE(location_id uuid, location_code text, location_name text, quantity numeric, reserved numeric, damaged numeric, available numeric, selling_price numeric, reorder_level numeric, rack_code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  return query
  select l.id,l.location_code,l.name,coalesce(b.quantity,0),coalesce(b.reserved_quantity,0),coalesce(b.damaged_quantity,0),
    greatest(coalesce(b.quantity,0)-coalesce(b.reserved_quantity,0)-coalesce(b.damaged_quantity,0)-coalesce(b.quarantine_quantity,0),0),
    s.selling_price,s.reorder_level,s.rack_code
  from public.business_locations l
  join public.location_product_settings s on s.tenant_id=p_tenant_id and s.location_id=l.id and s.variant_id=p_variant_id and s.active
  left join public.location_stock_balances b on b.tenant_id=s.tenant_id and b.location_id=s.location_id and b.variant_id=s.variant_id
  where l.tenant_id=p_tenant_id and l.active
    and (private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'locations.view_all') or private.erp_user_location_allowed(p_tenant_id,l.id,'view'))
  order by l.location_code;
end $$;


--
-- Name: inventory_location_stock_summary_v42(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_location_stock_summary_v42(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid) RETURNS TABLE(variant_id uuid, sku text, product_name text, on_hand numeric, reserved numeric, available numeric, damaged numeric, quarantine numeric, in_transit_in numeric, in_transit_out numeric, total_company_on_hand numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v_all boolean;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  v_all:=private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'locations.view_all') or private.erp_has_permission(p_tenant_id,'locations.manage_all');
  if p_location_id is not null then perform private.v4_location_access(p_tenant_id,p_location_id,'view');end if;
  return query
  with scoped as (
    select b.variant_id,
      sum(b.quantity)::numeric on_hand,sum(b.reserved_quantity)::numeric reserved,
      sum(b.damaged_quantity)::numeric damaged,sum(b.quarantine_quantity)::numeric quarantine
    from public.location_stock_balances b
    where b.tenant_id=p_tenant_id and (p_location_id is null or b.location_id=p_location_id)
      and (p_location_id is not null or v_all or private.erp_user_location_allowed(p_tenant_id,b.location_id,'view'))
    group by b.variant_id
  ), company as (
    select b.variant_id,sum(b.quantity)::numeric total
    from public.location_stock_balances b
    where b.tenant_id=p_tenant_id and (v_all or private.erp_user_location_allowed(p_tenant_id,b.location_id,'view'))
    group by b.variant_id
  ), transit_in as (
    select i.variant_id,sum(greatest(i.dispatched_quantity-i.received_quantity,0))::numeric qty
    from public.stock_transfers t join public.stock_transfer_items i on i.transfer_id=t.id
    where t.tenant_id=p_tenant_id and t.status='dispatched' and (p_location_id is null or t.to_location_id=p_location_id)
      and (p_location_id is not null or v_all or private.erp_user_location_allowed(p_tenant_id,t.to_location_id,'view'))
    group by i.variant_id
  ), transit_out as (
    select i.variant_id,sum(greatest(i.dispatched_quantity-i.received_quantity,0))::numeric qty
    from public.stock_transfers t join public.stock_transfer_items i on i.transfer_id=t.id
    where t.tenant_id=p_tenant_id and t.status='dispatched' and (p_location_id is null or t.from_location_id=p_location_id)
      and (p_location_id is not null or v_all or private.erp_user_location_allowed(p_tenant_id,t.from_location_id,'view'))
    group by i.variant_id
  )
  select s.variant_id,pv.sku::text,p.name::text,s.on_hand,s.reserved,
    (s.on_hand-s.reserved-s.damaged-s.quarantine)::numeric,s.damaged,s.quarantine,
    coalesce(ti.qty,0),coalesce(tout.qty,0),coalesce(c.total,0)
  from scoped s join public.product_variants pv on pv.id=s.variant_id join public.products p on p.id=pv.product_id
  left join company c on c.variant_id=s.variant_id left join transit_in ti on ti.variant_id=s.variant_id left join transit_out tout on tout.variant_id=s.variant_id
  order by p.name,pv.sku;
end $$;


--
-- Name: inventory_movement_history_v481(uuid, uuid, uuid, text, timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_movement_history_v481(p_tenant_id uuid, p_variant_id uuid DEFAULT NULL::uuid, p_location_id uuid DEFAULT NULL::uuid, p_movement_type text DEFAULT NULL::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 500) RETURNS TABLE(movement_id uuid, location_id uuid, location_name text, variant_id uuid, product_name text, sku text, movement_type text, movement_group text, display_quantity numeric, unit_code text, base_quantity_delta numeric, balance_before numeric, balance_after numeric, unit_cost numeric, reference_type text, reference_number text, note text, occurred_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  return query select m.id,m.location_id,l.name,m.variant_id,p.name,pv.sku,m.movement_type,m.movement_group,coalesce(m.display_quantity,m.quantity_delta),m.unit_code,coalesce(m.base_quantity_delta,m.quantity_delta),m.balance_before,m.balance_after,m.unit_cost,m.reference_type,m.reference_number,m.note,m.created_at
  from public.location_stock_movements m join public.business_locations l on l.id=m.location_id join public.product_variants pv on pv.id=m.variant_id join public.products p on p.id=pv.product_id
  where m.tenant_id=p_tenant_id and (p_variant_id is null or m.variant_id=p_variant_id) and (p_location_id is null or m.location_id=p_location_id) and (p_movement_type is null or m.movement_type=p_movement_type) and (p_from is null or m.created_at>=p_from) and (p_to is null or m.created_at<p_to)
    and (private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'locations.view_all') or private.erp_user_location_allowed(p_tenant_id,m.location_id,'view'))
  order by m.created_at desc limit greatest(1,least(coalesce(p_limit,500),5000));
end $$;


--
-- Name: inventory_next_sku(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_next_sku(p_tenant_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_no bigint;v_sku text;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  loop
    insert into public.tenant_code_counters(tenant_id,code_key,last_number) values(p_tenant_id,'sku',1)
    on conflict(tenant_id,code_key) do update set last_number=public.tenant_code_counters.last_number+1
    returning last_number into v_no;
    v_sku:='SKU-'||lpad(v_no::text,6,'0');
    exit when not exists(select 1 from public.product_variants where tenant_id=p_tenant_id and upper(sku)=upper(v_sku));
  end loop;
  return v_sku;
end $$;


--
-- Name: inventory_next_sku_v4(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_next_sku_v4(p_tenant_id uuid, p_prefix text DEFAULT 'SKU'::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare n integer:=1;candidate text;begin if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;loop candidate:=upper(coalesce(nullif(trim(p_prefix),''),'SKU'))||'-'||lpad(n::text,6,'0');exit when not exists(select 1 from public.product_variants where tenant_id=p_tenant_id and lower(sku)=lower(candidate));n:=n+1;if n>9999999 then raise exception 'SKU sequence exhausted';end if;end loop;return candidate;end $$;


--
-- Name: inventory_product_lookup_v482(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_product_lookup_v482(p_tenant_id uuid, p_code text, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_variant uuid;v_code text:=lower(trim(coalesce(p_code,'')));v jsonb;begin
 if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
 if v_code='' then return '{}'::jsonb;end if;
 select pv.id into v_variant from public.product_variants pv where pv.tenant_id=p_tenant_id and lower(trim(pv.sku))=v_code limit 1;
 if v_variant is null then select i.variant_id into v_variant from public.product_identifiers_v482 i where i.tenant_id=p_tenant_id and i.active and lower(trim(i.code))=v_code limit 1;end if;
 -- Compatibility fallback for historical installations where a legacy barcode/part number
 -- has not yet been promoted to the identifier table. SKU always has first priority.
 if v_variant is null then select pv.id into v_variant from public.product_variants pv where pv.tenant_id=p_tenant_id and (lower(trim(coalesce(pv.barcode,'')))=v_code or lower(trim(coalesce(pv.part_number,'')))=v_code) order by case when lower(trim(coalesce(pv.barcode,'')))=v_code then 0 else 1 end limit 1;end if;
 if v_variant is null then return '{}'::jsonb;end if;
 select r into v from public.inventory_list_products_v482(p_tenant_id,p_location_id) r where (r->>'variant_id')::uuid=v_variant limit 1;
 return coalesce(v,'{}'::jsonb);
end$$;


--
-- Name: inventory_product_units_save_v481(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_product_units_save_v481(p_tenant_id uuid, p_variant_id uuid, p_base_unit_code text, p_units jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare x jsonb;v_unit uuid;v_base uuid;v_old_base uuid;v_code text;v_count int:=0;v_default_sale int:=0;v_default_purchase int:=0;v_requested_sale int:=0;v_requested_purchase int:=0;v_has_history boolean:=false;begin
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'inventory.manage') then raise exception 'Inventory manage permission required';end if;
  if not exists(select 1 from public.product_variants pv where pv.id=p_variant_id and pv.tenant_id=p_tenant_id) then raise exception 'Product variant not found';end if;
  perform private.v481_seed_units(p_tenant_id);
  v_code:=upper(trim(coalesce(p_base_unit_code,'PCS')));
  select u.id into v_base from public.inventory_units_v481 u where u.tenant_id=p_tenant_id and u.code=v_code and u.active;
  if v_base is null then raise exception 'Base unit % not found',v_code;end if;
  select pu.unit_id into v_old_base from public.product_units_v481 pu where pu.tenant_id=p_tenant_id and pu.variant_id=p_variant_id and pu.is_base and pu.active limit 1;
  if v_old_base is not null and v_old_base<>v_base then
    select exists(select 1 from public.location_stock_movements m where m.tenant_id=p_tenant_id and m.variant_id=p_variant_id)
        or exists(select 1 from public.location_stock_balances b where b.tenant_id=p_tenant_id and b.variant_id=p_variant_id and abs(coalesce(b.quantity,0))>0.000001)
      into v_has_history;
    if v_has_history then raise exception 'Base inventory unit cannot be changed after stock/history exists. Add a conversion unit instead.';end if;
  end if;
  select count(*) filter(where coalesce((value->>'is_default_sale')::boolean,false) and coalesce((value->>'allow_sale')::boolean,true)),
         count(*) filter(where coalesce((value->>'is_default_purchase')::boolean,false) and coalesce((value->>'allow_purchase')::boolean,false))
    into v_requested_sale,v_requested_purchase
  from jsonb_array_elements(coalesce(p_units,'[]'::jsonb));
  if v_requested_sale>1 then raise exception 'Only one default sale unit is allowed';end if;
  if v_requested_purchase>1 then raise exception 'Only one default purchase unit is allowed';end if;

  -- Clear flags first; rows are preserved so historical IDs remain stable.
  update public.product_units_v481 set is_base=false,is_default_sale=false,is_default_purchase=false,active=false,updated_at=now() where tenant_id=p_tenant_id and variant_id=p_variant_id;
  insert into public.product_units_v481(tenant_id,variant_id,unit_id,is_base,allow_purchase,allow_sale,is_default_purchase,is_default_sale,conversion_to_base,quantity_step,active)
  values(p_tenant_id,p_variant_id,v_base,true,true,true,v_requested_purchase=0,v_requested_sale=0,1,coalesce((select case when allow_fractional then power(10::numeric,-least(decimal_places,3)) else 1 end from public.inventory_units_v481 where id=v_base),1),true)
  on conflict(tenant_id,variant_id,unit_id) do update set is_base=true,allow_purchase=true,allow_sale=true,is_default_purchase=(v_requested_purchase=0),is_default_sale=(v_requested_sale=0),conversion_to_base=1,quantity_step=case when excluded.quantity_step<=0 then 1 else excluded.quantity_step end,active=true,updated_at=now();

  for x in select value from jsonb_array_elements(coalesce(p_units,'[]'::jsonb)) loop
    v_unit:=null;
    if nullif(x->>'unit_id','') is not null then begin v_unit:=(x->>'unit_id')::uuid; exception when others then v_unit:=null; end; end if;
    if v_unit is null and nullif(trim(coalesce(x->>'code','')),'') is not null then select u.id into v_unit from public.inventory_units_v481 u where u.tenant_id=p_tenant_id and u.code=upper(trim(x->>'code')) and u.active;end if;
    if v_unit is null then raise exception 'Unknown unit in product conversion';end if;
    if v_unit=v_base then
      update public.product_units_v481 set
        quantity_step=coalesce(nullif(x->>'quantity_step','')::numeric,quantity_step),
        cutting_allowed=coalesce((x->>'cutting_allowed')::boolean,cutting_allowed),
        cutting_charge=coalesce(nullif(x->>'cutting_charge','')::numeric,cutting_charge),
        sale_price=nullif(x->>'sale_price','')::numeric,
        purchase_cost=nullif(x->>'purchase_cost','')::numeric,
        updated_at=now()
      where tenant_id=p_tenant_id and variant_id=p_variant_id and unit_id=v_base;
      continue;
    end if;
    insert into public.product_units_v481(tenant_id,variant_id,unit_id,is_base,allow_purchase,allow_sale,is_default_purchase,is_default_sale,conversion_to_base,quantity_step,sale_price,purchase_cost,cutting_allowed,cutting_charge,active,settings)
    values(p_tenant_id,p_variant_id,v_unit,false,coalesce((x->>'allow_purchase')::boolean,false),coalesce((x->>'allow_sale')::boolean,true),coalesce((x->>'is_default_purchase')::boolean,false) and coalesce((x->>'allow_purchase')::boolean,false),coalesce((x->>'is_default_sale')::boolean,false) and coalesce((x->>'allow_sale')::boolean,true),coalesce(nullif(x->>'conversion_to_base','')::numeric,1),coalesce(nullif(x->>'quantity_step','')::numeric,1),nullif(x->>'sale_price','')::numeric,nullif(x->>'purchase_cost','')::numeric,coalesce((x->>'cutting_allowed')::boolean,false),coalesce(nullif(x->>'cutting_charge','')::numeric,0),coalesce((x->>'active')::boolean,true),coalesce(x->'settings','{}'::jsonb))
    on conflict(tenant_id,variant_id,unit_id) do update set allow_purchase=excluded.allow_purchase,allow_sale=excluded.allow_sale,is_default_purchase=excluded.is_default_purchase,is_default_sale=excluded.is_default_sale,conversion_to_base=excluded.conversion_to_base,quantity_step=excluded.quantity_step,sale_price=excluded.sale_price,purchase_cost=excluded.purchase_cost,cutting_allowed=excluded.cutting_allowed,cutting_charge=excluded.cutting_charge,active=excluded.active,settings=excluded.settings,updated_at=now();
  end loop;

  -- Guarantee one default sale/purchase among active allowed units; base is the fallback.
  select count(*) into v_default_sale from public.product_units_v481 where tenant_id=p_tenant_id and variant_id=p_variant_id and active and allow_sale and is_default_sale;
  if v_default_sale=0 then update public.product_units_v481 set is_default_sale=true where tenant_id=p_tenant_id and variant_id=p_variant_id and unit_id=v_base;end if;
  if v_default_sale>1 then raise exception 'Only one default sale unit is allowed';end if;
  select count(*) into v_default_purchase from public.product_units_v481 where tenant_id=p_tenant_id and variant_id=p_variant_id and active and allow_purchase and is_default_purchase;
  if v_default_purchase=0 then update public.product_units_v481 set is_default_purchase=true where tenant_id=p_tenant_id and variant_id=p_variant_id and unit_id=v_base;end if;
  if v_default_purchase>1 then raise exception 'Only one default purchase unit is allowed';end if;

  insert into public.product_invoice_attributes_v45(tenant_id,variant_id,unit_code,updated_at,updated_by)
  values(p_tenant_id,p_variant_id,v_code,now(),auth.uid()) on conflict(tenant_id,variant_id) do update set unit_code=excluded.unit_code,updated_at=now(),updated_by=auth.uid();
  select count(*) into v_count from public.product_units_v481 where tenant_id=p_tenant_id and variant_id=p_variant_id and active;
  return jsonb_build_object('variant_id',p_variant_id,'base_unit_code',v_code,'active_units',v_count);
end $$;


--
-- Name: inventory_product_units_v481(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_product_units_v481(p_tenant_id uuid, p_variant_id uuid) RETURNS TABLE(unit_id uuid, code text, name text, unit_group text, decimal_places integer, allow_fractional boolean, is_base boolean, allow_purchase boolean, allow_sale boolean, is_default_purchase boolean, is_default_sale boolean, conversion_to_base numeric, quantity_step numeric, sale_price numeric, purchase_cost numeric, cutting_allowed boolean, cutting_charge numeric, active boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  return query select u.id,u.code,u.name,u.unit_group,u.decimal_places,u.allow_fractional,pu.is_base,pu.allow_purchase,pu.allow_sale,pu.is_default_purchase,pu.is_default_sale,pu.conversion_to_base,pu.quantity_step,pu.sale_price,pu.purchase_cost,pu.cutting_allowed,pu.cutting_charge,pu.active
  from public.product_units_v481 pu join public.inventory_units_v481 u on u.id=pu.unit_id
  where pu.tenant_id=p_tenant_id and pu.variant_id=p_variant_id order by pu.is_base desc,pu.is_default_sale desc,u.name;
end $$;


--
-- Name: inventory_serial_history_v483(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_serial_history_v483(p_tenant_id uuid, p_serial_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v jsonb;begin
 if not private.erp_user_has_tenant_access(p_tenant_id) or not private.v483_trace_view_allowed(p_tenant_id) then raise exception 'Traceability view permission required';end if;
 select jsonb_build_object(
  'serial',jsonb_build_object(
    'serial_id',s.id,'serial_number',s.serial_number,'status',s.status,'variant_id',s.variant_id,
    'product_name',p.name,'variant_name',pv.name,'sku',pv.sku,
    'location_name',coalesce(l.name,sl.name,pl.name),'supplier_name',sup.name,'customer_name',c.name,
    'purchase_number',pur.purchase_number,'sale_number',sa.sale_number,'received_at',s.received_at,'sold_at',s.sold_at
  ),
  'warranties',coalesce((
    select jsonb_agg(jsonb_build_object(
      'warranty_id',w.id,'customer_name',cw.name,'sale_number',sw.sale_number,
      'warranty_start',w.warranty_start,'warranty_expiry',w.warranty_expiry,
      'status',case when w.status='active' and w.warranty_expiry<current_date then 'expired' else w.status end
    ) order by w.created_at desc)
    from public.product_warranties_v483 w
    left join public.customers cw on cw.id=w.customer_id
    left join public.sales sw on sw.id=w.sale_id
    where w.tenant_id=p_tenant_id and w.serial_id=s.id
  ),'[]'::jsonb),
  'events',coalesce((
    select jsonb_agg(jsonb_build_object(
      'event_id',e.id,'event_type',e.event_type,'quantity',e.quantity,'location_name',el.name,
      'supplier_name',es.name,'customer_name',ec.name,'purchase_number',ep.purchase_number,'sale_number',esa.sale_number,
      'reference_number',e.reference_number,'created_at',e.created_at
    ) order by e.created_at desc)
    from public.inventory_trace_events_v483 e
    left join public.business_locations el on el.id=e.location_id
    left join public.suppliers es on es.id=e.supplier_id
    left join public.customers ec on ec.id=e.customer_id
    left join public.purchases ep on ep.id=e.purchase_id
    left join public.sales esa on esa.id=e.sale_id
    where e.tenant_id=p_tenant_id and e.serial_id=s.id
      and private.erp_document_scope_allowed(p_tenant_id,e.location_id,null,'view')
  ),'[]'::jsonb)
 ) into v
 from public.inventory_serials_v483 s
 join public.product_variants pv on pv.id=s.variant_id and pv.tenant_id=s.tenant_id
 join public.products p on p.id=pv.product_id
 left join public.business_locations l on l.id=s.current_location_id
 left join public.suppliers sup on sup.id=s.supplier_id
 left join public.customers c on c.id=s.customer_id
 left join public.purchases pur on pur.id=s.purchase_id
 left join public.sales sa on sa.id=s.sale_id
 left join public.document_origins so on so.tenant_id=s.tenant_id and so.entity_type='sale' and so.entity_id=s.sale_id
 left join public.document_origins po on po.tenant_id=s.tenant_id and po.entity_type='purchase' and po.entity_id=s.purchase_id
 left join public.business_locations sl on sl.id=so.location_id
 left join public.business_locations pl on pl.id=po.location_id
 where s.tenant_id=p_tenant_id and s.id=p_serial_id
   and private.erp_document_scope_allowed(p_tenant_id,coalesce(s.current_location_id,so.location_id,po.location_id),null,'view');
 if v is null then raise exception 'Serial not found or location access denied';end if;
 return v;
end$$;


--
-- Name: inventory_serial_resolve_v483(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_serial_resolve_v483(p_tenant_id uuid, p_serial_number text, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v jsonb;begin
 if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
 select jsonb_build_object(
   'serial_id',s.id,'serial_number',s.serial_number,'status',s.status,'variant_id',s.variant_id,
   'product_name',p.name,'variant_name',pv.name,'sku',pv.sku,'location_id',s.current_location_id
 ) into v
 from public.inventory_serials_v483 s
 join public.product_variants pv on pv.id=s.variant_id and pv.tenant_id=s.tenant_id
 join public.products p on p.id=pv.product_id
 where s.tenant_id=p_tenant_id
   and lower(trim(s.serial_number))=lower(trim(p_serial_number))
   and (p_location_id is null or s.current_location_id=p_location_id)
   and private.erp_document_scope_allowed(p_tenant_id,s.current_location_id,p_location_id,'view')
 limit 1;
 return v;
end$$;


--
-- Name: inventory_serial_search_v483(uuid, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_serial_search_v483(p_tenant_id uuid, p_query text DEFAULT ''::text, p_location_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 200) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare q text:='%'||lower(trim(coalesce(p_query,'')))||'%';begin
 if not private.erp_user_has_tenant_access(p_tenant_id) or not private.v483_trace_view_allowed(p_tenant_id) then raise exception 'Traceability view permission required';end if;
 return query
 select jsonb_build_object(
  'serial_id',s.id,'serial_number',s.serial_number,'status',s.status,'variant_id',s.variant_id,
  'product_name',p.name,'variant_name',pv.name,'sku',pv.sku,
  'location_id',coalesce(s.current_location_id,so.location_id,po.location_id),
  'location_name',coalesce(l.name,sl.name,pl.name),
  'supplier_id',s.supplier_id,'supplier_name',sup.name,'purchase_id',s.purchase_id,'purchase_number',pur.purchase_number,
  'customer_id',s.customer_id,'customer_name',c.name,'sale_id',s.sale_id,'sale_number',sa.sale_number,
  'received_at',s.received_at,'sold_at',s.sold_at,
  'warranty_start',w.warranty_start,'warranty_expiry',w.warranty_expiry,
  'warranty_status',case when w.status='active' and w.warranty_expiry<current_date then 'expired' else w.status end
 )
 from public.inventory_serials_v483 s
 join public.product_variants pv on pv.id=s.variant_id and pv.tenant_id=s.tenant_id
 join public.products p on p.id=pv.product_id
 left join public.business_locations l on l.id=s.current_location_id
 left join public.suppliers sup on sup.id=s.supplier_id
 left join public.purchases pur on pur.id=s.purchase_id
 left join public.customers c on c.id=s.customer_id
 left join public.sales sa on sa.id=s.sale_id
 left join public.document_origins so on so.tenant_id=s.tenant_id and so.entity_type='sale' and so.entity_id=s.sale_id
 left join public.document_origins po on po.tenant_id=s.tenant_id and po.entity_type='purchase' and po.entity_id=s.purchase_id
 left join public.business_locations sl on sl.id=so.location_id
 left join public.business_locations pl on pl.id=po.location_id
 left join lateral(
  select x.* from public.product_warranties_v483 x
  where x.tenant_id=s.tenant_id and x.serial_id=s.id and x.status<>'void'
  order by x.created_at desc limit 1
 ) w on true
 where s.tenant_id=p_tenant_id
 and private.erp_document_scope_allowed(p_tenant_id,coalesce(s.current_location_id,so.location_id,po.location_id),p_location_id,'view')
 and (
  trim(coalesce(p_query,''))='' or lower(s.serial_number) like q or lower(coalesce(p.name,'')) like q or
  lower(coalesce(pv.sku,'')) like q or lower(coalesce(sup.name,'')) like q or lower(coalesce(c.name,'')) like q or
  lower(coalesce(pur.purchase_number,'')) like q or lower(coalesce(sa.sale_number,'')) like q
 )
 order by s.updated_at desc
 limit greatest(1,least(coalesce(p_limit,200),1000));
end$$;


--
-- Name: inventory_sku_available(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_sku_available(p_tenant_id uuid, p_sku text, p_variant_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
  select private.erp_user_has_tenant_access(p_tenant_id) and not exists(
    select 1 from public.product_variants pv where pv.tenant_id=p_tenant_id and upper(pv.sku)=upper(trim(p_sku)) and (p_variant_id is null or pv.id<>p_variant_id)
  );
$$;


--
-- Name: inventory_stock_count_post_v4(uuid, uuid, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_stock_count_post_v4(p_tenant_id uuid, p_location_id uuid, p_items jsonb, p_notes text DEFAULT NULL::text, p_device_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_id uuid:=gen_random_uuid();v_no text;x jsonb;v_current numeric;v_counted numeric;v_delta numeric;begin
  perform private.v4_location_access(p_tenant_id,p_location_id,'manage');
  if not private.erp_has_permission(p_tenant_id,'inventory.stock_count') and not private.erp_has_permission(p_tenant_id,'inventory.manage') and not private.erp_user_is_owner(p_tenant_id) then raise exception 'Stock count permission required';end if;
  v_no:='CNT-'||lpad(nextval('public.stock_count_number_seq')::text,6,'0');
  insert into public.stock_counts(id,tenant_id,location_id,count_number,status,notes,created_by) values(v_id,p_tenant_id,p_location_id,v_no,'draft',nullif(trim(coalesce(p_notes,'')),''),auth.uid());
  for x in select value from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) loop
    select coalesce(quantity,0) into v_current from public.location_stock_balances where tenant_id=p_tenant_id and location_id=p_location_id and variant_id=(x->>'variant_id')::uuid;
    v_current:=coalesce(v_current,0);v_counted:=coalesce((x->>'counted_quantity')::numeric,0);if v_counted<0 then raise exception 'Counted quantity cannot be negative';end if;v_delta:=v_counted-v_current;
    insert into public.stock_count_items(count_id,variant_id,system_quantity,counted_quantity) values(v_id,(x->>'variant_id')::uuid,v_current,v_counted);
    if v_delta<>0 then
      perform public.inventory_adjust_stock(p_tenant_id,(x->>'variant_id')::uuid,v_delta,'Stock count • '||v_no);
      perform private.v4_location_stock_apply(p_tenant_id,p_location_id,(x->>'variant_id')::uuid,v_delta,'stock_count','stock_count',v_id,v_no,'Physical stock count',p_device_id,true);
    end if;
  end loop;
  update public.stock_counts set status='posted',posted_by=auth.uid(),posted_at=now() where id=v_id;
  return jsonb_build_object('count_id',v_id,'count_number',v_no,'status','posted');
end $$;


--
-- Name: inventory_stock_count_post_v483(uuid, uuid, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_stock_count_post_v483(p_tenant_id uuid, p_location_id uuid, p_items jsonb, p_notes text, p_device_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $_$
  select public.inventory_stock_count_post_v485($1,$2,$3,$4,$5,null)
$_$;


--
-- Name: inventory_stock_count_post_v485(uuid, uuid, jsonb, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_stock_count_post_v485(p_tenant_id uuid, p_location_id uuid, p_items jsonb, p_notes text DEFAULT NULL::text, p_device_id uuid DEFAULT NULL::uuid, p_request_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_existing jsonb;v_id uuid:=gen_random_uuid();v_no text;x jsonb;v_variant uuid;v_mode text;v_system numeric;v_reserved numeric;v_damage numeric;v_quarantine numeric;
  v_counted numeric;v_delta numeric;v_any_variance boolean:=false;v_tracking jsonb;
  v_serials jsonb;s jsonb;v_serial text;v_serial_row public.inventory_serials_v483%rowtype;v_seen_serial uuid[]:='{}'::uuid[];sr record;v_serial_damage numeric:=0;
  v_batches jsonb;b jsonb;v_batch_id uuid;v_batch_no text;v_batch_qty numeric;v_batch_damage numeric;v_old_qty numeric;v_old_damage numeric;v_old_reserved numeric;
  v_batch_total numeric;v_batch_damage_total numeric;v_seen_batch uuid[]:='{}'::uuid[];br record;v_mfg date;v_exp date;v_event_qty numeric;v_require_expiry boolean:=false;
  v_result jsonb;
begin
  if nullif(trim(coalesce(p_request_id,'')),'') is not null then
    v_existing:=private.v47_request_existing(p_tenant_id,p_request_id,'warehouse.stock_count');
    if v_existing is not null then return v_existing;end if;
  end if;
  perform private.v4_location_access(p_tenant_id,p_location_id,'manage');
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'inventory.stock_count') and not private.erp_has_permission(p_tenant_id,'inventory.manage') then raise exception 'Stock count permission required';end if;
  if p_items is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'Add at least one counted product';end if;

  v_no:='CNT-'||to_char(current_date,'YYMMDD')||'-'||lpad(nextval('public.stock_count_number_seq')::text,6,'0');
  insert into public.stock_counts(id,tenant_id,location_id,count_number,status,notes,created_by,request_key,reconciliation_status,updated_at)
  values(v_id,p_tenant_id,p_location_id,v_no,'draft',nullif(trim(coalesce(p_notes,'')),''),auth.uid(),nullif(trim(coalesce(p_request_id,'')),''),'pending',now());

  for x in select value from jsonb_array_elements(p_items) loop
    v_variant:=nullif(x->>'variant_id','')::uuid;
    if v_variant is null or not exists(select 1 from public.product_variants pv join public.products p on p.id=pv.product_id where pv.tenant_id=p_tenant_id and pv.id=v_variant and p.item_type='stock') then raise exception 'Stock-count product is invalid';end if;
    insert into public.location_stock_balances(tenant_id,location_id,variant_id) values(p_tenant_id,p_location_id,v_variant) on conflict do nothing;
    select quantity,reserved_quantity,damaged_quantity,quarantine_quantity into v_system,v_reserved,v_damage,v_quarantine
      from public.location_stock_balances where tenant_id=p_tenant_id and location_id=p_location_id and variant_id=v_variant for update;
    v_system:=coalesce(v_system,0);v_reserved:=coalesce(v_reserved,0);v_damage:=coalesce(v_damage,0);v_quarantine:=coalesce(v_quarantine,0);
    if v_reserved>0.000001 then raise exception 'Cannot post a stock count while product % has reserved transfer stock. Dispatch/cancel the transfer first.',v_variant;end if;
    v_mode:=private.v483_tracking_mode(p_tenant_id,v_variant);
    v_tracking:=coalesce(x->'tracking','{}'::jsonb);

    if v_mode='none' then
      v_counted:=coalesce(nullif(x->>'counted_quantity','')::numeric,-1);
      if v_counted<0 then raise exception 'Counted quantity cannot be negative';end if;

    elsif v_mode='serial' then
      v_serials:=coalesce(x->'serial_numbers',v_tracking->'serial_numbers','[]'::jsonb);
      if jsonb_typeof(v_serials)<>'array' then raise exception 'Serial count must provide serial_numbers as an array';end if;
      v_seen_serial:='{}'::uuid[];
      for s in select value from jsonb_array_elements(v_serials) loop
        v_serial:=trim(coalesce(case when jsonb_typeof(s)='string' then s#>>'{}' else s->>'serial_number' end,''));
        if v_serial='' then raise exception 'Serial number cannot be blank';end if;
        select * into v_serial_row from public.inventory_serials_v483 where tenant_id=p_tenant_id and lower(trim(serial_number))=lower(v_serial) for update;
        if found then
          if v_serial_row.variant_id<>v_variant then raise exception 'Serial % belongs to another product',v_serial;end if;
          if v_serial_row.id=any(v_seen_serial) then raise exception 'Serial % is duplicated in this stock count',v_serial;end if;
          if v_serial_row.reserved_transfer_id is not null then raise exception 'Serial % is reserved for transfer and cannot be counted now',v_serial;end if;
          if v_serial_row.status in('sold','in_transit','recalled','void') then raise exception 'Serial % has status % and cannot be counted as local stock',v_serial,v_serial_row.status;end if;
          if v_serial_row.current_location_id is not null and v_serial_row.current_location_id<>p_location_id then raise exception 'Serial % is registered at another location',v_serial;end if;
          if v_serial_row.status='missing' or v_serial_row.current_location_id is null then
            update public.inventory_serials_v483 set status='in_stock',current_location_id=p_location_id,updated_at=now() where id=v_serial_row.id;
            insert into public.inventory_trace_events_v483(tenant_id,variant_id,serial_id,event_type,quantity,location_id,reference_number,source_key,metadata,created_by)
            values(p_tenant_id,v_variant,v_serial_row.id,'adjustment',1,p_location_id,v_no,'stock-count:'||v_id::text||':serial-in:'||v_serial_row.id::text,jsonb_build_object('direction','in','reason','serial recovered/found during count'),auth.uid()) on conflict do nothing;
          end if;
          v_seen_serial:=array_append(v_seen_serial,v_serial_row.id);
        else
          insert into public.inventory_serials_v483(tenant_id,variant_id,serial_number,status,current_location_id,received_at,notes,created_by)
          values(p_tenant_id,v_variant,v_serial,'in_stock',p_location_id,now(),'Created by physical stock count '||v_no,auth.uid()) returning * into v_serial_row;
          v_seen_serial:=array_append(v_seen_serial,v_serial_row.id);
          insert into public.inventory_trace_events_v483(tenant_id,variant_id,serial_id,event_type,quantity,location_id,reference_number,source_key,metadata,created_by)
          values(p_tenant_id,v_variant,v_serial_row.id,'adjustment',1,p_location_id,v_no,'stock-count:'||v_id::text||':serial-new:'||v_serial_row.id::text,jsonb_build_object('direction','in','reason','unregistered serial found during count'),auth.uid());
        end if;
      end loop;
      for sr in
        select id,serial_number,status from public.inventory_serials_v483
        where tenant_id=p_tenant_id and variant_id=v_variant and current_location_id=p_location_id and status in('in_stock','quarantine')
          and not (id=any(v_seen_serial)) for update
      loop
        update public.inventory_serials_v483 set status='missing',current_location_id=null,reserved_transfer_id=null,updated_at=now() where id=sr.id;
        insert into public.inventory_trace_events_v483(tenant_id,variant_id,serial_id,event_type,quantity,location_id,reference_number,source_key,metadata,created_by)
        values(p_tenant_id,v_variant,sr.id,'adjustment',1,p_location_id,v_no,'stock-count:'||v_id::text||':serial-out:'||sr.id::text,jsonb_build_object('direction','out','reason','serial missing during count','serial_number',sr.serial_number),auth.uid()) on conflict do nothing;
      end loop;
      v_counted:=coalesce(cardinality(v_seen_serial),0);
      select count(*)::numeric into v_serial_damage from public.inventory_serials_v483 where tenant_id=p_tenant_id and variant_id=v_variant and current_location_id=p_location_id and status='quarantine';
      v_tracking:=jsonb_build_object('serial_numbers',v_serials,'counted_serials',v_counted);

    else
      v_batches:=coalesce(x->'batches',v_tracking->'batches','[]'::jsonb);
      if jsonb_typeof(v_batches)<>'array' then raise exception 'Batch count must provide batches as an array';end if;
      v_batch_total:=0;v_batch_damage_total:=0;v_seen_batch:='{}'::uuid[];
      for b in select value from jsonb_array_elements(v_batches) loop
        v_batch_id:=null;v_batch_no:=trim(coalesce(b->>'batch_number',''));
        v_batch_qty:=coalesce(nullif(b->>'quantity','')::numeric,0);v_batch_damage:=coalesce(nullif(b->>'damaged_quantity','')::numeric,0);
        if v_batch_qty<0 or v_batch_damage<0 then raise exception 'Batch counted quantities cannot be negative';end if;
        if nullif(b->>'batch_id','') is not null then v_batch_id:=(b->>'batch_id')::uuid;end if;
        if v_batch_id is not null and not exists(
          select 1 from public.inventory_batches_v483 ib where ib.id=v_batch_id and ib.tenant_id=p_tenant_id and ib.variant_id=v_variant
        ) then raise exception 'Batch does not belong to the selected product/business';end if;
        if v_batch_id is null and v_batch_no<>'' then select id into v_batch_id from public.inventory_batches_v483 where tenant_id=p_tenant_id and variant_id=v_variant and lower(trim(batch_number))=lower(v_batch_no);end if;
        if v_batch_id is null then
          if v_batch_no='' then raise exception 'Batch number is required';end if;
          v_mfg:=nullif(b->>'manufactured_on','')::date;v_exp:=nullif(b->>'expiry_on','')::date;
          select coalesce(require_batch_expiry,false) into v_require_expiry from public.product_tracking_policies_v483 where tenant_id=p_tenant_id and variant_id=v_variant;
          if coalesce(v_require_expiry,false) and v_exp is null then raise exception 'Expiry date is required for batch %',v_batch_no;end if;
          insert into public.inventory_batches_v483(tenant_id,variant_id,batch_number,manufactured_on,expiry_on,status,notes,created_by)
          values(p_tenant_id,v_variant,v_batch_no,v_mfg,v_exp,'active','Created by physical stock count '||v_no,auth.uid()) returning id into v_batch_id;
        else
          v_mfg:=nullif(b->>'manufactured_on','')::date;v_exp:=nullif(b->>'expiry_on','')::date;
          if exists(
            select 1 from public.inventory_batches_v483 ib where ib.id=v_batch_id
              and ((v_mfg is not null and ib.manufactured_on is distinct from v_mfg) or (v_exp is not null and ib.expiry_on is distinct from v_exp))
          ) then raise exception 'Batch dates conflict with the registered batch';end if;
        end if;
        if v_batch_id=any(v_seen_batch) then raise exception 'The same batch cannot appear twice in a stock count';end if;
        v_seen_batch:=array_append(v_seen_batch,v_batch_id);
        select coalesce(quantity,0),coalesce(damaged_quantity,0),coalesce(reserved_quantity,0) into v_old_qty,v_old_damage,v_old_reserved
          from public.inventory_batch_balances_v483 where tenant_id=p_tenant_id and batch_id=v_batch_id and location_id=p_location_id for update;
        v_old_qty:=coalesce(v_old_qty,0);v_old_damage:=coalesce(v_old_damage,0);v_old_reserved:=coalesce(v_old_reserved,0);
        if v_old_reserved>0.000001 then raise exception 'Batch % is reserved for transfer and cannot be counted now',coalesce(v_batch_no,v_batch_id::text);end if;
        insert into public.inventory_batch_balances_v483(tenant_id,batch_id,location_id,quantity,damaged_quantity,reserved_quantity,updated_at)
        values(p_tenant_id,v_batch_id,p_location_id,v_batch_qty,v_batch_damage,0,now())
        on conflict(tenant_id,batch_id,location_id) do update set quantity=excluded.quantity,damaged_quantity=excluded.damaged_quantity,reserved_quantity=0,updated_at=now();
        v_event_qty:=abs(v_batch_qty-v_old_qty)+abs(v_batch_damage-v_old_damage);
        if v_event_qty>0.000001 then
          insert into public.inventory_trace_events_v483(tenant_id,variant_id,batch_id,event_type,quantity,location_id,reference_number,source_key,metadata,created_by)
          values(p_tenant_id,v_variant,v_batch_id,'adjustment',v_event_qty,p_location_id,v_no,'stock-count:'||v_id::text||':batch:'||v_batch_id::text,
            jsonb_build_object('before_quantity',v_old_qty,'before_damaged',v_old_damage,'after_quantity',v_batch_qty,'after_damaged',v_batch_damage,'direction',case when v_batch_qty+v_batch_damage>=v_old_qty+v_old_damage then 'in' else 'out' end),auth.uid()) on conflict do nothing;
        end if;
        v_batch_total:=v_batch_total+v_batch_qty;v_batch_damage_total:=v_batch_damage_total+v_batch_damage;
      end loop;
      for br in
        select bb.batch_id,bb.quantity,coalesce(bb.damaged_quantity,0) damaged_quantity,b.batch_number
        from public.inventory_batch_balances_v483 bb join public.inventory_batches_v483 b on b.id=bb.batch_id and b.tenant_id=bb.tenant_id
        where bb.tenant_id=p_tenant_id and bb.location_id=p_location_id and b.variant_id=v_variant and (bb.quantity<>0 or coalesce(bb.damaged_quantity,0)<>0)
          and not (bb.batch_id=any(v_seen_batch)) for update of bb
      loop
        v_event_qty:=br.quantity+br.damaged_quantity;
        update public.inventory_batch_balances_v483 set quantity=0,damaged_quantity=0,reserved_quantity=0,updated_at=now() where tenant_id=p_tenant_id and batch_id=br.batch_id and location_id=p_location_id;
        if v_event_qty>0.000001 then
          insert into public.inventory_trace_events_v483(tenant_id,variant_id,batch_id,event_type,quantity,location_id,reference_number,source_key,metadata,created_by)
          values(p_tenant_id,v_variant,br.batch_id,'adjustment',v_event_qty,p_location_id,v_no,'stock-count:'||v_id::text||':batch-zero:'||br.batch_id::text,jsonb_build_object('direction','out','reason','batch missing during count','batch_number',br.batch_number),auth.uid()) on conflict do nothing;
        end if;
      end loop;
      update public.inventory_batches_v483 ib set status=case when exists(select 1 from public.inventory_batch_balances_v483 bb where bb.tenant_id=ib.tenant_id and bb.batch_id=ib.id and bb.quantity+coalesce(bb.damaged_quantity,0)>0) then 'active' else 'exhausted' end,updated_at=now()
      where ib.tenant_id=p_tenant_id and ib.variant_id=v_variant and ib.status in('active','exhausted');
      v_counted:=v_batch_total+v_batch_damage_total;
      v_tracking:=jsonb_build_object('batches',v_batches,'counted_saleable_quantity',v_batch_total,'counted_damaged_quantity',v_batch_damage_total);
    end if;

    v_delta:=v_counted-v_system;
    if abs(v_delta)>0.000001 then v_any_variance:=true;end if;
    insert into public.stock_count_items(count_id,variant_id,system_quantity,counted_quantity,tracking_mode,tracking_payload,system_reserved_quantity,system_damaged_quantity,system_quarantine_quantity,reconciliation_note)
    values(v_id,v_variant,v_system,v_counted,v_mode,coalesce(v_tracking,'{}'::jsonb),v_reserved,v_damage,v_quarantine,
      case when abs(v_delta)<=0.000001 then 'No quantity variance' else 'Ledger adjusted by '||v_delta::text end);

    if abs(v_delta)>0.000001 then
      perform public.inventory_adjust_stock(p_tenant_id,v_variant,v_delta,'Stock count • '||v_no);
      perform private.v4_location_stock_apply(p_tenant_id,p_location_id,v_variant,v_delta,'stock_count','stock_count',v_id,v_no,'Physical stock reconciliation',p_device_id,true);
    end if;
    if v_mode='serial' then
      update public.location_stock_balances set damaged_quantity=coalesce(v_serial_damage,0),quarantine_quantity=0,updated_at=now()
      where tenant_id=p_tenant_id and location_id=p_location_id and variant_id=v_variant;
    elsif v_mode='batch' then
      update public.location_stock_balances set damaged_quantity=coalesce(v_batch_damage_total,0),quarantine_quantity=0,updated_at=now()
      where tenant_id=p_tenant_id and location_id=p_location_id and variant_id=v_variant;
    end if;
  end loop;

  update public.stock_counts set status='posted',posted_by=auth.uid(),posted_at=now(),reconciliation_status=case when v_any_variance then 'variance' else 'reconciled' end,updated_at=now() where id=v_id;
  perform private.thq_sync_bump_v480(p_tenant_id,'inventory','stock_count',v_id::text,'posted');
  v_result:=jsonb_build_object('success',true,'count_id',v_id,'count_number',v_no,'status','posted','had_variance',v_any_variance);
  if nullif(trim(coalesce(p_request_id,'')),'') is not null then v_result:=private.v47_request_complete(p_tenant_id,p_request_id,'warehouse.stock_count',v_result);end if;
  return v_result;
end$$;


--
-- Name: inventory_stock_count_snapshot_v485(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_stock_count_snapshot_v485(p_tenant_id uuid, p_location_id uuid, p_query text DEFAULT ''::text) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare r record;q text:='%'||lower(trim(coalesce(p_query,'')))||'%';v_mode text;v_tracking jsonb;
begin
  perform private.v4_location_access(p_tenant_id,p_location_id,'view');
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'inventory.stock_count') and not private.erp_has_permission(p_tenant_id,'inventory.manage') then raise exception 'Stock count permission required';end if;
  for r in
    select b.variant_id,p.name product_name,pv.sku,coalesce(b.quantity,0) system_quantity,coalesce(b.reserved_quantity,0) reserved_quantity,
      coalesce(b.damaged_quantity,0) damaged_quantity,coalesce(b.quarantine_quantity,0) quarantine_quantity
    from public.location_stock_balances b
    join public.product_variants pv on pv.id=b.variant_id and pv.tenant_id=b.tenant_id
    join public.products p on p.id=pv.product_id
    where b.tenant_id=p_tenant_id and b.location_id=p_location_id and p.item_type='stock'
      and (trim(coalesce(p_query,''))='' or lower(p.name) like q or lower(pv.sku) like q or lower(coalesce(pv.barcode,'')) like q)
    order by p.name,pv.sku
  loop
    v_mode:=private.v483_tracking_mode(p_tenant_id,r.variant_id);
    if v_mode='serial' then
      select jsonb_build_object('serial_numbers',coalesce(jsonb_agg(jsonb_build_object('serial_number',s.serial_number,'status',s.status) order by s.serial_number),'[]'::jsonb)) into v_tracking
      from public.inventory_serials_v483 s
      where s.tenant_id=p_tenant_id and s.variant_id=r.variant_id and s.current_location_id=p_location_id and s.status in('in_stock','quarantine');
    elsif v_mode='batch' then
      select jsonb_build_object('batches',coalesce(jsonb_agg(jsonb_build_object(
        'batch_id',b.id,'batch_number',b.batch_number,'manufactured_on',b.manufactured_on,'expiry_on',b.expiry_on,
        'quantity',bb.quantity,'damaged_quantity',coalesce(bb.damaged_quantity,0),'reserved_quantity',coalesce(bb.reserved_quantity,0)
      ) order by (b.expiry_on is null),b.expiry_on,b.batch_number),'[]'::jsonb)) into v_tracking
      from public.inventory_batches_v483 b join public.inventory_batch_balances_v483 bb on bb.tenant_id=b.tenant_id and bb.batch_id=b.id
      where b.tenant_id=p_tenant_id and b.variant_id=r.variant_id and bb.location_id=p_location_id and (bb.quantity<>0 or coalesce(bb.damaged_quantity,0)<>0 or coalesce(bb.reserved_quantity,0)<>0);
    else
      v_tracking:='{}'::jsonb;
    end if;
    return next jsonb_build_object(
      'variant_id',r.variant_id,'product_name',r.product_name,'sku',r.sku,'tracking_mode',v_mode,
      'system_quantity',r.system_quantity,'reserved_quantity',r.reserved_quantity,'damaged_quantity',r.damaged_quantity,'quarantine_quantity',r.quarantine_quantity,
      'available_quantity',greatest(r.system_quantity-r.reserved_quantity-r.damaged_quantity-r.quarantine_quantity,0),
      'count_blocked',r.reserved_quantity>0,'tracking',coalesce(v_tracking,'{}'::jsonb)
    );
  end loop;
end$$;


--
-- Name: inventory_stock_integrity_v42(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_stock_integrity_v42(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v jsonb;begin
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'inventory.manage') then raise exception 'Inventory manage permission required';end if;
  with global_qty as (
    select variant_id,sum(quantity)::numeric qty from public.stock_balances where tenant_id=p_tenant_id group by variant_id
  ), location_qty as (
    select variant_id,sum(quantity)::numeric qty from public.location_stock_balances where tenant_id=p_tenant_id group by variant_id
  ), x as (
    select coalesce(g.variant_id,l.variant_id) variant_id,coalesce(g.qty,0) global_qty,coalesce(l.qty,0) location_qty
    from global_qty g full join location_qty l on l.variant_id=g.variant_id
  )
  select jsonb_build_object(
    'tenant_id',p_tenant_id,'checked_at',now(),'mismatch_count',count(*) filter(where abs(global_qty-location_qty)>0.000001),
    'mismatches',coalesce(jsonb_agg(jsonb_build_object('variant_id',x.variant_id,'sku',pv.sku,'global_quantity',x.global_qty,'location_quantity',x.location_qty,'difference',x.location_qty-x.global_qty)) filter(where abs(global_qty-location_qty)>0.000001),'[]'::jsonb)
  ) into v
  from x left join public.product_variants pv on pv.id=x.variant_id;
  return v;
end $$;


--
-- Name: inventory_stock_reconciliation_v485(uuid, uuid, text, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_stock_reconciliation_v485(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_query text DEFAULT ''::text, p_only_variance boolean DEFAULT false, p_limit integer DEFAULT 2000) RETURNS TABLE(location_id uuid, location_name text, variant_id uuid, product_name text, sku text, tracking_mode text, location_quantity numeric, tracked_quantity numeric, reserved_quantity numeric, damaged_quantity numeric, quarantine_quantity numeric, available_quantity numeric, company_stock_quantity numeric, all_locations_quantity numeric, tracked_reconciled boolean, company_reconciled boolean, latest_count_number text, latest_counted_quantity numeric, latest_count_variance numeric, latest_count_at timestamp with time zone, reconciliation_status text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare q text:='%'||lower(trim(coalesce(p_query,'')))||'%';
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  return query
  with base as (
    select b.location_id,l.location_code||' • '||l.name location_name,b.variant_id,p.name product_name,pv.sku,
      private.v483_tracking_mode(p_tenant_id,b.variant_id) tracking_mode,b.quantity,b.reserved_quantity,b.damaged_quantity,b.quarantine_quantity,
      coalesce((select sum(sb.quantity) from public.stock_balances sb where sb.tenant_id=p_tenant_id and sb.variant_id=b.variant_id),0) company_qty,
      coalesce((select sum(lb.quantity) from public.location_stock_balances lb where lb.tenant_id=p_tenant_id and lb.variant_id=b.variant_id),0) locations_qty
    from public.location_stock_balances b join public.business_locations l on l.id=b.location_id join public.product_variants pv on pv.id=b.variant_id join public.products p on p.id=pv.product_id
    where b.tenant_id=p_tenant_id and (p_location_id is null or b.location_id=p_location_id)
      and (trim(coalesce(p_query,''))='' or lower(p.name) like q or lower(pv.sku) like q or lower(coalesce(pv.barcode,'')) like q)
      and (private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'locations.view_all') or private.erp_has_permission(p_tenant_id,'locations.manage_all') or private.erp_user_location_allowed(p_tenant_id,b.location_id,'view'))
  ), calc as (
    select base.*,
      case when base.tracking_mode='none' then base.quantity else private.v483_location_tracked_quantity(p_tenant_id,base.variant_id,base.location_id,base.tracking_mode) end tracked_qty,
      lc.count_number latest_count_number,li.counted_quantity latest_counted_quantity,li.variance latest_count_variance,lc.posted_at latest_count_at
    from base
    left join lateral (
      select c.id,c.count_number,c.posted_at from public.stock_counts c join public.stock_count_items ci on ci.count_id=c.id
      where c.tenant_id=p_tenant_id and c.location_id=base.location_id and ci.variant_id=base.variant_id and c.status='posted'
      order by c.posted_at desc nulls last,c.created_at desc limit 1
    ) lc on true
    left join public.stock_count_items li on li.count_id=lc.id and li.variant_id=base.variant_id
  )
  select calc.location_id,calc.location_name,calc.variant_id,calc.product_name,calc.sku,calc.tracking_mode,
    calc.quantity,calc.tracked_qty,calc.reserved_quantity,calc.damaged_quantity,calc.quarantine_quantity,
    greatest(calc.quantity-calc.reserved_quantity-calc.damaged_quantity-calc.quarantine_quantity,0),calc.company_qty,calc.locations_qty,
    abs(calc.quantity-calc.tracked_qty)<=0.000001,abs(calc.company_qty-calc.locations_qty)<=0.000001,
    calc.latest_count_number,calc.latest_counted_quantity,calc.latest_count_variance,calc.latest_count_at,
    case
      when abs(calc.company_qty-calc.locations_qty)>0.000001 then 'COMPANY/LOCATION MISMATCH'
      when calc.tracking_mode<>'none' and abs(calc.quantity-calc.tracked_qty)>0.000001 then 'TRACKING MISMATCH'
      when calc.reserved_quantity>0.000001 then 'RESERVED / PENDING TRANSFER'
      when calc.latest_count_variance is not null and abs(calc.latest_count_variance)>0.000001 then 'COUNT VARIANCE RECONCILED'
      else 'OK'
    end
  from calc
  where not coalesce(p_only_variance,false)
     or abs(calc.company_qty-calc.locations_qty)>0.000001
     or (calc.tracking_mode<>'none' and abs(calc.quantity-calc.tracked_qty)>0.000001)
     or abs(coalesce(calc.latest_count_variance,0))>0.000001
  order by case when abs(calc.company_qty-calc.locations_qty)>0.000001 or (calc.tracking_mode<>'none' and abs(calc.quantity-calc.tracked_qty)>0.000001) then 0 else 1 end,calc.location_name,calc.product_name,calc.sku
  limit greatest(1,least(coalesce(p_limit,2000),10000));
end$$;


--
-- Name: inventory_tracking_policy_save_v483(uuid, uuid, text, boolean, integer, integer, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_tracking_policy_save_v483(p_tenant_id uuid, p_variant_id uuid, p_tracking_mode text, p_warranty_enabled boolean, p_warranty_months integer, p_warranty_days integer, p_require_batch_expiry boolean DEFAULT false, p_allow_expired_sale boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_mode text:=lower(trim(coalesce(p_tracking_mode,'none')));v_current_mode text;begin
 if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'inventory.manage') then raise exception 'Inventory manage permission required';end if;
 if v_mode not in('none','serial','batch') then raise exception 'Tracking mode must be none, serial or batch';end if;
 if not exists(select 1 from public.product_variants pv join public.products p on p.id=pv.product_id where pv.tenant_id=p_tenant_id and pv.id=p_variant_id and p.item_type='stock') then raise exception 'Serial/batch tracking is available only for stock products';end if;
 if coalesce(p_warranty_months,0)<0 or coalesce(p_warranty_days,0)<0 then raise exception 'Warranty period cannot be negative';end if;
 if coalesce(p_warranty_enabled,false) and v_mode='none' then raise exception 'Warranty tracking requires serial or batch tracking';end if;
 if coalesce(p_warranty_enabled,false) and coalesce(p_warranty_months,0)=0 and coalesce(p_warranty_days,0)=0 then raise exception 'Set a warranty period when warranty tracking is enabled';end if;
 select tracking_mode into v_current_mode from public.product_tracking_policies_v483 where tenant_id=p_tenant_id and variant_id=p_variant_id;
 if v_current_mode in('serial','batch') and v_current_mode<>v_mode and exists(select 1 from public.inventory_trace_events_v483 where tenant_id=p_tenant_id and variant_id=p_variant_id) then
  raise exception 'Tracking mode cannot be changed after serial/batch history exists';
 end if;
 if v_mode='none' and exists(select 1 from public.inventory_serials_v483 where tenant_id=p_tenant_id and variant_id=p_variant_id and status in('in_stock','sold','returned')) then raise exception 'Serial history exists for this product; tracking cannot be disabled';end if;
 if v_mode='none' and exists(select 1 from public.inventory_batches_v483 b join public.inventory_batch_balances_v483 bb on bb.batch_id=b.id and bb.tenant_id=b.tenant_id where b.tenant_id=p_tenant_id and b.variant_id=p_variant_id and bb.quantity>0) then raise exception 'Batch stock exists for this product; tracking cannot be disabled';end if;
 insert into public.product_tracking_policies_v483(tenant_id,variant_id,tracking_mode,warranty_enabled,warranty_months,warranty_days,require_batch_expiry,allow_expired_sale,updated_at)
 values(p_tenant_id,p_variant_id,v_mode,coalesce(p_warranty_enabled,false),coalesce(p_warranty_months,0),coalesce(p_warranty_days,0),case when v_mode='batch' then coalesce(p_require_batch_expiry,false) else false end,case when v_mode='batch' then coalesce(p_allow_expired_sale,false) else false end,now())
 on conflict(tenant_id,variant_id) do update set tracking_mode=excluded.tracking_mode,warranty_enabled=excluded.warranty_enabled,warranty_months=excluded.warranty_months,warranty_days=excluded.warranty_days,require_batch_expiry=excluded.require_batch_expiry,allow_expired_sale=excluded.allow_expired_sale,updated_at=now();
 perform private.thq_sync_bump_v480(p_tenant_id,'catalogue','tracking_policy',p_variant_id::text,'save');
 return public.inventory_tracking_policy_v483(p_tenant_id,p_variant_id);
end$$;


--
-- Name: inventory_tracking_policy_v483(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_tracking_policy_v483(p_tenant_id uuid, p_variant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v public.product_tracking_policies_v483%rowtype;begin
 if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
 if not exists(select 1 from public.product_variants where tenant_id=p_tenant_id and id=p_variant_id) then raise exception 'Product not found';end if;
 select * into v from public.product_tracking_policies_v483 where tenant_id=p_tenant_id and variant_id=p_variant_id;
 return jsonb_build_object(
  'variant_id',p_variant_id,'tracking_mode',coalesce(v.tracking_mode,'none'),
  'warranty_enabled',coalesce(v.warranty_enabled,false),'warranty_months',coalesce(v.warranty_months,0),'warranty_days',coalesce(v.warranty_days,0),
  'require_batch_expiry',coalesce(v.require_batch_expiry,false),'allow_expired_sale',coalesce(v.allow_expired_sale,false)
 );
end$$;


--
-- Name: inventory_tracking_reconciliation_v483(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_tracking_reconciliation_v483(p_tenant_id uuid, p_variant_id uuid, p_location_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_mode text;v_stock numeric;v_tracked numeric;begin
 perform private.v4_location_access(p_tenant_id,p_location_id,'view');
 if not exists(select 1 from public.product_variants where tenant_id=p_tenant_id and id=p_variant_id) then raise exception 'Product not found';end if;
 v_mode:=private.v483_tracking_mode(p_tenant_id,p_variant_id);
 select coalesce(quantity,0) into v_stock from public.location_stock_balances where tenant_id=p_tenant_id and location_id=p_location_id and variant_id=p_variant_id;
 v_stock:=coalesce(v_stock,0);v_tracked:=private.v483_location_tracked_quantity(p_tenant_id,p_variant_id,p_location_id,v_mode);
 return jsonb_build_object('tracking_mode',v_mode,'stock_quantity',v_stock,'tracked_quantity',v_tracked,'difference',v_stock-v_tracked,'reconciled',v_mode='none' or abs(v_stock-v_tracked)<=0.000001);
end$$;


--
-- Name: inventory_tracking_register_opening_v483(uuid, uuid, uuid, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_tracking_register_opening_v483(p_tenant_id uuid, p_variant_id uuid, p_location_id uuid, p_serial_numbers jsonb DEFAULT '[]'::jsonb, p_batches jsonb DEFAULT '[]'::jsonb, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_mode text;v_stock numeric;v_existing numeric;v_count numeric;v_sum numeric;x jsonb;v_serial text;v_batch text;v_qty numeric;v_batch_id uuid;v_serial_id uuid;v_expiry date;v_mfg date;v_seen_serials text[]:='{}'::text[];v_seen_batches text[]:='{}'::text[];begin
 if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'inventory.manage') then raise exception 'Inventory manage permission required';end if;
 perform private.v4_location_access(p_tenant_id,p_location_id,'manage');
 v_mode:=private.v483_tracking_mode(p_tenant_id,p_variant_id);if v_mode='none' then raise exception 'Enable serial or batch tracking first';end if;
 select coalesce(quantity,0) into v_stock from public.location_stock_balances where tenant_id=p_tenant_id and location_id=p_location_id and variant_id=p_variant_id for update;v_stock:=coalesce(v_stock,0);
 v_existing:=private.v483_location_tracked_quantity(p_tenant_id,p_variant_id,p_location_id,v_mode);
 if abs(v_existing-v_stock)<=0.000001 then return jsonb_build_object('registered',0,'reconciled',true,'stock_quantity',v_stock,'tracked_quantity',v_existing);end if;
 if v_existing<>0 then raise exception 'Existing tracked quantity (%) does not match stock (%). Opening registration is only allowed from zero tracked quantity',v_existing,v_stock;end if;
 if v_mode='serial' then
  if v_stock<>trunc(v_stock) then raise exception 'Serial-tracked stock must be a whole base-unit quantity';end if;
  select count(*)::numeric into v_count from jsonb_array_elements(coalesce(p_serial_numbers,'[]'::jsonb));if v_count<>v_stock then raise exception 'Register exactly % serial numbers to match current stock',v_stock;end if;
  for x in select value from jsonb_array_elements(coalesce(p_serial_numbers,'[]'::jsonb)) loop
   v_serial:=trim(coalesce(case when jsonb_typeof(x)='string' then x#>>'{}' else x->>'serial_number' end,''));if v_serial='' then raise exception 'Serial number cannot be blank';end if;
   if lower(v_serial)=any(v_seen_serials) then raise exception 'Duplicate serial number % in opening registration',v_serial;end if;v_seen_serials:=array_append(v_seen_serials,lower(v_serial));
   insert into public.inventory_serials_v483(tenant_id,variant_id,serial_number,status,current_location_id,received_at,notes,created_by) values(p_tenant_id,p_variant_id,v_serial,'in_stock',p_location_id,now(),nullif(trim(coalesce(p_note,'')),''),auth.uid()) returning id into v_serial_id;
   insert into public.inventory_trace_events_v483(tenant_id,variant_id,serial_id,event_type,quantity,location_id,source_key,metadata,created_by) values(p_tenant_id,p_variant_id,v_serial_id,'opening',1,p_location_id,'opening:'||p_location_id::text||':serial:'||v_serial_id::text,jsonb_build_object('note',nullif(trim(coalesce(p_note,'')),'')),auth.uid());
  end loop;
 else
  select coalesce(sum(coalesce(nullif(value->>'quantity','')::numeric,0)),0) into v_sum from jsonb_array_elements(coalesce(p_batches,'[]'::jsonb));if abs(v_sum-v_stock)>0.000001 then raise exception 'Batch quantities must total current stock %; received %',v_stock,v_sum;end if;
  for x in select value from jsonb_array_elements(coalesce(p_batches,'[]'::jsonb)) loop
   v_batch:=trim(coalesce(x->>'batch_number',''));v_qty:=coalesce(nullif(x->>'quantity','')::numeric,0);v_expiry:=nullif(x->>'expiry_on','')::date;v_mfg:=nullif(x->>'manufactured_on','')::date;
   if v_batch='' or v_qty<=0 then raise exception 'Each batch requires a batch number and positive quantity';end if;
   if lower(v_batch)=any(v_seen_batches) then raise exception 'Duplicate batch % in opening registration',v_batch;end if;v_seen_batches:=array_append(v_seen_batches,lower(v_batch));
   if coalesce((select require_batch_expiry from public.product_tracking_policies_v483 where tenant_id=p_tenant_id and variant_id=p_variant_id),false) and v_expiry is null then raise exception 'Expiry date is required for batch %',v_batch;end if;
   insert into public.inventory_batches_v483(tenant_id,variant_id,batch_number,manufactured_on,expiry_on,notes,created_by) values(p_tenant_id,p_variant_id,v_batch,v_mfg,v_expiry,nullif(trim(coalesce(p_note,'')),''),auth.uid()) on conflict(tenant_id,variant_id,lower(trim(batch_number))) do update set manufactured_on=coalesce(public.inventory_batches_v483.manufactured_on,excluded.manufactured_on),expiry_on=coalesce(public.inventory_batches_v483.expiry_on,excluded.expiry_on),status='active',updated_at=now() returning id into v_batch_id;
   if exists(select 1 from public.inventory_batches_v483 where id=v_batch_id and ((manufactured_on is not null and v_mfg is not null and manufactured_on<>v_mfg) or (expiry_on is not null and v_expiry is not null and expiry_on<>v_expiry))) then raise exception 'Batch % already exists with different manufacture/expiry dates',v_batch;end if;
   insert into public.inventory_batch_balances_v483(tenant_id,batch_id,location_id,quantity) values(p_tenant_id,v_batch_id,p_location_id,v_qty) on conflict(tenant_id,batch_id,location_id) do update set quantity=public.inventory_batch_balances_v483.quantity+excluded.quantity,updated_at=now();
   insert into public.inventory_trace_events_v483(tenant_id,variant_id,batch_id,event_type,quantity,location_id,source_key,metadata,created_by) values(p_tenant_id,p_variant_id,v_batch_id,'opening',v_qty,p_location_id,'opening:'||p_location_id::text||':batch:'||v_batch_id::text,jsonb_build_object('note',nullif(trim(coalesce(p_note,'')),'')),auth.uid());
  end loop;
 end if;
 perform private.thq_sync_bump_v480(p_tenant_id,'inventory','tracking_opening',p_variant_id::text,'register');
 return public.inventory_tracking_reconciliation_v483(p_tenant_id,p_variant_id,p_location_id);
end$$;


--
-- Name: inventory_transfer_approve_v42(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_transfer_approve_v42(p_tenant_id uuid, p_transfer_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$begin
  perform public.inventory_transfer_decide_v485(p_tenant_id,p_transfer_id,true,null);
end$$;


--
-- Name: inventory_transfer_cancel_v42(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_transfer_cancel_v42(p_tenant_id uuid, p_transfer_id uuid, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$begin
  perform public.inventory_transfer_cancel_v485(p_tenant_id,p_transfer_id,p_reason);
end$$;


--
-- Name: inventory_transfer_cancel_v485(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_transfer_cancel_v485(p_tenant_id uuid, p_transfer_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v public.stock_transfers%rowtype;
begin
  select * into v from public.stock_transfers where tenant_id=p_tenant_id and id=p_transfer_id for update;
  if not found then raise exception 'Transfer not found';end if;
  perform private.v4_location_access(p_tenant_id,v.from_location_id,'view');
  if v.status not in('draft','requested','approved') then raise exception 'In-transit/received transfers cannot be cancelled';end if;
  if auth.uid()<>v.created_by and not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'inventory.manage') then raise exception 'Transfer cancel permission required';end if;
  perform private.v485_transfer_release_reservation(v.id,p_reason);
  update public.stock_transfers set status='cancelled',cancelled_by=auth.uid(),cancelled_at=now(),cancel_reason=nullif(trim(coalesce(p_reason,'')),''),updated_at=now() where id=v.id;
  perform private.v485_transfer_history_add(p_tenant_id,v.id,'cancelled',v.status,'cancelled',p_reason);
  perform private.thq_sync_bump_v480(p_tenant_id,'inventory','stock_transfer',v.id::text,'cancelled');
  return jsonb_build_object('success',true,'transfer_id',v.id,'transfer_number',v.transfer_number,'status','cancelled');
end$$;


--
-- Name: inventory_transfer_create_v4(uuid, uuid, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_transfer_create_v4(p_tenant_id uuid, p_from_location_id uuid, p_to_location_id uuid, p_items jsonb, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $_$select public.inventory_transfer_create_v42($1,$2,$3,$4,$5)$_$;


--
-- Name: inventory_transfer_create_v42(uuid, uuid, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_transfer_create_v42(p_tenant_id uuid, p_from_location_id uuid, p_to_location_id uuid, p_items jsonb, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v_id uuid:=gen_random_uuid();v_no text;x jsonb;v_qty numeric;v_available numeric;begin
  perform private.v4_location_access(p_tenant_id,p_from_location_id,'operate');
  perform private.v4_location_access(p_tenant_id,p_to_location_id,'view');
  if p_from_location_id=p_to_location_id then raise exception 'Source and destination must be different';end if;
  if not private.erp_has_permission(p_tenant_id,'inventory.transfer') and not private.erp_has_permission(p_tenant_id,'inventory.manage') and not private.erp_user_is_owner(p_tenant_id) then raise exception 'Stock transfer permission required';end if;
  if jsonb_array_length(coalesce(p_items,'[]'::jsonb))=0 then raise exception 'Add at least one transfer item';end if;

  v_no:='TRF-'||lpad(nextval('public.stock_transfer_number_seq')::text,6,'0');
  insert into public.stock_transfers(id,tenant_id,transfer_number,from_location_id,to_location_id,status,notes,created_by,requested_by,requested_at,reservation_applied)
  values(v_id,p_tenant_id,v_no,p_from_location_id,p_to_location_id,'requested',nullif(trim(coalesce(p_notes,'')),''),auth.uid(),auth.uid(),now(),true);

  for x in select value from jsonb_array_elements(p_items) loop
    v_qty:=coalesce((x->>'quantity')::numeric,0);
    if v_qty<=0 then raise exception 'Transfer quantity must be positive';end if;
    if not exists(select 1 from public.product_variants where id=(x->>'variant_id')::uuid and tenant_id=p_tenant_id) then raise exception 'Product does not belong to this business';end if;

    insert into public.location_stock_balances(tenant_id,location_id,variant_id)
    values(p_tenant_id,p_from_location_id,(x->>'variant_id')::uuid) on conflict do nothing;

    select quantity-reserved_quantity-damaged_quantity-quarantine_quantity into v_available
    from public.location_stock_balances
    where tenant_id=p_tenant_id and location_id=p_from_location_id and variant_id=(x->>'variant_id')::uuid
    for update;
    if coalesce(v_available,0)<v_qty then raise exception 'Insufficient available stock. Available: %, requested: %',coalesce(v_available,0),v_qty;end if;

    update public.location_stock_balances set reserved_quantity=reserved_quantity+v_qty,updated_at=now()
    where tenant_id=p_tenant_id and location_id=p_from_location_id and variant_id=(x->>'variant_id')::uuid;
    insert into public.stock_transfer_items(transfer_id,variant_id,quantity,note)
    values(v_id,(x->>'variant_id')::uuid,v_qty,nullif(trim(coalesce(x->>'note','')),''));
  end loop;
  return jsonb_build_object('transfer_id',v_id,'transfer_number',v_no,'status','requested');
exception when others then
  -- The surrounding transaction rolls back reservations/items automatically.
  raise;
end $$;


--
-- Name: inventory_transfer_create_v47(uuid, uuid, uuid, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_transfer_create_v47(p_tenant_id uuid, p_from_location_id uuid, p_to_location_id uuid, p_items jsonb, p_notes text, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v jsonb;begin v:=private.v47_request_existing(p_tenant_id,p_request_id,'inventory.transfer');if v is not null then return v;end if;v:=public.inventory_transfer_create_v4(p_tenant_id,p_from_location_id,p_to_location_id,p_items,p_notes);return private.v47_request_complete(p_tenant_id,p_request_id,'inventory.transfer',v);end$$;


--
-- Name: inventory_transfer_create_v483(uuid, uuid, uuid, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_transfer_create_v483(p_tenant_id uuid, p_from_location_id uuid, p_to_location_id uuid, p_items jsonb, p_notes text, p_request_id text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $_$
  select public.inventory_transfer_request_v485($1,$2,$3,$4,$5,null,null,$6)
$_$;


--
-- Name: inventory_transfer_decide_v485(uuid, uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_transfer_decide_v485(p_tenant_id uuid, p_transfer_id uuid, p_approve boolean, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v public.stock_transfers%rowtype;v_to text;
begin
  select * into v from public.stock_transfers where tenant_id=p_tenant_id and id=p_transfer_id for update;
  if not found then raise exception 'Transfer not found';end if;
  perform private.v4_location_access(p_tenant_id,v.from_location_id,'manage');
  perform private.warehouse_v485_permission(p_tenant_id,true);
  if v.status<>'requested' then raise exception 'Only requested transfers can be approved or rejected';end if;
  if coalesce(p_approve,false) then
    update public.stock_transfers set status='approved',approved_by=auth.uid(),approved_at=now(),updated_at=now() where id=v.id;
    v_to:='approved';
    perform private.v485_transfer_history_add(p_tenant_id,v.id,'approved','requested','approved',p_note);
  else
    if trim(coalesce(p_note,''))='' then raise exception 'Rejection reason is required';end if;
    perform private.v485_transfer_release_reservation(v.id,p_note);
    update public.stock_transfers set status='rejected',rejected_by=auth.uid(),rejected_at=now(),rejection_reason=trim(p_note),updated_at=now() where id=v.id;
    v_to:='rejected';
    perform private.v485_transfer_history_add(p_tenant_id,v.id,'rejected','requested','rejected',p_note);
  end if;
  perform private.thq_sync_bump_v480(p_tenant_id,'inventory','stock_transfer',v.id::text,v_to);
  return jsonb_build_object('success',true,'transfer_id',v.id,'transfer_number',v.transfer_number,'status',v_to);
end$$;


--
-- Name: inventory_transfer_detail_v42(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_transfer_detail_v42(p_tenant_id uuid, p_transfer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v jsonb;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  select jsonb_build_object(
    'id',t.id,'transfer_number',t.transfer_number,'status',t.status,'notes',t.notes,
    'from_location_id',t.from_location_id,'from_location',fl.location_code||' • '||fl.name,
    'to_location_id',t.to_location_id,'to_location',tl.location_code||' • '||tl.name,
    'requested_at',t.requested_at,'approved_at',t.approved_at,'dispatched_at',t.dispatched_at,'received_at',t.received_at,
    'rejected_at',t.rejected_at,'rejection_reason',t.rejection_reason,'cancelled_at',t.cancelled_at,'cancel_reason',t.cancel_reason,
    'items',coalesce((select jsonb_agg(jsonb_build_object('variant_id',i.variant_id,'sku',pv.sku,'product_name',p.name,'quantity',i.quantity,'dispatched_quantity',i.dispatched_quantity,'received_quantity',i.received_quantity,'note',i.note) order by p.name,pv.sku)
      from public.stock_transfer_items i join public.product_variants pv on pv.id=i.variant_id join public.products p on p.id=pv.product_id where i.transfer_id=t.id),'[]'::jsonb)
  ) into v
  from public.stock_transfers t join public.business_locations fl on fl.id=t.from_location_id join public.business_locations tl on tl.id=t.to_location_id
  where t.id=p_transfer_id and t.tenant_id=p_tenant_id
    and (private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'locations.view_all') or private.erp_has_permission(p_tenant_id,'locations.manage_all') or private.erp_user_location_allowed(p_tenant_id,t.from_location_id,'view') or private.erp_user_location_allowed(p_tenant_id,t.to_location_id,'view'));
  if v is null then raise exception 'Transfer not found or access denied';end if;
  return v;
end $$;


--
-- Name: inventory_transfer_detail_v485(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_transfer_detail_v485(p_tenant_id uuid, p_transfer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v jsonb;v_from uuid;v_to uuid;
begin
  select from_location_id,to_location_id into v_from,v_to
  from public.stock_transfers
  where tenant_id=p_tenant_id and id=p_transfer_id;

  if v_from is null then
    raise exception 'Transfer not found';
  end if;

  if not (
    private.erp_user_is_owner(p_tenant_id)
    or private.erp_has_permission(p_tenant_id,'locations.view_all')
    or private.erp_has_permission(p_tenant_id,'locations.manage_all')
    or private.erp_user_location_allowed(p_tenant_id,v_from,'view')
    or private.erp_user_location_allowed(p_tenant_id,v_to,'view')
  ) then
    raise exception 'Access denied';
  end if;

  select jsonb_build_object(
    'transfer',
    to_jsonb(t) || jsonb_build_object(
      'status',case when t.status='dispatched' then 'in_transit' else t.status end,
      'from_location',fl.location_code||' • '||fl.name,
      'to_location',tl.location_code||' • '||tl.name,
      'from_is_warehouse',(fl.hierarchy_role='warehouse' or fl.location_type='warehouse'),
      'to_is_warehouse',(tl.hierarchy_role='warehouse' or tl.location_type='warehouse')
    ),

    'items',
    coalesce(
      (
        select jsonb_agg(
          to_jsonb(i) || jsonb_build_object(
            'product_name', p.name,
            'sku', pv.sku,
            'allocations',
            coalesce(
              (
                select jsonb_agg(
                  jsonb_build_object(
                    'id',a.id,
                    'status',a.status,
                    'quantity',a.quantity,
                    'serial_id',a.serial_id,
                    'serial_number',s.serial_number,
                    'batch_id',a.batch_id,
                    'batch_number',b.batch_number,
                    'expiry_on',b.expiry_on
                  )
                  order by coalesce(s.serial_number,b.batch_number), a.id
                )
                from public.stock_transfer_allocations_v485 a
                left join public.inventory_serials_v483 s on s.id=a.serial_id
                left join public.inventory_batches_v483 b on b.id=a.batch_id
                where a.transfer_item_id=i.id
              ),
              '[]'::jsonb
            )
          )
          order by p.name, pv.sku
        )
        from public.stock_transfer_items i
        join public.product_variants pv on pv.id=i.variant_id
        join public.products p on p.id=pv.product_id
        where i.transfer_id=t.id
      ),
      '[]'::jsonb
    ),

    'history',
    coalesce(
      (
        select jsonb_agg(
          to_jsonb(h)
          order by h.created_at, h.id
        )
        from public.stock_transfer_history_v485 h
        where h.transfer_id=t.id
      ),
      '[]'::jsonb
    )
  )
  into v
  from public.stock_transfers t
  join public.business_locations fl on fl.id=t.from_location_id
  join public.business_locations tl on tl.id=t.to_location_id
  where t.tenant_id=p_tenant_id and t.id=p_transfer_id;

  return v;
end$$;


--
-- Name: inventory_transfer_dispatch_v4(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_transfer_dispatch_v4(p_tenant_id uuid, p_transfer_id uuid, p_device_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$begin
  perform public.inventory_transfer_dispatch_v485(p_tenant_id,p_transfer_id,p_device_id,null,null);
end$$;


--
-- Name: inventory_transfer_dispatch_v485(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_transfer_dispatch_v485(p_tenant_id uuid, p_transfer_id uuid, p_device_id uuid DEFAULT NULL::uuid, p_dispatch_note text DEFAULT NULL::text, p_transport_reference text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v public.stock_transfers%rowtype;r public.stock_transfer_items%rowtype;a record;v_reserved numeric;v_serial text;v_batch text;
begin
  select * into v from public.stock_transfers where tenant_id=p_tenant_id and id=p_transfer_id for update;
  if not found then raise exception 'Transfer not found';end if;
  perform private.v4_location_access(p_tenant_id,v.from_location_id,'operate');
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'inventory.transfer') and not private.erp_has_permission(p_tenant_id,'inventory.manage') then raise exception 'Stock transfer permission required';end if;
  if v.status in('in_transit','dispatched') then
    return jsonb_build_object('success',true,'transfer_id',v.id,'transfer_number',v.transfer_number,'status','in_transit','idempotent',true);
  end if;
  if v.status<>'approved' then raise exception 'Only approved transfers can be dispatched';end if;
  if not coalesce(v.reservation_applied,false) then raise exception 'Transfer reservation is missing; cancel and recreate this transfer';end if;

  for r in select * from public.stock_transfer_items where transfer_id=v.id order by id loop
    select reserved_quantity into v_reserved from public.location_stock_balances
      where tenant_id=p_tenant_id and location_id=v.from_location_id and variant_id=r.variant_id for update;
    if coalesce(v_reserved,0)+0.000001<r.quantity then raise exception 'Reserved stock is inconsistent for transfer line %',r.id;end if;

    if r.tracking_mode='serial' then
      if (select count(*) from public.stock_transfer_allocations_v485 where transfer_item_id=r.id and status='reserved' and serial_id is not null)<>r.quantity::bigint then
        raise exception 'Serial allocation is incomplete for transfer line %',r.id;
      end if;
    elsif r.tracking_mode='batch' then
      if abs(coalesce((select sum(quantity) from public.stock_transfer_allocations_v485 where transfer_item_id=r.id and status='reserved' and batch_id is not null),0)-r.quantity)>0.000001 then
        raise exception 'Batch allocation is incomplete for transfer line %',r.id;
      end if;
    end if;

    -- Release the aggregate reservation immediately before removing the source stock.
    update public.location_stock_balances set reserved_quantity=greatest(0,reserved_quantity-r.quantity),updated_at=now()
      where tenant_id=p_tenant_id and location_id=v.from_location_id and variant_id=r.variant_id;
    perform private.v4_location_stock_apply(p_tenant_id,v.from_location_id,r.variant_id,-r.quantity,'transfer_out','stock_transfer',v.id,v.transfer_number,'Dispatched / in transit',p_device_id,false);
    update public.stock_transfer_items set dispatched_quantity=r.quantity,updated_at=now() where id=r.id;

    for a in select * from public.stock_transfer_allocations_v485 where transfer_item_id=r.id and status='reserved' order by id loop
      if a.serial_id is not null then
        select serial_number into v_serial from public.inventory_serials_v483
          where id=a.serial_id and tenant_id=p_tenant_id and status='in_stock' and current_location_id=v.from_location_id and reserved_transfer_id=v.id for update;
        if v_serial is null then raise exception 'Reserved serial allocation changed before dispatch';end if;
        update public.inventory_serials_v483
          set status='in_transit',current_location_id=null,reserved_transfer_id=null,updated_at=now()
          where id=a.serial_id;
        insert into public.inventory_trace_events_v483(
          tenant_id,variant_id,serial_id,event_type,quantity,location_id,reference_number,source_key,metadata,transfer_id,transfer_item_id,created_by
        ) values(
          p_tenant_id,r.variant_id,a.serial_id,'transfer_out',1,v.from_location_id,v.transfer_number,
          'transfer:'||v.id::text||':out:serial:'||a.serial_id::text,
          jsonb_build_object('from_location_id',v.from_location_id,'to_location_id',v.to_location_id,'serial_number',v_serial),v.id,r.id,auth.uid()
        ) on conflict do nothing;
      elsif a.batch_id is not null then
        select b.batch_number into v_batch from public.inventory_batches_v483 b where b.id=a.batch_id and b.tenant_id=p_tenant_id;
        update public.inventory_batch_balances_v483
          set reserved_quantity=greatest(0,reserved_quantity-a.quantity),quantity=quantity-a.quantity,updated_at=now()
          where tenant_id=p_tenant_id and batch_id=a.batch_id and location_id=v.from_location_id
            and reserved_quantity+0.000001>=a.quantity and quantity+0.000001>=a.quantity;
        if not found then raise exception 'Reserved batch allocation changed before dispatch: %',coalesce(v_batch,a.batch_id::text);end if;
        insert into public.inventory_trace_events_v483(
          tenant_id,variant_id,batch_id,event_type,quantity,location_id,reference_number,source_key,metadata,transfer_id,transfer_item_id,created_by
        ) values(
          p_tenant_id,r.variant_id,a.batch_id,'transfer_out',a.quantity,v.from_location_id,v.transfer_number,
          'transfer:'||v.id::text||':out:batch:'||a.batch_id::text,
          jsonb_build_object('from_location_id',v.from_location_id,'to_location_id',v.to_location_id,'batch_number',v_batch),v.id,r.id,auth.uid()
        ) on conflict do nothing;
      end if;
      update public.stock_transfer_allocations_v485 set status='in_transit',dispatched_at=now(),updated_at=now() where id=a.id;
    end loop;
  end loop;

  update public.stock_transfers
    set status='in_transit',reservation_applied=false,dispatched_by=auth.uid(),dispatched_at=now(),in_transit_at=now(),
        dispatch_note=nullif(trim(coalesce(p_dispatch_note,'')),''),
        transport_reference=coalesce(nullif(trim(coalesce(p_transport_reference,'')),''),transport_reference),updated_at=now()
    where id=v.id;
  perform private.v485_transfer_history_add(p_tenant_id,v.id,'dispatched','approved','in_transit',p_dispatch_note,jsonb_build_object('transport_reference',coalesce(nullif(trim(coalesce(p_transport_reference,'')),''),v.transport_reference)));
  perform private.thq_sync_bump_v480(p_tenant_id,'inventory','stock_transfer',v.id::text,'in_transit');
  return jsonb_build_object('success',true,'transfer_id',v.id,'transfer_number',v.transfer_number,'status','in_transit');
end$$;


--
-- Name: inventory_transfer_history_v485(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_transfer_history_v485(p_tenant_id uuid, p_transfer_id uuid) RETURNS TABLE(event_id uuid, event_type text, from_status text, to_status text, note text, metadata jsonb, changed_by uuid, occurred_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_from uuid;v_to uuid;
begin
  select from_location_id,to_location_id into v_from,v_to from public.stock_transfers where tenant_id=p_tenant_id and id=p_transfer_id;
  if v_from is null then raise exception 'Transfer not found';end if;
  if not (private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'locations.view_all') or private.erp_has_permission(p_tenant_id,'locations.manage_all') or private.erp_user_location_allowed(p_tenant_id,v_from,'view') or private.erp_user_location_allowed(p_tenant_id,v_to,'view')) then raise exception 'Access denied';end if;
  return query select h.id,h.event_type,h.from_status,h.to_status,h.note,h.metadata,h.changed_by,h.created_at
    from public.stock_transfer_history_v485 h where h.tenant_id=p_tenant_id and h.transfer_id=p_transfer_id order by h.created_at,h.id;
end$$;


--
-- Name: inventory_transfer_receive_v4(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_transfer_receive_v4(p_tenant_id uuid, p_transfer_id uuid, p_device_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$begin
  perform public.inventory_transfer_receive_v485(p_tenant_id,p_transfer_id,p_device_id,null);
end$$;


--
-- Name: inventory_transfer_receive_v485(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_transfer_receive_v485(p_tenant_id uuid, p_transfer_id uuid, p_device_id uuid DEFAULT NULL::uuid, p_receive_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v public.stock_transfers%rowtype;r public.stock_transfer_items%rowtype;a record;v_serial text;v_batch text;
begin
  select * into v from public.stock_transfers where tenant_id=p_tenant_id and id=p_transfer_id for update;
  if not found then raise exception 'Transfer not found';end if;
  perform private.v4_location_access(p_tenant_id,v.to_location_id,'operate');
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'inventory.transfer') and not private.erp_has_permission(p_tenant_id,'inventory.manage') then raise exception 'Stock transfer permission required';end if;
  if v.status='received' then
    return jsonb_build_object('success',true,'transfer_id',v.id,'transfer_number',v.transfer_number,'status','received','idempotent',true);
  end if;
  if v.status not in('in_transit','dispatched') then raise exception 'Only in-transit transfers can be received';end if;

  for r in select * from public.stock_transfer_items where transfer_id=v.id order by id loop
    if r.dispatched_quantity<=0 then raise exception 'Transfer line % was not dispatched',r.id;end if;
    perform public.inventory_location_assign_v4(p_tenant_id,v.to_location_id,r.variant_id,true,null,null,null);
    perform private.v4_location_stock_apply(p_tenant_id,v.to_location_id,r.variant_id,r.dispatched_quantity,'transfer_in','stock_transfer',v.id,v.transfer_number,'Received from transfer',p_device_id,false);

    for a in select * from public.stock_transfer_allocations_v485 where transfer_item_id=r.id and status='in_transit' order by id loop
      if a.serial_id is not null then
        select serial_number into v_serial from public.inventory_serials_v483 where id=a.serial_id and tenant_id=p_tenant_id and status='in_transit' for update;
        if v_serial is null then raise exception 'In-transit serial allocation is missing';end if;
        update public.inventory_serials_v483
          set status='in_stock',current_location_id=v.to_location_id,reserved_transfer_id=null,updated_at=now()
          where id=a.serial_id;
        insert into public.inventory_trace_events_v483(
          tenant_id,variant_id,serial_id,event_type,quantity,location_id,reference_number,source_key,metadata,transfer_id,transfer_item_id,created_by
        ) values(
          p_tenant_id,r.variant_id,a.serial_id,'transfer_in',1,v.to_location_id,v.transfer_number,
          'transfer:'||v.id::text||':in:serial:'||a.serial_id::text,
          jsonb_build_object('from_location_id',v.from_location_id,'to_location_id',v.to_location_id,'serial_number',v_serial),v.id,r.id,auth.uid()
        ) on conflict do nothing;
      elsif a.batch_id is not null then
        select batch_number into v_batch from public.inventory_batches_v483 where id=a.batch_id and tenant_id=p_tenant_id;
        insert into public.inventory_batch_balances_v483(tenant_id,batch_id,location_id,quantity,damaged_quantity,reserved_quantity,updated_at)
          values(p_tenant_id,a.batch_id,v.to_location_id,a.quantity,0,0,now())
          on conflict(tenant_id,batch_id,location_id) do update set quantity=public.inventory_batch_balances_v483.quantity+excluded.quantity,updated_at=now();
        update public.inventory_batches_v483 set status='active',updated_at=now() where id=a.batch_id and tenant_id=p_tenant_id and status='exhausted';
        insert into public.inventory_trace_events_v483(
          tenant_id,variant_id,batch_id,event_type,quantity,location_id,reference_number,source_key,metadata,transfer_id,transfer_item_id,created_by
        ) values(
          p_tenant_id,r.variant_id,a.batch_id,'transfer_in',a.quantity,v.to_location_id,v.transfer_number,
          'transfer:'||v.id::text||':in:batch:'||a.batch_id::text,
          jsonb_build_object('from_location_id',v.from_location_id,'to_location_id',v.to_location_id,'batch_number',v_batch),v.id,r.id,auth.uid()
        ) on conflict do nothing;
      end if;
      update public.stock_transfer_allocations_v485 set status='received',received_at=now(),updated_at=now() where id=a.id;
    end loop;
    update public.stock_transfer_items set received_quantity=r.dispatched_quantity,updated_at=now() where id=r.id;
  end loop;

  update public.stock_transfers set status='received',received_by=auth.uid(),received_at=now(),receive_note=nullif(trim(coalesce(p_receive_note,'')),''),updated_at=now() where id=v.id;
  perform private.v485_transfer_history_add(p_tenant_id,v.id,'received',v.status,'received',p_receive_note);
  perform private.thq_sync_bump_v480(p_tenant_id,'inventory','stock_transfer',v.id::text,'received');
  return jsonb_build_object('success',true,'transfer_id',v.id,'transfer_number',v.transfer_number,'status','received');
end$$;


--
-- Name: inventory_transfer_reject_v42(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_transfer_reject_v42(p_tenant_id uuid, p_transfer_id uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$begin
  perform public.inventory_transfer_decide_v485(p_tenant_id,p_transfer_id,false,p_reason);
end$$;


--
-- Name: inventory_transfer_request_v485(uuid, uuid, uuid, jsonb, text, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_transfer_request_v485(p_tenant_id uuid, p_from_location_id uuid, p_to_location_id uuid, p_items jsonb, p_notes text DEFAULT NULL::text, p_expected_arrival_date date DEFAULT NULL::date, p_transport_reference text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_existing jsonb;v_id uuid:=gen_random_uuid();v_no text;x jsonb;v_variant uuid;v_qty numeric;v_available numeric;v_mode text;
  v_item_id uuid;v_serials jsonb;s jsonb;v_serial text;v_serial_id uuid;v_serial_count numeric;v_seen_serial text[]:='{}'::text[];
  v_batches jsonb;b jsonb;v_batch_id uuid;v_batch_number text;v_batch_qty numeric;v_batch_available numeric;v_batch_sum numeric;v_seen_batch uuid[]:='{}'::uuid[];
  v_result jsonb;
begin
  if nullif(trim(coalesce(p_request_id,'')),'') is not null then
    v_existing:=private.v47_request_existing(p_tenant_id,p_request_id,'warehouse.transfer.request');
    if v_existing is not null then return v_existing;end if;
  end if;
  perform private.v4_location_access(p_tenant_id,p_from_location_id,'operate');
  perform private.v4_location_access(p_tenant_id,p_to_location_id,'view');
  perform private.warehouse_v485_permission(p_tenant_id,false);
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'inventory.transfer') and not private.erp_has_permission(p_tenant_id,'inventory.manage') then
    raise exception 'Stock transfer permission required';
  end if;
  if p_from_location_id=p_to_location_id then raise exception 'Source and destination must be different';end if;
  if p_items is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'Add at least one transfer item';end if;

  v_no:='TRF-'||to_char(current_date,'YYMMDD')||'-'||lpad(nextval('public.stock_transfer_number_seq')::text,6,'0');
  insert into public.stock_transfers(
    id,tenant_id,transfer_number,from_location_id,to_location_id,status,notes,created_by,requested_by,requested_at,
    reservation_applied,expected_arrival_date,transport_reference,request_key,updated_at
  ) values(
    v_id,p_tenant_id,v_no,p_from_location_id,p_to_location_id,'requested',nullif(trim(coalesce(p_notes,'')),''),auth.uid(),auth.uid(),now(),
    true,p_expected_arrival_date,nullif(trim(coalesce(p_transport_reference,'')),''),nullif(trim(coalesce(p_request_id,'')),''),now()
  );

  for x in select value from jsonb_array_elements(p_items) loop
    v_variant:=nullif(x->>'variant_id','')::uuid;
    v_qty:=coalesce(nullif(x->>'quantity','')::numeric,0);
    if v_variant is null or not exists(select 1 from public.product_variants where tenant_id=p_tenant_id and id=v_variant) then raise exception 'Product does not belong to this business';end if;
    if v_qty<=0 then raise exception 'Transfer quantity must be positive';end if;
    v_mode:=private.v483_tracking_mode(p_tenant_id,v_variant);
    if v_mode='serial' and v_qty<>trunc(v_qty) then raise exception 'Serial-tracked transfer quantity must be whole base units';end if;
    perform private.v483_assert_reconciled(p_tenant_id,v_variant,p_from_location_id);

    insert into public.location_stock_balances(tenant_id,location_id,variant_id)
      values(p_tenant_id,p_from_location_id,v_variant) on conflict do nothing;
    select quantity-reserved_quantity-damaged_quantity-quarantine_quantity into v_available
      from public.location_stock_balances
      where tenant_id=p_tenant_id and location_id=p_from_location_id and variant_id=v_variant
      for update;
    if coalesce(v_available,0)+0.000001<v_qty then raise exception 'Insufficient available stock. Available: %, requested: %',coalesce(v_available,0),v_qty;end if;

    update public.location_stock_balances
      set reserved_quantity=reserved_quantity+v_qty,updated_at=now()
      where tenant_id=p_tenant_id and location_id=p_from_location_id and variant_id=v_variant;

    insert into public.stock_transfer_items(transfer_id,variant_id,quantity,note,tracking_mode,tracking_payload,updated_at)
      values(v_id,v_variant,v_qty,nullif(trim(coalesce(x->>'note','')),''),v_mode,coalesce(x->'tracking','{}'::jsonb),now())
      returning id into v_item_id;

    if v_mode='serial' then
      v_serials:=coalesce(x->'serial_numbers',x->'tracking'->'serial_numbers','[]'::jsonb);
      if jsonb_typeof(v_serials)<>'array' then raise exception 'serial_numbers must be an array';end if;
      select count(*)::numeric into v_serial_count from jsonb_array_elements(v_serials);
      if v_serial_count<>v_qty then raise exception 'Provide exactly % serial numbers for the transfer line',v_qty;end if;
      v_seen_serial:='{}'::text[];
      for s in select value from jsonb_array_elements(v_serials) loop
        v_serial:=trim(coalesce(case when jsonb_typeof(s)='string' then s#>>'{}' else s->>'serial_number' end,''));
        if v_serial='' then raise exception 'Serial number cannot be blank';end if;
        if lower(v_serial)=any(v_seen_serial) then raise exception 'Serial % is duplicated on the transfer',v_serial;end if;
        v_seen_serial:=array_append(v_seen_serial,lower(v_serial));
        select id into v_serial_id from public.inventory_serials_v483
          where tenant_id=p_tenant_id and variant_id=v_variant and current_location_id=p_from_location_id
            and status='in_stock' and reserved_transfer_id is null and lower(trim(serial_number))=lower(v_serial)
          for update;
        if v_serial_id is null then raise exception 'Serial % is not available at the source location',v_serial;end if;
        update public.inventory_serials_v483 set reserved_transfer_id=v_id,updated_at=now() where id=v_serial_id;
        insert into public.stock_transfer_allocations_v485(tenant_id,transfer_id,transfer_item_id,variant_id,serial_id,quantity,status,from_location_id,to_location_id,created_by)
          values(p_tenant_id,v_id,v_item_id,v_variant,v_serial_id,1,'reserved',p_from_location_id,p_to_location_id,auth.uid());
      end loop;
    elsif v_mode='batch' then
      v_batches:=coalesce(x->'batches',x->'tracking'->'batches','[]'::jsonb);
      if jsonb_typeof(v_batches)<>'array' or jsonb_array_length(v_batches)=0 then raise exception 'Batch-tracked transfers require batch allocations';end if;
      v_batch_sum:=0;v_seen_batch:='{}'::uuid[];
      for b in select value from jsonb_array_elements(v_batches) loop
        v_batch_qty:=coalesce(nullif(b->>'quantity','')::numeric,0);
        if v_batch_qty<=0 then raise exception 'Batch transfer quantity must be positive';end if;
        if nullif(b->>'batch_id','') is not null then
          v_batch_id:=(b->>'batch_id')::uuid;
        else
          v_batch_number:=trim(coalesce(b->>'batch_number',''));
          select id into v_batch_id from public.inventory_batches_v483
            where tenant_id=p_tenant_id and variant_id=v_variant and lower(trim(batch_number))=lower(v_batch_number);
        end if;
        if v_batch_id is null then raise exception 'Batch % was not found',coalesce(v_batch_number,'');end if;
        if not exists(
          select 1 from public.inventory_batches_v483 ib
          where ib.id=v_batch_id and ib.tenant_id=p_tenant_id and ib.variant_id=v_variant
        ) then raise exception 'Batch does not belong to the selected product/business';end if;
        if v_batch_id=any(v_seen_batch) then raise exception 'The same batch cannot appear twice on one transfer line';end if;
        v_seen_batch:=array_append(v_seen_batch,v_batch_id);
        select quantity-coalesce(reserved_quantity,0) into v_batch_available
          from public.inventory_batch_balances_v483
          where tenant_id=p_tenant_id and batch_id=v_batch_id and location_id=p_from_location_id
          for update;
        if coalesce(v_batch_available,0)+0.000001<v_batch_qty then raise exception 'Insufficient available quantity in batch %',coalesce(v_batch_number,v_batch_id::text);end if;
        update public.inventory_batch_balances_v483 set reserved_quantity=reserved_quantity+v_batch_qty,updated_at=now()
          where tenant_id=p_tenant_id and batch_id=v_batch_id and location_id=p_from_location_id;
        insert into public.stock_transfer_allocations_v485(tenant_id,transfer_id,transfer_item_id,variant_id,batch_id,quantity,status,from_location_id,to_location_id,created_by)
          values(p_tenant_id,v_id,v_item_id,v_variant,v_batch_id,v_batch_qty,'reserved',p_from_location_id,p_to_location_id,auth.uid());
        v_batch_sum:=v_batch_sum+v_batch_qty;
      end loop;
      if abs(v_batch_sum-v_qty)>0.000001 then raise exception 'Batch allocations % must equal transfer quantity %',v_batch_sum,v_qty;end if;
    end if;
  end loop;

  perform private.v485_transfer_history_add(p_tenant_id,v_id,'requested',null,'requested',p_notes,jsonb_build_object('expected_arrival_date',p_expected_arrival_date,'transport_reference',nullif(trim(coalesce(p_transport_reference,'')),'')));
  perform private.thq_sync_bump_v480(p_tenant_id,'inventory','stock_transfer',v_id::text,'requested');
  v_result:=jsonb_build_object('success',true,'transfer_id',v_id,'transfer_number',v_no,'status','requested','reservation_applied',true);
  if nullif(trim(coalesce(p_request_id,'')),'') is not null then
    v_result:=private.v47_request_complete(p_tenant_id,p_request_id,'warehouse.transfer.request',v_result);
  end if;
  return v_result;
end$$;


--
-- Name: inventory_transfer_tracking_options_v485(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_transfer_tracking_options_v485(p_tenant_id uuid, p_location_id uuid, p_variant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_mode text;v jsonb;
begin
  perform private.v4_location_access(p_tenant_id,p_location_id,'view');
  v_mode:=private.v483_tracking_mode(p_tenant_id,p_variant_id);
  if v_mode='serial' then
    select jsonb_build_object('tracking_mode','serial','serials',coalesce(jsonb_agg(jsonb_build_object('id',s.id,'serial_number',s.serial_number,'status',s.status) order by s.serial_number),'[]'::jsonb)) into v
    from public.inventory_serials_v483 s
    where s.tenant_id=p_tenant_id and s.variant_id=p_variant_id and s.current_location_id=p_location_id and s.status='in_stock' and s.reserved_transfer_id is null;
  elsif v_mode='batch' then
    select jsonb_build_object('tracking_mode','batch','batches',coalesce(jsonb_agg(jsonb_build_object(
      'id',b.id,'batch_number',b.batch_number,'manufactured_on',b.manufactured_on,'expiry_on',b.expiry_on,
      'quantity',bb.quantity,'reserved_quantity',coalesce(bb.reserved_quantity,0),'available_quantity',greatest(bb.quantity-coalesce(bb.reserved_quantity,0),0)
    ) order by (b.expiry_on is null),b.expiry_on,b.batch_number),'[]'::jsonb)) into v
    from public.inventory_batches_v483 b join public.inventory_batch_balances_v483 bb on bb.tenant_id=b.tenant_id and bb.batch_id=b.id
    where b.tenant_id=p_tenant_id and b.variant_id=p_variant_id and bb.location_id=p_location_id and bb.quantity-coalesce(bb.reserved_quantity,0)>0 and b.status in('active','quarantine');
  else
    v:=jsonb_build_object('tracking_mode','none','serials','[]'::jsonb,'batches','[]'::jsonb);
  end if;
  return coalesce(v,jsonb_build_object('tracking_mode',v_mode,'serials','[]'::jsonb,'batches','[]'::jsonb));
end$$;


--
-- Name: inventory_transfers_list_v4(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_transfers_list_v4(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100) RETURNS TABLE(id uuid, transfer_number text, from_location_id uuid, from_location text, to_location_id uuid, to_location text, status text, notes text, created_at timestamp with time zone, approved_at timestamp with time zone, dispatched_at timestamp with time zone, received_at timestamp with time zone, item_count bigint, total_quantity numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  return query select t.id,t.transfer_number,t.from_location_id,fl.location_code||' • '||fl.name,t.to_location_id,tl.location_code||' • '||tl.name,t.status,t.notes,t.created_at,t.approved_at,t.dispatched_at,t.received_at,count(i.id),coalesce(sum(i.quantity),0)
  from public.stock_transfers t join public.business_locations fl on fl.id=t.from_location_id join public.business_locations tl on tl.id=t.to_location_id left join public.stock_transfer_items i on i.transfer_id=t.id
  where t.tenant_id=p_tenant_id and (p_location_id is null or t.from_location_id=p_location_id or t.to_location_id=p_location_id)
    and (private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'locations.view_all') or private.erp_user_location_allowed(p_tenant_id,t.from_location_id,'view') or private.erp_user_location_allowed(p_tenant_id,t.to_location_id,'view'))
  group by t.id,fl.location_code,fl.name,tl.location_code,tl.name order by t.created_at desc limit greatest(1,least(coalesce(p_limit,100),500));
end $$;


--
-- Name: inventory_transfers_list_v42(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_transfers_list_v42(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100) RETURNS TABLE(id uuid, transfer_number text, from_location_id uuid, from_location text, to_location_id uuid, to_location text, status text, notes text, created_at timestamp with time zone, requested_at timestamp with time zone, approved_at timestamp with time zone, dispatched_at timestamp with time zone, received_at timestamp with time zone, item_count bigint, total_quantity numeric, in_transit_quantity numeric, reservation_applied boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  return query
  select t.id,t.transfer_number,t.from_location_id,fl.location_code||' • '||fl.name,t.to_location_id,tl.location_code||' • '||tl.name,
    t.status,t.notes,t.created_at,t.requested_at,t.approved_at,t.dispatched_at,t.received_at,count(i.id),coalesce(sum(i.quantity),0),
    coalesce(sum(case when t.status='dispatched' then greatest(i.dispatched_quantity-i.received_quantity,0) else 0 end),0),t.reservation_applied
  from public.stock_transfers t
  join public.business_locations fl on fl.id=t.from_location_id
  join public.business_locations tl on tl.id=t.to_location_id
  left join public.stock_transfer_items i on i.transfer_id=t.id
  where t.tenant_id=p_tenant_id and (p_location_id is null or t.from_location_id=p_location_id or t.to_location_id=p_location_id)
    and (private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'locations.view_all') or private.erp_has_permission(p_tenant_id,'locations.manage_all') or private.erp_user_location_allowed(p_tenant_id,t.from_location_id,'view') or private.erp_user_location_allowed(p_tenant_id,t.to_location_id,'view'))
  group by t.id,fl.location_code,fl.name,tl.location_code,tl.name
  order by t.created_at desc limit greatest(1,least(coalesce(p_limit,100),500));
end $$;


--
-- Name: inventory_transfers_list_v485(uuid, uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_transfers_list_v485(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_query text DEFAULT ''::text, p_limit integer DEFAULT 500) RETURNS TABLE(id uuid, transfer_number text, from_location_id uuid, from_location text, from_is_warehouse boolean, to_location_id uuid, to_location text, to_is_warehouse boolean, status text, notes text, expected_arrival_date date, transport_reference text, created_at timestamp with time zone, requested_at timestamp with time zone, approved_at timestamp with time zone, in_transit_at timestamp with time zone, received_at timestamp with time zone, item_count bigint, total_quantity numeric, serial_count bigint, batch_quantity numeric, in_transit_quantity numeric, reservation_applied boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare q text:='%'||lower(trim(coalesce(p_query,'')))||'%';
begin
  perform private.warehouse_v485_permission(p_tenant_id,false);
  return query
  select t.id,t.transfer_number,t.from_location_id,fl.location_code||' • '||fl.name,(fl.hierarchy_role='warehouse' or fl.location_type='warehouse'),
    t.to_location_id,tl.location_code||' • '||tl.name,(tl.hierarchy_role='warehouse' or tl.location_type='warehouse'),
    case when t.status='dispatched' then 'in_transit' else t.status end,t.notes,t.expected_arrival_date,t.transport_reference,
    t.created_at,t.requested_at,t.approved_at,coalesce(t.in_transit_at,t.dispatched_at),t.received_at,
    count(distinct i.id),coalesce(sum(i.quantity),0),
    coalesce((select count(*) from public.stock_transfer_allocations_v485 a where a.transfer_id=t.id and a.serial_id is not null and a.status<>'released'),0),
    coalesce((select sum(a.quantity) from public.stock_transfer_allocations_v485 a where a.transfer_id=t.id and a.batch_id is not null and a.status<>'released'),0),
    coalesce(sum(case when t.status in('dispatched','in_transit') then greatest(i.dispatched_quantity-i.received_quantity,0) else 0 end),0),t.reservation_applied
  from public.stock_transfers t
  join public.business_locations fl on fl.id=t.from_location_id
  join public.business_locations tl on tl.id=t.to_location_id
  left join public.stock_transfer_items i on i.transfer_id=t.id
  where t.tenant_id=p_tenant_id
    and (p_location_id is null or t.from_location_id=p_location_id or t.to_location_id=p_location_id)
    and (p_status is null or trim(p_status)='' or (case when t.status='dispatched' then 'in_transit' else t.status end)=lower(trim(p_status)))
    and (trim(coalesce(p_query,''))='' or lower(t.transfer_number) like q or lower(fl.name) like q or lower(tl.name) like q or lower(coalesce(t.transport_reference,'')) like q or lower(coalesce(t.notes,'')) like q)
    and (private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'locations.view_all') or private.erp_has_permission(p_tenant_id,'locations.manage_all') or private.erp_user_location_allowed(p_tenant_id,t.from_location_id,'view') or private.erp_user_location_allowed(p_tenant_id,t.to_location_id,'view'))
  group by t.id,fl.location_code,fl.name,fl.hierarchy_role,fl.location_type,tl.location_code,tl.name,tl.hierarchy_role,tl.location_type
  order by t.created_at desc
  limit greatest(1,least(coalesce(p_limit,500),2000));
end$$;


--
-- Name: inventory_unit_save_v481(uuid, uuid, text, text, text, integer, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_unit_save_v481(p_tenant_id uuid, p_unit_id uuid, p_code text, p_name text, p_group text, p_decimal_places integer, p_allow_fractional boolean, p_active boolean DEFAULT true) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_id uuid;begin
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'inventory.manage') then raise exception 'Inventory manage permission required';end if;
  if trim(coalesce(p_code,''))='' or trim(coalesce(p_name,''))='' then raise exception 'Unit code and name are required';end if;
  if p_unit_id is not null and exists(select 1 from public.inventory_units_v481 u where u.id=p_unit_id and u.tenant_id=p_tenant_id and u.system_unit) then
    raise exception 'System unit definitions cannot be edited. Create a custom unit instead.';
  end if;
  if p_unit_id is null then
    insert into public.inventory_units_v481(tenant_id,code,name,unit_group,decimal_places,allow_fractional,active)
    values(p_tenant_id,upper(trim(p_code)),trim(p_name),coalesce(nullif(trim(p_group),''),'custom'),greatest(0,least(coalesce(p_decimal_places,0),6)),coalesce(p_allow_fractional,false),coalesce(p_active,true)) returning id into v_id;
  else
    update public.inventory_units_v481 set code=upper(trim(p_code)),name=trim(p_name),unit_group=coalesce(nullif(trim(p_group),''),'custom'),decimal_places=greatest(0,least(coalesce(p_decimal_places,0),6)),allow_fractional=coalesce(p_allow_fractional,false),active=coalesce(p_active,true),updated_at=now()
    where id=p_unit_id and tenant_id=p_tenant_id returning id into v_id;
    if v_id is null then raise exception 'Unit not found';end if;
  end if; return v_id;
end $$;


--
-- Name: inventory_units_list_v481(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_units_list_v481(p_tenant_id uuid, p_active_only boolean DEFAULT true) RETURNS TABLE(unit_id uuid, code text, name text, unit_group text, decimal_places integer, allow_fractional boolean, system_unit boolean, active boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  return query select u.id,u.code,u.name,u.unit_group,u.decimal_places,u.allow_fractional,u.system_unit,u.active
  from public.inventory_units_v481 u where u.tenant_id=p_tenant_id and (not p_active_only or u.active) order by u.unit_group,u.name;
end $$;


--
-- Name: inventory_update_product(uuid, uuid, text, text, text, text, text, text, text, numeric, numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_update_product(p_tenant_id uuid, p_variant_id uuid, p_name text, p_description text, p_category_name text, p_brand_name text, p_sku text, p_barcode text, p_part_number text, p_cost_price numeric, p_selling_price numeric, p_list_price numeric, p_tax_rate numeric, p_reorder_level numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_product_id uuid;

  v_category_id uuid;
  v_brand_id uuid;

  v_category_name text;
  v_brand_name text;

  v_barcode text;
  v_part_number text;
begin

  -- ----------------------------------------------------------
  -- PERMISSION
  -- ----------------------------------------------------------

  if not private.has_permission(
    p_tenant_id,
    'inventory.manage'
  ) then

    raise exception 'Access denied'
      using errcode = '42501';

  end if;


  -- ----------------------------------------------------------
  -- FIND PRODUCT
  -- ----------------------------------------------------------

  select pv.product_id
  into v_product_id

  from public.product_variants pv

  where pv.id = p_variant_id
    and pv.tenant_id = p_tenant_id;


  if v_product_id is null then
    raise exception 'Product not found';
  end if;


  -- ----------------------------------------------------------
  -- VALIDATION
  -- ----------------------------------------------------------

  if nullif(trim(p_name), '') is null then
    raise exception 'Product name is required';
  end if;


  if nullif(trim(p_sku), '') is null then
    raise exception 'SKU is required';
  end if;


  if p_cost_price is null
     or p_cost_price < 0 then

    raise exception
      'Cost price cannot be negative';

  end if;


  if p_selling_price is null
     or p_selling_price < 0 then

    raise exception
      'Selling price cannot be negative';

  end if;


  if p_list_price is not null
     and p_list_price < 0 then

    raise exception
      'List price cannot be negative';

  end if;


  if p_tax_rate is null
     or p_tax_rate < 0
     or p_tax_rate > 100 then

    raise exception
      'Tax rate must be between 0 and 100';

  end if;


  if p_reorder_level is null
     or p_reorder_level < 0 then

    raise exception
      'Reorder level cannot be negative';

  end if;


  -- ----------------------------------------------------------
  -- CLEAN VALUES
  -- ----------------------------------------------------------

  v_barcode :=
    nullif(
      trim(
        coalesce(
          p_barcode,
          ''
        )
      ),
      ''
    );


  v_part_number :=
    nullif(
      trim(
        coalesce(
          p_part_number,
          ''
        )
      ),
      ''
    );


  v_category_name :=
    nullif(
      trim(
        coalesce(
          p_category_name,
          ''
        )
      ),
      ''
    );


  v_brand_name :=
    nullif(
      trim(
        coalesce(
          p_brand_name,
          ''
        )
      ),
      ''
    );


  -- ----------------------------------------------------------
  -- DUPLICATE SKU
  -- ----------------------------------------------------------

  if exists (
    select 1

    from public.product_variants pv

    where pv.tenant_id = p_tenant_id
      and pv.id <> p_variant_id
      and lower(pv.sku) =
          lower(trim(p_sku))
  ) then

    raise exception
      'A product with this SKU already exists';

  end if;


  -- ----------------------------------------------------------
  -- DUPLICATE BARCODE
  -- ----------------------------------------------------------

  if v_barcode is not null
     and exists (
       select 1

       from public.product_variants pv

       where pv.tenant_id = p_tenant_id
         and pv.id <> p_variant_id
         and pv.barcode = v_barcode
     ) then

    raise exception
      'A product with this barcode already exists';

  end if;


  -- ----------------------------------------------------------
  -- CATEGORY
  -- ----------------------------------------------------------

  if v_category_name is null then

    v_category_id := null;

  else

    select pc.id
    into v_category_id

    from public.product_categories pc

    where pc.tenant_id = p_tenant_id
      and lower(pc.name) =
          lower(v_category_name)

    limit 1;


    if v_category_id is null then

      insert into public.product_categories (
        tenant_id,
        name,
        is_active
      )
      values (
        p_tenant_id,
        v_category_name,
        true
      )
      returning id
      into v_category_id;

    end if;

  end if;


  -- ----------------------------------------------------------
  -- BRAND
  -- ----------------------------------------------------------

  if v_brand_name is null then

    v_brand_id := null;

  else

    select pb.id
    into v_brand_id

    from public.product_brands pb

    where pb.tenant_id = p_tenant_id
      and lower(pb.name) =
          lower(v_brand_name)

    limit 1;


    if v_brand_id is null then

      insert into public.product_brands (
        tenant_id,
        name,
        is_active
      )
      values (
        p_tenant_id,
        v_brand_name,
        true
      )
      returning id
      into v_brand_id;

    end if;

  end if;


  -- ----------------------------------------------------------
  -- UPDATE PRODUCT
  -- ----------------------------------------------------------

  update public.products
  set
    name = trim(p_name),

    description =
      nullif(
        trim(
          coalesce(
            p_description,
            ''
          )
        ),
        ''
      ),

    category_id = v_category_id,
    brand_id = v_brand_id,

    tax_rate = p_tax_rate

  where id = v_product_id
    and tenant_id = p_tenant_id;


  -- ----------------------------------------------------------
  -- UPDATE VARIANT
  -- ----------------------------------------------------------

  update public.product_variants
  set
    sku = trim(p_sku),

    barcode = v_barcode,

    part_number =
      v_part_number,

    cost_price =
      p_cost_price,

    selling_price =
      p_selling_price,

    list_price =
      p_list_price,

    reorder_level =
      p_reorder_level

  where id = p_variant_id
    and tenant_id = p_tenant_id;


  return jsonb_build_object(
    'success', true,
    'product_id', v_product_id,
    'variant_id', p_variant_id
  );

end;
$$;


--
-- Name: invoice_print_event_v4(uuid, text, uuid, text, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_print_event_v4(p_tenant_id uuid, p_entity_type text, p_entity_id uuid, p_invoice_number text, p_template_id uuid, p_printer_profile_id uuid, p_action text, p_device_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  insert into public.invoice_print_events(tenant_id,entity_type,entity_id,invoice_number,template_id,printer_profile_id,action,copy_number,created_by,device_id)
  values(p_tenant_id,p_entity_type,p_entity_id,p_invoice_number,p_template_id,p_printer_profile_id,p_action,1+(select count(*) from public.invoice_print_events where tenant_id=p_tenant_id and entity_type=p_entity_type and entity_id=p_entity_id and action in('print','reprint')),auth.uid(),p_device_id);
end $$;


--
-- Name: invoice_print_profile_save_v4(uuid, uuid, uuid, uuid, text, text, text, integer, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_print_profile_save_v4(p_tenant_id uuid, p_profile_id uuid, p_location_id uuid, p_device_id uuid, p_name text, p_paper_size text, p_printer_name text, p_copies integer, p_auto_print boolean, p_active boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v uuid;begin
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'settings.manage') then raise exception 'Settings permission required';end if;
  if p_paper_size not in('58mm','80mm','a4') then raise exception 'Invalid paper size';end if;
  if p_profile_id is null then insert into public.printer_profiles(tenant_id,location_id,device_id,name,paper_size,printer_name,copies,auto_print,active) values(p_tenant_id,p_location_id,p_device_id,trim(p_name),p_paper_size,nullif(trim(coalesce(p_printer_name,'')),''),greatest(1,least(coalesce(p_copies,1),10)),coalesce(p_auto_print,false),coalesce(p_active,true)) returning id into v;
  else update public.printer_profiles set location_id=p_location_id,device_id=p_device_id,name=trim(p_name),paper_size=p_paper_size,printer_name=nullif(trim(coalesce(p_printer_name,'')),''),copies=greatest(1,least(coalesce(p_copies,1),10)),auto_print=coalesce(p_auto_print,false),active=coalesce(p_active,true) where id=p_profile_id and tenant_id=p_tenant_id returning id into v;end if;return v;
end $$;


--
-- Name: printer_profiles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.printer_profiles (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    location_id uuid,
    device_id uuid,
    name text NOT NULL,
    paper_size text DEFAULT '80mm'::text NOT NULL,
    printer_name text,
    copies integer DEFAULT 1 NOT NULL,
    auto_print boolean DEFAULT false NOT NULL,
    active boolean DEFAULT true NOT NULL,
    settings jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    purpose text DEFAULT 'invoice'::text NOT NULL,
    route_name text,
    cash_drawer_enabled boolean DEFAULT false NOT NULL,
    cash_drawer_command text,
    is_default boolean DEFAULT false NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT printer_profiles_copies_check CHECK (((copies >= 1) AND (copies <= 10))),
    CONSTRAINT printer_profiles_paper_size_check CHECK ((paper_size = ANY (ARRAY['58mm'::text, '80mm'::text, 'a4'::text]))),
    CONSTRAINT printer_profiles_purpose_check CHECK ((purpose = ANY (ARRAY['invoice'::text, 'kot'::text, 'report'::text, 'label'::text])))
);


--
-- Name: invoice_print_profiles_list_v4(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_print_profiles_list_v4(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_device_id uuid DEFAULT NULL::uuid) RETURNS SETOF public.printer_profiles
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  return query select * from public.printer_profiles where tenant_id=p_tenant_id and active
    and (p_location_id is null or location_id is null or location_id=p_location_id)
    and (p_device_id is null or device_id is null or device_id=p_device_id)
  order by case when device_id=p_device_id then 0 when location_id=p_location_id then 1 else 2 end,name;
end $$;


--
-- Name: invoice_template_capabilities_v495(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_template_capabilities_v495(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  return jsonb_build_object(
    'paper_types',jsonb_build_array('a4','80mm'),
    'logo_formats',jsonb_build_array('png','jpg','jpeg'),
    'max_logo_bytes',5242880,
    'columns',jsonb_build_array('item','sku','hsn','qty','unit','rate','discount','tax','tax_amount','taxable','total'),
    'print_dialog',true,
    'pdf_download',true,
    'xlsx_reports',true
  );
end $$;


--
-- Name: journal_center_detail_v500(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_center_detail_v500(p_tenant_id uuid, p_journal_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare h jsonb;lines jsonb;begin perform private.v500_accounting_access(p_tenant_id,false);
  select to_jsonb(j) into h from public.journal_entries j where j.id=p_journal_id and j.tenant_id=p_tenant_id;if h is null then raise exception 'Journal not found';end if;
  select coalesce(jsonb_agg(jsonb_build_object('line_id',l.id,'account_id',l.account_id,'account_code',a.code,'account_name',a.name,'account_type',a.account_type,'party_type',l.party_type,'party_id',l.party_id,'description',l.description,'debit',l.debit,'credit',l.credit) order by a.code,l.id),'[]'::jsonb) into lines from public.journal_lines l join public.accounting_accounts a on a.id=l.account_id where l.journal_entry_id=p_journal_id;
  return jsonb_build_object('journal',h,'lines',lines,'balanced',abs(coalesce((select sum(debit-credit) from public.journal_lines where journal_entry_id=p_journal_id),0))<=0.005);
end $$;


--
-- Name: journal_center_list_v500(uuid, date, date, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_center_list_v500(p_tenant_id uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_query text DEFAULT ''::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 1000) RETURNS TABLE(journal_id uuid, entry_number text, entry_date date, description text, status text, source_type text, source_id uuid, source_reference text, location_id uuid, location_name text, total_debit numeric, total_credit numeric, line_count bigint, created_at timestamp with time zone, created_by uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare q text:='%'||lower(trim(coalesce(p_query,'')))||'%';begin perform private.v500_accounting_access(p_tenant_id,false);
  return query select j.id,j.entry_number,j.entry_date,j.description,j.status,coalesce(j.source_type,''),j.source_id,coalesce(j.source_reference,''),j.location_id,coalesce(l.location_code||' • '||l.name,l.name,''),coalesce(sum(x.debit),0)::numeric,coalesce(sum(x.credit),0)::numeric,count(x.id),j.created_at,j.created_by
  from public.journal_entries j left join public.journal_lines x on x.journal_entry_id=j.id left join public.business_locations l on l.id=j.location_id
  where j.tenant_id=p_tenant_id and (p_from is null or j.entry_date>=p_from) and (p_to is null or j.entry_date<=p_to) and (p_status is null or j.status=p_status) and (trim(coalesce(p_query,''))='' or lower(j.entry_number) like q or lower(j.description) like q or lower(coalesce(j.source_reference,'')) like q or lower(coalesce(j.source_type,'')) like q)
  group by j.id,l.id order by j.entry_date desc,j.created_at desc limit greatest(1,least(coalesce(p_limit,1000),5000));
end $$;


--
-- Name: journal_reverse_v500(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.journal_reverse_v500(p_tenant_id uuid, p_journal_id uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare j public.journal_entries%rowtype;x record;v_lines jsonb:='[]'::jsonb;v_new uuid;begin perform private.v500_accounting_access(p_tenant_id,true);if trim(coalesce(p_reason,''))='' then raise exception 'Reversal reason is required';end if;select * into j from public.journal_entries where id=p_journal_id and tenant_id=p_tenant_id for update;if not found then raise exception 'Journal not found';end if;if j.status<>'posted' then raise exception 'Only posted journals can be reversed';end if;if coalesce(j.source_type,'manual') not in('manual','finance_voucher_v500','opening_balance_v500') then raise exception 'Operational journal % must be reversed from its source transaction, not Journal Center',coalesce(j.source_type,'unknown');end if;perform private.v500_assert_posting_period_open(p_tenant_id,current_date);for x in select * from public.journal_lines where journal_entry_id=j.id order by id loop v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',x.account_id,'debit',x.credit,'credit',x.debit,'party_type',x.party_type,'party_id',x.party_id,'description','Reversal: '||coalesce(x.description,j.description)));end loop;update public.journal_entries set status='reversed' where id=j.id;v_new:=private.v4_journal_create(p_tenant_id,j.location_id,current_date,'Reversal of '||j.entry_number||' • '||trim(p_reason),'journal_reversal_v500',j.id,j.entry_number,v_lines);update public.journal_entries set reversal_of=j.id where id=v_new;update public.finance_vouchers_v500 set status='reversed',reversal_journal_id=v_new,reversed_by=auth.uid(),reversed_at=now() where tenant_id=p_tenant_id and journal_id=j.id;update public.opening_balance_batches_v500 set status='reversed' where tenant_id=p_tenant_id and journal_id=j.id;return v_new;end $$;


--
-- Name: label_template_save_v482(uuid, uuid, text, text, text, numeric, numeric, integer, boolean, boolean, boolean, boolean, boolean, text, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.label_template_save_v482(p_tenant_id uuid, p_template_id uuid, p_code text, p_name text, p_paper_mode text, p_width_mm numeric, p_height_mm numeric, p_columns integer, p_show_business boolean, p_show_product boolean, p_show_price boolean, p_show_sku boolean, p_show_code_text boolean, p_code_mode text, p_is_default boolean, p_active boolean DEFAULT true) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v_id uuid;begin
 if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'inventory.manage') then raise exception 'Inventory manage permission required';end if;
 if p_is_default then update public.label_templates_v482 set is_default=false,updated_at=now() where tenant_id=p_tenant_id;end if;
 if p_template_id is null then
  insert into public.label_templates_v482(tenant_id,code,name,paper_mode,width_mm,height_mm,columns,show_business,show_product,show_price,show_sku,show_code_text,code_mode,is_default,active)
  values(p_tenant_id,upper(trim(p_code)),trim(p_name),p_paper_mode,p_width_mm,p_height_mm,p_columns,p_show_business,p_show_product,p_show_price,p_show_sku,p_show_code_text,p_code_mode,p_is_default,p_active) returning id into v_id;
 else
  update public.label_templates_v482 set code=upper(trim(p_code)),name=trim(p_name),paper_mode=p_paper_mode,width_mm=p_width_mm,height_mm=p_height_mm,columns=p_columns,show_business=p_show_business,show_product=p_show_product,show_price=p_show_price,show_sku=p_show_sku,show_code_text=p_show_code_text,code_mode=p_code_mode,is_default=p_is_default,active=p_active,updated_at=now() where id=p_template_id and tenant_id=p_tenant_id returning id into v_id;
  if v_id is null then raise exception 'Label template not found';end if;
 end if;
 perform private.thq_sync_bump_v480(p_tenant_id,'catalogue','label_template',v_id::text,'save');return v_id;
end$$;


--
-- Name: label_templates_v482(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.label_templates_v482(p_tenant_id uuid) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$begin
 if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
 return query select to_jsonb(t) from public.label_templates_v482 t where t.tenant_id=p_tenant_id and t.active order by t.is_default desc,t.name;
end$$;


--
-- Name: loan_activate_v491(uuid, uuid, date, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loan_activate_v491(p_tenant_id uuid, p_loan_id uuid, p_disbursement_date date DEFAULT CURRENT_DATE, p_payment_method text DEFAULT 'bank'::text, p_reference_number text DEFAULT NULL::text, p_device_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v public.loan_accounts_v490%rowtype;v_ppy numeric;v_pr numeric;v_inst numeric;v_flat numeric;v_bal numeric;v_int numeric;v_prin numeric;v_due date;i int;v_lines jsonb;v_shift uuid;begin
 select * into v from public.loan_accounts_v490 where tenant_id=p_tenant_id and id=p_loan_id for update;if not found then raise exception 'Loan not found';end if;perform private.loan_v490_access(p_tenant_id,v.location_id,'loans.disburse','manage');if p_device_id is not null and not exists(select 1 from public.business_devices d where d.id=p_device_id and d.tenant_id=p_tenant_id and d.location_id=v.location_id and d.status='active') then raise exception 'Invalid POS/device for this loan location';end if;if v.status='active' then return jsonb_build_object('success',true,'loan_id',v.id,'status','active','idempotent',true);end if;if v.status<>'approved' then raise exception 'Only Approved loans can be activated';end if;if coalesce(p_disbursement_date,current_date)>v.first_payment_date then raise exception 'First payment date cannot be before funding date';end if;
 delete from public.loan_schedule_v490 where tenant_id=p_tenant_id and loan_id=p_loan_id;v_ppy:=private.loan_v490_periods_per_year(v.repayment_frequency);v_pr:=case when v_ppy=0 then 0 else v.interest_rate/100.0/v_ppy end;v_bal:=v.principal_amount;
 if v.amortization_method='flat' then v_flat:=round(v.principal_amount*v.interest_rate/100.0*(v.repayment_term_count/v_ppy),2);v_inst:=round((v.principal_amount+v_flat)/v.repayment_term_count,2);elsif abs(v_pr)<0.000000001 then v_inst:=round(v.principal_amount/v.repayment_term_count,2);else v_inst:=round(v.principal_amount*v_pr/(1-power(1+v_pr,-v.repayment_term_count)),2);end if;
 for i in 1..v.repayment_term_count loop v_due:=private.loan_v490_due_date(v.first_payment_date,v.repayment_frequency,i-1);if i=v.repayment_term_count or v_due>v.maturity_date then v_due:=v.maturity_date;end if;if v.amortization_method='flat' then v_int:=case when i=v.repayment_term_count then round(v_flat-coalesce((select sum(interest_due) from public.loan_schedule_v490 where loan_id=p_loan_id),0),2) else round(v_flat/v.repayment_term_count,2) end;v_prin:=case when i=v.repayment_term_count then round(v_bal,2) else least(round(v.principal_amount/v.repayment_term_count,2),v_bal) end;else v_int:=round(v_bal*v_pr,2);v_prin:=case when i=v.repayment_term_count then round(v_bal,2) else least(greatest(round(v_inst-v_int,2),0),v_bal) end;end if;insert into public.loan_schedule_v490(tenant_id,loan_id,installment_no,due_date,opening_principal,principal_due,interest_due,status) values(p_tenant_id,p_loan_id,i,v_due,round(v_bal,2),v_prin,v_int,case when v_due<=current_date then 'due' else 'pending' end);v_bal:=greatest(v_bal-v_prin,0);end loop;
 update public.loan_accounts_v490 set status='active',disbursement_date=coalesce(p_disbursement_date,current_date),disbursed_by=auth.uid(),disbursed_at=now(),principal_outstanding=principal_amount,updated_by=auth.uid(),updated_at=now() where id=p_loan_id;
 if v.accounting_enabled then perform private.v491_ensure_financial_mappings(p_tenant_id); if v.direction='given' then v_lines:=jsonb_build_array(jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'loan_receivable'),'debit',v.principal_amount,'credit',0,'party_type',v.counterparty_type,'party_id',coalesce(v.client_id,v.supplier_id),'description','Loan given principal'),jsonb_build_object('account_id',private.v4_payment_account(p_tenant_id,p_payment_method),'debit',0,'credit',v.principal_amount,'description','Loan given funding')); else v_lines:=jsonb_build_array(jsonb_build_object('account_id',private.v4_payment_account(p_tenant_id,p_payment_method),'debit',v.principal_amount,'credit',0,'description','Loan taken funds received'),jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'loan_payable'),'debit',0,'credit',v.principal_amount,'party_type',v.counterparty_type,'party_id',coalesce(v.client_id,v.supplier_id),'description','Loan taken principal payable'));end if;perform private.v4_journal_create(p_tenant_id,v.location_id,coalesce(p_disbursement_date,current_date),'Loan activation '||v.loan_number,'loan_activation_v491',v.id,v.loan_number,v_lines); if p_device_id is not null and lower(coalesce(p_payment_method,''))='cash' then select id into v_shift from public.cashier_shifts where tenant_id=p_tenant_id and device_id=p_device_id and status='open' order by opened_at desc limit 1; if v_shift is not null then insert into public.cash_drawer_movements(tenant_id,shift_id,movement_type,amount,reference_type,reference_id,reference_number,note,created_by) values(p_tenant_id,v_shift,case when v.direction='given' then 'cash_out' else 'cash_in' end,case when v.direction='given' then -abs(v.principal_amount) else abs(v.principal_amount) end,'loan_activation_v491',v.id,v.loan_number,case when v.direction='given' then 'Loan given' else 'Loan taken funds received' end,auth.uid()); end if; end if;end if;
 insert into public.loan_rate_history_v490(tenant_id,loan_id,effective_date,previous_rate,new_rate,rate_index,rate_margin,reason,changed_by) values(p_tenant_id,p_loan_id,coalesce(p_disbursement_date,current_date),null,v.interest_rate,v.rate_index,v.rate_margin,'Initial effective rate',auth.uid());perform private.loan_v490_refresh(p_tenant_id,p_loan_id);perform private.loan_v490_event(p_tenant_id,p_loan_id,'activated',case when v.direction='given' then 'Loan funds given' else 'Loan funds received' end,jsonb_build_object('direction',v.direction,'amount',v.principal_amount,'payment_method',p_payment_method,'accounting_enabled',v.accounting_enabled));return jsonb_build_object('success',true,'loan_id',v.id,'status','active','direction',v.direction);
end $$;


--
-- Name: loan_collateral_save_v490(uuid, uuid, uuid, text, text, text, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loan_collateral_save_v490(p_tenant_id uuid, p_loan_id uuid, p_collateral_id uuid, p_type text, p_description text, p_reference_number text, p_estimated_value numeric, p_status text DEFAULT 'active'::text, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v public.loan_accounts_v490%rowtype;v_id uuid:=coalesce(p_collateral_id,gen_random_uuid());begin
  select * into v from public.loan_accounts_v490 where tenant_id=p_tenant_id and id=p_loan_id;if not found then raise exception 'Loan not found';end if;
  perform private.loan_v490_access(p_tenant_id,v.location_id,'loans.manage','manage');
  if nullif(trim(coalesce(p_type,'')),'') is null or nullif(trim(coalesce(p_description,'')),'') is null then raise exception 'Collateral type and description are required';end if;
  insert into public.loan_collateral_v490(id,tenant_id,loan_id,collateral_type,description,reference_number,estimated_value,status,notes,created_by)
  values(v_id,p_tenant_id,p_loan_id,trim(p_type),trim(p_description),nullif(trim(coalesce(p_reference_number,'')),''),greatest(coalesce(p_estimated_value,0),0),coalesce(nullif(lower(trim(p_status)),''),'active'),nullif(trim(coalesce(p_notes,'')),''),auth.uid())
  on conflict(id) do update set collateral_type=excluded.collateral_type,description=excluded.description,reference_number=excluded.reference_number,estimated_value=excluded.estimated_value,status=excluded.status,notes=excluded.notes,updated_at=now();
  perform private.loan_v490_event(p_tenant_id,p_loan_id,'collateral_updated','Loan collateral updated');return v_id;
end $$;


--
-- Name: loan_create_v490(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loan_create_v490(p_tenant_id uuid, p_location_id uuid, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_id uuid:=gen_random_uuid();v_no text;v_client uuid;v_principal numeric;v_rate numeric;v_rate_type text;
  v_freq text;v_terms integer;v_first date;v_maturity date;v_amort text;v_penalty numeric;
begin
  perform private.loan_v490_access(p_tenant_id,p_location_id,'loans.create','operate');
  v_client:=nullif(p_payload->>'client_id','')::uuid;
  if v_client is null or not exists(select 1 from public.customers where id=v_client and tenant_id=p_tenant_id and coalesce(status,'active')='active' and not coalesce(is_walk_in,false)) then raise exception 'An active non-walk-in client/customer is required';end if;
  v_principal:=coalesce(nullif(p_payload->>'principal_amount','')::numeric,0);if v_principal<=0 then raise exception 'Principal amount must be positive';end if;
  v_rate:=coalesce(nullif(p_payload->>'interest_rate','')::numeric,0);if v_rate<0 or v_rate>1000 then raise exception 'Invalid interest rate';end if;
  v_rate_type:=lower(coalesce(nullif(p_payload->>'rate_type',''),'fixed'));if v_rate_type not in('fixed','variable') then raise exception 'Rate type must be fixed or variable';end if;
  v_freq:=lower(coalesce(nullif(p_payload->>'repayment_frequency',''),'monthly'));
  if v_freq not in('weekly','biweekly','monthly','quarterly','half_yearly','yearly') then raise exception 'Invalid repayment frequency';end if;
  v_terms:=coalesce(nullif(p_payload->>'repayment_term_count','')::integer,0);if v_terms<=0 or v_terms>1200 then raise exception 'Invalid repayment term count';end if;
  v_first:=nullif(p_payload->>'first_payment_date','')::date;if v_first is null then raise exception 'First payment date is required';end if;
  v_maturity:=coalesce(nullif(p_payload->>'maturity_date','')::date,private.loan_v490_due_date(v_first,v_freq,v_terms-1));
  if v_maturity<v_first then raise exception 'Maturity date cannot be before first payment date';end if;
  if v_terms>1 and v_maturity<private.loan_v490_due_date(v_first,v_freq,v_terms-2) then raise exception 'Maturity date is too early for the selected repayment terms';end if;
  v_amort:=lower(coalesce(nullif(p_payload->>'amortization_method',''),'reducing_balance'));
  if v_amort not in('reducing_balance','flat') then raise exception 'Invalid amortization method';end if;
  v_penalty:=coalesce(nullif(p_payload->>'penalty_rate','')::numeric,0);if v_penalty<0 or v_penalty>1000 then raise exception 'Invalid penalty rate';end if;
  if v_rate_type='variable' and nullif(trim(coalesce(p_payload->>'rate_index','')),'') is null then raise exception 'Variable-rate loans require a rate index';end if;

  v_no:='LOAN-'||lpad(nextval('public.loan_number_seq_v490')::text,8,'0');
  insert into public.loan_accounts_v490(
    id,tenant_id,location_id,loan_number,client_id,external_client_reference,purpose,principal_amount,interest_rate,rate_type,
    rate_index,rate_margin,rate_reset_frequency,next_rate_review_date,amortization_method,repayment_frequency,repayment_term_count,
    repayment_terms,first_payment_date,maturity_date,payment_warning_days,maturity_warning_days,grace_days,penalty_rate,
    collateral_summary,notes,status,created_by,updated_by
  ) values(
    v_id,p_tenant_id,p_location_id,v_no,v_client,nullif(trim(coalesce(p_payload->>'external_client_reference','')),''),
    nullif(trim(coalesce(p_payload->>'purpose','')),''),v_principal,v_rate,v_rate_type,
    nullif(trim(coalesce(p_payload->>'rate_index','')),''),coalesce(nullif(p_payload->>'rate_margin','')::numeric,0),
    nullif(lower(trim(coalesce(p_payload->>'rate_reset_frequency',''))),''),nullif(p_payload->>'next_rate_review_date','')::date,
    v_amort,v_freq,v_terms,nullif(trim(coalesce(p_payload->>'repayment_terms','')),''),v_first,v_maturity,
    coalesce(nullif(p_payload->>'payment_warning_days','')::integer,5),coalesce(nullif(p_payload->>'maturity_warning_days','')::integer,30),
    coalesce(nullif(p_payload->>'grace_days','')::integer,0),v_penalty,
    nullif(trim(coalesce(p_payload->>'collateral_summary','')),''),nullif(trim(coalesce(p_payload->>'notes','')),''),'draft',auth.uid(),auth.uid()
  );
  perform private.loan_v490_event(p_tenant_id,v_id,'created','Loan created',jsonb_build_object('principal_amount',v_principal,'rate_type',v_rate_type,'interest_rate',v_rate));
  perform private.thq_sync_bump_v480(p_tenant_id,'finance','loan',v_id::text,'create');
  return jsonb_build_object('success',true,'loan_id',v_id,'loan_number',v_no,'status','draft');
end $$;


--
-- Name: loan_create_v491(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loan_create_v491(p_tenant_id uuid, p_location_id uuid, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_id uuid:=gen_random_uuid();v_no text;v_client uuid;v_supplier uuid;v_dir text;v_party text;v_name text;v_principal numeric;v_rate numeric;v_rate_type text;v_freq text;v_terms int;v_first date;v_mat date;v_amort text;begin
 perform private.loan_v490_access(p_tenant_id,p_location_id,'loans.create','operate');
 v_dir:=lower(coalesce(nullif(p_payload->>'direction',''),'given')); if v_dir not in('given','taken') then raise exception 'Loan direction must be given or taken';end if;
 v_party:=lower(coalesce(nullif(p_payload->>'counterparty_type',''),case when v_dir='given' then 'customer' else 'supplier' end)); if v_party not in('customer','supplier','other') then raise exception 'Invalid loan counterparty type'; end if;
 v_client:=nullif(p_payload->>'client_id','')::uuid; v_supplier:=nullif(p_payload->>'supplier_id','')::uuid;
 if v_party='customer' then select name into v_name from public.customers where id=v_client and tenant_id=p_tenant_id and coalesce(status,'active')='active' and not coalesce(is_walk_in,false); if v_name is null then raise exception 'Active non-walk-in customer/client is required';end if;
 elsif v_party='supplier' then select name into v_name from public.suppliers where id=v_supplier and tenant_id=p_tenant_id and coalesce(status,'active')='active'; if v_name is null then raise exception 'Active supplier/lender is required';end if;
 else v_name:=nullif(trim(coalesce(p_payload->>'counterparty_name','')),''); if v_name is null then raise exception 'Lender/borrower name is required';end if; end if;
 v_principal:=coalesce(nullif(p_payload->>'principal_amount','')::numeric,0); if v_principal<=0 then raise exception 'Principal amount must be positive';end if;
 v_rate:=coalesce(nullif(p_payload->>'interest_rate','')::numeric,0); if v_rate<0 or v_rate>1000 then raise exception 'Invalid interest rate';end if;
 v_rate_type:=lower(coalesce(nullif(p_payload->>'rate_type',''),'fixed')); if v_rate_type not in('fixed','variable') then raise exception 'Invalid interest type';end if;
 v_freq:=lower(coalesce(nullif(p_payload->>'repayment_frequency',''),'monthly')); if v_freq not in('weekly','biweekly','monthly','quarterly','half_yearly','yearly') then raise exception 'Invalid repayment frequency';end if;
 v_terms:=coalesce(nullif(p_payload->>'repayment_term_count','')::int,0); if v_terms<=0 or v_terms>1200 then raise exception 'Invalid repayment terms';end if;
 v_first:=nullif(p_payload->>'first_payment_date','')::date; if v_first is null then raise exception 'First payment date is required';end if;
 v_mat:=coalesce(nullif(p_payload->>'maturity_date','')::date,private.loan_v490_due_date(v_first,v_freq,v_terms-1)); if v_mat<v_first then raise exception 'Maturity date cannot be before first payment date';end if; if v_terms>1 and v_mat<private.loan_v490_due_date(v_first,v_freq,v_terms-2) then raise exception 'Maturity date is too early for the selected repayment terms';end if;
 v_amort:=lower(coalesce(nullif(p_payload->>'amortization_method',''),'reducing_balance')); if v_amort not in('reducing_balance','flat') then raise exception 'Invalid amortization method';end if;
 if v_rate_type='variable' and nullif(trim(coalesce(p_payload->>'rate_index','')),'') is null then raise exception 'Variable-rate loans require a rate index';end if;
 v_no:=case when v_dir='given' then 'LG-' else 'LT-' end||lpad(nextval('public.loan_number_seq_v490')::text,8,'0');
 insert into public.loan_accounts_v490(id,tenant_id,location_id,loan_number,client_id,supplier_id,direction,counterparty_type,counterparty_name,counterparty_reference,external_client_reference,purpose,principal_amount,interest_rate,rate_type,rate_index,rate_margin,rate_reset_frequency,next_rate_review_date,amortization_method,repayment_frequency,repayment_term_count,repayment_terms,first_payment_date,maturity_date,payment_warning_days,maturity_warning_days,grace_days,penalty_rate,collateral_summary,notes,status,accounting_enabled,created_by,updated_by)
 values(v_id,p_tenant_id,p_location_id,v_no,v_client,v_supplier,v_dir,v_party,v_name,nullif(trim(coalesce(p_payload->>'counterparty_reference','')),''),nullif(trim(coalesce(p_payload->>'external_client_reference','')),''),nullif(trim(coalesce(p_payload->>'purpose','')),''),v_principal,v_rate,v_rate_type,nullif(trim(coalesce(p_payload->>'rate_index','')),''),coalesce(nullif(p_payload->>'rate_margin','')::numeric,0),nullif(lower(trim(coalesce(p_payload->>'rate_reset_frequency',''))),''),nullif(p_payload->>'next_rate_review_date','')::date,v_amort,v_freq,v_terms,nullif(trim(coalesce(p_payload->>'repayment_terms','')),''),v_first,v_mat,coalesce(nullif(p_payload->>'payment_warning_days','')::int,5),coalesce(nullif(p_payload->>'maturity_warning_days','')::int,30),coalesce(nullif(p_payload->>'grace_days','')::int,0),coalesce(nullif(p_payload->>'penalty_rate','')::numeric,0),nullif(trim(coalesce(p_payload->>'collateral_summary','')),''),nullif(trim(coalesce(p_payload->>'notes','')),''),'draft',private.loan_v491_accounting_enabled(p_tenant_id),auth.uid(),auth.uid());
 perform private.loan_v490_event(p_tenant_id,v_id,'created',case when v_dir='given' then 'Loan given created' else 'Loan taken created' end,jsonb_build_object('direction',v_dir,'counterparty_type',v_party,'counterparty_name',v_name,'principal_amount',v_principal,'accounting_enabled',private.loan_v491_accounting_enabled(p_tenant_id)));
 return jsonb_build_object('success',true,'loan_id',v_id,'loan_number',v_no,'direction',v_dir,'status','draft');
end $$;


--
-- Name: loan_dashboard_v490(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loan_dashboard_v490(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_result jsonb;begin
  perform private.loan_v490_access(p_tenant_id,p_location_id,'loans.view','view');
  with scoped as(
    select l.* from public.loan_accounts_v490 l
    where l.tenant_id=p_tenant_id
      and (p_location_id is null or l.location_id=p_location_id)
      and private.erp_document_scope_allowed(p_tenant_id,l.location_id,p_location_id,'view')
  ), overdue as(
    select count(*)::bigint installments,
      count(distinct l.id)::bigint loans,
      round(coalesce(sum(greatest(s.principal_due-s.principal_paid,0)+greatest(s.interest_due-s.interest_paid,0)+greatest(s.penalty_due-s.penalty_paid,0)),0),2) amount
    from scoped l join public.loan_schedule_v490 s on s.loan_id=l.id and s.tenant_id=l.tenant_id
    where l.status in('active','defaulted') and s.status<>'waived'
      and current_date>s.due_date+l.grace_days
      and (s.principal_due+s.interest_due+s.penalty_due)-(s.principal_paid+s.interest_paid+s.penalty_paid)>0.005
  ), due7 as(
    select count(*)::bigint installments,
      round(coalesce(sum(greatest(s.principal_due-s.principal_paid,0)+greatest(s.interest_due-s.interest_paid,0)+greatest(s.penalty_due-s.penalty_paid,0)),0),2) amount
    from scoped l join public.loan_schedule_v490 s on s.loan_id=l.id and s.tenant_id=l.tenant_id
    where l.status in('active','defaulted') and s.status<>'waived' and s.due_date between current_date and current_date+7
      and (s.principal_due+s.interest_due+s.penalty_due)-(s.principal_paid+s.interest_paid+s.penalty_paid)>0.005
  ), collected as(
    select round(coalesce(sum(p.amount),0),2) amount
    from public.loan_payments_v490 p join scoped l on l.id=p.loan_id
    where p.status='posted' and p.payment_date=current_date
  )
  select jsonb_build_object(
    'total_loans',count(*),
    'draft',count(*) filter(where s.status='draft'),
    'submitted',count(*) filter(where s.status='submitted'),
    'approved',count(*) filter(where s.status='approved'),
    'active',count(*) filter(where s.status='active'),
    'defaulted',count(*) filter(where s.status='defaulted'),
    'closed',count(*) filter(where s.status='closed'),
    'active_principal',round(coalesce(sum(s.principal_outstanding) filter(where s.status in('active','defaulted')),0),2),
    'outstanding_interest',round(coalesce(sum(s.interest_outstanding) filter(where s.status in('active','defaulted')),0),2),
    'outstanding_penalty',round(coalesce(sum(s.penalty_outstanding) filter(where s.status in('active','defaulted')),0),2),
    'total_outstanding',round(coalesce(sum(s.principal_outstanding+s.interest_outstanding+s.penalty_outstanding) filter(where s.status in('active','defaulted')),0),2),
    'overdue_loans',(select loans from overdue),'overdue_installments',(select installments from overdue),'overdue_amount',(select amount from overdue),
    'due_next_7_days',(select installments from due7),'due_next_7_days_amount',(select amount from due7),
    'maturing_next_30_days',count(*) filter(where s.status in('active','defaulted') and s.maturity_date between current_date and current_date+30),
    'variable_rate_reviews',count(*) filter(where s.status in('approved','active','defaulted') and s.rate_type='variable' and s.next_rate_review_date between current_date and current_date+30),
    'collections_today',(select amount from collected)
  ) into v_result from scoped s;
  return coalesce(v_result,'{}'::jsonb);
end $$;


--
-- Name: loan_dashboard_v491(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loan_dashboard_v491(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare r jsonb;begin
 perform private.loan_v490_access(p_tenant_id,p_location_id,'loans.view','view');
 with scoped as (
   select l.*
   from public.loan_accounts_v490 l
   where l.tenant_id=p_tenant_id
     and (p_location_id is null or l.location_id=p_location_id)
     and private.erp_document_scope_allowed(p_tenant_id,l.location_id,p_location_id,'view')
 ), next_due as (
   select s.loan_id,min(s.due_date) due_date
   from public.loan_schedule_v490 s
   join scoped l on l.id=s.loan_id
   where s.status<>'waived'
     and (s.principal_due+s.interest_due+s.penalty_due)-(s.principal_paid+s.interest_paid+s.penalty_paid)>0.005
   group by s.loan_id
 ), pay_today as (
   select l.direction,coalesce(sum(p.amount),0) amount
   from public.loan_payments_v490 p join scoped l on l.id=p.loan_id
   where p.status<>'reversed' and p.payment_date=current_date
   group by l.direction
 )
 select jsonb_build_object(
   'total_loans',count(*),
   'active',count(*) filter(where status='active'),
   'defaulted',count(*) filter(where status='defaulted'),
   'given_active_principal',coalesce(sum(principal_outstanding) filter(where direction='given' and status in('active','defaulted')),0),
   'taken_active_principal',coalesce(sum(principal_outstanding) filter(where direction='taken' and status in('active','defaulted')),0),
   'receivable',coalesce(sum(principal_outstanding+interest_outstanding+penalty_outstanding) filter(where direction='given' and status in('active','defaulted')),0),
   'payable',coalesce(sum(principal_outstanding+interest_outstanding+penalty_outstanding) filter(where direction='taken' and status in('active','defaulted')),0),
   'total_outstanding',coalesce(sum(principal_outstanding+interest_outstanding+penalty_outstanding) filter(where status in('active','defaulted')),0),
   'overdue_loans',count(*) filter(where status in('active','defaulted') and exists(select 1 from next_due n where n.loan_id=scoped.id and n.due_date+grace_days<current_date)),
   'maturing_next_30_days',count(*) filter(where status in('active','defaulted') and maturity_date between current_date and current_date+30),
   'collected_today',coalesce((select amount from pay_today where direction='given'),0),
   'repaid_today',coalesce((select amount from pay_today where direction='taken'),0),
   'accounting_enabled',private.loan_v491_accounting_enabled(p_tenant_id)
 ) into r from scoped;
 return coalesce(r,'{}'::jsonb);
end $$;


--
-- Name: loan_decide_v490(uuid, uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loan_decide_v490(p_tenant_id uuid, p_loan_id uuid, p_approve boolean, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v public.loan_accounts_v490%rowtype;begin
  select * into v from public.loan_accounts_v490 where tenant_id=p_tenant_id and id=p_loan_id for update;if not found then raise exception 'Loan not found';end if;
  perform private.loan_v490_access(p_tenant_id,v.location_id,'loans.approve','manage');
  if v.status<>'submitted' then raise exception 'Only Submitted loans can be approved/rejected';end if;
  if coalesce(p_approve,false) then
    update public.loan_accounts_v490 set status='approved',approved_by=auth.uid(),approved_at=now(),rejection_reason=null,rejected_by=null,rejected_at=null,updated_by=auth.uid(),updated_at=now() where id=p_loan_id;
    perform private.loan_v490_event(p_tenant_id,p_loan_id,'approved',coalesce(nullif(trim(p_note),''),'Loan approved'));
  else
    if nullif(trim(coalesce(p_note,'')),'') is null then raise exception 'Rejection reason is required';end if;
    update public.loan_accounts_v490 set status='rejected',rejected_by=auth.uid(),rejected_at=now(),rejection_reason=trim(p_note),updated_by=auth.uid(),updated_at=now() where id=p_loan_id;
    perform private.loan_v490_event(p_tenant_id,p_loan_id,'rejected',trim(p_note));
  end if;
  perform private.thq_sync_bump_v480(p_tenant_id,'finance','loan',p_loan_id::text,case when p_approve then 'approve' else 'reject' end);
  return jsonb_build_object('success',true,'loan_id',p_loan_id,'status',case when p_approve then 'approved' else 'rejected' end);
end $$;


--
-- Name: loan_detail_v490(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loan_detail_v490(p_tenant_id uuid, p_loan_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v public.loan_accounts_v490%rowtype;v_result jsonb;begin
  select * into v from public.loan_accounts_v490 where tenant_id=p_tenant_id and id=p_loan_id;
  if not found then raise exception 'Loan not found';end if;
  perform private.loan_v490_access(p_tenant_id,v.location_id,'loans.view','view');
  if v.status in('active','defaulted','closed') then perform private.loan_v490_refresh(p_tenant_id,p_loan_id);end if;
  select jsonb_build_object(
    'loan',to_jsonb(l)||jsonb_build_object(
      'total_outstanding',round(l.principal_outstanding+l.interest_outstanding+l.penalty_outstanding,2),
      'client_name',c.name,'client_public_id',c.tracking_code,'client_phone',c.phone,'client_email',c.email,
      'location_name',bl.name,'location_code',bl.location_code
    ),
    'customer',jsonb_build_object('id',c.id,'public_id',c.tracking_code,'name',c.name,'phone',c.phone,'email',c.email,'tax_number',c.tax_number,'credit_limit',c.credit_limit,'status',c.status),
    'schedule',coalesce((select jsonb_agg(to_jsonb(s) order by s.installment_no) from public.loan_schedule_v490 s where s.tenant_id=p_tenant_id and s.loan_id=l.id),'[]'::jsonb),
    'payments',coalesce((select jsonb_agg(to_jsonb(p) order by p.payment_date desc,p.created_at desc) from public.loan_payments_v490 p where p.tenant_id=p_tenant_id and p.loan_id=l.id),'[]'::jsonb),
    'rate_history',coalesce((select jsonb_agg(to_jsonb(r) order by r.effective_date desc,r.changed_at desc) from public.loan_rate_history_v490 r where r.tenant_id=p_tenant_id and r.loan_id=l.id),'[]'::jsonb),
    'collateral',coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at) from public.loan_collateral_v490 x where x.tenant_id=p_tenant_id and x.loan_id=l.id),'[]'::jsonb),
    'guarantors',coalesce((select jsonb_agg(to_jsonb(g) order by g.created_at) from public.loan_guarantors_v490 g where g.tenant_id=p_tenant_id and g.loan_id=l.id),'[]'::jsonb),
    'events',coalesce((select jsonb_agg(to_jsonb(e) order by e.event_date desc) from public.loan_events_v490 e where e.tenant_id=p_tenant_id and e.loan_id=l.id),'[]'::jsonb)
  ) into v_result
  from public.loan_accounts_v490 l
  join public.customers c on c.id=l.client_id
  join public.business_locations bl on bl.id=l.location_id
  where l.tenant_id=p_tenant_id and l.id=p_loan_id;
  return v_result;
end $$;


--
-- Name: loan_detail_v491(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loan_detail_v491(p_tenant_id uuid, p_loan_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v public.loan_accounts_v490%rowtype;begin
 select * into v from public.loan_accounts_v490 where tenant_id=p_tenant_id and id=p_loan_id; if not found then raise exception 'Loan not found';end if; perform private.loan_v490_access(p_tenant_id,v.location_id,'loans.view','view'); if v.status in('active','defaulted','closed') then perform private.loan_v490_refresh(p_tenant_id,p_loan_id); select * into v from public.loan_accounts_v490 where id=p_loan_id;end if;
 return jsonb_build_object('loan',to_jsonb(v)||jsonb_build_object('total_outstanding',round(v.principal_outstanding+v.interest_outstanding+v.penalty_outstanding,2),'client_name',v.counterparty_name,'client_public_id',coalesce(v.counterparty_reference,''),'location_name',(select name from public.business_locations where id=v.location_id)),'counterparty',private.loan_v491_party_json(v),'schedule',coalesce((select jsonb_agg(to_jsonb(s) order by s.installment_no) from public.loan_schedule_v490 s where s.loan_id=v.id),'[]'::jsonb),'payments',coalesce((select jsonb_agg(to_jsonb(p) order by p.payment_date desc,p.created_at desc) from public.loan_payments_v490 p where p.loan_id=v.id),'[]'::jsonb),'rate_history',coalesce((select jsonb_agg(to_jsonb(r) order by r.effective_date desc) from public.loan_rate_history_v490 r where r.loan_id=v.id),'[]'::jsonb),'collateral',coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at) from public.loan_collateral_v490 x where x.loan_id=v.id),'[]'::jsonb),'guarantors',coalesce((select jsonb_agg(to_jsonb(g) order by g.created_at) from public.loan_guarantors_v490 g where g.loan_id=v.id),'[]'::jsonb),'events',coalesce((select jsonb_agg(to_jsonb(e) order by e.event_date desc) from public.loan_events_v490 e where e.loan_id=v.id),'[]'::jsonb),'settings',jsonb_build_object('reflect_in_accounting',v.accounting_enabled));
end $$;


--
-- Name: loan_disburse_v490(uuid, uuid, date, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loan_disburse_v490(p_tenant_id uuid, p_loan_id uuid, p_disbursement_date date DEFAULT CURRENT_DATE, p_payment_method text DEFAULT 'bank'::text, p_reference_number text DEFAULT NULL::text, p_device_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v public.loan_accounts_v490%rowtype;v_ppy numeric;v_period_rate numeric;v_installment numeric;v_flat_interest numeric;
  v_balance numeric;v_interest numeric;v_principal numeric;v_due date;v_i integer;v_lines jsonb;v_shift uuid;
begin
  select * into v from public.loan_accounts_v490 where tenant_id=p_tenant_id and id=p_loan_id for update;if not found then raise exception 'Loan not found';end if;
  perform private.loan_v490_access(p_tenant_id,v.location_id,'loans.disburse','manage');
  if p_device_id is not null and not exists(
    select 1 from public.business_devices d where d.id=p_device_id and d.tenant_id=p_tenant_id and d.location_id=v.location_id and d.status='active'
  ) then raise exception 'Invalid POS/device for this loan location';end if;
  if v.status='active' then return jsonb_build_object('success',true,'loan_id',v.id,'loan_number',v.loan_number,'status','active','idempotent',true);end if;
  if v.status<>'approved' then raise exception 'Only Approved loans can be disbursed';end if;
  if coalesce(p_disbursement_date,current_date)>v.first_payment_date then raise exception 'First payment date cannot be before disbursement date';end if;
  delete from public.loan_schedule_v490 where tenant_id=p_tenant_id and loan_id=p_loan_id;
  v_ppy:=private.loan_v490_periods_per_year(v.repayment_frequency);
  v_period_rate:=case when v_ppy=0 then 0 else v.interest_rate/100.0/v_ppy end;
  v_balance:=v.principal_amount;
  if v.amortization_method='flat' then
    v_flat_interest:=round(v.principal_amount*v.interest_rate/100.0*(v.repayment_term_count/v_ppy),2);
    v_installment:=round((v.principal_amount+v_flat_interest)/v.repayment_term_count,2);
  elsif abs(v_period_rate)<0.000000001 then
    v_installment:=round(v.principal_amount/v.repayment_term_count,2);
  else
    v_installment:=round(v.principal_amount*v_period_rate/(1-power(1+v_period_rate,-v.repayment_term_count)),2);
  end if;

  for v_i in 1..v.repayment_term_count loop
    v_due:=private.loan_v490_due_date(v.first_payment_date,v.repayment_frequency,v_i-1);
    if v_i=v.repayment_term_count or v_due>v.maturity_date then v_due:=v.maturity_date;end if;
    if v.amortization_method='flat' then
      v_interest:=case when v_i=v.repayment_term_count then round(v_flat_interest-coalesce((select sum(interest_due) from public.loan_schedule_v490 where loan_id=p_loan_id),0),2) else round(v_flat_interest/v.repayment_term_count,2) end;
      v_principal:=case when v_i=v.repayment_term_count then round(v_balance,2) else least(round(v.principal_amount/v.repayment_term_count,2),v_balance) end;
    else
      v_interest:=round(v_balance*v_period_rate,2);
      v_principal:=case when v_i=v.repayment_term_count then round(v_balance,2) else least(greatest(round(v_installment-v_interest,2),0),v_balance) end;
    end if;
    insert into public.loan_schedule_v490(tenant_id,loan_id,installment_no,due_date,opening_principal,principal_due,interest_due,status)
    values(p_tenant_id,p_loan_id,v_i,v_due,round(v_balance,2),v_principal,v_interest,case when v_due<=current_date then 'due' else 'pending' end);
    v_balance:=greatest(v_balance-v_principal,0);
  end loop;

  update public.loan_accounts_v490 set status='active',disbursement_date=coalesce(p_disbursement_date,current_date),disbursed_by=auth.uid(),disbursed_at=now(),
    principal_outstanding=principal_amount,updated_by=auth.uid(),updated_at=now() where id=p_loan_id;

  v_lines:=jsonb_build_array(
    jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'loan_receivable'),'debit',v.principal_amount,'credit',0,'party_type','customer','party_id',v.client_id,'description','Loan principal advanced'),
    jsonb_build_object('account_id',private.v4_payment_account(p_tenant_id,p_payment_method),'debit',0,'credit',v.principal_amount,'party_type','customer','party_id',v.client_id,'description','Loan disbursement')
  );
  perform private.v4_journal_create(p_tenant_id,v.location_id,coalesce(p_disbursement_date,current_date),'Loan disbursement '||v.loan_number,'loan_disbursement_v490',v.id,v.loan_number,v_lines);

  if p_device_id is not null and lower(coalesce(p_payment_method,''))='cash' then
    select id into v_shift from public.cashier_shifts where tenant_id=p_tenant_id and device_id=p_device_id and status='open' order by opened_at desc limit 1;
    if v_shift is not null then
      insert into public.cash_drawer_movements(tenant_id,shift_id,movement_type,amount,reference_type,reference_id,reference_number,note,created_by)
      values(p_tenant_id,v_shift,'cash_out',-abs(v.principal_amount),'loan_disbursement_v490',v.id,v.loan_number,'Loan disbursement',auth.uid());
    end if;
  end if;

  insert into public.loan_rate_history_v490(tenant_id,loan_id,effective_date,previous_rate,new_rate,rate_index,rate_margin,reason,changed_by)
  values(p_tenant_id,p_loan_id,coalesce(p_disbursement_date,current_date),null,v.interest_rate,v.rate_index,v.rate_margin,'Initial effective rate',auth.uid());
  perform private.loan_v490_refresh(p_tenant_id,p_loan_id);
  perform private.loan_v490_event(p_tenant_id,p_loan_id,'disbursed','Loan disbursed',jsonb_build_object('amount',v.principal_amount,'payment_method',p_payment_method,'reference_number',p_reference_number));
  perform private.thq_sync_bump_v480(p_tenant_id,'finance','loan',p_loan_id::text,'disburse');
  return jsonb_build_object('success',true,'loan_id',v.id,'loan_number',v.loan_number,'status','active','principal_amount',v.principal_amount);
end $$;


--
-- Name: loan_guarantor_save_v490(uuid, uuid, uuid, uuid, text, text, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loan_guarantor_save_v490(p_tenant_id uuid, p_loan_id uuid, p_guarantor_id uuid, p_customer_id uuid, p_name text, p_phone text, p_email text, p_guarantee_amount numeric, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v public.loan_accounts_v490%rowtype;v_id uuid:=coalesce(p_guarantor_id,gen_random_uuid());begin
  select * into v from public.loan_accounts_v490 where tenant_id=p_tenant_id and id=p_loan_id;if not found then raise exception 'Loan not found';end if;
  perform private.loan_v490_access(p_tenant_id,v.location_id,'loans.manage','manage');
  if p_customer_id is not null and not exists(select 1 from public.customers where id=p_customer_id and tenant_id=p_tenant_id) then raise exception 'Guarantor customer not found';end if;
  if nullif(trim(coalesce(p_name,'')),'') is null then raise exception 'Guarantor name is required';end if;
  insert into public.loan_guarantors_v490(id,tenant_id,loan_id,customer_id,name,phone,email,guarantee_amount,notes,created_by)
  values(v_id,p_tenant_id,p_loan_id,p_customer_id,trim(p_name),nullif(trim(coalesce(p_phone,'')),''),nullif(trim(coalesce(p_email,'')),''),p_guarantee_amount,nullif(trim(coalesce(p_notes,'')),''),auth.uid())
  on conflict(id) do update set customer_id=excluded.customer_id,name=excluded.name,phone=excluded.phone,email=excluded.email,guarantee_amount=excluded.guarantee_amount,notes=excluded.notes,updated_at=now();
  perform private.loan_v490_event(p_tenant_id,p_loan_id,'guarantor_updated','Loan guarantor updated');return v_id;
end $$;


--
-- Name: loan_list_v490(uuid, uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loan_list_v490(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_query text DEFAULT ''::text, p_limit integer DEFAULT 500) RETURNS TABLE(loan_id uuid, loan_number text, client_id uuid, client_public_id text, client_name text, location_id uuid, location_name text, purpose text, principal_amount numeric, interest_rate numeric, rate_type text, rate_index text, rate_margin numeric, amortization_method text, repayment_frequency text, repayment_term_count integer, repayment_terms text, first_payment_date date, maturity_date date, disbursement_date date, status text, principal_outstanding numeric, interest_outstanding numeric, penalty_outstanding numeric, total_outstanding numeric, total_paid numeric, next_due_date date, next_due_amount numeric, overdue_installments bigint, overdue_amount numeric, days_to_maturity integer, warning_level text, warning_message text, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_q text:='%'||lower(trim(coalesce(p_query,'')))||'%';begin
  perform private.loan_v490_access(p_tenant_id,p_location_id,'loans.view','view');
  return query
  select
    l.id,l.loan_number,l.client_id,c.tracking_code,c.name,l.location_id,bl.name,l.purpose,
    l.principal_amount,l.interest_rate,l.rate_type,l.rate_index,l.rate_margin,l.amortization_method,
    l.repayment_frequency,l.repayment_term_count,l.repayment_terms,l.first_payment_date,l.maturity_date,l.disbursement_date,l.status,
    l.principal_outstanding,l.interest_outstanding,l.penalty_outstanding,
    round(l.principal_outstanding+l.interest_outstanding+l.penalty_outstanding,2),l.total_paid,
    nd.due_date,coalesce(nd.due_amount,0),coalesce(ov.cnt,0),coalesce(ov.amount,0),
    (l.maturity_date-current_date)::integer,
    case
      when coalesce(ov.cnt,0)>0 then 'danger'
      when l.status in('active','defaulted') and l.maturity_date between current_date and current_date+l.maturity_warning_days then 'warning'
      when l.status in('active','defaulted') and nd.due_date is not null and nd.due_date<=current_date+l.payment_warning_days then 'warning'
      when l.rate_type='variable' and l.next_rate_review_date is not null and l.next_rate_review_date<=current_date+l.payment_warning_days then 'info'
      when l.status='defaulted' then 'danger'
      else 'normal' end,
    case
      when coalesce(ov.cnt,0)>0 then coalesce(ov.cnt,0)::text||' overdue installment(s)'
      when l.status in('active','defaulted') and l.maturity_date between current_date and current_date+l.maturity_warning_days then 'Matures in '||(l.maturity_date-current_date)::text||' day(s)'
      when l.status in('active','defaulted') and nd.due_date is not null and nd.due_date<=current_date+l.payment_warning_days then 'Payment due '||to_char(nd.due_date,'DD Mon YYYY')
      when l.rate_type='variable' and l.next_rate_review_date is not null and l.next_rate_review_date<=current_date+l.payment_warning_days then 'Variable rate review due '||to_char(l.next_rate_review_date,'DD Mon YYYY')
      when l.status='defaulted' then 'Loan marked defaulted'
      else null end,
    l.created_at,l.updated_at
  from public.loan_accounts_v490 l
  join public.customers c on c.id=l.client_id and c.tenant_id=l.tenant_id
  join public.business_locations bl on bl.id=l.location_id
  left join lateral(
    select s.due_date,
      round(greatest(s.principal_due-s.principal_paid,0)+greatest(s.interest_due-s.interest_paid,0)+greatest(s.penalty_due-s.penalty_paid,0),2) due_amount
    from public.loan_schedule_v490 s
    where s.tenant_id=l.tenant_id and s.loan_id=l.id and s.status<>'waived'
      and (s.principal_due+s.interest_due+s.penalty_due)-(s.principal_paid+s.interest_paid+s.penalty_paid)>0.005
    order by s.due_date,s.installment_no limit 1
  ) nd on true
  left join lateral(
    select count(*)::bigint cnt,
      round(coalesce(sum(greatest(s.principal_due-s.principal_paid,0)+greatest(s.interest_due-s.interest_paid,0)+greatest(s.penalty_due-s.penalty_paid,0)),0),2) amount
    from public.loan_schedule_v490 s
    where s.tenant_id=l.tenant_id and s.loan_id=l.id and s.status<>'waived'
      and current_date>s.due_date+l.grace_days
      and (s.principal_due+s.interest_due+s.penalty_due)-(s.principal_paid+s.interest_paid+s.penalty_paid)>0.005
  ) ov on true
  where l.tenant_id=p_tenant_id
    and (p_location_id is null or l.location_id=p_location_id)
    and (p_status is null or trim(p_status)='' or l.status=lower(trim(p_status)))
    and private.erp_document_scope_allowed(p_tenant_id,l.location_id,p_location_id,'view')
    and (trim(coalesce(p_query,''))='' or lower(concat_ws(' ',l.loan_number,c.name,c.tracking_code,l.external_client_reference,l.purpose,l.status)) like v_q)
  order by case when coalesce(ov.cnt,0)>0 then 0 when l.status in('active','defaulted') then 1 else 2 end,l.updated_at desc
  limit least(greatest(coalesce(p_limit,500),1),2000);
end $$;


--
-- Name: loan_list_v491(uuid, uuid, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loan_list_v491(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_direction text DEFAULT NULL::text, p_query text DEFAULT ''::text, p_limit integer DEFAULT 500) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare result jsonb; begin
 perform private.loan_v490_access(p_tenant_id,p_location_id,'loans.view','view');
 select coalesce(jsonb_agg(x order by (x->>'warning_rank')::int,(x->>'updated_at') desc),'[]'::jsonb) into result from (
  select to_jsonb(l)||private.loan_v491_party_json(l)||jsonb_build_object('loan_id',l.id,'client_name',coalesce(l.counterparty_name,c.name,s.name),'client_public_id',coalesce(c.tracking_code,s.tracking_code,l.counterparty_reference,''),'total_outstanding',round(l.principal_outstanding+l.interest_outstanding+l.penalty_outstanding,2),'next_due_date',nd.due_date,'next_due_amount',coalesce(nd.amount,0),'warning_level',case when coalesce(ov.cnt,0)>0 then 'danger' when l.status='defaulted' then 'danger' when nd.due_date<=current_date+l.payment_warning_days then 'warning' else 'normal' end,'warning_message',case when coalesce(ov.cnt,0)>0 then ov.cnt||' overdue installment(s)' when nd.due_date<=current_date+l.payment_warning_days then 'Payment due '||to_char(nd.due_date,'DD Mon YYYY') else null end,'warning_rank',case when coalesce(ov.cnt,0)>0 then 0 when l.status in('active','defaulted') then 1 else 2 end) x
  from public.loan_accounts_v490 l left join public.customers c on c.id=l.client_id left join public.suppliers s on s.id=l.supplier_id
  left join lateral(select sc.due_date,round((sc.principal_due+sc.interest_due+sc.penalty_due)-(sc.principal_paid+sc.interest_paid+sc.penalty_paid),2) amount from public.loan_schedule_v490 sc where sc.loan_id=l.id and sc.status<>'waived' and (sc.principal_due+sc.interest_due+sc.penalty_due)-(sc.principal_paid+sc.interest_paid+sc.penalty_paid)>0.005 order by sc.due_date limit 1) nd on true
  left join lateral(select count(*) cnt from public.loan_schedule_v490 sc where sc.loan_id=l.id and sc.status='overdue') ov on true
  where l.tenant_id=p_tenant_id and (p_location_id is null or l.location_id=p_location_id) and (p_status is null or p_status='' or l.status=lower(p_status)) and (p_direction is null or p_direction='' or l.direction=lower(p_direction)) and (trim(coalesce(p_query,''))='' or lower(concat_ws(' ',l.loan_number,l.counterparty_name,c.name,s.name,c.tracking_code,s.tracking_code,l.purpose,l.counterparty_reference)) like '%'||lower(trim(p_query))||'%') and private.erp_document_scope_allowed(p_tenant_id,l.location_id,p_location_id,'view') limit least(greatest(coalesce(p_limit,500),1),2000)
 ) q;
 return result;
end $$;


--
-- Name: loan_payment_create_v490(uuid, uuid, numeric, date, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loan_payment_create_v490(p_tenant_id uuid, p_loan_id uuid, p_amount numeric, p_payment_date date DEFAULT CURRENT_DATE, p_payment_method text DEFAULT 'cash'::text, p_reference_number text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_device_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v public.loan_accounts_v490%rowtype;
  v_payment uuid:=gen_random_uuid();
  v_no text;
  v_amount numeric:=round(coalesce(p_amount,0),2);
  v_remaining numeric:=round(coalesce(p_amount,0),2);
  v_method text:=lower(coalesce(nullif(trim(p_payment_method),''),'cash'));
  v_device_id uuid:=p_device_id;
  v_device_app text;
  v_device_location uuid;
  r record;
  v_pen numeric;v_int numeric;v_prin numeric;v_take numeric;
  v_total_pen numeric:=0;v_total_int numeric:=0;v_total_prin numeric:=0;
  v_lines jsonb:='[]'::jsonb;
  v_shift uuid;
begin
  if v_remaining<=0 then raise exception 'Payment amount must be positive';end if;
  if v_method not in('cash','upi','card','credit_card','debit_card','bank','bank_transfer') then
    raise exception 'Unsupported loan payment method %',v_method;
  end if;

  select * into v from public.loan_accounts_v490
  where tenant_id=p_tenant_id and id=p_loan_id for update;
  if not found then raise exception 'Loan not found';end if;

  perform private.loan_v490_access(p_tenant_id,v.location_id,'loans.collect','operate');

  -- Client workstations can have a registered Client device. It must not be
  -- treated as a POS cash drawer. Only an active POS device is retained for
  -- cash-shift posting; Client/non-POS device IDs are intentionally ignored.
  if v_device_id is not null then
    select d.app_type,d.location_id into v_device_app,v_device_location
    from public.business_devices d
    where d.id=v_device_id and d.tenant_id=p_tenant_id and d.status='active';
    if not found then
      v_device_id:=null;
      v_device_app:=null;
      v_device_location:=null;
    elsif v_device_app='pos' and v_device_location<>v.location_id then
      raise exception 'POS device belongs to a different loan location';
    elsif v_device_app<>'pos' then
      v_device_id:=null;
    end if;
  end if;

  if v.status not in('active','defaulted') then
    raise exception 'Payments are allowed only for Active/Defaulted loans';
  end if;

  perform private.loan_v490_refresh(p_tenant_id,p_loan_id);
  select * into v from public.loan_accounts_v490
  where tenant_id=p_tenant_id and id=p_loan_id for update;

  if v_remaining>v.principal_outstanding+v.interest_outstanding+v.penalty_outstanding+0.005 then
    raise exception 'Payment % exceeds loan outstanding %',v_remaining,
      round(v.principal_outstanding+v.interest_outstanding+v.penalty_outstanding,2);
  end if;

  -- Re-check/repair accounting immediately before the journal is created.
  perform private.v47_ensure_accounting_for_tenant(p_tenant_id);
  if private.v4_account_id(p_tenant_id,'loan_receivable') is null then
    raise exception 'Loan receivable accounting mapping is not configured';
  end if;
  if private.v4_account_id(p_tenant_id,'loan_interest_income') is null then
    raise exception 'Loan interest income accounting mapping is not configured';
  end if;
  if private.v4_account_id(p_tenant_id,'loan_penalty_income') is null then
    raise exception 'Loan penalty income accounting mapping is not configured';
  end if;
  if private.v4_payment_account(p_tenant_id,v_method) is null then
    raise exception 'Payment account mapping is not configured for %',v_method;
  end if;

  v_no:='LPAY-'||lpad(nextval('public.loan_payment_number_seq_v490')::text,9,'0');
  insert into public.loan_payments_v490(
    id,tenant_id,loan_id,location_id,payment_number,payment_date,amount,payment_method,
    reference_number,notes,device_id,created_by
  ) values(
    v_payment,p_tenant_id,p_loan_id,v.location_id,v_no,coalesce(p_payment_date,current_date),v_amount,v_method,
    nullif(trim(coalesce(p_reference_number,'')),''),nullif(trim(coalesce(p_notes,'')),''),v_device_id,auth.uid()
  );

  -- Apply penalty -> interest -> principal, oldest installment first. Future
  -- scheduled installments are valid for early/pre-payments as well.
  for r in
    select * from public.loan_schedule_v490
    where tenant_id=p_tenant_id and loan_id=p_loan_id and status<>'waived'
      and (principal_due+interest_due+penalty_due)-(principal_paid+interest_paid+penalty_paid)>0.005
    order by due_date,installment_no
    for update
  loop
    exit when v_remaining<=0.005;
    v_pen:=greatest(r.penalty_due-r.penalty_paid,0);
    v_int:=greatest(r.interest_due-r.interest_paid,0);
    v_prin:=greatest(r.principal_due-r.principal_paid,0);

    v_take:=least(v_remaining,v_pen);v_pen:=v_take;v_remaining:=v_remaining-v_take;
    v_take:=least(v_remaining,v_int);v_int:=v_take;v_remaining:=v_remaining-v_take;
    v_take:=least(v_remaining,v_prin);v_prin:=v_take;v_remaining:=v_remaining-v_take;

    if v_pen+v_int+v_prin>0 then
      update public.loan_schedule_v490
      set penalty_paid=penalty_paid+v_pen,
          interest_paid=interest_paid+v_int,
          principal_paid=principal_paid+v_prin,
          updated_at=now()
      where id=r.id;
      insert into public.loan_payment_allocations_v490(
        tenant_id,payment_id,schedule_id,principal_amount,interest_amount,penalty_amount
      ) values(p_tenant_id,v_payment,r.id,v_prin,v_int,v_pen);
      v_total_pen:=v_total_pen+v_pen;
      v_total_int:=v_total_int+v_int;
      v_total_prin:=v_total_prin+v_prin;
    end if;
  end loop;

  if v_remaining>0.005 then
    raise exception 'Payment could not be fully allocated. Remaining %',round(v_remaining,2);
  end if;

  update public.loan_payments_v490
  set principal_amount=round(v_total_prin,2),
      interest_amount=round(v_total_int,2),
      penalty_amount=round(v_total_pen,2)
  where id=v_payment;

  v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
    'account_id',private.v4_payment_account(p_tenant_id,v_method),
    'debit',v_amount,'credit',0,'party_type','customer','party_id',v.client_id,
    'description','Loan repayment received'
  ));
  if v_total_prin>0 then
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
      'account_id',private.v4_account_id(p_tenant_id,'loan_receivable'),
      'debit',0,'credit',v_total_prin,'party_type','customer','party_id',v.client_id,
      'description','Loan principal repaid'
    ));
  end if;
  if v_total_int>0 then
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
      'account_id',private.v4_account_id(p_tenant_id,'loan_interest_income'),
      'debit',0,'credit',v_total_int,'party_type','customer','party_id',v.client_id,
      'description','Loan interest income'
    ));
  end if;
  if v_total_pen>0 then
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object(
      'account_id',private.v4_account_id(p_tenant_id,'loan_penalty_income'),
      'debit',0,'credit',v_total_pen,'party_type','customer','party_id',v.client_id,
      'description','Loan penalty income'
    ));
  end if;

  begin
    perform private.v4_journal_create(
      p_tenant_id,v.location_id,coalesce(p_payment_date,current_date),
      'Loan payment '||v_no,'loan_payment_v490',v_payment,v_no,v_lines
    );
  exception when others then
    raise exception 'Loan payment accounting post failed: %',SQLERRM;
  end;

  if v_device_id is not null and v_device_app='pos' and v_method='cash' then
    select id into v_shift from public.cashier_shifts
    where tenant_id=p_tenant_id and device_id=v_device_id and status='open'
    order by opened_at desc limit 1;
    if v_shift is not null then
      insert into public.cash_drawer_movements(
        tenant_id,shift_id,movement_type,amount,reference_type,reference_id,reference_number,note,created_by
      ) values(
        p_tenant_id,v_shift,'cash_in',abs(v_amount),'loan_payment_v490',v_payment,v_no,'Loan repayment',auth.uid()
      );
    end if;
  end if;

  perform private.loan_v490_refresh(p_tenant_id,p_loan_id);
  perform private.loan_v490_event(
    p_tenant_id,p_loan_id,'payment','Loan payment received',
    jsonb_build_object(
      'payment_id',v_payment,'payment_number',v_no,'amount',v_amount,
      'principal',round(v_total_prin,2),'interest',round(v_total_int,2),'penalty',round(v_total_pen,2),
      'payment_method',v_method
    )
  );
  perform private.thq_sync_bump_v480(p_tenant_id,'finance','loan_payment',v_payment::text,'create');

  return jsonb_build_object(
    'success',true,'payment_id',v_payment,'payment_number',v_no,'amount',v_amount,
    'principal_amount',round(v_total_prin,2),'interest_amount',round(v_total_int,2),'penalty_amount',round(v_total_pen,2),
    'remaining_outstanding',greatest(round(v.principal_outstanding+v.interest_outstanding+v.penalty_outstanding-v_amount,2),0)
  );
end $$;


--
-- Name: loan_payment_create_v491(uuid, uuid, numeric, date, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loan_payment_create_v491(p_tenant_id uuid, p_loan_id uuid, p_amount numeric, p_payment_date date DEFAULT CURRENT_DATE, p_payment_method text DEFAULT 'cash'::text, p_reference_number text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_device_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v public.loan_accounts_v490%rowtype;pid uuid:=gen_random_uuid();pno text;rem numeric:=round(coalesce(p_amount,0),2);amt numeric:=rem;r record;pen numeric;intr numeric;prin numeric;take numeric;tp numeric:=0;ti numeric:=0;tpr numeric:=0;lines jsonb:='[]'::jsonb;v_shift uuid;begin
 if rem<=0 then raise exception 'Payment amount must be positive';end if;select * into v from public.loan_accounts_v490 where tenant_id=p_tenant_id and id=p_loan_id for update;if not found then raise exception 'Loan not found';end if;perform private.loan_v490_access(p_tenant_id,v.location_id,'loans.collect','operate');if p_device_id is not null and not exists(select 1 from public.business_devices d where d.id=p_device_id and d.tenant_id=p_tenant_id and d.location_id=v.location_id and d.status='active') then raise exception 'Invalid POS/device for this loan location';end if;if v.status not in('active','defaulted') then raise exception 'Payments are allowed only for Active/Defaulted loans';end if;perform private.loan_v490_refresh(p_tenant_id,p_loan_id);select * into v from public.loan_accounts_v490 where id=p_loan_id for update;if rem>v.principal_outstanding+v.interest_outstanding+v.penalty_outstanding+0.005 then raise exception 'Payment exceeds outstanding amount';end if;
 pno:=case when v.direction='given' then 'LRCV-' else 'LPAY-' end||lpad(nextval('public.loan_payment_number_seq_v490')::text,9,'0');insert into public.loan_payments_v490(id,tenant_id,loan_id,location_id,payment_number,payment_date,amount,payment_method,reference_number,notes,device_id,created_by) values(pid,p_tenant_id,p_loan_id,v.location_id,pno,coalesce(p_payment_date,current_date),amt,lower(p_payment_method),nullif(trim(coalesce(p_reference_number,'')),''),nullif(trim(coalesce(p_notes,'')),''),p_device_id,auth.uid());
 for r in select * from public.loan_schedule_v490 where loan_id=p_loan_id and status<>'waived' and (principal_due+interest_due+penalty_due)-(principal_paid+interest_paid+penalty_paid)>0.005 order by due_date,installment_no for update loop exit when rem<=0.005;pen:=least(rem,greatest(r.penalty_due-r.penalty_paid,0));rem:=rem-pen;intr:=least(rem,greatest(r.interest_due-r.interest_paid,0));rem:=rem-intr;prin:=least(rem,greatest(r.principal_due-r.principal_paid,0));rem:=rem-prin;update public.loan_schedule_v490 set penalty_paid=penalty_paid+pen,interest_paid=interest_paid+intr,principal_paid=principal_paid+prin,updated_at=now() where id=r.id;insert into public.loan_payment_allocations_v490(tenant_id,payment_id,schedule_id,principal_amount,interest_amount,penalty_amount) values(p_tenant_id,pid,r.id,prin,intr,pen);tp:=tp+pen;ti:=ti+intr;tpr:=tpr+prin;end loop;if rem>0.005 then raise exception 'Payment could not be fully allocated';end if;update public.loan_payments_v490 set principal_amount=tpr,interest_amount=ti,penalty_amount=tp where id=pid;
 if v.accounting_enabled then if v.direction='given' then lines:=lines||jsonb_build_array(jsonb_build_object('account_id',private.v4_payment_account(p_tenant_id,p_payment_method),'debit',amt,'credit',0,'description','Loan collection received'));if tpr>0 then lines:=lines||jsonb_build_array(jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'loan_receivable'),'debit',0,'credit',tpr,'description','Loan principal collected'));end if;if ti>0 then lines:=lines||jsonb_build_array(jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'loan_interest_income'),'debit',0,'credit',ti,'description','Loan interest income'));end if;if tp>0 then lines:=lines||jsonb_build_array(jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'loan_penalty_income'),'debit',0,'credit',tp,'description','Loan penalty income'));end if;else if tpr>0 then lines:=lines||jsonb_build_array(jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'loan_payable'),'debit',tpr,'credit',0,'description','Loan principal repaid'));end if;if ti>0 then lines:=lines||jsonb_build_array(jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'loan_interest_expense'),'debit',ti,'credit',0,'description','Loan interest expense'));end if;if tp>0 then lines:=lines||jsonb_build_array(jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'loan_penalty_expense'),'debit',tp,'credit',0,'description','Loan penalty expense'));end if;lines:=lines||jsonb_build_array(jsonb_build_object('account_id',private.v4_payment_account(p_tenant_id,p_payment_method),'debit',0,'credit',amt,'description','Loan repayment paid'));end if;perform private.v4_journal_create(p_tenant_id,v.location_id,coalesce(p_payment_date,current_date),'Loan payment '||pno,'loan_payment_v491',pid,pno,lines);if p_device_id is not null and lower(coalesce(p_payment_method,''))='cash' then select id into v_shift from public.cashier_shifts where tenant_id=p_tenant_id and device_id=p_device_id and status='open' order by opened_at desc limit 1;if v_shift is not null then insert into public.cash_drawer_movements(tenant_id,shift_id,movement_type,amount,reference_type,reference_id,reference_number,note,created_by) values(p_tenant_id,v_shift,case when v.direction='given' then 'cash_in' else 'cash_out' end,case when v.direction='given' then abs(amt) else -abs(amt) end,'loan_payment_v491',pid,pno,case when v.direction='given' then 'Loan collection' else 'Loan repayment' end,auth.uid());end if;end if;end if;
 perform private.loan_v490_refresh(p_tenant_id,p_loan_id);perform private.loan_v490_event(p_tenant_id,p_loan_id,'payment',case when v.direction='given' then 'Loan collection received' else 'Loan repayment paid' end,jsonb_build_object('amount',amt,'principal',tpr,'interest',ti,'penalty',tp,'direction',v.direction,'accounting_enabled',v.accounting_enabled));return jsonb_build_object('success',true,'payment_id',pid,'payment_number',pno,'direction',v.direction,'amount',amt,'principal_amount',tpr,'interest_amount',ti,'penalty_amount',tp);
end $$;


--
-- Name: loan_payment_reverse_v490(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loan_payment_reverse_v490(p_tenant_id uuid, p_payment_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v public.loan_payments_v490%rowtype;a record;v_shift uuid;begin
  if nullif(trim(coalesce(p_reason,'')),'') is null then raise exception 'Reversal reason is required';end if;
  select * into v from public.loan_payments_v490 where tenant_id=p_tenant_id and id=p_payment_id for update;if not found then raise exception 'Loan payment not found';end if;
  perform private.loan_v490_access(p_tenant_id,v.location_id,'loans.manage','manage');
  if v.status='reversed' then return jsonb_build_object('success',true,'payment_id',v.id,'status','reversed','idempotent',true);end if;
  for a in select * from public.loan_payment_allocations_v490 where tenant_id=p_tenant_id and payment_id=p_payment_id loop
    update public.loan_schedule_v490 set principal_paid=greatest(principal_paid-a.principal_amount,0),interest_paid=greatest(interest_paid-a.interest_amount,0),penalty_paid=greatest(penalty_paid-a.penalty_amount,0),paid_at=null,updated_at=now() where id=a.schedule_id;
  end loop;
  update public.loan_payments_v490 set status='reversed',reversed_by=auth.uid(),reversed_at=now(),reversal_reason=trim(p_reason) where id=p_payment_id;
  update public.journal_entries set status='reversed' where tenant_id=p_tenant_id and source_type='loan_payment_v490' and source_id=p_payment_id and status='posted';
  if v.device_id is not null and lower(v.payment_method)='cash' then
    select id into v_shift from public.cashier_shifts where tenant_id=p_tenant_id and device_id=v.device_id and status='open' order by opened_at desc limit 1;
    if v_shift is not null then
      insert into public.cash_drawer_movements(tenant_id,shift_id,movement_type,amount,reference_type,reference_id,reference_number,note,created_by)
      values(p_tenant_id,v_shift,'cash_out',-abs(v.amount),'loan_payment_reversal_v490',v.id,v.payment_number,'Loan payment reversal: '||trim(p_reason),auth.uid());
    end if;
  end if;
  perform private.loan_v490_refresh(p_tenant_id,v.loan_id);
  perform private.loan_v490_event(p_tenant_id,v.loan_id,'payment_reversed','Loan payment reversed: '||trim(p_reason),jsonb_build_object('payment_id',v.id,'payment_number',v.payment_number,'amount',v.amount));
  perform private.thq_sync_bump_v480(p_tenant_id,'finance','loan_payment',v.id::text,'reverse');
  return jsonb_build_object('success',true,'payment_id',v.id,'status','reversed');
end $$;


--
-- Name: loan_payment_reverse_v491(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loan_payment_reverse_v491(p_tenant_id uuid, p_payment_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v public.loan_payments_v490%rowtype;a record;l public.loan_accounts_v490%rowtype;v_shift uuid;begin
 if nullif(trim(coalesce(p_reason,'')),'') is null then raise exception 'Reversal reason is required';end if;
 select * into v from public.loan_payments_v490 where tenant_id=p_tenant_id and id=p_payment_id for update;if not found then raise exception 'Loan payment not found';end if;
 select * into l from public.loan_accounts_v490 where id=v.loan_id and tenant_id=p_tenant_id;if not found then raise exception 'Loan not found';end if;
 perform private.loan_v490_access(p_tenant_id,v.location_id,'loans.manage','manage');
 if v.status='reversed' then return jsonb_build_object('success',true,'payment_id',v.id,'status','reversed','idempotent',true);end if;
 for a in select * from public.loan_payment_allocations_v490 where tenant_id=p_tenant_id and payment_id=p_payment_id loop
  update public.loan_schedule_v490 set principal_paid=greatest(principal_paid-a.principal_amount,0),interest_paid=greatest(interest_paid-a.interest_amount,0),penalty_paid=greatest(penalty_paid-a.penalty_amount,0),paid_at=null,updated_at=now() where id=a.schedule_id;
 end loop;
 if l.accounting_enabled then
  perform private.v4_reverse_source_journal(p_tenant_id,'loan_payment_v491',v.id,'loan_payment_reversal_v491','Reverse loan payment '||v.payment_number||' • '||trim(p_reason));
  if v.device_id is not null and lower(coalesce(v.payment_method,''))='cash' then
    select id into v_shift from public.cashier_shifts where tenant_id=p_tenant_id and device_id=v.device_id and status='open' order by opened_at desc limit 1;
    if v_shift is not null then
      insert into public.cash_drawer_movements(tenant_id,shift_id,movement_type,amount,reference_type,reference_id,reference_number,note,created_by)
      values(p_tenant_id,v_shift,case when l.direction='given' then 'cash_out' else 'cash_in' end,case when l.direction='given' then -abs(v.amount) else abs(v.amount) end,'loan_payment_reversal_v491',v.id,v.payment_number,'Loan payment reversal: '||trim(p_reason),auth.uid());
    end if;
  end if;
 end if;
 update public.loan_payments_v490 set status='reversed',reversed_by=auth.uid(),reversed_at=now(),reversal_reason=trim(p_reason) where id=p_payment_id;
 perform private.loan_v490_refresh(p_tenant_id,v.loan_id);
 perform private.loan_v490_event(p_tenant_id,v.loan_id,'payment_reversed','Loan payment reversed: '||trim(p_reason),jsonb_build_object('payment_id',v.id,'payment_number',v.payment_number,'amount',v.amount,'direction',l.direction));
 return jsonb_build_object('success',true,'payment_id',v.id,'status','reversed');
end $$;


--
-- Name: loan_rate_change_v490(uuid, uuid, numeric, date, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loan_rate_change_v490(p_tenant_id uuid, p_loan_id uuid, p_new_rate numeric, p_effective_date date DEFAULT CURRENT_DATE, p_rate_index text DEFAULT NULL::text, p_rate_margin numeric DEFAULT NULL::numeric, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v public.loan_accounts_v490%rowtype;r record;v_ppy numeric;v_interest numeric;begin
  select * into v from public.loan_accounts_v490 where tenant_id=p_tenant_id and id=p_loan_id for update;if not found then raise exception 'Loan not found';end if;
  perform private.loan_v490_access(p_tenant_id,v.location_id,'loans.rate_manage','manage');
  if v.rate_type<>'variable' then raise exception 'Only variable-rate loans can change rate';end if;
  if v.status not in('approved','active','defaulted') then raise exception 'Rate cannot be changed in the current loan status';end if;
  if coalesce(p_new_rate,-1)<0 or p_new_rate>1000 then raise exception 'Invalid new interest rate';end if;
  insert into public.loan_rate_history_v490(tenant_id,loan_id,effective_date,previous_rate,new_rate,rate_index,rate_margin,reason,changed_by)
  values(p_tenant_id,p_loan_id,coalesce(p_effective_date,current_date),v.interest_rate,p_new_rate,coalesce(nullif(trim(p_rate_index),''),v.rate_index),coalesce(p_rate_margin,v.rate_margin),nullif(trim(coalesce(p_reason,'')),''),auth.uid());
  update public.loan_accounts_v490 set interest_rate=p_new_rate,rate_index=coalesce(nullif(trim(p_rate_index),''),rate_index),rate_margin=coalesce(p_rate_margin,rate_margin),updated_by=auth.uid(),updated_at=now() where id=p_loan_id;
  if v.status in('active','defaulted') then
    v_ppy:=private.loan_v490_periods_per_year(v.repayment_frequency);
    for r in select * from public.loan_schedule_v490 where tenant_id=p_tenant_id and loan_id=p_loan_id and due_date>=coalesce(p_effective_date,current_date)
             and principal_paid+interest_paid+penalty_paid<=0.005 and status<>'waived' order by installment_no for update loop
      v_interest:=round(r.opening_principal*p_new_rate/100.0/v_ppy,2);
      update public.loan_schedule_v490 set interest_due=v_interest,updated_at=now() where id=r.id;
    end loop;
    perform private.loan_v490_refresh(p_tenant_id,p_loan_id);
  end if;
  perform private.loan_v490_event(p_tenant_id,p_loan_id,'rate_changed','Interest rate changed',jsonb_build_object('previous_rate',v.interest_rate,'new_rate',p_new_rate,'effective_date',coalesce(p_effective_date,current_date)));
  perform private.thq_sync_bump_v480(p_tenant_id,'finance','loan',p_loan_id::text,'rate_change');
  return jsonb_build_object('success',true,'loan_id',p_loan_id,'interest_rate',p_new_rate,'rate_type','variable');
end $$;


--
-- Name: loan_settings_v491_get(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loan_settings_v491_get(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
 if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
 return jsonb_build_object('reflect_in_accounting',private.loan_v491_accounting_enabled(p_tenant_id),'note','This setting applies to new Draft/Approved loans. Active loans keep their accounting mode to preserve reconciliation.');
end $$;


--
-- Name: loan_settings_v491_set(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loan_settings_v491_set(p_tenant_id uuid, p_reflect boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
 if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'loans.manage') then raise exception 'Permission denied'; end if;
 insert into public.tenant_settings_v2(tenant_id,settings,updated_by) values(p_tenant_id,jsonb_build_object('loans',jsonb_build_object('reflect_in_accounting',coalesce(p_reflect,true))),auth.uid())
 on conflict(tenant_id) do update set settings=jsonb_set(coalesce(public.tenant_settings_v2.settings,'{}'::jsonb),'{loans,reflect_in_accounting}',to_jsonb(coalesce(p_reflect,true)),true),updated_by=auth.uid(),updated_at=now();
 update public.loan_accounts_v490 set accounting_enabled=coalesce(p_reflect,true),updated_at=now(),updated_by=auth.uid() where tenant_id=p_tenant_id and status in('draft','submitted','approved');
 return jsonb_build_object('success',true,'reflect_in_accounting',coalesce(p_reflect,true));
end $$;


--
-- Name: loan_status_v490(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loan_status_v490(p_tenant_id uuid, p_loan_id uuid, p_status text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v public.loan_accounts_v490%rowtype;v_status text:=lower(trim(coalesce(p_status,'')));begin
  select * into v from public.loan_accounts_v490 where tenant_id=p_tenant_id and id=p_loan_id for update;if not found then raise exception 'Loan not found';end if;
  perform private.loan_v490_access(p_tenant_id,v.location_id,'loans.manage','manage');
  if v_status='cancelled' and v.status in('draft','submitted','approved','rejected') then
    update public.loan_accounts_v490 set status='cancelled',updated_by=auth.uid(),updated_at=now() where id=p_loan_id;
  elsif v_status='defaulted' and v.status='active' then
    update public.loan_accounts_v490 set status='defaulted',updated_by=auth.uid(),updated_at=now() where id=p_loan_id;
  elsif v_status='active' and v.status='defaulted' then
    update public.loan_accounts_v490 set status='active',updated_by=auth.uid(),updated_at=now() where id=p_loan_id;
  else raise exception 'Invalid loan status transition % -> %',v.status,v_status;end if;
  perform private.loan_v490_event(p_tenant_id,p_loan_id,'status_changed',coalesce(nullif(trim(p_reason),''),'Loan status changed to '||v_status),jsonb_build_object('from',v.status,'to',v_status));
  perform private.thq_sync_bump_v480(p_tenant_id,'finance','loan',p_loan_id::text,'status');
  return jsonb_build_object('success',true,'loan_id',p_loan_id,'status',v_status);
end $$;


--
-- Name: loan_submit_v490(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loan_submit_v490(p_tenant_id uuid, p_loan_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v public.loan_accounts_v490%rowtype;begin
  select * into v from public.loan_accounts_v490 where tenant_id=p_tenant_id and id=p_loan_id for update;if not found then raise exception 'Loan not found';end if;
  perform private.loan_v490_access(p_tenant_id,v.location_id,'loans.create','operate');
  if v.status<>'draft' then raise exception 'Only Draft loans can be submitted';end if;
  update public.loan_accounts_v490 set status='submitted',updated_by=auth.uid(),updated_at=now() where id=p_loan_id;
  perform private.loan_v490_event(p_tenant_id,p_loan_id,'submitted','Loan submitted for approval');
  perform private.thq_sync_bump_v480(p_tenant_id,'finance','loan',p_loan_id::text,'submit');
  return jsonb_build_object('success',true,'loan_id',p_loan_id,'status','submitted');
end $$;


--
-- Name: loan_update_v490(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loan_update_v490(p_tenant_id uuid, p_loan_id uuid, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v public.loan_accounts_v490%rowtype;v_client uuid;v_first date;v_mat date;begin
  select * into v from public.loan_accounts_v490 where tenant_id=p_tenant_id and id=p_loan_id for update;if not found then raise exception 'Loan not found';end if;
  perform private.loan_v490_access(p_tenant_id,v.location_id,'loans.create','operate');
  if v.status not in('draft','rejected') then raise exception 'Only Draft/Rejected loans can be edited';end if;
  v_client:=coalesce(nullif(p_payload->>'client_id','')::uuid,v.client_id);
  if not exists(select 1 from public.customers where id=v_client and tenant_id=p_tenant_id and coalesce(status,'active')='active' and not coalesce(is_walk_in,false)) then raise exception 'Client/customer must be active and not walk-in';end if;
  v_first:=coalesce(nullif(p_payload->>'first_payment_date','')::date,v.first_payment_date);
  v_mat:=coalesce(nullif(p_payload->>'maturity_date','')::date,v.maturity_date);if v_mat<v_first then raise exception 'Maturity date cannot be before first payment date';end if;
  update public.loan_accounts_v490 set
    client_id=v_client,
    external_client_reference=coalesce(nullif(trim(p_payload->>'external_client_reference'),''),external_client_reference),
    purpose=coalesce(nullif(trim(p_payload->>'purpose'),''),purpose),
    principal_amount=coalesce(nullif(p_payload->>'principal_amount','')::numeric,principal_amount),
    interest_rate=coalesce(nullif(p_payload->>'interest_rate','')::numeric,interest_rate),
    rate_type=coalesce(nullif(lower(p_payload->>'rate_type'),''),rate_type),
    rate_index=coalesce(nullif(trim(p_payload->>'rate_index'),''),rate_index),
    rate_margin=coalesce(nullif(p_payload->>'rate_margin','')::numeric,rate_margin),
    rate_reset_frequency=coalesce(nullif(lower(p_payload->>'rate_reset_frequency'),''),rate_reset_frequency),
    next_rate_review_date=coalesce(nullif(p_payload->>'next_rate_review_date','')::date,next_rate_review_date),
    amortization_method=coalesce(nullif(lower(p_payload->>'amortization_method'),''),amortization_method),
    repayment_frequency=coalesce(nullif(lower(p_payload->>'repayment_frequency'),''),repayment_frequency),
    repayment_term_count=coalesce(nullif(p_payload->>'repayment_term_count','')::integer,repayment_term_count),
    repayment_terms=coalesce(nullif(trim(p_payload->>'repayment_terms'),''),repayment_terms),
    first_payment_date=v_first,maturity_date=v_mat,
    payment_warning_days=coalesce(nullif(p_payload->>'payment_warning_days','')::integer,payment_warning_days),
    maturity_warning_days=coalesce(nullif(p_payload->>'maturity_warning_days','')::integer,maturity_warning_days),
    grace_days=coalesce(nullif(p_payload->>'grace_days','')::integer,grace_days),
    penalty_rate=coalesce(nullif(p_payload->>'penalty_rate','')::numeric,penalty_rate),
    collateral_summary=coalesce(nullif(trim(p_payload->>'collateral_summary'),''),collateral_summary),
    notes=coalesce(nullif(trim(p_payload->>'notes'),''),notes),
    status='draft',rejection_reason=null,rejected_by=null,rejected_at=null,updated_by=auth.uid(),updated_at=now()
  where tenant_id=p_tenant_id and id=p_loan_id;
  if exists(
    select 1 from public.loan_accounts_v490 where tenant_id=p_tenant_id and id=p_loan_id
      and rate_type='variable' and nullif(trim(coalesce(rate_index,'')),'') is null
  ) then raise exception 'Variable-rate loans require a rate index';end if;
  if exists(
    select 1 from public.loan_accounts_v490 where tenant_id=p_tenant_id and id=p_loan_id
      and repayment_term_count>1
      and maturity_date<private.loan_v490_due_date(first_payment_date,repayment_frequency,repayment_term_count-2)
  ) then raise exception 'Maturity date is too early for the selected repayment terms';end if;
  perform private.loan_v490_event(p_tenant_id,p_loan_id,'updated','Loan details updated');
  perform private.thq_sync_bump_v480(p_tenant_id,'finance','loan',p_loan_id::text,'update');
  return jsonb_build_object('success',true,'loan_id',p_loan_id,'status','draft');
end $$;


--
-- Name: loan_update_v491(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loan_update_v491(p_tenant_id uuid, p_loan_id uuid, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
 v public.loan_accounts_v490%rowtype;v_client uuid;v_supplier uuid;v_party text;v_name text;v_dir text;
 v_principal numeric;v_rate numeric;v_penalty numeric;v_rate_type text;v_freq text;v_terms int;v_first date;v_mat date;v_amort text;
begin
 select * into v from public.loan_accounts_v490 where tenant_id=p_tenant_id and id=p_loan_id for update;
 if not found then raise exception 'Loan not found';end if;
 perform private.loan_v490_access(p_tenant_id,v.location_id,'loans.create','operate');
 if v.status not in('draft','rejected') then raise exception 'Only Draft/Rejected loans can be edited';end if;

 v_dir:=lower(coalesce(nullif(p_payload->>'direction',''),v.direction));
 if v_dir not in('given','taken') then raise exception 'Loan direction must be given or taken';end if;
 v_party:=lower(coalesce(nullif(p_payload->>'counterparty_type',''),v.counterparty_type));
 if v_party not in('customer','supplier','other') then raise exception 'Invalid loan counterparty type';end if;
 v_client:=nullif(coalesce(nullif(p_payload->>'client_id',''),v.client_id::text),'')::uuid;
 v_supplier:=nullif(coalesce(nullif(p_payload->>'supplier_id',''),v.supplier_id::text),'')::uuid;
 if v_party='customer' then
   select name into v_name from public.customers where id=v_client and tenant_id=p_tenant_id and coalesce(status,'active')='active' and not coalesce(is_walk_in,false);
   if v_name is null then raise exception 'Active non-walk-in customer/client is required';end if;
 elsif v_party='supplier' then
   select name into v_name from public.suppliers where id=v_supplier and tenant_id=p_tenant_id and coalesce(status,'active')='active';
   if v_name is null then raise exception 'Active supplier/lender is required';end if;
 else
   v_name:=coalesce(nullif(trim(coalesce(p_payload->>'counterparty_name','')),''),v.counterparty_name);
   if v_name is null then raise exception 'Lender/borrower name is required';end if;
 end if;

 v_principal:=coalesce(nullif(p_payload->>'principal_amount','')::numeric,v.principal_amount);
 v_rate:=coalesce(nullif(p_payload->>'interest_rate','')::numeric,v.interest_rate);
 v_penalty:=coalesce(nullif(p_payload->>'penalty_rate','')::numeric,v.penalty_rate);
 if v_principal<=0 then raise exception 'Principal amount must be positive';end if;
 if v_rate<0 or v_rate>1000 then raise exception 'Invalid interest rate';end if;
 if v_penalty<0 or v_penalty>1000 then raise exception 'Invalid penalty rate';end if;
 v_rate_type:=lower(coalesce(nullif(p_payload->>'rate_type',''),v.rate_type));
 if v_rate_type not in('fixed','variable') then raise exception 'Invalid interest type';end if;
 v_freq:=lower(coalesce(nullif(p_payload->>'repayment_frequency',''),v.repayment_frequency));
 if v_freq not in('weekly','biweekly','monthly','quarterly','half_yearly','yearly') then raise exception 'Invalid repayment frequency';end if;
 v_terms:=coalesce(nullif(p_payload->>'repayment_term_count','')::int,v.repayment_term_count);
 if v_terms<=0 or v_terms>1200 then raise exception 'Invalid repayment terms';end if;
 v_first:=coalesce(nullif(p_payload->>'first_payment_date','')::date,v.first_payment_date);
 v_mat:=coalesce(nullif(p_payload->>'maturity_date','')::date,private.loan_v490_due_date(v_first,v_freq,v_terms-1));
 if v_mat<v_first then raise exception 'Maturity date cannot be before first payment date';end if;
 if v_terms>1 and v_mat<private.loan_v490_due_date(v_first,v_freq,v_terms-2) then raise exception 'Maturity date is too early for the selected repayment terms';end if;
 v_amort:=lower(coalesce(nullif(p_payload->>'amortization_method',''),v.amortization_method));
 if v_amort not in('reducing_balance','flat') then raise exception 'Invalid amortization method';end if;
 if v_rate_type='variable' and nullif(trim(coalesce(p_payload->>'rate_index',v.rate_index,'')),'') is null then raise exception 'Variable-rate loans require a rate index';end if;

 update public.loan_accounts_v490 set
   direction=v_dir,counterparty_type=v_party,
   client_id=case when v_party='customer' then v_client else null end,
   supplier_id=case when v_party='supplier' then v_supplier else null end,
   counterparty_name=v_name,
   counterparty_reference=coalesce(nullif(trim(p_payload->>'counterparty_reference'),''),counterparty_reference),
   external_client_reference=coalesce(nullif(trim(p_payload->>'external_client_reference'),''),external_client_reference),
   purpose=coalesce(nullif(trim(p_payload->>'purpose'),''),purpose),principal_amount=v_principal,interest_rate=v_rate,
   rate_type=v_rate_type,rate_index=coalesce(nullif(trim(p_payload->>'rate_index'),''),rate_index),
   rate_margin=coalesce(nullif(p_payload->>'rate_margin','')::numeric,rate_margin),
   rate_reset_frequency=coalesce(nullif(lower(p_payload->>'rate_reset_frequency'),''),rate_reset_frequency),
   next_rate_review_date=coalesce(nullif(p_payload->>'next_rate_review_date','')::date,next_rate_review_date),
   amortization_method=v_amort,repayment_frequency=v_freq,repayment_term_count=v_terms,
   repayment_terms=coalesce(nullif(trim(p_payload->>'repayment_terms'),''),repayment_terms),first_payment_date=v_first,maturity_date=v_mat,
   payment_warning_days=coalesce(nullif(p_payload->>'payment_warning_days','')::int,payment_warning_days),
   maturity_warning_days=coalesce(nullif(p_payload->>'maturity_warning_days','')::int,maturity_warning_days),
   grace_days=coalesce(nullif(p_payload->>'grace_days','')::int,grace_days),penalty_rate=v_penalty,
   collateral_summary=coalesce(nullif(trim(p_payload->>'collateral_summary'),''),collateral_summary),
   notes=coalesce(nullif(trim(p_payload->>'notes'),''),notes),status='draft',rejection_reason=null,rejected_by=null,rejected_at=null,
   accounting_enabled=private.loan_v491_accounting_enabled(p_tenant_id),updated_by=auth.uid(),updated_at=now()
 where id=p_loan_id;
 perform private.loan_v490_event(p_tenant_id,p_loan_id,'updated','Loan details updated',jsonb_build_object('direction',v_dir,'counterparty_type',v_party,'counterparty_name',v_name));
 perform private.thq_sync_bump_v480(p_tenant_id,'finance','loan',p_loan_id::text,'update');
 return jsonb_build_object('success',true,'loan_id',p_loan_id,'direction',v_dir,'status','draft');
end $$;


--
-- Name: loan_warnings_v490(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loan_warnings_v490(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 250) RETURNS TABLE(warning_type text, severity text, loan_id uuid, loan_number text, client_id uuid, client_name text, location_id uuid, event_date date, amount numeric, days_until integer, message text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  perform private.loan_v490_access(p_tenant_id,p_location_id,'loans.view','view');
  return query
  with scoped as(
    select l.*,c.name client_name
    from public.loan_accounts_v490 l join public.customers c on c.id=l.client_id
    where l.tenant_id=p_tenant_id and l.status in('approved','active','defaulted')
      and (p_location_id is null or l.location_id=p_location_id)
      and private.erp_document_scope_allowed(p_tenant_id,l.location_id,p_location_id,'view')
  ), warnings(warning_type,severity,loan_id,loan_number,client_id,client_name,location_id,event_date,amount,days_until,message) as(
    select 'overdue_payment'::text,'danger'::text,l.id,l.loan_number,l.client_id,l.client_name,l.location_id,s.due_date,
      round(greatest(s.principal_due-s.principal_paid,0)+greatest(s.interest_due-s.interest_paid,0)+greatest(s.penalty_due-s.penalty_paid,0),2),
      (s.due_date-current_date)::integer,
      ('Installment #'||s.installment_no::text||' overdue by '||(current_date-s.due_date)::text||' day(s)')::text
    from scoped l join public.loan_schedule_v490 s on s.loan_id=l.id and s.tenant_id=l.tenant_id
    where l.status in('active','defaulted') and s.status<>'waived' and current_date>s.due_date+l.grace_days
      and (s.principal_due+s.interest_due+s.penalty_due)-(s.principal_paid+s.interest_paid+s.penalty_paid)>0.005
    union all
    select 'payment_due'::text,'warning'::text,l.id,l.loan_number,l.client_id,l.client_name,l.location_id,s.due_date,
      round(greatest(s.principal_due-s.principal_paid,0)+greatest(s.interest_due-s.interest_paid,0)+greatest(s.penalty_due-s.penalty_paid,0),2),
      (s.due_date-current_date)::integer,
      ('Installment #'||s.installment_no::text||' due in '||greatest(s.due_date-current_date,0)::text||' day(s)')::text
    from scoped l join public.loan_schedule_v490 s on s.loan_id=l.id and s.tenant_id=l.tenant_id
    where l.status in('active','defaulted') and s.status<>'waived'
      and s.due_date between current_date and current_date+l.payment_warning_days
      and (s.principal_due+s.interest_due+s.penalty_due)-(s.principal_paid+s.interest_paid+s.penalty_paid)>0.005
    union all
    select 'maturity'::text,'warning'::text,l.id,l.loan_number,l.client_id,l.client_name,l.location_id,l.maturity_date,
      round(l.principal_outstanding+l.interest_outstanding+l.penalty_outstanding,2),(l.maturity_date-current_date)::integer,
      ('Loan matures in '||greatest(l.maturity_date-current_date,0)::text||' day(s)')::text
    from scoped l where l.status in('active','defaulted') and l.maturity_date between current_date and current_date+l.maturity_warning_days
    union all
    select 'rate_review'::text,'info'::text,l.id,l.loan_number,l.client_id,l.client_name,l.location_id,l.next_rate_review_date,
      null::numeric,(l.next_rate_review_date-current_date)::integer,
      ('Variable interest rate review due in '||greatest(l.next_rate_review_date-current_date,0)::text||' day(s)')::text
    from scoped l where l.rate_type='variable' and l.next_rate_review_date is not null
      and l.next_rate_review_date between current_date and current_date+greatest(l.payment_warning_days,7)
  )
  select w.warning_type,w.severity,w.loan_id,w.loan_number,w.client_id,w.client_name,w.location_id,
         w.event_date,w.amount,w.days_until,w.message
  from warnings w
  order by case w.severity when 'danger' then 0 when 'warning' then 1 else 2 end,w.event_date,w.loan_number
  limit least(greatest(coalesce(p_limit,250),1),2000);
end $$;


--
-- Name: loan_warnings_v491(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loan_warnings_v491(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 250) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare r jsonb;begin
 perform private.loan_v490_access(p_tenant_id,p_location_id,'loans.view','view');
 select coalesce(jsonb_agg(x order by case x->>'severity' when 'danger' then 0 when 'warning' then 1 else 2 end,(x->>'event_date')::date),'[]'::jsonb) into r from (
  select jsonb_build_object('loan_id',l.id,'loan_number',l.loan_number,'client_name',coalesce(l.counterparty_name,c.name,s.name,'Party'),'direction',l.direction,'warning_type',case when sc.due_date is not null and current_date>sc.due_date+l.grace_days then 'overdue_payment' when l.maturity_date<=current_date+l.maturity_warning_days then 'maturity' when sc.due_date<=current_date+l.payment_warning_days then 'payment_due' when l.rate_type='variable' and l.next_rate_review_date<=current_date+l.payment_warning_days then 'rate_review' else 'status' end,'severity',case when sc.due_date is not null and current_date>sc.due_date+l.grace_days then 'danger' when l.status='defaulted' then 'danger' else 'warning' end,'event_date',coalesce(sc.due_date,l.maturity_date),'amount',coalesce(sc.balance,0),'message',case when l.direction='given' then 'Receivable loan requires attention' else 'Payable loan requires attention' end) x
  from public.loan_accounts_v490 l left join public.customers c on c.id=l.client_id left join public.suppliers s on s.id=l.supplier_id
  left join lateral(select z.due_date,round((z.principal_due+z.interest_due+z.penalty_due)-(z.principal_paid+z.interest_paid+z.penalty_paid),2) balance from public.loan_schedule_v490 z where z.loan_id=l.id and z.status<>'waived' and (z.principal_due+z.interest_due+z.penalty_due)-(z.principal_paid+z.interest_paid+z.penalty_paid)>0.005 order by z.due_date limit 1) sc on true
  where l.tenant_id=p_tenant_id and l.status in('active','defaulted') and (p_location_id is null or l.location_id=p_location_id) and private.erp_document_scope_allowed(p_tenant_id,l.location_id,p_location_id,'view') and (l.status='defaulted' or (sc.due_date is not null and sc.due_date<=current_date+l.payment_warning_days) or l.maturity_date<=current_date+l.maturity_warning_days or (l.rate_type='variable' and l.next_rate_review_date is not null and l.next_rate_review_date<=current_date+l.payment_warning_days)) limit least(greatest(coalesce(p_limit,250),1),1000)
 )q;
 return r;
end $$;


--
-- Name: location_business_summary(uuid, uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.location_business_summary(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_from_date date DEFAULT ((CURRENT_DATE - '29 days'::interval))::date, p_to_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_sales numeric:=0;v_purchases numeric:=0;v_expenses numeric:=0;v_count bigint:=0;v_locations jsonb;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  select coalesce(sum(s.grand_total),0),count(*) into v_sales,v_count
  from public.sales s left join public.document_origins o on o.entity_type='sale' and o.entity_id=s.id
  where s.tenant_id=p_tenant_id and s.sale_date between p_from_date and p_to_date and coalesce(s.status,'') not in ('cancelled','void') and (p_location_id is null or o.location_id=p_location_id);
  select coalesce(sum(p.grand_total),0) into v_purchases from public.purchases p left join public.document_origins o on o.entity_type='purchase' and o.entity_id=p.id
  where p.tenant_id=p_tenant_id and p.purchase_date between p_from_date and p_to_date and coalesce(p.status,'') not in ('cancelled','void') and (p_location_id is null or o.location_id=p_location_id);
  select coalesce(sum(e.amount+coalesce(e.tax_amount,0)),0) into v_expenses from public.expenses e left join public.document_origins o on o.entity_type='expense' and o.entity_id=e.id
  where e.tenant_id=p_tenant_id and e.expense_date between p_from_date and p_to_date and coalesce(e.status,'posted') not in ('cancelled','void') and (p_location_id is null or o.location_id=p_location_id);
  select coalesce(jsonb_agg(jsonb_build_object('location_id',l.id,'location_code',l.location_code,'name',l.name,'tracking_code',l.tracking_code,'sales',coalesce(x.sales,0),'invoice_count',coalesce(x.invoice_count,0)) order by l.name),'[]'::jsonb)
  into v_locations from public.business_locations l left join (
    select o.location_id,sum(s.grand_total)::numeric sales,count(*)::bigint invoice_count from public.sales s join public.document_origins o on o.entity_type='sale' and o.entity_id=s.id where s.tenant_id=p_tenant_id and s.sale_date between p_from_date and p_to_date and coalesce(s.status,'') not in ('cancelled','void') group by o.location_id
  ) x on x.location_id=l.id where l.tenant_id=p_tenant_id and l.active;
  return jsonb_build_object('sales',v_sales,'purchases',v_purchases,'expenses',v_expenses,'invoice_count',v_count,'locations',v_locations,'mode',case when p_location_id is null then 'merged' else 'location' end);
end $$;


--
-- Name: mobile_approval_decide_v487(uuid, uuid, text, uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mobile_approval_decide_v487(p_tenant_id uuid, p_device_id uuid, p_approval_type text, p_id uuid, p_approve boolean, p_note text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_type text:=lower(trim(coalesce(p_approval_type,'')));v_result jsonb;
begin
  perform private.v487_client_mobile_location(p_tenant_id,p_device_id);
  if v_type='approval_request' then
    perform public.approval_request_decide_v4(p_tenant_id,p_id,p_approve,p_note);
    return jsonb_build_object('success',true,'approval_type',v_type,'id',p_id,'status',case when p_approve then 'approved' else 'rejected' end);
  elsif v_type='purchase_request' then
    return public.purchase_request_status_v484(p_tenant_id,p_id,case when p_approve then 'approved' else 'rejected' end,p_note);
  elsif v_type='purchase_order' then
    return public.purchase_order_decide_v484(p_tenant_id,p_id,p_approve,p_note);
  end if;
  raise exception 'Unsupported mobile approval type';
end$$;


--
-- Name: mobile_approvals_v487(uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mobile_approvals_v487(p_tenant_id uuid, p_device_id uuid, p_status text DEFAULT 'pending'::text, p_limit integer DEFAULT 200) RETURNS TABLE(approval_type text, id uuid, reference text, module_key text, action_key text, location_id uuid, location_name text, amount numeric, status text, summary text, requested_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  perform private.v487_client_mobile_location(p_tenant_id,p_device_id);
  return query
  select * from (
    select 'approval_request'::text,a.id,coalesce(a.entity_type,'')||case when a.entity_id is null then '' else ' '||a.entity_id::text end,a.module_key,a.action_key,null::uuid,null::text,a.amount,a.status,coalesce(a.reason,a.action_key),a.requested_at
      from public.approval_requests a where a.tenant_id=p_tenant_id and (p_status is null or p_status='' or a.status=p_status)
    union all
    select 'purchase_request'::text,r.id,r.request_number,'purchases','approve_purchase_request',r.location_id,l.name,
      coalesce((select sum(i.quantity*i.estimated_unit_cost) from public.purchase_request_items_v484 i where i.request_id=r.id),0)::numeric,r.status,coalesce(r.purpose,'Purchase Request'),coalesce(r.submitted_at,r.created_at)
      from public.purchase_requests_v484 r join public.business_locations l on l.id=r.location_id
      where r.tenant_id=p_tenant_id and (p_status is null or p_status='' or (p_status='pending' and r.status='submitted') or r.status=p_status)
        and private.erp_document_scope_allowed(p_tenant_id,r.location_id,null,'view')
    union all
    select 'purchase_order'::text,o.id,o.order_number,'purchases','approve_purchase_order',o.location_id,l.name,o.grand_total,o.status,'Purchase Order • '||s.name,coalesce(o.submitted_at,o.created_at)
      from public.purchase_orders_v480 o join public.business_locations l on l.id=o.location_id join public.suppliers s on s.id=o.supplier_id
      where o.tenant_id=p_tenant_id and (p_status is null or p_status='' or (p_status='pending' and o.status='submitted') or o.status=p_status)
        and private.erp_document_scope_allowed(p_tenant_id,o.location_id,null,'view')
  ) q order by requested_at desc limit greatest(1,least(coalesce(p_limit,200),1000));
end$$;


--
-- Name: mobile_business_summary_v480(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mobile_business_summary_v480(p_tenant_id uuid, p_day date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_attention jsonb;v_stores jsonb;v_sales numeric:=0;v_returns numeric:=0;v_profit numeric:=0;v_invoices bigint:=0;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  v_attention:=public.business_attention_summary_v480(p_tenant_id,null,30);
  select coalesce(jsonb_agg(to_jsonb(x) order by x.location_name),'[]'::jsonb),coalesce(sum(x.sales_total),0),coalesce(sum(x.returns_total),0),coalesce(sum(x.gross_profit),0),coalesce(sum(x.invoice_count),0)
    into v_stores,v_sales,v_returns,v_profit,v_invoices
  from public.mobile_store_status_v480(p_tenant_id,p_day) x;
  return jsonb_build_object('day',coalesce(p_day,current_date),'sales',v_sales,'returns',v_returns,'net_sales',greatest(v_sales-v_returns,0),'gross_profit',v_profit,'invoice_count',v_invoices,
    'attention',v_attention,'stores',coalesce(v_stores,'[]'::jsonb),'sync',public.thq_sync_versions_v480(p_tenant_id));
end $$;


--
-- Name: mobile_client_api_contract_v487(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mobile_client_api_contract_v487(p_tenant_id uuid, p_device_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  perform private.v487_client_mobile_location(p_tenant_id,p_device_id);
  return jsonb_build_object('api_version','v1','release','4.8.7','resource','client-mobile','dashboard',true,'sales_status',true,'purchases',true,'inventory',true,'customer_outstanding',true,'supplier_outstanding',true,'reports',true,'approvals',true,'customer_payment',true,'store_performance',true);
end$$;


--
-- Name: mobile_client_context_v487(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mobile_client_context_v487(p_tenant_id uuid, p_device_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_location uuid;d public.business_devices%rowtype;l public.business_locations%rowtype;
begin
  v_location:=private.v487_client_mobile_location(p_tenant_id,p_device_id);
  select * into d from public.business_devices where id=p_device_id and tenant_id=p_tenant_id;
  select * into l from public.business_locations where id=v_location and tenant_id=p_tenant_id;
  return jsonb_build_object(
    'release','4.8.7','device_id',d.id,'device_code',d.device_code,'device_name',d.name,'location_id',l.id,
    'location_code',l.location_code,'location_name',l.name,'mobile_client',true,'read_first',true,
    'can_approve',private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'approvals.approve'),
    'can_receive_customer_payment',private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'sales.manage') or private.erp_has_permission(p_tenant_id,'payments.receive')
  );
end$$;


--
-- Name: mobile_client_dashboard_v487(uuid, uuid, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mobile_client_dashboard_v487(p_tenant_id uuid, p_device_id uuid, p_day date DEFAULT CURRENT_DATE, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_bound uuid;v_location uuid;v_base jsonb;v_attention jsonb;v_approvals bigint:=0;v_pr bigint:=0;v_po bigint:=0;v_recv numeric:=0;v_pay numeric:=0;v_store record;
begin
  v_bound:=private.v487_client_mobile_location(p_tenant_id,p_device_id);
  v_location:=coalesce(p_location_id,case when private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'locations.view_all') or private.erp_has_permission(p_tenant_id,'locations.manage_all') then null else v_bound end);
  if v_location is not null and not private.erp_document_scope_allowed(p_tenant_id,v_location,v_location,'view') then raise exception 'Location access denied';end if;
  if v_location is null then
    v_base:=public.mobile_business_summary_v480(p_tenant_id,coalesce(p_day,current_date));
  else
    select * into v_store from public.mobile_store_status_v480(p_tenant_id,coalesce(p_day,current_date)) x where x.location_id=v_location;
    v_base:=jsonb_build_object('day',coalesce(p_day,current_date),'sales',coalesce(v_store.sales_total,0),'returns',coalesce(v_store.returns_total,0),'net_sales',coalesce(v_store.net_sales,0),'gross_profit',coalesce(v_store.gross_profit,0),'invoice_count',coalesce(v_store.invoice_count,0),'stores',case when v_store.location_id is null then '[]'::jsonb else jsonb_build_array(to_jsonb(v_store)) end);
  end if;
  v_attention:=public.business_attention_summary_v480(p_tenant_id,v_location,30);
  select count(*) into v_approvals from public.approval_requests a where a.tenant_id=p_tenant_id and a.status='pending';
  select count(*) into v_pr from public.purchase_requests_v484 r where r.tenant_id=p_tenant_id and r.status='submitted' and (v_location is null or r.location_id=v_location) and private.erp_document_scope_allowed(p_tenant_id,r.location_id,v_location,'view');
  select count(*) into v_po from public.purchase_orders_v480 o where o.tenant_id=p_tenant_id and o.status='submitted' and (v_location is null or o.location_id=v_location) and private.erp_document_scope_allowed(p_tenant_id,o.location_id,v_location,'view');
  select coalesce(sum(x.total_outstanding),0) into v_recv from public.customer_credit_intelligence_v480(p_tenant_id,v_location,'',5000) x;
  select coalesce(sum(x.total_outstanding),0) into v_pay from public.mobile_supplier_outstanding_v487(p_tenant_id,p_device_id,v_location,'',5000) x;
  return v_base||jsonb_build_object(
    'attention',v_attention,'location_id',v_location,'customer_outstanding',round(v_recv,2),'supplier_outstanding',round(v_pay,2),
    'pending_approvals',v_approvals+v_pr+v_po,'generic_approvals',v_approvals,'purchase_request_approvals',v_pr,'purchase_order_approvals',v_po
  );
end$$;


