-- Name: mobile_customer_outstanding_v487(uuid, uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mobile_customer_outstanding_v487(p_tenant_id uuid, p_device_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_query text DEFAULT ''::text, p_limit integer DEFAULT 250) RETURNS TABLE(customer_id uuid, public_id text, customer_name text, phone text, total_outstanding numeric, days_1_30 numeric, days_31_60 numeric, days_61_90 numeric, days_90_plus numeric, open_invoice_count bigint, oldest_due_date date, status text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  perform private.v487_client_mobile_location(p_tenant_id,p_device_id);
  return query select x.customer_id,x.public_id,x.customer_name,x.phone,x.total_outstanding,x.days_1_30,x.days_31_60,x.days_61_90,x.days_90_plus,x.open_invoice_count,x.oldest_due_date,x.status
  from public.customer_credit_intelligence_v480(p_tenant_id,p_location_id,p_query,p_limit) x where x.total_outstanding>0.005;
end$$;


