--
-- Name: mobile_pos_kot_create_v488(uuid, uuid, text, text, uuid, uuid, jsonb, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mobile_pos_kot_create_v488(p_tenant_id uuid, p_device_id uuid, p_request_id text, p_order_type text, p_table_id uuid, p_customer_id uuid, p_items jsonb, p_note text DEFAULT ''::text, p_send_now boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_location uuid;v_existing jsonb;v_order jsonb;v_kot jsonb;v_response jsonb;v_order_id uuid;v_kot_id uuid;v_payload jsonb;
begin
  if nullif(trim(coalesce(p_request_id,'')),'') is null then raise exception 'Request ID is required';end if;
  v_location:=private.v488_mobile_pos_location(p_tenant_id,p_device_id);
  perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':mobile-kot:'||trim(p_request_id),0));
  select response into v_existing from public.mobile_pos_kot_requests_v488 where tenant_id=p_tenant_id and request_id=trim(p_request_id) and status='sent';
  if v_existing is not null then return v_existing||jsonb_build_object('idempotent_replay',true);end if;
  v_payload:=jsonb_build_object('order_type',p_order_type,'table_id',p_table_id,'customer_id',p_customer_id,'items',coalesce(p_items,'[]'::jsonb),'note',coalesce(p_note,''),'send_now',coalesce(p_send_now,true));
  insert into public.mobile_pos_kot_requests_v488(tenant_id,request_id,device_id,location_id,payload,status,created_by,updated_at)
  values(p_tenant_id,trim(p_request_id),p_device_id,v_location,v_payload,'processing',auth.uid(),now())
  on conflict(tenant_id,request_id) do update set payload=excluded.payload,status='processing',updated_at=now();
  begin
    v_order:=public.restaurant_order_create_v32(p_tenant_id,v_location,p_device_id,coalesce(nullif(trim(p_order_type),''),'takeaway'),p_table_id,p_customer_id,15,p_note,null,coalesce(p_items,'[]'::jsonb));
    v_order_id:=nullif(v_order->>'order_id','')::uuid;
    if coalesce(p_send_now,true) then
      v_kot:=public.restaurant_kot_send_v32(p_tenant_id,v_order_id,p_device_id,p_note);
      v_kot_id:=nullif(v_kot->>'kot_id','')::uuid;
    else v_kot:='{}'::jsonb;end if;
    v_response:=coalesce(v_order,'{}'::jsonb)||coalesce(v_kot,'{}'::jsonb)||jsonb_build_object('ok',true,'request_id',trim(p_request_id),'mobile_pos',true);
    update public.mobile_pos_kot_requests_v488 set order_id=v_order_id,kot_id=v_kot_id,response=v_response,status='sent',updated_at=now() where tenant_id=p_tenant_id and request_id=trim(p_request_id);
    return v_response;
  exception when others then
    update public.mobile_pos_kot_requests_v488 set response=jsonb_build_object('ok',false,'message',sqlerrm),status='error',updated_at=now() where tenant_id=p_tenant_id and request_id=trim(p_request_id);
    raise;
  end;
end$$;


--
-- Name: mobile_pos_kot_create_v520(uuid, uuid, text, text, uuid, uuid, jsonb, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mobile_pos_kot_create_v520(p_tenant_id uuid, p_device_id uuid, p_request_id text, p_order_type text, p_table_id uuid, p_customer_id uuid, p_items jsonb, p_note text DEFAULT ''::text, p_send_now boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_location uuid;
  v_request text:=nullif(trim(coalesce(p_request_id,'')),'');
  v_payload jsonb;
  v_identity jsonb;
  v_hash text;
  r private.mobile_pos_kot_requests_v520%rowtype;
  v_order jsonb;
  v_kot jsonb:='{}'::jsonb;
  v_response jsonb;
  v_order_id uuid;
  v_kot_id uuid;
begin
  if v_request is null then raise exception 'Request ID is required'; end if;
  if length(v_request)>160 then raise exception 'Mobile KOT request ID is too long'; end if;
  v_location:=private.v488_mobile_pos_location(p_tenant_id,p_device_id);

  v_payload:=jsonb_build_object(
    'order_type',coalesce(nullif(trim(p_order_type),''),'takeaway'),
    'table_id',p_table_id,
    'customer_id',p_customer_id,
    'items',coalesce(p_items,'[]'::jsonb),
    'note',coalesce(p_note,''),
    'send_now',coalesce(p_send_now,true)
  );
  v_identity:=jsonb_build_object('device_id',p_device_id,'location_id',v_location,'payload',v_payload);
  v_hash:=private.gst_request_hash_v520(v_identity);

  perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':mobile-kot-v520:'||v_request,0));
  select * into r
  from private.mobile_pos_kot_requests_v520
  where tenant_id=p_tenant_id and request_id=v_request
  for update;

  if found then
    if r.request_hash is distinct from v_hash
       or r.device_id is distinct from p_device_id
       or r.location_id is distinct from v_location
       or r.payload is distinct from v_payload then
      raise exception 'Request ID was already used with a different Mobile KOT payload';
    end if;
    if r.status='sent' and r.response is not null then
      return r.response || jsonb_build_object('idempotent_replay',true);
    end if;
    raise exception 'Existing Mobile KOT request is incomplete and requires reconciliation';
  end if;

  insert into private.mobile_pos_kot_requests_v520(
    tenant_id,request_id,request_hash,device_id,location_id,payload,status,created_by
  ) values(
    p_tenant_id,v_request,v_hash,p_device_id,v_location,v_payload,'processing',auth.uid()
  );

  v_order:=public.restaurant_order_create_v32(
    p_tenant_id,v_location,p_device_id,
    coalesce(nullif(trim(p_order_type),''),'takeaway'),
    p_table_id,p_customer_id,15,p_note,null,coalesce(p_items,'[]'::jsonb)
  );
  v_order_id:=nullif(v_order->>'order_id','')::uuid;
  if v_order_id is null then raise exception 'Restaurant order was not created'; end if;

  if coalesce(p_send_now,true) then
    v_kot:=public.restaurant_kot_send_v32(p_tenant_id,v_order_id,p_device_id,p_note);
    v_kot_id:=nullif(v_kot->>'kot_id','')::uuid;
    if v_kot_id is null then raise exception 'Restaurant KOT was not created'; end if;
  end if;

  v_response:=coalesce(v_order,'{}'::jsonb)||coalesce(v_kot,'{}'::jsonb)||jsonb_build_object(
    'ok',true,
    'request_id',v_request,
    'mobile_pos',true,
    'mobile_release','5.2',
    'mobile_contract','v5.2',
    'gst_authoritative',false,
    'gst_authority_at_billing','gst_restaurant_order_bill_v520'
  );

  update private.mobile_pos_kot_requests_v520
  set order_id=v_order_id,kot_id=v_kot_id,response=v_response,status='sent',updated_at=now()
  where tenant_id=p_tenant_id and request_id=v_request;

  return v_response;
end
$$;


--
-- Name: mobile_pos_product_cache_v520(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mobile_pos_product_cache_v520(p_tenant_id uuid, p_device_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_base jsonb;
  v_result jsonb;
begin
  perform private.v488_mobile_pos_location(p_tenant_id,p_device_id);
  v_base:=public.pos_offline_product_cache_v486(p_tenant_id,p_device_id);

  select coalesce(jsonb_agg(
    case
      when nullif(e->'gst_profile'->>'profile_id','') is not null then
        e || jsonb_build_object(
          'tax_rate',case
            when lower(coalesce(e->'gst_profile'->>'taxability',''))='taxable'
              then coalesce(nullif(e->'gst_profile'->>'gst_rate','')::numeric,0)
            else 0
          end,
          'tax_source','gst_profile_v520'
        )
      else
        e || jsonb_build_object(
          'tax_rate',coalesce(nullif(e->>'tax_rate','')::numeric,0),
          'tax_source','legacy_fallback'
        )
    end
    order by e->>'product_name',e->>'sku'
  ),'[]'::jsonb)
  into v_result
  from jsonb_array_elements(coalesce(v_base,'[]'::jsonb)) e;

  return coalesce(v_result,'[]'::jsonb);
end
$$;


--
-- Name: mobile_pos_receipt_event_v488(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mobile_pos_receipt_event_v488(p_tenant_id uuid, p_device_id uuid, p_request_id text, p_event_type text, p_local_invoice_number text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_location uuid;v_sale uuid;v_state text:='local';v_id uuid;
begin
  v_location:=private.v488_mobile_pos_location(p_tenant_id,p_device_id);
  if lower(trim(coalesce(p_event_type,''))) not in('print','share') then raise exception 'Invalid receipt event';end if;
  select nullif(server_response->>'sale_id','')::uuid,case when status='synced' then 'synced' else 'local' end into v_sale,v_state
  from public.pos_offline_sync_v486 where tenant_id=p_tenant_id and request_id=trim(p_request_id);
  insert into public.mobile_pos_receipt_events_v488(tenant_id,device_id,location_id,request_id,local_invoice_number,sale_id,event_type,receipt_state,created_by)
  values(p_tenant_id,p_device_id,v_location,trim(p_request_id),nullif(trim(coalesce(p_local_invoice_number,'')),''),v_sale,lower(trim(p_event_type)),v_state,auth.uid()) returning id into v_id;
  return jsonb_build_object('ok',true,'event_id',v_id,'receipt_state',v_state);
end$$;


--
-- Name: mobile_pos_receipt_event_v520(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mobile_pos_receipt_event_v520(p_tenant_id uuid, p_device_id uuid, p_request_id text, p_event_type text, p_local_invoice_number text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_location uuid;
  v_request text:=nullif(trim(coalesce(p_request_id,'')),'');
  v_event text:=lower(trim(coalesce(p_event_type,'')));
  q public.pos_offline_sync_v486%rowtype;
  v_sale uuid;
  v_state text:='local';
  v_id uuid;
begin
  v_location:=private.v488_mobile_pos_location(p_tenant_id,p_device_id);
  if v_request is null then raise exception 'Request ID is required'; end if;
  if v_event not in('print','share') then raise exception 'Invalid receipt event'; end if;

  select * into q
  from public.pos_offline_sync_v486
  where tenant_id=p_tenant_id
    and request_id=v_request
    and device_id=p_device_id
    and location_id=v_location
    and sync_contract_version='v5.2'
    and payload_snapshot->>'channel'='mobile_pos';

  if found then
    if q.status='synced' then
      if q.sale_id is null or q.gst_snapshot_id is null or q.gst_journal_id is null then
        raise exception 'Synced Mobile POS request is missing authoritative GST recovery evidence';
      end if;
      v_sale:=q.sale_id;
      v_state:='synced';
    end if;
  elsif exists(
    select 1 from public.pos_offline_sync_v486 x
    where x.tenant_id=p_tenant_id and x.request_id=v_request
  ) then
    raise exception 'Request ID belongs to another POS device, location, or sync contract';
  end if;

  insert into public.mobile_pos_receipt_events_v488(
    tenant_id,device_id,location_id,request_id,local_invoice_number,
    sale_id,event_type,receipt_state,created_by
  ) values(
    p_tenant_id,p_device_id,v_location,v_request,
    nullif(trim(coalesce(p_local_invoice_number,'')),''),
    v_sale,v_event,v_state,auth.uid()
  ) returning id into v_id;

  return jsonb_build_object(
    'ok',true,
    'event_id',v_id,
    'receipt_state',v_state,
    'sale_id',v_sale,
    'mobile_contract','v5.2',
    'authoritative_gst',v_state='synced'
  );
end
$$;


--
