--
-- Name: mobile_pos_sync_status_v488(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mobile_pos_sync_status_v488(p_tenant_id uuid, p_device_id uuid, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_location uuid;v_summary jsonb;v_rows jsonb;
begin
  v_location:=private.v488_mobile_pos_location(p_tenant_id,p_device_id);
  v_summary:=public.pos_offline_sync_summary_v486(p_tenant_id,p_device_id);
  select coalesce(jsonb_agg(to_jsonb(x) order by x.last_attempt_at desc nulls last,x.first_seen_at desc),'[]'::jsonb) into v_rows
    from public.pos_offline_sync_list_v486(p_tenant_id,p_device_id,null,greatest(1,least(coalesce(p_limit,100),500))) x;
  return jsonb_build_object('release','4.8.8','location_id',v_location,'summary',coalesce(v_summary,'{}'::jsonb),'recent',coalesce(v_rows,'[]'::jsonb));
end$$;


--
-- Name: mobile_pos_sync_status_v520(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mobile_pos_sync_status_v520(p_tenant_id uuid, p_device_id uuid, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_location uuid;
  v_summary jsonb;
  v_recent jsonb;
begin
  v_location:=private.v488_mobile_pos_location(p_tenant_id,p_device_id);

  select jsonb_build_object(
    'pending',count(*) filter(where q.status in('pending','syncing')),
    'conflict',count(*) filter(where q.status='conflict'),
    'error',count(*) filter(where q.status='error'),
    'cancelled',count(*) filter(where q.status='cancelled'),
    'synced_today',count(*) filter(where q.status='synced' and q.synced_at::date=current_date),
    'last_synced_at',max(q.synced_at)
  )
  into v_summary
  from public.pos_offline_sync_v486 q
  where q.tenant_id=p_tenant_id
    and q.device_id=p_device_id
    and q.location_id=v_location
    and q.sync_contract_version='v5.2'
    and q.payload_snapshot->>'channel'='mobile_pos';

  select coalesce(jsonb_agg(to_jsonb(r) order by r.updated_at desc),'[]'::jsonb)
  into v_recent
  from (
    select
      q.request_id,q.local_invoice_number,q.status,q.conflict_code,q.conflict_message,
      q.attempts,q.first_seen_at,q.last_attempt_at,q.synced_at,q.updated_at,
      q.sale_id,q.gst_snapshot_id,q.gst_journal_id,q.server_response
    from public.pos_offline_sync_v486 q
    where q.tenant_id=p_tenant_id
      and q.device_id=p_device_id
      and q.location_id=v_location
      and q.sync_contract_version='v5.2'
      and q.payload_snapshot->>'channel'='mobile_pos'
    order by q.updated_at desc
    limit greatest(1,least(coalesce(p_limit,100),500))
  ) r;

  return jsonb_build_object(
    'release','5.2',
    'mobile_contract','v5.2',
    'device_id',p_device_id,
    'location_id',v_location,
    'summary',coalesce(v_summary,'{}'::jsonb),
    'recent',coalesce(v_recent,'[]'::jsonb)
  );
end
$$;


--
-- Name: mobile_pos_terminal_context_v488(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mobile_pos_terminal_context_v488(p_tenant_id uuid, p_device_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_location uuid;d public.business_devices%rowtype;l public.business_locations%rowtype;v_settings jsonb:='{}'::jsonb;v_restaurant boolean:=false;v_shift jsonb;
begin
  v_location:=private.v488_mobile_pos_location(p_tenant_id,p_device_id);
  select * into d from public.business_devices where id=p_device_id and tenant_id=p_tenant_id;
  select * into l from public.business_locations where id=v_location and tenant_id=p_tenant_id;
  select to_jsonb(s) into v_settings from public.mobile_pos_terminal_settings_v488 s where s.tenant_id=p_tenant_id and s.device_id=p_device_id;
  select exists(select 1 from public.tenant_modules tm where tm.tenant_id=p_tenant_id and tm.module_key='restaurant' and tm.enabled) into v_restaurant;
  begin v_shift:=public.cashier_shift_current_v472(p_tenant_id,p_device_id);exception when others then v_shift:=null;end;
  return jsonb_build_object(
    'release','4.8.8','mobile_pos',true,'device_id',d.id,'device_code',d.device_code,'device_name',d.name,
    'location_id',l.id,'location_code',l.location_code,'location_name',l.name,
    'username',coalesce((select u.username::text from public.user_login_names u where u.user_id=auth.uid()),auth.uid()::text),
    'restaurant_enabled',v_restaurant,'current_shift',v_shift,'settings',coalesce(v_settings,'{}'::jsonb),
    'offline_supported',true,'camera_scanner',true,'system_printing',true,'kot_groundwork',true
  );
end$$;


