--
-- Name: mobile_purchases_status_v487(uuid, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mobile_purchases_status_v487(p_tenant_id uuid, p_device_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100) RETURNS TABLE(document_type text, id uuid, document_number text, document_date date, supplier_name text, status text, grand_total numeric, balance_due numeric, location_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  perform private.v487_client_mobile_location(p_tenant_id,p_device_id);
  return query
  select * from (
    select 'purchase_order'::text,o.id,o.order_number,o.order_date,s.name,o.status,o.grand_total,0::numeric,l.name
      from public.purchase_orders_v480 o join public.suppliers s on s.id=o.supplier_id join public.business_locations l on l.id=o.location_id
      where o.tenant_id=p_tenant_id and (p_location_id is null or o.location_id=p_location_id) and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view')
    union all
    select 'purchase_invoice'::text,i.id,i.invoice_number,i.invoice_date,s.name,i.status,i.grand_total,i.balance_due,l.name
      from public.purchase_invoices_v484 i join public.suppliers s on s.id=i.supplier_id join public.business_locations l on l.id=i.location_id
      where i.tenant_id=p_tenant_id and (p_location_id is null or i.location_id=p_location_id) and private.erp_document_scope_allowed(p_tenant_id,i.location_id,p_location_id,'view')
    union all
    select 'legacy_purchase'::text,p.id,p.purchase_number,p.purchase_date,s.name,coalesce(p.status,'posted'),p.grand_total,
      greatest(p.grand_total-coalesce(py.paid,0)-coalesce(rt.returned,0),0)::numeric,l.name
      from public.purchases p join public.suppliers s on s.id=p.supplier_id
      left join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='purchase' and o.entity_id=p.id
      left join public.business_locations l on l.id=o.location_id
      left join(select purchase_id,sum(amount) paid from public.purchase_payments group by purchase_id) py on py.purchase_id=p.id
      left join(select purchase_id,sum(grand_total) returned from public.purchase_returns where credit_status<>'waived' group by purchase_id) rt on rt.purchase_id=p.id
      where p.tenant_id=p_tenant_id and (p_location_id is null or o.location_id=p_location_id) and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view')
  ) q order by document_date desc limit greatest(1,least(coalesce(p_limit,100),500));
end$$;


--
-- Name: mobile_sales_status_v487(uuid, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mobile_sales_status_v487(p_tenant_id uuid, p_device_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100) RETURNS TABLE(id uuid, sale_number text, sale_date date, customer_name text, status text, grand_total numeric, paid_total numeric, balance_due numeric, location_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_bound uuid;v_loc uuid;
begin
  v_bound:=private.v487_client_mobile_location(p_tenant_id,p_device_id);v_loc:=p_location_id;
  return query
  select s.id,s.sale_number,s.sale_date,c.name,coalesce(s.status,'posted'),s.grand_total,coalesce(py.paid,0)::numeric,
    greatest(s.grand_total-coalesce(rt.returned,0)-coalesce(py.paid,0),0)::numeric,l.name
  from public.sales s join public.customers c on c.id=s.customer_id
  left join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='sale' and o.entity_id=s.id
  left join public.business_locations l on l.id=o.location_id
  left join(select sale_id,sum(amount) paid from public.sale_payments group by sale_id) py on py.sale_id=s.id
  left join(select sale_id,sum(grand_total) returned from public.sales_returns where refund_status<>'waived' group by sale_id) rt on rt.sale_id=s.id
  where s.tenant_id=p_tenant_id and (v_loc is null or o.location_id=v_loc) and private.erp_document_scope_allowed(p_tenant_id,o.location_id,v_loc,'view')
  order by s.sale_date desc,s.created_at desc limit greatest(1,least(coalesce(p_limit,100),500));
end$$;


--
-- Name: mobile_store_status_v480(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mobile_store_status_v480(p_tenant_id uuid, p_day date DEFAULT CURRENT_DATE) RETURNS TABLE(location_id uuid, location_code text, location_name text, sales_total numeric, returns_total numeric, net_sales numeric, gross_profit numeric, invoice_count bigint, inventory_value numeric, low_stock_count bigint, out_of_stock_count bigint, receivables numeric, payables numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  return query
  with sale as (
    select o.location_id,sum(s.grand_total)::numeric total,sum(coalesce(s.gross_profit,0))::numeric profit,count(*)::bigint cnt
    from public.sales s join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='sale' and o.entity_id=s.id
    where s.tenant_id=p_tenant_id and s.sale_date=coalesce(p_day,current_date) and coalesce(s.status,'') not in('void','cancelled')
      and private.erp_document_scope_allowed(p_tenant_id,o.location_id,null,'view') group by o.location_id
  ), ret as (
    select r.location_id,sum(r.grand_total)::numeric total,
      sum(coalesce(si.cost_total,0)*(ri.quantity/nullif(si.quantity,0)))::numeric returned_cost
    from public.sales_returns r join public.sales_return_items ri on ri.sales_return_id=r.id join public.sale_items si on si.id=ri.sale_item_id
    where r.tenant_id=p_tenant_id and r.return_date=coalesce(p_day,current_date) and r.refund_status<>'waived'
      and private.erp_document_scope_allowed(p_tenant_id,r.location_id,null,'view') group by r.location_id
  ), stock as (
    select ii.location_id,sum(ii.stock_value)::numeric val,count(*) filter(where ii.status='low_stock')::bigint low,count(*) filter(where ii.status='out_of_stock')::bigint out
    from public.inventory_intelligence_v480(p_tenant_id,null,30,'',5000) ii group by ii.location_id
  ), recv as (
    select o.location_id,sum(greatest(s.grand_total-coalesce(rt.returned,0)-coalesce(py.paid,0),0))::numeric amount
    from public.sales s join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='sale' and o.entity_id=s.id
    left join(select sale_id,sum(amount) paid from public.sale_payments group by sale_id) py on py.sale_id=s.id
    left join(select sale_id,sum(grand_total) returned from public.sales_returns where refund_status<>'waived' group by sale_id) rt on rt.sale_id=s.id
    where s.tenant_id=p_tenant_id and coalesce(s.status,'') not in('void','cancelled') and private.erp_document_scope_allowed(p_tenant_id,o.location_id,null,'view') group by o.location_id
  ), pay as (
    select o.location_id,sum(greatest(p.grand_total-coalesce(rt.returned,0)-coalesce(py.paid,0),0))::numeric amount
    from public.purchases p join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='purchase' and o.entity_id=p.id
    left join(select purchase_id,sum(amount) paid from public.purchase_payments group by purchase_id) py on py.purchase_id=p.id
    left join(select purchase_id,sum(grand_total) returned from public.purchase_returns where credit_status<>'waived' group by purchase_id) rt on rt.purchase_id=p.id
    where p.tenant_id=p_tenant_id and coalesce(p.status,'') not in('void','cancelled') and private.erp_document_scope_allowed(p_tenant_id,o.location_id,null,'view') group by o.location_id
  )
  select l.id,l.location_code,l.name,coalesce(sale.total,0),coalesce(ret.total,0),greatest(coalesce(sale.total,0)-coalesce(ret.total,0),0),
    coalesce(sale.profit,0)-coalesce(ret.total-coalesce(ret.returned_cost,0),0),coalesce(sale.cnt,0),coalesce(stock.val,0),coalesce(stock.low,0),coalesce(stock.out,0),coalesce(recv.amount,0),coalesce(pay.amount,0)
  from public.business_locations l
  left join sale on sale.location_id=l.id left join ret on ret.location_id=l.id left join stock on stock.location_id=l.id left join recv on recv.location_id=l.id left join pay on pay.location_id=l.id
  where l.tenant_id=p_tenant_id and l.active and private.erp_document_scope_allowed(p_tenant_id,l.id,null,'view')
  order by l.name;
end $$;


--
-- Name: mobile_supplier_outstanding_v487(uuid, uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mobile_supplier_outstanding_v487(p_tenant_id uuid, p_device_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_query text DEFAULT ''::text, p_limit integer DEFAULT 250) RETURNS TABLE(supplier_id uuid, supplier_name text, phone text, total_outstanding numeric, current_amount numeric, days_1_30 numeric, days_31_60 numeric, days_61_90 numeric, days_90_plus numeric, open_invoice_count bigint, oldest_due_date date, status text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare q text:='%'||lower(trim(coalesce(p_query,'')))||'%';
begin
  perform private.v487_client_mobile_location(p_tenant_id,p_device_id);
  return query
  with legacy as (
    select p.supplier_id,coalesce(p.due_date,p.purchase_date) due_date,greatest(p.grand_total-coalesce(py.paid,0)-coalesce(rt.returned,0),0)::numeric balance
    from public.purchases p
    left join(select purchase_id,sum(amount) paid from public.purchase_payments group by purchase_id) py on py.purchase_id=p.id
    left join(select purchase_id,sum(grand_total) returned from public.purchase_returns where credit_status<>'waived' group by purchase_id) rt on rt.purchase_id=p.id
    left join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='purchase' and o.entity_id=p.id
    where p.tenant_id=p_tenant_id and coalesce(p.status,'') not in('void','cancelled') and (p_location_id is null or o.location_id=p_location_id)
      and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view') and greatest(p.grand_total-coalesce(py.paid,0)-coalesce(rt.returned,0),0)>0.005
  ), v2 as (
    select i.supplier_id,coalesce(i.due_date,i.invoice_date) due_date,i.balance_due::numeric balance
    from public.purchase_invoices_v484 i where i.tenant_id=p_tenant_id and i.status in('posted','part_paid') and i.balance_due>0.005
      and (p_location_id is null or i.location_id=p_location_id) and private.erp_document_scope_allowed(p_tenant_id,i.location_id,p_location_id,'view')
  ), open_docs as (select * from legacy union all select * from v2), agg as (
    select d.supplier_id,sum(d.balance)::numeric outstanding,count(*)::bigint cnt,min(d.due_date) oldest,
      sum(d.balance) filter(where d.due_date>=current_date)::numeric current_amt,
      sum(d.balance) filter(where d.due_date<current_date and d.due_date>=current_date-30)::numeric a1,
      sum(d.balance) filter(where d.due_date<current_date-30 and d.due_date>=current_date-60)::numeric a2,
      sum(d.balance) filter(where d.due_date<current_date-60 and d.due_date>=current_date-90)::numeric a3,
      sum(d.balance) filter(where d.due_date<current_date-90)::numeric a4
    from open_docs d group by d.supplier_id
  )
  select s.id,s.name,coalesce(s.phone,''),coalesce(a.outstanding,0),coalesce(a.current_amt,0),coalesce(a.a1,0),coalesce(a.a2,0),coalesce(a.a3,0),coalesce(a.a4,0),coalesce(a.cnt,0),a.oldest,
    case when coalesce(a.a4,0)>0 then 'critical_overdue' when coalesce(a.a1,0)+coalesce(a.a2,0)+coalesce(a.a3,0)>0 then 'overdue' else 'current' end::text
  from public.suppliers s join agg a on a.supplier_id=s.id
  where s.tenant_id=p_tenant_id and (trim(coalesce(p_query,''))='' or lower(s.name) like q or lower(coalesce(s.phone,'')) like q)
  order by coalesce(a.a4,0) desc,coalesce(a.outstanding,0) desc,s.name limit greatest(1,least(coalesce(p_limit,250),2000));
end$$;


--
-- Name: notification_mark_read_v4(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notification_mark_read_v4(p_tenant_id uuid, p_notification_id uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ update public.notifications set read_at=coalesce(read_at,now()) where id=p_notification_id and tenant_id=p_tenant_id and (user_id is null or user_id=auth.uid()) $$;


--
-- Name: notifications; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.notifications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    user_id uuid,
    location_id uuid,
    category text DEFAULT 'system'::text NOT NULL,
    severity text DEFAULT 'info'::text NOT NULL,
    title text NOT NULL,
    message text NOT NULL,
    entity_type text,
    entity_id uuid,
    read_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT notifications_severity_check CHECK ((severity = ANY (ARRAY['info'::text, 'success'::text, 'warning'::text, 'critical'::text])))
);


--
-- Name: notifications_list_v4(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notifications_list_v4(p_tenant_id uuid, p_limit integer DEFAULT 50) RETURNS SETOF public.notifications
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$begin if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;perform private.v4_refresh_notifications(p_tenant_id,auth.uid());perform private.loan_v490_refresh_notifications(p_tenant_id,auth.uid());perform private.v495_refresh_notifications(p_tenant_id,auth.uid());perform private.v500_refresh_notifications(p_tenant_id,auth.uid());perform private.v500_build25_refresh_notifications(p_tenant_id,auth.uid());return query select * from public.notifications where tenant_id=p_tenant_id and (user_id is null or user_id=auth.uid()) order by case severity when 'critical' then 0 when 'warning' then 1 when 'success' then 2 else 3 end,(read_at is null) desc,created_at desc limit greatest(1,least(coalesce(p_limit,50),300));end $$;


--
-- Name: notifications_mark_all_read_v495(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notifications_mark_all_read_v495(p_tenant_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_count integer;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  update public.notifications set read_at=coalesce(read_at,now()) where tenant_id=p_tenant_id and (user_id is null or user_id=auth.uid()) and read_at is null;
  get diagnostics v_count=row_count; return v_count;
end $$;


--
-- Name: opening_balance_post_v500(uuid, date, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.opening_balance_post_v500(p_tenant_id uuid, p_entry_date date, p_lines jsonb, p_description text DEFAULT 'Opening balances'::text, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v_id uuid:=gen_random_uuid();v_journal uuid;begin perform private.v500_accounting_access(p_tenant_id,true);if exists(select 1 from public.opening_balance_batches_v500 where tenant_id=p_tenant_id and status='posted' and entry_date=p_entry_date and coalesce(location_id,'00000000-0000-0000-0000-000000000000'::uuid)=coalesce(p_location_id,'00000000-0000-0000-0000-000000000000'::uuid)) then raise exception 'Opening balances already posted for this date and location';end if;v_journal:=private.v4_journal_create(p_tenant_id,p_location_id,p_entry_date,coalesce(nullif(trim(p_description),''),'Opening balances'),'opening_balance_v500',v_id,'OPENING',p_lines);insert into public.opening_balance_batches_v500(id,tenant_id,location_id,entry_date,description,journal_id,created_by) values(v_id,p_tenant_id,p_location_id,p_entry_date,coalesce(nullif(trim(p_description),''),'Opening balances'),v_journal,auth.uid());return jsonb_build_object('opening_balance_id',v_id,'journal_id',v_journal);end $$;


--
-- Name: opening_balances_list_v500(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.opening_balances_list_v500(p_tenant_id uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare r record;begin perform private.v500_accounting_access(p_tenant_id,false);for r in select b.*,j.entry_number from public.opening_balance_batches_v500 b join public.journal_entries j on j.id=b.journal_id where b.tenant_id=p_tenant_id and (p_from is null or b.entry_date>=p_from) and (p_to is null or b.entry_date<=p_to) order by b.entry_date desc,b.created_at desc loop return next to_jsonb(r);end loop;return;end $$;


--
-- Name: operations_pipeline_v489(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.operations_pipeline_v489(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_pr bigint:=0;v_po bigint:=0;v_grn bigint:=0;v_invoice bigint:=0;
  v_transit bigint:=0;v_conflicts bigint:=0;v_batches bigint:=0;v_warranty bigint:=0;
  v_restaurant bigint:=0;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  select count(*) into v_pr from public.purchase_requests_v484 r
   where r.tenant_id=p_tenant_id and r.status='submitted'
     and (p_location_id is null or r.location_id=p_location_id)
     and private.erp_document_scope_allowed(p_tenant_id,r.location_id,p_location_id,'view');
  select count(*) into v_po from public.purchase_orders_v480 p
   where p.tenant_id=p_tenant_id and p.status='submitted'
     and (p_location_id is null or p.location_id=p_location_id)
     and private.erp_document_scope_allowed(p_tenant_id,p.location_id,p_location_id,'view');
  select count(*) into v_grn from public.goods_receipts_v484 g
   where g.tenant_id=p_tenant_id and g.status='draft'
     and (p_location_id is null or g.location_id=p_location_id)
     and private.erp_document_scope_allowed(p_tenant_id,g.location_id,p_location_id,'view');
  select count(*) into v_invoice from public.purchase_invoices_v484 i
   where i.tenant_id=p_tenant_id and i.status='draft'
     and (p_location_id is null or i.location_id=p_location_id)
     and private.erp_document_scope_allowed(p_tenant_id,i.location_id,p_location_id,'view');
  select count(*) into v_transit from public.stock_transfers t
   where t.tenant_id=p_tenant_id and t.status in('dispatched','in_transit')
     and (p_location_id is null or t.from_location_id=p_location_id or t.to_location_id=p_location_id)
     and (private.erp_document_scope_allowed(p_tenant_id,t.from_location_id,p_location_id,'view')
       or private.erp_document_scope_allowed(p_tenant_id,t.to_location_id,p_location_id,'view'));
  select count(*) into v_conflicts from public.pos_offline_sync_v486 q
   where q.tenant_id=p_tenant_id and q.status in('conflict','error')
     and (p_location_id is null or q.location_id=p_location_id)
     and private.erp_document_scope_allowed(p_tenant_id,q.location_id,p_location_id,'view');
  select count(distinct b.id) into v_batches
    from public.inventory_batches_v483 b
    join public.inventory_batch_balances_v483 bb on bb.tenant_id=b.tenant_id and bb.batch_id=b.id
   where b.tenant_id=p_tenant_id and b.status='active' and b.expiry_on between current_date and current_date+30
     and bb.quantity>0 and (p_location_id is null or bb.location_id=p_location_id)
     and private.erp_document_scope_allowed(p_tenant_id,bb.location_id,p_location_id,'view');
  select count(*) into v_warranty from public.product_warranties_v483 w
   where w.tenant_id=p_tenant_id and w.status='active' and w.warranty_expiry between current_date and current_date+30
     and exists(select 1 from public.document_origins o where o.tenant_id=p_tenant_id and o.entity_type='sale' and o.entity_id=w.sale_id
       and (p_location_id is null or o.location_id=p_location_id) and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view'));
  select count(*) into v_restaurant from public.restaurant_orders r
   where r.tenant_id=p_tenant_id and coalesce(r.status,'') not in('billed','cancelled','closed')
     and (p_location_id is null or r.location_id=p_location_id)
     and private.erp_document_scope_allowed(p_tenant_id,r.location_id,p_location_id,'view');
  return jsonb_build_object(
    'purchase_requests_awaiting_approval',v_pr,
    'purchase_orders_awaiting_approval',v_po,
    'draft_grns',v_grn,
    'draft_purchase_invoices',v_invoice,
    'transfers_in_transit',v_transit,
    'offline_pos_conflicts',v_conflicts,
    'batches_expiring_30d',v_batches,
    'warranties_expiring_30d',v_warranty,
    'restaurant_open_orders',v_restaurant
  );
end $$;


--
-- Name: payment_method_save_v522(uuid, text, text, uuid, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payment_method_save_v522(p_tenant_id uuid, p_code text, p_display_name text, p_ledger_account_id uuid, p_active boolean, p_sort_order integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_code text:=lower(trim(coalesce(p_code,'')));v_id uuid;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  if not(private.erp_user_is_owner(p_tenant_id, auth.uid()) or private.erp_has_permission(p_tenant_id,'settings.manage') or private.erp_has_permission(p_tenant_id,'business.settings')) then
    raise exception 'Owner/Admin permission required';
  end if;
  if v_code not in ('cash','upi','card','bank','cheque','wallet','credit','other') then raise exception 'Unsupported payment method %',p_code; end if;
  if v_code<>'credit' and coalesce(p_active,true) and p_ledger_account_id is null then raise exception 'Active settlement method requires a ledger mapping'; end if;
  if p_ledger_account_id is not null and not exists(select 1 from public.accounting_accounts a where a.id=p_ledger_account_id and a.tenant_id=p_tenant_id and a.active) then
    raise exception 'Ledger account is invalid or inactive';
  end if;
  insert into public.payment_methods_v522(tenant_id,code,display_name,ledger_account_id,active,allow_over_tender,sort_order)
  values(p_tenant_id,v_code,coalesce(nullif(trim(p_display_name),''),initcap(v_code)),case when v_code='credit' then null else p_ledger_account_id end,
         coalesce(p_active,true),v_code='cash',coalesce(p_sort_order,0))
  on conflict(tenant_id,code) do update set display_name=excluded.display_name,ledger_account_id=excluded.ledger_account_id,
    active=excluded.active,allow_over_tender=excluded.allow_over_tender,sort_order=excluded.sort_order,updated_at=now()
  returning id into v_id;
  if v_code<>'credit' and p_ledger_account_id is not null then
    insert into public.accounting_account_mappings(tenant_id,mapping_key,account_id,updated_at)
    values(p_tenant_id,'payment.'||v_code,p_ledger_account_id,now())
    on conflict(tenant_id,mapping_key) do update set account_id=excluded.account_id,updated_at=now();
  end if;
  return jsonb_build_object('success',true,'id',v_id,'code',v_code);
end;
$$;


--
-- Name: payment_methods_list_v522(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payment_methods_list_v522(p_tenant_id uuid) RETURNS TABLE(id uuid, code text, display_name text, ledger_account_id uuid, ledger_code text, ledger_name text, active boolean, allow_over_tender boolean, sort_order integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  return query
  select pm.id,pm.code,pm.display_name,pm.ledger_account_id,a.code,a.name,pm.active,pm.allow_over_tender,pm.sort_order
  from public.payment_methods_v522 pm
  left join public.accounting_accounts a on a.id=pm.ledger_account_id and a.tenant_id=pm.tenant_id
  where pm.tenant_id=p_tenant_id
  order by pm.sort_order,pm.display_name;
end;
$$;


--
-- Name: payments_party_detail_v491(uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payments_party_detail_v491(p_tenant_id uuid, p_party_type text, p_party_id uuid, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_party jsonb;
  v_documents jsonb:='[]'::jsonb;
  v_payments jsonb:='[]'::jsonb;
  v_credit numeric:=0;
  v_kind text:=lower(trim(coalesce(p_party_type,'')));
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if not private.erp_has_permission(p_tenant_id,'payments.view')
     and not private.erp_has_permission(p_tenant_id,'sales.manage')
     and not private.erp_has_permission(p_tenant_id,'purchases.manage')
     and not private.erp_user_is_owner(p_tenant_id) then raise exception 'Permission denied';end if;

  if v_kind='customer' then
    select jsonb_build_object(
      'party_id',c.id,'party_type','customer','party_name',c.name,'tracking_code',coalesce(c.tracking_code,''),
      'phone',coalesce(c.phone,''),'email',coalesce(c.email,''),'tax_number',coalesce(c.tax_number,'')
    ) into v_party from public.customers c where c.tenant_id=p_tenant_id and c.id=p_party_id;
    if v_party is null then raise exception 'Customer not found';end if;

    with sale_paid as (
      select sale_id,sum(amount)::numeric paid from public.sale_payments group by sale_id
    ), sale_returned as (
      select sale_id,sum(grand_total)::numeric returned from public.sales_returns where refund_status<>'waived' group by sale_id
    ), docs as (
      select 'sale'::text source_type,s.id source_id,
        coalesce(dn.terminal_number,ln.local_number,s.sale_number) reference,s.sale_date doc_date,s.due_date,
        s.grand_total::numeric total,coalesce(sp.paid,0)::numeric paid,
        greatest(s.grand_total-coalesce(sp.paid,0)-coalesce(sr.returned,0),0)::numeric balance,
        coalesce(s.status,'') status,o.location_id,l.name location_name,
        jsonb_build_object('returned',coalesce(sr.returned,0),'sale_number',s.sale_number) extra
      from public.sales s
      left join sale_paid sp on sp.sale_id=s.id left join sale_returned sr on sr.sale_id=s.id
      left join public.document_origins o on o.tenant_id=s.tenant_id and o.entity_type='sale' and o.entity_id=s.id
      left join public.business_locations l on l.id=o.location_id
      left join public.location_document_numbers ln on ln.entity_type='sale' and ln.entity_id=s.id
      left join public.device_document_numbers dn on dn.entity_type='sale' and dn.entity_id=s.id
      where s.tenant_id=p_tenant_id and s.customer_id=p_party_id and coalesce(s.status,'') not in('cancelled','void')
        and greatest(s.grand_total-coalesce(sp.paid,0)-coalesce(sr.returned,0),0)>0.005
        and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view')
      union all
      select 'loan'::text,l.id,l.loan_number,coalesce(l.disbursement_date,l.created_at::date),
        coalesce((select min(sc.due_date) from public.loan_schedule_v490 sc where sc.tenant_id=l.tenant_id and sc.loan_id=l.id and sc.status<>'waived'
          and (sc.principal_due+sc.interest_due+sc.penalty_due)-(sc.principal_paid+sc.interest_paid+sc.penalty_paid)>0.005),l.maturity_date),
        (l.principal_amount+l.interest_outstanding+l.penalty_outstanding)::numeric,l.total_paid::numeric,
        (l.principal_outstanding+l.interest_outstanding+l.penalty_outstanding)::numeric,l.status,l.location_id,bl.name,
        jsonb_build_object(
          'principal_outstanding',l.principal_outstanding,'interest_outstanding',l.interest_outstanding,
          'penalty_outstanding',l.penalty_outstanding,'interest_rate',l.interest_rate,'rate_type',l.rate_type,
          'maturity_date',l.maturity_date,'repayment_frequency',l.repayment_frequency,'repayment_term_count',l.repayment_term_count
        )
      from public.loan_accounts_v490 l join public.business_locations bl on bl.id=l.location_id
      where l.tenant_id=p_tenant_id and coalesce(l.direction,'given')='given' and l.client_id=p_party_id and l.status in('active','defaulted')
        and (l.principal_outstanding+l.interest_outstanding+l.penalty_outstanding)>0.005
        and private.erp_document_scope_allowed(p_tenant_id,l.location_id,p_location_id,'view')
    )
    select coalesce(jsonb_agg(jsonb_build_object(
      'source_type',source_type,'source_id',source_id,'reference',reference,'date',doc_date,'due_date',due_date,
      'total',total,'paid',paid,'balance',balance,'status',status,'location_id',location_id,'location_name',location_name,
      'overdue',due_date is not null and due_date<current_date,'extra',extra
    ) order by coalesce(due_date,doc_date),doc_date),'[]'::jsonb) into v_documents from docs;

    with payments as (
      select coalesce(sp.paid_at,sp.created_at) ts,'sale_payment'::text payment_type,sp.id,
        coalesce(dn.terminal_number,ln.local_number,s.sale_number) reference,sp.amount::numeric amount,sp.payment_method,
        null::text payment_number,o.location_id,l.name location_name
      from public.sale_payments sp join public.sales s on s.id=sp.sale_id
      left join public.document_origins o on o.tenant_id=s.tenant_id and o.entity_type='sale' and o.entity_id=s.id
      left join public.business_locations l on l.id=o.location_id
      left join public.location_document_numbers ln on ln.entity_type='sale' and ln.entity_id=s.id
      left join public.device_document_numbers dn on dn.entity_type='sale' and dn.entity_id=s.id
      where s.tenant_id=p_tenant_id and s.customer_id=p_party_id
        and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view')
      union all
      select lp.created_at,'loan_payment',lp.id,la.loan_number,lp.amount,lp.payment_method,lp.payment_number,lp.location_id,bl.name
      from public.loan_payments_v490 lp join public.loan_accounts_v490 la on la.id=lp.loan_id
      join public.business_locations bl on bl.id=lp.location_id
      where lp.tenant_id=p_tenant_id and coalesce(la.direction,'given')='given' and la.client_id=p_party_id and lp.status='posted'
        and private.erp_document_scope_allowed(p_tenant_id,lp.location_id,p_location_id,'view')
    )
    select coalesce(jsonb_agg(jsonb_build_object(
      'payment_type',payment_type,'payment_id',id,'reference',reference,'payment_number',payment_number,
      'date',ts::date,'amount',amount,'payment_method',payment_method,'location_id',location_id,'location_name',location_name
    ) order by ts desc),'[]'::jsonb) into v_payments from (select * from payments order by ts desc limit 100) p;

  elsif v_kind='supplier' then
    select jsonb_build_object(
      'party_id',s.id,'party_type','supplier','party_name',s.name,'tracking_code',coalesce(s.tracking_code,''),
      'phone',coalesce(s.phone,''),'email',coalesce(s.email,''),'tax_number',coalesce(s.tax_number,'')
    ) into v_party from public.suppliers s where s.tenant_id=p_tenant_id and s.id=p_party_id;
    if v_party is null then raise exception 'Supplier not found';end if;

    with purchase_paid as (
      select purchase_id,sum(amount)::numeric paid from public.purchase_payments group by purchase_id
    ), purchase_returned as (
      select purchase_id,sum(grand_total)::numeric returned from public.purchase_returns where credit_status<>'waived' group by purchase_id
    ), docs as (
      select 'purchase'::text source_type,p.id source_id,
        coalesce(dn.terminal_number,ln.local_number,p.purchase_number) reference,p.purchase_date doc_date,p.due_date,
        p.grand_total::numeric total,coalesce(pp.paid,0)::numeric paid,
        greatest(p.grand_total-coalesce(pp.paid,0)-coalesce(pr.returned,0),0)::numeric balance,
        coalesce(p.status,'') status,o.location_id,l.name location_name,
        jsonb_build_object('returned',coalesce(pr.returned,0),'purchase_number',p.purchase_number) extra
      from public.purchases p
      left join purchase_paid pp on pp.purchase_id=p.id left join purchase_returned pr on pr.purchase_id=p.id
      left join public.document_origins o on o.tenant_id=p.tenant_id and o.entity_type='purchase' and o.entity_id=p.id
      left join public.business_locations l on l.id=o.location_id
      left join public.location_document_numbers ln on ln.entity_type='purchase' and ln.entity_id=p.id
      left join public.device_document_numbers dn on dn.entity_type='purchase' and dn.entity_id=p.id
      where p.tenant_id=p_tenant_id and p.supplier_id=p_party_id and coalesce(p.status,'') not in('cancelled','void')
        and greatest(p.grand_total-coalesce(pp.paid,0)-coalesce(pr.returned,0),0)>0.005
        and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view')
      union all
      select 'purchase_invoice'::text,i.id,i.invoice_number,i.invoice_date,i.due_date,i.grand_total,i.paid_total,i.balance_due,
        i.status,i.location_id,bl.name,
        jsonb_build_object('supplier_invoice_number',coalesce(i.supplier_invoice_number,''),'purchase_order_id',i.purchase_order_id)
      from public.purchase_invoices_v484 i join public.business_locations bl on bl.id=i.location_id
      where i.tenant_id=p_tenant_id and i.supplier_id=p_party_id and i.status in('posted','part_paid') and i.balance_due>0.005
        and private.erp_document_scope_allowed(p_tenant_id,i.location_id,p_location_id,'view')
      union all
      select 'loan_taken'::text,l.id,l.loan_number,coalesce(l.disbursement_date,l.created_at::date),
        coalesce((select min(sc.due_date) from public.loan_schedule_v490 sc where sc.loan_id=l.id and sc.status<>'waived' and (sc.principal_due+sc.interest_due+sc.penalty_due)-(sc.principal_paid+sc.interest_paid+sc.penalty_paid)>0.005),l.maturity_date),
        l.principal_amount+l.interest_outstanding+l.penalty_outstanding,l.total_paid,
        l.principal_outstanding+l.interest_outstanding+l.penalty_outstanding,l.status,l.location_id,bl.name,
        jsonb_build_object('direction','taken','principal_outstanding',l.principal_outstanding,'interest_outstanding',l.interest_outstanding,'penalty_outstanding',l.penalty_outstanding,'interest_rate',l.interest_rate,'maturity_date',l.maturity_date)
      from public.loan_accounts_v490 l join public.business_locations bl on bl.id=l.location_id
      where l.tenant_id=p_tenant_id and l.direction='taken' and l.counterparty_type='supplier' and l.supplier_id=p_party_id and l.status in('active','defaulted')
        and (l.principal_outstanding+l.interest_outstanding+l.penalty_outstanding)>0.005
        and private.erp_document_scope_allowed(p_tenant_id,l.location_id,p_location_id,'view')
    )
    select coalesce(jsonb_agg(jsonb_build_object(
      'source_type',source_type,'source_id',source_id,'reference',reference,'date',doc_date,'due_date',due_date,
      'total',total,'paid',paid,'balance',balance,'status',status,'location_id',location_id,'location_name',location_name,
      'overdue',due_date is not null and due_date<current_date,'extra',extra
    ) order by coalesce(due_date,doc_date),doc_date),'[]'::jsonb) into v_documents from docs;

    select coalesce(sum(greatest(p.amount-coalesce(a.allocated,0),0)),0) into v_credit
    from public.supplier_payments_v484 p
    left join (
      select supplier_payment_id,sum(amount)::numeric allocated from public.supplier_payment_allocations_v484 group by supplier_payment_id
    ) a on a.supplier_payment_id=p.id
    where p.tenant_id=p_tenant_id and p.supplier_id=p_party_id and p.status='posted'
      and private.erp_document_scope_allowed(p_tenant_id,p.location_id,p_location_id,'view');

    with payments as (
      select coalesce(pp.paid_at,pp.created_at) ts,'purchase_payment'::text payment_type,pp.id,
        coalesce(dn.terminal_number,ln.local_number,p.purchase_number) reference,pp.amount::numeric amount,pp.payment_method,
        null::text payment_number,o.location_id,l.name location_name
      from public.purchase_payments pp join public.purchases p on p.id=pp.purchase_id
      left join public.document_origins o on o.tenant_id=p.tenant_id and o.entity_type='purchase' and o.entity_id=p.id
      left join public.business_locations l on l.id=o.location_id
      left join public.location_document_numbers ln on ln.entity_type='purchase' and ln.entity_id=p.id
      left join public.device_document_numbers dn on dn.entity_type='purchase' and dn.entity_id=p.id
      where p.tenant_id=p_tenant_id and p.supplier_id=p_party_id
        and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view')
      union all
      select sp.created_at,'supplier_payment',sp.id,sp.reference_number,sp.amount,sp.payment_method,sp.payment_number,sp.location_id,bl.name
      from public.supplier_payments_v484 sp join public.business_locations bl on bl.id=sp.location_id
      where sp.tenant_id=p_tenant_id and sp.supplier_id=p_party_id and sp.status='posted'
        and private.erp_document_scope_allowed(p_tenant_id,sp.location_id,p_location_id,'view')
      union all
      select lp.created_at,'loan_repayment',lp.id,la.loan_number,lp.amount,lp.payment_method,lp.payment_number,lp.location_id,bl.name
      from public.loan_payments_v490 lp join public.loan_accounts_v490 la on la.id=lp.loan_id join public.business_locations bl on bl.id=lp.location_id
      where lp.tenant_id=p_tenant_id and la.direction='taken' and la.counterparty_type='supplier' and la.supplier_id=p_party_id and lp.status='posted'
        and private.erp_document_scope_allowed(p_tenant_id,lp.location_id,p_location_id,'view')
    )
    select coalesce(jsonb_agg(jsonb_build_object(
      'payment_type',payment_type,'payment_id',id,'reference',coalesce(reference,''),'payment_number',payment_number,
      'date',ts::date,'amount',amount,'payment_method',payment_method,'location_id',location_id,'location_name',location_name
    ) order by ts desc),'[]'::jsonb) into v_payments from (select * from payments order by ts desc limit 100) p;
  else
    raise exception 'Party type must be customer or supplier';
  end if;

  return jsonb_build_object(
    'party',v_party,
    'documents',v_documents,
    'recent_payments',v_payments,
    'gross_outstanding',coalesce((select sum((x->>'balance')::numeric) from jsonb_array_elements(v_documents) x),0),
    'credit_balance',round(coalesce(v_credit,0),2),
    'net_outstanding',greatest(coalesce((select sum((x->>'balance')::numeric) from jsonb_array_elements(v_documents) x),0)-coalesce(v_credit,0),0),
    'overdue',coalesce((select sum((x->>'balance')::numeric) from jsonb_array_elements(v_documents) x where coalesce((x->>'overdue')::boolean,false)),0)
  );
end $$;


--
-- Name: payments_party_summary_v491(uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payments_party_summary_v491(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_query text DEFAULT ''::text, p_limit integer DEFAULT 500) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_receivables jsonb;
  v_payables jsonb;
  v_q text:='%'||lower(trim(coalesce(p_query,'')))||'%';
  v_limit int:=greatest(1,least(coalesce(p_limit,500),2000));
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if not private.erp_has_permission(p_tenant_id,'payments.view')
     and not private.erp_has_permission(p_tenant_id,'sales.manage')
     and not private.erp_has_permission(p_tenant_id,'purchases.manage')
     and not private.erp_user_is_owner(p_tenant_id) then
    raise exception 'Permission denied';
  end if;

  with sale_paid as (
    select sale_id,sum(amount)::numeric paid from public.sale_payments group by sale_id
  ), sale_returned as (
    select sale_id,sum(grand_total)::numeric returned
    from public.sales_returns where refund_status<>'waived' group by sale_id
  ), sale_docs as (
    select s.customer_id party_id,'sale'::text source_type,s.id source_id,
      coalesce(dn.terminal_number,ln.local_number,s.sale_number) reference,
      s.sale_date doc_date,s.due_date,
      s.grand_total::numeric total,coalesce(sp.paid,0)::numeric paid,
      greatest(s.grand_total-coalesce(sp.paid,0)-coalesce(sr.returned,0),0)::numeric balance,
      o.location_id,l.name location_name
    from public.sales s
    left join sale_paid sp on sp.sale_id=s.id
    left join sale_returned sr on sr.sale_id=s.id
    left join public.document_origins o on o.tenant_id=s.tenant_id and o.entity_type='sale' and o.entity_id=s.id
    left join public.business_locations l on l.id=o.location_id
    left join public.location_document_numbers ln on ln.entity_type='sale' and ln.entity_id=s.id
    left join public.device_document_numbers dn on dn.entity_type='sale' and dn.entity_id=s.id
    where s.tenant_id=p_tenant_id and coalesce(s.status,'') not in('cancelled','void')
      and greatest(s.grand_total-coalesce(sp.paid,0)-coalesce(sr.returned,0),0)>0.005
      and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view')
  ), loan_docs as (
    select l.client_id party_id,'loan'::text source_type,l.id source_id,l.loan_number reference,
      coalesce(l.disbursement_date,l.created_at::date) doc_date,
      coalesce((select min(s.due_date) from public.loan_schedule_v490 s
        where s.tenant_id=l.tenant_id and s.loan_id=l.id and s.status<>'waived'
          and (s.principal_due+s.interest_due+s.penalty_due)-(s.principal_paid+s.interest_paid+s.penalty_paid)>0.005),l.maturity_date) due_date,
      (l.principal_amount+l.interest_outstanding+l.penalty_outstanding)::numeric total,
      l.total_paid::numeric paid,
      (l.principal_outstanding+l.interest_outstanding+l.penalty_outstanding)::numeric balance,
      l.location_id,bl.name location_name
    from public.loan_accounts_v490 l
    join public.business_locations bl on bl.id=l.location_id
    where l.tenant_id=p_tenant_id and coalesce(l.direction,'given')='given' and l.counterparty_type='customer' and l.status in('active','defaulted')
      and (l.principal_outstanding+l.interest_outstanding+l.penalty_outstanding)>0.005
      and private.erp_document_scope_allowed(p_tenant_id,l.location_id,p_location_id,'view')
  ), customer_docs as (
    select * from sale_docs union all select * from loan_docs
  ), customer_rows as (
    select c.id party_id,'customer'::text party_type,c.name party_name,
      coalesce(c.tracking_code,'') tracking_code,coalesce(c.phone,'') phone,coalesce(c.email,'') email,
      round(sum(d.balance),2) balance,
      round(sum(case when d.source_type='sale' then d.balance else 0 end),2) sales_outstanding,
      round(sum(case when d.source_type='loan' then d.balance else 0 end),2) loan_outstanding,
      round(sum(case when d.due_date is not null and d.due_date<current_date then d.balance else 0 end),2) overdue,
      count(*)::int document_count,min(d.due_date) filter(where d.due_date>=current_date) next_due_date,
      max(d.doc_date) last_activity_date
    from customer_docs d join public.customers c on c.id=d.party_id and c.tenant_id=p_tenant_id
    where trim(coalesce(p_query,''))='' or lower(c.name) like v_q or lower(coalesce(c.tracking_code,'')) like v_q
      or lower(coalesce(c.phone,'')) like v_q or lower(coalesce(c.email,'')) like v_q
    group by c.id,c.name,c.tracking_code,c.phone,c.email
    order by sum(d.balance) desc,c.name
    limit v_limit
  )
  select coalesce(jsonb_agg(to_jsonb(r) order by r.balance desc,r.party_name),'[]'::jsonb)
  into v_receivables from customer_rows r;

  with purchase_paid as (
    select purchase_id,sum(amount)::numeric paid from public.purchase_payments group by purchase_id
  ), purchase_returned as (
    select purchase_id,sum(grand_total)::numeric returned
    from public.purchase_returns where credit_status<>'waived' group by purchase_id
  ), legacy_docs as (
    select p.supplier_id party_id,'purchase'::text source_type,p.id source_id,
      coalesce(dn.terminal_number,ln.local_number,p.purchase_number) reference,
      p.purchase_date doc_date,p.due_date,p.grand_total::numeric total,coalesce(pp.paid,0)::numeric paid,
      greatest(p.grand_total-coalesce(pp.paid,0)-coalesce(pr.returned,0),0)::numeric balance,
      o.location_id,l.name location_name
    from public.purchases p
    left join purchase_paid pp on pp.purchase_id=p.id
    left join purchase_returned pr on pr.purchase_id=p.id
    left join public.document_origins o on o.tenant_id=p.tenant_id and o.entity_type='purchase' and o.entity_id=p.id
    left join public.business_locations l on l.id=o.location_id
    left join public.location_document_numbers ln on ln.entity_type='purchase' and ln.entity_id=p.id
    left join public.device_document_numbers dn on dn.entity_type='purchase' and dn.entity_id=p.id
    where p.tenant_id=p_tenant_id and coalesce(p.status,'') not in('cancelled','void')
      and greatest(p.grand_total-coalesce(pp.paid,0)-coalesce(pr.returned,0),0)>0.005
      and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view')
  ), v2_docs as (
    select i.supplier_id party_id,'purchase_invoice'::text source_type,i.id source_id,
      i.invoice_number reference,i.invoice_date doc_date,i.due_date,i.grand_total::numeric total,
      i.paid_total::numeric paid,i.balance_due::numeric balance,i.location_id,l.name location_name
    from public.purchase_invoices_v484 i join public.business_locations l on l.id=i.location_id
    where i.tenant_id=p_tenant_id and i.status in('posted','part_paid') and i.balance_due>0.005
      and private.erp_document_scope_allowed(p_tenant_id,i.location_id,p_location_id,'view')
  ), taken_loan_docs as (
    select l.supplier_id party_id,'loan_taken'::text source_type,l.id source_id,l.loan_number reference,
      coalesce(l.disbursement_date,l.created_at::date) doc_date,
      coalesce((select min(sc.due_date) from public.loan_schedule_v490 sc where sc.loan_id=l.id and sc.status<>'waived' and (sc.principal_due+sc.interest_due+sc.penalty_due)-(sc.principal_paid+sc.interest_paid+sc.penalty_paid)>0.005),l.maturity_date) due_date,
      (l.principal_amount+l.interest_outstanding+l.penalty_outstanding)::numeric total,l.total_paid::numeric paid,
      (l.principal_outstanding+l.interest_outstanding+l.penalty_outstanding)::numeric balance,l.location_id,bl.name location_name
    from public.loan_accounts_v490 l join public.business_locations bl on bl.id=l.location_id
    where l.tenant_id=p_tenant_id and l.direction='taken' and l.counterparty_type='supplier' and l.supplier_id is not null and l.status in('active','defaulted')
      and (l.principal_outstanding+l.interest_outstanding+l.penalty_outstanding)>0.005
      and private.erp_document_scope_allowed(p_tenant_id,l.location_id,p_location_id,'view')
  ), supplier_docs as (
    select * from legacy_docs union all select * from v2_docs union all select * from taken_loan_docs
  ), supplier_credits as (
    select p.supplier_id,
      round(sum(greatest(p.amount-coalesce(a.allocated,0),0)),2)::numeric credit_balance
    from public.supplier_payments_v484 p
    left join (
      select supplier_payment_id,sum(amount)::numeric allocated
      from public.supplier_payment_allocations_v484 group by supplier_payment_id
    ) a on a.supplier_payment_id=p.id
    where p.tenant_id=p_tenant_id and p.status='posted'
      and private.erp_document_scope_allowed(p_tenant_id,p.location_id,p_location_id,'view')
    group by p.supplier_id
  ), supplier_rows as (
    select s.id party_id,'supplier'::text party_type,s.name party_name,
      coalesce(s.tracking_code,'') tracking_code,coalesce(s.phone,'') phone,coalesce(s.email,'') email,
      round(greatest(sum(d.balance)-coalesce(sc.credit_balance,0),0),2) balance,
      round(sum(case when d.source_type='purchase' then d.balance else 0 end),2) purchase_outstanding,
      round(sum(case when d.source_type='purchase_invoice' then d.balance else 0 end),2) invoice_outstanding,
      round(sum(case when d.source_type='loan_taken' then d.balance else 0 end),2) loan_outstanding,
      round(coalesce(sc.credit_balance,0),2) credit_balance,
      round(sum(case when d.due_date is not null and d.due_date<current_date then d.balance else 0 end),2) overdue,
      count(*)::int document_count,min(d.due_date) filter(where d.due_date>=current_date) next_due_date,
      max(d.doc_date) last_activity_date
    from supplier_docs d join public.suppliers s on s.id=d.party_id and s.tenant_id=p_tenant_id
    left join supplier_credits sc on sc.supplier_id=s.id
    where trim(coalesce(p_query,''))='' or lower(s.name) like v_q or lower(coalesce(s.tracking_code,'')) like v_q
      or lower(coalesce(s.phone,'')) like v_q or lower(coalesce(s.email,'')) like v_q
    group by s.id,s.name,s.tracking_code,s.phone,s.email,sc.credit_balance
    having greatest(sum(d.balance)-coalesce(sc.credit_balance,0),0)>0.005 or coalesce(sc.credit_balance,0)>0.005
    order by greatest(sum(d.balance)-coalesce(sc.credit_balance,0),0) desc,s.name
    limit v_limit
  )
  select coalesce(jsonb_agg(to_jsonb(r) order by r.balance desc,r.party_name),'[]'::jsonb)
  into v_payables from supplier_rows r;

  return jsonb_build_object(
    'receivables',v_receivables,
    'payables',v_payables,
    'totals',jsonb_build_object(
      'receivable',coalesce((select sum((x->>'balance')::numeric) from jsonb_array_elements(v_receivables) x),0),
      'payable',coalesce((select sum((x->>'balance')::numeric) from jsonb_array_elements(v_payables) x),0),
      'customer_count',jsonb_array_length(v_receivables),
      'supplier_count',jsonb_array_length(v_payables)
    )
  );
end $$;


--
-- Name: payments_pending_list(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payments_pending_list(p_tenant_id uuid, p_limit integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_rec jsonb; v_pay jsonb; begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  if not private.erp_has_permission(p_tenant_id,'payments.view') and not private.erp_has_permission(p_tenant_id,'sales.manage') and not private.erp_has_permission(p_tenant_id,'purchases.manage') then raise exception 'Permission denied'; end if;
  select coalesce(jsonb_agg(x order by (x->>'date')::date desc),'[]'::jsonb) into v_rec from (
    select jsonb_build_object('id',s.id,'type','receivable','reference',s.sale_number,'party_id',s.customer_id,'party_name',c.name,'date',s.sale_date,'due_date',s.due_date,'total',s.grand_total,'paid',coalesce((select sum(sp.amount) from public.sale_payments sp where sp.sale_id=s.id),0),'balance',s.grand_total-coalesce((select sum(sp.amount) from public.sale_payments sp where sp.sale_id=s.id),0)) x
    from public.sales s join public.customers c on c.id=s.customer_id where s.tenant_id=p_tenant_id and coalesce(s.status,'') not in ('cancelled','void') and s.grand_total-coalesce((select sum(sp.amount) from public.sale_payments sp where sp.sale_id=s.id),0) > 0.005 limit greatest(1,least(coalesce(p_limit,300),1000))
  ) q;
  select coalesce(jsonb_agg(x order by (x->>'date')::date desc),'[]'::jsonb) into v_pay from (
    select jsonb_build_object('id',p.id,'type','payable','reference',p.purchase_number,'party_id',p.supplier_id,'party_name',s.name,'date',p.purchase_date,'due_date',p.due_date,'total',p.grand_total,'paid',coalesce((select sum(pp.amount) from public.purchase_payments pp where pp.purchase_id=p.id),0),'balance',p.grand_total-coalesce((select sum(pp.amount) from public.purchase_payments pp where pp.purchase_id=p.id),0)) x
    from public.purchases p join public.suppliers s on s.id=p.supplier_id where p.tenant_id=p_tenant_id and coalesce(p.status,'') not in ('cancelled','void') and p.grand_total-coalesce((select sum(pp.amount) from public.purchase_payments pp where pp.purchase_id=p.id),0) > 0.005 limit greatest(1,least(coalesce(p_limit,300),1000))
  ) q;
  return jsonb_build_object('receivables',coalesce(v_rec,'[]'::jsonb),'payables',coalesce(v_pay,'[]'::jsonb));
end $$;


--
-- Name: payments_pending_list_v32(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payments_pending_list_v32(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_rec jsonb;v_pay jsonb;v_lim int:=greatest(1,least(coalesce(p_limit,300),1000));begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if not private.erp_has_permission(p_tenant_id,'payments.view') and not private.erp_has_permission(p_tenant_id,'sales.manage') and not private.erp_has_permission(p_tenant_id,'purchases.manage') and not private.erp_user_is_owner(p_tenant_id) then raise exception 'Permission denied';end if;
  select coalesce(jsonb_agg(x order by (x->>'date')::date desc),'[]'::jsonb) into v_rec from (
    select jsonb_build_object('id',s.id,'type','receivable','reference',coalesce(dn.terminal_number,ln.local_number,s.sale_number),'party_id',s.customer_id,'party_name',c.name,'date',s.sale_date,'due_date',s.due_date,'total',s.grand_total,'paid',coalesce(py.paid,0),'balance',s.grand_total-coalesce(py.paid,0),'location_id',o.location_id,'location_name',l.name) x
    from public.sales s join public.customers c on c.id=s.customer_id left join (select sale_id,sum(amount) paid from public.sale_payments group by sale_id)py on py.sale_id=s.id
    left join public.document_origins o on o.entity_type='sale' and o.entity_id=s.id left join public.business_locations l on l.id=o.location_id
    left join public.location_document_numbers ln on ln.entity_type='sale' and ln.entity_id=s.id left join public.device_document_numbers dn on dn.entity_type='sale' and dn.entity_id=s.id
    where s.tenant_id=p_tenant_id and coalesce(s.status,'') not in ('cancelled','void') and s.grand_total-coalesce(py.paid,0)>0.005 and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view') limit v_lim
  )q;
  select coalesce(jsonb_agg(x order by (x->>'date')::date desc),'[]'::jsonb) into v_pay from (
    select jsonb_build_object('id',p.id,'type','payable','reference',coalesce(dn.terminal_number,ln.local_number,p.purchase_number),'party_id',p.supplier_id,'party_name',s.name,'date',p.purchase_date,'due_date',p.due_date,'total',p.grand_total,'paid',coalesce(py.paid,0),'balance',p.grand_total-coalesce(py.paid,0),'location_id',o.location_id,'location_name',l.name) x
    from public.purchases p join public.suppliers s on s.id=p.supplier_id left join (select purchase_id,sum(amount) paid from public.purchase_payments group by purchase_id)py on py.purchase_id=p.id
    left join public.document_origins o on o.entity_type='purchase' and o.entity_id=p.id left join public.business_locations l on l.id=o.location_id
    left join public.location_document_numbers ln on ln.entity_type='purchase' and ln.entity_id=p.id left join public.device_document_numbers dn on dn.entity_type='purchase' and dn.entity_id=p.id
    where p.tenant_id=p_tenant_id and coalesce(p.status,'') not in ('cancelled','void') and p.grand_total-coalesce(py.paid,0)>0.005 and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view') limit v_lim
  )q;
  return jsonb_build_object('receivables',v_rec,'payables',v_pay);
end $$;


--
-- Name: payments_pending_list_v4(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payments_pending_list_v4(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_rec jsonb;v_pay jsonb;v_lim int:=greatest(1,least(coalesce(p_limit,300),1000));begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if not private.erp_has_permission(p_tenant_id,'payments.view') and not private.erp_has_permission(p_tenant_id,'sales.manage') and not private.erp_has_permission(p_tenant_id,'purchases.manage') and not private.erp_user_is_owner(p_tenant_id) then raise exception 'Permission denied';end if;

  select coalesce(jsonb_agg(x order by (x->>'date')::date desc),'[]'::jsonb) into v_rec from (
    select jsonb_build_object(
      'id',s.id,'type','receivable','reference',coalesce(dn.terminal_number,ln.local_number,s.sale_number),
      'party_id',s.customer_id,'party_name',c.name,'date',s.sale_date,'due_date',s.due_date,'total',s.grand_total,
      'paid',coalesce(py.paid,0),'returned',coalesce(rt.returned,0),
      'balance',greatest(s.grand_total-coalesce(py.paid,0)-coalesce(rt.returned,0),0),
      'location_id',o.location_id,'location_name',l.name
    ) x
    from public.sales s
    join public.customers c on c.id=s.customer_id
    left join (select sale_id,sum(amount) paid from public.sale_payments group by sale_id) py on py.sale_id=s.id
    left join (select sale_id,sum(grand_total) returned from public.sales_returns where refund_status<>'waived' group by sale_id) rt on rt.sale_id=s.id
    left join public.document_origins o on o.entity_type='sale' and o.entity_id=s.id
    left join public.business_locations l on l.id=o.location_id
    left join public.location_document_numbers ln on ln.entity_type='sale' and ln.entity_id=s.id
    left join public.device_document_numbers dn on dn.entity_type='sale' and dn.entity_id=s.id
    where s.tenant_id=p_tenant_id and coalesce(s.status,'') not in('cancelled','void')
      and greatest(s.grand_total-coalesce(py.paid,0)-coalesce(rt.returned,0),0)>0.005
      and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view')
    order by s.sale_date desc limit v_lim
  ) q;

  select coalesce(jsonb_agg(x order by (x->>'date')::date desc),'[]'::jsonb) into v_pay from (
    select jsonb_build_object(
      'id',p.id,'type','payable','reference',coalesce(dn.terminal_number,ln.local_number,p.purchase_number),
      'party_id',p.supplier_id,'party_name',s.name,'date',p.purchase_date,'due_date',p.due_date,'total',p.grand_total,
      'paid',coalesce(py.paid,0),'returned',coalesce(rt.returned,0),
      'balance',greatest(p.grand_total-coalesce(py.paid,0)-coalesce(rt.returned,0),0),
      'location_id',o.location_id,'location_name',l.name
    ) x
    from public.purchases p
    join public.suppliers s on s.id=p.supplier_id
    left join (select purchase_id,sum(amount) paid from public.purchase_payments group by purchase_id) py on py.purchase_id=p.id
    left join (select purchase_id,sum(grand_total) returned from public.purchase_returns where credit_status<>'waived' group by purchase_id) rt on rt.purchase_id=p.id
    left join public.document_origins o on o.entity_type='purchase' and o.entity_id=p.id
    left join public.business_locations l on l.id=o.location_id
    left join public.location_document_numbers ln on ln.entity_type='purchase' and ln.entity_id=p.id
    left join public.device_document_numbers dn on dn.entity_type='purchase' and dn.entity_id=p.id
    where p.tenant_id=p_tenant_id and coalesce(p.status,'') not in('cancelled','void')
      and greatest(p.grand_total-coalesce(py.paid,0)-coalesce(rt.returned,0),0)>0.005
      and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view')
    order by p.purchase_date desc limit v_lim
  ) q;

  return jsonb_build_object('receivables',v_rec,'payables',v_pay);
end $$;


--
-- Name: platform_admin_v2_grant(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_admin_v2_grant(p_email text, p_role_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'auth', 'pg_temp'
    AS $$
declare v_user uuid;
begin
  if not private.platform_v2_has_role('super_admin') then raise exception 'Super Admin access required'; end if;
  if p_role_key not in ('super_admin','support_admin','billing_admin','sales_admin','technical_admin','auditor') then raise exception 'Invalid platform role'; end if;
  select id into v_user from auth.users where lower(email)=lower(trim(p_email)) limit 1;
  if v_user is null then raise exception 'No authenticated user exists with this email'; end if;
  insert into private.platform_admin_role_assignments(user_id,role_key,active,created_by) values(v_user,p_role_key,true,auth.uid())
  on conflict(user_id) do update set role_key=excluded.role_key,active=true,updated_at=now();
  perform private.platform_audit_write('platform_admin.grant','platform_admin',v_user::text,null,jsonb_build_object('email',lower(trim(p_email)),'role_key',p_role_key));
end $$;


--
-- Name: platform_admin_v2_revoke(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_admin_v2_revoke(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if not private.platform_v2_has_role('super_admin') then raise exception 'Super Admin access required'; end if;
  if p_user_id=auth.uid() then raise exception 'You cannot revoke your own platform access'; end if;
  update private.platform_admin_role_assignments set active=false,updated_at=now() where user_id=p_user_id;
  perform private.platform_audit_write('platform_admin.revoke','platform_admin',p_user_id::text,null,'{}'::jsonb);
end $$;


--
-- Name: platform_admin_v3_grant(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_admin_v3_grant(p_username text, p_role_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_user uuid;begin
  if not private.platform_v2_has_role('super_admin') then raise exception 'Super Admin access required'; end if;
  if p_role_key not in ('super_admin','support_admin','billing_admin','sales_admin','technical_admin','auditor') then raise exception 'Invalid platform role'; end if;
  select user_id into v_user from public.user_login_names where username=lower(trim(p_username));
  if v_user is null then raise exception 'No Flexi ERP user exists with this username';end if;
  insert into private.platform_admin_role_assignments(user_id,role_key,active,created_by) values(v_user,p_role_key,true,auth.uid())
  on conflict(user_id) do update set role_key=excluded.role_key,active=true,updated_at=now();
  perform private.platform_audit_write('platform_admin.grant','platform_admin',v_user::text,null,jsonb_build_object('username',lower(trim(p_username)),'role_key',p_role_key));
end $$;


--
-- Name: platform_admins_v2_list(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_admins_v2_list() RETURNS TABLE(user_id uuid, email text, role_key text, active boolean, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'auth', 'pg_temp'
    AS $$
begin
  if not private.platform_v2_has_role('super_admin') then raise exception 'Super Admin access required'; end if;
  return query select a.user_id,u.email::text,a.role_key,a.active,a.created_at from private.platform_admin_role_assignments a join auth.users u on u.id=a.user_id order by u.email;
end $$;


--
-- Name: platform_admins_v3_list(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_admins_v3_list() RETURNS TABLE(user_id uuid, username text, email text, role_key text, active boolean, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'auth', 'pg_temp'
    AS $$ begin
  if not private.platform_v2_has_role('super_admin') then raise exception 'Super Admin access required'; end if;
  return query select a.user_id,coalesce(n.username,''),u.email::text,a.role_key,a.active,a.created_at
  from private.platform_admin_role_assignments a join auth.users u on u.id=a.user_id left join public.user_login_names n on n.user_id=a.user_id
  order by coalesce(n.username,u.email::text);
end $$;


--
-- Name: platform_app_error_logs_list(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_app_error_logs_list(p_limit integer DEFAULT 300) RETURNS SETOF public.app_error_logs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.platform_v2_is_admin() then raise exception 'Platform admin required'; end if;
  return query select * from public.app_error_logs order by created_at desc limit greatest(1,least(coalesce(p_limit,300),2000));
end $$;


--
-- Name: platform_app_release_save_v4(uuid, text, text, text, integer, text, boolean, boolean, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_app_release_save_v4(p_id uuid, p_app_key text, p_platform text, p_version text, p_build_number integer, p_status text, p_minimum_supported boolean, p_mandatory boolean, p_release_notes text, p_download_url text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_id uuid; begin
  if not private.platform_v2_has_role('super_admin') and not private.platform_v2_has_role('technical_admin') then raise exception 'Technical admin required';end if;
  if p_app_key not in('client','pos','admin') then raise exception 'Invalid app';end if;
  if trim(coalesce(p_platform,''))='' or trim(coalesce(p_version,''))='' then raise exception 'Platform and version required';end if;
  if p_minimum_supported then update public.platform_app_releases set minimum_supported=false where app_key=p_app_key and platform=p_platform;end if;
  if p_id is null then
    insert into public.platform_app_releases(app_key,platform,version,build_number,status,minimum_supported,mandatory,release_notes,download_url)
    values(p_app_key,trim(p_platform),trim(p_version),greatest(coalesce(p_build_number,1),1),case when p_status in('beta','stable','deprecated','blocked') then p_status else 'stable' end,coalesce(p_minimum_supported,false),coalesce(p_mandatory,false),nullif(trim(coalesce(p_release_notes,'')),''),nullif(trim(coalesce(p_download_url,'')),'')) returning id into v_id;
  else
    update public.platform_app_releases set app_key=p_app_key,platform=trim(p_platform),version=trim(p_version),build_number=greatest(coalesce(p_build_number,1),1),status=case when p_status in('beta','stable','deprecated','blocked') then p_status else 'stable' end,minimum_supported=coalesce(p_minimum_supported,false),mandatory=coalesce(p_mandatory,false),release_notes=nullif(trim(coalesce(p_release_notes,'')),''),download_url=nullif(trim(coalesce(p_download_url,'')),'') where id=p_id returning id into v_id;
  end if;
  if v_id is null then raise exception 'Release not found';end if;
  return v_id;
end $$;


--
-- Name: platform_app_releases; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.platform_app_releases (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    app_key text NOT NULL,
    platform text NOT NULL,
    version text NOT NULL,
    build_number integer DEFAULT 1 NOT NULL,
    status text DEFAULT 'stable'::text NOT NULL,
    minimum_supported boolean DEFAULT false NOT NULL,
    mandatory boolean DEFAULT false NOT NULL,
    release_notes text,
    download_url text,
    released_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT platform_app_releases_app_key_check CHECK ((app_key = ANY (ARRAY['client'::text, 'pos'::text, 'admin'::text]))),
    CONSTRAINT platform_app_releases_status_check CHECK ((status = ANY (ARRAY['beta'::text, 'stable'::text, 'deprecated'::text, 'blocked'::text])))
);


--
-- Name: platform_app_releases_list_v4(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_app_releases_list_v4() RETURNS SETOF public.platform_app_releases
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.platform_v2_is_admin() then raise exception 'Platform admin required';end if;
  return query select * from public.platform_app_releases order by app_key,platform,released_at desc;
end $$;


--
-- Name: platform_apply_template_settings(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_apply_template_settings(p_tenant_id uuid, p_template_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_settings jsonb;
begin
  if not private.platform_v2_is_admin() then raise exception 'Platform admin access required'; end if;
  select settings into v_settings from public.business_templates where key=p_template_key and is_active;
  if v_settings is null then raise exception 'Template not found'; end if;
  insert into public.tenant_settings_v2(tenant_id,settings,updated_by) values(p_tenant_id,v_settings,auth.uid())
  on conflict(tenant_id) do update set settings=public.tenant_settings_v2.settings || excluded.settings,updated_by=auth.uid(),updated_at=now();
  perform private.platform_audit_write('template.apply_settings','tenant',p_tenant_id::text,p_tenant_id,jsonb_build_object('template_key',p_template_key));
end $$;


--
-- Name: platform_audit_list(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_audit_list(p_limit integer DEFAULT 200) RETURNS TABLE(id uuid, created_at timestamp with time zone, actor_email text, action text, entity_type text, entity_id text, tenant_name text, details jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'auth', 'pg_temp'
    AS $$
begin
  if not private.platform_v2_is_admin() then raise exception 'Platform admin access required'; end if;
  return query select a.id,a.created_at,coalesce(u.email::text,''),a.action,a.entity_type,a.entity_id,t.name,a.details
  from private.platform_audit_log a left join auth.users u on u.id=a.actor_user_id left join public.tenants t on t.id=a.tenant_id
  order by a.created_at desc limit least(greatest(coalesce(p_limit,200),1),1000);
end $$;


--
-- Name: platform_business_archive_v41(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_business_archive_v41(p_tenant_id uuid, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.platform_v2_has_role('super_admin') then raise exception 'Super Admin required';end if;
  if not exists(select 1 from public.tenants where id=p_tenant_id) then raise exception 'Business not found';end if;
  update public.tenants set status='inactive' where id=p_tenant_id;
  update public.business_devices set status='revoked',activation_hash=null,activation_expires_at=null,updated_at=now() where tenant_id=p_tenant_id and status<>'revoked';
  perform private.platform_audit_write('business.archive','tenant',p_tenant_id::text,p_tenant_id,jsonb_build_object('reason',nullif(trim(coalesce(p_reason,'')),'')));
end $$;


--
-- Name: platform_business_delete_v471(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_business_delete_v471(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v_name text;begin
  if coalesce(auth.role(),'')<>'service_role' then raise exception 'Service role required';end if;
  select name into v_name from public.tenants where id=p_tenant_id for update;
  if v_name is null then raise exception 'Business not found';end if;
  delete from public.tenants where id=p_tenant_id;
  if found then return jsonb_build_object('success',true,'tenant_id',p_tenant_id,'business_name',v_name);end if;
  raise exception 'Business delete did not complete';
end $$;


--
-- Name: platform_business_devices_list(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_business_devices_list(p_tenant_id uuid) RETURNS TABLE(id uuid, tenant_id uuid, location_id uuid, location_name text, device_code text, tracking_code text, name text, app_type text, platform_hint text, status text, allowed_modules text[], invoice_prefix text, activated_at timestamp with time zone, last_seen_at timestamp with time zone, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.platform_v2_is_admin() then raise exception 'Platform admin required';end if;
  return query select d.id,d.tenant_id,d.location_id,l.name,d.device_code,d.tracking_code,d.name,d.app_type,d.platform_hint,d.status,d.allowed_modules,d.invoice_prefix,d.activated_at,d.last_seen_at,d.created_at
  from public.business_devices d join public.business_locations l on l.id=d.location_id where d.tenant_id=p_tenant_id order by d.created_at desc;
end $$;


--
-- Name: platform_business_identity(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_business_identity(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ declare r jsonb; begin
  if not public.current_user_is_platform_admin() then raise exception 'Platform admin required'; end if;
  select jsonb_build_object('tenant_id',t.id,'business_code',t.business_code,'name',t.name,'slug',t.slug,'status',t.status)
  into r from public.tenants t where t.id=p_tenant_id;
  return coalesce(r,'{}'::jsonb);
end $$;


--
-- Name: platform_business_location_save(uuid, uuid, uuid, text, text, text, text, text, text, text, text, text, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_business_location_save(p_tenant_id uuid, p_location_id uuid, p_parent_location_id uuid, p_location_code text, p_name text, p_location_type text, p_phone text, p_email text, p_gstin text, p_address_line1 text, p_address_line2 text, p_city text, p_state text, p_postal_code text, p_country text, p_invoice_prefix text, p_active boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_id uuid; begin
  if not private.platform_v2_has_role('super_admin') and not private.platform_v2_has_role('support_admin') then raise exception 'Platform admin required'; end if;
  if trim(coalesce(p_name,''))='' then raise exception 'Location name required'; end if;
  if p_location_id is null then
    insert into public.business_locations(tenant_id,parent_location_id,location_code,name,location_type,phone,email,gstin,address_line1,address_line2,city,state,postal_code,country,invoice_prefix,active)
    values(p_tenant_id,p_parent_location_id,upper(trim(p_location_code)),trim(p_name),p_location_type,nullif(trim(p_phone),''),nullif(trim(p_email),''),nullif(trim(p_gstin),''),nullif(trim(p_address_line1),''),nullif(trim(p_address_line2),''),nullif(trim(p_city),''),nullif(trim(p_state),''),nullif(trim(p_postal_code),''),coalesce(nullif(trim(p_country),''),'India'),nullif(trim(p_invoice_prefix),''),coalesce(p_active,true))
    returning id into v_id;
  else
    update public.business_locations set parent_location_id=p_parent_location_id,location_code=upper(trim(p_location_code)),name=trim(p_name),location_type=p_location_type,phone=nullif(trim(p_phone),''),email=nullif(trim(p_email),''),gstin=nullif(trim(p_gstin),''),address_line1=nullif(trim(p_address_line1),''),address_line2=nullif(trim(p_address_line2),''),city=nullif(trim(p_city),''),state=nullif(trim(p_state),''),postal_code=nullif(trim(p_postal_code),''),country=coalesce(nullif(trim(p_country),''),'India'),invoice_prefix=nullif(trim(p_invoice_prefix),''),active=coalesce(p_active,true),updated_at=now()
    where id=p_location_id and tenant_id=p_tenant_id returning id into v_id;
    if v_id is null then raise exception 'Location not found'; end if;
  end if;
  perform private.platform_audit_write('location.save','business_location',v_id::text,p_tenant_id,jsonb_build_object('name',p_name,'code',p_location_code));
  return v_id;
end $$;


--
-- Name: platform_business_location_save_v42(uuid, uuid, uuid, text, text, text, text, integer, text, text, text, text, text, text, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_business_location_save_v42(p_tenant_id uuid, p_location_id uuid, p_parent_location_id uuid, p_location_code text, p_name text, p_location_type text, p_hierarchy_role text, p_sort_order integer, p_phone text, p_email text, p_gstin text, p_address_line1 text, p_address_line2 text, p_city text, p_state text, p_postal_code text, p_country text, p_invoice_prefix text, p_active boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_id uuid;v_role text:=lower(coalesce(nullif(trim(p_hierarchy_role),''),'child_store'));v_parent uuid:=p_parent_location_id;v_main uuid;
begin
  if not private.platform_v2_has_role('super_admin') and not private.platform_v2_has_role('support_admin') then raise exception 'Platform admin required'; end if;
  if nullif(trim(p_location_code),'') is null then raise exception 'Location code is required'; end if;
  if nullif(trim(p_name),'') is null then raise exception 'Location name is required'; end if;
  if v_role not in('main_store','child_store','warehouse','operational') then raise exception 'Invalid location role'; end if;
  if p_location_id is not null and exists(select 1 from public.business_locations where id=p_location_id and tenant_id=p_tenant_id and hierarchy_role='main_store') and v_role<>'main_store' then raise exception 'MAIN Store role cannot be changed'; end if;
  if v_role='main_store' then
    if exists(select 1 from public.business_locations where tenant_id=p_tenant_id and hierarchy_role='main_store' and id is distinct from p_location_id) then raise exception 'This business already has a MAIN Store'; end if;
    if not coalesce(p_active,true) then raise exception 'MAIN Store cannot be deactivated'; end if;
    v_parent:=null;
  else
    v_main:=private.v500_ensure_main_location(p_tenant_id);v_parent:=coalesce(v_parent,v_main);
    if not exists(select 1 from public.business_locations l where l.id=v_parent and l.tenant_id=p_tenant_id and l.active) then raise exception 'Parent location must be an active location in the same business'; end if;
  end if;
  v_id:=public.platform_business_location_save(p_tenant_id,p_location_id,v_parent,upper(trim(p_location_code)),trim(p_name),p_location_type,p_phone,p_email,p_gstin,p_address_line1,p_address_line2,p_city,p_state,p_postal_code,p_country,coalesce(nullif(upper(trim(coalesce(p_invoice_prefix,''))),''),upper(trim(p_location_code))),p_active);
  update public.business_locations set hierarchy_role=v_role,sort_order=case when v_role='main_store' then 0 else coalesce(p_sort_order,100) end,parent_location_id=case when v_role='main_store' then null else v_parent end,updated_at=now() where id=v_id and tenant_id=p_tenant_id;
  return v_id;
end $$;


--
-- Name: platform_business_locations_list(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_business_locations_list(p_tenant_id uuid) RETURNS SETOF public.business_locations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.platform_v2_is_admin() then raise exception 'Platform admin required'; end if;
  return query select * from public.business_locations where tenant_id=p_tenant_id order by active desc,name;
end $$;


--
-- Name: platform_business_prepare_delete_v41(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_business_prepare_delete_v41(p_tenant_id uuid, p_confirm_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_tenant record;v_member record;v_children bigint;begin
  if not private.platform_v2_has_role('super_admin') then raise exception 'Super Admin required';end if;
  select id,name,business_code,status into v_tenant from public.tenants where id=p_tenant_id;
  if v_tenant.id is null then raise exception 'Business not found';end if;
  if upper(trim(coalesce(p_confirm_code,'')))<>upper(coalesce(v_tenant.business_code,'')) then
    raise exception 'Business code confirmation does not match';
  end if;
  select division_id,member_type into v_member from public.business_division_members where tenant_id=p_tenant_id;
  if v_member.member_type='main' then
    select count(*) into v_children from public.business_division_members
    where division_id=v_member.division_id and tenant_id<>p_tenant_id;
    if coalesce(v_children,0)>0 then
      raise exception 'Move or remove child businesses from this division before permanently deleting the main business';
    end if;
  end if;
  perform private.platform_audit_write(
    'business.permanent_delete_requested','tenant',p_tenant_id::text,p_tenant_id,
    jsonb_build_object('name',v_tenant.name,'business_code',v_tenant.business_code)
  );
  return jsonb_build_object(
    'tenant_id',v_tenant.id,'name',v_tenant.name,'business_code',v_tenant.business_code,
    'status',v_tenant.status,'division_id',v_member.division_id,'division_role',v_member.member_type
  );
end $$;


--
-- Name: platform_create_business(text, text, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_create_business(p_name text, p_slug text, p_business_type text, p_module_keys text[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_tenant_id uuid;v_slug text;
begin
  if not private.is_platform_admin() then raise exception 'Access denied' using errcode='42501'; end if;
  if nullif(trim(p_name),'') is null then raise exception 'Business name is required'; end if;
  v_slug:=lower(trim(p_slug));if nullif(v_slug,'') is null then raise exception 'Business slug is required'; end if;
  if v_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' then raise exception 'Slug may contain only lowercase letters, numbers and hyphens'; end if;
  if exists(select 1 from public.tenants t where t.slug=v_slug) then raise exception 'A business with this slug already exists'; end if;
  if exists(select 1 from unnest(coalesce(p_module_keys,array[]::text[])) requested(module_key) left join public.modules m on m.key=requested.module_key where m.key is null) then raise exception 'One or more selected modules do not exist'; end if;
  insert into public.tenants(name,slug,business_type,status) values(trim(p_name),v_slug,nullif(trim(p_business_type),''),'active') returning id into v_tenant_id;
  insert into public.tenant_settings(tenant_id,currency_code,timezone,locale) values(v_tenant_id,'INR','Asia/Kolkata','en_IN');
  insert into public.tenant_modules(tenant_id,module_key,enabled) select v_tenant_id,m.key,true from public.modules m where m.key='dashboard' or m.key=any(coalesce(p_module_keys,array[]::text[])) on conflict(tenant_id,module_key) do update set enabled=true;
  perform private.seed_default_roles(v_tenant_id);perform private.v500_ensure_main_location(v_tenant_id);return v_tenant_id;
end $_$;


--
-- Name: platform_current_admin_context(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_current_admin_context() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'auth', 'pg_temp'
    AS $$
declare v_role text; v_legacy boolean;
begin
  v_legacy := coalesce(public.current_user_is_platform_admin(), false);
  if auth.uid() is null then return jsonb_build_object('is_admin',false); end if;

  if v_legacy and not exists(select 1 from private.platform_admin_role_assignments where user_id=auth.uid()) then
    insert into private.platform_admin_role_assignments(user_id,role_key,active,created_by)
    values(auth.uid(),'super_admin',true,auth.uid())
    on conflict(user_id) do nothing;
  end if;

  select role_key into v_role from private.platform_admin_role_assignments where user_id=auth.uid() and active;
  return jsonb_build_object('is_admin',v_legacy or v_role is not null,'role_key',coalesce(v_role,case when v_legacy then 'super_admin' end));
end $$;


--
-- Name: platform_device_issue_activation(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_device_issue_activation(p_tenant_id uuid, p_location_id uuid, p_name text, p_app_type text, p_platform_hint text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$ declare
  v_id uuid:=gen_random_uuid(); v_code text; v_device_code text; v_exp timestamptz:=now()+interval '24 hours';
begin
  if not private.platform_v2_has_role('super_admin') and not private.platform_v2_has_role('support_admin') then raise exception 'Platform admin required'; end if;
  if p_app_type not in ('client','pos') then raise exception 'Invalid app type'; end if;
  if not exists(select 1 from public.business_locations where id=p_location_id and tenant_id=p_tenant_id and active) then raise exception 'Invalid location'; end if;
  v_code:=upper(substr(encode(gen_random_bytes(8),'hex'),1,12));
  v_device_code:=upper(p_app_type)||'-'||upper(substr(replace(v_id::text,'-',''),1,6));
  insert into public.business_devices(id,tenant_id,location_id,device_code,name,app_type,platform_hint,status,activation_hash,activation_expires_at)
  values(v_id,p_tenant_id,p_location_id,v_device_code,trim(p_name),p_app_type,nullif(trim(p_platform_hint),''),'pending',encode(digest(v_code,'sha256'),'hex'),v_exp);
  perform private.platform_audit_write('device.activation_issue','business_device',v_id::text,p_tenant_id,jsonb_build_object('device_code',v_device_code,'app_type',p_app_type,'location_id',p_location_id));
  return jsonb_build_object('device_id',v_id,'device_code',v_device_code,'activation_code',v_code,'expires_at',v_exp);
end $$;


--
-- Name: platform_device_issue_activation_v32(uuid, uuid, text, text, text, text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_device_issue_activation_v32(p_tenant_id uuid, p_location_id uuid, p_name text, p_app_type text, p_platform_hint text DEFAULT NULL::text, p_module_keys text[] DEFAULT '{}'::text[], p_invoice_prefix text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$ declare v_id uuid:=gen_random_uuid();v_code text;v_device_code text;v_exp timestamptz:=now()+interval '24 hours';v_modules text[];begin
  if not private.platform_v2_has_role('super_admin') and not private.platform_v2_has_role('support_admin') then raise exception 'Platform admin required';end if;
  if p_app_type not in('client','pos') then raise exception 'Invalid app type';end if;
  if not exists(select 1 from public.business_locations where id=p_location_id and tenant_id=p_tenant_id and active) then raise exception 'Invalid location';end if;
  if p_app_type='pos' then select coalesce(array_agg(distinct x),'{}'::text[]) into v_modules from unnest(coalesce(p_module_keys,'{}'::text[]))x where x in('sales','inventory','customers','suppliers','purchases','expenses','restaurant','logs','cashier_shifts','notifications','tasks','support') and exists(select 1 from public.tenant_modules tm where tm.tenant_id=p_tenant_id and tm.module_key=x and tm.enabled);else v_modules:='{}'::text[];end if;
  if nullif(upper(trim(p_invoice_prefix)),'') is not null and exists(select 1 from public.business_devices d where d.tenant_id=p_tenant_id and d.status<>'revoked' and upper(coalesce(d.invoice_prefix,''))=upper(trim(p_invoice_prefix))) then raise exception 'Terminal invoice prefix is already in use';end if;
  v_code:=upper(substr(encode(gen_random_bytes(8),'hex'),1,12));v_device_code:=upper(p_app_type)||'-'||upper(substr(replace(v_id::text,'-',''),1,6));
  insert into public.business_devices(id,tenant_id,location_id,device_code,name,app_type,platform_hint,status,activation_hash,activation_expires_at,allowed_modules,invoice_prefix) values(v_id,p_tenant_id,p_location_id,v_device_code,trim(p_name),p_app_type,nullif(trim(p_platform_hint),''),'pending',encode(digest(v_code,'sha256'),'hex'),v_exp,v_modules,nullif(upper(trim(p_invoice_prefix)),''));
  return jsonb_build_object('device_id',v_id,'device_code',v_device_code,'activation_code',v_code,'expires_at',v_exp,'allowed_modules',v_modules);
end $$;


--
-- Name: platform_device_revoke(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_device_revoke(p_tenant_id uuid, p_device_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if not private.platform_v2_is_admin() then raise exception 'Platform admin required'; end if;
  update public.business_devices
  set status='revoked',device_secret_hash=null,activation_hash=null,activation_expires_at=null,updated_at=now()
  where id=p_device_id and tenant_id=p_tenant_id;
end $$;


--
-- Name: platform_device_settings_update(uuid, uuid, text[], text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_device_settings_update(p_tenant_id uuid, p_device_id uuid, p_module_keys text[], p_invoice_prefix text, p_name text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_type text;v_modules text[];begin
  if not private.platform_v2_has_role('super_admin') and not private.platform_v2_has_role('support_admin') then raise exception 'Platform admin required';end if;
  select app_type into v_type from public.business_devices where id=p_device_id and tenant_id=p_tenant_id;
  if v_type is null then raise exception 'System not found';end if;
  if v_type='pos' then
    select coalesce(array_agg(distinct x),'{}'::text[]) into v_modules
    from unnest(coalesce(p_module_keys,'{}'::text[]))x
    where x in('sales','inventory','customers','suppliers','purchases','expenses','restaurant','logs','cashier_shifts','notifications','tasks','support','terminal_day')
      and exists(select 1 from public.tenant_modules tm where tm.tenant_id=p_tenant_id and tm.module_key=x and tm.enabled);
  else v_modules:='{}'::text[];end if;
  if nullif(upper(trim(p_invoice_prefix)),'') is not null and exists(
    select 1 from public.business_devices d where d.tenant_id=p_tenant_id and d.id<>p_device_id and d.status<>'revoked'
      and upper(coalesce(d.invoice_prefix,''))=upper(trim(p_invoice_prefix))
  ) then raise exception 'Terminal invoice prefix is already in use';end if;
  update public.business_devices
  set allowed_modules=v_modules,invoice_prefix=case when v_type='pos' then nullif(upper(trim(p_invoice_prefix)),'') else invoice_prefix end,
      name=coalesce(nullif(trim(p_name),''),name),updated_at=now()
  where id=p_device_id and tenant_id=p_tenant_id;
end $$;


--
-- Name: platform_device_versions_list_v4(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_device_versions_list_v4(p_tenant_id uuid DEFAULT NULL::uuid) RETURNS TABLE(device_id uuid, tenant_id uuid, business_name text, location_code text, device_code text, device_name text, app_key text, platform text, version text, build_number integer, last_seen_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.platform_v2_is_admin() then raise exception 'Platform admin required';end if;
  return query select s.device_id,s.tenant_id,t.name,l.location_code,d.device_code,d.name,s.app_key,s.platform,s.version,s.build_number,s.last_seen_at
  from public.device_app_status s join public.business_devices d on d.id=s.device_id join public.business_locations l on l.id=d.location_id join public.tenants t on t.id=s.tenant_id
  where p_tenant_id is null or s.tenant_id=p_tenant_id order by s.last_seen_at desc;
end $$;


--
-- Name: platform_division_assign_business_v41(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_division_assign_business_v41(p_division_id uuid, p_tenant_id uuid, p_member_type text DEFAULT 'child'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_type text:=lower(coalesce(p_member_type,'child'));v_old_div uuid;v_old_type text;begin
  if not private.platform_v2_has_role('super_admin') then raise exception 'Super Admin required';end if;
  if not exists(select 1 from public.business_divisions where id=p_division_id and active) then raise exception 'Division not found';end if;
  if not exists(select 1 from public.tenants where id=p_tenant_id) then raise exception 'Business not found';end if;
  if v_type not in('main','child') then raise exception 'Invalid division member type';end if;

  select division_id,member_type into v_old_div,v_old_type from public.business_division_members where tenant_id=p_tenant_id;
  delete from public.business_division_members where tenant_id=p_tenant_id;
  if v_old_div is not null and v_old_type='main' and (v_old_div<>p_division_id or v_type<>'main') then
    update public.business_divisions set main_tenant_id=null,updated_at=now() where id=v_old_div and main_tenant_id=p_tenant_id;
  end if;
  if v_type='main' then
    -- One main business per division. The previous main remains a child member.
    update public.business_division_members set member_type='child' where division_id=p_division_id and member_type='main';
    update public.business_divisions set main_tenant_id=p_tenant_id,updated_at=now() where id=p_division_id;
  end if;
  insert into public.business_division_members(division_id,tenant_id,member_type) values(p_division_id,p_tenant_id,v_type)
  on conflict(division_id,tenant_id) do update set member_type=excluded.member_type;
  perform private.platform_audit_write('division.assign_business','business_division',p_division_id::text,p_tenant_id,jsonb_build_object('member_type',v_type));
end $$;


--
-- Name: platform_division_remove_business_v41(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_division_remove_business_v41(p_tenant_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_div uuid;begin
  if not private.platform_v2_has_role('super_admin') then raise exception 'Super Admin required';end if;
  select division_id into v_div from public.business_division_members where tenant_id=p_tenant_id;
  delete from public.business_division_members where tenant_id=p_tenant_id;
  if v_div is not null then
    update public.business_divisions set main_tenant_id=null,updated_at=now() where id=v_div and main_tenant_id=p_tenant_id;
  end if;
  perform private.platform_audit_write('division.remove_business','tenant',p_tenant_id::text,p_tenant_id,'{}'::jsonb);
end $$;


--
-- Name: platform_division_save_v41(uuid, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_division_save_v41(p_division_id uuid, p_name text, p_division_code text DEFAULT NULL::text, p_active boolean DEFAULT true) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_id uuid:=coalesce(p_division_id,gen_random_uuid());v_code text;begin
  if not private.platform_v2_has_role('super_admin') then raise exception 'Super Admin required';end if;
  if trim(coalesce(p_name,''))='' then raise exception 'Division name is required';end if;
  v_code:=upper(regexp_replace(trim(coalesce(p_division_code,'')),'[^A-Za-z0-9_-]+','','g'));
  if v_code='' then v_code:='DIV-'||lpad(nextval('public.business_division_code_seq')::text,5,'0');end if;
  insert into public.business_divisions(id,division_code,name,active,created_by,updated_at)
  values(v_id,v_code,trim(p_name),coalesce(p_active,true),auth.uid(),now())
  on conflict(id) do update set name=excluded.name,active=excluded.active,updated_at=now();
  perform private.platform_audit_write(case when p_division_id is null then 'division.create' else 'division.update' end,'business_division',v_id::text,null,jsonb_build_object('name',trim(p_name),'code',v_code));
  return v_id;
end $$;


--
-- Name: platform_divisions_list_v41(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_divisions_list_v41() RETURNS TABLE(division_id uuid, division_code text, division_name text, main_tenant_id uuid, main_business_name text, member_count bigint, active boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.platform_v2_is_admin() then raise exception 'Platform admin required';end if;
  return query
  select d.id,d.division_code::text,d.name::text,d.main_tenant_id,t.name::text,
    (select count(*) from public.business_division_members dm where dm.division_id=d.id),d.active
  from public.business_divisions d
  left join public.tenants t on t.id=d.main_tenant_id
  order by d.active desc,d.name;
end $$;


--
-- Name: platform_get_business_modules(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_get_business_modules(p_tenant_id uuid) RETURNS TABLE(module_key text, module_name text, description text, category text, is_core boolean, enabled boolean, sort_order integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin

  if not private.is_platform_admin() then
    raise exception 'Access denied'
      using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.tenants t
    where t.id = p_tenant_id
  ) then
    raise exception 'Business not found';
  end if;

  return query

  select
    m.key,
    m.name,
    m.description,
    m.category,
    m.is_core,
    coalesce(tm.enabled, false),
    m.sort_order

  from public.modules m

  left join public.tenant_modules tm
    on tm.module_key = m.key
    and tm.tenant_id = p_tenant_id

  order by
    m.category,
    m.sort_order,
    m.name;

end;
$$;


--
-- Name: platform_get_business_permissions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_get_business_permissions(p_tenant_id uuid) RETURNS TABLE(permission_key text, permission_name text, module_key text, module_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin

  if not private.is_platform_admin() then
    raise exception 'Access denied'
      using errcode = '42501';
  end if;

  return query

  select
    p.key,
    p.name,
    p.module_key,
    m.name

  from public.permissions p

  join public.modules m
    on m.key = p.module_key

  join public.tenant_modules tm
    on tm.module_key = p.module_key
   and tm.tenant_id = p_tenant_id
   and tm.enabled = true

  order by
    m.sort_order,
    m.name,
    p.name;

end;
$$;


--
-- Name: platform_get_business_roles(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_get_business_roles(p_tenant_id uuid) RETURNS TABLE(role_id uuid, role_key text, role_name text, is_system boolean, permission_keys text[])
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin

  if not private.is_platform_admin() then
    raise exception 'Access denied'
      using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.tenants t
    where t.id = p_tenant_id
  ) then
    raise exception 'Business not found';
  end if;

  return query
  select
    r.id,
    r.key,
    r.name,
    r.is_system,

    coalesce(
      array_agg(
        rp.permission_key
        order by rp.permission_key
      ) filter (
        where rp.permission_key is not null
      ),
      array[]::text[]
    )

  from public.roles r

  left join public.role_permissions rp
    on rp.role_id = r.id

  where r.tenant_id = p_tenant_id

  group by
    r.id,
    r.key,
    r.name,
    r.is_system

  order by
    case r.key
      when 'owner' then 1
      when 'manager' then 2
      when 'cashier' then 3
      when 'salesperson' then 4
      when 'store_keeper' then 5
      when 'accountant' then 6
      else 100
    end,
    r.name;

end;
$$;


--
-- Name: platform_invoice_template_upsert(uuid, text, text, text, text, jsonb, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_invoice_template_upsert(p_id uuid, p_key text, p_name text, p_paper_type text, p_description text, p_config jsonb, p_sample_logo_key text, p_is_active boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_id uuid; begin
  if not private.platform_v2_has_role('super_admin') and not private.platform_v2_has_role('technical_admin') then raise exception 'Permission denied'; end if;
  if p_paper_type not in ('a4','80mm') then raise exception 'Invalid paper type'; end if;
  if p_id is null then
    insert into public.invoice_templates(key,name,paper_type,description,config,sample_logo_key,is_system,is_active) values(trim(p_key),trim(p_name),p_paper_type,nullif(trim(p_description),''),coalesce(p_config,'{}'::jsonb),nullif(trim(p_sample_logo_key),''),false,p_is_active) returning id into v_id;
  else
    update public.invoice_templates set key=trim(p_key),name=trim(p_name),paper_type=p_paper_type,description=nullif(trim(p_description),''),config=coalesce(p_config,'{}'::jsonb),sample_logo_key=nullif(trim(p_sample_logo_key),''),is_active=p_is_active,updated_at=now() where id=p_id returning id into v_id;
  end if;
  perform private.platform_audit_write('invoice_template_upsert','invoice_template',v_id::text,null,jsonb_build_object('key',p_key,'paper_type',p_paper_type));
  return v_id;
end $$;


