-- Name: platform_invoice_templates_list(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_invoice_templates_list() RETURNS SETOF public.invoice_templates
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin if not private.platform_v2_is_admin() then raise exception 'Platform admin required'; end if; return query select * from public.invoice_templates order by paper_type,name; end $$;


--
-- Name: platform_list_businesses(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_list_businesses() RETURNS TABLE(id uuid, name text, slug text, business_type text, status text, module_count bigint, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin

  if not private.is_platform_admin() then
    raise exception 'Access denied'
      using errcode = '42501';
  end if;

  return query
  select
    t.id,
    t.name,
    t.slug,
    t.business_type,
    t.status,
    count(tm.module_key)
      filter (where tm.enabled = true) as module_count,
    t.created_at
  from public.tenants t
  left join public.tenant_modules tm
    on tm.tenant_id = t.id
  group by
    t.id,
    t.name,
    t.slug,
    t.business_type,
    t.status,
    t.created_at
  order by t.created_at desc;

end;
$$;


--
-- Name: platform_list_businesses_v41(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_list_businesses_v41() RETURNS TABLE(id uuid, name text, slug text, business_type text, status text, module_count bigint, created_at timestamp with time zone, division_id uuid, division_name text, division_role text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.platform_v2_is_admin() then raise exception 'Platform admin required';end if;
  return query
  select t.id,t.name::text,t.slug::text,t.business_type::text,t.status::text,
    (select count(*) from public.tenant_modules tm where tm.tenant_id=t.id and tm.enabled),t.created_at,
    dm.division_id,d.name::text,dm.member_type::text
  from public.tenants t
  left join public.business_division_members dm on dm.tenant_id=t.id
  left join public.business_divisions d on d.id=dm.division_id
  order by coalesce(d.name,t.name),case when dm.member_type='main' then 0 else 1 end,t.name;
end $$;


--
-- Name: platform_list_modules(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_list_modules() RETURNS TABLE(key text, name text, description text, category text, is_core boolean, sort_order integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin

  if not private.is_platform_admin() then
    raise exception 'Access denied'
      using errcode = '42501';
  end if;

  return query
  select
    m.key,
    m.name,
    m.description,
    m.category,
    m.is_core,
    m.sort_order
  from public.modules m
  order by
    m.category,
    m.sort_order,
    m.name;

end;
$$;


--
-- Name: platform_location_delete_v471(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_location_delete_v471(p_tenant_id uuid, p_location_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare l public.business_locations%rowtype;v_has_history boolean:=false;
begin
  if not private.platform_v2_has_role('super_admin') and not private.platform_v2_has_role('support_admin') then raise exception 'Platform admin required';end if;
  select * into l from public.business_locations where id=p_location_id and tenant_id=p_tenant_id for update;
  if not found then raise exception 'Store/location not found';end if;
  if coalesce(l.hierarchy_role,'')='main_store' or upper(coalesce(l.location_code,''))='MAIN' then
    raise exception 'MAIN STORE cannot be deleted. Rename/edit it instead.';
  end if;
  if exists(select 1 from public.business_devices where tenant_id=p_tenant_id and location_id=p_location_id and status<>'revoked') then
    raise exception 'Move or delete the systems assigned to this store before deleting it';
  end if;
  if exists(select 1 from public.business_locations where tenant_id=p_tenant_id and parent_location_id=p_location_id and active) then
    raise exception 'Move/archive child locations before deleting this store';
  end if;
  select exists(select 1 from public.document_origins where tenant_id=p_tenant_id and location_id=p_location_id)
      or exists(select 1 from public.journal_entries where tenant_id=p_tenant_id and location_id=p_location_id)
      or exists(select 1 from public.location_stock_balances where tenant_id=p_tenant_id and location_id=p_location_id)
  into v_has_history;

  if v_has_history then
    update public.business_locations set active=false,updated_at=now() where id=p_location_id;
    perform private.business_audit_write_v471(p_tenant_id,'location.archive','business_location',p_location_id,l.location_code,null::jsonb,jsonb_build_object('reason',p_reason));
    return jsonb_build_object('success',true,'action','archived','location_id',p_location_id,'message','Store has business history and was safely archived.');
  end if;

  delete from public.business_locations where id=p_location_id and tenant_id=p_tenant_id;
  perform private.business_audit_write_v471(p_tenant_id,'location.delete','business_location',p_location_id,l.location_code,null::jsonb,jsonb_build_object('reason',p_reason));
  return jsonb_build_object('success',true,'action','deleted','location_id',p_location_id,'message','Unused store permanently deleted.');
end $$;


--
-- Name: platform_menu_copy_default_v45(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_menu_copy_default_v45(p_tenant_id uuid, p_app_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare r record;v_parent uuid;v_new uuid;v_map jsonb:='{}'::jsonb;begin
  if not private.platform_v2_has_role('technical_admin') and not private.platform_v2_has_role('super_admin') then raise exception 'Super/technical admin required';end if;
  if not exists(select 1 from public.tenants where id=p_tenant_id) then raise exception 'Business not found';end if;
  if p_app_key not in('client','pos') then raise exception 'Invalid app key';end if;
  delete from public.app_menu_nodes_v45 where tenant_id=p_tenant_id and app_key=p_app_key;
  for r in
    with recursive tree as (
      select n.*,0 depth from public.app_menu_nodes_v45 n where n.tenant_id is null and n.app_key=p_app_key and n.parent_id is null
      union all
      select c.*,t.depth+1 from public.app_menu_nodes_v45 c join tree t on c.parent_id=t.id where c.tenant_id is null and c.app_key=p_app_key
    ) select * from tree order by depth,sort_order,label
  loop
    v_parent:=case when r.parent_id is null then null else nullif(v_map->>r.parent_id::text,'')::uuid end;
    insert into public.app_menu_nodes_v45(tenant_id,app_key,node_key,node_type,module_key,parent_id,label,icon_key,sort_order,enabled,collapsed_by_default,metadata,updated_by)
    values(p_tenant_id,p_app_key,r.node_key,r.node_type,r.module_key,v_parent,r.label,r.icon_key,r.sort_order,r.enabled,r.collapsed_by_default,r.metadata,auth.uid()) returning id into v_new;
    v_map:=jsonb_set(v_map,array[r.id::text],to_jsonb(v_new::text),true);
  end loop;
  perform private.platform_audit_write('menu.copy_default','tenant',p_tenant_id::text,p_tenant_id,jsonb_build_object('app_key',p_app_key));
end $$;


--
-- Name: platform_menu_node_delete_v45(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_menu_node_delete_v45(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_tenant uuid;v_app text;begin
  if not private.platform_v2_has_role('technical_admin') and not private.platform_v2_has_role('super_admin') then raise exception 'Super/technical admin required';end if;
  select tenant_id,app_key into v_tenant,v_app from public.app_menu_nodes_v45 where id=p_id;
  delete from public.app_menu_nodes_v45 where id=p_id;
  perform private.platform_audit_write('menu.node.delete','app_menu_node',p_id::text,v_tenant,jsonb_build_object('app_key',v_app));
end $$;


--
-- Name: platform_menu_node_save_v45(uuid, uuid, text, text, text, text, uuid, text, text, integer, boolean, boolean, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_menu_node_save_v45(p_id uuid, p_tenant_id uuid, p_app_key text, p_node_key text, p_node_type text, p_module_key text, p_parent_id uuid, p_label text, p_icon_key text, p_sort_order integer, p_enabled boolean, p_collapsed_by_default boolean, p_metadata jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_id uuid:=coalesce(p_id,gen_random_uuid());begin
  if not private.platform_v2_has_role('technical_admin') and not private.platform_v2_has_role('super_admin') then raise exception 'Super/technical admin required';end if;
  if p_app_key not in('client','pos') then raise exception 'Invalid app key';end if;
  if p_node_type not in('group','module') then raise exception 'Invalid node type';end if;
  if trim(coalesce(p_label,''))='' or trim(coalesce(p_node_key,''))='' then raise exception 'Key and label required';end if;
  if p_node_type='module' and not exists(select 1 from public.modules where key=p_module_key) then raise exception 'Module not found';end if;
  if p_parent_id is not null then
    if p_parent_id=v_id then raise exception 'A menu cannot be its own parent';end if;
    if not exists(select 1 from public.app_menu_nodes_v45 x where x.id=p_parent_id and x.app_key=p_app_key and x.tenant_id is not distinct from p_tenant_id) then raise exception 'Parent menu not found';end if;
    if exists(
      with recursive ancestors as (
        select x.id,x.parent_id from public.app_menu_nodes_v45 x where x.id=p_parent_id
        union all
        select x.id,x.parent_id from public.app_menu_nodes_v45 x join ancestors a on x.id=a.parent_id
      ) select 1 from ancestors where id=v_id
    ) then raise exception 'Menu nesting would create a cycle';end if;
  end if;
  insert into public.app_menu_nodes_v45(id,tenant_id,app_key,node_key,node_type,module_key,parent_id,label,icon_key,sort_order,enabled,collapsed_by_default,metadata,updated_by)
  values(v_id,p_tenant_id,p_app_key,trim(p_node_key),p_node_type,case when p_node_type='module' then p_module_key else null end,p_parent_id,trim(p_label),nullif(trim(coalesce(p_icon_key,'')),''),coalesce(p_sort_order,100),coalesce(p_enabled,true),coalesce(p_collapsed_by_default,false),coalesce(p_metadata,'{}'::jsonb),auth.uid())
  on conflict(id) do update set node_key=excluded.node_key,node_type=excluded.node_type,module_key=excluded.module_key,parent_id=excluded.parent_id,label=excluded.label,icon_key=excluded.icon_key,sort_order=excluded.sort_order,enabled=excluded.enabled,collapsed_by_default=excluded.collapsed_by_default,metadata=excluded.metadata,updated_by=auth.uid(),updated_at=now();
  perform private.platform_audit_write('menu.node.save','app_menu_node',v_id::text,p_tenant_id,jsonb_build_object('app_key',p_app_key,'label',p_label,'module_key',p_module_key));
  return v_id;
end $$;


--
-- Name: app_menu_nodes_v45; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.app_menu_nodes_v45 (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid,
    app_key text NOT NULL,
    node_key text NOT NULL,
    node_type text NOT NULL,
    module_key text,
    parent_id uuid,
    label text NOT NULL,
    icon_key text,
    sort_order integer DEFAULT 100 NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    collapsed_by_default boolean DEFAULT false NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT app_menu_nodes_v45_app_key_check CHECK ((app_key = ANY (ARRAY['client'::text, 'pos'::text]))),
    CONSTRAINT app_menu_nodes_v45_check CHECK ((((node_type = 'module'::text) AND (module_key IS NOT NULL)) OR ((node_type = 'group'::text) AND (module_key IS NULL)))),
    CONSTRAINT app_menu_nodes_v45_node_type_check CHECK ((node_type = ANY (ARRAY['group'::text, 'module'::text])))
);


--
-- Name: platform_menu_nodes_v45_list(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_menu_nodes_v45_list(p_tenant_id uuid, p_app_key text) RETURNS SETOF public.app_menu_nodes_v45
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.platform_v2_is_admin() then raise exception 'Platform admin required';end if;
  return query select * from public.app_menu_nodes_v45 n
  where n.app_key=p_app_key and ((p_tenant_id is null and n.tenant_id is null) or n.tenant_id=p_tenant_id)
  order by n.parent_id nulls first,n.sort_order,n.label;
end $$;


--
-- Name: platform_module_v2_upsert(text, text, text, text, integer, boolean, boolean, boolean, boolean, text, text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_module_v2_upsert(p_key text, p_name text, p_description text, p_category text, p_sort_order integer, p_is_core boolean, p_is_active boolean, p_is_beta boolean, p_requires_configuration boolean, p_minimum_plan_key text, p_dependencies text[], p_business_types text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if not private.platform_v2_has_role('technical_admin') then raise exception 'Technical admin access required'; end if;
  if coalesce(trim(p_key),'')='' or coalesce(trim(p_name),'')='' then raise exception 'Module key and name are required'; end if;

  insert into public.modules(key,name,description,category,is_core,sort_order,is_active,is_beta,requires_configuration,minimum_plan_key)
  values(trim(p_key),trim(p_name),nullif(trim(p_description),''),coalesce(nullif(trim(p_category),''),'General'),coalesce(p_is_core,false),coalesce(p_sort_order,100),coalesce(p_is_active,true),coalesce(p_is_beta,false),coalesce(p_requires_configuration,false),nullif(trim(p_minimum_plan_key),''))
  on conflict(key) do update set name=excluded.name,description=excluded.description,category=excluded.category,is_core=excluded.is_core,sort_order=excluded.sort_order,is_active=excluded.is_active,is_beta=excluded.is_beta,requires_configuration=excluded.requires_configuration,minimum_plan_key=excluded.minimum_plan_key;

  delete from public.module_dependencies where module_key=p_key;
  insert into public.module_dependencies(module_key,depends_on_module_key)
  select p_key,x from unnest(coalesce(p_dependencies,array[]::text[])) x
  where x<>p_key and exists(select 1 from public.modules m where m.key=x)
  on conflict do nothing;

  delete from public.module_business_types where module_key=p_key;
  insert into public.module_business_types(module_key,business_type)
  select p_key,trim(x) from unnest(coalesce(p_business_types,array[]::text[])) x where trim(x)<>''
  on conflict do nothing;

  perform private.platform_audit_write('module.upsert','module',p_key,null,jsonb_build_object('name',p_name,'active',p_is_active));
end $$;


--
-- Name: platform_modules_v2_list(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_modules_v2_list() RETURNS TABLE(key text, name text, description text, category text, is_core boolean, sort_order integer, is_active boolean, is_beta boolean, requires_configuration boolean, minimum_plan_key text, dependencies text[], business_types text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if not private.platform_v2_is_admin() then raise exception 'Platform admin access required'; end if;
  return query
  select m.key,m.name,m.description,m.category,m.is_core,m.sort_order,m.is_active,m.is_beta,m.requires_configuration,m.minimum_plan_key,
         coalesce((select array_agg(md.depends_on_module_key order by md.depends_on_module_key) from public.module_dependencies md where md.module_key=m.key),array[]::text[]),
         coalesce((select array_agg(mbt.business_type order by mbt.business_type) from public.module_business_types mbt where mbt.module_key=m.key),array[]::text[])
  from public.modules m order by m.category,m.sort_order,m.name;
end $$;


--
-- Name: platform_next_pos_invoice_prefix_v500(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_next_pos_invoice_prefix_v500(p_tenant_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if not private.platform_v2_has_role('super_admin') and not private.platform_v2_has_role('support_admin') then raise exception 'Platform admin required'; end if;
  return private.v500_next_pos_invoice_prefix(p_tenant_id);
end $$;


--
-- Name: platform_overview_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_overview_summary() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if not private.platform_v2_is_admin() then raise exception 'Platform admin access required'; end if;
  return jsonb_build_object(
    'businesses', (select count(*) from public.tenants),
    'active_businesses', (select count(*) from public.tenants where status='active'),
    'active_subscriptions', (select count(*) from public.tenant_subscriptions where status='active'),
    'trials', (select count(*) from public.tenant_subscriptions where status='trial'),
    'plans', (select count(*) from public.subscription_plans where is_active),
    'templates', (select count(*) from public.business_templates where is_active),
    'modules', (select count(*) from public.modules where is_active)
  );
end $$;


--
-- Name: platform_parties_list_v45(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_parties_list_v45(p_tenant_id uuid, p_party_type text, p_query text DEFAULT NULL::text) RETURNS TABLE(id uuid, name text, phone text, reference text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare q text:='%'||lower(trim(coalesce(p_query,'')))||'%';begin
  if not private.platform_v2_is_admin() then raise exception 'Platform admin required';end if;
  if p_party_type='customer' then
    return query select c.id,c.name::text,coalesce(c.phone,'')::text,coalesce(c.tracking_code,'')::text from public.customers c
      where c.tenant_id=p_tenant_id and (trim(coalesce(p_query,''))='' or lower(c.name) like q or lower(coalesce(c.phone,'')) like q or lower(coalesce(c.tracking_code,'')) like q)
      order by c.name limit 250;
  elsif p_party_type='supplier' then
    return query select s.id,s.name::text,coalesce(s.phone,'')::text,coalesce(s.tracking_code,'')::text from public.suppliers s
      where s.tenant_id=p_tenant_id and (trim(coalesce(p_query,''))='' or lower(s.name) like q or lower(coalesce(s.phone,'')) like q or lower(coalesce(s.tracking_code,'')) like q)
      order by s.name limit 250;
  else raise exception 'Invalid party type';end if;
end $$;


--
-- Name: platform_payment_correct_v45(uuid, text, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_payment_correct_v45(p_tenant_id uuid, p_entity_type text, p_payment_id uuid, p_payment_method text, p_reference_number text, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_old_method text;v_amount numeric;v_paid_at timestamptz;v_entity uuid;v_loc uuid;v_ref text;v_party uuid;v_lines jsonb;v_shift uuid;begin
  if not private.platform_v2_has_role('super_admin') and not private.platform_v2_has_role('technical_admin') then raise exception 'Super/technical admin required';end if;
  if trim(coalesce(p_reason,''))='' then raise exception 'Correction reason is required';end if;
  if lower(coalesce(p_payment_method,'')) not in('cash','bank','upi','card','credit_card','debit_card') then raise exception 'Unsupported payment method';end if;

  if p_entity_type='sale' then
    select sp.payment_method,sp.amount,sp.paid_at,sp.sale_id,s.sale_number,s.customer_id,o.location_id
      into v_old_method,v_amount,v_paid_at,v_entity,v_ref,v_party,v_loc
    from public.sale_payments sp join public.sales s on s.id=sp.sale_id
    left join public.document_origins o on o.entity_type='sale' and o.entity_id=s.id
    where sp.id=p_payment_id and s.tenant_id=p_tenant_id;
    if v_entity is null then raise exception 'Sale payment not found';end if;
    perform private.v4_reverse_source_journal(p_tenant_id,'sale_payment',p_payment_id,'sale_payment_edit_reverse','Admin payment correction');
    update public.journal_entries set status='reversed' where tenant_id=p_tenant_id and source_type='sale_payment' and source_id=p_payment_id and status='posted';
    update public.sale_payments set payment_method=lower(p_payment_method),reference_number=nullif(trim(coalesce(p_reference_number,'')),'') where id=p_payment_id;
    v_lines:=jsonb_build_array(
      jsonb_build_object('account_id',private.v4_payment_account(p_tenant_id,p_payment_method),'debit',v_amount,'credit',0,'party_type','customer','party_id',v_party,'description','Customer receipt • corrected'),
      jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'accounts_receivable'),'debit',0,'credit',v_amount,'party_type','customer','party_id',v_party,'description','Receivable settlement • corrected')
    );
    perform private.v4_journal_create(p_tenant_id,v_loc,coalesce(v_paid_at::date,current_date),'Customer receipt • '||v_ref,'sale_payment',p_payment_id,v_ref,v_lines);
    if lower(coalesce(v_old_method,''))='cash' and lower(p_payment_method)<>'cash' then
      update public.cash_drawer_movements set amount=0,note=coalesce(note,'')||' • Corrected from cash to '||lower(p_payment_method)
       where tenant_id=p_tenant_id and reference_type='sale_payment' and reference_id=p_payment_id;
    elsif lower(coalesce(v_old_method,''))<>'cash' and lower(p_payment_method)='cash' then
      select cs.id into v_shift from public.cashier_shifts cs join public.document_origins o on o.device_id=cs.device_id
      where o.entity_type='sale' and o.entity_id=v_entity and cs.tenant_id=p_tenant_id and cs.opened_at<=coalesce(v_paid_at,now()) and (cs.closed_at is null or cs.closed_at>=coalesce(v_paid_at,now())) order by cs.opened_at desc limit 1;
      if v_shift is not null and not exists(select 1 from public.cash_drawer_movements where reference_type='sale_payment' and reference_id=p_payment_id and amount<>0) then
        insert into public.cash_drawer_movements(tenant_id,shift_id,movement_type,amount,reference_type,reference_id,reference_number,note,created_by)
        values(p_tenant_id,v_shift,'sale',v_amount,'sale_payment',p_payment_id,v_ref,'Admin corrected payment to cash',auth.uid());
      end if;
    end if;
  elsif p_entity_type='purchase' then
    select pp.payment_method,pp.amount,pp.paid_at,pp.purchase_id,p.purchase_number,p.supplier_id,o.location_id
      into v_old_method,v_amount,v_paid_at,v_entity,v_ref,v_party,v_loc
    from public.purchase_payments pp join public.purchases p on p.id=pp.purchase_id
    left join public.document_origins o on o.entity_type='purchase' and o.entity_id=p.id
    where pp.id=p_payment_id and p.tenant_id=p_tenant_id;
    if v_entity is null then raise exception 'Purchase payment not found';end if;
    perform private.v4_reverse_source_journal(p_tenant_id,'purchase_payment',p_payment_id,'purchase_payment_edit_reverse','Admin payment correction');
    update public.journal_entries set status='reversed' where tenant_id=p_tenant_id and source_type='purchase_payment' and source_id=p_payment_id and status='posted';
    update public.purchase_payments set payment_method=lower(p_payment_method),reference_number=nullif(trim(coalesce(p_reference_number,'')),'') where id=p_payment_id;
    v_lines:=jsonb_build_array(
      jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'accounts_payable'),'debit',v_amount,'credit',0,'party_type','supplier','party_id',v_party,'description','Payable settlement • corrected'),
      jsonb_build_object('account_id',private.v4_payment_account(p_tenant_id,p_payment_method),'debit',0,'credit',v_amount,'party_type','supplier','party_id',v_party,'description','Supplier payment • corrected')
    );
    perform private.v4_journal_create(p_tenant_id,v_loc,coalesce(v_paid_at::date,current_date),'Supplier payment • '||v_ref,'purchase_payment',p_payment_id,v_ref,v_lines);
  else raise exception 'Payment correction supports sale or purchase';end if;

  insert into public.transaction_corrections(tenant_id,entity_type,entity_id,correction_type,reason,created_by,metadata)
  values(p_tenant_id,p_entity_type,v_entity,'edit',trim(p_reason),auth.uid(),jsonb_build_object('payment_id',p_payment_id,'old_method',v_old_method,'new_method',lower(p_payment_method),'reference_number',p_reference_number));
  perform private.platform_audit_write('transaction.payment.correct',p_entity_type,v_entity::text,p_tenant_id,jsonb_build_object('payment_id',p_payment_id,'old_method',v_old_method,'new_method',lower(p_payment_method),'reason',trim(p_reason)));
end $$;


--
-- Name: platform_return_correct_v45(uuid, text, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_return_correct_v45(p_tenant_id uuid, p_entity_type text, p_entity_id uuid, p_patch jsonb, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_type text:=lower(coalesce(p_entity_type,''));v_before jsonb;v_after jsonb;v_loc uuid;v_ref text;x jsonb;
  v_item_id uuid;v_variant uuid;v_old_qty numeric;v_new_qty numeric;v_delta numeric;v_stock_delta numeric;v_other numeric;
  v_original_qty numeric;v_unit numeric;v_discount_per_unit numeric;v_tax_rate numeric;v_sub numeric;v_disc numeric;v_line numeric;
  v_total_sub numeric;v_total_tax numeric;v_total numeric;
begin
  if not private.platform_v2_has_role('super_admin') and not private.platform_v2_has_role('technical_admin') then raise exception 'Super/technical admin required';end if;
  if v_type not in('sales_return','purchase_return') then raise exception 'Unsupported return type';end if;
  if trim(coalesce(p_reason,''))='' then raise exception 'Correction reason is required';end if;
  v_before:=public.platform_transaction_detail_v45(p_tenant_id,v_type,p_entity_id);

  if v_type='sales_return' then
    select location_id,return_number into v_loc,v_ref from public.sales_returns where id=p_entity_id and tenant_id=p_tenant_id for update;
    if v_loc is null then raise exception 'Sales return not found';end if;
    if p_patch?'items' then
      perform private.v4_reverse_source_journal(p_tenant_id,'sales_return',p_entity_id,'sales_return_edit_reverse','Admin correction '||v_ref);
      update public.journal_entries set status='reversed' where tenant_id=p_tenant_id and source_type='sales_return' and source_id=p_entity_id and status='posted';
      for x in select value from jsonb_array_elements(coalesce(p_patch->'items','[]'::jsonb)) loop
        v_item_id:=(x->>'item_id')::uuid;
        select ri.variant_id,ri.quantity,si.quantity,si.unit_price,coalesce(si.discount_amount,0)/nullif(si.quantity,0),coalesce(si.tax_rate,0)
          into v_variant,v_old_qty,v_original_qty,v_unit,v_discount_per_unit,v_tax_rate
        from public.sales_return_items ri join public.sale_items si on si.id=ri.sale_item_id
        where ri.id=v_item_id and ri.sales_return_id=p_entity_id for update;
        if v_variant is null then raise exception 'Sales return item not found';end if;
        v_new_qty:=coalesce(nullif(x->>'quantity','')::numeric,v_old_qty);
        if v_new_qty<0 then raise exception 'Return quantity cannot be negative';end if;
        select coalesce(sum(other.quantity),0) into v_other
        from public.sales_return_items other join public.sales_returns sr on sr.id=other.sales_return_id
        where sr.sale_id=(select sale_id from public.sales_returns where id=p_entity_id) and other.sale_item_id=(select sale_item_id from public.sales_return_items where id=v_item_id) and other.id<>v_item_id;
        if v_other+v_new_qty>v_original_qty+0.0001 then raise exception 'Corrected return quantity exceeds originally sold quantity';end if;
        v_delta:=v_new_qty-v_old_qty;
        if v_delta<0 and coalesce((select quantity-reserved_quantity-damaged_quantity-quarantine_quantity from public.location_stock_balances where tenant_id=p_tenant_id and location_id=v_loc and variant_id=v_variant),0)<abs(v_delta) then
          raise exception 'Cannot reduce the sales return because the returned stock has already been consumed';
        end if;
        if abs(v_delta)>0.0001 then
          perform public.inventory_adjust_stock(p_tenant_id,v_variant,v_delta,'Admin sales return correction • '||v_ref);
          perform private.v4_location_stock_apply(p_tenant_id,v_loc,v_variant,v_delta,case when v_delta>0 then 'adjustment_in' else 'adjustment_out' end,'sales_return',p_entity_id,v_ref,'Platform Admin correction • '||trim(p_reason),null,false);
        end if;
        if v_new_qty=0 then
          delete from public.sales_return_items where id=v_item_id;
        else
          v_sub:=round(v_unit*v_new_qty,2);v_disc:=round(coalesce(v_discount_per_unit,0)*v_new_qty,2);
          v_line:=round(greatest(v_sub-v_disc,0)*(1+v_tax_rate/100.0),2);
          update public.sales_return_items set quantity=v_new_qty,unit_price=v_unit,discount_amount=v_disc,tax_rate=v_tax_rate,line_total=v_line where id=v_item_id;
        end if;
      end loop;
      select coalesce(sum((unit_price*quantity)-discount_amount),0),coalesce(sum(line_total-((unit_price*quantity)-discount_amount)),0),coalesce(sum(line_total),0)
        into v_total_sub,v_total_tax,v_total from public.sales_return_items where sales_return_id=p_entity_id;
      update public.sales_returns set subtotal=v_total_sub,tax_total=v_total_tax,grand_total=v_total where id=p_entity_id;
      if v_total>0 then perform private.v4_post_sales_return(p_entity_id);end if;
    end if;
    if p_patch?'reason' then update public.sales_returns set reason=coalesce(nullif(trim(p_patch->>'reason'),''),reason) where id=p_entity_id;end if;

  else
    select location_id,return_number into v_loc,v_ref from public.purchase_returns where id=p_entity_id and tenant_id=p_tenant_id for update;
    if v_loc is null then raise exception 'Purchase return not found';end if;
    if p_patch?'items' then
      perform private.v4_reverse_source_journal(p_tenant_id,'purchase_return',p_entity_id,'purchase_return_edit_reverse','Admin correction '||v_ref);
      update public.journal_entries set status='reversed' where tenant_id=p_tenant_id and source_type='purchase_return' and source_id=p_entity_id and status='posted';
      for x in select value from jsonb_array_elements(coalesce(p_patch->'items','[]'::jsonb)) loop
        v_item_id:=(x->>'item_id')::uuid;
        select ri.variant_id,ri.quantity,pi.quantity,pi.unit_cost,coalesce(pi.discount_amount,0)/nullif(pi.quantity,0),coalesce(pi.tax_rate,0)
          into v_variant,v_old_qty,v_original_qty,v_unit,v_discount_per_unit,v_tax_rate
        from public.purchase_return_items ri join public.purchase_items pi on pi.id=ri.purchase_item_id
        where ri.id=v_item_id and ri.purchase_return_id=p_entity_id for update;
        if v_variant is null then raise exception 'Purchase return item not found';end if;
        v_new_qty:=coalesce(nullif(x->>'quantity','')::numeric,v_old_qty);
        if v_new_qty<0 then raise exception 'Return quantity cannot be negative';end if;
        select coalesce(sum(other.quantity),0) into v_other
        from public.purchase_return_items other join public.purchase_returns pr on pr.id=other.purchase_return_id
        where pr.purchase_id=(select purchase_id from public.purchase_returns where id=p_entity_id) and other.purchase_item_id=(select purchase_item_id from public.purchase_return_items where id=v_item_id) and other.id<>v_item_id;
        if v_other+v_new_qty>v_original_qty+0.0001 then raise exception 'Corrected return quantity exceeds originally purchased quantity';end if;
        v_delta:=v_new_qty-v_old_qty;
        v_stock_delta:=-v_delta;
        if v_stock_delta<0 and coalesce((select quantity-reserved_quantity-damaged_quantity-quarantine_quantity from public.location_stock_balances where tenant_id=p_tenant_id and location_id=v_loc and variant_id=v_variant),0)<abs(v_stock_delta) then
          raise exception 'Cannot increase the purchase return because that stock is no longer available';
        end if;
        if abs(v_stock_delta)>0.0001 then
          perform public.inventory_adjust_stock(p_tenant_id,v_variant,v_stock_delta,'Admin purchase return correction • '||v_ref);
          perform private.v4_location_stock_apply(p_tenant_id,v_loc,v_variant,v_stock_delta,case when v_stock_delta>0 then 'adjustment_in' else 'adjustment_out' end,'purchase_return',p_entity_id,v_ref,'Platform Admin correction • '||trim(p_reason),null,false);
        end if;
        if v_new_qty=0 then
          delete from public.purchase_return_items where id=v_item_id;
        else
          v_sub:=round(v_unit*v_new_qty,2);v_disc:=round(coalesce(v_discount_per_unit,0)*v_new_qty,2);
          v_line:=round(greatest(v_sub-v_disc,0)*(1+v_tax_rate/100.0),2);
          update public.purchase_return_items set quantity=v_new_qty,unit_cost=v_unit,discount_amount=v_disc,tax_rate=v_tax_rate,line_total=v_line where id=v_item_id;
        end if;
      end loop;
      select coalesce(sum((unit_cost*quantity)-discount_amount),0),coalesce(sum(line_total-((unit_cost*quantity)-discount_amount)),0),coalesce(sum(line_total),0)
        into v_total_sub,v_total_tax,v_total from public.purchase_return_items where purchase_return_id=p_entity_id;
      update public.purchase_returns set subtotal=v_total_sub,tax_total=v_total_tax,grand_total=v_total where id=p_entity_id;
      if v_total>0 then perform private.v4_post_purchase_return(p_entity_id);end if;
    end if;
    if p_patch?'reason' then update public.purchase_returns set reason=coalesce(nullif(trim(p_patch->>'reason'),''),reason) where id=p_entity_id;end if;
  end if;

  v_after:=public.platform_transaction_detail_v45(p_tenant_id,v_type,p_entity_id);
  insert into public.transaction_corrections(tenant_id,entity_type,entity_id,correction_type,reason,created_by,metadata)
  values(p_tenant_id,v_type,p_entity_id,'edit',trim(p_reason),auth.uid(),jsonb_build_object('before',v_before,'patch',p_patch,'after',v_after,'platform_admin',true));
  perform private.platform_audit_write('transaction.correct',v_type,p_entity_id::text,p_tenant_id,jsonb_build_object('reason',trim(p_reason),'patch',p_patch));
  return v_after;
end $$;


--
-- Name: platform_setting_set(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_setting_set(p_key text, p_value jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if not private.platform_v2_has_role('technical_admin') then raise exception 'Technical admin access required'; end if;
  insert into public.platform_settings(key,value,updated_by) values(trim(p_key),coalesce(p_value,'null'::jsonb),auth.uid())
  on conflict(key) do update set value=excluded.value,updated_by=auth.uid(),updated_at=now();
  perform private.platform_audit_write('platform_setting.set','platform_setting',p_key,null,jsonb_build_object('value',p_value));
end $$;


--
-- Name: platform_settings_list(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_settings_list() RETURNS TABLE(key text, value jsonb, description text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if not private.platform_v2_is_admin() then raise exception 'Platform admin access required'; end if;
  return query select s.key,s.value,s.description from public.platform_settings s order by s.key;
end $$;


--
-- Name: platform_subscription_plan_upsert(uuid, text, text, text, numeric, numeric, text, boolean, integer, text[], jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_subscription_plan_upsert(p_id uuid, p_key text, p_name text, p_description text, p_monthly_price numeric, p_yearly_price numeric, p_currency_code text, p_is_active boolean, p_sort_order integer, p_module_keys text[], p_limits jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_id uuid;
begin
  if not private.platform_v2_has_role('billing_admin') then raise exception 'Billing admin access required'; end if;
  if coalesce(trim(p_key),'')='' or coalesce(trim(p_name),'')='' then raise exception 'Plan key and name are required'; end if;
  if coalesce(p_monthly_price,0)<0 or coalesce(p_yearly_price,0)<0 then raise exception 'Prices cannot be negative'; end if;
  if p_id is null then
    insert into public.subscription_plans(key,name,description,monthly_price,yearly_price,currency_code,is_active,sort_order,limits)
    values(trim(p_key),trim(p_name),nullif(trim(p_description),''),coalesce(p_monthly_price,0),coalesce(p_yearly_price,0),upper(coalesce(nullif(trim(p_currency_code),''),'INR')),coalesce(p_is_active,true),coalesce(p_sort_order,100),coalesce(p_limits,'{}'::jsonb))
    on conflict(key) do update set name=excluded.name,description=excluded.description,monthly_price=excluded.monthly_price,yearly_price=excluded.yearly_price,currency_code=excluded.currency_code,is_active=excluded.is_active,sort_order=excluded.sort_order,limits=excluded.limits,updated_at=now()
    returning id into v_id;
  else
    update public.subscription_plans set name=trim(p_name),description=nullif(trim(p_description),''),monthly_price=coalesce(p_monthly_price,0),yearly_price=coalesce(p_yearly_price,0),currency_code=upper(coalesce(nullif(trim(p_currency_code),''),'INR')),is_active=coalesce(p_is_active,true),sort_order=coalesce(p_sort_order,100),limits=coalesce(p_limits,limits),updated_at=now() where id=p_id returning id into v_id;
    if v_id is null then raise exception 'Plan not found'; end if;
  end if;

  delete from public.subscription_plan_modules where plan_id=v_id;
  insert into public.subscription_plan_modules(plan_id,module_key)
  select v_id,x
  from unnest(coalesce(p_module_keys,array[]::text[])) x
  where exists(select 1 from public.modules m where m.key=x and m.is_active)
  on conflict do nothing;

  -- Required base dependencies when a detail module is selected directly.
  insert into public.subscription_plan_modules(plan_id,module_key)
  select v_id,md.depends_on_module_key
  from public.subscription_plan_modules chosen
  join public.module_dependencies md on md.module_key=chosen.module_key
  join public.modules dependency on dependency.key=md.depends_on_module_key and dependency.is_active
  where chosen.plan_id=v_id
  on conflict do nothing;

  -- Companion workspaces always follow the fast transaction module.
  insert into public.subscription_plan_modules(plan_id,module_key)
  select v_id,'sales_details'
  where exists(select 1 from public.subscription_plan_modules where plan_id=v_id and module_key='sales')
    and exists(select 1 from public.modules where key='sales_details' and is_active)
  on conflict do nothing;

  insert into public.subscription_plan_modules(plan_id,module_key)
  select v_id,'purchase_details'
  where exists(select 1 from public.subscription_plan_modules where plan_id=v_id and module_key='purchases')
    and exists(select 1 from public.modules where key='purchase_details' and is_active)
  on conflict do nothing;

  insert into public.subscription_plan_modules(plan_id,module_key) values(v_id,'dashboard') on conflict do nothing;
  perform private.platform_audit_write('subscription_plan.upsert','subscription_plan',v_id::text,null,jsonb_build_object('key',p_key));
  return v_id;
end $$;


--
-- Name: platform_subscription_plans_list(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_subscription_plans_list() RETURNS TABLE(id uuid, key text, name text, description text, monthly_price numeric, yearly_price numeric, currency_code text, is_active boolean, sort_order integer, module_keys text[], limits jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if not private.platform_v2_is_admin() then raise exception 'Platform admin access required'; end if;
  return query select sp.id,sp.key,sp.name,sp.description,sp.monthly_price,sp.yearly_price,sp.currency_code,sp.is_active,sp.sort_order,
    coalesce((select array_agg(spm.module_key order by m.sort_order,m.name) from public.subscription_plan_modules spm join public.modules m on m.key=spm.module_key where spm.plan_id=sp.id),array[]::text[]),sp.limits
  from public.subscription_plans sp order by sp.sort_order,sp.name;
end $$;


--
-- Name: platform_support_ticket_status_v4(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_support_ticket_status_v4(p_ticket_id uuid, p_status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.platform_v2_is_admin() then raise exception 'Platform admin required';end if;
  if p_status not in('open','in_progress','waiting_customer','resolved','closed') then raise exception 'Invalid status';end if;
  update public.support_tickets set status=p_status,updated_at=now(),resolved_at=case when p_status in('resolved','closed') then coalesce(resolved_at,now()) else null end where id=p_ticket_id;
end $$;


--
-- Name: platform_support_tickets_list_v4(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_support_tickets_list_v4(p_status text DEFAULT NULL::text, p_limit integer DEFAULT 300) RETURNS TABLE(id uuid, ticket_number text, business_name text, location_code text, device_code text, username text, app_key text, app_version text, category text, priority text, status text, subject text, description text, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.platform_v2_is_admin() then raise exception 'Platform admin required';end if;
  return query select s.id,s.ticket_number,coalesce(t.name,''),coalesce(l.location_code,''),coalesce(d.device_code,''),coalesce(u.username,''),s.app_key,s.app_version,s.category,s.priority,s.status,s.subject,s.description,s.created_at,s.updated_at
  from public.support_tickets s left join public.tenants t on t.id=s.tenant_id left join public.business_locations l on l.id=s.location_id left join public.business_devices d on d.id=s.device_id left join public.user_login_names u on u.user_id=s.user_id
  where p_status is null or p_status='' or s.status=p_status order by case s.priority when 'urgent' then 1 when 'high' then 2 when 'normal' then 3 else 4 end,s.created_at desc limit greatest(1,least(coalesce(p_limit,300),2000));
end $$;


--
-- Name: platform_system_activate_v46(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_system_activate_v46(p_tenant_id uuid, p_device_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
declare
  v_code text;
  v_exp timestamptz := now() + interval '24 hours';
  v_device public.business_devices%rowtype;
begin
  if not private.platform_v2_has_role('super_admin')
     and not private.platform_v2_has_role('support_admin') then
    raise exception 'Platform admin required';
  end if;

  select *
  into v_device
  from public.business_devices
  where id = p_device_id
    and tenant_id = p_tenant_id
  for update;

  if v_device.id is null then
    raise exception 'System not found';
  end if;

  if v_device.status not in ('pending','inactive') then
    raise exception 'Only pending or inactive systems can be activated';
  end if;

  v_code := upper(substr(encode(gen_random_bytes(8),'hex'),1,12));

  update public.business_devices
  set activation_hash = encode(digest(v_code,'sha256'),'hex'),
      activation_expires_at = v_exp,
      activation_issued_at = now(),
      activation_issued_by = auth.uid(),
      updated_at = now(),
      deactivated_at = null,
      deactivated_by = null,
      deactivation_reason = null
  where id = p_device_id;

  perform private.business_audit_write(
    p_tenant_id,
    'system.activation_issued',
    'business_device',
    p_device_id,
    v_device.device_code,
    null::jsonb,
    jsonb_build_object(
      'location_id', v_device.location_id,
      'expires_at', v_exp
    )
  );

  return jsonb_build_object(
    'device_id', v_device.id,
    'device_code', v_device.device_code,
    'activation_code', v_code,
    'business_code',
      (select business_code
       from public.tenants
       where id = p_tenant_id),
    'expires_at', v_exp,
    'status', 'pending'
  );
end
$$;


--
-- Name: platform_system_create_v46(uuid, uuid, text, text, text, text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_system_create_v46(p_tenant_id uuid, p_location_id uuid, p_name text, p_app_type text, p_platform_hint text DEFAULT NULL::text, p_module_keys text[] DEFAULT '{}'::text[], p_invoice_prefix text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
declare
  v_id uuid := gen_random_uuid();
  v_code text;
  v_modules text[];
  v_prefix text;
  v_no int;
begin
  if not private.platform_v2_has_role('super_admin')
     and not private.platform_v2_has_role('support_admin') then
    raise exception 'Platform admin required';
  end if;

  if p_app_type not in ('client','pos') then
    raise exception 'Invalid app type';
  end if;

  if not exists(
    select 1
    from public.business_locations
    where id = p_location_id
      and tenant_id = p_tenant_id
      and active
  ) then
    raise exception 'Invalid location';
  end if;

  if p_app_type = 'pos' then
    select coalesce(array_agg(distinct x),'{}'::text[])
    into v_modules
    from unnest(coalesce(p_module_keys,'{}'::text[])) x
    where x in (
      'sales',
      'inventory',
      'customers',
      'suppliers',
      'purchases',
      'expenses',
      'restaurant',
      'logs',
      'cashier_shifts',
      'notifications',
      'tasks',
      'support',
      'terminal_day'
    )
    and exists(
      select 1
      from public.tenant_modules tm
      where tm.tenant_id = p_tenant_id
        and tm.module_key = x
        and tm.enabled
    );
  else
    v_modules := '{}'::text[];
  end if;

  if nullif(upper(trim(p_invoice_prefix)),'') is not null then
    v_prefix := upper(trim(p_invoice_prefix));
  else
    select
      coalesce(
        max(
          nullif(
            regexp_replace(
              coalesce(d.invoice_prefix,''),
              '[^0-9]',
              '',
              'g'
            ),
            ''
          )::int
        ),
        0
      ) + 1
    into v_no
    from public.business_devices d
    where d.tenant_id = p_tenant_id
      and d.app_type = p_app_type
      and d.status <> 'revoked';

    v_prefix := upper(p_app_type) || lpad(v_no::text,2,'0');
  end if;

  if exists(
    select 1
    from public.business_devices d
    where d.tenant_id = p_tenant_id
      and d.status <> 'revoked'
      and upper(coalesce(d.invoice_prefix,'')) = v_prefix
  ) then
    raise exception 'Terminal invoice prefix is already in use';
  end if;

  insert into public.business_devices(
    id,
    tenant_id,
    location_id,
    device_code,
    name,
    app_type,
    platform_hint,
    status,
    activation_hash,
    activation_expires_at,
    allowed_modules,
    invoice_prefix,
    activation_count
  )
  values(
    v_id,
    p_tenant_id,
    p_location_id,
    upper(p_app_type) || '-' ||
      upper(substr(replace(v_id::text,'-',''),1,8)),
    coalesce(nullif(trim(p_name),''),'System'),
    p_app_type,
    nullif(trim(p_platform_hint),''),
    'pending',
    null,
    null,
    v_modules,
    v_prefix,
    0
  );

  perform private.business_audit_write(
    p_tenant_id,
    'system.create',
    'business_device',
    v_id,
    v_prefix,
    null::jsonb,
    jsonb_build_object(
      'location_id', p_location_id,
      'app_type', p_app_type
    )
  );

  return jsonb_build_object(
    'device_id', v_id,
    'status', 'pending',
    'invoice_prefix', v_prefix,
    'allowed_modules', v_modules
  );
end
$$;


--
-- Name: platform_system_create_v471(uuid, uuid, text, text, text, text[], text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_system_create_v471(p_tenant_id uuid, p_location_id uuid, p_name text, p_app_type text, p_platform_hint text DEFAULT NULL::text, p_module_keys text[] DEFAULT '{}'::text[], p_invoice_prefix text DEFAULT NULL::text, p_system_role text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
declare v_id uuid:=gen_random_uuid();v_modules text[]:='{}'::text[];v_prefix text;v_device_code text;v_role text;
begin
  if not private.platform_v2_has_role('super_admin') and not private.platform_v2_has_role('support_admin') then raise exception 'Platform admin required';end if;
  if p_app_type not in('client','pos') then raise exception 'Invalid app type';end if;
  if not exists(select 1 from public.business_locations where id=p_location_id and tenant_id=p_tenant_id and active) then raise exception 'Target store/location is not active';end if;
  v_role:=coalesce(nullif(trim(p_system_role),''),case when p_app_type='pos' then 'pos' else 'office' end);
  if p_app_type='pos' and v_role<>'pos' then raise exception 'POS systems must use POS role';end if;
  if p_app_type='client' and v_role not in('back_office','office','inventory') then raise exception 'Invalid Client system role';end if;
  if p_app_type='pos' then
    select coalesce(array_agg(distinct x),'{}'::text[]) into v_modules from unnest(coalesce(p_module_keys,'{}'::text[])) x
    where x in('sales','inventory','customers','suppliers','purchases','expenses','restaurant','logs','cashier_shifts','notifications','tasks','support','terminal_day')
      and exists(select 1 from public.tenant_modules tm where tm.tenant_id=p_tenant_id and tm.module_key=x and tm.enabled);
    if coalesce(array_length(v_modules,1),0)=0 then raise exception 'Select at least one enabled POS module';end if;
    if nullif(upper(trim(coalesce(p_invoice_prefix,''))),'') is null then v_prefix:=private.v500_next_pos_invoice_prefix(p_tenant_id);
    else
      perform 1 from public.tenants where id=p_tenant_id for update;v_prefix:=upper(trim(p_invoice_prefix));
      if exists(select 1 from public.business_devices d where d.tenant_id=p_tenant_id and d.app_type='pos' and upper(trim(coalesce(d.invoice_prefix,'')))=v_prefix) then raise exception 'Terminal invoice prefix is already in use';end if;
    end if;
  else v_prefix:=null;end if;
  v_device_code:=upper(p_app_type)||'-'||upper(substr(replace(v_id::text,'-',''),1,8));
  insert into public.business_devices(id,tenant_id,location_id,device_code,name,app_type,platform_hint,status,allowed_modules,invoice_prefix,system_role,activation_count)
  values(v_id,p_tenant_id,p_location_id,v_device_code,coalesce(nullif(trim(p_name),''),'System'),p_app_type,nullif(trim(p_platform_hint),''),'pending',v_modules,v_prefix,v_role,0);
  perform private.business_audit_write_v471(p_tenant_id,'system.create','business_device',v_id,v_device_code,null::jsonb,jsonb_build_object('location_id',p_location_id,'app_type',p_app_type,'system_role',v_role,'modules',v_modules,'invoice_prefix',v_prefix));
  return jsonb_build_object('device_id',v_id,'device_code',v_device_code,'status','pending','location_id',p_location_id,'invoice_prefix',v_prefix,'allowed_modules',v_modules,'system_role',v_role);
end $$;


--
-- Name: platform_system_deactivate_v46(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_system_deactivate_v46(p_tenant_id uuid, p_device_id uuid, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v_code text;begin
  if not private.platform_v2_has_role('super_admin') and not private.platform_v2_has_role('support_admin') then raise exception 'Platform admin required';end if;
  select device_code into v_code from public.business_devices where id=p_device_id and tenant_id=p_tenant_id for update;
  if v_code is null then raise exception 'System not found';end if;
  update public.system_installations set status='inactive',deactivated_at=now(),deactivation_reason=nullif(trim(coalesce(p_reason,'')),'')
  where tenant_id=p_tenant_id and system_id=p_device_id and status='active';
  update public.business_devices set status='inactive',installation_id=null,device_secret_hash=null,last_seen_at=null,
    deactivated_at=now(),deactivated_by=auth.uid(),deactivation_reason=nullif(trim(coalesce(p_reason,'')),''),updated_at=now()
  where id=p_device_id and tenant_id=p_tenant_id and status='active';
  perform private.business_audit_write_v471(p_tenant_id,'system.deactivate','business_device',p_device_id,v_code,null::jsonb,jsonb_build_object('reason',nullif(trim(coalesce(p_reason,'')),'')));
end$$;


--
-- Name: platform_system_delete_v471(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_system_delete_v471(p_tenant_id uuid, p_system_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare d public.business_devices%rowtype;v_has_history boolean:=false;
begin
  if not private.platform_v2_has_role('super_admin') and not private.platform_v2_has_role('support_admin') then raise exception 'Platform admin required';end if;
  select * into d from public.business_devices where id=p_system_id and tenant_id=p_tenant_id for update;
  if not found then raise exception 'System not found';end if;

  select exists(select 1 from public.document_origins where tenant_id=p_tenant_id and device_id=p_system_id)
      or exists(select 1 from public.cashier_shifts where tenant_id=p_tenant_id and device_id=p_system_id)
      or exists(select 1 from public.system_installations where tenant_id=p_tenant_id and system_id=p_system_id)
  into v_has_history;

  delete from public.pos_held_sales where tenant_id=p_tenant_id and device_id=p_system_id;
  update public.system_installations set status='revoked',deactivated_at=coalesce(deactivated_at,now()),
    deactivation_reason=coalesce(nullif(trim(coalesce(p_reason,'')),''),'System removed from Admin')
  where tenant_id=p_tenant_id and system_id=p_system_id and status<>'revoked';

  if v_has_history then
    update public.business_devices set status='revoked',installation_id=null,device_secret_hash=null,activation_hash=null,
      activation_expires_at=null,last_seen_at=null,deactivated_at=coalesce(deactivated_at,now()),deactivation_reason=coalesce(nullif(trim(coalesce(p_reason,'')),''),'System removed from Admin'),updated_at=now()
    where id=p_system_id;
    perform private.business_audit_write_v471(p_tenant_id,'system.archive','business_device',p_system_id,d.device_code,null::jsonb,jsonb_build_object('reason',p_reason));
    return jsonb_build_object('success',true,'action','archived','system_id',p_system_id,'message','System has transaction/installation history and was safely archived.');
  end if;

  delete from public.business_devices where id=p_system_id and tenant_id=p_tenant_id;
  perform private.business_audit_write_v471(p_tenant_id,'system.delete','business_device',p_system_id,d.device_code,null::jsonb,jsonb_build_object('reason',p_reason));
  return jsonb_build_object('success',true,'action','deleted','system_id',p_system_id,'message','Unused system permanently deleted.');
end $$;


--
-- Name: platform_system_update_v471(uuid, uuid, uuid, text, text[], text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_system_update_v471(p_tenant_id uuid, p_system_id uuid, p_location_id uuid, p_name text, p_module_keys text[], p_invoice_prefix text, p_system_role text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  d public.business_devices%rowtype;
  v_modules text[];
  v_role text;
  v_old_location uuid;
  v_prefix text;
begin
  if not private.platform_v2_has_role('super_admin') and not private.platform_v2_has_role('support_admin') then raise exception 'Platform admin required';end if;
  select * into d from public.business_devices where id=p_system_id and tenant_id=p_tenant_id for update;
  if not found then raise exception 'System not found';end if;
  if not exists(select 1 from public.business_locations where id=p_location_id and tenant_id=p_tenant_id and active) then raise exception 'Target store/location is not active';end if;
  v_old_location:=d.location_id;
  v_role:=coalesce(nullif(trim(p_system_role),''),d.system_role,case when d.app_type='pos' then 'pos' else 'office' end);
  if d.app_type='pos' and v_role<>'pos' then raise exception 'POS systems must use POS role';end if;
  if d.app_type='client' and v_role not in('back_office','office','inventory') then raise exception 'Invalid Client system role';end if;

  if d.location_id<>p_location_id then
    if exists(select 1 from public.cashier_shifts where tenant_id=p_tenant_id and device_id=p_system_id and status='open') then raise exception 'Close the cashier shift before moving this system to another store';end if;
    if exists(select 1 from public.pos_held_sales where tenant_id=p_tenant_id and device_id=p_system_id) then raise exception 'Resume or remove held invoices before moving this POS to another store';end if;
  end if;

  if d.app_type='pos' then
    select coalesce(array_agg(distinct x),'{}'::text[]) into v_modules
    from unnest(coalesce(p_module_keys,'{}'::text[]))x
    where x in('sales','inventory','customers','suppliers','purchases','expenses','restaurant','logs','cashier_shifts','notifications','tasks','support','terminal_day')
      and exists(select 1 from public.tenant_modules tm where tm.tenant_id=p_tenant_id and tm.module_key=x and tm.enabled);
    if coalesce(array_length(v_modules,1),0)=0 then raise exception 'Select at least one enabled POS module'; end if;
    v_prefix:=coalesce(
      nullif(upper(trim(coalesce(p_invoice_prefix,''))),''),
      nullif(upper(trim(coalesce(d.invoice_prefix,''))),''),
      private.v500_next_pos_invoice_prefix(p_tenant_id)
    );
    if v_prefix is distinct from nullif(upper(trim(coalesce(d.invoice_prefix,''))),'') then
      if exists(
        select 1 from public.document_origins o
        where o.tenant_id=p_tenant_id and o.device_id=p_system_id
      ) then
        raise exception 'Terminal invoice prefix cannot be changed after this POS has transaction history';
      end if;
      if exists(
        select 1 from public.business_devices x
        where x.tenant_id=p_tenant_id and x.app_type='pos' and x.id<>p_system_id
          and upper(trim(coalesce(x.invoice_prefix,'')))=v_prefix
      ) then
        raise exception 'Terminal invoice prefix is already in use';
      end if;
    end if;
  else
    v_modules:='{}'::text[];
    v_prefix:=d.invoice_prefix;
  end if;

  update public.business_devices
  set location_id=p_location_id,
      name=coalesce(nullif(trim(p_name),''),name),
      allowed_modules=v_modules,
      invoice_prefix=v_prefix,
      system_role=v_role,
      updated_at=now()
  where id=p_system_id;

  perform private.business_audit_write_v471(
    p_tenant_id,'system.update','business_device',p_system_id,d.device_code,null::jsonb,
    jsonb_build_object('from_location_id',v_old_location,'to_location_id',p_location_id,'system_role',v_role,'modules',v_modules,'invoice_prefix',v_prefix)
  );
  return jsonb_build_object('success',true,'system_id',p_system_id,'location_id',p_location_id,'system_role',v_role,'allowed_modules',v_modules,'invoice_prefix',v_prefix);
end $$;


--
-- Name: platform_systems_list_v46(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_systems_list_v46(p_tenant_id uuid) RETURNS TABLE(id uuid, location_id uuid, location_name text, location_code text, device_code text, tracking_code text, name text, app_type text, platform_hint text, status text, allowed_modules text[], invoice_prefix text, installation_id text, activated_at timestamp with time zone, activation_issued_at timestamp with time zone, last_seen_at timestamp with time zone, deactivated_at timestamp with time zone, deactivation_reason text, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.platform_v2_is_admin() then raise exception 'Platform admin required'; end if;
  return query
  select d.id,d.location_id,l.name,l.location_code,d.device_code,d.tracking_code,d.name,d.app_type,d.platform_hint,
         d.status,d.allowed_modules,d.invoice_prefix,d.installation_id,d.activated_at,d.activation_issued_at,d.last_seen_at,
         d.deactivated_at,d.deactivation_reason,d.created_at
  from public.business_devices d
  join public.business_locations l on l.id=d.location_id
  where d.tenant_id=p_tenant_id
  order by l.sort_order,l.name,d.app_type,d.created_at;
end $$;


--
-- Name: platform_systems_list_v471(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_systems_list_v471(p_tenant_id uuid) RETURNS TABLE(id uuid, location_id uuid, location_name text, location_code text, device_code text, tracking_code text, name text, app_type text, system_role text, platform_hint text, status text, allowed_modules text[], invoice_prefix text, installation_id text, activated_at timestamp with time zone, activation_issued_at timestamp with time zone, last_seen_at timestamp with time zone, deactivated_at timestamp with time zone, deactivation_reason text, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.platform_v2_is_admin() then raise exception 'Platform admin required';end if;
  return query select d.id,d.location_id,l.name,l.location_code,d.device_code,d.tracking_code,d.name,d.app_type,
    coalesce(d.system_role,case when d.app_type='pos' then 'pos' else 'office' end),d.platform_hint,d.status,d.allowed_modules,d.invoice_prefix,
    d.installation_id,d.activated_at,d.activation_issued_at,d.last_seen_at,d.deactivated_at,d.deactivation_reason,d.created_at
  from public.business_devices d join public.business_locations l on l.id=d.location_id
  where d.tenant_id=p_tenant_id order by l.sort_order,l.name,d.app_type,d.created_at;
end $$;


--
-- Name: platform_template_upsert(uuid, text, text, text, text, boolean, integer, text[], jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_template_upsert(p_id uuid, p_key text, p_name text, p_business_type text, p_description text, p_is_active boolean, p_sort_order integer, p_module_keys text[], p_settings jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_id uuid;
begin
  if not private.platform_v2_has_role('technical_admin') then raise exception 'Technical admin access required'; end if;
  if coalesce(trim(p_key),'')='' or coalesce(trim(p_name),'')='' then raise exception 'Template key and name are required'; end if;
  if p_id is null then
    insert into public.business_templates(key,name,business_type,description,is_active,is_system,sort_order,settings)
    values(trim(p_key),trim(p_name),coalesce(nullif(trim(p_business_type),''),'Custom'),nullif(trim(p_description),''),coalesce(p_is_active,true),false,coalesce(p_sort_order,100),coalesce(p_settings,'{}'::jsonb))
    on conflict(key) do update set name=excluded.name,business_type=excluded.business_type,description=excluded.description,is_active=excluded.is_active,sort_order=excluded.sort_order,settings=excluded.settings,updated_at=now()
    returning id into v_id;
  else
    update public.business_templates set name=trim(p_name),business_type=coalesce(nullif(trim(p_business_type),''),'Custom'),description=nullif(trim(p_description),''),is_active=coalesce(p_is_active,true),sort_order=coalesce(p_sort_order,100),settings=coalesce(p_settings,settings),updated_at=now() where id=p_id returning id into v_id;
    if v_id is null then raise exception 'Template not found'; end if;
  end if;

  delete from public.business_template_modules where template_id=v_id;
  insert into public.business_template_modules(template_id,module_key)
  select v_id,x from unnest(coalesce(p_module_keys,array[]::text[])) x where exists(select 1 from public.modules m where m.key=x and m.is_active)
  on conflict do nothing;
  insert into public.business_template_modules(template_id,module_key) values(v_id,'dashboard') on conflict do nothing;
  perform private.platform_audit_write('template.upsert','business_template',v_id::text,null,jsonb_build_object('key',p_key));
  return v_id;
end $$;


--
-- Name: platform_templates_list(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_templates_list() RETURNS TABLE(id uuid, key text, name text, business_type text, description text, is_active boolean, is_system boolean, sort_order integer, module_keys text[], settings jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if not private.platform_v2_is_admin() then raise exception 'Platform admin access required'; end if;
  return query select bt.id,bt.key,bt.name,bt.business_type,bt.description,bt.is_active,bt.is_system,bt.sort_order,
    coalesce((select array_agg(btm.module_key order by m.sort_order,m.name) from public.business_template_modules btm join public.modules m on m.key=btm.module_key where btm.template_id=bt.id),array[]::text[]),bt.settings
  from public.business_templates bt order by bt.sort_order,bt.name;
end $$;


--
-- Name: platform_tenant_invoice_template_set(uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_tenant_invoice_template_set(p_tenant_id uuid, p_paper_type text, p_template_id uuid, p_overrides jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.platform_v2_is_admin() then raise exception 'Platform admin required'; end if;
  if not exists(select 1 from public.invoice_templates where id=p_template_id and paper_type=p_paper_type and is_active) then raise exception 'Template not found'; end if;
  insert into public.tenant_invoice_templates(tenant_id,paper_type,template_id,overrides,updated_at,updated_by) values(p_tenant_id,p_paper_type,p_template_id,coalesce(p_overrides,'{}'::jsonb),now(),auth.uid())
  on conflict(tenant_id,paper_type) do update set template_id=excluded.template_id,overrides=excluded.overrides,updated_at=now(),updated_by=auth.uid();
end $$;


--
-- Name: platform_tenant_subscription_get(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_tenant_subscription_get(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v jsonb;
begin
  if not private.platform_v2_is_admin() then raise exception 'Platform admin access required'; end if;
  select jsonb_build_object('tenant_id',p_tenant_id,'plan_id',sp.id,'plan_key',sp.key,'plan_name',sp.name,'status',ts.status,'billing_cycle',ts.billing_cycle,'starts_at',ts.starts_at,'ends_at',ts.ends_at,'trial_ends_at',ts.trial_ends_at,'limit_overrides',ts.limit_overrides)
  into v from public.tenant_subscriptions ts join public.subscription_plans sp on sp.id=ts.plan_id where ts.tenant_id=p_tenant_id;
  return coalesce(v,jsonb_build_object('tenant_id',p_tenant_id,'status','none','billing_cycle','monthly','limit_overrides','{}'::jsonb));
end $$;


--
-- Name: platform_tenant_subscription_set(uuid, uuid, text, text, timestamp with time zone, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_tenant_subscription_set(p_tenant_id uuid, p_plan_id uuid, p_status text, p_billing_cycle text, p_ends_at timestamp with time zone, p_trial_ends_at timestamp with time zone, p_limit_overrides jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if not private.platform_v2_has_role('billing_admin') then raise exception 'Billing admin access required'; end if;
  if not exists(select 1 from public.tenants where id=p_tenant_id) then raise exception 'Tenant not found'; end if;
  if not exists(select 1 from public.subscription_plans where id=p_plan_id and is_active) then raise exception 'Plan not found or disabled'; end if;
  if p_status not in ('trial','active','past_due','suspended','cancelled') then raise exception 'Invalid subscription status'; end if;
  if p_billing_cycle not in ('monthly','yearly','custom') then raise exception 'Invalid billing cycle'; end if;
  insert into public.tenant_subscriptions(tenant_id,plan_id,status,billing_cycle,starts_at,ends_at,trial_ends_at,limit_overrides)
  values(p_tenant_id,p_plan_id,p_status,p_billing_cycle,now(),p_ends_at,p_trial_ends_at,coalesce(p_limit_overrides,'{}'::jsonb))
  on conflict(tenant_id) do update set plan_id=excluded.plan_id,status=excluded.status,billing_cycle=excluded.billing_cycle,ends_at=excluded.ends_at,trial_ends_at=excluded.trial_ends_at,limit_overrides=excluded.limit_overrides,updated_at=now();
  perform private.platform_audit_write('tenant_subscription.set','tenant_subscription',p_tenant_id::text,p_tenant_id,jsonb_build_object('plan_id',p_plan_id,'status',p_status,'billing_cycle',p_billing_cycle));
end $$;


--
-- Name: platform_tenant_ui_design_get_v43(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_tenant_ui_design_get_v43(p_tenant_id uuid, p_app_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v jsonb;
begin
  if not private.platform_v2_is_admin() then raise exception 'Platform admin access required'; end if;
  if p_app_key not in ('client','pos') then raise exception 'Invalid app key'; end if;
  select jsonb_build_object(
    'template_id',t.id,'key',t.key,'name',t.name,'app_key',t.app_key,
    'config',t.config || coalesce(x.overrides,'{}'::jsonb),'base_config',t.config,'overrides',coalesce(x.overrides,'{}'::jsonb)
  ) into v
  from public.tenant_ui_designs x join public.ui_design_templates t on t.id=x.template_id
  where x.tenant_id=p_tenant_id and x.app_key=p_app_key;
  return coalesce(v,'{}'::jsonb);
end $$;


--
-- Name: platform_tenant_ui_design_set_v43(uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_tenant_ui_design_set_v43(p_tenant_id uuid, p_app_key text, p_template_id uuid, p_overrides jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if not private.platform_v2_is_admin() then raise exception 'Platform admin access required'; end if;
  if p_app_key not in ('client','pos') then raise exception 'Invalid app key'; end if;
  if not exists(select 1 from public.ui_design_templates where id=p_template_id and app_key=p_app_key and is_active) then
    raise exception 'Active design template not found for this app';
  end if;
  insert into public.tenant_ui_designs(tenant_id,app_key,template_id,overrides,updated_at,updated_by)
  values(p_tenant_id,p_app_key,p_template_id,coalesce(p_overrides,'{}'::jsonb),now(),auth.uid())
  on conflict(tenant_id,app_key) do update set template_id=excluded.template_id,overrides=excluded.overrides,updated_at=now(),updated_by=auth.uid();
  perform private.platform_audit_write('tenant.ui_design.set','tenant',p_tenant_id::text,p_tenant_id,jsonb_build_object('app_key',p_app_key,'template_id',p_template_id));
end $$;


--
-- Name: platform_transaction_correct_v45(uuid, text, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_transaction_correct_v45(p_tenant_id uuid, p_entity_type text, p_entity_id uuid, p_patch jsonb, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_type text:=lower(p_entity_type);v_before jsonb;v_after jsonb;v_loc uuid;v_paid numeric:=0;x jsonb;r record;old_qty numeric;new_qty numeric;delta numeric;new_price numeric;new_disc numeric;new_tax numeric;new_sub numeric;new_taxable numeric;new_tax_amount numeric;new_line numeric;unit_cost numeric;begin
  if not private.platform_v2_has_role('super_admin') and not private.platform_v2_has_role('technical_admin') then raise exception 'Super/technical admin required';end if;
  if trim(coalesce(p_reason,''))='' then raise exception 'Correction reason is required';end if;
  v_before:=public.platform_transaction_detail_v45(p_tenant_id,v_type,p_entity_id);
  select location_id into v_loc from public.document_origins where tenant_id=p_tenant_id and entity_type=v_type and entity_id=p_entity_id;

  if v_type='sale' then
    if (p_patch ? 'customer_id') and not exists(select 1 from public.customers where id=(p_patch->>'customer_id')::uuid and tenant_id=p_tenant_id) then raise exception 'Customer not found';end if;
    update public.sales set
      customer_id=case when p_patch?'customer_id' then (p_patch->>'customer_id')::uuid else customer_id end,
      due_date=case when p_patch?'due_date' then nullif(p_patch->>'due_date','')::date else due_date end,
      notes=case when p_patch?'notes' then p_patch->>'notes' else notes end
    where id=p_entity_id and tenant_id=p_tenant_id;
    if p_patch?'items' then
      if exists(select 1 from public.sales_returns where sale_id=p_entity_id) then raise exception 'Item/value edits are blocked after a return. Use a correcting return/new invoice.';end if;
      select coalesce(sum(amount),0) into v_paid from public.sale_payments where sale_id=p_entity_id;
      perform private.v4_reverse_source_journal(p_tenant_id,'sale',p_entity_id,'sale_edit_reverse','Admin correction sale');
      update public.journal_entries set status='reversed' where tenant_id=p_tenant_id and source_type='sale' and source_id=p_entity_id and status='posted';
      for x in select value from jsonb_array_elements(p_patch->'items') loop
        select quantity into old_qty from public.sale_items where id=(x->>'item_id')::uuid and sale_id=p_entity_id for update;
        if old_qty is null then raise exception 'Sale item not found';end if;
        new_qty:=coalesce(nullif(x->>'quantity','')::numeric,old_qty);if new_qty<=0 then raise exception 'Quantity must be positive. Use Return/Void to remove an item.';end if;
        select coalesce(cost_total/nullif(quantity,0),0),unit_price,discount_amount,tax_rate into unit_cost,new_price,new_disc,new_tax from public.sale_items where id=(x->>'item_id')::uuid;
        new_price:=coalesce(nullif(x->>'unit_price','')::numeric,new_price);new_disc:=coalesce(nullif(x->>'discount_amount','')::numeric,new_disc);new_tax:=coalesce(nullif(x->>'tax_rate','')::numeric,new_tax);
        delta:=old_qty-new_qty;
        if abs(delta)>0.0001 and exists(select 1 from public.product_variants pv join public.products p on p.id=pv.product_id where pv.id=(select variant_id from public.sale_items where id=(x->>'item_id')::uuid) and p.item_type='stock') then
          if delta<0 and coalesce((select quantity-reserved_quantity-damaged_quantity-quarantine_quantity from public.location_stock_balances where tenant_id=p_tenant_id and location_id=v_loc and variant_id=(select variant_id from public.sale_items where id=(x->>'item_id')::uuid)),0)<abs(delta) then raise exception 'Insufficient branch stock for correction';end if;
          perform public.inventory_adjust_stock(p_tenant_id,(select variant_id from public.sale_items where id=(x->>'item_id')::uuid),delta,'Admin sale correction');
          perform private.v4_location_stock_apply(p_tenant_id,v_loc,(select variant_id from public.sale_items where id=(x->>'item_id')::uuid),delta,'adjustment','sale',p_entity_id,null,'Platform Admin correction • '||trim(p_reason),null,false);
        end if;
        new_sub:=round(new_qty*new_price,2);new_taxable:=greatest(new_sub-new_disc,0);new_tax_amount:=round(new_taxable*new_tax/100.0,2);new_line:=new_taxable+new_tax_amount;
        update public.sale_items set quantity=new_qty,unit_price=new_price,discount_amount=new_disc,tax_rate=new_tax,subtotal=new_sub,taxable_amount=new_taxable,tax_amount=new_tax_amount,line_total=new_line,cost_total=round(unit_cost*new_qty,2),gross_profit=new_taxable-round(unit_cost*new_qty,2) where id=(x->>'item_id')::uuid and sale_id=p_entity_id;
      end loop;
      update public.sales s set subtotal=q.subtotal,discount_total=q.discount_total,taxable_total=q.taxable_total,tax_total=q.tax_total,grand_total=q.line_total+s.additional_charges,cost_total=q.cost_total,gross_profit=q.gross_profit
      from (select sale_id,sum(subtotal) subtotal,sum(discount_amount) discount_total,sum(taxable_amount) taxable_total,sum(tax_amount) tax_total,sum(line_total) line_total,sum(cost_total) cost_total,sum(gross_profit) gross_profit from public.sale_items where sale_id=p_entity_id group by sale_id) q where s.id=q.sale_id;
      if v_paid>(select grand_total from public.sales where id=p_entity_id)+0.005 then raise exception 'Corrected total would be below payments already received';end if;
      perform private.v4_accounting_post_document(p_tenant_id,'sale',p_entity_id);
    end if;
  elsif v_type='purchase' then
    if (p_patch?'supplier_id') and not exists(select 1 from public.suppliers where id=(p_patch->>'supplier_id')::uuid and tenant_id=p_tenant_id) then raise exception 'Supplier not found';end if;
    update public.purchases set
      supplier_id=case when p_patch?'supplier_id' then (p_patch->>'supplier_id')::uuid else supplier_id end,
      supplier_invoice_number=case when p_patch?'supplier_invoice_number' then p_patch->>'supplier_invoice_number' else supplier_invoice_number end,
      due_date=case when p_patch?'due_date' then nullif(p_patch->>'due_date','')::date else due_date end,
      notes=case when p_patch?'notes' then p_patch->>'notes' else notes end
    where id=p_entity_id and tenant_id=p_tenant_id;
    if p_patch?'items' then
      if exists(select 1 from public.purchase_returns where purchase_id=p_entity_id) then raise exception 'Item/value edits are blocked after a return. Use Purchase Return/new bill.';end if;
      select coalesce(sum(amount),0) into v_paid from public.purchase_payments where purchase_id=p_entity_id;
      perform private.v4_reverse_source_journal(p_tenant_id,'purchase',p_entity_id,'purchase_edit_reverse','Admin correction purchase');
      update public.journal_entries set status='reversed' where tenant_id=p_tenant_id and source_type='purchase' and source_id=p_entity_id and status='posted';
      for x in select value from jsonb_array_elements(p_patch->'items') loop
        select quantity,unit_cost,discount_amount,tax_rate into old_qty,new_price,new_disc,new_tax from public.purchase_items where id=(x->>'item_id')::uuid and purchase_id=p_entity_id for update;
        if old_qty is null then raise exception 'Purchase item not found';end if;
        new_qty:=coalesce(nullif(x->>'quantity','')::numeric,old_qty);if new_qty<=0 then raise exception 'Quantity must be positive. Use Purchase Return/Void to remove an item.';end if;
        new_price:=coalesce(nullif(x->>'unit_cost','')::numeric,new_price);new_disc:=coalesce(nullif(x->>'discount_amount','')::numeric,new_disc);new_tax:=coalesce(nullif(x->>'tax_rate','')::numeric,new_tax);
        delta:=new_qty-old_qty;
        if abs(delta)>0.0001 and exists(select 1 from public.product_variants pv join public.products p on p.id=pv.product_id where pv.id=(select variant_id from public.purchase_items where id=(x->>'item_id')::uuid) and p.item_type='stock') then
          if delta<0 and coalesce((select quantity-reserved_quantity-damaged_quantity-quarantine_quantity from public.location_stock_balances where tenant_id=p_tenant_id and location_id=v_loc and variant_id=(select variant_id from public.purchase_items where id=(x->>'item_id')::uuid)),0)<abs(delta) then raise exception 'Cannot reduce purchase because stock has already been consumed';end if;
          perform public.inventory_adjust_stock(p_tenant_id,(select variant_id from public.purchase_items where id=(x->>'item_id')::uuid),delta,'Admin purchase correction');
          perform private.v4_location_stock_apply(p_tenant_id,v_loc,(select variant_id from public.purchase_items where id=(x->>'item_id')::uuid),delta,'adjustment','purchase',p_entity_id,null,'Platform Admin correction • '||trim(p_reason),null,false);
        end if;
        new_sub:=round(new_qty*new_price,2);new_taxable:=greatest(new_sub-new_disc,0);new_tax_amount:=round(new_taxable*new_tax/100.0,2);new_line:=new_taxable+new_tax_amount;
        update public.purchase_items set quantity=new_qty,unit_cost=new_price,discount_amount=new_disc,tax_rate=new_tax,subtotal=new_sub,taxable_amount=new_taxable,tax_amount=new_tax_amount,line_total=new_line where id=(x->>'item_id')::uuid and purchase_id=p_entity_id;
      end loop;
      update public.purchases p set subtotal=q.subtotal,discount_total=q.discount_total,taxable_total=q.taxable_total,tax_total=q.tax_total,grand_total=q.line_total+p.additional_charges
      from (select purchase_id,sum(subtotal) subtotal,sum(discount_amount) discount_total,sum(taxable_amount) taxable_total,sum(tax_amount) tax_total,sum(line_total) line_total from public.purchase_items where purchase_id=p_entity_id group by purchase_id) q where p.id=q.purchase_id;
      if v_paid>(select grand_total from public.purchases where id=p_entity_id)+0.005 then raise exception 'Corrected total would be below payments already made';end if;
      perform private.v4_accounting_post_document(p_tenant_id,'purchase',p_entity_id);
    end if;
  elsif v_type='expense' then
    perform private.v4_reverse_source_journal(p_tenant_id,'expense',p_entity_id,'expense_edit_reverse','Admin correction expense');
    update public.journal_entries set status='reversed' where tenant_id=p_tenant_id and source_type='expense' and source_id=p_entity_id and status='posted';
    update public.expenses set
      expense_date=case when p_patch?'expense_date' then (p_patch->>'expense_date')::date else expense_date end,
      payee=case when p_patch?'payee' then p_patch->>'payee' else payee end,
      description=case when p_patch?'description' then p_patch->>'description' else description end,
      total_amount=case when p_patch?'total_amount' then (p_patch->>'total_amount')::numeric else total_amount end,
      tax_amount=case when p_patch?'tax_amount' then (p_patch->>'tax_amount')::numeric else tax_amount end,
      payment_method=case when p_patch?'payment_method' then p_patch->>'payment_method' else payment_method end,
      updated_at=now()
    where id=p_entity_id and tenant_id=p_tenant_id;
    perform private.v4_accounting_post_document(p_tenant_id,'expense',p_entity_id);
  else raise exception 'Unsupported entity type';end if;

  v_after:=public.platform_transaction_detail_v45(p_tenant_id,v_type,p_entity_id);
  insert into public.transaction_corrections(tenant_id,entity_type,entity_id,correction_type,reason,created_by,metadata)
  values(p_tenant_id,v_type,p_entity_id,'edit',trim(p_reason),auth.uid(),jsonb_build_object('before',v_before,'patch',p_patch,'after',v_after,'platform_admin',true));
  perform private.platform_audit_write('transaction.correct',v_type,p_entity_id::text,p_tenant_id,jsonb_build_object('reason',trim(p_reason),'patch',p_patch));
  return v_after;
end $$;


--
-- Name: platform_transaction_detail_v45(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_transaction_detail_v45(p_tenant_id uuid, p_entity_type text, p_entity_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v jsonb;v_type text:=lower(coalesce(p_entity_type,''));
begin
  if not private.platform_v2_is_admin() then raise exception 'Platform admin required';end if;
  if v_type='sale' then
    select jsonb_build_object('entity',to_jsonb(s),'party',to_jsonb(c),'origin',to_jsonb(o),
      'items',coalesce((select jsonb_agg(to_jsonb(i)) from public.sale_items i where i.sale_id=s.id),'[]'::jsonb),
      'payments',coalesce((select jsonb_agg(to_jsonb(p)) from public.sale_payments p where p.sale_id=s.id),'[]'::jsonb)) into v
    from public.sales s join public.customers c on c.id=s.customer_id
    left join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='sale' and o.entity_id=s.id
    where s.id=p_entity_id and s.tenant_id=p_tenant_id;
  elsif v_type='purchase' then
    select jsonb_build_object('entity',to_jsonb(p),'party',to_jsonb(sp),'origin',to_jsonb(o),
      'items',coalesce((select jsonb_agg(to_jsonb(i)) from public.purchase_items i where i.purchase_id=p.id),'[]'::jsonb),
      'payments',coalesce((select jsonb_agg(to_jsonb(py)) from public.purchase_payments py where py.purchase_id=p.id),'[]'::jsonb)) into v
    from public.purchases p join public.suppliers sp on sp.id=p.supplier_id
    left join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='purchase' and o.entity_id=p.id
    where p.id=p_entity_id and p.tenant_id=p_tenant_id;
  elsif v_type='expense' then
    select jsonb_build_object('entity',to_jsonb(e),'origin',to_jsonb(o),'items','[]'::jsonb,'payments','[]'::jsonb) into v
    from public.expenses e
    left join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='expense' and o.entity_id=e.id
    where e.id=p_entity_id and e.tenant_id=p_tenant_id;
  elsif v_type='sales_return' then
    select jsonb_build_object(
      'entity',to_jsonb(r),'party',to_jsonb(c),
      'origin',jsonb_build_object('location_id',r.location_id,'device_id',r.device_id,'source_type','sale','source_id',r.sale_id,'source_number',s.sale_number),
      'items',coalesce((select jsonb_agg(to_jsonb(ri)||jsonb_build_object('product_name',pr.name,'sku',pv.sku,'part_number',pv.part_number) order by ri.id)
        from public.sales_return_items ri join public.product_variants pv on pv.id=ri.variant_id join public.products pr on pr.id=pv.product_id where ri.sales_return_id=r.id),'[]'::jsonb),
      'payments','[]'::jsonb
    ) into v
    from public.sales_returns r join public.sales s on s.id=r.sale_id join public.customers c on c.id=s.customer_id
    where r.id=p_entity_id and r.tenant_id=p_tenant_id;
  elsif v_type='purchase_return' then
    select jsonb_build_object(
      'entity',to_jsonb(r),'party',to_jsonb(sp),
      'origin',jsonb_build_object('location_id',r.location_id,'device_id',r.device_id,'source_type','purchase','source_id',r.purchase_id,'source_number',p.purchase_number),
      'items',coalesce((select jsonb_agg(to_jsonb(ri)||jsonb_build_object('product_name',pr.name,'sku',pv.sku,'part_number',pv.part_number) order by ri.id)
        from public.purchase_return_items ri join public.product_variants pv on pv.id=ri.variant_id join public.products pr on pr.id=pv.product_id where ri.purchase_return_id=r.id),'[]'::jsonb),
      'payments','[]'::jsonb
    ) into v
    from public.purchase_returns r join public.purchases p on p.id=r.purchase_id join public.suppliers sp on sp.id=p.supplier_id
    where r.id=p_entity_id and r.tenant_id=p_tenant_id;
  else
    raise exception 'Unsupported entity type';
  end if;
  if v is null then raise exception 'Transaction not found';end if;
  return v;
end $$;


--
-- Name: platform_transaction_void_v44(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_transaction_void_v44(p_tenant_id uuid, p_entity_type text, p_entity_id uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_type text:=lower(coalesce(p_entity_type,''));v_loc uuid;v_ref text;r record;begin
  if not private.platform_v2_has_role('super_admin') and not private.platform_v2_has_role('technical_admin') then raise exception 'Super/technical admin required';end if;
  if trim(coalesce(p_reason,''))='' then raise exception 'Reason is required';end if;

  if v_type='sale' then
    if exists(select 1 from public.sale_payments where sale_id=p_entity_id and amount<>0) then raise exception 'Paid sale cannot be directly voided. Use business return/refund workflow.';end if;
    if exists(select 1 from public.sales_returns where sale_id=p_entity_id) then raise exception 'Sale with returns cannot be voided';end if;
    select o.location_id,s.sale_number into v_loc,v_ref from public.sales s join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='sale' and o.entity_id=s.id where s.id=p_entity_id and s.tenant_id=p_tenant_id for update;
    if v_loc is null then raise exception 'Sale not found or has no branch origin';end if;
    for r in select si.variant_id,si.quantity,pr.item_type from public.sale_items si join public.product_variants pv on pv.id=si.variant_id join public.products pr on pr.id=pv.product_id where si.sale_id=p_entity_id loop
      if r.item_type='stock' then
        perform public.inventory_adjust_stock(p_tenant_id,r.variant_id,r.quantity,'Admin void sale • '||v_ref);
        perform private.v4_location_stock_apply(p_tenant_id,v_loc,r.variant_id,r.quantity,'sale_return','sale',p_entity_id,v_ref,'Platform Admin Void • '||trim(p_reason),null,false);
      end if;
    end loop;
    update public.sales set status='void' where id=p_entity_id and tenant_id=p_tenant_id;
    insert into public.transaction_corrections(tenant_id,entity_type,entity_id,correction_type,reason,created_by,metadata) values(p_tenant_id,'sale',p_entity_id,'void',trim(p_reason),auth.uid(),jsonb_build_object('platform_admin',true));

  elsif v_type='purchase' then
    if exists(select 1 from public.purchase_payments where purchase_id=p_entity_id and amount<>0) then raise exception 'Paid purchase cannot be directly voided. Use business return/refund workflow.';end if;
    if exists(select 1 from public.purchase_returns where purchase_id=p_entity_id) then raise exception 'Purchase with returns cannot be voided';end if;
    select o.location_id,p.purchase_number into v_loc,v_ref from public.purchases p join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='purchase' and o.entity_id=p.id where p.id=p_entity_id and p.tenant_id=p_tenant_id for update;
    if v_loc is null then raise exception 'Purchase not found or has no branch origin';end if;
    for r in select pi.variant_id,pi.quantity,pr.item_type from public.purchase_items pi join public.product_variants pv on pv.id=pi.variant_id join public.products pr on pr.id=pv.product_id where pi.purchase_id=p_entity_id loop
      if r.item_type='stock' then
        if coalesce((select quantity from public.location_stock_balances where tenant_id=p_tenant_id and location_id=v_loc and variant_id=r.variant_id),0)<r.quantity then raise exception 'Cannot void purchase because branch stock has already been consumed';end if;
        perform public.inventory_adjust_stock(p_tenant_id,r.variant_id,-r.quantity,'Admin void purchase • '||v_ref);
        perform private.v4_location_stock_apply(p_tenant_id,v_loc,r.variant_id,-r.quantity,'purchase_return','purchase',p_entity_id,v_ref,'Platform Admin Void • '||trim(p_reason),null,false);
      end if;
    end loop;
    update public.purchases set status='void' where id=p_entity_id and tenant_id=p_tenant_id;
    insert into public.transaction_corrections(tenant_id,entity_type,entity_id,correction_type,reason,created_by,metadata) values(p_tenant_id,'purchase',p_entity_id,'void',trim(p_reason),auth.uid(),jsonb_build_object('platform_admin',true));

  elsif v_type='expense' then
    select expense_number into v_ref from public.expenses where id=p_entity_id and tenant_id=p_tenant_id and status='posted' for update;
    if v_ref is null then raise exception 'Posted expense not found';end if;
    update public.expenses set status='void',updated_at=now() where id=p_entity_id and tenant_id=p_tenant_id;
    begin perform private.v4_reverse_source_journal(p_tenant_id,'expense',p_entity_id,'expense_void','Platform Admin Void '||v_ref); exception when undefined_function then null; end;
  else
    raise exception 'Unsupported entity type';
  end if;
  perform private.platform_audit_write('transaction.void',v_type,p_entity_id::text,p_tenant_id,jsonb_build_object('reason',trim(p_reason),'reference',v_ref));
end $$;


--
-- Name: platform_transactions_list_v44(uuid, date, date, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_transactions_list_v44(p_tenant_id uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_query text DEFAULT NULL::text, p_limit integer DEFAULT 500) RETURNS TABLE(entity_type text, entity_id uuid, reference text, entry_date date, party text, total numeric, paid numeric, balance numeric, status text, location_id uuid, location_name text, device_id uuid, device_name text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare q text:='%'||lower(trim(coalesce(p_query,'')))||'%';lim integer:=greatest(1,least(coalesce(p_limit,500),2000));begin
  if not private.platform_v2_is_admin() then raise exception 'Platform admin required';end if;
  return query
  select z.* from (
    select 'sale'::text,s.id,coalesce(dn.terminal_number,ln.local_number,s.sale_number)::text,s.sale_date,c.name::text,s.grand_total,
      coalesce(py.paid,0)::numeric,greatest(s.grand_total-coalesce(py.paid,0),0)::numeric,s.status::text,o.location_id,l.name::text,o.device_id,d.name::text,s.created_at
    from public.sales s join public.customers c on c.id=s.customer_id
    left join(select sale_id,sum(amount) paid from public.sale_payments group by sale_id) py on py.sale_id=s.id
    left join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='sale' and o.entity_id=s.id
    left join public.business_locations l on l.id=o.location_id left join public.business_devices d on d.id=o.device_id
    left join public.location_document_numbers ln on ln.tenant_id=p_tenant_id and ln.entity_type='sale' and ln.entity_id=s.id
    left join public.device_document_numbers dn on dn.tenant_id=p_tenant_id and dn.entity_type='sale' and dn.entity_id=s.id
    where s.tenant_id=p_tenant_id and (p_from is null or s.sale_date>=p_from) and (p_to is null or s.sale_date<=p_to)
      and (trim(coalesce(p_query,''))='' or lower(coalesce(s.sale_number,'')) like q or lower(coalesce(c.name,'')) like q or lower(coalesce(dn.terminal_number,ln.local_number,'')) like q)
    union all
    select 'purchase'::text,p.id,coalesce(dn.terminal_number,ln.local_number,p.purchase_number)::text,p.purchase_date,sup.name::text,p.grand_total,
      coalesce(py.paid,0)::numeric,greatest(p.grand_total-coalesce(py.paid,0),0)::numeric,p.status::text,o.location_id,l.name::text,o.device_id,d.name::text,p.created_at
    from public.purchases p join public.suppliers sup on sup.id=p.supplier_id
    left join(select purchase_id,sum(amount) paid from public.purchase_payments group by purchase_id) py on py.purchase_id=p.id
    left join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='purchase' and o.entity_id=p.id
    left join public.business_locations l on l.id=o.location_id left join public.business_devices d on d.id=o.device_id
    left join public.location_document_numbers ln on ln.tenant_id=p_tenant_id and ln.entity_type='purchase' and ln.entity_id=p.id
    left join public.device_document_numbers dn on dn.tenant_id=p_tenant_id and dn.entity_type='purchase' and dn.entity_id=p.id
    where p.tenant_id=p_tenant_id and (p_from is null or p.purchase_date>=p_from) and (p_to is null or p.purchase_date<=p_to)
      and (trim(coalesce(p_query,''))='' or lower(coalesce(p.purchase_number,'')) like q or lower(coalesce(sup.name,'')) like q or lower(coalesce(p.supplier_invoice_number,'')) like q or lower(coalesce(dn.terminal_number,ln.local_number,'')) like q)
    union all
    select 'expense'::text,e.id,e.expense_number::text,e.expense_date,coalesce(e.payee,e.description)::text,e.total_amount,0::numeric,e.total_amount,e.status::text,o.location_id,l.name::text,o.device_id,d.name::text,e.created_at
    from public.expenses e
    left join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='expense' and o.entity_id=e.id
    left join public.business_locations l on l.id=o.location_id left join public.business_devices d on d.id=o.device_id
    where e.tenant_id=p_tenant_id and (p_from is null or e.expense_date>=p_from) and (p_to is null or e.expense_date<=p_to)
      and (trim(coalesce(p_query,''))='' or lower(coalesce(e.expense_number,'')) like q or lower(coalesce(e.payee,'')) like q or lower(coalesce(e.description,'')) like q)
  ) z order by z.created_at desc limit lim;
end $$;


--
-- Name: platform_transactions_list_v45(uuid, date, date, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_transactions_list_v45(p_tenant_id uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_query text DEFAULT NULL::text, p_limit integer DEFAULT 500) RETURNS TABLE(entity_type text, entity_id uuid, reference text, entry_date date, party text, total numeric, paid numeric, balance numeric, status text, location_id uuid, location_name text, device_id uuid, device_name text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare q text:='%'||lower(trim(coalesce(p_query,'')))||'%';lim integer:=greatest(1,least(coalesce(p_limit,500),2000));
begin
  if not private.platform_v2_is_admin() then raise exception 'Platform admin required';end if;
  return query
  select z.* from (
    select b.entity_type,b.entity_id,b.reference,b.entry_date,b.party,b.total,b.paid,b.balance,b.status,b.location_id,b.location_name,b.device_id,b.device_name,b.created_at
    from public.platform_transactions_list_v44(p_tenant_id,p_from,p_to,p_query,2000) b

    union all

    select 'sales_return'::text,r.id,r.return_number::text,r.return_date,c.name::text,r.grand_total,
      0::numeric,r.grand_total::numeric,r.refund_status::text,r.location_id,l.name::text,r.device_id,d.name::text,r.created_at
    from public.sales_returns r
    join public.sales s on s.id=r.sale_id and s.tenant_id=p_tenant_id
    join public.customers c on c.id=s.customer_id
    join public.business_locations l on l.id=r.location_id
    left join public.business_devices d on d.id=r.device_id
    where r.tenant_id=p_tenant_id
      and (p_from is null or r.return_date>=p_from) and (p_to is null or r.return_date<=p_to)
      and (trim(coalesce(p_query,''))='' or lower(coalesce(r.return_number,'')) like q or lower(coalesce(s.sale_number,'')) like q or lower(coalesce(c.name,'')) like q)

    union all

    select 'purchase_return'::text,r.id,r.return_number::text,r.return_date,sp.name::text,r.grand_total,
      0::numeric,r.grand_total::numeric,r.credit_status::text,r.location_id,l.name::text,r.device_id,d.name::text,r.created_at
    from public.purchase_returns r
    join public.purchases p on p.id=r.purchase_id and p.tenant_id=p_tenant_id
    join public.suppliers sp on sp.id=p.supplier_id
    join public.business_locations l on l.id=r.location_id
    left join public.business_devices d on d.id=r.device_id
    where r.tenant_id=p_tenant_id
      and (p_from is null or r.return_date>=p_from) and (p_to is null or r.return_date<=p_to)
      and (trim(coalesce(p_query,''))='' or lower(coalesce(r.return_number,'')) like q or lower(coalesce(p.purchase_number,'')) like q or lower(coalesce(p.supplier_invoice_number,'')) like q or lower(coalesce(sp.name,'')) like q)
  ) z
  order by z.created_at desc
  limit lim;
end $$;


--
-- Name: platform_ui_design_template_upsert_v43(uuid, text, text, text, text, jsonb, boolean, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_ui_design_template_upsert_v43(p_id uuid, p_key text, p_name text, p_app_key text, p_description text, p_config jsonb, p_is_active boolean, p_is_default boolean, p_sort_order integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_id uuid;
begin
  if not private.platform_v2_has_role('super_admin') and not private.platform_v2_has_role('technical_admin') then
    raise exception 'Technical admin access required';
  end if;
  if p_app_key not in ('client','pos') then raise exception 'Invalid app key'; end if;
  if coalesce(trim(p_key),'')='' or coalesce(trim(p_name),'')='' then raise exception 'Key and name are required'; end if;
  if p_id is not null and exists(select 1 from public.ui_design_templates where id=p_id and app_key<>p_app_key) then
    raise exception 'Template app key cannot be changed after creation';
  end if;

  if coalesce(p_is_default,false) then
    update public.ui_design_templates set is_default=false,updated_at=now() where app_key=p_app_key and is_default=true and (p_id is null or id<>p_id);
  end if;

  if p_id is null then
    insert into public.ui_design_templates(key,name,app_key,description,config,is_system,is_default,is_active,sort_order)
    values(trim(p_key),trim(p_name),p_app_key,nullif(trim(p_description),''),coalesce(p_config,'{}'::jsonb),false,coalesce(p_is_default,false),coalesce(p_is_active,true),coalesce(p_sort_order,100))
    on conflict(key) do update set name=excluded.name,app_key=excluded.app_key,description=excluded.description,config=excluded.config,is_default=excluded.is_default,is_active=excluded.is_active,sort_order=excluded.sort_order,updated_at=now()
    returning id into v_id;
  else
    update public.ui_design_templates set
      key=trim(p_key),name=trim(p_name),app_key=p_app_key,description=nullif(trim(p_description),''),
      config=coalesce(p_config,'{}'::jsonb),is_default=coalesce(p_is_default,false),is_active=coalesce(p_is_active,true),
      sort_order=coalesce(p_sort_order,100),updated_at=now()
    where id=p_id returning id into v_id;
    if v_id is null then raise exception 'Design template not found'; end if;
  end if;
  perform private.platform_audit_write('ui_design_template.upsert','ui_design_template',v_id::text,null,jsonb_build_object('key',p_key,'app_key',p_app_key));
  return v_id;
end $$;


--
-- Name: ui_design_templates; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ui_design_templates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    key text NOT NULL,
    name text NOT NULL,
    app_key text NOT NULL,
    description text,
    config jsonb DEFAULT '{}'::jsonb NOT NULL,
    is_system boolean DEFAULT false NOT NULL,
    is_default boolean DEFAULT false NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    sort_order integer DEFAULT 100 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ui_design_templates_app_key_check CHECK ((app_key = ANY (ARRAY['client'::text, 'pos'::text])))
);


--
-- Name: platform_ui_design_templates_list_v43(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_ui_design_templates_list_v43(p_app_key text DEFAULT NULL::text) RETURNS SETOF public.ui_design_templates
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if not private.platform_v2_is_admin() then raise exception 'Platform admin access required'; end if;
  return query
  select * from public.ui_design_templates
  where p_app_key is null or app_key=p_app_key
  order by app_key,sort_order,name;
end $$;


--
-- Name: platform_update_business_modules(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_update_business_modules(p_tenant_id uuid, p_module_keys text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_owner_role_id uuid;
begin

  -- ----------------------------------------------------------
  -- PLATFORM ADMIN ONLY
  -- ----------------------------------------------------------

  if not private.is_platform_admin() then
    raise exception 'Access denied'
      using errcode = '42501';
  end if;


  -- ----------------------------------------------------------
  -- VERIFY BUSINESS
  -- ----------------------------------------------------------

  if not exists (
    select 1
    from public.tenants t
    where t.id = p_tenant_id
  ) then
    raise exception 'Business not found';
  end if;


  -- ----------------------------------------------------------
  -- VALIDATE MODULE KEYS
  -- ----------------------------------------------------------

  if exists (
    select 1

    from unnest(
      coalesce(
        p_module_keys,
        array[]::text[]
      )
    ) requested(module_key)

    left join public.modules m
      on m.key = requested.module_key

    where m.key is null
  ) then
    raise exception
      'One or more selected modules do not exist';
  end if;


  -- ----------------------------------------------------------
  -- DISABLE ALL OPTIONAL MODULES
  --
  -- Dashboard is always enabled.
  -- ----------------------------------------------------------

  update public.tenant_modules
  set enabled = false
  where tenant_id = p_tenant_id
    and module_key <> 'dashboard';


  -- ----------------------------------------------------------
  -- ALWAYS ENABLE DASHBOARD
  -- ----------------------------------------------------------

  insert into public.tenant_modules (
    tenant_id,
    module_key,
    enabled
  )
  values (
    p_tenant_id,
    'dashboard',
    true
  )
  on conflict (
    tenant_id,
    module_key
  )
  do update set
    enabled = true;


  -- ----------------------------------------------------------
  -- ENABLE SELECTED MODULES
  -- ----------------------------------------------------------

  insert into public.tenant_modules (
    tenant_id,
    module_key,
    enabled
  )

  select
    p_tenant_id,
    m.key,
    true

  from public.modules m

  where m.key = any(
    coalesce(
      p_module_keys,
      array[]::text[]
    )
  )

  on conflict (
    tenant_id,
    module_key
  )
  do update set
    enabled = true;


  -- ----------------------------------------------------------
  -- REMOVE PERMISSIONS BELONGING TO DISABLED MODULES
  --
  -- Applies to Manager, Cashier, Accountant, etc.
  -- ----------------------------------------------------------

  delete from public.role_permissions rp

  using
    public.roles r,
    public.permissions p

  where rp.role_id = r.id
    and rp.permission_key = p.key
    and r.tenant_id = p_tenant_id

    and not exists (
      select 1

      from public.tenant_modules tm

      where tm.tenant_id = p_tenant_id
        and tm.module_key = p.module_key
        and tm.enabled = true
    );


  -- ----------------------------------------------------------
  -- FIND OWNER ROLE
  -- ----------------------------------------------------------

  select r.id
  into v_owner_role_id

  from public.roles r

  where r.tenant_id = p_tenant_id
    and r.key = 'owner'

  limit 1;


  -- ----------------------------------------------------------
  -- OWNER ALWAYS GETS FULL ACCESS TO ENABLED MODULES
  -- ----------------------------------------------------------

  if v_owner_role_id is not null then

    delete from public.role_permissions
    where role_id = v_owner_role_id;


    insert into public.role_permissions (
      role_id,
      permission_key
    )

    select
      v_owner_role_id,
      p.key

    from public.permissions p

    join public.tenant_modules tm
      on tm.module_key = p.module_key

    where tm.tenant_id = p_tenant_id
      and tm.enabled = true

    on conflict do nothing;

  end if;


end;
$$;


--
-- Name: platform_update_business_modules_v2(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_update_business_modules_v2(p_tenant_id uuid, p_module_keys text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_requested text[]; v_expanded text[];
begin
  if not private.platform_v2_is_admin() then raise exception 'Platform admin access required'; end if;
  if not exists(select 1 from public.tenants where id=p_tenant_id) then raise exception 'Tenant not found'; end if;

  select array_agg(distinct x) into v_requested from unnest(coalesce(p_module_keys,array[]::text[]) || array['dashboard']) x;

  with recursive wanted(module_key) as (
    select unnest(v_requested)
    union
    select md.depends_on_module_key from public.module_dependencies md join wanted w on w.module_key=md.module_key
  ) select array_agg(distinct w.module_key) into v_expanded from wanted w join public.modules m on m.key=w.module_key and m.is_active;

  if exists(select 1 from public.tenant_subscriptions ts where ts.tenant_id=p_tenant_id and ts.status in ('trial','active','past_due')) then
    if exists(
      select 1 from unnest(v_expanded) x
      where not exists(select 1 from public.tenant_subscriptions ts join public.subscription_plan_modules spm on spm.plan_id=ts.plan_id where ts.tenant_id=p_tenant_id and spm.module_key=x)
    ) then raise exception 'One or more selected modules are not included in this tenant subscription plan'; end if;
  end if;

  insert into public.tenant_modules(tenant_id,module_key,enabled)
  select p_tenant_id,m.key,(m.key=any(v_expanded)) from public.modules m
  on conflict(tenant_id,module_key) do update set enabled=excluded.enabled;

  -- Remove disabled-module permissions. Owner gets permissions for every enabled module.
  delete from public.role_permissions rp using public.roles r,public.permissions p
  where rp.role_id=r.id and rp.permission_key=p.key and r.tenant_id=p_tenant_id and not (p.module_key=any(v_expanded));

  insert into public.role_permissions(role_id,permission_key)
  select r.id,p.key from public.roles r join public.permissions p on p.module_key=any(v_expanded)
  where r.tenant_id=p_tenant_id and r.key='owner'
  on conflict do nothing;

  perform private.platform_audit_write('tenant.modules.update','tenant',p_tenant_id::text,p_tenant_id,jsonb_build_object('module_keys',v_expanded));
end $$;


--
-- Name: platform_update_role_permissions(uuid, uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_update_role_permissions(p_tenant_id uuid, p_role_id uuid, p_permission_keys text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_role_key text;
begin

  if not private.is_platform_admin() then
    raise exception 'Access denied'
      using errcode = '42501';
  end if;


  -- ----------------------------------------------------------
  -- Verify role belongs to business
  -- ----------------------------------------------------------

  select r.key
  into v_role_key

  from public.roles r

  where r.id = p_role_id
    and r.tenant_id = p_tenant_id;


  if v_role_key is null then
    raise exception 'Role not found';
  end if;


  -- ----------------------------------------------------------
  -- Owner cannot be restricted.
  -- ----------------------------------------------------------

  if v_role_key = 'owner' then
    raise exception
      'Owner permissions cannot be manually restricted';
  end if;


  -- ----------------------------------------------------------
  -- Validate requested permissions.
  --
  -- Permission must:
  -- 1. exist
  -- 2. belong to an enabled module for this business
  -- ----------------------------------------------------------

  if exists (
    select 1

    from unnest(
      coalesce(
        p_permission_keys,
        array[]::text[]
      )
    ) requested(permission_key)

    left join public.permissions p
      on p.key = requested.permission_key

    left join public.tenant_modules tm
      on tm.tenant_id = p_tenant_id
     and tm.module_key = p.module_key
     and tm.enabled = true

    where p.key is null
       or tm.module_key is null
  ) then
    raise exception
      'One or more permissions are invalid or belong to disabled modules';
  end if;


  -- ----------------------------------------------------------
  -- Replace permission set
  -- ----------------------------------------------------------

  delete from public.role_permissions
  where role_id = p_role_id;


  insert into public.role_permissions (
    role_id,
    permission_key
  )

  select
    p_role_id,
    requested.permission_key

  from unnest(
    coalesce(
      p_permission_keys,
      array[]::text[]
    )
  ) requested(permission_key)

  on conflict do nothing;

end;
$$;


--
-- Name: platform_username_lookup(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_username_lookup(p_username text) RETURNS TABLE(user_id uuid, username text, display_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ begin
  if not public.current_user_is_platform_admin() then raise exception 'Platform admin required'; end if;
  return query select n.user_id,n.username,null::text as display_name
  from public.user_login_names n
  where n.username=lower(trim(p_username));
end $$;


--
-- Name: platform_usernames_list(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_usernames_list(p_tenant_id uuid DEFAULT NULL::uuid) RETURNS TABLE(user_id uuid, username text, display_name text, tenant_id uuid, tenant_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ begin
  if not public.current_user_is_platform_admin() then raise exception 'Platform admin required'; end if;
  return query
  select distinct n.user_id,n.username,null::text as display_name,tm.tenant_id,t.name
  from public.user_login_names n
  left join public.tenant_memberships tm on tm.user_id=n.user_id and tm.status='active'
  left join public.tenants t on t.id=tm.tenant_id
  where p_tenant_id is null or tm.tenant_id=p_tenant_id
  order by n.username;
end $$;


--
-- Name: pos_device_preferences_get_v44(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_device_preferences_get_v44(p_tenant_id uuid, p_device_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v jsonb;v_location uuid;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  select location_id into v_location from public.business_devices where id=p_device_id and tenant_id=p_tenant_id and status='active';
  if v_location is null then raise exception 'Terminal not found';end if;
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_user_location_allowed(p_tenant_id,v_location,'view') then raise exception 'Terminal access denied';end if;
  select settings into v from public.pos_device_preferences where tenant_id=p_tenant_id and device_id=p_device_id;
  return coalesce(v,'{}'::jsonb);
end $$;


--
-- Name: pos_device_preferences_set_v44(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_device_preferences_set_v44(p_tenant_id uuid, p_device_id uuid, p_settings jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'settings.manage') then raise exception 'Settings permission required';end if;
  if not exists(select 1 from public.business_devices where id=p_device_id and tenant_id=p_tenant_id and status='active') then raise exception 'Terminal not found';end if;
  insert into public.pos_device_preferences(tenant_id,device_id,settings,updated_at,updated_by)
  values(p_tenant_id,p_device_id,coalesce(p_settings,'{}'::jsonb),now(),auth.uid())
  on conflict(tenant_id,device_id) do update set settings=excluded.settings,updated_at=now(),updated_by=auth.uid();
end $$;


--
-- Name: pos_expenses_today_v473(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_expenses_today_v473(p_tenant_id uuid, p_device_id uuid, p_day date DEFAULT CURRENT_DATE) RETURNS TABLE(expense_id uuid, expense_number text, invoice_number text, category_id uuid, category_name text, expense_date date, payee text, description text, amount numeric, tax_amount numeric, total_amount numeric, payment_method text, reference_number text, notes text, status text, created_at timestamp with time zone, location_id uuid, location_name text, device_id uuid, device_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_location uuid;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  select d.location_id into v_location from public.business_devices d
  where d.id=p_device_id and d.tenant_id=p_tenant_id and d.status='active';
  if v_location is null then raise exception 'Active terminal not found';end if;
  if not private.erp_user_is_owner(p_tenant_id)
     and not private.erp_user_location_allowed(p_tenant_id,v_location,'view') then raise exception 'Terminal access denied';end if;

  return query
  select e.id,e.expense_number::text,coalesce(dn.terminal_number,ln.local_number,e.expense_number)::text,
    e.category_id,c.name::text,e.expense_date,e.payee::text,e.description::text,
    e.amount,e.tax_amount,e.total_amount,e.payment_method::text,e.reference_number::text,e.notes::text,e.status::text,e.created_at,
    o.location_id,l.name::text,o.device_id,d.name::text
  from public.expenses e
  join public.expense_categories c on c.id=e.category_id
  join public.document_origins o
    on o.tenant_id=p_tenant_id and o.entity_type='expense' and o.entity_id=e.id and o.device_id=p_device_id
  left join public.business_locations l on l.id=o.location_id
  left join public.business_devices d on d.id=o.device_id
  left join public.location_document_numbers ln
    on ln.tenant_id=p_tenant_id and ln.entity_type='expense' and ln.entity_id=e.id
  left join public.device_document_numbers dn
    on dn.tenant_id=p_tenant_id and dn.entity_type='expense' and dn.entity_id=e.id
  where e.tenant_id=p_tenant_id and e.expense_date=coalesce(p_day,current_date)
  order by e.created_at desc;
end $$;


