--
-- Name: pos_offline_available_serials_v486(uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_offline_available_serials_v486(p_tenant_id uuid, p_device_id uuid, p_after text DEFAULT ''::text, p_limit integer DEFAULT 1000) RETURNS TABLE(serial_id uuid, serial_number text, variant_id uuid, updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_location uuid;v_after text:=lower(trim(coalesce(p_after,'')));
begin
  v_location:=private.v486_pos_device_location(p_tenant_id,p_device_id,null);
  return query
  select s.id,s.serial_number,s.variant_id,s.updated_at
  from public.inventory_serials_v483 s
  where s.tenant_id=p_tenant_id and s.current_location_id=v_location and s.status='in_stock'
    and lower(s.serial_number)>v_after
    and not exists(select 1 from public.stock_transfer_allocations_v485 a join public.stock_transfers t on t.id=a.transfer_id where a.tenant_id=p_tenant_id and a.serial_id=s.id and t.status in('requested','approved','in_transit'))
  order by lower(s.serial_number),s.id limit greatest(1,least(coalesce(p_limit,1000),2000));
end$$;


--
-- Name: pos_offline_cache_manifest_v486(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_offline_cache_manifest_v486(p_tenant_id uuid, p_device_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_location uuid;v_shift jsonb;v_gst_version text;begin v_location:=private.v486_pos_device_location(p_tenant_id,p_device_id,null);begin v_shift:=public.cashier_shift_current_v472(p_tenant_id,p_device_id);exception when others then v_shift:=null;end;select md5(coalesce(string_agg(concat_ws(':',variant_id,effective_from,updated_at,gst_rate,cess_rate,taxability),',' order by variant_id),'empty')) into v_gst_version from public.gst_product_tax_profiles_v520 where tenant_id=p_tenant_id and active and effective_to is null;return jsonb_build_object('tenant_id',p_tenant_id,'device_id',p_device_id,'location_id',v_location,'generated_at',now(),'schema_version','5.2.0-foundation','migration_no',214,'current_shift',v_shift,'gst_engine','gst_v520','gst_profile_version',coalesce(v_gst_version,'empty'),'gst_provider_connected',false);end$$;


--
-- Name: pos_offline_customer_cache_v486(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_offline_customer_cache_v486(p_tenant_id uuid, p_device_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v jsonb;
begin
  perform private.v486_pos_device_location(p_tenant_id,p_device_id,null);
  select coalesce(jsonb_agg(x order by x->>'customer_name'),'[]'::jsonb) into v from public.customers_list_v482(p_tenant_id) as t(x) where x->>'status'='active';
  return coalesce(v,'[]'::jsonb);
end$$;


--
-- Name: pos_offline_product_cache_v486(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_offline_product_cache_v486(p_tenant_id uuid, p_device_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_location uuid;v jsonb;begin v_location:=private.v486_pos_device_location(p_tenant_id,p_device_id,null);select coalesce(jsonb_agg(x||jsonb_build_object('stock_quantity',case when x->>'item_type'='stock' then greatest(coalesce(lb.quantity,0)-coalesce(lb.reserved_quantity,0)-coalesce(lb.damaged_quantity,0)-coalesce(lb.quarantine_quantity,0),0) else coalesce(nullif(x->>'stock_quantity','')::numeric,0) end,'offline_available_quantity',case when x->>'item_type'='stock' then greatest(coalesce(lb.quantity,0)-coalesce(lb.reserved_quantity,0)-coalesce(lb.damaged_quantity,0)-coalesce(lb.quarantine_quantity,0),0) else coalesce(nullif(x->>'stock_quantity','')::numeric,0) end,'gst_profile',jsonb_strip_nulls(jsonb_build_object('profile_id',gp.id,'supply_kind',gp.supply_kind,'hsn_sac',gp.hsn_sac,'taxability',gp.taxability,'gst_rate',coalesce(gp.gst_rate,prod.tax_rate,0),'cess_rate',coalesce(gp.cess_rate,0),'cess_per_unit',coalesce(gp.cess_per_unit,0),'tax_inclusive',coalesce(gp.tax_inclusive,false),'reverse_charge',coalesce(gp.reverse_charge,false),'validation_status',coalesce(gp.validation_status,'legacy_fallback'),'effective_from',gp.effective_from))) order by x->>'product_name',x->>'sku'),'[]'::jsonb) into v from public.inventory_list_products_v483(p_tenant_id,v_location) as t(x) left join public.location_stock_balances lb on lb.tenant_id=p_tenant_id and lb.location_id=v_location and lb.variant_id=nullif(x->>'variant_id','')::uuid left join public.location_product_settings lps on lps.tenant_id=p_tenant_id and lps.location_id=v_location and lps.variant_id=nullif(x->>'variant_id','')::uuid left join public.product_variants pv on pv.id=nullif(x->>'variant_id','')::uuid and pv.tenant_id=p_tenant_id left join public.products prod on prod.id=pv.product_id and prod.tenant_id=pv.tenant_id left join lateral(select g.* from public.gst_product_tax_profiles_v520 g where g.tenant_id=p_tenant_id and g.variant_id=pv.id and g.active and g.effective_from<=current_date and (g.effective_to is null or g.effective_to>=current_date) order by g.effective_from desc limit 1) gp on true where x->>'product_status'='active' and x->>'variant_status'='active' and coalesce(lps.active,true);return coalesce(v,'[]'::jsonb);end$$;


--
-- Name: pos_offline_request_lookup_v486(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_offline_request_lookup_v486(p_tenant_id uuid, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v public.pos_offline_sync_v486%rowtype;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  select * into v from public.pos_offline_sync_v486 where tenant_id=p_tenant_id and request_id=trim(p_request_id);
  if not found then return null;end if;
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_user_location_allowed(p_tenant_id,v.location_id,'view') then raise exception 'Location access denied';end if;
  return jsonb_build_object('request_id',v.request_id,'device_id',v.device_id,'location_id',v.location_id,'local_invoice_number',v.local_invoice_number,'status',v.status,'conflict_code',v.conflict_code,'conflict_message',v.conflict_message,'attempts',v.attempts,'first_seen_at',v.first_seen_at,'last_attempt_at',v.last_attempt_at,'synced_at',v.synced_at,'server_response',v.server_response);
end$$;


--
-- Name: pos_offline_sale_sync_v486(uuid, uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_offline_sale_sync_v486(p_tenant_id uuid, p_device_id uuid, p_location_id uuid, p_request_id text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_location uuid;v_existing jsonb;v_result jsonb;v_items jsonb;v_priced jsonb;v_client jsonb;v_server jsonb;v_i integer;v_client_price numeric;v_server_price numeric;v_client_tax numeric;v_server_tax numeric;v_variant uuid;v_customer uuid;v_sale_date date;v_due_date date;v_local text;v_message text;v_code text;v_profile public.gst_product_tax_profiles_v520%rowtype;v_product_tax numeric;begin if nullif(trim(coalesce(p_request_id,'')),'') is null then raise exception 'Request ID is required';end if;v_location:=private.v486_pos_device_location(p_tenant_id,p_device_id,p_location_id);perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':offline:'||trim(p_request_id),0));select server_response into v_existing from public.pos_offline_sync_v486 where tenant_id=p_tenant_id and request_id=trim(p_request_id) and status='synced';if v_existing is not null then return v_existing||jsonb_build_object('idempotent_replay',true);end if;v_items:=coalesce(p_payload->'items','[]'::jsonb);if jsonb_typeof(v_items)<>'array' or jsonb_array_length(v_items)=0 then raise exception 'Offline invoice has no items';end if;v_customer:=nullif(p_payload->>'customer_id','')::uuid;v_local:=nullif(trim(coalesce(p_payload->>'local_invoice_number','')),'');if v_customer is null or not exists(select 1 from public.customers c where c.id=v_customer and c.tenant_id=p_tenant_id and c.status='active') then return private.v486_offline_conflict(p_tenant_id,p_device_id,v_location,p_request_id,v_local,'CUSTOMER_UNAVAILABLE','Customer is no longer available.',p_payload);end if;v_sale_date:=coalesce(nullif(p_payload->>'sale_date','')::date,current_date);v_due_date:=nullif(p_payload->>'due_date','')::date;v_priced:=private.v482_price_sale_items(p_tenant_id,v_customer,v_items,v_location);for v_i in 0..jsonb_array_length(v_items)-1 loop v_client:=v_items->v_i;v_server:=v_priced->v_i;v_variant:=nullif(v_client->>'variant_id','')::uuid;v_client_price:=coalesce(nullif(v_client->>'unit_price','')::numeric,0);v_server_price:=coalesce(nullif(v_server->>'unit_price','')::numeric,0);if abs(v_client_price-v_server_price)>0.005 then v_message:=format('Price changed for product %s. Offline %s, current %s.',v_variant,round(v_client_price,2),round(v_server_price,2));return private.v486_offline_conflict(p_tenant_id,p_device_id,v_location,p_request_id,v_local,'PRICE_CHANGED',v_message,p_payload);end if;select p.tax_rate into v_product_tax from public.product_variants pv join public.products p on p.id=pv.product_id and p.tenant_id=pv.tenant_id where pv.id=v_variant and pv.tenant_id=p_tenant_id;if not found then return private.v486_offline_conflict(p_tenant_id,p_device_id,v_location,p_request_id,v_local,'PRODUCT_UNAVAILABLE','A product on the offline invoice is no longer available.',p_payload);end if;select * into v_profile from private.gst_profile_for_variant_v520(p_tenant_id,v_variant,v_sale_date);v_server_tax:=case when v_profile.id is null then coalesce(v_product_tax,0) when v_profile.taxability='taxable' then coalesce(v_profile.gst_rate,0) else 0 end;v_client_tax:=coalesce(nullif(v_client->>'tax_rate','')::numeric,0);if abs(v_client_tax-v_server_tax)>0.0001 then v_message:=format('Tax changed for product %s. Offline %s, current %s.',v_variant,round(v_client_tax,4),round(v_server_tax,4));return private.v486_offline_conflict(p_tenant_id,p_device_id,v_location,p_request_id,v_local,'TAX_CHANGED',v_message,p_payload);end if;end loop;insert into public.pos_offline_sync_v486(tenant_id,request_id,device_id,location_id,local_invoice_number,status,payload_snapshot,attempts,last_attempt_at,created_by,updated_at) values(p_tenant_id,trim(p_request_id),p_device_id,v_location,v_local,'syncing',p_payload,1,now(),auth.uid(),now()) on conflict(tenant_id,request_id) do update set status='syncing',payload_snapshot=excluded.payload_snapshot,attempts=public.pos_offline_sync_v486.attempts+1,last_attempt_at=now(),updated_at=now(),conflict_code=null,conflict_message=null;begin v_result:=public.sales_create_v489(p_tenant_id,v_customer,v_sale_date,v_due_date,v_items,coalesce(nullif(p_payload->>'additional_charges','')::numeric,0),coalesce(nullif(p_payload->>'round_off','')::numeric,0),coalesce(nullif(p_payload->>'initial_payment','')::numeric,0),coalesce(nullif(p_payload->>'payment_method',''),'cash'),coalesce(p_payload->>'payment_reference',''),trim(concat_ws(' • ',nullif(p_payload->>'notes',''),'Offline POS '||coalesce(v_local,''))),v_location,p_device_id,trim(p_request_id));exception when others then v_message:=sqlerrm;if v_message ilike '%stock%' or v_message ilike '%serial%' or v_message ilike '%batch%' or v_message ilike '%reconciled%' then v_code:='STOCK_CONFLICT';else v_code:='SERVER_VALIDATION';end if;return private.v486_offline_conflict(p_tenant_id,p_device_id,v_location,p_request_id,v_local,v_code,v_message,p_payload);end;v_result:=coalesce(v_result,'{}'::jsonb)||jsonb_build_object('ok',true,'status','synced','request_id',trim(p_request_id),'local_invoice_number',v_local,'offline_sync','v4.8.6','gst_engine','legacy_unverified');update public.pos_offline_sync_v486 set status='synced',server_response=v_result,conflict_code=null,conflict_message=null,synced_at=now(),last_attempt_at=now(),updated_at=now() where tenant_id=p_tenant_id and request_id=trim(p_request_id);return v_result;end $$;


--
-- Name: pos_offline_sync_list_v486(uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_offline_sync_list_v486(p_tenant_id uuid, p_device_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 500) RETURNS TABLE(request_id text, device_id uuid, device_code text, location_id uuid, location_name text, local_invoice_number text, status text, conflict_code text, conflict_message text, attempts integer, first_seen_at timestamp with time zone, last_attempt_at timestamp with time zone, synced_at timestamp with time zone, server_response jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  return query
  select q.request_id,q.device_id,d.device_code,q.location_id,l.location_code||' • '||l.name,q.local_invoice_number,q.status,
         q.conflict_code,q.conflict_message,q.attempts,q.first_seen_at,q.last_attempt_at,q.synced_at,q.server_response
  from public.pos_offline_sync_v486 q
  join public.business_devices d on d.id=q.device_id
  join public.business_locations l on l.id=q.location_id
  where q.tenant_id=p_tenant_id and (p_device_id is null or q.device_id=p_device_id)
    and (p_status is null or p_status='' or q.status=p_status)
    and (private.erp_user_is_owner(p_tenant_id) or private.erp_user_location_allowed(p_tenant_id,q.location_id,'view'))
  order by q.updated_at desc limit greatest(1,least(coalesce(p_limit,500),2000));
end$$;


--
-- Name: pos_offline_sync_summary_v486(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_offline_sync_summary_v486(p_tenant_id uuid, p_device_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  return (select jsonb_build_object(
    'pending',count(*) filter(where status in('pending','syncing')),
    'conflict',count(*) filter(where status='conflict'),
    'error',count(*) filter(where status='error'),
    'synced_today',count(*) filter(where status='synced' and synced_at::date=current_date),
    'last_synced_at',max(synced_at)
  ) from public.pos_offline_sync_v486 where tenant_id=p_tenant_id and (p_device_id is null or device_id=p_device_id));
end$$;


--
-- Name: pos_printer_profile_save_v44(uuid, uuid, uuid, text, text, text, text, text, integer, boolean, boolean, text, boolean, boolean, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_printer_profile_save_v44(p_tenant_id uuid, p_device_id uuid, p_profile_id uuid, p_name text, p_purpose text, p_paper_size text, p_printer_name text, p_route_name text, p_copies integer, p_auto_print boolean, p_cash_drawer_enabled boolean, p_cash_drawer_command text, p_is_default boolean, p_active boolean, p_settings jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_id uuid:=coalesce(p_profile_id,gen_random_uuid());v_location uuid;v_purpose text:=lower(coalesce(p_purpose,'invoice'));
begin
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'settings.manage') then
    raise exception 'Settings permission required';
  end if;
  select location_id into v_location from public.business_devices where id=p_device_id and tenant_id=p_tenant_id and status='active';
  if v_location is null then raise exception 'Active terminal not found';end if;
  if v_purpose not in('invoice','kot','report','label') then raise exception 'Invalid printer purpose';end if;
  if lower(coalesce(p_paper_size,'80mm')) not in('58mm','80mm','a4') then raise exception 'Invalid paper size';end if;
  if trim(coalesce(p_name,''))='' then raise exception 'Printer profile name is required';end if;

  if coalesce(p_is_default,false) then
    update public.printer_profiles set is_default=false,updated_at=now()
    where tenant_id=p_tenant_id and device_id=p_device_id and purpose=v_purpose and id<>v_id;
  end if;

  insert into public.printer_profiles(
    id,tenant_id,location_id,device_id,name,paper_size,printer_name,copies,auto_print,active,settings,
    purpose,route_name,cash_drawer_enabled,cash_drawer_command,is_default,updated_at
  ) values(
    v_id,p_tenant_id,v_location,p_device_id,trim(p_name),lower(coalesce(p_paper_size,'80mm')),
    nullif(trim(coalesce(p_printer_name,'')),''),greatest(1,least(coalesce(p_copies,1),10)),coalesce(p_auto_print,false),coalesce(p_active,true),coalesce(p_settings,'{}'::jsonb),
    v_purpose,nullif(trim(coalesce(p_route_name,'')),''),coalesce(p_cash_drawer_enabled,false),nullif(trim(coalesce(p_cash_drawer_command,'')),''),coalesce(p_is_default,false),now()
  ) on conflict(id) do update set
    name=excluded.name,paper_size=excluded.paper_size,printer_name=excluded.printer_name,copies=excluded.copies,
    auto_print=excluded.auto_print,active=excluded.active,settings=excluded.settings,purpose=excluded.purpose,
    route_name=excluded.route_name,cash_drawer_enabled=excluded.cash_drawer_enabled,
    cash_drawer_command=excluded.cash_drawer_command,is_default=excluded.is_default,updated_at=now();
  return v_id;
end $$;


--
-- Name: pos_printer_profiles_list_v44(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_printer_profiles_list_v44(p_tenant_id uuid, p_device_id uuid) RETURNS SETOF public.printer_profiles
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_location uuid;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  select location_id into v_location from public.business_devices
  where id=p_device_id and tenant_id=p_tenant_id and status='active';
  if v_location is null then raise exception 'Active POS terminal not found';end if;
  if not private.erp_user_is_owner(p_tenant_id)
     and not private.erp_user_location_allowed(p_tenant_id,v_location,'view') then
    raise exception 'Terminal access denied';
  end if;
  return query
    select p.* from public.printer_profiles p
    where p.tenant_id=p_tenant_id and p.active
      and (p.device_id=p_device_id or (p.device_id is null and (p.location_id=v_location or p.location_id is null)))
    order by p.purpose,p.is_default desc,p.name;
end $$;


--
-- Name: pos_purchases_today_v473(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_purchases_today_v473(p_tenant_id uuid, p_device_id uuid, p_day date DEFAULT CURRENT_DATE) RETURNS TABLE(purchase_id uuid, purchase_number text, invoice_number text, supplier_id uuid, supplier_name text, supplier_invoice_number text, purchase_date date, due_date date, subtotal numeric, discount_total numeric, tax_total numeric, additional_charges numeric, grand_total numeric, paid_amount numeric, balance_due numeric, payment_status text, status text, created_at timestamp with time zone, location_id uuid, location_name text, device_id uuid, device_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_location uuid;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  select d.location_id into v_location from public.business_devices d
  where d.id=p_device_id and d.tenant_id=p_tenant_id and d.status='active';
  if v_location is null then raise exception 'Active terminal not found';end if;
  if not private.erp_user_is_owner(p_tenant_id)
     and not private.erp_user_location_allowed(p_tenant_id,v_location,'view') then raise exception 'Terminal access denied';end if;

  return query
  select p.id,p.purchase_number::text,coalesce(dn.terminal_number,ln.local_number,p.purchase_number)::text,
    p.supplier_id,s.name::text,p.supplier_invoice_number::text,p.purchase_date,p.due_date,
    p.subtotal,p.discount_total,p.tax_total,p.additional_charges,p.grand_total,
    coalesce(py.paid,0)::numeric,
    greatest(p.grand_total-coalesce(rt.returned,0)-coalesce(py.paid,0),0)::numeric,
    (case
      when greatest(p.grand_total-coalesce(rt.returned,0)-coalesce(py.paid,0),0)<=0.0001 then 'paid'
      when coalesce(py.paid,0)>0 then 'partial' else 'unpaid' end)::text,
    p.status::text,p.created_at,o.location_id,l.name::text,o.device_id,d.name::text
  from public.purchases p
  join public.suppliers s on s.id=p.supplier_id
  join public.document_origins o
    on o.tenant_id=p_tenant_id and o.entity_type='purchase' and o.entity_id=p.id and o.device_id=p_device_id
  left join public.business_locations l on l.id=o.location_id
  left join public.business_devices d on d.id=o.device_id
  left join (
    select pp.purchase_id as entity_purchase_id,sum(pp.amount) as paid
    from public.purchase_payments pp group by pp.purchase_id
  ) py on py.entity_purchase_id=p.id
  left join (
    select pr.purchase_id,sum(pr.grand_total) as returned
    from public.purchase_returns pr where pr.credit_status<>'waived' group by pr.purchase_id
  ) rt on rt.purchase_id=p.id
  left join public.location_document_numbers ln
    on ln.tenant_id=p_tenant_id and ln.entity_type='purchase' and ln.entity_id=p.id
  left join public.device_document_numbers dn
    on dn.tenant_id=p_tenant_id and dn.entity_type='purchase' and dn.entity_id=p.id
  where p.tenant_id=p_tenant_id and p.purchase_date=coalesce(p_day,current_date)
    and (private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'purchases.view') or private.erp_has_permission(p_tenant_id,'purchases.manage'))
  order by p.created_at desc;
end $$;


--
-- Name: pos_return_documents_today_v473(uuid, uuid, date, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_return_documents_today_v473(p_tenant_id uuid, p_device_id uuid, p_day date DEFAULT CURRENT_DATE, p_type text DEFAULT 'all'::text, p_query text DEFAULT ''::text, p_limit integer DEFAULT 200) RETURNS TABLE(entity_type text, entity_id uuid, document_number text, document_date date, party text, grand_total numeric, status text, return_status text, location_id uuid, device_id uuid, matched_product text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_location uuid;
  q text := '%' || lower(trim(coalesce(p_query,''))) || '%';
  lim integer := greatest(1,least(coalesce(p_limit,200),500));
begin
  if p_type not in('all','sale','purchase') then raise exception 'Invalid return search type'; end if;
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;

  select d.location_id into v_location
  from public.business_devices d
  where d.id=p_device_id and d.tenant_id=p_tenant_id and d.status='active';
  if v_location is null then raise exception 'Active terminal not found'; end if;
  if not private.erp_user_is_owner(p_tenant_id)
     and not private.erp_user_location_allowed(p_tenant_id,v_location,'view') then
    raise exception 'Terminal access denied';
  end if;

  return query
  select z.entity_type,z.entity_id,z.document_number,z.document_date,z.party,z.grand_total,
         z.status,z.return_status,z.location_id,z.device_id,z.matched_product
  from (
    select
      'sale'::text entity_type,
      s.id entity_id,
      coalesce(dn.terminal_number,ln.local_number,s.sale_number)::text document_number,
      s.sale_date document_date,
      c.name::text party,
      s.grand_total,
      s.status::text status,
      coalesce(public.transaction_return_status_v45(p_tenant_id,'sale',s.id)->>'status','not_returned') return_status,
      o.location_id,
      o.device_id,
      (
        select concat_ws(' • ',pr.name,pv.sku,nullif(pv.barcode,''),nullif(pv.part_number,''))
        from public.sale_items si
        join public.product_variants pv on pv.id=si.variant_id
        join public.products pr on pr.id=pv.product_id
        where si.sale_id=s.id
          and (trim(coalesce(p_query,''))='' or lower(pr.name) like q or lower(coalesce(pv.sku,'')) like q
               or lower(coalesce(pv.barcode,'')) like q or lower(coalesce(pv.part_number,'')) like q)
        order by si.id limit 1
      )::text matched_product
    from public.sales s
    join public.customers c on c.id=s.customer_id
    join public.document_origins o
      on o.tenant_id=p_tenant_id and o.entity_type='sale' and o.entity_id=s.id and o.device_id=p_device_id
    left join public.location_document_numbers ln
      on ln.tenant_id=p_tenant_id and ln.entity_type='sale' and ln.entity_id=s.id
    left join public.device_document_numbers dn
      on dn.tenant_id=p_tenant_id and dn.entity_type='sale' and dn.entity_id=s.id
    where p_type in('all','sale')
      and s.tenant_id=p_tenant_id
      and s.sale_date=coalesce(p_day,current_date)
      and coalesce(s.status,'') not in('void','cancelled')
      and (
        trim(coalesce(p_query,''))='' or lower(coalesce(s.sale_number,'')) like q
        or lower(coalesce(dn.terminal_number,ln.local_number,'')) like q
        or lower(coalesce(c.name,'')) like q
        or exists(
          select 1 from public.sale_items si
          join public.product_variants pv on pv.id=si.variant_id
          join public.products pr on pr.id=pv.product_id
          where si.sale_id=s.id and (
            lower(pr.name) like q or lower(coalesce(pv.sku,'')) like q
            or lower(coalesce(pv.barcode,'')) like q or lower(coalesce(pv.part_number,'')) like q
          )
        )
      )

    union all

    select
      'purchase'::text,
      p.id,
      p.purchase_number::text,
      p.purchase_date,
      sp.name::text,
      p.grand_total,
      p.status::text,
      coalesce(public.transaction_return_status_v45(p_tenant_id,'purchase',p.id)->>'status','not_returned'),
      o.location_id,
      o.device_id,
      (
        select concat_ws(' • ',pr.name,pv.sku,nullif(pv.barcode,''),nullif(pv.part_number,''))
        from public.purchase_items pi
        join public.product_variants pv on pv.id=pi.variant_id
        join public.products pr on pr.id=pv.product_id
        where pi.purchase_id=p.id
          and (trim(coalesce(p_query,''))='' or lower(pr.name) like q or lower(coalesce(pv.sku,'')) like q
               or lower(coalesce(pv.barcode,'')) like q or lower(coalesce(pv.part_number,'')) like q)
        order by pi.id limit 1
      )::text
    from public.purchases p
    join public.suppliers sp on sp.id=p.supplier_id
    join public.document_origins o
      on o.tenant_id=p_tenant_id and o.entity_type='purchase' and o.entity_id=p.id and o.device_id=p_device_id
    where p_type in('all','purchase')
      and p.tenant_id=p_tenant_id
      and p.purchase_date=coalesce(p_day,current_date)
      and coalesce(p.status,'') not in('void','cancelled')
      and (
        trim(coalesce(p_query,''))='' or lower(coalesce(p.purchase_number,'')) like q
        or lower(coalesce(p.supplier_invoice_number,'')) like q or lower(coalesce(sp.name,'')) like q
        or exists(
          select 1 from public.purchase_items pi
          join public.product_variants pv on pv.id=pi.variant_id
          join public.products pr on pr.id=pv.product_id
          where pi.purchase_id=p.id and (
            lower(pr.name) like q or lower(coalesce(pv.sku,'')) like q
            or lower(coalesce(pv.barcode,'')) like q or lower(coalesce(pv.part_number,'')) like q
          )
        )
      )
  ) z
  order by z.document_date desc,z.document_number desc
  limit lim;
end $$;


--
-- Name: pos_sales_today_v473(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_sales_today_v473(p_tenant_id uuid, p_device_id uuid, p_day date DEFAULT CURRENT_DATE) RETURNS TABLE(sale_id uuid, sale_number text, invoice_number text, customer_id uuid, customer_name text, sale_date date, due_date date, subtotal numeric, discount_total numeric, tax_total numeric, additional_charges numeric, grand_total numeric, paid_amount numeric, balance_due numeric, payment_status text, cost_total numeric, gross_profit numeric, status text, created_at timestamp with time zone, location_id uuid, location_name text, device_id uuid, device_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_location uuid;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  select d.location_id into v_location from public.business_devices d
  where d.id=p_device_id and d.tenant_id=p_tenant_id and d.status='active';
  if v_location is null then raise exception 'Active terminal not found';end if;
  if not private.erp_user_is_owner(p_tenant_id)
     and not private.erp_user_location_allowed(p_tenant_id,v_location,'view') then raise exception 'Terminal access denied';end if;

  return query
  select s.id,s.sale_number::text,coalesce(dn.terminal_number,ln.local_number,s.sale_number)::text,
    s.customer_id,c.name::text,s.sale_date,s.due_date,
    s.subtotal,s.discount_total,s.tax_total,s.additional_charges,s.grand_total,
    coalesce(py.paid,0)::numeric,
    greatest(s.grand_total-coalesce(rt.returned,0)-coalesce(py.paid,0),0)::numeric,
    (case
      when greatest(s.grand_total-coalesce(rt.returned,0)-coalesce(py.paid,0),0)<=0.0001 then 'paid'
      when coalesce(py.paid,0)>0 then 'partial' else 'unpaid' end)::text,
    coalesce(s.cost_total,0)::numeric,coalesce(s.gross_profit,0)::numeric,s.status::text,s.created_at,
    o.location_id,l.name::text,o.device_id,d.name::text
  from public.sales s
  join public.customers c on c.id=s.customer_id
  join public.document_origins o
    on o.tenant_id=p_tenant_id and o.entity_type='sale' and o.entity_id=s.id and o.device_id=p_device_id
  left join public.business_locations l on l.id=o.location_id
  left join public.business_devices d on d.id=o.device_id
  left join (
    select sp.sale_id as entity_sale_id,sum(sp.amount) as paid
    from public.sale_payments sp group by sp.sale_id
  ) py on py.entity_sale_id=s.id
  left join (
    select sr.sale_id,sum(sr.grand_total) as returned
    from public.sales_returns sr where sr.refund_status<>'waived' group by sr.sale_id
  ) rt on rt.sale_id=s.id
  left join public.location_document_numbers ln
    on ln.tenant_id=p_tenant_id and ln.entity_type='sale' and ln.entity_id=s.id
  left join public.device_document_numbers dn
    on dn.tenant_id=p_tenant_id and dn.entity_type='sale' and dn.entity_id=s.id
  where s.tenant_id=p_tenant_id and s.sale_date=coalesce(p_day,current_date)
    and (private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'sales.view') or private.erp_has_permission(p_tenant_id,'sales.manage'))
  order by s.created_at desc;
end $$;


--
-- Name: pos_terminal_day_v41(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_terminal_day_v41(p_tenant_id uuid, p_device_id uuid, p_day date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_location uuid;v_invoice_count bigint:=0;v_gross numeric:=0;v_cash numeric:=0;v_upi numeric:=0;v_card numeric:=0;v_bank numeric:=0;v_other numeric:=0;v_invoices jsonb:='[]'::jsonb;v_shift jsonb:='{}'::jsonb;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  select d.location_id into v_location from public.business_devices d
  where d.id=p_device_id and d.tenant_id=p_tenant_id and d.status='active';
  if v_location is null then raise exception 'Active terminal not found';end if;
  if not private.erp_user_is_owner(p_tenant_id)
     and not private.erp_user_location_allowed(p_tenant_id,v_location,'view') then
    raise exception 'Terminal access denied';
  end if;

  select count(*),coalesce(sum(s.grand_total),0)
  into v_invoice_count,v_gross
  from public.sales s
  join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='sale' and o.entity_id=s.id and o.device_id=p_device_id
  where s.tenant_id=p_tenant_id and s.sale_date=p_day and coalesce(s.status,'') not in('cancelled','void');

  select
    coalesce(sum(sp.amount) filter(where lower(sp.payment_method)='cash'),0),
    coalesce(sum(sp.amount) filter(where lower(sp.payment_method)='upi'),0),
    coalesce(sum(sp.amount) filter(where lower(sp.payment_method)='card'),0),
    coalesce(sum(sp.amount) filter(where lower(sp.payment_method)='bank'),0),
    coalesce(sum(sp.amount) filter(where lower(sp.payment_method) not in('cash','upi','card','bank')),0)
  into v_cash,v_upi,v_card,v_bank,v_other
  from public.sale_payments sp
  join public.sales s on s.id=sp.sale_id and s.tenant_id=p_tenant_id
  join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='sale' and o.entity_id=s.id and o.device_id=p_device_id
  where s.sale_date=p_day and coalesce(s.status,'') not in('cancelled','void');

  select coalesce(jsonb_agg(jsonb_build_object(
      'sale_id',s2.id,'sale_number',s2.sale_number,
      'invoice_number',coalesce(dn2.terminal_number,ln2.local_number,s2.sale_number),
      'created_at',s2.created_at,'customer_name',c2.name,'grand_total',s2.grand_total,
      'paid_amount',coalesce((select sum(pp2.amount) from public.sale_payments pp2 where pp2.sale_id=s2.id),0),
      'status',s2.status
    ) order by s2.created_at desc),'[]'::jsonb)
  into v_invoices
  from public.sales s2
  join public.document_origins o2 on o2.tenant_id=p_tenant_id and o2.entity_type='sale' and o2.entity_id=s2.id and o2.device_id=p_device_id
  join public.customers c2 on c2.id=s2.customer_id
  left join public.location_document_numbers ln2 on ln2.tenant_id=p_tenant_id and ln2.entity_type='sale' and ln2.entity_id=s2.id
  left join public.device_document_numbers dn2 on dn2.tenant_id=p_tenant_id and dn2.entity_type='sale' and dn2.entity_id=s2.id
  where s2.tenant_id=p_tenant_id and s2.sale_date=p_day;

  select coalesce((
      select to_jsonb(cs) || jsonb_build_object(
        'expected_now',coalesce((select sum(cm.amount) from public.cash_drawer_movements cm where cm.shift_id=cs.id),0)
      )
      from public.cashier_shifts cs
      where cs.tenant_id=p_tenant_id and cs.device_id=p_device_id
        and cs.opened_at::date<=p_day and coalesce(cs.closed_at::date,p_day)>=p_day
      order by cs.opened_at desc limit 1
    ),'{}'::jsonb) into v_shift;

  return jsonb_build_object(
    'day',p_day,'device_id',p_device_id,'location_id',v_location,
    'invoice_count',v_invoice_count,'gross_sales',v_gross,
    'cash',v_cash,'upi',v_upi,'card',v_card,'bank',v_bank,'other_payments',v_other,
    'invoices',v_invoices,'shift',v_shift
  );
end $$;


--
-- Name: pos_terminal_day_v45(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_terminal_day_v45(p_tenant_id uuid, p_device_id uuid, p_day date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_base jsonb;v_returns numeric:=0;v_return_count bigint:=0;v_purchase_returns numeric:=0;v_purchase_return_count bigint:=0;v_expenses numeric:=0;v_expense_count bigint:=0;v_held bigint:=0;v_return_rows jsonb:='[]'::jsonb;begin
  select public.pos_terminal_day_v41(p_tenant_id,p_device_id,p_day) into v_base;
  select coalesce(sum(r.grand_total),0),count(*) into v_returns,v_return_count
  from public.sales_returns r where r.tenant_id=p_tenant_id and r.device_id=p_device_id and r.return_date=p_day and r.refund_status<>'waived';
  select coalesce(sum(r.grand_total),0),count(*) into v_purchase_returns,v_purchase_return_count
  from public.purchase_returns r where r.tenant_id=p_tenant_id and r.device_id=p_device_id and r.return_date=p_day and r.credit_status<>'waived';
  select coalesce(sum(e.total_amount),0),count(*) into v_expenses,v_expense_count
  from public.expenses e join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='expense' and o.entity_id=e.id and o.device_id=p_device_id
  where e.tenant_id=p_tenant_id and e.expense_date=p_day and e.status='posted';
  select count(*) into v_held from public.pos_held_sales h where h.tenant_id=p_tenant_id and h.device_id=p_device_id;
  select coalesce(jsonb_agg(x order by x.created_at desc),'[]'::jsonb) into v_return_rows from (
    select r.id,r.return_number,'sale_return'::text return_type,r.return_date,r.grand_total,r.reason,r.created_at,s.sale_number reference,c.name party
    from public.sales_returns r join public.sales s on s.id=r.sale_id join public.customers c on c.id=s.customer_id
    where r.tenant_id=p_tenant_id and r.device_id=p_device_id and r.return_date=p_day
    union all
    select r.id,r.return_number,'purchase_return',r.return_date,r.grand_total,r.reason,r.created_at,p.purchase_number,sp.name
    from public.purchase_returns r join public.purchases p on p.id=r.purchase_id join public.suppliers sp on sp.id=p.supplier_id
    where r.tenant_id=p_tenant_id and r.device_id=p_device_id and r.return_date=p_day
  ) x;
  return coalesce(v_base,'{}'::jsonb)||jsonb_build_object(
    'sales_returns',v_returns,'sales_return_count',v_return_count,
    'purchase_returns',v_purchase_returns,'purchase_return_count',v_purchase_return_count,
    'net_sales',greatest(coalesce((v_base->>'gross_sales')::numeric,0)-v_returns,0),
    'expenses',v_expenses,'expense_count',v_expense_count,'held_count',v_held,'returns',v_return_rows
  );
end $$;


--
-- Name: pos_terminal_day_v471(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_terminal_day_v471(p_tenant_id uuid, p_device_id uuid, p_day date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v jsonb;v_receipts numeric:=0;v_receipt_count bigint:=0;v_receipt_rows jsonb:='[]'::jsonb;begin
  select public.pos_terminal_day_v45(p_tenant_id,p_device_id,p_day) into v;
  select coalesce(sum(r.amount),0),count(*) into v_receipts,v_receipt_count from public.customer_receipts r
  where r.tenant_id=p_tenant_id and r.device_id=p_device_id and r.receipt_date=p_day;
  select coalesce(jsonb_agg(jsonb_build_object('receipt_id',r.id,'receipt_number',r.receipt_number,'customer_id',r.customer_id,
    'customer_name',c.name,'amount',r.amount,'payment_method',r.payment_method,'reference_number',r.reference_number,'created_at',r.created_at)
    order by r.created_at desc),'[]'::jsonb) into v_receipt_rows
  from public.customer_receipts r join public.customers c on c.id=r.customer_id
  where r.tenant_id=p_tenant_id and r.device_id=p_device_id and r.receipt_date=p_day;
  return coalesce(v,'{}'::jsonb)||jsonb_build_object('customer_receipts',v_receipts,'customer_receipt_count',v_receipt_count,'customer_receipt_rows',v_receipt_rows);
end $$;


--
-- Name: pos_terminal_day_v472(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_terminal_day_v472(p_tenant_id uuid, p_device_id uuid, p_day date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v jsonb;
  v_purchase_total numeric:=0;v_purchase_count bigint:=0;v_purchase_returns numeric:=0;
  v_sales_discount numeric:=0;v_sales_tax numeric:=0;v_sales_paid numeric:=0;v_sales_outstanding numeric:=0;
  v_purchase_discount numeric:=0;v_purchase_tax numeric:=0;v_purchase_paid numeric:=0;v_purchase_outstanding numeric:=0;
  v_receipt_cash numeric:=0;v_receipt_upi numeric:=0;v_receipt_card numeric:=0;v_receipt_bank numeric:=0;v_receipt_other numeric:=0;
  v_cash_in numeric:=0;v_cash_out numeric:=0;
  v_shift_count bigint:=0;v_open_shift_count bigint:=0;v_first_start timestamptz;v_last_end timestamptz;
  v_shift_opening numeric:=0;v_shift_closing numeric:=0;v_shift_difference numeric:=0;v_shift_rows jsonb:='[]'::jsonb;
begin
  if not private.v472_terminal_day_module_enabled(p_tenant_id,p_device_id) then
    raise exception 'Terminal Daily is disabled for this POS';
  end if;
  -- Reuse mature sale/return/expense/receipt calculations, then explicitly remove
  -- the legacy single-shift object so Terminal Daily owns no shift state.
  select public.pos_terminal_day_v471(p_tenant_id,p_device_id,p_day) into v;
  v:=coalesce(v,'{}'::jsonb)-array['shift','invoices','returns','customer_receipt_rows'];

  -- Daily sales summary. Outstanding is return-aware and reflects the current
  -- balance of invoices billed on this terminal/day; no transaction rows are returned.
  select
    coalesce(sum(s.discount_total),0),
    coalesce(sum(s.tax_total),0),
    coalesce(sum(coalesce(py.paid,0)),0),
    coalesce(sum(greatest(s.grand_total-coalesce(rt.returned,0)-coalesce(py.paid,0),0)),0)
  into v_sales_discount,v_sales_tax,v_sales_paid,v_sales_outstanding
  from public.sales s
  join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='sale' and o.entity_id=s.id and o.device_id=p_device_id
  left join (select sale_id,sum(amount) paid from public.sale_payments group by sale_id) py on py.sale_id=s.id
  left join (select sale_id,sum(grand_total) returned from public.sales_returns where refund_status<>'waived' group by sale_id) rt on rt.sale_id=s.id
  where s.tenant_id=p_tenant_id and s.sale_date=p_day and coalesce(s.status,'') not in('cancelled','void');

  select count(*),coalesce(sum(p.grand_total),0),coalesce(sum(p.discount_total),0),coalesce(sum(p.tax_total),0),
    coalesce(sum(coalesce(py.paid,0)),0),
    coalesce(sum(greatest(p.grand_total-coalesce(rt.returned,0)-coalesce(py.paid,0),0)),0)
  into v_purchase_count,v_purchase_total,v_purchase_discount,v_purchase_tax,v_purchase_paid,v_purchase_outstanding
  from public.purchases p
  join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='purchase' and o.entity_id=p.id and o.device_id=p_device_id
  left join (select purchase_id,sum(amount) paid from public.purchase_payments group by purchase_id) py on py.purchase_id=p.id
  left join (select purchase_id,sum(grand_total) returned from public.purchase_returns where credit_status<>'waived' group by purchase_id) rt on rt.purchase_id=p.id
  where p.tenant_id=p_tenant_id and p.purchase_date=p_day and coalesce(p.status,'') not in('cancelled','void');

  select
    coalesce(sum(r.amount) filter(where lower(r.payment_method)='cash'),0),
    coalesce(sum(r.amount) filter(where lower(r.payment_method)='upi'),0),
    coalesce(sum(r.amount) filter(where lower(r.payment_method)='card'),0),
    coalesce(sum(r.amount) filter(where lower(r.payment_method)='bank'),0),
    coalesce(sum(r.amount) filter(where lower(r.payment_method) not in('cash','upi','card','bank')),0)
  into v_receipt_cash,v_receipt_upi,v_receipt_card,v_receipt_bank,v_receipt_other
  from public.customer_receipts r
  where r.tenant_id=p_tenant_id and r.device_id=p_device_id and r.receipt_date=p_day;

  select
    coalesce(sum(m.amount) filter(where m.movement_type='cash_in'),0),
    abs(coalesce(sum(m.amount) filter(where m.movement_type='cash_out'),0))
  into v_cash_in,v_cash_out
  from public.cash_drawer_movements m
  join public.cashier_shifts s on s.id=m.shift_id
  where s.tenant_id=p_tenant_id and s.device_id=p_device_id and m.created_at::date=p_day;

  select count(*),count(*) filter(where s.status='open'),min(s.opened_at),max(s.closed_at),
    coalesce(sum(s.opening_cash),0),coalesce(sum(s.declared_cash) filter(where s.status<>'open'),0),
    coalesce(sum(s.difference) filter(where s.status<>'open'),0)
  into v_shift_count,v_open_shift_count,v_first_start,v_last_end,v_shift_opening,v_shift_closing,v_shift_difference
  from public.cashier_shifts s
  where s.tenant_id=p_tenant_id and s.device_id=p_device_id
    and s.opened_at::date<=p_day and coalesce(s.closed_at::date,p_day)>=p_day;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',s.id,'shift_number',s.shift_number,'cashier',coalesce(ul.username,''),'status',s.status,
    'opened_at',s.opened_at,'closed_at',s.closed_at,'opening_cash',s.opening_cash,
    'closing_cash',s.declared_cash,'expected_cash',case when s.status='open' then private.v472_shift_expected_cash(s.id) else s.expected_cash end,
    'difference',s.difference
  ) order by s.opened_at),'[]'::jsonb) into v_shift_rows
  from public.cashier_shifts s left join public.user_login_names ul on ul.user_id=s.user_id
  where s.tenant_id=p_tenant_id and s.device_id=p_device_id
    and s.opened_at::date<=p_day and coalesce(s.closed_at::date,p_day)>=p_day;

  return v||jsonb_build_object(
    'sales_discount',v_sales_discount,'sales_tax',v_sales_tax,'sales_paid',v_sales_paid,
    'sales_outstanding',v_sales_outstanding,
    'net_sales',coalesce((v->>'gross_sales')::numeric,0)-coalesce((v->>'sales_returns')::numeric,0),
    'purchase_count',v_purchase_count,'purchases',v_purchase_total,
    'purchase_discount',v_purchase_discount,'purchase_tax',v_purchase_tax,'purchase_paid',v_purchase_paid,
    'purchase_outstanding',v_purchase_outstanding,
    'net_purchases',v_purchase_total-coalesce((v->>'purchase_returns')::numeric,0),
    'customer_receipts_cash',v_receipt_cash,'customer_receipts_upi',v_receipt_upi,
    'customer_receipts_card',v_receipt_card,'customer_receipts_bank',v_receipt_bank,
    'customer_receipts_other',v_receipt_other,
    'cash_in',v_cash_in,'cash_out',v_cash_out,
    'total_collected',coalesce((v->>'cash')::numeric,0)+coalesce((v->>'upi')::numeric,0)+coalesce((v->>'card')::numeric,0)+coalesce((v->>'bank')::numeric,0)+coalesce((v->>'other_payments')::numeric,0)+coalesce((v->>'customer_receipts')::numeric,0),
    'shift_summary',jsonb_build_object(
      'shift_count',v_shift_count,'open_shift_count',v_open_shift_count,
      'first_start',v_first_start,'last_end',v_last_end,
      'opening_cash',v_shift_opening,'closing_cash',v_shift_closing,'difference',v_shift_difference,
      'shifts',v_shift_rows
    )
  );
end $$;


--
-- Name: pos_terminal_day_v473(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_terminal_day_v473(p_tenant_id uuid, p_device_id uuid, p_day date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v jsonb;
  v_held bigint:=0;
  v_timezone text:='UTC';
  v_business_today date;
begin
  select coalesce(ts.timezone,'UTC') into v_timezone from public.tenant_settings ts where ts.tenant_id=p_tenant_id;
  v_business_today:=(now() at time zone coalesce(v_timezone,'UTC'))::date;
  select public.pos_terminal_day_v472(p_tenant_id,p_device_id,p_day) into v;
  -- V4.7.3 keeps Terminal Daily intentionally summary-only. Individual shift
  -- rows belong to Cashier Shift; historical invoice rows are drill-down only.
  if v ? 'shift_summary' then
    v:=jsonb_set(
      v,
      '{shift_summary}',
      coalesce(v->'shift_summary','{}'::jsonb)-'shifts',
      true
    );
  end if;
  if coalesce(p_day,v_business_today)=v_business_today then
    select count(*) into v_held
    from public.pos_held_sales h
    where h.tenant_id=p_tenant_id and h.device_id=p_device_id;
  end if;
  return coalesce(v,'{}'::jsonb)||jsonb_build_object('held_count',v_held);
end $$;


--
-- Name: pos_terminal_invoices_v473(uuid, uuid, date, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pos_terminal_invoices_v473(p_tenant_id uuid, p_device_id uuid, p_day date DEFAULT CURRENT_DATE, p_query text DEFAULT ''::text, p_limit integer DEFAULT 200) RETURNS TABLE(sale_id uuid, sale_number text, invoice_number text, customer_name text, created_at timestamp with time zone, grand_total numeric, paid_amount numeric, returned_amount numeric, outstanding_amount numeric, status text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_location uuid;
  q text := '%' || lower(trim(coalesce(p_query,''))) || '%';
  lim integer := greatest(1,least(coalesce(p_limit,200),500));
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then
    raise exception 'Access denied';
  end if;

  select d.location_id into v_location
  from public.business_devices d
  where d.id=p_device_id and d.tenant_id=p_tenant_id and d.status='active';

  if v_location is null then raise exception 'Active terminal not found'; end if;
  if not private.erp_user_is_owner(p_tenant_id)
     and not private.erp_user_location_allowed(p_tenant_id,v_location,'view') then
    raise exception 'Terminal access denied';
  end if;

  return query
  select
    s.id,
    s.sale_number::text,
    coalesce(dn.terminal_number,ln.local_number,s.sale_number)::text,
    coalesce(c.name,'')::text,
    s.created_at,
    s.grand_total::numeric,
    coalesce(py.paid,0)::numeric,
    coalesce(rt.returned,0)::numeric,
    greatest(s.grand_total-coalesce(rt.returned,0)-coalesce(py.paid,0),0)::numeric,
    s.status::text
  from public.sales s
  join public.document_origins o
    on o.tenant_id=p_tenant_id and o.entity_type='sale' and o.entity_id=s.id and o.device_id=p_device_id
  join public.customers c on c.id=s.customer_id
  left join public.location_document_numbers ln
    on ln.tenant_id=p_tenant_id and ln.entity_type='sale' and ln.entity_id=s.id
  left join public.device_document_numbers dn
    on dn.tenant_id=p_tenant_id and dn.entity_type='sale' and dn.entity_id=s.id
  left join (
    select sp.sale_id,sum(sp.amount)::numeric paid
    from public.sale_payments sp group by sp.sale_id
  ) py on py.sale_id=s.id
  left join (
    select sr.sale_id,sum(sr.grand_total)::numeric returned
    from public.sales_returns sr where sr.refund_status<>'waived' group by sr.sale_id
  ) rt on rt.sale_id=s.id
  where s.tenant_id=p_tenant_id
    and s.sale_date=coalesce(p_day,current_date)
    and (
      trim(coalesce(p_query,''))='' or
      lower(coalesce(s.sale_number,'')) like q or
      lower(coalesce(dn.terminal_number,ln.local_number,'')) like q or
      lower(coalesce(c.name,'')) like q
    )
  order by s.created_at desc
  limit lim;
end $$;


--
-- Name: pricing_list_save_v482(uuid, uuid, text, text, text, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pricing_list_save_v482(p_tenant_id uuid, p_price_list_id uuid, p_code text, p_name text, p_description text, p_is_default boolean, p_active boolean DEFAULT true) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v_id uuid;begin
 if not private.v482_pricing_manage_allowed(p_tenant_id) then raise exception 'Pricing manage permission required';end if;
 if trim(coalesce(p_code,''))='' or trim(coalesce(p_name,''))='' then raise exception 'Code and name are required';end if;
 if p_is_default then update public.price_lists_v482 set is_default=false,updated_at=now() where tenant_id=p_tenant_id;end if;
 if p_price_list_id is null then
   insert into public.price_lists_v482(tenant_id,code,name,description,is_default,active) values(p_tenant_id,upper(trim(p_code)),trim(p_name),nullif(trim(coalesce(p_description,'')),''),p_is_default,p_active) returning id into v_id;
 else
   update public.price_lists_v482 set code=upper(trim(p_code)),name=trim(p_name),description=nullif(trim(coalesce(p_description,'')),''),is_default=p_is_default,active=p_active,updated_at=now() where id=p_price_list_id and tenant_id=p_tenant_id returning id into v_id;
   if v_id is null then raise exception 'Price list not found';end if;
 end if;
 if not exists(select 1 from public.price_lists_v482 pl where pl.tenant_id=p_tenant_id and pl.active and pl.is_default) then update public.price_lists_v482 set is_default=true where id=v_id;end if;
 perform private.thq_sync_bump_v480(p_tenant_id,'catalogue','price_list',v_id::text,'save'); return v_id;
end$$;


--
-- Name: pricing_lists_v482(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pricing_lists_v482(p_tenant_id uuid) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$begin
 if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
 return query select jsonb_build_object('price_list_id',pl.id,'code',pl.code,'name',pl.name,'description',pl.description,'is_default',pl.is_default,'system_list',pl.system_list,'active',pl.active)
 from public.price_lists_v482 pl where pl.tenant_id=p_tenant_id order by pl.is_default desc,pl.name;
end$$;


--
-- Name: pricing_resolve_v482(uuid, uuid, uuid, uuid, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pricing_resolve_v482(p_tenant_id uuid, p_variant_id uuid, p_customer_id uuid, p_unit_id uuid, p_quantity numeric, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$begin
 if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
 return private.pricing_resolve_v482_internal(p_tenant_id,p_variant_id,p_customer_id,p_unit_id,p_quantity,p_location_id);
end$$;


--
-- Name: pricing_rule_save_v482(uuid, uuid, uuid, uuid, uuid, numeric, numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pricing_rule_save_v482(p_tenant_id uuid, p_rule_id uuid, p_price_list_id uuid, p_variant_id uuid, p_unit_id uuid, p_min_quantity numeric, p_unit_price numeric, p_active boolean DEFAULT true) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v_id uuid;begin
 if not private.v482_pricing_manage_allowed(p_tenant_id) then raise exception 'Pricing manage permission required';end if;
 if coalesce(p_min_quantity,0)<=0 then raise exception 'Minimum quantity must be greater than zero';end if;
 if coalesce(p_unit_price,-1)<0 then raise exception 'Price cannot be negative';end if;
 if not exists(select 1 from public.price_lists_v482 pl where pl.id=p_price_list_id and pl.tenant_id=p_tenant_id and pl.active) then raise exception 'Price list not found';end if;
 if not exists(select 1 from public.product_units_v481 pu where pu.tenant_id=p_tenant_id and pu.variant_id=p_variant_id and pu.unit_id=p_unit_id and pu.active and pu.allow_sale) then raise exception 'Unit is not enabled for sale on this product';end if;
 if p_rule_id is null then
  insert into public.price_list_items_v482(tenant_id,price_list_id,variant_id,unit_id,min_quantity,unit_price,active) values(p_tenant_id,p_price_list_id,p_variant_id,p_unit_id,p_min_quantity,p_unit_price,p_active)
  on conflict(tenant_id,price_list_id,variant_id,unit_id,min_quantity) do update set unit_price=excluded.unit_price,active=excluded.active,updated_at=now() returning id into v_id;
 else
  update public.price_list_items_v482 set price_list_id=p_price_list_id,variant_id=p_variant_id,unit_id=p_unit_id,min_quantity=p_min_quantity,unit_price=p_unit_price,active=p_active,updated_at=now() where id=p_rule_id and tenant_id=p_tenant_id returning id into v_id;
  if v_id is null then raise exception 'Pricing rule not found';end if;
 end if;
 perform private.thq_sync_bump_v480(p_tenant_id,'catalogue','price_rule',v_id::text,'save');return v_id;
end$$;


--
-- Name: pricing_rules_v482(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pricing_rules_v482(p_tenant_id uuid, p_price_list_id uuid, p_variant_id uuid DEFAULT NULL::uuid) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$begin
 if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
 return query select jsonb_build_object('rule_id',r.id,'price_list_id',r.price_list_id,'price_list_name',pl.name,'variant_id',r.variant_id,'product_name',p.name,'sku',pv.sku,'unit_id',r.unit_id,'unit_code',u.code,'unit_name',u.name,'min_quantity',r.min_quantity,'unit_price',r.unit_price,'active',r.active)
 from public.price_list_items_v482 r join public.price_lists_v482 pl on pl.id=r.price_list_id join public.product_variants pv on pv.id=r.variant_id join public.products p on p.id=pv.product_id join public.inventory_units_v481 u on u.id=r.unit_id
 where r.tenant_id=p_tenant_id and r.price_list_id=p_price_list_id and (p_variant_id is null or r.variant_id=p_variant_id) order by p.name,u.name,r.min_quantity;
end$$;


--
-- Name: product_identifier_archive_v482(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.product_identifier_archive_v482(p_tenant_id uuid, p_identifier_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v_variant uuid;begin
 if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'inventory.manage') then raise exception 'Inventory manage permission required';end if;
 update public.product_identifiers_v482 set active=false,is_primary=false,updated_at=now() where id=p_identifier_id and tenant_id=p_tenant_id returning variant_id into v_variant;
 if v_variant is null then raise exception 'Identifier not found';end if;
 perform private.v482_sync_legacy_identifiers(p_tenant_id,v_variant);
 perform private.thq_sync_bump_v480(p_tenant_id,'catalogue','product_identifier',v_variant::text,'archive');
end$$;


--
-- Name: product_identifier_generate_v482(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.product_identifier_generate_v482(p_tenant_id uuid, p_variant_id uuid, p_identifier_type text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_type text:=lower(trim(coalesce(p_identifier_type,'')));v_seq bigint;v_seed text;v_code text;v_id uuid;v_short text;begin
 if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'inventory.manage') then raise exception 'Inventory manage permission required';end if;
 if not exists(select 1 from public.product_variants pv where pv.tenant_id=p_tenant_id and pv.id=p_variant_id) then raise exception 'Product variant not found';end if;
 insert into public.product_identifier_sequences_v482(tenant_id) values(p_tenant_id) on conflict do nothing;
 if v_type='barcode' then
  select s.next_barcode into v_seq from public.product_identifier_sequences_v482 s where s.tenant_id=p_tenant_id for update;
  update public.product_identifier_sequences_v482 set next_barcode=next_barcode+1,updated_at=now() where tenant_id=p_tenant_id;
  v_seed:='28'||lpad(v_seq::text,10,'0');v_code:=v_seed||private.v482_ean13_check_digit(v_seed);
 elsif v_type='qr' then
  select s.next_qr into v_seq from public.product_identifier_sequences_v482 s where s.tenant_id=p_tenant_id for update;
  update public.product_identifier_sequences_v482 set next_qr=next_qr+1,updated_at=now() where tenant_id=p_tenant_id;
  v_short:=replace(left(p_variant_id::text,8),'-','');v_code:='THQ:PRODUCT:'||v_short||':'||lpad(v_seq::text,8,'0');
 else raise exception 'Only barcode or QR identifiers can be generated automatically';end if;
 v_id:=public.product_identifier_save_v482(p_tenant_id,null,p_variant_id,v_type,v_code,null,'Generated by THQ',not exists(select 1 from public.product_identifiers_v482 i where i.tenant_id=p_tenant_id and i.variant_id=p_variant_id and i.identifier_type=v_type and i.active and i.is_primary),true);
 update public.product_identifiers_v482 set generated=true where id=v_id;
 return jsonb_build_object('identifier_id',v_id,'identifier_type',v_type,'code',v_code);
end$$;


--
-- Name: product_identifier_save_v482(uuid, uuid, uuid, text, text, uuid, text, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.product_identifier_save_v482(p_tenant_id uuid, p_identifier_id uuid, p_variant_id uuid, p_identifier_type text, p_code text, p_supplier_id uuid, p_label text, p_is_primary boolean, p_active boolean DEFAULT true) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_id uuid;v_type text:=lower(trim(coalesce(p_identifier_type,'')));v_code text:=trim(coalesce(p_code,''));begin
 if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'inventory.manage') then raise exception 'Inventory manage permission required';end if;
 if v_type not in('barcode','qr','manufacturer','supplier','internal','alternate_sku') then raise exception 'Invalid identifier type';end if;
 if v_code='' then raise exception 'Identifier code is required';end if;
 if not exists(select 1 from public.product_variants pv where pv.tenant_id=p_tenant_id and pv.id=p_variant_id) then raise exception 'Product variant not found';end if;
 if exists(select 1 from public.product_variants pv where pv.tenant_id=p_tenant_id and pv.id<>p_variant_id and lower(trim(pv.sku))=lower(v_code)) then raise exception 'Code % is already used as another product SKU',v_code;end if;
 if p_supplier_id is not null and not exists(select 1 from public.suppliers s where s.tenant_id=p_tenant_id and s.id=p_supplier_id) then raise exception 'Supplier not found';end if;
 if p_is_primary then update public.product_identifiers_v482 set is_primary=false,updated_at=now() where tenant_id=p_tenant_id and variant_id=p_variant_id and identifier_type=v_type and active;end if;
 if p_identifier_id is null then
  insert into public.product_identifiers_v482(tenant_id,variant_id,identifier_type,code,supplier_id,label,is_primary,active) values(p_tenant_id,p_variant_id,v_type,v_code,p_supplier_id,nullif(trim(coalesce(p_label,'')),''),p_is_primary,p_active) returning id into v_id;
 else
  update public.product_identifiers_v482 set identifier_type=v_type,code=v_code,supplier_id=p_supplier_id,label=nullif(trim(coalesce(p_label,'')),''),is_primary=p_is_primary,active=p_active,updated_at=now() where id=p_identifier_id and tenant_id=p_tenant_id and variant_id=p_variant_id returning id into v_id;
  if v_id is null then raise exception 'Identifier not found';end if;
 end if;
 perform private.v482_sync_legacy_identifiers(p_tenant_id,p_variant_id);
 perform private.thq_sync_bump_v480(p_tenant_id,'catalogue','product_identifier',p_variant_id::text,'save');return v_id;
end$$;


--
-- Name: product_identifiers_v482_list(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.product_identifiers_v482_list(p_tenant_id uuid, p_variant_id uuid) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$begin
 if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
 return query select jsonb_build_object('identifier_id',i.id,'variant_id',i.variant_id,'identifier_type',i.identifier_type,'code',i.code,'supplier_id',i.supplier_id,'supplier_name',s.name,'label',i.label,'is_primary',i.is_primary,'generated',i.generated,'active',i.active,'created_at',i.created_at)
 from public.product_identifiers_v482 i left join public.suppliers s on s.id=i.supplier_id where i.tenant_id=p_tenant_id and i.variant_id=p_variant_id order by i.active desc,i.is_primary desc,i.identifier_type,i.code;
end$$;


--
-- Name: product_profit_explain_v600(uuid, uuid, date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.product_profit_explain_v600(p_tenant_id uuid, p_variant_id uuid, p_from date, p_to date, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  cur record;
  prev record;
  v_days integer;
  v_prev_from date;
  v_prev_to date;
  v_cur_net_qty numeric;
  v_prev_net_qty numeric;
  v_cur_avg_revenue numeric;
  v_prev_avg_revenue numeric;
  v_cur_avg_cost numeric;
  v_prev_avg_cost numeric;
  v_cur_discount_rate numeric;
  v_prev_discount_rate numeric;
  v_cur_return_rate numeric;
  v_prev_return_rate numeric;
  v_drivers jsonb := '[]'::jsonb;
  v_profit_change numeric;
begin
  if not private.has_permission(p_tenant_id,'profitability.view') then raise exception 'Permission denied' using errcode='42501'; end if;
  if p_variant_id is null or p_from is null or p_to is null or p_to<p_from then raise exception 'Variant and valid period are required'; end if;

  select * into cur from private.v600_product_profit_rows(p_tenant_id,p_from,p_to,p_location_id,p_variant_id) limit 1;
  v_days := (p_to-p_from)+1; v_prev_to:=p_from-1; v_prev_from:=v_prev_to-(v_days-1);
  select * into prev from private.v600_product_profit_rows(p_tenant_id,v_prev_from,v_prev_to,p_location_id,p_variant_id) limit 1;

  if cur.variant_id is null then
    select v.id as variant_id,p.id as product_id,p.name as product_name,v.name as variant_name,v.sku,p.category_id,c.name as category_name,p.brand_id,b.name as brand_name,
      0::numeric sold_qty,0::numeric sale_revenue,0::numeric sale_cogs,0::numeric sale_discount,0::numeric returned_qty,0::numeric return_revenue,0::numeric return_cogs,
      0::numeric net_revenue,0::numeric net_cogs,0::numeric gross_profit,null::numeric margin_pct
    into cur
    from public.product_variants v join public.products p on p.id=v.product_id and p.tenant_id=v.tenant_id
    left join public.product_categories c on c.id=p.category_id and c.tenant_id=p.tenant_id
    left join public.product_brands b on b.id=p.brand_id and b.tenant_id=p.tenant_id
    where v.tenant_id=p_tenant_id and v.id=p_variant_id;
    if cur.variant_id is null then raise exception 'Product variant not found'; end if;
  end if;
  if prev.variant_id is null then
    prev := cur;
    prev.sold_qty:=0; prev.sale_revenue:=0; prev.sale_cogs:=0; prev.sale_discount:=0; prev.returned_qty:=0; prev.return_revenue:=0; prev.return_cogs:=0; prev.net_revenue:=0; prev.net_cogs:=0; prev.gross_profit:=0; prev.margin_pct:=null;
  end if;

  v_cur_net_qty := cur.sold_qty-cur.returned_qty;
  v_prev_net_qty := prev.sold_qty-prev.returned_qty;
  v_cur_avg_revenue := case when v_cur_net_qty=0 then null else cur.net_revenue/v_cur_net_qty end;
  v_prev_avg_revenue := case when v_prev_net_qty=0 then null else prev.net_revenue/v_prev_net_qty end;
  v_cur_avg_cost := case when v_cur_net_qty=0 then null else cur.net_cogs/v_cur_net_qty end;
  v_prev_avg_cost := case when v_prev_net_qty=0 then null else prev.net_cogs/v_prev_net_qty end;
  v_cur_discount_rate := case when (cur.sale_revenue+cur.sale_discount)=0 then null else cur.sale_discount*100.0/(cur.sale_revenue+cur.sale_discount) end;
  v_prev_discount_rate := case when (prev.sale_revenue+prev.sale_discount)=0 then null else prev.sale_discount*100.0/(prev.sale_revenue+prev.sale_discount) end;
  v_cur_return_rate := case when cur.sold_qty=0 then null else cur.returned_qty*100.0/cur.sold_qty end;
  v_prev_return_rate := case when prev.sold_qty=0 then null else prev.returned_qty*100.0/prev.sold_qty end;
  v_profit_change := cur.gross_profit-prev.gross_profit;

  v_drivers := v_drivers || jsonb_build_array(jsonb_build_object(
    'driver','net_sales_change','impact_on_profit',round(cur.net_revenue-prev.net_revenue,4),
    'current',round(cur.net_revenue,4),'previous',round(prev.net_revenue,4),
    'explanation','Exact gross-profit bridge component: change in net product revenue.'
  ));
  v_drivers := v_drivers || jsonb_build_array(jsonb_build_object(
    'driver','cogs_change','impact_on_profit',round(-(cur.net_cogs-prev.net_cogs),4),
    'current',round(cur.net_cogs,4),'previous',round(prev.net_cogs,4),
    'explanation','Exact gross-profit bridge component: higher COGS reduces profit; lower COGS increases profit.'
  ));
  if v_cur_avg_cost is not null and v_prev_avg_cost is not null and v_cur_avg_cost is distinct from v_prev_avg_cost then
    v_drivers := v_drivers || jsonb_build_array(jsonb_build_object('driver','average_recognized_cost_per_net_unit','current',round(v_cur_avg_cost,4),'previous',round(v_prev_avg_cost,4),'change_pct',case when v_prev_avg_cost=0 then null else round((v_cur_avg_cost-v_prev_avg_cost)*100.0/v_prev_avg_cost,4) end,'diagnostic',true));
  end if;
  if v_cur_avg_revenue is not null and v_prev_avg_revenue is not null and v_cur_avg_revenue is distinct from v_prev_avg_revenue then
    v_drivers := v_drivers || jsonb_build_array(jsonb_build_object('driver','average_net_revenue_per_net_unit','current',round(v_cur_avg_revenue,4),'previous',round(v_prev_avg_revenue,4),'change_pct',case when v_prev_avg_revenue=0 then null else round((v_cur_avg_revenue-v_prev_avg_revenue)*100.0/v_prev_avg_revenue,4) end,'diagnostic',true));
  end if;
  if v_cur_discount_rate is distinct from v_prev_discount_rate then
    v_drivers := v_drivers || jsonb_build_array(jsonb_build_object('driver','discount_rate','current_pct',case when v_cur_discount_rate is null then null else round(v_cur_discount_rate,4) end,'previous_pct',case when v_prev_discount_rate is null then null else round(v_prev_discount_rate,4) end,'diagnostic',true));
  end if;
  if v_cur_return_rate is distinct from v_prev_return_rate then
    v_drivers := v_drivers || jsonb_build_array(jsonb_build_object('driver','return_rate','current_pct',case when v_cur_return_rate is null then null else round(v_cur_return_rate,4) end,'previous_pct',case when v_prev_return_rate is null then null else round(v_prev_return_rate,4) end,'diagnostic',true));
  end if;

  return jsonb_build_object(
    'product',jsonb_build_object('variant_id',cur.variant_id,'product_id',cur.product_id,'product_name',cur.product_name,'variant_name',cur.variant_name,'sku',cur.sku,'category',cur.category_name,'brand',cur.brand_name),
    'period',jsonb_build_object('from',p_from,'to',p_to),
    'equation',jsonb_build_object('label','Net Sales - Recognized COGS = Gross Profit','net_sales',round(cur.net_revenue,4),'recognized_cogs',round(cur.net_cogs,4),'gross_profit',round(cur.gross_profit,4),'margin_pct',cur.margin_pct),
    'returns',jsonb_build_object('returned_qty',cur.returned_qty,'revenue_reversed',round(cur.return_revenue,4),'cogs_reversed',round(cur.return_cogs,4)),
    'previous_period',jsonb_build_object('from',v_prev_from,'to',v_prev_to,'net_sales',round(prev.net_revenue,4),'recognized_cogs',round(prev.net_cogs,4),'gross_profit',round(prev.gross_profit,4),'margin_pct',prev.margin_pct),
    'profit_change',round(v_profit_change,4),
    'drivers',v_drivers,
    'integrity_note','Exact bridge drivers sum to gross-profit change. Diagnostic rates describe contributing conditions but are not asserted as additive causal impacts.'
  );
end;
$$;


--
-- Name: product_profitability_v600(uuid, date, date, uuid, uuid, uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.product_profitability_v600(p_tenant_id uuid, p_from date, p_to date, p_location_id uuid DEFAULT NULL::uuid, p_variant_id uuid DEFAULT NULL::uuid, p_category_id uuid DEFAULT NULL::uuid, p_brand_id uuid DEFAULT NULL::uuid, p_query text DEFAULT NULL::text, p_limit integer DEFAULT 500) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_rows jsonb;
  v_totals jsonb;
  v_days integer;
  v_prev_from date;
  v_prev_to date;
  v_prev jsonb;
begin
  if not private.has_permission(p_tenant_id,'profitability.view') then
    raise exception 'Permission denied' using errcode='42501';
  end if;
  if p_from is null or p_to is null or p_to<p_from then raise exception 'Valid from/to dates are required'; end if;

  select coalesce(jsonb_agg(to_jsonb(q) order by q.gross_profit asc,q.net_revenue desc),'[]'::jsonb)
  into v_rows
  from (
    select r.*
    from private.v600_product_profit_rows(p_tenant_id,p_from,p_to,p_location_id,p_variant_id) r
    where (p_category_id is null or r.category_id=p_category_id)
      and (p_brand_id is null or r.brand_id=p_brand_id)
      and (nullif(trim(coalesce(p_query,'')),'') is null
        or r.product_name ilike '%'||trim(p_query)||'%'
        or r.variant_name ilike '%'||trim(p_query)||'%'
        or r.sku ilike '%'||trim(p_query)||'%')
    order by r.gross_profit asc,r.net_revenue desc
    limit greatest(1,least(coalesce(p_limit,500),2000))
  ) q;

  select jsonb_build_object(
    'sales',round(coalesce(sum(r.net_revenue),0),4),
    'cost',round(coalesce(sum(r.net_cogs),0),4),
    'profit',round(coalesce(sum(r.gross_profit),0),4),
    'margin_pct',case when coalesce(sum(r.net_revenue),0)=0 then null else round(sum(r.gross_profit)*100.0/sum(r.net_revenue),4) end,
    'sold_qty',coalesce(sum(r.sold_qty),0),
    'returned_qty',coalesce(sum(r.returned_qty),0),
    'discount',round(coalesce(sum(r.sale_discount),0),4),
    'return_revenue',round(coalesce(sum(r.return_revenue),0),4),
    'return_cost',round(coalesce(sum(r.return_cogs),0),4)
  ) into v_totals
  from private.v600_product_profit_rows(p_tenant_id,p_from,p_to,p_location_id,p_variant_id) r
  where (p_category_id is null or r.category_id=p_category_id)
    and (p_brand_id is null or r.brand_id=p_brand_id)
    and (nullif(trim(coalesce(p_query,'')),'') is null
      or r.product_name ilike '%'||trim(p_query)||'%'
      or r.variant_name ilike '%'||trim(p_query)||'%'
      or r.sku ilike '%'||trim(p_query)||'%');

  v_days := (p_to-p_from)+1;
  v_prev_to := p_from-1;
  v_prev_from := v_prev_to-(v_days-1);
  select jsonb_build_object(
    'from',v_prev_from,'to',v_prev_to,
    'sales',round(coalesce(sum(r.net_revenue),0),4),
    'cost',round(coalesce(sum(r.net_cogs),0),4),
    'profit',round(coalesce(sum(r.gross_profit),0),4),
    'margin_pct',case when coalesce(sum(r.net_revenue),0)=0 then null else round(sum(r.gross_profit)*100.0/sum(r.net_revenue),4) end
  ) into v_prev
  from private.v600_product_profit_rows(p_tenant_id,v_prev_from,v_prev_to,p_location_id,p_variant_id) r
  where (p_category_id is null or r.category_id=p_category_id)
    and (p_brand_id is null or r.brand_id=p_brand_id);

  return jsonb_build_object(
    'period',jsonb_build_object('from',p_from,'to',p_to,'location_id',p_location_id),
    'basis','Net product revenue before GST minus recognized sale-item COGS; returns reverse original sale-item revenue and cost proportionally.',
    'totals',v_totals,
    'previous_period',v_prev,
    'products',v_rows
  );
end;
$$;


--
-- Name: production_recipe_save(uuid, uuid, text, uuid, numeric, text, boolean, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.production_recipe_save(p_tenant_id uuid, p_recipe_id uuid, p_name text, p_output_variant_id uuid, p_output_quantity numeric, p_notes text, p_active boolean, p_items jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_id uuid; x jsonb; begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  if not private.erp_has_permission(p_tenant_id,'production.manage') then raise exception 'Permission denied'; end if;
  if trim(coalesce(p_name,''))='' or coalesce(p_output_quantity,0)<=0 then raise exception 'Invalid recipe'; end if;
  if p_recipe_id is null then
    insert into public.production_recipes(tenant_id,name,output_variant_id,output_quantity,notes,active)
    values(p_tenant_id,trim(p_name),p_output_variant_id,p_output_quantity,nullif(trim(p_notes),''),coalesce(p_active,true)) returning id into v_id;
  else
    update public.production_recipes set name=trim(p_name),output_variant_id=p_output_variant_id,output_quantity=p_output_quantity,notes=nullif(trim(p_notes),''),active=coalesce(p_active,true),updated_at=now()
    where id=p_recipe_id and tenant_id=p_tenant_id returning id into v_id;
    if v_id is null then raise exception 'Recipe not found'; end if;
    delete from public.production_recipe_items where recipe_id=v_id;
  end if;
  if jsonb_typeof(coalesce(p_items,'[]'::jsonb))<>'array' then raise exception 'Recipe items must be array'; end if;
  for x in select * from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) loop
    if coalesce((x->>'quantity')::numeric,0)<=0 then continue; end if;
    insert into public.production_recipe_items(recipe_id,tenant_id,input_variant_id,quantity,waste_percent)
    values(v_id,p_tenant_id,(x->>'input_variant_id')::uuid,(x->>'quantity')::numeric,coalesce(nullif(x->>'waste_percent','')::numeric,0));
  end loop;
  perform private.business_audit_write(p_tenant_id,'save','production_recipe',v_id,null,null,jsonb_build_object('name',p_name));
  return v_id;
end $$;


--
-- Name: production_recipes_list(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.production_recipes_list(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v jsonb; begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',r.id,'tracking_code',r.tracking_code,'name',r.name,'output_variant_id',r.output_variant_id,
    'output_quantity',r.output_quantity,'notes',r.notes,'active',r.active,
    'items',coalesce((select jsonb_agg(jsonb_build_object('id',i.id,'input_variant_id',i.input_variant_id,'quantity',i.quantity,'waste_percent',i.waste_percent) order by i.id) from public.production_recipe_items i where i.recipe_id=r.id),'[]'::jsonb)
  ) order by r.name),'[]'::jsonb) into v from public.production_recipes r where r.tenant_id=p_tenant_id;
  return v;
end $$;


--
-- Name: production_recipes_list_v32(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.production_recipes_list_v32(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if not (private.erp_user_is_owner(p_tenant_id)
          or private.erp_has_permission(p_tenant_id,'production.view')
          or private.erp_has_permission(p_tenant_id,'production.run')
          or private.erp_has_permission(p_tenant_id,'production.manage')) then
    raise exception 'Permission denied';
  end if;
  return public.production_recipes_list(p_tenant_id);
end $$;


--
-- Name: production_run_complete(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.production_run_complete(p_tenant_id uuid, p_run_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  if not private.erp_has_permission(p_tenant_id,'production.run') and not private.erp_has_permission(p_tenant_id,'production.manage') then raise exception 'Permission denied'; end if;
  update public.production_runs set status='completed',completed_at=now() where id=p_run_id and tenant_id=p_tenant_id and status='started';
  if not found then raise exception 'Production run not found or already closed'; end if;
  perform private.business_audit_write(p_tenant_id,'complete','production_run',p_run_id,null,null,'{}'::jsonb);
end $$;


--
-- Name: production_run_execute(uuid, uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.production_run_execute(p_tenant_id uuid, p_recipe_id uuid, p_location_id uuid, p_batches numeric, p_notes text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_run jsonb;v_run_id uuid;v_run_number text;v_output uuid;v_output_qty numeric;x jsonb;begin
  v_run:=public.production_run_start(p_tenant_id,p_recipe_id,p_location_id,p_batches,p_notes);
  v_run_id:=(v_run->>'run_id')::uuid;v_run_number:=v_run->>'run_number';v_output:=(v_run->>'output_variant_id')::uuid;v_output_qty:=(v_run->>'output_quantity')::numeric;
  for x in select * from jsonb_array_elements(v_run->'raw_materials') loop
    perform public.inventory_adjust_stock(p_tenant_id,(x->>'variant_id')::uuid,-((x->>'quantity')::numeric),'Production raw material • '||v_run_number);
  end loop;
  perform public.inventory_adjust_stock(p_tenant_id,v_output,v_output_qty,'Production finished goods • '||v_run_number);
  perform public.production_run_complete(p_tenant_id,v_run_id);
  return v_run || jsonb_build_object('status','completed');
end $$;


--
-- Name: production_run_execute_v32(uuid, uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.production_run_execute_v32(p_tenant_id uuid, p_recipe_id uuid, p_location_id uuid, p_batches numeric, p_notes text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if not private.erp_user_location_allowed(p_tenant_id,p_location_id,'operate')
     and not private.erp_has_permission(p_tenant_id,'locations.manage_all') then
    raise exception 'You cannot post production for this store';
  end if;
  return public.production_run_execute(p_tenant_id,p_recipe_id,p_location_id,p_batches,p_notes);
end $$;


--
-- Name: production_run_start(uuid, uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.production_run_start(p_tenant_id uuid, p_recipe_id uuid, p_location_id uuid, p_batches numeric, p_notes text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_id uuid:=gen_random_uuid();v_run text;v_tracking text;v_recipe public.production_recipes%rowtype;v_items jsonb; begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  if not private.erp_has_permission(p_tenant_id,'production.run') and not private.erp_has_permission(p_tenant_id,'production.manage') then raise exception 'Permission denied'; end if;
  if coalesce(p_batches,0)<=0 then raise exception 'Batch quantity must be positive'; end if;
  select * into v_recipe from public.production_recipes where id=p_recipe_id and tenant_id=p_tenant_id and active;
  if v_recipe.id is null then raise exception 'Recipe not found'; end if;
  insert into public.production_runs(id,tenant_id,recipe_id,run_number,location_id,planned_batches,notes,created_by)
  values(v_id,p_tenant_id,p_recipe_id,'',p_location_id,p_batches,nullif(trim(p_notes),''),auth.uid()) returning run_number,tracking_code into v_run,v_tracking;
  select coalesce(jsonb_agg(jsonb_build_object('variant_id',i.input_variant_id,'quantity',i.quantity*p_batches*(1+i.waste_percent/100))),'[]'::jsonb)
  into v_items from public.production_recipe_items i where i.recipe_id=p_recipe_id;
  insert into public.document_origins(tenant_id,entity_type,entity_id,location_id,created_by) values(p_tenant_id,'production_run',v_id,p_location_id,auth.uid()) on conflict do nothing;
  return jsonb_build_object('run_id',v_id,'run_number',v_run,'tracking_code',v_tracking,'output_variant_id',v_recipe.output_variant_id,'output_quantity',v_recipe.output_quantity*p_batches,'raw_materials',v_items);
end $$;


--
-- Name: production_runs_list(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.production_runs_list(p_tenant_id uuid, p_limit integer DEFAULT 200) RETURNS TABLE(id uuid, tracking_code text, run_number text, recipe_id uuid, recipe_name text, location_id uuid, location_name text, planned_batches numeric, status text, notes text, started_at timestamp with time zone, completed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  return query select pr.id,pr.tracking_code,pr.run_number,pr.recipe_id,r.name,pr.location_id,l.name,pr.planned_batches,pr.status,pr.notes,pr.started_at,pr.completed_at
  from public.production_runs pr join public.production_recipes r on r.id=pr.recipe_id left join public.business_locations l on l.id=pr.location_id
  where pr.tenant_id=p_tenant_id order by pr.started_at desc limit greatest(1,least(coalesce(p_limit,200),1000));
end $$;


--
-- Name: production_runs_list_v32(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.production_runs_list_v32(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 200) RETURNS TABLE(id uuid, tracking_code text, run_number text, recipe_id uuid, recipe_name text, location_id uuid, location_name text, planned_batches numeric, status text, notes text, started_at timestamp with time zone, completed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if not (private.erp_user_is_owner(p_tenant_id)
          or private.erp_has_permission(p_tenant_id,'production.view')
          or private.erp_has_permission(p_tenant_id,'production.run')
          or private.erp_has_permission(p_tenant_id,'production.manage')) then
    raise exception 'Permission denied';
  end if;
  if p_location_id is not null and not private.erp_document_scope_allowed(p_tenant_id,p_location_id,p_location_id,'view') then
    raise exception 'Location access denied';
  end if;
  return query
  select pr.id,pr.tracking_code,pr.run_number,pr.recipe_id,r.name,pr.location_id,l.name,
         pr.planned_batches,pr.status,pr.notes,pr.started_at,pr.completed_at
  from public.production_runs pr
  join public.production_recipes r on r.id=pr.recipe_id
  left join public.business_locations l on l.id=pr.location_id
  where pr.tenant_id=p_tenant_id
    and private.erp_document_scope_allowed(p_tenant_id,pr.location_id,p_location_id,'view')
  order by pr.started_at desc
  limit greatest(1,least(coalesce(p_limit,200),1000));
end $$;


--
-- Name: purchase_cycle_summary_v490(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_cycle_summary_v490(p_tenant_id uuid, p_purchase_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_loc uuid;v jsonb;begin
  select location_id into v_loc from public.purchase_orders_v480 where tenant_id=p_tenant_id and id=p_purchase_order_id;
  if v_loc is null then raise exception 'Purchase Order not found';end if;
  perform private.purchasing_v484_access(p_tenant_id,v_loc,false);
  select jsonb_build_object(
    'purchase_order_id',po.id,'order_number',po.order_number,'status',po.status,
    'request_id',po.request_id,'request_number',pr.request_number,
    'supplier_id',po.supplier_id,'supplier_name',s.name,'location_id',po.location_id,'location_name',l.name,
    'ordered_quantity',coalesce(sum(i.quantity),0),'received_quantity',coalesce(sum(i.received_quantity),0),
    'accepted_quantity',coalesce(sum(i.accepted_quantity),0),'damaged_quantity',coalesce(sum(i.damaged_quantity),0),
    'rejected_quantity',coalesce(sum(i.rejected_quantity),0),'invoiced_quantity',coalesce(sum(i.invoiced_quantity),0),
    'remaining_receive_quantity',coalesce(sum(greatest(i.quantity-i.received_quantity,0)),0),
    'remaining_invoice_quantity',coalesce(sum(greatest(i.accepted_quantity+i.damaged_quantity-i.invoiced_quantity,0)),0),
    'po_total',po.grand_total,
    'posted_invoice_total',coalesce((select sum(pi.grand_total) from public.purchase_invoices_v484 pi where pi.purchase_order_id=po.id and pi.status in('posted','part_paid','paid')),0),
    'invoice_balance_due',coalesce((select sum(pi.balance_due) from public.purchase_invoices_v484 pi where pi.purchase_order_id=po.id and pi.status in('posted','part_paid')),0),
    'grn_count',(select count(*) from public.goods_receipts_v484 g where g.purchase_order_id=po.id and g.status='posted'),
    'invoice_count',(select count(*) from public.purchase_invoices_v484 pi where pi.purchase_order_id=po.id and pi.status<>'void')
  ) into v
  from public.purchase_orders_v480 po
  join public.suppliers s on s.id=po.supplier_id
  join public.business_locations l on l.id=po.location_id
  left join public.purchase_requests_v484 pr on pr.id=po.request_id
  left join public.purchase_order_items_v480 i on i.purchase_order_id=po.id
  where po.tenant_id=p_tenant_id and po.id=p_purchase_order_id
  group by po.id,pr.request_number,s.name,l.name;
  return coalesce(v,'{}'::jsonb);
end $$;


--
-- Name: purchase_invoice_create_v484(uuid, uuid, text, date, date, jsonb, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_invoice_create_v484(p_tenant_id uuid, p_purchase_order_id uuid, p_supplier_invoice_number text, p_invoice_date date, p_due_date date, p_items jsonb, p_additional_charges numeric DEFAULT 0, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare po public.purchase_orders_v480%rowtype;v_id uuid:=gen_random_uuid();v_no text;x jsonb;poi public.purchase_order_items_v480%rowtype;gi public.goods_receipt_items_v484%rowtype;v_qty numeric;v_cost numeric;v_rate numeric;v_line numeric;v_tax numeric;v_sub numeric:=0;v_tax_total numeric:=0;v_total numeric:=0;v_invoiced numeric;v_received_payable numeric;begin
  select * into po from public.purchase_orders_v480 where tenant_id=p_tenant_id and id=p_purchase_order_id for update;if not found then raise exception 'Purchase Order not found';end if;perform private.purchasing_v484_access(p_tenant_id,po.location_id,true);
  if po.status not in('partially_received','received','closed') then raise exception 'Purchase Invoice requires posted GRN quantities';end if;
  if p_items is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'At least one invoice line is required';end if;
  if trim(coalesce(p_supplier_invoice_number,''))='' then raise exception 'Supplier invoice number is required';end if;
  v_no:='PINV-'||to_char(coalesce(p_invoice_date,current_date),'YYMMDD')||'-'||lpad(nextval('public.purchase_invoice_number_seq_v484')::text,6,'0');
  insert into public.purchase_invoices_v484(id,tenant_id,location_id,supplier_id,purchase_order_id,invoice_number,supplier_invoice_number,invoice_date,due_date,additional_charges,notes,created_by)
  values(v_id,p_tenant_id,po.location_id,po.supplier_id,po.id,v_no,trim(p_supplier_invoice_number),coalesce(p_invoice_date,current_date),p_due_date,greatest(coalesce(p_additional_charges,0),0),nullif(trim(coalesce(p_notes,'')),''),auth.uid());
  for x in select value from jsonb_array_elements(p_items) loop
    select * into poi from public.purchase_order_items_v480 where id=nullif(x->>'purchase_order_item_id','')::uuid and purchase_order_id=po.id for update;if not found then raise exception 'PO line not found';end if;
    v_qty:=coalesce(nullif(x->>'quantity','')::numeric,0);v_cost:=greatest(coalesce(nullif(x->>'unit_cost','')::numeric,poi.unit_cost,0),0);v_rate:=greatest(coalesce(nullif(x->>'tax_rate','')::numeric,poi.tax_rate,0),0);if v_qty<=0 then raise exception 'Invoice quantity must be positive';end if;
    if nullif(x->>'goods_receipt_item_id','') is not null then
      select * into gi from public.goods_receipt_items_v484 where id=(x->>'goods_receipt_item_id')::uuid and purchase_order_item_id=poi.id;if not found then raise exception 'GRN line does not belong to this PO line';end if;
      select coalesce(sum(ii.quantity),0) into v_invoiced from public.purchase_invoice_items_v484 ii join public.purchase_invoices_v484 ih on ih.id=ii.purchase_invoice_id where ii.goods_receipt_item_id=gi.id and ih.status<>'void';
      v_received_payable:=gi.accepted_quantity+gi.damaged_quantity;if v_qty+v_invoiced-v_received_payable>0.000001 then raise exception 'Invoice quantity exceeds accepted/damaged GRN quantity remaining';end if;
    else
      select coalesce(sum(ii.quantity),0) into v_invoiced from public.purchase_invoice_items_v484 ii join public.purchase_invoices_v484 ih on ih.id=ii.purchase_invoice_id where ii.purchase_order_item_id=poi.id and ih.status<>'void';
      v_received_payable:=coalesce(poi.accepted_quantity,0)+coalesce(poi.damaged_quantity,0);if v_qty+v_invoiced-v_received_payable>0.000001 then raise exception 'Invoice quantity exceeds received payable PO quantity remaining';end if;
    end if;
    v_line:=round(v_qty*v_cost,2);v_tax:=round(v_line*v_rate/100.0,2);v_sub:=v_sub+v_line;v_tax_total:=v_tax_total+v_tax;
    insert into public.purchase_invoice_items_v484(purchase_invoice_id,purchase_order_item_id,goods_receipt_item_id,variant_id,quantity,unit_cost,tax_rate,line_subtotal,tax_amount,line_total,note)
    values(v_id,poi.id,nullif(x->>'goods_receipt_item_id','')::uuid,poi.variant_id,v_qty,v_cost,v_rate,v_line,v_tax,v_line+v_tax,nullif(trim(coalesce(x->>'note','')),''));
  end loop;
  v_total:=round(v_sub+v_tax_total+greatest(coalesce(p_additional_charges,0),0),2);
  update public.purchase_invoices_v484 set subtotal=v_sub,tax_total=v_tax_total,grand_total=v_total,balance_due=v_total,updated_at=now() where id=v_id;
  perform private.thq_sync_bump_v480(p_tenant_id,'transactions','purchase_invoice',v_id::text,'create');
  return jsonb_build_object('success',true,'purchase_invoice_id',v_id,'invoice_number',v_no,'supplier_invoice_number',trim(p_supplier_invoice_number),'status','draft','grand_total',v_total);
end$$;


--
-- Name: purchase_invoice_create_v489(uuid, uuid, text, date, date, jsonb, numeric, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_invoice_create_v489(p_tenant_id uuid, p_purchase_order_id uuid, p_supplier_invoice_number text, p_invoice_date date, p_due_date date, p_items jsonb, p_additional_charges numeric, p_round_off numeric, p_notes text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v jsonb;v_id uuid;v_round numeric:=round(coalesce(p_round_off,0),2);v_add numeric:=greatest(coalesce(p_additional_charges,0),0);v_final numeric;
begin
  if abs(v_round)>0.999999 then raise exception 'Round off must be between -1.00 and 1.00';end if;
  v:=public.purchase_invoice_create_v484(p_tenant_id,p_purchase_order_id,p_supplier_invoice_number,p_invoice_date,p_due_date,p_items,v_add+greatest(v_round,0),p_notes);
  v_id:=nullif(v->>'purchase_invoice_id','')::uuid;if v_id is null then return v;end if;
  select round(coalesce(sum(ii.line_total),0)+v_add+v_round,2) into v_final from public.purchase_invoice_items_v484 ii where ii.purchase_invoice_id=v_id;
  if v_final<0 then raise exception 'Rounded purchase invoice total cannot be negative';end if;
  update public.purchase_invoices_v484 set additional_charges=v_add,round_off=v_round,grand_total=v_final,balance_due=greatest(v_final-paid_total,0),updated_at=now() where id=v_id and tenant_id=p_tenant_id;
  return v||jsonb_build_object('grand_total',v_final,'round_off',v_round,'rounding_engine','v4.8.9');
end $$;


--
-- Name: purchase_invoice_detail_v484(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_invoice_detail_v484(p_tenant_id uuid, p_purchase_invoice_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_loc uuid;v jsonb;begin
 select location_id into v_loc from public.purchase_invoices_v484 where tenant_id=p_tenant_id and id=p_purchase_invoice_id;if v_loc is null then raise exception 'Purchase Invoice not found';end if;perform private.purchasing_v484_access(p_tenant_id,v_loc,false);
 select jsonb_build_object('invoice',to_jsonb(i)||jsonb_build_object('supplier_name',s.name,'location_name',l.name,'order_number',po.order_number),
 'items',coalesce((select jsonb_agg(to_jsonb(ii)||jsonb_build_object('product_name',p.name,'sku',pv.sku,'grn_number',g.grn_number) order by p.name) from public.purchase_invoice_items_v484 ii join public.product_variants pv on pv.id=ii.variant_id join public.products p on p.id=pv.product_id left join public.goods_receipt_items_v484 gi on gi.id=ii.goods_receipt_item_id left join public.goods_receipts_v484 g on g.id=gi.goods_receipt_id where ii.purchase_invoice_id=i.id),'[]'::jsonb)) into v
 from public.purchase_invoices_v484 i join public.suppliers s on s.id=i.supplier_id join public.business_locations l on l.id=i.location_id left join public.purchase_orders_v480 po on po.id=i.purchase_order_id where i.id=p_purchase_invoice_id and i.tenant_id=p_tenant_id;return v;
end$$;


--
-- Name: purchase_invoice_list_v484(uuid, uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_invoice_list_v484(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_query text DEFAULT ''::text, p_limit integer DEFAULT 500) RETURNS TABLE(id uuid, invoice_number text, supplier_invoice_number text, invoice_date date, due_date date, status text, purchase_order_id uuid, order_number text, supplier_id uuid, supplier_name text, location_id uuid, location_name text, subtotal numeric, tax_total numeric, grand_total numeric, paid_total numeric, balance_due numeric, line_count bigint, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare q text:='%'||lower(trim(coalesce(p_query,'')))||'%';begin
 perform private.purchasing_v484_permission(p_tenant_id,false);
 return query select i.id,i.invoice_number,i.supplier_invoice_number,i.invoice_date,i.due_date,i.status,i.purchase_order_id,po.order_number,i.supplier_id,s.name,i.location_id,l.name,i.subtotal,i.tax_total,i.grand_total,i.paid_total,i.balance_due,count(ii.id),i.created_at
 from public.purchase_invoices_v484 i left join public.purchase_orders_v480 po on po.id=i.purchase_order_id join public.suppliers s on s.id=i.supplier_id join public.business_locations l on l.id=i.location_id left join public.purchase_invoice_items_v484 ii on ii.purchase_invoice_id=i.id left join public.product_variants pv on pv.id=ii.variant_id left join public.products p on p.id=pv.product_id
 where i.tenant_id=p_tenant_id and (p_location_id is null or i.location_id=p_location_id) and (p_status is null or p_status='' or i.status=p_status) and private.erp_document_scope_allowed(p_tenant_id,i.location_id,p_location_id,'view')
 and (trim(coalesce(p_query,''))='' or lower(i.invoice_number) like q or lower(coalesce(i.supplier_invoice_number,'')) like q or lower(coalesce(po.order_number,'')) like q or lower(s.name) like q or lower(coalesce(p.name,'')) like q or lower(coalesce(pv.sku,'')) like q)
 group by i.id,po.order_number,s.name,l.name order by i.created_at desc limit greatest(1,least(coalesce(p_limit,500),2000));
end$$;


--
-- Name: purchase_invoice_post_v484(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_invoice_post_v484(p_tenant_id uuid, p_purchase_invoice_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare i public.purchase_invoices_v484%rowtype;li record;v_lines jsonb:='[]'::jsonb;v_net numeric;v_open boolean;v_old_status text;begin
  select * into i from public.purchase_invoices_v484 where tenant_id=p_tenant_id and id=p_purchase_invoice_id for update;
  if not found then raise exception 'Purchase Invoice not found';end if;
  perform private.purchasing_v484_access(p_tenant_id,i.location_id,true);
  if i.status in('posted','part_paid','paid') then return jsonb_build_object('success',true,'purchase_invoice_id',i.id,'invoice_number',i.invoice_number,'status',i.status,'idempotent',true);end if;
  if i.status<>'draft' then raise exception 'Only Draft invoices can be posted';end if;
  if i.grand_total<=0 then raise exception 'Purchase Invoice total must be positive';end if;
  v_net:=greatest(i.subtotal+i.additional_charges,0);
  if v_net>0 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'inventory_asset'),'debit',v_net,'credit',0,'party_type','supplier','party_id',i.supplier_id,'description','Purchase invoice / inventory'));end if;
  if i.tax_total>0 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'input_gst'),'debit',i.tax_total,'credit',0,'description','Input GST'));end if;
  if i.round_off>0.000001 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'rounding'),'debit',i.round_off,'credit',0,'description','Purchase invoice round off'));end if;
  if i.round_off< -0.000001 then v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'rounding'),'debit',0,'credit',abs(i.round_off),'description','Purchase invoice round off'));end if;
  v_lines:=v_lines||jsonb_build_array(jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'accounts_payable'),'debit',0,'credit',i.grand_total,'party_type','supplier','party_id',i.supplier_id,'description','Supplier payable'));
  if not private.gst_v520_authoritative_bound_context(p_tenant_id,'purchase_invoice_v484',i.id) then perform private.v4_journal_create(p_tenant_id,i.location_id,i.invoice_date,'Purchase Invoice '||i.invoice_number,'purchase_invoice_v484',i.id,i.invoice_number,v_lines);end if;
  update public.purchase_invoices_v484 set status='posted',posted_by=auth.uid(),posted_at=now(),balance_due=grand_total-paid_total,updated_at=now() where id=i.id;
  for li in select purchase_order_item_id,sum(quantity) qty from public.purchase_invoice_items_v484 where purchase_invoice_id=i.id group by purchase_order_item_id loop
    update public.purchase_order_items_v480 set invoiced_quantity=invoiced_quantity+li.qty where id=li.purchase_order_item_id;
  end loop;

  select exists(
    select 1 from public.purchase_order_items_v480 poi
    where poi.purchase_order_id=i.purchase_order_id
      and (poi.received_quantity+0.000001<poi.quantity or poi.invoiced_quantity+0.000001<poi.accepted_quantity+poi.damaged_quantity)
  ) into v_open;
  if not v_open then
    select status into v_old_status from public.purchase_orders_v480 where id=i.purchase_order_id for update;
    if v_old_status not in('closed','cancelled') then
      update public.purchase_orders_v480 set status='closed',closed_at=coalesce(closed_at,now()),updated_at=now() where id=i.purchase_order_id;
      insert into public.purchase_order_status_history_v480(purchase_order_id,from_status,to_status,reason,changed_by)
      values(i.purchase_order_id,v_old_status,'closed','All received quantities invoiced; Purchase Order closed automatically',auth.uid());
    end if;
  end if;

  perform private.thq_sync_bump_v480(p_tenant_id,'finance','purchase_invoice',i.id::text,'post');
  return jsonb_build_object('success',true,'purchase_invoice_id',i.id,'invoice_number',i.invoice_number,'status','posted','grand_total',i.grand_total,'round_off',i.round_off,'purchase_order_status',case when v_open then null else 'closed' end);
end $$;


--
-- Name: purchase_invoice_void_v490(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_invoice_void_v490(p_tenant_id uuid, p_purchase_invoice_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare i public.purchase_invoices_v484%rowtype;li record;v_po_status text;v_new_po_status text;v_has_received boolean;v_complete_received boolean;begin
  if nullif(trim(coalesce(p_reason,'')),'') is null then raise exception 'Void reason is required';end if;
  select * into i from public.purchase_invoices_v484 where tenant_id=p_tenant_id and id=p_purchase_invoice_id for update;
  if not found then raise exception 'Purchase Invoice not found';end if;
  perform private.purchasing_v484_access(p_tenant_id,i.location_id,true);
  if i.status='void' then return jsonb_build_object('success',true,'purchase_invoice_id',i.id,'status','void','idempotent',true);end if;
  if i.status not in('draft','posted') then raise exception 'Only Draft or unpaid Posted invoices can be voided';end if;
  if coalesce(i.paid_total,0)>0.005 or exists(
    select 1 from public.supplier_payment_allocations_v484 a
    join public.supplier_payments_v484 p on p.id=a.supplier_payment_id
    where a.purchase_invoice_id=i.id and p.status='posted'
  ) then raise exception 'Invoice has supplier payments. Void/reverse those payments first';end if;

  if i.status='posted' then
    update public.journal_entries set status='reversed'
    where tenant_id=p_tenant_id and source_type='purchase_invoice_v484' and source_id=i.id and status='posted';
    insert into public.supplier_ledger_entries_v484(
      tenant_id,supplier_id,location_id,entry_date,entry_type,source_id,reference_number,description,debit,credit,created_by
    ) values(
      p_tenant_id,i.supplier_id,i.location_id,current_date,'void',i.id,i.invoice_number,
      'Void purchase invoice: '||trim(p_reason),0,i.grand_total,auth.uid()
    ) on conflict(tenant_id,entry_type,source_id) do nothing;
    for li in select purchase_order_item_id,sum(quantity) qty from public.purchase_invoice_items_v484 where purchase_invoice_id=i.id group by purchase_order_item_id loop
      update public.purchase_order_items_v480
      set invoiced_quantity=greatest(invoiced_quantity-li.qty,0)
      where id=li.purchase_order_item_id;
    end loop;
  end if;

  update public.purchase_invoices_v484
  set status='void',balance_due=0,updated_at=now(),notes=concat_ws(E'\n',notes,'Voided: '||trim(p_reason))
  where id=i.id;

  if i.purchase_order_id is not null then
    select status into v_po_status from public.purchase_orders_v480 where id=i.purchase_order_id for update;
    select exists(select 1 from public.purchase_order_items_v480 where purchase_order_id=i.purchase_order_id and received_quantity>0.000001),
           not exists(select 1 from public.purchase_order_items_v480 where purchase_order_id=i.purchase_order_id and received_quantity+0.000001<quantity)
    into v_has_received,v_complete_received;
    v_new_po_status:=case when v_complete_received then 'received' when v_has_received then 'partially_received' else case when v_po_status='draft' then 'draft' else 'ordered' end end;
    if v_po_status='closed' or v_po_status='received' then
      update public.purchase_orders_v480 set status=v_new_po_status,closed_at=null,updated_at=now() where id=i.purchase_order_id;
      insert into public.purchase_order_status_history_v480(purchase_order_id,from_status,to_status,reason,changed_by)
      values(i.purchase_order_id,v_po_status,v_new_po_status,'Reopened because invoice '||i.invoice_number||' was voided',auth.uid());
    end if;
  end if;

  perform private.thq_sync_bump_v480(p_tenant_id,'finance','purchase_invoice',i.id::text,'void');
  return jsonb_build_object('success',true,'purchase_invoice_id',i.id,'invoice_number',i.invoice_number,'status','void','purchase_order_status',v_new_po_status);
end $$;


--
-- Name: purchase_order_create_v480(uuid, uuid, uuid, jsonb, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_order_create_v480(p_tenant_id uuid, p_location_id uuid, p_supplier_id uuid, p_items jsonb, p_expected_date date DEFAULT NULL::date, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_id uuid:=gen_random_uuid();v_no text;v_sub numeric:=0;v_tax numeric:=0;v_total numeric:=0;x jsonb;v_variant uuid;v_qty numeric;v_cost numeric;v_rate numeric;v_line numeric;v_line_tax numeric;begin
  perform private.purchase_planning_access_v480(p_tenant_id,p_location_id,true);
  if not exists(select 1 from public.suppliers where id=p_supplier_id and tenant_id=p_tenant_id and coalesce(status,'active')='active') then raise exception 'Active supplier not found';end if;
  if p_items is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'At least one item is required';end if;
  v_no:='PO-'||to_char(current_date,'YYMMDD')||'-'||lpad(nextval('public.purchase_order_number_seq')::text,6,'0');
  insert into public.purchase_orders_v480(id,tenant_id,location_id,supplier_id,order_number,expected_date,notes,created_by)
  values(v_id,p_tenant_id,p_location_id,p_supplier_id,v_no,p_expected_date,nullif(trim(coalesce(p_notes,'')),''),auth.uid());
  for x in select value from jsonb_array_elements(p_items)
  loop
    v_variant:=nullif(x->>'variant_id','')::uuid;v_qty:=coalesce(nullif(x->>'quantity','')::numeric,0);v_cost:=greatest(coalesce(nullif(x->>'unit_cost','')::numeric,0),0);v_rate:=greatest(coalesce(nullif(x->>'tax_rate','')::numeric,0),0);
    if v_variant is null or v_qty<=0 then raise exception 'Invalid purchase order item';end if;
    if not exists(select 1 from public.product_variants where id=v_variant and tenant_id=p_tenant_id) then raise exception 'Product variant not found';end if;
    v_line:=round(v_qty*v_cost,2);v_line_tax:=round(v_line*v_rate/100.0,2);
    insert into public.purchase_order_items_v480(purchase_order_id,variant_id,quantity,unit_cost,tax_rate,line_subtotal,tax_amount,line_total,note)
    values(v_id,v_variant,v_qty,v_cost,v_rate,v_line,v_line_tax,v_line+v_line_tax,nullif(trim(coalesce(x->>'note','')),''))
    on conflict(purchase_order_id,variant_id) do update set quantity=public.purchase_order_items_v480.quantity+excluded.quantity,
      unit_cost=excluded.unit_cost,tax_rate=excluded.tax_rate,
      line_subtotal=round((public.purchase_order_items_v480.quantity+excluded.quantity)*excluded.unit_cost,2),
      tax_amount=round((public.purchase_order_items_v480.quantity+excluded.quantity)*excluded.unit_cost*excluded.tax_rate/100.0,2),
      line_total=round((public.purchase_order_items_v480.quantity+excluded.quantity)*excluded.unit_cost*(1+excluded.tax_rate/100.0),2);
  end loop;
  select coalesce(sum(line_subtotal),0),coalesce(sum(tax_amount),0),coalesce(sum(line_total),0) into v_sub,v_tax,v_total from public.purchase_order_items_v480 where purchase_order_id=v_id;
  update public.purchase_orders_v480 set subtotal=v_sub,tax_total=v_tax,grand_total=v_total,updated_at=now() where id=v_id;
  insert into public.purchase_order_status_history_v480(purchase_order_id,to_status,reason,changed_by) values(v_id,'draft','Purchase order created',auth.uid());
  perform private.thq_sync_bump_v480(p_tenant_id,'transactions','purchase_order',v_id::text,'create');
  return jsonb_build_object('success',true,'purchase_order_id',v_id,'order_number',v_no,'status','draft','grand_total',v_total);
end $$;


--
-- Name: purchase_order_create_v484(uuid, uuid, uuid, jsonb, date, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_order_create_v484(p_tenant_id uuid, p_location_id uuid, p_supplier_id uuid, p_items jsonb, p_expected_date date DEFAULT NULL::date, p_notes text DEFAULT NULL::text, p_request_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v jsonb;v_po uuid;v_req_loc uuid;v_req_status text;begin
  if p_request_id is not null then
    select location_id,status into v_req_loc,v_req_status from public.purchase_requests_v484 where tenant_id=p_tenant_id and id=p_request_id for update;
    if v_req_loc is null then raise exception 'Purchase request not found';end if;if v_req_loc<>p_location_id then raise exception 'PO location must match Purchase Request location';end if;if v_req_status<>'approved' then raise exception 'Purchase Request must be approved before conversion to a PO';end if;
  end if;
  v:=public.purchase_order_create_v480(p_tenant_id,p_location_id,p_supplier_id,p_items,p_expected_date,p_notes);
  v_po:=nullif(v->>'purchase_order_id','')::uuid;
  if v_po is not null then
    update public.purchase_orders_v480 set request_id=p_request_id where id=v_po;
    if p_request_id is not null then
      update public.purchase_requests_v484 set status='converted',converted_purchase_order_id=v_po,updated_at=now() where id=p_request_id;
      insert into public.purchase_request_history_v484(request_id,from_status,to_status,note,changed_by) values(p_request_id,'approved','converted','Converted to Purchase Order '||(v->>'order_number'),auth.uid());
      update public.purchase_order_items_v480 poi set request_item_id=ri.id from public.purchase_request_items_v484 ri where poi.purchase_order_id=v_po and ri.request_id=p_request_id and ri.variant_id=poi.variant_id;
    end if;
  end if;
  return v||jsonb_build_object('request_id',p_request_id,'purchasing_engine','v4.8.4');
end$$;


--
-- Name: purchase_order_decide_v484(uuid, uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_order_decide_v484(p_tenant_id uuid, p_purchase_order_id uuid, p_approve boolean, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_old text;v_loc uuid;v_status text;begin
  select status,location_id into v_old,v_loc from public.purchase_orders_v480 where tenant_id=p_tenant_id and id=p_purchase_order_id for update;if v_loc is null then raise exception 'Purchase Order not found';end if;
  perform private.purchasing_v484_approval_access(p_tenant_id,v_loc);if v_old<>'submitted' then raise exception 'Only Submitted Purchase Orders can be decided';end if;
  v_status:=case when p_approve then 'approved' else 'rejected' end;if not p_approve and trim(coalesce(p_note,''))='' then raise exception 'Rejection reason is required';end if;
  update public.purchase_orders_v480 set status=v_status,updated_at=now(),approved_by=case when p_approve then auth.uid() else approved_by end,approved_at=case when p_approve then now() else approved_at end,rejected_by=case when not p_approve then auth.uid() else rejected_by end,rejected_at=case when not p_approve then now() else rejected_at end,rejection_reason=case when not p_approve then trim(p_note) else rejection_reason end where id=p_purchase_order_id;
  insert into public.purchase_order_status_history_v480(purchase_order_id,from_status,to_status,reason,changed_by) values(p_purchase_order_id,v_old,v_status,nullif(trim(coalesce(p_note,'')),''),auth.uid());
  perform private.thq_sync_bump_v480(p_tenant_id,'transactions','purchase_order',p_purchase_order_id::text,'decision.'||v_status);
  return jsonb_build_object('success',true,'purchase_order_id',p_purchase_order_id,'status',v_status);
end$$;


--
-- Name: purchase_order_detail_v480(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_order_detail_v480(p_tenant_id uuid, p_purchase_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v jsonb;v_location uuid;begin
  select location_id into v_location from public.purchase_orders_v480 where id=p_purchase_order_id and tenant_id=p_tenant_id;
  if v_location is null then raise exception 'Purchase order not found';end if;perform private.purchase_planning_access_v480(p_tenant_id,v_location,false);
  select jsonb_build_object(
    'order',to_jsonb(po)||jsonb_build_object('location_name',l.name,'supplier_name',s.name),
    'items',coalesce((select jsonb_agg(to_jsonb(i)||jsonb_build_object('product_name',p.name,'sku',pv.sku) order by p.name) from public.purchase_order_items_v480 i join public.product_variants pv on pv.id=i.variant_id join public.products p on p.id=pv.product_id where i.purchase_order_id=po.id),'[]'::jsonb),
    'history',coalesce((select jsonb_agg(to_jsonb(h) order by h.id) from public.purchase_order_status_history_v480 h where h.purchase_order_id=po.id),'[]'::jsonb)
  ) into v
  from public.purchase_orders_v480 po join public.business_locations l on l.id=po.location_id join public.suppliers s on s.id=po.supplier_id
  where po.id=p_purchase_order_id and po.tenant_id=p_tenant_id;
  return v;
end $$;


--
-- Name: purchase_order_detail_v484(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_order_detail_v484(p_tenant_id uuid, p_purchase_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_loc uuid;v jsonb;begin
 select location_id into v_loc from public.purchase_orders_v480 where tenant_id=p_tenant_id and id=p_purchase_order_id;if v_loc is null then raise exception 'Purchase Order not found';end if;perform private.purchasing_v484_access(p_tenant_id,v_loc,false);
 select jsonb_build_object(
  'order',to_jsonb(po)||jsonb_build_object('supplier_name',s.name,'location_name',l.name,'request_number',pr.request_number),
  'items',coalesce((select jsonb_agg(to_jsonb(i)||jsonb_build_object('product_name',p.name,'sku',pv.sku,'remaining_receive_quantity',greatest(i.quantity-i.received_quantity,0),'remaining_invoice_quantity',greatest(i.accepted_quantity+i.damaged_quantity-i.invoiced_quantity,0),'tracking_mode',private.v483_tracking_mode(p_tenant_id,i.variant_id)) order by p.name) from public.purchase_order_items_v480 i join public.product_variants pv on pv.id=i.variant_id join public.products p on p.id=pv.product_id where i.purchase_order_id=po.id),'[]'::jsonb),
  'history',coalesce((select jsonb_agg(to_jsonb(h) order by h.id) from public.purchase_order_status_history_v480 h where h.purchase_order_id=po.id),'[]'::jsonb),
  'grns',coalesce((select jsonb_agg(to_jsonb(g) order by g.created_at desc) from public.goods_receipts_v484 g where g.purchase_order_id=po.id),'[]'::jsonb),
  'invoices',coalesce((select jsonb_agg(to_jsonb(i) order by i.created_at desc) from public.purchase_invoices_v484 i where i.purchase_order_id=po.id),'[]'::jsonb)
 ) into v from public.purchase_orders_v480 po join public.suppliers s on s.id=po.supplier_id join public.business_locations l on l.id=po.location_id left join public.purchase_requests_v484 pr on pr.id=po.request_id where po.id=p_purchase_order_id and po.tenant_id=p_tenant_id;return v;
end$$;


--
-- Name: purchase_order_list_v480(uuid, uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_order_list_v480(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_query text DEFAULT ''::text, p_limit integer DEFAULT 500) RETURNS TABLE(id uuid, order_number text, order_date date, expected_date date, status text, location_id uuid, location_name text, supplier_id uuid, supplier_name text, grand_total numeric, item_count bigint, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare q text:='%'||lower(trim(coalesce(p_query,'')))||'%';begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  return query select po.id,po.order_number,po.order_date,po.expected_date,po.status,po.location_id,l.name,po.supplier_id,s.name,po.grand_total,count(i.id),po.created_at
  from public.purchase_orders_v480 po join public.business_locations l on l.id=po.location_id join public.suppliers s on s.id=po.supplier_id
  left join public.purchase_order_items_v480 i on i.purchase_order_id=po.id
  where po.tenant_id=p_tenant_id and (p_location_id is null or po.location_id=p_location_id)
    and private.erp_document_scope_allowed(p_tenant_id,po.location_id,p_location_id,'view')
    and (nullif(trim(coalesce(p_status,'')),'') is null or po.status=p_status)
    and (trim(coalesce(p_query,''))='' or lower(po.order_number) like q or lower(s.name) like q)
  group by po.id,l.name,s.name order by po.created_at desc limit greatest(1,least(coalesce(p_limit,500),2000));
end $$;


--
-- Name: purchase_order_list_v484(uuid, uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_order_list_v484(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_query text DEFAULT ''::text, p_limit integer DEFAULT 500) RETURNS TABLE(id uuid, order_number text, order_date date, expected_date date, status text, request_id uuid, request_number text, supplier_id uuid, supplier_name text, location_id uuid, location_name text, item_count bigint, ordered_quantity numeric, received_quantity numeric, accepted_quantity numeric, damaged_quantity numeric, rejected_quantity numeric, invoiced_quantity numeric, remaining_receive_quantity numeric, remaining_invoice_quantity numeric, subtotal numeric, tax_total numeric, grand_total numeric, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare q text:='%'||lower(trim(coalesce(p_query,'')))||'%';begin
 perform private.purchasing_v484_permission(p_tenant_id,false);
 return query select po.id,po.order_number,po.order_date,po.expected_date,po.status,po.request_id,pr.request_number,po.supplier_id,s.name,po.location_id,l.name,count(i.id),
  coalesce(sum(i.quantity),0),coalesce(sum(i.received_quantity),0),coalesce(sum(i.accepted_quantity),0),coalesce(sum(i.damaged_quantity),0),coalesce(sum(i.rejected_quantity),0),coalesce(sum(i.invoiced_quantity),0),
  coalesce(sum(greatest(i.quantity-i.received_quantity,0)),0),coalesce(sum(greatest(i.accepted_quantity+i.damaged_quantity-i.invoiced_quantity,0)),0),po.subtotal,po.tax_total,po.grand_total,po.created_at
 from public.purchase_orders_v480 po join public.suppliers s on s.id=po.supplier_id join public.business_locations l on l.id=po.location_id left join public.purchase_requests_v484 pr on pr.id=po.request_id left join public.purchase_order_items_v480 i on i.purchase_order_id=po.id left join public.product_variants pv on pv.id=i.variant_id left join public.products p on p.id=pv.product_id
 where po.tenant_id=p_tenant_id and (p_location_id is null or po.location_id=p_location_id) and (p_status is null or p_status='' or po.status=p_status) and private.erp_document_scope_allowed(p_tenant_id,po.location_id,p_location_id,'view')
 and (trim(coalesce(p_query,''))='' or lower(po.order_number) like q or lower(coalesce(pr.request_number,'')) like q or lower(s.name) like q or lower(coalesce(p.name,'')) like q or lower(coalesce(pv.sku,'')) like q)
 group by po.id,pr.request_number,s.name,l.name order by po.created_at desc limit greatest(1,least(coalesce(p_limit,500),2000));
end$$;


--
-- Name: purchase_order_status_v480(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_order_status_v480(p_tenant_id uuid, p_purchase_order_id uuid, p_status text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_old text;v_loc uuid;v_status text:=lower(trim(coalesce(p_status,'')));begin
  select status,location_id into v_old,v_loc from public.purchase_orders_v480 where id=p_purchase_order_id and tenant_id=p_tenant_id for update;if v_loc is null then raise exception 'Purchase order not found';end if;
  perform private.purchase_planning_access_v480(p_tenant_id,v_loc,true);
  if v_status in('approved','rejected') then raise exception 'Use the V4.8.4 PO approval action';end if;
  if v_status='submitted' and v_old not in('draft','rejected') then raise exception 'Only Draft/Rejected purchase orders can be submitted';end if;
  if v_status='ordered' and v_old<>'approved' then raise exception 'Only Approved purchase orders can be marked Ordered';end if;
  if v_status='cancelled' and v_old in('received','closed','cancelled') then raise exception 'Purchase order cannot be cancelled in its current state';end if;
  if v_status not in('submitted','ordered','cancelled') then raise exception 'Unsupported manual PO status';end if;
  if v_status='cancelled' and exists(select 1 from public.purchase_order_items_v480 where purchase_order_id=p_purchase_order_id and received_quantity>0.000001) then raise exception 'A partially received Purchase Order cannot be cancelled; keep it open for remaining receipt/invoice processing';end if;
  update public.purchase_orders_v480 set status=v_status,updated_at=now(),submitted_by=case when v_status='submitted' then auth.uid() else submitted_by end,submitted_at=case when v_status='submitted' then now() else submitted_at end,ordered_at=case when v_status='ordered' then now() else ordered_at end,cancelled_at=case when v_status='cancelled' then now() else cancelled_at end where id=p_purchase_order_id;
  insert into public.purchase_order_status_history_v480(purchase_order_id,from_status,to_status,reason,changed_by) values(p_purchase_order_id,v_old,v_status,nullif(trim(coalesce(p_reason,'')),''),auth.uid());
  perform private.thq_sync_bump_v480(p_tenant_id,'transactions','purchase_order',p_purchase_order_id::text,'status.'||v_status);
  return jsonb_build_object('success',true,'purchase_order_id',p_purchase_order_id,'from_status',v_old,'status',v_status);
end$$;


--
-- Name: purchase_price_history_v484(uuid, uuid, uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_price_history_v484(p_tenant_id uuid, p_variant_id uuid DEFAULT NULL::uuid, p_supplier_id uuid DEFAULT NULL::uuid, p_location_id uuid DEFAULT NULL::uuid, p_query text DEFAULT ''::text, p_limit integer DEFAULT 1000) RETURNS TABLE(source_type text, document_id uuid, document_number text, purchase_date date, location_id uuid, location_name text, supplier_id uuid, supplier_name text, variant_id uuid, product_name text, sku text, quantity numeric, unit_cost numeric, tax_rate numeric, line_total numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare q text:='%'||lower(trim(coalesce(p_query,'')))||'%';begin
 perform private.purchasing_v484_permission(p_tenant_id,false);
 return query
 with history(source_type,document_id,document_number,purchase_date,location_id,location_name,supplier_id,supplier_name,variant_id,product_name,sku,quantity,unit_cost,tax_rate,line_total) as (
   select 'purchase_invoice_v484'::text, ih.id,ih.invoice_number::text,ih.invoice_date,ih.location_id,l.name::text,ih.supplier_id,s.name::text,ii.variant_id,p.name::text,pv.sku::text,ii.quantity::numeric,ii.unit_cost::numeric,ii.tax_rate::numeric,ii.line_total::numeric
   from public.purchase_invoices_v484 ih
   join public.purchase_invoice_items_v484 ii on ii.purchase_invoice_id=ih.id
   join public.product_variants pv on pv.id=ii.variant_id
   join public.products p on p.id=pv.product_id
   join public.suppliers s on s.id=ih.supplier_id
   join public.business_locations l on l.id=ih.location_id
   where ih.tenant_id=p_tenant_id and ih.status in('posted','part_paid','paid')
   union all
   select 'direct_purchase'::text,ph.id,ph.purchase_number::text,ph.purchase_date,o.location_id,l.name::text,ph.supplier_id,s.name::text,pi.variant_id,p.name::text,pv.sku::text,
          coalesce(pi.entered_quantity,pi.quantity)::numeric,coalesce(pi.entered_unit_cost,pi.unit_cost)::numeric,pi.tax_rate::numeric,pi.line_total::numeric
   from public.purchases ph
   join public.purchase_items pi on pi.purchase_id=ph.id
   join public.product_variants pv on pv.id=pi.variant_id
   join public.products p on p.id=pv.product_id
   join public.suppliers s on s.id=ph.supplier_id
   left join public.document_origins o on o.entity_type='purchase' and o.entity_id=ph.id and o.tenant_id=ph.tenant_id
   left join public.business_locations l on l.id=o.location_id
   where ph.tenant_id=p_tenant_id and coalesce(ph.status,'') not in('cancelled','void')
 )
 select h.source_type,h.document_id,h.document_number,h.purchase_date,h.location_id,h.location_name,h.supplier_id,h.supplier_name,
        h.variant_id,h.product_name,h.sku,h.quantity,h.unit_cost,h.tax_rate,h.line_total
 from history h
 where (p_variant_id is null or h.variant_id=p_variant_id)
   and (p_supplier_id is null or h.supplier_id=p_supplier_id)
   and (p_location_id is null or h.location_id=p_location_id)
   and (h.location_id is null or private.erp_document_scope_allowed(p_tenant_id,h.location_id,p_location_id,'view'))
   and (trim(coalesce(p_query,''))='' or lower(coalesce(h.document_number,'')) like q or lower(coalesce(h.supplier_name,'')) like q or lower(coalesce(h.product_name,'')) like q or lower(coalesce(h.sku,'')) like q)
 order by h.purchase_date desc,h.document_number desc
 limit greatest(1,least(coalesce(p_limit,1000),5000));
end $$;


--
-- Name: purchase_quotation_convert_v500(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_quotation_convert_v500(p_tenant_id uuid, p_quotation_id uuid, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare q public.purchase_quotations_v500%rowtype;v_items jsonb;v_po jsonb;v_po_id uuid;begin
  select * into q from public.purchase_quotations_v500 where id=p_quotation_id and tenant_id=p_tenant_id for update;if not found then raise exception 'Quotation not found';end if;perform private.purchasing_v484_access(p_tenant_id,q.location_id,true);if q.status not in('received','selected') then raise exception 'Only received/selected quotation can be converted';end if;
  select coalesce(jsonb_agg(jsonb_build_object('variant_id',i.variant_id,'quantity',i.quantity,'unit_cost',i.unit_cost,'tax_rate',i.tax_rate,'note',i.note)),'[]'::jsonb) into v_items from public.purchase_quotation_items_v500 i where i.quotation_id=q.id;
  v_po:=public.purchase_order_create_v484(p_tenant_id,q.location_id,q.supplier_id,v_items,q.expected_delivery_date,concat_ws(' • ',nullif(trim(coalesce(p_notes,'')),''),'Quotation '||q.quotation_number),q.request_id);v_po_id:=nullif(v_po->>'purchase_order_id','')::uuid;
  update public.purchase_quotations_v500 set status='converted',converted_purchase_order_id=v_po_id,updated_at=now() where id=q.id;update public.purchase_quotations_v500 set status='rejected',updated_at=now() where tenant_id=p_tenant_id and request_id=q.request_id and id<>q.id and status in('received','selected');return v_po||jsonb_build_object('quotation_id',q.id,'quotation_number',q.quotation_number);
end $$;


--
-- Name: purchase_quotation_detail_v500(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_quotation_detail_v500(p_tenant_id uuid, p_quotation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare h jsonb;i jsonb;begin perform private.purchasing_v484_permission(p_tenant_id,false);select to_jsonb(q) into h from public.purchase_quotations_v500 q where q.id=p_quotation_id and q.tenant_id=p_tenant_id;if h is null then raise exception 'Quotation not found';end if;select coalesce(jsonb_agg(jsonb_build_object('id',qi.id,'variant_id',qi.variant_id,'product_name',p.name,'sku',pv.sku,'quantity',qi.quantity,'unit_cost',qi.unit_cost,'tax_rate',qi.tax_rate,'line_total',qi.line_total,'request_item_id',qi.request_item_id,'note',qi.note) order by p.name),'[]'::jsonb) into i from public.purchase_quotation_items_v500 qi join public.product_variants pv on pv.id=qi.variant_id join public.products p on p.id=pv.product_id where qi.quotation_id=p_quotation_id;return jsonb_build_object('quotation',h,'items',i);end $$;


--
-- Name: purchase_quotation_save_v500(uuid, uuid, uuid, uuid, uuid, text, date, date, date, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_quotation_save_v500(p_tenant_id uuid, p_quotation_id uuid, p_request_id uuid, p_location_id uuid, p_supplier_id uuid, p_supplier_quote_reference text, p_quote_date date, p_valid_until date, p_expected_delivery_date date, p_payment_terms text, p_items jsonb, p_notes text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v_id uuid:=coalesce(p_quotation_id,gen_random_uuid());v_no text;x jsonb;v_qty numeric;v_cost numeric;v_tax numeric;v_line numeric;v_sub numeric:=0;v_tax_total numeric:=0;v_request_item uuid;v_variant uuid;begin perform private.purchasing_v484_access(p_tenant_id,p_location_id,true);if not exists(select 1 from public.suppliers where id=p_supplier_id and tenant_id=p_tenant_id and coalesce(status,'active')='active') then raise exception 'Active supplier not found';end if;if p_request_id is not null and not exists(select 1 from public.purchase_requests_v484 where id=p_request_id and tenant_id=p_tenant_id and location_id=p_location_id) then raise exception 'Purchase request not found for this business/location';end if;if jsonb_typeof(coalesce(p_items,'null'::jsonb))<>'array' or jsonb_array_length(p_items)=0 then raise exception 'Quotation must contain items';end if;if p_valid_until is not null and p_valid_until<coalesce(p_quote_date,current_date) then raise exception 'Valid-until date cannot precede quote date';end if;if p_quotation_id is null then v_no:='PQT-'||to_char(coalesce(p_quote_date,current_date),'YYMMDD')||'-'||lpad(nextval('public.purchase_quotation_number_seq_v500')::text,6,'0');insert into public.purchase_quotations_v500(id,tenant_id,request_id,location_id,supplier_id,quotation_number,supplier_quote_reference,quote_date,valid_until,expected_delivery_date,payment_terms,notes,created_by) values(v_id,p_tenant_id,p_request_id,p_location_id,p_supplier_id,v_no,nullif(trim(coalesce(p_supplier_quote_reference,'')),''),coalesce(p_quote_date,current_date),p_valid_until,p_expected_delivery_date,nullif(trim(coalesce(p_payment_terms,'')),''),nullif(trim(coalesce(p_notes,'')),''),auth.uid());else select quotation_number into v_no from public.purchase_quotations_v500 where id=v_id and tenant_id=p_tenant_id and status in('draft','received') for update;if v_no is null then raise exception 'Editable quotation not found';end if;delete from public.purchase_quotation_items_v500 where quotation_id=v_id;update public.purchase_quotations_v500 set request_id=p_request_id,location_id=p_location_id,supplier_id=p_supplier_id,supplier_quote_reference=nullif(trim(coalesce(p_supplier_quote_reference,'')),''),quote_date=coalesce(p_quote_date,current_date),valid_until=p_valid_until,expected_delivery_date=p_expected_delivery_date,payment_terms=nullif(trim(coalesce(p_payment_terms,'')),''),notes=nullif(trim(coalesce(p_notes,'')),''),updated_at=now() where id=v_id;end if;for x in select value from jsonb_array_elements(p_items) loop begin v_qty:=coalesce(nullif(x->>'quantity','')::numeric,0);v_cost:=coalesce(nullif(x->>'unit_cost','')::numeric,0);v_tax:=coalesce(nullif(x->>'tax_rate','')::numeric,0);v_variant:=(x->>'variant_id')::uuid;v_request_item:=nullif(x->>'request_item_id','')::uuid;exception when others then raise exception 'Invalid quotation item';end;if v_qty<=0 or v_cost<0 or v_tax<0 or v_tax>100 then raise exception 'Invalid quotation quantity/cost/tax';end if;if not exists(select 1 from public.product_variants pv join public.products p on p.id=pv.product_id and p.tenant_id=pv.tenant_id where pv.id=v_variant and pv.tenant_id=p_tenant_id and pv.status='active' and p.status='active') then raise exception 'Quotation product is invalid/inactive';end if;if v_request_item is not null then if p_request_id is null or not exists(select 1 from public.purchase_request_items_v484 ri where ri.id=v_request_item and ri.request_id=p_request_id and ri.variant_id=v_variant) then raise exception 'Quotation request item does not belong to the selected purchase request/product';end if;end if;v_line:=round(v_qty*v_cost,2);v_sub:=v_sub+v_line;v_tax_total:=v_tax_total+round(v_line*v_tax/100,2);insert into public.purchase_quotation_items_v500(quotation_id,request_item_id,variant_id,quantity,unit_cost,tax_rate,line_total,note) values(v_id,v_request_item,v_variant,v_qty,v_cost,v_tax,round(v_line+v_line*v_tax/100,2),nullif(trim(coalesce(x->>'note','')),''));end loop;update public.purchase_quotations_v500 set subtotal=round(v_sub,2),tax_total=round(v_tax_total,2),grand_total=round(v_sub+v_tax_total,2),status='received',updated_at=now() where id=v_id;return jsonb_build_object('quotation_id',v_id,'quotation_number',v_no,'grand_total',round(v_sub+v_tax_total,2));end $$;


--
-- Name: purchase_quotations_list_v500(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_quotations_list_v500(p_tenant_id uuid, p_request_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_query text DEFAULT ''::text) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare r record;q text:='%'||lower(trim(coalesce(p_query,'')))||'%';begin perform private.purchasing_v484_permission(p_tenant_id,false);
  for r in select qh.*,s.name supplier_name,s.phone supplier_phone,pr.request_number,po.order_number converted_order_number from public.purchase_quotations_v500 qh join public.suppliers s on s.id=qh.supplier_id left join public.purchase_requests_v484 pr on pr.id=qh.request_id left join public.purchase_orders_v480 po on po.id=qh.converted_purchase_order_id where qh.tenant_id=p_tenant_id and (p_request_id is null or qh.request_id=p_request_id) and (p_status is null or qh.status=p_status) and (trim(coalesce(p_query,''))='' or lower(qh.quotation_number) like q or lower(s.name) like q or lower(coalesce(qh.supplier_quote_reference,'')) like q) order by qh.quote_date desc,qh.created_at desc loop return next to_jsonb(r);end loop;return;
end $$;


--
-- Name: purchase_reorder_suggestions_v480(uuid, uuid, integer, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_reorder_suggestions_v480(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_days integer DEFAULT 30, p_query text DEFAULT ''::text, p_limit integer DEFAULT 1000) RETURNS TABLE(location_id uuid, location_code text, location_name text, variant_id uuid, product_name text, sku text, current_stock numeric, reorder_level numeric, max_stock numeric, avg_daily_sales numeric, days_cover numeric, suggested_quantity numeric, last_supplier_id uuid, last_supplier_name text, last_unit_cost numeric, tax_rate numeric, last_purchase_date date)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  return query
  with intel as (
    select * from public.inventory_intelligence_v480(p_tenant_id,p_location_id,p_days,p_query,p_limit)
    where suggested_reorder>0
  ), last_buy as (
    select distinct on(o.location_id,pi.variant_id) o.location_id,pi.variant_id,p.supplier_id,s.name supplier_name,pi.unit_cost,p.purchase_date
    from public.purchase_items pi join public.purchases p on p.id=pi.purchase_id
    join public.suppliers s on s.id=p.supplier_id
    join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='purchase' and o.entity_id=p.id
    where p.tenant_id=p_tenant_id and coalesce(p.status,'') not in('void','cancelled')
    order by o.location_id,pi.variant_id,p.purchase_date desc,p.created_at desc
  )
  select i.location_id,i.location_code,i.location_name,i.variant_id,i.product_name,i.sku,i.available,i.reorder_level,i.max_stock,
    i.avg_daily_sales,i.days_cover,i.suggested_reorder,lb.supplier_id,lb.supplier_name,coalesce(lb.unit_cost,i.average_cost,0),coalesce(pv.tax_rate,0),lb.purchase_date
  from intel i join public.product_variants pv on pv.id=i.variant_id left join last_buy lb on lb.location_id=i.location_id and lb.variant_id=i.variant_id
  order by i.location_name,i.status,i.product_name;
end $$;


--
-- Name: purchase_request_create_v484(uuid, uuid, jsonb, date, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_request_create_v484(p_tenant_id uuid, p_location_id uuid, p_items jsonb, p_required_date date DEFAULT NULL::date, p_priority text DEFAULT 'normal'::text, p_preferred_supplier_id uuid DEFAULT NULL::uuid, p_purpose text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_id uuid:=gen_random_uuid();v_no text;x jsonb;v_norm jsonb;v_variant uuid;v_qty numeric;begin
  perform private.purchasing_v484_access(p_tenant_id,p_location_id,true);
  if lower(coalesce(p_priority,'normal')) not in('low','normal','high','urgent') then raise exception 'Invalid priority';end if;
  if p_preferred_supplier_id is not null and not exists(select 1 from public.suppliers where tenant_id=p_tenant_id and id=p_preferred_supplier_id and coalesce(status,'active')='active') then raise exception 'Preferred supplier not found';end if;
  if p_items is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'At least one item is required';end if;
  v_norm:=private.v481_normalize_items(p_tenant_id,p_items,'purchase');
  v_no:='PR-'||to_char(current_date,'YYMMDD')||'-'||lpad(nextval('public.purchase_request_number_seq_v484')::text,6,'0');
  insert into public.purchase_requests_v484(id,tenant_id,location_id,preferred_supplier_id,request_number,required_date,priority,purpose,notes,requested_by)
  values(v_id,p_tenant_id,p_location_id,p_preferred_supplier_id,v_no,p_required_date,lower(coalesce(p_priority,'normal')),nullif(trim(coalesce(p_purpose,'')),''),nullif(trim(coalesce(p_notes,'')),''),auth.uid());
  for x in select value from jsonb_array_elements(v_norm) loop
    v_variant:=nullif(x->>'variant_id','')::uuid;v_qty:=coalesce(nullif(x->>'quantity','')::numeric,0);
    if v_variant is null or v_qty<=0 then raise exception 'Invalid purchase request item';end if;
    insert into public.purchase_request_items_v484(request_id,variant_id,quantity,entered_quantity,entered_unit_id,entered_unit_code,conversion_to_base,estimated_unit_cost,note)
    values(v_id,v_variant,v_qty,nullif(x->>'_entered_quantity','')::numeric,nullif(x->>'_entered_unit_id','')::uuid,nullif(x->>'_entered_unit_code',''),coalesce(nullif(x->>'_conversion_to_base','')::numeric,1),greatest(coalesce(nullif(x->>'_entered_unit_cost','')::numeric,nullif(x->>'unit_cost','')::numeric,0),0),nullif(trim(coalesce(x->>'note','')),''));
  end loop;
  insert into public.purchase_request_history_v484(request_id,to_status,note,changed_by) values(v_id,'draft','Purchase request created',auth.uid());
  perform private.thq_sync_bump_v480(p_tenant_id,'transactions','purchase_request',v_id::text,'create');
  return jsonb_build_object('success',true,'request_id',v_id,'request_number',v_no,'status','draft');
end$$;


--
-- Name: purchase_request_detail_v484(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_request_detail_v484(p_tenant_id uuid, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_loc uuid;v jsonb;begin
  select location_id into v_loc from public.purchase_requests_v484 where tenant_id=p_tenant_id and id=p_request_id;
  if v_loc is null then raise exception 'Purchase request not found';end if;perform private.purchasing_v484_access(p_tenant_id,v_loc,false);
  select jsonb_build_object('request',to_jsonb(r)||jsonb_build_object('location_name',l.name,'preferred_supplier_name',s.name),
    'items',coalesce((select jsonb_agg(to_jsonb(i)||jsonb_build_object('product_name',p.name,'sku',pv.sku) order by p.name) from public.purchase_request_items_v484 i join public.product_variants pv on pv.id=i.variant_id join public.products p on p.id=pv.product_id where i.request_id=r.id),'[]'::jsonb),
    'history',coalesce((select jsonb_agg(to_jsonb(h) order by h.id) from public.purchase_request_history_v484 h where h.request_id=r.id),'[]'::jsonb)) into v
  from public.purchase_requests_v484 r join public.business_locations l on l.id=r.location_id left join public.suppliers s on s.id=r.preferred_supplier_id where r.id=p_request_id and r.tenant_id=p_tenant_id;
  return v;
end$$;


--
-- Name: purchase_request_list_v484(uuid, uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_request_list_v484(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_query text DEFAULT ''::text, p_limit integer DEFAULT 500) RETURNS TABLE(id uuid, request_number text, request_date date, required_date date, priority text, status text, location_id uuid, location_name text, preferred_supplier_id uuid, preferred_supplier_name text, item_count bigint, total_quantity numeric, estimated_total numeric, purpose text, requested_by uuid, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare q text:='%'||lower(trim(coalesce(p_query,'')))||'%';begin
  perform private.purchasing_v484_permission(p_tenant_id,false);
  return query select r.id,r.request_number,r.request_date,r.required_date,r.priority,r.status,r.location_id,l.name,r.preferred_supplier_id,s.name,count(i.id),coalesce(sum(i.quantity),0),coalesce(sum(i.quantity*i.estimated_unit_cost),0),r.purpose,r.requested_by,r.created_at
  from public.purchase_requests_v484 r join public.business_locations l on l.id=r.location_id left join public.suppliers s on s.id=r.preferred_supplier_id left join public.purchase_request_items_v484 i on i.request_id=r.id left join public.product_variants pv on pv.id=i.variant_id left join public.products p on p.id=pv.product_id
  where r.tenant_id=p_tenant_id and (p_location_id is null or r.location_id=p_location_id) and (p_status is null or p_status='' or r.status=p_status)
    and private.erp_document_scope_allowed(p_tenant_id,r.location_id,p_location_id,'view')
    and (trim(coalesce(p_query,''))='' or lower(r.request_number) like q or lower(coalesce(r.purpose,'')) like q or lower(coalesce(s.name,'')) like q or lower(coalesce(p.name,'')) like q or lower(coalesce(pv.sku,'')) like q)
  group by r.id,l.name,s.name order by r.created_at desc limit greatest(1,least(coalesce(p_limit,500),2000));
end$$;


--
-- Name: purchase_request_status_v484(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_request_status_v484(p_tenant_id uuid, p_request_id uuid, p_status text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_old text;v_loc uuid;v_status text:=lower(trim(coalesce(p_status,'')));begin
  select status,location_id into v_old,v_loc from public.purchase_requests_v484 where tenant_id=p_tenant_id and id=p_request_id for update;if v_loc is null then raise exception 'Purchase request not found';end if;
  if v_status in('approved','rejected') then perform private.purchasing_v484_approval_access(p_tenant_id,v_loc);else perform private.purchasing_v484_access(p_tenant_id,v_loc,true);end if;
  if v_status not in('submitted','approved','rejected','cancelled') then raise exception 'Unsupported Purchase Request status transition';end if;
  if v_status='submitted' and v_old<>'draft' then raise exception 'Only Draft requests can be submitted';end if;
  if v_status in('approved','rejected') and v_old<>'submitted' then raise exception 'Only Submitted requests can be approved or rejected';end if;
  if v_status='cancelled' and v_old not in('draft','submitted','approved') then raise exception 'This request cannot be cancelled';end if;
  if v_status='rejected' and trim(coalesce(p_note,''))='' then raise exception 'Rejection reason is required';end if;
  update public.purchase_requests_v484 set status=v_status,updated_at=now(),
    submitted_by=case when v_status='submitted' then auth.uid() else submitted_by end,submitted_at=case when v_status='submitted' then now() else submitted_at end,
    approved_by=case when v_status='approved' then auth.uid() else approved_by end,approved_at=case when v_status='approved' then now() else approved_at end,
    rejected_by=case when v_status='rejected' then auth.uid() else rejected_by end,rejected_at=case when v_status='rejected' then now() else rejected_at end,rejection_reason=case when v_status='rejected' then trim(p_note) else rejection_reason end
  where id=p_request_id;
  insert into public.purchase_request_history_v484(request_id,from_status,to_status,note,changed_by) values(p_request_id,v_old,v_status,nullif(trim(coalesce(p_note,'')),''),auth.uid());
  perform private.thq_sync_bump_v480(p_tenant_id,'transactions','purchase_request',p_request_id::text,'status.'||v_status);
  return jsonb_build_object('success',true,'request_id',p_request_id,'from_status',v_old,'status',v_status);
end$$;


--
-- Name: purchase_return_create_v4(uuid, uuid, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_return_create_v4(p_tenant_id uuid, p_purchase_id uuid, p_items jsonb, p_reason text, p_device_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_loc uuid;v_id uuid:=gen_random_uuid();v_no text;x jsonb;v_pi public.purchase_items%rowtype;v_prev numeric;v_qty numeric;v_line numeric;v_sub numeric:=0;v_tax numeric:=0;v_total numeric:=0;begin
  if trim(coalesce(p_reason,''))='' then raise exception 'Return reason is required';end if;
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'purchases.return') and not private.erp_has_permission(p_tenant_id,'purchases.manage') then raise exception 'Purchase return permission required';end if;
  select location_id into v_loc from public.document_origins where tenant_id=p_tenant_id and entity_type='purchase' and entity_id=p_purchase_id;
  if v_loc is null then raise exception 'Original purchase does not have a store origin';end if;perform private.v4_location_access(p_tenant_id,v_loc,'operate');
  v_no:='PRN-'||lpad(nextval('public.purchase_return_number_seq')::text,6,'0');
  insert into public.purchase_returns(id,tenant_id,purchase_id,return_number,location_id,device_id,reason,created_by) values(v_id,p_tenant_id,p_purchase_id,v_no,v_loc,p_device_id,trim(p_reason),auth.uid());
  for x in select value from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) loop
    select * into v_pi from public.purchase_items where id=(x->>'purchase_item_id')::uuid and purchase_id=p_purchase_id;if not found then raise exception 'Purchase item not found';end if;
    v_qty:=(x->>'quantity')::numeric;if v_qty<=0 then raise exception 'Return quantity must be positive';end if;
    select coalesce(sum(i.quantity),0) into v_prev from public.purchase_return_items i join public.purchase_returns r on r.id=i.purchase_return_id where r.purchase_id=p_purchase_id and i.purchase_item_id=v_pi.id;
    if v_prev+v_qty>v_pi.quantity then raise exception 'Return quantity exceeds purchased quantity';end if;
    if coalesce((select quantity-reserved_quantity-damaged_quantity-quarantine_quantity from public.location_stock_balances where tenant_id=p_tenant_id and location_id=v_loc and variant_id=v_pi.variant_id),0)<v_qty then raise exception 'Insufficient branch stock for purchase return';end if;
    v_line:=round(((v_pi.unit_cost*v_qty)-coalesce(v_pi.discount_amount,0)*(v_qty/v_pi.quantity))*(1+coalesce(v_pi.tax_rate,0)/100.0),2);
    insert into public.purchase_return_items(purchase_return_id,purchase_item_id,variant_id,quantity,unit_cost,discount_amount,tax_rate,line_total)
    values(v_id,v_pi.id,v_pi.variant_id,v_qty,v_pi.unit_cost,coalesce(v_pi.discount_amount,0)*(v_qty/v_pi.quantity),coalesce(v_pi.tax_rate,0),v_line);
    v_sub:=v_sub+(v_pi.unit_cost*v_qty)-coalesce(v_pi.discount_amount,0)*(v_qty/v_pi.quantity);v_tax:=v_tax+(v_line-((v_pi.unit_cost*v_qty)-coalesce(v_pi.discount_amount,0)*(v_qty/v_pi.quantity)));v_total:=v_total+v_line;
    perform public.inventory_adjust_stock(p_tenant_id,v_pi.variant_id,-v_qty,'Purchase return • '||v_no);
    perform private.v4_location_stock_apply(p_tenant_id,v_loc,v_pi.variant_id,-v_qty,'purchase_return','purchase_return',v_id,v_no,trim(p_reason),p_device_id,false);
  end loop;
  update public.purchase_returns set subtotal=v_sub,tax_total=v_tax,grand_total=v_total where id=v_id;
  insert into public.transaction_corrections(tenant_id,entity_type,entity_id,correction_type,reason,created_by,metadata) values(p_tenant_id,'purchase',p_purchase_id,'return',trim(p_reason),auth.uid(),jsonb_build_object('return_id',v_id,'return_number',v_no,'amount',v_total));
  return jsonb_build_object('return_id',v_id,'return_number',v_no,'grand_total',v_total,'credit_status','supplier_credit');
end $$;


--
-- Name: purchase_return_create_v47(uuid, uuid, jsonb, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_return_create_v47(p_tenant_id uuid, p_purchase_id uuid, p_items jsonb, p_reason text, p_device_id uuid, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v jsonb;begin v:=private.v47_request_existing(p_tenant_id,p_request_id,'purchase.return');if v is not null then return v;end if;v:=public.purchase_return_create_v4(p_tenant_id,p_purchase_id,p_items,p_reason,p_device_id);return private.v47_request_complete(p_tenant_id,p_request_id,'purchase.return',v);end$$;


--
-- Name: purchase_return_create_v481(uuid, uuid, jsonb, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_return_create_v481(p_tenant_id uuid, p_purchase_id uuid, p_items jsonb, p_reason text, p_device_id uuid, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare x jsonb;v_items jsonb:='[]'::jsonb;v_pi public.purchase_items%rowtype;v_entered numeric;v_factor numeric;v_step numeric:=1;v_fractional boolean:=false;v jsonb;v_return uuid;begin
  for x in select value from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) loop
    select pi.* into v_pi from public.purchase_items pi where pi.id=(x->>'purchase_item_id')::uuid and pi.purchase_id=p_purchase_id;
    if not found then raise exception 'Purchase item not found';end if;
    v_entered:=coalesce(nullif(x->>'quantity','')::numeric,0);
    if v_entered<=0 then raise exception 'Return quantity must be positive';end if;
    v_factor:=coalesce(nullif(v_pi.conversion_to_base,0),1);
    if v_pi.entered_unit_id is not null then
      select pu.quantity_step,u.allow_fractional into v_step,v_fractional from public.product_units_v481 pu join public.inventory_units_v481 u on u.id=pu.unit_id where pu.tenant_id=p_tenant_id and pu.variant_id=v_pi.variant_id and pu.unit_id=v_pi.entered_unit_id;
      v_step:=greatest(coalesce(v_step,1),0.000001);
      if not coalesce(v_fractional,false) and v_entered<>trunc(v_entered) then raise exception 'Return unit % only allows whole quantities',coalesce(v_pi.entered_unit_code,'');end if;
      if abs((v_entered/v_step)-round(v_entered/v_step))>0.000001 then raise exception 'Return quantity for unit % must use increments of %',coalesce(v_pi.entered_unit_code,''),v_step;end if;
    end if;
    v_items:=v_items||jsonb_build_array(x||jsonb_build_object('quantity',v_entered*v_factor,'_entered_quantity',v_entered,'_unit_id',v_pi.entered_unit_id,'_unit_code',coalesce(v_pi.entered_unit_code,''),'_conversion_to_base',v_factor));
  end loop;
  v:=public.purchase_return_create_v47(p_tenant_id,p_purchase_id,v_items,p_reason,p_device_id,p_request_id);
  v_return:=nullif(v->>'return_id','')::uuid;
  if v_return is not null then
    for x in select value from jsonb_array_elements(v_items) loop
      update public.purchase_return_items ri set
        entered_unit_id=nullif(x->>'_unit_id','')::uuid,
        entered_unit_code=nullif(x->>'_unit_code',''),
        entered_quantity=(x->>'_entered_quantity')::numeric,
        conversion_to_base=(x->>'_conversion_to_base')::numeric
      where ri.purchase_return_id=v_return and ri.purchase_item_id=(x->>'purchase_item_id')::uuid;
      update public.location_stock_movements m set
        unit_id=nullif(x->>'_unit_id','')::uuid,
        unit_code=nullif(x->>'_unit_code',''),
        display_quantity=-abs((x->>'_entered_quantity')::numeric),
        conversion_to_base=(x->>'_conversion_to_base')::numeric
      where m.tenant_id=p_tenant_id and m.reference_type='purchase_return' and m.reference_id=v_return
        and m.variant_id=(select pi.variant_id from public.purchase_items pi where pi.id=(x->>'purchase_item_id')::uuid)
        and m.movement_type='purchase_return';
    end loop;
  end if;
  return v;
end $$;


--
-- Name: purchase_return_create_v483(uuid, uuid, jsonb, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_return_create_v483(p_tenant_id uuid, p_purchase_id uuid, p_items jsonb, p_reason text, p_device_id uuid, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare x jsonb;v_variant uuid;begin
 for x in select value from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) loop
  select variant_id into v_variant from public.purchase_items where id=(x->>'purchase_item_id')::uuid and purchase_id=p_purchase_id;
  if v_variant is null then raise exception 'Purchase item not found';end if;
  if private.v483_tracking_mode(p_tenant_id,v_variant)<>'none' then raise exception 'Returns for serial/batch products require trace allocation and are blocked in v4.8.3';end if;
 end loop;
 return public.purchase_return_create_v481(p_tenant_id,p_purchase_id,p_items,p_reason,p_device_id,p_request_id);
end$$;


--
-- Name: purchase_void_v4(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_void_v4(p_tenant_id uuid, p_purchase_id uuid, p_reason text, p_device_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_loc uuid;v_ref text;r record;begin
  if trim(coalesce(p_reason,''))='' then raise exception 'Void reason is required';end if;
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'purchases.void') then raise exception 'Purchase void permission required';end if;
  if exists(select 1 from public.purchase_payments where purchase_id=p_purchase_id and amount<>0) then raise exception 'Paid purchase cannot be voided directly. Use purchase return/refund workflow.';end if;
  if exists(select 1 from public.purchase_returns where purchase_id=p_purchase_id) then raise exception 'Purchase with returns cannot be voided';end if;
  select o.location_id,p.purchase_number into v_loc,v_ref from public.purchases p join public.document_origins o on o.entity_type='purchase' and o.entity_id=p.id where p.id=p_purchase_id and p.tenant_id=p_tenant_id for update;
  if v_loc is null then raise exception 'Purchase not found or has no branch origin';end if;perform private.v4_location_access(p_tenant_id,v_loc,'operate');
  for r in select pi.variant_id,pi.quantity,pr.item_type from public.purchase_items pi join public.product_variants pv on pv.id=pi.variant_id join public.products pr on pr.id=pv.product_id where pi.purchase_id=p_purchase_id loop
    if r.item_type='stock' then
      if coalesce((select quantity from public.location_stock_balances where tenant_id=p_tenant_id and location_id=v_loc and variant_id=r.variant_id),0)<r.quantity then raise exception 'Cannot void purchase because branch stock has already been consumed';end if;
      perform public.inventory_adjust_stock(p_tenant_id,r.variant_id,-r.quantity,'Void purchase • '||v_ref);perform private.v4_location_stock_apply(p_tenant_id,v_loc,r.variant_id,-r.quantity,'purchase_return','purchase',p_purchase_id,v_ref,'Void • '||trim(p_reason),p_device_id,false);
    end if;
  end loop;
  update public.purchases set status='void' where id=p_purchase_id and tenant_id=p_tenant_id;
  insert into public.transaction_corrections(tenant_id,entity_type,entity_id,correction_type,reason,created_by) values(p_tenant_id,'purchase',p_purchase_id,'void',trim(p_reason),auth.uid());
end $$;


--
-- Name: purchase_void_v47(uuid, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_void_v47(p_tenant_id uuid, p_purchase_id uuid, p_reason text, p_device_id uuid, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v jsonb;begin v:=private.v47_request_existing(p_tenant_id,p_request_id,'purchase.void');if v is not null then return v;end if;perform public.purchase_void_v4(p_tenant_id,p_purchase_id,p_reason,p_device_id);v:=jsonb_build_object('success',true,'purchase_id',p_purchase_id);return private.v47_request_complete(p_tenant_id,p_request_id,'purchase.void',v);end$$;


--
-- Name: purchase_void_v483(uuid, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_void_v483(p_tenant_id uuid, p_purchase_id uuid, p_reason text, p_device_id uuid, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$begin
 if exists(select 1 from public.purchase_items pi where pi.purchase_id=p_purchase_id and private.v483_tracking_mode(p_tenant_id,pi.variant_id)<>'none') then raise exception 'Voiding a purchase containing serial/batch products requires trace reversal and is blocked in v4.8.3';end if;
 return public.purchase_void_v47(p_tenant_id,p_purchase_id,p_reason,p_device_id,p_request_id);
end$$;


--
-- Name: purchases_add_payment(uuid, uuid, numeric, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchases_add_payment(p_tenant_id uuid, p_purchase_id uuid, p_amount numeric, p_payment_method text, p_reference_number text, p_notes text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_purchase_total numeric;

  v_paid_before numeric;
  v_paid_after numeric;

  v_balance_before numeric;
  v_balance_after numeric;

  v_payment_method text;

  v_payment_id uuid;

  v_payment_status text;
begin

  -- ----------------------------------------------------------
  -- PERMISSION
  -- ----------------------------------------------------------

  if not private.has_permission(
    p_tenant_id,
    'purchases.manage'
  ) then

    raise exception 'Access denied'
      using errcode = '42501';

  end if;


  -- ----------------------------------------------------------
  -- VALIDATE AMOUNT
  -- ----------------------------------------------------------

  if p_amount is null
     or p_amount <= 0 then

    raise exception
      'Payment amount must be greater than zero';

  end if;


  -- ----------------------------------------------------------
  -- PURCHASE
  -- ----------------------------------------------------------

  select p.grand_total
  into v_purchase_total

  from public.purchases p

  where p.id = p_purchase_id
    and p.tenant_id = p_tenant_id
    and p.status = 'posted'

  for update;


  if v_purchase_total is null then

    raise exception
      'Purchase not found or is not active';

  end if;


  -- ----------------------------------------------------------
  -- CURRENT PAYMENTS
  -- ----------------------------------------------------------

  select coalesce(
    sum(pp.amount),
    0
  )

  into v_paid_before

  from public.purchase_payments pp

  where pp.purchase_id = p_purchase_id
    and pp.tenant_id = p_tenant_id;


  v_balance_before :=
    v_purchase_total
    - v_paid_before;


  if v_balance_before <= 0 then

    raise exception
      'This purchase is already fully paid';

  end if;


  if p_amount >
     v_balance_before then

    raise exception
      'Payment cannot exceed remaining balance of %',
      v_balance_before;

  end if;


  -- ----------------------------------------------------------
  -- PAYMENT METHOD
  -- ----------------------------------------------------------

  v_payment_method :=
    lower(
      trim(
        coalesce(
          p_payment_method,
          ''
        )
      )
    );


  if v_payment_method not in (
    'cash',
    'bank',
    'card',
    'upi',
    'cheque',
    'other'
  ) then

    raise exception
      'Invalid payment method';

  end if;


  -- ----------------------------------------------------------
  -- CREATE PAYMENT
  -- ----------------------------------------------------------

  insert into public.purchase_payments (
    tenant_id,

    purchase_id,

    amount,

    payment_method,

    reference_number,

    notes,

    paid_at,

    created_by
  )
  values (
    p_tenant_id,

    p_purchase_id,

    p_amount,

    v_payment_method,

    nullif(
      trim(
        coalesce(
          p_reference_number,
          ''
        )
      ),
      ''
    ),

    nullif(
      trim(
        coalesce(
          p_notes,
          ''
        )
      ),
      ''
    ),

    now(),

    auth.uid()
  )

  returning id
  into v_payment_id;


  -- ----------------------------------------------------------
  -- NEW BALANCE
  -- ----------------------------------------------------------

  v_paid_after :=
    v_paid_before
    + p_amount;


  v_balance_after :=
    v_purchase_total
    - v_paid_after;


  if v_balance_after <= 0 then

    v_payment_status :=
      'paid';

  elsif v_paid_after > 0 then

    v_payment_status :=
      'partial';

  else

    v_payment_status :=
      'unpaid';

  end if;


  -- ----------------------------------------------------------
  -- RESULT
  -- ----------------------------------------------------------

  return jsonb_build_object(

    'success',
    true,

    'payment_id',
    v_payment_id,

    'amount',
    p_amount,

    'paid_amount',
    v_paid_after,

    'balance_due',
    v_balance_after,

    'payment_status',
    v_payment_status
  );

end;
$$;


--
-- Name: purchases_add_payment_v32(uuid, uuid, numeric, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchases_add_payment_v32(p_tenant_id uuid, p_purchase_id uuid, p_amount numeric, p_payment_method text, p_reference_number text, p_notes text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_loc uuid;v jsonb;begin
  select location_id into v_loc from public.document_origins where entity_type='purchase' and entity_id=p_purchase_id and tenant_id=p_tenant_id;
  if not private.erp_document_scope_allowed(p_tenant_id,v_loc,null,'operate') then raise exception 'Location access denied';end if;
  v:=public.purchases_add_payment(p_tenant_id,p_purchase_id,p_amount,p_payment_method,p_reference_number,p_notes);return v;
end $$;


--
-- Name: purchases_add_payment_v47(uuid, uuid, numeric, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchases_add_payment_v47(p_tenant_id uuid, p_purchase_id uuid, p_amount numeric, p_payment_method text, p_reference_number text, p_notes text, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v jsonb;begin v:=private.v47_request_existing(p_tenant_id,p_request_id,'purchase.payment');if v is not null then return v;end if;v:=public.purchases_add_payment_v32(p_tenant_id,p_purchase_id,p_amount,p_payment_method,p_reference_number,p_notes);return private.v47_request_complete(p_tenant_id,p_request_id,'purchase.payment',v);end$$;


--
-- Name: purchases_create(uuid, uuid, text, date, date, jsonb, numeric, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchases_create(p_tenant_id uuid, p_supplier_id uuid, p_supplier_invoice_number text, p_purchase_date date, p_due_date date, p_items jsonb, p_additional_charges numeric, p_initial_payment numeric, p_payment_method text, p_notes text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_purchase_id uuid;
  v_purchase_number text;

  v_supplier_name text;
  v_supplier_tax_number text;

  v_location_id uuid;

  v_item jsonb;

  v_variant_id uuid;

  v_product_name text;
  v_sku text;
  v_part_number text;
  v_unit_code text;

  v_quantity numeric;
  v_unit_cost numeric;
  v_discount numeric;
  v_tax_rate numeric;

  v_line_subtotal numeric;
  v_line_taxable numeric;
  v_line_tax numeric;
  v_line_total numeric;

  v_subtotal numeric := 0;
  v_discount_total numeric := 0;
  v_taxable_total numeric := 0;
  v_tax_total numeric := 0;
  v_grand_total numeric := 0;

  v_current_stock numeric;
  v_current_cost numeric;
  v_new_average_cost numeric;

  v_initial_payment numeric;
  v_payment_method text;

  v_supplier_invoice_number text;
begin

  -- ----------------------------------------------------------
  -- PERMISSION
  -- ----------------------------------------------------------

  if not private.has_permission(
    p_tenant_id,
    'purchases.manage'
  ) then

    raise exception 'Access denied'
      using errcode = '42501';

  end if;


  -- ----------------------------------------------------------
  -- BUSINESS
  -- ----------------------------------------------------------

  if not exists (
    select 1
    from public.tenants t
    where t.id = p_tenant_id
      and t.status = 'active'
  ) then

    raise exception
      'Business not found or inactive';

  end if;


  -- ----------------------------------------------------------
  -- SUPPLIER
  -- ----------------------------------------------------------

  select
    s.name,
    s.tax_number

  into
    v_supplier_name,
    v_supplier_tax_number

  from public.suppliers s

  where s.id = p_supplier_id
    and s.tenant_id = p_tenant_id
    and s.status = 'active';


  if v_supplier_name is null then
    raise exception
      'Active supplier not found';
  end if;


  -- ----------------------------------------------------------
  -- PURCHASE DATE
  -- ----------------------------------------------------------

  if p_purchase_date is null then
    raise exception
      'Purchase date is required';
  end if;


  if p_due_date is not null
     and p_due_date < p_purchase_date then

    raise exception
      'Due date cannot be before purchase date';

  end if;


  -- ----------------------------------------------------------
  -- ITEMS
  -- ----------------------------------------------------------

  if p_items is null
     or jsonb_typeof(p_items) <> 'array'
     or jsonb_array_length(p_items) = 0 then

    raise exception
      'Purchase must contain at least one item';

  end if;


  -- Prevent same SKU being entered twice.

  if exists (
    select 1

    from (
      select
        item ->> 'variant_id'
          as variant_id_text,
        count(*) as item_count

      from jsonb_array_elements(p_items)
        as item

      group by
        item ->> 'variant_id'
    ) duplicates

    where duplicates.variant_id_text is null
       or duplicates.variant_id_text = ''
       or duplicates.item_count > 1
  ) then

    raise exception
      'Each product may appear only once in a purchase';

  end if;


  -- ----------------------------------------------------------
  -- ADDITIONAL CHARGES
  -- ----------------------------------------------------------

  if p_additional_charges is null
     or p_additional_charges < 0 then

    raise exception
      'Additional charges cannot be negative';

  end if;


  -- ----------------------------------------------------------
  -- INITIAL PAYMENT
  -- ----------------------------------------------------------

  v_initial_payment :=
    coalesce(
      p_initial_payment,
      0
    );


  if v_initial_payment < 0 then
    raise exception
      'Initial payment cannot be negative';
  end if;


  v_payment_method :=
    lower(
      trim(
        coalesce(
          p_payment_method,
          ''
        )
      )
    );


  if v_initial_payment > 0 then

    if v_payment_method = '' then
      v_payment_method := 'cash';
    end if;


    if v_payment_method not in (
      'cash',
      'bank',
      'card',
      'upi',
      'cheque',
      'other'
    ) then

      raise exception
        'Invalid payment method';

    end if;

  end if;


  -- ----------------------------------------------------------
  -- SUPPLIER INVOICE
  -- ----------------------------------------------------------

  v_supplier_invoice_number :=
    nullif(
      trim(
        coalesce(
          p_supplier_invoice_number,
          ''
        )
      ),
      ''
    );


  if v_supplier_invoice_number is not null
     and exists (
       select 1

       from public.purchases p

       where p.tenant_id = p_tenant_id
         and p.supplier_id = p_supplier_id
         and lower(p.supplier_invoice_number) =
             lower(v_supplier_invoice_number)
     ) then

    raise exception
      'This supplier invoice has already been entered';

  end if;


  -- ----------------------------------------------------------
  -- DEFAULT STOCK LOCATION
  -- ----------------------------------------------------------

  select il.id
  into v_location_id

  from public.inventory_locations il

  where il.tenant_id = p_tenant_id
    and il.is_active = true

  order by
    il.is_default desc,
    case
      when il.code = 'MAIN'
        then 0
      else 1
    end,
    il.created_at

  limit 1;


  if v_location_id is null then
    raise exception
      'No active inventory location exists';
  end if;


  -- ----------------------------------------------------------
  -- INTERNAL DOCUMENT NUMBER
  -- ----------------------------------------------------------

  v_purchase_number :=
    private.next_document_number(
      p_tenant_id,
      'purchase',
      'PUR'
    );


  -- ----------------------------------------------------------
  -- CREATE HEADER
  --
  -- Totals updated after processing items.
  -- ----------------------------------------------------------

  insert into public.purchases (
    tenant_id,

    purchase_number,

    supplier_id,
    supplier_name,
    supplier_tax_number,

    supplier_invoice_number,

    purchase_date,
    due_date,

    status,

    subtotal,
    discount_total,
    taxable_total,
    tax_total,
    additional_charges,
    grand_total,

    notes,

    posted_at,
    created_by
  )
  values (
    p_tenant_id,

    v_purchase_number,

    p_supplier_id,
    v_supplier_name,
    v_supplier_tax_number,

    v_supplier_invoice_number,

    p_purchase_date,
    p_due_date,

    'posted',

    0,
    0,
    0,
    0,
    p_additional_charges,
    0,

    nullif(
      trim(
        coalesce(
          p_notes,
          ''
        )
      ),
      ''
    ),

    now(),
    auth.uid()
  )
  returning id
  into v_purchase_id;


  -- ==========================================================
  -- PROCESS EACH PURCHASE ITEM
  -- ==========================================================

  for v_item in

    select value
    from jsonb_array_elements(
      p_items
    )

  loop

    -- --------------------------------------------------------
    -- PARSE LINE
    -- --------------------------------------------------------

    begin
      v_variant_id :=
        (v_item ->> 'variant_id')::uuid;

      v_quantity :=
        (v_item ->> 'quantity')::numeric;

      v_unit_cost :=
        (v_item ->> 'unit_cost')::numeric;

      v_discount :=
        coalesce(
          nullif(
            v_item ->> 'discount_amount',
            ''
          )::numeric,
          0
        );

      v_tax_rate :=
        coalesce(
          nullif(
            v_item ->> 'tax_rate',
            ''
          )::numeric,
          0
        );

    exception
      when others then

        raise exception
          'Invalid purchase item data';

    end;


    -- --------------------------------------------------------
    -- LINE VALIDATION
    -- --------------------------------------------------------

    if v_quantity <= 0 then
      raise exception
        'Purchase quantity must be greater than zero';
    end if;


    if v_unit_cost < 0 then
      raise exception
        'Purchase cost cannot be negative';
    end if;


    if v_discount < 0 then
      raise exception
        'Item discount cannot be negative';
    end if;


    if v_tax_rate < 0
       or v_tax_rate > 100 then

      raise exception
        'Item tax rate must be between 0 and 100';

    end if;


    -- --------------------------------------------------------
    -- LOCK SKU
    --
    -- Serializes cost updates for this SKU.
    -- --------------------------------------------------------

    select
      p.name,
      pv.sku,
      pv.part_number,
      iu.code,
      pv.cost_price

    into
      v_product_name,
      v_sku,
      v_part_number,
      v_unit_code,
      v_current_cost

    from public.product_variants pv

    join public.products p
      on p.id = pv.product_id
     and p.tenant_id = pv.tenant_id

    left join public.inventory_units iu
      on iu.id = p.base_unit_id
     and iu.tenant_id = p.tenant_id

    where pv.id = v_variant_id
      and pv.tenant_id = p_tenant_id
      and pv.status = 'active'
      and p.status = 'active'
      and p.item_type = 'stock'

    for update of pv;


    if v_product_name is null then
      raise exception
        'Purchase item is invalid or is not an active stock item';
    end if;


    -- --------------------------------------------------------
    -- CALCULATE LINE TOTALS
    -- --------------------------------------------------------

    v_line_subtotal :=
      round(
        v_quantity * v_unit_cost,
        4
      );


    if v_discount >
       v_line_subtotal then

      raise exception
        'Item discount cannot exceed item subtotal';

    end if;


    v_line_taxable :=
      round(
        v_line_subtotal
        - v_discount,
        4
      );


    v_line_tax :=
      round(
        v_line_taxable
        * v_tax_rate
        / 100,
        4
      );


    v_line_total :=
      round(
        v_line_taxable
        + v_line_tax,
        4
      );


    -- --------------------------------------------------------
    -- CREATE PURCHASE LINE
    -- --------------------------------------------------------

    insert into public.purchase_items (
      tenant_id,
      purchase_id,
      variant_id,

      product_name,
      sku,
      part_number,
      unit_code,

      quantity,
      unit_cost,

      discount_amount,
      tax_rate,

      subtotal,
      taxable_amount,
      tax_amount,
      line_total
    )
    values (
      p_tenant_id,
      v_purchase_id,
      v_variant_id,

      v_product_name,
      v_sku,
      v_part_number,
      v_unit_code,

      v_quantity,
      v_unit_cost,

      v_discount,
      v_tax_rate,

      v_line_subtotal,
      v_line_taxable,
      v_line_tax,
      v_line_total
    );


    -- --------------------------------------------------------
    -- CURRENT STOCK
    --
    -- Used for moving average purchase cost.
    -- --------------------------------------------------------

    select
      coalesce(
        sum(sb.quantity),
        0
      )

    into v_current_stock

    from public.stock_balances sb

    where sb.tenant_id = p_tenant_id
      and sb.variant_id = v_variant_id;


    -- --------------------------------------------------------
    -- MOVING AVERAGE COST
    --
    -- Example:
    --
    -- Existing:
    -- 15 units @ ₹3200
    --
    -- Purchase:
    -- 10 units @ ₹3100
    --
    -- New average:
    -- ₹3160
    -- --------------------------------------------------------

    if
      v_current_stock + v_quantity > 0
    then

      v_new_average_cost :=
        round(
          (
            (
              v_current_stock
              * v_current_cost
            )
            +
            (
              v_quantity
              * v_unit_cost
            )
          )
          /
          (
            v_current_stock
            + v_quantity
          ),
          4
        );

    else

      v_new_average_cost :=
        v_unit_cost;

    end if;


    update public.product_variants
    set cost_price =
      v_new_average_cost
    where id = v_variant_id
      and tenant_id = p_tenant_id;


    -- --------------------------------------------------------
    -- STOCK MOVEMENT
    -- --------------------------------------------------------

    insert into public.stock_movements (
      tenant_id,
      variant_id,
      location_id,

      movement_type,
      quantity_delta,

      unit_cost,

      reference_type,
      reference_id,
      reference_number,

      note,

      occurred_at,
      created_by
    )
    values (
      p_tenant_id,
      v_variant_id,
      v_location_id,

      'purchase',
      v_quantity,

      v_unit_cost,

      'purchase',
      v_purchase_id,
      v_purchase_number,

      'Purchase from '
      || v_supplier_name,

      now(),
      auth.uid()
    );


    -- --------------------------------------------------------
    -- CURRENT STOCK BALANCE
    -- --------------------------------------------------------

    insert into public.stock_balances (
      tenant_id,
      location_id,
      variant_id,
      quantity,
      updated_at
    )
    values (
      p_tenant_id,
      v_location_id,
      v_variant_id,
      v_quantity,
      now()
    )

    on conflict (
      tenant_id,
      location_id,
      variant_id
    )
    do update set

      quantity =
        public.stock_balances.quantity
        + excluded.quantity,

      updated_at = now();


    -- --------------------------------------------------------
    -- HEADER TOTALS
    -- --------------------------------------------------------

    v_subtotal :=
      v_subtotal
      + v_line_subtotal;


    v_discount_total :=
      v_discount_total
      + v_discount;


    v_taxable_total :=
      v_taxable_total
      + v_line_taxable;


    v_tax_total :=
      v_tax_total
      + v_line_tax;

  end loop;


  -- ----------------------------------------------------------
  -- GRAND TOTAL
  -- ----------------------------------------------------------

  v_grand_total :=
    round(
      v_taxable_total
      + v_tax_total
      + p_additional_charges,
      4
    );


  if v_initial_payment >
     v_grand_total then

    raise exception
      'Initial payment cannot exceed purchase total';

  end if;


  -- ----------------------------------------------------------
  -- UPDATE HEADER TOTALS
  -- ----------------------------------------------------------

  update public.purchases
  set
    subtotal =
      v_subtotal,

    discount_total =
      v_discount_total,

    taxable_total =
      v_taxable_total,

    tax_total =
      v_tax_total,

    grand_total =
      v_grand_total

  where id = v_purchase_id
    and tenant_id = p_tenant_id;


  -- ----------------------------------------------------------
  -- OPTIONAL INITIAL PAYMENT
  -- ----------------------------------------------------------

  if v_initial_payment > 0 then

    insert into public.purchase_payments (
      tenant_id,
      purchase_id,

      amount,

      payment_method,

      notes,

      paid_at,
      created_by
    )
    values (
      p_tenant_id,
      v_purchase_id,

      v_initial_payment,

      v_payment_method,

      'Payment entered with purchase',

      now(),
      auth.uid()
    );

  end if;


  -- ----------------------------------------------------------
  -- RESULT
  -- ----------------------------------------------------------

  return jsonb_build_object(
    'success', true,

    'purchase_id',
    v_purchase_id,

    'purchase_number',
    v_purchase_number,

    'grand_total',
    v_grand_total,

    'paid_amount',
    v_initial_payment,

    'balance_due',
    v_grand_total
      - v_initial_payment
  );

end;
$$;


--
-- Name: purchases_create_v32(uuid, uuid, text, date, date, jsonb, numeric, numeric, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchases_create_v32(p_tenant_id uuid, p_supplier_id uuid, p_supplier_invoice_number text, p_purchase_date date, p_due_date date, p_items jsonb, p_additional_charges numeric, p_initial_payment numeric, p_payment_method text, p_notes text, p_location_id uuid, p_device_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_result jsonb;
  v_ref text;
  v_id uuid;
  v_origin jsonb;
begin
  perform private.erp_validate_transaction_origin(p_tenant_id,p_location_id,p_device_id,'purchases');

  select public.purchases_create(
    p_tenant_id=>p_tenant_id,
    p_supplier_id=>p_supplier_id,
    p_supplier_invoice_number=>p_supplier_invoice_number,
    p_purchase_date=>p_purchase_date,
    p_due_date=>p_due_date,
    p_items=>p_items,
    p_additional_charges=>p_additional_charges,
    p_initial_payment=>p_initial_payment,
    p_payment_method=>p_payment_method,
    p_notes=>p_notes
  ) into v_result;

  v_ref:=coalesce(v_result->>'purchase_number',v_result->>'number');
  if nullif(v_ref,'') is null then raise exception 'Purchase transaction did not return a purchase number'; end if;
  v_id:=public.document_origin_attach_by_reference(p_tenant_id,'purchase',v_ref,p_location_id,p_device_id);
  v_origin:=public.document_origin_get(p_tenant_id,'purchase',v_id);
  return coalesce(v_result,'{}'::jsonb) || jsonb_build_object(
    'purchase_id',coalesce(v_result->>'purchase_id',v_id::text),
    'invoice_number',v_origin->>'invoice_number',
    'location_id',p_location_id,
    'device_id',p_device_id
  );
end $$;


--
-- Name: purchases_create_v4(uuid, uuid, text, date, date, jsonb, numeric, numeric, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchases_create_v4(p_tenant_id uuid, p_supplier_id uuid, p_supplier_invoice_number text, p_purchase_date date, p_due_date date, p_items jsonb, p_additional_charges numeric, p_initial_payment numeric, p_payment_method text, p_notes text, p_location_id uuid, p_device_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_result jsonb;v_purchase_id uuid;v_ref text;x jsonb;v_variant uuid;v_qty numeric;v_item_type text;v_origin jsonb;begin
  perform private.erp_validate_transaction_origin(p_tenant_id,p_location_id,p_device_id,'purchases');
  select public.purchases_create(p_tenant_id,p_supplier_id,p_supplier_invoice_number,p_purchase_date,p_due_date,p_items,p_additional_charges,p_initial_payment,p_payment_method,p_notes) into v_result;
  v_ref:=coalesce(v_result->>'purchase_number',v_result->>'number');
  begin v_purchase_id:=coalesce(nullif(v_result->>'purchase_id',''),nullif(v_result->>'id',''))::uuid;exception when others then v_purchase_id:=null;end;
  if v_purchase_id is null then select id into v_purchase_id from public.purchases where tenant_id=p_tenant_id and purchase_number=v_ref order by created_at desc limit 1;end if;
  if v_purchase_id is null then raise exception 'Purchase transaction could not be resolved';end if;
  perform public.document_origin_attach(p_tenant_id,'purchase',v_purchase_id,p_location_id,p_device_id);
  for x in select value from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) loop
    v_variant:=(x->>'variant_id')::uuid;v_qty:=coalesce((x->>'quantity')::numeric,0);
    select p.item_type into v_item_type from public.product_variants pv join public.products p on p.id=pv.product_id where pv.id=v_variant and pv.tenant_id=p_tenant_id;
    if v_item_type='stock' then
      perform public.inventory_location_assign_v4(p_tenant_id,p_location_id,v_variant,true,null,null,null);
      perform private.v4_location_stock_apply(p_tenant_id,p_location_id,v_variant,v_qty,'purchase','purchase',v_purchase_id,v_ref,'Purchase',p_device_id,false);
    end if;
  end loop;
  begin v_origin:=public.document_origin_get(p_tenant_id,'purchase',v_purchase_id); exception when others then v_origin:='{}'::jsonb;end;
  return coalesce(v_result,'{}'::jsonb)||jsonb_build_object('purchase_id',v_purchase_id,'location_id',p_location_id,'device_id',p_device_id,'invoice_number',coalesce(v_origin->>'invoice_number',v_ref));
end $$;


--
-- Name: purchases_create_v47(uuid, uuid, text, date, date, jsonb, numeric, numeric, text, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchases_create_v47(p_tenant_id uuid, p_supplier_id uuid, p_supplier_invoice_number text, p_purchase_date date, p_due_date date, p_items jsonb, p_additional_charges numeric, p_initial_payment numeric, p_payment_method text, p_notes text, p_location_id uuid, p_device_id uuid, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v jsonb;begin
  v:=private.v47_request_existing(p_tenant_id,p_request_id,'purchase.create'); if v is not null then return v;end if;
  v:=public.purchases_create_v4(p_tenant_id,p_supplier_id,p_supplier_invoice_number,p_purchase_date,p_due_date,p_items,p_additional_charges,p_initial_payment,p_payment_method,p_notes,p_location_id,p_device_id);
  return private.v47_request_complete(p_tenant_id,p_request_id,'purchase.create',v);
end $$;


--
-- Name: purchases_create_v481(uuid, uuid, text, date, date, jsonb, numeric, numeric, text, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchases_create_v481(p_tenant_id uuid, p_supplier_id uuid, p_supplier_invoice_number text, p_purchase_date date, p_due_date date, p_items jsonb, p_additional_charges numeric, p_initial_payment numeric, p_payment_method text, p_notes text, p_location_id uuid, p_device_id uuid, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_items jsonb;v jsonb;v_purchase uuid;x jsonb;v_variant uuid;begin
  v_items:=private.v481_normalize_items(p_tenant_id,p_items,'purchase');
  v:=public.purchases_create_v47(p_tenant_id,p_supplier_id,p_supplier_invoice_number,p_purchase_date,p_due_date,v_items,p_additional_charges,p_initial_payment,p_payment_method,p_notes,p_location_id,p_device_id,p_request_id);
  v_purchase:=nullif(v->>'purchase_id','')::uuid;
  if v_purchase is not null then
    for x in select value from jsonb_array_elements(v_items) loop
      v_variant:=(x->>'variant_id')::uuid;
      update public.purchase_items pi set entered_unit_id=nullif(x->>'_entered_unit_id','')::uuid,entered_unit_code=x->>'_entered_unit_code',entered_quantity=(x->>'_entered_quantity')::numeric,conversion_to_base=(x->>'_conversion_to_base')::numeric,entered_unit_cost=(x->>'_entered_unit_cost')::numeric where pi.purchase_id=v_purchase and pi.variant_id=v_variant;
      update public.location_stock_movements m set unit_id=nullif(x->>'_entered_unit_id','')::uuid,unit_code=x->>'_entered_unit_code',display_quantity=abs((x->>'_entered_quantity')::numeric),conversion_to_base=(x->>'_conversion_to_base')::numeric,metadata=m.metadata||jsonb_build_object('entered_unit_cost',(x->>'_entered_unit_cost')::numeric)
      where m.tenant_id=p_tenant_id and m.reference_type='purchase' and m.reference_id=v_purchase and m.variant_id=v_variant and m.movement_type='purchase';
    end loop;
  end if;return v;
end $$;


--
-- Name: purchases_create_v483(uuid, uuid, text, date, date, jsonb, numeric, numeric, text, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchases_create_v483(p_tenant_id uuid, p_supplier_id uuid, p_supplier_invoice_number text, p_purchase_date date, p_due_date date, p_items jsonb, p_additional_charges numeric, p_initial_payment numeric, p_payment_method text, p_notes text, p_location_id uuid, p_device_id uuid, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_normalized jsonb;v_result jsonb;v_purchase uuid;x jsonb;v_variant uuid;v_mode text;v_recon jsonb;begin
 v_normalized:=private.v481_normalize_items(p_tenant_id,p_items,'purchase');
 -- A tracking policy may be enabled while legacy stock is still unregistered. Do not
 -- receive more tracked stock until the current location is reconciled, otherwise the
 -- opening quantity can no longer be registered unambiguously.
 for x in select value from jsonb_array_elements(v_normalized) loop
  v_variant:=(x->>'variant_id')::uuid;v_mode:=private.v483_tracking_mode(p_tenant_id,v_variant);
  if v_mode<>'none' then
   v_recon:=public.inventory_tracking_reconciliation_v483(p_tenant_id,v_variant,p_location_id);
   if not coalesce((v_recon->>'reconciled')::boolean,false) then
    raise exception 'Register existing serial/batch opening stock before receiving product % at this store',v_variant;
   end if;
  end if;
 end loop;
 v_result:=public.purchases_create_v481(p_tenant_id,p_supplier_id,p_supplier_invoice_number,p_purchase_date,p_due_date,p_items,p_additional_charges,p_initial_payment,p_payment_method,p_notes,p_location_id,p_device_id,p_request_id);
 v_purchase:=nullif(v_result->>'purchase_id','')::uuid;
 if v_purchase is not null then perform private.v483_apply_purchase_trace(p_tenant_id,v_purchase,p_supplier_id,p_location_id,v_normalized);end if;
 return v_result||jsonb_build_object('tracking_engine','v4.8.3');
end$$;


--
-- Name: purchases_create_v489(uuid, uuid, text, date, date, jsonb, numeric, numeric, numeric, text, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchases_create_v489(p_tenant_id uuid, p_supplier_id uuid, p_supplier_invoice_number text, p_purchase_date date, p_due_date date, p_items jsonb, p_additional_charges numeric, p_round_off numeric, p_initial_payment numeric, p_payment_method text, p_notes text, p_location_id uuid, p_device_id uuid, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v jsonb;v_id uuid;v_round numeric:=round(coalesce(p_round_off,0),2);v_add numeric:=greatest(coalesce(p_additional_charges,0),0);v_final numeric;v_old_round numeric;v_old_add numeric;v_old_total numeric;
begin
  if abs(v_round)>0.999999 then raise exception 'Round off must be between -1.00 and 1.00';end if;
  v:=public.purchases_create_v483(p_tenant_id,p_supplier_id,p_supplier_invoice_number,p_purchase_date,p_due_date,p_items,v_add+greatest(v_round,0),p_initial_payment,p_payment_method,p_notes,p_location_id,p_device_id,p_request_id);
  v_id:=nullif(v->>'purchase_id','')::uuid;if v_id is null then return v;end if;
  select round_off,additional_charges,grand_total into v_old_round,v_old_add,v_old_total from public.purchases where id=v_id and tenant_id=p_tenant_id for update;
  select round(coalesce(sum(pi.line_total),0)+v_add+v_round,2) into v_final from public.purchase_items pi where pi.purchase_id=v_id;
  if v_final<0 then raise exception 'Rounded purchase total cannot be negative';end if;
  if coalesce(p_initial_payment,0)>v_final+0.005 then raise exception 'Payment cannot exceed rounded purchase total';end if;
  if abs(coalesce(v_old_round,0)-v_round)>0.000001 or abs(coalesce(v_old_add,0)-v_add)>0.000001 or abs(coalesce(v_old_total,0)-v_final)>0.000001 then
    update public.journal_entries set status='reversed' where tenant_id=p_tenant_id and source_type='purchase' and source_id=v_id and status='posted';
    update public.purchases set additional_charges=v_add,round_off=v_round,grand_total=v_final where id=v_id and tenant_id=p_tenant_id;
    perform private.v4_accounting_post_document(p_tenant_id,'purchase',v_id);
  end if;
  return v||jsonb_build_object('grand_total',v_final,'round_off',v_round,'rounding_engine','v4.8.9');
end $$;


--
-- Name: purchases_get_detail(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchases_get_detail(p_tenant_id uuid, p_purchase_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_result jsonb;
begin

  if not (
    private.has_permission(
      p_tenant_id,
      'purchases.view'
    )
    or
    private.has_permission(
      p_tenant_id,
      'purchases.manage'
    )
  ) then

    raise exception 'Access denied'
      using errcode = '42501';

  end if;


  if not exists (
    select 1

    from public.purchases p

    where p.id = p_purchase_id
      and p.tenant_id = p_tenant_id
  ) then

    raise exception
      'Purchase not found';

  end if;


  select jsonb_build_object(

    'purchase',
    jsonb_build_object(
      'purchase_id',
      p.id,

      'purchase_number',
      p.purchase_number,

      'supplier_id',
      p.supplier_id,

      'supplier_name',
      p.supplier_name,

      'supplier_tax_number',
      p.supplier_tax_number,

      'supplier_invoice_number',
      p.supplier_invoice_number,

      'purchase_date',
      p.purchase_date,

      'due_date',
      p.due_date,

      'status',
      p.status,

      'subtotal',
      p.subtotal,

      'discount_total',
      p.discount_total,

      'taxable_total',
      p.taxable_total,

      'tax_total',
      p.tax_total,

      'additional_charges',
      p.additional_charges,

      'grand_total',
      p.grand_total,

      'notes',
      p.notes,

      'created_at',
      p.created_at
    ),

    'items',
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'item_id',
            pi.id,

            'variant_id',
            pi.variant_id,

            'product_name',
            pi.product_name,

            'sku',
            pi.sku,

            'part_number',
            pi.part_number,

            'unit_code',
            pi.unit_code,

            'quantity',
            pi.quantity,

            'unit_cost',
            pi.unit_cost,

            'discount_amount',
            pi.discount_amount,

            'tax_rate',
            pi.tax_rate,

            'subtotal',
            pi.subtotal,

            'taxable_amount',
            pi.taxable_amount,

            'tax_amount',
            pi.tax_amount,

            'line_total',
            pi.line_total
          )

          order by pi.created_at
        )

        from public.purchase_items pi

        where pi.purchase_id = p.id
          and pi.tenant_id = p.tenant_id
      ),

      '[]'::jsonb
    ),

    'payments',
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'payment_id',
            pp.id,

            'amount',
            pp.amount,

            'payment_method',
            pp.payment_method,

            'reference_number',
            pp.reference_number,

            'notes',
            pp.notes,

            'paid_at',
            pp.paid_at
          )

          order by pp.paid_at
        )

        from public.purchase_payments pp

        where pp.purchase_id = p.id
          and pp.tenant_id = p.tenant_id
      ),

      '[]'::jsonb
    ),

    'paid_amount',
    (
      select coalesce(
        sum(pp.amount),
        0
      )

      from public.purchase_payments pp

      where pp.purchase_id = p.id
        and pp.tenant_id = p.tenant_id
    ),

    'balance_due',
    p.grand_total
    -
    (
      select coalesce(
        sum(pp.amount),
        0
      )

      from public.purchase_payments pp

      where pp.purchase_id = p.id
        and pp.tenant_id = p.tenant_id
    )

  )

  into v_result

  from public.purchases p

  where p.id = p_purchase_id
    and p.tenant_id = p_tenant_id;


  return v_result;

end;
$$;


--
-- Name: purchases_get_detail_v32(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchases_get_detail_v32(p_tenant_id uuid, p_purchase_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_loc uuid;v jsonb;v_items jsonb;begin
  select o.location_id into v_loc from public.document_origins o where o.entity_type='purchase' and o.entity_id=p_purchase_id and o.tenant_id=p_tenant_id;
  if not private.erp_document_scope_allowed(p_tenant_id,v_loc,null,'view') then raise exception 'Location access denied';end if;
  v:=public.purchases_get_detail(p_tenant_id,p_purchase_id);
  select coalesce(jsonb_agg(i.value||jsonb_build_object(
    'unit_code',coalesce(pi.entered_unit_code,nullif(i.value->>'unit_code','')),
    'quantity',coalesce(pi.entered_quantity,(i.value->>'quantity')::numeric),
    'base_quantity',coalesce(pi.quantity,(i.value->>'quantity')::numeric),
    'unit_cost',coalesce(pi.entered_unit_cost,(i.value->>'unit_cost')::numeric),
    'conversion_to_base',coalesce(pi.conversion_to_base,1)
  )),'[]'::jsonb) into v_items
  from jsonb_array_elements(coalesce(v->'items','[]'::jsonb)) i(value)
  left join public.purchase_items pi on pi.purchase_id=p_purchase_id and pi.variant_id=nullif(i.value->>'variant_id','')::uuid;
  return jsonb_set(v,'{items}',coalesce(v_items,'[]'::jsonb),true);
end $$;


--
-- Name: purchases_get_detail_v520(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchases_get_detail_v520(p_tenant_id uuid, p_purchase_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_result jsonb;
  v_gst jsonb;
begin
  v_result := public.purchases_get_detail_v32(p_tenant_id, p_purchase_id);

  select jsonb_build_object(
    'authoritative', true,
    'snapshot_id', s.id,
    'document_class', s.document_class,
    'tax_mode', s.tax_mode,
    'supply_type', s.supply_type,
    'interstate', s.interstate,
    'place_of_supply_code', s.place_of_supply_code,
    'supplier_gstin', s.supplier_gstin,
    'recipient_gstin', s.recipient_gstin,
    'taxable_total', s.taxable_total,
    'cgst_total', s.cgst_total,
    'sgst_total', s.sgst_total,
    'utgst_total', s.utgst_total,
    'igst_total', s.igst_total,
    'cess_total', s.cess_total,
    'tax_collected_total', s.tax_collected_total,
    'government_tax_total', s.government_tax_total,
    'lines', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'source_line_id', l.source_line_id,
          'line_no', l.line_no,
          'hsn_sac', l.hsn_sac,
          'gst_rate', l.applied_gst_rate,
          'taxable_value', l.taxable_value,
          'cgst', l.cgst,
          'sgst', l.sgst,
          'utgst', l.utgst,
          'igst', l.igst,
          'cess', l.cess,
          'tax_amount', l.tax_amount
        ) order by l.line_no
      )
      from public.gst_document_line_snapshots_v520 l
      where l.snapshot_id = s.id
    ), '[]'::jsonb)
  )
  into v_gst
  from public.gst_document_snapshots_v520 s
  where s.tenant_id = p_tenant_id
    and s.source_type = 'purchase'
    and s.source_id = p_purchase_id
  order by s.created_at desc
  limit 1;

  return v_result || jsonb_build_object('gst', v_gst);
end;
$$;


--
-- Name: purchases_list(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchases_list(p_tenant_id uuid) RETURNS TABLE(purchase_id uuid, purchase_number text, supplier_id uuid, supplier_name text, supplier_invoice_number text, purchase_date date, due_date date, subtotal numeric, discount_total numeric, tax_total numeric, additional_charges numeric, grand_total numeric, paid_amount numeric, balance_due numeric, payment_status text, status text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin

  if not (
    private.has_permission(
      p_tenant_id,
      'purchases.view'
    )
    or
    private.has_permission(
      p_tenant_id,
      'purchases.manage'
    )
  ) then

    raise exception 'Access denied'
      using errcode = '42501';

  end if;


  return query

  select
    p.id,

    p.purchase_number,

    p.supplier_id,
    p.supplier_name,

    p.supplier_invoice_number,

    p.purchase_date,
    p.due_date,

    p.subtotal,
    p.discount_total,
    p.tax_total,
    p.additional_charges,

    p.grand_total,

    coalesce(
      pay.paid_amount,
      0
    )::numeric,

    (
      p.grand_total
      -
      coalesce(
        pay.paid_amount,
        0
      )
    )::numeric,

    case
      when
        coalesce(
          pay.paid_amount,
          0
        ) <= 0
        and p.grand_total > 0
      then 'unpaid'

      when
        coalesce(
          pay.paid_amount,
          0
        ) < p.grand_total
      then 'partial'

      else 'paid'
    end,

    p.status,

    p.created_at

  from public.purchases p

  left join lateral (
    select
      coalesce(
        sum(pp.amount),
        0
      ) as paid_amount

    from public.purchase_payments pp

    where pp.purchase_id = p.id
      and pp.tenant_id = p.tenant_id
  ) pay
    on true

  where p.tenant_id = p_tenant_id

  order by
    p.purchase_date desc,
    p.created_at desc;

end;
$$;


--
-- Name: purchases_list_v32(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchases_list_v32(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid) RETURNS TABLE(purchase_id uuid, purchase_number text, invoice_number text, supplier_id uuid, supplier_name text, supplier_invoice_number text, purchase_date date, due_date date, subtotal numeric, discount_total numeric, tax_total numeric, additional_charges numeric, grand_total numeric, paid_amount numeric, balance_due numeric, payment_status text, status text, created_at timestamp with time zone, location_id uuid, location_name text, device_id uuid, device_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  return query
  select p.id,p.purchase_number::text,coalesce(dn.terminal_number,ln.local_number,p.purchase_number)::text,
    p.supplier_id,s.name::text,p.supplier_invoice_number::text,p.purchase_date,p.due_date,
    p.subtotal,p.discount_total,p.tax_total,p.additional_charges,p.grand_total,
    coalesce(py.paid,0)::numeric,greatest(p.grand_total-coalesce(py.paid,0),0)::numeric,
    (case when greatest(p.grand_total-coalesce(py.paid,0),0)<=0.0001 then 'paid' when coalesce(py.paid,0)>0 then 'partial' else 'unpaid' end)::text,
    p.status::text,p.created_at,o.location_id,l.name::text,o.device_id,d.name::text
  from public.purchases p
  join public.suppliers s on s.id=p.supplier_id
  left join (
    select pp.purchase_id as entity_purchase_id,sum(pp.amount) as paid
    from public.purchase_payments pp group by pp.purchase_id
  ) py on py.entity_purchase_id=p.id
  left join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='purchase' and o.entity_id=p.id
  left join public.business_locations l on l.id=o.location_id
  left join public.business_devices d on d.id=o.device_id
  left join public.location_document_numbers ln on ln.tenant_id=p_tenant_id and ln.entity_type='purchase' and ln.entity_id=p.id
  left join public.device_document_numbers dn on dn.tenant_id=p_tenant_id and dn.entity_type='purchase' and dn.entity_id=p.id
  where p.tenant_id=p_tenant_id
    and (private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'purchases.view') or private.erp_has_permission(p_tenant_id,'purchases.manage'))
    and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view')
  order by p.purchase_date desc,p.created_at desc;
end $$;


--
-- Name: purchasing_dashboard_v484(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchasing_dashboard_v484(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_requests bigint;v_approval bigint;v_open_po bigint;v_partial bigint;v_unposted_grn bigint;v_open_invoices bigint;v_payable numeric;begin
 perform private.purchasing_v484_permission(p_tenant_id,false);
 select count(*) into v_requests from public.purchase_requests_v484 r where r.tenant_id=p_tenant_id and r.status in('draft','submitted') and (p_location_id is null or r.location_id=p_location_id) and private.erp_document_scope_allowed(p_tenant_id,r.location_id,p_location_id,'view');
 select count(*) into v_approval from public.purchase_orders_v480 p where p.tenant_id=p_tenant_id and p.status='submitted' and (p_location_id is null or p.location_id=p_location_id) and private.erp_document_scope_allowed(p_tenant_id,p.location_id,p_location_id,'view');
 select count(*) into v_open_po from public.purchase_orders_v480 p where p.tenant_id=p_tenant_id and p.status in('approved','ordered','partially_received') and (p_location_id is null or p.location_id=p_location_id) and private.erp_document_scope_allowed(p_tenant_id,p.location_id,p_location_id,'view');
 select count(*) into v_partial from public.purchase_orders_v480 p where p.tenant_id=p_tenant_id and p.status='partially_received' and (p_location_id is null or p.location_id=p_location_id) and private.erp_document_scope_allowed(p_tenant_id,p.location_id,p_location_id,'view');
 select count(*) into v_unposted_grn from public.goods_receipts_v484 g where g.tenant_id=p_tenant_id and g.status='draft' and (p_location_id is null or g.location_id=p_location_id) and private.erp_document_scope_allowed(p_tenant_id,g.location_id,p_location_id,'view');
 select count(*),coalesce(sum(balance_due),0) into v_open_invoices,v_payable from public.purchase_invoices_v484 i where i.tenant_id=p_tenant_id and i.status in('posted','part_paid') and (p_location_id is null or i.location_id=p_location_id) and private.erp_document_scope_allowed(p_tenant_id,i.location_id,p_location_id,'view');
 return jsonb_build_object('open_requests',v_requests,'po_awaiting_approval',v_approval,'open_purchase_orders',v_open_po,'partial_purchase_orders',v_partial,'draft_grns',v_unposted_grn,'open_supplier_invoices',v_open_invoices,'v2_payable_balance',v_payable);
end$$;


--
-- Name: recurring_expense_save_v500(uuid, uuid, uuid, uuid, text, text, text, numeric, numeric, text, text, date, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recurring_expense_save_v500(p_tenant_id uuid, p_id uuid, p_location_id uuid, p_category_id uuid, p_title text, p_payee text, p_description text, p_amount numeric, p_tax_amount numeric, p_payment_method text, p_frequency text, p_next_run_date date, p_auto_post boolean, p_active boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v uuid;begin perform private.v500_accounting_access(p_tenant_id,true);perform private.v4_location_access(p_tenant_id,p_location_id,'operate');
  if p_frequency not in('weekly','monthly','quarterly','yearly') then raise exception 'Invalid recurrence frequency';end if;if coalesce(p_amount,0)<=0 then raise exception 'Amount must be positive';end if;
  if p_id is null then insert into public.recurring_expenses_v500(tenant_id,location_id,category_id,title,payee,description,amount,tax_amount,payment_method,frequency,next_run_date,auto_post,active,created_by) values(p_tenant_id,p_location_id,p_category_id,trim(p_title),nullif(trim(coalesce(p_payee,'')),''),trim(p_description),p_amount,coalesce(p_tax_amount,0),coalesce(nullif(trim(p_payment_method),''),'cash'),p_frequency,p_next_run_date,coalesce(p_auto_post,false),coalesce(p_active,true),auth.uid()) returning id into v;
  else update public.recurring_expenses_v500 set location_id=p_location_id,category_id=p_category_id,title=trim(p_title),payee=nullif(trim(coalesce(p_payee,'')),''),description=trim(p_description),amount=p_amount,tax_amount=coalesce(p_tax_amount,0),payment_method=coalesce(nullif(trim(p_payment_method),''),'cash'),frequency=p_frequency,next_run_date=p_next_run_date,auto_post=coalesce(p_auto_post,false),active=coalesce(p_active,true),updated_at=now() where id=p_id and tenant_id=p_tenant_id returning id into v;end if;
  if v is null then raise exception 'Recurring expense not found';end if;return v;
end $$;


--
-- Name: recurring_expenses_list_v500(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recurring_expenses_list_v500(p_tenant_id uuid) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare r record;begin perform private.v500_accounting_access(p_tenant_id,false);for r in select e.*,c.name category_name,l.location_code,l.name location_name from public.recurring_expenses_v500 e join public.expense_categories c on c.id=e.category_id join public.business_locations l on l.id=e.location_id where e.tenant_id=p_tenant_id order by e.active desc,e.next_run_date,e.title loop return next to_jsonb(r);end loop;return;end $$;


--
-- Name: recurring_expenses_process_v500(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recurring_expenses_process_v500(p_tenant_id uuid, p_through_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare r public.recurring_expenses_v500%rowtype;v_result jsonb;v_count integer:=0;v_next date;v_request text;begin perform private.v500_accounting_access(p_tenant_id,true);
  for r in select * from public.recurring_expenses_v500 where tenant_id=p_tenant_id and active and auto_post and next_run_date<=coalesce(p_through_date,current_date) order by next_run_date for update loop
    v_request:='recurring-expense:'||r.id::text||':'||r.next_run_date::text;
    v_result:=public.expenses_create_v489(r.tenant_id,r.category_id,r.next_run_date,r.payee,r.description,r.amount,r.tax_amount,0,r.payment_method,coalesce(r.reference_prefix,'REC')||'-'||to_char(r.next_run_date,'YYYYMMDD'),'Recurring expense: '||r.title,r.location_id,null,v_request);
    v_next:=case r.frequency when 'weekly' then r.next_run_date+7 when 'monthly' then (r.next_run_date+interval '1 month')::date when 'quarterly' then (r.next_run_date+interval '3 months')::date else (r.next_run_date+interval '1 year')::date end;
    update public.recurring_expenses_v500 set last_run_date=r.next_run_date,next_run_date=v_next,updated_at=now() where id=r.id;v_count:=v_count+1;
  end loop;return jsonb_build_object('processed',v_count,'through_date',coalesce(p_through_date,current_date));
end $$;


--
-- Name: reorder_suggestions_v500(uuid, uuid, integer, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reorder_suggestions_v500(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_days integer DEFAULT 30, p_query text DEFAULT ''::text, p_limit integer DEFAULT 1000) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare r record;v_supplier uuid;v_supplier_name text;v_last_cost numeric;begin
  for r in select * from public.inventory_intelligence_v480(p_tenant_id,p_location_id,p_days,p_query,p_limit) where status in('out_of_stock','low_stock') and suggested_reorder>0 loop
    select p.supplier_id,s.name,pi.unit_cost into v_supplier,v_supplier_name,v_last_cost from public.purchase_items pi join public.purchases p on p.id=pi.purchase_id join public.suppliers s on s.id=p.supplier_id where p.tenant_id=p_tenant_id and pi.variant_id=r.variant_id and coalesce(p.status,'') not in('void','cancelled') order by p.purchase_date desc,p.created_at desc limit 1;
    return next to_jsonb(r)||jsonb_build_object('suggested_supplier_id',v_supplier,'suggested_supplier_name',v_supplier_name,'last_unit_cost',coalesce(v_last_cost,r.average_cost));
  end loop;return;
end $$;


--
-- Name: report_export_log_v44(uuid, text, text, date, date, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_export_log_v44(p_tenant_id uuid, p_report_key text, p_format text, p_from date, p_to date, p_location_id uuid, p_device_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_id uuid;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if lower(coalesce(p_format,'')) not in('pdf','xlsx','print','csv') then raise exception 'Invalid export format';end if;
  insert into public.report_export_events(tenant_id,report_key,format,from_date,to_date,location_id,device_id,created_by)
  values(p_tenant_id,coalesce(nullif(trim(p_report_key),''),'summary'),lower(p_format),p_from,p_to,p_location_id,p_device_id,auth.uid()) returning id into v_id;
  return v_id;
end $$;


--
-- Name: reports_catalog_v500(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reports_catalog_v500() RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
select jsonb_build_array(
  jsonb_build_object('category','Sales','reports',jsonb_build_array('sales_summary','sales_register','sales_by_product','sales_by_customer','sales_by_salesperson','sales_by_store','sales_by_pos','sales_by_payment_method','returns')),
  jsonb_build_object('category','Inventory','reports',jsonb_build_array('current_stock','stock_valuation','stock_movement','stock_aging','expiry','dead_stock','low_stock','serials','batches')),
  jsonb_build_object('category','Purchase','reports',jsonb_build_array('purchase_register','supplier_purchase','purchase_returns','supplier_outstanding','supplier_performance','price_history')),
  jsonb_build_object('category','Accounting','reports',jsonb_build_array('profit_loss','balance_sheet','trial_balance','general_ledger','cash_flow','receivables','payables','journal_register','expenses','tax','reconciliation'))
)
$$;


--
-- Name: reports_center_data_v500(uuid, text, date, date, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reports_center_data_v500(p_tenant_id uuid, p_report_key text, p_from date, p_to date, p_location_id uuid DEFAULT NULL::uuid, p_query text DEFAULT ''::text, p_limit integer DEFAULT 1000) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare r record;k text:=lower(trim(coalesce(p_report_key,'')));q text:='%'||lower(trim(coalesce(p_query,'')))||'%';begin if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;if p_from is null or p_to is null or p_to<p_from then raise exception 'Valid report date range is required';end if;if k='sales_summary' then return next public.reports_get_summary_v4(p_tenant_id,p_from,p_to,p_location_id);return;elsif k='sales_register' then for r in select * from public.accounting_register_v4(p_tenant_id,'sales',p_from,p_to,p_location_id,p_query) loop return next to_jsonb(r);end loop;return;elsif k='sales_by_product' then for r in select si.variant_id,si.product_name,si.sku,sum(si.quantity) quantity,round(sum(si.taxable_amount),2) taxable_sales,round(sum(si.tax_amount),2) tax,round(sum(si.line_total),2) total,round(sum(si.gross_profit),2) gross_profit from public.sale_items si join public.sales s on s.id=si.sale_id where s.tenant_id=p_tenant_id and s.sale_date between p_from and p_to and coalesce(s.status,'') not in('void','cancelled') and (p_location_id is null or private.v500_document_location(p_tenant_id,'sale',s.id)=p_location_id) and (trim(coalesce(p_query,''))='' or lower(si.product_name) like q or lower(coalesce(si.sku,'')) like q) group by si.variant_id,si.product_name,si.sku order by total desc limit greatest(1,least(coalesce(p_limit,1000),5000)) loop return next to_jsonb(r);end loop;return;elsif k='sales_by_customer' then for r in select s.customer_id,s.customer_name,count(*) invoices,round(sum(s.taxable_total),2) taxable_sales,round(sum(s.tax_total),2) tax,round(sum(s.grand_total),2) total,round(sum(s.gross_profit),2) gross_profit from public.sales s where s.tenant_id=p_tenant_id and s.sale_date between p_from and p_to and coalesce(s.status,'') not in('void','cancelled') and (p_location_id is null or private.v500_document_location(p_tenant_id,'sale',s.id)=p_location_id) and (trim(coalesce(p_query,''))='' or lower(s.customer_name) like q) group by s.customer_id,s.customer_name order by total desc limit greatest(1,least(coalesce(p_limit,1000),5000)) loop return next to_jsonb(r);end loop;return;elsif k='sales_by_salesperson' then for r in select cp.salesperson_user_id,coalesce(u.username::text,'Unassigned') salesperson,count(*) invoices,round(sum(s.taxable_total),2) taxable_sales,round(sum(s.grand_total),2) total from public.sales s left join public.customer_crm_profiles_v500 cp on cp.tenant_id=s.tenant_id and cp.customer_id=s.customer_id left join public.user_login_names u on u.user_id=cp.salesperson_user_id where s.tenant_id=p_tenant_id and s.sale_date between p_from and p_to and coalesce(s.status,'') not in('void','cancelled') and (p_location_id is null or private.v500_document_location(p_tenant_id,'sale',s.id)=p_location_id) group by cp.salesperson_user_id,u.username order by total desc loop return next to_jsonb(r);end loop;return;elsif k='sales_by_store' then for r in select l.id location_id,l.location_code,l.name,count(s.id) invoices,round(coalesce(sum(s.taxable_total),0),2) taxable_sales,round(coalesce(sum(s.grand_total),0),2) total from public.business_locations l left join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='sale' and o.location_id=l.id left join public.sales s on s.id=o.entity_id and s.tenant_id=p_tenant_id and s.sale_date between p_from and p_to and coalesce(s.status,'') not in('void','cancelled') where l.tenant_id=p_tenant_id and (p_location_id is null or l.id=p_location_id) group by l.id,l.location_code,l.name order by total desc loop return next to_jsonb(r);end loop;return;elsif k='sales_by_pos' then for r in select d.id device_id,coalesce(d.device_code,d.name) terminal,count(s.id) invoices,round(coalesce(sum(s.grand_total),0),2) total from public.business_devices d left join public.document_origins o on o.tenant_id=p_tenant_id and o.device_id=d.id and o.entity_type='sale' left join public.sales s on s.id=o.entity_id and s.sale_date between p_from and p_to and coalesce(s.status,'') not in('void','cancelled') where d.tenant_id=p_tenant_id and d.app_type='pos' and (p_location_id is null or d.location_id=p_location_id) group by d.id,d.device_code,d.name order by total desc loop return next to_jsonb(r);end loop;return;elsif k='sales_by_payment_method' then for r in select lower(coalesce(py.payment_method,'unknown')) payment_method,count(*) payment_count,round(sum(py.amount),2) amount from public.sale_payments py join public.sales s on s.id=py.sale_id where py.tenant_id=p_tenant_id and py.paid_at::date between p_from and p_to and (p_location_id is null or private.v500_document_location(p_tenant_id,'sale',s.id)=p_location_id) group by 1 order by amount desc loop return next to_jsonb(r);end loop;return;elsif k='purchase_register' then for r in select * from public.accounting_register_v4(p_tenant_id,'purchases',p_from,p_to,p_location_id,p_query) loop return next to_jsonb(r);end loop;return;elsif k='supplier_purchase' then for r in select p.supplier_id,s.name supplier_name,count(*) bills,round(sum(p.grand_total),2) total from public.purchases p join public.suppliers s on s.id=p.supplier_id where p.tenant_id=p_tenant_id and p.purchase_date between p_from and p_to and coalesce(p.status,'') not in('void','cancelled') and (p_location_id is null or private.v500_document_location(p_tenant_id,'purchase',p.id)=p_location_id) and (trim(coalesce(p_query,''))='' or lower(s.name) like q) group by p.supplier_id,s.name order by total desc loop return next to_jsonb(r);end loop;return;elsif k='price_history' then for r in select * from public.purchase_price_history_v484(p_tenant_id,null,null,p_location_id,p_query,p_limit) x where x.purchase_date between p_from and p_to loop return next to_jsonb(r);end loop;return;elsif k='supplier_performance' then for r in select * from public.supplier_performance_v500(p_tenant_id,p_from,p_to,p_limit) loop return next to_jsonb(r);end loop;return;elsif k in('returns','purchase_returns') then for r in select x row_json from public.returns_report_v500(p_tenant_id,case when k='purchase_returns' then 'purchase' else 'all' end,p_from,p_to,p_location_id,p_query,p_limit) x loop return next r.row_json;end loop;return;elsif k in('current_stock','stock_valuation','stock_aging','dead_stock','low_stock') then for r in select * from public.inventory_intelligence_v480(p_tenant_id,p_location_id,greatest(1,least((p_to-p_from)+1,365)),p_query,p_limit) x where (k not in('dead_stock','low_stock') or (k='dead_stock' and x.status='dead_stock') or (k='low_stock' and x.status in('low_stock','out_of_stock'))) loop return next to_jsonb(r);end loop;return;elsif k='stock_movement' then for r in select m.created_at,m.location_id,l.location_code,p.name product_name,pv.sku,m.movement_type,m.quantity_delta,m.unit_cost,m.reference_type,m.reference_number,m.note from public.location_stock_movements m join public.product_variants pv on pv.id=m.variant_id join public.products p on p.id=pv.product_id left join public.business_locations l on l.id=m.location_id where m.tenant_id=p_tenant_id and m.created_at::date between p_from and p_to and (p_location_id is null or m.location_id=p_location_id) and (trim(coalesce(p_query,''))='' or lower(p.name) like q or lower(coalesce(pv.sku,'')) like q or lower(coalesce(m.reference_number,'')) like q) order by m.created_at desc limit greatest(1,least(coalesce(p_limit,1000),5000)) loop return next to_jsonb(r);end loop;return;elsif k='expiry' then for r in select b.id batch_id,p.name product_name,pv.sku,b.batch_number,b.expiry_on,bb.location_id,l.location_code,bb.quantity from public.inventory_batches_v483 b join public.product_variants pv on pv.id=b.variant_id join public.products p on p.id=pv.product_id join public.inventory_batch_balances_v483 bb on bb.batch_id=b.id left join public.business_locations l on l.id=bb.location_id where b.tenant_id=p_tenant_id and b.expiry_on between p_from and p_to and bb.quantity>0 and (p_location_id is null or bb.location_id=p_location_id) order by b.expiry_on limit greatest(1,least(coalesce(p_limit,1000),5000)) loop return next to_jsonb(r);end loop;return;elsif k='serials' then for r in select s.serial_number,s.status,s.current_location_id location_id,l.location_code,p.name product_name,pv.sku,s.updated_at from public.inventory_serials_v483 s join public.product_variants pv on pv.id=s.variant_id join public.products p on p.id=pv.product_id left join public.business_locations l on l.id=s.current_location_id where s.tenant_id=p_tenant_id and (p_location_id is null or s.current_location_id=p_location_id) and (trim(coalesce(p_query,''))='' or lower(s.serial_number) like q or lower(p.name) like q or lower(coalesce(pv.sku,'')) like q) order by s.updated_at desc limit greatest(1,least(coalesce(p_limit,1000),5000)) loop return next to_jsonb(r);end loop;return;elsif k='batches' then for r in select b.batch_number,b.manufactured_on,b.expiry_on,p.name product_name,pv.sku,bb.location_id,l.location_code,bb.quantity from public.inventory_batches_v483 b join public.product_variants pv on pv.id=b.variant_id join public.products p on p.id=pv.product_id join public.inventory_batch_balances_v483 bb on bb.batch_id=b.id left join public.business_locations l on l.id=bb.location_id where b.tenant_id=p_tenant_id and (p_location_id is null or bb.location_id=p_location_id) and (trim(coalesce(p_query,''))='' or lower(b.batch_number) like q or lower(p.name) like q) order by b.created_at desc limit greatest(1,least(coalesce(p_limit,1000),5000)) loop return next to_jsonb(r);end loop;return;elsif k in('general_ledger','journal_register') then for r in select * from public.journal_center_list_v500(p_tenant_id,p_from,p_to,p_query,null,p_limit) loop return next to_jsonb(r);end loop;return;elsif k='balance_sheet' then return next public.accounting_balance_sheet_v500(p_tenant_id,p_to,p_location_id);return;elsif k in('trial_balance','profit_loss','cash_flow') then return next public.accounting_statement_v41(p_tenant_id,k,p_from,p_to,p_location_id);return;elsif k='receivables' then for r in select * from public.customer_credit_intelligence_v480(p_tenant_id,p_location_id,p_query,p_limit) loop return next to_jsonb(r);end loop;return;elsif k in('payables','supplier_outstanding') then for r in select * from public.supplier_payables_intelligence_v480(p_tenant_id,p_location_id,p_query,p_limit) loop return next to_jsonb(r);end loop;return;elsif k='reconciliation' then return next public.finance_reconciliation_v500(p_tenant_id);return;elsif k='tax' then return next public.gst_summary_v4(p_tenant_id,p_from,p_to,p_location_id);return;elsif k='expenses' then for r in select e.expense_date,e.expense_number,c.name category,e.payee,e.description,e.amount,e.tax_amount,e.total_amount,e.payment_method,e.reference_number,e.status from public.expenses e join public.expense_categories c on c.id=e.category_id left join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='expense' and o.entity_id=e.id where e.tenant_id=p_tenant_id and e.expense_date between p_from and p_to and e.status='posted' and (p_location_id is null or o.location_id=p_location_id) and (trim(coalesce(p_query,''))='' or lower(e.expense_number) like q or lower(e.description) like q or lower(coalesce(e.payee,'')) like q) order by e.expense_date desc limit greatest(1,least(coalesce(p_limit,1000),5000)) loop return next to_jsonb(r);end loop;return;else raise exception 'Unsupported report key: %',p_report_key;end if;end $$;


--
-- Name: reports_export_dataset_v44(uuid, date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reports_export_dataset_v44(p_tenant_id uuid, p_from date, p_to date, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_summary jsonb;v_sales jsonb;v_purchases jsonb;v_expenses jsonb;v_top_products jsonb;v_top_customers jsonb;v_gst jsonb;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if p_from is null or p_to is null or p_from>p_to then raise exception 'Invalid report date range';end if;
  if p_location_id is not null and not private.erp_user_is_owner(p_tenant_id)
     and not private.erp_has_permission(p_tenant_id,'locations.view_all')
     and not private.erp_user_location_allowed(p_tenant_id,p_location_id,'view') then raise exception 'Location access denied';end if;

  select public.reports_get_summary_v32(p_tenant_id,p_from,p_to,p_location_id) into v_summary;
  select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into v_sales from public.sales_list_v32(p_tenant_id,p_location_id) x where x.sale_date between p_from and p_to;
  select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into v_purchases from public.purchases_list_v32(p_tenant_id,p_location_id) x where x.purchase_date between p_from and p_to;
  select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into v_expenses from public.expenses_list_v32(p_tenant_id,p_location_id,p_from,p_to) x;
  select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into v_top_products from public.analytics_top_products_v4(p_tenant_id,p_from,p_to,p_location_id,100) x;
  select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into v_top_customers from public.analytics_top_customers_v4(p_tenant_id,p_from,p_to,p_location_id,100) x;
  select public.gst_summary_v4(p_tenant_id,p_from,p_to,p_location_id) into v_gst;

  return jsonb_build_object(
    'tenant_id',p_tenant_id,'from',p_from,'to',p_to,'location_id',p_location_id,
    'summary',coalesce(v_summary,'{}'::jsonb),'sales',v_sales,'purchases',v_purchases,
    'expenses',v_expenses,'top_products',v_top_products,'top_customers',v_top_customers,
    'gst',coalesce(v_gst,'{}'::jsonb)
  );
end $$;


--
-- Name: reports_get_summary(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reports_get_summary(p_tenant_id uuid, p_from_date date, p_to_date date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_sales numeric:=0;v_sales_tax numeric:=0;v_purchases numeric:=0;v_purchase_tax numeric:=0;v_expenses numeric:=0;v_gp numeric:=0;
  v_recv numeric:=0;v_pay numeric:=0;v_stock numeric:=0;v_sc int:=0;v_pc int:=0;v_ec int:=0;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  if p_from_date is null or p_to_date is null or p_from_date>p_to_date then raise exception 'Invalid date range'; end if;

  select coalesce(sum(grand_total),0),coalesce(sum(tax_total),0),coalesce(sum(gross_profit),0),count(*) into v_sales,v_sales_tax,v_gp,v_sc
  from public.sales where tenant_id=p_tenant_id and sale_date between p_from_date and p_to_date and coalesce(status,'')<>'cancelled';
  select coalesce(sum(grand_total),0),coalesce(sum(tax_total),0),count(*) into v_purchases,v_purchase_tax,v_pc
  from public.purchases where tenant_id=p_tenant_id and purchase_date between p_from_date and p_to_date and coalesce(status,'')<>'cancelled';
  if to_regclass('public.expenses') is not null then select coalesce(sum(total_amount),0),count(*) into v_expenses,v_ec from public.expenses where tenant_id=p_tenant_id and expense_date between p_from_date and p_to_date and status='posted'; end if;

  select coalesce(sum(greatest(s.grand_total-coalesce(p.paid,0),0)),0) into v_recv from public.sales s left join (select sale_id,sum(amount) paid from public.sale_payments group by sale_id)p on p.sale_id=s.id where s.tenant_id=p_tenant_id and coalesce(s.status,'')<>'cancelled';
  select coalesce(sum(greatest(pu.grand_total-coalesce(py.paid,0),0)),0) into v_pay from public.purchases pu left join (select purchase_id,sum(amount) paid from public.purchase_payments group by purchase_id)py on py.purchase_id=pu.id where pu.tenant_id=p_tenant_id and coalesce(pu.status,'')<>'cancelled';
  select coalesce(sum(sb.quantity*pv.cost_price),0) into v_stock from public.stock_balances sb join public.product_variants pv on pv.id=sb.variant_id where sb.tenant_id=p_tenant_id;

  return jsonb_build_object('from_date',p_from_date,'to_date',p_to_date,'sales',v_sales,'sales_tax',v_sales_tax,'purchases',v_purchases,'purchase_tax',v_purchase_tax,'expenses',v_expenses,'gross_profit',v_gp,'net_profit',v_gp-v_expenses,'receivables',v_recv,'payables',v_pay,'stock_value',v_stock,'sale_count',v_sc,'purchase_count',v_pc,'expense_count',v_ec);
end $$;


--
-- Name: reports_get_summary_v32(uuid, date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reports_get_summary_v32(p_tenant_id uuid, p_from_date date, p_to_date date, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare
  v_sales numeric:=0;v_sales_tax numeric:=0;v_purchases numeric:=0;v_purchase_tax numeric:=0;v_expenses numeric:=0;v_gp numeric:=0;v_recv numeric:=0;v_pay numeric:=0;v_stock numeric:=0;
  v_sc int:=0;v_pc int:=0;v_ec int:=0;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if p_from_date is null or p_to_date is null or p_from_date>p_to_date then raise exception 'Invalid date range';end if;
  select coalesce(sum(s.grand_total),0),coalesce(sum(s.tax_total),0),coalesce(sum(s.gross_profit),0),count(*) into v_sales,v_sales_tax,v_gp,v_sc
  from public.sales s left join public.document_origins o on o.entity_type='sale' and o.entity_id=s.id
  where s.tenant_id=p_tenant_id and s.sale_date between p_from_date and p_to_date and coalesce(s.status,'') not in ('cancelled','void') and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view');
  select coalesce(sum(p.grand_total),0),coalesce(sum(p.tax_total),0),count(*) into v_purchases,v_purchase_tax,v_pc
  from public.purchases p left join public.document_origins o on o.entity_type='purchase' and o.entity_id=p.id
  where p.tenant_id=p_tenant_id and p.purchase_date between p_from_date and p_to_date and coalesce(p.status,'') not in ('cancelled','void') and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view');
  select coalesce(sum(e.total_amount),0),count(*) into v_expenses,v_ec
  from public.expenses e left join public.document_origins o on o.entity_type='expense' and o.entity_id=e.id
  where e.tenant_id=p_tenant_id and e.expense_date between p_from_date and p_to_date and e.status='posted' and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view');
  select coalesce(sum(greatest(s.grand_total-coalesce(py.paid,0),0)),0) into v_recv
  from public.sales s left join (select sale_id,sum(amount) paid from public.sale_payments group by sale_id) py on py.sale_id=s.id
  left join public.document_origins o on o.entity_type='sale' and o.entity_id=s.id
  where s.tenant_id=p_tenant_id and coalesce(s.status,'') not in ('cancelled','void') and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view');
  select coalesce(sum(greatest(p.grand_total-coalesce(py.paid,0),0)),0) into v_pay
  from public.purchases p left join (select purchase_id,sum(amount) paid from public.purchase_payments group by purchase_id) py on py.purchase_id=p.id
  left join public.document_origins o on o.entity_type='purchase' and o.entity_id=p.id
  where p.tenant_id=p_tenant_id and coalesce(p.status,'') not in ('cancelled','void') and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view');
  select coalesce(sum(sb.quantity*pv.cost_price),0) into v_stock from public.stock_balances sb join public.product_variants pv on pv.id=sb.variant_id where sb.tenant_id=p_tenant_id;
  return jsonb_build_object('from_date',p_from_date,'to_date',p_to_date,'sales',v_sales,'sales_tax',v_sales_tax,'purchases',v_purchases,'purchase_tax',v_purchase_tax,'expenses',v_expenses,'gross_profit',v_gp,'net_profit',v_gp-v_expenses,'receivables',v_recv,'payables',v_pay,'stock_value',v_stock,'sale_count',v_sc,'purchase_count',v_pc,'expense_count',v_ec,'location_id',p_location_id,'stock_scope','business');
end $$;


--
-- Name: reports_get_summary_v4(uuid, date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reports_get_summary_v4(p_tenant_id uuid, p_from_date date, p_to_date date, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v jsonb;v_stock numeric:=0;v_sr numeric:=0;v_pr numeric:=0;v_sr_profit numeric:=0;v_recv numeric:=0;v_pay numeric:=0;
begin
  select public.reports_get_summary_v32(p_tenant_id,p_from_date,p_to_date,p_location_id) into v;
  select coalesce(sum(r.grand_total),0),coalesce(sum(r.subtotal-coalesce(c.return_cost,0)),0)
  into v_sr,v_sr_profit
  from public.sales_returns r
  left join (
    select ri.sales_return_id,sum(coalesce(si.cost_total,0)*(ri.quantity/nullif(si.quantity,0))) return_cost
    from public.sales_return_items ri join public.sale_items si on si.id=ri.sale_item_id group by ri.sales_return_id
  ) c on c.sales_return_id=r.id
  where r.tenant_id=p_tenant_id and r.return_date between p_from_date and p_to_date and r.refund_status<>'waived'
    and private.erp_document_scope_allowed(p_tenant_id,r.location_id,p_location_id,'view');
  select coalesce(sum(r.grand_total),0) into v_pr from public.purchase_returns r
  where r.tenant_id=p_tenant_id and r.return_date between p_from_date and p_to_date and r.credit_status<>'waived'
    and private.erp_document_scope_allowed(p_tenant_id,r.location_id,p_location_id,'view');

  select coalesce(sum(greatest(s.grand_total-coalesce(py.paid,0)-coalesce(rt.returned,0),0)),0) into v_recv
  from public.sales s left join (select sale_id,sum(amount) paid from public.sale_payments group by sale_id)py on py.sale_id=s.id
  left join (select sale_id,sum(grand_total) returned from public.sales_returns where refund_status<>'waived' group by sale_id)rt on rt.sale_id=s.id
  left join public.document_origins o on o.entity_type='sale' and o.entity_id=s.id
  where s.tenant_id=p_tenant_id and coalesce(s.status,'') not in('cancelled','void') and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view');
  select coalesce(sum(greatest(p.grand_total-coalesce(py.paid,0)-coalesce(rt.returned,0),0)),0) into v_pay
  from public.purchases p left join (select purchase_id,sum(amount) paid from public.purchase_payments group by purchase_id)py on py.purchase_id=p.id
  left join (select purchase_id,sum(grand_total) returned from public.purchase_returns where credit_status<>'waived' group by purchase_id)rt on rt.purchase_id=p.id
  left join public.document_origins o on o.entity_type='purchase' and o.entity_id=p.id
  where p.tenant_id=p_tenant_id and coalesce(p.status,'') not in('cancelled','void') and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view');

  select coalesce(sum(coalesce(b.quantity,0)*coalesce(nullif(b.average_cost,0),pv.cost_price,0)),0) into v_stock
  from public.location_product_settings s join public.product_variants pv on pv.id=s.variant_id join public.business_locations bl on bl.id=s.location_id and bl.active
  left join public.location_stock_balances b on b.tenant_id=s.tenant_id and b.location_id=s.location_id and b.variant_id=s.variant_id
  where s.tenant_id=p_tenant_id and s.active and (p_location_id is null or s.location_id=p_location_id)
    and private.erp_document_scope_allowed(p_tenant_id,s.location_id,p_location_id,'view');

  return coalesce(v,'{}'::jsonb)||jsonb_build_object(
    'sales',greatest(coalesce((v->>'sales')::numeric,0)-v_sr,0),
    'purchases',greatest(coalesce((v->>'purchases')::numeric,0)-v_pr,0),
    'gross_profit',coalesce((v->>'gross_profit')::numeric,0)-v_sr_profit,
    'net_profit',coalesce((v->>'gross_profit')::numeric,0)-v_sr_profit-coalesce((v->>'expenses')::numeric,0),
    'receivables',v_recv,'payables',v_pay,'stock_value',v_stock,
    'sales_returns',v_sr,'purchase_returns',v_pr,'stock_scope',case when p_location_id is null then 'accessible_locations' else 'location' end
  );
end $$;


--
-- Name: restaurant_kot_send(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurant_kot_send(p_tenant_id uuid, p_order_id uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_order public.restaurant_orders%rowtype;v_id uuid:=gen_random_uuid();v_no text;v_track text;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;if not private.erp_has_permission(p_tenant_id,'restaurant.kot') and not private.erp_has_permission(p_tenant_id,'restaurant.manage') then raise exception 'Permission denied';end if;
  select * into v_order from public.restaurant_orders where id=p_order_id and tenant_id=p_tenant_id for update;if v_order.id is null then raise exception 'Order not found';end if;if v_order.status in ('billed','cancelled') then raise exception 'Order is closed';end if;
  insert into public.restaurant_kots(id,tenant_id,location_id,order_id,kot_number,note) values(v_id,p_tenant_id,v_order.location_id,p_order_id,'',coalesce(nullif(trim(p_note),''),v_order.chef_note)) returning kot_number,tracking_code into v_no,v_track;
  update public.restaurant_orders set status='sent_to_kitchen',kitchen_sent_at=coalesce(kitchen_sent_at,now()),updated_at=now() where id=p_order_id;
  return jsonb_build_object('kot_id',v_id,'kot_number',v_no,'tracking_code',v_track);
end $$;


--
-- Name: restaurant_kot_send_v32(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurant_kot_send_v32(p_tenant_id uuid, p_order_id uuid, p_device_id uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_location uuid;
begin
  select location_id into v_location from public.restaurant_orders where id=p_order_id and tenant_id=p_tenant_id;
  if v_location is null then raise exception 'Order not found';end if;
  perform private.erp_validate_vertical_device_scope(p_tenant_id,v_location,p_device_id,'restaurant','operate');
  return public.restaurant_kot_send(p_tenant_id,p_order_id,p_note);
end $$;


--
-- Name: restaurant_operations_summary_v489(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurant_operations_summary_v489(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_device_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_tables bigint:=0;v_occupied bigint:=0;v_open bigint:=0;v_queue bigint:=0;v_preparing bigint:=0;v_ready bigint:=0;v_sales numeric:=0;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if p_device_id is not null and p_location_id is not null then
    perform private.erp_validate_vertical_device_scope(p_tenant_id,p_location_id,p_device_id,'restaurant','view');
  end if;
  select count(*) into v_tables from public.restaurant_tables t
   where t.tenant_id=p_tenant_id and t.active
     and (p_location_id is null or t.location_id=p_location_id)
     and private.erp_document_scope_allowed(p_tenant_id,t.location_id,p_location_id,'view');
  select count(distinct r.table_id),count(*)
    into v_occupied,v_open
    from public.restaurant_orders r
   where r.tenant_id=p_tenant_id and r.status not in('billed','cancelled')
     and (p_location_id is null or r.location_id=p_location_id)
     and private.erp_document_scope_allowed(p_tenant_id,r.location_id,p_location_id,'view');
  select count(*) filter(where k.status='queued'),count(*) filter(where k.status='preparing'),count(*) filter(where k.status='ready')
    into v_queue,v_preparing,v_ready
    from public.restaurant_kots k
   where k.tenant_id=p_tenant_id and k.status not in('served','cancelled')
     and (p_location_id is null or k.location_id=p_location_id)
     and private.erp_document_scope_allowed(p_tenant_id,k.location_id,p_location_id,'view');
  select coalesce(sum(s.grand_total),0) into v_sales
    from public.restaurant_orders r join public.sales s on s.id=r.sale_id and s.tenant_id=r.tenant_id
   where r.tenant_id=p_tenant_id and r.status='billed' and s.sale_date=current_date
     and (p_location_id is null or r.location_id=p_location_id)
     and private.erp_document_scope_allowed(p_tenant_id,r.location_id,p_location_id,'view');
  return jsonb_build_object(
    'tables',v_tables,'occupied_tables',v_occupied,'available_tables',greatest(v_tables-v_occupied,0),
    'open_orders',v_open,'kot_queued',v_queue,'kot_preparing',v_preparing,'kot_ready',v_ready,
    'restaurant_sales_today',round(v_sales,2)
  );
end $$;


--
-- Name: restaurant_order_bill_v489(uuid, uuid, uuid, uuid, date, numeric, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurant_order_bill_v489(p_tenant_id uuid, p_order_id uuid, p_device_id uuid, p_customer_id uuid, p_due_date date, p_initial_payment numeric, p_payment_method text, p_payment_reference text, p_round_off numeric DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  o public.restaurant_orders%rowtype;v_customer uuid;v_items jsonb;v_sale jsonb;v_sale_id uuid;v_existing jsonb;
  v_total numeric;v_method text;
begin
  select * into o from public.restaurant_orders
  where id=p_order_id and tenant_id=p_tenant_id for update;
  if o.id is null then raise exception 'Restaurant order not found';end if;
  perform private.erp_validate_vertical_device_scope(p_tenant_id,o.location_id,p_device_id,'restaurant','operate');
  if not private.erp_user_is_owner(p_tenant_id)
     and not private.erp_has_permission(p_tenant_id,'restaurant.order')
     and not private.erp_has_permission(p_tenant_id,'restaurant.manage') then
    raise exception 'Restaurant billing permission denied';
  end if;
  if o.status='cancelled' then raise exception 'Cancelled restaurant order cannot be billed';end if;
  if o.status='billed' and o.sale_id is not null then
    select jsonb_build_object('success',true,'idempotent',true,'order_id',o.id,'sale_id',s.id,
      'sale_number',s.sale_number,'grand_total',s.grand_total,'round_off',coalesce(s.round_off,0))
      into v_existing from public.sales s where s.id=o.sale_id and s.tenant_id=p_tenant_id;
    if v_existing is not null then return v_existing;end if;
  end if;
  v_customer:=coalesce(o.customer_id,p_customer_id);
  if v_customer is null or not exists(
    select 1 from public.customers c where c.id=v_customer and c.tenant_id=p_tenant_id and coalesce(c.status,'active')='active'
  ) then raise exception 'Choose an active customer before billing';end if;
  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
      'variant_id',i.variant_id,'quantity',i.quantity,'unit_id',i.unit_id,
      'unit_price',i.unit_price,'discount_amount',i.discount_amount,'tax_rate',i.tax_rate
    )) order by i.created_at,i.id),'[]'::jsonb)
    into v_items from public.restaurant_order_items i where i.order_id=o.id and i.tenant_id=p_tenant_id;
  if jsonb_array_length(v_items)=0 then raise exception 'Restaurant order has no items';end if;
  v_method:=coalesce(nullif(lower(trim(p_payment_method)),''),'cash');
  -- Create the sale without a payment first. This lets the authoritative pricing engine
  -- determine the exact current total; non-credit restaurant bills are then settled for
  -- that server total in the same transaction, so a changed price cannot strand billing.
  v_sale:=public.sales_create_v489(
    p_tenant_id,v_customer,current_date,p_due_date,v_items,0,coalesce(p_round_off,0),
    0,v_method,coalesce(p_payment_reference,''),'Restaurant '||o.order_number,o.location_id,p_device_id,
    'restaurant-bill:'||o.id::text
  );
  v_sale_id:=nullif(v_sale->>'sale_id','')::uuid;
  if v_sale_id is null then raise exception 'Restaurant sale was not created';end if;
  v_total:=coalesce(nullif(v_sale->>'grand_total','')::numeric,0);
  if v_method<>'credit' and v_total>0.005 then
    perform public.sales_add_payment_v47(
      p_tenant_id,v_sale_id,v_total,v_method,coalesce(p_payment_reference,''),
      'Restaurant settlement '||o.order_number,'restaurant-payment:'||o.id::text
    );
    v_sale:=v_sale||jsonb_build_object('paid_total',v_total,'balance_due',0);
  end if;
  update public.restaurant_orders set status='billed',sale_id=v_sale_id,billed_at=coalesce(billed_at,now()),updated_at=now()
   where id=o.id and tenant_id=p_tenant_id;
  update public.restaurant_kots set status='served',served_at=coalesce(served_at,now())
   where tenant_id=p_tenant_id and order_id=o.id and status not in('served','cancelled');
  perform private.thq_sync_bump_v480(p_tenant_id,'transactions','restaurant_order',o.id::text,'bill');
  return coalesce(v_sale,'{}'::jsonb)||jsonb_build_object('success',true,'order_id',o.id,'restaurant_billing','v4.8.9');
end $$;


--
-- Name: restaurant_order_create(uuid, uuid, uuid, text, uuid, uuid, integer, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurant_order_create(p_tenant_id uuid, p_location_id uuid, p_device_id uuid, p_order_type text, p_table_id uuid, p_customer_id uuid, p_preparation_minutes integer, p_chef_note text, p_delivery_address text, p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_id uuid:=gen_random_uuid();v_order text;v_track text;x jsonb;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if not private.erp_has_permission(p_tenant_id,'restaurant.order') and not private.erp_has_permission(p_tenant_id,'restaurant.manage') then raise exception 'Permission denied';end if;
  if p_order_type not in ('dine_in','takeaway','delivery') then raise exception 'Invalid order type';end if;
  if p_order_type='dine_in' and p_table_id is null then raise exception 'Choose a table';end if;
  if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'Add at least one item';end if;
  insert into public.restaurant_orders(id,tenant_id,location_id,device_id,order_number,order_type,table_id,customer_id,preparation_minutes,chef_note,delivery_address,created_by)
  values(v_id,p_tenant_id,p_location_id,p_device_id,'',p_order_type,p_table_id,p_customer_id,greatest(coalesce(p_preparation_minutes,15),0),nullif(trim(p_chef_note),''),nullif(trim(p_delivery_address),''),auth.uid()) returning order_number,tracking_code into v_order,v_track;
  for x in select * from jsonb_array_elements(p_items) loop
    insert into public.restaurant_order_items(order_id,tenant_id,variant_id,quantity,unit_price,discount_amount,tax_rate,item_note)
    values(v_id,p_tenant_id,(x->>'variant_id')::uuid,(x->>'quantity')::numeric,coalesce(nullif(x->>'unit_price','')::numeric,0),coalesce(nullif(x->>'discount_amount','')::numeric,0),coalesce(nullif(x->>'tax_rate','')::numeric,0),nullif(trim(x->>'item_note'),''));
  end loop;
  insert into public.document_origins(tenant_id,entity_type,entity_id,location_id,device_id,created_by) values(p_tenant_id,'restaurant_order',v_id,p_location_id,p_device_id,auth.uid()) on conflict do nothing;
  return jsonb_build_object('order_id',v_id,'order_number',v_order,'tracking_code',v_track);
end $$;


--
-- Name: restaurant_order_create_v32(uuid, uuid, uuid, text, uuid, uuid, integer, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurant_order_create_v32(p_tenant_id uuid, p_location_id uuid, p_device_id uuid, p_order_type text, p_table_id uuid, p_customer_id uuid, p_preparation_minutes integer, p_chef_note text, p_delivery_address text, p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_id uuid:=gen_random_uuid();
  v_order text;v_track text;
  x jsonb;v_priced jsonb;v_norm jsonb;
  v_variant uuid;v_unit uuid;v_qty numeric;v_factor numeric;v_unit_price numeric;v_tax numeric;
  v_discount numeric;v_source text;v_price_list uuid;v_price_name text;
begin
  perform private.erp_validate_vertical_device_scope(p_tenant_id,p_location_id,p_device_id,'restaurant','operate');
  if not private.erp_user_is_owner(p_tenant_id)
     and not private.erp_has_permission(p_tenant_id,'restaurant.order')
     and not private.erp_has_permission(p_tenant_id,'restaurant.manage') then
    raise exception 'Restaurant order permission denied';
  end if;
  if p_order_type not in ('dine_in','takeaway','delivery') then raise exception 'Invalid order type';end if;
  if p_order_type='dine_in' and p_table_id is null then raise exception 'Choose a table';end if;
  if p_table_id is not null and not exists(
    select 1 from public.restaurant_tables t
    where t.id=p_table_id and t.tenant_id=p_tenant_id and t.location_id=p_location_id and t.active
  ) then raise exception 'Choose a table from this store';end if;
  if p_customer_id is not null and not exists(
    select 1 from public.customers c where c.id=p_customer_id and c.tenant_id=p_tenant_id and coalesce(c.status,'active')='active'
  ) then raise exception 'Customer is not available';end if;
  if jsonb_typeof(coalesce(p_items,'[]'::jsonb))<>'array' or jsonb_array_length(coalesce(p_items,'[]'::jsonb))=0 then
    raise exception 'Add at least one item';
  end if;

  v_priced:=private.v482_price_sale_items(p_tenant_id,p_customer_id,p_items,p_location_id);

  insert into public.restaurant_orders(
    id,tenant_id,location_id,device_id,order_number,order_type,table_id,customer_id,
    preparation_minutes,chef_note,delivery_address,created_by
  ) values(
    v_id,p_tenant_id,p_location_id,p_device_id,'',p_order_type,p_table_id,p_customer_id,
    greatest(coalesce(p_preparation_minutes,15),0),nullif(trim(p_chef_note),''),nullif(trim(p_delivery_address),''),auth.uid()
  ) returning order_number,tracking_code into v_order,v_track;

  for x in select value from jsonb_array_elements(v_priced) loop
    v_norm:=private.v481_normalize_line(p_tenant_id,x,'sale');
    v_variant:=nullif(x->>'variant_id','')::uuid;
    v_unit:=nullif(v_norm->>'_entered_unit_id','')::uuid;
    v_qty:=coalesce(nullif(v_norm->>'_entered_quantity','')::numeric,0);
    v_factor:=coalesce(nullif(v_norm->>'_conversion_to_base','')::numeric,1);
    v_unit_price:=coalesce(nullif(v_norm->>'_entered_unit_price','')::numeric,0);
    v_discount:=greatest(coalesce(nullif(x->>'discount_amount','')::numeric,0),0);
    v_source:=nullif(x->>'_pricing_source','');
    v_price_list:=nullif(x->>'_price_list_id','')::uuid;
    v_price_name:=nullif(x->>'_price_list_name','');

    -- Operational compatibility only.  GST v5.2 never treats this order-time
    -- tax_rate as authoritative; final tax comes from the immutable GST quote.
    select coalesce(p.tax_rate,0) into v_tax
    from public.product_variants pv
    join public.products p on p.id=pv.product_id and p.tenant_id=pv.tenant_id
    where pv.id=v_variant and pv.tenant_id=p_tenant_id;
    if not found then raise exception 'Product is not available for this business';end if;
    if v_discount > v_qty*v_unit_price then raise exception 'Restaurant item discount exceeds line value';end if;

    insert into public.restaurant_order_items(
      order_id,tenant_id,variant_id,quantity,unit_id,conversion_to_base,unit_price,
      discount_amount,tax_rate,item_note,pricing_source,price_list_id,pricing_metadata
    ) values(
      v_id,p_tenant_id,v_variant,v_qty,v_unit,v_factor,v_unit_price,
      v_discount,v_tax,nullif(trim(x->>'item_note'),''),coalesce(v_source,'product_price'),v_price_list,
      jsonb_strip_nulls(jsonb_build_object('price_list_name',v_price_name,'resolved_at',now(),'engine','v4.8.2'))
    );
  end loop;

  insert into public.document_origins(tenant_id,entity_type,entity_id,location_id,device_id,created_by)
  values(p_tenant_id,'restaurant_order',v_id,p_location_id,p_device_id,auth.uid())
  on conflict do nothing;
  perform private.thq_sync_bump_v480(p_tenant_id,'transactions','restaurant_order',v_id::text,'create');
  return jsonb_build_object('order_id',v_id,'order_number',v_order,'tracking_code',v_track,'pricing_engine','v4.8.2','restaurant_engine','v4.8.9');
end
$$;


--
-- Name: restaurant_order_detail(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurant_order_detail(p_tenant_id uuid, p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v jsonb;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  select jsonb_build_object(
    'order',to_jsonb(o),
    'items',coalesce((select jsonb_agg(to_jsonb(i) order by i.created_at) from public.restaurant_order_items i where i.order_id=o.id),'[]'::jsonb),
    'kots',coalesce((select jsonb_agg(to_jsonb(k) order by k.sent_at) from public.restaurant_kots k where k.order_id=o.id),'[]'::jsonb)
  ) into v from public.restaurant_orders o where o.id=p_order_id and o.tenant_id=p_tenant_id;
  if v is null then raise exception 'Order not found';end if;return v;
end $$;


--
-- Name: restaurant_order_detail_v32(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurant_order_detail_v32(p_tenant_id uuid, p_order_id uuid, p_device_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_location uuid;
begin
  select location_id into v_location from public.restaurant_orders where id=p_order_id and tenant_id=p_tenant_id;
  if v_location is null then raise exception 'Order not found';end if;
  perform private.erp_validate_vertical_device_scope(p_tenant_id,v_location,p_device_id,'restaurant','view');
  return public.restaurant_order_detail(p_tenant_id,p_order_id);
end $$;


--
-- Name: restaurant_order_mark_billed(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurant_order_mark_billed(p_tenant_id uuid, p_order_id uuid, p_sale_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;if not private.erp_has_permission(p_tenant_id,'restaurant.order') and not private.erp_has_permission(p_tenant_id,'restaurant.manage') then raise exception 'Permission denied';end if;
  if not exists(select 1 from public.sales where id=p_sale_id and tenant_id=p_tenant_id) then raise exception 'Sale not found';end if;
  update public.restaurant_orders set status='billed',sale_id=p_sale_id,billed_at=now(),updated_at=now() where id=p_order_id and tenant_id=p_tenant_id and status<>'cancelled';
  if not found then raise exception 'Order not found';end if;
end $$;


--
-- Name: restaurant_order_mark_billed_by_reference(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurant_order_mark_billed_by_reference(p_tenant_id uuid, p_order_id uuid, p_sale_number text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_sale_id uuid;begin
  select id into v_sale_id from public.sales where tenant_id=p_tenant_id and sale_number=p_sale_number;
  if v_sale_id is null then raise exception 'Sale not found';end if;
  perform public.restaurant_order_mark_billed(p_tenant_id,p_order_id,v_sale_id);
end $$;


--
-- Name: restaurant_order_mark_billed_by_reference_v32(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurant_order_mark_billed_by_reference_v32(p_tenant_id uuid, p_order_id uuid, p_device_id uuid, p_sale_number text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_location uuid;
  v_sale_id uuid;
  v_sale_location uuid;
begin
  select location_id into v_location from public.restaurant_orders where id=p_order_id and tenant_id=p_tenant_id;
  if v_location is null then raise exception 'Order not found';end if;
  perform private.erp_validate_vertical_device_scope(p_tenant_id,v_location,p_device_id,'restaurant','operate');
  select s.id,o.location_id into v_sale_id,v_sale_location
  from public.sales s left join public.document_origins o on o.entity_type='sale' and o.entity_id=s.id
  where s.tenant_id=p_tenant_id and s.sale_number=p_sale_number;
  if v_sale_id is null then raise exception 'Sale not found';end if;
  if v_sale_location is not null and v_sale_location is distinct from v_location then
    raise exception 'Restaurant order and sale must belong to the same store';
  end if;
  if v_sale_location is null and not private.erp_user_is_owner(p_tenant_id) then
    raise exception 'Legacy sale has no store origin';
  end if;
  perform public.restaurant_order_mark_billed(p_tenant_id,p_order_id,v_sale_id);
end $$;


--
-- Name: restaurant_order_set_status(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurant_order_set_status(p_tenant_id uuid, p_order_id uuid, p_status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;if not private.erp_has_permission(p_tenant_id,'restaurant.kot') and not private.erp_has_permission(p_tenant_id,'restaurant.manage') then raise exception 'Permission denied';end if;
  if p_status not in ('preparing','ready','served','cancelled') then raise exception 'Invalid status';end if;
  update public.restaurant_orders set status=p_status,ready_at=case when p_status='ready' then now() else ready_at end,served_at=case when p_status='served' then now() else served_at end,updated_at=now() where id=p_order_id and tenant_id=p_tenant_id and status not in ('billed','cancelled');
  if not found then raise exception 'Order not found or closed';end if;
  update public.restaurant_kots set status=case when p_status='preparing' then 'preparing' when p_status='ready' then 'ready' when p_status='served' then 'served' when p_status='cancelled' then 'cancelled' else status end,started_at=case when p_status='preparing' then coalesce(started_at,now()) else started_at end,ready_at=case when p_status='ready' then coalesce(ready_at,now()) else ready_at end,served_at=case when p_status='served' then coalesce(served_at,now()) else served_at end where order_id=p_order_id and status not in ('served','cancelled');
end $$;


--
-- Name: restaurant_order_set_status_v32(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurant_order_set_status_v32(p_tenant_id uuid, p_order_id uuid, p_device_id uuid, p_status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_location uuid;
begin
  select location_id into v_location from public.restaurant_orders where id=p_order_id and tenant_id=p_tenant_id;
  if v_location is null then raise exception 'Order not found';end if;
  perform private.erp_validate_vertical_device_scope(p_tenant_id,v_location,p_device_id,'restaurant','operate');
  perform public.restaurant_order_set_status(p_tenant_id,p_order_id,p_status);
end $$;


--
-- Name: restaurant_orders_list(uuid, uuid, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurant_orders_list(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_live_only boolean DEFAULT true, p_limit integer DEFAULT 200) RETURNS TABLE(id uuid, tracking_code text, order_number text, order_type text, table_id uuid, table_name text, customer_id uuid, customer_name text, status text, preparation_minutes integer, chef_note text, delivery_address text, opened_at timestamp with time zone, kitchen_sent_at timestamp with time zone, ready_at timestamp with time zone, sale_id uuid, total numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  return query select o.id,o.tracking_code,o.order_number,o.order_type,o.table_id,t.name,o.customer_id,c.name,o.status,o.preparation_minutes,o.chef_note,o.delivery_address,o.opened_at,o.kitchen_sent_at,o.ready_at,o.sale_id,
    coalesce((select sum(greatest(i.quantity*i.unit_price-i.discount_amount,0)*(1+i.tax_rate/100)) from public.restaurant_order_items i where i.order_id=o.id),0)::numeric
  from public.restaurant_orders o left join public.restaurant_tables t on t.id=o.table_id left join public.customers c on c.id=o.customer_id
  where o.tenant_id=p_tenant_id and (p_location_id is null or o.location_id=p_location_id) and (not p_live_only or o.status not in ('billed','cancelled'))
  order by o.opened_at desc limit greatest(1,least(coalesce(p_limit,200),1000));
end $$;


--
-- Name: restaurant_orders_list_v32(uuid, uuid, uuid, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurant_orders_list_v32(p_tenant_id uuid, p_location_id uuid, p_device_id uuid, p_live_only boolean DEFAULT true, p_limit integer DEFAULT 200) RETURNS TABLE(id uuid, tracking_code text, order_number text, order_type text, table_id uuid, table_name text, customer_id uuid, customer_name text, status text, preparation_minutes integer, chef_note text, delivery_address text, opened_at timestamp with time zone, kitchen_sent_at timestamp with time zone, ready_at timestamp with time zone, sale_id uuid, total numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  perform private.erp_validate_vertical_device_scope(p_tenant_id,p_location_id,p_device_id,'restaurant','view');
  if not (private.erp_user_is_owner(p_tenant_id)
          or private.erp_has_permission(p_tenant_id,'restaurant.view')
          or private.erp_has_permission(p_tenant_id,'restaurant.order')
          or private.erp_has_permission(p_tenant_id,'restaurant.kot')
          or private.erp_has_permission(p_tenant_id,'restaurant.manage')) then
    raise exception 'Permission denied';
  end if;
  return query
  select o.id,o.tracking_code,o.order_number,o.order_type,o.table_id,t.name,o.customer_id,c.name,
         o.status,o.preparation_minutes,o.chef_note,o.delivery_address,o.opened_at,o.kitchen_sent_at,
         o.ready_at,o.sale_id,
         coalesce((select sum(greatest(i.quantity*i.unit_price-i.discount_amount,0)*(1+i.tax_rate/100))
                   from public.restaurant_order_items i where i.order_id=o.id),0)::numeric
  from public.restaurant_orders o
  left join public.restaurant_tables t on t.id=o.table_id
  left join public.customers c on c.id=o.customer_id
  where o.tenant_id=p_tenant_id
    and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view')
    and (not p_live_only or o.status not in ('billed','cancelled'))
  order by o.opened_at desc
  limit greatest(1,least(coalesce(p_limit,200),1000));
end $$;


--
-- Name: restaurant_table_save(uuid, uuid, uuid, text, text, integer, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurant_table_save(p_tenant_id uuid, p_table_id uuid, p_location_id uuid, p_table_code text, p_name text, p_capacity integer, p_area text, p_active boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_id uuid;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;if not private.erp_has_permission(p_tenant_id,'restaurant.manage') then raise exception 'Permission denied'; end if;
  if p_table_id is null then insert into public.restaurant_tables(tenant_id,location_id,table_code,name,capacity,area,active) values(p_tenant_id,p_location_id,upper(trim(p_table_code)),trim(p_name),greatest(coalesce(p_capacity,4),1),nullif(trim(p_area),''),coalesce(p_active,true)) returning id into v_id;
  else update public.restaurant_tables set location_id=p_location_id,table_code=upper(trim(p_table_code)),name=trim(p_name),capacity=greatest(coalesce(p_capacity,4),1),area=nullif(trim(p_area),''),active=coalesce(p_active,true),updated_at=now() where id=p_table_id and tenant_id=p_tenant_id returning id into v_id;end if;
  if v_id is null then raise exception 'Table not found';end if;return v_id;
end $$;


--
-- Name: restaurant_table_save_v32(uuid, uuid, uuid, uuid, text, text, integer, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurant_table_save_v32(p_tenant_id uuid, p_table_id uuid, p_location_id uuid, p_device_id uuid, p_table_code text, p_name text, p_capacity integer, p_area text, p_active boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_old_location uuid;
begin
  perform private.erp_validate_vertical_device_scope(p_tenant_id,p_location_id,p_device_id,'restaurant','operate');
  if not private.erp_has_permission(p_tenant_id,'restaurant.manage') and not private.erp_user_is_owner(p_tenant_id) then
    raise exception 'Permission denied';
  end if;
  if p_table_id is not null then
    select location_id into v_old_location from public.restaurant_tables where id=p_table_id and tenant_id=p_tenant_id;
    if v_old_location is null then raise exception 'Table not found';end if;
    if not private.erp_document_scope_allowed(p_tenant_id,v_old_location,v_old_location,'operate') then
      raise exception 'You cannot edit this table';
    end if;
  end if;
  return public.restaurant_table_save(p_tenant_id,p_table_id,p_location_id,p_table_code,p_name,p_capacity,p_area,p_active);
end $$;


--
-- Name: restaurant_tables; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.restaurant_tables (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    location_id uuid,
    tracking_code text,
    table_code text NOT NULL,
    name text NOT NULL,
    capacity integer DEFAULT 4 NOT NULL,
    area text,
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT restaurant_tables_capacity_check CHECK ((capacity > 0))
);


--
-- Name: restaurant_tables_list(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurant_tables_list(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid) RETURNS SETOF public.restaurant_tables
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  return query select * from public.restaurant_tables where tenant_id=p_tenant_id and (p_location_id is null or location_id=p_location_id) order by area nulls first,table_code;
end $$;


--
-- Name: restaurant_tables_list_v32(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurant_tables_list_v32(p_tenant_id uuid, p_location_id uuid, p_device_id uuid) RETURNS SETOF public.restaurant_tables
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  perform private.erp_validate_vertical_device_scope(p_tenant_id,p_location_id,p_device_id,'restaurant','view');
  if not (private.erp_user_is_owner(p_tenant_id)
          or private.erp_has_permission(p_tenant_id,'restaurant.view')
          or private.erp_has_permission(p_tenant_id,'restaurant.order')
          or private.erp_has_permission(p_tenant_id,'restaurant.kot')
          or private.erp_has_permission(p_tenant_id,'restaurant.manage')) then
    raise exception 'Permission denied';
  end if;
  return query
  select t.* from public.restaurant_tables t
  where t.tenant_id=p_tenant_id
    and private.erp_document_scope_allowed(p_tenant_id,t.location_id,p_location_id,'view')
  order by t.area nulls first,t.table_code;
end $$;


--
-- Name: return_documents_search_v45(uuid, uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.return_documents_search_v45(p_tenant_id uuid, p_location_id uuid, p_type text DEFAULT 'all'::text, p_query text DEFAULT ''::text, p_limit integer DEFAULT 200) RETURNS TABLE(entity_type text, entity_id uuid, document_number text, document_date date, party text, grand_total numeric, status text, return_status text, location_id uuid, device_id uuid, matched_product text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  q text := '%' || lower(trim(coalesce(p_query,''))) || '%';
  lim integer := greatest(1,least(coalesce(p_limit,200),500));
begin
  if p_type not in('all','sale','purchase') then raise exception 'Invalid return search type'; end if;
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  if p_location_id is null then raise exception 'POS return search requires a store/location'; end if;
  perform private.v4_location_access(p_tenant_id,p_location_id,'view');

  return query
  select z.entity_type,z.entity_id,z.document_number,z.document_date,z.party,z.grand_total,z.status,z.return_status,z.location_id,z.device_id,z.matched_product
  from (
    select
      'sale'::text as entity_type,
      s.id as entity_id,
      s.sale_number::text as document_number,
      s.sale_date as document_date,
      c.name::text as party,
      s.grand_total,
      s.status::text as status,
      coalesce(public.transaction_return_status_v45(p_tenant_id,'sale',s.id)->>'status','not_returned') as return_status,
      o.location_id,
      o.device_id,
      (
        select concat_ws(' • ',pr.name,pv.sku,nullif(pv.barcode,''),nullif(pv.part_number,''))
        from public.sale_items si
        join public.product_variants pv on pv.id=si.variant_id
        join public.products pr on pr.id=pv.product_id
        where si.sale_id=s.id
          and (
            trim(coalesce(p_query,''))='' or lower(pr.name) like q or lower(coalesce(pv.sku,'')) like q or
            lower(coalesce(pv.barcode,'')) like q or lower(coalesce(pv.part_number,'')) like q
          )
        order by si.id
        limit 1
      )::text as matched_product
    from public.sales s
    join public.customers c on c.id=s.customer_id
    join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='sale' and o.entity_id=s.id
    where p_type in('all','sale')
      and s.tenant_id=p_tenant_id
      and o.location_id=p_location_id
      and coalesce(s.status,'') not in('void','cancelled')
      and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view')
      and (
        trim(coalesce(p_query,''))='' or
        lower(coalesce(s.sale_number,'')) like q or lower(coalesce(c.name,'')) like q or
        exists(
          select 1 from public.sale_items si
          join public.product_variants pv on pv.id=si.variant_id
          join public.products pr on pr.id=pv.product_id
          where si.sale_id=s.id and (
            lower(pr.name) like q or lower(coalesce(pv.sku,'')) like q or
            lower(coalesce(pv.barcode,'')) like q or lower(coalesce(pv.part_number,'')) like q
          )
        )
      )

    union all

    select
      'purchase'::text,
      p.id,
      p.purchase_number::text,
      p.purchase_date,
      sp.name::text,
      p.grand_total,
      p.status::text,
      coalesce(public.transaction_return_status_v45(p_tenant_id,'purchase',p.id)->>'status','not_returned'),
      o.location_id,
      o.device_id,
      (
        select concat_ws(' • ',pr.name,pv.sku,nullif(pv.barcode,''),nullif(pv.part_number,''))
        from public.purchase_items pi
        join public.product_variants pv on pv.id=pi.variant_id
        join public.products pr on pr.id=pv.product_id
        where pi.purchase_id=p.id
          and (
            trim(coalesce(p_query,''))='' or lower(pr.name) like q or lower(coalesce(pv.sku,'')) like q or
            lower(coalesce(pv.barcode,'')) like q or lower(coalesce(pv.part_number,'')) like q
          )
        order by pi.id
        limit 1
      )::text
    from public.purchases p
    join public.suppliers sp on sp.id=p.supplier_id
    join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='purchase' and o.entity_id=p.id
    where p_type in('all','purchase')
      and p.tenant_id=p_tenant_id
      and o.location_id=p_location_id
      and coalesce(p.status,'') not in('void','cancelled')
      and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view')
      and (
        trim(coalesce(p_query,''))='' or
        lower(coalesce(p.purchase_number,'')) like q or
        lower(coalesce(p.supplier_invoice_number,'')) like q or
        lower(coalesce(sp.name,'')) like q or
        exists(
          select 1 from public.purchase_items pi
          join public.product_variants pv on pv.id=pi.variant_id
          join public.products pr on pr.id=pv.product_id
          where pi.purchase_id=p.id and (
            lower(pr.name) like q or lower(coalesce(pv.sku,'')) like q or
            lower(coalesce(pv.barcode,'')) like q or lower(coalesce(pv.part_number,'')) like q
          )
        )
      )
  ) z
  order by z.document_date desc,z.document_number desc
  limit lim;
end $$;


--
-- Name: returns_register_v45(uuid, date, date, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.returns_register_v45(p_tenant_id uuid, p_from date, p_to date, p_location_id uuid DEFAULT NULL::uuid, p_type text DEFAULT 'all'::text, p_query text DEFAULT NULL::text) RETURNS TABLE(return_type text, return_id uuid, return_number text, return_date date, reference text, party text, grand_total numeric, status text, location_id uuid, location_name text, device_id uuid, device_name text, reason text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare q text:='%'||lower(trim(coalesce(p_query,'')))||'%';begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  return query select * from (
    select 'sale_return'::text,r.id,r.return_number,r.return_date,s.sale_number,c.name,r.grand_total,r.refund_status,r.location_id,l.name,r.device_id,d.name,r.reason,r.created_at
    from public.sales_returns r join public.sales s on s.id=r.sale_id join public.customers c on c.id=s.customer_id join public.business_locations l on l.id=r.location_id left join public.business_devices d on d.id=r.device_id
    where r.tenant_id=p_tenant_id and r.return_date between p_from and p_to and private.erp_document_scope_allowed(p_tenant_id,r.location_id,p_location_id,'view') and p_type in('all','sale') and (trim(coalesce(p_query,''))='' or lower(r.return_number) like q or lower(s.sale_number) like q or lower(c.name) like q)
    union all
    select 'purchase_return',r.id,r.return_number,r.return_date,p.purchase_number,sp.name,r.grand_total,r.credit_status,r.location_id,l.name,r.device_id,d.name,r.reason,r.created_at
    from public.purchase_returns r join public.purchases p on p.id=r.purchase_id join public.suppliers sp on sp.id=p.supplier_id join public.business_locations l on l.id=r.location_id left join public.business_devices d on d.id=r.device_id
    where r.tenant_id=p_tenant_id and r.return_date between p_from and p_to and private.erp_document_scope_allowed(p_tenant_id,r.location_id,p_location_id,'view') and p_type in('all','purchase') and (trim(coalesce(p_query,''))='' or lower(r.return_number) like q or lower(p.purchase_number) like q or lower(sp.name) like q)
  ) z order by z.created_at desc;
end $$;


--
-- Name: returns_report_v500(uuid, text, date, date, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.returns_report_v500(p_tenant_id uuid, p_kind text DEFAULT 'all'::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_location_id uuid DEFAULT NULL::uuid, p_query text DEFAULT ''::text, p_limit integer DEFAULT 5000) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare r record;q text:='%'||lower(trim(coalesce(p_query,'')))||'%';begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if lower(coalesce(p_kind,'all')) not in('all','sales','purchase') then raise exception 'Invalid return type';end if;
  for r in
    with rows as (
      select
        'sales'::text return_side,sr.id return_id,sr.return_number::text return_number,sr.return_date return_date,
        s.id source_id,coalesce(dn.terminal_number,ln.local_number,s.sale_number)::text source_number,
        c.id party_id,c.name::text party_name,'customer'::text party_type,
        sri.variant_id,p.name::text product_name,pv.sku::text sku,pv.barcode::text barcode,pv.part_number::text part_number,
        pia.hsn_sac::text hsn_sac,coalesce(pia.unit_code,'')::text unit_code,
        sri.quantity::numeric quantity,sri.unit_price::numeric unit_rate,sri.discount_amount::numeric discount_amount,sri.tax_rate::numeric tax_rate,
        round(greatest(sri.line_total-((sri.unit_price*sri.quantity)-sri.discount_amount),0),2)::numeric tax_amount,
        round((sri.unit_price*sri.quantity)-sri.discount_amount,2)::numeric taxable_amount,sri.line_total::numeric line_total,
        sr.subtotal::numeric document_subtotal,sr.tax_total::numeric document_tax,sr.grand_total::numeric document_total,
        sr.reason::text reason,sr.refund_status::text settlement_status,
        sr.location_id,bl.location_code::text location_code,bl.name::text location_name,sr.created_by,sr.created_at,
        (select j.id from public.journal_entries j where j.tenant_id=p_tenant_id and j.source_type='sales_return' and j.source_id=sr.id and j.status='posted' limit 1) accounting_journal_id,
        'inventory_in / cogs_reversal / output_tax_reversal / customer_credit_or_ar'::text accounting_effect
      from public.sales_returns sr
      join public.sales_return_items sri on sri.sales_return_id=sr.id
      join public.sales s on s.id=sr.sale_id
      join public.customers c on c.id=s.customer_id
      join public.product_variants pv on pv.id=sri.variant_id
      join public.products p on p.id=pv.product_id
      left join public.product_invoice_attributes_v45 pia on pia.tenant_id=sr.tenant_id and pia.variant_id=sri.variant_id
      left join public.business_locations bl on bl.id=sr.location_id
      left join public.location_document_numbers ln on ln.entity_type='sale' and ln.entity_id=s.id
      left join public.device_document_numbers dn on dn.entity_type='sale' and dn.entity_id=s.id
      where sr.tenant_id=p_tenant_id and sr.refund_status<>'waived'
        and (p_from is null or sr.return_date>=p_from) and (p_to is null or sr.return_date<=p_to)
        and (p_location_id is null or sr.location_id=p_location_id)
      union all
      select
        'purchase'::text,pr.id,pr.return_number::text,pr.return_date,
        pch.id,coalesce(dn.terminal_number,ln.local_number,pch.purchase_number)::text,
        s.id,s.name::text,'supplier'::text,
        pri.variant_id,prod.name::text,pv.sku::text,pv.barcode::text,pv.part_number::text,
        pia.hsn_sac::text,coalesce(pia.unit_code,'')::text,
        pri.quantity::numeric,pri.unit_cost::numeric,pri.discount_amount::numeric,pri.tax_rate::numeric,
        round(greatest(pri.line_total-((pri.unit_cost*pri.quantity)-pri.discount_amount),0),2)::numeric,
        round((pri.unit_cost*pri.quantity)-pri.discount_amount,2)::numeric,pri.line_total::numeric,
        pr.subtotal::numeric,pr.tax_total::numeric,pr.grand_total::numeric,
        pr.reason::text,pr.credit_status::text,
        pr.location_id,bl.location_code::text,bl.name::text,pr.created_by,pr.created_at,
        (select j.id from public.journal_entries j where j.tenant_id=p_tenant_id and j.source_type='purchase_return' and j.source_id=pr.id and j.status='posted' limit 1),
        'inventory_out / input_tax_reversal / supplier_credit_or_ap'::text
      from public.purchase_returns pr
      join public.purchase_return_items pri on pri.purchase_return_id=pr.id
      join public.purchases pch on pch.id=pr.purchase_id
      join public.suppliers s on s.id=pch.supplier_id
      join public.product_variants pv on pv.id=pri.variant_id
      join public.products prod on prod.id=pv.product_id
      left join public.product_invoice_attributes_v45 pia on pia.tenant_id=pr.tenant_id and pia.variant_id=pri.variant_id
      left join public.business_locations bl on bl.id=pr.location_id
      left join public.location_document_numbers ln on ln.entity_type='purchase' and ln.entity_id=pch.id
      left join public.device_document_numbers dn on dn.entity_type='purchase' and dn.entity_id=pch.id
      where pr.tenant_id=p_tenant_id and pr.credit_status<>'waived'
        and (p_from is null or pr.return_date>=p_from) and (p_to is null or pr.return_date<=p_to)
        and (p_location_id is null or pr.location_id=p_location_id)
    )
    select * from rows x
    where (lower(coalesce(p_kind,'all'))='all' or x.return_side=lower(p_kind))
      and (trim(coalesce(p_query,''))='' or lower(x.return_number) like q or lower(coalesce(x.source_number,'')) like q or lower(x.party_name) like q or lower(x.product_name) like q or lower(coalesce(x.sku,'')) like q or lower(coalesce(x.barcode,'')) like q or lower(coalesce(x.hsn_sac,'')) like q or lower(coalesce(x.reason,'')) like q)
    order by return_date desc,created_at desc
    limit greatest(1,least(coalesce(p_limit,5000),10000))
  loop return next to_jsonb(r);end loop;return;
end $$;


--
-- Name: sales_add_payment(uuid, uuid, numeric, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_add_payment(p_tenant_id uuid, p_sale_id uuid, p_amount numeric, p_payment_method text, p_reference_number text, p_notes text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_sale_total numeric;

  v_paid_before numeric;
  v_paid_after numeric;

  v_balance_before numeric;
  v_balance_after numeric;

  v_method text;

  v_payment_id uuid;

  v_status text;
begin

  -- ----------------------------------------------------------
  -- PERMISSION
  -- ----------------------------------------------------------

  if not private.has_permission(
    p_tenant_id,
    'sales.manage'
  ) then

    raise exception 'Access denied'
      using errcode = '42501';

  end if;


  -- ----------------------------------------------------------
  -- AMOUNT
  -- ----------------------------------------------------------

  if p_amount is null
     or p_amount <= 0 then

    raise exception
      'Payment amount must be greater than zero';

  end if;


  -- ----------------------------------------------------------
  -- SALE
  -- ----------------------------------------------------------

  select s.grand_total
  into v_sale_total

  from public.sales s

  where s.id = p_sale_id
    and s.tenant_id = p_tenant_id
    and s.status = 'posted'

  for update;


  if v_sale_total is null then

    raise exception
      'Sale not found or is not active';

  end if;


  -- ----------------------------------------------------------
  -- CURRENT PAYMENT
  -- ----------------------------------------------------------

  select coalesce(
    sum(sp.amount),
    0
  )

  into v_paid_before

  from public.sale_payments sp

  where sp.sale_id = p_sale_id
    and sp.tenant_id = p_tenant_id;


  v_balance_before :=
    v_sale_total
    - v_paid_before;


  if v_balance_before <= 0.0001 then

    raise exception
      'This sale is already fully paid';

  end if;


  if p_amount >
     v_balance_before + 0.0001 then

    raise exception
      'Payment cannot exceed remaining balance of %',
      v_balance_before;

  end if;


  -- ----------------------------------------------------------
  -- PAYMENT METHOD
  -- ----------------------------------------------------------

  v_method :=
    lower(
      trim(
        coalesce(
          p_payment_method,
          ''
        )
      )
    );


  if v_method not in (
    'cash',
    'bank',
    'card',
    'upi',
    'cheque',
    'other'
  ) then

    raise exception
      'Invalid payment method';

  end if;


  -- ----------------------------------------------------------
  -- PAYMENT
  -- ----------------------------------------------------------

  insert into public.sale_payments (
    tenant_id,

    sale_id,

    amount,

    payment_method,

    reference_number,

    notes,

    paid_at,

    created_by
  )
  values (
    p_tenant_id,

    p_sale_id,

    p_amount,

    v_method,

    nullif(
      trim(
        coalesce(
          p_reference_number,
          ''
        )
      ),
      ''
    ),

    nullif(
      trim(
        coalesce(
          p_notes,
          ''
        )
      ),
      ''
    ),

    now(),

    auth.uid()
  )

  returning id
  into v_payment_id;


  v_paid_after :=
    v_paid_before
    + p_amount;


  v_balance_after :=
    v_sale_total
    - v_paid_after;


  if v_balance_after <= 0.0001 then
    v_status := 'paid';

  elsif v_paid_after > 0 then
    v_status := 'partial';

  else
    v_status := 'unpaid';

  end if;


  return jsonb_build_object(
    'success',
    true,

    'payment_id',
    v_payment_id,

    'amount',
    p_amount,

    'paid_amount',
    v_paid_after,

    'balance_due',
    v_balance_after,

    'payment_status',
    v_status
  );

end;
$$;


--
-- Name: sales_add_payment_v32(uuid, uuid, numeric, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_add_payment_v32(p_tenant_id uuid, p_sale_id uuid, p_amount numeric, p_payment_method text, p_reference_number text, p_notes text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_loc uuid;v jsonb;begin
  select location_id into v_loc from public.document_origins where entity_type='sale' and entity_id=p_sale_id and tenant_id=p_tenant_id;
  if not private.erp_document_scope_allowed(p_tenant_id,v_loc,null,'operate') then raise exception 'Location access denied';end if;
  v:=public.sales_add_payment(p_tenant_id,p_sale_id,p_amount,p_payment_method,p_reference_number,p_notes);return v;
end $$;


--
-- Name: sales_add_payment_v47(uuid, uuid, numeric, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_add_payment_v47(p_tenant_id uuid, p_sale_id uuid, p_amount numeric, p_payment_method text, p_reference_number text, p_notes text, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v jsonb;begin v:=private.v47_request_existing(p_tenant_id,p_request_id,'sale.payment');if v is not null then return v;end if;v:=public.sales_add_payment_v32(p_tenant_id,p_sale_id,p_amount,p_payment_method,p_reference_number,p_notes);return private.v47_request_complete(p_tenant_id,p_request_id,'sale.payment',v);end$$;


--
-- Name: sales_create(uuid, uuid, date, date, jsonb, numeric, numeric, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_create(p_tenant_id uuid, p_customer_id uuid, p_sale_date date, p_due_date date, p_items jsonb, p_additional_charges numeric, p_initial_payment numeric, p_payment_method text, p_payment_reference text, p_notes text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_sale_id uuid;
  v_sale_number text;

  v_customer_name text;
  v_customer_phone text;
  v_customer_tax_number text;

  v_is_walk_in boolean;
  v_credit_limit numeric;

  v_location_id uuid;

  v_item jsonb;

  v_variant_id uuid;

  v_product_name text;
  v_item_type text;

  v_sku text;
  v_part_number text;
  v_unit_code text;

  v_quantity numeric;
  v_unit_price numeric;
  v_unit_cost numeric;

  v_discount numeric;
  v_tax_rate numeric;

  v_line_subtotal numeric;
  v_line_taxable numeric;
  v_line_tax numeric;
  v_line_total numeric;

  v_line_cost numeric;
  v_line_profit numeric;

  v_subtotal numeric := 0;
  v_discount_total numeric := 0;
  v_taxable_total numeric := 0;
  v_tax_total numeric := 0;

  v_cost_total numeric := 0;
  v_gross_profit numeric := 0;

  v_grand_total numeric := 0;

  v_initial_payment numeric;
  v_payment_method text;

  v_balance_due numeric;

  v_location_stock numeric;

  v_existing_outstanding numeric := 0;
begin

  -- ----------------------------------------------------------
  -- PERMISSION
  -- ----------------------------------------------------------

  if not private.has_permission(
    p_tenant_id,
    'sales.manage'
  ) then

    raise exception 'Access denied'
      using errcode = '42501';

  end if;


  -- ----------------------------------------------------------
  -- BUSINESS
  -- ----------------------------------------------------------

  if not exists (
    select 1

    from public.tenants t

    where t.id = p_tenant_id
      and t.status = 'active'
  ) then

    raise exception
      'Business not found or inactive';

  end if;


  -- ----------------------------------------------------------
  -- CUSTOMER
  -- ----------------------------------------------------------

  select
    c.name,
    c.phone,
    c.tax_number,
    c.is_walk_in,
    c.credit_limit

  into
    v_customer_name,
    v_customer_phone,
    v_customer_tax_number,
    v_is_walk_in,
    v_credit_limit

  from public.customers c

  where c.id = p_customer_id
    and c.tenant_id = p_tenant_id
    and c.status = 'active';


  if v_customer_name is null then

    raise exception
      'Active customer not found';

  end if;


  -- ----------------------------------------------------------
  -- DATE
  -- ----------------------------------------------------------

  if p_sale_date is null then

    raise exception
      'Sale date is required';

  end if;


  if p_due_date is not null
     and p_due_date < p_sale_date then

    raise exception
      'Due date cannot be before sale date';

  end if;


  -- ----------------------------------------------------------
  -- ITEMS
  -- ----------------------------------------------------------

  if p_items is null
     or jsonb_typeof(p_items) <> 'array'
     or jsonb_array_length(p_items) = 0 then

    raise exception
      'Sale must contain at least one item';

  end if;


  -- Same product variant may appear only once.

  if exists (
    select 1

    from (
      select
        item ->> 'variant_id'
          as variant_id_text,

        count(*) as item_count

      from jsonb_array_elements(
        p_items
      ) as item

      group by
        item ->> 'variant_id'
    ) duplicates

    where duplicates.variant_id_text is null
       or duplicates.variant_id_text = ''
       or duplicates.item_count > 1
  ) then

    raise exception
      'Each product may appear only once in a sale';

  end if;


  -- ----------------------------------------------------------
  -- ADDITIONAL CHARGES
  -- ----------------------------------------------------------

  if p_additional_charges is null
     or p_additional_charges < 0 then

    raise exception
      'Additional charges cannot be negative';

  end if;


  -- ----------------------------------------------------------
  -- INITIAL PAYMENT
  -- ----------------------------------------------------------

  v_initial_payment :=
    coalesce(
      p_initial_payment,
      0
    );


  if v_initial_payment < 0 then

    raise exception
      'Initial payment cannot be negative';

  end if;


  v_payment_method :=
    lower(
      trim(
        coalesce(
          p_payment_method,
          ''
        )
      )
    );


  if v_initial_payment > 0 then

    if v_payment_method = '' then
      v_payment_method := 'cash';
    end if;


    if v_payment_method not in (
      'cash',
      'bank',
      'card',
      'upi',
      'cheque',
      'other'
    ) then

      raise exception
        'Invalid payment method';

    end if;

  end if;


  -- ----------------------------------------------------------
  -- DEFAULT STOCK LOCATION
  -- ----------------------------------------------------------

  select il.id
  into v_location_id

  from public.inventory_locations il

  where il.tenant_id = p_tenant_id
    and il.is_active = true

  order by
    il.is_default desc,

    case
      when il.code = 'MAIN'
        then 0
      else 1
    end,

    il.created_at

  limit 1;


  if v_location_id is null then

    raise exception
      'No active inventory location exists';

  end if;


  -- ----------------------------------------------------------
  -- DOCUMENT NUMBER
  -- ----------------------------------------------------------

  v_sale_number :=
    private.next_document_number(
      p_tenant_id,
      'sale',
      'SAL'
    );


  -- ----------------------------------------------------------
  -- CREATE HEADER
  -- ----------------------------------------------------------

  insert into public.sales (
    tenant_id,

    sale_number,

    customer_id,
    customer_name,
    customer_phone,
    customer_tax_number,

    sale_date,
    due_date,

    status,

    subtotal,
    discount_total,
    taxable_total,
    tax_total,
    additional_charges,
    grand_total,

    cost_total,
    gross_profit,

    notes,

    posted_at,
    created_by
  )
  values (
    p_tenant_id,

    v_sale_number,

    p_customer_id,
    v_customer_name,
    v_customer_phone,
    v_customer_tax_number,

    p_sale_date,
    p_due_date,

    'posted',

    0,
    0,
    0,
    0,
    p_additional_charges,
    0,

    0,
    0,

    nullif(
      trim(
        coalesce(
          p_notes,
          ''
        )
      ),
      ''
    ),

    now(),
    auth.uid()
  )

  returning id
  into v_sale_id;


  -- ==========================================================
  -- PROCESS ITEMS
  -- ==========================================================

  for v_item in

    select value

    from jsonb_array_elements(
      p_items
    )

  loop

    -- --------------------------------------------------------
    -- PARSE
    -- --------------------------------------------------------

    begin

      v_variant_id :=
        (v_item ->> 'variant_id')::uuid;

      v_quantity :=
        (v_item ->> 'quantity')::numeric;

      v_unit_price :=
        (v_item ->> 'unit_price')::numeric;

      v_discount :=
        coalesce(
          nullif(
            v_item ->> 'discount_amount',
            ''
          )::numeric,
          0
        );

      v_tax_rate :=
        coalesce(
          nullif(
            v_item ->> 'tax_rate',
            ''
          )::numeric,
          0
        );

    exception
      when others then

        raise exception
          'Invalid sale item data';

    end;


    -- --------------------------------------------------------
    -- VALIDATION
    -- --------------------------------------------------------

    if v_quantity <= 0 then

      raise exception
        'Sale quantity must be greater than zero';

    end if;


    if v_unit_price < 0 then

      raise exception
        'Selling price cannot be negative';

    end if;


    if v_discount < 0 then

      raise exception
        'Item discount cannot be negative';

    end if;


    if v_tax_rate < 0
       or v_tax_rate > 100 then

      raise exception
        'Item tax rate must be between 0 and 100';

    end if;


    -- --------------------------------------------------------
    -- PRODUCT + COST SNAPSHOT
    -- --------------------------------------------------------

    select
      p.name,
      p.item_type,

      pv.sku,
      pv.part_number,

      iu.code,

      pv.cost_price

    into
      v_product_name,
      v_item_type,

      v_sku,
      v_part_number,

      v_unit_code,

      v_unit_cost

    from public.product_variants pv

    join public.products p
      on p.id = pv.product_id
     and p.tenant_id = pv.tenant_id

    left join public.inventory_units iu
      on iu.id = p.base_unit_id
     and iu.tenant_id = p.tenant_id

    where pv.id = v_variant_id
      and pv.tenant_id = p_tenant_id
      and pv.status = 'active'
      and p.status = 'active'

    for update of pv;


    if v_product_name is null then

      raise exception
        'Sale item is invalid or inactive';

    end if;


    -- --------------------------------------------------------
    -- LINE CALCULATION
    -- --------------------------------------------------------

    v_line_subtotal :=
      round(
        v_quantity
        * v_unit_price,
        4
      );


    if v_discount >
       v_line_subtotal then

      raise exception
        'Item discount cannot exceed item subtotal';

    end if;


    v_line_taxable :=
      round(
        v_line_subtotal
        - v_discount,
        4
      );


    v_line_tax :=
      round(
        v_line_taxable
        * v_tax_rate
        / 100,
        4
      );


    v_line_total :=
      round(
        v_line_taxable
        + v_line_tax,
        4
      );


    v_line_cost :=
      round(
        v_quantity
        * v_unit_cost,
        4
      );


    -- Profit excludes output tax.

    v_line_profit :=
      round(
        v_line_taxable
        - v_line_cost,
        4
      );


    -- --------------------------------------------------------
    -- STOCK AVAILABILITY
    -- --------------------------------------------------------

    if v_item_type = 'stock' then

      -- Ensure a balance row exists.

      insert into public.stock_balances (
        tenant_id,
        location_id,
        variant_id,
        quantity,
        updated_at
      )
      values (
        p_tenant_id,
        v_location_id,
        v_variant_id,
        0,
        now()
      )

      on conflict (
        tenant_id,
        location_id,
        variant_id
      )
      do nothing;


      -- Lock stock row to prevent concurrent overselling.

      select sb.quantity
      into v_location_stock

      from public.stock_balances sb

      where sb.tenant_id = p_tenant_id
        and sb.location_id = v_location_id
        and sb.variant_id = v_variant_id

      for update;


      if v_location_stock <
         v_quantity then

        raise exception
          'Insufficient stock for %. Available: %, requested: %',
          v_product_name,
          v_location_stock,
          v_quantity;

      end if;

    end if;


    -- --------------------------------------------------------
    -- CREATE SALE ITEM
    -- --------------------------------------------------------

    insert into public.sale_items (
      tenant_id,
      sale_id,
      variant_id,

      product_name,
      item_type,

      sku,
      part_number,
      unit_code,

      quantity,

      unit_price,
      unit_cost,

      discount_amount,
      tax_rate,

      subtotal,
      taxable_amount,
      tax_amount,
      line_total,

      cost_total,
      gross_profit
    )
    values (
      p_tenant_id,
      v_sale_id,
      v_variant_id,

      v_product_name,
      v_item_type,

      v_sku,
      v_part_number,
      v_unit_code,

      v_quantity,

      v_unit_price,
      v_unit_cost,

      v_discount,
      v_tax_rate,

      v_line_subtotal,
      v_line_taxable,
      v_line_tax,
      v_line_total,

      v_line_cost,
      v_line_profit
    );


    -- --------------------------------------------------------
    -- STOCK OUT
    -- --------------------------------------------------------

    if v_item_type = 'stock' then

      insert into public.stock_movements (
        tenant_id,
        variant_id,
        location_id,

        movement_type,
        quantity_delta,

        unit_cost,

        reference_type,
        reference_id,
        reference_number,

        note,

        occurred_at,
        created_by
      )
      values (
        p_tenant_id,
        v_variant_id,
        v_location_id,

        'sale',
        -v_quantity,

        v_unit_cost,

        'sale',
        v_sale_id,
        v_sale_number,

        'Sale to '
        || v_customer_name,

        now(),
        auth.uid()
      );


      update public.stock_balances
      set
        quantity =
          quantity
          - v_quantity,

        updated_at = now()

      where tenant_id = p_tenant_id
        and location_id = v_location_id
        and variant_id = v_variant_id;

    end if;


    -- --------------------------------------------------------
    -- HEADER TOTALS
    -- --------------------------------------------------------

    v_subtotal :=
      v_subtotal
      + v_line_subtotal;


    v_discount_total :=
      v_discount_total
      + v_discount;


    v_taxable_total :=
      v_taxable_total
      + v_line_taxable;


    v_tax_total :=
      v_tax_total
      + v_line_tax;


    v_cost_total :=
      v_cost_total
      + v_line_cost;


    v_gross_profit :=
      v_gross_profit
      + v_line_profit;

  end loop;


  -- ----------------------------------------------------------
  -- GRAND TOTAL
  -- ----------------------------------------------------------

  v_grand_total :=
    round(
      v_taxable_total
      + v_tax_total
      + p_additional_charges,
      4
    );


  if v_initial_payment >
     v_grand_total then

    raise exception
      'Initial payment cannot exceed sale total';

  end if;


  v_balance_due :=
    v_grand_total
    - v_initial_payment;


  -- ----------------------------------------------------------
  -- WALK-IN CUSTOMER
  --
  -- Walk-in sales must be fully paid.
  -- ----------------------------------------------------------

  
if v_is_walk_in = true
     and v_balance_due > 0.0001
     and not exists (
       select 1
       from private.gst_authoritative_tx_context_v520 gst_ctx
       where gst_ctx.txid = txid_current()
         and gst_ctx.tenant_id = p_tenant_id
         and gst_ctx.source_type = 'sale'
     ) then


    raise exception
      'Walk-in Customer sales must be fully paid';

  end if;


  -- ----------------------------------------------------------
  -- CUSTOMER CREDIT LIMIT
  --
  -- credit_limit = 0 means no configured limit.
  -- Any positive limit is enforced.
  -- ----------------------------------------------------------

  
if v_is_walk_in = false
     and v_balance_due > 0
     and v_credit_limit > 0
     and not exists (
       select 1
       from private.gst_authoritative_tx_context_v520 gst_ctx
       where gst_ctx.txid = txid_current()
         and gst_ctx.tenant_id = p_tenant_id
         and gst_ctx.source_type = 'sale'
     ) then


    select coalesce(
      sum(
        s.grand_total
        -
        coalesce(
          payments.paid_amount,
          0
        )
      ),
      0
    )

    into v_existing_outstanding

    from public.sales s

    left join lateral (
      select
        coalesce(
          sum(sp.amount),
          0
        ) as paid_amount

      from public.sale_payments sp

      where sp.sale_id = s.id
        and sp.tenant_id = s.tenant_id
    ) payments
      on true

    where s.tenant_id = p_tenant_id
      and s.customer_id = p_customer_id
      and s.status = 'posted'
      and s.id <> v_sale_id;


    if
      v_existing_outstanding
      + v_balance_due
      >
      v_credit_limit
      + 0.0001
    then

      raise exception
        'Customer credit limit exceeded. Limit: %, existing outstanding: %, new balance: %',
        v_credit_limit,
        v_existing_outstanding,
        v_balance_due;

    end if;

  end if;


  -- ----------------------------------------------------------
  -- FINALIZE HEADER
  -- ----------------------------------------------------------

  update public.sales
  set
    subtotal =
      v_subtotal,

    discount_total =
      v_discount_total,

    taxable_total =
      v_taxable_total,

    tax_total =
      v_tax_total,

    grand_total =
      v_grand_total,

    cost_total =
      v_cost_total,

    gross_profit =
      v_gross_profit

  where id = v_sale_id
    and tenant_id = p_tenant_id;


  -- ----------------------------------------------------------
  -- INITIAL PAYMENT
  -- ----------------------------------------------------------

  if v_initial_payment > 0 then

    insert into public.sale_payments (
      tenant_id,
      sale_id,

      amount,

      payment_method,

      reference_number,

      notes,

      paid_at,
      created_by
    )
    values (
      p_tenant_id,
      v_sale_id,

      v_initial_payment,

      v_payment_method,

      nullif(
        trim(
          coalesce(
            p_payment_reference,
            ''
          )
        ),
        ''
      ),

      'Payment entered with sale',

      now(),
      auth.uid()
    );

  end if;


  -- ----------------------------------------------------------
  -- RESULT
  -- ----------------------------------------------------------

  return jsonb_build_object(
    'success',
    true,

    'sale_id',
    v_sale_id,

    'sale_number',
    v_sale_number,

    'grand_total',
    v_grand_total,

    'paid_amount',
    v_initial_payment,

    'balance_due',
    v_balance_due,

    'cost_total',
    v_cost_total,

    'gross_profit',
    v_gross_profit
  );

end;
$$;


--
-- Name: sales_create_v32(uuid, uuid, date, date, jsonb, numeric, numeric, text, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_create_v32(p_tenant_id uuid, p_customer_id uuid, p_sale_date date, p_due_date date, p_items jsonb, p_additional_charges numeric, p_initial_payment numeric, p_payment_method text, p_payment_reference text, p_notes text, p_location_id uuid, p_device_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_result jsonb;
  v_ref text;
  v_id uuid;
  v_origin jsonb;
begin
  perform private.erp_validate_transaction_origin(p_tenant_id,p_location_id,p_device_id,'sales');

  select public.sales_create(
    p_tenant_id=>p_tenant_id,
    p_customer_id=>p_customer_id,
    p_sale_date=>p_sale_date,
    p_due_date=>p_due_date,
    p_items=>p_items,
    p_additional_charges=>p_additional_charges,
    p_initial_payment=>p_initial_payment,
    p_payment_method=>p_payment_method,
    p_payment_reference=>p_payment_reference,
    p_notes=>p_notes
  ) into v_result;

  v_ref:=coalesce(v_result->>'sale_number',v_result->>'number');
  if nullif(v_ref,'') is null then raise exception 'Sale transaction did not return a sale number'; end if;
  v_id:=public.document_origin_attach_by_reference(p_tenant_id,'sale',v_ref,p_location_id,p_device_id);
  v_origin:=public.document_origin_get(p_tenant_id,'sale',v_id);
  return coalesce(v_result,'{}'::jsonb) || jsonb_build_object(
    'sale_id',coalesce(v_result->>'sale_id',v_id::text),
    'invoice_number',v_origin->>'invoice_number',
    'location_id',p_location_id,
    'device_id',p_device_id
  );
end $$;


--
-- Name: sales_create_v4(uuid, uuid, date, date, jsonb, numeric, numeric, text, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_create_v4(p_tenant_id uuid, p_customer_id uuid, p_sale_date date, p_due_date date, p_items jsonb, p_additional_charges numeric, p_initial_payment numeric, p_payment_method text, p_payment_reference text, p_notes text, p_location_id uuid, p_device_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_result jsonb;v_sale_id uuid;v_ref text;x jsonb;v_variant uuid;v_qty numeric;v_item_type text;v_origin jsonb;begin
  perform private.erp_validate_transaction_origin(p_tenant_id,p_location_id,p_device_id,'sales');
  for x in select value from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) loop
    v_variant:=(x->>'variant_id')::uuid;v_qty:=coalesce((x->>'quantity')::numeric,0);
    select p.item_type into v_item_type from public.product_variants pv join public.products p on p.id=pv.product_id where pv.id=v_variant and pv.tenant_id=p_tenant_id;
    if v_item_type='stock' then
      if not exists(select 1 from public.location_product_settings where tenant_id=p_tenant_id and location_id=p_location_id and variant_id=v_variant and active) then raise exception 'Product is not assigned to this store';end if;
      if coalesce((select quantity-reserved_quantity-damaged_quantity-quarantine_quantity from public.location_stock_balances where tenant_id=p_tenant_id and location_id=p_location_id and variant_id=v_variant),0)<v_qty then raise exception 'Insufficient branch stock for %',coalesce(x->>'sku',v_variant::text);end if;
    end if;
  end loop;
  select public.sales_create(p_tenant_id,p_customer_id,p_sale_date,p_due_date,p_items,p_additional_charges,p_initial_payment,p_payment_method,p_payment_reference,p_notes) into v_result;
  v_ref:=coalesce(v_result->>'sale_number',v_result->>'number');
  begin v_sale_id:=coalesce(nullif(v_result->>'sale_id',''),nullif(v_result->>'id',''))::uuid;exception when others then v_sale_id:=null;end;
  if v_sale_id is null then select id into v_sale_id from public.sales where tenant_id=p_tenant_id and sale_number=v_ref order by created_at desc limit 1;end if;
  if v_sale_id is null then raise exception 'Sale transaction could not be resolved';end if;
  perform public.document_origin_attach(p_tenant_id,'sale',v_sale_id,p_location_id,p_device_id);
  for x in select value from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) loop
    v_variant:=(x->>'variant_id')::uuid;v_qty:=coalesce((x->>'quantity')::numeric,0);
    select p.item_type into v_item_type from public.product_variants pv join public.products p on p.id=pv.product_id where pv.id=v_variant and pv.tenant_id=p_tenant_id;
    if v_item_type='stock' then perform private.v4_location_stock_apply(p_tenant_id,p_location_id,v_variant,-v_qty,'sale','sale',v_sale_id,v_ref,'Sale',p_device_id,false); end if;
  end loop;
  begin v_origin:=public.document_origin_get(p_tenant_id,'sale',v_sale_id); exception when others then v_origin:='{}'::jsonb;end;
  return coalesce(v_result,'{}'::jsonb)||jsonb_build_object('sale_id',v_sale_id,'location_id',p_location_id,'device_id',p_device_id,'invoice_number',coalesce(v_origin->>'invoice_number',v_ref));
end $$;


--
-- Name: sales_create_v47(uuid, uuid, date, date, jsonb, numeric, numeric, text, text, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_create_v47(p_tenant_id uuid, p_customer_id uuid, p_sale_date date, p_due_date date, p_items jsonb, p_additional_charges numeric, p_initial_payment numeric, p_payment_method text, p_payment_reference text, p_notes text, p_location_id uuid, p_device_id uuid, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v jsonb;v_type text;v_modules text[];begin
  v:=private.v47_request_existing(p_tenant_id,p_request_id,'sale.create'); if v is not null then return v;end if;
  if p_device_id is not null then
    select app_type,coalesce(allowed_modules,'{}'::text[]) into v_type,v_modules
    from public.business_devices where id=p_device_id and tenant_id=p_tenant_id and status='active';
    if v_type='pos' and 'cashier_shifts'=any(v_modules)
       and not exists(select 1 from public.cashier_shifts s where s.tenant_id=p_tenant_id and s.device_id=p_device_id and s.status='open') then
      raise exception 'Open cashier shift before billing on this POS';
    end if;
  end if;
  v:=public.sales_create_v4(p_tenant_id,p_customer_id,p_sale_date,p_due_date,p_items,p_additional_charges,p_initial_payment,p_payment_method,p_payment_reference,p_notes,p_location_id,p_device_id);
  return private.v47_request_complete(p_tenant_id,p_request_id,'sale.create',v);
end $$;


--
-- Name: sales_create_v481(uuid, uuid, date, date, jsonb, numeric, numeric, text, text, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_create_v481(p_tenant_id uuid, p_customer_id uuid, p_sale_date date, p_due_date date, p_items jsonb, p_additional_charges numeric, p_initial_payment numeric, p_payment_method text, p_payment_reference text, p_notes text, p_location_id uuid, p_device_id uuid, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_items jsonb;v jsonb;v_sale uuid;x jsonb;v_variant uuid;begin
  v_items:=private.v481_normalize_items(p_tenant_id,p_items,'sale');
  v:=public.sales_create_v47(p_tenant_id,p_customer_id,p_sale_date,p_due_date,v_items,p_additional_charges,p_initial_payment,p_payment_method,p_payment_reference,p_notes,p_location_id,p_device_id,p_request_id);
  v_sale:=nullif(v->>'sale_id','')::uuid;
  if v_sale is not null then
    for x in select value from jsonb_array_elements(v_items) loop
      v_variant:=(x->>'variant_id')::uuid;
      update public.sale_items si set entered_unit_id=nullif(x->>'_entered_unit_id','')::uuid,entered_unit_code=x->>'_entered_unit_code',entered_quantity=(x->>'_entered_quantity')::numeric,conversion_to_base=(x->>'_conversion_to_base')::numeric,entered_unit_price=(x->>'_entered_unit_price')::numeric
      where si.sale_id=v_sale and si.variant_id=v_variant;
      update public.location_stock_movements m set unit_id=nullif(x->>'_entered_unit_id','')::uuid,unit_code=x->>'_entered_unit_code',display_quantity=-abs((x->>'_entered_quantity')::numeric),conversion_to_base=(x->>'_conversion_to_base')::numeric,metadata=m.metadata||jsonb_build_object('entered_unit_price',(x->>'_entered_unit_price')::numeric)
      where m.tenant_id=p_tenant_id and m.reference_type='sale' and m.reference_id=v_sale and m.variant_id=v_variant and m.movement_type='sale';
    end loop;
  end if;return v;
end $$;


--
-- Name: sales_create_v482(uuid, uuid, date, date, jsonb, numeric, numeric, text, text, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_create_v482(p_tenant_id uuid, p_customer_id uuid, p_sale_date date, p_due_date date, p_items jsonb, p_additional_charges numeric, p_initial_payment numeric, p_payment_method text, p_payment_reference text, p_notes text, p_location_id uuid, p_device_id uuid, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v_priced jsonb;v_result jsonb;v_sale uuid;x jsonb;v_variant uuid;begin
 v_priced:=private.v482_price_sale_items(p_tenant_id,p_customer_id,p_items,p_location_id);
 v_result:=public.sales_create_v481(p_tenant_id,p_customer_id,p_sale_date,p_due_date,v_priced,p_additional_charges,p_initial_payment,p_payment_method,p_payment_reference,p_notes,p_location_id,p_device_id,p_request_id);
 v_sale:=nullif(v_result->>'sale_id','')::uuid;
 if v_sale is not null then
  for x in select value from jsonb_array_elements(v_priced) loop
   v_variant:=(x->>'variant_id')::uuid;
   update public.sale_items si set pricing_source=nullif(x->>'_pricing_source',''),price_list_id=nullif(x->>'_price_list_id','')::uuid,pricing_metadata=jsonb_strip_nulls(jsonb_build_object('price_list_name',nullif(x->>'_price_list_name',''),'resolved_at',now()))
   where si.sale_id=v_sale and si.variant_id=v_variant and si.entered_unit_id=nullif(x->>'unit_id','')::uuid;
  end loop;
 end if;
 return v_result||jsonb_build_object('pricing_engine','v4.8.2');
end$$;


--
-- Name: sales_create_v483(uuid, uuid, date, date, jsonb, numeric, numeric, text, text, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_create_v483(p_tenant_id uuid, p_customer_id uuid, p_sale_date date, p_due_date date, p_items jsonb, p_additional_charges numeric, p_initial_payment numeric, p_payment_method text, p_payment_reference text, p_notes text, p_location_id uuid, p_device_id uuid, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_normalized jsonb;v_result jsonb;v_sale uuid;x jsonb;v_variant uuid;v_mode text;v_serials jsonb;v_count numeric;v_qty numeric;begin
 v_normalized:=private.v481_normalize_items(p_tenant_id,p_items,'sale');
 for x in select value from jsonb_array_elements(v_normalized) loop
  v_variant:=(x->>'variant_id')::uuid;v_mode:=private.v483_tracking_mode(p_tenant_id,v_variant);if v_mode='none' then continue;end if;perform private.v483_assert_reconciled(p_tenant_id,v_variant,p_location_id);
  if v_mode='serial' then v_qty:=coalesce(nullif(x->>'quantity','')::numeric,0);v_serials:=coalesce(x->'serial_numbers','[]'::jsonb);select count(*)::numeric into v_count from jsonb_array_elements(v_serials);if v_count<>v_qty then raise exception 'Provide exactly % serial numbers for serial-tracked product',v_qty;end if;end if;
 end loop;
 v_result:=public.sales_create_v482(p_tenant_id,p_customer_id,p_sale_date,p_due_date,p_items,p_additional_charges,p_initial_payment,p_payment_method,p_payment_reference,p_notes,p_location_id,p_device_id,p_request_id);
 v_sale:=nullif(v_result->>'sale_id','')::uuid;if v_sale is not null then perform private.v483_apply_sale_trace(p_tenant_id,v_sale,p_customer_id,p_location_id,p_sale_date,v_normalized);end if;
 return v_result||jsonb_build_object('tracking_engine','v4.8.3');
end$$;


--
-- Name: sales_create_v489(uuid, uuid, date, date, jsonb, numeric, numeric, numeric, text, text, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_create_v489(p_tenant_id uuid, p_customer_id uuid, p_sale_date date, p_due_date date, p_items jsonb, p_additional_charges numeric, p_round_off numeric, p_initial_payment numeric, p_payment_method text, p_payment_reference text, p_notes text, p_location_id uuid, p_device_id uuid, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v jsonb;v_id uuid;v_round numeric:=round(coalesce(p_round_off,0),2);v_add numeric:=greatest(coalesce(p_additional_charges,0),0);v_final numeric;v_old_round numeric;v_old_add numeric;v_old_total numeric;
begin
  if abs(v_round)>0.999999 then raise exception 'Round off must be between -1.00 and 1.00';end if;
  v:=public.sales_create_v483(p_tenant_id,p_customer_id,p_sale_date,p_due_date,p_items,v_add+greatest(v_round,0),p_initial_payment,p_payment_method,p_payment_reference,p_notes,p_location_id,p_device_id,p_request_id);
  v_id:=nullif(v->>'sale_id','')::uuid;if v_id is null then return v;end if;
  select round_off,additional_charges,grand_total into v_old_round,v_old_add,v_old_total from public.sales where id=v_id and tenant_id=p_tenant_id for update;
  select round(coalesce(sum(si.line_total),0)+v_add+v_round,2) into v_final from public.sale_items si where si.sale_id=v_id;
  if v_final<0 then raise exception 'Rounded sale total cannot be negative';end if;
  if coalesce(p_initial_payment,0)>v_final+0.005 then raise exception 'Payment cannot exceed rounded sale total';end if;
  if abs(coalesce(v_old_round,0)-v_round)>0.000001 or abs(coalesce(v_old_add,0)-v_add)>0.000001 or abs(coalesce(v_old_total,0)-v_final)>0.000001 then
    -- This is a replacement journal, not a void. Retire the original posting and create
    -- one corrected posting; a posted reversal would be double-counted by reports that
    -- intentionally read only status='posted' journals.
    update public.journal_entries set status='reversed' where tenant_id=p_tenant_id and source_type='sale' and source_id=v_id and status='posted';
    update public.sales set additional_charges=v_add,round_off=v_round,grand_total=v_final where id=v_id and tenant_id=p_tenant_id;
    perform private.v4_accounting_post_document(p_tenant_id,'sale',v_id);
  end if;
  return v||jsonb_build_object('grand_total',v_final,'round_off',v_round,'rounding_engine','v4.8.9');
end $$;


--
-- Name: sales_get_detail(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_get_detail(p_tenant_id uuid, p_sale_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_result jsonb;
begin

  if not (
    private.has_permission(
      p_tenant_id,
      'sales.view'
    )
    or
    private.has_permission(
      p_tenant_id,
      'sales.manage'
    )
  ) then

    raise exception 'Access denied'
      using errcode = '42501';

  end if;


  if not exists (
    select 1

    from public.sales s

    where s.id = p_sale_id
      and s.tenant_id = p_tenant_id
  ) then

    raise exception
      'Sale not found';

  end if;


  select jsonb_build_object(

    'sale',
    jsonb_build_object(
      'sale_id',
      s.id,

      'sale_number',
      s.sale_number,

      'customer_id',
      s.customer_id,

      'customer_name',
      s.customer_name,

      'customer_phone',
      s.customer_phone,

      'customer_tax_number',
      s.customer_tax_number,

      'sale_date',
      s.sale_date,

      'due_date',
      s.due_date,

      'status',
      s.status,

      'subtotal',
      s.subtotal,

      'discount_total',
      s.discount_total,

      'taxable_total',
      s.taxable_total,

      'tax_total',
      s.tax_total,

      'additional_charges',
      s.additional_charges,

      'grand_total',
      s.grand_total,

      'cost_total',
      s.cost_total,

      'gross_profit',
      s.gross_profit,

      'notes',
      s.notes,

      'created_at',
      s.created_at
    ),

    'items',
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'item_id',
            si.id,

            'variant_id',
            si.variant_id,

            'product_name',
            si.product_name,

            'item_type',
            si.item_type,

            'sku',
            si.sku,

            'part_number',
            si.part_number,

            'unit_code',
            si.unit_code,

            'quantity',
            si.quantity,

            'unit_price',
            si.unit_price,

            'unit_cost',
            si.unit_cost,

            'discount_amount',
            si.discount_amount,

            'tax_rate',
            si.tax_rate,

            'subtotal',
            si.subtotal,

            'taxable_amount',
            si.taxable_amount,

            'tax_amount',
            si.tax_amount,

            'line_total',
            si.line_total,

            'cost_total',
            si.cost_total,

            'gross_profit',
            si.gross_profit
          )

          order by si.created_at
        )

        from public.sale_items si

        where si.sale_id = s.id
          and si.tenant_id = s.tenant_id
      ),

      '[]'::jsonb
    ),

    'payments',
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'payment_id',
            sp.id,

            'amount',
            sp.amount,

            'payment_method',
            sp.payment_method,

            'reference_number',
            sp.reference_number,

            'notes',
            sp.notes,

            'paid_at',
            sp.paid_at
          )

          order by sp.paid_at
        )

        from public.sale_payments sp

        where sp.sale_id = s.id
          and sp.tenant_id = s.tenant_id
      ),

      '[]'::jsonb
    ),

    'paid_amount',
    (
      select coalesce(
        sum(sp.amount),
        0
      )

      from public.sale_payments sp

      where sp.sale_id = s.id
        and sp.tenant_id = s.tenant_id
    ),

    'balance_due',
    s.grand_total
    -
    (
      select coalesce(
        sum(sp.amount),
        0
      )

      from public.sale_payments sp

      where sp.sale_id = s.id
        and sp.tenant_id = s.tenant_id
    )

  )

  into v_result

  from public.sales s

  where s.id = p_sale_id
    and s.tenant_id = p_tenant_id;


  return v_result;

end;
$$;


--
-- Name: sales_get_detail_v32(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_get_detail_v32(p_tenant_id uuid, p_sale_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_loc uuid;v jsonb;v_items jsonb;begin
  select o.location_id into v_loc from public.document_origins o where o.entity_type='sale' and o.entity_id=p_sale_id and o.tenant_id=p_tenant_id;
  if not private.erp_document_scope_allowed(p_tenant_id,v_loc,null,'view') then raise exception 'Location access denied';end if;
  v:=public.sales_get_detail(p_tenant_id,p_sale_id);
  select coalesce(jsonb_agg(i.value||jsonb_build_object(
    'hsn_sac',a.hsn_sac,
    'unit_code',coalesce(si.entered_unit_code,nullif(i.value->>'unit_code',''),a.unit_code),
    'quantity',coalesce(si.entered_quantity,(i.value->>'quantity')::numeric),
    'base_quantity',coalesce(si.quantity,(i.value->>'quantity')::numeric),
    'unit_price',coalesce(si.entered_unit_price,(i.value->>'unit_price')::numeric),
    'conversion_to_base',coalesce(si.conversion_to_base,1),
    'preferred_supplier_name',a.preferred_supplier_name
  )),'[]'::jsonb) into v_items
  from jsonb_array_elements(coalesce(v->'items','[]'::jsonb)) i(value)
  left join public.sale_items si on si.sale_id=p_sale_id and si.variant_id=nullif(i.value->>'variant_id','')::uuid
  left join public.product_invoice_attributes_v45 a on a.tenant_id=p_tenant_id and a.variant_id=nullif(i.value->>'variant_id','')::uuid;
  return jsonb_set(v,'{items}',coalesce(v_items,'[]'::jsonb),true);
end $$;


--
-- Name: sales_get_detail_v482(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_get_detail_v482(p_tenant_id uuid, p_sale_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v jsonb;v_items jsonb;begin
 v:=public.sales_get_detail_v32(p_tenant_id,p_sale_id);
 select coalesce(jsonb_agg(i.value||jsonb_build_object('pricing_source',si.pricing_source,'price_list_id',si.price_list_id,'pricing_metadata',si.pricing_metadata)),'[]'::jsonb) into v_items
 from jsonb_array_elements(coalesce(v->'items','[]'::jsonb)) i(value) left join public.sale_items si on si.sale_id=p_sale_id and si.variant_id=nullif(i.value->>'variant_id','')::uuid and (si.entered_unit_code is null or si.entered_unit_code=coalesce(i.value->>'unit_code',si.entered_unit_code));
 return jsonb_set(v,'{items}',coalesce(v_items,'[]'::jsonb),true);
end$$;


--
-- Name: sales_get_detail_v495(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_get_detail_v495(p_tenant_id uuid, p_sale_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v jsonb; c record; sale_doc jsonb;
begin
  v:=public.sales_get_detail_v482(p_tenant_id,p_sale_id);
  select cu.phone,cu.email,cu.address_line1,cu.address_line2,cu.city,cu.state,cu.postal_code,cu.country
    into c
  from public.sales s join public.customers cu on cu.id=s.customer_id
  where s.id=p_sale_id and s.tenant_id=p_tenant_id;
  sale_doc:=coalesce(v->'sale','{}'::jsonb)||jsonb_strip_nulls(jsonb_build_object(
    'customer_phone',c.phone,'customer_email',c.email,'customer_address_line1',c.address_line1,'customer_address_line2',c.address_line2,
    'customer_city',c.city,'customer_state',c.state,'customer_postal_code',c.postal_code,'customer_country',c.country
  ));
  return jsonb_set(v,'{sale}',sale_doc,true);
end $$;


--
-- Name: sales_get_detail_v520(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_get_detail_v520(p_tenant_id uuid, p_sale_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_result jsonb;
  v_gst jsonb;
begin
  -- Reuse the existing permission-checked sale detail contract.
  v_result := public.sales_get_detail_v495(p_tenant_id, p_sale_id);

  select jsonb_build_object(
    'authoritative', true,
    'snapshot_id', s.id,
    'document_class', s.document_class,
    'tax_mode', s.tax_mode,
    'supply_type', s.supply_type,
    'interstate', s.interstate,
    'place_of_supply_code', s.place_of_supply_code,
    'supplier_gstin', s.supplier_gstin,
    'recipient_gstin', s.recipient_gstin,
    'taxable_total', s.taxable_total,
    'cgst_total', s.cgst_total,
    'sgst_total', s.sgst_total,
    'utgst_total', s.utgst_total,
    'igst_total', s.igst_total,
    'cess_total', s.cess_total,
    'tax_collected_total', s.tax_collected_total,
    'government_tax_total', s.government_tax_total,
    'lines', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'source_line_id', l.source_line_id,
          'line_no', l.line_no,
          'hsn_sac', l.hsn_sac,
          'gst_rate', l.applied_gst_rate,
          'taxable_value', l.taxable_value,
          'cgst', l.cgst,
          'sgst', l.sgst,
          'utgst', l.utgst,
          'igst', l.igst,
          'cess', l.cess,
          'tax_amount', l.tax_amount
        ) order by l.line_no
      )
      from public.gst_document_line_snapshots_v520 l
      where l.snapshot_id = s.id
    ), '[]'::jsonb)
  )
  into v_gst
  from public.gst_document_snapshots_v520 s
  where s.tenant_id = p_tenant_id
    and s.source_type = 'sale'
    and s.source_id = p_sale_id
  order by s.created_at desc
  limit 1;

  return v_result || jsonb_build_object('gst', v_gst);
end;
$$;


--
-- Name: sales_list(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_list(p_tenant_id uuid) RETURNS TABLE(sale_id uuid, sale_number text, customer_id uuid, customer_name text, sale_date date, due_date date, subtotal numeric, discount_total numeric, tax_total numeric, additional_charges numeric, grand_total numeric, paid_amount numeric, balance_due numeric, payment_status text, cost_total numeric, gross_profit numeric, status text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin

  if not (
    private.has_permission(
      p_tenant_id,
      'sales.view'
    )
    or
    private.has_permission(
      p_tenant_id,
      'sales.manage'
    )
  ) then

    raise exception 'Access denied'
      using errcode = '42501';

  end if;


  return query

  select
    s.id,

    s.sale_number,

    s.customer_id,
    s.customer_name,

    s.sale_date,
    s.due_date,

    s.subtotal,
    s.discount_total,
    s.tax_total,
    s.additional_charges,

    s.grand_total,

    coalesce(
      pay.paid_amount,
      0
    )::numeric,

    (
      s.grand_total
      -
      coalesce(
        pay.paid_amount,
        0
      )
    )::numeric,

    case

      when s.grand_total <= 0.0001
      then 'paid'

      when coalesce(
        pay.paid_amount,
        0
      ) <= 0
      then 'unpaid'

      when coalesce(
        pay.paid_amount,
        0
      ) < s.grand_total
      then 'partial'

      else 'paid'

    end,

    s.cost_total,
    s.gross_profit,

    s.status,

    s.created_at

  from public.sales s

  left join lateral (
    select
      coalesce(
        sum(sp.amount),
        0
      ) as paid_amount

    from public.sale_payments sp

    where sp.sale_id = s.id
      and sp.tenant_id = s.tenant_id
  ) pay
    on true

  where s.tenant_id = p_tenant_id

  order by
    s.sale_date desc,
    s.created_at desc;

end;
$$;


--
-- Name: sales_list_v32(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_list_v32(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid) RETURNS TABLE(sale_id uuid, sale_number text, invoice_number text, customer_id uuid, customer_name text, sale_date date, due_date date, subtotal numeric, discount_total numeric, tax_total numeric, additional_charges numeric, grand_total numeric, paid_amount numeric, balance_due numeric, payment_status text, cost_total numeric, gross_profit numeric, status text, created_at timestamp with time zone, location_id uuid, location_name text, device_id uuid, device_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if p_location_id is not null and not private.erp_user_location_allowed(p_tenant_id,p_location_id,'view')
     and not private.erp_has_permission(p_tenant_id,'locations.view_all')
     and not private.erp_has_permission(p_tenant_id,'locations.manage_all')
     and not private.erp_user_is_owner(p_tenant_id) then
    raise exception 'Location access denied';
  end if;
  return query
  select s.id,s.sale_number::text,coalesce(dn.terminal_number,ln.local_number,s.sale_number)::text,
    s.customer_id,c.name::text,s.sale_date,s.due_date,
    s.subtotal,s.discount_total,s.tax_total,s.additional_charges,s.grand_total,
    coalesce(py.paid,0)::numeric,greatest(s.grand_total-coalesce(py.paid,0),0)::numeric,
    (case when greatest(s.grand_total-coalesce(py.paid,0),0)<=0.0001 then 'paid' when coalesce(py.paid,0)>0 then 'partial' else 'unpaid' end)::text,
    coalesce(s.cost_total,0)::numeric,coalesce(s.gross_profit,0)::numeric,s.status::text,s.created_at,
    o.location_id,l.name::text,o.device_id,d.name::text
  from public.sales s
  join public.customers c on c.id=s.customer_id
  left join (
    select sp.sale_id as entity_sale_id,sum(sp.amount) as paid
    from public.sale_payments sp group by sp.sale_id
  ) py on py.entity_sale_id=s.id
  left join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='sale' and o.entity_id=s.id
  left join public.business_locations l on l.id=o.location_id
  left join public.business_devices d on d.id=o.device_id
  left join public.location_document_numbers ln on ln.tenant_id=p_tenant_id and ln.entity_type='sale' and ln.entity_id=s.id
  left join public.device_document_numbers dn on dn.tenant_id=p_tenant_id and dn.entity_type='sale' and dn.entity_id=s.id
  where s.tenant_id=p_tenant_id
    and (private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'sales.view') or private.erp_has_permission(p_tenant_id,'sales.manage'))
    and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view')
  order by s.sale_date desc,s.created_at desc;
end $$;


--
-- Name: sales_resolve_number_v32(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_resolve_number_v32(p_tenant_id uuid, p_sale_number text) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_id uuid;v_loc uuid;begin
  select s.id,o.location_id into v_id,v_loc from public.sales s left join public.document_origins o on o.entity_type='sale' and o.entity_id=s.id
  where s.tenant_id=p_tenant_id and s.sale_number=p_sale_number order by s.created_at desc limit 1;
  if v_id is null then return null;end if;
  if not private.erp_document_scope_allowed(p_tenant_id,v_loc,null,'view') then raise exception 'Location access denied';end if;
  return v_id;
end $$;


--
-- Name: sales_return_create_v4(uuid, uuid, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_return_create_v4(p_tenant_id uuid, p_sale_id uuid, p_items jsonb, p_reason text, p_device_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_loc uuid;v_id uuid:=gen_random_uuid();v_no text;x jsonb;v_si public.sale_items%rowtype;v_prev numeric;v_qty numeric;v_line numeric;v_sub numeric:=0;v_tax numeric:=0;v_total numeric:=0;begin
  if trim(coalesce(p_reason,''))='' then raise exception 'Return reason is required';end if;
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'sales.return') and not private.erp_has_permission(p_tenant_id,'sales.manage') then raise exception 'Sales return permission required';end if;
  select location_id into v_loc from public.document_origins where tenant_id=p_tenant_id and entity_type='sale' and entity_id=p_sale_id;
  if v_loc is null then raise exception 'Original sale does not have a store origin';end if;perform private.v4_location_access(p_tenant_id,v_loc,'operate');
  v_no:='SRN-'||lpad(nextval('public.sales_return_number_seq')::text,6,'0');
  insert into public.sales_returns(id,tenant_id,sale_id,return_number,location_id,device_id,reason,created_by) values(v_id,p_tenant_id,p_sale_id,v_no,v_loc,p_device_id,trim(p_reason),auth.uid());
  for x in select value from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) loop
    select * into v_si from public.sale_items where id=(x->>'sale_item_id')::uuid and sale_id=p_sale_id;if not found then raise exception 'Sale item not found';end if;
    v_qty:=(x->>'quantity')::numeric;if v_qty<=0 then raise exception 'Return quantity must be positive';end if;
    select coalesce(sum(i.quantity),0) into v_prev from public.sales_return_items i join public.sales_returns r on r.id=i.sales_return_id where r.sale_id=p_sale_id and i.sale_item_id=v_si.id;
    if v_prev+v_qty>v_si.quantity then raise exception 'Return quantity exceeds sold quantity';end if;
    v_line:=round(((v_si.unit_price*v_qty)-coalesce(v_si.discount_amount,0)*(v_qty/v_si.quantity))*(1+coalesce(v_si.tax_rate,0)/100.0),2);
    insert into public.sales_return_items(sales_return_id,sale_item_id,variant_id,quantity,unit_price,discount_amount,tax_rate,line_total)
    values(v_id,v_si.id,v_si.variant_id,v_qty,v_si.unit_price,coalesce(v_si.discount_amount,0)*(v_qty/v_si.quantity),coalesce(v_si.tax_rate,0),v_line);
    v_sub:=v_sub+(v_si.unit_price*v_qty)-coalesce(v_si.discount_amount,0)*(v_qty/v_si.quantity);v_tax:=v_tax+(v_line-((v_si.unit_price*v_qty)-coalesce(v_si.discount_amount,0)*(v_qty/v_si.quantity)));v_total:=v_total+v_line;
    perform public.inventory_adjust_stock(p_tenant_id,v_si.variant_id,v_qty,'Sale return • '||v_no);
    perform private.v4_location_stock_apply(p_tenant_id,v_loc,v_si.variant_id,v_qty,'sale_return','sales_return',v_id,v_no,trim(p_reason),p_device_id,false);
  end loop;
  update public.sales_returns set subtotal=v_sub,tax_total=v_tax,grand_total=v_total where id=v_id;
  insert into public.transaction_corrections(tenant_id,entity_type,entity_id,correction_type,reason,created_by,metadata) values(p_tenant_id,'sale',p_sale_id,'return',trim(p_reason),auth.uid(),jsonb_build_object('return_id',v_id,'return_number',v_no,'amount',v_total));
  return jsonb_build_object('return_id',v_id,'return_number',v_no,'grand_total',v_total,'refund_status','credit_due');
end $$;


--
-- Name: sales_return_create_v47(uuid, uuid, jsonb, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_return_create_v47(p_tenant_id uuid, p_sale_id uuid, p_items jsonb, p_reason text, p_device_id uuid, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v jsonb;begin v:=private.v47_request_existing(p_tenant_id,p_request_id,'sale.return');if v is not null then return v;end if;v:=public.sales_return_create_v4(p_tenant_id,p_sale_id,p_items,p_reason,p_device_id);return private.v47_request_complete(p_tenant_id,p_request_id,'sale.return',v);end$$;


--
-- Name: sales_return_create_v481(uuid, uuid, jsonb, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_return_create_v481(p_tenant_id uuid, p_sale_id uuid, p_items jsonb, p_reason text, p_device_id uuid, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare x jsonb;v_items jsonb:='[]'::jsonb;v_si public.sale_items%rowtype;v_entered numeric;v_factor numeric;v_step numeric:=1;v_fractional boolean:=false;v jsonb;v_return uuid;begin
  for x in select value from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) loop
    select si.* into v_si from public.sale_items si where si.id=(x->>'sale_item_id')::uuid and si.sale_id=p_sale_id;
    if not found then raise exception 'Sale item not found';end if;
    v_entered:=coalesce(nullif(x->>'quantity','')::numeric,0);
    if v_entered<=0 then raise exception 'Return quantity must be positive';end if;
    v_factor:=coalesce(nullif(v_si.conversion_to_base,0),1);
    if v_si.entered_unit_id is not null then
      select pu.quantity_step,u.allow_fractional into v_step,v_fractional from public.product_units_v481 pu join public.inventory_units_v481 u on u.id=pu.unit_id where pu.tenant_id=p_tenant_id and pu.variant_id=v_si.variant_id and pu.unit_id=v_si.entered_unit_id;
      v_step:=greatest(coalesce(v_step,1),0.000001);
      if not coalesce(v_fractional,false) and v_entered<>trunc(v_entered) then raise exception 'Return unit % only allows whole quantities',coalesce(v_si.entered_unit_code,'');end if;
      if abs((v_entered/v_step)-round(v_entered/v_step))>0.000001 then raise exception 'Return quantity for unit % must use increments of %',coalesce(v_si.entered_unit_code,''),v_step;end if;
    end if;
    v_items:=v_items||jsonb_build_array(x||jsonb_build_object('quantity',v_entered*v_factor,'_entered_quantity',v_entered,'_unit_id',v_si.entered_unit_id,'_unit_code',coalesce(v_si.entered_unit_code,''),'_conversion_to_base',v_factor));
  end loop;
  v:=public.sales_return_create_v47(p_tenant_id,p_sale_id,v_items,p_reason,p_device_id,p_request_id);
  v_return:=nullif(v->>'return_id','')::uuid;
  if v_return is not null then
    for x in select value from jsonb_array_elements(v_items) loop
      update public.sales_return_items ri set
        entered_unit_id=nullif(x->>'_unit_id','')::uuid,
        entered_unit_code=nullif(x->>'_unit_code',''),
        entered_quantity=(x->>'_entered_quantity')::numeric,
        conversion_to_base=(x->>'_conversion_to_base')::numeric
      where ri.sales_return_id=v_return and ri.sale_item_id=(x->>'sale_item_id')::uuid;
      update public.location_stock_movements m set
        unit_id=nullif(x->>'_unit_id','')::uuid,
        unit_code=nullif(x->>'_unit_code',''),
        display_quantity=abs((x->>'_entered_quantity')::numeric),
        conversion_to_base=(x->>'_conversion_to_base')::numeric
      where m.tenant_id=p_tenant_id and m.reference_type='sales_return' and m.reference_id=v_return
        and m.variant_id=(select si.variant_id from public.sale_items si where si.id=(x->>'sale_item_id')::uuid)
        and m.movement_type in('sale_return','sales_return');
    end loop;
  end if;
  return v;
end $$;


--
-- Name: sales_return_create_v483(uuid, uuid, jsonb, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_return_create_v483(p_tenant_id uuid, p_sale_id uuid, p_items jsonb, p_reason text, p_device_id uuid, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare x jsonb;v_variant uuid;begin
 for x in select value from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) loop
  select variant_id into v_variant from public.sale_items where id=(x->>'sale_item_id')::uuid and sale_id=p_sale_id;
  if v_variant is null then raise exception 'Sale item not found';end if;
  if private.v483_tracking_mode(p_tenant_id,v_variant)<>'none' then raise exception 'Returns for serial/batch products require trace allocation and are blocked in v4.8.3';end if;
 end loop;
 return public.sales_return_create_v481(p_tenant_id,p_sale_id,p_items,p_reason,p_device_id,p_request_id);
end$$;


--
-- Name: sales_update_metadata(uuid, uuid, uuid, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_update_metadata(p_tenant_id uuid, p_sale_id uuid, p_customer_id uuid, p_due_date date, p_notes text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_before jsonb; v_after jsonb; v_number text;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  if not private.erp_has_permission(p_tenant_id,'sales.edit') and not private.erp_has_permission(p_tenant_id,'sales.manage') then raise exception 'Permission denied'; end if;
  select to_jsonb(s),s.sale_number into v_before,v_number from public.sales s where s.id=p_sale_id and s.tenant_id=p_tenant_id for update;
  if v_before is null then raise exception 'Sale not found'; end if;
  if coalesce(v_before->>'status','') in ('cancelled','void') then raise exception 'Voided sale cannot be edited'; end if;
  if not exists(select 1 from public.customers c where c.id=p_customer_id and c.tenant_id=p_tenant_id and coalesce(c.status,'active')='active') then raise exception 'Invalid customer'; end if;
  update public.sales set customer_id=p_customer_id,due_date=p_due_date,notes=nullif(trim(p_notes),'') where id=p_sale_id and tenant_id=p_tenant_id;
  select to_jsonb(s) into v_after from public.sales s where s.id=p_sale_id;
  perform private.business_audit_write(p_tenant_id,'update_metadata','sale',p_sale_id,v_number,v_before,v_after);
  return jsonb_build_object('sale_id',p_sale_id,'sale_number',v_number);
end $$;


--
-- Name: sales_update_metadata_v32(uuid, uuid, uuid, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_update_metadata_v32(p_tenant_id uuid, p_sale_id uuid, p_customer_id uuid, p_due_date date, p_notes text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_loc uuid;begin
  select location_id into v_loc from public.document_origins where entity_type='sale' and entity_id=p_sale_id and tenant_id=p_tenant_id;
  if not private.erp_document_scope_allowed(p_tenant_id,v_loc,null,'operate') then raise exception 'Location access denied';end if;
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'sales.edit') then raise exception 'Sale edit permission denied';end if;
  perform public.sales_update_metadata(p_tenant_id,p_sale_id,p_customer_id,p_due_date,p_notes);
end $$;


--
-- Name: sales_void_v4(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_void_v4(p_tenant_id uuid, p_sale_id uuid, p_reason text, p_device_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_loc uuid;v_ref text;r record;begin
  if trim(coalesce(p_reason,''))='' then raise exception 'Void reason is required';end if;
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'sales.void') then raise exception 'Sales void permission required';end if;
  if exists(select 1 from public.sale_payments where sale_id=p_sale_id and amount<>0) then raise exception 'Paid sale cannot be voided directly. Use return/refund workflow.';end if;
  if exists(select 1 from public.sales_returns where sale_id=p_sale_id) then raise exception 'Sale with returns cannot be voided';end if;
  select o.location_id,s.sale_number into v_loc,v_ref from public.sales s join public.document_origins o on o.entity_type='sale' and o.entity_id=s.id where s.id=p_sale_id and s.tenant_id=p_tenant_id for update;
  if v_loc is null then raise exception 'Sale not found or has no branch origin';end if;perform private.v4_location_access(p_tenant_id,v_loc,'operate');
  for r in select si.variant_id,si.quantity,p.item_type from public.sale_items si join public.product_variants pv on pv.id=si.variant_id join public.products p on p.id=pv.product_id where si.sale_id=p_sale_id loop
    if r.item_type='stock' then perform public.inventory_adjust_stock(p_tenant_id,r.variant_id,r.quantity,'Void sale • '||v_ref);perform private.v4_location_stock_apply(p_tenant_id,v_loc,r.variant_id,r.quantity,'sale_return','sale',p_sale_id,v_ref,'Void • '||trim(p_reason),p_device_id,false);end if;
  end loop;
  update public.sales set status='void' where id=p_sale_id and tenant_id=p_tenant_id;
  insert into public.transaction_corrections(tenant_id,entity_type,entity_id,correction_type,reason,created_by) values(p_tenant_id,'sale',p_sale_id,'void',trim(p_reason),auth.uid());
end $$;


--
-- Name: sales_void_v47(uuid, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_void_v47(p_tenant_id uuid, p_sale_id uuid, p_reason text, p_device_id uuid, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v jsonb;begin v:=private.v47_request_existing(p_tenant_id,p_request_id,'sale.void');if v is not null then return v;end if;perform public.sales_void_v4(p_tenant_id,p_sale_id,p_reason,p_device_id);v:=jsonb_build_object('success',true,'sale_id',p_sale_id);return private.v47_request_complete(p_tenant_id,p_request_id,'sale.void',v);end$$;


--
-- Name: sales_void_v483(uuid, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sales_void_v483(p_tenant_id uuid, p_sale_id uuid, p_reason text, p_device_id uuid, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$begin
 if exists(select 1 from public.sale_items si where si.sale_id=p_sale_id and private.v483_tracking_mode(p_tenant_id,si.variant_id)<>'none') then raise exception 'Voiding a sale containing serial/batch products requires trace reversal and is blocked in v4.8.3';end if;
 return public.sales_void_v47(p_tenant_id,p_sale_id,p_reason,p_device_id,p_request_id);
end$$;


--
-- Name: selector_search_v495(uuid, text, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.selector_search_v495(p_tenant_id uuid, p_entity text, p_query text DEFAULT ''::text, p_location_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50) RETURNS TABLE(id uuid, label text, subtitle text, search_code text, match_rank integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare q text:=lower(trim(coalesce(p_query,''))); lim integer:=greatest(1,least(coalesce(p_limit,50),200));
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if p_entity='customer' then
    return query
    select c.id,c.name,
      concat_ws(' • ',nullif(c.tracking_code,''),nullif(c.phone,''),nullif(c.tax_number,''))::text,
      concat_ws(' ',c.name,c.tracking_code,c.phone,c.email,c.tax_number)::text,
      case when q='' then 0 when lower(c.name) like q||'%' or lower(coalesce(c.tracking_code,'')) like q||'%' or lower(coalesce(c.phone,'')) like q||'%' then 0 else 1 end
    from public.customers c where c.tenant_id=p_tenant_id and coalesce(c.status,'active')='active'
      and (q='' or lower(concat_ws(' ',c.name,c.tracking_code,c.phone,c.email,c.tax_number)) like '%'||q||'%')
    order by 5,c.name limit lim;
  elsif p_entity='supplier' then
    return query
    select s.id,s.name,
      concat_ws(' • ',nullif(s.tracking_code,''),nullif(s.phone,''),nullif(s.tax_number,''))::text,
      concat_ws(' ',s.name,s.tracking_code,s.phone,s.email,s.tax_number)::text,
      case when q='' then 0 when lower(s.name) like q||'%' or lower(coalesce(s.tracking_code,'')) like q||'%' or lower(coalesce(s.phone,'')) like q||'%' then 0 else 1 end
    from public.suppliers s where s.tenant_id=p_tenant_id and coalesce(s.status,'active')='active'
      and (q='' or lower(concat_ws(' ',s.name,s.tracking_code,s.phone,s.email,s.tax_number)) like '%'||q||'%')
    order by 5,s.name limit lim;
  elsif p_entity='product' then
    return query
    select pv.id,p.name,
      concat_ws(' • ',nullif(pv.sku,''),nullif(pv.barcode,''),nullif(pv.part_number,''))::text,
      concat_ws(' ',p.name,pv.name,pv.sku,pv.barcode,pv.part_number)::text,
      case when q='' then 0 when lower(p.name) like q||'%' or lower(coalesce(pv.sku,'')) like q||'%' or lower(coalesce(pv.barcode,'')) like q||'%' or lower(coalesce(pv.part_number,'')) like q||'%' then 0 else 1 end
    from public.product_variants pv join public.products p on p.id=pv.product_id
    where p.tenant_id=p_tenant_id
      and (q='' or lower(concat_ws(' ',p.name,pv.name,pv.sku,pv.barcode,pv.part_number)) like '%'||q||'%')
    order by 5,p.name,pv.sku limit lim;
  elsif p_entity='account' then
    return query
    select a.id,a.name,concat_ws(' • ',a.code,a.account_type)::text,concat_ws(' ',a.code,a.name,a.account_type)::text,
      case when q='' then 0 when lower(a.code) like q||'%' or lower(a.name) like q||'%' then 0 else 1 end
    from public.accounting_accounts a where a.tenant_id=p_tenant_id and a.active
      and (q='' or lower(concat_ws(' ',a.code,a.name,a.account_type)) like '%'||q||'%')
    order by 5,a.code limit lim;
  elsif p_entity='location' then
    return query
    select l.id,l.name,concat_ws(' • ',l.location_code,l.city,l.state)::text,concat_ws(' ',l.location_code,l.name,l.city,l.state,l.postal_code)::text,
      case when q='' then 0 when lower(l.location_code) like q||'%' or lower(l.name) like q||'%' then 0 else 1 end
    from public.business_locations l where l.tenant_id=p_tenant_id and l.active
      and (private.erp_user_is_owner(p_tenant_id) or private.erp_user_location_allowed(p_tenant_id,l.id,'view'))
      and (q='' or lower(concat_ws(' ',l.location_code,l.name,l.city,l.state,l.postal_code)) like '%'||q||'%')
    order by 5,l.location_code limit lim;
  else
    raise exception 'Unsupported selector entity %',p_entity;
  end if;
end $$;


--
-- Name: service_job_bill_v51(uuid, uuid, uuid, date, numeric, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_job_bill_v51(p_tenant_id uuid, p_job_id uuid, p_billing_variant_id uuid, p_due_date date, p_initial_payment numeric, p_payment_method text, p_payment_reference text, p_device_id uuid, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare j public.service_jobs%rowtype;v_tax numeric;v_item_type text;v_variant_status text;v_product_status text;v_expected numeric;v_result jsonb;v_sale_id uuid;v_sale_number text;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if not (private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'transport_service.create') or private.erp_has_permission(p_tenant_id,'transport_service.manage')) then raise exception 'Transport service permission required';end if;
  select * into j from public.service_jobs where id=p_job_id and tenant_id=p_tenant_id for update;
  if not found then raise exception 'Service job not found';end if;
  if j.sale_id is not null then raise exception 'Service job is already billed';end if;
  if j.status='cancelled' then raise exception 'Cancelled service job cannot be billed';end if;
  if j.customer_id is null then raise exception 'Assign a customer before billing';end if;
  if not private.erp_document_scope_allowed(p_tenant_id,j.location_id,j.location_id,'operate') then raise exception 'Location access denied';end if;
  select p.tax_rate,p.item_type,p.status,pv.status into v_tax,v_item_type,v_product_status,v_variant_status
  from public.product_variants pv join public.products p on p.id=pv.product_id and p.tenant_id=pv.tenant_id
  where pv.id=p_billing_variant_id and pv.tenant_id=p_tenant_id;
  if v_item_type is null or v_product_status<>'active' or v_variant_status<>'active' then raise exception 'Billing service item is invalid or inactive';end if;
  if v_item_type='stock' then raise exception 'Transport billing requires a Service or Non-stock item';end if;
  v_expected:=round(j.quantity*j.rate*(1+coalesce(v_tax,0)/100.0),2);
  if coalesce(p_initial_payment,0)<0 or coalesce(p_initial_payment,0)>v_expected+0.005 then raise exception 'Initial payment cannot exceed service invoice total';end if;
  if coalesce(p_initial_payment,0)>0 and lower(trim(coalesce(p_payment_method,''))) not in('cash','bank','card','upi','cheque','other') then raise exception 'Invalid payment method';end if;

  v_result:=public.sales_create_v481(
    p_tenant_id,j.customer_id,j.service_date,p_due_date,
    jsonb_build_array(jsonb_build_object('variant_id',p_billing_variant_id,'quantity',j.quantity,'unit_price',j.rate,'discount_amount',0,'tax_rate',coalesce(v_tax,0))),
    0,coalesce(p_initial_payment,0),case when coalesce(p_initial_payment,0)>0 then lower(trim(p_payment_method)) else 'credit' end,
    coalesce(p_payment_reference,''),'Transport service '||j.job_number||' • '||coalesce(j.tracking_code,''),j.location_id,p_device_id,p_request_id
  );
  v_sale_id:=nullif(v_result->>'sale_id','')::uuid;v_sale_number:=v_result->>'sale_number';
  if v_sale_id is null then raise exception 'Sale was not created';end if;
  update public.sale_items set pricing_source='service_job',pricing_metadata=coalesce(pricing_metadata,'{}'::jsonb)||jsonb_build_object('service_job_id',j.id,'service_job_number',j.job_number,'service_rate',j.rate)
  where sale_id=v_sale_id and variant_id=p_billing_variant_id;
  update public.service_jobs set sale_id=v_sale_id,status='completed',updated_at=now() where id=j.id;
  perform private.business_audit_write_v471(p_tenant_id,'service.job.bill','service_job',j.id,j.job_number,to_jsonb(j),jsonb_build_object('sale_id',v_sale_id,'sale_number',v_sale_number,'total',v_result->'grand_total'));
  return v_result||jsonb_build_object('job_id',j.id,'job_number',j.job_number,'service_total',j.total_amount,'billing_source','service_job_v51');
end $$;


--
-- Name: service_job_create(uuid, uuid, uuid, uuid, date, text, text, numeric, numeric, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_job_create(p_tenant_id uuid, p_location_id uuid, p_customer_id uuid, p_vehicle_id uuid, p_service_date date, p_from_location text, p_to_location text, p_distance_km numeric, p_quantity numeric, p_quantity_unit text, p_rate numeric, p_notes text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_id uuid:=gen_random_uuid();v_job text;v_tracking text;v_total numeric; begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;if not private.erp_has_permission(p_tenant_id,'transport_service.create') and not private.erp_has_permission(p_tenant_id,'transport_service.manage') then raise exception 'Permission denied'; end if;
  v_total:=round(coalesce(p_quantity,0)*coalesce(p_rate,0),2);
  insert into public.service_jobs(id,tenant_id,job_number,location_id,customer_id,vehicle_id,service_date,from_location,to_location,distance_km,quantity,quantity_unit,rate,total_amount,notes,created_by)
  values(v_id,p_tenant_id,'',p_location_id,p_customer_id,p_vehicle_id,coalesce(p_service_date,current_date),nullif(trim(p_from_location),''),nullif(trim(p_to_location),''),coalesce(p_distance_km,0),coalesce(p_quantity,0),nullif(trim(p_quantity_unit),''),coalesce(p_rate,0),v_total,nullif(trim(p_notes),''),auth.uid()) returning job_number,tracking_code into v_job,v_tracking;
  insert into public.document_origins(tenant_id,entity_type,entity_id,location_id,created_by) values(p_tenant_id,'service_job',v_id,p_location_id,auth.uid()) on conflict do nothing;
  return jsonb_build_object('job_id',v_id,'job_number',v_job,'tracking_code',v_tracking,'total_amount',v_total);
end $$;


--
-- Name: service_job_create_v32(uuid, uuid, uuid, uuid, date, text, text, numeric, numeric, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_job_create_v32(p_tenant_id uuid, p_location_id uuid, p_customer_id uuid, p_vehicle_id uuid, p_service_date date, p_from_location text, p_to_location text, p_distance_km numeric, p_quantity numeric, p_quantity_unit text, p_rate numeric, p_notes text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_vehicle_location uuid;
begin
  if not private.erp_document_scope_allowed(p_tenant_id,p_location_id,p_location_id,'operate') then
    raise exception 'You cannot create jobs for this store';
  end if;
  if p_vehicle_id is not null then
    select location_id into v_vehicle_location from public.service_vehicles where id=p_vehicle_id and tenant_id=p_tenant_id;
    if v_vehicle_location is null then raise exception 'Vehicle not found';end if;
    if v_vehicle_location is distinct from p_location_id then raise exception 'Choose a vehicle assigned to this store';end if;
  end if;
  return public.service_job_create(
    p_tenant_id,p_location_id,p_customer_id,p_vehicle_id,p_service_date,p_from_location,p_to_location,
    p_distance_km,p_quantity,p_quantity_unit,p_rate,p_notes
  );
end $$;


--
-- Name: service_job_link_sale(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_job_link_sale(p_tenant_id uuid, p_job_id uuid, p_sale_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;if not private.erp_has_permission(p_tenant_id,'transport_service.create') and not private.erp_has_permission(p_tenant_id,'transport_service.manage') then raise exception 'Permission denied'; end if;
  if not exists(select 1 from public.sales where id=p_sale_id and tenant_id=p_tenant_id) then raise exception 'Sale not found'; end if;
  update public.service_jobs set sale_id=p_sale_id,status='completed',updated_at=now() where id=p_job_id and tenant_id=p_tenant_id;
end $$;


--
-- Name: service_job_link_sale_by_reference(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_job_link_sale_by_reference(p_tenant_id uuid, p_job_id uuid, p_sale_number text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_sale_id uuid;begin
  select id into v_sale_id from public.sales where tenant_id=p_tenant_id and sale_number=p_sale_number;
  if v_sale_id is null then raise exception 'Sale not found';end if;
  perform public.service_job_link_sale(p_tenant_id,p_job_id,v_sale_id);
end $$;


--
-- Name: service_job_link_sale_by_reference_v32(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_job_link_sale_by_reference_v32(p_tenant_id uuid, p_job_id uuid, p_sale_number text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_job_location uuid;
  v_sale_id uuid;
  v_sale_location uuid;
begin
  select location_id into v_job_location from public.service_jobs where id=p_job_id and tenant_id=p_tenant_id;
  if v_job_location is null then raise exception 'Service job not found';end if;
  if not private.erp_document_scope_allowed(p_tenant_id,v_job_location,v_job_location,'operate') then
    raise exception 'Location access denied';
  end if;
  select s.id,o.location_id into v_sale_id,v_sale_location
  from public.sales s left join public.document_origins o on o.entity_type='sale' and o.entity_id=s.id
  where s.tenant_id=p_tenant_id and s.sale_number=p_sale_number;
  if v_sale_id is null then raise exception 'Sale not found';end if;
  if v_sale_location is null then
    if not private.erp_user_is_owner(p_tenant_id) then raise exception 'Legacy sale has no store origin';end if;
  elsif v_sale_location is distinct from v_job_location then
    raise exception 'Service job and sale must belong to the same store';
  end if;
  perform public.service_job_link_sale(p_tenant_id,p_job_id,v_sale_id);
end $$;


--
-- Name: service_job_link_sale_by_reference_v51(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_job_link_sale_by_reference_v51(p_tenant_id uuid, p_job_id uuid, p_sale_number text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare j public.service_jobs%rowtype;v_sale_id uuid;v_sale_location uuid;v_sale_customer uuid;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if not (private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'transport_service.create') or private.erp_has_permission(p_tenant_id,'transport_service.manage')) then raise exception 'Transport service permission required';end if;
  select * into j from public.service_jobs where id=p_job_id and tenant_id=p_tenant_id for update;
  if not found then raise exception 'Service job not found';end if;
  if j.sale_id is not null then raise exception 'Service job is already billed';end if;
  select s.id,o.location_id,s.customer_id into v_sale_id,v_sale_location,v_sale_customer
  from public.sales s left join public.document_origins o on o.tenant_id=s.tenant_id and o.entity_type='sale' and o.entity_id=s.id
  where s.tenant_id=p_tenant_id and s.sale_number=trim(p_sale_number) and s.status='posted';
  if v_sale_id is null then raise exception 'Posted sale not found';end if;
  if v_sale_location is distinct from j.location_id then raise exception 'Service job and sale must belong to the same store';end if;
  if j.customer_id is not null and v_sale_customer is distinct from j.customer_id then raise exception 'Sale customer does not match service job customer';end if;
  update public.service_jobs set sale_id=v_sale_id,status='completed',updated_at=now() where id=j.id;
  perform private.business_audit_write_v471(p_tenant_id,'service.job.link_sale','service_job',j.id,j.job_number,to_jsonb(j),jsonb_build_object('sale_id',v_sale_id,'sale_number',p_sale_number));
  return jsonb_build_object('success',true,'job_id',j.id,'sale_id',v_sale_id,'sale_number',trim(p_sale_number));
end $$;


--
-- Name: service_job_save_v51(uuid, uuid, uuid, uuid, uuid, date, text, text, numeric, numeric, text, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_job_save_v51(p_tenant_id uuid, p_job_id uuid, p_location_id uuid, p_customer_id uuid, p_vehicle_id uuid, p_service_date date, p_from_location text, p_to_location text, p_distance_km numeric, p_quantity numeric, p_quantity_unit text, p_rate numeric, p_notes text, p_status text DEFAULT 'planned'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_id uuid;v_job text;v_tracking text;v_total numeric;v_status text:=lower(coalesce(nullif(trim(p_status),''),'planned'));v_old public.service_jobs%rowtype;v_vehicle_location uuid;v_vehicle_active boolean;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if p_job_id is null then
    if not (private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'transport_service.create') or private.erp_has_permission(p_tenant_id,'transport_service.manage')) then raise exception 'Transport service create permission required';end if;
  else
    if not (private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'transport_service.manage')) then raise exception 'Transport service manage permission required';end if;
  end if;
  if v_status not in('planned','in_progress','completed','cancelled') then raise exception 'Invalid service job status';end if;
  if p_location_id is null or not exists(select 1 from public.business_locations where id=p_location_id and tenant_id=p_tenant_id and active) then raise exception 'Active store/location is required';end if;
  if not private.erp_document_scope_allowed(p_tenant_id,p_location_id,p_location_id,'operate') then raise exception 'Location access denied';end if;
  if p_customer_id is not null and not exists(select 1 from public.customers where id=p_customer_id and tenant_id=p_tenant_id and status='active') then raise exception 'Active customer not found';end if;
  if p_vehicle_id is not null then
    select location_id,active into v_vehicle_location,v_vehicle_active from public.service_vehicles where id=p_vehicle_id and tenant_id=p_tenant_id;
    if v_vehicle_location is null then raise exception 'Vehicle not found';end if;
    if not coalesce(v_vehicle_active,false) then raise exception 'Selected vehicle is inactive';end if;
    if v_vehicle_location is distinct from p_location_id then raise exception 'Choose a vehicle assigned to this store';end if;
  end if;
  if coalesce(p_distance_km,0)<0 then raise exception 'Distance cannot be negative';end if;
  if coalesce(p_quantity,0)<=0 then raise exception 'Quantity must be greater than zero';end if;
  if coalesce(p_rate,0)<0 then raise exception 'Rate cannot be negative';end if;
  if nullif(trim(coalesce(p_quantity_unit,'')),'') is null then raise exception 'Quantity unit is required';end if;
  v_total:=round(coalesce(p_quantity,0)*coalesce(p_rate,0),2);

  if p_job_id is not null then
    select * into v_old from public.service_jobs where id=p_job_id and tenant_id=p_tenant_id for update;
    if not found then raise exception 'Service job not found';end if;
    if v_old.sale_id is not null and (p_location_id is distinct from v_old.location_id or p_customer_id is distinct from v_old.customer_id or p_vehicle_id is distinct from v_old.vehicle_id or coalesce(p_quantity,0)<>v_old.quantity or coalesce(p_rate,0)<>v_old.rate) then raise exception 'Billed service jobs cannot change store, customer, vehicle, quantity or rate';end if;
    if v_old.sale_id is not null and v_status='cancelled' then raise exception 'Billed service job cannot be cancelled; reverse the linked sale first';end if;
  end if;

  if p_job_id is null then
    v_id:=gen_random_uuid();
    insert into public.service_jobs(id,tenant_id,job_number,location_id,customer_id,vehicle_id,service_date,from_location,to_location,distance_km,quantity,quantity_unit,rate,total_amount,notes,status,created_by)
    values(v_id,p_tenant_id,'',p_location_id,p_customer_id,p_vehicle_id,coalesce(p_service_date,current_date),nullif(trim(coalesce(p_from_location,'')),''),nullif(trim(coalesce(p_to_location,'')),''),coalesce(p_distance_km,0),p_quantity,trim(p_quantity_unit),p_rate,v_total,nullif(trim(coalesce(p_notes,'')),''),v_status,auth.uid())
    returning job_number,tracking_code into v_job,v_tracking;
    insert into public.document_origins(tenant_id,entity_type,entity_id,location_id,created_by) values(p_tenant_id,'service_job',v_id,p_location_id,auth.uid()) on conflict do nothing;
  else
    v_id:=p_job_id;
    update public.service_jobs set location_id=p_location_id,customer_id=p_customer_id,vehicle_id=p_vehicle_id,service_date=coalesce(p_service_date,service_date),from_location=nullif(trim(coalesce(p_from_location,'')),''),to_location=nullif(trim(coalesce(p_to_location,'')),''),distance_km=coalesce(p_distance_km,0),quantity=p_quantity,quantity_unit=trim(p_quantity_unit),rate=p_rate,total_amount=v_total,notes=nullif(trim(coalesce(p_notes,'')),''),status=v_status,updated_at=now()
    where id=v_id and tenant_id=p_tenant_id returning job_number,tracking_code into v_job,v_tracking;
    update public.document_origins set location_id=p_location_id where tenant_id=p_tenant_id and entity_type='service_job' and entity_id=v_id;
  end if;
  perform private.business_audit_write_v471(p_tenant_id,'service.job.save','service_job',v_id,v_job,case when p_job_id is null then null else to_jsonb(v_old) end,jsonb_build_object('location_id',p_location_id,'status',v_status,'total_amount',v_total));
  return jsonb_build_object('job_id',v_id,'job_number',v_job,'tracking_code',v_tracking,'total_amount',v_total,'status',v_status);
end $$;


--
-- Name: service_job_status_v51(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_job_status_v51(p_tenant_id uuid, p_job_id uuid, p_status text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare j public.service_jobs%rowtype;v_status text:=lower(trim(coalesce(p_status,'')));
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if not (private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'transport_service.create') or private.erp_has_permission(p_tenant_id,'transport_service.manage')) then raise exception 'Transport service permission required';end if;
  if v_status not in('planned','in_progress','completed','cancelled') then raise exception 'Invalid service job status';end if;
  select * into j from public.service_jobs where id=p_job_id and tenant_id=p_tenant_id for update;
  if not found then raise exception 'Service job not found';end if;
  if not private.erp_document_scope_allowed(p_tenant_id,j.location_id,j.location_id,'operate') then raise exception 'Location access denied';end if;
  if j.sale_id is not null and v_status='cancelled' then raise exception 'Billed service job cannot be cancelled; reverse the linked sale first';end if;
  update public.service_jobs set status=case when sale_id is not null then 'completed' else v_status end,updated_at=now() where id=p_job_id;
  perform private.business_audit_write_v471(p_tenant_id,'service.job.status','service_job',p_job_id,j.job_number,to_jsonb(j),jsonb_build_object('status',case when j.sale_id is not null then 'completed' else v_status end));
  return jsonb_build_object('success',true,'job_id',p_job_id,'status',case when j.sale_id is not null then 'completed' else v_status end);
end $$;


--
-- Name: service_jobs_list(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_jobs_list(p_tenant_id uuid, p_limit integer DEFAULT 300) RETURNS TABLE(id uuid, tracking_code text, job_number text, service_date date, location_id uuid, location_name text, customer_id uuid, customer_name text, vehicle_id uuid, registration_number text, from_location text, to_location text, distance_km numeric, quantity numeric, quantity_unit text, rate numeric, total_amount numeric, notes text, status text, sale_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  return query select j.id,j.tracking_code,j.job_number,j.service_date,j.location_id,l.name,j.customer_id,c.name,j.vehicle_id,v.registration_number,j.from_location,j.to_location,j.distance_km,j.quantity,j.quantity_unit,j.rate,j.total_amount,j.notes,j.status,j.sale_id
  from public.service_jobs j left join public.business_locations l on l.id=j.location_id left join public.customers c on c.id=j.customer_id left join public.service_vehicles v on v.id=j.vehicle_id
  where j.tenant_id=p_tenant_id order by j.service_date desc,j.created_at desc limit greatest(1,least(coalesce(p_limit,300),2000));
end $$;


--
-- Name: service_jobs_list_v32(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_jobs_list_v32(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 300) RETURNS TABLE(id uuid, tracking_code text, job_number text, service_date date, location_id uuid, location_name text, customer_id uuid, customer_name text, vehicle_id uuid, registration_number text, from_location text, to_location text, distance_km numeric, quantity numeric, quantity_unit text, rate numeric, total_amount numeric, notes text, status text, sale_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if not (private.erp_user_is_owner(p_tenant_id)
          or private.erp_has_permission(p_tenant_id,'transport_service.view')
          or private.erp_has_permission(p_tenant_id,'transport_service.create')
          or private.erp_has_permission(p_tenant_id,'transport_service.manage')) then
    raise exception 'Permission denied';
  end if;
  if p_location_id is not null and not private.erp_document_scope_allowed(p_tenant_id,p_location_id,p_location_id,'view') then
    raise exception 'Location access denied';
  end if;
  return query
  select j.id,j.tracking_code,j.job_number,j.service_date,j.location_id,l.name,j.customer_id,c.name,
         j.vehicle_id,v.registration_number,j.from_location,j.to_location,j.distance_km,j.quantity,
         j.quantity_unit,j.rate,j.total_amount,j.notes,j.status,j.sale_id
  from public.service_jobs j
  left join public.business_locations l on l.id=j.location_id
  left join public.customers c on c.id=j.customer_id
  left join public.service_vehicles v on v.id=j.vehicle_id
  where j.tenant_id=p_tenant_id
    and private.erp_document_scope_allowed(p_tenant_id,j.location_id,p_location_id,'view')
  order by j.service_date desc,j.created_at desc
  limit greatest(1,least(coalesce(p_limit,300),2000));
end $$;


--
-- Name: service_jobs_list_v51(uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_jobs_list_v51(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 500) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if not (private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'transport_service.view') or private.erp_has_permission(p_tenant_id,'transport_service.create') or private.erp_has_permission(p_tenant_id,'transport_service.manage')) then raise exception 'Permission denied';end if;
  return query
  select jsonb_build_object(
    'id',j.id,'tracking_code',j.tracking_code,'job_number',j.job_number,'service_date',j.service_date,'status',j.status,
    'location_id',j.location_id,'location_name',l.name,'customer_id',j.customer_id,'customer_name',c.name,'customer_phone',c.phone,
    'vehicle_id',j.vehicle_id,'registration_number',v.registration_number,'vehicle_type',v.vehicle_type,'driver_name',v.driver_name,
    'from_location',j.from_location,'to_location',j.to_location,'distance_km',j.distance_km,'quantity',j.quantity,'quantity_unit',j.quantity_unit,
    'rate',j.rate,'total_amount',j.total_amount,'notes',j.notes,'sale_id',j.sale_id,'sale_number',s.sale_number,'sale_status',s.status,
    'created_at',j.created_at,'updated_at',j.updated_at
  )
  from public.service_jobs j
  left join public.business_locations l on l.id=j.location_id and l.tenant_id=j.tenant_id
  left join public.customers c on c.id=j.customer_id and c.tenant_id=j.tenant_id
  left join public.service_vehicles v on v.id=j.vehicle_id and v.tenant_id=j.tenant_id
  left join public.sales s on s.id=j.sale_id and s.tenant_id=j.tenant_id
  where j.tenant_id=p_tenant_id
    and private.erp_document_scope_allowed(p_tenant_id,j.location_id,p_location_id,'view')
    and (p_status is null or trim(p_status)='' or j.status=lower(trim(p_status)))
  order by j.service_date desc,j.created_at desc
  limit greatest(1,least(coalesce(p_limit,500),2000));
end $$;


--
-- Name: service_vehicle_save(uuid, uuid, text, text, text, numeric, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_vehicle_save(p_tenant_id uuid, p_vehicle_id uuid, p_registration_number text, p_vehicle_type text, p_make_model text, p_capacity numeric, p_capacity_unit text, p_driver_name text, p_driver_phone text, p_active boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_id uuid; begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;if not private.erp_has_permission(p_tenant_id,'transport_service.manage') then raise exception 'Permission denied'; end if;
  if p_vehicle_id is null then insert into public.service_vehicles(tenant_id,registration_number,vehicle_type,make_model,capacity,capacity_unit,driver_name,driver_phone,active) values(p_tenant_id,upper(trim(p_registration_number)),nullif(trim(p_vehicle_type),''),nullif(trim(p_make_model),''),p_capacity,nullif(trim(p_capacity_unit),''),nullif(trim(p_driver_name),''),nullif(trim(p_driver_phone),''),coalesce(p_active,true)) returning id into v_id;
  else update public.service_vehicles set registration_number=upper(trim(p_registration_number)),vehicle_type=nullif(trim(p_vehicle_type),''),make_model=nullif(trim(p_make_model),''),capacity=p_capacity,capacity_unit=nullif(trim(p_capacity_unit),''),driver_name=nullif(trim(p_driver_name),''),driver_phone=nullif(trim(p_driver_phone),''),active=coalesce(p_active,true),updated_at=now() where id=p_vehicle_id and tenant_id=p_tenant_id returning id into v_id; end if;
  if v_id is null then raise exception 'Vehicle not found'; end if;return v_id;
end $$;


--
-- Name: service_vehicle_save_v32(uuid, uuid, uuid, text, text, text, numeric, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_vehicle_save_v32(p_tenant_id uuid, p_vehicle_id uuid, p_location_id uuid, p_registration_number text, p_vehicle_type text, p_make_model text, p_capacity numeric, p_capacity_unit text, p_driver_name text, p_driver_phone text, p_active boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_id uuid;
  v_old_location uuid;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if not private.erp_has_permission(p_tenant_id,'transport_service.manage') then raise exception 'Permission denied';end if;
  if p_location_id is null or not private.erp_document_scope_allowed(p_tenant_id,p_location_id,p_location_id,'operate') then
    raise exception 'Location access denied';
  end if;
  if p_vehicle_id is not null then
    select location_id into v_old_location from public.service_vehicles where id=p_vehicle_id and tenant_id=p_tenant_id;
    if v_old_location is null then raise exception 'Vehicle not found';end if;
    if not private.erp_document_scope_allowed(p_tenant_id,v_old_location,v_old_location,'operate') then
      raise exception 'You cannot edit this vehicle';
    end if;
  end if;

  if p_vehicle_id is null then
    insert into public.service_vehicles(
      tenant_id,location_id,registration_number,vehicle_type,make_model,capacity,
      capacity_unit,driver_name,driver_phone,active
    ) values(
      p_tenant_id,p_location_id,upper(trim(p_registration_number)),nullif(trim(p_vehicle_type),''),
      nullif(trim(p_make_model),''),p_capacity,nullif(trim(p_capacity_unit),''),
      nullif(trim(p_driver_name),''),nullif(trim(p_driver_phone),''),coalesce(p_active,true)
    ) returning id into v_id;
  else
    update public.service_vehicles
    set location_id=p_location_id,registration_number=upper(trim(p_registration_number)),
        vehicle_type=nullif(trim(p_vehicle_type),''),make_model=nullif(trim(p_make_model),''),
        capacity=p_capacity,capacity_unit=nullif(trim(p_capacity_unit),''),
        driver_name=nullif(trim(p_driver_name),''),driver_phone=nullif(trim(p_driver_phone),''),
        active=coalesce(p_active,true),updated_at=now()
    where id=p_vehicle_id and tenant_id=p_tenant_id
    returning id into v_id;
  end if;
  if v_id is null then raise exception 'Vehicle not found';end if;
  perform private.business_audit_write(p_tenant_id,'save','service_vehicle',v_id,null,null,
    jsonb_build_object('location_id',p_location_id,'registration_number',p_registration_number));
  return v_id;
end $$;


--
-- Name: service_vehicle_save_v51(uuid, uuid, uuid, text, text, text, numeric, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_vehicle_save_v51(p_tenant_id uuid, p_vehicle_id uuid, p_location_id uuid, p_registration_number text, p_vehicle_type text, p_make_model text, p_capacity numeric, p_capacity_unit text, p_driver_name text, p_driver_phone text, p_active boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_id uuid;v_old public.service_vehicles%rowtype;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if not (private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'transport_service.manage')) then raise exception 'Transport service manage permission required';end if;
  if nullif(trim(coalesce(p_registration_number,'')),'') is null then raise exception 'Registration number is required';end if;
  if coalesce(p_capacity,0)<0 then raise exception 'Capacity cannot be negative';end if;
  if p_location_id is null or not exists(select 1 from public.business_locations l where l.id=p_location_id and l.tenant_id=p_tenant_id and l.active) then raise exception 'Active store/location is required';end if;
  if not private.erp_document_scope_allowed(p_tenant_id,p_location_id,p_location_id,'operate') then raise exception 'Location access denied';end if;
  if exists(select 1 from public.service_vehicles x where x.tenant_id=p_tenant_id and upper(trim(x.registration_number))=upper(trim(p_registration_number)) and x.id is distinct from p_vehicle_id) then raise exception 'Vehicle registration number already exists';end if;

  if p_vehicle_id is not null then
    select * into v_old from public.service_vehicles where id=p_vehicle_id and tenant_id=p_tenant_id for update;
    if not found then raise exception 'Vehicle not found';end if;
    if not private.erp_document_scope_allowed(p_tenant_id,v_old.location_id,v_old.location_id,'operate') then raise exception 'You cannot edit this vehicle';end if;
    if not coalesce(p_active,true) and exists(select 1 from public.service_jobs j where j.tenant_id=p_tenant_id and j.vehicle_id=p_vehicle_id and j.status in('planned','in_progress')) then raise exception 'Complete or cancel open service jobs before deactivating this vehicle';end if;
  end if;

  if p_vehicle_id is null then
    insert into public.service_vehicles(tenant_id,location_id,registration_number,vehicle_type,make_model,capacity,capacity_unit,driver_name,driver_phone,active)
    values(p_tenant_id,p_location_id,upper(trim(p_registration_number)),nullif(trim(coalesce(p_vehicle_type,'')),''),nullif(trim(coalesce(p_make_model,'')),''),coalesce(p_capacity,0),nullif(trim(coalesce(p_capacity_unit,'')),''),nullif(trim(coalesce(p_driver_name,'')),''),nullif(trim(coalesce(p_driver_phone,'')),''),coalesce(p_active,true))
    returning id into v_id;
  else
    update public.service_vehicles set location_id=p_location_id,registration_number=upper(trim(p_registration_number)),vehicle_type=nullif(trim(coalesce(p_vehicle_type,'')),''),make_model=nullif(trim(coalesce(p_make_model,'')),''),capacity=coalesce(p_capacity,0),capacity_unit=nullif(trim(coalesce(p_capacity_unit,'')),''),driver_name=nullif(trim(coalesce(p_driver_name,'')),''),driver_phone=nullif(trim(coalesce(p_driver_phone,'')),''),active=coalesce(p_active,true),updated_at=now()
    where id=p_vehicle_id and tenant_id=p_tenant_id returning id into v_id;
  end if;
  perform private.business_audit_write_v471(p_tenant_id,'service.vehicle.save','service_vehicle',v_id,upper(trim(p_registration_number)),case when p_vehicle_id is null then null else to_jsonb(v_old) end,jsonb_build_object('location_id',p_location_id,'active',coalesce(p_active,true)));
  return v_id;
end $$;


--
-- Name: service_vehicles; Type: TABLE; Schema: public; Owner: -
