    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;


--
-- Name: stock_adjustment_request_v500(uuid, uuid, uuid, uuid, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_adjustment_request_v500(p_tenant_id uuid, p_location_id uuid, p_device_id uuid, p_variant_id uuid, p_quantity_delta numeric, p_note text, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v public.stock_adjustment_requests_v500%rowtype;v_ap uuid;begin if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;perform private.v4_location_access(p_tenant_id,p_location_id,'operate');if coalesce(p_quantity_delta,0)=0 then raise exception 'Adjustment quantity cannot be zero';end if;if trim(coalesce(p_note,''))='' then raise exception 'Adjustment reason is required';end if;if trim(coalesce(p_request_id,''))='' then raise exception 'Request ID is required';end if;if private.v483_tracking_mode(p_tenant_id,p_variant_id)<>'none' then raise exception 'Use serial/batch trace operations for tracked products';end if;if not exists(select 1 from public.product_variants where id=p_variant_id and tenant_id=p_tenant_id and status='active') then raise exception 'Active product variant not found';end if;select * into v from public.stock_adjustment_requests_v500 where tenant_id=p_tenant_id and request_key=p_request_id;if found then return jsonb_build_object('adjustment_request_id',v.id,'approval_request_id',v.approval_request_id,'status',v.status,'result',v.result);end if;insert into public.stock_adjustment_requests_v500(tenant_id,location_id,device_id,variant_id,quantity_delta,note,request_key,requested_by) values(p_tenant_id,p_location_id,p_device_id,p_variant_id,p_quantity_delta,trim(p_note),trim(p_request_id),auth.uid()) returning * into v;insert into public.approval_requests(tenant_id,module_key,action_key,entity_type,entity_id,amount,reason,requested_by) values(p_tenant_id,'inventory','stock_adjustment','stock_adjustment_v500',v.id,abs(p_quantity_delta),trim(p_note),auth.uid()) returning id into v_ap;update public.stock_adjustment_requests_v500 set approval_request_id=v_ap where id=v.id;return jsonb_build_object('adjustment_request_id',v.id,'approval_request_id',v_ap,'status','pending','message','Stock adjustment submitted for approval');end $$;


--
-- Name: stock_adjustments_list_v500(uuid, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_adjustments_list_v500(p_tenant_id uuid, p_status text DEFAULT NULL::text, p_location_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 500) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare r record;begin if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;for r in select s.*,p.name product_name,pv.sku,l.location_code,l.name location_name from public.stock_adjustment_requests_v500 s join public.product_variants pv on pv.id=s.variant_id join public.products p on p.id=pv.product_id left join public.business_locations l on l.id=s.location_id where s.tenant_id=p_tenant_id and (p_status is null or s.status=p_status) and (p_location_id is null or s.location_id=p_location_id) and (private.erp_user_is_owner(p_tenant_id) or private.erp_user_location_allowed(p_tenant_id,s.location_id,'view')) order by s.requested_at desc limit greatest(1,least(coalesce(p_limit,500),5000)) loop return next to_jsonb(r);end loop;return;end $$;


--
-- Name: stock_count_detail_v485(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_count_detail_v485(p_tenant_id uuid, p_count_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_loc uuid;v jsonb;
begin
  select location_id into v_loc from public.stock_counts where tenant_id=p_tenant_id and id=p_count_id;
  if v_loc is null then raise exception 'Stock count not found';end if;
  perform private.v4_location_access(p_tenant_id,v_loc,'view');
  select jsonb_build_object(
    'count',to_jsonb(c)||jsonb_build_object('location_name',l.location_code||' • '||l.name),
    'items',coalesce((select jsonb_agg(to_jsonb(i)||jsonb_build_object('product_name',p.name,'sku',pv.sku) order by p.name,pv.sku)
      from public.stock_count_items i join public.product_variants pv on pv.id=i.variant_id join public.products p on p.id=pv.product_id where i.count_id=c.id),'[]'::jsonb)
  ) into v from public.stock_counts c join public.business_locations l on l.id=c.location_id where c.tenant_id=p_tenant_id and c.id=p_count_id;
  return v;
end$$;


--
-- Name: stock_counts_list_v485(uuid, uuid, date, date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_counts_list_v485(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_limit integer DEFAULT 500) RETURNS TABLE(id uuid, count_number text, location_id uuid, location_name text, status text, reconciliation_status text, notes text, line_count bigint, total_system_quantity numeric, total_counted_quantity numeric, total_variance numeric, created_at timestamp with time zone, posted_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'inventory.stock_count') and not private.erp_has_permission(p_tenant_id,'inventory.manage') then raise exception 'Stock count permission required';end if;
  return query
  select c.id,c.count_number,c.location_id,l.location_code||' • '||l.name,c.status,c.reconciliation_status,c.notes,
    count(i.id),coalesce(sum(i.system_quantity),0),coalesce(sum(i.counted_quantity),0),coalesce(sum(i.variance),0),c.created_at,c.posted_at
  from public.stock_counts c join public.business_locations l on l.id=c.location_id left join public.stock_count_items i on i.count_id=c.id
  where c.tenant_id=p_tenant_id and (p_location_id is null or c.location_id=p_location_id)
    and (p_from is null or c.created_at::date>=p_from) and (p_to is null or c.created_at::date<=p_to)
    and (private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'locations.view_all') or private.erp_has_permission(p_tenant_id,'locations.manage_all') or private.erp_user_location_allowed(p_tenant_id,c.location_id,'view'))
  group by c.id,l.location_code,l.name order by c.created_at desc limit greatest(1,least(coalesce(p_limit,500),2000));
end$$;


--
-- Name: supplier_payables_intelligence_v480(uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supplier_payables_intelligence_v480(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_query text DEFAULT ''::text, p_limit integer DEFAULT 1000) RETURNS TABLE(supplier_id uuid, supplier_name text, phone text, total_outstanding numeric, current_amount numeric, days_1_30 numeric, days_31_60 numeric, days_61_90 numeric, days_90_plus numeric, open_invoice_count bigint, oldest_due_date date, last_purchase_date date, status text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare q text:='%'||lower(trim(coalesce(p_query,'')))||'%';
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  return query
  with legacy_open as (
    select p.supplier_id,p.purchase_date,coalesce(p.due_date,p.purchase_date) due_date,
      greatest(p.grand_total-coalesce(rt.returned,0)-coalesce(py.paid,0),0)::numeric balance
    from public.purchases p
    left join(select purchase_id,sum(amount) paid from public.purchase_payments group by purchase_id) py on py.purchase_id=p.id
    left join(select purchase_id,sum(grand_total) returned from public.purchase_returns where credit_status<>'waived' group by purchase_id) rt on rt.purchase_id=p.id
    left join public.document_origins o on o.tenant_id=p_tenant_id and o.entity_type='purchase' and o.entity_id=p.id
    where p.tenant_id=p_tenant_id and coalesce(p.status,'') not in('void','cancelled')
      and (p_location_id is null or o.location_id=p_location_id)
      and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view')
      and greatest(p.grand_total-coalesce(rt.returned,0)-coalesce(py.paid,0),0)>0.005
  ), v2_open as (
    select i.supplier_id,i.invoice_date as purchase_date,coalesce(i.due_date,i.invoice_date) due_date,
      greatest(i.balance_due,0)::numeric balance
    from public.purchase_invoices_v484 i
    where i.tenant_id=p_tenant_id and i.status in('posted','part_paid') and i.balance_due>0.005
      and (p_location_id is null or i.location_id=p_location_id)
      and private.erp_document_scope_allowed(p_tenant_id,i.location_id,p_location_id,'view')
  ), open_docs as (
    select * from legacy_open
    union all
    select * from v2_open
  ), agg as (
    select op.supplier_id,sum(op.balance)::numeric outstanding,count(*)::bigint cnt,min(op.due_date) oldest,max(op.purchase_date) last_purchase,
      coalesce(sum(op.balance) filter(where op.due_date>=current_date),0)::numeric current_amt,
      coalesce(sum(op.balance) filter(where op.due_date<current_date and op.due_date>=current_date-30),0)::numeric a1,
      coalesce(sum(op.balance) filter(where op.due_date<current_date-30 and op.due_date>=current_date-60),0)::numeric a2,
      coalesce(sum(op.balance) filter(where op.due_date<current_date-60 and op.due_date>=current_date-90),0)::numeric a3,
      coalesce(sum(op.balance) filter(where op.due_date<current_date-90),0)::numeric a4
    from open_docs op group by op.supplier_id
  )
  select s.id,s.name,coalesce(s.phone,''),coalesce(a.outstanding,0)::numeric,coalesce(a.current_amt,0)::numeric,coalesce(a.a1,0)::numeric,
    coalesce(a.a2,0)::numeric,coalesce(a.a3,0)::numeric,coalesce(a.a4,0)::numeric,coalesce(a.cnt,0),a.oldest,a.last_purchase,
    (case when coalesce(a.outstanding,0)<=0.005 then 'clear' when coalesce(a.a4,0)>0 then 'critical_overdue'
      when coalesce(a.a1,0)+coalesce(a.a2,0)+coalesce(a.a3,0)>0 then 'overdue' else 'current' end)::text
  from public.suppliers s left join agg a on a.supplier_id=s.id
  where s.tenant_id=p_tenant_id and coalesce(s.status,'active')='active'
    and (trim(coalesce(p_query,''))='' or lower(s.name) like q or lower(coalesce(s.phone,'')) like q)
  order by coalesce(a.a4,0) desc,coalesce(a.outstanding,0) desc,s.name
  limit greatest(1,least(coalesce(p_limit,1000),5000));
end $$;


--
-- Name: supplier_payment_create_v484(uuid, uuid, uuid, date, numeric, text, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supplier_payment_create_v484(p_tenant_id uuid, p_location_id uuid, p_supplier_id uuid, p_payment_date date, p_amount numeric, p_payment_method text, p_allocations jsonb DEFAULT '[]'::jsonb, p_reference_number text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_id uuid:=gen_random_uuid();v_no text;v_sum numeric:=0;x jsonb;v_invoice uuid;v_alloc numeric;i public.purchase_invoices_v484%rowtype;v_lines jsonb;begin
  perform private.purchasing_v484_access(p_tenant_id,p_location_id,true);
  if not exists(select 1 from public.suppliers where tenant_id=p_tenant_id and id=p_supplier_id and coalesce(status,'active')='active') then raise exception 'Supplier not found';end if;
  if coalesce(p_amount,0)<=0 then raise exception 'Payment amount must be positive';end if;if trim(coalesce(p_payment_method,''))='' then raise exception 'Payment method is required';end if;
  if jsonb_typeof(coalesce(p_allocations,'[]'::jsonb))<>'array' then raise exception 'Allocations must be an array';end if;
  for x in select value from jsonb_array_elements(coalesce(p_allocations,'[]'::jsonb)) loop
    v_invoice:=nullif(x->>'purchase_invoice_id','')::uuid;v_alloc:=coalesce(nullif(x->>'amount','')::numeric,0);if v_invoice is null or v_alloc<=0 then raise exception 'Each allocation requires an invoice and positive amount';end if;
    select * into i from public.purchase_invoices_v484 where tenant_id=p_tenant_id and id=v_invoice and supplier_id=p_supplier_id for update;if not found then raise exception 'Supplier invoice not found';end if;if i.status not in('posted','part_paid') then raise exception 'Invoice % is not open for payment',i.invoice_number;end if;if v_alloc-i.balance_due>0.005 then raise exception 'Allocation exceeds balance on invoice %',i.invoice_number;end if;v_sum:=v_sum+v_alloc;
  end loop;
  if v_sum-p_amount>0.005 then raise exception 'Allocated amount cannot exceed payment amount';end if;
  v_no:='SPAY-'||to_char(coalesce(p_payment_date,current_date),'YYMMDD')||'-'||lpad(nextval('public.supplier_payment_number_seq_v484')::text,6,'0');
  insert into public.supplier_payments_v484(id,tenant_id,location_id,supplier_id,payment_number,payment_date,amount,payment_method,reference_number,notes,created_by)
  values(v_id,p_tenant_id,p_location_id,p_supplier_id,v_no,coalesce(p_payment_date,current_date),p_amount,lower(trim(p_payment_method)),nullif(trim(coalesce(p_reference_number,'')),''),nullif(trim(coalesce(p_notes,'')),''),auth.uid());
  for x in select value from jsonb_array_elements(coalesce(p_allocations,'[]'::jsonb)) loop
    v_invoice:=(x->>'purchase_invoice_id')::uuid;v_alloc:=(x->>'amount')::numeric;
    insert into public.supplier_payment_allocations_v484(supplier_payment_id,purchase_invoice_id,amount) values(v_id,v_invoice,v_alloc);
    perform private.v484_refresh_invoice_payment_status(v_invoice);
  end loop;
  insert into public.supplier_ledger_entries_v484(tenant_id,supplier_id,location_id,entry_date,entry_type,source_id,reference_number,description,debit,credit,created_by)
  values(p_tenant_id,p_supplier_id,p_location_id,coalesce(p_payment_date,current_date),'supplier_payment',v_id,v_no,'Supplier payment'||case when v_sum<p_amount-0.005 then ' (includes unallocated credit)' else '' end,0,p_amount,auth.uid());
  v_lines:=jsonb_build_array(
    jsonb_build_object('account_id',private.v4_account_id(p_tenant_id,'accounts_payable'),'debit',p_amount,'credit',0,'party_type','supplier','party_id',p_supplier_id,'description','Supplier payable settlement'),
    jsonb_build_object('account_id',private.v4_payment_account(p_tenant_id,lower(trim(p_payment_method))),'debit',0,'credit',p_amount,'party_type','supplier','party_id',p_supplier_id,'description','Supplier payment')
  );
  perform private.v4_journal_create(p_tenant_id,p_location_id,coalesce(p_payment_date,current_date),'Supplier Payment '||v_no,'supplier_payment_v484',v_id,v_no,v_lines);
  perform private.thq_sync_bump_v480(p_tenant_id,'finance','supplier_payment',v_id::text,'post');
  return jsonb_build_object('success',true,'supplier_payment_id',v_id,'payment_number',v_no,'amount',p_amount,'allocated_amount',v_sum,'unallocated_amount',greatest(p_amount-v_sum,0));
end$$;


--
-- Name: supplier_payment_create_v490(uuid, uuid, uuid, date, numeric, text, jsonb, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supplier_payment_create_v490(p_tenant_id uuid, p_location_id uuid, p_supplier_id uuid, p_payment_date date, p_amount numeric, p_payment_method text, p_allocations jsonb DEFAULT '[]'::jsonb, p_reference_number text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_device_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v jsonb;v_payment uuid;v_no text;v_shift uuid;begin
  if p_device_id is not null and not exists(
    select 1 from public.business_devices d where d.id=p_device_id and d.tenant_id=p_tenant_id and d.location_id=p_location_id and d.status='active'
  ) then raise exception 'Invalid device for supplier payment location';end if;
  v:=public.supplier_payment_create_v484(p_tenant_id,p_location_id,p_supplier_id,p_payment_date,p_amount,p_payment_method,p_allocations,p_reference_number,p_notes);
  v_payment:=nullif(v->>'supplier_payment_id','')::uuid;v_no:=v->>'payment_number';
  if v_payment is not null and p_device_id is not null and lower(trim(coalesce(p_payment_method,'')))='cash' then
    select id into v_shift from public.cashier_shifts where tenant_id=p_tenant_id and device_id=p_device_id and status='open' order by opened_at desc limit 1;
    if v_shift is not null and not exists(select 1 from public.cash_drawer_movements where reference_type='supplier_payment_v490' and reference_id=v_payment) then
      insert into public.cash_drawer_movements(tenant_id,shift_id,movement_type,amount,reference_type,reference_id,reference_number,note,created_by)
      values(p_tenant_id,v_shift,'cash_out',-abs(p_amount),'supplier_payment_v490',v_payment,v_no,'Supplier cash payment',auth.uid());
    end if;
  end if;
  return v||jsonb_build_object('payment_engine','v4.9.0');
end $$;


--
-- Name: supplier_payment_list_v484(uuid, uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supplier_payment_list_v484(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_supplier_id uuid DEFAULT NULL::uuid, p_query text DEFAULT ''::text, p_limit integer DEFAULT 500) RETURNS TABLE(id uuid, payment_number text, payment_date date, supplier_id uuid, supplier_name text, location_id uuid, location_name text, amount numeric, allocated_amount numeric, unallocated_amount numeric, payment_method text, reference_number text, status text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare q text:='%'||lower(trim(coalesce(p_query,'')))||'%';begin
 perform private.purchasing_v484_permission(p_tenant_id,false);
 return query select p.id,p.payment_number,p.payment_date,p.supplier_id,s.name,p.location_id,l.name,p.amount,coalesce(sum(a.amount),0),greatest(p.amount-coalesce(sum(a.amount),0),0),p.payment_method,p.reference_number,p.status,p.created_at
 from public.supplier_payments_v484 p join public.suppliers s on s.id=p.supplier_id join public.business_locations l on l.id=p.location_id left join public.supplier_payment_allocations_v484 a on a.supplier_payment_id=p.id
 where p.tenant_id=p_tenant_id and (p_location_id is null or p.location_id=p_location_id) and (p_supplier_id is null or p.supplier_id=p_supplier_id) and private.erp_document_scope_allowed(p_tenant_id,p.location_id,p_location_id,'view')
 and (trim(coalesce(p_query,''))='' or lower(p.payment_number) like q or lower(s.name) like q or lower(coalesce(p.reference_number,'')) like q)
 group by p.id,s.name,l.name order by p.created_at desc limit greatest(1,least(coalesce(p_limit,500),2000));
end$$;


--
-- Name: supplier_payment_void_v490(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supplier_payment_void_v490(p_tenant_id uuid, p_supplier_payment_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare p public.supplier_payments_v484%rowtype;a record;v_device uuid;v_shift uuid;begin
  if nullif(trim(coalesce(p_reason,'')),'') is null then raise exception 'Void reason is required';end if;
  select * into p from public.supplier_payments_v484 where tenant_id=p_tenant_id and id=p_supplier_payment_id for update;
  if not found then raise exception 'Supplier payment not found';end if;
  perform private.purchasing_v484_access(p_tenant_id,p.location_id,true);
  if p.status='void' then return jsonb_build_object('success',true,'supplier_payment_id',p.id,'status','void','idempotent',true);end if;

  update public.supplier_payments_v484 set status='void',voided_by=auth.uid(),voided_at=now(),void_reason=trim(p_reason) where id=p.id;
  for a in select purchase_invoice_id from public.supplier_payment_allocations_v484 where supplier_payment_id=p.id loop
    perform private.v484_refresh_invoice_payment_status(a.purchase_invoice_id);
  end loop;
  update public.journal_entries set status='reversed'
  where tenant_id=p_tenant_id and source_type='supplier_payment_v484' and source_id=p.id and status='posted';
  insert into public.supplier_ledger_entries_v484(
    tenant_id,supplier_id,location_id,entry_date,entry_type,source_id,reference_number,description,debit,credit,created_by
  ) values(
    p_tenant_id,p.supplier_id,p.location_id,current_date,'void',p.id,p.payment_number,
    'Void supplier payment: '||trim(p_reason),p.amount,0,auth.uid()
  ) on conflict(tenant_id,entry_type,source_id) do nothing;

  select d.id into v_device
  from public.business_devices d join public.cashier_shifts s on s.device_id=d.id and s.tenant_id=p_tenant_id and s.status='open'
  where d.tenant_id=p_tenant_id and d.location_id=p.location_id and d.status='active'
    and exists(select 1 from public.cash_drawer_movements m where m.shift_id=s.id and m.reference_type='supplier_payment_v490' and m.reference_id=p.id)
  order by s.opened_at desc limit 1;
  if v_device is not null and lower(p.payment_method)='cash' then
    select id into v_shift from public.cashier_shifts where tenant_id=p_tenant_id and device_id=v_device and status='open' order by opened_at desc limit 1;
    if v_shift is not null and not exists(select 1 from public.cash_drawer_movements where reference_type='supplier_payment_void_v490' and reference_id=p.id) then
      insert into public.cash_drawer_movements(tenant_id,shift_id,movement_type,amount,reference_type,reference_id,reference_number,note,created_by)
      values(p_tenant_id,v_shift,'cash_in',abs(p.amount),'supplier_payment_void_v490',p.id,p.payment_number,'Supplier payment void: '||trim(p_reason),auth.uid());
    end if;
  end if;
  perform private.thq_sync_bump_v480(p_tenant_id,'finance','supplier_payment',p.id::text,'void');
  return jsonb_build_object('success',true,'supplier_payment_id',p.id,'payment_number',p.payment_number,'status','void');
end $$;


--
-- Name: supplier_performance_v500(uuid, date, date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supplier_performance_v500(p_tenant_id uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_limit integer DEFAULT 500) RETURNS TABLE(supplier_id uuid, supplier_name text, purchase_value numeric, po_count bigint, grn_count bigint, accepted_qty numeric, damaged_qty numeric, rejected_qty numeric, damage_reject_pct numeric, on_time_pct numeric, avg_delivery_days numeric, last_purchase_date date)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin perform private.purchasing_v484_permission(p_tenant_id,false);
  return query with po as(select p.supplier_id,count(*) po_count,max(p.order_date) last_purchase,coalesce(sum(p.grand_total),0) value from public.purchase_orders_v480 p where p.tenant_id=p_tenant_id and p.status<>'cancelled' and (p_from is null or p.order_date>=p_from) and (p_to is null or p.order_date<=p_to) group by p.supplier_id),gr as(select g.supplier_id,count(distinct g.id) grn_count,coalesce(sum(i.accepted_quantity),0) accepted,coalesce(sum(i.damaged_quantity),0) damaged,coalesce(sum(i.rejected_quantity),0) rejected,avg(g.receipt_date-po2.order_date)::numeric avg_days,avg(case when po2.expected_date is null or g.receipt_date<=po2.expected_date then 100 else 0 end)::numeric ontime from public.goods_receipts_v484 g join public.goods_receipt_items_v484 i on i.goods_receipt_id=g.id join public.purchase_orders_v480 po2 on po2.id=g.purchase_order_id where g.tenant_id=p_tenant_id and g.status='posted' and (p_from is null or g.receipt_date>=p_from) and (p_to is null or g.receipt_date<=p_to) group by g.supplier_id) select s.id,s.name,coalesce(po.value,0)::numeric,coalesce(po.po_count,0),coalesce(gr.grn_count,0),coalesce(gr.accepted,0)::numeric,coalesce(gr.damaged,0)::numeric,coalesce(gr.rejected,0)::numeric,case when coalesce(gr.accepted,0)+coalesce(gr.damaged,0)+coalesce(gr.rejected,0)>0 then round((coalesce(gr.damaged,0)+coalesce(gr.rejected,0))*100/(coalesce(gr.accepted,0)+coalesce(gr.damaged,0)+coalesce(gr.rejected,0)),2) else 0 end::numeric,round(coalesce(gr.ontime,0),2)::numeric,round(coalesce(gr.avg_days,0),2)::numeric,po.last_purchase from public.suppliers s left join po on po.supplier_id=s.id left join gr on gr.supplier_id=s.id where s.tenant_id=p_tenant_id and coalesce(s.status,'active')='active' order by coalesce(po.value,0) desc,s.name limit greatest(1,least(coalesce(p_limit,500),5000));
end $$;


--
-- Name: suppliers_create(uuid, text, text, text, text, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.suppliers_create(p_tenant_id uuid, p_name text, p_contact_person text, p_phone text, p_email text, p_tax_number text, p_address_line1 text, p_address_line2 text, p_city text, p_state text, p_postal_code text, p_country text, p_notes text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_supplier_id uuid;

  v_tax_number text;
begin

  -- ----------------------------------------------------------
  -- PERMISSION
  -- ----------------------------------------------------------

  if not private.has_permission(
    p_tenant_id,
    'suppliers.manage'
  ) then

    raise exception 'Access denied'
      using errcode = '42501';

  end if;


  -- ----------------------------------------------------------
  -- TENANT
  -- ----------------------------------------------------------

  if not exists (
    select 1
    from public.tenants t

    where t.id = p_tenant_id
      and t.status = 'active'
  ) then

    raise exception
      'Business not found or inactive';

  end if;


  -- ----------------------------------------------------------
  -- VALIDATION
  -- ----------------------------------------------------------

  if nullif(
    trim(
      coalesce(
        p_name,
        ''
      )
    ),
    ''
  ) is null then

    raise exception
      'Supplier name is required';

  end if;


  v_tax_number :=
    nullif(
      upper(
        trim(
          coalesce(
            p_tax_number,
            ''
          )
        )
      ),
      ''
    );


  if v_tax_number is not null
     and exists (
       select 1

       from public.suppliers s

       where s.tenant_id = p_tenant_id
         and upper(s.tax_number) =
             v_tax_number
     ) then

    raise exception
      'A supplier with this Tax ID already exists';

  end if;


  -- ----------------------------------------------------------
  -- CREATE
  -- ----------------------------------------------------------

  insert into public.suppliers (
    tenant_id,

    name,

    contact_person,
    phone,
    email,

    tax_number,

    address_line1,
    address_line2,

    city,
    state,
    postal_code,

    country,

    notes,

    status,

    created_by
  )
  values (
    p_tenant_id,

    trim(p_name),

    nullif(
      trim(coalesce(p_contact_person, '')),
      ''
    ),

    nullif(
      trim(coalesce(p_phone, '')),
      ''
    ),

    nullif(
      lower(trim(coalesce(p_email, ''))),
      ''
    ),

    v_tax_number,

    nullif(
      trim(coalesce(p_address_line1, '')),
      ''
    ),

    nullif(
      trim(coalesce(p_address_line2, '')),
      ''
    ),

    nullif(
      trim(coalesce(p_city, '')),
      ''
    ),

    nullif(
      trim(coalesce(p_state, '')),
      ''
    ),

    nullif(
      trim(coalesce(p_postal_code, '')),
      ''
    ),

    coalesce(
      nullif(
        trim(coalesce(p_country, '')),
        ''
      ),
      'India'
    ),

    nullif(
      trim(coalesce(p_notes, '')),
      ''
    ),

    'active',

    auth.uid()
  )
  returning id
  into v_supplier_id;


  return v_supplier_id;

end;
$$;


--
-- Name: suppliers_get_statement(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.suppliers_get_statement(p_tenant_id uuid, p_supplier_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_name text; v_rows jsonb; v_debit numeric; v_credit numeric;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  select s.name into v_name from public.suppliers s where s.id=p_supplier_id and s.tenant_id=p_tenant_id;
  if v_name is null then raise exception 'Supplier not found'; end if;

  with raw as (
    select p.purchase_date::timestamp as ts, p.purchase_date as entry_date, 'purchase'::text as entry_type,
           p.purchase_number as reference, 'Purchase bill'::text as description,
           p.grand_total::numeric as debit, 0::numeric as credit
    from public.purchases p
    where p.tenant_id=p_tenant_id and p.supplier_id=p_supplier_id and coalesce(p.status,'') <> 'cancelled'
    union all
    select coalesce(pp.paid_at,pp.created_at) as ts, coalesce(pp.paid_at,pp.created_at)::date as entry_date,
           'payment'::text, p.purchase_number, 'Supplier payment'::text,
           0::numeric, pp.amount::numeric
    from public.purchase_payments pp join public.purchases p on p.id=pp.purchase_id
    where p.tenant_id=p_tenant_id and p.supplier_id=p_supplier_id
  ), running as (
    select *, sum(debit-credit) over(order by ts, entry_type, reference rows unbounded preceding) as balance
    from raw
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'entry_date',entry_date,'entry_type',entry_type,'reference',reference,'description',description,
      'debit',debit,'credit',credit,'balance',balance
    ) order by ts,entry_type,reference),'[]'::jsonb),
    coalesce(sum(debit),0),coalesce(sum(credit),0)
  into v_rows,v_debit,v_credit from running;

  return jsonb_build_object(
    'party_id',p_supplier_id,'party_name',v_name,'opening_balance',0,
    'total_debit',v_debit,'total_credit',v_credit,'closing_balance',v_debit-v_credit,'rows',v_rows
  );
end $$;


--
-- Name: suppliers_get_statement_v484(uuid, uuid, date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.suppliers_get_statement_v484(p_tenant_id uuid, p_supplier_id uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_name text;v_rows jsonb;v_debit numeric;v_credit numeric;begin
 perform private.purchasing_v484_permission(p_tenant_id,false);select name into v_name from public.suppliers where tenant_id=p_tenant_id and id=p_supplier_id;if v_name is null then raise exception 'Supplier not found';end if;
 with raw as (
   select p.purchase_date::timestamp as ts,p.purchase_date entry_date,'legacy_purchase'::text entry_type,p.purchase_number reference,'Legacy purchase bill'::text description,p.grand_total::numeric debit,0::numeric credit,o.location_id
   from public.purchases p left join public.document_origins o on o.entity_type='purchase' and o.entity_id=p.id and o.tenant_id=p.tenant_id where p.tenant_id=p_tenant_id and p.supplier_id=p_supplier_id and coalesce(p.status,'') not in('cancelled','void')
   union all
   select coalesce(pp.paid_at,pp.created_at),coalesce(pp.paid_at,pp.created_at)::date,'legacy_payment',p.purchase_number,'Legacy supplier payment',0::numeric,pp.amount::numeric,o.location_id
   from public.purchase_payments pp join public.purchases p on p.id=pp.purchase_id left join public.document_origins o on o.entity_type='purchase' and o.entity_id=p.id and o.tenant_id=p.tenant_id where p.tenant_id=p_tenant_id and p.supplier_id=p_supplier_id
   union all
   select e.created_at,e.entry_date,e.entry_type,e.reference_number,coalesce(e.description,''),e.debit,e.credit,e.location_id from public.supplier_ledger_entries_v484 e where e.tenant_id=p_tenant_id and e.supplier_id=p_supplier_id
 ), filtered as (
   select * from raw where (p_from is null or entry_date>=p_from) and (p_to is null or entry_date<=p_to) and (p_location_id is null or location_id=p_location_id) and (location_id is null or private.erp_document_scope_allowed(p_tenant_id,location_id,p_location_id,'view'))
 ), running as (
   select *,sum(debit-credit) over(order by ts,entry_type,reference rows unbounded preceding) balance from filtered
 )
 select coalesce(jsonb_agg(jsonb_build_object('entry_date',entry_date,'entry_type',entry_type,'reference',reference,'description',description,'debit',debit,'credit',credit,'balance',balance) order by ts,entry_type,reference),'[]'::jsonb),coalesce(sum(debit),0),coalesce(sum(credit),0) into v_rows,v_debit,v_credit from running;
 return jsonb_build_object('party_id',p_supplier_id,'party_name',v_name,'opening_balance',0,'total_debit',v_debit,'total_credit',v_credit,'closing_balance',v_debit-v_credit,'rows',v_rows);
end$$;


--
-- Name: suppliers_list(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.suppliers_list(p_tenant_id uuid) RETURNS TABLE(supplier_id uuid, supplier_name text, contact_person text, phone text, email text, tax_number text, address_line1 text, address_line2 text, city text, state text, postal_code text, country text, notes text, status text, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin

  if not (
    private.has_permission(
      p_tenant_id,
      'suppliers.view'
    )
    or
    private.has_permission(
      p_tenant_id,
      'suppliers.manage'
    )
  ) then

    raise exception 'Access denied'
      using errcode = '42501';

  end if;


  return query

  select
    s.id,

    s.name,

    s.contact_person,

    s.phone,

    s.email,

    s.tax_number,

    s.address_line1,
    s.address_line2,

    s.city,
    s.state,
    s.postal_code,
    s.country,

    s.notes,

    s.status,

    s.created_at,
    s.updated_at

  from public.suppliers s

  where s.tenant_id = p_tenant_id

  order by
    case
      when s.status = 'active'
        then 0
      else 1
    end,

    lower(s.name);

end;
$$;


--
-- Name: suppliers_list_v32(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.suppliers_list_v32(p_tenant_id uuid) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_row jsonb;v_id uuid;v_code text;
begin
  for v_row in select to_jsonb(x) from public.suppliers_list(p_tenant_id) x loop
    begin v_id:=coalesce(nullif(v_row->>'supplier_id',''),nullif(v_row->>'id',''))::uuid; exception when others then v_id:=null; end;
    if v_id is not null then select tracking_code into v_code from public.suppliers where tenant_id=p_tenant_id and id=v_id; end if;
    return next v_row || jsonb_build_object('tracking_code',v_code,'public_id',v_code);
  end loop;
  return;
end $$;


--
-- Name: suppliers_update(uuid, uuid, text, text, text, text, text, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.suppliers_update(p_tenant_id uuid, p_supplier_id uuid, p_name text, p_contact_person text, p_phone text, p_email text, p_tax_number text, p_address_line1 text, p_address_line2 text, p_city text, p_state text, p_postal_code text, p_country text, p_notes text, p_status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tax_number text;
begin

  -- ----------------------------------------------------------
  -- PERMISSION
  -- ----------------------------------------------------------

  if not private.has_permission(
    p_tenant_id,
    'suppliers.manage'
  ) then

    raise exception 'Access denied'
      using errcode = '42501';

  end if;


  -- ----------------------------------------------------------
  -- SUPPLIER
  -- ----------------------------------------------------------

  if not exists (
    select 1

    from public.suppliers s

    where s.id = p_supplier_id
      and s.tenant_id = p_tenant_id
  ) then

    raise exception 'Supplier not found';

  end if;


  -- ----------------------------------------------------------
  -- VALIDATION
  -- ----------------------------------------------------------

  if nullif(
    trim(
      coalesce(
        p_name,
        ''
      )
    ),
    ''
  ) is null then

    raise exception
      'Supplier name is required';

  end if;


  if p_status not in (
    'active',
    'inactive'
  ) then

    raise exception
      'Invalid supplier status';

  end if;


  v_tax_number :=
    nullif(
      upper(
        trim(
          coalesce(
            p_tax_number,
            ''
          )
        )
      ),
      ''
    );


  if v_tax_number is not null
     and exists (
       select 1

       from public.suppliers s

       where s.tenant_id = p_tenant_id
         and s.id <> p_supplier_id
         and upper(s.tax_number) =
             v_tax_number
     ) then

    raise exception
      'A supplier with this Tax ID already exists';

  end if;


  -- ----------------------------------------------------------
  -- UPDATE
  -- ----------------------------------------------------------

  update public.suppliers
  set
    name = trim(p_name),

    contact_person =
      nullif(
        trim(coalesce(p_contact_person, '')),
        ''
      ),

    phone =
      nullif(
        trim(coalesce(p_phone, '')),
        ''
      ),

    email =
      nullif(
        lower(trim(coalesce(p_email, ''))),
        ''
      ),

    tax_number =
      v_tax_number,

    address_line1 =
      nullif(
        trim(coalesce(p_address_line1, '')),
        ''
      ),

    address_line2 =
      nullif(
        trim(coalesce(p_address_line2, '')),
        ''
      ),

    city =
      nullif(
        trim(coalesce(p_city, '')),
        ''
      ),

    state =
      nullif(
        trim(coalesce(p_state, '')),
        ''
      ),

    postal_code =
      nullif(
        trim(coalesce(p_postal_code, '')),
        ''
      ),

    country =
      coalesce(
        nullif(
          trim(coalesce(p_country, '')),
          ''
        ),
        'India'
      ),

    notes =
      nullif(
        trim(coalesce(p_notes, '')),
        ''
      ),

    status = p_status

  where id = p_supplier_id
    and tenant_id = p_tenant_id;

end;
$$;


--
-- Name: support_ticket_create_v4(uuid, uuid, uuid, text, text, text, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.support_ticket_create_v4(p_tenant_id uuid, p_location_id uuid, p_device_id uuid, p_app_key text, p_app_version text, p_category text, p_priority text, p_subject text, p_description text, p_error_log_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_id uuid:=gen_random_uuid();v_no text;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;v_no:='SUP-'||lpad(nextval('public.support_ticket_number_seq')::text,7,'0');
  insert into public.support_tickets(id,tenant_id,location_id,device_id,user_id,ticket_number,app_key,app_version,category,priority,subject,description,error_log_id) values(v_id,p_tenant_id,p_location_id,p_device_id,auth.uid(),v_no,p_app_key,p_app_version,coalesce(nullif(trim(p_category),''),'general'),case when p_priority in('low','normal','high','urgent') then p_priority else 'normal' end,trim(p_subject),trim(p_description),p_error_log_id);
  return jsonb_build_object('ticket_id',v_id,'ticket_number',v_no,'status','open');
end $$;


--
-- Name: system_claim_activation_v47(text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.system_claim_activation_v47(p_business_code text, p_activation_hash text, p_installation_id text, p_app_key text, p_secret_hash text, p_platform_hint text DEFAULT NULL::text, p_app_version text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
declare d public.business_devices%rowtype;t public.tenants%rowtype;l public.business_locations%rowtype;v_installation uuid;
begin
  if nullif(trim(coalesce(p_business_code,'')),'') is null or nullif(trim(coalesce(p_activation_hash,'')),'') is null
     or nullif(trim(coalesce(p_installation_id,'')),'') is null or p_app_key not in('client','pos')
     or nullif(trim(coalesce(p_secret_hash,'')),'') is null then
    raise exception 'Invalid activation request';
  end if;

  select * into t from public.tenants where upper(business_code)=upper(trim(p_business_code));
  if not found then raise exception 'Invalid business or activation code';end if;

  select * into d
  from public.business_devices
  where tenant_id=t.id and app_type=p_app_key and status in('pending','inactive')
    and activation_hash=p_activation_hash
    and (activation_expires_at is null or activation_expires_at>=now())
  order by activation_issued_at desc nulls last,created_at desc
  limit 1 for update;
  if not found then raise exception 'Invalid or expired activation code';end if;

  if exists(select 1 from public.system_installations where installation_id=trim(p_installation_id) and status='active' and system_id<>d.id) then
    raise exception 'This installation is already registered to another system';
  end if;
  if exists(select 1 from public.business_devices where installation_id=trim(p_installation_id) and status='active' and id<>d.id) then
    raise exception 'This installation is already registered to another system';
  end if;

  update public.system_installations
  set status='inactive',deactivated_at=now(),deactivation_reason='Replaced by a new activation'
  where system_id=d.id and status='active';

  insert into public.system_installations(tenant_id,system_id,installation_id,secret_hash,status,platform_hint,app_version,activated_at,last_seen_at)
  values(t.id,d.id,trim(p_installation_id),p_secret_hash,'active',coalesce(nullif(trim(p_platform_hint),''),d.platform_hint),nullif(trim(coalesce(p_app_version,'')),''),now(),now())
  returning id into v_installation;

  update public.business_devices
  set status='active',installation_id=trim(p_installation_id),device_secret_hash=p_secret_hash,
      activation_hash=null,activation_expires_at=null,activated_at=now(),last_seen_at=now(),
      activation_count=coalesce(activation_count,0)+1,deactivated_at=null,deactivated_by=null,deactivation_reason=null,updated_at=now()
  where id=d.id;

  select * into l from public.business_locations where id=d.location_id;
  return jsonb_build_object(
    'success',true,'tenant_id',t.id,'tenant_name',t.name,'business_code',t.business_code,
    'device_id',d.id,'device_code',d.device_code,'device_name',d.name,'installation_record_id',v_installation,
    'location_id',l.id,'location_name',l.name,'location_code',l.location_code,'location_tracking_code',l.tracking_code
  );
end $$;


--
-- Name: system_health_summary_v47(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.system_health_summary_v47(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v_critical bigint;v_warning bigint;begin
  select coalesce(sum(issue_count) filter(where severity='critical'),0),coalesce(sum(issue_count) filter(where severity='warning'),0)
  into v_critical,v_warning from public.system_integrity_scan_v47(p_tenant_id);
  return jsonb_build_object('tenant_id',p_tenant_id,'schema',public.thq_backend_contract_v47(),'critical',v_critical,'warning',v_warning,'release_ready',v_critical=0,'checked_at',now());
end$$;


--
-- Name: system_installations_list_v47(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.system_installations_list_v47(p_tenant_id uuid, p_system_id uuid) RETURNS TABLE(id uuid, installation_id text, status text, platform_hint text, app_version text, activated_at timestamp with time zone, last_seen_at timestamp with time zone, deactivated_at timestamp with time zone, deactivation_reason text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$begin
  if not private.platform_v2_is_admin()
     and not private.erp_user_is_owner(p_tenant_id)
     and not private.erp_has_permission(p_tenant_id,'locations.manage') then raise exception 'Permission denied';end if;
  if not exists(select 1 from public.business_devices where id=p_system_id and tenant_id=p_tenant_id) then raise exception 'System not found';end if;
  return query select s.id,s.installation_id,s.status,s.platform_hint,s.app_version,s.activated_at,s.last_seen_at,s.deactivated_at,s.deactivation_reason
  from public.system_installations s where s.tenant_id=p_tenant_id and s.system_id=p_system_id order by s.activated_at desc;
end$$;


--
-- Name: system_integrity_scan_v47(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.system_integrity_scan_v47(p_tenant_id uuid) RETURNS TABLE(severity text, code text, issue_count bigint, description text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$begin
  if not private.platform_v2_is_admin() and not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;

  return query
  select 'critical'::text,'UNBALANCED_POSTED_JOURNAL'::text,count(*)::bigint,'Posted journal debit and credit totals do not match.'::text
  from (
    select j.id from public.journal_entries j join public.journal_lines l on l.journal_entry_id=j.id
    where j.tenant_id=p_tenant_id and j.status='posted' group by j.id having abs(sum(l.debit)-sum(l.credit))>0.01
  ) q;

  return query
  select 'critical','NEGATIVE_AVAILABLE_STOCK',count(*)::bigint,'Location available stock is below zero.'
  from public.location_stock_balances b where b.tenant_id=p_tenant_id and (coalesce(b.quantity,0)-coalesce(b.reserved_quantity,0)-coalesce(b.damaged_quantity,0)-coalesce(b.quarantine_quantity,0)) < -0.000001;

  return query
  select 'critical','SALE_WITHOUT_JOURNAL',count(*)::bigint,'Non-void sale has no posted sale journal.'
  from public.sales s where s.tenant_id=p_tenant_id and coalesce(s.status,'') not in('void','cancelled')
    and not exists(select 1 from public.journal_entries j where j.tenant_id=p_tenant_id and j.source_type='sale' and j.source_id=s.id and j.status='posted');

  return query
  select 'critical','PURCHASE_WITHOUT_JOURNAL',count(*)::bigint,'Non-void purchase has no posted purchase journal.'
  from public.purchases p where p.tenant_id=p_tenant_id and coalesce(p.status,'') not in('void','cancelled')
    and not exists(select 1 from public.journal_entries j where j.tenant_id=p_tenant_id and j.source_type='purchase' and j.source_id=p.id and j.status='posted');

  return query
  select 'critical','EXPENSE_WITHOUT_JOURNAL',count(*)::bigint,'Posted expense has no posted expense journal.'
  from public.expenses e where e.tenant_id=p_tenant_id and e.status='posted'
    and not exists(select 1 from public.journal_entries j where j.tenant_id=p_tenant_id and j.source_type='expense' and j.source_id=e.id and j.status='posted');

  return query
  select 'warning','SALE_WITHOUT_ORIGIN',count(*)::bigint,'Sale has no store/system origin record.'
  from public.sales s where s.tenant_id=p_tenant_id and not exists(select 1 from public.document_origins o where o.tenant_id=p_tenant_id and o.entity_type='sale' and o.entity_id=s.id);

  return query
  select 'warning','PURCHASE_WITHOUT_ORIGIN',count(*)::bigint,'Purchase has no store/system origin record.'
  from public.purchases p where p.tenant_id=p_tenant_id and not exists(select 1 from public.document_origins o where o.tenant_id=p_tenant_id and o.entity_type='purchase' and o.entity_id=p.id);

  return query
  select 'critical','ACTIVE_SYSTEM_WITHOUT_INSTALLATION',count(*)::bigint,'Active logical system does not have an active physical installation binding.'
  from public.business_devices d where d.tenant_id=p_tenant_id and d.status='active'
    and not exists(select 1 from public.system_installations si where si.system_id=d.id and si.status='active');

  return query
  select 'critical','INSTALLATION_BINDING_MISMATCH',count(*)::bigint,'Compatibility system binding and active installation history disagree.'
  from public.business_devices d join public.system_installations si on si.system_id=d.id and si.status='active'
  where d.tenant_id=p_tenant_id and (d.status<>'active' or coalesce(d.installation_id,'')<>coalesce(si.installation_id,''));

  return query
  select 'critical','SALE_OVERPAYMENT',count(*)::bigint,'Sale payments exceed the sale grand total.'
  from public.sales s where s.tenant_id=p_tenant_id and coalesce((select sum(sp.amount) from public.sale_payments sp where sp.sale_id=s.id),0) > s.grand_total+0.01;

  return query
  select 'critical','PURCHASE_OVERPAYMENT',count(*)::bigint,'Purchase payments exceed the purchase grand total.'
  from public.purchases p where p.tenant_id=p_tenant_id and coalesce((select sum(pp.amount) from public.purchase_payments pp where pp.purchase_id=p.id),0) > p.grand_total+0.01;
end $$;


--
-- Name: tenant_business_location_save(uuid, uuid, uuid, text, text, text, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_business_location_save(p_tenant_id uuid, p_location_id uuid, p_parent_location_id uuid, p_location_code text, p_name text, p_location_type text, p_phone text, p_email text, p_gstin text, p_invoice_prefix text, p_active boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_id uuid;begin
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'locations.manage') then raise exception 'Permission denied';end if;
  if trim(coalesce(p_name,''))='' then raise exception 'Location name required';end if;
  if p_location_id is null then
    insert into public.business_locations(tenant_id,parent_location_id,location_code,name,location_type,phone,email,gstin,invoice_prefix,active)
    values(p_tenant_id,p_parent_location_id,upper(trim(p_location_code)),trim(p_name),p_location_type,nullif(trim(p_phone),''),nullif(trim(p_email),''),nullif(trim(p_gstin),''),nullif(upper(trim(p_invoice_prefix)),''),coalesce(p_active,true)) returning id into v_id;
  else
    if not private.erp_user_location_allowed(p_tenant_id,p_location_id,'manage') and not private.erp_user_is_owner(p_tenant_id) then raise exception 'Location manage access denied';end if;
    update public.business_locations set parent_location_id=p_parent_location_id,location_code=upper(trim(p_location_code)),name=trim(p_name),location_type=p_location_type,phone=nullif(trim(p_phone),''),email=nullif(trim(p_email),''),gstin=nullif(trim(p_gstin),''),invoice_prefix=nullif(upper(trim(p_invoice_prefix)),''),active=coalesce(p_active,true),updated_at=now()
    where id=p_location_id and tenant_id=p_tenant_id returning id into v_id;
  end if;
  return v_id;
end $$;


--
-- Name: tenant_business_location_save_v4(uuid, uuid, uuid, text, text, text, text, text, text, text, text, text, text, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_business_location_save_v4(p_tenant_id uuid, p_location_id uuid, p_parent_location_id uuid, p_location_code text, p_name text, p_location_type text, p_phone text, p_email text, p_gstin text, p_address_line1 text, p_address_line2 text, p_city text, p_state text, p_postal_code text, p_country text, p_invoice_prefix text, p_logo_url text, p_active boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_id uuid;v_settings jsonb;
begin
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'locations.manage') then raise exception 'Permission denied';end if;
  if trim(coalesce(p_location_code,''))='' then raise exception 'Location code required';end if;
  if trim(coalesce(p_name,''))='' then raise exception 'Location name required';end if;
  if p_parent_location_id is not null and not exists(select 1 from public.business_locations where id=p_parent_location_id and tenant_id=p_tenant_id) then raise exception 'Invalid parent location';end if;
  v_settings:=jsonb_build_object('logo_url',nullif(trim(coalesce(p_logo_url,'')),''));
  if p_location_id is null then
    insert into public.business_locations(
      tenant_id,parent_location_id,location_code,name,location_type,phone,email,gstin,address_line1,address_line2,city,state,postal_code,country,invoice_prefix,settings,active
    ) values(
      p_tenant_id,p_parent_location_id,upper(trim(p_location_code)),trim(p_name),p_location_type,
      nullif(trim(coalesce(p_phone,'')),''),nullif(trim(coalesce(p_email,'')),''),nullif(upper(trim(coalesce(p_gstin,''))),''),
      nullif(trim(coalesce(p_address_line1,'')),''),nullif(trim(coalesce(p_address_line2,'')),''),nullif(trim(coalesce(p_city,'')),''),
      nullif(trim(coalesce(p_state,'')),''),nullif(trim(coalesce(p_postal_code,'')),''),coalesce(nullif(trim(coalesce(p_country,'')),''),'India'),
      nullif(upper(trim(coalesce(p_invoice_prefix,''))),''),v_settings,coalesce(p_active,true)
    ) returning id into v_id;
  else
    if not private.erp_user_location_allowed(p_tenant_id,p_location_id,'manage') and not private.erp_user_is_owner(p_tenant_id) then raise exception 'Location manage access denied';end if;
    update public.business_locations set
      parent_location_id=p_parent_location_id,location_code=upper(trim(p_location_code)),name=trim(p_name),location_type=p_location_type,
      phone=nullif(trim(coalesce(p_phone,'')),''),email=nullif(trim(coalesce(p_email,'')),''),gstin=nullif(upper(trim(coalesce(p_gstin,''))),''),
      address_line1=nullif(trim(coalesce(p_address_line1,'')),''),address_line2=nullif(trim(coalesce(p_address_line2,'')),''),city=nullif(trim(coalesce(p_city,'')),''),
      state=nullif(trim(coalesce(p_state,'')),''),postal_code=nullif(trim(coalesce(p_postal_code,'')),''),country=coalesce(nullif(trim(coalesce(p_country,'')),''),'India'),
      invoice_prefix=nullif(upper(trim(coalesce(p_invoice_prefix,''))),''),
      settings=coalesce(public.business_locations.settings,'{}'::jsonb)||v_settings,
      active=coalesce(p_active,true),updated_at=now()
    where id=p_location_id and tenant_id=p_tenant_id returning id into v_id;
  end if;
  if v_id is null then raise exception 'Location not found';end if;
  return v_id;
end $$;


--
-- Name: tenant_business_location_save_v42(uuid, uuid, uuid, text, text, text, text, integer, text, text, text, text, text, text, text, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_business_location_save_v42(p_tenant_id uuid, p_location_id uuid, p_parent_location_id uuid, p_location_code text, p_name text, p_location_type text, p_hierarchy_role text, p_sort_order integer, p_phone text, p_email text, p_gstin text, p_address_line1 text, p_address_line2 text, p_city text, p_state text, p_postal_code text, p_country text, p_invoice_prefix text, p_logo_url text, p_active boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_id uuid; v_role text:=lower(coalesce(nullif(trim(p_hierarchy_role),''),'child_store')); v_parent uuid:=p_parent_location_id;
begin
  if v_role not in('main_store','child_store','warehouse','operational') then raise exception 'Invalid location role';end if;
  if p_location_id is not null and exists(select 1 from public.business_locations where id=p_location_id and tenant_id=p_tenant_id and hierarchy_role='main_store') and v_role<>'main_store' then
    raise exception 'MAIN Store role cannot be changed';
  end if;
  if v_role='main_store' and exists(select 1 from public.business_locations where tenant_id=p_tenant_id and hierarchy_role='main_store' and id is distinct from p_location_id) then
    raise exception 'This business already has a MAIN Store';
  end if;
  if v_role='main_store' and not coalesce(p_active,true) then raise exception 'MAIN Store cannot be deactivated';end if;
  if v_role='main_store' then v_parent:=null; end if;
  v_id:=public.tenant_business_location_save_v4(
    p_tenant_id,p_location_id,v_parent,p_location_code,p_name,p_location_type,p_phone,p_email,p_gstin,
    p_address_line1,p_address_line2,p_city,p_state,p_postal_code,p_country,p_invoice_prefix,p_logo_url,p_active
  );
  update public.business_locations
  set hierarchy_role=v_role,sort_order=coalesce(p_sort_order,100),
      parent_location_id=case when v_role='main_store' then null else coalesce(v_parent,private.v42_main_location(p_tenant_id)) end,
      updated_at=now()
  where id=v_id and tenant_id=p_tenant_id;
  return v_id;
end $$;


--
-- Name: tenant_device_issue_activation(uuid, uuid, text, text, text, text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_device_issue_activation(p_tenant_id uuid, p_location_id uuid, p_name text, p_app_type text, p_platform_hint text DEFAULT NULL::text, p_module_keys text[] DEFAULT '{}'::text[], p_invoice_prefix text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$ declare v_id uuid:=gen_random_uuid();v_code text;v_device_code text;v_exp timestamptz:=now()+interval '24 hours';v_modules text[];begin
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'locations.manage') then raise exception 'Permission denied';end if;if not private.erp_user_location_allowed(p_tenant_id,p_location_id,'manage') and not private.erp_user_is_owner(p_tenant_id) then raise exception 'Location manage access denied';end if;if p_app_type not in('client','pos') then raise exception 'Invalid app type';end if;
  if p_app_type='pos' then select coalesce(array_agg(distinct x),'{}'::text[]) into v_modules from unnest(coalesce(p_module_keys,'{}'::text[]))x where x in('sales','inventory','customers','suppliers','purchases','expenses','restaurant','logs','cashier_shifts','notifications','tasks','support') and exists(select 1 from public.tenant_modules tm where tm.tenant_id=p_tenant_id and tm.module_key=x and tm.enabled);else v_modules:='{}'::text[];end if;
  if nullif(upper(trim(p_invoice_prefix)),'') is not null and exists(select 1 from public.business_devices d where d.tenant_id=p_tenant_id and d.status<>'revoked' and upper(coalesce(d.invoice_prefix,''))=upper(trim(p_invoice_prefix))) then raise exception 'Terminal invoice prefix is already in use';end if;
  v_code:=upper(substr(encode(gen_random_bytes(8),'hex'),1,12));v_device_code:=upper(p_app_type)||'-'||upper(substr(replace(v_id::text,'-',''),1,6));insert into public.business_devices(id,tenant_id,location_id,device_code,name,app_type,platform_hint,status,activation_hash,activation_expires_at,allowed_modules,invoice_prefix) values(v_id,p_tenant_id,p_location_id,v_device_code,trim(p_name),p_app_type,nullif(trim(p_platform_hint),''),'pending',encode(digest(v_code,'sha256'),'hex'),v_exp,v_modules,nullif(upper(trim(p_invoice_prefix)),''));return jsonb_build_object('device_id',v_id,'device_code',v_device_code,'activation_code',v_code,'expires_at',v_exp,'allowed_modules',v_modules);
end $$;


--
-- Name: tenant_device_revoke(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_device_revoke(p_tenant_id uuid, p_device_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_loc uuid;begin
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'locations.manage') then raise exception 'Permission denied';end if;
  select location_id into v_loc from public.business_devices where tenant_id=p_tenant_id and id=p_device_id;
  if v_loc is null then raise exception 'Device not found';end if;
  if not private.erp_user_location_allowed(p_tenant_id,v_loc,'manage') and not private.erp_user_is_owner(p_tenant_id) then raise exception 'Location manage access denied';end if;
  update public.business_devices set status='revoked',activation_hash=null,device_secret_hash=null,updated_at=now() where id=p_device_id and tenant_id=p_tenant_id;
end $$;


--
-- Name: tenant_device_settings_update(uuid, uuid, text[], text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_device_settings_update(p_tenant_id uuid, p_device_id uuid, p_module_keys text[], p_invoice_prefix text, p_name text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_loc uuid;v_type text;v_modules text[];begin
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'locations.manage') then raise exception 'Permission denied';end if;select location_id,app_type into v_loc,v_type from public.business_devices where tenant_id=p_tenant_id and id=p_device_id;if v_loc is null then raise exception 'Device not found';end if;if not private.erp_user_location_allowed(p_tenant_id,v_loc,'manage') and not private.erp_user_is_owner(p_tenant_id) then raise exception 'Location manage access denied';end if;
  if v_type='pos' then select coalesce(array_agg(distinct x),'{}'::text[]) into v_modules from unnest(coalesce(p_module_keys,'{}'::text[]))x where x in('sales','inventory','customers','suppliers','purchases','expenses','restaurant','logs','cashier_shifts','notifications','tasks','support') and exists(select 1 from public.tenant_modules tm where tm.tenant_id=p_tenant_id and tm.module_key=x and tm.enabled);else v_modules:='{}'::text[];end if;
  update public.business_devices set allowed_modules=v_modules,invoice_prefix=nullif(upper(trim(p_invoice_prefix)),''),name=coalesce(nullif(trim(p_name),''),name),updated_at=now() where id=p_device_id and tenant_id=p_tenant_id;
end $$;


--
-- Name: tenant_invoice_template_assign_v45(uuid, text, uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_invoice_template_assign_v45(p_tenant_id uuid, p_paper_type text, p_template_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_device_id uuid DEFAULT NULL::uuid, p_overrides jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_id uuid;
begin

  if not private.erp_user_is_owner(p_tenant_id)
     and not private.erp_has_permission(
       p_tenant_id,
       'settings.manage'
     ) then
    raise exception 'Settings permission required';
  end if;

  if p_location_id is not null
     and not exists(
       select 1
       from public.business_locations
       where id = p_location_id
         and tenant_id = p_tenant_id
     ) then
    raise exception 'Store does not belong to business';
  end if;

  if p_device_id is not null
     and not exists(
       select 1
       from public.business_devices
       where id = p_device_id
         and tenant_id = p_tenant_id
         and (
           p_location_id is null
           or location_id = p_location_id
         )
     ) then
    raise exception
      'Terminal does not belong to selected store';
  end if;

  if not exists(
    select 1
    from public.invoice_templates
    where id = p_template_id
      and paper_type = p_paper_type
      and is_active
      and (
        owner_tenant_id is null
        or owner_tenant_id = p_tenant_id
      )
  ) then
    raise exception 'Template not available';
  end if;

  select id
  into v_id
  from public.tenant_invoice_template_assignments_v45
  where tenant_id = p_tenant_id
    and paper_type = p_paper_type
    and location_id is not distinct from p_location_id
    and device_id is not distinct from p_device_id
  limit 1;

  if v_id is null then

    insert into
      public.tenant_invoice_template_assignments_v45(
        tenant_id,
        paper_type,
        template_id,
        location_id,
        device_id,
        overrides,
        updated_at,
        updated_by
      )
    values(
      p_tenant_id,
      p_paper_type,
      p_template_id,
      p_location_id,
      p_device_id,
      coalesce(p_overrides,'{}'::jsonb),
      now(),
      auth.uid()
    )
    returning id into v_id;

  else

    update public.tenant_invoice_template_assignments_v45
    set
      template_id = p_template_id,
      overrides = coalesce(p_overrides,'{}'::jsonb),
      is_active = true,
      updated_at = now(),
      updated_by = auth.uid()
    where id = v_id;

  end if;


  -- FIX same incorrect argument type.
  perform private.business_audit_write(
    p_tenant_id,
    'invoice_template.assign',
    'invoice_template',
    p_template_id,
    p_paper_type,
    null::jsonb,
    jsonb_build_object(
      'location_id',p_location_id,
      'device_id',p_device_id,
      'assignment_id',v_id
    )
  );

  return v_id;

end $$;


--
-- Name: tenant_invoice_template_clone_v45(uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_invoice_template_clone_v45(p_tenant_id uuid, p_source_template_id uuid, p_name text, p_paper_type text, p_config jsonb DEFAULT NULL::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare src public.invoice_templates%rowtype;v_id uuid;v_key text;begin
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'settings.manage') then raise exception 'Settings permission required';end if;
  if trim(coalesce(p_name,''))='' then raise exception 'Template name is required';end if;
  if p_paper_type not in('a4','80mm') then raise exception 'Invalid paper type';end if;
  select * into src from public.invoice_templates where id=p_source_template_id and is_active and (owner_tenant_id is null or owner_tenant_id=p_tenant_id);
  if not found then raise exception 'Source template not found';end if;
  v_key:='tenant_'||replace(p_tenant_id::text,'-','')||'_'||substr(replace(gen_random_uuid()::text,'-',''),1,10);
  insert into public.invoice_templates(key,name,paper_type,description,config,sample_logo_key,is_system,is_active,owner_tenant_id)
  values(v_key,trim(p_name),p_paper_type,'Custom THQ invoice template',coalesce(p_config,src.config),src.sample_logo_key,false,true,p_tenant_id)
  returning id into v_id;
  perform private.business_audit_write(p_tenant_id,'invoice_template.create','invoice_template',v_id,p_name,null,jsonb_build_object('source_template_id',p_source_template_id,'paper_type',p_paper_type));
  return v_id;
end $$;


--
-- Name: tenant_invoice_template_get(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_invoice_template_get(p_tenant_id uuid, p_paper_type text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v jsonb; begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  select jsonb_build_object('id',it.id,'key',it.key,'name',it.name,'paper_type',it.paper_type,'config',it.config || coalesce(tit.overrides,'{}'::jsonb),'sample_logo_key',it.sample_logo_key)
  into v from public.tenant_invoice_templates tit join public.invoice_templates it on it.id=tit.template_id where tit.tenant_id=p_tenant_id and tit.paper_type=p_paper_type;
  if v is null then select jsonb_build_object('id',id,'key',key,'name',name,'paper_type',paper_type,'config',config,'sample_logo_key',sample_logo_key) into v from public.invoice_templates where paper_type=p_paper_type and is_active order by is_system desc,name limit 1; end if;
  return coalesce(v,'{}'::jsonb);
end $$;


--
-- Name: tenant_invoice_template_get_v45(uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_invoice_template_get_v45(p_tenant_id uuid, p_paper_type text, p_location_id uuid DEFAULT NULL::uuid, p_device_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare a record;t record;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  select x.* into a from public.tenant_invoice_template_assignments_v45 x
  where x.tenant_id=p_tenant_id and x.paper_type=p_paper_type and x.is_active
    and (x.location_id is null or x.location_id=p_location_id)
    and (x.device_id is null or x.device_id=p_device_id)
  order by (x.device_id is not null) desc,(x.location_id is not null) desc,x.updated_at desc limit 1;
  if found then
    select * into t from public.invoice_templates where id=a.template_id and is_active;
    return jsonb_build_object('id',t.id,'key',t.key,'name',t.name,'paper_type',t.paper_type,'config',t.config||coalesce(a.overrides,'{}'::jsonb),'sample_logo_key',t.sample_logo_key,'assignment_id',a.id);
  end if;
  select it.*,tit.overrides as tenant_overrides into t
  from public.tenant_invoice_templates tit join public.invoice_templates it on it.id=tit.template_id
  where tit.tenant_id=p_tenant_id and tit.paper_type=p_paper_type and it.is_active;
  if found then
    return jsonb_build_object('id',t.id,'key',t.key,'name',t.name,'paper_type',t.paper_type,'config',t.config||coalesce(t.tenant_overrides,'{}'::jsonb),'sample_logo_key',t.sample_logo_key);
  end if;
  select * into t from public.invoice_templates where paper_type=p_paper_type and is_active and owner_tenant_id is null order by is_system desc,name limit 1;
  return coalesce(jsonb_build_object('id',t.id,'key',t.key,'name',t.name,'paper_type',t.paper_type,'config',t.config,'sample_logo_key',t.sample_logo_key),'{}'::jsonb);
end $$;


--
-- Name: tenant_invoice_template_save_v44(uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_invoice_template_save_v44(p_tenant_id uuid, p_paper_type text, p_template_id uuid, p_overrides jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'settings.manage') then raise exception 'Settings permission required';end if;
  if p_paper_type not in('a4','80mm') then raise exception 'Invalid paper type';end if;
  if not exists(select 1 from public.invoice_templates where id=p_template_id and paper_type=p_paper_type and is_active) then raise exception 'Invoice template not found';end if;
  insert into public.tenant_invoice_templates(tenant_id,paper_type,template_id,overrides,updated_at,updated_by)
  values(p_tenant_id,p_paper_type,p_template_id,coalesce(p_overrides,'{}'::jsonb),now(),auth.uid())
  on conflict(tenant_id,paper_type) do update set template_id=excluded.template_id,overrides=excluded.overrides,updated_at=now(),updated_by=auth.uid();
  perform private.business_audit_write(p_tenant_id,'invoice_template.save','invoice_template',p_template_id,p_paper_type,null,jsonb_build_object('paper_type',p_paper_type,'overrides',coalesce(p_overrides,'{}'::jsonb)));
end $$;


--
-- Name: tenant_invoice_template_save_v45(uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_invoice_template_save_v45(p_tenant_id uuid, p_paper_type text, p_template_id uuid, p_overrides jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v jsonb:=coalesce(p_overrides,'{}'::jsonb);begin
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'settings.manage') then raise exception 'Settings permission required';end if;
  if p_paper_type not in('a4','80mm') then raise exception 'Invalid paper type';end if;
  if not exists(select 1 from public.invoice_templates where id=p_template_id and paper_type=p_paper_type and is_active and (owner_tenant_id is null or owner_tenant_id=p_tenant_id)) then raise exception 'Invoice template not found';end if;
  insert into public.tenant_invoice_templates(tenant_id,paper_type,template_id,overrides,updated_at,updated_by)
  values(p_tenant_id,p_paper_type,p_template_id,v,now(),auth.uid())
  on conflict(tenant_id,paper_type) do update set template_id=excluded.template_id,overrides=excluded.overrides,updated_at=now(),updated_by=auth.uid();
  perform private.business_audit_write(p_tenant_id,'invoice_template.default','invoice_template',p_template_id,p_paper_type,null,jsonb_build_object('paper_type',p_paper_type,'overrides',v));
end $$;


--
-- Name: tenant_invoice_template_update_v45(uuid, uuid, text, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_invoice_template_update_v45(p_tenant_id uuid, p_template_id uuid, p_name text, p_config jsonb, p_is_active boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'settings.manage') then raise exception 'Settings permission required';end if;
  update public.invoice_templates set name=coalesce(nullif(trim(p_name),''),name),config=coalesce(p_config,config),is_active=p_is_active,updated_at=now()
  where id=p_template_id and owner_tenant_id=p_tenant_id;
  if not found then raise exception 'Only business-owned custom templates can be edited directly';end if;
  perform private.business_audit_write(p_tenant_id,'invoice_template.update','invoice_template',p_template_id,p_name,null,jsonb_build_object('active',p_is_active));
end $$;


--
-- Name: tenant_invoice_templates_list_v44(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_invoice_templates_list_v44(p_tenant_id uuid, p_paper_type text DEFAULT NULL::text) RETURNS TABLE(template_id uuid, template_key text, template_name text, paper_type text, description text, base_config jsonb, selected boolean, overrides jsonb, effective_config jsonb, sample_logo_key text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  return query
  select it.id,it.key::text,it.name::text,it.paper_type::text,it.description::text,it.config,
    (tit.template_id=it.id),coalesce(tit.overrides,'{}'::jsonb),it.config||coalesce(tit.overrides,'{}'::jsonb),it.sample_logo_key::text
  from public.invoice_templates it
  left join public.tenant_invoice_templates tit on tit.tenant_id=p_tenant_id and tit.paper_type=it.paper_type
  where it.is_active and (p_paper_type is null or it.paper_type=p_paper_type)
  order by it.paper_type,(tit.template_id=it.id) desc,it.is_system desc,it.name;
end $$;


--
-- Name: tenant_invoice_templates_list_v45(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_invoice_templates_list_v45(p_tenant_id uuid, p_paper_type text DEFAULT NULL::text) RETURNS TABLE(template_id uuid, template_key text, template_name text, paper_type text, description text, base_config jsonb, selected boolean, overrides jsonb, effective_config jsonb, sample_logo_key text, is_custom boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  return query
  select it.id,it.key::text,it.name::text,it.paper_type::text,it.description::text,it.config,
    (tit.template_id=it.id),coalesce(tit.overrides,'{}'::jsonb),it.config||coalesce(tit.overrides,'{}'::jsonb),it.sample_logo_key::text,
    (it.owner_tenant_id is not null)
  from public.invoice_templates it
  left join public.tenant_invoice_templates tit on tit.tenant_id=p_tenant_id and tit.paper_type=it.paper_type
  where it.is_active and (it.owner_tenant_id is null or it.owner_tenant_id=p_tenant_id)
    and (p_paper_type is null or it.paper_type=p_paper_type)
  order by it.paper_type,(tit.template_id=it.id) desc,(it.owner_tenant_id=p_tenant_id) desc,it.is_system desc,it.name;
end $$;


--
-- Name: tenant_locations_devices_list(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_locations_devices_list(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_all boolean;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  v_all:=private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'locations.view_all') or private.erp_has_permission(p_tenant_id,'locations.manage');
  return jsonb_build_object(
    'locations',coalesce((select jsonb_agg(jsonb_build_object('id',l.id,'parent_location_id',l.parent_location_id,'location_code',l.location_code,'tracking_code',l.tracking_code,'name',l.name,'location_type',l.location_type,'phone',l.phone,'email',l.email,'gstin',l.gstin,'invoice_prefix',l.invoice_prefix,'active',l.active) order by l.name)
      from public.business_locations l left join public.business_user_location_access a on a.tenant_id=p_tenant_id and a.user_id=auth.uid() and a.location_id=l.id
      where l.tenant_id=p_tenant_id and (v_all or a.user_id is not null)),'[]'::jsonb),
    'devices',coalesce((select jsonb_agg(jsonb_build_object('id',d.id,'location_id',d.location_id,'device_code',d.device_code,'tracking_code',d.tracking_code,'name',d.name,'app_type',d.app_type,'status',d.status,'allowed_modules',d.allowed_modules,'invoice_prefix',d.invoice_prefix,'last_seen_at',d.last_seen_at) order by d.created_at desc)
      from public.business_devices d join public.business_locations l on l.id=d.location_id left join public.business_user_location_access a on a.tenant_id=p_tenant_id and a.user_id=auth.uid() and a.location_id=l.id
      where d.tenant_id=p_tenant_id and (v_all or a.user_id is not null)),'[]'::jsonb)
  );
end $$;


--
-- Name: tenant_locations_devices_list_v42(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_locations_devices_list_v42(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare v_all boolean;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  v_all:=private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'locations.view_all') or private.erp_has_permission(p_tenant_id,'locations.manage') or private.erp_has_permission(p_tenant_id,'locations.manage_all');
  return jsonb_build_object(
    'locations',coalesce((select jsonb_agg(jsonb_build_object('id',l.id,'parent_location_id',l.parent_location_id,'location_code',l.location_code,'tracking_code',l.tracking_code,'name',l.name,'location_type',l.location_type,'hierarchy_role',l.hierarchy_role,'sort_order',l.sort_order,'phone',l.phone,'email',l.email,'gstin',l.gstin,'address_line1',l.address_line1,'address_line2',l.address_line2,'city',l.city,'state',l.state,'postal_code',l.postal_code,'country',l.country,'invoice_prefix',l.invoice_prefix,'settings',coalesce(l.settings,'{}'::jsonb),'active',l.active,'access_level',case when v_all then 'manage' else a.access_level end) order by case when l.hierarchy_role='main_store' then 0 when l.hierarchy_role='warehouse' then 2 else 1 end,l.sort_order,l.name) from public.business_locations l left join public.business_user_location_access a on a.tenant_id=p_tenant_id and a.user_id=auth.uid() and a.location_id=l.id where l.tenant_id=p_tenant_id and (v_all or a.user_id is not null)),'[]'::jsonb),
    'devices',coalesce((select jsonb_agg(jsonb_build_object('id',d.id,'location_id',d.location_id,'device_code',d.device_code,'tracking_code',d.tracking_code,'name',d.name,'app_type',d.app_type,'system_role',d.system_role,'platform_hint',d.platform_hint,'status',d.status,'allowed_modules',d.allowed_modules,'invoice_prefix',d.invoice_prefix,'activated_at',d.activated_at,'last_seen_at',d.last_seen_at,'settings',coalesce(d.settings,'{}'::jsonb)) order by d.created_at desc) from public.business_devices d join public.business_locations l on l.id=d.location_id left join public.business_user_location_access a on a.tenant_id=p_tenant_id and a.user_id=auth.uid() and a.location_id=l.id where d.tenant_id=p_tenant_id and (v_all or a.user_id is not null)),'[]'::jsonb)
  );
end $$;


--
-- Name: tenant_settings_v2_get(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_settings_v2_get(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_platform jsonb; v_tenant jsonb;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) and not private.platform_v2_is_admin() then raise exception 'Access denied'; end if;
  select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) into v_platform from public.platform_settings;
  select settings into v_tenant from public.tenant_settings_v2 where tenant_id=p_tenant_id;
  return coalesce(v_platform,'{}'::jsonb) || coalesce(v_tenant,'{}'::jsonb);
end $$;


--
-- Name: tenant_settings_v2_set(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_settings_v2_set(p_tenant_id uuid, p_settings jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  if not private.erp_has_permission(p_tenant_id,'settings.manage') then raise exception 'Permission denied'; end if;
  insert into public.tenant_settings_v2(tenant_id,settings,updated_by) values(p_tenant_id,coalesce(p_settings,'{}'::jsonb),auth.uid())
  on conflict(tenant_id) do update set settings=excluded.settings,updated_by=auth.uid(),updated_at=now();
end $$;


--
-- Name: tenant_system_create_v471(uuid, uuid, text, text, text, text[], text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_system_create_v471(p_tenant_id uuid, p_location_id uuid, p_name text, p_app_type text, p_platform_hint text DEFAULT NULL::text, p_module_keys text[] DEFAULT '{}'::text[], p_invoice_prefix text DEFAULT NULL::text, p_system_role text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
declare v_id uuid:=gen_random_uuid();v_code text;v_device_code text;v_exp timestamptz:=now()+interval '24 hours';v_modules text[]:='{}'::text[];v_prefix text;v_role text;
begin
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'locations.manage') and not private.erp_has_permission(p_tenant_id,'locations.manage_all') then raise exception 'Permission denied';end if;
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_user_location_allowed(p_tenant_id,p_location_id,'manage') then raise exception 'Location manage access denied';end if;
  if p_app_type not in('client','pos') then raise exception 'Invalid app type';end if;
  if not exists(select 1 from public.business_locations where id=p_location_id and tenant_id=p_tenant_id and active) then raise exception 'Target store/location is not active';end if;
  v_role:=coalesce(nullif(trim(p_system_role),''),case when p_app_type='pos' then 'pos' else 'office' end);
  if p_app_type='pos' and v_role<>'pos' then raise exception 'POS systems must use POS role';end if;
  if p_app_type='client' and v_role not in('back_office','office','inventory') then raise exception 'Invalid Client system role';end if;
  if p_app_type='pos' then
    select coalesce(array_agg(distinct x),'{}'::text[]) into v_modules from unnest(coalesce(p_module_keys,'{}'::text[])) x
    where x in('sales','inventory','customers','suppliers','purchases','expenses','restaurant','logs','cashier_shifts','notifications','tasks','support','terminal_day')
      and exists(select 1 from public.tenant_modules tm where tm.tenant_id=p_tenant_id and tm.module_key=x and tm.enabled);
    if coalesce(array_length(v_modules,1),0)=0 then raise exception 'Select at least one enabled POS module';end if;
    if nullif(upper(trim(coalesce(p_invoice_prefix,''))),'') is null then v_prefix:=private.v500_next_pos_invoice_prefix(p_tenant_id);
    else
      perform 1 from public.tenants where id=p_tenant_id for update;v_prefix:=upper(trim(p_invoice_prefix));
      if exists(select 1 from public.business_devices d where d.tenant_id=p_tenant_id and d.app_type='pos' and upper(trim(coalesce(d.invoice_prefix,'')))=v_prefix) then raise exception 'Terminal invoice prefix is already in use';end if;
    end if;
  else v_prefix:=null;end if;
  v_code:=upper(substr(encode(gen_random_bytes(8),'hex'),1,12));v_device_code:=upper(p_app_type)||'-'||upper(substr(replace(v_id::text,'-',''),1,8));
  insert into public.business_devices(id,tenant_id,location_id,device_code,name,app_type,platform_hint,status,activation_hash,activation_expires_at,activation_issued_at,activation_issued_by,allowed_modules,invoice_prefix,system_role,activation_count)
  values(v_id,p_tenant_id,p_location_id,v_device_code,coalesce(nullif(trim(p_name),''),'System'),p_app_type,nullif(trim(p_platform_hint),''),'pending',encode(digest(v_code,'sha256'),'hex'),v_exp,now(),auth.uid(),v_modules,v_prefix,v_role,1);
  perform private.business_audit_write_v471(p_tenant_id,'system.create','business_device',v_id,v_device_code,null::jsonb,jsonb_build_object('location_id',p_location_id,'app_type',p_app_type,'system_role',v_role,'modules',v_modules,'invoice_prefix',v_prefix));
  return jsonb_build_object('device_id',v_id,'device_code',v_device_code,'activation_code',v_code,'expires_at',v_exp,'location_id',p_location_id,'invoice_prefix',v_prefix,'allowed_modules',v_modules,'system_role',v_role);
end $$;


--
-- Name: tenant_system_revoke_v471(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_system_revoke_v471(p_tenant_id uuid, p_system_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$declare d public.business_devices%rowtype;begin
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'locations.manage') and not private.erp_has_permission(p_tenant_id,'locations.manage_all') then raise exception 'Permission denied';end if;
  select * into d from public.business_devices where id=p_system_id and tenant_id=p_tenant_id for update;if not found then raise exception 'System not found';end if;
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_user_location_allowed(p_tenant_id,d.location_id,'manage') then raise exception 'Location manage access denied';end if;
  if exists(select 1 from public.cashier_shifts where tenant_id=p_tenant_id and device_id=p_system_id and status='open') then raise exception 'Close the cashier shift before revoking this POS';end if;
  update public.system_installations set status='revoked',deactivated_at=coalesce(deactivated_at,now()),deactivation_reason=coalesce(nullif(trim(coalesce(p_reason,'')),''),'Revoked by business manager') where tenant_id=p_tenant_id and system_id=p_system_id and status<>'revoked';
  update public.business_devices set status='revoked',activation_hash=null,activation_expires_at=null,device_secret_hash=null,installation_id=null,updated_at=now() where id=p_system_id;
  perform private.business_audit_write_v471(p_tenant_id,'system.revoke','business_device',p_system_id,d.device_code,null::jsonb,jsonb_build_object('reason',coalesce(p_reason,'Business manager revoke')));
  return jsonb_build_object('success',true,'system_id',p_system_id,'status','revoked');
end $$;


--
-- Name: tenant_system_update_v471(uuid, uuid, uuid, text, text[], text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_system_update_v471(p_tenant_id uuid, p_system_id uuid, p_location_id uuid, p_name text, p_module_keys text[], p_invoice_prefix text, p_system_role text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  d public.business_devices%rowtype;
  v_modules text[];
  v_role text;
  v_old_location uuid;
  v_prefix text;
begin
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'locations.manage') and not private.erp_has_permission(p_tenant_id,'locations.manage_all') then raise exception 'Permission denied';end if;
  select * into d from public.business_devices where id=p_system_id and tenant_id=p_tenant_id for update;
  if not found then raise exception 'System not found';end if;
  if not private.erp_user_is_owner(p_tenant_id) and (not private.erp_user_location_allowed(p_tenant_id,d.location_id,'manage') or not private.erp_user_location_allowed(p_tenant_id,p_location_id,'manage')) then raise exception 'Location manage access denied';end if;
  if not exists(select 1 from public.business_locations where id=p_location_id and tenant_id=p_tenant_id and active) then raise exception 'Target store/location is not active';end if;
  v_old_location:=d.location_id;
  v_role:=coalesce(nullif(trim(p_system_role),''),d.system_role,case when d.app_type='pos' then 'pos' else 'office' end);
  if d.app_type='pos' and v_role<>'pos' then raise exception 'POS systems must use POS role';end if;
  if d.app_type='client' and v_role not in('back_office','office','inventory') then raise exception 'Invalid Client system role';end if;
  if d.location_id<>p_location_id then
    if exists(select 1 from public.cashier_shifts where tenant_id=p_tenant_id and device_id=p_system_id and status='open') then raise exception 'Close the cashier shift before moving this system to another store';end if;
    if exists(select 1 from public.pos_held_sales where tenant_id=p_tenant_id and device_id=p_system_id) then raise exception 'Resume or remove held invoices before moving this POS to another store';end if;
  end if;
  if d.app_type='pos' then
    select coalesce(array_agg(distinct x),'{}'::text[]) into v_modules from unnest(coalesce(p_module_keys,'{}'::text[]))x
    where x in('sales','inventory','customers','suppliers','purchases','expenses','restaurant','logs','cashier_shifts','notifications','tasks','support','terminal_day')
      and exists(select 1 from public.tenant_modules tm where tm.tenant_id=p_tenant_id and tm.module_key=x and tm.enabled);
    if coalesce(array_length(v_modules,1),0)=0 then raise exception 'Select at least one enabled POS module'; end if;
    v_prefix:=coalesce(
      nullif(upper(trim(coalesce(p_invoice_prefix,''))),''),
      nullif(upper(trim(coalesce(d.invoice_prefix,''))),''),
      private.v500_next_pos_invoice_prefix(p_tenant_id)
    );
    if v_prefix is distinct from nullif(upper(trim(coalesce(d.invoice_prefix,''))),'') then
      if exists(
        select 1 from public.document_origins o
        where o.tenant_id=p_tenant_id and o.device_id=p_system_id
      ) then
        raise exception 'Terminal invoice prefix cannot be changed after this POS has transaction history';
      end if;
      if exists(
        select 1 from public.business_devices x
        where x.tenant_id=p_tenant_id and x.app_type='pos' and x.id<>p_system_id
          and upper(trim(coalesce(x.invoice_prefix,'')))=v_prefix
      ) then
        raise exception 'Terminal invoice prefix is already in use';
      end if;
    end if;
  else
    v_modules:='{}'::text[];
    v_prefix:=d.invoice_prefix;
  end if;
  update public.business_devices set location_id=p_location_id,name=coalesce(nullif(trim(p_name),''),name),allowed_modules=v_modules,invoice_prefix=v_prefix,system_role=v_role,updated_at=now() where id=p_system_id;
  perform private.business_audit_write_v471(p_tenant_id,'system.update','business_device',p_system_id,d.device_code,null::jsonb,jsonb_build_object('from_location_id',v_old_location,'to_location_id',p_location_id,'system_role',v_role,'modules',v_modules,'invoice_prefix',v_prefix));
  return jsonb_build_object('success',true,'system_id',p_system_id,'location_id',p_location_id,'system_role',v_role,'allowed_modules',v_modules,'invoice_prefix',v_prefix);
end $$;


--
-- Name: tenant_ui_design_get_v43(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_ui_design_get_v43(p_tenant_id uuid, p_app_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v jsonb;
begin
  if p_app_key not in ('client','pos') then raise exception 'Invalid app key'; end if;
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if;
  select jsonb_build_object(
    'template_id',t.id,'key',t.key,'name',t.name,'app_key',t.app_key,
    'config',t.config || coalesce(x.overrides,'{}'::jsonb),'base_config',t.config,'overrides',coalesce(x.overrides,'{}'::jsonb)
  ) into v
  from public.tenant_ui_designs x join public.ui_design_templates t on t.id=x.template_id
  where x.tenant_id=p_tenant_id and x.app_key=p_app_key and t.is_active;
  if v is null then
    select jsonb_build_object('template_id',id,'key',key,'name',name,'app_key',app_key,'config',config,'base_config',config,'overrides','{}'::jsonb)
    into v from public.ui_design_templates
    where app_key=p_app_key and is_active
    order by is_default desc,sort_order,name limit 1;
  end if;
  return coalesce(v,'{}'::jsonb);
end $$;


--
-- Name: tenant_user_access_get(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_user_access_get(p_tenant_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'users.manage') then raise exception 'Permission denied';end if;
  return jsonb_build_object(
    'client_enabled',coalesce((select enabled from public.business_user_app_access where tenant_id=p_tenant_id and user_id=p_user_id and app_key='client'),true),
    'pos_enabled',coalesce((select enabled from public.business_user_app_access where tenant_id=p_tenant_id and user_id=p_user_id and app_key='pos'),false),
    'locations',coalesce((select jsonb_agg(jsonb_build_object('location_id',a.location_id,'access_level',a.access_level)) from public.business_user_location_access a where a.tenant_id=p_tenant_id and a.user_id=p_user_id),'[]'::jsonb)
  );
end $$;


--
-- Name: tenant_user_access_set(uuid, uuid, boolean, boolean, uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_user_access_set(p_tenant_id uuid, p_user_id uuid, p_client_enabled boolean, p_pos_enabled boolean, p_location_ids uuid[], p_access_level text DEFAULT 'operate'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'users.manage') then raise exception 'Permission denied';end if;
  if p_access_level not in ('view','operate','manage') then raise exception 'Invalid access level';end if;
  if not exists(select 1 from public.tenant_memberships where tenant_id=p_tenant_id and user_id=p_user_id and status='active') then raise exception 'User is not an active member';end if;
  if private.erp_user_is_owner(p_tenant_id,p_user_id) and not private.erp_user_is_owner(p_tenant_id) then raise exception 'Only an owner can alter owner access';end if;

  insert into public.business_user_app_access(tenant_id,user_id,app_key,enabled) values(p_tenant_id,p_user_id,'client',coalesce(p_client_enabled,true))
  on conflict(tenant_id,user_id,app_key) do update set enabled=excluded.enabled,updated_at=now();
  insert into public.business_user_app_access(tenant_id,user_id,app_key,enabled) values(p_tenant_id,p_user_id,'pos',coalesce(p_pos_enabled,false))
  on conflict(tenant_id,user_id,app_key) do update set enabled=excluded.enabled,updated_at=now();

  delete from public.business_user_location_access where tenant_id=p_tenant_id and user_id=p_user_id;
  insert into public.business_user_location_access(tenant_id,user_id,location_id,access_level)
  select p_tenant_id,p_user_id,l.id,p_access_level from public.business_locations l
  where l.tenant_id=p_tenant_id and l.active and l.id=any(coalesce(p_location_ids,'{}'::uuid[]))
  on conflict do update set access_level=excluded.access_level,updated_at=now();
end $$;


--
-- Name: tenant_user_management_context(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tenant_user_management_context(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_manage boolean;begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  v_manage:=private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'users.manage');
  return jsonb_build_object(
    'can_manage',v_manage,
    'roles',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'key',r.key,'name',r.name,'is_system',coalesce(r.is_system,false)) order by r.name) from public.roles r where r.tenant_id=p_tenant_id and (private.erp_user_is_owner(p_tenant_id) or r.key<>'owner')),'[]'::jsonb),
    'locations',coalesce((select jsonb_agg(jsonb_build_object('id',l.id,'code',l.location_code,'name',l.name) order by l.name) from public.business_locations l where l.tenant_id=p_tenant_id and l.active and (private.erp_user_is_owner(p_tenant_id) or private.erp_user_location_allowed(p_tenant_id,l.id,'manage'))),'[]'::jsonb)
  );
end $$;


