ules where key='gst_compliance' and is_active) then miss:=array_append(miss,'module.gst_compliance');end if;if not exists(select 1 from public.permissions where key='gst_compliance.view') then miss:=array_append(miss,'permission.gst_compliance.view');end if;if not exists(select 1 from public.gst_tax_rate_master_v520 where rate=40 and effective_from='2025-09-21') then miss:=array_append(miss,'rate.40');end if;if position('product_variants pv join public.products p' in lower(pg_get_functiondef('public.pos_offline_sale_sync_v486(uuid,uuid,uuid,text,jsonb)'::regprocedure)))=0 then miss:=array_append(miss,'offline.tax_lookup_fix');end if;if not exists(select 1 from public.thq_schema_releases where migration_no=214 and schema_version='5.2.0-foundation') then miss:=array_append(miss,'migration.214');end if;return jsonb_build_object('ready',cardinality(miss)=0,'missing',to_jsonb(miss),'schema_version','5.2.0-foundation','migration_no',214,'stage','GST Foundation','provider_connected',false,'production_irp_enabled',false,'principle','ONE Invoice / ONE GST Calculation / ONE Accounting Entry Source / ONE GST Status / ONE Audit Trail');end $$;


--
-- Name: transaction_bulk_import_history_v490(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transaction_bulk_import_history_v490(p_tenant_id uuid, p_import_type text DEFAULT NULL::text, p_limit integer DEFAULT 100) RETURNS TABLE(run_id uuid, import_type text, location_id uuid, location_name text, source_name text, source_key text, row_count integer, document_count integer, success_count integer, failed_count integer, skipped_count integer, status text, created_at timestamp with time zone, completed_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'bulk_import.use') then raise exception 'Bulk Import permission required';end if;
  return query
  select r.id,r.import_type,r.location_id,l.name::text,r.source_name,r.source_key,r.row_count,r.document_count,r.success_count,r.failed_count,r.skipped_count,r.status,r.created_at,r.completed_at
  from public.transaction_import_runs_v490 r join public.business_locations l on l.id=r.location_id
  where r.tenant_id=p_tenant_id and (p_import_type is null or trim(p_import_type)='' or r.import_type=lower(trim(p_import_type)))
    and private.erp_document_scope_allowed(p_tenant_id,r.location_id,null,'view')
  order by r.created_at desc limit greatest(1,least(coalesce(p_limit,100),1000));
end $$;


--
-- Name: transaction_bulk_import_v490(uuid, text, uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transaction_bulk_import_v490(p_tenant_id uuid, p_import_type text, p_location_id uuid, p_device_id uuid, p_source_name text, p_source_key text, p_documents jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare
  v_type text:=lower(trim(coalesce(p_import_type,'')));
  v_run uuid;v_existing public.transaction_import_runs_v490%rowtype;
  v_success integer:=0;v_failed integer:=0;v_skipped integer:=0;v_rows integer:=0;
  v_results jsonb:='[]'::jsonb;d jsonb;v_external text;v_doc public.transaction_import_documents_v490%rowtype;
  v_result jsonb;v_entity uuid;v_number text;v_request text;v_message text;
  v_party uuid;v_items jsonb;v_date date;v_due date;v_amount numeric;v_add numeric;v_round numeric;
begin
  if v_type not in('sales','purchases') then raise exception 'Import type must be sales or purchases';end if;
  if nullif(trim(coalesce(p_source_key,'')),'') is null then raise exception 'Import source key is required';end if;
  if p_documents is null or jsonb_typeof(p_documents)<>'array' or jsonb_array_length(p_documents)=0 then raise exception 'At least one document is required';end if;
  if jsonb_array_length(p_documents)>1000 then raise exception 'A single import is limited to 1000 documents';end if;
  if p_location_id is null then raise exception 'A concrete store/location is required';end if;
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'bulk_import.use') then raise exception 'Bulk Import permission required';end if;
  if v_type='purchases' then perform private.purchasing_v484_access(p_tenant_id,p_location_id,true);
  else
    if not private.erp_document_scope_allowed(p_tenant_id,p_location_id,p_location_id,'operate') then raise exception 'Location access denied';end if;
    if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'sales.manage') then raise exception 'Sales management permission required';end if;
  end if;

  select * into v_existing from public.transaction_import_runs_v490 where tenant_id=p_tenant_id and import_type=v_type and source_key=trim(p_source_key) for update;
  if found and v_existing.status in('completed','completed_with_errors') then
    return coalesce(v_existing.result,'{}'::jsonb)||jsonb_build_object('idempotent_replay',true,'run_id',v_existing.id);
  end if;
  if found then
    v_run:=v_existing.id;
    update public.transaction_import_runs_v490 set status='processing',source_name=nullif(trim(coalesce(p_source_name,'')),''),completed_at=null where id=v_run;
  else
    insert into public.transaction_import_runs_v490(tenant_id,import_type,location_id,source_name,source_key,document_count,created_by)
    values(p_tenant_id,v_type,p_location_id,nullif(trim(coalesce(p_source_name,'')),''),trim(p_source_key),jsonb_array_length(p_documents),auth.uid()) returning id into v_run;
  end if;

  for d in select value from jsonb_array_elements(p_documents) loop
    v_rows:=v_rows+greatest(coalesce(nullif(d->>'source_row_count','')::integer,1),1);
    v_external:=nullif(trim(coalesce(d->>'external_key',d->>'document_ref','')),'');
    if v_external is null then
      v_failed:=v_failed+1;
      v_results:=v_results||jsonb_build_array(jsonb_build_object('status','failed','error','Each document requires external_key/document_ref'));
      continue;
    end if;

    select * into v_doc from public.transaction_import_documents_v490 where tenant_id=p_tenant_id and import_type=v_type and external_key=v_external for update;
    if found and v_doc.status='success' then
      v_skipped:=v_skipped+1;
      v_results:=v_results||jsonb_build_array(jsonb_build_object('external_key',v_external,'status','success','entity_id',v_doc.entity_id,'entity_number',v_doc.entity_number,'idempotent_replay',true));
      continue;
    end if;
    if found then
      update public.transaction_import_documents_v490 set run_id=v_run,status='processing',error_message=null,updated_at=now() where id=v_doc.id;
    else
      insert into public.transaction_import_documents_v490(run_id,tenant_id,import_type,external_key,status)
      values(v_run,p_tenant_id,v_type,v_external,'processing') returning * into v_doc;
    end if;

    begin
      v_items:=coalesce(d->'items','[]'::jsonb);
      if jsonb_typeof(v_items)<>'array' or jsonb_array_length(v_items)=0 then raise exception 'Document has no items';end if;
      v_date:=coalesce(nullif(d->>'document_date','')::date,current_date);
      v_due:=nullif(d->>'due_date','')::date;
      v_add:=greatest(coalesce(nullif(d->>'additional_charges','')::numeric,0),0);
      v_round:=coalesce(nullif(d->>'round_off','')::numeric,0);
      v_amount:=greatest(coalesce(nullif(d->>'initial_payment','')::numeric,0),0);
      v_request:='bulk-'||v_type||'-'||md5(p_tenant_id::text||':'||v_external);

      if v_type='sales' then
        v_party:=nullif(d->>'customer_id','')::uuid;
        if v_party is null then raise exception 'Customer is required';end if;
        v_result:=public.sales_create_v489(
          p_tenant_id,v_party,v_date,v_due,v_items,v_add,v_round,v_amount,
          coalesce(nullif(lower(trim(d->>'payment_method')),''),'cash'),coalesce(d->>'payment_reference',''),coalesce(d->>'notes',''),
          p_location_id,p_device_id,v_request
        );
        v_entity:=nullif(v_result->>'sale_id','')::uuid;v_number:=coalesce(v_result->>'invoice_number',v_result->>'sale_number');
      else
        v_party:=nullif(d->>'supplier_id','')::uuid;
        if v_party is null then raise exception 'Supplier is required';end if;
        if nullif(trim(coalesce(d->>'supplier_invoice_number','')),'') is null then raise exception 'Supplier invoice number is required';end if;
        v_result:=public.purchases_create_v489(
          p_tenant_id,v_party,trim(d->>'supplier_invoice_number'),v_date,v_due,v_items,v_add,v_round,v_amount,
          coalesce(nullif(lower(trim(d->>'payment_method')),''),'bank'),coalesce(d->>'notes',''),p_location_id,p_device_id,v_request
        );
        v_entity:=nullif(v_result->>'purchase_id','')::uuid;v_number:=v_result->>'purchase_number';
      end if;
      if v_entity is null then raise exception 'Transaction creation returned no document ID';end if;
      update public.transaction_import_documents_v490 set status='success',entity_id=v_entity,entity_number=v_number,response=coalesce(v_result,'{}'::jsonb),error_message=null,updated_at=now() where id=v_doc.id;
      v_success:=v_success+1;
      v_results:=v_results||jsonb_build_array(jsonb_build_object('external_key',v_external,'status','success','entity_id',v_entity,'entity_number',v_number,'response',v_result));
    exception when others then
      v_message:=sqlerrm;
      update public.transaction_import_documents_v490 set status='failed',error_message=v_message,response='{}'::jsonb,updated_at=now() where id=v_doc.id;
      v_failed:=v_failed+1;
      v_results:=v_results||jsonb_build_array(jsonb_build_object('external_key',v_external,'status','failed','error',v_message));
    end;
  end loop;

  v_result:=jsonb_build_object(
    'success',v_failed=0,'run_id',v_run,'import_type',v_type,'source_key',trim(p_source_key),
    'success_count',v_success,'failed_count',v_failed,'skipped_count',v_skipped,'document_count',jsonb_array_length(p_documents),'row_count',v_rows,
    'documents',v_results
  );
  update public.transaction_import_runs_v490
  set row_count=v_rows,document_count=jsonb_array_length(p_documents),success_count=v_success,failed_count=v_failed,skipped_count=v_skipped,
      status=case when v_failed=0 then 'completed' else 'completed_with_errors' end,result=v_result,completed_at=now()
  where id=v_run;
  perform private.thq_sync_bump_v480(p_tenant_id,'transactions','bulk_'||v_type,v_run::text,'import');
  return v_result;
exception when others then
  if v_run is not null then
    update public.transaction_import_runs_v490 set status='failed',result=jsonb_build_object('error',sqlerrm),completed_at=now() where id=v_run;
  end if;
  raise;
end $$;


--
-- Name: transaction_explain_core_v600(uuid, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transaction_explain_core_v600(p_tenant_id uuid, p_entity_type text, p_entity_id uuid, p_event_limit integer DEFAULT 500) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_type text:=lower(trim(coalesce(p_entity_type,'')));
  v_root_type text;
  v_root_id uuid;
  v_corr uuid;
  v_sensitive boolean;
  v_audit boolean;
  v_accounting boolean;
  v_inventory boolean;
  v_current jsonb;
  v_origin jsonb;
  v_story jsonb:='[]'::jsonb;
  v_legacy_audit jsonb:='[]'::jsonb;
  v_payments jsonb:='[]'::jsonb;
  v_approvals jsonb:='[]'::jsonb;
  v_journals jsonb:='[]'::jsonb;
  v_stock jsonb:='[]'::jsonb;
  v_gst jsonb:='[]'::jsonb;
  v_story_count integer:=0;
  v_legacy_count integer:=0;
  v_quality text;
  v_notice text;
begin
  if p_entity_id is null then raise exception 'Entity id is required'; end if;
  if not private.v600_can_view_entity(p_tenant_id,v_type) then raise exception 'Permission denied' using errcode='42501'; end if;

  v_sensitive:=private.has_permission(p_tenant_id,'audit_history.view_sensitive');
  v_audit:=private.has_permission(p_tenant_id,'audit_center.view');
  v_accounting:=v_audit or private.has_permission(p_tenant_id,'accounting.view') or private.has_permission(p_tenant_id,'accounting.manage');
  v_inventory:=v_audit or private.has_permission(p_tenant_id,'inventory.view') or private.has_permission(p_tenant_id,'inventory.manage');
  v_root_type:=v_type; v_root_id:=p_entity_id;

  if v_type='sale' then
    select to_jsonb(s) into v_current from public.sales s where s.tenant_id=p_tenant_id and s.id=p_entity_id;
  elsif v_type='sale_item' then
    select to_jsonb(si),si.sale_id into v_current,v_root_id from public.sale_items si where si.tenant_id=p_tenant_id and si.id=p_entity_id;
    v_root_type:='sale';
  elsif v_type='sale_payment' then
    select to_jsonb(sp),sp.sale_id into v_current,v_root_id from public.sale_payments sp where sp.tenant_id=p_tenant_id and sp.id=p_entity_id;
    v_root_type:='sale';
  elsif v_type='sales_return' then
    select to_jsonb(sr),sr.sale_id into v_current,v_root_id from public.sales_returns sr where sr.tenant_id=p_tenant_id and sr.id=p_entity_id;
    v_root_type:='sale';
  elsif v_type='purchase' then
    select to_jsonb(p) into v_current from public.purchases p where p.tenant_id=p_tenant_id and p.id=p_entity_id;
  elsif v_type='purchase_item' then
    select to_jsonb(pi),pi.purchase_id into v_current,v_root_id from public.purchase_items pi where pi.tenant_id=p_tenant_id and pi.id=p_entity_id;
    v_root_type:='purchase';
  elsif v_type='purchase_payment' then
    select to_jsonb(pp),pp.purchase_id into v_current,v_root_id from public.purchase_payments pp where pp.tenant_id=p_tenant_id and pp.id=p_entity_id;
    v_root_type:='purchase';
  elsif v_type='purchase_invoice' then
    select to_jsonb(pi) into v_current from public.purchase_invoices_v484 pi where pi.tenant_id=p_tenant_id and pi.id=p_entity_id;
  elsif v_type='supplier_payment' then
    select to_jsonb(sp) into v_current from public.supplier_payments_v484 sp where sp.tenant_id=p_tenant_id and sp.id=p_entity_id;
  elsif v_type='journal_entry' then
    select to_jsonb(j) into v_current from public.journal_entries j where j.tenant_id=p_tenant_id and j.id=p_entity_id;
    if v_current is not null and nullif(v_current->>'source_id','') is not null then
      v_root_id:=(v_current->>'source_id')::uuid; v_root_type:=coalesce(nullif(v_current->>'source_type',''),'journal_entry');
    end if;
  elsif v_type='stock_adjustment' then
    select to_jsonb(a) into v_current from public.stock_adjustment_requests_v500 a where a.tenant_id=p_tenant_id and a.id=p_entity_id;
  else
    select jsonb_build_object('entity_type',v_type,'entity_id',p_entity_id) into v_current;
  end if;

  if v_current is null then raise exception 'Transaction not found'; end if;
  v_corr:=extensions.uuid_generate_v5(extensions.uuid_ns_url(),'thq:v600:'||p_tenant_id::text||':'||lower(v_root_type)||':'||v_root_id::text);

  select to_jsonb(o) into v_origin
  from public.document_origins o
  where o.tenant_id=p_tenant_id and o.entity_type=v_root_type and o.entity_id=v_root_id
  order by o.created_at asc limit 1;

  select count(*),coalesce(jsonb_agg(jsonb_build_object(
    'sequence',e.event_sequence,'id',e.id,'action',e.action,'event_time',e.event_time,
    'entity_type',e.entity_type,'entity_id',e.entity_id,'entity_reference',e.entity_reference,
    'actor',jsonb_build_object('user_id',e.actor_user_id,'name',e.actor_name,'roles',e.actor_role_keys),
    'location_id',e.location_id,'device',jsonb_build_object('id',e.device_id,'name',e.device_name,'code',e.device_code,'app',e.source_app),
    'changed_fields',e.changed_fields,'before',case when v_sensitive then e.before_data else null end,'after',case when v_sensitive then e.after_data else null end,
    'reason',e.reason,'approval',jsonb_build_object('request_id',e.approval_request_id,'approved_by',e.approved_by,'approved_at',e.approved_at,'note',e.approval_note),
    'source_module',e.source_module,'related_entities',e.related_entities,'event_hash',e.event_hash
  ) order by e.event_sequence),'[]'::jsonb)
  into v_story_count,v_story
  from (
    select * from public.transaction_story_events_v600
    where tenant_id=p_tenant_id and correlation_id=v_corr
    order by event_sequence
    limit greatest(1,least(coalesce(p_event_limit,500),2000))
  ) e;

  select count(*),coalesce(jsonb_agg(jsonb_build_object(
    'id',a.id,'action',a.action,'entity_type',a.entity_type,'entity_id',a.entity_id,'entity_reference',a.entity_reference,
    'user_id',a.user_id,'created_at',a.created_at,'location_id',a.location_id,'device_id',a.device_id,'reason',a.reason,
    'before',case when v_sensitive then a.before_data else null end,'after',case when v_sensitive then a.after_data else null end,'metadata',a.metadata
  ) order by a.created_at),'[]'::jsonb)
  into v_legacy_count,v_legacy_audit
  from public.business_audit_log a
  where a.tenant_id=p_tenant_id and (
    (a.entity_type=v_type and a.entity_id=p_entity_id) or
    (a.entity_type=v_root_type and a.entity_id=v_root_id)
  );

  if v_root_type='sale' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id',sp.id,'amount',sp.amount,'method',sp.payment_method,'reference',sp.reference_number,'notes',sp.notes,
      'paid_at',sp.paid_at,'created_by',sp.created_by,'created_by_name',u.username::text
    ) order by sp.paid_at,sp.id),'[]'::jsonb) into v_payments
    from public.sale_payments sp left join public.user_login_names u on u.user_id=sp.created_by
    where sp.tenant_id=p_tenant_id and sp.sale_id=v_root_id;
  elsif v_root_type='purchase' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id',pp.id,'amount',pp.amount,'method',pp.payment_method,'reference',pp.reference_number,'notes',pp.notes,
      'paid_at',pp.paid_at,'created_by',pp.created_by,'created_by_name',u.username::text
    ) order by pp.paid_at,pp.id),'[]'::jsonb) into v_payments
    from public.purchase_payments pp left join public.user_login_names u on u.user_id=pp.created_by
    where pp.tenant_id=p_tenant_id and pp.purchase_id=v_root_id;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',ar.id,'module',ar.module_key,'action',ar.action_key,'entity_type',ar.entity_type,'entity_id',ar.entity_id,
    'amount',ar.amount,'percentage',ar.percentage,'status',ar.status,'reason',ar.reason,
    'requested_by',ar.requested_by,'requested_at',ar.requested_at,'decided_by',ar.decided_by,'decided_at',ar.decided_at,'decision_note',ar.decision_note
  ) order by ar.requested_at),'[]'::jsonb) into v_approvals
  from public.approval_requests ar
  where ar.tenant_id=p_tenant_id and (
    (ar.entity_type=v_type and ar.entity_id=p_entity_id) or
    (ar.entity_type=v_root_type and ar.entity_id=v_root_id)
  );

  if v_accounting then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id',j.id,'entry_number',j.entry_number,'entry_date',j.entry_date,'description',j.description,'status',j.status,
      'source_type',j.source_type,'source_id',j.source_id,'source_reference',j.source_reference,'reversal_of',j.reversal_of,
      'created_by',j.created_by,'created_at',j.created_at,'posted_at',j.posted_at,'location_id',j.location_id
    ) order by j.entry_date,j.created_at),'[]'::jsonb) into v_journals
    from public.journal_entries j
    where j.tenant_id=p_tenant_id and (
      (j.source_type=v_root_type and j.source_id=v_root_id) or
      (v_root_type='sale' and j.source_type='sales_return' and exists(select 1 from public.sales_returns sr where sr.tenant_id=p_tenant_id and sr.sale_id=v_root_id and sr.id=j.source_id))
    );
  end if;

  if v_inventory then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id',m.id,'movement_type',m.movement_type,'variant_id',m.variant_id,'quantity_delta',m.quantity_delta,'unit_cost',m.unit_cost,
      'reference_type',m.reference_type,'reference_id',m.reference_id,'reference_number',m.reference_number,'note',m.note,
      'created_by',m.created_by,'device_id',m.device_id,'created_at',m.created_at,'balance_before',m.balance_before,'balance_after',m.balance_after,
      'movement_group',m.movement_group
    ) order by m.created_at,m.id),'[]'::jsonb) into v_stock
    from public.location_stock_movements m
    where m.tenant_id=p_tenant_id and (
      (m.reference_type=v_root_type and m.reference_id=v_root_id) or
      (v_root_type='sale' and m.reference_type='sales_return' and exists(select 1 from public.sales_returns sr where sr.tenant_id=p_tenant_id and sr.sale_id=v_root_id and sr.id=m.reference_id))
    );
  end if;

  select coalesce(jsonb_agg(x.evidence order by x.evidence_time,x.evidence_id),'[]'::jsonb) into v_gst
  from (
    select s.id evidence_id,s.created_at evidence_time,jsonb_build_object(
      'evidence_type','authoritative_snapshot','id',s.id,'source_type',s.source_type,'source_id',s.source_id,'source_number',s.source_number,
      'document_number',s.document_number,'document_date',s.document_date,'location_id',s.location_id,'tax_mode',s.tax_mode,
      'taxable_total',s.taxable_total,'cgst_total',s.cgst_total,'sgst_total',s.sgst_total,'utgst_total',s.utgst_total,'igst_total',s.igst_total,
      'cess_total',s.cess_total,'tax_collected_total',s.tax_collected_total,'rcm_tax_payable_total',s.rcm_tax_payable_total,
      'government_tax_total',s.government_tax_total,'grand_total',s.grand_total,'engine_version',s.engine_version,
      'snapshot_hash',s.snapshot_hash,'document_identity_hash',s.document_identity_hash,'created_at',s.created_at
    ) evidence
    from public.gst_document_snapshots_v520 s
    where s.tenant_id=p_tenant_id and (
      (s.source_type=v_root_type and s.source_id=v_root_id) or
      (v_root_type='sale' and s.source_type='sales_return' and exists(select 1 from public.sales_returns sr where sr.tenant_id=p_tenant_id and sr.sale_id=v_root_id and sr.id=s.source_id))
    )
    union all
    select l.id,l.marked_at,jsonb_build_object(
      'evidence_type','legacy_unverified','id',l.id,'source_type',l.source_type,'source_id',l.source_id,'source_number',l.source_number,
      'document_date',l.document_date,'location_id',l.location_id,'legacy_taxable_total',l.legacy_taxable_total,'legacy_tax_total',l.legacy_tax_total,
      'legacy_grand_total',l.legacy_grand_total,'verification_status',l.verification_status,'note',l.note,'source_hash',l.source_hash,'marked_at',l.marked_at
    )
    from public.gst_legacy_document_markers_v520 l
    where l.tenant_id=p_tenant_id and (
      (l.source_type=v_root_type and l.source_id=v_root_id) or
      (v_root_type='sale' and l.source_type='sales_return' and exists(select 1 from public.sales_returns sr where sr.tenant_id=p_tenant_id and sr.sale_id=v_root_id and sr.id=l.source_id))
    )
  ) x;

  if v_story_count>0 then
    v_quality:='enhanced_v600';
    v_notice:='v6.0 Transaction Story evidence is available. Older actions not captured before v6.0 are shown only when existing THQ records provide real evidence.';
  elsif v_legacy_count>0 then
    v_quality:='historical_partial';
    v_notice:='Historical transaction: enhanced v6.0 event tracking was not active. Existing audit/payment/stock/journal/GST records are shown; missing actor/edit/device/reason history is not inferred.';
  else
    v_quality:='historical_baseline_only';
    v_notice:='Historical transaction: enhanced tracking was not active when this record was created. THQ shows current state and related recorded evidence only; no missing history is fabricated.';
  end if;

  return jsonb_build_object(
    'requested_entity',jsonb_build_object('type',v_type,'id',p_entity_id),
    'transaction_root',jsonb_build_object('type',v_root_type,'id',v_root_id,'correlation_id',v_corr),
    'tracking_quality',v_quality,'historical_notice',v_notice,'sensitive_values_visible',v_sensitive,
    'current_record',v_current,'origin',v_origin,
    'transaction_story',v_story,'legacy_audit_evidence',v_legacy_audit,
    'payments',v_payments,'approvals',v_approvals,'journals',v_journals,'stock_movements',v_stock,'gst_evidence',v_gst,
    'accounting_visible',v_accounting,'inventory_visible',v_inventory,
    'gst_integrity_rule','Authoritative v5.2 GST snapshots remain authoritative. A failed v5.2 transaction must never be re-routed to a legacy writer; legacy markers are historical evidence only.'
  );
end;
$$;


--
-- Name: transaction_explain_v600(uuid, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transaction_explain_v600(p_tenant_id uuid, p_entity_type text, p_entity_id uuid, p_event_limit integer DEFAULT 500) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_base jsonb;
  v_root_type text;
  v_root_id uuid;
  v_root_corr uuid;
  v_story jsonb:='[]'::jsonb;
  v_total integer:=0;
  v_native integer:=0;
  v_historical integer:=0;
  v_quality text;
  v_notice text;
begin
  v_base:=public.transaction_explain_core_v600(p_tenant_id,p_entity_type,p_entity_id,p_event_limit);
  v_root_type:=v_base#>>'{transaction_root,type}';
  v_root_id:=(v_base#>>'{transaction_root,id}')::uuid;
  v_root_corr:=(v_base#>>'{transaction_root,correlation_id}')::uuid;

  with candidate as (
    select e.*,
      coalesce((e.metadata->>'historical_reconstruction')::boolean,false) as is_historical
    from public.transaction_story_events_v600 e
    where e.tenant_id=p_tenant_id and (
      e.correlation_id=v_root_corr
      or (
        v_root_type='sale' and e.correlation_id in (
          select extensions.uuid_generate_v5(
            extensions.uuid_ns_url(),
            'thq:v600:'||p_tenant_id::text||':sales_return:'||sr.id::text
          )
          from public.sales_returns sr
          where sr.tenant_id=p_tenant_id and sr.sale_id=v_root_id
        )
      )
    )
    order by e.event_time,e.event_sequence
    limit greatest(1,least(coalesce(p_event_limit,500),2000))
  )
  select count(*),
    count(*) filter(where not is_historical),
    count(*) filter(where is_historical),
    coalesce(jsonb_agg(jsonb_build_object(
      'sequence',event_sequence,'id',id,'correlation_id',correlation_id,'action',action,'event_time',event_time,
      'entity_type',entity_type,'entity_id',entity_id,'entity_reference',entity_reference,
      'actor',jsonb_build_object('user_id',actor_user_id,'name',actor_name,'roles',actor_role_keys),
      'location_id',location_id,'device',jsonb_build_object('id',device_id,'name',device_name,'code',device_code,'app',source_app),
      'changed_fields',changed_fields,
      'before',case when (v_base->>'sensitive_values_visible')::boolean then before_data else null end,
      'after',case when (v_base->>'sensitive_values_visible')::boolean then after_data else null end,
      'reason',reason,
      'approval',jsonb_build_object('request_id',approval_request_id,'approved_by',approved_by,'approved_at',approved_at,'note',approval_note),
      'source_module',source_module,'source_function',source_function,'related_entities',related_entities,
      'evidence_quality',case when is_historical then 'historical_reconstructed_baseline' else 'native_v600_event' end,
      'metadata',metadata,
      'integrity',jsonb_build_object('previous_hash',previous_event_hash,'event_hash',event_hash)
    ) order by event_time,event_sequence),'[]'::jsonb)
  into v_total,v_native,v_historical,v_story
  from candidate;

  if v_native>0 and v_historical>0 then
    v_quality:='enhanced_v600_with_historical_baseline';
    v_notice:='Native v6.0 events are available from the upgrade point forward. Earlier baseline entries are reconstructed only from records that already existed and are explicitly labeled; missing pre-v6 edits are not inferred.';
  elsif v_native>0 then
    v_quality:='enhanced_v600';
    v_notice:='Native v6.0 Transaction Story evidence is available for this transaction.';
  elsif v_historical>0 then
    v_quality:='historical_reconstructed_baseline';
    v_notice:='Historical transaction: baseline events were reconstructed from records that actually existed at upgrade time. They do not represent a complete pre-v6 edit history, and missing actor/reason/device changes are not fabricated.';
  else
    v_quality:=coalesce(v_base->>'tracking_quality','historical_baseline_only');
    v_notice:=v_base->>'historical_notice';
  end if;

  return jsonb_set(
    jsonb_set(
      jsonb_set(v_base,'{transaction_story}',v_story,true),
      '{tracking_quality}',to_jsonb(v_quality),true
    ),
    '{historical_notice}',to_jsonb(v_notice),true
  ) || jsonb_build_object('story_counts',jsonb_build_object('total',v_total,'native_v600',v_native,'historical_baseline',v_historical));
end;
$$;


--
-- Name: transaction_history_v600(uuid, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transaction_history_v600(p_tenant_id uuid, p_entity_type text, p_entity_id uuid, p_limit integer DEFAULT 250) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v jsonb;
begin
  v:=public.transaction_explain_v600(p_tenant_id,p_entity_type,p_entity_id,p_limit);
  return jsonb_build_object(
    'tenant_id',p_tenant_id,
    'requested_entity',v->'requested_entity',
    'transaction_root',v->'transaction_root',
    'tracking_quality',v->'tracking_quality',
    'historical_notice',v->'historical_notice',
    'story_counts',v->'story_counts',
    'sensitive_values_visible',v->'sensitive_values_visible',
    'events',v->'transaction_story'
  );
end;
$$;


--
-- Name: transaction_return_status_v45(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transaction_return_status_v45(p_tenant_id uuid, p_entity_type text, p_entity_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare original_qty numeric:=0;returned_qty numeric:=0;returned_total numeric:=0;v_status text:='not_returned';begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if p_entity_type='sale' then
    select coalesce(sum(quantity),0) into original_qty from public.sale_items where sale_id=p_entity_id;
    select coalesce(sum(i.quantity),0),coalesce(sum(r.grand_total),0) into returned_qty,returned_total from public.sales_returns r join public.sales_return_items i on i.sales_return_id=r.id where r.tenant_id=p_tenant_id and r.sale_id=p_entity_id and r.refund_status<>'waived';
  elsif p_entity_type='purchase' then
    select coalesce(sum(quantity),0) into original_qty from public.purchase_items where purchase_id=p_entity_id;
    select coalesce(sum(i.quantity),0),coalesce(sum(r.grand_total),0) into returned_qty,returned_total from public.purchase_returns r join public.purchase_return_items i on i.purchase_return_id=r.id where r.tenant_id=p_tenant_id and r.purchase_id=p_entity_id and r.credit_status<>'waived';
  else raise exception 'Invalid entity type';end if;
  if returned_qty>0 and returned_qty+0.0001>=original_qty then v_status:='fully_returned';
  elsif returned_qty>0 then v_status:='partially_returned';end if;
  return jsonb_build_object('status',v_status,'original_quantity',original_qty,'returned_quantity',returned_qty,'returned_total',returned_total);
end $$;


--
-- Name: transaction_story_verify_v600(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transaction_story_verify_v600(p_tenant_id uuid, p_entity_type text, p_entity_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_corr uuid;
  v_prev text := null;
  v_expected text;
  v_payload jsonb;
  r record;
  v_checked integer := 0;
begin
  if not private.has_permission(p_tenant_id,'audit_center.view') then
    raise exception 'Permission denied' using errcode='42501';
  end if;
  v_corr := extensions.uuid_generate_v5(extensions.uuid_ns_url(),'thq:v600:'||p_tenant_id::text||':'||lower(p_entity_type)||':'||p_entity_id::text);
  for r in select * from public.transaction_story_events_v600 where tenant_id=p_tenant_id and correlation_id=v_corr order by event_sequence loop
    if r.previous_event_hash is distinct from v_prev then
      return jsonb_build_object('valid',false,'checked',v_checked,'failed_sequence',r.event_sequence,'reason','previous_hash_mismatch');
    end if;
    v_payload := jsonb_build_object(
      'id',r.id,'tenant_id',r.tenant_id,'correlation_id',r.correlation_id,
      'root_entity_type',r.root_entity_type,'root_entity_id',r.root_entity_id,
      'entity_type',r.entity_type,'entity_id',r.entity_id,'entity_reference',r.entity_reference,
      'action',r.action,'event_time',r.event_time,'actor_user_id',r.actor_user_id,'actor_name',r.actor_name,
      'actor_role_keys',r.actor_role_keys,'location_id',r.location_id,'device_id',r.device_id,
      'device_name',r.device_name,'device_code',r.device_code,'source_app',r.source_app,
      'request_id',r.request_id,'before_data',r.before_data,'after_data',r.after_data,'changed_fields',r.changed_fields,
      'reason',r.reason,'approval_request_id',r.approval_request_id,'approved_by',r.approved_by,
      'approved_at',r.approved_at,'approval_note',r.approval_note,'source_module',r.source_module,
      'source_function',r.source_function,'related_entities',r.related_entities,
      'metadata',r.metadata,'previous_event_hash',r.previous_event_hash
    );
    v_expected := encode(extensions.digest(coalesce(v_prev,'')||v_payload::text,'sha256'),'hex');
    if v_expected is distinct from r.event_hash then
      return jsonb_build_object('valid',false,'checked',v_checked,'failed_sequence',r.event_sequence,'reason','event_hash_mismatch');
    end if;
    v_prev := r.event_hash;
    v_checked := v_checked+1;
  end loop;
  return jsonb_build_object('valid',true,'checked',v_checked,'correlation_id',v_corr);
end;
$$;


--
-- Name: user_saved_view_save_v4(uuid, text, text, jsonb, jsonb, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_saved_view_save_v4(p_tenant_id uuid, p_module_key text, p_name text, p_filters jsonb, p_columns jsonb DEFAULT '[]'::jsonb, p_sort jsonb DEFAULT '{}'::jsonb, p_is_default boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_id uuid; begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if trim(coalesce(p_name,''))='' then raise exception 'View name required';end if;
  if p_is_default then
    update public.user_saved_views set is_default=false
    where tenant_id=p_tenant_id and user_id=auth.uid() and module_key=p_module_key;
  end if;
  insert into public.user_saved_views(tenant_id,user_id,module_key,name,filters,columns,sort,is_default)
  values(p_tenant_id,auth.uid(),p_module_key,trim(p_name),coalesce(p_filters,'{}'::jsonb),coalesce(p_columns,'[]'::jsonb),coalesce(p_sort,'{}'::jsonb),coalesce(p_is_default,false))
  on conflict(tenant_id,user_id,module_key,name) do update set
    filters=excluded.filters,columns=excluded.columns,sort=excluded.sort,is_default=excluded.is_default
  returning id into v_id;
  return v_id;
end $$;


--
-- Name: user_saved_views; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.user_saved_views (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    user_id uuid NOT NULL,
    module_key text NOT NULL,
    name text NOT NULL,
    filters jsonb DEFAULT '{}'::jsonb NOT NULL,
    columns jsonb DEFAULT '[]'::jsonb NOT NULL,
    sort jsonb DEFAULT '{}'::jsonb NOT NULL,
    is_default boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: user_saved_views_list_v4(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_saved_views_list_v4(p_tenant_id uuid, p_module_key text) RETURNS SETOF public.user_saved_views
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  return query select * from public.user_saved_views
  where tenant_id=p_tenant_id and user_id=auth.uid() and module_key=p_module_key
  order by is_default desc,name;
end $$;


--
-- Name: warehouse_inventory_v485(uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.warehouse_inventory_v485(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_query text DEFAULT ''::text, p_limit integer DEFAULT 1000) RETURNS TABLE(location_id uuid, location_code text, location_name text, variant_id uuid, product_name text, sku text, tracking_mode text, on_hand numeric, reserved numeric, available numeric, damaged numeric, quarantine numeric, in_transit_in numeric, in_transit_out numeric, average_cost numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare q text:='%'||lower(trim(coalesce(p_query,'')))||'%';
begin
  perform private.warehouse_v485_permission(p_tenant_id,false);
  return query
  select l.id,l.location_code,l.name,b.variant_id,p.name,pv.sku,private.v483_tracking_mode(p_tenant_id,b.variant_id),
    b.quantity,b.reserved_quantity,greatest(b.quantity-b.reserved_quantity-b.damaged_quantity-b.quarantine_quantity,0),b.damaged_quantity,b.quarantine_quantity,
    coalesce((select sum(greatest(i.dispatched_quantity-i.received_quantity,0)) from public.stock_transfers t join public.stock_transfer_items i on i.transfer_id=t.id where t.tenant_id=p_tenant_id and t.to_location_id=l.id and i.variant_id=b.variant_id and t.status in('dispatched','in_transit')),0),
    coalesce((select sum(greatest(i.dispatched_quantity-i.received_quantity,0)) from public.stock_transfers t join public.stock_transfer_items i on i.transfer_id=t.id where t.tenant_id=p_tenant_id and t.from_location_id=l.id and i.variant_id=b.variant_id and t.status in('dispatched','in_transit')),0),b.average_cost
  from public.location_stock_balances b
  join public.business_locations l on l.id=b.location_id and l.tenant_id=b.tenant_id
  join public.product_variants pv on pv.id=b.variant_id and pv.tenant_id=b.tenant_id
  join public.products p on p.id=pv.product_id
  where b.tenant_id=p_tenant_id and l.active and (l.hierarchy_role='warehouse' or l.location_type='warehouse')
    and (p_location_id is null or l.id=p_location_id)
    and (trim(coalesce(p_query,''))='' or lower(p.name) like q or lower(pv.sku) like q or lower(coalesce(pv.barcode,'')) like q)
    and (private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'locations.view_all') or private.erp_has_permission(p_tenant_id,'locations.manage_all') or private.erp_user_location_allowed(p_tenant_id,l.id,'view'))
  order by l.name,p.name,pv.sku
  limit greatest(1,least(coalesce(p_limit,1000),5000));
end$$;


--
-- Name: warehouse_locations_v485(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.warehouse_locations_v485(p_tenant_id uuid) RETURNS TABLE(location_id uuid, location_code text, location_name text, location_type text, hierarchy_role text, product_count bigint, on_hand numeric, reserved numeric, available numeric, damaged numeric, quarantine numeric, in_transit_in numeric, in_transit_out numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  perform private.warehouse_v485_permission(p_tenant_id,false);
  return query
  select l.id,l.location_code,l.name,l.location_type,l.hierarchy_role,
    count(distinct case when coalesce(b.quantity,0)<>0 then b.variant_id end),
    coalesce(sum(b.quantity),0),coalesce(sum(b.reserved_quantity),0),
    coalesce(sum(greatest(b.quantity-b.reserved_quantity-b.damaged_quantity-b.quarantine_quantity,0)),0),
    coalesce(sum(b.damaged_quantity),0),coalesce(sum(b.quarantine_quantity),0),
    coalesce((select sum(greatest(i.dispatched_quantity-i.received_quantity,0))
      from public.stock_transfers t join public.stock_transfer_items i on i.transfer_id=t.id
      where t.tenant_id=p_tenant_id and t.to_location_id=l.id and t.status in('dispatched','in_transit')),0),
    coalesce((select sum(greatest(i.dispatched_quantity-i.received_quantity,0))
      from public.stock_transfers t join public.stock_transfer_items i on i.transfer_id=t.id
      where t.tenant_id=p_tenant_id and t.from_location_id=l.id and t.status in('dispatched','in_transit')),0)
  from public.business_locations l
  left join public.location_stock_balances b on b.tenant_id=l.tenant_id and b.location_id=l.id
  where l.tenant_id=p_tenant_id and l.active
    and (l.hierarchy_role='warehouse' or l.location_type='warehouse')
    and (private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'locations.view_all') or private.erp_has_permission(p_tenant_id,'locations.manage_all') or private.erp_user_location_allowed(p_tenant_id,l.id,'view'))
  group by l.id,l.location_code,l.name,l.location_type,l.hierarchy_role
  order by l.name,l.location_code;
end$$;


--
-- Name: warranty_register_v483(uuid, text, text, integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.warranty_register_v483(p_tenant_id uuid, p_query text DEFAULT ''::text, p_status text DEFAULT NULL::text, p_expiring_days integer DEFAULT NULL::integer, p_limit integer DEFAULT 300, p_location_id uuid DEFAULT NULL::uuid) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare q text:='%'||lower(trim(coalesce(p_query,'')))||'%';begin
 if not private.erp_user_has_tenant_access(p_tenant_id) or not private.v483_trace_view_allowed(p_tenant_id) then raise exception 'Traceability view permission required';end if;
 return query
 select jsonb_build_object(
  'warranty_id',w.id,'variant_id',w.variant_id,'product_name',p.name,'variant_name',pv.name,'sku',pv.sku,
  'serial_number',s.serial_number,'batch_number',b.batch_number,'customer_id',w.customer_id,'customer_name',c.name,
  'sale_id',w.sale_id,'sale_number',sa.sale_number,'quantity',w.quantity,'warranty_start',w.warranty_start,
  'warranty_expiry',w.warranty_expiry,'days_remaining',w.warranty_expiry-current_date,
  'status',case when w.status='active' and w.warranty_expiry<current_date then 'expired' else w.status end,
  'location_id',o.location_id,'location_name',l.name
 )
 from public.product_warranties_v483 w
 join public.product_variants pv on pv.id=w.variant_id and pv.tenant_id=w.tenant_id
 join public.products p on p.id=pv.product_id
 left join public.inventory_serials_v483 s on s.id=w.serial_id
 left join public.inventory_batches_v483 b on b.id=w.batch_id
 join public.customers c on c.id=w.customer_id
 join public.sales sa on sa.id=w.sale_id
 left join public.document_origins o on o.tenant_id=w.tenant_id and o.entity_type='sale' and o.entity_id=w.sale_id
 left join public.business_locations l on l.id=o.location_id
 where w.tenant_id=p_tenant_id
 and private.erp_document_scope_allowed(p_tenant_id,o.location_id,p_location_id,'view')
 and (
  trim(coalesce(p_query,''))='' or lower(coalesce(s.serial_number,'')) like q or lower(coalesce(b.batch_number,'')) like q or
  lower(coalesce(p.name,'')) like q or lower(coalesce(pv.sku,'')) like q or lower(coalesce(c.name,'')) like q or
  lower(coalesce(sa.sale_number,'')) like q
 )
 and (
  p_status is null or lower(p_status)=case when w.status='active' and w.warranty_expiry<current_date then 'expired' else lower(w.status) end
 )
 and (
  p_expiring_days is null or (w.status='active' and w.warranty_expiry between current_date and current_date+greatest(p_expiring_days,0))
 )
 order by w.warranty_expiry,w.created_at desc
 limit greatest(1,least(coalesce(p_limit,300),1000));
end$$;


--
-- Name: warranty_sync_v51(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.warranty_sync_v51(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
declare v_expired integer:=0;v_reactivated integer:=0;v_voided integer:=0;v_serial_backfill integer:=0;v_batch_backfill integer:=0;
begin
  if not private.erp_user_has_tenant_access(p_tenant_id) or not private.v483_trace_view_allowed(p_tenant_id) then
    raise exception 'Traceability view permission required';
  end if;

  update public.product_warranties_v483 w
  set status='void',updated_at=now()
  from public.sales s
  where w.tenant_id=p_tenant_id and s.id=w.sale_id and s.tenant_id=w.tenant_id
    and s.status='cancelled' and w.status in('active','expired');
  get diagnostics v_voided=row_count;

  update public.product_warranties_v483
  set status='expired',updated_at=now()
  where tenant_id=p_tenant_id and status='active' and warranty_expiry<current_date;
  get diagnostics v_expired=row_count;

  update public.product_warranties_v483 w
  set status='active',updated_at=now()
  from public.sales s
  where w.tenant_id=p_tenant_id and s.id=w.sale_id and s.tenant_id=w.tenant_id and s.status='posted'
    and w.status='expired' and w.warranty_expiry>=current_date;
  get diagnostics v_reactivated=row_count;

  insert into public.product_warranties_v483(
    tenant_id,variant_id,serial_id,batch_id,customer_id,sale_id,sale_item_id,quantity,
    warranty_start,warranty_expiry,status,created_by
  )
  select s.tenant_id,s.variant_id,s.id,null,s.customer_id,s.sale_id,s.sale_item_id,1,
         sa.sale_date,
         (sa.sale_date+make_interval(months=>coalesce(tp.warranty_months,0),days=>coalesce(tp.warranty_days,0)))::date,
         case when (sa.sale_date+make_interval(months=>coalesce(tp.warranty_months,0),days=>coalesce(tp.warranty_days,0)))::date<current_date then 'expired' else 'active' end,
         coalesce(s.created_by,sa.created_by)
  from public.inventory_serials_v483 s
  join public.sales sa on sa.id=s.sale_id and sa.tenant_id=s.tenant_id and sa.status='posted'
  join public.product_tracking_policies_v483 tp on tp.tenant_id=s.tenant_id and tp.variant_id=s.variant_id and tp.warranty_enabled
  where s.tenant_id=p_tenant_id and s.status='sold' and s.sale_id is not null and s.sale_item_id is not null
    and not exists(select 1 from public.product_warranties_v483 w where w.tenant_id=s.tenant_id and w.serial_id=s.id and w.sale_id=s.sale_id and w.status<>'void')
  on conflict do nothing;
  get diagnostics v_serial_backfill=row_count;

  insert into public.product_warranties_v483(
    tenant_id,variant_id,serial_id,batch_id,customer_id,sale_id,sale_item_id,quantity,
    warranty_start,warranty_expiry,status,created_by
  )
  select e.tenant_id,e.variant_id,null,e.batch_id,e.customer_id,e.sale_id,e.sale_item_id,sum(e.quantity),
         sa.sale_date,
         (sa.sale_date+make_interval(months=>coalesce(tp.warranty_months,0),days=>coalesce(tp.warranty_days,0)))::date,
         case when (sa.sale_date+make_interval(months=>coalesce(tp.warranty_months,0),days=>coalesce(tp.warranty_days,0)))::date<current_date then 'expired' else 'active' end,
         (array_agg(e.created_by) filter(where e.created_by is not null))[1]
  from public.inventory_trace_events_v483 e
  join public.sales sa on sa.id=e.sale_id and sa.tenant_id=e.tenant_id and sa.status='posted'
  join public.product_tracking_policies_v483 tp on tp.tenant_id=e.tenant_id and tp.variant_id=e.variant_id and tp.warranty_enabled
  where e.tenant_id=p_tenant_id and e.event_type='sale' and e.batch_id is not null and e.sale_id is not null and e.sale_item_id is not null
    and not exists(select 1 from public.product_warranties_v483 w where w.tenant_id=e.tenant_id and w.batch_id=e.batch_id and w.sale_id=e.sale_id and w.sale_item_id=e.sale_item_id and w.status<>'void')
  group by e.tenant_id,e.variant_id,e.batch_id,e.customer_id,e.sale_id,e.sale_item_id,sa.sale_date,tp.warranty_months,tp.warranty_days
  on conflict do nothing;
  get diagnostics v_batch_backfill=row_count;

  return jsonb_build_object('success',true,'expired',v_expired,'reactivated',v_reactivated,'voided',v_voided,'serial_backfilled',v_serial_backfill,'batch_backfilled',v_batch_backfill);
end $$;


--
-- Name: workshop_job_create_v4(uuid, uuid, uuid, uuid, text, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workshop_job_create_v4(p_tenant_id uuid, p_location_id uuid, p_vehicle_id uuid, p_customer_id uuid, p_complaint text, p_estimated_delivery timestamp with time zone, p_technician uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_id uuid:=gen_random_uuid();v_no text;begin perform private.v4_location_access(p_tenant_id,p_location_id,'operate');if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'workshop.manage') then raise exception 'Workshop permission required';end if;v_no:='JOB-'||lpad(nextval('public.workshop_job_number_seq')::text,6,'0');insert into public.workshop_job_cards(id,tenant_id,location_id,vehicle_id,customer_id,job_number,complaint,estimated_delivery,technician_user_id,created_by) values(v_id,p_tenant_id,p_location_id,p_vehicle_id,p_customer_id,v_no,trim(p_complaint),p_estimated_delivery,p_technician,auth.uid());return jsonb_build_object('job_id',v_id,'job_number',v_no);end $$;


--
-- Name: workshop_job_status_v4(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workshop_job_status_v4(p_tenant_id uuid, p_job_id uuid, p_status text, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_loc uuid;begin
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'workshop.manage') then raise exception 'Workshop manage permission required';end if;
  if p_status not in('open','inspection','estimate','approved','in_progress','waiting_parts','ready','delivered','cancelled') then raise exception 'Invalid job status';end if;
  select location_id into v_loc from public.workshop_job_cards where id=p_job_id and tenant_id=p_tenant_id;if v_loc is null then raise exception 'Job not found';end if;perform private.v4_location_access(p_tenant_id,v_loc,'operate');
  update public.workshop_job_cards set status=p_status,inspection_notes=case when trim(coalesce(p_note,''))='' then inspection_notes else concat_ws(E'\n',inspection_notes,trim(p_note)) end,updated_at=now() where id=p_job_id and tenant_id=p_tenant_id;
end $$;


--
-- Name: workshop_jobs_list_v4(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workshop_jobs_list_v4(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_query text DEFAULT NULL::text) RETURNS TABLE(id uuid, job_number text, status text, vehicle_id uuid, vehicle_number text, customer_id uuid, customer_name text, complaint text, estimated_amount numeric, estimated_delivery timestamp with time zone, technician_user_id uuid, technician_username text, location_id uuid, location_code text, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare q text:='%'||lower(trim(coalesce(p_query,'')))||'%';begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'workshop.view') and not private.erp_has_permission(p_tenant_id,'workshop.manage') then raise exception 'Workshop permission required';end if;
  return query select j.id,j.job_number,j.status,j.vehicle_id,v.vehicle_number,j.customer_id,coalesce(c.name,''),j.complaint,j.estimated_amount,j.estimated_delivery,j.technician_user_id,coalesce(u.username,''),j.location_id,coalesce(l.location_code,''),j.created_at
  from public.workshop_job_cards j join public.workshop_vehicles v on v.id=j.vehicle_id left join public.customers c on c.id=j.customer_id left join public.user_login_names u on u.user_id=j.technician_user_id left join public.business_locations l on l.id=j.location_id
  where j.tenant_id=p_tenant_id and (p_location_id is null or j.location_id=p_location_id) and private.erp_document_scope_allowed(p_tenant_id,j.location_id,p_location_id,'view')
    and (p_status is null or p_status='' or j.status=p_status)
    and (trim(coalesce(p_query,''))='' or lower(j.job_number) like q or lower(v.vehicle_number) like q or lower(coalesce(c.name,'')) like q or lower(coalesce(j.complaint,'')) like q)
  order by case j.status when 'ready' then 1 when 'in_progress' then 2 when 'waiting_parts' then 3 when 'open' then 4 else 5 end,j.created_at desc;
end $$;


--
-- Name: workshop_vehicle_save_v4(uuid, uuid, uuid, uuid, text, text, text, integer, text, text, numeric, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workshop_vehicle_save_v4(p_tenant_id uuid, p_id uuid, p_location_id uuid, p_customer_id uuid, p_vehicle_number text, p_make text, p_model text, p_year integer, p_vin text, p_chassis text, p_odometer numeric, p_notes text, p_active boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare v_id uuid;begin
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'workshop.manage') then raise exception 'Workshop manage permission required';end if;
  perform private.v4_location_access(p_tenant_id,p_location_id,'operate');
  if trim(coalesce(p_vehicle_number,''))='' then raise exception 'Vehicle number required';end if;
  if p_id is null then
    insert into public.workshop_vehicles(tenant_id,customer_id,location_id,vehicle_number,make,model,year,vin,chassis_number,odometer,notes,active)
    values(p_tenant_id,p_customer_id,p_location_id,upper(trim(p_vehicle_number)),nullif(trim(coalesce(p_make,'')),''),nullif(trim(coalesce(p_model,'')),''),p_year,nullif(trim(coalesce(p_vin,'')),''),nullif(trim(coalesce(p_chassis,'')),''),p_odometer,nullif(trim(coalesce(p_notes,'')),''),coalesce(p_active,true)) returning id into v_id;
  else
    update public.workshop_vehicles set customer_id=p_customer_id,location_id=p_location_id,vehicle_number=upper(trim(p_vehicle_number)),make=nullif(trim(coalesce(p_make,'')),''),model=nullif(trim(coalesce(p_model,'')),''),year=p_year,vin=nullif(trim(coalesce(p_vin,'')),''),chassis_number=nullif(trim(coalesce(p_chassis,'')),''),odometer=p_odometer,notes=nullif(trim(coalesce(p_notes,'')),''),active=coalesce(p_active,true)
    where id=p_id and tenant_id=p_tenant_id returning id into v_id;
  end if;
  if v_id is null then raise exception 'Vehicle not found';end if;return v_id;
end $$;


--
-- Name: workshop_vehicles_list_v4(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workshop_vehicles_list_v4(p_tenant_id uuid, p_location_id uuid DEFAULT NULL::uuid, p_query text DEFAULT NULL::text) RETURNS TABLE(id uuid, vehicle_number text, make text, model text, year integer, vin text, chassis_number text, odometer numeric, notes text, active boolean, customer_id uuid, customer_name text, location_id uuid, location_code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$ declare q text:='%'||lower(trim(coalesce(p_query,'')))||'%';begin
  if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;
  if not private.erp_user_is_owner(p_tenant_id) and not private.erp_has_permission(p_tenant_id,'workshop.view') and not private.erp_has_permission(p_tenant_id,'workshop.manage') then raise exception 'Workshop permission required';end if;
  return query select v.id,v.vehicle_number,v.make,v.model,v.year,v.vin,v.chassis_number,v.odometer,v.notes,v.active,v.customer_id,coalesce(c.name,''),v.location_id,coalesce(l.location_code,'')
  from public.workshop_vehicles v left join public.customers c on c.id=v.customer_id left join public.business_locations l on l.id=v.location_id
  where v.tenant_id=p_tenant_id and (p_location_id is null or v.location_id=p_location_id)
    and (v.location_id is null or private.erp_document_scope_allowed(p_tenant_id,v.location_id,p_location_id,'view'))
    and (trim(coalesce(p_query,''))='' or lower(v.vehicle_number) like q or lower(coalesce(v.make,'')) like q or lower(coalesce(v.model,'')) like q or lower(coalesce(v.vin,'')) like q or lower(coalesce(c.name,'')) like q)
  order by v.active desc,v.vehicle_number;
end $$;


--
-- Name: gst_authoritative_tx_context_v520; Type: TABLE; Schema: private; Owner: -
--

CREATE TABLE private.gst_authoritative_tx_context_v520 (
    txid bigint NOT NULL,
    tenant_id uuid NOT NULL,
    source_type text NOT NULL,
    source_id uuid,
    started_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: gst_transaction_requests_v520; Type: TABLE; Schema: private; Owner: -
--

CREATE TABLE private.gst_transaction_requests_v520 (
    tenant_id uuid NOT NULL,
    request_id text NOT NULL,
    operation text NOT NULL,
    request_hash text NOT NULL,
    status text DEFAULT 'processing'::text NOT NULL,
    source_type text,
    source_id uuid,
    snapshot_id uuid,
    journal_id uuid,
    response jsonb,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT gst_transaction_requests_v520_check CHECK (((status = 'processing'::text) OR ((source_type IS NOT NULL) AND (source_id IS NOT NULL) AND (snapshot_id IS NOT NULL) AND (journal_id IS NOT NULL) AND (response IS NOT NULL) AND (completed_at IS NOT NULL)))),
    CONSTRAINT gst_transaction_requests_v520_request_hash_check CHECK ((length(request_hash) = 64)),
    CONSTRAINT gst_transaction_requests_v520_status_check CHECK ((status = ANY (ARRAY['processing'::text, 'completed'::text])))
);


--
-- Name: mobile_pos_kot_requests_v520; Type: TABLE; Schema: private; Owner: -
--

CREATE TABLE private.mobile_pos_kot_requests_v520 (
    tenant_id uuid NOT NULL,
    request_id text NOT NULL,
    request_hash text NOT NULL,
